//! Expression type-checker ÃÂ¢ÃÂÃÂ Phase 3 of TS_PARITY_PLAN.
//!
//! Walks HIR expressions and assigns each one a TypeId, populating
//! the HIR's `types` column. Also drives the cross-statement checks:
//! `let x: T = expr;` verifies `expr`'s type is assignable to `T`.
//!
//! Scope today (Phase 3 expression typing ÃÂ¢ÃÂÃÂ minimal):
//!   - Literals (number / string / bigint / boolean / null /
//!     undefined) ÃÂ¢ÃÂÃÂ matching Primitive
//!   - Identifier references ÃÂ¢ÃÂÃÂ type taken from the binder's symbol
//!     when known, else `Primitive.any` (forgiving for partial input)
//!   - Binary `+` on number+number / string+string ÃÂ¢ÃÂÃÂ matching
//!     primitive; mixed ÃÂ¢ÃÂÃÂ string (matches JS coercion)
//!   - Comparison ops ÃÂ¢ÃÂÃÂ boolean
//!   - Logical `&&`/`||`/`??` ÃÂ¢ÃÂÃÂ union of branch types
//!   - Conditional `c ? a : b` ÃÂ¢ÃÂÃÂ union of branches
//!   - Assignment `target = value` ÃÂ¢ÃÂÃÂ value's type
//!   - VarDecl with annotation: assign annotation to the decl's
//!     type slot, check init assigns to it; else infer from init
//!
//! Out of scope (Phase 3 follow-ups):
//!   - Call type-checking (needs signature lowering)
//!   - Member access / element access (needs object-type lowering)
//!   - Generic instantiation
//!   - Control-flow narrowing
//!   - Class/interface body member resolution

const std = @import("std");
const hir_mod = @import("hir");
const types = @import("types.zig");
const interner = @import("interner.zig");
const relation = @import("relation.zig");
const lower = @import("lower.zig");
const lib = @import("lib.zig");
const string_interner = @import("string_interner");
const binder_mod = @import("binder");

pub const TypeId = types.TypeId;
pub const NodeId = hir_mod.NodeId;
pub const Hir = hir_mod.Hir;

/// Which property of a resolution target is being resolved — tsc's
/// `TypeSystemPropertyName`. A (target, kind) pair uniquely identifies
/// an in-flight resolution so the resolution stack can detect a cycle
/// (e.g. a mapped symbol's `type` re-entering its own resolution). New
/// kinds are added as lazy resolutions are routed through the stack.
pub const TypeResolutionKind = enum(u8) {
    /// `getTypeOfMappedSymbol` / member type — the property whose value
    /// is being materialized (TS2615 / TS2527 family).
    type,
    /// `getResolvedBaseConstraint`.
    resolved_base_constraint,
    /// `getTypeArguments` resolved type arguments.
    resolved_type_arguments,
    /// `getReturnTypeOfSignature`.
    resolved_return_type,
    /// `getDeclaredTypeOfSymbol`.
    declared_type,
    /// Written `.d.ts`-emit serialized type (TS4118 family).
    written_type,
};

/// One in-flight type resolution: the (target, kind) pair plus whether
/// it has so far avoided a cycle. `target` is a caller-chosen stable id
/// (a symbol/node/type id, or a hash of a compound key like a mapped
/// (node,key) pair) — the analogue of tsc's resolution-target pointer.
const TypeResolution = struct { target: u64, kind: TypeResolutionKind, result: bool };

pub const CheckError = error{
    OutOfMemory,
};

/// One nested elaboration entry hanging under a parent diagnostic,
/// mirroring tsc's `messageChain` (typescript-go
/// `ast.Diagnostic.messageChain`). Upstream renders these as indented
/// continuation lines under the parent header — e.g. TS2326
/// `Types of property '{0}' are incompatible.` nested below a TS2430
/// structural-incompatibility error. Each entry carries its OWN code
/// and message and may itself nest further `children`, recursively.
///
/// Lifetime: `message` is borrowed for the lifetime of the diagnostic
/// (the checker allocates it in `diag_arena`, same as the parent
/// `Diagnostic.message`). `children` likewise points into a stable
/// allocation (typically `diag_arena`).
pub const DiagnosticChainEntry = struct {
    /// TypeScript-compatible code for this nested message (e.g. 2326).
    code: u32 = 0,
    /// `TS` for tsc-compatible codes; `HM` for Home-only codes.
    code_prefix: Diagnostic.CodePrefix = .TS,
    /// Fully-formatted (argument-substituted) message text.
    message: []const u8,
    /// Deeper nested elaboration; empty for leaf entries. Upstream tsc
    /// chains can recurse arbitrarily (e.g. TS2326 → TS2322 leaf).
    children: []const DiagnosticChainEntry = &.{},
};

/// A secondary anchor attached to a primary diagnostic. Mirrors tsc's
/// `relatedInformation` array on `Diagnostic` (e.g. TS9027 "Add a type
/// annotation to the variable 'X'" attached to a TS9010 primary, or
/// TS18017 "The shadowing declaration of 'X' is defined here" attached
/// to TS18014). Allocated in `diag_arena` alongside the parent's
/// `message`.
///
/// Conformance baselines currently don't surface related-info lines
/// (most `.errors.txt` fixtures only check the primary header), so
/// adding `related` entries is additive and doesn't regress existing
/// baselines. The LSP `publishDiagnostics` path can render them as
/// `relatedInformation[]` once it's wired.
pub const RelatedInfo = struct {
    /// HIR node the related anchor points at (could be different from
    /// the primary diagnostic's `node`).
    node: NodeId,
    /// Optional absolute source byte offset, used when the secondary
    /// anchor belongs to trivia rather than an HIR node.
    pos: ?u32 = null,
    /// Optional path of a DIFFERENT source file the anchor lives in
    /// (with `pos` a byte offset into THAT file). Null means the anchor
    /// is in the primary diagnostic's own file (the `node`/`pos` case).
    /// Used for cross-file related info such as TS1377 "'{0}' was
    /// exported here", whose anchor is in the imported module. The legacy
    /// header-only `.errors.txt` formatter doesn't render related lines,
    /// so this is additive; the LSP path can map (file,pos) to line:col.
    file: ?[]const u8 = null,
    /// TypeScript-compatible code for this related entry (e.g. 9027,
    /// 18017). 0 if uncategorized.
    code: u32 = 0,
    code_prefix: Diagnostic.CodePrefix = .TS,
    /// Fully-formatted message text for the related anchor.
    message: []const u8,
};

pub const Diagnostic = struct {
    node: NodeId,
    /// Optional absolute source byte offset for diagnostics that
    /// belong to trivia rather than an HIR node, such as an unused
    /// `// @ts-expect-error` directive.
    pos: ?u32 = null,
    /// TypeScript-compatible code (e.g. 2322). 0 for uncategorized.
    code: u32 = 0,
    /// `TS` for tsc-compatible codes; `HM` for Home-only codes.
    code_prefix: CodePrefix = .TS,
    message: []const u8,
    /// Optional nested elaboration chain. Empty by default so existing
    /// single-message emission is unchanged. When non-empty, formatters
    /// render each entry as an indented continuation line under this
    /// diagnostic's header (tsc `messageChain`). Additive: callers that
    /// don't set it keep the prior flat behaviour.
    chain: []const DiagnosticChainEntry = &.{},
    /// Optional related-info anchors. Each entry points at a different
    /// node and carries its own message (and optional code). Empty by
    /// default so existing single-anchor emission is unchanged.
    /// Surfaced by the LSP's `publishDiagnostics` and (eventually) by
    /// the conformance baseline formatter; not rendered in the legacy
    /// header-only `.errors.txt` shape, so this is additive.
    related: []const RelatedInfo = &.{},
    /// Diagnostic category. Mirrors tsc's `CategoryError` vs
    /// `CategorySuggestion` split. Defaults to `.error_` so existing
    /// emission is unchanged. `.suggestion`-category diagnostics
    /// (e.g. TS7043-TS7050 "a better type may be inferred from usage")
    /// are NOT errors: tsc routes them through `getSuggestionDiagnostics`
    /// and they never appear in `.errors.txt` baselines. The driver
    /// only surfaces them when `include_suggestions` is requested, so
    /// conformance / normal compilation are unaffected.
    category: Category = .error_,
    /// Whole-program / config diagnostic with no file-line prefix in
    /// tsc's default formatter (e.g. TS2209 project-root-ambiguous).
    /// Propagated to `ts_driver.Diagnostic.is_global`. Defaults false so
    /// existing node-anchored emission is unchanged.
    is_global: bool = false,

    pub const CodePrefix = enum { TS, HM };
    pub const Category = enum { error_, suggestion };
};

/// External module-resolution hook the checker can delegate to.
///
/// When set via `Checker.setExternalResolver`, the checker will ask
/// this resolver to map a bare/relative module specifier to a
/// resolved file path before falling back to its in-source
/// `@filename:` virtual-section scan. This lets the conformance
/// harness route through `ts_resolver` for `package.json`-aware
/// fixtures (`packageJsonMain*`, `nestedPackageJsonRedirect`,
/// `typesVersions.*`, `untypedModuleImport_*`) instead of having
/// the checker re-implement node resolution against virtual-file
/// markers.
///
/// The vtable shape stays opaque so `ts_checker` does not pull
/// `ts_resolver` in as a build dependency.
pub const ExternalResolver = struct {
    ptr: *anyopaque,
    vtable: *const VTable,

    pub const Resolution = struct {
        /// Resolved file path. Borrowed; lifetime is the resolver's
        /// arena (which must outlive the `Checker`'s
        /// `checkSourceFile` call). The checker never frees it.
        path: []const u8,
        /// True when `path` ends in `.d.ts` / `.d.cts` / `.d.mts`
        /// or `.ts` / `.tsx` / `.mts` / `.cts` ÃÂ¢ÃÂÃÂ i.e. tsc would
        /// treat the resolution as "typed".
        is_declaration: bool,
        /// When the resolution went through `package.json` `exports`
        /// and landed on an untyped JS file under an ESM importer, but
        /// a declaration file WOULD have resolved with `exports`
        /// ignored, this carries that otherwise-unreachable declaration
        /// path. The checker uses it to attach the TS6278 "There are
        /// types at ..." elaboration to TS7016. Null when none applies.
        /// Borrowed like `path`.
        alternate_result: ?[]const u8 = null,
        /// Missing emitted output path that was reverse-mapped back to
        /// this source file through project-reference-style output
        /// mapping. When present, the checker reports TS6305.
        project_reference_output: ?[]const u8 = null,
        /// True when the package exports object had an active
        /// `import`/`require` condition mapped to null. The checker
        /// keeps that as TS2307 even if the resolver also found a
        /// declaration through `types`.
        blocked_by_exports_null: bool = false,
        /// True when resolution went through package.json `exports` or
        /// `imports`.
        package_json_map: bool = false,
        /// True when a package.json `imports` wildcard pattern resolved
        /// this specifier.
        package_imports_pattern: bool = false,
    };

    // Cross-file export-table query result for the declaration-emit
    // privacy cluster. Mirrors the subset of upstream's
    // isSymbolAccessibleWorker / selectDiagnosticBasedOnModuleName that
    // Home can establish faithfully from a resolved source module: the
    // module's rendered name ({2} slot, e.g. "type" for ./type) and
    // whether the referenced bare name is an exported type-space symbol
    // there.
    pub const ModuleExport = struct {
        // Rendered module name for the {2} diagnostic slot. Upstream
        // symbolToString of the external-module symbol renders the
        // quoted module stem ("type" for a file type.ts resolved from
        // ./type). Borrowed; lives in the resolver's arena.
        module_name: []const u8,
        // True when the bare name is declared+exported in the resolved
        // module's top-level body (a type-space export). This is the
        // `from private module` case (TS4024/4030/...). When this is
        // true the importing `.d.ts` could in principle re-import the
        // name; upstream still flags it because the WRITTEN alias is not
        // preserved (it renders `from private module '{2}'`).
        exported_type: bool,
        // True when the same export is available in value space. Classes
        // and enums are both type/value exports; interfaces and type
        // aliases are type-only declarations.
        exported_value: bool = false,
        // True when the bare name is NOT a direct top-level export but is
        // reachable only as a type-space member nested inside one of the
        // resolved module's exported namespaces (e.g.
        // `Widgets.SpecializedWidget.Widget2`). Such a symbol has no
        // top-level import alias the importing file can write into the
        // `.d.ts`, so its accessible-symbol chain is empty while it still
        // originates in a different external module — upstream's
        // `Accessibility == CannotBeNamed` branch
        // (`isSymbolAccessibleWorker`'s `symbolExternalModule !=
        // enclosingExternalModule` fall-through). Drives the
        // `... from external module {2} but cannot be named`
        // (TS4023/4026/...) variants.
        cannot_be_named: bool = false,
        /// True when `name` is exported from the resolved module using a
        /// TYPE-ONLY export (`export type { name }`, `export type * `, or
        /// a `type`-modified export specifier). Drives TS1379 (an import
        /// alias `mod.name` cannot reference a type-only export). Additive:
        /// resolvers that don't compute it leave it false.
        type_only_export: bool = false,
        /// When `type_only_export` is true: the resolved module's path and
        /// the byte offset of the type-only export declaration within it.
        /// Anchors the TS1377 "'{0}' was exported here" cross-file
        /// related-info. Empty/0 when unavailable.
        export_path: []const u8 = "",
        export_pos: u32 = 0,
        /// True when the queried specifier is backed by a visible ambient
        /// module declaration. Ambient module bodies are not always exposed
        /// through the resolved file's top-level export table, so absence of
        /// a proven export should remain unknown instead of becoming TS2305.
        ambient_module: bool = false,
        /// True when every visible ambient declaration matching the module
        /// specifier was inspected for this name. A false export result is a
        /// trusted missing member only when this bit is set.
        ambient_module_exports_known: bool = false,
        /// True when the exported value is an ambient const enum. Under
        /// isolatedModules-like flags (including verbatimModuleSyntax),
        /// TypeScript rejects value imports/re-exports of these symbols with
        /// TS2748 even though they are value-space exports.
        ambient_const_enum: bool = false,
    };
    pub const InferredExportUnsafeReference = struct {
        /// Type name that makes the inferred exported value non-portable.
        /// Empty when upstream's unsafe-import callback cannot identify a
        /// specific symbol name, selecting TS2742 instead of TS2883.
        /// Borrowed; lives in the resolver's arena.
        symbol_name: []const u8,
        /// Module specifier that would be needed to name the type in the
        /// emitted declaration file, e.g. `foo/node_modules/nested`.
        /// Borrowed; lives in the resolver's arena.
        module_specifier: []const u8,
    };
    pub const VTable = struct {
        /// Resolve `specifier` from `containing_file`. Returns
        /// `null` when the specifier did not resolve.
        resolve: *const fn (
            self: *anyopaque,
            specifier: []const u8,
            containing_file: []const u8,
        ) ?Resolution,
        // Cross-file export-table query: resolve specifier from
        // containing_file, then report the resolved module's rendered
        // name and whether name is an exported type-space symbol there.
        // Optional (null when the resolver cannot merge foreign export
        // tables). Returns null when the specifier does not resolve.
        moduleExport: ?*const fn (
            self: *anyopaque,
            specifier: []const u8,
            containing_file: []const u8,
            name: []const u8,
        ) ?ModuleExport = null,
        // Declaration-emit portability query for inferred exported
        // variables initialized by an imported call expression. Returns
        // the first type reference in the imported function's declared
        // return type that would require a non-portable module reference
        // in the generated `.d.ts` (TS2883).
        inferredExportUnsafeReference: ?*const fn (
            self: *anyopaque,
            specifier: []const u8,
            containing_file: []const u8,
            exported_name: []const u8,
        ) ?InferredExportUnsafeReference = null,
        // TS2209/TS2210: project-root-ambiguous state from the most recent
        // `resolve`. Takes no args — reads the resolver's last-stashed
        // record. Optional; null when the resolver can't report it.
        ambiguousProjectRoot: ?*const fn (self: *anyopaque) ?AmbiguousProjectRoot = null,
    };

    pub fn resolve(
        self: ExternalResolver,
        specifier: []const u8,
        containing_file: []const u8,
    ) ?Resolution {
        return self.vtable.resolve(self.ptr, specifier, containing_file);
    }

    pub fn moduleExport(
        self: ExternalResolver,
        specifier: []const u8,
        containing_file: []const u8,
        name: []const u8,
    ) ?ModuleExport {
        const f = self.vtable.moduleExport orelse return null;
        return f(self.ptr, specifier, containing_file, name);
    }

    pub fn inferredExportUnsafeReference(
        self: ExternalResolver,
        specifier: []const u8,
        containing_file: []const u8,
        exported_name: []const u8,
    ) ?InferredExportUnsafeReference {
        const f = self.vtable.inferredExportUnsafeReference orelse return null;
        return f(self.ptr, specifier, containing_file, exported_name);
    }

    /// TS2209/TS2210 project-root-ambiguous record from the most recent
    /// `resolve` (an `exports`/`imports` map entry under `outDir` with no
    /// `rootDir`/config). Read immediately after a failed bare resolution
    /// so the checker reports the right code instead of TS2307.
    pub const AmbiguousProjectRoot = struct {
        entry: []const u8,
        file: []const u8,
        is_imports: bool,
    };

    pub fn ambiguousProjectRoot(self: ExternalResolver) ?AmbiguousProjectRoot {
        const f = self.vtable.ambiguousProjectRoot orelse return null;
        return f(self.ptr);
    }
};

pub const ScriptObjectExpando = struct {
