    pub fn setAllowJsEnabled(self: *Checker, enabled: bool) void {
        self.allow_js_enabled = enabled;
    }

    pub fn setJsxOptionPresent(self: *Checker, enabled: bool) void {
        self.jsx_option_present = enabled;
