        jsx_fragment_factory_scope_required: bool,
    ) void {
        self.jsx_transform_enabled = transform_enabled;
        self.jsx_factory_compiler_option_present = jsx_factory_present;
        self.jsx_fragment_factory_compiler_option_present = jsx_fragment_factory_present;
        self.jsx_fragment_factory_name = jsx_fragment_factory_name;
        self.jsx_fragment_factory_scope_required = jsx_fragment_factory_scope_required;
