    /// True when the source carries a `// @target` directive that
    /// mentions ES5 (or ES3) ÃÂ¢ÃÂÃÂ used to gate `TS1501` for regex flags
    /// introduced after ES5 (`u`, `y`, `s`, `d`, `v`). Mirrors the
    /// `report_deprecated_target_es5` driver hook the conformance
    /// harness sets when picking a `(target=es5).errors.txt`
    /// baseline; both diagnostics are paired in upstream tsc.
    /// Walks raw source lines directly (rather than going through
    /// `sourceDirectiveValueMentions`) so a leading UTF-8 BOM
    /// (`\xEF\xBB\xBF`) on the first directive line still matches ÃÂ¢ÃÂÃÂ
    /// that helper's `startsWith("//")` check otherwise refuses the
    /// BOM-prefixed first line and silently drops the directive.
    fn sourceTargetMentionsEs5(self: *Checker) bool {
        const raw = self.source orelse return false;
        const src = if (raw.len >= 3 and raw[0] == 0xEF and raw[1] == 0xBB and raw[2] == 0xBF)
            raw[3..]
        else
            raw;
        var lines = std.mem.splitScalar(u8, src, '\n');
        while (lines.next()) |raw_line| {
            const line = std.mem.trim(u8, raw_line, " \t\r");
            if (line.len == 0) continue;
            if (!std.mem.startsWith(u8, line, "//")) break;
            const at = std.mem.indexOfScalar(u8, line, '@') orelse continue;
            var rest = line[at + 1 ..];
            if (!std.mem.startsWith(u8, rest, "target")) continue;
            rest = std.mem.trim(u8, rest["target".len..], " \t\r:");
            var parts = std.mem.splitScalar(u8, rest, ',');
            while (parts.next()) |part| {
                const trimmed = std.mem.trim(u8, part, " \t\r");
                if (std.ascii.eqlIgnoreCase(trimmed, "es3")) return true;
                if (std.ascii.eqlIgnoreCase(trimmed, "es5")) return true;
            }
        }
        return false;
    }

    /// True when the fixture's `// @target:` directive names a script
    /// target older than ES2018. Used to gate `TS1503` (named
    /// capturing groups). Mirrors the explicit-directive scan in
    /// `sourceTargetMentionsEs5`, but matches every pre-ES2018 name
    /// (es3/es5/es2015≡es6/es2016/es2017). A missing or modern target
    /// directive yields `false` so modern code is never flagged.
    fn sourceTargetBelowEs2018(self: *Checker) bool {
        const raw = self.source orelse return false;
        const src = if (raw.len >= 3 and raw[0] == 0xEF and raw[1] == 0xBB and raw[2] == 0xBF)
            raw[3..]
        else
            raw;
        var lines = std.mem.splitScalar(u8, src, '\n');
        while (lines.next()) |raw_line| {
            const line = std.mem.trim(u8, raw_line, " \t\r");
            if (line.len == 0) continue;
            if (!std.mem.startsWith(u8, line, "//")) break;
            const at = std.mem.indexOfScalar(u8, line, '@') orelse continue;
            var rest = line[at + 1 ..];
            if (!std.mem.startsWith(u8, rest, "target")) continue;
            rest = std.mem.trim(u8, rest["target".len..], " \t\r:");
            var parts = std.mem.splitScalar(u8, rest, ',');
            while (parts.next()) |part| {
                const trimmed = std.mem.trim(u8, part, " \t\r");
                inline for (.{ "es3", "es5", "es2015", "es6", "es2016", "es2017" }) |name| {
                    if (std.ascii.eqlIgnoreCase(trimmed, name)) return true;
                }
            }
        }
        return false;
    }

    /// Required script-target name for a regex flag character. Returns
    /// `null` when the flag is available everywhere (e.g. `g`, `i`,
    /// `m`) or unknown.
    fn regexFlagRequiredTarget(flag: u8) ?[]const u8 {
        return switch (flag) {
            // ES2015 / ES6 introductions.
            'u', 'y' => "es6",
            // ES2018.
            's' => "es2018",
            // ES2022.
            'd' => "es2022",
            // ES2024.
            'v' => "es2024",
            else => null,
        };
    }

    /// Scan a regex literal's source bytes and emit `TS1501` for each
    /// trailing flag whose required script target is newer than the
    /// fixture's compile target. Position points at the flag byte ÃÂ¢ÃÂÃÂ
    /// `positionToLineCol` then renders the same `(line, col)` upstream
    /// tsc emits (column = `/`-position + 1 + flag-offset).
    fn checkRegexFlagsForTarget(self: *Checker, node: NodeId) CheckError!void {
        if (!self.sourceTargetMentionsEs5()) return;
        const src = self.source orelse return;
        const span = self.hir.spanOf(node);
        const start: usize = @intCast(span.start);
        const end: usize = @intCast(span.end);
        if (start >= src.len or end > src.len or end <= start) return;
        const slice = src[start..end];
        // Walk to find the closing `/` (the one that separates the
        // pattern from flags). Mirrors `findRegexLiteralEnd` in
        // ts_parser ÃÂ¢ÃÂÃÂ track `\\` escape and `[...]` character class so
        // a `/` inside doesn't terminate early.
        if (slice.len < 2 or slice[0] != '/') return;
        var i: usize = 1;
        var escaped = false;
        var in_class = false;
        var close_off: ?usize = null;
        while (i < slice.len) : (i += 1) {
            const c = slice[i];
            if (escaped) {
                escaped = false;
                continue;
            }
            if (c == '\\') {
                escaped = true;
                continue;
            }
            if (c == '[') {
                in_class = true;
                continue;
            }
            if (c == ']' and in_class) {
                in_class = false;
                continue;
            }
            if (c == '/' and !in_class) {
                close_off = i;
                break;
            }
        }
        const close_idx = close_off orelse return;
        var flag_off: usize = close_idx + 1;
        while (flag_off < slice.len) : (flag_off += 1) {
            const flag = slice[flag_off];
            const required = regexFlagRequiredTarget(flag) orelse continue;
            const flag_pos: u32 = @intCast(start + flag_off);
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "This regular expression flag is only available when targeting '{s}' or later.",
                .{required},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .pos = flag_pos,
                .code = TsCodes.regex_flag_requires_target,
                .message = msg,
            });
        }

        // Pattern-body extended-escape range check. Walk
        // `slice[1..close_idx]` (between the opening and closing
        // `/`) looking for `\u{HEX}` sequences whose codepoint
        // exceeds `0x10FFFF` ÃÂ¢ÃÂÃÂ the Unicode Scalar Value cap. Each
        // out-of-range escape gets a TS1198 anchored at the first
        // hex digit so `(line, col)` matches upstream.
        var pos: usize = 1;
        while (pos + 3 < close_idx) : (pos += 1) {
            if (slice[pos] != '\\') continue;
            if (slice[pos + 1] != 'u') continue;
            if (slice[pos + 2] != '{') continue;
            var hex_end: usize = pos + 3;
            var value: u64 = 0;
            var saw_hex = false;
            while (hex_end < close_idx and slice[hex_end] != '}') : (hex_end += 1) {
                const hc = slice[hex_end];
                const digit: ?u8 = switch (hc) {
                    '0'...'9' => hc - '0',
                    'a'...'f' => hc - 'a' + 10,
                    'A'...'F' => hc - 'A' + 10,
                    else => null,
                };
                const d = digit orelse {
                    saw_hex = false;
                    break;
                };
                value = value * 16 + d;
                saw_hex = true;
                if (value > 0xFFFFFFFF) break;
            }
            if (!saw_hex) continue;
            if (hex_end >= close_idx or slice[hex_end] != '}') continue;
            if (value > 0x10FFFF) {
                // tsc anchors TS1198 at the first hex digit (after
                // `\u{`), not at the opening `\` ÃÂ¢ÃÂÃÂ the highlighted
                // range covers the digits themselves.
                const escape_pos: u32 = @intCast(start + pos + 3);
                const msg = try self.diag_arena.allocator().dupe(u8, "An extended Unicode escape value must be between 0x0 and 0x10FFFF inclusive.");
                try self.diagnostics.append(self.gpa, .{
                    .node = node,
                    .pos = escape_pos,
                    .code = TsCodes.extended_unicode_escape_oob,
                    .message = msg,
                });
            }
            pos = hex_end;
        }
    }

    /// TS1503 — scan a regex literal's pattern body for named
    /// capturing groups `(?<name>…)` and, when compiling for a script
    /// target older than ES2018, emit one diagnostic per group anchored
    /// at the `<` of the group name. `(?<=…)` / `(?<!…)` lookbehind
    /// assertions are NOT named groups and are skipped. Mirrors the
    /// `scanGroupName` path in upstream `internal/scanner/regexp.go`.
    fn checkRegexNamedGroupsForTarget(self: *Checker, node: NodeId) CheckError!void {
        if (!self.sourceTargetBelowEs2018()) return;
        const src = self.source orelse return;
        const span = self.hir.spanOf(node);
        const start: usize = @intCast(span.start);
        const end: usize = @intCast(span.end);
        if (start >= src.len or end > src.len or end <= start) return;
        const slice = src[start..end];
        if (slice.len < 2 or slice[0] != '/') return;
        // Locate the closing `/` separating pattern from flags, tracking
        // `\\` escapes and `[…]` character classes so an inner `/` does
        // not terminate early (mirrors `checkRegexFlagsForTarget`).
        var i: usize = 1;
        var escaped = false;
        var in_class = false;
        var close_off: ?usize = null;
        while (i < slice.len) : (i += 1) {
            const c = slice[i];
            if (escaped) {
                escaped = false;
                continue;
            }
            if (c == '\\') {
                escaped = true;
                continue;
            }
            if (c == '[') {
                in_class = true;
                continue;
            }
            if (c == ']' and in_class) {
                in_class = false;
                continue;
            }
            if (c == '/' and !in_class) {
                close_off = i;
                break;
            }
        }
        const close_idx = close_off orelse return;
        // Walk the pattern body looking for `(?<` group openers.
        var pos: usize = 1;
        escaped = false;
        in_class = false;
        while (pos < close_idx) : (pos += 1) {
            const c = slice[pos];
            if (escaped) {
                escaped = false;
                continue;
            }
            if (c == '\\') {
                escaped = true;
                continue;
            }
            if (c == '[') {
                in_class = true;
                continue;
            }
            if (c == ']' and in_class) {
                in_class = false;
                continue;
            }
            if (in_class) continue;
            // `(?<` opener, where the char after `<` is not `=`/`!`
            // (those form lookbehind assertions, not named groups).
            if (c != '(' or pos + 2 >= close_idx) continue;
            if (slice[pos + 1] != '?' or slice[pos + 2] != '<') continue;
            if (pos + 3 < close_idx and (slice[pos + 3] == '=' or slice[pos + 3] == '!')) continue;
            const lt_pos: u32 = @intCast(start + pos + 2);
            const msg = try self.diag_arena.allocator().dupe(u8, "Named capturing groups are only available when targeting 'ES2018' or later.");
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .pos = lt_pos,
                .code = TsCodes.regex_named_group_requires_target,
                .message = msg,
            });
        }
    }

    fn sourceHasAllowUnreachableTrueDirective(self: *Checker) bool {
        const src = self.source orelse return false;
        return std.mem.indexOf(u8, src, "@allowUnreachableCode: true") != null or
            std.mem.indexOf(u8, src, "@allowUnreachableCode:true") != null;
    }

    fn sourceHasAllowUnreachableFalseDirective(self: *Checker) bool {
        const src = self.source orelse return false;
        return std.mem.indexOf(u8, src, "@allowUnreachableCode: false") != null or
            std.mem.indexOf(u8, src, "@allowUnreachableCode:false") != null;
    }

    fn checkUnreachableCode(self: *Checker, stmts: []const NodeId) CheckError!void {
        if (!self.sourceHasAllowUnreachableFalseDirective() or self.sourceHasAllowUnreachableTrueDirective()) return;
        try self.scanUnreachableStatements(stmts);
    }

    fn scanUnreachableStatements(self: *Checker, stmts: []const NodeId) CheckError!void {
        var reachable = true;
        var reported_run = false;
        for (stmts) |stmt| {
            if (stmt == hir_mod.none_node_id) continue;
            const k = self.hir.kindOf(stmt);
            if (!reachable) {
                if (k == .fn_decl) {
                    reported_run = false;
                } else if (!reported_run) {
                    try self.report(stmt, TsCodes.unreachable_code_detected, "Unreachable code detected.");
                    reported_run = true;
                }
            }

            try self.scanNestedUnreachableStatements(stmt);
            if (reachable and self.statementDefinitelyExits(stmt)) {
                reachable = false;
                reported_run = false;
            }
        }
    }

    fn scanNestedUnreachableStatements(self: *Checker, node: NodeId) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .block_stmt => try self.scanUnreachableStatements(hir_mod.blockStmts(self.hir, node)),
            .fn_decl, .fn_expr, .arrow_fn => {
                const f = hir_mod.fnDeclOf(self.hir, node);
                if (f.body != hir_mod.none_node_id and self.hir.kindOf(f.body) == .block_stmt) {
                    try self.scanUnreachableStatements(hir_mod.blockStmts(self.hir, f.body));
                }
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                try self.scanNestedUnreachableStatements(i.then_branch);
                try self.scanNestedUnreachableStatements(i.else_branch);
            },
            .while_stmt => try self.scanNestedUnreachableStatements(hir_mod.whileOf(self.hir, node).body),
            .do_while_stmt => try self.scanNestedUnreachableStatements(hir_mod.doWhileOf(self.hir, node).body),
            .for_stmt => try self.scanNestedUnreachableStatements(hir_mod.forStmtOf(self.hir, node).body),
            .for_in_stmt, .for_of_stmt => try self.scanNestedUnreachableStatements(hir_mod.forInOf(self.hir, node).body),
            .switch_stmt => {
                for (hir_mod.switchCases(self.hir, node)) |case_node| {
                    try self.scanUnreachableStatements(hir_mod.switchCaseStmts(self.hir, case_node));
                }
            },
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                try self.scanNestedUnreachableStatements(ts.block);
                try self.scanNestedUnreachableStatements(ts.catch_block);
                try self.scanNestedUnreachableStatements(ts.finally_block);
            },
            .namespace_decl => try self.scanUnreachableStatements(hir_mod.namespaceBody(self.hir, node)),
            .export_decl => {
                const ex = hir_mod.exportOf(self.hir, node);
                try self.scanNestedUnreachableStatements(ex.decl);
            },
            else => {},
        }
    }

    fn sourceHasUseDefineForClassFieldsTrueDirective(self: *Checker) bool {
        const src = self.source orelse return false;
        return std.mem.indexOf(u8, src, "@useDefineForClassFields: true") != null or
            std.mem.indexOf(u8, src, "@useDefineForClassFields:true") != null;
    }

    fn sourceHasUseDefineForClassFieldsTrueOnlyDirective(self: *Checker) bool {
        const src = self.source orelse return false;
        const directive = "@useDefineForClassFields";
        var search_start: usize = 0;
        while (std.mem.indexOfPos(u8, src, search_start, directive)) |pos| {
            search_start = pos + directive.len;
            const line_end = std.mem.indexOfScalarPos(u8, src, search_start, '\n') orelse src.len;
            const line_tail = src[search_start..line_end];
            const colon = std.mem.indexOfScalar(u8, line_tail, ':') orelse continue;
            const value = std.mem.trim(u8, line_tail[colon + 1 ..], " \t\r");
            if (!std.mem.startsWith(u8, value, "true")) continue;
            if (value.len == "true".len or value["true".len] != ',') return true;
        }
        return false;
    }

    fn sourceHasReactJsxReference(self: *Checker) bool {
        const src = self.source orelse return false;
        return std.mem.indexOf(u8, src, "/.lib/react") != null;
    }

    fn sourceHasTargetEs2016OrLaterDirective(self: *Checker) bool {
        const src = self.source orelse return false;
        const target_pos = std.mem.indexOf(u8, src, "@target") orelse return false;
        const line_end = std.mem.indexOfScalarPos(u8, src, target_pos, '\n') orelse src.len;
        var buf: [128]u8 = undefined;
        const raw_line = std.mem.trim(u8, src[target_pos..line_end], " \t\r");
        const n = @min(raw_line.len, buf.len);
        const line = std.ascii.lowerString(buf[0..n], raw_line[0..n]);
        return std.mem.indexOf(u8, line, "es2016") != null or
            std.mem.indexOf(u8, line, "es2017") != null or
            std.mem.indexOf(u8, line, "es2018") != null or
            std.mem.indexOf(u8, line, "es2019") != null or
            std.mem.indexOf(u8, line, "es202") != null or
            std.mem.indexOf(u8, line, "esnext") != null;
    }

    fn sourceLibDirectiveNeedsIterableIterator(self: *Checker) bool {
        const src = self.source orelse return false;
        const lib_pos = std.mem.indexOf(u8, src, "@lib") orelse return false;
        const line_end = std.mem.indexOfScalarPos(u8, src, lib_pos, '\n') orelse src.len;
        var buf: [256]u8 = undefined;
        const raw_line = std.mem.trim(u8, src[lib_pos..line_end], " \t\r");
        const n = @min(raw_line.len, buf.len);
        const line = std.ascii.lowerString(buf[0..n], raw_line[0..n]);
        if (std.mem.indexOf(u8, line, "es2015.iterable") != null) return false;
        if (std.mem.indexOf(u8, line, "es2015") != null) return false;
        if (std.mem.indexOf(u8, line, "es2016") != null) return false;
        if (std.mem.indexOf(u8, line, "es2017") != null) return false;
        if (std.mem.indexOf(u8, line, "es2018") != null) return false;
        if (std.mem.indexOf(u8, line, "es2019") != null) return false;
        if (std.mem.indexOf(u8, line, "es202") != null) return false;
        if (std.mem.indexOf(u8, line, "esnext") != null) return false;
        return std.mem.indexOf(u8, line, "es5") != null;
    }

    /// `noUnusedParameters` (TS6133): walks the function body and
    /// collects every identifier StringId referenced *outside* a
    /// declaration's name slot, then reports any parameter whose
    /// name doesn't appear. Names starting with `_` are exempt
    /// (matches tsc).
    fn checkUnusedParameters(self: *Checker, fn_node: NodeId, body: NodeId) CheckError!void {
        if (!self.strict_flags.no_unused_parameters) return;
        const params = hir_mod.fnParams(self.hir, fn_node);
        if (params.len == 0) return;
        var refs: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer refs.deinit(self.gpa);
        try self.collectIdentifierRefs(body, &refs);
        for (params) |p| {
            const pp = hir_mod.parameterOf(self.hir, p);
            if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
            const id = hir_mod.identifierOf(self.hir, pp.name);
            const name_str = self.string_interner.get(id.name);
            if (name_str.len > 0 and name_str[0] == '_') continue;
            if (refs.contains(id.name)) continue;
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "'{s}' is declared but its value is never read.",
                .{name_str},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = p,
                .code = TsCodes.declared_but_not_read,
                .message = msg,
            });
        }
    }

    /// Root (leftmost) name of a `type_ref`. For a qualified name
    /// like `A.B.C` the root is `A`; for a bare `T` it's `T`. Only the
    /// root can ever resolve to a type parameter.
    fn typeRefRootName(self: *Checker, type_ref_node: NodeId) hir_mod.StringId {
        const quals = hir_mod.typeRefQualifier(self.hir, type_ref_node);
        if (quals.len > 0 and self.hir.kindOf(quals[0]) == .identifier) {
            return hir_mod.identifierOf(self.hir, quals[0]).name;
        }
        return hir_mod.typeRefOf(self.hir, type_ref_node).name;
    }

    /// True when `ancestor` lexically encloses `descendant`, walking
    /// the HIR parent chain. Bounded by `nodeCount` so a malformed
    /// (self-referential) parent link can't spin.
    fn nodeIsAncestorOf(self: *Checker, ancestor: NodeId, descendant: NodeId) bool {
        var cur = descendant;
        var guard: u32 = 0;
        const max = self.hir.nodeCount();
        while (cur != hir_mod.none_node_id and guard <= max) : (guard += 1) {
            if (cur == ancestor) return true;
            const p = self.hir.parentOf(cur);
            if (p == cur) break;
            cur = p;
        }
        return false;
    }

    /// `noUnusedParameters` (TS6133 / TS6205): report declaration type
    /// parameters that are never referenced in a type position. Mirrors
    /// tsc's `checkUnusedTypeParameters`: type parameters are gated by
    /// `noUnusedParameters` (not `noUnusedLocals`) to match upstream's
    /// `UnusedKindParameter` classification.
    fn checkUnusedTypeParameters(
        self: *Checker,
        owner_node: NodeId,
        tps: []const NodeId,
        allow_all_unused_summary: bool,
    ) CheckError!void {
        if (!self.strict_flags.no_unused_parameters) return;
        if (tps.len == 0) return;

        // Declared type-parameter names, for a cheap membership test
        // during the reference scan.
        var declared: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer declared.deinit(self.gpa);
        for (tps) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            try declared.put(self.gpa, hir_mod.typeParameterOf(self.hir, tp).name, {});
        }
        if (declared.count() == 0) return;

        // A type parameter is "used" when its name appears as the root
        // of a `type_ref` (its only possible reference form) anywhere
        // within this declaration's subtree. Matching value identifiers
        // are also counted ÃÂ¢ÃÂÃÂ type parameters can't be value-referenced,
        // so this only ever suppresses a report, never adds a spurious
        // one (keeps us safe against any reference form not modeled as a
        // `type_ref`).
        var used: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer used.deinit(self.gpa);
        const n = self.hir.nodeCount();
        var id: NodeId = 1;
        while (id < n) : (id += 1) {
            const cand: hir_mod.StringId = switch (self.hir.kindOf(id)) {
                .type_ref => self.typeRefRootName(id),
                .identifier => blk: {
                    if (self.isDeclNameSlot(id)) continue;
                    break :blk hir_mod.identifierOf(self.hir, id).name;
                },
                else => continue,
            };
            if (!declared.contains(cand) or used.contains(cand)) continue;
            if (!self.nodeIsAncestorOf(owner_node, id)) continue;
            try used.put(self.gpa, cand, {});
        }

        // All-unused case: >1 type parameter, every one unreferenced and
        // not underscore-prefixed.
        var all_unused = allow_all_unused_summary and tps.len > 1;
        for (tps) |tp| {
            const eligible = blk: {
                if (self.hir.kindOf(tp) != .type_parameter) break :blk false;
                const name = hir_mod.typeParameterOf(self.hir, tp).name;
                const name_str = self.string_interner.get(name);
                if (name_str.len > 0 and name_str[0] == '_') break :blk false;
                break :blk !used.contains(name);
            };
            if (!eligible) all_unused = false;
        }

        if (all_unused) {
            const sp = self.hir.spanOf(tps[0]).start;
            const msg = try self.diag_arena.allocator().dupe(u8, "All type parameters are unused.");
            try self.diagnostics.append(self.gpa, .{
                .node = owner_node,
                .pos = if (sp > 0) sp - 1 else sp,
                .code = TsCodes.all_type_parameters_unused,
                .message = msg,
            });
            return;
        }

        for (tps) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            const name = hir_mod.typeParameterOf(self.hir, tp).name;
            const name_str = self.string_interner.get(name);
            if (name_str.len > 0 and name_str[0] == '_') continue;
            if (used.contains(name)) continue;
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "'{s}' is declared but its value is never read.",
                .{name_str},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = tp,
                .pos = if (tps.len == 1)
                    self.typeParameterListDiagnosticStart(tp)
                else
                    self.typeParameterNameDiagnosticStart(tp),
                .code = TsCodes.declared_but_not_read,
                .message = msg,
            });
        }
    }

    fn typeParameterNameDiagnosticStart(self: *Checker, tp: NodeId) u32 {
        const sp = self.hir.spanOf(tp);
        const fallback = sp.start;
        const src = self.source orelse return fallback;
        if (sp.start >= sp.end or sp.end > src.len) return fallback;
        const tp_payload = hir_mod.typeParameterOf(self.hir, tp);
        const name = self.string_interner.get(tp_payload.name);
        if (name.len == 0) return fallback;
        const text = src[sp.start..sp.end];
        var offset: usize = 0;
        while (std.mem.indexOf(u8, text[offset..], name)) |rel| {
            const i = offset + rel;
            const before_ok = i == 0 or !asciiIdentifierContinue(text[i - 1]);
            const after = i + name.len;
            const after_ok = after >= text.len or !asciiIdentifierContinue(text[after]);
            if (before_ok and after_ok) return sp.start + @as(u32, @intCast(i));
            offset = after;
        }
        return fallback;
    }

    fn typeParameterListDiagnosticStart(self: *Checker, tp: NodeId) u32 {
        const sp = self.hir.spanOf(tp).start;
        return if (sp > 0) sp - 1 else sp;
    }

    /// Declaration merging: a class and an interface with the same
    /// name in the same root scope contribute to a single type — the
    /// interface's members the class doesn't declare join the class's
    /// instance type. Conservative subset: only non-generic sibling
    /// interfaces, only simple-named members (no call/construct/index
    /// signatures, no computed keys); on a name conflict the class's
    /// member wins. Mirrors `mergedClassInterface`.
    fn mergeSameNameInterfaceMembers(
        self: *Checker,
        class_node: NodeId,
        instance_members: *std.ArrayListUnmanaged(types.ObjectMember),
    ) CheckError!void {
        const class_name = self.declarationName(class_node) orelse return;
        const root = self.rootBlockFor(class_node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return;
        for (hir_mod.blockStmts(self.hir, root)) |raw| {
            const decl = self.unwrapExportDecl(raw);
            if (decl == hir_mod.none_node_id or self.hir.kindOf(decl) != .interface_decl) continue;
            const it = hir_mod.interfaceOf(self.hir, decl);
            if (it.name == hir_mod.none_node_id or self.hir.kindOf(it.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, it.name).name != class_name) continue;
            if (it.type_params_len > 0) continue;
            for (hir_mod.interfaceMembers(self.hir, decl)) |m| {
                if (self.hir.kindOf(m) != .interface_member) continue;
                const im = hir_mod.interfaceMemberOf(self.hir, m);
                if (im.name == 0) continue;
                if (self.syntheticSignatureMemberName(im.name)) continue;
                if (objectMemberListContains(instance_members.items, im.name)) continue;
                const member_t: TypeId = blk: {
                    if (im.type_node != hir_mod.none_node_id) {
                        break :blk self.lowererLowerWithTypeParams(im.type_node) catch types.Primitive.any;
                    }
                    break :blk types.Primitive.any;
                };
                try instance_members.append(self.gpa, .{
                    .name = im.name,
                    .type = member_t,
                    .is_optional = im.is_optional,
                    .is_readonly = im.is_readonly,
                    .is_method = im.is_method,
                });
            }
        }
    }

    fn interfaceMergesWithClass(self: *Checker, interface_node: NodeId) bool {
        if (self.hir.kindOf(interface_node) != .interface_decl) return false;
        const it = hir_mod.interfaceOf(self.hir, interface_node);
        if (it.name == hir_mod.none_node_id or self.hir.kindOf(it.name) != .identifier) return false;
        const iface_name = hir_mod.identifierOf(self.hir, it.name).name;
        const root = self.rootBlockFor(interface_node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        for (hir_mod.blockStmts(self.hir, root)) |raw| {
            const decl = self.unwrapExportDecl(raw);
            if (decl == hir_mod.none_node_id or decl == interface_node) continue;
            if (self.hir.kindOf(decl) != .class_decl and self.hir.kindOf(decl) != .class_expr) continue;
            const class_name = self.declarationName(decl) orelse continue;
            if (class_name == iface_name) return true;
        }
        return false;
    }

    /// `noUnusedParameters` (TS6133) for `catch (e) { ... }` clauses.
    /// Mirrors `checkUnusedParameters`: emits TS6133 when the catch
    /// binding's name is never read inside the catch block. Names
    /// starting with `_` are exempt by tsc convention.
    /// TS2492 — `try {} catch (e) { let e; }`. When a catch clause names
    /// a bare identifier (no type annotation, no initializer) and the
    /// catch block directly declares a block-scoped variable (`let` /
    /// `const`) of the same name, the redeclaration is an error. Mirrors
    /// upstream `checkCatchClause`, which anchors at the inner
    /// declaration's value declaration. `var` redeclarations are handled
    /// by the subsequent-declaration rule (TS2403), not here.
    fn checkCatchClauseRedeclaration(self: *Checker, catch_param: NodeId, catch_block: NodeId) CheckError!void {
        if (catch_param == hir_mod.none_node_id or catch_block == hir_mod.none_node_id) return;
        if (self.hir.kindOf(catch_param) != .identifier) return;
        if (self.hir.kindOf(catch_block) != .block_stmt) return;
        const caught_name = hir_mod.identifierOf(self.hir, catch_param).name;
        for (hir_mod.blockStmts(self.hir, catch_block)) |stmt| {
            const k = self.hir.kindOf(stmt);
            if (k != .let_decl and k != .const_decl) continue;
            const v = hir_mod.varDeclOf(self.hir, stmt);
            if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, v.name).name != caught_name) continue;
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot redeclare identifier '{s}' in catch clause.",
                .{self.string_interner.get(caught_name)},
            );
            try self.report(v.name, TsCodes.redeclare_identifier_in_catch_clause, msg);
        }
    }

    fn checkUnusedCatchParam(self: *Checker, try_node: NodeId) CheckError!void {
        if (!self.strict_flags.no_unused_parameters) return;
        const ts = hir_mod.tryOf(self.hir, try_node);
        if (ts.catch_param == hir_mod.none_node_id) return;
        if (self.hir.kindOf(ts.catch_param) != .identifier) return;
        const id = hir_mod.identifierOf(self.hir, ts.catch_param);
        const name_str = self.string_interner.get(id.name);
        if (name_str.len > 0 and name_str[0] == '_') return;
        var refs: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer refs.deinit(self.gpa);
        if (ts.catch_block != hir_mod.none_node_id) {
            try self.collectIdentifierRefs(ts.catch_block, &refs);
        }
        if (refs.contains(id.name)) return;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' is declared but its value is never read.",
            .{name_str},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = ts.catch_param,
            .code = TsCodes.declared_but_not_read,
            .message = msg,
        });
    }

    fn checkClassUsedBeforeDeclaration(self: *Checker, stmts: []const NodeId) CheckError!void {
        var class_names: std.AutoHashMapUnmanaged(hir_mod.StringId, NodeId) = .empty;
        defer class_names.deinit(self.gpa);
        var enum_names: std.AutoHashMapUnmanaged(hir_mod.StringId, NodeId) = .empty;
        defer enum_names.deinit(self.gpa);
        for (stmts) |raw| {
            try self.collectClassNamesForUseBefore(raw, &class_names);
            try self.collectEnumNamesForUseBefore(raw, &enum_names);
        }

        var declared: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer declared.deinit(self.gpa);
        var reported: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer reported.deinit(self.gpa);
        var reported_class_decls: std.AutoHashMapUnmanaged(NodeId, void) = .empty;
        defer reported_class_decls.deinit(self.gpa);
        var enum_reported: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer enum_reported.deinit(self.gpa);
        for (stmts) |raw| {
            const s = self.unwrapExportDecl(raw);
            if (s == hir_mod.none_node_id) continue;

            // Collect refs WITH nodes so the TS2449 diagnostic can
            // anchor at the actual `ClassName` reference (e.g. the
            // `C2` in `class C1 extends C2`) instead of the whole
            // statement ÃÂ¢ÃÂÃÂ matches upstream tsc column anchors. See
            // fixture `symbolProperty33.ts(1,18)`.
            var ref_nodes: std.ArrayListUnmanaged(NameRef) = .empty;
            defer ref_nodes.deinit(self.gpa);
            try self.collectIdentifierRefsWithNodes(s, &ref_nodes);
            try self.collectImportAliasClassMemberRefs(s, &class_names, &ref_nodes);
            const own_name_opt = self.classDeclarationName(s);
            for (ref_nodes.items) |ref| {
                const name = ref.name;
                if (own_name_opt) |own| {
                    if (own == name) {
                        if (!self.nodeInsideOwnClassComputedMemberKey(ref.node, s)) continue;
                        const name_str = self.string_interner.get(name);
                        const msg = try std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "Class '{s}' used before its declaration.",
                            .{name_str},
                        );
                        try self.diagnostics.append(self.gpa, .{
                            .node = ref.node,
                            .pos = ref.pos,
                            .code = TsCodes.class_used_before_declaration,
                            .message = msg,
                            .related = try self.declaredHereRelated(s, name_str),
                        });
                        continue;
                    }
                }
                if (self.identifierIsExportEqualsTarget(ref.node)) continue;
                // A reference inside a function body is DEFERRED: it runs
                // when the function is called, after the block-scoped class
                // binding is initialized in normal flow, so tsc does not
                // flag it (circularTypeofWithFunctionModule — `maker.Bar`
                // inside function `maker` merged with `namespace maker`).
                // The plain collectors already stop at function boundaries;
                // the namespace-merge member-ref path does not, so guard here.
                if (self.nodeInsideFunctionBody(ref.node)) continue;
                if (ref.target_decl != hir_mod.none_node_id) {
                    if (reported_class_decls.contains(ref.target_decl)) continue;
                    if (self.sourceHasCheckJsDirective() and self.virtualSectionIsJsLike(s)) continue;
                    const ref_pos = ref.pos orelse self.hir.spanOf(ref.node).start;
                    const target_pos = self.declarationNameSpanStart(ref.target_decl) orelse self.hir.spanOf(ref.target_decl).start;
                    if (ref_pos >= target_pos) continue;
                    const name_str = self.string_interner.get(name);
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Class '{s}' used before its declaration.",
                        .{name_str},
                    );
                    if (std.mem.indexOf(u8, self.source orelse "", "typeof maker.Bar") != null) std.debug.print("[2449-A] name={s} pos={?d} node={d} kind={s} in_fn={}\n", .{ name_str, ref.pos, ref.node, @tagName(self.hir.kindOf(ref.node)), self.nodeInsideFunctionBody(ref.node) });
                    try self.diagnostics.append(self.gpa, .{
                        .node = ref.node,
                        .pos = ref.pos,
                        .code = TsCodes.class_used_before_declaration,
                        .message = msg,
                        .related = try self.declaredHereRelated(ref.target_decl, name_str),
                    });
                    try reported_class_decls.put(self.gpa, ref.target_decl, {});
                    continue;
                }
                if (!class_names.contains(name) or declared.contains(name) or reported.contains(name)) continue;
                if (self.sourceHasVirtualFilenameSections()) {
                    const decl = class_names.get(name) orelse hir_mod.none_node_id;
                    if (decl != hir_mod.none_node_id and self.virtualSectionStartForNode(decl) != self.virtualSectionStartForNode(ref.node)) continue;
                }
                if (self.sourceHasCheckJsDirective() and self.virtualSectionIsJsLike(s)) continue;
                const name_str = self.string_interner.get(name);
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Class '{s}' used before its declaration.",
                    .{name_str},
                );
                try self.diagnostics.append(self.gpa, .{
                    .node = ref.node,
                    .pos = ref.pos,
                    .code = TsCodes.class_used_before_declaration,
                    .message = msg,
                });
                try reported.put(self.gpa, name, {});
            }
            // TS2450 mirror of the class-anchored TS2449 loop. Enums
            // don't hoist their value bindings, so `let x = E.A; enum
            // E { A }` references E before declaration. Skip the
            // enum's own self-name (a computed member can reference
            // the enum being declared, which is legal).
            const own_enum_name_opt: ?hir_mod.StringId = blk_self_enum: {
                if (self.hir.kindOf(s) == .enum_decl) {
                    const e_self = hir_mod.enumOf(self.hir, s);
                    if (e_self.name != hir_mod.none_node_id and self.hir.kindOf(e_self.name) == .identifier) {
                        break :blk_self_enum hir_mod.identifierOf(self.hir, e_self.name).name;
                    }
                }
                break :blk_self_enum null;
            };
            for (ref_nodes.items) |ref| {
                const name = ref.name;
                if (own_enum_name_opt) |own| {
                    if (own == name) continue;
                }
                if (self.identifierIsExportEqualsTarget(ref.node)) continue;
                if (!enum_names.contains(name) or declared.contains(name) or enum_reported.contains(name)) continue;
                if (self.sourceHasCheckJsDirective() and self.virtualSectionIsJsLike(s)) continue;
                const name_str = self.string_interner.get(name);
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Enum '{s}' used before its declaration.",
                    .{name_str},
                );
                try self.diagnostics.append(self.gpa, .{
                    .node = ref.node,
                    .pos = ref.pos,
                    .code = TsCodes.enum_used_before_declaration,
                    .message = msg,
                });
                try enum_reported.put(self.gpa, name, {});
            }

            const k = self.hir.kindOf(s);
            if (k == .var_decl or k == .let_decl or k == .const_decl) {
                const v = hir_mod.varDeclOf(self.hir, s);
                if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                    try declared.put(self.gpa, hir_mod.identifierOf(self.hir, v.name).name, {});
                }
            } else if (k == .fn_decl or k == .fn_expr) {
                const f = hir_mod.fnDeclOf(self.hir, s);
                if (f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier) {
                    try declared.put(self.gpa, hir_mod.identifierOf(self.hir, f.name).name, {});
                }
            } else if (k == .class_decl or k == .class_expr) {
                const c = hir_mod.classOf(self.hir, s);
                if (c.name != hir_mod.none_node_id and self.hir.kindOf(c.name) == .identifier) {
                    const id = hir_mod.identifierOf(self.hir, c.name);
                    try declared.put(self.gpa, id.name, {});
                }
            } else if (k == .enum_decl) {
                const ed = hir_mod.enumOf(self.hir, s);
                if (ed.name != hir_mod.none_node_id and self.hir.kindOf(ed.name) == .identifier) {
                    const id = hir_mod.identifierOf(self.hir, ed.name);
                    try declared.put(self.gpa, id.name, {});
                }
            } else if (k == .namespace_decl or k == .module_decl) {
                // A class declared inside a namespace is referenced as
                // `M.C` from outside, never bare `C`, so its declaration
                // order is local to the namespace body. Recurse with a
                // fresh statement-ordered analysis instead of flattening
                // inner names into this scope (which produced a spurious
                // TS2449 for `(new C)[...]` placed after `class C` inside
                // the same namespace ÃÂ¢ÃÂÃÂ see ES5SymbolProperty2.ts).
                try self.checkClassUsedBeforeDeclaration(hir_mod.namespaceBody(self.hir, s));
                try self.markClassNamesDeclaredInNode(s, &declared);
            }
        }
    }

    fn collectClassNamesForUseBefore(
        self: *Checker,
        node: NodeId,
        out: *std.AutoHashMapUnmanaged(hir_mod.StringId, NodeId),
    ) CheckError!void {
        const s = self.unwrapExportDecl(node);
        if (s == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(s)) {
            .class_decl, .class_expr => {
                const c = hir_mod.classOf(self.hir, s);
                if (c.name == hir_mod.none_node_id or self.hir.kindOf(c.name) != .identifier) return;
                const id = hir_mod.identifierOf(self.hir, c.name);
                try out.put(self.gpa, id.name, s);
            },
            // Classes declared inside a namespace belong to that
            // namespace's own statement-ordered analysis (run via the
            // recursive `checkClassUsedBeforeDeclaration` call); they are
            // never referenced bare from the enclosing scope, so they
            // must not join the outer scope's class-name set.
            .namespace_decl, .module_decl => {},
            else => {},
        }
    }

    fn markClassNamesDeclaredInNode(
        self: *Checker,
        node: NodeId,
        out: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
    ) CheckError!void {
        const s = self.unwrapExportDecl(node);
        if (s == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(s)) {
            .class_decl, .class_expr => {
                const c = hir_mod.classOf(self.hir, s);
                if (c.name == hir_mod.none_node_id or self.hir.kindOf(c.name) != .identifier) return;
                const id = hir_mod.identifierOf(self.hir, c.name);
                try out.put(self.gpa, id.name, {});
            },
            .namespace_decl, .module_decl => for (hir_mod.namespaceBody(self.hir, s)) |inner| {
                try self.markClassNamesDeclaredInNode(inner, out);
            },
            else => {},
        }
    }

    /// Mirror of `collectClassNamesForUseBefore` for enum decls.
    /// Top-level enums in a statement list contribute to the TS2450
    /// use-before-decl scan; namespace-nested enums get their own
    /// recursive scan via `checkClassUsedBeforeDeclaration`, so we
    /// skip them at this level for the same reason.
    fn collectEnumNamesForUseBefore(
        self: *Checker,
        node: NodeId,
        out: *std.AutoHashMapUnmanaged(hir_mod.StringId, NodeId),
    ) CheckError!void {
        const s = self.unwrapExportDecl(node);
        if (s == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(s)) {
            .enum_decl => {
                const e = hir_mod.enumOf(self.hir, s);
                if (e.name == hir_mod.none_node_id or self.hir.kindOf(e.name) != .identifier) return;
                const id = hir_mod.identifierOf(self.hir, e.name);
                try out.put(self.gpa, id.name, s);
            },
            .namespace_decl, .module_decl => {},
            else => {},
        }
    }

    fn classDeclarationName(self: *Checker, node: NodeId) ?hir_mod.StringId {
        if (node == hir_mod.none_node_id) return null;
        const k = self.hir.kindOf(node);
        if (k != .class_decl and k != .class_expr) return null;
        const c = hir_mod.classOf(self.hir, node);
        if (c.name == hir_mod.none_node_id or self.hir.kindOf(c.name) != .identifier) return null;
        return hir_mod.identifierOf(self.hir, c.name).name;
    }

    fn nodeInsideOwnClassComputedMemberKey(self: *Checker, node: NodeId, class_node: NodeId) bool {
        var child = node;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id and cur != class_node) : ({
            child = cur;
            cur = self.hir.parentOf(cur);
        }) {
            const is_computed_key = switch (self.hir.kindOf(cur)) {
                .object_property => blk: {
                    const op = hir_mod.objectPropertyOf(self.hir, cur);
                    break :blk op.is_computed and op.key == child;
                },
                .fn_decl, .fn_expr => blk: {
                    const f = hir_mod.fnDeclOf(self.hir, cur);
                    break :blk f.name == child and self.nodeIsBracketedComputedName(f.name);
                },
                else => false,
            };
            if (!is_computed_key) continue;
            for (hir_mod.classMembers(self.hir, class_node)) |member| {
                if (member == cur) return true;
            }
            return false;
        }
        return false;
    }

    /// Recursively collect every identifier StringId reachable from
    /// `node` that is *not* the name slot of a declaration. Stops
    /// at nested function boundaries so inner-fn references don't
    /// satisfy outer-fn parameters.
    fn collectIdentifierRefs(
        self: *Checker,
        node: NodeId,
        out: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        const k = self.hir.kindOf(node);
        switch (k) {
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, node);
                if (!self.isDeclNameSlot(node)) try out.put(self.gpa, id.name, {});
            },
            // Nested fns shadow the outer scope ÃÂ¢ÃÂÃÂ skip them.
            .fn_decl, .fn_expr, .arrow_fn => return,
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |s| try self.collectIdentifierRefs(s, out);
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                try self.collectIdentifierRefs(i.cond, out);
                try self.collectIdentifierRefs(i.then_branch, out);
                try self.collectIdentifierRefs(i.else_branch, out);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                try self.collectIdentifierRefs(w.cond, out);
                try self.collectIdentifierRefs(w.body, out);
            },
            .do_while_stmt => {
                const w = hir_mod.doWhileOf(self.hir, node);
                try self.collectIdentifierRefs(w.cond, out);
                try self.collectIdentifierRefs(w.body, out);
            },
            .for_stmt => {
                const fr = hir_mod.forStmtOf(self.hir, node);
                try self.collectIdentifierRefs(fr.init, out);
                try self.collectIdentifierRefs(fr.cond, out);
                try self.collectIdentifierRefs(fr.update, out);
                try self.collectIdentifierRefs(fr.body, out);
            },
            .return_stmt => {
                const r = hir_mod.returnOf(self.hir, node);
                try self.collectIdentifierRefs(r.value, out);
            },
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, node);
                // Skip `v.name` ÃÂ¢ÃÂÃÂ it's the declaration site.
                try self.collectIdentifierRefs(v.init, out);
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                try self.collectIdentifierRefs(b.lhs, out);
                try self.collectIdentifierRefs(b.rhs, out);
            },
            .unary_op => {
                const u = hir_mod.unaryOf(self.hir, node);
                try self.collectIdentifierRefs(u.operand, out);
            },
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                try self.collectIdentifierRefs(l.lhs, out);
                try self.collectIdentifierRefs(l.rhs, out);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                try self.collectIdentifierRefs(c.cond, out);
                try self.collectIdentifierRefs(c.then_branch, out);
                try self.collectIdentifierRefs(c.else_branch, out);
            },
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                if (a.op == null) {
                    try self.collectIdentifierRefsInAssignmentTarget(a.target, out);
                } else {
                    try self.collectIdentifierRefs(a.target, out);
                }
                try self.collectIdentifierRefs(a.value, out);
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                try self.collectIdentifierRefs(c.callee, out);
                for (hir_mod.callArgs(self.hir, node)) |arg| try self.collectIdentifierRefs(arg, out);
            },
            .member_access => {
                const m = hir_mod.memberOf(self.hir, node);
                try self.collectIdentifierRefs(m.object, out);
                // `m.name` is a StringId, not a node ÃÂ¢ÃÂÃÂ no descend.
            },
            .class_decl, .class_expr => {
                const c = hir_mod.classOf(self.hir, node);
                try self.collectIdentifierRefs(c.extends, out);
                for (hir_mod.classMembers(self.hir, node)) |m| try self.collectIdentifierRefs(m, out);
            },
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                try self.collectIdentifierRefs(e.object, out);
                try self.collectIdentifierRefs(e.index, out);
            },
            .as_expr, .satisfies_expr, .type_assertion => {
                const a = hir_mod.asExpressionOf(self.hir, node);
                try self.collectIdentifierRefs(a.expr, out);
            },
            .throw_stmt => {
                const t = hir_mod.throwOf(self.hir, node);
                try self.collectIdentifierRefs(t.value, out);
            },
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                try self.collectIdentifierRefs(ts.block, out);
                try self.collectIdentifierRefs(ts.catch_block, out);
                try self.collectIdentifierRefs(ts.finally_block, out);
            },
            .switch_stmt => {
                const sw = hir_mod.switchOf(self.hir, node);
                try self.collectIdentifierRefs(sw.discriminant, out);
                for (hir_mod.switchCases(self.hir, node)) |case| try self.collectIdentifierRefs(case, out);
            },
            .switch_case => {
                for (hir_mod.switchCaseStmts(self.hir, node)) |s| try self.collectIdentifierRefs(s, out);
            },
            .array_literal => {
                for (hir_mod.arrayLiteralElements(self.hir, node)) |el| try self.collectIdentifierRefs(el, out);
            },
            .spread => {
                const sp = hir_mod.spreadOf(self.hir, node);
                try self.collectIdentifierRefs(sp.expression, out);
            },
            .object_literal => {
                for (hir_mod.objectLiteralProps(self.hir, node)) |p| try self.collectIdentifierRefs(p, out);
            },
            .object_property => {
                const op = hir_mod.objectPropertyOf(self.hir, node);
                try self.collectIdentifierRefs(op.value, out);
                // Computed keys reference identifiers; skip the name slot.
                if (op.is_computed) try self.collectIdentifierRefs(op.key, out);
            },
            else => {},
        }
    }

    fn collectIdentifierRefsInAssignmentTarget(
        self: *Checker,
        node: NodeId,
        out: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .identifier => return,
            .member_access => {
                const m = hir_mod.memberOf(self.hir, node);
                try self.collectIdentifierRefs(m.object, out);
            },
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                try self.collectIdentifierRefs(e.object, out);
                try self.collectIdentifierRefs(e.index, out);
            },
            .array_literal, .array_pattern => {
                const elems = if (self.hir.kindOf(node) == .array_literal)
                    hir_mod.arrayLiteralElements(self.hir, node)
                else
                    hir_mod.patternElements(self.hir, node);
                for (elems) |el| {
                    if (el == hir_mod.none_node_id) continue;
                    switch (self.hir.kindOf(el)) {
                        .spread => try self.collectIdentifierRefsInAssignmentTarget(hir_mod.spreadOf(self.hir, el).expression, out),
                        .assignment => {
                            const a = hir_mod.assignmentOf(self.hir, el);
                            try self.collectIdentifierRefsInAssignmentTarget(a.target, out);
                            try self.collectIdentifierRefs(a.value, out);
                        },
                        else => try self.collectIdentifierRefsInAssignmentTarget(el, out),
                    }
                }
            },
            .object_literal, .object_pattern => {
                const props = if (self.hir.kindOf(node) == .object_literal)
                    hir_mod.objectLiteralProps(self.hir, node)
                else
                    hir_mod.patternElements(self.hir, node);
                for (props) |prop| {
                    switch (self.hir.kindOf(prop)) {
                        .object_property => {
                            const op = hir_mod.objectPropertyOf(self.hir, prop);
                            if (op.is_computed) try self.collectIdentifierRefs(op.key, out);
                            if (op.value == hir_mod.none_node_id) continue;
                            if (self.hir.kindOf(op.value) == .assignment) {
                                const a = hir_mod.assignmentOf(self.hir, op.value);
                                try self.collectIdentifierRefsInAssignmentTarget(a.target, out);
                                try self.collectIdentifierRefs(a.value, out);
                            } else {
                                try self.collectIdentifierRefsInAssignmentTarget(op.value, out);
                            }
                        },
                        .spread => try self.collectIdentifierRefsInAssignmentTarget(hir_mod.spreadOf(self.hir, prop).expression, out),
                        else => try self.collectIdentifierRefsInAssignmentTarget(prop, out),
                    }
                }
            },
            else => try self.collectIdentifierRefs(node, out),
        }
    }

    const BindingDefaultMode = enum { variable, parameter };
    const BindingSlot = struct {
        name: hir_mod.StringId,
        node: NodeId,
        default_value: NodeId,
    };
    const NameRef = struct {
        name: hir_mod.StringId,
        node: NodeId,
        pos: ?u32 = null,
        target_decl: NodeId = hir_mod.none_node_id,
    };
    const PrivateMemberCandidateMap = std.AutoArrayHashMapUnmanaged(hir_mod.StringId, NodeId);

    fn checkFnParameterDuplicateNames(self: *Checker, fn_node: NodeId) CheckError!void {
        const params = hir_mod.fnParams(self.hir, fn_node);
        if (params.len < 2) return;
        var counts: std.AutoHashMapUnmanaged(hir_mod.StringId, u32) = .empty;
        defer counts.deinit(self.gpa);
        for (params) |param| {
            if (self.hir.kindOf(param) != .parameter) continue;
            const p = hir_mod.parameterOf(self.hir, param);
            if (p.name == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(p.name) != .identifier) continue;
            const id = hir_mod.identifierOf(self.hir, p.name);
            const gop = try counts.getOrPut(self.gpa, id.name);
            if (gop.found_existing) {
                gop.value_ptr.* += 1;
            } else {
                gop.value_ptr.* = 1;
            }
        }
        for (params) |param| {
            if (self.hir.kindOf(param) != .parameter) continue;
            const p = hir_mod.parameterOf(self.hir, param);
            if (p.name == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(p.name) != .identifier) continue;
            const id = hir_mod.identifierOf(self.hir, p.name);
            if (counts.get(id.name)) |c| {
                if (c > 1) try self.reportDuplicateIdentifier(param, id.name);
            }
        }
    }

    /// TS2396 ÃÂ¢ÃÂÃÂ a function targeting < ES2015 that has a rest
    /// parameter and a real body must not also declare a parameter
    /// named `arguments`; the downlevel emit synthesizes `arguments`
    /// references to materialize the rest array. Mirrors upstream
    /// `checkCollisionWithArgumentsInGeneratedCode`.
    fn checkArgumentsCollisionWithRestParameter(self: *Checker, fn_node: NodeId) CheckError!void {
        if (!self.sourceTargetMentionsEs5()) return;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        // Ambient declarations (no body) emit nothing, so no collision.
        if (f.body == hir_mod.none_node_id) return;
        const params = hir_mod.fnParams(self.hir, fn_node);
        var has_rest = false;
        for (params) |param| {
            if (self.hir.kindOf(param) != .parameter) continue;
            if (hir_mod.parameterOf(self.hir, param).flags.is_rest) {
                has_rest = true;
                break;
            }
        }
        if (!has_rest) return;
        const arguments_id = self.string_interner.intern("arguments") catch return error.OutOfMemory;
        for (params) |param| {
            if (self.hir.kindOf(param) != .parameter) continue;
            const p = hir_mod.parameterOf(self.hir, param);
            if (p.name == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(p.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, p.name).name != arguments_id) continue;
            try self.report(p.name, TsCodes.duplicate_identifier_arguments_rest, "Duplicate identifier 'arguments'. Compiler uses 'arguments' to initialize rest parameters.");
        }
    }

    fn checkFnParameterDefaultReferences(self: *Checker, fn_node: NodeId) CheckError!void {
        var body_vars: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer body_vars.deinit(self.gpa);
        const fn_payload = hir_mod.fnDeclOf(self.hir, fn_node);
        try self.collectVarDeclNames(fn_payload.body, &body_vars);
        for (hir_mod.fnParams(self.hir, fn_node)) |p| {
            if (self.hir.kindOf(p) != .parameter) continue;
            const pp = hir_mod.parameterOf(self.hir, p);
            if (pp.name == hir_mod.none_node_id) continue;
            const nk = self.hir.kindOf(pp.name);
            if (nk == .object_pattern or nk == .array_pattern) {
                try self.checkPatternComputedBindingKeys(pp.name);
                try self.checkPatternComputedBindingKeysAgainstBodyVars(pp.name, &body_vars);
                try self.checkBindingPatternDefaultReferences(pp.name, .parameter);
                try self.checkPatternDefaultsAgainstBodyVars(pp.name, &body_vars);
            }
            if (pp.default_value != hir_mod.none_node_id) {
                _ = try self.checkExpression(pp.default_value);
                if (!self.sourceHasUseDefineForClassFieldsTrueDirective()) {
                    const param_name_id: ?hir_mod.StringId = if (nk == .identifier)
                        hir_mod.identifierOf(self.hir, pp.name).name
                    else
                        null;
                    // For object/array patterns, tsc renders the
                    // pattern's source text as the parameter's display
                    // name: `Parameter '{ b = a(), ...x }' cannot
                    // reference identifier 'a' declared after it.`.
                    // Mirrors `parameterInitializersForwardReferencing.2`.
                    const pattern_node: ?NodeId = if (nk == .object_pattern or nk == .array_pattern)
                        pp.name
                    else
                        null;
                    try self.checkDefaultExprAgainstBodyVarsWithPattern(pp.default_value, &body_vars, param_name_id, pattern_node);
                }
                // TS2372: `function f(x = x) {}` ÃÂ¢ÃÂÃÂ the default
                // expression mentions the same identifier as the
                // parameter being declared. tsc anchors the diagnostic
                // at the offending reference node so the column matches
                // upstream (`asyncFunctionDeclaration3_es2017.ts(1,20)`).
                if (nk == .identifier) {
                    const param_name_id = hir_mod.identifierOf(self.hir, pp.name).name;
                    var refs: std.ArrayListUnmanaged(NameRef) = .empty;
                    defer refs.deinit(self.gpa);
                    try self.collectIdentifierRefsWithNodes(pp.default_value, &refs);
                    for (refs.items) |ref| {
                        if (ref.name == param_name_id) {
                            try self.reportBindingDefaultReferenceNamed(ref.node, .parameter, true, param_name_id, ref.name);
                            break;
                        }
                    }
                }
            }
            if (nk == .array_pattern and pp.default_value != hir_mod.none_node_id) {
                const default_t = try self.checkExpression(pp.default_value);
                if (!self.isIterableLikeType(default_t) and !self.objectLiteralHasSymbolIteratorMethod(pp.default_value)) {
                    if (self.target_es5_baseline) {
                        try self.reportTypeNotArrayForTarget(pp.name, default_t);
                    } else {
                        try self.report(pp.name, TsCodes.yield_star_not_iterable, "Type must have a '[Symbol.iterator]()' method that returns an iterator.");
                    }
                }
            }
            if (nk == .object_pattern and pp.type_annotation != hir_mod.none_node_id) {
                const param_t = self.hir.typeOf(p);
                if (param_t != types.Primitive.none) try self.checkObjectBindingPatternAgainstType(pp.name, param_t, true);
            } else if (nk == .array_pattern and pp.type_annotation != hir_mod.none_node_id) {
                const param_t = self.hir.typeOf(p);
                if (param_t != types.Primitive.none) try self.checkArrayBindingPatternAgainstType(pp.name, param_t);
            }
        }
    }

    fn collectVarDeclNames(
        self: *Checker,
        node: NodeId,
        out: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .block_stmt => for (hir_mod.blockStmts(self.hir, node)) |s| try self.collectVarDeclNames(s, out),
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, node);
                try self.collectBindingNames(v.name, out);
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                try self.collectVarDeclNames(i.then_branch, out);
                try self.collectVarDeclNames(i.else_branch, out);
            },
            .for_stmt => {
                const fr = hir_mod.forStmtOf(self.hir, node);
                try self.collectVarDeclNames(fr.init, out);
                try self.collectVarDeclNames(fr.body, out);
            },
            .for_in_stmt, .for_of_stmt => {
                const fr = hir_mod.forInOf(self.hir, node);
                try self.collectVarDeclNames(fr.target, out);
                try self.collectVarDeclNames(fr.body, out);
            },
            .while_stmt => try self.collectVarDeclNames(hir_mod.whileOf(self.hir, node).body, out),
            .do_while_stmt => try self.collectVarDeclNames(hir_mod.doWhileOf(self.hir, node).body, out),
            .switch_stmt => for (hir_mod.switchCases(self.hir, node)) |case| try self.collectVarDeclNames(case, out),
            .switch_case => for (hir_mod.switchCaseStmts(self.hir, node)) |s| try self.collectVarDeclNames(s, out),
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                try self.collectVarDeclNames(ts.block, out);
                try self.collectVarDeclNames(ts.catch_block, out);
                try self.collectVarDeclNames(ts.finally_block, out);
            },
            .fn_decl, .fn_expr, .arrow_fn, .class_decl, .class_expr => return,
            else => {},
        }
    }

    fn collectBindingNames(
        self: *Checker,
        node: NodeId,
        out: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, node);
                try out.put(self.gpa, id.name, {});
            },
            .object_pattern, .array_pattern => {
                var slots: std.ArrayListUnmanaged(BindingSlot) = .empty;
                defer slots.deinit(self.gpa);
                try self.collectBindingSlots(node, &slots);
                for (slots.items) |slot| try out.put(self.gpa, slot.name, {});
            },
            else => {},
        }
    }

    fn checkPatternDefaultsAgainstBodyVars(
        self: *Checker,
        pattern_node: NodeId,
        body_vars: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
    ) CheckError!void {
        var slots: std.ArrayListUnmanaged(BindingSlot) = .empty;
        defer slots.deinit(self.gpa);
        try self.collectBindingSlots(pattern_node, &slots);
        for (slots.items) |slot| {
            if (slot.default_value == hir_mod.none_node_id) continue;
            try self.checkDefaultExprAgainstBodyVars(slot.default_value, body_vars, slot.name);
        }
    }

    fn checkDefaultExprAgainstBodyVars(
        self: *Checker,
        default_value: NodeId,
        body_vars: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
        param_name: ?hir_mod.StringId,
    ) CheckError!void {
        try self.checkDefaultExprAgainstBodyVarsWithPattern(default_value, body_vars, param_name, null);
    }

    fn checkDefaultExprAgainstBodyVarsWithPattern(
        self: *Checker,
        default_value: NodeId,
        body_vars: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
        param_name: ?hir_mod.StringId,
        pattern_node: ?NodeId,
    ) CheckError!void {
        var refs: std.ArrayListUnmanaged(NameRef) = .empty;
        defer refs.deinit(self.gpa);
        try self.collectIdentifierRefsWithNodes(default_value, &refs);
        for (refs.items) |ref| {
            if (param_name != null and ref.name == param_name.?) continue;
            if (body_vars.contains(ref.name)) {
                try self.reportBindingDefaultReferenceNamedWithPattern(
                    ref.node,
                    .parameter,
                    false,
                    param_name,
                    ref.name,
                    pattern_node,
                );
            }
        }
    }

    fn checkBindingPatternDefaultReferences(
        self: *Checker,
        pattern_node: NodeId,
        mode: BindingDefaultMode,
    ) CheckError!void {
        var slots: std.ArrayListUnmanaged(BindingSlot) = .empty;
        defer slots.deinit(self.gpa);
        try self.collectBindingSlots(pattern_node, &slots);
        for (slots.items, 0..) |slot, i| {
            if (slot.default_value == hir_mod.none_node_id) continue;
            var refs: std.ArrayListUnmanaged(NameRef) = .empty;
            defer refs.deinit(self.gpa);
            try self.collectIdentifierRefsWithNodes(slot.default_value, &refs);
            for (refs.items) |ref| {
                var j: usize = i;
                while (j < slots.items.len) : (j += 1) {
                    const later = slots.items[j];
                    if (later.name != ref.name) continue;
                    try self.reportBindingDefaultReferenceNamed(ref.node, mode, j == i, slot.name, ref.name);
                    break;
                }
            }
        }
    }

    fn collectBindingSlots(
        self: *Checker,
        pattern_node: NodeId,
        out: *std.ArrayListUnmanaged(BindingSlot),
    ) CheckError!void {
        const pk = self.hir.kindOf(pattern_node);
        if (pk != .object_pattern and pk != .array_pattern) return;
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.flags.is_computed_binding_key) continue;
            if (ep.name == hir_mod.none_node_id) continue;
            const nk = self.hir.kindOf(ep.name);
            if (nk == .identifier) {
                const id = hir_mod.identifierOf(self.hir, ep.name);
                try out.append(self.gpa, .{
                    .name = id.name,
                    .node = ep.name,
                    .default_value = ep.default_value,
                });
            } else if (nk == .object_pattern or nk == .array_pattern) {
                try self.collectBindingSlots(ep.name, out);
            }
        }
    }

    fn checkPatternComputedBindingKeys(self: *Checker, pattern_node: NodeId) CheckError!void {
        const pk = self.hir.kindOf(pattern_node);
        if (pk != .object_pattern and pk != .array_pattern) return;
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.flags.is_computed_binding_key) {
                if (ep.default_value != hir_mod.none_node_id) _ = try self.checkExpression(ep.default_value);
                continue;
            }
            if (ep.name == hir_mod.none_node_id) continue;
            const nk = self.hir.kindOf(ep.name);
            if (nk == .object_pattern or nk == .array_pattern) {
                try self.checkPatternComputedBindingKeys(ep.name);
            }
        }
    }

    /// True iff `node` is nested inside a class expression/declaration that
    /// lies on the path between `node` and `root` (exclusive of `root`). Used
    /// to exclude class-scoped references from the parameter forward-reference
    /// check, since a nested class has its own scope.
    fn nodeIsInsideNestedClassWithin(self: *Checker, node: NodeId, root: NodeId) bool {
        var cur: hir_mod.NodeId = node;
        while (cur != hir_mod.none_node_id and cur != root) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .class_decl or k == .class_expr) return true;
        }
        return false;
    }

    fn checkPatternComputedBindingKeysAgainstBodyVars(
        self: *Checker,
        pattern_node: NodeId,
        body_vars: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
    ) CheckError!void {
        const pk = self.hir.kindOf(pattern_node);
        if (pk != .object_pattern and pk != .array_pattern) return;
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.flags.is_computed_binding_key) {
                var refs: std.ArrayListUnmanaged(NameRef) = .empty;
                defer refs.deinit(self.gpa);
                try self.collectIdentifierRefsWithNodes(ep.default_value, &refs);
                for (refs.items) |ref| {
                    if (!body_vars.contains(ref.name)) continue;
                    // Under `useDefineForClassFields`, a reference nested inside
                    // a class expression/declaration (e.g. its heritage in
                    // `[class extends C {}.x]`) is not treated as a parameter
                    // forward reference and tsc emits no TS2373. With the flag
                    // OFF, tsc DOES report it — the two variants of
                    // classWithStaticFieldInParameterBindingPattern differ only
                    // by this flag (.3 true ⇒ no error, .2 false ⇒ TS2373).
                    if (self.sourceHasUseDefineForClassFieldsTrueDirective() and
                        self.nodeIsInsideNestedClassWithin(ref.node, ep.default_value)) continue;
                    try self.reportBindingDefaultReferenceNamedWithPattern(
                        ref.node,
                        .parameter,
                        false,
                        null,
                        ref.name,
                        pattern_node,
                    );
                }
                continue;
            }
            if (ep.name == hir_mod.none_node_id) continue;
            const nk = self.hir.kindOf(ep.name);
            if (nk == .object_pattern or nk == .array_pattern) {
                try self.checkPatternComputedBindingKeysAgainstBodyVars(ep.name, body_vars);
            }
        }
    }

    fn collectIdentifierRefsWithNodes(
        self: *Checker,
        node: NodeId,
        out: *std.ArrayListUnmanaged(NameRef),
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, node);
                try out.append(self.gpa, .{ .name = id.name, .node = node });
            },
            .fn_decl, .fn_expr => {
                const f = hir_mod.fnDeclOf(self.hir, node);
                if (f.name != hir_mod.none_node_id and self.nodeIsBracketedComputedName(f.name)) {
                    try self.collectIdentifierRefsWithNodes(f.name, out);
                }
                return;
            },
            .arrow_fn => return,
            .block_stmt => for (hir_mod.blockStmts(self.hir, node)) |s| try self.collectIdentifierRefsWithNodes(s, out),
            .return_stmt => try self.collectIdentifierRefsWithNodes(hir_mod.returnOf(self.hir, node).value, out),
            .throw_stmt => try self.collectIdentifierRefsWithNodes(hir_mod.throwOf(self.hir, node).value, out),
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, node);
                try self.collectIdentifierRefsWithNodes(v.init, out);
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                try self.collectIdentifierRefsWithNodes(b.lhs, out);
                try self.collectIdentifierRefsWithNodes(b.rhs, out);
            },
            .unary_op => try self.collectIdentifierRefsWithNodes(hir_mod.unaryOf(self.hir, node).operand, out),
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                try self.collectIdentifierRefsWithNodes(l.lhs, out);
                try self.collectIdentifierRefsWithNodes(l.rhs, out);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                try self.collectIdentifierRefsWithNodes(c.cond, out);
                try self.collectIdentifierRefsWithNodes(c.then_branch, out);
                try self.collectIdentifierRefsWithNodes(c.else_branch, out);
            },
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                try self.collectIdentifierRefsWithNodes(a.target, out);
                try self.collectIdentifierRefsWithNodes(a.value, out);
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                try self.collectIdentifierRefsWithNodes(c.callee, out);
                for (hir_mod.callArgs(self.hir, node)) |arg| try self.collectIdentifierRefsWithNodes(arg, out);
            },
            .member_access => {
                const m = hir_mod.memberOf(self.hir, node);
                if (self.findQualifiedClassDecl(node)) |target_decl| {
                    try out.append(self.gpa, .{
                        .name = m.name,
                        .node = node,
                        .pos = self.memberAccessNamePos(node),
                        .target_decl = target_decl,
                    });
                }
                try self.collectIdentifierRefsWithNodes(m.object, out);
            },
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                try self.collectIdentifierRefsWithNodes(e.object, out);
                try self.collectIdentifierRefsWithNodes(e.index, out);
            },
            .as_expr, .satisfies_expr, .type_assertion, .non_null_expr => {
                const a = hir_mod.asExpressionOf(self.hir, node);
                try self.collectIdentifierRefsWithNodes(a.expr, out);
            },
            .array_literal => for (hir_mod.arrayLiteralElements(self.hir, node)) |el| try self.collectIdentifierRefsWithNodes(el, out),
            .spread => try self.collectIdentifierRefsWithNodes(hir_mod.spreadOf(self.hir, node).expression, out),
            .object_literal => for (hir_mod.objectLiteralProps(self.hir, node)) |p| try self.collectIdentifierRefsWithNodes(p, out),
            .object_property => {
                const op = hir_mod.objectPropertyOf(self.hir, node);
                try self.collectIdentifierRefsWithNodes(op.value, out);
                if (op.is_computed) try self.collectIdentifierRefsWithNodes(op.key, out);
            },
            .class_decl, .class_expr => {
                const c = hir_mod.classOf(self.hir, node);
                try self.collectIdentifierRefsWithNodes(c.extends, out);
                for (hir_mod.classMembers(self.hir, node)) |m| try self.collectIdentifierRefsWithNodes(m, out);
            },
            .type_ref => {
                const r = hir_mod.typeRefOf(self.hir, node);
                const pos = self.qualifiedTypeRefLeafNamePos(node) orelse self.hir.spanOf(node).start;
                const target_decl = self.visibleClassDeclForHeritageTypeRef(node) orelse hir_mod.none_node_id;
                try out.append(self.gpa, .{
                    .name = r.name,
                    .node = node,
                    .pos = pos,
                    .target_decl = target_decl,
                });
                for (hir_mod.typeRefArgs(self.hir, node)) |arg| try self.collectIdentifierRefsWithNodes(arg, out);
            },
            .namespace_decl, .module_decl => {
                for (hir_mod.namespaceBody(self.hir, node)) |s| try self.collectIdentifierRefsWithNodes(s, out);
            },
            .export_decl => {
                const ex = hir_mod.exportOf(self.hir, node);
                try self.collectIdentifierRefsWithNodes(ex.decl, out);
            },
            else => {},
        }
    }

    fn varInitializerReferencesOwnBinding(self: *Checker, init_node: NodeId, name: hir_mod.StringId) CheckError!bool {
        var refs: std.ArrayListUnmanaged(NameRef) = .empty;
        defer refs.deinit(self.gpa);
        try self.collectIdentifierRefsWithNodes(init_node, &refs);
        for (refs.items) |ref| {
            if (ref.name == name) return true;
        }
        return false;
    }

    fn nodeInsideFunctionBody(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .fn_decl, .fn_expr, .arrow_fn => return true,
                else => {},
            }
        }
        return false;
    }

    fn collectImportAliasClassMemberRefs(
        self: *Checker,
        node: NodeId,
        class_names: *const std.AutoHashMapUnmanaged(hir_mod.StringId, NodeId),
        out: *std.ArrayListUnmanaged(NameRef),
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .member_access => {
                const m = hir_mod.memberOf(self.hir, node);
                if (self.memberAccessImportAliasClassDecl(m.object, m.name)) |target| {
                    try out.append(self.gpa, .{
                        .name = m.name,
                        .node = node,
                        .pos = self.memberAccessNamePos(node),
                        .target_decl = target,
                    });
                }
                try self.collectImportAliasClassMemberRefs(m.object, class_names, out);
            },
            .fn_decl, .fn_expr, .arrow_fn => return,
            .block_stmt => for (hir_mod.blockStmts(self.hir, node)) |s| try self.collectImportAliasClassMemberRefs(s, class_names, out),
            .return_stmt => try self.collectImportAliasClassMemberRefs(hir_mod.returnOf(self.hir, node).value, class_names, out),
            .throw_stmt => try self.collectImportAliasClassMemberRefs(hir_mod.throwOf(self.hir, node).value, class_names, out),
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, node);
                try self.collectImportAliasClassMemberRefs(v.init, class_names, out);
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                try self.collectImportAliasClassMemberRefs(b.lhs, class_names, out);
                try self.collectImportAliasClassMemberRefs(b.rhs, class_names, out);
            },
            .unary_op => try self.collectImportAliasClassMemberRefs(hir_mod.unaryOf(self.hir, node).operand, class_names, out),
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                try self.collectImportAliasClassMemberRefs(l.lhs, class_names, out);
                try self.collectImportAliasClassMemberRefs(l.rhs, class_names, out);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                try self.collectImportAliasClassMemberRefs(c.cond, class_names, out);
                try self.collectImportAliasClassMemberRefs(c.then_branch, class_names, out);
                try self.collectImportAliasClassMemberRefs(c.else_branch, class_names, out);
            },
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                try self.collectImportAliasClassMemberRefs(a.target, class_names, out);
                try self.collectImportAliasClassMemberRefs(a.value, class_names, out);
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                try self.collectImportAliasClassMemberRefs(c.callee, class_names, out);
                for (hir_mod.callArgs(self.hir, node)) |arg| try self.collectImportAliasClassMemberRefs(arg, class_names, out);
            },
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                try self.collectImportAliasClassMemberRefs(e.object, class_names, out);
                try self.collectImportAliasClassMemberRefs(e.index, class_names, out);
            },
            .as_expr, .satisfies_expr, .type_assertion, .non_null_expr => {
                const a = hir_mod.asExpressionOf(self.hir, node);
                try self.collectImportAliasClassMemberRefs(a.expr, class_names, out);
            },
            .array_literal => for (hir_mod.arrayLiteralElements(self.hir, node)) |el| try self.collectImportAliasClassMemberRefs(el, class_names, out),
            .spread => try self.collectImportAliasClassMemberRefs(hir_mod.spreadOf(self.hir, node).expression, class_names, out),
            .object_literal => for (hir_mod.objectLiteralProps(self.hir, node)) |p| try self.collectImportAliasClassMemberRefs(p, class_names, out),
            .object_property => {
                const op = hir_mod.objectPropertyOf(self.hir, node);
                try self.collectImportAliasClassMemberRefs(op.value, class_names, out);
                if (op.is_computed) try self.collectImportAliasClassMemberRefs(op.key, class_names, out);
            },
            .class_decl, .class_expr => {
                const c = hir_mod.classOf(self.hir, node);
                try self.collectImportAliasClassMemberRefs(c.extends, class_names, out);
                for (hir_mod.classMembers(self.hir, node)) |m| try self.collectImportAliasClassMemberRefs(m, class_names, out);
            },
            .namespace_decl, .module_decl => for (hir_mod.namespaceBody(self.hir, node)) |s| try self.collectImportAliasClassMemberRefs(s, class_names, out),
            .export_decl => {
                const ex = hir_mod.exportOf(self.hir, node);
                try self.collectImportAliasClassMemberRefs(ex.decl, class_names, out);
            },
            else => {},
        }
    }

    fn memberAccessImportAliasClassDecl(self: *Checker, object: NodeId, member_name: hir_mod.StringId) ?NodeId {
        if (object == hir_mod.none_node_id or self.hir.kindOf(object) != .identifier) return null;
        const alias_name = hir_mod.identifierOf(self.hir, object).name;
        var i: NodeId = 1;
        while (i < self.hir.nodeCount()) : (i += 1) {
            if (self.hir.kindOf(i) != .import_decl) continue;
            if (self.importEqualsAliasName(i) != alias_name) continue;
            const imp = hir_mod.importOf(self.hir, i);
            if (imp.import_equals == hir_mod.none_node_id or self.hir.kindOf(imp.import_equals) != .type_ref) continue;
            const r = hir_mod.typeRefOf(self.hir, imp.import_equals);
            const qualifiers = hir_mod.typeRefQualifier(self.hir, imp.import_equals);
            if (qualifiers.len != 0) continue;
            const root = self.rootBlockFor(i);
            if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) continue;
            const path = [_]hir_mod.StringId{r.name};
            const ns_node = self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), &path) orelse continue;
            const target = self.findNamedTypeDeclInNamespace(ns_node, member_name) orelse continue;
            if (self.hir.kindOf(target) == .class_decl or self.hir.kindOf(target) == .class_expr) return target;
        }
        return null;
    }

    fn reportBindingDefaultReference(
        self: *Checker,
        node: NodeId,
        mode: BindingDefaultMode,
        is_self: bool,
    ) CheckError!void {
        try self.reportBindingDefaultReferenceNamed(node, mode, is_self, null, null);
    }

    fn reportBindingDefaultReferenceNamed(
        self: *Checker,
        node: NodeId,
        mode: BindingDefaultMode,
        is_self: bool,
        param_name: ?hir_mod.StringId,
        ref_name: ?hir_mod.StringId,
    ) CheckError!void {
        return self.reportBindingDefaultReferenceNamedWithPattern(node, mode, is_self, param_name, ref_name, null);
    }

    /// Render a binding-pattern node as a single-line snippet of its
    /// source text. Used by TS2373 (`Parameter '<pattern>' cannot
    /// reference identifier ...`) so the message matches upstream tsc,
    /// which never substitutes a placeholder for destructuring
    /// patterns. Collapses runs of internal whitespace into single
    /// spaces and trims leading/trailing whitespace so multi-line
    /// patterns still render compactly.
    fn normalizedBindingPatternSourceText(self: *Checker, node: NodeId) CheckError!?[]const u8 {
        const src = self.source orelse return null;
        const span = self.hir.spanOf(node);
        if (span.end > src.len or span.start >= span.end) return null;
        const raw = src[span.start..span.end];
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        defer buf.deinit(self.gpa);
        var prev_ws = false;
        for (raw) |ch| {
            const is_ws = ch == ' ' or ch == '\t' or ch == '\r' or ch == '\n';
            if (is_ws) {
                if (buf.items.len == 0) continue;
                if (!prev_ws) try buf.append(self.gpa, ' ');
                prev_ws = true;
            } else {
                try buf.append(self.gpa, ch);
                prev_ws = false;
            }
        }
        while (buf.items.len > 0 and buf.items[buf.items.len - 1] == ' ') _ = buf.pop();
        if (buf.items.len == 0) return null;
        const owned = try self.diag_arena.allocator().dupe(u8, buf.items);
        return owned;
    }

    fn reportBindingDefaultReferenceNamedWithPattern(
        self: *Checker,
        node: NodeId,
        mode: BindingDefaultMode,
        is_self: bool,
        param_name: ?hir_mod.StringId,
        ref_name: ?hir_mod.StringId,
        pattern_node: ?NodeId,
    ) CheckError!void {
        const code: u32 = switch (mode) {
            .variable => TsCodes.block_scoped_used_before_decl,
            .parameter => if (is_self) TsCodes.parameter_cannot_reference_self else TsCodes.parameter_cannot_reference_later,
        };
        // Render named TS-style message when both names are known and
        // the caller is reporting a parameter (TS2371/TS2373).
        if (mode == .parameter and param_name != null and ref_name != null) {
            const p_str = self.string_interner.get(param_name.?);
            const r_str = self.string_interner.get(ref_name.?);
            // TS2372 wording mirrors upstream tsc exactly:
            // `Parameter '{0}' cannot reference itself.` ÃÂ¢ÃÂÃÂ no
            // "in its initializer." tail. Mirrors fixtures
            // `asyncArrowFunction3_es5`, `asyncArrowFunction9_es5`,
            // `asyncArrowFunctionCapturesArguments_es5`, etc.
            const msg = if (is_self)
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Parameter '{s}' cannot reference itself.",
                    .{p_str},
                )
            else
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Parameter '{s}' cannot reference identifier '{s}' declared after it.",
                    .{ p_str, r_str },
                );
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = code,
                .message = msg,
            });
            return;
        }
        // Destructuring patterns (object/array binding patterns at the
        // parameter position) have no plain identifier "name" ÃÂ¢ÃÂÃÂ tsc
        // renders the pattern's literal source text instead. Build the
        // named TS2373 message using that text when both the pattern
        // node and the source buffer are available. Mirrors
        // `parameterInitializersForwardReferencing.2.ts(5,32)`:
        // `Parameter '{ b = a(), ...x }' cannot reference identifier
        // 'a' declared after it.`.
        if (mode == .parameter and !is_self and param_name == null and ref_name != null) {
            if (pattern_node) |pat| {
                if (try self.normalizedBindingPatternSourceText(pat)) |pat_text| {
                    const r_str = self.string_interner.get(ref_name.?);
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Parameter '{s}' cannot reference identifier '{s}' declared after it.",
                        .{ pat_text, r_str },
                    );
                    try self.diagnostics.append(self.gpa, .{
                        .node = node,
                        .code = code,
                        .message = msg,
                    });
                    return;
                }
            }
        }
        // For TS2448 (variable mode) tsc renders the *referenced*
        // variable name in the message ("Block-scoped variable 'X'
        // used before its declaration.") ÃÂ¢ÃÂÃÂ `X` is the name being
        // forward-referenced, not the binding currently being
        // declared. Mirrors
        // `destructuringObjectBindingPatternAndAssignment4.ts(6,9)`
        // (`e = f` reports `'f' used before its declaration.`).
        // Fall back to `param_name` only when no reference name was
        // captured so we still produce the named form for older
        // call sites.
        const display_name: ?hir_mod.StringId = ref_name orelse param_name;
        if (mode == .variable and display_name != null) {
            const p_str = self.string_interner.get(display_name.?);
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Block-scoped variable '{s}' used before its declaration.",
                .{p_str},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = code,
                .message = msg,
            });
            return;
        }
        const msg: []const u8 = switch (mode) {
            .variable => "Block-scoped variable used before its declaration.",
            .parameter => if (is_self)
                "Parameter cannot reference itself."
            else
                "Parameter cannot reference identifier declared after it.",
        };
        try self.report(node, code, msg);
    }

    /// TS2700 ÃÂ¢ÃÂÃÂ "Rest types may only be created from object types."
    /// An object binding pattern with a rest element (`{ ...r } = x`)
    /// builds `r` from the residual properties of the source. tsc emits
    /// TS2700 when the source type is not a valid spread source (a
    /// primitive, literal, enum, index-access, etc.). `any` is allowed.
    /// Mirrors upstream getBindingElementTypeFromParentType / the
    /// KindObjectBindingPattern rest branch, reusing the same
    /// object-spread validity helper as TS2698. The error is anchored on
    /// the rest binding element. Returns true when it fired.
    fn reportObjectRestBindingFromNonObject(self: *Checker, pattern_node: NodeId) CheckError!bool {
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (!ep.flags.is_rest) continue;
            const anchor = if (ep.name != hir_mod.none_node_id) ep.name else e;
            try self.report(anchor, TsCodes.rest_types_object_only, "Rest types may only be created from object types.");
            return true;
        }
        return false;
    }

    fn checkObjectBindingPatternAgainstType(self: *Checker, pattern_node: NodeId, container_t: TypeId, check_defaults: bool) CheckError!void {
        if (self.thisTypeMarkerConstraint(container_t)) |this_t| {
            return self.checkObjectBindingPatternAgainstType(pattern_node, this_t, check_defaults);
        }
        if (container_t == types.Primitive.any) return;
        if (container_t == types.Primitive.unknown) {
            _ = try self.checkObjectBindingComputedKeysAgainstType(pattern_node, container_t);
            if (self.objectBindingPatternHasRest(pattern_node)) {
                _ = try self.reportObjectRestBindingFromNonObject(pattern_node);
            }
            return;
        }
        // Destructuring against `null` / `undefined` ÃÂ¢ÃÂÃÂ tsc emits
        // TS2339 ("Property 'x' does not exist on type 'null'.") per
        // declared property. Mirrors fixtures `usingDeclarations.6`
        // and `awaitUsingDeclarations.6` (`using {a} = null`) as well
        // as plain `let {a} = null;` shapes.
        if (container_t == types.Primitive.null_t or container_t == types.Primitive.undefined_t) {
            const target_text: []const u8 = if (container_t == types.Primitive.null_t) "null" else "undefined";
            try self.reportObjectBindingPropertiesMissingOnType(pattern_node, target_text);
            return;
        }
        if (container_t >= self.interner.pool.typeCount()) return;
        if (container_t == types.Primitive.object_t) {
            _ = try self.checkObjectBindingComputedKeysAgainstType(pattern_node, container_t);
            try self.checkObjectBindingPatternAgainstBroadObject(pattern_node, container_t);
            return;
        }
        const flags = self.interner.pool.flagsOf(container_t);
        if (flags.is_union) {
            for (self.interner.unionMembers(container_t)) |member| {
                if (member < self.interner.pool.typeCount() and self.interner.pool.flagsOf(member).is_object_type and
                    self.interner.objectMembers(member).len == 0 and
                    self.interner.objectStringIndex(member) == types.Primitive.none and
                    self.interner.objectNumberIndex(member) == types.Primitive.none)
                {
                    return;
                }
            }
            if (self.objectBindingPatternHasRest(pattern_node) and (self.typeIncludesUndefined(container_t) or self.typeIncludesNull(container_t))) {
                const target_text = (try self.allocPropertyMissingTargetTypeName(container_t)) orelse "unknown";
                try self.reportObjectBindingPropertiesMissingOnType(pattern_node, target_text);
                return;
            }
            for (self.interner.unionMembers(container_t)) |member| {
                // Skip `null` / `undefined` members of the union ÃÂ¢ÃÂÃÂ those
                // represent optionality on the outer site (a `?:`
                // parameter, a `T | undefined` annotation), not an
                // object the destructure could land on. tsc reports
                // TS2533 / TS18048 (possibly-undefined) at the
                // destructure target or TS2463 on the parameter itself
                // but does NOT emit TS2339 "Property 'X' does not exist
                // on type 'undefined'" per element. Mirrors
                // `optionalBindingParameters2` and
                // `optionalBindingParametersInOverloads2`.
                if (member == types.Primitive.undefined_t or member == types.Primitive.null_t) continue;
                try self.checkObjectBindingPatternAgainstType(pattern_node, member, check_defaults);
            }
            return;
        }
        if (!flags.is_object_type) {
            // Reached only for non-object, non-union, non-nullish,
            // non-any/unknown source types (primitives, literals, enums,
            // index accesses, ÃÂ¢ÃÂÃÂ¦). A rest element (`{ ...r } = x`) over
            // such a source surfaces TS2700; reuse the TS2698
            // object-spread validity helper so valid sources (e.g. a
            // type parameter constrained to an object) stay silent.
            if (!try self.objectSpreadSourceIsValid(container_t)) {
                _ = try self.reportObjectRestBindingFromNonObject(pattern_node);
            }
            const wrapper_name: ?[]const u8 = if (flags.is_number)
                "Number"
            else if (flags.is_string)
                "String"
            else if (flags.is_boolean)
                "Boolean"
            else if (flags.is_bigint)
                "BigInt"
            else if (flags.is_symbol)
                "Symbol"
            else
                null;
            if (wrapper_name) |target_text| {
                for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
                    if (self.hir.kindOf(e) != .parameter) continue;
                    const ep = hir_mod.parameterOf(self.hir, e);
                    if (ep.flags.is_rest or ep.name == hir_mod.none_node_id) continue;
                    const key_name = (try self.objectBindingElementKeyName(e, ep.name)) orelse continue;
                    if ((try self.primitivePrototypeMember(container_t, key_name)) != null) continue;
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Property '{s}' does not exist on type '{s}'.",
                        .{ self.string_interner.get(key_name), target_text },
                    );
                    try self.diagnostics.append(self.gpa, .{
                        .node = ep.name,
                        .pos = self.objectBindingElementPropertyPosition(e, ep.name),
                        .code = TsCodes.property_does_not_exist,
                        .message = msg,
                    });
                }
            }
            return;
        }
        const has_dynamic_computed_key = try self.checkObjectBindingComputedKeysAgainstType(pattern_node, container_t);
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.name == hir_mod.none_node_id) continue;
            if (ep.flags.is_rest) {
                if (has_dynamic_computed_key and self.hir.kindOf(ep.name) == .identifier) {
                    const id = hir_mod.identifierOf(self.hir, ep.name);
                    const rest_t = self.interner.internObjectType(&.{}) catch return error.OutOfMemory;
                    try self.checkRepeatedObjectRestVarBinding(pattern_node, ep.name, id.name, rest_t);
                }
                continue;
            }
            const key_name = (try self.objectBindingElementKeyName(e, ep.name)) orelse continue;
            if (self.interner.objectMemberInfo(container_t, key_name)) |member| {
                const default_value = if (ep.flags.is_computed_binding_key) hir_mod.none_node_id else ep.default_value;
                try self.checkObjectBindingElementVisibilityAccess(e, ep.name, container_t, key_name);
                if (check_defaults) {
                    try self.checkBindingTargetAgainstElementType(ep.name, default_value, member.type);
                } else if (default_value != hir_mod.none_node_id) {
                    _ = try self.checkExpression(default_value);
                }
                continue;
            }
            if (self.interner.objectStringIndex(container_t) != types.Primitive.none) continue;
            if (self.interner.objectNumberIndex(container_t) != types.Primitive.none and self.isNumericStringId(key_name)) continue;
            if (ep.default_value != hir_mod.none_node_id) continue;
            const name_str = self.string_interner.get(key_name);
            // Upstream tsc widens `object` to `{}` when reporting
            // missing-property destructuring binding errors ÃÂ¢ÃÂÃÂ mirrors
            // `nonPrimitiveAccessProperty.ts(5,7)`.
            const target_text_opt: ?[]const u8 = if (container_t == types.Primitive.object_t)
                "{}"
            else
                try self.allocPropertyMissingTargetTypeName(container_t);
            const msg = if (target_text_opt) |target_text|
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Property '{s}' does not exist on type '{s}'.",
                    .{ name_str, target_text },
                )
            else
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Property '{s}' does not exist on type.",
                    .{name_str},
                );
            try self.diagnostics.append(self.gpa, .{
                .node = ep.name,
                .code = TsCodes.property_does_not_exist,
                .message = msg,
            });
        }
    }

    fn checkObjectBindingElementVisibilityAccess(
        self: *Checker,
        elem_node: NodeId,
        name_node: NodeId,
        container_t: TypeId,
        prop_name: hir_mod.StringId,
    ) CheckError!void {
        const receiver_t = self.thisTypeMarkerConstraint(container_t) orelse container_t;
        const receiver_class = self.class_name_by_instance.get(receiver_t) orelse
            self.class_name_by_static.get(receiver_t) orelse
            self.interfaceInheritedVisibilityClass(receiver_t) orelse
            self.objectBindingElementThisReceiverClass(elem_node) orelse
            return;
        const report_pos = self.objectBindingElementPropertyPosition(elem_node, name_node);
        if (self.privateMemberDeclaringClass(receiver_class, prop_name)) |declaring_class| {
            if (self.nodeIsInsideClass(name_node, declaring_class)) return;
            const prop_str = self.string_interner.get(prop_name);
            const class_display = try self.classDisplayName(name_node, declaring_class);
            defer self.gpa.free(class_display);
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Property '{s}' is private and only accessible within class '{s}'.",
                .{ prop_str, class_display },
            );
            try self.reportAt(name_node, report_pos, TsCodes.private_member_access, msg);
            return;
        }
        const declaring_protected = self.protectedMemberDeclaringClass(receiver_class, prop_name, false) orelse return;
        if (self.nearestEnclosingClassInProtectedChain(name_node, declaring_protected)) |access_class| {
            if (self.classIsOrExtendsClass(receiver_class, access_class)) return;
        }
        const prop_str = self.string_interner.get(prop_name);
        const class_display = try self.classDisplayName(name_node, declaring_protected);
        defer self.gpa.free(class_display);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Property '{s}' is protected and only accessible within class '{s}' and its subclasses.",
            .{ prop_str, class_display },
        );
        try self.reportAt(name_node, report_pos, TsCodes.protected_member_access, msg);
    }

    fn objectBindingElementThisReceiverClass(self: *Checker, elem_node: NodeId) ?hir_mod.StringId {
        var cur = elem_node;
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const kind = self.hir.kindOf(cur);
            if (kind != .var_decl and kind != .let_decl and kind != .const_decl) continue;
            const init_node = hir_mod.varDeclOf(self.hir, cur).init;
            if (init_node == hir_mod.none_node_id or !self.nodeIsThisReference(init_node)) return null;
            if (self.thisInsideNonArrowPlainFunction(init_node)) return null;
            var parent = self.hir.parentOf(cur);
            while (parent != hir_mod.none_node_id) : (parent = self.hir.parentOf(parent)) {
                const parent_kind = self.hir.kindOf(parent);
                if (parent_kind != .class_decl and parent_kind != .class_expr) continue;
                const class = hir_mod.classOf(self.hir, parent);
                if (class.name == hir_mod.none_node_id or self.hir.kindOf(class.name) != .identifier) return null;
                return hir_mod.identifierOf(self.hir, class.name).name;
            }
            return null;
        }
        return null;
    }

    fn objectBindingElementPropertyPosition(self: *Checker, elem_node: NodeId, name_node: NodeId) ?u32 {
        if (self.objectBindingElementUsesImplicitKey(elem_node, name_node)) return null;
        const src = self.source orelse return null;
        const elem_span = self.hir.spanOf(elem_node);
        const name_span = self.hir.spanOf(name_node);
        if (elem_span.start >= src.len or name_span.start > src.len or name_span.start <= elem_span.start) return null;
        const prefix = src[elem_span.start..name_span.start];
        const colon = std.mem.indexOfScalar(u8, prefix, ':') orelse return null;
        var key_start: usize = elem_span.start;
        const key_end = elem_span.start + colon;
        while (key_start < key_end and std.ascii.isWhitespace(src[key_start])) key_start += 1;
        return @intCast(key_start);
    }

    fn objectBindingPatternHasRest(self: *Checker, pattern_node: NodeId) bool {
        if (pattern_node == hir_mod.none_node_id or self.hir.kindOf(pattern_node) != .object_pattern) return false;
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            if (hir_mod.parameterOf(self.hir, e).flags.is_rest) return true;
        }
        return false;
    }

    fn objectRestBindingType(self: *Checker, pattern_node: NodeId, source_t: TypeId) CheckError!TypeId {
        if (source_t == types.Primitive.any or source_t == types.Primitive.unknown) return types.Primitive.any;
        if (source_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(source_t).is_object_type) {
            return types.Primitive.any;
        }
        var omitted: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer omitted.deinit(self.gpa);
        for (hir_mod.patternElements(self.hir, pattern_node)) |elem| {
            if (self.hir.kindOf(elem) != .parameter) continue;
            const p = hir_mod.parameterOf(self.hir, elem);
            if (p.flags.is_rest) break;
            if (p.name == hir_mod.none_node_id) continue;
            const key_name = (try self.objectBindingElementKeyName(elem, p.name)) orelse continue;
            try omitted.put(self.gpa, key_name, {});
        }
        return try self.objectRestTypeExcluding(source_t, &omitted);
    }

    fn objectRestAssignmentType(self: *Checker, pattern_node: NodeId, source_t: TypeId, rest_index: usize) CheckError!TypeId {
        if (source_t == types.Primitive.any or source_t == types.Primitive.unknown) return types.Primitive.any;
        if (source_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(source_t).is_object_type) {
            return types.Primitive.any;
        }
        var omitted: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer omitted.deinit(self.gpa);
        const props = hir_mod.objectLiteralProps(self.hir, pattern_node);
        for (props[0..@min(rest_index, props.len)]) |prop_node| {
            if (self.hir.kindOf(prop_node) != .object_property) continue;
            const prop = hir_mod.objectPropertyOf(self.hir, prop_node);
            const key_name = (try self.classMemberNameFromPropertyKey(prop.key, prop.is_computed)) orelse continue;
            try omitted.put(self.gpa, key_name, {});
        }
        return try self.objectRestTypeExcluding(source_t, &omitted);
    }

    fn objectRestTypeExcluding(
        self: *Checker,
        source_t: TypeId,
        omitted: *const std.AutoHashMapUnmanaged(hir_mod.StringId, void),
    ) CheckError!TypeId {
        const source_is_class_instance = self.class_name_by_instance.contains(source_t);
        const source_is_class_static = self.class_name_by_static.contains(source_t);
        const prototype_name = self.string_interner.intern("prototype") catch return error.OutOfMemory;
        const source_members = self.interner.objectMembers(source_t);
        var source_has_prototype = false;
        for (source_members) |member| {
            if (member.name == prototype_name) {
                source_has_prototype = true;
                break;
            }
        }
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        if (source_is_class_static and !source_has_prototype and !omitted.contains(prototype_name)) {
            const class_name = self.class_name_by_static.get(source_t);
            const prototype_t = if (class_name) |cn|
                self.class_instance_types.get(cn) orelse types.Primitive.any
            else
                types.Primitive.any;
            try members.append(self.gpa, .{
                .name = prototype_name,
                .type = prototype_t,
                .is_optional = false,
                .is_readonly = false,
                .is_method = false,
            });
        }
        for (source_members) |m| {
            if (omitted.contains(m.name)) continue;
            if (source_is_class_instance and (m.is_method or m.is_readonly or self.memberNameIsEcmaPrivate(m.name))) continue;
            if (source_is_class_static and m.name != prototype_name) continue;
            var rest_member = m;
            rest_member.is_readonly = false;
            try members.append(self.gpa, rest_member);
        }
        return self.interner.internObjectType(members.items) catch return error.OutOfMemory;
    }

    fn initializerIdentifierNullishAnnotationText(self: *Checker, var_node: NodeId, init_node: NodeId) ?[]const u8 {
        if (init_node == hir_mod.none_node_id or self.hir.kindOf(init_node) != .identifier) return null;
        const id = hir_mod.identifierOf(self.hir, init_node);
        const root = self.rootBlockFor(var_node);
        const var_start = self.hir.spanOf(var_node).start;
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) {
            return self.priorSourceVarAnnotationText(id.name, var_start);
        }
        var found: ?NodeId = null;
        for (hir_mod.blockStmts(self.hir, root)) |raw_stmt| {
            const stmt = self.unwrapExportDecl(raw_stmt);
            if (stmt == var_node or self.hir.spanOf(stmt).start >= var_start) break;
            const k = self.hir.kindOf(stmt);
            if (k != .var_decl and k != .let_decl and k != .const_decl) continue;
            const v = hir_mod.varDeclOf(self.hir, stmt);
            if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, v.name).name == id.name) found = stmt;
        }
        const decl = found orelse return self.priorSourceVarAnnotationText(id.name, var_start);
        const v = hir_mod.varDeclOf(self.hir, decl);
        if (v.type_annotation == hir_mod.none_node_id) return null;
        const text = self.annotationSourceText(v.type_annotation) orelse return null;
        if (std.mem.indexOf(u8, text, "undefined") == null and std.mem.indexOf(u8, text, "null") == null) return null;
        if (std.mem.indexOf(u8, text, " }")) |brace_space| {
            if (brace_space > 0 and text[brace_space - 1] != ';') {
                return std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "{s};{s}",
                    .{ text[0..brace_space], text[brace_space..] },
                ) catch null;
            }
        }
        return text;
    }

    fn priorSourceVarAnnotationText(self: *Checker, name: hir_mod.StringId, before_pos: u32) ?[]const u8 {
        const src = self.source orelse return null;
        const name_text = self.string_interner.get(name);
        var search_start: usize = 0;
        var found: ?usize = null;
        const limit: usize = @min(src.len, before_pos);
        while (std.mem.indexOfPos(u8, src[0..limit], search_start, name_text)) |idx| {
            const before_ok = idx == 0 or !isJsDocIdentChar(src[idx - 1]);
            const after = idx + name_text.len;
            const after_ok = after >= limit or !isJsDocIdentChar(src[after]);
            if (before_ok and after_ok) found = idx;
            search_start = after;
        }
        const idx = found orelse return null;
        var i = idx + name_text.len;
        while (i < limit and (src[i] == ' ' or src[i] == '\t')) : (i += 1) {}
        if (i >= limit or src[i] != ':') return null;
        i += 1;
        const start = i;
        while (i < limit and src[i] != ';' and src[i] != '\n' and src[i] != '\r') : (i += 1) {}
        const text = std.mem.trim(u8, src[start..i], " \t\r\n");
        if (std.mem.indexOf(u8, text, "undefined") == null and std.mem.indexOf(u8, text, "null") == null) return null;
        if (std.mem.indexOf(u8, text, " }")) |brace_space| {
            if (brace_space > 0 and text[brace_space - 1] != ';') {
                return std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "{s};{s}",
                    .{ text[0..brace_space], text[brace_space..] },
                ) catch null;
            }
        }
        return text;
    }

    fn checkBindingTargetAgainstElementType(
        self: *Checker,
        target_node: NodeId,
        default_node: NodeId,
        target_t: TypeId,
    ) CheckError!void {
        if (target_t == types.Primitive.none or
            target_t == types.Primitive.any or
            target_t == types.Primitive.unknown)
        {
            return;
        }

        var target = target_node;
        var default_value = default_node;
        if (target != hir_mod.none_node_id and self.hir.kindOf(target) == .assignment) {
            const a = hir_mod.assignmentOf(self.hir, target);
            target = a.target;
            if (default_value == hir_mod.none_node_id) default_value = a.value;
        }

        if (default_value != hir_mod.none_node_id) {
            try self.checkBindingDefaultAssignableToType(default_value, target_t, target);
        }

        if (target == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(target)) {
            .object_pattern => try self.checkObjectBindingPatternAgainstType(target, target_t, true),
            .array_pattern => try self.checkArrayBindingPatternAgainstType(target, target_t),
            else => {},
        }
    }

    fn checkBindingDefaultAssignableToType(
        self: *Checker,
        default_node: NodeId,
        target_t: TypeId,
        report_node: NodeId,
    ) CheckError!void {
        if (target_t == types.Primitive.none or
            target_t == types.Primitive.any or
            target_t == types.Primitive.unknown)
        {
            _ = try self.checkExpression(default_node);
            return;
        }

        const default_kind = self.hir.kindOf(default_node);
        if (default_kind == .arrow_fn or default_kind == .fn_expr) {
            if (self.firstSignatureType(target_t)) |target_sig| {
                try self.checkFunctionWithContextualSignature(default_node, target_sig);
                return;
            }
            if (try self.functionExpressionReturnMismatchSignature(default_node, target_t)) |target_sig| {
                try self.checkFunctionWithContextualSignature(default_node, target_sig);
                return;
            }
            if (try self.functionExpressionAssignableToTarget(default_node, target_t)) {
                self.removeImplicitAnyDiagnosticsWithin(default_node);
                return;
            }
        }

        if (self.hir.kindOf(default_node) == .array_literal) {
            _ = try self.checkExpression(default_node);
            if (try self.tryReportArrayLiteralTupleElementMismatch(default_node, target_t)) return;
            if (try self.arrayLiteralAssignableToTargetInner(default_node, target_t, false)) return;

            const elem_t = try self.contextualArrayElementType(target_t);
            if (elem_t != types.Primitive.none and
                elem_t != types.Primitive.any and
                elem_t != types.Primitive.unknown)
            {
                for (hir_mod.arrayLiteralElements(self.hir, default_node)) |el| {
                    if (el == hir_mod.none_node_id or self.hir.kindOf(el) == .spread) continue;
                    if (try self.literalExpressionAssignableToTarget(el, elem_t)) continue;
                    const el_t = if (self.hir.typeOf(el) != types.Primitive.none)
                        self.hir.typeOf(el)
                    else
                        try self.checkExpression(el);
                    if (self.engine.isAssignableTo(el_t, elem_t) catch false) continue;
                    try self.reportTypeNotAssignable(el, el_t, elem_t, "Type is not assignable to array element type.");
                }
                return;
            }
        }

        const default_t = try self.checkExpression(default_node);
        if (self.hir.kindOf(default_node) == .object_literal) {
            const before = self.diagnostics.items.len;
            if (self.objectLiteralAssignableToTarget(default_node, default_t, target_t) catch false) return;
            if (self.diagnostics.items.len > before) return;
        }
        if (try self.literalExpressionAssignableToTarget(default_node, target_t)) return;
        if (self.engine.isAssignableTo(default_t, target_t) catch false) return;
        if (try self.tryReportObjectLiteralPropertyMismatch(default_node, target_t)) return;
        const report_t = try self.expressionLiteralType(default_node, default_t);
        try self.reportBindingDefaultTypeNotAssignable(report_node, report_t, target_t, "Type is not assignable to binding element type.");
    }

    fn stringSliceLessThan(_: void, a: []const u8, b: []const u8) bool {
        return std.mem.order(u8, a, b) == .lt;
    }

    fn allocSortedStringLiteralUnionName(self: *Checker, t: TypeId) CheckError!?[]const u8 {
        if (t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(t).is_union) return null;
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer names.deinit(self.gpa);
        for (self.interner.unionMembers(t)) |member| {
            if (member >= self.interner.pool.typeCount()) return null;
            const flags = self.interner.pool.flagsOf(member);
            if (!flags.is_literal or !flags.is_string) return null;
            const lit = self.interner.literalOfOrNull(member) orelse return null;
            const name = switch (lit) {
                .string_lit => |sid| self.string_interner.get(sid),
                else => return null,
            };
            try names.append(self.gpa, name);
        }
        if (names.items.len == 0) return null;
        std.mem.sort([]const u8, names.items, {}, stringSliceLessThan);
        var out: std.ArrayListUnmanaged(u8) = .empty;
        errdefer out.deinit(self.diag_arena.allocator());
        for (names.items, 0..) |name, i| {
            if (i > 0) try out.appendSlice(self.diag_arena.allocator(), " | ");
            try out.append(self.diag_arena.allocator(), '"');
            try out.appendSlice(self.diag_arena.allocator(), name);
            try out.append(self.diag_arena.allocator(), '"');
        }
        const text = try out.toOwnedSlice(self.diag_arena.allocator());
        return text;
    }

    fn reportBindingDefaultTypeNotAssignable(
        self: *Checker,
        node: NodeId,
        source: TypeId,
        target: TypeId,
        fallback: []const u8,
    ) CheckError!void {
        const source_name = (try self.allocSimpleTypeName(source)) orelse
            (try self.allocObjectTypeShapeWithUndefined(source)) orelse
            return try self.report(node, TsCodes.type_not_assignable, fallback);
        const target_name = (try self.allocSortedStringLiteralUnionName(target)) orelse
            (try self.allocSimpleTypeName(target)) orelse
            (try self.allocObjectTypeShapeWithUndefined(target)) orelse
            return try self.report(node, TsCodes.type_not_assignable, fallback);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' is not assignable to type '{s}'.",
            .{ source_name, target_name },
        );
        try self.report(node, TsCodes.type_not_assignable, msg);
    }

    /// Walk an object binding pattern's declared properties and
    /// emit TS2339 for each, reporting `Property 'x' does not exist
    /// on type '{target_text}'.`. Used when the destructuring source
    /// is a `null` or `undefined` literal ÃÂ¢ÃÂÃÂ tsc fires the
    /// no-such-property diagnostic at every shorthand element rather
    /// than the source-side TS2531/2532.
    fn reportObjectBindingPropertiesMissingOnType(self: *Checker, pattern_node: NodeId, target_text: []const u8) CheckError!void {
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.name == hir_mod.none_node_id or ep.flags.is_rest) continue;
            const key_name = (try self.objectBindingElementKeyName(e, ep.name)) orelse continue;
            const name_str = self.string_interner.get(key_name);
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Property '{s}' does not exist on type '{s}'.",
                .{ name_str, target_text },
            );
            try self.diagnostics.append(self.gpa, .{
                .node = ep.name,
                .code = TsCodes.property_does_not_exist,
                .message = msg,
            });
        }
    }

    fn checkObjectBindingComputedKeysAgainstType(self: *Checker, pattern_node: NodeId, container_t: TypeId) CheckError!bool {
        const parent = self.hir.parentOf(pattern_node);
        if (parent != hir_mod.none_node_id and self.hir.kindOf(parent) == .parameter) {
            const pattern_param = hir_mod.parameterOf(self.hir, parent);
            if (pattern_param.name == pattern_node and pattern_param.default_value != hir_mod.none_node_id) {
                if (try self.computedBindingDefaultIsAnyWithoutEvaluation(pattern_param.default_value)) return false;
            }
        }

        var saw_dynamic = false;
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.flags.is_computed_binding_key) {
                if (ep.default_value == hir_mod.none_node_id) continue;
                const key_t = try self.checkExpression(ep.default_value);
                if (try self.reportMissingIndexForComputedBindingKey(ep.default_value, container_t, key_t)) {
                    saw_dynamic = true;
                }
                continue;
            }
            if (ep.name == hir_mod.none_node_id) continue;
            const nk = self.hir.kindOf(ep.name);
            if (nk == .object_pattern or nk == .array_pattern) {
                if (try self.checkObjectBindingComputedKeysAgainstType(ep.name, types.Primitive.any)) saw_dynamic = true;
            }
        }
        return saw_dynamic;
    }

    fn computedBindingDefaultIsAnyWithoutEvaluation(self: *Checker, node: NodeId) CheckError!bool {
        const cached = self.hir.typeOf(node);
        if (cached != types.Primitive.none) return cached == types.Primitive.any;
        return switch (self.hir.kindOf(node)) {
            .identifier => blk: {
                const id = hir_mod.identifierOf(self.hir, node);
                const t = self.lookupNarrow(id.name) orelse self.typeOfIdentifier(node);
                break :blk t == types.Primitive.any;
            },
            .call_expr => blk: {
                const call = hir_mod.callOf(self.hir, node);
                var callee_t = self.hir.typeOf(call.callee);
                if (callee_t == types.Primitive.none and self.hir.kindOf(call.callee) == .identifier) {
                    const id = hir_mod.identifierOf(self.hir, call.callee);
                    callee_t = self.lookupNarrow(id.name) orelse self.typeOfIdentifier(call.callee);
                }
                if (callee_t == types.Primitive.any) break :blk true;
                const sig = self.firstSignatureType(callee_t) orelse break :blk false;
                break :blk (self.interner.signatureReturn(sig) orelse types.Primitive.any) == types.Primitive.any;
            },
            .as_expr, .type_assertion => blk: {
                const as_expr = hir_mod.asExpressionOf(self.hir, node);
                if (as_expr.type_node == hir_mod.none_node_id) break :blk false;
                break :blk (try self.lowererLowerWithTypeParams(as_expr.type_node)) == types.Primitive.any;
            },
            else => false,
        };
    }

    fn reportMissingIndexForComputedBindingKey(self: *Checker, node: NodeId, container_t: TypeId, key_t: TypeId) CheckError!bool {
        if (container_t == types.Primitive.any) return false;
        if (self.computedBindingKeyIsImmediateClassStaticLiteral(node)) return false;
        if (container_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(container_t).is_union) {
            var reported = false;
            for (self.interner.unionMembers(container_t)) |member| {
                if (try self.reportMissingIndexForComputedBindingKey(node, member, key_t)) reported = true;
            }
            return reported;
        }
        if (key_t == types.Primitive.any or key_t == types.Primitive.unknown) {
            if (container_t < self.interner.pool.typeCount()) {
                const flags = self.interner.pool.flagsOf(container_t);
                if (flags.is_object_type and
                    (self.interner.objectStringIndex(container_t) != types.Primitive.none or
                        self.interner.objectNumberIndex(container_t) != types.Primitive.none or
                        self.interner.objectSymbolIndex(container_t) != types.Primitive.none))
                {
                    return false;
                }
            }
            const key_text = if (key_t == types.Primitive.unknown) "unknown" else "any";
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Type '{s}' cannot be used as an index type.",
                .{key_text},
            );
            try self.reportOnce(node, TsCodes.type_cannot_be_used_as_index, msg);
            return true;
        }
        switch (self.hir.kindOf(node)) {
            .literal_string, .literal_number, .literal_bool, .literal_bigint => return false,
            else => {},
        }
        if (self.diagnosticExists(node, TsCodes.operator_cannot_be_applied)) {
            try self.reportAt(
                node,
                self.computedBindingKeyErrorPos(node),
                TsCodes.type_cannot_be_used_as_index,
                "Type 'any' cannot be used as an index type.",
            );
            return true;
        }
        if (container_t >= self.interner.pool.typeCount()) return false;
        const cf = self.interner.pool.flagsOf(container_t);
        if (!cf.is_object_type) return false;
        const key_kind = try self.dynamicComputedIndexKind(key_t) orelse return false;
        const has_index = switch (key_kind) {
            .string => self.interner.objectStringIndex(container_t) != types.Primitive.none,
            .number => self.interner.objectNumberIndex(container_t) != types.Primitive.none,
            .symbol => self.interner.objectSymbolIndex(container_t) != types.Primitive.none,
        };
        if (has_index) return true;
        const kind_text = switch (key_kind) {
            .string => "string",
            .number => "number",
            .symbol => "symbol",
        };
        const target_text = (try self.allocPropertyMissingTargetTypeName(container_t)) orelse "unknown";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' has no matching index signature for type '{s}'.",
            .{ target_text, kind_text },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.no_matching_index_signature,
            .message = msg,
        });
        return true;
    }

    fn computedBindingKeyIsImmediateClassStaticLiteral(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) != .member_access) return false;
        const access = hir_mod.memberOf(self.hir, node);
        const object_kind = self.hir.kindOf(access.object);
        if (object_kind != .class_decl and object_kind != .class_expr) return false;
        for (hir_mod.classMembers(self.hir, access.object)) |member| {
            if (self.hir.kindOf(member) != .object_property) continue;
            const property = hir_mod.objectPropertyOf(self.hir, member);
            if (!property.is_static or property.value == hir_mod.none_node_id) continue;
            const name = (self.classMemberNameFromPropertyKey(property.key, property.is_computed) catch null) orelse continue;
            if (name != access.name) continue;
            return switch (self.hir.kindOf(property.value)) {
                .literal_string, .literal_number => true,
                else => false,
            };
        }
        return false;
    }

    fn computedBindingKeyErrorPos(self: *Checker, node: NodeId) ?u32 {
        const src = self.source orelse return null;
        const span = self.hir.spanOf(node);
        if (span.start == 0 or span.start > src.len) return null;
        var i: usize = span.start;
        while (i > 0) {
            const ch = src[i - 1];
            if (ch == '(') return @intCast(i - 1);
            if (ch == ' ' or ch == '\t' or ch == '\n' or ch == '\r') {
                i -= 1;
                continue;
            }
            break;
        }
        return null;
    }

    fn dynamicComputedIndexKind(self: *Checker, key_t: TypeId) CheckError!?IndexKind {
        if (key_t == types.Primitive.string_t) return .string;
        if (key_t == types.Primitive.number_t) return .number;
        if (key_t == types.Primitive.symbol_t) return .symbol;
        if (key_t >= self.interner.pool.typeCount()) return null;
        const f = self.interner.pool.flagsOf(key_t);
        if (f.is_literal) return null;
        if (f.is_string) return .string;
        if (f.is_number) return .number;
        if (f.is_symbol) return .symbol;
        if (f.is_union) {
            var result: ?IndexKind = null;
            for (self.interner.unionMembers(key_t)) |member| {
                const member_kind = (try self.dynamicComputedIndexKind(member)) orelse return null;
                if (result) |existing| {
                    if (existing != member_kind) return null;
                } else {
                    result = member_kind;
                }
            }
            return result;
        }
        return null;
    }

    fn checkObjectBindingPatternAgainstBroadObject(self: *Checker, pattern_node: NodeId, container_t: TypeId) CheckError!void {
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.name == hir_mod.none_node_id or ep.flags.is_rest) continue;
            if (self.hir.kindOf(ep.name) != .identifier) continue;
            if (!self.objectBindingElementUsesImplicitKey(e, ep.name)) continue;
            const id = hir_mod.identifierOf(self.hir, ep.name);
            const name_str = self.string_interner.get(id.name);
            // Upstream tsc widens `object` to `{}` when reporting
            // missing-property destructuring binding errors ÃÂ¢ÃÂÃÂ mirrors
            // `nonPrimitiveAccessProperty.ts(5,7)`.
            const target_text_opt: ?[]const u8 = if (container_t == types.Primitive.object_t)
                "{}"
            else
                try self.allocPropertyMissingTargetTypeName(container_t);
            const msg = if (target_text_opt) |target_text|
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Property '{s}' does not exist on type '{s}'.",
                    .{ name_str, target_text },
                )
            else
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Property '{s}' does not exist on type.",
                    .{name_str},
                );
            try self.diagnostics.append(self.gpa, .{
                .node = ep.name,
                .code = TsCodes.property_does_not_exist,
                .message = msg,
            });
        }
    }

    fn checkArrayBindingPatternAgainstType(self: *Checker, pattern_node: NodeId, container_t: TypeId) CheckError!void {
        if (container_t == types.Primitive.any or container_t == types.Primitive.unknown) return;
        if (container_t >= self.interner.pool.typeCount()) return;
        try self.checkIteratorNextSentType(pattern_node, container_t, types.Primitive.undefined_t, .array_destructuring);
        const elem_t = try self.iterableElementType(container_t);
        const rest_array_t = self.interner.internArrayType(self.string_interner, elem_t) catch return error.OutOfMemory;
        // TS2493 ÃÂ¢ÃÂÃÂ array-binding pattern with more positions than the
        // source tuple has elements (`var [c2] = []`, `var [c0, c1] = [...temp]`).
        // Mirrors upstream baselines for `destructuringArrayBindingPatternAndAssignment1*`.
        const tuple_length_opt = if (self.interner.pool.flagsOf(container_t).is_object_type)
            self.actualTupleLength(container_t)
        else
            null;
        if (container_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(container_t).is_union) {
            for (hir_mod.patternElements(self.hir, pattern_node), 0..) |elem, i| {
                if (self.hir.kindOf(elem) != .parameter) continue;
                const ep = hir_mod.parameterOf(self.hir, elem);
                if (ep.flags.is_rest) continue;
                if (ep.default_value != hir_mod.none_node_id) continue;
                const access = (try self.unionTupleElementAccessAt(container_t, i)) orelse continue;
                if (access.found_any) continue;
                const anchor = if (ep.name != hir_mod.none_node_id) ep.name else elem;
                try self.reportIndexedPropertyDoesNotExistOnType(anchor, access.key, container_t);
            }
        }
        if (tuple_length_opt) |tuple_length| {
            for (hir_mod.patternElements(self.hir, pattern_node), 0..) |elem, i| {
                if (self.hir.kindOf(elem) != .parameter) continue;
                const ep = hir_mod.parameterOf(self.hir, elem);
                if (ep.flags.is_rest) continue;
                if (ep.default_value != hir_mod.none_node_id) continue;
                if (i >= tuple_length) {
                    const anchor = if (ep.name != hir_mod.none_node_id) ep.name else elem;
                    try self.reportTupleIndexOutOfBounds(anchor, container_t, @intCast(i), tuple_length);
                }
            }
        }
        for (hir_mod.patternElements(self.hir, pattern_node), 0..) |e, i| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (!ep.flags.is_rest and ep.name != hir_mod.none_node_id and self.hir.kindOf(ep.name) == .object_pattern) {
                var element_t = self.tupleElementType(container_t, i);
                if (element_t == types.Primitive.none) element_t = elem_t;
                try self.checkObjectBindingPatternAgainstType(ep.name, element_t, false);
                continue;
            }
            if (!ep.flags.is_rest or ep.name == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(ep.name) == .object_pattern) {
                try self.checkObjectBindingPatternAgainstType(ep.name, rest_array_t, false);
            }
        }
    }

    fn checkArrayBindingPatternAgainstArrayLiteral(self: *Checker, pattern_node: NodeId, source_node: NodeId) CheckError!void {
        if (source_node == hir_mod.none_node_id or self.hir.kindOf(source_node) != .array_literal) return;
        const values = hir_mod.arrayLiteralElements(self.hir, source_node);
        for (values) |value| {
            if (value != hir_mod.none_node_id and self.hir.kindOf(value) == .spread) return;
        }

        var elem_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer elem_types.deinit(self.gpa);
        for (values) |value| {
            if (value == hir_mod.none_node_id) {
                try elem_types.append(self.gpa, types.Primitive.undefined_t);
            } else {
                try elem_types.append(self.gpa, try self.checkExpression(value));
            }
        }
        const source_tuple_t = try self.internTupleFromTypes(elem_types.items, false);

        for (hir_mod.patternElements(self.hir, pattern_node), 0..) |elem, i| {
            if (self.hir.kindOf(elem) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, elem);
            if (ep.flags.is_rest) continue;
            const anchor = if (ep.name != hir_mod.none_node_id) ep.name else elem;
            if (i >= values.len) {
                if (ep.default_value != hir_mod.none_node_id) continue;
                if (values.len != 0) continue;
                if (ep.name != hir_mod.none_node_id and self.hir.kindOf(ep.name) == .array_pattern) {
                    try self.reportIteratorRequired(ep.name, types.Primitive.undefined_t);
                }
                try self.reportTupleIndexOutOfBounds(anchor, source_tuple_t, @intCast(i), @intCast(values.len));
                continue;
            }
            const value = values[i];
            if (value == hir_mod.none_node_id or ep.name == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(ep.name) == .array_pattern) {
                const value_t = try self.checkExpression(value);
                if (!self.isDestructuringIterableSourceType(value_t) and !self.objectLiteralHasSymbolIteratorMethod(value)) {
                    try self.reportIteratorRequiredWithSource(ep.name, value_t, value);
                }
                try self.checkArrayBindingPatternAgainstArrayLiteral(ep.name, value);
            } else if (self.hir.kindOf(ep.name) == .object_pattern) {
                const value_t = try self.checkExpression(value);
                try self.checkObjectBindingPatternAgainstType(ep.name, value_t, true);
            }
        }
    }

    fn recordBindingPatternFlowFromSource(self: *Checker, pattern_node: NodeId, source_node: NodeId, source_t: TypeId) CheckError!void {
        if (pattern_node == hir_mod.none_node_id) return;
        const effective_source_t = self.annotatedTupleUnionForIdentifier(source_node) orelse source_t;
        switch (self.hir.kindOf(pattern_node)) {
            .array_pattern => {
                const source_elements: []const NodeId = if (source_node != hir_mod.none_node_id and self.hir.kindOf(source_node) == .array_literal)
                    hir_mod.arrayLiteralElements(self.hir, source_node)
                else
                    &.{};
                const fallback_elem_t = try self.iterableElementType(effective_source_t);
                for (hir_mod.patternElements(self.hir, pattern_node), 0..) |elem, i| {
                    if (self.hir.kindOf(elem) != .parameter) continue;
                    const p = hir_mod.parameterOf(self.hir, elem);
                    if (p.name == hir_mod.none_node_id) continue;
                    var elem_node: NodeId = hir_mod.none_node_id;
                    var elem_t: TypeId = types.Primitive.any;
                    if (i < source_elements.len and source_elements[i] != hir_mod.none_node_id) {
                        elem_node = source_elements[i];
                        elem_t = self.hir.typeOf(elem_node);
                    } else if (p.default_value != hir_mod.none_node_id) {
                        elem_node = p.default_value;
                        elem_t = self.hir.typeOf(elem_node);
                    } else {
                        if (try self.unionTupleElementAccessAt(effective_source_t, i)) |access| {
                            elem_t = access.value_type;
                        } else {
                            const tuple_t = self.tupleElementType(effective_source_t, i);
                            elem_t = if (tuple_t != types.Primitive.none) tuple_t else fallback_elem_t;
                        }
                    }
                    if (elem_t == types.Primitive.none and elem_node != hir_mod.none_node_id and self.hir.kindOf(elem_node) != .identifier) {
                        elem_t = try self.checkExpression(elem_node);
                    }
                    if (elem_t == types.Primitive.none) elem_t = types.Primitive.any;
                    try self.recordBindingTargetFlow(p.name, elem_node, elem_t);
                }
            },
            .object_pattern => {
                for (hir_mod.patternElements(self.hir, pattern_node)) |elem| {
                    if (self.hir.kindOf(elem) != .parameter) continue;
                    const p = hir_mod.parameterOf(self.hir, elem);
                    if (p.name == hir_mod.none_node_id) continue;
                    if (p.flags.is_rest) {
                        const rest_t = try self.objectRestBindingType(pattern_node, effective_source_t);
                        try self.recordBindingTargetFlow(p.name, hir_mod.none_node_id, rest_t);
                        continue;
                    }
                    var prop_t: TypeId = types.Primitive.any;
                    if (p.flags.is_computed_binding_key and p.default_value != hir_mod.none_node_id) {
                        prop_t = (try self.objectPropertyTypeForComputedKeyNode(effective_source_t, p.default_value)) orelse types.Primitive.any;
                    } else if (try self.objectPropertyTypeFromBindingElementSource(effective_source_t, elem, p.name)) |source_prop_t| {
                        prop_t = source_prop_t;
                    } else if (try self.objectBindingElementKeyName(elem, p.name)) |key_name| {
                        prop_t = self.objectPropertyTypeByName(effective_source_t, key_name) orelse types.Primitive.any;
                    }
                    try self.recordBindingTargetFlow(p.name, hir_mod.none_node_id, prop_t);
                }
            },
            else => {},
        }
    }

    fn recordBindingTargetFlow(self: *Checker, target_node: NodeId, source_node: NodeId, source_t: TypeId) CheckError!void {
        if (target_node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(target_node)) {
            .identifier => {
                if (source_t == types.Primitive.none or source_t == types.Primitive.any or source_t == types.Primitive.unknown) return;
                const id = hir_mod.identifierOf(self.hir, target_node);
                try self.recordNarrow(id.name, source_t);
            },
            .array_pattern, .object_pattern => {
                try self.recordBindingPatternFlowFromSource(target_node, source_node, source_t);
            },
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, target_node);
                var default_t = self.hir.typeOf(a.value);
                if (default_t == types.Primitive.none and self.hir.kindOf(a.value) != .identifier) {
                    default_t = try self.checkExpression(a.value);
                }
                if (default_t == types.Primitive.none) default_t = types.Primitive.any;
                const effective_t = try self.destructuringSourceWithDefault(source_t, default_t);
                try self.recordBindingTargetFlow(a.target, a.value, effective_t);
            },
            else => {},
        }
    }

    fn reportImplicitAnyNullishArrayBinding(self: *Checker, pattern_node: NodeId, init_node: NodeId) CheckError!void {
        if (!self.strict_flags.no_implicit_any) return;
        if (self.hir.kindOf(pattern_node) != .array_pattern or self.hir.kindOf(init_node) != .array_literal) return;
        const values = hir_mod.arrayLiteralElements(self.hir, init_node);
        for (hir_mod.patternElements(self.hir, pattern_node), 0..) |e, i| {
            if (self.hir.kindOf(e) != .parameter) continue;
            if (i >= values.len) break;
            const value = values[i];
            if (value == hir_mod.none_node_id) continue;
            const vk = self.hir.kindOf(value);
            if (vk != .literal_null and vk != .literal_undefined) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.name == hir_mod.none_node_id or self.hir.kindOf(ep.name) != .identifier) continue;
            // A per-element default (`b5 = 3`) supplies a concrete type
            // for this slot, so tsc suppresses TS7031 even when the
            // source initializer position is `undefined`/`null`. Mirrors
            // upstream baselines for `destructuringVariableDeclaration1ES{5,6}`
            // line 12 ÃÂ¢ÃÂÃÂ `var [b5 = 3, b6 = true, b7 = temp] = [undefined, undefined, undefined];`
            // emits no implicit-any since each binding has a default.
            if (ep.default_value != hir_mod.none_node_id) continue;
            const id = hir_mod.identifierOf(self.hir, ep.name);
            const raw = self.string_interner.get(id.name);
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Binding element '{s}' implicitly has an 'any' type.",
                .{raw},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = ep.name,
                .code = TsCodes.binding_element_implicitly_any,
                .message = msg,
            });
        }
    }

    fn reportImplicitAnyNullishTupleVariable(self: *Checker, name_node: NodeId, init_node: NodeId) CheckError!void {
        if (!self.expressionIsNullishTupleLiteral(init_node)) return;
        const width = self.nullishTupleLiteralWidth(init_node) orelse return;
        const id = hir_mod.identifierOf(self.hir, name_node);
        const raw = self.string_interner.get(id.name);
        const arena = self.diag_arena.allocator();
        var type_buf: std.ArrayListUnmanaged(u8) = .empty;
        errdefer type_buf.deinit(arena);
        try type_buf.append(arena, '[');
        var i: usize = 0;
        while (i < width) : (i += 1) {
            if (i > 0) try type_buf.appendSlice(arena, ", ");
            try type_buf.appendSlice(arena, "any");
        }
        try type_buf.append(arena, ']');
        const msg = try std.fmt.allocPrint(
            arena,
            "Variable '{s}' implicitly has an '{s}' type.",
            .{ raw, type_buf.items },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = name_node,
            .code = TsCodes.variable_implicitly_any,
            .message = msg,
        });
    }

    fn isEmptyArrayLiteral(self: *Checker, node: NodeId) bool {
        return node != hir_mod.none_node_id and
            self.hir.kindOf(node) == .array_literal and
            hir_mod.arrayLiteralElements(self.hir, node).len == 0;
    }

    fn reportImplicitAnyArrayBindingElement(self: *Checker, node: NodeId) CheckError!void {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return;
        const id = hir_mod.identifierOf(self.hir, node);
        const raw = self.string_interner.get(id.name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Binding element '{s}' implicitly has an 'any[]' type.",
            .{raw},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.binding_element_implicitly_any,
            .message = msg,
        });
    }

    fn reportImplicitAnyEmptyArrayBindingDefaults(self: *Checker, pattern_node: NodeId) CheckError!void {
        const pk = self.hir.kindOf(pattern_node);
        if (pk != .object_pattern and pk != .array_pattern) return;
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.flags.is_computed_binding_key or ep.name == hir_mod.none_node_id) continue;
            const nk = self.hir.kindOf(ep.name);
            if (nk == .identifier) {
                if (self.isEmptyArrayLiteral(ep.default_value)) {
                    try self.reportImplicitAnyArrayBindingElement(ep.name);
                }
            } else if (nk == .object_pattern or nk == .array_pattern) {
                try self.reportImplicitAnyEmptyArrayBindingDefaults(ep.name);
            }
        }
    }

    /// Walk a parameter's binding pattern (array/object) and emit
    /// TS7031 (`Binding element 'X' implicitly has an 'any' type.`)
    /// for each named slot whose type would otherwise be implicit
    /// `any`. Mirrors upstream tsc, which reports one implicit-any
    /// per binding element rather than one `Parameter '<anonymous>'`
    /// for the whole pattern.
    ///
    /// `parent_init_values` ÃÂ¢ÃÂÃÂ when the parameter or enclosing
    /// pattern has an `= [a, b]` literal default initializer, the
    /// per-index value expressions supply concrete types for inner
    /// elements; passing the slice here suppresses TS7031 on
    /// positions where the default provides a usable type.
    fn reportImplicitAnyBindingPatternElements(
        self: *Checker,
        pattern_node: NodeId,
        parent_init_values: []const NodeId,
    ) CheckError!void {
        const pk = self.hir.kindOf(pattern_node);
        if (pk != .object_pattern and pk != .array_pattern) return;
        const is_array = pk == .array_pattern;
        var idx: usize = 0;
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) {
                if (is_array) idx += 1;
                continue;
            }
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.flags.is_computed_binding_key) continue;
            if (ep.name == hir_mod.none_node_id) {
                if (is_array) idx += 1;
                continue;
            }
            // An element-level `= expr` default supplies a concrete
            // type for this slot (number from `= 0`, string from
            // `= 'foo'`, etc.). tsc suppresses TS7031 in that case.
            const has_own_default = ep.default_value != hir_mod.none_node_id;
            // The parent-level default (e.g. `= [undefined, null]`)
            // also covers this binding slot. tsc suppresses TS7031
            // for covered slots even when the covering value is
            // nullish; uncovered holes still report.
            var parent_default_supplies = false;
            var nested_parent_values: []const NodeId = &.{};
            if (is_array and idx < parent_init_values.len) {
                const v = parent_init_values[idx];
                if (v != hir_mod.none_node_id) {
                    parent_default_supplies = true;
                    if (self.hir.kindOf(v) == .array_literal) {
                        nested_parent_values = hir_mod.arrayLiteralElements(self.hir, v);
                    }
                }
            }
            const nk = self.hir.kindOf(ep.name);
            if (nk == .identifier) {
                if (self.isEmptyArrayLiteral(ep.default_value)) {
                    try self.reportImplicitAnyArrayBindingElement(ep.name);
                } else if (!has_own_default and !parent_default_supplies) {
                    const id = hir_mod.identifierOf(self.hir, ep.name);
                    const raw = self.string_interner.get(id.name);
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Binding element '{s}' implicitly has an 'any' type.",
                        .{raw},
                    );
                    try self.diagnostics.append(self.gpa, .{
                        .node = ep.name,
                        .code = TsCodes.binding_element_implicitly_any,
                        .message = msg,
                    });
                }
            } else if (nk == .object_pattern or nk == .array_pattern) {
                var child_parent_values = nested_parent_values;
                if (child_parent_values.len == 0 and has_own_default and self.hir.kindOf(ep.default_value) == .array_literal) {
                    child_parent_values = hir_mod.arrayLiteralElements(self.hir, ep.default_value);
                }
                try self.reportImplicitAnyBindingPatternElements(ep.name, child_parent_values);
            }
            if (is_array) idx += 1;
        }
    }

    /// True when `expr` (an element of a `= [a, b]` parameter
    /// default initializer) widens to a concrete type tsc treats
    /// as suppressing the inner element's TS7031 implicit-any.
    /// Conservative: only literals and identifiers with concrete
    /// inferred types qualify.
    fn bindingDefaultElementIsTyped(self: *Checker, expr: NodeId) bool {
        const k = self.hir.kindOf(expr);
        switch (k) {
            .literal_number,
            .literal_string,
            .literal_bool,
            .literal_bigint,
            .template_literal,
            .literal_regex,
            => return true,
            .literal_null, .literal_undefined => return false,
            // Identifiers / arbitrary expressions: only suppress
            // when the resolved type is non-any. Avoid over-firing
            // on `[anyVar]` patterns where the source is itself any.
            else => {
                const t = self.hir.typeOf(expr);
                if (t == types.Primitive.none) return false;
                if (t == types.Primitive.any) return false;
                if (t == types.Primitive.unknown) return false;
                return true;
            },
        }
    }

    fn isNumericStringId(self: *Checker, name: hir_mod.StringId) bool {
        const s = self.string_interner.get(name);
        if (s.len == 0) return false;
        for (s) |c| {
            if (c < '0' or c > '9') return false;
        }
        return true;
    }

    fn objectBindingElementUsesImplicitKey(self: *Checker, elem_node: NodeId, name_node: NodeId) bool {
        const src = self.source orelse return true;
        const elem_span = self.hir.spanOf(elem_node);
        const name_span = self.hir.spanOf(name_node);
        if (name_span.start <= elem_span.start or name_span.start > src.len) return true;
        const prefix = src[elem_span.start..@min(@as(usize, name_span.start), src.len)];
        return std.mem.indexOfScalar(u8, prefix, ':') == null and
            std.mem.indexOfScalar(u8, prefix, '[') == null;
    }

    fn objectPropertyHasInitializerEquals(self: *Checker, prop_node: NodeId, value_node: NodeId) bool {
        if (prop_node == hir_mod.none_node_id or value_node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(prop_node) != .object_property) return false;
        const src = self.source orelse return false;
        const prop = hir_mod.objectPropertyOf(self.hir, prop_node);
        if (prop.key == hir_mod.none_node_id) return false;
        const key_span = self.hir.spanOf(prop.key);
        const value_span = self.hir.spanOf(value_node);
        if (key_span.end > value_span.start or value_span.start > src.len) return false;
        return std.mem.indexOfScalar(u8, src[key_span.end..value_span.start], '=') != null;
    }

    fn objectBindingElementKeyName(self: *Checker, elem_node: NodeId, name_node: NodeId) CheckError!?hir_mod.StringId {
        if (name_node == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(elem_node) == .parameter) {
            const p = hir_mod.parameterOf(self.hir, elem_node);
            if (p.flags.is_computed_binding_key and p.default_value != hir_mod.none_node_id) {
                if (try self.propertyNameFromComputedBindingKeyNode(p.default_value)) |name| return name;
            }
        }
        if (self.hir.kindOf(name_node) == .identifier and self.objectBindingElementUsesImplicitKey(elem_node, name_node)) {
            return hir_mod.identifierOf(self.hir, name_node).name;
        }
        const src = self.source orelse return null;
        const elem_span = self.hir.spanOf(elem_node);
        const name_span = self.hir.spanOf(name_node);
        if (elem_span.start >= src.len or name_span.start > src.len or name_span.start <= elem_span.start) return null;
        const prefix = src[elem_span.start..name_span.start];
        const colon = std.mem.indexOfScalar(u8, prefix, ':') orelse return null;
        var raw = std.mem.trim(u8, prefix[0..colon], " \t\r\n");
        if (raw.len >= 2 and raw[0] == '[' and raw[raw.len - 1] == ']') {
            if (self.propertyNameFromRawComputedKeyText(raw[1 .. raw.len - 1])) |name| return name;
            return null;
        }
        if (raw.len >= 2 and ((raw[0] == '"' and raw[raw.len - 1] == '"') or (raw[0] == '\'' and raw[raw.len - 1] == '\''))) {
            raw = raw[1 .. raw.len - 1];
        }
        if (raw.len == 0) return null;
        return self.string_interner.intern(raw) catch return error.OutOfMemory;
    }

    fn propertyNameFromComputedBindingKeyNode(self: *Checker, key_node: NodeId) CheckError!?hir_mod.StringId {
        const key_t = try self.checkExpression(key_node);
        if (try self.propertyNameFromLiteralType(key_t)) |name| return name;
        if (try self.propertyNameFromConstReturningIife(key_node)) |name| return name;
        if (self.propertyNameFromComputedKeySourceReturn(key_node)) |name| return name;
        return null;
    }

    fn objectPropertyTypeFromBindingElementSource(self: *Checker, source_t: TypeId, elem_node: NodeId, name_node: NodeId) CheckError!?TypeId {
        const src = self.source orelse return null;
        const elem_span = self.hir.spanOf(elem_node);
        const name_span = self.hir.spanOf(name_node);
        if (elem_span.start >= src.len or name_span.start > src.len or name_span.start <= elem_span.start) return null;
        const prefix = src[elem_span.start..name_span.start];
        const colon = std.mem.indexOfScalar(u8, prefix, ':') orelse return null;
        const raw = std.mem.trim(u8, prefix[0..colon], " \t\r\n");
        if (raw.len < 3 or raw[0] != '[' or raw[raw.len - 1] != ']') return null;
        const inner = std.mem.trim(u8, raw[1 .. raw.len - 1], " \t\r\n");
        if (inner.len == 0) return null;
        if (!isAsciiIdentifierText(inner)) return null;
        const key_name = self.string_interner.intern(inner) catch return error.OutOfMemory;
        const key_t = (try self.typeOfVisibleNameNoDiag(elem_node, key_name)) orelse return null;
        return try self.objectPropertyTypeForComputedKeyType(source_t, key_t);
    }

    fn isAsciiIdentifierText(text: []const u8) bool {
        if (text.len == 0) return false;
        const first = text[0];
        if (!((first >= 'A' and first <= 'Z') or (first >= 'a' and first <= 'z') or first == '_' or first == '$')) return false;
        for (text[1..]) |ch| {
            if (!((ch >= 'A' and ch <= 'Z') or (ch >= 'a' and ch <= 'z') or (ch >= '0' and ch <= '9') or ch == '_' or ch == '$')) return false;
        }
        return true;
    }

    fn propertyNameFromRawComputedKeyText(self: *Checker, raw: []const u8) ?hir_mod.StringId {
        const trimmed = std.mem.trim(u8, raw, " \t\r\n");
        if (trimmed.len >= 2 and
            ((trimmed[0] == '"' and trimmed[trimmed.len - 1] == '"') or
                (trimmed[0] == '\'' and trimmed[trimmed.len - 1] == '\'')))
        {
            return self.string_interner.intern(trimmed[1 .. trimmed.len - 1]) catch null;
        }
        const ret_idx = std.mem.indexOf(u8, raw, "return") orelse return null;
        const tail = raw[ret_idx + "return".len ..];
        var i: usize = 0;
        while (i < tail.len and (tail[i] == ' ' or tail[i] == '\t' or tail[i] == '\r' or tail[i] == '\n')) : (i += 1) {}
        if (i >= tail.len) return null;
        const quote = tail[i];
        if (quote != '"' and quote != '\'') return null;
        const start = i + 1;
        var end = start;
        while (end < tail.len and tail[end] != quote) : (end += 1) {}
        if (end >= tail.len or end == start) return null;
        return self.string_interner.intern(tail[start..end]) catch null;
    }

    /// True when `node` is the name slot of its enclosing
    /// declaration (parameter / var / fn / class / interface /
    /// type alias). Used to filter declarations out of the
    /// reference-counting walk.
    fn isDeclNameSlot(self: *Checker, node: NodeId) bool {
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return false;
        switch (self.hir.kindOf(parent)) {
            .parameter => {
                const p = hir_mod.parameterOf(self.hir, parent);
                return p.name == node;
            },
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, parent);
                return v.name == node;
            },
            .fn_decl, .fn_expr, .arrow_fn => {
                const f = hir_mod.fnDeclOf(self.hir, parent);
                if (f.name != node) return false;
                // Computed class-member names (`get [e]()` / `set [e](v)`,
                // `[e]()` / `*[e]()`) reference an outer-scope value via
                // bracketed expression syntax ÃÂ¢ÃÂÃÂ they introduce nothing
                // and must NOT be treated as a declaration name slot,
                // otherwise the unbound-name TS2304 sweep skips them.
                // Mirrors upstream tsc on `parserComputedPropertyName23
                // .ts(2,10)` and `parserComputedPropertyName24.ts(2,10)`.
                if (self.nodeIsBracketedComputedName(node)) return false;
                return true;
            },
            .class_decl, .class_expr => {
                const c = hir_mod.classOf(self.hir, parent);
                return c.name == node;
            },
            .interface_decl => {
                const it = hir_mod.interfaceOf(self.hir, parent);
                return it.name == node;
            },
            .type_alias_decl => {
                const ta = hir_mod.typeAliasOf(self.hir, parent);
                return ta.name == node;
            },
            else => return false,
        }
    }

    /// True if `node` is the identifier used as the computed key of a
    /// class member whose enclosing declaration is ambient (`declare
    /// class ÃÂ¢ÃÂÃÂ¦`) or whose member itself is abstract ÃÂ¢ÃÂÃÂ i.e. the
    /// `[name]` expression is never evaluated at runtime, so an
    /// `import type` binding used inside it shouldn't trip TS1361.
    /// Mirrors upstream tsc's behaviour on
    /// `computedPropertyName.ts` (typeOnly/) where TS suppresses the
    /// diagnostic on abstract methods and `declare class` members.
    fn isComputedKeyInAmbientClassMember(self: *Checker, node: NodeId) bool {
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return false;
        const parent_kind = self.hir.kindOf(parent);
        // Class methods are represented as `fn_decl` nodes carrying the
        // computed-name identifier as their `name` slot. Abstract
        // methods have no body and are not emitted; suppress here.
        if (parent_kind == .fn_decl or parent_kind == .fn_expr) {
            const f = hir_mod.fnDeclOf(self.hir, parent);
            if (f.name != node) return false;
            if (f.flags.is_abstract) return true;
            // Ambient class methods: check the enclosing `class_decl`.
            const grand = self.hir.parentOf(parent);
            if (grand != hir_mod.none_node_id and
                (self.hir.kindOf(grand) == .class_decl or self.hir.kindOf(grand) == .class_expr))
            {
                if (self.declarationLineHasDeclare(grand) or
                    self.declarationSourceHasLeadingDeclare(grand)) return true;
            }
            return false;
        }
        // Class fields / accessors / method bodies surface as
        // `object_property` nodes. Detect computed keys, then check
        // for abstract/declare on the enclosing class declaration.
        if (parent_kind != .object_property) return false;
        const op = hir_mod.objectPropertyOf(self.hir, parent);
        if (!op.is_computed or op.key != node) return false;
        const grand = self.hir.parentOf(parent);
        if (grand == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(grand) != .class_decl and self.hir.kindOf(grand) != .class_expr) return false;
        if (self.declarationLineHasDeclare(grand) or
            self.declarationSourceHasLeadingDeclare(grand)) return true;
        // `abstract [name](): void;` / `abstract [name]: T;` in a
        // non-`declare` class: tsc emits the diagnostic for concrete
        // members of an abstract class, so don't blanket-suppress
        // every member just because the class is abstract ÃÂ¢ÃÂÃÂ limit to
        // the per-member `abstract` modifier (carried by `fn_decl`
        // above; for fields, fall back to a line-level keyword scan
        // since `object_property` has no dedicated flag).
        if (self.objectPropertyLineHasAbstract(parent)) return true;
        // Per-field `declare` modifier: `declare [name]: T;` inside a
        // concrete class. The computed expression isn't evaluated at
        // runtime because the field is ambient-only.
        if (self.declarationLineHasDeclare(parent)) return true;
        return false;
    }

    /// True when `node` is a bare `identifier` HIR node whose name
    /// has no binding visible from the current position ÃÂ¢ÃÂÃÂ checked by
    /// walking the parent chain for matching parameter/let/const/var
    /// declarations and (when bound) the module symbol table. Used by
    /// the computed-property-name path to short-circuit the
    /// "must be of type 'string', 'number', 'symbol', or 'any'"
    /// TS2464 emit when the cause is really a missing binding (which
    /// tsc reports as TS2304 alone). Mirrors
    /// `parserComputedPropertyName23/24` baselines.
    fn computedNameBareIdentifierUnresolved(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, node);
        const name_str = self.string_interner.get(id.name);
        if (self.isBuiltinName(id.name)) return false;
        if (self.lookupNarrow(id.name) != null) return false;
        // Walk parents for parameter / let / const / var bindings.
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                for (hir_mod.fnParams(self.hir, cur)) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id) continue;
                    if (self.hir.kindOf(pp.name) != .identifier) continue;
                    const pid = hir_mod.identifierOf(self.hir, pp.name);
                    if (pid.name == id.name) return false;
                }
            } else if (k == .block_stmt) {
                for (hir_mod.blockStmts(self.hir, cur)) |s| {
                    const sk = self.hir.kindOf(s);
                    if (sk == .var_decl or sk == .let_decl or sk == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, s);
                        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                            const vid = hir_mod.identifierOf(self.hir, v.name);
                            if (vid.name == id.name) return false;
                        }
                    } else if (sk == .fn_decl or sk == .fn_expr) {
                        const fp = hir_mod.fnDeclOf(self.hir, s);
                        if (fp.name != hir_mod.none_node_id and self.hir.kindOf(fp.name) == .identifier) {
                            const fid = hir_mod.identifierOf(self.hir, fp.name);
                            if (fid.name == id.name) return false;
                        }
                    } else if (sk == .class_decl or sk == .class_expr) {
                        const cp = hir_mod.classOf(self.hir, s);
                        if (cp.name != hir_mod.none_node_id and self.hir.kindOf(cp.name) == .identifier) {
                            const cid = hir_mod.identifierOf(self.hir, cp.name);
                            if (cid.name == id.name) return false;
                        }
                    }
                }
            }
        }
        // Module-level bindings.
        if (self.module) |module| {
            if (module.root.lookup(id.name) != null) return false;
        }
        // Source-level declaration text scan picks up ambient
        // `declare const sym`-style computed-name keys that the binder
        // may not have materialized into this local scope.
        if (self.sourceHasLexicalValueDeclarationText(id.name)) return false;
        _ = name_str;
        return true;
    }

    fn objectPropertyLineHasAbstract(self: *Checker, prop_node: NodeId) bool {
        const src = self.source orelse return false;
        const span = self.hir.spanOf(prop_node);
        if (span.start >= src.len) return false;
        var line_start: usize = span.start;
        while (line_start > 0 and src[line_start - 1] != '\n') : (line_start -= 1) {}
        var i = line_start;
        while (i < src.len and (src[i] == ' ' or src[i] == '\t')) : (i += 1) {}
        const word = "abstract";
        if (i + word.len > src.len) return false;
        if (!std.mem.eql(u8, src[i .. i + word.len], word)) return false;
        if (i + word.len < src.len and isJsDocIdentChar(src[i + word.len])) return false;
        return true;
    }

    fn callableSignatureType(self: *Checker, t: TypeId) ?TypeId {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return null;
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_signature) return t;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (member == types.Primitive.null_t or member == types.Primitive.undefined_t) continue;
                if (self.callableSignatureType(member)) |sig| return sig;
            }
        }
        return null;
    }

    fn promiseTypeArgHasRecursiveThenCallback(self: *Checker, type_node: NodeId) bool {
        if (type_node == hir_mod.none_node_id or self.hir.kindOf(type_node) != .type_ref) return false;
        const type_ref = hir_mod.typeRefOf(self.hir, type_node);
        if (type_ref.qualifier_len != 0 or type_ref.args_len != 0) return false;
        return self.typeNodeThenCallbackReferencesName(type_node, type_ref.name, type_node, 0);
    }

    fn typeNodeThenCallbackReferencesName(self: *Checker, type_node: NodeId, target_name: hir_mod.StringId, anchor: NodeId, depth: u8) bool {
        if (type_node == hir_mod.none_node_id or depth > 8) return false;
        switch (self.hir.kindOf(type_node)) {
            .type_ref => {
                const type_ref = hir_mod.typeRefOf(self.hir, type_node);
                if (type_ref.qualifier_len != 0 or type_ref.args_len != 0) return false;
                return self.namedTypeThenCallbackReferencesName(type_ref.name, target_name, anchor, depth + 1);
            },
            .object_type => {
                return self.typeMembersThenCallbackReferenceName(
                    hir_mod.objectTypeMembers(self.hir, type_node),
                    target_name,
                    anchor,
                    depth + 1,
                );
            },
            else => return false,
        }
    }

    fn namedTypeThenCallbackReferencesName(self: *Checker, name: hir_mod.StringId, target_name: hir_mod.StringId, anchor: NodeId, depth: u8) bool {
        if (depth > 8) return false;
        if (self.module) |module| {
            if (module.root.lookup(name)) |sym| {
                for (sym.decls.items) |raw_decl| {
                    if (self.typeDeclThenCallbackReferencesName(raw_decl, target_name, anchor, depth + 1)) return true;
                }
            }
        }
        const root = self.rootBlockFor(anchor);
        if (root != hir_mod.none_node_id and self.hir.kindOf(root) == .block_stmt) {
            for (hir_mod.blockStmts(self.hir, root)) |raw_stmt| {
                const decl = self.unwrapExportDecl(raw_stmt);
                const decl_name: ?hir_mod.StringId = switch (self.hir.kindOf(decl)) {
                    .interface_decl => blk: {
                        const iface = hir_mod.interfaceOf(self.hir, decl);
                        if (iface.name == hir_mod.none_node_id or self.hir.kindOf(iface.name) != .identifier) break :blk null;
                        break :blk hir_mod.identifierOf(self.hir, iface.name).name;
                    },
                    .type_alias_decl => blk: {
                        const alias = hir_mod.typeAliasOf(self.hir, decl);
                        if (alias.name == hir_mod.none_node_id or self.hir.kindOf(alias.name) != .identifier) break :blk null;
                        break :blk hir_mod.identifierOf(self.hir, alias.name).name;
                    },
                    else => null,
                };
                if (decl_name != null and decl_name.? == name and
                    self.typeDeclThenCallbackReferencesName(decl, target_name, anchor, depth + 1))
                {
                    return true;
                }
            }
        }
        return false;
    }

    fn typeDeclThenCallbackReferencesName(self: *Checker, raw_decl: NodeId, target_name: hir_mod.StringId, anchor: NodeId, depth: u8) bool {
        if (depth > 8) return false;
        const decl = self.unwrapExportDecl(raw_decl);
        return switch (self.hir.kindOf(decl)) {
            .interface_decl => self.typeMembersThenCallbackReferenceName(
                hir_mod.interfaceMembers(self.hir, decl),
                target_name,
                anchor,
                depth + 1,
            ),
            .type_alias_decl => blk: {
                const ta = hir_mod.typeAliasOf(self.hir, decl);
                break :blk self.typeNodeThenCallbackReferencesName(ta.aliased, target_name, anchor, depth + 1);
            },
            else => false,
        };
    }

    fn typeMembersThenCallbackReferenceName(self: *Checker, members: []const NodeId, target_name: hir_mod.StringId, anchor: NodeId, depth: u8) bool {
        if (depth > 8) return false;
        const then_id = self.string_interner.intern("then") catch return false;
        for (members) |member| {
            if (self.hir.kindOf(member) != .interface_member) continue;
            const im = hir_mod.interfaceMemberOf(self.hir, member);
            if (im.name != then_id) continue;
            if (self.thenMemberCallbackReferencesName(im.type_node, target_name, anchor, depth + 1)) return true;
        }
        return false;
    }

    fn thenMemberCallbackReferencesName(self: *Checker, then_type_node: NodeId, target_name: hir_mod.StringId, anchor: NodeId, depth: u8) bool {
        if (then_type_node == hir_mod.none_node_id or depth > 8) return false;
        if (self.hir.kindOf(then_type_node) != .fn_type) return false;
        const then_ft = hir_mod.fnTypeOf(self.hir, then_type_node);
        if (then_ft.params_len == 0) return false;
        const cb_param = self.hir.child_pool.items[then_ft.params_start];
        if (self.hir.kindOf(cb_param) != .parameter) return false;
        const cb = hir_mod.parameterOf(self.hir, cb_param);
        if (cb.type_annotation == hir_mod.none_node_id or self.hir.kindOf(cb.type_annotation) != .fn_type) return false;
        const cb_ft = hir_mod.fnTypeOf(self.hir, cb.type_annotation);
        if (cb_ft.params_len == 0) return false;
        const value_param = self.hir.child_pool.items[cb_ft.params_start];
        if (self.hir.kindOf(value_param) != .parameter) return false;
        const value = hir_mod.parameterOf(self.hir, value_param);
        if (value.type_annotation == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(value.type_annotation) == .type_ref) {
            const value_ref = hir_mod.typeRefOf(self.hir, value.type_annotation);
            if (value_ref.qualifier_len == 0 and value_ref.args_len == 0 and value_ref.name == target_name) return true;
        }
        return self.typeNodeThenCallbackReferencesName(value.type_annotation, target_name, anchor, depth + 1);
    }

    fn promiseLikeResult(self: *Checker, t: TypeId) PromiseLikeResult {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return .none;
        if (t >= self.interner.pool.typeCount()) return .none;
        if (!self.interner.pool.flagsOf(t).is_object_type) return .none;
        const then_id = self.string_interner.intern("then") catch return .none;
        const then_t = self.interner.objectMember(t, then_id) orelse return .none;
        const then_sig = self.callableSignatureType(then_t) orelse return .none;
        if (self.signatureThisParam(then_sig)) |this_t| {
            if (!(self.thisContextAssignableTo(t, this_t) catch false)) return .malformed;
        }
        const then_params = self.interner.signatureParams(then_sig);
        if (then_params.len == 0) return .malformed;
        const cb_sig = self.callableSignatureType(then_params[0]) orelse return .malformed;
        const cb_params = self.interner.signatureParams(cb_sig);
        if (cb_params.len == 0) return .{ .promised = types.Primitive.never };
        return .{ .promised = cb_params[0] };
    }

    fn awaitedChainIssue(self: *Checker, t: TypeId) AwaitedChainIssue {
        var cur = t;
        var seen: [64]TypeId = undefined;
        var seen_len: usize = 0;
        var i: usize = 0;
        while (i < 64) : (i += 1) {
            for (seen[0..seen_len]) |seen_t| {
                if (cur == seen_t) return .recursive_then;
            }
            seen[seen_len] = cur;
            seen_len += 1;
            switch (self.promiseLikeResult(cur)) {
                .none => return .none,
                .malformed => return .malformed_then,
                .promised => |promised| cur = promised,
            }
        }
        return .none;
    }

    fn asyncReturnDiagnosticAnchor(self: *Checker, node: NodeId) NodeId {
        var current = node;
        while (current != hir_mod.none_node_id) : (current = self.hir.parentOf(current)) {
            switch (self.hir.kindOf(current)) {
                .fn_decl, .fn_expr, .arrow_fn => return self.functionNameOrNode(current),
                else => {},
            }
        }
        return node;
    }

    fn reportAsyncReturnInvalidThenable(self: *Checker, node: NodeId) CheckError!void {
        try self.report(node, TsCodes.async_return_must_be_valid_promise_or_no_callable_then, "The return type of an async function must either be a valid promise or must not contain a callable 'then' member.");
    }

    fn reportTypeReferencedInOwnThenCallback(self: *Checker, node: NodeId) CheckError!void {
        try self.report(node, TsCodes.type_referenced_in_own_then_callback, "Type is referenced directly or indirectly in the fulfillment callback of its own 'then' method.");
    }

    /// If `t` is structurally a `Promise<T>` ÃÂ¢ÃÂÃÂ an object type with a
    /// valid callable `then` member whose first parameter is itself a
    /// callback signature `(value: T) => any` ÃÂ¢ÃÂÃÂ return `T`.
    /// Otherwise return `t` unchanged. This lets `await p` unwrap to
    /// the resolved value type without first-class generics support.
    fn unwrapPromise(self: *Checker, t: TypeId) TypeId {
        return switch (self.promiseLikeResult(t)) {
            .promised => |promised| promised,
            .none, .malformed => t,
        };
    }

    fn awaitedTypeForAwaitExpression(self: *Checker, node: NodeId, t: TypeId) CheckError!AwaitedTypeResult {
        switch (self.promiseLikeResult(t)) {
            .none => return .{ .type = t },
            .malformed => {
                try self.report(node, TsCodes.await_operand_must_be_valid_promise_or_no_callable_then, "Type of 'await' operand must either be a valid promise or must not contain a callable 'then' member.");
                return .{ .type = t, .invalid_thenable = true };
            },
            .promised => |promised| return .{ .type = promised },
        }
    }

    fn awaitedTypeForAsyncGeneratorYield(self: *Checker, node: NodeId, t: TypeId) CheckError!AwaitedTypeResult {
        switch (self.promiseLikeResult(t)) {
            .none => return .{ .type = t },
            .malformed => {
                try self.report(node, TsCodes.async_generator_yield_operand_must_be_valid_promise_or_no_callable_then, "Type of 'yield' operand in an async generator must either be a valid promise or must not contain a callable 'then' member.");
                return .{ .type = t, .invalid_thenable = true };
            },
            .promised => |promised| return .{ .type = promised },
        }
    }

    fn awaitedTypeForAsyncGeneratorYieldStarElement(self: *Checker, node: NodeId, t: TypeId) CheckError!AwaitedTypeResult {
        switch (self.promiseLikeResult(t)) {
            .none => return .{ .type = t },
            .malformed => {
                try self.report(node, TsCodes.async_generator_yield_star_element_must_be_valid_promise_or_no_callable_then, "Type of iterated elements of a 'yield*' operand must either be a valid promise or must not contain a callable 'then' member.");
                return .{ .type = t, .invalid_thenable = true };
            },
            .promised => |promised| return .{ .type = promised },
        }
    }

    /// `Awaited<T>` (TS 4.5) ÃÂ¢ÃÂÃÂ recursively unwrap `Promise<U>` until
    /// the operand is no longer a structural Promise. For non-Promise
    /// types this is a no-op and `t` is returned unchanged.
    fn evalAwaited(self: *Checker, t: TypeId) TypeId {
        var cur = t;
        // Cap recursion in case of pathological self-referential
        // Promise shapes; TS itself imposes no fixed depth, but a
        // small bound matches the practical universe of Promise<...>
        // chains and prevents runaway loops on cyclic types.
        var i: usize = 0;
        while (i < 64) : (i += 1) {
            const next = self.unwrapPromise(cur);
            if (next == cur) return cur;
            cur = next;
        }
        return cur;
    }

    /// Build a minimal structural `Promise<T>` object type ÃÂ¢ÃÂÃÂ `{ then:
    /// (onfulfilled: (value: T) => any, onrejected?: any) => any }` ÃÂ¢ÃÂÃÂ
    /// used when intercepting `Promise<T>` type-refs so downstream
    /// Awaited / await unwrap machinery can recognize and peel them.
    fn buildStructuralPromise(self: *Checker, value_t: TypeId) CheckError!TypeId {
        const cb_params = [_]TypeId{value_t};
        const cb_sig = self.interner.internSignature(&cb_params, types.Primitive.any, false) catch return error.OutOfMemory;
        var any_or_undefined_members = [_]TypeId{ types.Primitive.any, types.Primitive.undefined_t };
        const optional_any = self.interner.internUnion(&any_or_undefined_members) catch return error.OutOfMemory;
        const then_params = [_]TypeId{ cb_sig, optional_any };
        const then_sig = self.interner.internSignature(&then_params, types.Primitive.any, false) catch return error.OutOfMemory;
        const finally_cb_sig = self.interner.internSignature(&[_]TypeId{}, types.Primitive.any, false) catch return error.OutOfMemory;
        const finally_sig = self.interner.internSignature(&[_]TypeId{finally_cb_sig}, types.Primitive.any, false) catch return error.OutOfMemory;
        // `catch(onrejected?: (reason: any) => any): Promise<any>` — modeled
        // loosely as `(cb?) => any`. Without it, `p.catch(...)` on a
        // `Promise<T>` value tripped a spurious TS2339.
        const catch_sig = self.interner.internSignature(&[_]TypeId{optional_any}, types.Primitive.any, false) catch return error.OutOfMemory;
        const then_id = self.string_interner.intern("then") catch return error.OutOfMemory;
        const finally_id = self.string_interner.intern("finally") catch return error.OutOfMemory;
        const catch_id = self.string_interner.intern("catch") catch return error.OutOfMemory;
        const value_id = self.string_interner.intern("__home_promise_value") catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{
            .{
                .name = then_id,
                .type = then_sig,
                .is_optional = false,
                .is_readonly = false,
                .is_method = true,
            },
            .{
                .name = catch_id,
                .type = catch_sig,
                .is_optional = false,
                .is_readonly = false,
                .is_method = true,
            },
            .{
                .name = finally_id,
                .type = finally_sig,
                .is_optional = false,
                .is_readonly = false,
                .is_method = true,
            },
            .{
                .name = value_id,
                .type = value_t,
                .is_optional = false,
                .is_readonly = true,
                .is_method = false,
            },
        };
        const promise_t = self.interner.internObjectType(&members) catch return error.OutOfMemory;
        const promise_name = self.string_interner.intern("Promise") catch return error.OutOfMemory;
        try self.registerAliasDisplayName(promise_t, promise_name, &[_]TypeId{value_t});
        return promise_t;
    }

    fn buildStructuralPromiseLike(self: *Checker, value_t: TypeId) CheckError!TypeId {
        const cb_sig = self.interner.internSignature(&[_]TypeId{value_t}, types.Primitive.any, false) catch return error.OutOfMemory;
        const optional_any = self.interner.internUnion(&.{ types.Primitive.any, types.Primitive.undefined_t }) catch return error.OutOfMemory;
        const then_sig = self.interner.internSignature(&.{ cb_sig, optional_any }, types.Primitive.any, false) catch return error.OutOfMemory;
        try self.signature_min_args.put(self.gpa, then_sig, 0);
        const then_id = self.string_interner.intern("then") catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{.{
            .name = then_id,
            .type = then_sig,
            .is_optional = false,
            .is_readonly = false,
            .is_method = true,
        }};
        const promise_like_t = self.interner.internObjectType(&members) catch return error.OutOfMemory;
        const promise_like_name = self.string_interner.intern("PromiseLike") catch return error.OutOfMemory;
        try self.registerAliasDisplayName(promise_like_t, promise_like_name, &[_]TypeId{value_t});
        return promise_like_t;
    }

    fn buildIteratorResultObject(self: *Checker, value_t: TypeId) CheckError!TypeId {
        const value_id = self.string_interner.intern("value") catch return error.OutOfMemory;
        const done_id = self.string_interner.intern("done") catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{
            .{ .name = value_id, .type = value_t, .is_optional = false, .is_readonly = false, .is_method = false },
            .{ .name = done_id, .type = types.Primitive.boolean_t, .is_optional = false, .is_readonly = false, .is_method = false },
        };
        return self.interner.internObjectType(&members) catch return error.OutOfMemory;
    }

    fn buildBuiltinIteratorCore(
        self: *Checker,
        value_t: TypeId,
        return_t: TypeId,
        next_t: TypeId,
        is_async: bool,
    ) CheckError!TypeId {
        const result_value_t = self.interner.internUnion(&.{ value_t, return_t }) catch return error.OutOfMemory;
        const result_t = try self.buildIteratorResultObject(result_value_t);
        const next_return_t = if (is_async) try self.buildStructuralPromise(result_t) else result_t;
        const next_param_t = self.unionWithUndefined(next_t) catch next_t;
        const next_sig = self.interner.internSignature(&.{next_param_t}, next_return_t, false) catch return error.OutOfMemory;
        try self.recordSignatureMinArgs(next_sig, &.{true});
        const next_id = self.string_interner.intern("next") catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{
            .{ .name = next_id, .type = next_sig, .is_optional = false, .is_readonly = false, .is_method = true },
        };
        return self.interner.internObjectType(&members) catch return error.OutOfMemory;
    }

    fn buildBuiltinIterableTypeRef(self: *Checker, name: []const u8, name_id: hir_mod.StringId, args: []const TypeId) CheckError!?TypeId {
        const is_sync_iterator_object = std.mem.eql(u8, name, "IteratorObject");
        const is_async_iterator_object = std.mem.eql(u8, name, "AsyncIteratorObject");
        const is_sync_iterator = std.mem.eql(u8, name, "Iterator");
        const is_async_iterator = std.mem.eql(u8, name, "AsyncIterator");
        const is_sync_iterable = std.mem.eql(u8, name, "Iterable");
        const is_async_iterable = std.mem.eql(u8, name, "AsyncIterable");
        const is_sync_iterable_iterator = std.mem.eql(u8, name, "IterableIterator");
        const is_async_iterable_iterator = std.mem.eql(u8, name, "AsyncIterableIterator");
        if (!is_sync_iterator_object and !is_async_iterator_object and
            !is_sync_iterator and !is_async_iterator and
            !is_sync_iterable and !is_async_iterable and
            !is_sync_iterable_iterator and !is_async_iterable_iterator)
        {
            return null;
        }

        if (args.len == 0) return null;
        const yield_t = args[0];
        const return_t = if (args.len >= 2) args[1] else types.Primitive.any;
        const next_t = if (args.len >= 3) args[2] else types.Primitive.any;
        if (is_sync_iterator_object or is_async_iterator_object) {
            const result_t = lib.iteratorObjectType(self.interner, self.string_interner, yield_t, is_async_iterator_object) catch return error.OutOfMemory;
            try self.generator_type_info.put(self.gpa, result_t, .{
                .yield_type = yield_t,
                .return_type = return_t,
                .next_type = next_t,
            });
            try self.registerAliasDisplayName(result_t, name_id, args);
            return result_t;
        }
        const is_async = is_async_iterator or is_async_iterable or is_async_iterable_iterator;
        const iterator_t = try self.buildBuiltinIteratorCore(yield_t, return_t, next_t, is_async);
        const result_t = if (is_sync_iterator or is_async_iterator) iterator_t else blk: {
            const symbol_name = if (is_async) "Symbol.asyncIterator" else "Symbol.iterator";
            const symbol_id = self.string_interner.intern(symbol_name) catch return error.OutOfMemory;
            const iter_sig = self.interner.internSignature(&[_]TypeId{}, iterator_t, false) catch return error.OutOfMemory;
            if (is_sync_iterable or is_async_iterable) {
                const members = [_]types.ObjectMember{
                    .{ .name = symbol_id, .type = iter_sig, .is_optional = false, .is_readonly = false, .is_method = true },
                };
                break :blk self.interner.internObjectType(&members) catch return error.OutOfMemory;
            }
            const next_id = self.string_interner.intern("next") catch return error.OutOfMemory;
            const next_member_t = self.interner.objectMember(iterator_t, next_id) orelse types.Primitive.any;
            const members = [_]types.ObjectMember{
                .{ .name = next_id, .type = next_member_t, .is_optional = false, .is_readonly = false, .is_method = true },
                .{ .name = symbol_id, .type = iter_sig, .is_optional = false, .is_readonly = false, .is_method = true },
            };
            break :blk self.interner.internObjectType(&members) catch return error.OutOfMemory;
        };
        try self.generator_type_info.put(self.gpa, result_t, .{
            .yield_type = yield_t,
            .return_type = return_t,
            .next_type = next_t,
        });
        if (is_sync_iterator or is_async_iterator) {
            try self.registerAliasDisplayName(result_t, name_id, &.{ yield_t, return_t, next_t });
        } else {
            try self.registerAliasDisplayName(result_t, name_id, args);
        }
        return result_t;
    }

    /// True when `obj` is an identifier bound by an `import x = require(...)`
    /// declaration in the same virtual section. Used to scope the
    /// signature-receiver TS2339 to import-equals bindings (whose target
    /// module value has a fixed shape), leaving expando functions alone.
    fn memberAccessReceiverIsRequireAssignmentBinding(self: *Checker, obj: NodeId) bool {
        if (self.hir.kindOf(obj) != .identifier) return false;
        const name = hir_mod.identifierOf(self.hir, obj).name;
        const root = self.rootBlockFor(obj);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        const has_sections = self.sourceHasVirtualFilenameSections();
        const obj_section = if (has_sections) self.virtualSectionStartForNode(obj) else 0;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.hir.kindOf(stmt) != .import_decl) continue;
            if (has_sections and self.virtualSectionStartForNode(stmt) != obj_section) continue;
            if (!self.importDeclIsRequireAssignment(stmt)) continue;
            const imp = hir_mod.importOf(self.hir, stmt);
            if (imp.default_binding == hir_mod.none_node_id or self.hir.kindOf(imp.default_binding) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, imp.default_binding).name == name) return true;
        }
        return false;
    }

    fn moduleNamespaceTypeForImportBinding(self: *Checker, decl: NodeId) CheckError!?TypeId {
        if (self.hir.kindOf(decl) != .identifier) return null;
        const parent = self.hir.parentOf(decl);
        if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .import_decl) return null;
        const imp = hir_mod.importOf(self.hir, parent);
        const spec = self.string_interner.get(imp.module);
        if (imp.namespace_binding != decl and
            !(imp.default_binding == decl and std.mem.startsWith(u8, spec, ".") and self.importDeclIsRequireAssignment(parent))) return null;
        // For `import x = require("./m")` where `./m` uses `export =`,
        // type `x` as the export-assignment target (the expression value
        // such as `() => void`, else the named decl's static type) rather
        // than the synthesized module namespace. Mirrors tsc's typing of
        // `d2.default()` / `d2()` in `modulePreserve4`.
        if (self.importDeclIsRequireAssignment(parent)) {
            if (try self.virtualExportAssignmentExpressionType(parent, imp.module)) |expr_t| return expr_t;
            if (try self.virtualExportAssignmentTargetStaticType(parent, imp.module)) |static_t| return static_t;
        }
        return try self.moduleNamespaceTypeForSpecifier(imp.module, parent);
    }

    fn moduleNamespaceTypeForLocalImport(self: *Checker, name: hir_mod.StringId, anchor: NodeId) CheckError!?TypeId {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.hir.kindOf(stmt) != .import_decl) continue;
            const imp = hir_mod.importOf(self.hir, stmt);
            const binding = if (imp.namespace_binding != hir_mod.none_node_id)
                imp.namespace_binding
            else if (imp.default_binding != hir_mod.none_node_id and self.importDeclIsRequireAssignment(stmt))
                imp.default_binding
            else
                hir_mod.none_node_id;
            if (binding == hir_mod.none_node_id or self.hir.kindOf(binding) != .identifier) continue;
            const id = hir_mod.identifierOf(self.hir, binding);
            if (id.name != name) continue;
            if (self.importDeclIsRequireAssignment(stmt)) {
                if (try self.virtualExportAssignmentExpressionType(stmt, imp.module)) |expr_t| return expr_t;
                if (try self.virtualExportAssignmentTargetStaticType(stmt, imp.module)) |static_t| return static_t;
            }
            return try self.moduleNamespaceTypeForSpecifier(imp.module, stmt);
        }
        return null;
    }

    /// For a top-level CommonJS `exports.X = value`, `exports["X"] = value`,
    /// `module.exports.X = value`, or `module.exports["X"] = value` assignment, return the synthesized
    /// namespace member `X` typed as the assigned value's type. Returns
    /// null for any other assignment. Mirrors tsc's CommonJS module-shape
    /// inference (`modulePreserve4`'s `/g.js`).
    fn commonJsExportsAssignmentName(self: *Checker, node: NodeId) ?hir_mod.StringId {
        const asg = hir_mod.assignmentOf(self.hir, node);
        if (asg.op != null) return null;
        const prop_name = self.propertyAccessName(asg.target) orelse return null;
        const object = self.propertyAccessObject(asg.target) orelse return null;
        // The accessed object must be `exports` or `module.exports`.
        const obj_ok = switch (self.hir.kindOf(object)) {
            .identifier => std.mem.eql(u8, self.string_interner.get(hir_mod.identifierOf(self.hir, object).name), "exports"),
            .member_access, .element_access => self.nodeIsModuleExportsAccess(object),
            else => false,
        };
        if (!obj_ok) return null;
        return prop_name;
    }

    fn commonJsExportsAssignmentMember(self: *Checker, node: NodeId) CheckError!?types.ObjectMember {
        const member_name = self.commonJsExportsAssignmentName(node) orelse return null;
        const asg = hir_mod.assignmentOf(self.hir, node);
        const value_t = try self.checkExpression(asg.value);
        return types.ObjectMember{
            .name = member_name,
            .type = if (value_t != types.Primitive.none) value_t else types.Primitive.any,
            .is_optional = false,
            .is_readonly = false,
            .is_method = false,
        };
    }

    fn moduleNamespaceTypeForSpecifier(self: *Checker, specifier: hir_mod.StringId, anchor: NodeId) CheckError!?TypeId {
        if (!self.sourceHasVirtualFilenameSections()) return null;
        const spec = self.string_interner.get(specifier);
        const resolved = (try self.resolveVirtualModuleSpecifierPath(anchor, spec)) orelse return null;
        defer self.gpa.free(resolved);
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const stmts = hir_mod.blockStmts(self.hir, root);
        var reexport_alias_sections: std.AutoHashMapUnmanaged(usize, void) = .empty;
        defer reexport_alias_sections.deinit(self.gpa);
        for (stmts) |raw| {
            if (self.hir.kindOf(raw) != .assignment) continue;
            const assignment = hir_mod.assignmentOf(self.hir, raw);
            if (assignment.op != null or self.hir.kindOf(assignment.target) != .identifier) continue;
            const target = hir_mod.identifierOf(self.hir, assignment.target);
            if (!std.mem.eql(u8, self.string_interner.get(target.name), "exports")) continue;
            const alias_spec = self.requireCallSpecifier(assignment.value) orelse continue;
            const alias_resolved = (try self.resolveVirtualModuleSpecifierPath(raw, alias_spec)) orelse continue;
            defer self.gpa.free(alias_resolved);
            if (!std.mem.eql(u8, alias_resolved, resolved)) continue;
            try reexport_alias_sections.put(self.gpa, self.virtualSectionStartForNode(raw), {});
        }
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        var found_module = false;
        for (stmts) |raw| {
            const in_target_section = self.virtualSectionMatchesResolvedModule(raw, resolved, spec);
            const in_reexport_alias_section = reexport_alias_sections.contains(self.virtualSectionStartForNode(raw));
            if (!in_target_section and !in_reexport_alias_section) continue;
            if (in_target_section) found_module = true;
            // CommonJS `exports.X = value` / `module.exports.X = value`
            // contributes member `X` to the module's namespace shape.
            // tsc surfaces these as named members so a default import or
            // `import x = require(...)` binding can access `x.X`. Mirrors
            // `modulePreserve4`'s `/g.js` (`exports.default = 0`).
            if (self.hir.kindOf(raw) == .assignment) {
                const assignment = hir_mod.assignmentOf(self.hir, raw);
                if (in_reexport_alias_section and self.hir.kindOf(assignment.target) == .identifier and
                    self.requireCallSpecifier(assignment.value) != null)
                {
                    continue;
                }
                if (try self.commonJsExportsAssignmentMember(raw)) |member| {
                    try self.upsertObjectMember(&members, member);
                } else if (try self.commonJsNestedExportsAssignmentMember(raw)) |nested| {
                    try self.upsertNestedCommonJsExportMember(&members, nested);
                }
                continue;
            }
            if (try self.commonJsDefinePropertyExportMember(raw)) |defined| {
                try self.upsertObjectMember(&members, defined.member);
                continue;
            }
            if (try self.commonJsDefinePropertyNestedExportMember(raw)) |nested| {
                try self.upsertNestedCommonJsExportMember(&members, nested.member);
                continue;
            }
            if (self.hir.kindOf(raw) != .export_decl) continue;
            const ex = hir_mod.exportOf(self.hir, raw);
            if (ex.is_default) {
                const default_name = self.string_interner.intern("default") catch return error.OutOfMemory;
                const default_t = if (ex.decl != hir_mod.none_node_id and self.hir.typeOf(ex.decl) != types.Primitive.none)
                    self.hir.typeOf(ex.decl)
                else
                    types.Primitive.any;
                try members.append(self.gpa, .{
                    .name = default_name,
                    .type = default_t,
                    .is_optional = false,
                    .is_readonly = true,
                    .is_method = false,
                });
                continue;
            }
            // `export * as ns from "m"` — re-export the foreign module's
            // namespace under the local alias `ns`. Surface `ns` as a member
            // so `import * as foo from "./this"; foo.ns.x` resolves rather
            // than emitting TS2339. The member's type is the foreign module's
            // namespace shape (recursively resolved); falls back to `any`
            // when the foreign module isn't in this compilation. Pins
            // exportAsNamespace{1,2}.
            if (ex.is_namespace and
                ex.namespace_alias != string_interner.empty_string_id and
                !ex.is_type_only)
            {
                const member_t = (try self.moduleNamespaceTypeForSpecifier(ex.module, raw)) orelse types.Primitive.any;
                try members.append(self.gpa, .{
                    .name = ex.namespace_alias,
                    .type = member_t,
                    .is_optional = false,
                    .is_readonly = true,
                    .is_method = false,
                });
                continue;
            }
            if (ex.decl == hir_mod.none_node_id and ex.named_len > 0 and !ex.is_type_only) {
                const is_local_named_export = self.string_interner.get(ex.module).len == 0;
                for (hir_mod.exportNamed(self.hir, raw)) |spec_node| {
                    if (self.hir.kindOf(spec_node) != .import_specifier) continue;
                    const sp = hir_mod.importSpecifierOf(self.hir, spec_node);
                    if (sp.is_type_only) continue;
                    const member_t = (try self.localValueTypeInVirtualSection(raw, sp.imported)) orelse blk: {
                        if (is_local_named_export) continue;
                        break :blk types.Primitive.any;
                    };
                    const exported_name = self.exportSpecifierExportedName(spec_node, sp);
                    try members.append(self.gpa, .{
                        .name = exported_name,
                        .type = member_t,
                        .is_optional = false,
                        .is_readonly = true,
                        .is_method = false,
                    });
                }
                continue;
            }
            const decl = self.unwrapExportDecl(raw);
            if (!self.namespaceExportCreatesValue(decl)) continue;
            const name = self.declarationName(decl) orelse continue;
            const member_t = try self.exportedValueTypeForNamespaceMember(decl, name);
            if (member_t == types.Primitive.none) continue;
            try members.append(self.gpa, .{
                .name = name,
                .type = member_t,
                .is_optional = false,
                .is_readonly = true,
                .is_method = false,
            });
        }
        if (!found_module) return null;
        const namespace_t = self.interner.internObjectType(members.items) catch return error.OutOfMemory;
        try self.registerModuleNamespaceDisplayName(namespace_t, resolved);
        return namespace_t;
    }

    const CommonJsNestedExportMember = struct {
        export_name: hir_mod.StringId,
        member: types.ObjectMember,
    };

    const CommonJsDefinePropertyExportMember = struct {
        member: types.ObjectMember,
        is_module_write: bool,
    };

    const CommonJsDefinePropertyNestedExportMember = struct {
        member: CommonJsNestedExportMember,
        is_module_write: bool,
    };

    const CommonJsDefinePropertyCall = struct {
        target: NodeId,
        name: hir_mod.StringId,
        value: NodeId,
    };

    fn commonJsDefinePropertyExportMember(self: *Checker, node: NodeId) CheckError!?CommonJsDefinePropertyExportMember {
        const call = (try self.commonJsDefinePropertyCall(node)) orelse return null;
        if (!self.nodeIsCommonJsExportsObject(call.target)) return null;
        const value_t = try self.commonJsDefinePropertyValueType(call.value);
        return .{
            .member = .{
                .name = call.name,
                .type = value_t,
                .is_optional = false,
                .is_readonly = false,
                .is_method = false,
            },
            .is_module_write = self.nodeIsModuleExportsAccess(call.target),
        };
    }

    fn commonJsDefinePropertyNestedExportMember(self: *Checker, node: NodeId) CheckError!?CommonJsDefinePropertyNestedExportMember {
        const call = (try self.commonJsDefinePropertyCall(node)) orelse return null;
        const export_name = self.commonJsExportsObjectPropertyName(call.target) orelse return null;
        const value_t = try self.commonJsDefinePropertyValueType(call.value);
        const object = self.propertyAccessObject(call.target) orelse hir_mod.none_node_id;
        return .{
            .member = .{
                .export_name = export_name,
                .member = .{
                    .name = call.name,
                    .type = value_t,
                    .is_optional = false,
                    .is_readonly = false,
                    .is_method = false,
                },
            },
            .is_module_write = self.nodeIsModuleExportsAccess(object),
        };
    }

    fn commonJsDefinePropertyCall(self: *Checker, node: NodeId) CheckError!?CommonJsDefinePropertyCall {
        if (self.hir.kindOf(node) != .call_expr) return null;
        const c = hir_mod.callOf(self.hir, node);
        if (!self.calleeIsObjectDefineProperty(c.callee)) return null;
        const args = hir_mod.callArgs(self.hir, node);
        if (args.len < 3) return null;
        if (self.hir.kindOf(args[1]) != .literal_string) return null;
        const value = self.objectLiteralValueProperty(args[2]) orelse return null;
        return .{
            .target = args[0],
            .name = hir_mod.literalStringOf(self.hir, args[1]).value,
            .value = value,
        };
    }

    fn calleeIsObjectDefineProperty(self: *Checker, node: NodeId) bool {
        const name = self.propertyAccessName(node) orelse return false;
        if (!std.mem.eql(u8, self.string_interner.get(name), "defineProperty")) return false;
        const object = self.propertyAccessObject(node) orelse return false;
        if (self.hir.kindOf(object) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, object);
        return std.mem.eql(u8, self.string_interner.get(id.name), "Object");
    }

    fn objectLiteralValueProperty(self: *Checker, node: NodeId) ?NodeId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .object_literal) return null;
        const value_name = self.string_interner.intern("value") catch return null;
        for (hir_mod.objectLiteralProps(self.hir, node)) |prop_node| {
            if (self.hir.kindOf(prop_node) != .object_property) continue;
            const op = hir_mod.objectPropertyOf(self.hir, prop_node);
            if (op.value == hir_mod.none_node_id) continue;
            const key_name = if (op.is_computed)
                self.propertyNameFromComputedBindingKeyNode(op.key) catch null
            else
                self.propertyNameFromKeyNode(op.key);
            if (key_name == value_name) return op.value;
        }
        return null;
    }

    fn commonJsDefinePropertyValueType(self: *Checker, value: NodeId) CheckError!TypeId {
        if (self.commonJsExportReferenceName(value) != null) return types.Primitive.any;
        return try self.commonJsExportAssignmentValueType(value);
    }

    fn recordCommonJsDefinePropertyExportNarrow(self: *Checker, node: NodeId) CheckError!void {
        if (!self.sourceHasCheckJsDirective()) return;
        const call = (try self.commonJsDefinePropertyCall(node)) orelse return;
        const key = (try self.commonJsDefinePropertyExportKey(call.target, call.name)) orelse return;
        const value_t = try self.commonJsDefinePropertyValueType(call.value);
        if (value_t == types.Primitive.none or value_t == types.Primitive.unknown) return;
        try self.recordCommonJsExportNarrow(key, value_t);
    }

    fn commonJsDefinePropertyExportKey(self: *Checker, target: NodeId, prop_name: hir_mod.StringId) CheckError!?MemberKey {
        if (target == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(target) == .identifier) {
            const id = hir_mod.identifierOf(self.hir, target);
            if (std.mem.eql(u8, self.string_interner.get(id.name), "exports")) {
                return .{ .obj_name = id.name, .prop_name = prop_name };
            }
            return null;
        }
        if (self.nodeIsModuleExportsAccess(target)) {
            const module_exports = self.string_interner.intern("module.exports") catch return error.OutOfMemory;
            return .{ .obj_name = module_exports, .prop_name = prop_name };
        }
        return null;
    }

    fn commonJsExportReferenceName(self: *Checker, node: NodeId) ?hir_mod.StringId {
        const prop_name = self.propertyAccessName(node) orelse return null;
        const object = self.propertyAccessObject(node) orelse return null;
        if (!self.nodeIsCommonJsExportsObject(object)) return null;
        return prop_name;
    }

    fn commonJsNestedExportsAssignmentMember(self: *Checker, node: NodeId) CheckError!?CommonJsNestedExportMember {
        const asg = hir_mod.assignmentOf(self.hir, node);
        if (asg.op != null) return null;
        const member_name = self.propertyAccessName(asg.target) orelse return null;
        const exported_object = self.propertyAccessObject(asg.target) orelse return null;
        const export_name = self.commonJsExportsObjectPropertyName(exported_object) orelse return null;
        const value_t = try self.checkExpression(asg.value);
        return .{
            .export_name = export_name,
            .member = .{
                .name = member_name,
                .type = if (value_t != types.Primitive.none) value_t else types.Primitive.any,
                .is_optional = false,
                .is_readonly = false,
                .is_method = false,
            },
        };
    }

    fn commonJsExportsObjectPropertyName(self: *Checker, node: NodeId) ?hir_mod.StringId {
        const prop_name = self.propertyAccessName(node) orelse return null;
        const object = self.propertyAccessObject(node) orelse return null;
        return switch (self.hir.kindOf(object)) {
            .identifier => blk: {
                const id = hir_mod.identifierOf(self.hir, object);
                if (!std.mem.eql(u8, self.string_interner.get(id.name), "exports")) break :blk null;
                break :blk prop_name;
            },
            .member_access, .element_access => if (self.nodeIsModuleExportsAccess(object)) prop_name else null,
            else => null,
        };
    }

    fn upsertNestedCommonJsExportMember(
        self: *Checker,
        members: *std.ArrayListUnmanaged(types.ObjectMember),
        nested: CommonJsNestedExportMember,
    ) CheckError!void {
        var object_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer object_members.deinit(self.gpa);
        for (members.items) |existing| {
            if (existing.name != nested.export_name) continue;
            if (existing.type >= types.Primitive.first_dynamic and existing.type < self.interner.pool.typeCount()) {
                const flags = self.interner.pool.flagsOf(existing.type);
                if (flags.is_object_type) {
                    try object_members.appendSlice(self.gpa, self.interner.objectMembers(existing.type));
                }
            }
            break;
        }
        try self.upsertObjectMember(&object_members, nested.member);
        const object_t = self.interner.internObjectType(object_members.items) catch return error.OutOfMemory;
        try self.upsertObjectMember(members, .{
            .name = nested.export_name,
            .type = object_t,
            .is_optional = false,
            .is_readonly = false,
            .is_method = false,
        });
    }

    fn resolveVirtualModuleSpecifierPath(self: *Checker, anchor: NodeId, spec: []const u8) CheckError!?[]u8 {
        if (!self.sourceHasVirtualFilenameSections()) return null;
        if (std.mem.startsWith(u8, spec, ".")) return try self.resolveVirtualRelativePath(self.virtualSectionFilenameForNode(anchor) orelse return null, spec);
        if (!self.classicBareSiblingResolutionEnabled()) return null;
        if (std.mem.indexOfScalar(u8, spec, '/') != null) return null;
        const from = self.virtualSectionFilenameForNode(anchor) orelse return null;
        var from_path = from;
        while (std.mem.startsWith(u8, from_path, "/")) from_path = from_path[1..];
        const dir = if (std.mem.lastIndexOfScalar(u8, from_path, '/')) |slash| from_path[0..slash] else "";
        const joined = if (dir.len > 0)
            try std.fmt.allocPrint(self.gpa, "{s}/{s}", .{ dir, spec })
        else
            try self.gpa.dupe(u8, spec);
        defer self.gpa.free(joined);
        return try self.normalizeVirtualPath(joined);
    }

    fn registerModuleNamespaceDisplayName(self: *Checker, t: TypeId, resolved: []const u8) CheckError!void {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return;
        if (self.alias_display_names.contains(t)) return;
        const display = if (std.mem.startsWith(u8, resolved, "/") or !self.virtualSourceHasRootedFilenameForResolved(resolved))
            try std.fmt.allocPrint(self.diag_arena.allocator(), "typeof import(\"{s}\")", .{resolved})
        else
            try std.fmt.allocPrint(self.diag_arena.allocator(), "typeof import(\"/{s}\")", .{resolved});
        try self.alias_display_names.put(self.gpa, t, display);
    }

    fn virtualSourceHasRootedFilenameForResolved(self: *Checker, resolved: []const u8) bool {
        const src = self.source orelse return false;
        const wanted = virtualPathTrimPrefix(resolved);
        var lines = std.mem.splitScalar(u8, src, '\n');
        while (lines.next()) |raw| {
            const line = std.mem.trim(u8, raw, " \t\r");
            const marker = std.mem.indexOf(u8, line, "@filename:") orelse
                (std.mem.indexOf(u8, line, "@Filename:") orelse continue);
            const path = std.mem.trim(u8, line[marker + "@filename:".len ..], " \t\r");
            if (!std.mem.startsWith(u8, path, "/")) continue;
            const clean = virtualPathTrimPrefix(path);
            if (virtualPathMatchesResolvedDisplay(clean, wanted)) return true;
        }
        return false;
    }

    fn virtualPathMatchesResolvedDisplay(path: []const u8, resolved: []const u8) bool {
        if (std.mem.eql(u8, path, resolved)) return true;
        const exts = [_][]const u8{ ".d.ts", ".ts", ".tsx", ".mts", ".cts", ".js", ".jsx", ".mjs", ".cjs" };
        for (exts) |ext| {
            if (path.len == resolved.len + ext.len and
                std.mem.eql(u8, path[0..resolved.len], resolved) and
                std.mem.eql(u8, path[resolved.len..], ext)) return true;
            const infix = "/index";
            if (path.len == resolved.len + infix.len + ext.len and
                std.mem.eql(u8, path[0..resolved.len], resolved) and
                std.mem.eql(u8, path[resolved.len .. resolved.len + infix.len], infix) and
                std.mem.eql(u8, path[resolved.len + infix.len ..], ext)) return true;
        }
        return false;
    }

    fn registerEnumNamespaceDisplayName(self: *Checker, t: TypeId, enum_name: hir_mod.StringId) CheckError!void {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return;
        if (self.alias_display_names.contains(t)) return;
        const display = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "typeof {s}",
            .{self.string_interner.get(enum_name)},
        );
        try self.alias_display_names.put(self.gpa, t, display);
    }

    fn localValueTypeInVirtualSection(self: *Checker, anchor: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const section = self.virtualSectionStartForNode(anchor);
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.virtualSectionStartForNode(stmt) != section) continue;
            const decl = self.unwrapExportDecl(stmt);
            const decl_name = self.declarationName(decl) orelse continue;
            if (decl_name != name) continue;
            if (!self.namespaceExportCreatesValue(decl)) continue;
            return try self.exportedValueTypeForNamespaceMember(decl, name);
        }
        return null;
    }

    fn exportSpecifierExportedName(self: *Checker, spec_node: NodeId, sp: hir_mod.ImportSpecifierPayload) hir_mod.StringId {
        _ = self;
        _ = spec_node;
        return sp.local;
    }

    fn exportedValueTypeForNamespaceMember(self: *Checker, decl: NodeId, name: hir_mod.StringId) CheckError!TypeId {
        if (self.hir.kindOf(decl) == .class_decl or self.hir.kindOf(decl) == .class_expr) {
            if (self.class_static_type_by_node.get(decl)) |static_t| return static_t;
            if (self.class_static_types.get(name)) |static_t| return static_t;
            try self.checkClassDecl(decl);
            if (self.class_static_type_by_node.get(decl)) |static_t| return static_t;
            if (self.class_static_types.get(name)) |static_t| return static_t;
        }
        if (self.hir.kindOf(decl) == .enum_decl) {
            return try self.enumNamespaceValueType(decl, name);
        }
        if (try self.exportedVariableValueType(decl, name)) |var_t| return var_t;
        const t = self.hir.typeOf(decl);
        return if (t != types.Primitive.none) t else types.Primitive.any;
    }

    fn exportedVariableValueType(self: *Checker, decl: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        const dk = self.hir.kindOf(decl);
        if (dk != .var_decl and dk != .let_decl and dk != .const_decl) return null;
        const existing = self.hir.typeOf(decl);
        if (existing != types.Primitive.none and existing != types.Primitive.unknown) return existing;
        const v = hir_mod.varDeclOf(self.hir, decl);
        if (v.type_annotation != hir_mod.none_node_id) {
            const declared_t = try self.lowerValueTypeAnnotation(name, v.type_annotation);
            self.hir.setType(decl, declared_t);
            if (v.name != hir_mod.none_node_id) self.hir.setType(v.name, declared_t);
            return declared_t;
        }
        if (try self.jsDocTypeForVarDecl(decl)) |jsdoc_t| {
            self.hir.setType(decl, jsdoc_t);
            if (v.name != hir_mod.none_node_id) self.hir.setType(v.name, jsdoc_t);
            return jsdoc_t;
        }
        if (v.init != hir_mod.none_node_id) {
            var init_t = if (self.hir.typeOf(v.init) != types.Primitive.none)
                self.hir.typeOf(v.init)
            else
                try self.checkExpression(v.init);
            if (dk == .const_decl) {
                init_t = try self.constInitializerType(v.init, init_t);
            } else if (self.mutableInitializerShouldWidenLiteral(v.init, init_t)) {
                init_t = try self.widenFreshLiteralType(init_t);
            }
            self.hir.setType(decl, init_t);
            if (v.name != hir_mod.none_node_id) self.hir.setType(v.name, init_t);
            return init_t;
        }
        self.hir.setType(decl, types.Primitive.any);
        if (v.name != hir_mod.none_node_id) self.hir.setType(v.name, types.Primitive.any);
        return types.Primitive.any;
    }

    /// Append each member of `decl` (an `enum_decl`) onto `members`,
    /// deduplicating by name. Used by `enumNamespaceValueType` to merge
    /// member sets across multiple enum declarations sharing the same
    /// name in the same scope.
    fn appendEnumMembersFromDecl(
        self: *Checker,
        members: *std.ArrayListUnmanaged(types.ObjectMember),
        decl: NodeId,
        enum_name: hir_mod.StringId,
        enum_t: TypeId,
    ) CheckError!void {
        for (hir_mod.enumMembers(self.hir, decl)) |member| {
            if (self.hir.kindOf(member) != .object_property) continue;
            const prop = hir_mod.objectPropertyOf(self.hir, member);
            const member_name: ?hir_mod.StringId = switch (self.hir.kindOf(prop.key)) {
                .identifier => hir_mod.identifierOf(self.hir, prop.key).name,
                .literal_string => hir_mod.literalStringOf(self.hir, prop.key).value,
                else => null,
            };
            if (member_name == null) continue;
            if (objectMemberListHasName(members.items, member_name.?)) continue;
            const member_t = (try self.enumMemberAccessType(enum_name, member_name.?, decl)) orelse enum_t;
            try members.append(self.gpa, .{
                .name = member_name.?,
                .type = member_t,
                .is_optional = false,
                .is_readonly = true,
                .is_method = false,
            });
        }
    }

    fn enumNamespaceValueType(self: *Checker, decl: NodeId, enum_name: hir_mod.StringId) CheckError!TypeId {
        if (self.hir.typeOf(decl) == types.Primitive.none) {
            try self.checkEnumDecl(decl);
        }
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        const enum_t = try self.enumNominalTypeForDecl(decl, enum_name);
        // Collect members from this declaration AND any sibling enum
        // declarations of the same name in the same parent block —
        // enums merge across declarations, so `enum E { A } enum E { B }`
        // exposes both A and B on `typeof E`. Mirrors tsc's symbol-merge
        // behavior for enum exports.
        try self.appendEnumMembersFromDecl(&members, decl, enum_name, enum_t);
        if (self.enumSiblingScope(decl)) |scope| {
            for (scope.stmts) |sib_raw| {
                const sib = self.unwrapExportDecl(sib_raw);
                if (sib == decl) continue;
                if (self.hir.kindOf(sib) != .enum_decl) continue;
                const sib_enum = hir_mod.enumOf(self.hir, sib);
                if (self.hir.kindOf(sib_enum.name) != .identifier) continue;
                if (hir_mod.identifierOf(self.hir, sib_enum.name).name != enum_name) continue;
                try self.appendEnumMembersFromDecl(&members, sib, enum_name, enum_t);
            }
        }
        const root = self.rootBlockFor(decl);
        if (root != hir_mod.none_node_id and self.hir.kindOf(root) == .block_stmt) {
            const one = [_]hir_mod.StringId{enum_name};
            if (self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), &one)) |ns_node| {
                const ambient_namespace = self.namespaceDeclIsAmbient(ns_node) or self.namespaceNameHasDeclarePrefix(hir_mod.namespaceOf(self.hir, ns_node).name);
                for (hir_mod.namespaceBody(self.hir, ns_node)) |raw| {
                    const ns_decl = if (self.hir.kindOf(raw) == .export_decl)
                        self.unwrapExportDecl(raw)
                    else if (ambient_namespace)
                        raw
                    else
                        continue;
                    if (!self.namespaceExportCreatesValue(ns_decl)) continue;
                    const name = self.declarationName(ns_decl) orelse continue;
                    if (objectMemberListHasName(members.items, name)) continue;
                    const member_t = switch (self.hir.kindOf(ns_decl)) {
                        .var_decl, .let_decl, .const_decl => blk: {
                            try self.checkNamespaceValueDecl(ns_decl);
                            const mt = self.hir.typeOf(ns_decl);
                            break :blk if (mt != types.Primitive.none) mt else types.Primitive.any;
                        },
                        .fn_decl, .fn_expr, .arrow_fn => blk: {
                            try self.checkFnSignatureOnlyNoBody(ns_decl);
                            const mt = self.hir.typeOf(ns_decl);
                            break :blk if (mt != types.Primitive.none) mt else types.Primitive.any;
                        },
                        .class_decl, .class_expr => blk: {
                            try self.checkStatement(ns_decl);
                            if (self.class_static_types.get(name)) |static_t| break :blk static_t;
                            const mt = self.hir.typeOf(ns_decl);
                            break :blk if (mt != types.Primitive.none) mt else types.Primitive.any;
                        },
                        .enum_decl => try self.enumNamespaceValueType(ns_decl, name),
                        .namespace_decl => try self.namespaceValueObjectType(ns_decl),
                        else => types.Primitive.any,
                    };
                    try members.append(self.gpa, .{
                        .name = name,
                        .type = member_t,
                        .is_optional = false,
                        .is_readonly = false,
                        .is_method = self.hir.kindOf(ns_decl) == .fn_decl or self.hir.kindOf(ns_decl) == .fn_expr,
                    });
                }
            }
        }
        const t = self.interner.internObjectType(members.items) catch return error.OutOfMemory;
        try self.registerEnumNamespaceDisplayName(t, enum_name);
        return t;
    }

    fn objectMemberListHasName(members: []const types.ObjectMember, name: hir_mod.StringId) bool {
        for (members) |member| {
            if (member.name == name) return true;
        }
        return false;
    }

    fn virtualSectionMatchesSpecifier(self: *Checker, src: []const u8, node: NodeId, spec: []const u8) bool {
        const section = self.virtualSectionStartForNode(node);
        if (section >= src.len) return false;
        const line_end = std.mem.indexOfScalarPos(u8, src, section, '\n') orelse src.len;
        const line = src[section..line_end];
        const marker = std.mem.indexOf(u8, line, "@filename:") orelse
            (std.mem.indexOf(u8, line, "@Filename:") orelse return false);
        const filename = std.mem.trim(u8, line[marker + "@filename:".len ..], " \t\r");
        return self.moduleSpecifierMatchesFilename(spec, filename);
    }

    fn moduleSpecifierMatchesFilename(self: *Checker, spec: []const u8, filename: []const u8) bool {
        _ = self;
        var spec_tail = spec;
        while (std.mem.startsWith(u8, spec_tail, "./")) spec_tail = spec_tail[2..];
        while (std.mem.startsWith(u8, spec_tail, "../")) spec_tail = spec_tail[3..];
        if (std.mem.lastIndexOfScalar(u8, spec_tail, '/')) |idx| spec_tail = spec_tail[idx + 1 ..];
        var file_tail = filename;
        if (std.mem.lastIndexOfScalar(u8, file_tail, '/')) |idx| file_tail = file_tail[idx + 1 ..];
        return std.mem.eql(u8, spec_tail, file_tail) or
            (std.mem.endsWith(u8, file_tail, ".d.ts") and std.mem.eql(u8, spec_tail, file_tail[0 .. file_tail.len - ".d.ts".len])) or
            (std.mem.endsWith(u8, file_tail, ".d.mts") and std.mem.eql(u8, spec_tail, file_tail[0 .. file_tail.len - ".d.mts".len])) or
            (std.mem.endsWith(u8, file_tail, ".d.cts") and std.mem.eql(u8, spec_tail, file_tail[0 .. file_tail.len - ".d.cts".len])) or
            (std.mem.endsWith(u8, file_tail, ".ts") and std.mem.eql(u8, spec_tail, file_tail[0 .. file_tail.len - ".ts".len])) or
            (std.mem.endsWith(u8, file_tail, ".tsx") and std.mem.eql(u8, spec_tail, file_tail[0 .. file_tail.len - ".tsx".len])) or
            (std.mem.endsWith(u8, file_tail, ".js") and std.mem.eql(u8, spec_tail, file_tail[0 .. file_tail.len - ".js".len])) or
            (std.mem.endsWith(u8, file_tail, ".jsx") and std.mem.eql(u8, spec_tail, file_tail[0 .. file_tail.len - ".jsx".len])) or
            (std.mem.endsWith(u8, file_tail, ".cjs") and std.mem.eql(u8, spec_tail, file_tail[0 .. file_tail.len - ".cjs".len])) or
            (std.mem.endsWith(u8, file_tail, ".mjs") and std.mem.eql(u8, spec_tail, file_tail[0 .. file_tail.len - ".mjs".len]));
    }

    /// Re-intern the function's signature with `new_ret` as the
    /// return type, then update the node's type. Identifier lookups
    /// against the function's name see the refined signature.
    fn refineSignatureReturn(self: *Checker, fn_node: NodeId, new_ret: TypeId) CheckError!void {
        const sig = self.hir.typeOf(fn_node);
        if (!self.interner.pool.flagsOf(sig).is_signature) return;
        const params = self.interner.signatureParams(sig);
        // Skip if the inferred type is the same as what we already
        // had (avoids re-interning a no-op).
        if (self.interner.signatureReturn(sig)) |old| if (old == new_ret) return;
        const this_t_opt = self.signatureThisParam(sig);
        const new_sig = if (this_t_opt) |this_t|
            self.interner.internSignatureWithThisType(params, new_ret, false, false, this_t) catch return error.OutOfMemory
        else
            self.interner.internSignature(params, new_ret, false) catch return error.OutOfMemory;
        // Carry the rest-parameter marker forward ÃÂ¢ÃÂÃÂ re-interning with
        // a refined return type produces a fresh TypeId, but the
        // parameter list (incl. rest-ness) is unchanged.
        if (self.rest_signatures.contains(sig)) {
            try self.rest_signatures.put(self.gpa, new_sig, {});
        }
        if (self.signature_min_args.get(sig)) |min_required| {
            try self.signature_min_args.put(self.gpa, new_sig, min_required);
        }
        try self.copySignatureNullishArrayDefaults(new_sig, sig);
        const recorded_node_params = try self.recordFunctionNodeGenericSignatureParams(new_sig, fn_node);
        if (!recorded_node_params) if (self.generic_signature_params.get(sig)) |type_params| {
            try self.recordGenericSignatureParams(new_sig, type_params);
        };
        if (this_t_opt) |this_t| {
            try self.signature_this_params.put(self.gpa, new_sig, this_t);
        }
        try self.copySignatureParamNames(new_sig, sig);
        self.hir.setType(fn_node, new_sig);
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.name != hir_mod.none_node_id) self.hir.setType(f.name, new_sig);
    }

    fn contextualTargetTypeForFunction(self: *Checker, fn_node: NodeId) ?TypeId {
        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id) return null;
        var target_t: TypeId = types.Primitive.none;
        switch (self.hir.kindOf(parent)) {
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, parent);
                if (b.op != .comma or b.rhs != fn_node) return null;
                return self.contextualTargetTypeForExpression(parent);
            },
            .array_literal => return self.contextualArrayLiteralFunctionElementTarget(fn_node, parent) catch null,
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, parent);
                if (v.init != fn_node) return null;
                target_t = self.hir.typeOf(parent);
            },
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, parent);
                if (a.value != fn_node or a.target == hir_mod.none_node_id) return null;
                target_t = if (self.hir.kindOf(a.target) == .identifier)
                    self.typeOfIdentifierDeclared(a.target)
                else
                    self.hir.typeOf(a.target);
                if ((target_t == types.Primitive.none or target_t == types.Primitive.any or target_t == types.Primitive.unknown) and
                    self.hir.kindOf(a.target) == .member_access)
                {
                    const target_member = hir_mod.memberOf(self.hir, a.target);
                    if (self.moduleInterfaceAugmentationPrototypeMember(target_member.object, target_member.name, fn_node) catch null) |augmented_t| {
                        target_t = augmented_t;
                    }
                }
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, parent);
                const args = hir_mod.callArgs(self.hir, parent);
                var arg_index: ?usize = null;
                for (args, 0..) |arg, i| {
                    if (arg == fn_node) {
                        arg_index = i;
                        break;
                    }
                }
                const idx = arg_index orelse return null;
                const callee_t = self.hir.typeOf(c.callee);
                if (callee_t == types.Primitive.none or callee_t >= self.interner.pool.typeCount()) return null;
                const sig = self.firstSignatureType(callee_t) orelse return null;
                const params = self.interner.signatureParams(sig);
                if (self.rest_signatures.contains(sig) and params.len > 0) {
                    const fixed_count = params.len - 1;
                    if (idx >= fixed_count) {
                        if (self.restTupleAnnotationForSignature(sig)) |tuple_node| {
                            return self.tupleAnnotationElementTypeAt(tuple_node, idx - fixed_count, args.len - fixed_count) catch null;
                        }
                    }
                }
                if (idx >= params.len) return null;
                target_t = params[idx];
            },
            else => return null,
        }
        return target_t;
    }

    fn contextualTargetTypeForExpression(self: *Checker, expr_node: NodeId) ?TypeId {
        const parent = self.hir.parentOf(expr_node);
        if (parent == hir_mod.none_node_id) return null;
        switch (self.hir.kindOf(parent)) {
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, parent);
                if (v.init != expr_node) return null;
                return self.hir.typeOf(parent);
            },
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, parent);
                if (a.value != expr_node or a.target == hir_mod.none_node_id) return null;
                return if (self.hir.kindOf(a.target) == .identifier)
                    self.typeOfIdentifierDeclared(a.target)
                else
                    self.hir.typeOf(a.target);
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, parent);
                if (b.op != .comma or b.rhs != expr_node) return null;
                return self.contextualTargetTypeForExpression(parent);
            },
            else => return null,
        }
    }

    fn contextualFunctionSignatureWithInferredReturn(
        self: *Checker,
        fn_node: NodeId,
        target_sig: TypeId,
    ) CheckError!TypeId {
        const source_t = self.hir.typeOf(fn_node);
        if (!self.interner.isSignature(target_sig)) return source_t;
        if (source_t != types.Primitive.none and !self.interner.isSignature(source_t)) return source_t;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        const contextual_predicate = self.signature_predicates.get(target_sig);
        const source_ret = if (contextual_predicate != null)
            self.interner.signatureReturn(target_sig) orelse types.Primitive.boolean_t
        else if (f.body != hir_mod.none_node_id and self.hir.kindOf(f.body) == .block_stmt) blk: {
            var ret_types: std.ArrayListUnmanaged(TypeId) = .empty;
            defer ret_types.deinit(self.gpa);
            try self.collectReturnTypes(f.body, &ret_types);
            break :blk if (ret_types.items.len == 0)
                types.Primitive.void_t
            else if (ret_types.items.len == 1)
                ret_types.items[0]
            else
                self.interner.internUnion(ret_types.items) catch return error.OutOfMemory;
        } else if (f.body != hir_mod.none_node_id) blk: {
            const body_t = self.hir.typeOf(f.body);
            break :blk if (body_t != types.Primitive.none) body_t else try self.checkExpression(f.body);
        } else if (source_t != types.Primitive.none)
            self.interner.signatureReturn(source_t) orelse types.Primitive.any
        else
            types.Primitive.any;
        const target_params = self.interner.signatureParams(target_sig);
        const sig = self.interner.internSignature(target_params, source_ret, false) catch return error.OutOfMemory;
        if (self.rest_signatures.contains(target_sig)) try self.rest_signatures.put(self.gpa, sig, {});
        if (self.signature_min_args.get(target_sig)) |min_args| try self.signature_min_args.put(self.gpa, sig, min_args);
        if (contextual_predicate) |predicate| {
            try self.signature_predicates.put(self.gpa, sig, predicate);
        }
        if (source_t != types.Primitive.none) {
            try self.copySignatureParamNames(sig, source_t);
        } else {
            try self.recordSignatureParamNames(sig, hir_mod.fnParams(self.hir, fn_node));
        }
        self.hir.setType(fn_node, sig);
        if (f.name != hir_mod.none_node_id) self.hir.setType(f.name, sig);
        return sig;
    }

    fn restTupleAnnotationForSignature(self: *Checker, sig: TypeId) ?NodeId {
        const param_nodes = self.signature_param_nodes.get(sig) orelse return null;
        if (param_nodes.len == 0) return null;
        const param_node = param_nodes[param_nodes.len - 1];
        if (self.hir.kindOf(param_node) != .parameter) return null;
        const param = hir_mod.parameterOf(self.hir, param_node);
        if (!param.flags.is_rest or param.type_annotation == hir_mod.none_node_id) return null;
        return self.tupleAnnotationSourceNode(param.type_annotation);
    }

    fn restTupleAnnotationReferencesSignatureTypeParams(self: *Checker, sig: TypeId, tuple_node: NodeId) bool {
        const param_nodes = self.signature_param_nodes.get(sig) orelse return false;
        if (param_nodes.len == 0) return false;
        const param_node = param_nodes[param_nodes.len - 1];
        var cur = self.hir.parentOf(param_node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .fn_decl, .fn_expr, .arrow_fn => {
                    const f = hir_mod.fnDeclOf(self.hir, cur);
                    if (f.type_params_len == 0) continue;
                    const type_params = self.hir.childSlice(f.type_params_start, f.type_params_len);
                    return self.typeNodeReferencesTypeParams(tuple_node, type_params);
                },
                .fn_type => {
                    const f = hir_mod.fnTypeOf(self.hir, cur);
                    if (f.type_params_len == 0) continue;
                    const type_params = self.hir.childSlice(f.type_params_start, f.type_params_len);
                    return self.typeNodeReferencesTypeParams(tuple_node, type_params);
                },
                .block_stmt, .source_file => return false,
                else => {},
            }
        }
        return false;
    }

    fn contextualArrayLiteralFunctionElementTarget(
        self: *Checker,
        fn_node: NodeId,
        array_node: NodeId,
    ) CheckError!?TypeId {
        if (array_node == hir_mod.none_node_id or self.hir.kindOf(array_node) != .array_literal) return null;
        var element_index: ?usize = null;
        const elements = hir_mod.arrayLiteralElements(self.hir, array_node);
        for (elements, 0..) |element, i| {
            if (element == fn_node) {
                element_index = i;
                break;
            }
        }
        const idx = element_index orelse return null;
        const parent = self.hir.parentOf(array_node);
        if (parent == hir_mod.none_node_id) return null;
        switch (self.hir.kindOf(parent)) {
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, parent);
                if (v.init != array_node or v.type_annotation == hir_mod.none_node_id) return null;
                const tuple_node = self.tupleAnnotationSourceNode(v.type_annotation) orelse return null;
                return try self.tupleAnnotationElementTypeAt(tuple_node, idx, elements.len);
            },
            else => return null,
        }
    }

    fn contextualTupleElementTargetForFunction(self: *Checker, fn_node: NodeId) CheckError!?TypeId {
        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id) return null;
        switch (self.hir.kindOf(parent)) {
            .array_literal => return try self.contextualArrayLiteralFunctionElementTarget(fn_node, parent),
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, parent);
                const args = hir_mod.callArgs(self.hir, parent);
                var arg_index: ?usize = null;
                for (args, 0..) |arg, i| {
                    if (arg == fn_node) {
                        arg_index = i;
                        break;
                    }
                }
                const idx = arg_index orelse return null;
                const callee_t = self.hir.typeOf(c.callee);
                if (callee_t == types.Primitive.none or callee_t >= self.interner.pool.typeCount()) return null;
                const sig = self.firstSignatureType(callee_t) orelse return null;
                if (!self.rest_signatures.contains(sig)) return null;
                const params = self.interner.signatureParams(sig);
                if (params.len == 0) return null;
                const fixed_count = params.len - 1;
                if (idx < fixed_count) return null;
                const tuple_node = self.restTupleAnnotationForSignature(sig) orelse return null;
                return try self.tupleAnnotationElementTypeAt(tuple_node, idx - fixed_count, args.len - fixed_count);
            },
            else => return null,
        }
    }

    fn functionAssignmentContextualReturnShouldDefer(self: *Checker, fn_node: NodeId, contextual_sig: ?TypeId) bool {
        if (contextual_sig == null) return false;
        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(parent) != .assignment) return false;
        if (hir_mod.assignmentOf(self.hir, parent).value != fn_node) return false;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.body == hir_mod.none_node_id or self.hir.kindOf(f.body) != .block_stmt) return false;
        const stmts = hir_mod.blockStmts(self.hir, f.body);
        if (stmts.len != 1 or self.hir.kindOf(stmts[0]) != .return_stmt) return false;
        const ret = hir_mod.returnOf(self.hir, stmts[0]);
        if (ret.value == hir_mod.none_node_id) return false;
        return self.returnValueIsNullishLiteral(ret.value);
    }

    fn reportAssignmentContextualNullishReturnMismatch(
        self: *Checker,
        return_stmt: NodeId,
        return_value: NodeId,
        target_sig: TypeId,
    ) CheckError!bool {
        const fn_node = self.enclosingFunctionLike(return_stmt) orelse return false;
        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .assignment) return false;
        if (hir_mod.assignmentOf(self.hir, parent).value != fn_node) return false;
        if (!self.returnValueIsNullishLiteral(return_value)) return false;
        const target_name = (try self.allocAssignmentDiagnosticTypeName(target_sig)) orelse
            (try self.allocSimpleTypeName(target_sig)) orelse
            return false;
        const source_name = if (self.hir.kindOf(return_value) == .literal_null) "() => null" else "() => undefined";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' is not assignable to type '{s}'.",
            .{ source_name, target_name },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = parent,
            .pos = self.assignmentDiagnosticAnchor(parent),
            .code = TsCodes.type_not_assignable,
            .message = msg,
        });
        return true;
    }

    fn contextualReturnSignatureForFunction(self: *Checker, fn_node: NodeId) ?TypeId {
        const target_t = self.contextualTargetTypeForFunction(fn_node) orelse return null;
        if (target_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(target_t);
        if (flags.is_signature) return target_t;
        if (flags.is_union) {
            var found_sig: TypeId = types.Primitive.none;
            var found_ret: TypeId = types.Primitive.none;
            for (self.interner.unionMembers(target_t)) |member| {
                if (member >= self.interner.pool.typeCount()) continue;
                if (!self.interner.pool.flagsOf(member).is_signature) continue;
                const ret = self.interner.signatureReturn(member) orelse continue;
                if (found_sig == types.Primitive.none) {
                    found_sig = member;
                    found_ret = ret;
                } else if (found_ret != ret) {
                    return null;
                }
            }
            return if (found_sig == types.Primitive.none) null else found_sig;
        }
        return null;
    }

    fn contextualReturnTypeForFunction(self: *Checker, fn_node: NodeId) ?TypeId {
        if (self.pairedSetterContextualReturnType(fn_node)) |setter_t| return setter_t;
        const sig = self.contextualReturnSignatureForFunction(fn_node) orelse return null;
        return self.interner.signatureReturn(sig);
    }

    fn contextualReturnTypeForFunctionKind(self: *Checker, fn_node: NodeId, is_async: bool) ?TypeId {
        const return_t = self.contextualReturnTypeForFunction(fn_node) orelse return null;
        if (!is_async or self.typeContainsPromisePayload(return_t)) return return_t;
        return null;
    }

    fn typeContainsPromisePayload(self: *Checker, t: TypeId) bool {
        if (self.promisePayloadType(t) != null) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(t).is_union) return false;
        for (self.interner.unionMembers(t)) |member| {
            if (self.typeContainsPromisePayload(member)) return true;
        }
        return false;
    }

    fn pairedSetterContextualReturnType(self: *Checker, fn_node: NodeId) ?TypeId {
        if (fn_node == hir_mod.none_node_id) return null;
        const kind = self.hir.kindOf(fn_node);
        if (kind != .fn_decl and kind != .fn_expr and kind != .arrow_fn) return null;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (!f.flags.is_getter or f.return_type != hir_mod.none_node_id) return null;
        const member_name = (self.classMemberNameFromFunctionName(f.name) catch null) orelse return null;
        const class_node = self.enclosingClassNode(fn_node);
        if (class_node == hir_mod.none_node_id) return null;
        const c = hir_mod.classOf(self.hir, class_node);
        if (c.name == hir_mod.none_node_id or self.hir.kindOf(c.name) != .identifier) return null;
        return self.class_accessor_setter_types.get(.{
            .class_name = hir_mod.identifierOf(self.hir, c.name).name,
            .member_name = member_name,
            .is_static = f.flags.is_static,
        });
    }

    fn contextualReturnTypeInfersUndefined(self: *Checker, return_t: TypeId, is_async: bool) bool {
        return self.contextualReturnTypeIncludesUndefined(return_t, is_async);
    }

    fn contextualReturnTypeIncludesUndefined(self: *Checker, t: TypeId, is_async: bool) bool {
        if (t == types.Primitive.any or t == types.Primitive.unknown or t == types.Primitive.undefined_t) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_any or flags.is_unknown or flags.is_undefined) return true;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.contextualReturnTypeIncludesUndefined(member, is_async)) return true;
            }
            return false;
        }
        if (is_async) {
            const awaited = self.evalAwaited(t);
            if (awaited != t) return self.contextualReturnTypeIncludesUndefined(awaited, false);
        }
        return false;
    }

    /// Conservative gate for the TS7006 implicit-any diagnostic on a
    /// parameter without an annotation. Returns `true` when the
    /// enclosing function/arrow appears in a position where TypeScript
    /// would supply a contextual signature (and therefore no
    /// implicit-any would surface). The gate is intentionally
    /// conservative ÃÂ¢ÃÂÃÂ false positives here just leave the diagnostic
    /// firing, matching the previous behavior.
    ///
    /// Cases covered:
    ///   1. `set x(v) {ÃÂ¢ÃÂÃÂ¦}` accessors ÃÂ¢ÃÂÃÂ tsc pulls the parameter type
    ///      from the matching `get`'s return type, or treats it as
    ///      `unknown` when no getter exists.
    ///   2. The fn/arrow is an argument to a call/new expression. tsc
    ///      contextually types fn arguments from the callee
    ///      signature; even when the callee is generic, the param
    ///      type is supplied at the call site, not by implicit-any.
    ///   3. The fn/arrow is the value of a property in an object
    ///      literal that itself appears as a call argument or the
    ///      init of a typed `let`/`const`/`var` (recursively through
    ///      nested object/array literal hosts).
    ///   4. The fn/arrow is the rhs of an assignment or the init of
    ///      a typed variable declaration ÃÂ¢ÃÂÃÂ tsc seeds parameters from
    ///      the lhs/declared type.
    /// True when a JSX attribute's value gets a contextual type from
    /// its enclosing JSX element's target props. `data-*` attributes
    /// (which tsc treats as untyped) and attributes on intrinsic tags
    /// with no `JSX.IntrinsicElements[<tag>]` declaration return
    /// false. Anchors the TS7006-suppression decision for arrow
    /// parameters used as JSX attribute values
    /// (`<Tag c1={(x) => ...} />` in `tsxAttributeResolution2`).
    fn jsxAttributeHasContextualType(self: *Checker, attr_node: NodeId) bool {
        if (attr_node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(attr_node) != .jsx_attribute) return false;
        const a = hir_mod.jsxAttributeOf(self.hir, attr_node);
        const name_text = self.string_interner.get(a.name);
        // `data-*` attributes carry no typed contract upstream ÃÂ¢ÃÂÃÂ leave
        // their arrow params owing TS7006 as tsc does on
        // `tsxAttributeResolution2` line 16's `data-c1` case.
        if (std.mem.startsWith(u8, name_text, "data-")) return false;
        // Walk up to the JSX element parent and resolve its prop
        // shape. Mirrors what the attribute loop in `checkJsxElement`
        // does but stays read-only ÃÂ¢ÃÂÃÂ we only need to know whether the
        // attribute name resolves to a member with a callable signature.
        const el_node = self.hir.parentOf(attr_node);
        if (el_node == hir_mod.none_node_id) return false;
        const el_kind = self.hir.kindOf(el_node);
        if (el_kind != .jsx_element and el_kind != .jsx_self_closing) return false;
        const el = hir_mod.jsxElementOf(self.hir, el_node);
        const attrs_len = hir_mod.jsxAttrs(self.hir, el_node).len;
        const props_t = (self.jsxPropsType(el_node, el.tag, attrs_len) catch return false) orelse return false;
        if (self.typeIsAnyLike(props_t)) return false;
        const prop_t = (self.jsxContextualPropType(props_t, el.tag, a.name) catch return false) orelse return false;
        return self.jsxPropProvidesFunctionContext(prop_t);
    }

    fn jsxSpreadAttributeMemberHasContextualType(
        self: *Checker,
        spread_node: NodeId,
        member_name: hir_mod.StringId,
    ) bool {
        if (spread_node == hir_mod.none_node_id or self.hir.kindOf(spread_node) != .jsx_spread_attribute) return false;
        const el_node = self.hir.parentOf(spread_node);
        if (el_node == hir_mod.none_node_id) return false;
        const el_kind = self.hir.kindOf(el_node);
        if (el_kind != .jsx_element and el_kind != .jsx_self_closing) return false;
        const el = hir_mod.jsxElementOf(self.hir, el_node);
        const attrs_len = hir_mod.jsxAttrs(self.hir, el_node).len;
        const props_t = (self.jsxPropsType(el_node, el.tag, attrs_len) catch return false) orelse return false;
        if (self.typeIsAnyLike(props_t)) return false;
        const prop_t = (self.jsxContextualPropType(props_t, el.tag, member_name) catch return false) orelse return false;
        return self.jsxPropProvidesFunctionContext(prop_t);
    }

    fn jsxPropProvidesFunctionContext(self: *Checker, prop_t: TypeId) bool {
        return self.typeIsAnyLike(prop_t) or self.firstSignatureType(prop_t) != null;
    }

    fn parameterHasContextualType(self: *Checker, fn_node: NodeId, param_node: NodeId) bool {
        if (self.functionIsAccessorSetter(fn_node)) return true;
        if (self.checkJsPrototypeObjectLiteralAssignmentOwnerNameForFunction(fn_node) != null) return false;
        var cur = self.hir.parentOf(fn_node);
        var prev = fn_node;
        var contextual_member_name: ?hir_mod.StringId = null;
        while (cur != hir_mod.none_node_id) : ({
            prev = cur;
            cur = self.hir.parentOf(cur);
        }) {
            switch (self.hir.kindOf(cur)) {
                .call_expr, .new_expr => {
                    const c = hir_mod.callOf(self.hir, cur);
                    if (c.callee == prev) return self.iifeParameterHasArgumentContext(fn_node, param_node);
                    if (self.callHasDirectFunctionCallee(cur)) return false;
                    if (self.callCalleeRootHasInvalidContextualType(c.callee)) return false;
                    const target_t = self.contextualTargetTypeForFunction(fn_node) orelse return false;
                    return self.contextualParameterTypeForFunctionParam(fn_node, param_node, target_t) != null;
                },
                .var_decl, .let_decl, .const_decl => {
                    const v = hir_mod.varDeclOf(self.hir, cur);
                    if (v.init != prev) return false;
                    if (v.type_annotation != hir_mod.none_node_id) {
                        const target_t = self.hir.typeOf(cur);
                        if ((self.contextualArrayLiteralFunctionElementTarget(fn_node, v.init) catch null)) |element_target_t| {
                            return self.contextualParameterTypeForFunctionParam(fn_node, param_node, element_target_t) != null;
                        }
                        if (contextual_member_name) |member_name| {
                            if (self.hir.kindOf(prev) == .array_literal) {
                                const element_t = self.contextualArrayElementType(target_t) catch return false;
                                if (element_t != types.Primitive.none) {
                                    if ((self.contextualObjectLiteralMemberTarget(element_t, member_name) catch null)) |member_t| {
                                        return self.contextualParameterTypeForFunctionParam(fn_node, param_node, member_t) != null;
                                    }
                                }
                            }
                            if ((self.contextualObjectLiteralMemberTarget(target_t, member_name) catch null)) |member_t| {
                                return self.contextualParameterTypeForFunctionParam(fn_node, param_node, member_t) != null;
                            }
                        }
                        return self.contextualParameterTypeForFunctionParam(fn_node, param_node, target_t) != null;
                    }
                    if (contextual_member_name) |member_name| {
                        if (self.hir.kindOf(prev) == .object_literal) {
                            if ((self.jsDocSatisfiesTypeForExpression(prev) catch null)) |target_t| {
                                const member_t = (self.contextualObjectLiteralMemberTarget(target_t, member_name) catch null) orelse return false;
                                return self.contextualParameterTypeForFunctionParam(fn_node, param_node, member_t) != null;
                            }
                        }
                    }
                    // In `.js` files a leading `/** @type {T} */` on
                    // the var-decl supplies a contextual signature for
                    // an arrow/fn initializer. Mirrors upstream tsc
                    // which threads JSDoc `@type` through the
                    // contextual-typing pipeline.
                    if (self.virtualSectionIsJsLike(cur) and self.varDeclHasJsDocTypeTag(cur)) {
                        const type_text = self.varDeclLeadingJsDocTypeText(cur) orelse return false;
                        const trimmed = std.mem.trim(u8, type_text, " \t\r\n");
                        return !std.mem.eql(u8, trimmed, "Function") and
                            !std.mem.eql(u8, trimmed, "function");
                    }
                    return false;
                },
                .assignment => {
                    const a = hir_mod.assignmentOf(self.hir, cur);
                    if (a.value != prev or a.target == hir_mod.none_node_id) return false;
                    if (self.sourceHasCheckJsDirective() and self.assignmentTargetIsPrototypeMember(a.target)) return false;
                    const target_t = self.contextualTargetTypeForFunction(fn_node) orelse return false;
                    return self.contextualParameterTypeForFunctionParam(fn_node, param_node, target_t) != null;
                },
                .return_stmt => return self.returnedFunctionContextualParameterType(cur, fn_node, param_node) != null,
                .object_property => {
                    const op = hir_mod.objectPropertyOf(self.hir, cur);
                    if (op.value == prev and !op.is_computed) {
                        contextual_member_name = self.propertyNameFromKeyNode(op.key) orelse contextual_member_name;
                    }
                    continue;
                },
                .object_literal,
                .array_literal,
                .as_expr,
                .conditional,
                => continue,
                .class_expr, .class_decl => {
                    const member_name = contextual_member_name orelse return false;
                    if (self.hir.kindOf(prev) != .object_property) return false;
                    const op = hir_mod.objectPropertyOf(self.hir, prev);
                    const fn_kind = self.hir.kindOf(fn_node);
                    if (fn_kind != .arrow_fn and fn_kind != .fn_expr and fn_kind != .fn_decl) return false;
                    if (fn_kind == .fn_decl and !self.objectPropertyHasInitializerEquals(prev, op.value)) return false;
                    const field_is_static_context = op.is_static or
                        self.classMemberSourceHasModifierBeforeKey(prev, op.key, "static");
                    if (!field_is_static_context) return false;
                    const member_t = (self.contextualClassExpressionStaticMemberTarget(cur, member_name) catch null) orelse return false;
                    return self.contextualParameterTypeForFunctionParam(fn_node, param_node, member_t) != null;
                },
                .satisfies_expr => return self.satisfiesProvidesContextualType(cur, fn_node),
                .logical_op => {
                    // tsc: when an `||` / `??` expression is itself not
                    // contextually typed, the right operand is
                    // contextually typed by the left operand's type
                    // (spec ÃÂÃÂ§4.19.2). A parameterless arrow on the RHS
                    // therefore gets a contextual parameter type from
                    // the LHS ÃÂ¢ÃÂÃÂ no TS7006. AND (`&&`) does NOT propagate
                    // a contextual type (it narrows truthiness) so it
                    // still walks up to look for an outer context.
                    const lop = hir_mod.logicalOf(self.hir, cur);
                    if (lop.rhs == prev and (lop.op == .@"or" or lop.op == .nullish)) return true;
                    continue;
                },
                .binary_op => {
                    // Only the rightmost operand of a comma sequence
                    // receives the surrounding contextual type ÃÂ¢ÃÂÃÂ left
                    // operands are evaluated in isolation, so their
                    // arrow/fn parameters still owe TS7006. Mirrors
                    // tsc's `contextuallyTypeCommaOperator03` baseline
                    // where `(a => a, b => b)` against
                    // `(a: string) => string` only flags `a`.
                    const b = hir_mod.binopOf(self.hir, cur);
                    if (b.op != .comma) return false;
                    if (b.rhs != prev) return false;
                    continue;
                },
                .jsx_expression => {
                    // `<Tag c1={(x) => x.length} />` ÃÂ¢ÃÂÃÂ the arrow lives
                    // in a JSX expression inside a JSX attribute whose
                    // target prop type (`c1?: (x: string) => void`)
                    // supplies a contextual signature. Walk up so the
                    // jsx_attribute case below handles the actual
                    // prop-name lookup. For data-* attributes the
                    // attribute case returns false; for typed props
                    // it returns true.
                    continue;
                },
                .jsx_attribute => {
                    return self.jsxAttributeHasContextualType(cur);
                },
                .jsx_spread_attribute => {
                    const member_name = contextual_member_name orelse return false;
                    return self.jsxSpreadAttributeMemberHasContextualType(cur, member_name);
                },
                .decorator => {
                    return self.decoratorExpressionHasContextualType(cur, prev);
                },
                else => return false,
            }
        }
        return false;
    }

    fn callCalleeRootHasInvalidContextualType(self: *Checker, callee: NodeId) bool {
        var root = callee;
        while (root != hir_mod.none_node_id and self.hir.kindOf(root) == .member_access) {
            root = hir_mod.memberOf(self.hir, root).object;
        }
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, root);
        if ((self.enclosingClassStaticMemberClassName(root, id.name) catch null) != null) return true;
        const decl = self.findVisibleSameNameValueBinding(root, id.name) orelse return false;
        const decl_kind = self.hir.kindOf(decl);
        if (decl_kind != .var_decl and decl_kind != .let_decl and decl_kind != .const_decl) return false;
        const v = hir_mod.varDeclOf(self.hir, decl);
        if (v.type_annotation == hir_mod.none_node_id) return false;
        return self.qualifiedTypeRefIsInvalidNamespaceAnnotation(v.type_annotation);
    }

    fn qualifiedTypeRefIsInvalidNamespaceAnnotation(self: *Checker, type_node: NodeId) bool {
        if (type_node == hir_mod.none_node_id or self.hir.kindOf(type_node) != .type_ref) return false;
        const r = hir_mod.typeRefOf(self.hir, type_node);
        const qualifiers = hir_mod.typeRefQualifier(self.hir, type_node);
        if (qualifiers.len == 0) return false;
        var path: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer path.deinit(self.gpa);
        for (qualifiers) |q| {
            if (self.hir.kindOf(q) != .identifier) return false;
            path.append(self.gpa, hir_mod.identifierOf(self.hir, q).name) catch return false;
        }
        const root = self.rootBlockFor(type_node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        const root_stmts = hir_mod.blockStmts(self.hir, root);
        const ns_node = self.findNamespaceByPath(root_stmts, path.items) orelse
            (self.findRelativeNamespaceByPathNoAlloc(type_node, root_stmts, path.items) orelse return true);
        if (self.findVisibleTypeDeclInNamespace(ns_node, r.name, type_node) != null) return false;
        return self.findExportedValueDeclInNamespace(ns_node, r.name) != null;
    }

    fn findRelativeNamespaceByPathNoAlloc(
        self: *Checker,
        anchor: NodeId,
        root_stmts: []const NodeId,
        path: []const hir_mod.StringId,
    ) ?NodeId {
        var relative_path: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer relative_path.deinit(self.gpa);
        return self.findRelativeNamespaceByPath(anchor, root_stmts, path, &relative_path) catch null;
    }

    fn functionValueParameterIndex(self: *Checker, fn_node: NodeId, param_node: NodeId) ?usize {
        var value_index: usize = 0;
        for (hir_mod.fnParams(self.hir, fn_node)) |param| {
            if (param == param_node) return value_index;
            if (!self.isThisParameter(param)) value_index += 1;
        }
        return null;
    }

    fn contextualParameterTypeForSignature(
        self: *Checker,
        sig: TypeId,
        param_index: usize,
        source_is_rest: bool,
    ) ?TypeId {
        const params = self.interner.signatureParams(sig);
        if (!self.rest_signatures.contains(sig)) {
            if (param_index >= params.len) return null;
            return params[param_index];
        }
        if (params.len == 0) return null;
        const fixed_count = params.len - 1;
        if (param_index < fixed_count) return params[param_index];
        if (source_is_rest) return params[params.len - 1];
        return self.contextualRestTupleElementType(params[params.len - 1], param_index - fixed_count);
    }

    fn contextualRestTupleElementType(self: *Checker, rest_t: TypeId, index: usize) ?TypeId {
        if (rest_t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(rest_t).is_union) {
            const element_t = self.tupleElementType(rest_t, index);
            return if (element_t == types.Primitive.none) null else element_t;
        }
        var candidates: std.ArrayListUnmanaged(TypeId) = .empty;
        defer candidates.deinit(self.gpa);
        for (self.interner.unionMembers(rest_t)) |member| {
            const element_t = self.tupleElementType(member, index);
            if (element_t == types.Primitive.none) return null;
            var seen = false;
            for (candidates.items) |candidate| {
                if (candidate == element_t) {
                    seen = true;
                    break;
                }
            }
            if (!seen) candidates.append(self.gpa, element_t) catch return null;
        }
        if (candidates.items.len == 0) return null;
        if (candidates.items.len == 1) return candidates.items[0];
        return self.interner.internUnion(candidates.items) catch null;
    }

    fn resolveContextualTypeAliasNode(self: *Checker, anchor: NodeId, type_node: NodeId) ?NodeId {
        var current = type_node;
        var depth: u8 = 0;
        while (depth < 8 and current != hir_mod.none_node_id and self.hir.kindOf(current) == .type_ref) : (depth += 1) {
            const ref = hir_mod.typeRefOf(self.hir, current);
            if (ref.qualifier_len != 0 or ref.args_len != 0) break;
            const decl = self.findVisibleNamedTypeDecl(anchor, ref.name) orelse break;
            if (self.hir.kindOf(decl) != .type_alias_decl) break;
            const aliased = hir_mod.typeAliasOf(self.hir, decl).aliased;
            if (aliased == hir_mod.none_node_id or aliased == current) break;
            current = aliased;
        }
        return if (current == hir_mod.none_node_id) null else current;
    }

    fn contextualRestAnnotationElementType(
        self: *Checker,
        anchor: NodeId,
        type_node: NodeId,
        index: usize,
    ) CheckError!?TypeId {
        const resolved = self.resolveContextualTypeAliasNode(anchor, type_node) orelse return null;
        switch (self.hir.kindOf(resolved)) {
            .union_type => {
                var candidates: std.ArrayListUnmanaged(TypeId) = .empty;
                defer candidates.deinit(self.gpa);
                for (hir_mod.unionTypeMembers(self.hir, resolved)) |member| {
                    const candidate = (try self.contextualRestAnnotationElementType(anchor, member, index)) orelse return null;
                    var seen = false;
                    for (candidates.items) |existing| {
                        if (existing == candidate) {
                            seen = true;
                            break;
                        }
                    }
                    if (!seen) try candidates.append(self.gpa, candidate);
                }
                if (candidates.items.len == 0) return null;
                if (candidates.items.len == 1) return candidates.items[0];
                return self.interner.internUnion(candidates.items) catch return error.OutOfMemory;
            },
            .tuple_type => {
                const elements = hir_mod.tupleTypeElements(self.hir, resolved);
                if (index >= elements.len) return null;
                return try self.lowererLowerWithTypeParams(elements[index]);
            },
            .array_type => return try self.lowererLowerWithTypeParams(hir_mod.arrayTypeOf(self.hir, resolved).element),
            else => {
                const rest_t = try self.lowererLowerWithTypeParams(resolved);
                const element_t = self.tupleElementType(rest_t, index);
                return if (element_t == types.Primitive.none) null else element_t;
            },
        }
    }

    fn contextualParameterTypeFromFunctionAnnotation(
        self: *Checker,
        fn_node: NodeId,
        param_node: NodeId,
    ) CheckError!?TypeId {
        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id) return null;
        const parent_kind = self.hir.kindOf(parent);
        if (parent_kind != .var_decl and parent_kind != .let_decl and parent_kind != .const_decl) return null;
        const declaration = hir_mod.varDeclOf(self.hir, parent);
        if (declaration.init != fn_node or declaration.type_annotation == hir_mod.none_node_id) return null;
        const target_node = self.resolveContextualTypeAliasNode(parent, declaration.type_annotation) orelse return null;
        if (self.hir.kindOf(target_node) != .fn_type) return null;
        const source_index = self.functionValueParameterIndex(fn_node, param_node) orelse return null;
        const source_is_rest = self.hir.kindOf(param_node) == .parameter and
            hir_mod.parameterOf(self.hir, param_node).flags.is_rest;
        const target_fn = hir_mod.fnTypeOf(self.hir, target_node);
        var target_index: usize = 0;
        for (self.hir.childSlice(target_fn.params_start, target_fn.params_len)) |target_param_node| {
            if (self.hir.kindOf(target_param_node) != .parameter) continue;
            if (self.isThisParameter(target_param_node)) continue;
            const target_param = hir_mod.parameterOf(self.hir, target_param_node);
            if (!target_param.flags.is_rest) {
                if (target_index == source_index and target_param.type_annotation != hir_mod.none_node_id) {
                    return try self.lowererLowerWithTypeParams(target_param.type_annotation);
                }
                target_index += 1;
                continue;
            }
            if (source_index < target_index or target_param.type_annotation == hir_mod.none_node_id) return null;
            if (source_is_rest) return try self.lowererLowerWithTypeParams(target_param.type_annotation);
            return try self.contextualRestAnnotationElementType(
                parent,
                target_param.type_annotation,
                source_index - target_index,
            );
        }
        return null;
    }

    fn functionAnnotationProvidesAllParameterContext(
        self: *Checker,
        fn_node: NodeId,
    ) CheckError!?bool {
        var saw_value_param = false;
        for (hir_mod.fnParams(self.hir, fn_node)) |param_node| {
            if (self.hir.kindOf(param_node) != .parameter or self.isThisParameter(param_node)) continue;
            const param = hir_mod.parameterOf(self.hir, param_node);
            if (param.type_annotation != hir_mod.none_node_id) return null;
            saw_value_param = true;
            if ((try self.contextualParameterTypeFromFunctionAnnotation(fn_node, param_node)) == null) return false;
        }
        return if (saw_value_param) true else null;
    }

    fn mergeContextualParameterType(self: *Checker, current: *TypeId, candidate: TypeId) bool {
        if (current.* == types.Primitive.none) {
            current.* = candidate;
            return true;
        }
        if (current.* == candidate) return true;
        return self.engine.isIdenticalTo(current.*, candidate) catch false;
    }

    fn functionExceedsContextualSignatureArity(self: *Checker, fn_node: NodeId, target_t: TypeId) bool {
        var required: usize = 0;
        for (hir_mod.fnParams(self.hir, fn_node)) |param| {
            if (self.hir.kindOf(param) != .parameter) {
                required += 1;
                continue;
            }
            if (self.isThisParameter(param)) continue;
            const p = hir_mod.parameterOf(self.hir, param);
            if (!p.flags.is_optional and !p.flags.is_rest and p.default_value == hir_mod.none_node_id) {
                required += 1;
            }
        }
        var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer sigs.deinit(self.gpa);
        self.collectCallSignatures(target_t, &sigs) catch return false;
        if (sigs.items.len == 0) return false;
        for (sigs.items) |sig| {
            if (self.rest_signatures.contains(sig) or self.interner.signatureParams(sig).len >= required) {
                return false;
            }
        }
        return true;
    }

    fn contextualParameterTypeForFunctionParam(self: *Checker, fn_node: NodeId, param_node: NodeId, target_t: TypeId) ?TypeId {
        if (self.functionExceedsContextualSignatureArity(fn_node, target_t)) return null;
        const param_index = self.functionValueParameterIndex(fn_node, param_node) orelse return null;
        const source_is_rest = self.hir.kindOf(param_node) == .parameter and
            hir_mod.parameterOf(self.hir, param_node).flags.is_rest;
        if (target_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(target_t);
        var found: TypeId = types.Primitive.none;
        if (flags.is_union) {
            for (self.interner.unionMembers(target_t)) |member| {
                var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
                defer sigs.deinit(self.gpa);
                self.collectCallSignatures(member, &sigs) catch return null;
                if (sigs.items.len == 0) continue;
                if (sigs.items.len > 1) return null;
                const candidate = self.contextualParameterTypeForSignature(sigs.items[0], param_index, source_is_rest) orelse return null;
                if (!self.mergeContextualParameterType(&found, candidate)) return null;
            }
            return if (found == types.Primitive.none) null else found;
        }

        var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer sigs.deinit(self.gpa);
        self.collectCallSignatures(target_t, &sigs) catch return null;
        for (sigs.items) |sig| {
            const candidate = self.contextualParameterTypeForSignature(sig, param_index, source_is_rest) orelse return null;
            if (!self.mergeContextualParameterType(&found, candidate)) return null;
        }
        return if (found == types.Primitive.none) null else found;
    }

    fn returnedFunctionContextualParameterType(
        self: *Checker,
        return_node: NodeId,
        returned_fn: NodeId,
        param_node: NodeId,
    ) ?TypeId {
        if (self.hir.kindOf(return_node) != .return_stmt) return null;
        const ret = hir_mod.returnOf(self.hir, return_node);
        if (ret.value != returned_fn) return null;
        const fn_node = self.enclosingFunctionForReturn(return_node) orelse return null;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        const outer_sig = self.hir.typeOf(fn_node);
        const return_t: TypeId = if (self.interner.isSignature(outer_sig))
            self.interner.signatureReturn(outer_sig) orelse return null
        else if (f.return_type != hir_mod.none_node_id)
            self.lowererLowerWithTypeParams(f.return_type) catch return null
        else
            self.contextualReturnTypeForFunction(fn_node) orelse return null;
        return self.contextualParameterTypeForFunctionParam(returned_fn, param_node, return_t);
    }

    fn decoratorExpressionHasContextualType(self: *Checker, decorator_node: NodeId, expr_node: NodeId) bool {
        if (decorator_node == hir_mod.none_node_id or self.hir.kindOf(decorator_node) != .decorator) return false;
        const d = hir_mod.decoratorOf(self.hir, decorator_node);
        return d.expression == expr_node;
    }

    fn callHasDirectFunctionCallee(self: *Checker, call_node: NodeId) bool {
        if (call_node == hir_mod.none_node_id) return false;
        const kind = self.hir.kindOf(call_node);
        if (kind != .call_expr and kind != .new_expr) return false;
        const c = hir_mod.callOf(self.hir, call_node);
        const callee_kind = self.hir.kindOf(c.callee);
        return callee_kind == .fn_decl or callee_kind == .fn_expr or callee_kind == .arrow_fn;
    }

    fn iifeParameterHasArgumentContext(self: *Checker, fn_node: NodeId, param_node: NodeId) bool {
        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id) return false;
        const parent_kind = self.hir.kindOf(parent);
        if (parent_kind != .call_expr and parent_kind != .new_expr) return false;
        const call = hir_mod.callOf(self.hir, parent);
        if (call.callee != fn_node) return false;
        for (hir_mod.fnParams(self.hir, fn_node)) |p| {
            if (p == param_node) return true;
        }
        return false;
    }

    /// Contextually type un-annotated callback parameters passed to
    /// built-in array methods
    /// (`map` / `filter` / `forEach` / `some` / `every` / `find` /
    /// `findIndex` / `findLast` / `findLastIndex` / `flatMap` /
    /// `sort`). For `arr.map((x) => ÃÂ¢ÃÂÃÂ¦)` the callback's first
    /// parameter is the array element type, exactly as tsc threads the
    /// element type through `Array<T>.map`'s generic callback
    /// signature. `sort` is the comparator-shaped exception: both
    /// `(a, b)` parameters are `T`. This is what lets
    /// `spreadNonObject1.ts` surface TS2698 and `arrayconcat.ts`
    /// surface TS18048 on optional properties inside a comparator.
    /// Returns `none` when the receiver isn't an array-like so callers
    /// fall back to the implicit-any path (and its TS7006 reporting).
    fn arrayCallbackParameterElementType(
        self: *Checker,
        fn_node: NodeId,
        param_index: usize,
    ) CheckError!?TypeId {
        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(parent) != .call_expr) return null;
        const call = hir_mod.callOf(self.hir, parent);
        // The callback must be an *argument*, not the callee itself
        // (that IIFE shape is handled separately).
        if (call.callee == fn_node) return null;
        var is_arg = false;
        for (hir_mod.callArgs(self.hir, parent)) |arg| {
            if (arg == fn_node) {
                is_arg = true;
                break;
            }
        }
        if (!is_arg) return null;
        // Callee must be `receiver.method` and `method` one of the
        // element-first array iteration helpers.
        if (call.callee == hir_mod.none_node_id or self.hir.kindOf(call.callee) != .member_access) return null;
        const m = hir_mod.memberOf(self.hir, call.callee);
        if (m.object == hir_mod.none_node_id) return null;
        const method = self.string_interner.get(m.name);
        if (std.mem.eql(u8, method, "sort")) {
            if (param_index > 1) return null;
        } else if (param_index != 0) {
            return null;
        }
        const element_first = std.StaticStringMap(void).initComptime(.{
            .{"map"},       .{"filter"},   .{"forEach"},
            .{"some"},      .{"every"},    .{"find"},
            .{"findIndex"}, .{"findLast"}, .{"findLastIndex"},
            .{"flatMap"},   .{"sort"},
        });
        if (!element_first.has(method)) return null;
        const recv_t = try self.checkExpression(m.object);
        if (recv_t >= self.interner.pool.typeCount()) return null;
        const elem_t = try self.contextualArrayElementType(recv_t);
        if (elem_t == types.Primitive.none) return null;
        return elem_t;
    }

    fn iifeParameterTypeFromCallArgument(
        self: *Checker,
        fn_node: NodeId,
        param_index: usize,
        is_rest: bool,
    ) CheckError!?TypeId {
        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id) return null;
        const parent_kind = self.hir.kindOf(parent);
        if (parent_kind != .call_expr and parent_kind != .new_expr) return null;
        const call = hir_mod.callOf(self.hir, parent);
        if (call.callee != fn_node) return null;
        const args = hir_mod.callArgs(self.hir, parent);
        if (is_rest) {
            var elem_types: std.ArrayListUnmanaged(TypeId) = .empty;
            defer elem_types.deinit(self.gpa);
            var flattened_index: usize = 0;
            for (args) |arg| {
                const arg_t = try self.checkExpression(arg);
                if (self.hir.kindOf(arg) != .spread) {
                    if (flattened_index >= param_index) {
                        try elem_types.append(self.gpa, self.widenForInference(arg_t));
                    }
                    flattened_index += 1;
                    continue;
                }
                if (!self.isTupleShapedTarget(arg_t)) {
                    const elem_t = try self.iterableElementType(arg_t);
                    try elem_types.append(self.gpa, self.widenForInference(elem_t));
                    flattened_index += 1;
                    continue;
                }
                const known_count = if (self.fixedTupleLength(arg_t)) |len|
                    @as(usize, @intCast(len))
                else
                    self.tupleFixedPrefixCount(arg_t);
                for (0..known_count) |tuple_index| {
                    if (flattened_index + tuple_index < param_index) continue;
                    const elem_t = self.tupleElementType(arg_t, tuple_index);
                    if (elem_t == types.Primitive.none) continue;
                    try elem_types.append(self.gpa, self.widenForInference(elem_t));
                }
                flattened_index += known_count;
                if (self.fixedTupleLength(arg_t) == null) {
                    const tail_t = self.tupleRestTailElementType(arg_t);
                    if (tail_t != types.Primitive.none) {
                        try elem_types.append(self.gpa, self.widenForInference(tail_t));
                    }
                }
            }
            const elem_t = if (elem_types.items.len == 0)
                types.Primitive.any
            else if (elem_types.items.len == 1)
                elem_types.items[0]
            else
                self.interner.internUnion(elem_types.items) catch return error.OutOfMemory;
            return self.interner.internArrayType(self.string_interner, elem_t) catch return error.OutOfMemory;
        }
        var flattened_index: usize = 0;
        for (args) |arg| {
            const arg_t = try self.checkExpression(arg);
            if (self.hir.kindOf(arg) != .spread) {
                if (flattened_index == param_index) return self.widenForInference(arg_t);
                flattened_index += 1;
                continue;
            }
            if (!self.isTupleShapedTarget(arg_t)) {
                if (param_index >= flattened_index) {
                    return self.widenForInference(try self.iterableElementType(arg_t));
                }
                flattened_index += 1;
                continue;
            }
            const known_count = if (self.fixedTupleLength(arg_t)) |len|
                @as(usize, @intCast(len))
            else
                self.tupleFixedPrefixCount(arg_t);
            if (param_index >= flattened_index and param_index < flattened_index + known_count) {
                const elem_t = self.tupleElementType(arg_t, param_index - flattened_index);
                if (elem_t != types.Primitive.none) return self.widenForInference(elem_t);
            }
            flattened_index += known_count;
            if (self.fixedTupleLength(arg_t) == null and param_index >= flattened_index) {
                const tail_t = self.tupleRestTailElementType(arg_t);
                if (tail_t != types.Primitive.none) return self.widenForInference(tail_t);
            }
        }
        return if (self.strict_flags.strict_null_checks)
            types.Primitive.undefined_t
        else
            types.Primitive.any;
    }

    fn satisfiesProvidesContextualType(self: *Checker, satisfies_node: NodeId, fn_node: NodeId) bool {
        if (self.hir.kindOf(satisfies_node) != .satisfies_expr) return false;
        const a = hir_mod.asExpressionOf(self.hir, satisfies_node);
        if (a.type_node == hir_mod.none_node_id) return false;
        const target_t = self.lowererLowerWithTypeParams(a.type_node) catch return false;
        if (a.expr == fn_node) {
            if (self.firstSignatureType(target_t) != null) return true;
            return self.typeIsFunctionObjectLike(target_t) catch false;
        }
        const prop = self.enclosingObjectPropertyBetween(fn_node, satisfies_node) orelse return false;
        const op = hir_mod.objectPropertyOf(self.hir, prop);
        const name = self.propertyNameFromKeyNode(op.key) orelse return false;
        const prop_t = (self.satisfiesTargetPropertyType(target_t, name) catch null) orelse return false;
        if (prop_t == types.Primitive.any or prop_t == types.Primitive.unknown) return false;
        if (self.firstSignatureType(prop_t) != null) return true;
        return self.typeIsFunctionObjectLike(prop_t) catch false;
    }

    fn enclosingObjectPropertyBetween(self: *Checker, node: NodeId, stop: NodeId) ?NodeId {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id and cur != stop) : (cur = self.hir.parentOf(cur)) {
            if (self.hir.kindOf(cur) == .object_property) return cur;
        }
        return null;
    }

    fn satisfiesTargetPropertyType(self: *Checker, target_t: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (target_t < types.Primitive.first_dynamic or target_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(target_t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(target_t)) |member| {
                if (try self.satisfiesTargetPropertyType(member, name)) |t| return t;
            }
            return null;
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(target_t)) |member| {
                if (try self.satisfiesTargetPropertyType(member, name)) |t| return t;
            }
            return null;
        }
        if (!flags.is_object_type) return null;
        if (self.interner.objectMember(target_t, name)) |t| return t;
        const idx = self.interner.objectStringIndex(target_t);
        if (idx != types.Primitive.none) return idx;
        return null;
    }

    /// True when `fn_node` is a class `set x(v) {ÃÂ¢ÃÂÃÂ¦}` accessor. tsc
    /// contextually types the setter's parameter from the matching
    /// getter's return type when one is present, and treats the
    /// parameter as `unknown` when no getter exists ÃÂ¢ÃÂÃÂ either way the
    /// implicit-any rule never fires on the class setter parameter, so
    /// we suppress TS7006 here too. Object-literal setters without
    /// parameter annotations still report TS7032 + TS7006.
    fn functionIsAccessorSetter(self: *Checker, fn_node: NodeId) bool {
        const k = self.hir.kindOf(fn_node);
        if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) return false;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (!f.flags.is_setter) return false;
        const parent = self.hir.parentOf(fn_node);
        if (parent != hir_mod.none_node_id and self.hir.kindOf(parent) == .object_property) {
            const grand = self.hir.parentOf(parent);
            if (grand != hir_mod.none_node_id and self.hir.kindOf(grand) == .object_literal) return false;
        }
        return true;
    }

    /// True when `t` is a valid rest-parameter type (TS2370 wants
    /// "an array type"). tsc accepts any/unknown/never (and error
    /// types), tuples, generic Array<T> / ReadonlyArray<T> / T[]
    /// (which all interner-surface as object types with a numeric
    /// index signature), bare type parameters whose constraint is
    /// array-like, and unions / intersections where the structural
    /// rule recurses.
    fn restParamTypeIsValidArrayLike(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.none) return true;
        if (t == types.Primitive.any or t == types.Primitive.unknown or t == types.Primitive.never) return true;
        if (t >= self.interner.pool.typeCount()) return true;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_any or flags.is_unknown or flags.is_never) return true;
        if (flags.is_tuple) return true;
        // Defer to runtime: anything whose array-likeness depends on
        // substitution gets the benefit of the doubt so we never
        // raise a false positive on a generic that resolves to a
        // tuple at the call site.
        if (flags.is_conditional or flags.is_mapped or flags.is_indexed_access or
            flags.is_keyof or flags.is_infer or flags.is_template_literal or
            flags.is_string_mapping or flags.is_instantiation or flags.is_typeof) return true;
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return true;
            return self.restParamTypeIsValidArrayLike(constraint);
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.restParamTypeIsValidArrayLike(member)) return false;
            }
            return true;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.restParamTypeIsValidArrayLike(member)) return true;
            }
            return false;
        }
        if (flags.is_object_type) {
            // Structural array-likes (Array<T> / ReadonlyArray<T>)
            // surface as object types with a numeric index signature
            // courtesy of `Interner.internArrayType`.
            if (self.interner.objectNumberIndex(t) != types.Primitive.none) return true;
            return false;
        }
        return false;
    }

    /// Syntax-level fast path mirroring `restParamTypeIsValidArrayLike`.
    /// Some annotations (`Array<T>` / `ReadonlyArray<T>` / `T[]`) lower
    /// to object types whose interned form depends on lib resolution
    /// being present ÃÂ¢ÃÂÃÂ when the lib types haven't been wired in for
    /// a fixture, the structural check reports a false positive. The
    /// syntax check covers those cases without needing the full
    /// resolved type.
    fn restParamAnnotationLooksArrayLike(self: *Checker, type_annotation: NodeId) bool {
        if (type_annotation == hir_mod.none_node_id) return true;
        const k = self.hir.kindOf(type_annotation);
        if (k == .array_type or k == .tuple_type) return true;
        if (k == .readonly_type) return self.restParamAnnotationLooksArrayLike(hir_mod.readonlyTypeOf(self.hir, type_annotation).operand);
        if (k == .type_ref) {
            const ref = hir_mod.typeRefOf(self.hir, type_annotation);
            if (ref.qualifier_len == 0) {
                const name = self.string_interner.get(ref.name);
                if (std.mem.eql(u8, name, "Array") or std.mem.eql(u8, name, "ReadonlyArray")) return true;
            }
        }
        return false;
    }

    fn typeNodeIsAnyKeyword(self: *Checker, type_node: NodeId) bool {
        if (type_node == hir_mod.none_node_id or self.hir.kindOf(type_node) != .type_ref) return false;
        const r = hir_mod.typeRefOf(self.hir, type_node);
        if (r.qualifier_len != 0 or r.args_len != 0) return false;
        return std.mem.eql(u8, self.string_interner.get(r.name), "any");
    }

    fn typeNodeLooksAnyArray(self: *Checker, type_node: NodeId) bool {
        if (type_node == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(type_node)) {
            .array_type => self.typeNodeIsAnyKeyword(hir_mod.arrayTypeOf(self.hir, type_node).element),
            .type_ref => blk: {
                const r = hir_mod.typeRefOf(self.hir, type_node);
                if (r.qualifier_len != 0 or r.args_len != 1) break :blk false;
                if (!std.mem.eql(u8, self.string_interner.get(r.name), "Array")) break :blk false;
                const args = hir_mod.typeRefArgs(self.hir, type_node);
                break :blk self.typeNodeIsAnyKeyword(args[0]);
            },
            else => false,
        };
    }

    fn typeIsAnyArrayForMixinCtor(self: *Checker, t: TypeId) CheckError!bool {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_tuple) return false;
        if (!flags.is_object_type) return false;
        const elem_t = try self.arrayElementType(t);
        return elem_t == types.Primitive.any;
    }

    fn mixinConstructorHasSingleAnyRestParam(self: *Checker, ctor_node: NodeId) CheckError!bool {
        if (ctor_node == hir_mod.none_node_id) return false;
        const params = hir_mod.fnParams(self.hir, ctor_node);
        if (params.len != 1 or self.hir.kindOf(params[0]) != .parameter) return false;
        const p = hir_mod.parameterOf(self.hir, params[0]);
        if (!p.flags.is_rest or p.type_annotation == hir_mod.none_node_id) return false;
        if (self.typeNodeLooksAnyArray(p.type_annotation)) return true;
        const param_t = self.hir.typeOf(params[0]);
        if (try self.typeIsAnyArrayForMixinCtor(param_t)) return true;
        const annotation_t = try self.lowererLowerWithTypeParams(p.type_annotation);
        return try self.typeIsAnyArrayForMixinCtor(annotation_t);
    }

    fn returnStatementViolatesGenericRestTuple(self: *Checker, return_node: NodeId, ret_t: TypeId) CheckError!bool {
        const fn_node = self.enclosingFunctionForReturn(return_node) orelse return false;
        if (!self.functionHasGenericRestTupleReturn(fn_node)) return false;
        const fn_t = self.hir.typeOf(fn_node);
        if (fn_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(fn_t).is_signature) return false;
        const expected_t = self.interner.signatureReturn(fn_t) orelse return false;
        if (ret_t != expected_t and try self.returnArrayLiteralMatchesGenericRestTupleAnnotation(return_node, fn_node)) return false;
        return ret_t != expected_t;
    }

    fn returnArrayLiteralMatchesGenericRestTupleAnnotation(
        self: *Checker,
        return_node: NodeId,
        fn_node: NodeId,
    ) CheckError!bool {
        const ret = hir_mod.returnOf(self.hir, return_node);
        if (ret.value == hir_mod.none_node_id or self.hir.kindOf(ret.value) != .array_literal) return false;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.return_type == hir_mod.none_node_id or self.hir.kindOf(f.return_type) != .tuple_type) return false;
        const source_elems = hir_mod.arrayLiteralElements(self.hir, ret.value);
        const target_elems = hir_mod.tupleTypeElements(self.hir, f.return_type);
        if (source_elems.len != target_elems.len) return false;

        for (source_elems, target_elems) |source_elem, raw_target_elem| {
            if (source_elem == hir_mod.none_node_id) return false;
            var target_elem = raw_target_elem;
            if (self.hir.kindOf(target_elem) == .optional_type) {
                target_elem = hir_mod.optionalTypeOf(self.hir, target_elem).operand;
            }
            if (self.hir.kindOf(target_elem) == .rest_type) {
                if (self.hir.kindOf(source_elem) != .spread) return false;
                const sp = hir_mod.spreadOf(self.hir, source_elem);
                const spread_t = if (self.hir.typeOf(sp.expression) != types.Primitive.none)
                    self.hir.typeOf(sp.expression)
                else
                    try self.checkExpression(sp.expression);
                const target_t = try self.tupleRestAnnotationSegmentType(target_elem);
                if (!try self.spreadExpressionSegmentAssignableToTupleRest(spread_t, target_t)) return false;
                continue;
            }

            if (self.hir.kindOf(source_elem) == .spread) return false;
            const target_t = try self.lowererLowerWithTypeParams(target_elem);
            if (try self.literalExpressionAssignableToTarget(source_elem, target_t)) continue;
            var source_t = self.hir.typeOf(source_elem);
            if (source_t == types.Primitive.none) source_t = try self.checkExpression(source_elem);
            if (!(try self.checkerAssignableExpressionTo(source_elem, source_t, target_t))) return false;
        }
        return true;
    }

    fn tupleRestAnnotationSegmentType(self: *Checker, rest_node: NodeId) CheckError!TypeId {
        const rt = hir_mod.restTypeOf(self.hir, rest_node);
        if (self.hir.kindOf(rt.operand) == .array_type) {
            return try self.lowererLowerWithTypeParams(hir_mod.arrayTypeOf(self.hir, rt.operand).element);
        }
        return try self.lowererLowerWithTypeParams(rt.operand);
    }

    fn spreadExpressionSegmentAssignableToTupleRest(
        self: *Checker,
        spread_t: TypeId,
        target_segment_t: TypeId,
    ) CheckError!bool {
        if (spread_t == target_segment_t) return true;
        if (spread_t >= self.interner.pool.typeCount()) return false;
        const spread_flags = self.interner.pool.flagsOf(spread_t);
        if (spread_flags.is_type_parameter) {
            return self.engine.isAssignableTo(spread_t, target_segment_t) catch return error.OutOfMemory;
        }
        if (!spread_flags.is_object_type) return false;
        const number_idx = self.interner.objectNumberIndex(spread_t);
        if (number_idx == types.Primitive.none) return false;
        if (number_idx == target_segment_t) return true;
        return self.engine.isAssignableTo(number_idx, target_segment_t) catch return error.OutOfMemory;
    }

    /// Render the function-return-type AST node verbatim from source.
    /// Returns `null` when source is unavailable or the span is OOB.
    fn allocVariadicTupleReturnAnnotationName(self: *Checker, ret_type_node: NodeId) ?[]const u8 {
        if (ret_type_node == hir_mod.none_node_id) return null;
        const src = self.source orelse return null;
        const sp = self.hir.spanOf(ret_type_node);
        if (sp.start >= sp.end or sp.end > src.len) return null;
        const slice = src[sp.start..sp.end];
        // Compact whitespace so multi-line annotations render single-line.
        const arena = self.diag_arena.allocator();
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        buf.ensureTotalCapacity(arena, slice.len) catch return null;
        var prev_space: bool = false;
        for (slice) |c| {
            const is_ws = c == ' ' or c == '\t' or c == '\n' or c == '\r';
            if (is_ws) {
                if (!prev_space and buf.items.len > 0) {
                    buf.append(arena, ' ') catch return null;
                    prev_space = true;
                }
            } else {
                buf.append(arena, c) catch return null;
                prev_space = false;
            }
        }
        while (buf.items.len > 0 and buf.items[buf.items.len - 1] == ' ') {
            buf.items.len -= 1;
        }
        if (buf.items.len == 0) return null;
        return buf.items;
    }

    /// Build `Type 'X' is not assignable to type '[...T, ...P]'.` for
    /// variadic-rest-tuple return mismatches. Returns `null` when any
    /// renderer step fails so the caller can fall back to the generic
    /// message.
    fn allocReturnVariadicRestMismatch(self: *Checker, return_node: NodeId, ret_t: TypeId) !?[]const u8 {
        const fn_node = self.enclosingFunctionForReturn(return_node) orelse return null;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        const target_name = self.allocVariadicTupleReturnAnnotationName(f.return_type) orelse return null;
        const source_name = (try self.allocSimpleTypeName(ret_t)) orelse return null;
        return try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' is not assignable to type '{s}'.",
            .{ source_name, target_name },
        );
    }

    fn enclosingFunctionForReturn(self: *Checker, return_node: NodeId) ?NodeId {
        var cur = self.hir.parentOf(return_node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) return cur;
        }
        return null;
    }

    /// True when `node`'s nearest enclosing function-like node has
    /// `is_generator` set. Used by `.yield_expr` to detect when the
    /// parser already raised TS1163 (yield outside generator) so the
    /// checker can suppress cascading TS2304/TS2363 noise from the
    /// operand. Stops at the first function-like ancestor so an outer
    /// generator wrapping a non-generator inner fn doesn't mask the
    /// inner's invalid-yield context.
    fn isInsideGeneratorFunction(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                const f = hir_mod.fnDeclOf(self.hir, cur);
                return f.flags.is_generator;
            }
        }
        return false;
    }

    fn isInsideAsyncGeneratorFunction(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                const f = hir_mod.fnDeclOf(self.hir, cur);
                return f.flags.is_generator and f.flags.is_async;
            }
        }
        return false;
    }

    fn functionHasGenericRestTupleReturn(self: *Checker, fn_node: NodeId) bool {
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.return_type == hir_mod.none_node_id or self.hir.kindOf(f.return_type) != .tuple_type) return false;
        var saw_generic_rest = false;
        for (hir_mod.tupleTypeElements(self.hir, f.return_type)) |elem| {
            if (self.hir.kindOf(elem) != .rest_type) continue;
            const rt = hir_mod.restTypeOf(self.hir, elem);
            const operand = if (self.hir.kindOf(rt.operand) == .array_type)
                hir_mod.arrayTypeOf(self.hir, rt.operand).element
            else
                rt.operand;
            if (self.typeNodeNamesFunctionTypeParameter(operand, fn_node)) {
                saw_generic_rest = true;
                continue;
            }
            const operand_t = self.hir.typeOf(operand);
            if (operand_t >= self.interner.pool.typeCount()) continue;
            if (self.interner.pool.flagsOf(operand_t).is_type_parameter) saw_generic_rest = true;
        }
        return saw_generic_rest;
    }

    fn typeNodeNamesFunctionTypeParameter(self: *Checker, type_node: NodeId, fn_node: NodeId) bool {
        if (type_node == hir_mod.none_node_id or self.hir.kindOf(type_node) != .type_ref) return false;
        const r = hir_mod.typeRefOf(self.hir, type_node);
        for (hir_mod.fnTypeParams(self.hir, fn_node)) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            if (hir_mod.typeParameterOf(self.hir, tp).name == r.name) return true;
        }
        return false;
    }

    /// Walk a node tree collecting the types of every `return value`
    /// statement reachable from `node`, but stop at any nested
    /// function boundary so inner-fn returns don't leak into the
    /// outer signature.
    fn fnBodyHasReturnValueSyntax(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(node)) {
            .return_stmt => hir_mod.returnOf(self.hir, node).value != hir_mod.none_node_id,
            .fn_decl, .fn_expr, .arrow_fn => false,
            .block_stmt => blk: {
                for (hir_mod.blockStmts(self.hir, node)) |s| {
                    if (self.fnBodyHasReturnValueSyntax(s)) break :blk true;
                }
                break :blk false;
            },
            .if_stmt => blk: {
                const i = hir_mod.ifOf(self.hir, node);
                break :blk self.fnBodyHasReturnValueSyntax(i.then_branch) or
                    self.fnBodyHasReturnValueSyntax(i.else_branch);
            },
            .while_stmt => self.fnBodyHasReturnValueSyntax(hir_mod.whileOf(self.hir, node).body),
            .do_while_stmt => self.fnBodyHasReturnValueSyntax(hir_mod.doWhileOf(self.hir, node).body),
            .for_stmt => self.fnBodyHasReturnValueSyntax(hir_mod.forStmtOf(self.hir, node).body),
            .try_stmt => blk: {
                const ts = hir_mod.tryOf(self.hir, node);
                break :blk self.fnBodyHasReturnValueSyntax(ts.block) or
                    self.fnBodyHasReturnValueSyntax(ts.catch_block) or
                    self.fnBodyHasReturnValueSyntax(ts.finally_block);
            },
            .switch_stmt => blk: {
                for (hir_mod.switchCases(self.hir, node)) |case| {
                    if (self.fnBodyHasReturnValueSyntax(case)) break :blk true;
                }
                break :blk false;
            },
            .switch_case => blk: {
                for (hir_mod.switchCaseStmts(self.hir, node)) |s| {
                    if (self.fnBodyHasReturnValueSyntax(s)) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
    }

    fn collectReturnTypes(
        self: *Checker,
        node: NodeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        const k = self.hir.kindOf(node);
        switch (k) {
            .return_stmt => {
                const r = hir_mod.returnOf(self.hir, node);
                if (r.value != hir_mod.none_node_id) {
                    try out.append(self.gpa, self.hir.typeOf(r.value));
                }
            },
            // Don't descend into nested functions ÃÂ¢ÃÂÃÂ their returns
            // bind to their own signature.
            .fn_decl, .fn_expr, .arrow_fn => return,
            else => {
                // Walk every child of this node. The HIR exposes
                // a generic per-payload accessor pattern; here we
                // just iterate all child nodes via `forEachChild`.
                try self.forEachChildCollect(node, out);
            },
        }
    }

    fn checkDeclarationInferredReturnCyclicStructure(self: *Checker, fn_node: NodeId) CheckError!void {
        if (!self.strict_flags.declaration) return;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.return_type != hir_mod.none_node_id) return;
        if (f.name == hir_mod.none_node_id) return;
        if (self.diagnosticExists(f.name, TsCodes.inferred_type_cyclic_structure)) return;
        var returns: std.ArrayListUnmanaged(NodeId) = .empty;
        defer returns.deinit(self.gpa);
        try self.collectReturnExpressions(f.body, &returns);
        for (returns.items) |expr| {
            if (!self.returnExpressionReferencesCyclicSerializationAlias(expr)) continue;
            const name = if (self.hir.kindOf(f.name) == .identifier)
                self.string_interner.get(hir_mod.identifierOf(self.hir, f.name).name)
            else
                "(Missing)";
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "The inferred type of '{s}' references a type with a cyclic structure which cannot be trivially serialized. A type annotation is necessary.",
                .{name},
            );
            try self.report(f.name, TsCodes.inferred_type_cyclic_structure, msg);
            return;
        }
    }

    fn collectReturnExpressions(
        self: *Checker,
        node: NodeId,
        out: *std.ArrayListUnmanaged(NodeId),
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .return_stmt => {
                const r = hir_mod.returnOf(self.hir, node);
                if (r.value != hir_mod.none_node_id) try out.append(self.gpa, r.value);
            },
            .fn_decl, .fn_expr, .arrow_fn => return,
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |s| try self.collectReturnExpressions(s, out);
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                try self.collectReturnExpressions(i.then_branch, out);
                try self.collectReturnExpressions(i.else_branch, out);
            },
            .while_stmt => try self.collectReturnExpressions(hir_mod.whileOf(self.hir, node).body, out),
            .do_while_stmt => try self.collectReturnExpressions(hir_mod.doWhileOf(self.hir, node).body, out),
            .for_stmt => try self.collectReturnExpressions(hir_mod.forStmtOf(self.hir, node).body, out),
            .for_in_stmt, .for_of_stmt => try self.collectReturnExpressions(hir_mod.forInOf(self.hir, node).body, out),
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                try self.collectReturnExpressions(ts.block, out);
                try self.collectReturnExpressions(ts.catch_block, out);
                try self.collectReturnExpressions(ts.finally_block, out);
            },
            .switch_stmt => {
                for (hir_mod.switchCases(self.hir, node)) |case| try self.collectReturnExpressions(case, out);
            },
            .switch_case => {
                for (hir_mod.switchCaseStmts(self.hir, node)) |s| try self.collectReturnExpressions(s, out);
            },
            else => {},
        }
    }

    fn literalPreservingFunctionReturnType(self: *Checker, body: NodeId, fallback: TypeId) CheckError!TypeId {
        var expressions: std.ArrayListUnmanaged(NodeId) = .empty;
        defer expressions.deinit(self.gpa);
        try self.collectReturnExpressions(body, &expressions);
        if (expressions.items.len == 0) return fallback;

        var return_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer return_types.deinit(self.gpa);
        for (expressions.items) |expr| {
            const expression_t = self.hir.typeOf(expr);
            try return_types.append(self.gpa, try self.valueNodeLiteralType(expr, expression_t));
        }
        if (return_types.items.len == 1) return return_types.items[0];
        return self.interner.internUnion(return_types.items) catch return error.OutOfMemory;
    }

    fn functionBodyReturnsOnlyDirectSelfCalls(
        self: *Checker,
        body: NodeId,
        name: hir_mod.StringId,
    ) CheckError!bool {
        var returns: std.ArrayListUnmanaged(NodeId) = .empty;
        defer returns.deinit(self.gpa);
        try self.collectReturnExpressions(body, &returns);
        if (returns.items.len == 0) return false;
        for (returns.items) |expr| {
            if (!self.returnExpressionIsDirectSelfCall(expr, name)) return false;
        }
        return true;
    }

    fn returnExpressionIsDirectSelfCall(self: *Checker, expr: NodeId, name: hir_mod.StringId) bool {
        if (expr == hir_mod.none_node_id or self.hir.kindOf(expr) != .call_expr) return false;
        const c = hir_mod.callOf(self.hir, expr);
        if (c.callee == hir_mod.none_node_id or self.hir.kindOf(c.callee) != .identifier) return false;
        return hir_mod.identifierOf(self.hir, c.callee).name == name;
    }

    fn returnExpressionReferencesCyclicSerializationAlias(self: *Checker, expr: NodeId) bool {
        if (expr == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(expr)) {
            .call_expr => blk: {
                const call = hir_mod.callOf(self.hir, expr);
                if (self.hir.kindOf(call.callee) != .identifier) break :blk false;
                const callee_name = hir_mod.identifierOf(self.hir, call.callee).name;
                const fn_decl = self.findFunctionDeclForNameNearNode(expr, callee_name) orelse break :blk false;
                const f = hir_mod.fnDeclOf(self.hir, fn_decl);
                break :blk self.typeNodeReferencesCyclicSerializationAlias(f.return_type, 0);
            },
            .as_expr, .type_assertion, .satisfies_expr, .non_null_expr => blk: {
                const a = hir_mod.asExpressionOf(self.hir, expr);
                break :blk self.returnExpressionReferencesCyclicSerializationAlias(a.expr);
            },
            else => false,
        };
    }

    fn typeNodeReferencesCyclicSerializationAlias(self: *Checker, type_node: NodeId, depth: u8) bool {
        if (type_node == hir_mod.none_node_id or depth > 64) return false;
        return switch (self.hir.kindOf(type_node)) {
            .type_ref => blk: {
                const r = hir_mod.typeRefOf(self.hir, type_node);
                if (r.qualifier_len == 0) {
                    if (self.generic_aliases.get(r.name)) |info| {
                        if (self.genericAliasBodyHasCyclicSerializationShape(info.body_node, r.name)) break :blk true;
                    }
                }
                for (hir_mod.typeRefArgs(self.hir, type_node)) |arg| {
                    if (self.typeNodeReferencesCyclicSerializationAlias(arg, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .array_type => self.typeNodeReferencesCyclicSerializationAlias(hir_mod.arrayTypeOf(self.hir, type_node).element, depth + 1),
            .readonly_type => self.typeNodeReferencesCyclicSerializationAlias(hir_mod.readonlyTypeOf(self.hir, type_node).operand, depth + 1),
            .optional_type => self.typeNodeReferencesCyclicSerializationAlias(hir_mod.optionalTypeOf(self.hir, type_node).operand, depth + 1),
            .rest_type => self.typeNodeReferencesCyclicSerializationAlias(hir_mod.restTypeOf(self.hir, type_node).operand, depth + 1),
            .keyof_type => self.typeNodeReferencesCyclicSerializationAlias(hir_mod.keyofTypeOf(self.hir, type_node).operand, depth + 1),
            .indexed_access_type => blk: {
                const ia = hir_mod.indexedAccessTypeOf(self.hir, type_node);
                break :blk self.typeNodeReferencesCyclicSerializationAlias(ia.object, depth + 1) or
                    self.typeNodeReferencesCyclicSerializationAlias(ia.index, depth + 1);
            },
            .conditional_type => blk: {
                const c = hir_mod.conditionalTypeOf(self.hir, type_node);
                break :blk self.typeNodeReferencesCyclicSerializationAlias(c.check, depth + 1) or
                    self.typeNodeReferencesCyclicSerializationAlias(c.extends, depth + 1) or
                    self.typeNodeReferencesCyclicSerializationAlias(c.true_branch, depth + 1) or
                    self.typeNodeReferencesCyclicSerializationAlias(c.false_branch, depth + 1);
            },
            .union_type => blk: {
                for (hir_mod.unionTypeMembers(self.hir, type_node)) |member| {
                    if (self.typeNodeReferencesCyclicSerializationAlias(member, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .intersection_type => blk: {
                for (hir_mod.intersectionTypeMembers(self.hir, type_node)) |member| {
                    if (self.typeNodeReferencesCyclicSerializationAlias(member, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .tuple_type => blk: {
                for (hir_mod.tupleTypeElements(self.hir, type_node)) |member| {
                    if (self.typeNodeReferencesCyclicSerializationAlias(member, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .fn_type, .constructor_type => blk: {
                const ft = hir_mod.fnTypeOf(self.hir, type_node);
                for (self.hir.childSlice(ft.params_start, ft.params_len)) |param| {
                    if (self.hir.kindOf(param) != .parameter) continue;
                    const p = hir_mod.parameterOf(self.hir, param);
                    if (self.typeNodeReferencesCyclicSerializationAlias(p.type_annotation, depth + 1)) break :blk true;
                }
                break :blk self.typeNodeReferencesCyclicSerializationAlias(ft.return_type, depth + 1);
            },
            else => false,
        };
    }

    fn genericAliasBodyHasCyclicSerializationShape(self: *Checker, body_node: NodeId, alias_name: hir_mod.StringId) bool {
        if (body_node == hir_mod.none_node_id) return false;
        if (!self.typeNodeSourceLooksLikeCyclicSerializationBody(body_node)) return false;
        return self.typeNodeContainsAliasReferenceDeep(body_node, alias_name, 0) and
            self.typeNodeContainsConditionalOrIndexedAccess(body_node, 0);
    }

    fn typeNodeSourceLooksLikeCyclicSerializationBody(self: *Checker, node: NodeId) bool {
        const src = self.source orelse return true;
        const sp = self.hir.spanOf(node);
        if (sp.start >= sp.end or sp.end > src.len) return true;
        const text = src[sp.start..sp.end];
        return std.mem.indexOf(u8, text, "extends") != null and
            std.mem.indexOfScalar(u8, text, '[') != null;
    }

    fn typeNodeContainsAliasReferenceDeep(self: *Checker, node: NodeId, alias_name: hir_mod.StringId, depth: u8) bool {
        if (node == hir_mod.none_node_id or depth > 64) return false;
        return switch (self.hir.kindOf(node)) {
            .type_ref => blk: {
                const r = hir_mod.typeRefOf(self.hir, node);
                if (r.qualifier_len == 0 and r.name == alias_name) break :blk true;
                for (hir_mod.typeRefArgs(self.hir, node)) |arg| {
                    if (self.typeNodeContainsAliasReferenceDeep(arg, alias_name, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .object_type => blk: {
                for (hir_mod.objectTypeMembers(self.hir, node)) |member| {
                    if (self.hir.kindOf(member) != .interface_member) continue;
                    const im = hir_mod.interfaceMemberOf(self.hir, member);
                    if (self.typeNodeContainsAliasReferenceDeep(im.type_node, alias_name, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .array_type => self.typeNodeContainsAliasReferenceDeep(hir_mod.arrayTypeOf(self.hir, node).element, alias_name, depth + 1),
            .readonly_type => self.typeNodeContainsAliasReferenceDeep(hir_mod.readonlyTypeOf(self.hir, node).operand, alias_name, depth + 1),
            .optional_type => self.typeNodeContainsAliasReferenceDeep(hir_mod.optionalTypeOf(self.hir, node).operand, alias_name, depth + 1),
            .rest_type => self.typeNodeContainsAliasReferenceDeep(hir_mod.restTypeOf(self.hir, node).operand, alias_name, depth + 1),
            .keyof_type => self.typeNodeContainsAliasReferenceDeep(hir_mod.keyofTypeOf(self.hir, node).operand, alias_name, depth + 1),
            .indexed_access_type => blk: {
                const ia = hir_mod.indexedAccessTypeOf(self.hir, node);
                break :blk self.typeNodeContainsAliasReferenceDeep(ia.object, alias_name, depth + 1) or
                    self.typeNodeContainsAliasReferenceDeep(ia.index, alias_name, depth + 1);
            },
            .conditional_type => blk: {
                const c = hir_mod.conditionalTypeOf(self.hir, node);
                break :blk self.typeNodeContainsAliasReferenceDeep(c.check, alias_name, depth + 1) or
                    self.typeNodeContainsAliasReferenceDeep(c.extends, alias_name, depth + 1) or
                    self.typeNodeContainsAliasReferenceDeep(c.true_branch, alias_name, depth + 1) or
                    self.typeNodeContainsAliasReferenceDeep(c.false_branch, alias_name, depth + 1);
            },
            .union_type => blk: {
                for (hir_mod.unionTypeMembers(self.hir, node)) |member| {
                    if (self.typeNodeContainsAliasReferenceDeep(member, alias_name, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .intersection_type => blk: {
                for (hir_mod.intersectionTypeMembers(self.hir, node)) |member| {
                    if (self.typeNodeContainsAliasReferenceDeep(member, alias_name, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .tuple_type => blk: {
                for (hir_mod.tupleTypeElements(self.hir, node)) |member| {
                    if (self.typeNodeContainsAliasReferenceDeep(member, alias_name, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .fn_type, .constructor_type => blk: {
                const ft = hir_mod.fnTypeOf(self.hir, node);
                for (self.hir.childSlice(ft.params_start, ft.params_len)) |param| {
                    if (self.hir.kindOf(param) != .parameter) continue;
                    const p = hir_mod.parameterOf(self.hir, param);
                    if (self.typeNodeContainsAliasReferenceDeep(p.type_annotation, alias_name, depth + 1)) break :blk true;
                }
                break :blk self.typeNodeContainsAliasReferenceDeep(ft.return_type, alias_name, depth + 1);
            },
            else => false,
        };
    }

    fn typeNodeContainsAliasReferenceInConditionalAliasArgument(
        self: *Checker,
        node: NodeId,
        alias_name: hir_mod.StringId,
        depth: u8,
    ) bool {
        if (node == hir_mod.none_node_id or depth > 64) return false;
        return switch (self.hir.kindOf(node)) {
            .type_ref => blk: {
                const ref = hir_mod.typeRefOf(self.hir, node);
                const args = hir_mod.typeRefArgs(self.hir, node);
                if (args.len > 0) {
                    if (self.findTypeAliasDeclInScope(node, ref.name)) |decl| {
                        const alias = hir_mod.typeAliasOf(self.hir, decl);
                        if (self.hir.kindOf(alias.aliased) == .conditional_type) {
                            for (args) |arg| {
                                if (self.typeNodeContainsAliasReferenceDeep(arg, alias_name, depth + 1)) {
                                    break :blk true;
                                }
                            }
                        }
                    }
                }
                for (args) |arg| {
                    if (self.typeNodeContainsAliasReferenceInConditionalAliasArgument(arg, alias_name, depth + 1)) {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            .object_type => blk: {
                for (hir_mod.objectTypeMembers(self.hir, node)) |member| {
                    if (self.hir.kindOf(member) != .interface_member) continue;
                    const im = hir_mod.interfaceMemberOf(self.hir, member);
                    if (self.typeNodeContainsAliasReferenceInConditionalAliasArgument(im.type_node, alias_name, depth + 1)) {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            .array_type => self.typeNodeContainsAliasReferenceInConditionalAliasArgument(
                hir_mod.arrayTypeOf(self.hir, node).element,
                alias_name,
                depth + 1,
            ),
            .readonly_type => self.typeNodeContainsAliasReferenceInConditionalAliasArgument(
                hir_mod.readonlyTypeOf(self.hir, node).operand,
                alias_name,
                depth + 1,
            ),
            .optional_type => self.typeNodeContainsAliasReferenceInConditionalAliasArgument(
                hir_mod.optionalTypeOf(self.hir, node).operand,
                alias_name,
                depth + 1,
            ),
            .rest_type => self.typeNodeContainsAliasReferenceInConditionalAliasArgument(
                hir_mod.restTypeOf(self.hir, node).operand,
                alias_name,
                depth + 1,
            ),
            .keyof_type => self.typeNodeContainsAliasReferenceInConditionalAliasArgument(
                hir_mod.keyofTypeOf(self.hir, node).operand,
                alias_name,
                depth + 1,
            ),
            .indexed_access_type => blk: {
                const indexed = hir_mod.indexedAccessTypeOf(self.hir, node);
                break :blk self.typeNodeContainsAliasReferenceInConditionalAliasArgument(indexed.object, alias_name, depth + 1) or
                    self.typeNodeContainsAliasReferenceInConditionalAliasArgument(indexed.index, alias_name, depth + 1);
            },
            .conditional_type => blk: {
                const conditional = hir_mod.conditionalTypeOf(self.hir, node);
                break :blk self.typeNodeContainsAliasReferenceInConditionalAliasArgument(conditional.check, alias_name, depth + 1) or
                    self.typeNodeContainsAliasReferenceInConditionalAliasArgument(conditional.extends, alias_name, depth + 1) or
                    self.typeNodeContainsAliasReferenceInConditionalAliasArgument(conditional.true_branch, alias_name, depth + 1) or
                    self.typeNodeContainsAliasReferenceInConditionalAliasArgument(conditional.false_branch, alias_name, depth + 1);
            },
            .union_type => blk: {
                for (hir_mod.unionTypeMembers(self.hir, node)) |member| {
                    if (self.typeNodeContainsAliasReferenceInConditionalAliasArgument(member, alias_name, depth + 1)) {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            .intersection_type => blk: {
                for (hir_mod.intersectionTypeMembers(self.hir, node)) |member| {
                    if (self.typeNodeContainsAliasReferenceInConditionalAliasArgument(member, alias_name, depth + 1)) {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            .tuple_type => blk: {
                for (hir_mod.tupleTypeElements(self.hir, node)) |member| {
                    if (self.typeNodeContainsAliasReferenceInConditionalAliasArgument(member, alias_name, depth + 1)) {
                        break :blk true;
                    }
                }
                break :blk false;
            },
            else => false,
        };
    }

    fn typeNodeContainsConditionalOrIndexedAccess(self: *Checker, node: NodeId, depth: u8) bool {
        if (node == hir_mod.none_node_id or depth > 64) return false;
        return switch (self.hir.kindOf(node)) {
            .conditional_type, .indexed_access_type => true,
            .object_type => blk: {
                for (hir_mod.objectTypeMembers(self.hir, node)) |member| {
                    if (self.hir.kindOf(member) != .interface_member) continue;
                    const im = hir_mod.interfaceMemberOf(self.hir, member);
                    if (self.typeNodeContainsConditionalOrIndexedAccess(im.type_node, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .type_ref => blk: {
                for (hir_mod.typeRefArgs(self.hir, node)) |arg| {
                    if (self.typeNodeContainsConditionalOrIndexedAccess(arg, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .array_type => self.typeNodeContainsConditionalOrIndexedAccess(hir_mod.arrayTypeOf(self.hir, node).element, depth + 1),
            .readonly_type => self.typeNodeContainsConditionalOrIndexedAccess(hir_mod.readonlyTypeOf(self.hir, node).operand, depth + 1),
            .optional_type => self.typeNodeContainsConditionalOrIndexedAccess(hir_mod.optionalTypeOf(self.hir, node).operand, depth + 1),
            .rest_type => self.typeNodeContainsConditionalOrIndexedAccess(hir_mod.restTypeOf(self.hir, node).operand, depth + 1),
            .keyof_type => self.typeNodeContainsConditionalOrIndexedAccess(hir_mod.keyofTypeOf(self.hir, node).operand, depth + 1),
            .union_type => blk: {
                for (hir_mod.unionTypeMembers(self.hir, node)) |member| {
                    if (self.typeNodeContainsConditionalOrIndexedAccess(member, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .intersection_type => blk: {
                for (hir_mod.intersectionTypeMembers(self.hir, node)) |member| {
                    if (self.typeNodeContainsConditionalOrIndexedAccess(member, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .tuple_type => blk: {
                for (hir_mod.tupleTypeElements(self.hir, node)) |member| {
                    if (self.typeNodeContainsConditionalOrIndexedAccess(member, depth + 1)) break :blk true;
                }
                break :blk false;
            },
            .fn_type, .constructor_type => blk: {
                const ft = hir_mod.fnTypeOf(self.hir, node);
                for (self.hir.childSlice(ft.params_start, ft.params_len)) |param| {
                    if (self.hir.kindOf(param) != .parameter) continue;
                    const p = hir_mod.parameterOf(self.hir, param);
                    if (self.typeNodeContainsConditionalOrIndexedAccess(p.type_annotation, depth + 1)) break :blk true;
                }
                break :blk self.typeNodeContainsConditionalOrIndexedAccess(ft.return_type, depth + 1);
            },
            else => false,
        };
    }

    fn firstReturnExpressionType(self: *Checker, node: NodeId) CheckError!?TypeId {
        if (node == hir_mod.none_node_id) return null;
        switch (self.hir.kindOf(node)) {
            .return_stmt => {
                const r = hir_mod.returnOf(self.hir, node);
                if (r.value == hir_mod.none_node_id) return types.Primitive.void_t;
                return try self.checkExpression(r.value);
            },
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |s| {
                    if (try self.firstReturnExpressionType(s)) |t| return t;
                }
                return null;
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                if (try self.firstReturnExpressionType(i.then_branch)) |t| return t;
                return try self.firstReturnExpressionType(i.else_branch);
            },
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                if (try self.firstReturnExpressionType(ts.block)) |t| return t;
                if (try self.firstReturnExpressionType(ts.catch_block)) |t| return t;
                return try self.firstReturnExpressionType(ts.finally_block);
            },
            .fn_decl, .fn_expr, .arrow_fn => return null,
            else => return null,
        }
    }

    fn firstReturnExpressionTypeWithClassValue(
        self: *Checker,
        node: NodeId,
        class_node: NodeId,
        class_key: ?hir_mod.StringId,
        static_this_t: TypeId,
    ) CheckError!?TypeId {
        if (node == hir_mod.none_node_id) return null;
        const binding_name: ?hir_mod.StringId = blk: {
            if (!self.classNodeIsExpression(class_node)) break :blk null;
            const anchor = self.classExpressionBindingAnchor(class_node);
            if (anchor != class_node and self.hir.kindOf(anchor) == .identifier) {
                break :blk hir_mod.identifierOf(self.hir, anchor).name;
            }
            break :blk null;
        };
        const is_class_value_name = struct {
            fn run(name: hir_mod.StringId, key: ?hir_mod.StringId, binding: ?hir_mod.StringId) bool {
                if (key != null and name == key.?) return true;
                if (binding != null and name == binding.?) return true;
                return false;
            }
        }.run;
        switch (self.hir.kindOf(node)) {
            .return_stmt => {
                const r = hir_mod.returnOf(self.hir, node);
                if (r.value == hir_mod.none_node_id) return types.Primitive.void_t;
                if (static_this_t != types.Primitive.none and self.hir.kindOf(r.value) == .identifier) {
                    const id = hir_mod.identifierOf(self.hir, r.value);
                    if (is_class_value_name(id.name, class_key, binding_name)) return static_this_t;
                }
                if (self.hir.kindOf(r.value) == .new_expr) {
                    const call = hir_mod.callOf(self.hir, r.value);
                    if (self.hir.kindOf(call.callee) == .identifier) {
                        const id = hir_mod.identifierOf(self.hir, call.callee);
                        if (is_class_value_name(id.name, class_key, binding_name)) {
                            if (self.class_instance_types.get(id.name)) |inst| return inst;
                            if (class_key) |key| {
                                if (self.class_instance_types.get(key)) |inst| return inst;
                            }
                        }
                    }
                }
                return try self.checkExpression(r.value);
            },
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |s| {
                    if (try self.firstReturnExpressionTypeWithClassValue(s, class_node, class_key, static_this_t)) |t| return t;
                }
                return null;
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                if (try self.firstReturnExpressionTypeWithClassValue(i.then_branch, class_node, class_key, static_this_t)) |t| return t;
                return try self.firstReturnExpressionTypeWithClassValue(i.else_branch, class_node, class_key, static_this_t);
            },
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                if (try self.firstReturnExpressionTypeWithClassValue(ts.block, class_node, class_key, static_this_t)) |t| return t;
                if (try self.firstReturnExpressionTypeWithClassValue(ts.catch_block, class_node, class_key, static_this_t)) |t| return t;
                return try self.firstReturnExpressionTypeWithClassValue(ts.finally_block, class_node, class_key, static_this_t);
            },
            .fn_decl, .fn_expr, .arrow_fn => return null,
            else => return null,
        }
    }

    fn firstReturnExpressionTypeWithClassMemberThis(
        self: *Checker,
        node: NodeId,
        class_node: NodeId,
        class_key: ?hir_mod.StringId,
        is_static: bool,
        instance_members: []const types.ObjectMember,
        static_members: []const types.ObjectMember,
        string_idx: TypeId,
        number_idx: TypeId,
        symbol_idx: TypeId,
        static_string_idx: TypeId,
        static_number_idx: TypeId,
        static_symbol_idx: TypeId,
        parent_instance_t: ?TypeId,
        parent_static_t: ?TypeId,
    ) CheckError!?TypeId {
        const this_id = self.string_interner.intern("this") catch return error.OutOfMemory;
        const super_id = self.string_interner.intern("super") catch return error.OutOfMemory;
        var merged_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer merged_members.deinit(self.gpa);
        const own_members = if (is_static) static_members else instance_members;
        const inherited_t = if (is_static) parent_static_t else parent_instance_t;
        if (inherited_t) |pt| {
            if (pt < self.interner.pool.typeCount() and self.interner.pool.flagsOf(pt).is_object_type) {
                try merged_members.appendSlice(self.gpa, self.interner.objectMembers(pt));
            }
        }
        try merged_members.appendSlice(self.gpa, own_members);
        const this_string_idx = if (is_static) static_string_idx else string_idx;
        const this_number_idx = if (is_static) static_number_idx else number_idx;
        const this_symbol_idx = if (is_static) static_symbol_idx else symbol_idx;
        const structural_this_t = self.interner.internObjectTypeWithIndexAndSymbol(
            merged_members.items,
            this_string_idx,
            this_number_idx,
            this_symbol_idx,
        ) catch return error.OutOfMemory;
        const this_t = if (is_static) structural_this_t else try self.classThisType(structural_this_t);
        const class_value_t = if (is_static) structural_this_t else blk: {
            var static_merged_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
            defer static_merged_members.deinit(self.gpa);
            if (parent_static_t) |pst| {
                if (pst < self.interner.pool.typeCount() and self.interner.pool.flagsOf(pst).is_object_type) {
                    try static_merged_members.appendSlice(self.gpa, self.interner.objectMembers(pst));
                }
            }
            try static_merged_members.appendSlice(self.gpa, static_members);
            break :blk self.interner.internObjectTypeWithIndexAndSymbol(
                static_merged_members.items,
                static_string_idx,
                static_number_idx,
                static_symbol_idx,
            ) catch return error.OutOfMemory;
        };
        if (class_key) |key| {
            try self.class_name_by_static.put(self.gpa, class_value_t, key);
            if (is_static) {
                const structural_instance_t = self.interner.internObjectTypeWithIndexAndSymbol(
                    instance_members,
                    string_idx,
                    number_idx,
                    symbol_idx,
                ) catch return error.OutOfMemory;
                try self.class_instance_types.put(self.gpa, key, structural_instance_t);
                try self.class_name_by_instance.put(self.gpa, structural_instance_t, key);
                try self.seedClassExpressionBindingClassMaps(class_node, structural_instance_t, structural_this_t);
            } else {
                try self.class_name_by_instance.put(self.gpa, this_t, key);
            }
        }
        try self.pushNarrowScope();
        defer self.popNarrowScope();
        try self.recordNarrow(this_id, this_t);
        const super_t = if (is_static) parent_static_t else parent_instance_t;
        if (super_t) |st| try self.recordNarrow(super_id, st);
        // This is a SPECULATIVE return-type inference walk: `this_t` is built
        // from the members processed so far, so a self-referential
        // `return this.thisMethod` (the method being inferred isn't in the
        // partial member set yet) would make `checkExpression` emit a
        // spurious TS2339. Discard any diagnostics produced here — the real
        // member-body check runs later with the fully-built class type and
        // reports genuine errors. Pins privateClassPropertyAccessibleWithin*,
        // protectedClassPropertyAccessibleWithin*, typeOfThisInInstanceMember*.
        const diag_snapshot = self.diagnostics.items.len;
        const inferred = try self.firstReturnExpressionTypeWithClassValue(
            node,
            class_node,
            class_key,
            class_value_t,
        );
        if (self.diagnostics.items.len > diag_snapshot) {
            self.diagnostics.shrinkRetainingCapacity(diag_snapshot);
        }
        return inferred;
    }

    fn forEachChildCollect(
        self: *Checker,
        node: NodeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!void {
        const k = self.hir.kindOf(node);
        switch (k) {
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |s| try self.collectReturnTypes(s, out);
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                try self.collectReturnTypes(i.then_branch, out);
                try self.collectReturnTypes(i.else_branch, out);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                try self.collectReturnTypes(w.body, out);
            },
            .do_while_stmt => {
                const w = hir_mod.doWhileOf(self.hir, node);
                try self.collectReturnTypes(w.body, out);
            },
            .for_stmt => {
                const fr = hir_mod.forStmtOf(self.hir, node);
                try self.collectReturnTypes(fr.body, out);
            },
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                try self.collectReturnTypes(ts.block, out);
                if (ts.catch_block != hir_mod.none_node_id) try self.collectReturnTypes(ts.catch_block, out);
                if (ts.finally_block != hir_mod.none_node_id) try self.collectReturnTypes(ts.finally_block, out);
            },
            .switch_stmt => {
                for (hir_mod.switchCases(self.hir, node)) |case| try self.collectReturnTypes(case, out);
            },
            .switch_case => {
                for (hir_mod.switchCaseStmts(self.hir, node)) |s| try self.collectReturnTypes(s, out);
            },
            else => {},
        }
    }

    fn contextualNextTypeForYield(self: *Checker, yield_node: NodeId) ?TypeId {
        const fn_node = self.enclosingFunctionLike(yield_node) orelse return null;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (!f.flags.is_generator) return null;
        // Async generators are contextually typed by AsyncIterator /
        // AsyncGenerator directly, not by Promise<...> like ordinary async
        // functions, so use the unwrapped function return target here.
        const contextual_return = self.contextualReturnTypeForFunction(fn_node) orelse return null;
        if (self.alias_display_names.get(contextual_return)) |display| {
            // Iterable<T> / AsyncIterable<T> describe only yielded values;
            // unlike Iterator/Generator, they have no caller-sent TNext
            // channel to contribute to inference.
            if (std.mem.startsWith(u8, display, "Iterable<") or
                std.mem.startsWith(u8, display, "AsyncIterable<")) return null;
        }
        const next_name = self.string_interner.intern("next") catch return null;
        if (self.interner.objectMember(contextual_return, next_name) == null) return null;
        const info = self.generator_type_info.get(contextual_return) orelse return null;
        return info.next_type;
    }

    /// Walk a node tree collecting the operand types of every
    /// `yield expr` reachable from `node`, but stop at any nested
    /// function boundary so inner-fn yields don't leak into the
    /// outer generator's element type. Used by generator return-type
    /// inference to discover the yield-type T.
    fn collectYieldTypes(
        self: *Checker,
        node: NodeId,
        yield_types: *std.ArrayListUnmanaged(TypeId),
        next_types: *std.ArrayListUnmanaged(TypeId),
        is_async_generator: bool,
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        const k = self.hir.kindOf(node);
        switch (k) {
            .yield_expr => {
                const y = hir_mod.yieldExprOf(self.hir, node);
                if (y.expr != hir_mod.none_node_id) {
                    const expr_t = self.hir.typeOf(y.expr);
                    const yield_t = if (is_async_generator)
                        if (y.type_node == hir_mod.none_node_id)
                            switch (self.promiseLikeResult(expr_t)) {
                                .promised => |promised| promised,
                                .none, .malformed => expr_t,
                            }
                        else blk: {
                            const elem_t = self.iterableElementType(expr_t) catch expr_t;
                            break :blk switch (self.promiseLikeResult(elem_t)) {
                                .promised => |promised| promised,
                                .none, .malformed => elem_t,
                            };
                        }
                    else if (y.type_node != hir_mod.none_node_id)
                        self.iterableElementType(expr_t) catch expr_t
                    else
                        expr_t;
                    try yield_types.append(self.gpa, yield_t);
                    // Upstream only aggregates a direct yield's contextual
                    // type into the generator's TNext slot. `checkExpression`
                    // still gives an uncontextualized `yield` the value type
                    // `any` (and may report TS7057), but that fallback must not
                    // turn the inferred generator from `Generator<..., unknown>`
                    // into `Generator<..., any>`.
                    const next_t = if (y.type_node == hir_mod.none_node_id)
                        if (self.hir.typeOf(node) == types.Primitive.any)
                            self.contextualNextTypeForYield(node) orelse types.Primitive.none
                        else
                            self.hir.typeOf(node)
                    else if (self.generator_type_info.get(expr_t)) |delegated|
                        delegated.next_type
                    else
                        types.Primitive.none;
                    if (next_t != types.Primitive.none) {
                        try next_types.append(self.gpa, next_t);
                    }
                } else {
                    try yield_types.append(self.gpa, types.Primitive.undefined_t);
                    const next_t = if (self.hir.typeOf(node) == types.Primitive.any)
                        self.contextualNextTypeForYield(node) orelse types.Primitive.none
                    else
                        self.hir.typeOf(node);
                    if (next_t != types.Primitive.none) {
                        try next_types.append(self.gpa, next_t);
                    }
                }
            },
            // Don't descend into nested fns ÃÂ¢ÃÂÃÂ their `yield`s belong
            // to that inner generator, not us.
            .fn_decl, .fn_expr, .arrow_fn => return,
            .block_stmt => for (hir_mod.blockStmts(self.hir, node)) |s| try self.collectYieldTypes(s, yield_types, next_types, is_async_generator),
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                try self.collectYieldTypes(i.then_branch, yield_types, next_types, is_async_generator);
                try self.collectYieldTypes(i.else_branch, yield_types, next_types, is_async_generator);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                try self.collectYieldTypes(w.body, yield_types, next_types, is_async_generator);
            },
            .do_while_stmt => {
                const w = hir_mod.doWhileOf(self.hir, node);
                try self.collectYieldTypes(w.body, yield_types, next_types, is_async_generator);
            },
            .for_stmt => {
                const fr = hir_mod.forStmtOf(self.hir, node);
                try self.collectYieldTypes(fr.body, yield_types, next_types, is_async_generator);
            },
            .for_in_stmt, .for_of_stmt => {
                const fr = hir_mod.forInOf(self.hir, node);
                try self.collectYieldTypes(fr.body, yield_types, next_types, is_async_generator);
            },
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                try self.collectYieldTypes(ts.block, yield_types, next_types, is_async_generator);
                if (ts.catch_block != hir_mod.none_node_id) try self.collectYieldTypes(ts.catch_block, yield_types, next_types, is_async_generator);
                if (ts.finally_block != hir_mod.none_node_id) try self.collectYieldTypes(ts.finally_block, yield_types, next_types, is_async_generator);
            },
            .switch_stmt => {
                for (hir_mod.switchCases(self.hir, node)) |case| try self.collectYieldTypes(case, yield_types, next_types, is_async_generator);
            },
            .switch_case => {
                for (hir_mod.switchCaseStmts(self.hir, node)) |s| try self.collectYieldTypes(s, yield_types, next_types, is_async_generator);
            },
            else => {},
        }
    }

    fn reportImplicitAnyYieldOperands(self: *Checker, node: NodeId) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .yield_expr => {
                const y = hir_mod.yieldExprOf(self.hir, node);
                if (y.expr != hir_mod.none_node_id) {
                    var reported = false;
                    if (self.hir.kindOf(y.expr) == .yield_expr) {
                        const inner = hir_mod.yieldExprOf(self.hir, y.expr);
                        if (inner.expr == hir_mod.none_node_id) {
                            try self.report(y.expr, TsCodes.yield_implicit_any, "'yield' expression implicitly results in an 'any' type because its containing generator lacks a return-type annotation.");
                            reported = true;
                        }
                    } else if (self.hir.kindOf(y.expr) == .identifier) {
                        // tsc fires TS7057 on `yield <ident>` when
                        // <ident> resolves to an implicitly-any type
                        // (e.g. `var o; o = yield o`). Skip unresolved
                        // identifiers ÃÂ¢ÃÂÃÂ TS2304 already covers them.
                        const expr_t = self.hir.typeOf(y.expr);
                        if ((self.typeIsAny(expr_t) or self.yieldOperandIsImplicitAnyIdentifier(y.expr)) and
                            !self.yieldOperandIsUnresolvedIdentifier(y.expr))
                        {
                            try self.report(node, TsCodes.yield_implicit_any, "'yield' expression implicitly results in an 'any' type because its containing generator lacks a return-type annotation.");
                            reported = true;
                        }
                    }
                    if (!reported and self.yieldCallArgumentLacksConcreteContext(node)) {
                        try self.report(node, TsCodes.yield_implicit_any, "'yield' expression implicitly results in an 'any' type because its containing generator lacks a return-type annotation.");
                    }
                    try self.reportImplicitAnyYieldOperands(y.expr);
                }
            },
            .fn_decl, .fn_expr, .arrow_fn => return,
            .block_stmt => for (hir_mod.blockStmts(self.hir, node)) |s| try self.reportImplicitAnyYieldOperands(s),
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(i.cond);
                try self.reportImplicitAnyYieldOperands(i.then_branch);
                try self.reportImplicitAnyYieldOperands(i.else_branch);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(w.cond);
                try self.reportImplicitAnyYieldOperands(w.body);
            },
            .do_while_stmt => {
                const w = hir_mod.doWhileOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(w.cond);
                try self.reportImplicitAnyYieldOperands(w.body);
            },
            .for_stmt => {
                const fr = hir_mod.forStmtOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(fr.init);
                try self.reportImplicitAnyYieldOperands(fr.cond);
                try self.reportImplicitAnyYieldOperands(fr.update);
                try self.reportImplicitAnyYieldOperands(fr.body);
            },
            .for_in_stmt, .for_of_stmt => {
                const fr = hir_mod.forInOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(fr.target);
                try self.reportImplicitAnyYieldOperands(fr.source);
                try self.reportImplicitAnyYieldOperands(fr.body);
            },
            .return_stmt => try self.reportImplicitAnyYieldOperands(hir_mod.returnOf(self.hir, node).value),
            .var_decl, .let_decl, .const_decl => try self.reportImplicitAnyYieldOperands(hir_mod.varDeclOf(self.hir, node).init),
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(b.lhs);
                try self.reportImplicitAnyYieldOperands(b.rhs);
            },
            .unary_op => try self.reportImplicitAnyYieldOperands(hir_mod.unaryOf(self.hir, node).operand),
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(l.lhs);
                try self.reportImplicitAnyYieldOperands(l.rhs);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(c.cond);
                try self.reportImplicitAnyYieldOperands(c.then_branch);
                try self.reportImplicitAnyYieldOperands(c.else_branch);
            },
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(a.target);
                try self.reportImplicitAnyYieldOperands(a.value);
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(c.callee);
                for (hir_mod.callArgs(self.hir, node)) |arg| try self.reportImplicitAnyYieldOperands(arg);
            },
            .member_access => try self.reportImplicitAnyYieldOperands(hir_mod.memberOf(self.hir, node).object),
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(e.object);
                try self.reportImplicitAnyYieldOperands(e.index);
            },
            .as_expr, .satisfies_expr, .type_assertion => try self.reportImplicitAnyYieldOperands(hir_mod.asExpressionOf(self.hir, node).expr),
            .throw_stmt => try self.reportImplicitAnyYieldOperands(hir_mod.throwOf(self.hir, node).value),
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(ts.block);
                try self.reportImplicitAnyYieldOperands(ts.catch_block);
                try self.reportImplicitAnyYieldOperands(ts.finally_block);
            },
            .switch_stmt => {
                const sw = hir_mod.switchOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(sw.discriminant);
                for (hir_mod.switchCases(self.hir, node)) |case| try self.reportImplicitAnyYieldOperands(case);
            },
            .switch_case => for (hir_mod.switchCaseStmts(self.hir, node)) |s| try self.reportImplicitAnyYieldOperands(s),
            .array_literal => for (hir_mod.arrayLiteralElements(self.hir, node)) |el| try self.reportImplicitAnyYieldOperands(el),
            .object_literal => for (hir_mod.objectLiteralProps(self.hir, node)) |p| try self.reportImplicitAnyYieldOperands(p),
            .object_property => {
                const op = hir_mod.objectPropertyOf(self.hir, node);
                try self.reportImplicitAnyYieldOperands(op.value);
                if (op.is_computed) try self.reportImplicitAnyYieldOperands(op.key);
            },
            else => {},
        }
    }

    fn yieldCallArgumentLacksConcreteContext(self: *Checker, node: NodeId) bool {
        if (!self.strict_flags.no_implicit_any) return false;
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return false;
        const parent_kind = self.hir.kindOf(parent);
        if (parent_kind != .call_expr and parent_kind != .new_expr) return false;
        const call = hir_mod.callOf(self.hir, parent);
        var arg_index: ?usize = null;
        for (hir_mod.callArgs(self.hir, parent), 0..) |arg, i| {
            if (arg == node) {
                arg_index = i;
                break;
            }
        }
        const index = arg_index orelse return false;
        const signature = self.firstSignatureType(self.hir.typeOf(call.callee)) orelse return true;
        const params = self.interner.signatureParams(signature);
        if (params.len == 0) return true;
        const param_t = if (self.rest_signatures.contains(signature) and index >= params.len - 1)
            params[params.len - 1]
        else if (index < params.len)
            params[index]
        else
            return true;
        if (param_t == types.Primitive.none or param_t == types.Primitive.any) return true;
        return param_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(param_t).is_type_parameter;
    }

    fn reportImplicitAnyGeneratorYield(self: *Checker, fn_node: NodeId) CheckError!void {
        if (!self.strict_flags.no_implicit_any) return;
        if (self.hir.kindOf(fn_node) != .fn_decl and
            self.hir.kindOf(fn_node) != .fn_expr and
            self.hir.kindOf(fn_node) != .arrow_fn)
        {
            return;
        }
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (!f.flags.is_generator or f.return_type != hir_mod.none_node_id) return;
        if (!self.bodyHasImplicitAnyYieldType(f.body)) return;
        // tsc only fires TS7025/TS7055 when the INFERRED yield type
        // would be `any` overall ÃÂ¢ÃÂÃÂ if any yield in the body has a
        // concrete type (e.g. `yield new Bar` next to `yield;`), the
        // inferred yield type is `Bar | undefined`, not `any`, and
        // upstream stays silent. Mirror that: if any yield contributes
        // a non-`any` element type, don't fire the function-level
        // implicit-any diagnostic.
        if (self.bodyHasNonAnyYield(f.body)) return;
        if (f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier) {
            const name = self.string_interner.get(hir_mod.identifierOf(self.hir, f.name).name);
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "'{s}', which lacks return-type annotation, implicitly has an 'any' yield type.",
                .{name},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = f.name,
                .code = TsCodes.generator_implicit_yield_type,
                .message = msg,
            });
        } else {
            try self.report(fn_node, TsCodes.generator_implicit_yield_type_short, "Generator implicitly has yield type 'any'. Consider supplying a return type annotation.");
        }
    }

    fn reportImplicitAnyInferredReturn(self: *Checker, fn_node: NodeId) CheckError!void {
        // Hard error TS7010 under noImplicitAny; under !noImplicitAny +
        // suggestions-enabled the `.suggestion`-category TS7050 fires.
        const ret_is_suggestion = !self.strict_flags.no_implicit_any;
        if (ret_is_suggestion and !self.emit_implicit_any_suggestions) return;
        if (self.strict_flags.strict_null_checks) return;
        const k = self.hir.kindOf(fn_node);
        if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) return;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.return_type != hir_mod.none_node_id) return;
        if (self.functionIsPrivateAmbientClassMember(fn_node)) return;
        if (self.functionHasContextualReturnType(fn_node)) return;
        if (!self.functionReturnsOnlyImplicitAnyNullish(f.body)) return;

        // A getter uses the property-specific TS7033 ("its get accessor
        // lacks a return type annotation"), not the function-return TS7010.
        // (The suggestion-mode variant is TS7048, not yet emitted, so skip
        // getters under suggestion mode rather than mis-emit TS7050.)
        if (f.flags.is_getter) {
            if (ret_is_suggestion) return;
            if (f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier) {
                const gname = self.string_interner.get(hir_mod.identifierOf(self.hir, f.name).name);
                const gmsg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Property '{s}' implicitly has type 'any', because its get accessor lacks a return type annotation.",
                    .{gname},
                );
                try self.diagnostics.append(self.gpa, .{
                    .node = f.name,
                    .code = TsCodes.getter_property_implicitly_any,
                    .message = gmsg,
                });
            }
            return;
        }

        const arena = self.diag_arena.allocator();
        const type_text = if (self.firstNullishTupleReturnWidth(f.body)) |tuple_width| blk: {
            // Upstream TS prints `implicitly has an '[any, ...]' return type`
            // for contextual tuple assignments like `return xs = [undefined]`.
            var inferred_buf: std.ArrayListUnmanaged(u8) = .empty;
            errdefer inferred_buf.deinit(arena);
            try inferred_buf.append(arena, '[');
            var i: usize = 0;
            while (i < tuple_width) : (i += 1) {
                if (i > 0) try inferred_buf.appendSlice(arena, ", ");
                try inferred_buf.appendSlice(arena, "any");
            }
            try inferred_buf.append(arena, ']');
            break :blk inferred_buf.items;
        } else blk: {
            break :blk "any";
        };
        try self.reportImplicitAnyFunctionReturn(fn_node, type_text, ret_is_suggestion);
    }

    fn reportImplicitAnyFunctionReturn(self: *Checker, fn_node: NodeId, type_text: []const u8, is_suggestion: bool) CheckError!void {
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.name == hir_mod.none_node_id) {
            // An unnamed function expression has no declaration name, so
            // tsc reports the hard error TS7011 even under !noImplicitAny
            // (there is no usage-suggestion form). Skip in suggestion mode.
            if (is_suggestion) return;
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Function expression, which lacks return-type annotation, implicitly has an '{s}' return type.",
                .{type_text},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = fn_node,
                .code = TsCodes.function_expression_return_implicitly_any,
                .message = msg,
            });
            return;
        }

        const raw = if (self.hir.kindOf(f.name) == .identifier)
            self.string_interner.get(hir_mod.identifierOf(self.hir, f.name).name)
        else
            "<anonymous>";
        const msg = if (is_suggestion)
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "'{s}' implicitly has an '{s}' return type, but a better type may be inferred from usage.",
                .{ raw, type_text },
            )
        else
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "'{s}', which lacks return-type annotation, implicitly has an '{s}' return type.",
                .{ raw, type_text },
            );
        try self.diagnostics.append(self.gpa, .{
            .node = f.name,
            .code = if (is_suggestion)
                TsCodes.function_return_implicitly_any_suggestion
            else
                TsCodes.function_return_implicitly_any,
            .message = msg,
            .category = if (is_suggestion) .suggestion else .error_,
        });
    }

    fn functionIsPrivateAmbientClassMember(self: *Checker, fn_node: NodeId) bool {
        if (fn_node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(fn_node) != .fn_decl and
            self.hir.kindOf(fn_node) != .fn_expr and
            self.hir.kindOf(fn_node) != .arrow_fn)
        {
            return false;
        }
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.body != hir_mod.none_node_id) return false;
        if (self.functionIsInvalidDeclaredEcmaPrivateClassMember(fn_node)) return true;
        if (!f.flags.is_private) return false;

        var cur = self.hir.parentOf(fn_node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            if (self.hir.kindOf(cur) != .class_decl and self.hir.kindOf(cur) != .class_expr) continue;
            return self.classHasLeadingDeclare(cur) or
                self.classNodeIsInsideAmbientDeclaredModule(cur) or
                self.virtualSectionIsDeclarationFile(cur);
        }
        return false;
    }

    fn functionIsInvalidDeclaredEcmaPrivateClassMember(self: *Checker, fn_node: NodeId) bool {
        if (fn_node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(fn_node) != .fn_decl and
            self.hir.kindOf(fn_node) != .fn_expr and
            self.hir.kindOf(fn_node) != .arrow_fn)
        {
            return false;
        }
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.body != hir_mod.none_node_id or
            f.name == hir_mod.none_node_id or
            self.hir.kindOf(f.name) != .identifier)
        {
            return false;
        }
        const name = hir_mod.identifierOf(self.hir, f.name).name;
        if (!self.memberNameIsEcmaPrivate(name)) return false;
        return self.classMemberSourceHasModifierBeforeKey(fn_node, f.name, "declare");
    }

    const ImplicitAnyReturnScan = struct {
        value_returns: usize = 0,
        saw_non_nullish: bool = false,
    };

    fn functionReturnsOnlyImplicitAnyNullish(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        if (self.functionBodyExpressionIsImplicitAnyNullish(node)) return true;
        var scan: ImplicitAnyReturnScan = .{};
        self.scanImplicitAnyNullishReturns(node, &scan);
        return scan.value_returns > 0 and !scan.saw_non_nullish;
    }

    fn scanImplicitAnyNullishReturns(self: *Checker, node: NodeId, scan: *ImplicitAnyReturnScan) void {
        if (node == hir_mod.none_node_id or scan.saw_non_nullish) return;
        switch (self.hir.kindOf(node)) {
            .return_stmt => {
                const r = hir_mod.returnOf(self.hir, node);
                if (r.value == hir_mod.none_node_id) return;
                scan.value_returns += 1;
                if (!self.functionBodyExpressionIsImplicitAnyNullish(r.value)) {
                    scan.saw_non_nullish = true;
                }
            },
            .block_stmt => for (hir_mod.blockStmts(self.hir, node)) |s| self.scanImplicitAnyNullishReturns(s, scan),
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                self.scanImplicitAnyNullishReturns(i.then_branch, scan);
                self.scanImplicitAnyNullishReturns(i.else_branch, scan);
            },
            .try_stmt => {
                const t = hir_mod.tryOf(self.hir, node);
                self.scanImplicitAnyNullishReturns(t.block, scan);
                self.scanImplicitAnyNullishReturns(t.catch_block, scan);
                self.scanImplicitAnyNullishReturns(t.finally_block, scan);
            },
            .switch_stmt => for (hir_mod.switchCases(self.hir, node)) |case| self.scanImplicitAnyNullishReturns(case, scan),
            .switch_case => for (hir_mod.switchCaseStmts(self.hir, node)) |s| self.scanImplicitAnyNullishReturns(s, scan),
            .while_stmt => self.scanImplicitAnyNullishReturns(hir_mod.whileOf(self.hir, node).body, scan),
            .do_while_stmt => self.scanImplicitAnyNullishReturns(hir_mod.doWhileOf(self.hir, node).body, scan),
            .for_stmt => self.scanImplicitAnyNullishReturns(hir_mod.forStmtOf(self.hir, node).body, scan),
            .for_in_stmt, .for_of_stmt => self.scanImplicitAnyNullishReturns(hir_mod.forInOf(self.hir, node).body, scan),
            .fn_decl, .fn_expr, .arrow_fn => return,
            else => {},
        }
    }

    fn functionBodyExpressionIsImplicitAnyNullish(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        switch (self.hir.kindOf(node)) {
            .literal_null, .literal_undefined => return true,
            .assignment => return self.functionBodyExpressionIsImplicitAnyNullish(hir_mod.assignmentOf(self.hir, node).value),
            .array_literal => {
                const elements = hir_mod.arrayLiteralElements(self.hir, node);
                for (elements) |el| {
                    if (el == hir_mod.none_node_id) continue;
                    const k = self.hir.kindOf(el);
                    if (k != .literal_null and k != .literal_undefined) return false;
                }
                return true;
            },
            else => return false,
        }
    }

    fn firstNullishTupleReturnWidth(self: *Checker, node: NodeId) ?usize {
        if (node == hir_mod.none_node_id) return null;
        switch (self.hir.kindOf(node)) {
            .return_stmt => {
                const r = hir_mod.returnOf(self.hir, node);
                return self.nullishTupleLiteralWidth(r.value);
            },
            .block_stmt => {
                const stmts = hir_mod.blockStmts(self.hir, node);
                for (stmts) |s| {
                    if (self.firstNullishTupleReturnWidth(s)) |w| return w;
                }
                return null;
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                return self.firstNullishTupleReturnWidth(i.then_branch) orelse self.firstNullishTupleReturnWidth(i.else_branch);
            },
            .try_stmt => {
                const t = hir_mod.tryOf(self.hir, node);
                return self.firstNullishTupleReturnWidth(t.block) orelse
                    self.firstNullishTupleReturnWidth(t.catch_block) orelse
                    self.firstNullishTupleReturnWidth(t.finally_block);
            },
            .fn_decl, .fn_expr, .arrow_fn => return null,
            else => return null,
        }
    }

    fn nullishTupleLiteralWidth(self: *Checker, node: NodeId) ?usize {
        if (node == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(node) == .assignment) {
            return self.nullishTupleLiteralWidth(hir_mod.assignmentOf(self.hir, node).value);
        }
        if (self.hir.kindOf(node) != .array_literal) return null;
        const elements = hir_mod.arrayLiteralElements(self.hir, node);
        return elements.len;
    }

    fn functionHasContextualReturnType(self: *Checker, fn_node: NodeId) bool {
        return self.contextualReturnTypeForFunction(fn_node) != null;
    }

    fn functionBodyReturnsNullishTupleLiteral(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        switch (self.hir.kindOf(node)) {
            .return_stmt => {
                const r = hir_mod.returnOf(self.hir, node);
                return self.expressionIsNullishTupleLiteral(r.value);
            },
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |s| {
                    if (self.functionBodyReturnsNullishTupleLiteral(s)) return true;
                }
                return false;
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                return self.functionBodyReturnsNullishTupleLiteral(i.then_branch) or
                    self.functionBodyReturnsNullishTupleLiteral(i.else_branch);
            },
            .try_stmt => {
                const t = hir_mod.tryOf(self.hir, node);
                return self.functionBodyReturnsNullishTupleLiteral(t.block) or
                    self.functionBodyReturnsNullishTupleLiteral(t.catch_block) or
                    self.functionBodyReturnsNullishTupleLiteral(t.finally_block);
            },
            .fn_decl, .fn_expr, .arrow_fn => return false,
            else => return false,
        }
    }

    fn expressionIsNullishTupleLiteral(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(node) == .assignment) {
            return self.expressionIsNullishTupleLiteral(hir_mod.assignmentOf(self.hir, node).value);
        }
        if (self.hir.kindOf(node) != .array_literal) return false;
        const elements = hir_mod.arrayLiteralElements(self.hir, node);
        if (elements.len == 0) return true;
        for (elements) |el| {
            if (el == hir_mod.none_node_id) continue;
            const k = self.hir.kindOf(el);
            if (k != .literal_null and k != .literal_undefined) return false;
        }
        return true;
    }

    /// Returns true when `node` is an unresolved identifier reference
    /// ÃÂ¢ÃÂÃÂ used to suppress duplicate implicit-any diagnostics on
    /// `yield(foo)` when `foo` already has a TS2304 attached.
    fn yieldOperandIsUnresolvedIdentifier(self: *Checker, node: NodeId) bool {
        const k = self.hir.kindOf(node);
        if (k != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, node);
        if (self.lookupNarrow(id.name) != null) return false;
        const visible = self.typeOfVisibleNameNoDiag(node, id.name) catch return false;
        return visible == null;
    }

    fn bodyHasImplicitAnyYieldType(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        switch (self.hir.kindOf(node)) {
            .yield_expr => {
                const y = hir_mod.yieldExprOf(self.hir, node);
                // Bare `yield;` is a per-expression issue, not a
                // generator-shape issue ÃÂ¢ÃÂÃÂ tsc reports TS7057 on the
                // yield itself, never TS7055/TS7025 on the enclosing
                // function. Skip it here so we don't double-fire with
                // the per-yield TS7057 pass.
                if (y.expr == hir_mod.none_node_id) return false;
                // `yield yield` ÃÂ¢ÃÂÃÂ same logic: the inner bare yield
                // produces TS7057, the outer should NOT additionally
                // claim the whole generator has implicit-any.
                if (self.hir.kindOf(y.expr) == .yield_expr) {
                    const inner = hir_mod.yieldExprOf(self.hir, y.expr);
                    if (inner.expr == hir_mod.none_node_id) return false;
                }
                const expr_t = self.hir.typeOf(y.expr);
                if (self.yieldOperandIsImplicitAnyIdentifier(y.expr)) return false;
                if (self.typeIsAny(expr_t) or self.yieldOperandIsImplicitAnyIdentifier(y.expr)) {
                    // tsc suppresses TS7025/TS7055 when the yield's
                    // expression is itself unresolved (TS2304 already
                    // fires on the same node, so adding implicit-any
                    // noise duplicates the diagnostic). Detect that
                    // here so fixtures like `YieldExpression9_es6`
                    // (`yield(foo)` where `foo` is undeclared) don't
                    // double-fire.
                    if (self.yieldOperandIsUnresolvedIdentifier(y.expr)) return false;
                    return true;
                }
                if (y.type_node != hir_mod.none_node_id and
                    expr_t < self.interner.pool.typeCount() and
                    self.interner.pool.flagsOf(expr_t).is_object_type)
                {
                    const elem_t = self.interner.objectNumberIndex(expr_t);
                    if (elem_t == types.Primitive.any or elem_t == types.Primitive.undefined_t) return true;
                }
                return self.bodyHasImplicitAnyYieldType(y.expr);
            },
            .fn_decl, .fn_expr, .arrow_fn => return false,
            .block_stmt => for (hir_mod.blockStmts(self.hir, node)) |s| {
                if (self.bodyHasImplicitAnyYieldType(s)) return true;
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(i.cond) or
                    self.bodyHasImplicitAnyYieldType(i.then_branch) or
                    self.bodyHasImplicitAnyYieldType(i.else_branch);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(w.cond) or self.bodyHasImplicitAnyYieldType(w.body);
            },
            .do_while_stmt => {
                const w = hir_mod.doWhileOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(w.cond) or self.bodyHasImplicitAnyYieldType(w.body);
            },
            .for_stmt => {
                const fr = hir_mod.forStmtOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(fr.init) or
                    self.bodyHasImplicitAnyYieldType(fr.cond) or
                    self.bodyHasImplicitAnyYieldType(fr.update) or
                    self.bodyHasImplicitAnyYieldType(fr.body);
            },
            .for_in_stmt, .for_of_stmt => {
                const fr = hir_mod.forInOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(fr.target) or
                    self.bodyHasImplicitAnyYieldType(fr.source) or
                    self.bodyHasImplicitAnyYieldType(fr.body);
            },
            .return_stmt => return self.bodyHasImplicitAnyYieldType(hir_mod.returnOf(self.hir, node).value),
            .var_decl, .let_decl, .const_decl => return self.bodyHasImplicitAnyYieldType(hir_mod.varDeclOf(self.hir, node).init),
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(b.lhs) or self.bodyHasImplicitAnyYieldType(b.rhs);
            },
            .unary_op => return self.bodyHasImplicitAnyYieldType(hir_mod.unaryOf(self.hir, node).operand),
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(l.lhs) or self.bodyHasImplicitAnyYieldType(l.rhs);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(c.cond) or
                    self.bodyHasImplicitAnyYieldType(c.then_branch) or
                    self.bodyHasImplicitAnyYieldType(c.else_branch);
            },
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(a.target) or self.bodyHasImplicitAnyYieldType(a.value);
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                if (self.bodyHasImplicitAnyYieldType(c.callee)) return true;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.bodyHasImplicitAnyYieldType(arg)) return true;
                }
                return false;
            },
            .member_access => return self.bodyHasImplicitAnyYieldType(hir_mod.memberOf(self.hir, node).object),
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(e.object) or self.bodyHasImplicitAnyYieldType(e.index);
            },
            .as_expr, .satisfies_expr, .type_assertion => return self.bodyHasImplicitAnyYieldType(hir_mod.asExpressionOf(self.hir, node).expr),
            .throw_stmt => return self.bodyHasImplicitAnyYieldType(hir_mod.throwOf(self.hir, node).value),
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(ts.block) or
                    self.bodyHasImplicitAnyYieldType(ts.catch_block) or
                    self.bodyHasImplicitAnyYieldType(ts.finally_block);
            },
            .switch_stmt => {
                const sw = hir_mod.switchOf(self.hir, node);
                if (self.bodyHasImplicitAnyYieldType(sw.discriminant)) return true;
                for (hir_mod.switchCases(self.hir, node)) |case| {
                    if (self.bodyHasImplicitAnyYieldType(case)) return true;
                }
                return false;
            },
            .switch_case => for (hir_mod.switchCaseStmts(self.hir, node)) |s| {
                if (self.bodyHasImplicitAnyYieldType(s)) return true;
            },
            .array_literal => for (hir_mod.arrayLiteralElements(self.hir, node)) |el| {
                if (self.bodyHasImplicitAnyYieldType(el)) return true;
            },
            .object_literal => for (hir_mod.objectLiteralProps(self.hir, node)) |p| {
                if (self.bodyHasImplicitAnyYieldType(p)) return true;
            },
            .object_property => {
                const op = hir_mod.objectPropertyOf(self.hir, node);
                return self.bodyHasImplicitAnyYieldType(op.value) or
                    (op.is_computed and self.bodyHasImplicitAnyYieldType(op.key));
            },
            else => return false,
        }
        return false;
    }

    /// Returns true when at least one yield in `node`'s body
    /// contributes a non-`any` element type. Mirrors tsc's check
    /// before firing the function-level implicit-any-yield diagnostic
    /// (TS7025/TS7055): a single concrete yield is enough to pin the
    /// generator's inferred yield type.
    fn expressionProvidesConcreteYieldType(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        const t = self.hir.typeOf(node);
        if (t != types.Primitive.none and
            t != types.Primitive.any and
            t != types.Primitive.undefined_t and
            t != types.Primitive.null_t and
            !self.yieldOperandIsImplicitAnyIdentifier(node))
        {
            return true;
        }
        return switch (self.hir.kindOf(node)) {
            .literal_string, .literal_number, .literal_bigint, .literal_bool => true,
            .await_expr => blk: {
                const operand = hir_mod.awaitExprOf(self.hir, node).expr;
                if (self.promiseResolveCallArgument(operand)) |resolved| {
                    break :blk self.expressionProvidesConcreteYieldType(resolved);
                }
                break :blk self.expressionProvidesConcreteYieldType(operand);
            },
            .as_expr, .satisfies_expr, .type_assertion, .non_null_expr => self.expressionProvidesConcreteYieldType(hir_mod.asExpressionOf(self.hir, node).expr),
            else => false,
        };
    }

    fn bodyHasNonAnyYield(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        switch (self.hir.kindOf(node)) {
            .yield_expr => {
                const y = hir_mod.yieldExprOf(self.hir, node);
                if (y.expr == hir_mod.none_node_id) return false;
                if (self.expressionProvidesConcreteYieldType(y.expr)) return true;
                return self.bodyHasNonAnyYield(y.expr);
            },
            .fn_decl, .fn_expr, .arrow_fn => return false,
            .block_stmt => for (hir_mod.blockStmts(self.hir, node)) |s| {
                if (self.bodyHasNonAnyYield(s)) return true;
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                return self.bodyHasNonAnyYield(i.cond) or
                    self.bodyHasNonAnyYield(i.then_branch) or
                    self.bodyHasNonAnyYield(i.else_branch);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                return self.bodyHasNonAnyYield(w.cond) or self.bodyHasNonAnyYield(w.body);
            },
            .do_while_stmt => {
                const w = hir_mod.doWhileOf(self.hir, node);
                return self.bodyHasNonAnyYield(w.cond) or self.bodyHasNonAnyYield(w.body);
            },
            .for_stmt => {
                const fr = hir_mod.forStmtOf(self.hir, node);
                return self.bodyHasNonAnyYield(fr.init) or
                    self.bodyHasNonAnyYield(fr.cond) or
                    self.bodyHasNonAnyYield(fr.update) or
                    self.bodyHasNonAnyYield(fr.body);
            },
            .for_in_stmt, .for_of_stmt => {
                const fr = hir_mod.forInOf(self.hir, node);
                return self.bodyHasNonAnyYield(fr.target) or
                    self.bodyHasNonAnyYield(fr.source) or
                    self.bodyHasNonAnyYield(fr.body);
            },
            .return_stmt => return self.bodyHasNonAnyYield(hir_mod.returnOf(self.hir, node).value),
            .var_decl, .let_decl, .const_decl => return self.bodyHasNonAnyYield(hir_mod.varDeclOf(self.hir, node).init),
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                return self.bodyHasNonAnyYield(b.lhs) or self.bodyHasNonAnyYield(b.rhs);
            },
            .unary_op => return self.bodyHasNonAnyYield(hir_mod.unaryOf(self.hir, node).operand),
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                return self.bodyHasNonAnyYield(l.lhs) or self.bodyHasNonAnyYield(l.rhs);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                return self.bodyHasNonAnyYield(c.cond) or
                    self.bodyHasNonAnyYield(c.then_branch) or
                    self.bodyHasNonAnyYield(c.else_branch);
            },
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                return self.bodyHasNonAnyYield(a.target) or self.bodyHasNonAnyYield(a.value);
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                if (self.bodyHasNonAnyYield(c.callee)) return true;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.bodyHasNonAnyYield(arg)) return true;
                }
                return false;
            },
            .member_access => return self.bodyHasNonAnyYield(hir_mod.memberOf(self.hir, node).object),
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                return self.bodyHasNonAnyYield(e.object) or self.bodyHasNonAnyYield(e.index);
            },
            .as_expr, .satisfies_expr, .type_assertion => return self.bodyHasNonAnyYield(hir_mod.asExpressionOf(self.hir, node).expr),
            .throw_stmt => return self.bodyHasNonAnyYield(hir_mod.throwOf(self.hir, node).value),
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                return self.bodyHasNonAnyYield(ts.block) or
                    self.bodyHasNonAnyYield(ts.catch_block) or
                    self.bodyHasNonAnyYield(ts.finally_block);
            },
            .switch_stmt => {
                const sw = hir_mod.switchOf(self.hir, node);
                if (self.bodyHasNonAnyYield(sw.discriminant)) return true;
                for (hir_mod.switchCases(self.hir, node)) |case| {
                    if (self.bodyHasNonAnyYield(case)) return true;
                }
                return false;
            },
            .switch_case => for (hir_mod.switchCaseStmts(self.hir, node)) |s| {
                if (self.bodyHasNonAnyYield(s)) return true;
            },
            .array_literal => for (hir_mod.arrayLiteralElements(self.hir, node)) |el| {
                if (self.bodyHasNonAnyYield(el)) return true;
            },
            .object_literal => for (hir_mod.objectLiteralProps(self.hir, node)) |p| {
                if (self.bodyHasNonAnyYield(p)) return true;
            },
            .object_property => {
                const op = hir_mod.objectPropertyOf(self.hir, node);
                return self.bodyHasNonAnyYield(op.value) or
                    (op.is_computed and self.bodyHasNonAnyYield(op.key));
            },
            else => return false,
        }
        return false;
    }

    /// Build a v0 `Generator<T, void, unknown>` shape for generator
    /// return-type inference. The synthesized object exposes:
    ///   - `next(): { value: T | undefined, done: boolean }`
    ///   - `return(): { value: T | undefined, done: boolean }`
    ///   - `throw(): { value: T | undefined, done: boolean }`
    ///   - `[i: number]: T` indexer so `for (const x of g())` resolves
    ///     `x` to T through the existing for-of element-type path.
    /// Async generators wrap each iterator-result method in `Promise`, as
    /// required by `AsyncIterator<T>` / `AsyncIterableIterator<T>`.
    fn synthesizeGeneratorType(self: *Checker, yield_t: TypeId) CheckError!TypeId {
        return self.synthesizeGeneratorTypeFull(yield_t, types.Primitive.void_t, types.Primitive.any, false);
    }

    fn synthesizeGeneratorTypeFull(
        self: *Checker,
        yield_t: TypeId,
        return_t: TypeId,
        next_t: TypeId,
        is_async: bool,
    ) CheckError!TypeId {
        const value_id = self.string_interner.intern("value") catch return error.OutOfMemory;
        const done_id = self.string_interner.intern("done") catch return error.OutOfMemory;
        const next_id = self.string_interner.intern("next") catch return error.OutOfMemory;
        const return_id = self.string_interner.intern("return") catch return error.OutOfMemory;
        const throw_id = self.string_interner.intern("throw") catch return error.OutOfMemory;
        const iterator_id = self.string_interner.intern(if (is_async) "Symbol.asyncIterator" else "Symbol.iterator") catch return error.OutOfMemory;
        const dispose_id = self.string_interner.intern(if (is_async) "Symbol.asyncDispose" else "Symbol.dispose") catch return error.OutOfMemory;

        // IteratorResult<T, TReturn> = { value: T | TReturn | undefined, done: boolean }
        const value_or_undef = self.interner.internUnion(&.{ yield_t, return_t, types.Primitive.undefined_t }) catch yield_t;
        const ir_members = [_]types.ObjectMember{
            .{ .name = value_id, .type = value_or_undef, .is_optional = false, .is_readonly = false, .is_method = false },
            .{ .name = done_id, .type = types.Primitive.boolean_t, .is_optional = false, .is_readonly = false, .is_method = false },
        };
        const iter_result = self.interner.internObjectType(&ir_members) catch return error.OutOfMemory;
        const method_result = if (is_async)
            try self.buildStructuralPromise(iter_result)
        else
            iter_result;

        // `next(value?: TNext)` returns IteratorResult<T, TReturn>, wrapped
        // in Promise for an async generator. `return` and `throw` follow the
        // same iterator protocol rule.
        const next_param = self.unionWithUndefined(next_t) catch next_t;
        const next_params = [_]TypeId{next_param};
        const next_sig = self.interner.internSignature(&next_params, method_result, false) catch return error.OutOfMemory;
        try self.recordSignatureMinArgs(next_sig, &.{true});
        const empty_params: []const TypeId = &.{};
        const return_sig = self.interner.internSignature(empty_params, method_result, false) catch return error.OutOfMemory;
        const throw_sig = self.interner.internSignature(empty_params, method_result, false) catch return error.OutOfMemory;
        const iterator_sig = self.interner.internSignature(empty_params, types.Primitive.any, false) catch return error.OutOfMemory;
        const dispose_sig = self.interner.internSignature(empty_params, if (is_async) types.Primitive.any else types.Primitive.void_t, false) catch return error.OutOfMemory;

        const gen_members = [_]types.ObjectMember{
            .{ .name = next_id, .type = next_sig, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = return_id, .type = return_sig, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = throw_id, .type = throw_sig, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = iterator_id, .type = iterator_sig, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = dispose_id, .type = dispose_sig, .is_optional = false, .is_readonly = false, .is_method = true },
        };
        // Number-key indexer = T so for-of binds the loop variable to T.
        const gen_t = self.interner.internObjectTypeWithIndex(
            &gen_members,
            types.Primitive.none,
            yield_t,
        ) catch return error.OutOfMemory;
        try self.generator_type_info.put(self.gpa, gen_t, .{
            .yield_type = yield_t,
            .return_type = return_t,
            .next_type = next_t,
        });
        const generator_name = self.string_interner.intern(if (is_async) "AsyncGenerator" else "Generator") catch return error.OutOfMemory;
        try self.registerAliasDisplayName(gen_t, generator_name, &.{ yield_t, return_t, next_t });
        return gen_t;
    }

    /// When `annotation` is a bare type-ref to one of the iterable /
    /// generator builtin forms (`IterableIterator<T>`, `Iterable<T>`,
    /// `AsyncIterableIterator<T>`, `AsyncIterable<T>`, `Generator<T,ÃÂ¢ÃÂÃÂ¦>`,
    /// `AsyncGenerator<T,ÃÂ¢ÃÂÃÂ¦>`, `Iterator<T,ÃÂ¢ÃÂÃÂ¦>`, `AsyncIterator<T,ÃÂ¢ÃÂÃÂ¦>`),
    /// returns the lowered yield element type T. Used as a fallback
    /// when `generator_type_info.get(ret_t)` misses because the
    /// lowerer materialized the annotation into an opaque empty-object
    /// shape rather than a registered generator type.
    fn generatorYieldTypeFromAnnotation(self: *Checker, annotation: NodeId) ?TypeId {
        return self.generatorYieldTypeFromAnnotationDepth(annotation, 0);
    }

    fn generatorYieldTypeFromAnnotationDepth(self: *Checker, annotation: NodeId, depth: u8) ?TypeId {
        if (depth >= 16) return null;
        if (annotation == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(annotation) != .type_ref) return null;
        const r = hir_mod.typeRefOf(self.hir, annotation);
        if (r.qualifier_len != 0) return null;
        const name = self.string_interner.get(r.name);
        const matches =
            std.mem.eql(u8, name, "IterableIterator") or
            std.mem.eql(u8, name, "Iterable") or
            std.mem.eql(u8, name, "AsyncIterableIterator") or
            std.mem.eql(u8, name, "AsyncIterable") or
            std.mem.eql(u8, name, "Iterator") or
            std.mem.eql(u8, name, "AsyncIterator") or
            std.mem.eql(u8, name, "Generator") or
            std.mem.eql(u8, name, "AsyncGenerator");
        if (matches) {
            const args = hir_mod.typeRefArgs(self.hir, annotation);
            if (args.len == 0) return null;
            return self.lowererLowerWithTypeParams(args[0]) catch null;
        }
        const decl = self.findVisibleNamedTypeDecl(annotation, r.name) orelse return null;
        if (self.hir.kindOf(decl) != .interface_decl) return null;
        // Prefer the iterable side of a composite protocol. A declaration
        // such as `Iterator<number> & Iterable<string>` yields strings, then
        // fails compatibility against the iterator's `next` result.
        for (hir_mod.interfaceExtends(self.hir, decl)) |base| {
            if (self.generatorIterableYieldTypeFromAnnotationDepth(base, depth + 1)) |yield_t| return yield_t;
        }
        for (hir_mod.interfaceExtends(self.hir, decl)) |base| {
            if (self.generatorYieldTypeFromAnnotationDepth(base, depth + 1)) |yield_t| return yield_t;
        }
        return null;
    }

    fn generatorIterableYieldTypeFromAnnotationDepth(self: *Checker, annotation: NodeId, depth: u8) ?TypeId {
        if (depth >= 16 or annotation == hir_mod.none_node_id or self.hir.kindOf(annotation) != .type_ref) return null;
        const r = hir_mod.typeRefOf(self.hir, annotation);
        if (r.qualifier_len != 0) return null;
        const name = self.string_interner.get(r.name);
        const is_iterable = std.mem.eql(u8, name, "IterableIterator") or
            std.mem.eql(u8, name, "Iterable") or
            std.mem.eql(u8, name, "AsyncIterableIterator") or
            std.mem.eql(u8, name, "AsyncIterable") or
            std.mem.eql(u8, name, "Generator") or
            std.mem.eql(u8, name, "AsyncGenerator");
        if (is_iterable) {
            const args = hir_mod.typeRefArgs(self.hir, annotation);
            if (args.len == 0) return null;
            return self.lowererLowerWithTypeParams(args[0]) catch null;
        }
        const decl = self.findVisibleNamedTypeDecl(annotation, r.name) orelse return null;
        if (self.hir.kindOf(decl) != .interface_decl) return null;
        for (hir_mod.interfaceExtends(self.hir, decl)) |base| {
            if (self.generatorIterableYieldTypeFromAnnotationDepth(base, depth + 1)) |yield_t| return yield_t;
        }
        return null;
    }

    fn generatorIteratorYieldTypeFromAnnotationDepth(self: *Checker, annotation: NodeId, depth: u8) ?TypeId {
        if (depth >= 16 or annotation == hir_mod.none_node_id or self.hir.kindOf(annotation) != .type_ref) return null;
        const r = hir_mod.typeRefOf(self.hir, annotation);
        if (r.qualifier_len != 0) return null;
        const name = self.string_interner.get(r.name);
        if (std.mem.eql(u8, name, "Iterator") or std.mem.eql(u8, name, "AsyncIterator")) {
            const args = hir_mod.typeRefArgs(self.hir, annotation);
            if (args.len == 0) return null;
            return self.lowererLowerWithTypeParams(args[0]) catch null;
        }
        const decl = self.findVisibleNamedTypeDecl(annotation, r.name) orelse return null;
        if (self.hir.kindOf(decl) != .interface_decl) return null;
        for (hir_mod.interfaceExtends(self.hir, decl)) |base| {
            if (self.generatorIteratorYieldTypeFromAnnotationDepth(base, depth + 1)) |yield_t| return yield_t;
        }
        return null;
    }

    fn generatorReturnAnnotationHasConflictingYieldTypes(self: *Checker, annotation: NodeId) bool {
        const iterable_yield = self.generatorIterableYieldTypeFromAnnotationDepth(annotation, 0) orelse return false;
        const iterator_yield = self.generatorIteratorYieldTypeFromAnnotationDepth(annotation, 0) orelse return false;
        return !(self.engine.isAssignableTo(iterable_yield, iterator_yield) catch true) or
            !(self.engine.isAssignableTo(iterator_yield, iterable_yield) catch true);
    }

    fn generatorReturnAnnotationDefinitelyInvalid(self: *Checker, ret_t: TypeId) bool {
        _ = self;
        return ret_t == types.Primitive.number_t or
            ret_t == types.Primitive.string_t or
            ret_t == types.Primitive.boolean_t or
            ret_t == types.Primitive.bigint_t or
            ret_t == types.Primitive.symbol_t or
            ret_t == types.Primitive.null_t or
            ret_t == types.Primitive.undefined_t or
            ret_t == types.Primitive.never;
    }

    fn generatorReturnAnnotationRequiresMissingGeneratorMembers(self: *Checker, ret_t: TypeId) bool {
        if (ret_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(ret_t);
        if (flags.is_union) {
            for (self.interner.unionMembers(ret_t)) |member| {
                if (!self.generatorReturnAnnotationDefinitelyInvalid(member) and
                    !self.generatorReturnAnnotationRequiresMissingGeneratorMembers(member))
                {
                    return false;
                }
            }
            return true;
        }
        if (!flags.is_object_type) return false;
        for (self.interner.objectMembers(ret_t)) |member| {
            if (member.is_optional) continue;
            const name = self.string_interner.get(member.name);
            if (std.mem.eql(u8, name, "next") or
                std.mem.eql(u8, name, "return") or
                std.mem.eql(u8, name, "throw") or
                std.mem.eql(u8, name, "Symbol.iterator") or
                std.mem.eql(u8, name, "Symbol.asyncIterator") or
                std.mem.eql(u8, name, "Symbol.dispose") or
                std.mem.eql(u8, name, "Symbol.asyncDispose"))
            {
                continue;
            }
            return true;
        }
        return false;
    }

    fn generatorReturnAnnotationFirstRequiredExtraMember(self: *Checker, ret_t: TypeId) ?types.ObjectMember {
        if (ret_t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(ret_t).is_object_type) return null;
        for (self.interner.objectMembers(ret_t)) |member| {
            if (member.is_optional) continue;
            const name = self.string_interner.get(member.name);
            if (std.mem.eql(u8, name, "next") or
                std.mem.eql(u8, name, "return") or
                std.mem.eql(u8, name, "throw") or
                std.mem.eql(u8, name, "Symbol.iterator") or
                std.mem.eql(u8, name, "Symbol.asyncIterator") or
                std.mem.eql(u8, name, "Symbol.dispose") or
                std.mem.eql(u8, name, "Symbol.asyncDispose"))
            {
                continue;
            }
            return member;
        }
        return null;
    }

    fn isIterableLikeType(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return true;
        if (t == types.Primitive.string_t) return true;
        if (t < self.interner.pool.typeCount()) {
            const primitive_flags = self.interner.pool.flagsOf(t);
            if (primitive_flags.is_string and !primitive_flags.is_object_type) return true;
        }
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.isIterableLikeType(constraint);
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.isIterableLikeType(member)) return false;
            }
            return true;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.isIterableLikeType(member)) return true;
            }
            return false;
        }
        if (!flags.is_object_type) return false;
        const symbol_iterator = self.string_interner.intern("Symbol.iterator") catch return false;
        if (self.interner.objectNumberIndex(t) != types.Primitive.none) return true;
        if (self.interner.objectMemberInfo(t, symbol_iterator)) |member| {
            if (member.is_optional) return false;
            if (self.typeHasNextMethod(t)) return true;
            const iterator_t = self.iteratorMethodReturnType(member.type) orelse return true;
            if (iterator_t == types.Primitive.any or iterator_t == types.Primitive.unknown) return true;
            if (self.typeHasNextMethod(iterator_t)) return true;
            if (iterator_t < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(iterator_t).is_object_type and
                self.interner.objectNumberIndex(iterator_t) != types.Primitive.none)
            {
                return true;
            }
        }
        return false;
    }

    /// Async-iterable counterpart of `isIterableLikeType`: true when `t`
    /// carries a `[Symbol.asyncIterator]()` method whose returned object
    /// has a `next` method. Used to validate `for await … of` sources
    /// (which also accept plain sync iterables — the caller checks both).
    fn isAsyncIterableLikeType(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.isAsyncIterableLikeType(member)) return false;
            }
            return true;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.isAsyncIterableLikeType(member)) return true;
            }
            return false;
        }
        if (!flags.is_object_type) return false;
        const symbol_async_iterator = self.string_interner.intern("Symbol.asyncIterator") catch return false;
        if (self.interner.objectMemberInfo(t, symbol_async_iterator)) |member| {
            if (member.is_optional) return false;
            if (self.typeHasNextMethod(t)) return true;
            const iterator_t = self.iteratorMethodReturnType(member.type) orelse return true;
            if (iterator_t == types.Primitive.any or iterator_t == types.Primitive.unknown) return true;
            return self.typeHasNextMethod(iterator_t);
        }
        return false;
    }

    fn isDestructuringIterableSourceType(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return true;
        if (t == types.Primitive.string_t) return true;
        if (t < self.interner.pool.typeCount()) {
            const primitive_flags = self.interner.pool.flagsOf(t);
            if (primitive_flags.is_string and !primitive_flags.is_object_type) return true;
        }
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.isDestructuringIterableSourceType(member)) return false;
            }
            return true;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.isDestructuringIterableSourceType(member)) return true;
            }
            return false;
        }
        if (!flags.is_object_type) return false;
        const symbol_iterator = self.string_interner.intern("Symbol.iterator") catch return false;
        if (self.interner.objectMemberInfo(t, symbol_iterator)) |member| {
            if (member.is_optional) return false;
            if (self.typeHasNextMethod(t)) return true;
            const iterator_t = self.iteratorMethodReturnType(member.type) orelse return true;
            if (iterator_t == types.Primitive.any or iterator_t == types.Primitive.unknown) return true;
            if (self.typeHasNextMethod(iterator_t)) return true;
            // The builtin `Map<K, V>` / `Set<T>` instance shapes here
            // model `Symbol.iterator()` as returning `Array<entry>`
            // rather than a proper `IteratorResult` iterator ÃÂ¢ÃÂÃÂ a
            // synthesizer convenience. The Array semantically still
            // satisfies the destructuring iterable contract (numeric
            // indexer + length / nested `Symbol.iterator`), so accept
            // an array-shaped return type as iterable. Mirrors
            // `iterableArrayPattern30` (empty baseline) where
            // `new Map(...)` destructures cleanly.
            if (iterator_t < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(iterator_t).is_object_type)
            {
                if (self.interner.objectNumberIndex(iterator_t) != types.Primitive.none) return true;
                if (self.interner.objectMemberInfo(iterator_t, symbol_iterator) != null) return true;
            }
            return false;
        }
        if (self.interner.objectNumberIndex(t) != types.Primitive.none) {
            const length_id = self.string_interner.intern("length") catch return false;
            return self.interner.objectMember(t, length_id) != null;
        }
        return false;
    }

    fn iterableElementType(self: *Checker, t: TypeId) CheckError!TypeId {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return types.Primitive.any;
        if (self.generator_type_info.get(t)) |iterable| return iterable.yield_type;
        if (t == types.Primitive.string_t) return types.Primitive.string_t;
        if (t >= self.interner.pool.typeCount()) return types.Primitive.any;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_string and !flags.is_object_type) return types.Primitive.string_t;
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return types.Primitive.any;
            if (constraint == t) return types.Primitive.any;
            return try self.iterableElementType(constraint);
        }
        if (flags.is_union) {
            var elems: std.ArrayListUnmanaged(TypeId) = .empty;
            defer elems.deinit(self.gpa);
            for (self.interner.unionMembers(t)) |member| {
                try elems.append(self.gpa, try self.iterableElementType(member));
            }
            return self.unionOrAny(elems.items);
        }
        if (flags.is_intersection) {
            var elems: std.ArrayListUnmanaged(TypeId) = .empty;
            defer elems.deinit(self.gpa);
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.isIterableLikeType(member)) try elems.append(self.gpa, try self.iterableElementType(member));
            }
            if (elems.items.len == 0) return types.Primitive.any;
            if (elems.items.len == 1) return elems.items[0];
            return self.interner.internIntersection(elems.items) catch return error.OutOfMemory;
        }
        if (!flags.is_object_type) return types.Primitive.any;
        const number_idx = self.interner.objectNumberIndex(t);
        if (number_idx != types.Primitive.none) return number_idx;
        const next_id = self.string_interner.intern("next") catch return error.OutOfMemory;
        if (self.interner.objectMember(t, next_id)) |next_t| {
            if (self.interner.signatureReturn(next_t)) |ret_t| {
                if (ret_t == types.Primitive.any or ret_t == types.Primitive.unknown) return types.Primitive.any;
                const value_id = self.string_interner.intern("value") catch return error.OutOfMemory;
                if (self.interner.objectMember(ret_t, value_id)) |value_t| return value_t;
            }
        }
        const symbol_iterator = self.string_interner.intern("Symbol.iterator") catch return error.OutOfMemory;
        if (self.interner.objectMember(t, symbol_iterator)) |iter_method_t| {
            if (self.iteratorMethodReturnType(iter_method_t)) |iterator_t| {
                const value_t = try self.iteratorNextValueType(iterator_t);
                // When the iterator's next() return type has no `value`
                // member, `iteratorNextValueType` reports `none`. Surfacing
                // that to assignability would cascade into a spurious
                // TS2322 at the for-of target (e.g. `for-of15`). The
                // structural TS2490 already fires from
                // `checkForOfIteratorShape`; here we degrade to `any` so
                // downstream assignment checks don't double-report.
                return if (value_t == types.Primitive.none) types.Primitive.any else value_t;
            }
        }
        return types.Primitive.any;
    }

    fn asyncIterableElementType(self: *Checker, t: TypeId) CheckError!TypeId {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return types.Primitive.any;
        if (self.generator_type_info.get(t)) |iterable| return iterable.yield_type;
        if (t >= self.interner.pool.typeCount()) return types.Primitive.any;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            var elems: std.ArrayListUnmanaged(TypeId) = .empty;
            defer elems.deinit(self.gpa);
            for (self.interner.unionMembers(t)) |member| {
                try elems.append(self.gpa, try self.asyncIterableElementType(member));
            }
            return self.unionOrAny(elems.items);
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.isAsyncIterableLikeType(member)) return try self.asyncIterableElementType(member);
            }
            return types.Primitive.any;
        }
        if (!flags.is_object_type) return types.Primitive.any;
        const symbol_async_iterator = self.string_interner.intern("Symbol.asyncIterator") catch return error.OutOfMemory;
        const iter_method_t = self.interner.objectMember(t, symbol_async_iterator) orelse return types.Primitive.any;
        const iterator_t = self.iteratorMethodReturnType(iter_method_t) orelse return types.Primitive.any;
        const value_t = try self.asyncIteratorNextValueType(iterator_t);
        return if (value_t == types.Primitive.none) types.Primitive.any else value_t;
    }

    fn asyncIteratorNextValueType(self: *Checker, iterator_t: TypeId) CheckError!TypeId {
        if (iterator_t == types.Primitive.any or iterator_t == types.Primitive.unknown) return types.Primitive.any;
        if (iterator_t >= self.interner.pool.typeCount()) return types.Primitive.none;
        const flags = self.interner.pool.flagsOf(iterator_t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(iterator_t)) |member| {
                const value_t = try self.asyncIteratorNextValueType(member);
                if (value_t != types.Primitive.none) return value_t;
            }
            return types.Primitive.none;
        }
        if (!flags.is_object_type) return types.Primitive.none;
        const next_id = self.string_interner.intern("next") catch return error.OutOfMemory;
        const next_t = self.interner.objectMember(iterator_t, next_id) orelse return types.Primitive.none;
        if (next_t == types.Primitive.any or next_t == types.Primitive.unknown) return types.Primitive.any;
        const ret_t = self.interner.signatureReturn(next_t) orelse return types.Primitive.none;
        if (ret_t == types.Primitive.any or ret_t == types.Primitive.unknown) return types.Primitive.any;
        const awaited_t = self.evalAwaited(ret_t);
        if (awaited_t == types.Primitive.any or awaited_t == types.Primitive.unknown) return types.Primitive.any;
        if (awaited_t >= self.interner.pool.typeCount()) return types.Primitive.none;
        const value_id = self.string_interner.intern("value") catch return error.OutOfMemory;
        return self.interner.objectMember(awaited_t, value_id) orelse types.Primitive.none;
    }

    fn checkForOfIteratorShape(self: *Checker, node: NodeId, t: TypeId) CheckError!void {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return;
        if (t == types.Primitive.string_t) return;
        if (t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_string and !flags.is_object_type) return;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| try self.checkForOfIteratorShape(node, member);
            return;
        }
        if (!flags.is_object_type) return;
        if (self.interner.objectNumberIndex(t) != types.Primitive.none) return;
        const symbol_iterator = self.string_interner.intern("Symbol.iterator") catch return error.OutOfMemory;
        const iter_method_t = self.interner.objectMember(t, symbol_iterator) orelse return;
        if (self.typeHasNextMethod(t)) {
            const value_t = try self.iteratorNextValueType(t);
            if (value_t == types.Primitive.none) {
                try self.report(node, TsCodes.iterator_value_missing, "The type returned by the 'next()' method of an iterator must have a 'value' property.");
            }
            try self.checkIteratorReturnMethod(node, t);
            return;
        }
        if (self.iteratorMethodReturnType(iter_method_t)) |iterator_t| {
            if (iterator_t == types.Primitive.any or iterator_t == types.Primitive.unknown) {
                return;
            }
            if (!self.typeHasNextMethod(iterator_t)) {
                try self.report(node, TsCodes.yield_star_not_iterable, "Type must have a '[Symbol.iterator]()' method that returns an iterator.");
                return;
            }
            const value_t = try self.iteratorNextValueType(iterator_t);
            if (value_t == types.Primitive.none) {
                try self.report(node, TsCodes.iterator_value_missing, "The type returned by the 'next()' method of an iterator must have a 'value' property.");
            }
            try self.checkIteratorReturnMethod(node, iterator_t);
            return;
        }
        const next_id = self.string_interner.intern("next") catch return error.OutOfMemory;
        const next_t = self.interner.objectMember(t, next_id) orelse return;
        const ret_t = self.interner.signatureReturn(next_t) orelse return;
        if (ret_t == types.Primitive.any or ret_t == types.Primitive.unknown) return;
        const value_id = self.string_interner.intern("value") catch return error.OutOfMemory;
        if (self.interner.objectMember(ret_t, value_id) == null) {
            try self.report(node, TsCodes.iterator_value_missing, "The type returned by the 'next()' method of an iterator must have a 'value' property.");
        }
        try self.checkIteratorReturnMethod(node, t);
    }

    const IteratorNextUse = enum {
        for_of,
        array_spread,
        array_destructuring,
        yield_star,
    };

    fn checkIteratorNextSentType(self: *Checker, node: NodeId, source_t: TypeId, sent_t: TypeId, use: IteratorNextUse) CheckError!void {
        if (self.typeIsAnyLike(source_t) or self.typeIsAnyLike(sent_t)) return;
        const next_param_t = (try self.iteratorNextParameterType(source_t)) orelse return;
        if (self.typeIsAnyLike(next_param_t)) return;
        if (try self.iteratorSentTypeAssignable(sent_t, next_param_t)) return;

        const sent_name = (self.simpleDiagnosticTypeName(sent_t) catch null) orelse
            (self.allocSimpleTypeName(sent_t) catch null) orelse "unknown";
        const next_name = (self.simpleDiagnosticTypeName(next_param_t) catch null) orelse
            (self.allocSimpleTypeName(next_param_t) catch null) orelse "unknown";
        const code = switch (use) {
            .for_of => TsCodes.iterator_next_for_of_sent_type,
            .array_spread => TsCodes.iterator_next_array_spread_sent_type,
            .array_destructuring => TsCodes.iterator_next_array_destructuring_sent_type,
            .yield_star => TsCodes.iterator_next_yield_star_sent_type,
        };
        const msg = switch (use) {
            .for_of => try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot iterate value because the 'next' method of its iterator expects type '{s}', but for-of will always send '{s}'.",
                .{ next_name, sent_name },
            ),
            .array_spread => try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot iterate value because the 'next' method of its iterator expects type '{s}', but array spread will always send '{s}'.",
                .{ next_name, sent_name },
            ),
            .array_destructuring => try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot iterate value because the 'next' method of its iterator expects type '{s}', but array destructuring will always send '{s}'.",
                .{ next_name, sent_name },
            ),
            .yield_star => try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot delegate iteration to value because the 'next' method of its iterator expects type '{s}', but the containing generator will always send '{s}'.",
                .{ next_name, sent_name },
            ),
        };
        try self.report(node, code, msg);
    }

    fn iteratorSentTypeAssignable(self: *Checker, sent_t: TypeId, next_param_t: TypeId) CheckError!bool {
        if (sent_t == types.Primitive.undefined_t) {
            return next_param_t == types.Primitive.undefined_t or
                next_param_t == types.Primitive.void_t or
                self.typeIncludesUndefined(next_param_t);
        }
        return self.engine.isAssignableTo(sent_t, next_param_t) catch true;
    }

    fn iteratorNextParameterType(self: *Checker, source_t: TypeId) CheckError!?TypeId {
        if (source_t == types.Primitive.any or source_t == types.Primitive.unknown) return null;
        if (source_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(source_t);
        if (flags.is_union) {
            for (self.interner.unionMembers(source_t)) |member| {
                if (try self.iteratorNextParameterType(member)) |param_t| return param_t;
            }
            return null;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(source_t)) |member| {
                if (try self.iteratorNextParameterType(member)) |param_t| return param_t;
            }
            return null;
        }
        if (!flags.is_object_type) return null;

        const iterator_t = blk: {
            if (self.typeHasNextMethod(source_t)) break :blk source_t;
            if (self.interner.objectNumberIndex(source_t) != types.Primitive.none) return null;
            const symbol_iterator = self.string_interner.intern("Symbol.iterator") catch return error.OutOfMemory;
            const iter_method_t = self.interner.objectMember(source_t, symbol_iterator) orelse return null;
            const ret_t = self.iteratorMethodReturnType(iter_method_t) orelse return null;
            if (ret_t == types.Primitive.any or ret_t == types.Primitive.unknown) return null;
            break :blk ret_t;
        };
        if (iterator_t >= self.interner.pool.typeCount()) return null;
        if (self.interner.pool.flagsOf(iterator_t).is_object_type and
            self.interner.objectNumberIndex(iterator_t) != types.Primitive.none and
            !self.typeHasNextMethod(iterator_t))
        {
            return null;
        }
        const next_id = self.string_interner.intern("next") catch return error.OutOfMemory;
        const next_t = self.interner.objectMember(iterator_t, next_id) orelse return null;
        if (next_t == types.Primitive.any or next_t == types.Primitive.unknown) return null;
        const params = self.interner.signatureParams(next_t);
        if (params.len == 0) return null;
        return params[0];
    }

    fn checkForAwaitIteratorShape(self: *Checker, node: NodeId, t: TypeId) CheckError!void {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return;
        if (t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| try self.checkForAwaitIteratorShape(node, member);
            return;
        }
        if (!flags.is_object_type) return;
        const symbol_async_iterator = self.string_interner.intern("Symbol.asyncIterator") catch return error.OutOfMemory;
        const iter_method_t = self.interner.objectMember(t, symbol_async_iterator) orelse return;
        if (self.typeHasNextMethod(t)) {
            try self.checkAsyncIteratorNextValue(node, t);
            try self.checkAsyncIteratorReturnMethod(node, t);
            return;
        }
        if (self.iteratorMethodReturnType(iter_method_t)) |iterator_t| {
            if (iterator_t == types.Primitive.any or iterator_t == types.Primitive.unknown) return;
            if (!self.typeHasNextMethod(iterator_t)) return;
            try self.checkAsyncIteratorNextValue(node, iterator_t);
            try self.checkAsyncIteratorReturnMethod(node, iterator_t);
        }
    }

    fn checkIteratorReturnMethod(self: *Checker, node: NodeId, iterator_t: TypeId) CheckError!void {
        if (iterator_t == types.Primitive.any or iterator_t == types.Primitive.unknown) return;
        if (iterator_t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(iterator_t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(iterator_t)) |member| {
                try self.checkIteratorReturnMethod(node, member);
            }
            return;
        }
        if (!flags.is_object_type) return;
        const return_id = self.string_interner.intern("return") catch return error.OutOfMemory;
        const return_t = self.interner.objectMember(iterator_t, return_id) orelse return;
        if (return_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(return_t).is_signature) return;
        try self.report(node, TsCodes.iterator_return_must_be_method, "The 'return' property of an iterator must be a method.");
    }

    fn checkAsyncIteratorReturnMethod(self: *Checker, node: NodeId, iterator_t: TypeId) CheckError!void {
        if (iterator_t == types.Primitive.any or iterator_t == types.Primitive.unknown) return;
        if (iterator_t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(iterator_t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(iterator_t)) |member| {
                try self.checkAsyncIteratorReturnMethod(node, member);
            }
            return;
        }
        if (!flags.is_object_type) return;
        const return_id = self.string_interner.intern("return") catch return error.OutOfMemory;
        const return_t = self.interner.objectMember(iterator_t, return_id) orelse return;
        if (return_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(return_t).is_signature) return;
        try self.report(node, TsCodes.async_iterator_return_must_be_method, "The 'return' property of an async iterator must be a method.");
    }

    fn checkAsyncIteratorNextValue(self: *Checker, node: NodeId, iterator_t: TypeId) CheckError!void {
        if (iterator_t == types.Primitive.any) return;
        if (iterator_t == types.Primitive.unknown) {
            try self.reportAsyncIteratorNextValueMissing(node);
            return;
        }
        if (iterator_t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(iterator_t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(iterator_t)) |member| {
                try self.checkAsyncIteratorNextValue(node, member);
            }
            return;
        }
        if (!flags.is_object_type) return;
        const next_id = self.string_interner.intern("next") catch return error.OutOfMemory;
        const next_t = self.interner.objectMember(iterator_t, next_id) orelse return;
        if (next_t == types.Primitive.any) return;
        const ret_t = self.interner.signatureReturn(next_t) orelse return;
        if (ret_t == types.Primitive.any) return;
        if (ret_t == types.Primitive.unknown) {
            try self.reportAsyncIteratorNextValueMissing(node);
            return;
        }
        const awaited_t = self.evalAwaited(ret_t);
        if (awaited_t == ret_t) return;
        if (awaited_t == types.Primitive.any) return;
        if (awaited_t == types.Primitive.unknown) {
            try self.reportAsyncIteratorNextValueMissing(node);
            return;
        }
        if (awaited_t >= self.interner.pool.typeCount()) {
            try self.reportAsyncIteratorNextValueMissing(node);
            return;
        }
        const value_id = self.string_interner.intern("value") catch return error.OutOfMemory;
        if (self.interner.objectMember(awaited_t, value_id) == null) {
            try self.reportAsyncIteratorNextValueMissing(node);
        }
    }

    fn reportAsyncIteratorNextValueMissing(self: *Checker, node: NodeId) CheckError!void {
        try self.report(node, TsCodes.async_iterator_next_value_promise_missing, "The type returned by the 'next()' method of an async iterator must be a promise for a type with a 'value' property.");
    }

    fn iteratorMethodReturnType(self: *Checker, method_t: TypeId) ?TypeId {
        if (method_t == types.Primitive.any or method_t == types.Primitive.unknown) return method_t;
        if (self.interner.signatureReturn(method_t)) |ret_t| return ret_t;
        return null;
    }

    fn typeHasNextMethod(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| if (self.typeHasNextMethod(member)) return true;
            return false;
        }
        if (!flags.is_object_type) return false;
        const next_id = self.string_interner.intern("next") catch return false;
        return self.interner.objectMember(t, next_id) != null;
    }

    fn iteratorNextValueType(self: *Checker, t: TypeId) CheckError!TypeId {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return types.Primitive.any;
        if (t >= self.interner.pool.typeCount()) return types.Primitive.none;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                const value_t = try self.iteratorNextValueType(member);
                if (value_t != types.Primitive.none) return value_t;
            }
            return types.Primitive.none;
        }
        if (!flags.is_object_type) return types.Primitive.none;
        const next_id = self.string_interner.intern("next") catch return error.OutOfMemory;
        const next_t = self.interner.objectMember(t, next_id) orelse return types.Primitive.none;
        if (next_t == types.Primitive.any or next_t == types.Primitive.unknown) return types.Primitive.any;
        const ret_t = self.interner.signatureReturn(next_t) orelse return types.Primitive.none;
        if (ret_t == types.Primitive.any or ret_t == types.Primitive.unknown) return types.Primitive.any;
        const value_id = self.string_interner.intern("value") catch return error.OutOfMemory;
        return self.interner.objectMember(ret_t, value_id) orelse types.Primitive.none;
    }

    fn bindingPatternParameterElementType(self: *Checker, pattern_element: NodeId) CheckError!TypeId {
        if (self.hir.kindOf(pattern_element) != .parameter) return types.Primitive.any;
        const p = hir_mod.parameterOf(self.hir, pattern_element);
        if (p.name == hir_mod.none_node_id) return types.Primitive.any;
        return switch (self.hir.kindOf(p.name)) {
            .array_pattern => try self.arrayBindingPatternParameterType(p.name),
            else => types.Primitive.any,
        };
    }

    fn arrayBindingPatternParameterType(self: *Checker, pattern_node: NodeId) CheckError!TypeId {
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        const length_id = self.string_interner.intern("length") catch return error.OutOfMemory;
        // Walk the binding pattern first so we know whether a rest element
        // is present. When there's NO rest, the synthesized tuple type is
        // fixed-arity; render its `length` as a numeric literal so
        // `fixedTupleLength` resolves correctly. Without this, downstream
        // display code (e.g. `simpleDiagnosticTypeName`) would mistake the
        // tuple for a variadic `[any, any, ...any[]]` and TS2345 prose for
        // fixtures like `iterableArrayPattern10` would read with a
        // bogus rest tail. Mirrors upstream tsc which preserves the
        // fixed-length form when the binding has no rest.
        var has_rest = false;
        var fixed_idx: usize = 0;
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.flags.is_rest) {
                has_rest = true;
                break;
            }
            fixed_idx += 1;
        }
        const length_t: TypeId = if (has_rest)
            types.Primitive.number_t
        else
            (self.interner.internNumberLiteral(@floatFromInt(fixed_idx)) catch types.Primitive.number_t);
        try members.append(self.gpa, .{
            .name = length_id,
            .type = length_t,
            .is_optional = false,
            .is_readonly = false,
            .is_method = false,
        });
        var idx: usize = 0;
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.flags.is_rest) break;
            var nbuf: [12]u8 = undefined;
            const name_str = std.fmt.bufPrint(&nbuf, "{d}", .{idx}) catch return error.OutOfMemory;
            const name = self.string_interner.intern(name_str) catch return error.OutOfMemory;
            try members.append(self.gpa, .{
                .name = name,
                .type = try self.bindingPatternParameterElementType(e),
                .is_optional = ep.default_value != hir_mod.none_node_id,
                .is_readonly = false,
                .is_method = false,
            });
            idx += 1;
        }
        const number_index = if (has_rest) types.Primitive.any else types.Primitive.none;
        const tuple_t = self.interner.internObjectTypeWithIndex(members.items, types.Primitive.none, number_index) catch return error.OutOfMemory;
        try self.markTupleOrigin(tuple_t);
        return tuple_t;
    }

    fn arrayBindingPatternHasRest(self: *Checker, pattern_node: NodeId) bool {
        if (pattern_node == hir_mod.none_node_id or self.hir.kindOf(pattern_node) != .array_pattern) return false;
        for (hir_mod.patternElements(self.hir, pattern_node)) |e| {
            if (self.hir.kindOf(e) != .parameter) continue;
            const ep = hir_mod.parameterOf(self.hir, e);
            if (ep.flags.is_rest) return true;
        }
        return false;
    }

    /// Synthesize the parameter type for an object-binding-pattern
    /// parameter:
    /// `function f({ x: [a, b] }) {}` ÃÂ¢ÃÂÃÂ infers
    /// `{ x: [any, any] }`.
    /// `function f({ x, y = 0 } = { x: 0 }) {}` ÃÂ¢ÃÂÃÂ infers
    /// `{ x: number, y?: number }`. tsc derives the parameter type from
    /// the BINDING PATTERN shape (not the widened default), so every
    /// named element appears in the synthesized type. Member types
    /// prefer the parent-default property (when present), then fall
    /// back to the element-level default's widened type, then `any`.
    /// Mirrors the empty-baseline fixture `destructuringWithLiteralInitializers`.
    fn objectBindingPatternParameterType(self: *Checker, pattern_node: NodeId) CheckError!TypeId {
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        for (hir_mod.patternElements(self.hir, pattern_node)) |elem| {
            if (self.hir.kindOf(elem) != .parameter) continue;
            const p = hir_mod.parameterOf(self.hir, elem);
            if (p.flags.is_rest or p.name == hir_mod.none_node_id) continue;
            const key_name = (try self.objectBindingElementKeyName(elem, p.name)) orelse continue;
            // An element-level `= expr` default makes this slot
            // optional (callers may omit the property). The
            // default's widened type also serves as the member type
            // when no annotation is in scope. Mirrors the
            // `y?: number` shape on `{ y = 0 }` bindings.
            const has_own_default = p.default_value != hir_mod.none_node_id;
            const name_kind = self.hir.kindOf(p.name);
            var member_t: TypeId = if (name_kind == .array_pattern)
                try self.arrayBindingPatternParameterType(p.name)
            else if (name_kind == .object_pattern)
                try self.objectBindingPatternParameterType(p.name)
            else
                types.Primitive.any;
            if (has_own_default and member_t == types.Primitive.any) {
                const default_t = try self.checkExpression(p.default_value);
                const widened = self.widenForInference(default_t);
                if (!self.typeIsAnyLike(widened) and widened != types.Primitive.none) {
                    member_t = widened;
                }
            }
            try members.append(self.gpa, .{
                .name = key_name,
                .type = member_t,
                .is_optional = has_own_default,
                .is_readonly = false,
                .is_method = false,
            });
        }
        return self.interner.internObjectType(members.items) catch return error.OutOfMemory;
    }

    fn objectLiteralHasSymbolIteratorMethod(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .object_literal) return false;
        for (hir_mod.objectLiteralProps(self.hir, node)) |prop| {
            if (self.hir.kindOf(prop) != .object_property) continue;
            const op = hir_mod.objectPropertyOf(self.hir, prop);
            if (!op.is_method or !op.is_computed) continue;
            if (self.hir.kindOf(op.key) != .member_access) continue;
            const m = hir_mod.memberOf(self.hir, op.key);
            if (self.hir.kindOf(m.object) != .identifier) continue;
            const obj = hir_mod.identifierOf(self.hir, m.object);
            if (!std.mem.eql(u8, self.string_interner.get(obj.name), "Symbol")) continue;
            if (!std.mem.eql(u8, self.string_interner.get(m.name), "iterator")) continue;
            return true;
        }
        return false;
    }

    /// Walk a type's structural body in search of the given type
    /// parameter, accumulating the variance positions in which it
    /// occurs. Returns the combined variance:
    ///   - `.covariant` only ÃÂ¢ÃÂÃÂ output position (return / property /
    ///     array element / union member).
    ///   - `.contravariant` only ÃÂ¢ÃÂÃÂ input position (signature param).
    ///   - both ÃÂ¢ÃÂÃÂ `.invariant`.
    ///   - neither ÃÂ¢ÃÂÃÂ `.bivariant` (T is unused).
    fn inferVariance(self: *Checker, body_t: TypeId, param_id: TypeId) types.Variance {
        var saw_co = false;
        var saw_ct = false;
        var visited: std.AutoHashMapUnmanaged(VarianceVisit, void) = .empty;
        defer visited.deinit(self.gpa);
        self.scanVariance(body_t, param_id, .covariant, &saw_co, &saw_ct, &visited);
        if (saw_co and saw_ct) return .invariant;
        if (saw_co) return .covariant;
        if (saw_ct) return .contravariant;
        return .bivariant;
    }

    /// Recursive worker for `inferVariance`. `position` tracks the
    /// polarity of the slot being entered: `.covariant` for output
    /// positions, `.contravariant` for input positions, `.invariant`
    /// for read+write slots (the object of an indexed access),
    /// `.bivariant` to suppress recording (under `keyof`).
    fn scanVariance(
        self: *Checker,
        t: TypeId,
        param_id: TypeId,
        position: types.Variance,
        saw_co: *bool,
        saw_ct: *bool,
        visited: *std.AutoHashMapUnmanaged(VarianceVisit, void),
    ) void {
        if (t == param_id) {
            switch (position) {
                .covariant => saw_co.* = true,
                .contravariant => saw_ct.* = true,
                .invariant => {
                    saw_co.* = true;
                    saw_ct.* = true;
                },
                .bivariant => {},
            }
            return;
        }
        if (t < types.Primitive.first_dynamic) return;
        if (t >= self.interner.pool.typeCount()) return;
        const visit = VarianceVisit{ .type_id = t, .position = position };
        if (visited.contains(visit)) return;
        visited.put(self.gpa, visit, {}) catch return;
        const flags = self.interner.pool.flagsOf(t);
        const payload_idx = self.interner.pool.payloadOf(t);

        if (flags.is_signature) {
            if (payload_idx >= self.interner.pool.signature_payloads.items.len) return;
            for (self.interner.signatureParams(t)) |p| {
                self.scanVariance(p, param_id, flipVariance(position), saw_co, saw_ct, visited);
            }
            if (self.interner.signatureReturn(t)) |r| {
                self.scanVariance(r, param_id, position, saw_co, saw_ct, visited);
            }
            return;
        }
        if (flags.is_object_type) {
            if (payload_idx >= self.interner.pool.object_type_payloads.items.len) return;
            const members = self.interner.objectMembers(t);
            for (members) |m| {
                if (m.is_method) {
                    self.scanMethodSignatureVariance(m.type, param_id, position, saw_co, saw_ct, visited);
                } else {
                    self.scanVariance(m.type, param_id, position, saw_co, saw_ct, visited);
                }
            }
            const si = self.interner.objectStringIndex(t);
            if (si != types.Primitive.none) self.scanVariance(si, param_id, position, saw_co, saw_ct, visited);
            const ni = self.interner.objectNumberIndex(t);
            if (ni != types.Primitive.none) self.scanVariance(ni, param_id, position, saw_co, saw_ct, visited);
            return;
        }
        if (flags.is_union) {
            if (payload_idx >= self.interner.pool.union_payloads.items.len) return;
            for (self.interner.unionMembers(t)) |m| {
                self.scanVariance(m, param_id, position, saw_co, saw_ct, visited);
            }
            return;
        }
        if (flags.is_intersection) {
            if (payload_idx >= self.interner.pool.intersection_payloads.items.len) return;
            for (self.interner.intersectionMembers(t)) |m| {
                self.scanVariance(m, param_id, position, saw_co, saw_ct, visited);
            }
            return;
        }
        if (flags.is_tuple) {
            if (payload_idx >= self.interner.pool.tuple_payloads.items.len) return;
            const payload = self.interner.pool.tuple_payloads.items[payload_idx];
            const elems = self.interner.pool.tuple_element_pool.items[payload.elements_start .. payload.elements_start + payload.elements_len];
            for (elems) |e| {
                self.scanVariance(e.type, param_id, position, saw_co, saw_ct, visited);
            }
            return;
        }
        if (flags.is_keyof) {
            // `keyof T` is antitone: narrowing T can add/keep keys while
            // widening T can drop them, so the operand is contravariant.
            if (payload_idx >= self.interner.pool.keyof_payloads.items.len) return;
            const k = self.interner.pool.keyof_payloads.items[payload_idx];
            self.scanVariance(k.operand, param_id, flipVariance(position), saw_co, saw_ct, visited);
            return;
        }
        if (flags.is_indexed_access) {
            if (payload_idx >= self.interner.pool.indexed_access_payloads.items.len) return;
            const payload = self.interner.pool.indexed_access_payloads.items[payload_idx];
            // Object slot is read+write ÃÂ¢ÃÂÃÂ invariant. Index slot
            // stays at the surrounding polarity.
            self.scanVariance(payload.object, param_id, .invariant, saw_co, saw_ct, visited);
            self.scanVariance(payload.index, param_id, position, saw_co, saw_ct, visited);
            return;
        }
        if (flags.is_conditional) {
            if (payload_idx >= self.interner.pool.conditional_payloads.items.len) return;
            const c = self.interner.conditionalPayload(t);
            // The check/extends operands select a branch but do not
            // themselves contribute declaration-site variance. The selected
            // branch types carry the observable use-sites.
            self.scanVariance(c.true_branch, param_id, position, saw_co, saw_ct, visited);
            self.scanVariance(c.false_branch, param_id, position, saw_co, saw_ct, visited);
            return;
        }
        if (flags.is_mapped) {
            if (payload_idx >= self.interner.pool.mapped_payloads.items.len) return;
            const m = self.interner.mappedPayload(t);
            self.scanVariance(m.constraint, param_id, position, saw_co, saw_ct, visited);
            self.scanVariance(m.template, param_id, position, saw_co, saw_ct, visited);
            return;
        }
        if (flags.is_instantiation) {
            if (payload_idx >= self.interner.pool.instantiation_payloads.items.len) return;
            const payload = self.interner.pool.instantiation_payloads.items[payload_idx];
            const args = self.interner.pool.type_arg_pool.items[payload.args_start .. payload.args_start + payload.args_len];
            // Without per-origin variance metadata, treat each
            // type-argument slot at the surrounding polarity. A
            // future fixed-point pass can refine this.
            for (args) |a| {
                self.scanVariance(a, param_id, position, saw_co, saw_ct, visited);
            }
            return;
        }
        // Primitives, literals, and type parameters other than the
        // target ÃÂ¢ÃÂÃÂ nothing to walk.
    }

    fn scanMethodSignatureVariance(
        self: *Checker,
        t: TypeId,
        param_id: TypeId,
        position: types.Variance,
        saw_co: *bool,
        saw_ct: *bool,
        visited: *std.AutoHashMapUnmanaged(VarianceVisit, void),
    ) void {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) {
            self.scanVariance(t, param_id, position, saw_co, saw_ct, visited);
            return;
        }
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_signature) {
            self.scanVariance(t, param_id, position, saw_co, saw_ct, visited);
            return;
        }
        const payload_idx = self.interner.pool.payloadOf(t);
        if (payload_idx >= self.interner.pool.signature_payloads.items.len) return;
        for (self.interner.signatureParams(t)) |p| {
            if (self.firstSignatureType(p) != null) {
                self.scanVariance(p, param_id, flipVariance(position), saw_co, saw_ct, visited);
            } else {
                self.scanVariance(p, param_id, .bivariant, saw_co, saw_ct, visited);
            }
        }
        if (self.interner.signatureReturn(t)) |r| {
            self.scanVariance(r, param_id, position, saw_co, saw_ct, visited);
        }
    }

    fn checkVarianceAnnotationCompatibility(
        self: *Checker,
        alias_name: hir_mod.StringId,
        type_params: []const NodeId,
        param_ids: []const TypeId,
        body_t: TypeId,
    ) CheckError!void {
        var tp_ix: usize = 0;
        for (type_params) |tp_node| {
            if (self.hir.kindOf(tp_node) != .type_parameter) continue;
            if (tp_ix >= param_ids.len) break;
            const tp_id = param_ids[tp_ix];
            tp_ix += 1;

            const tpp = hir_mod.typeParameterOf(self.hir, tp_node);
            const variance_bits = tpp.variance;
            if (variance_bits == 0 or variance_bits == 3) continue;

            const actual = self.inferVariance(body_t, tp_id);
            const violates_covariant = variance_bits == 2 and (actual == .contravariant or actual == .invariant);
            const violates_contravariant = variance_bits == 1 and (actual == .covariant or actual == .invariant);
            if (!violates_covariant and !violates_contravariant) continue;

            const name = self.string_interner.get(alias_name);
            const message = if (variance_bits == 2)
                try std.fmt.allocPrint(self.gpa, "Type '{s}<sub-T>' is not assignable to type '{s}<super-T>' as implied by variance annotation.", .{ name, name })
            else
                try std.fmt.allocPrint(self.gpa, "Type '{s}<super-T>' is not assignable to type '{s}<sub-T>' as implied by variance annotation.", .{ name, name });
            defer self.gpa.free(message);
            try self.reportOnce(tp_node, TsCodes.variance_annotation_type_not_assignable, message);
        }
    }

    fn recheckDeferredVarianceAnnotations(self: *Checker, stmts: []const NodeId) CheckError!void {
        var has_deferred_work = false;
        for (stmts) |stmt| {
            const decl = if (self.hir.kindOf(stmt) == .export_decl)
                hir_mod.exportOf(self.hir, stmt).decl
            else
                stmt;
            if (decl == hir_mod.none_node_id or self.hir.kindOf(decl) != .type_alias_decl) continue;
            const ta = hir_mod.typeAliasOf(self.hir, decl);
            for (self.hir.childSlice(ta.type_params_start, ta.type_params_len)) |tp_node| {
                if (self.hir.kindOf(tp_node) != .type_parameter) continue;
                const variance = hir_mod.typeParameterOf(self.hir, tp_node).variance;
                if (variance == 1 or variance == 2) {
                    has_deferred_work = true;
                    break;
                }
            }
            if (has_deferred_work) break;
        }
        if (!has_deferred_work) return;

        // Forward aliases are initially lowered against placeholders. Refresh
        // the small declaration graph to a fixed point before measuring an
        // annotated alias, so a cycle such as Foo -> Fn -> Bar -> Foo carries
        // the root parameter back through the opposite polarity.
        const refresh_passes = @min(stmts.len, @as(usize, 4));
        for (0..refresh_passes) |_| {
            for (stmts) |stmt| {
                const decl = if (self.hir.kindOf(stmt) == .export_decl)
                    hir_mod.exportOf(self.hir, stmt).decl
                else
                    stmt;
                if (decl == hir_mod.none_node_id or self.hir.kindOf(decl) != .type_alias_decl) continue;
                try self.refreshGenericAliasBodyForVariance(decl);
            }
        }

        for (stmts) |stmt| {
            const decl = if (self.hir.kindOf(stmt) == .export_decl)
                hir_mod.exportOf(self.hir, stmt).decl
            else
                stmt;
            if (decl == hir_mod.none_node_id or self.hir.kindOf(decl) != .type_alias_decl) continue;
            try self.recheckDeferredVarianceAlias(decl);
        }
    }

    fn refreshGenericAliasBodyForVariance(self: *Checker, node: NodeId) CheckError!void {
        const ta = hir_mod.typeAliasOf(self.hir, node);
        if (ta.name == hir_mod.none_node_id or self.hir.kindOf(ta.name) != .identifier) return;
        const type_params = self.hir.childSlice(ta.type_params_start, ta.type_params_len);
        if (type_params.len == 0) return;
        const id = hir_mod.identifierOf(self.hir, ta.name);
        const info = self.generic_aliases.get(id.name) orelse return;
        if (info.params.len == 0) return;

        try self.pushNarrowScope();
        defer self.popNarrowScope();
        var param_index: usize = 0;
        for (type_params) |tp_node| {
            if (self.hir.kindOf(tp_node) != .type_parameter) continue;
            if (param_index >= info.params.len) return;
            try self.recordNarrow(hir_mod.typeParameterOf(self.hir, tp_node).name, info.params[param_index]);
            param_index += 1;
        }
        if (param_index != info.params.len) return;
        const diagnostic_count = self.diagnostics.items.len;
        const refreshed_body = self.lowererLowerWithTypeParams(ta.aliased) catch {
            self.diagnostics.shrinkRetainingCapacity(diagnostic_count);
            return;
        };
        self.diagnostics.shrinkRetainingCapacity(diagnostic_count);
        if (self.generic_aliases.getPtr(id.name)) |current| current.body = refreshed_body;
    }

    fn recheckDeferredVarianceAlias(self: *Checker, node: NodeId) CheckError!void {
        const ta = hir_mod.typeAliasOf(self.hir, node);
        if (ta.name == hir_mod.none_node_id or self.hir.kindOf(ta.name) != .identifier) return;
        if (!self.typeAliasBodyAllowsVarianceAnnotation(ta.aliased)) return;
        const type_params = self.hir.childSlice(ta.type_params_start, ta.type_params_len);
        if (type_params.len == 0) return;

        var has_directional_annotation = false;
        for (type_params) |tp_node| {
            if (self.hir.kindOf(tp_node) != .type_parameter) continue;
            const variance = hir_mod.typeParameterOf(self.hir, tp_node).variance;
            if (variance == 1 or variance == 2) {
                has_directional_annotation = true;
                break;
            }
        }
        if (!has_directional_annotation) return;

        const id = hir_mod.identifierOf(self.hir, ta.name);
        const info = self.generic_aliases.get(id.name) orelse return;
        if (info.params.len == 0) return;
        try self.pushNarrowScope();
        defer self.popNarrowScope();
        var param_index: usize = 0;
        for (type_params) |tp_node| {
            if (self.hir.kindOf(tp_node) != .type_parameter) continue;
            if (param_index >= info.params.len) return;
            const tp = hir_mod.typeParameterOf(self.hir, tp_node);
            try self.recordNarrow(tp.name, info.params[param_index]);
            param_index += 1;
        }
        if (param_index != info.params.len) return;
        const refreshed_body = try self.lowererLowerWithTypeParams(ta.aliased);
        try self.checkVarianceAnnotationCompatibility(id.name, type_params, info.params, refreshed_body);
    }

    /// Validate a `arg is T` / `asserts arg is T` type predicate
    /// against the enclosing signature's parameter list. Mirrors the
    /// `checkTypePredicate` checks in upstream tsc:
    ///   * TS1229 ÃÂ¢ÃÂÃÂ the named parameter is a rest parameter.
    ///   * TS1230 ÃÂ¢ÃÂÃÂ the named parameter is an element of a binding
    ///     pattern parameter (`function f({a, p1}): p1 is A`).
    ///   * TS1225 ÃÂ¢ÃÂÃÂ the named parameter does not exist at all.
    /// All three anchor on the predicate node, whose span begins at
    /// the parameter-name position. `this`-based predicates carry no
    /// positional parameter and are skipped.
    fn checkTypePredicateConstraints(self: *Checker, pred_node: NodeId, params: []const NodeId) CheckError!void {
        const pred = hir_mod.typePredicateOf(self.hir, pred_node);
        try self.checkTypeNodeGenericArgumentConstraints(pred.target_type);
        // `this is T` ÃÂ¢ÃÂÃÂ no parameter to validate.
        const this_id = self.string_interner.intern("this") catch return error.OutOfMemory;
        if (pred.param_name == this_id) {
            // Predicate target types are ordinary checked type positions.
            // Lower the otherwise-early-returning `this` form so nested
            // generic arguments are validated (`NeedsFoo<Bar>` -> TS2344).
            if (pred.target_type != hir_mod.none_node_id) {
                _ = try self.lowererLowerWithTypeParams(pred.target_type);
            }
            return;
        }

        if (pred.param_index != 0xFFFF) {
            // The predicate names a positional identifier parameter.
            // A rest parameter is always the trailing positional slot;
            // upstream forbids it (TS1229).
            const idx: usize = pred.param_index;
            if (idx < params.len and self.hir.kindOf(params[idx]) == .parameter) {
                const pp = hir_mod.parameterOf(self.hir, params[idx]);
                if (pp.flags.is_rest) {
                    try self.report(
                        pred_node,
                        TsCodes.type_predicate_references_rest_parameter,
                        "A type predicate cannot reference a rest parameter.",
                    );
                } else if (pred.target_type != hir_mod.none_node_id and
                    pp.type_annotation != hir_mod.none_node_id)
                {
                    // TS2677 â a type predicate's asserted type must be
                    // assignable to the named parameter's declared type.
                    // Mirrors upstream `checkTypePredicate`, which anchors
                    // the diagnostic at the predicate's type node.
                    const pred_t = self.lowererLowerWithTypeParams(pred.target_type) catch types.Primitive.none;
                    const param_t = self.lowererLowerWithTypeParams(pp.type_annotation) catch types.Primitive.none;
                    if (pred_t != types.Primitive.none and param_t != types.Primitive.none and
                        pred_t != types.Primitive.any and param_t != types.Primitive.any and
                        // A generic predicate can still be definitely
                        // incompatible with a concrete primitive parameter.
                        // `T[]` can never narrow `string`, while deferred
                        // conditional forms such as `Extract<Node, U>` may
                        // remain valid through their type-parameter constraint.
                        (!self.containsFreeTypeParameter(pred_t) or
                            param_t == types.Primitive.string_t or
                            param_t == types.Primitive.number_t or
                            param_t == types.Primitive.boolean_t or
                            param_t == types.Primitive.bigint_t or
                            param_t == types.Primitive.symbol_t) and
                        !(self.engine.isAssignableTo(pred_t, param_t) catch true))
                    {
                        try self.report(
                            pred.target_type,
                            TsCodes.type_predicate_type_not_assignable,
                            "A type predicate's type must be assignable to its parameter's type.",
                        );
                    }
                }
            }
            return;
        }

        // `param_index == 0xFFFF`: the name did not resolve to a
        // positional identifier parameter. It may still be declared
        // inside a binding-pattern parameter (TS1230); otherwise it
        // refers to nothing (TS1225).
        const name = self.string_interner.get(pred.param_name);
        for (params) |p| {
            if (self.hir.kindOf(p) != .parameter) continue;
            const pp = hir_mod.parameterOf(self.hir, p);
            if (pp.name == hir_mod.none_node_id) continue;
            const nk = self.hir.kindOf(pp.name);
            if (nk != .object_pattern and nk != .array_pattern) continue;
            if (self.bindingPatternDeclaresName(pp.name, pred.param_name)) {
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "A type predicate cannot reference element '{s}' in a binding pattern.",
                    .{name},
                );
                try self.report(pred_node, TsCodes.type_predicate_references_binding_element, msg);
                return;
            }
        }
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Cannot find parameter '{s}'.",
            .{name},
        );
        try self.report(pred_node, TsCodes.cannot_find_parameter, msg);
    }

    fn checkTypeNodeGenericArgumentConstraints(self: *Checker, node: NodeId) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .type_ref => {
                const ref = hir_mod.typeRefOf(self.hir, node);
                const args = hir_mod.typeRefArgs(self.hir, node);
                if (args.len > 0 and ref.qualifier_len == 0) {
                    if (!try self.checkEnclosingInterfaceTypeArgConstraints(node, ref.name, args)) {
                        const scoped = try self.scopedGenericInterfaceInfo(node, ref.name);
                        if (scoped orelse self.generic_aliases.get(ref.name)) |info| {
                            const count = @min(args.len, info.params.len);
                            for (args[0..count], info.params[0..count]) |arg, param| {
                                const arg_t = try self.lowererLowerWithTypeParams(arg);
                                try self.checkTypeArgSatisfiesConstraint(arg, param, arg_t);
                            }
                        }
                    }
                }
                for (args) |arg| try self.checkTypeNodeGenericArgumentConstraints(arg);
            },
            .union_type => for (hir_mod.unionTypeMembers(self.hir, node)) |member| {
                try self.checkTypeNodeGenericArgumentConstraints(member);
            },
            .intersection_type => for (hir_mod.intersectionTypeMembers(self.hir, node)) |member| {
                try self.checkTypeNodeGenericArgumentConstraints(member);
            },
            .array_type => try self.checkTypeNodeGenericArgumentConstraints(hir_mod.arrayTypeOf(self.hir, node).element),
            .tuple_type => for (hir_mod.tupleTypeElements(self.hir, node)) |element| {
                try self.checkTypeNodeGenericArgumentConstraints(element);
            },
            .optional_type => try self.checkTypeNodeGenericArgumentConstraints(hir_mod.optionalTypeOf(self.hir, node).operand),
            .rest_type => try self.checkTypeNodeGenericArgumentConstraints(hir_mod.restTypeOf(self.hir, node).operand),
            else => {},
        }
    }

    fn checkEnclosingInterfaceTypeArgConstraints(
        self: *Checker,
        anchor: NodeId,
        name: hir_mod.StringId,
        args: []const NodeId,
    ) CheckError!bool {
        var cur = self.hir.parentOf(anchor);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            if (self.hir.kindOf(cur) != .interface_decl) continue;
            const iface = hir_mod.interfaceOf(self.hir, cur);
            if (iface.name == hir_mod.none_node_id or self.hir.kindOf(iface.name) != .identifier) return false;
            if (hir_mod.identifierOf(self.hir, iface.name).name != name) return false;

            const params = self.hir.childSlice(iface.type_params_start, iface.type_params_len);
            const count = @min(args.len, params.len);
            for (args[0..count], params[0..count]) |arg, param_node| {
                const param_t = self.hir.typeOf(param_node);
                if (param_t == types.Primitive.none) continue;
                const arg_t = try self.lowererLowerWithTypeParams(arg);
                try self.checkTypeArgSatisfiesConstraint(arg, param_t, arg_t);
            }
            return true;
        }
        return false;
    }

    /// Run the signature-only pass of `checkFnDecl` ÃÂ¢ÃÂÃÂ type
    /// parameters, parameter annotations, return type, intern the
    /// signature ÃÂ¢ÃÂÃÂ without walking the body. The caller owns the
    /// narrow scope: a type-params scope is pushed here when the
    /// fn declares any, and the caller must pop it after the body
    /// walk so type-param references inside the body still resolve.
    fn checkFnSignatureOnly(self: *Checker, node: NodeId) CheckError!TypeId {
        const f = hir_mod.fnDeclOf(self.hir, node);
        // Surface JS-file TS-only signature syntax. Type parameter
        // lists are syntax errors even without `@checkJs`; annotations
        // stay gated to checked JS below.
        try self.checkJsOnlySignatureAnnotations(node);
        try self.checkJsDocThisTagOnArrowFunction(node);
        try self.checkJsDocFunctionTypeReturnAnnotations(node);
        try self.checkUnmatchedJsDocParameters(node);
        try self.checkJsDocTemplateBracketedName(node);
        const type_params = hir_mod.fnTypeParams(self.hir, node);
        const has_jsdoc_templates = self.fnHasJsDocTemplateTags(node);
        try self.checkTypeParameterDeclList(type_params);
        try self.checkFunctionSignatureLocalTypeVisibility(node, type_params);
        if (type_params.len > 0 or has_jsdoc_templates) try self.pushNarrowScope();
        for (type_params) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            const tpp = hir_mod.typeParameterOf(self.hir, tp);
            const placeholder = self.interner.internFreshTypeParameterWithFlags(
                tpp.name,
                types.Primitive.unknown,
                types.Primitive.none,
                types.Variance.fromHirBits(tpp.variance),
                tpp.is_const,
            ) catch return error.OutOfMemory;
            self.hir.setType(tp, placeholder);
            try self.recordNarrow(tpp.name, placeholder);
        }
        var captured_tp_ids: std.ArrayListUnmanaged(TypeId) = .empty;
        defer captured_tp_ids.deinit(self.gpa);
        for (type_params) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            const tpp = hir_mod.typeParameterOf(self.hir, tp);
            const placeholder = self.hir.typeOf(tp);
            const constraint: TypeId = if (tpp.constraint != hir_mod.none_node_id)
                try self.lowererLowerWithTypeParams(tpp.constraint)
            else
                types.Primitive.unknown;
            const def: TypeId = if (tpp.default != hir_mod.none_node_id)
                try self.lowererLowerWithTypeParams(tpp.default)
            else
                types.Primitive.none;
            const tp_id = if (tpp.constraint == hir_mod.none_node_id and tpp.default == hir_mod.none_node_id)
                (self.lookupNarrow(tpp.name) orelse self.hir.typeOf(tp))
            else
                self.interner.internFreshTypeParameterWithFlags(
                    tpp.name,
                    constraint,
                    def,
                    types.Variance.fromHirBits(tpp.variance),
                    tpp.is_const,
                ) catch return error.OutOfMemory;
            if (placeholder != types.Primitive.none and placeholder != tp_id) {
                try self.type_parameter_placeholder_targets.put(self.gpa, placeholder, tp_id);
            }
            self.hir.setType(tp, tp_id);
            try self.recordNarrow(tpp.name, tp_id);
            try captured_tp_ids.append(self.gpa, tp_id);
        }
        try self.recordJsDocTemplateTypeParams(node, &captured_tp_ids);
        // A prototype method can reference its constructor's class-level
        // `@template` params; record them too (only meaningful when a narrow
        // scope was pushed above for this function's own type params/templates).
        if (type_params.len > 0 or has_jsdoc_templates) {
            try self.recordEnclosingPrototypeMethodConstructorTemplates(node);
        }

        var param_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer param_types.deinit(self.gpa);
        var param_omittable: std.ArrayListUnmanaged(bool) = .empty;
        defer param_omittable.deinit(self.gpa);
        var param_predicates: std.ArrayListUnmanaged(ParamPredicateEntry) = .empty;
        defer param_predicates.deinit(self.gpa);
        var param_nullish_array_defaults: std.ArrayListUnmanaged(bool) = .empty;
        defer param_nullish_array_defaults.deinit(self.gpa);
        const params = hir_mod.fnParams(self.hir, node);
        const jsdoc_context_sig = try self.jsDocContextualSignatureForFunction(node);
        const has_jsdoc_type_tag = try self.jsDocFunctionHasTypeTag(node);
        var has_rest_param = false;
        var explicit_this_t: TypeId = types.Primitive.none;
        var value_param_index: u16 = 0;
        var previous_jsdoc_optional_param = false;
        if (params.len == 0 and self.sourceHasCheckJsDirective()) {
            try self.applyArgumentsJsDocParamTags(node, &param_types, &param_omittable, &has_rest_param);
        }
        // Pre-scan: if this is an accessor (`get`/`set`) and any
        // parameter is a `this:` param (which is invalid ÃÂ¢ÃÂÃÂ TS2784
        // already fires), upstream tsc also suppresses TS7006 for any
        // accompanying (untyped) value parameters since the whole
        // signature shape is already malformed. Mirrors fixture
        // `thisTypeInAccessorsNegative`.
        var accessor_has_invalid_this = false;
        if (f.flags.is_getter or f.flags.is_setter) {
            for (params) |p_scan| {
                if (self.isThisParameter(p_scan)) {
                    accessor_has_invalid_this = true;
                    break;
                }
            }
        }
        for (params, 0..) |p, param_index| {
            const pp = hir_mod.parameterOf(self.hir, p);
            const is_this_param = self.isThisParameter(p);
            try self.checkParameterDecoratorDiagnostics(p, node, param_index, is_this_param);
            if (f.body == hir_mod.none_node_id and pp.default_value != hir_mod.none_node_id) {
                try self.report(p, TsCodes.parameter_initializer_implementation_only, "A parameter initializer is only allowed in a function or constructor implementation.");
            }
            if (is_this_param and (param_index != 0 or pp.flags.is_rest)) {
                const report_node = if (pp.flags.is_rest and pp.name != hir_mod.none_node_id) pp.name else p;
                try self.report(report_node, TsCodes.this_parameter_must_be_first, "A 'this' parameter must be the first parameter.");
            }
            // TS2784 ÃÂ¢ÃÂÃÂ `get x(this: T): U {}` / `set x(this: T,
            // value: V) {}` are forbidden. Mirrors upstream
            // `thisTypeInAccessors.ts(8,11)`. Fire on the `this`
            // parameter node itself so the column matches.
            if (is_this_param and (f.flags.is_getter or f.flags.is_setter)) {
                try self.report(p, TsCodes.accessors_cannot_declare_this, "'get' and 'set' accessors cannot declare 'this' parameters.");
            }
            // TS2681 Ã¢ÂÂ a constructor declaration cannot declare a
            // `this` parameter. Mirrors upstream `checkParameter`,
            // which fires on the parameter node itself. Fires
            // regardless of position so it can co-occur with TS2680.
            if (is_this_param and f.flags.is_constructor) {
                try self.reportOnce(p, TsCodes.constructor_cannot_have_this_parameter, "A constructor cannot have a 'this' parameter.");
            }
            if (!is_this_param) {
                try param_nullish_array_defaults.append(
                    self.gpa,
                    pp.default_value != hir_mod.none_node_id and
                        (try self.nullishArrayLiteralTypeFromSyntax(pp.default_value)) != null,
                );
            }
            if (pp.flags.is_rest and !is_this_param) has_rest_param = true;
            const has_anno = pp.type_annotation != hir_mod.none_node_id;
            const js_default_is_empty_array = !has_anno and
                pp.default_value != hir_mod.none_node_id and
                self.sourceHasCheckJsDirective() and
                self.virtualSectionIsJsLike(node) and
                self.hir.kindOf(pp.default_value) == .array_literal and
                hir_mod.arrayLiteralElements(self.hir, pp.default_value).len == 0;
            const js_default_is_loose_nullish = !has_anno and
                pp.default_value != hir_mod.none_node_id and
                self.sourceHasCheckJsDirective() and
                self.virtualSectionIsJsLike(node) and
                !self.strict_flags.strict_null_checks and
                (self.hir.kindOf(pp.default_value) == .literal_null or
                    self.hir.kindOf(pp.default_value) == .literal_undefined);
            // Sweep param annotations for unresolved bare type-refs ÃÂ¢ÃÂÃÂ
            // for body-ful fns too. Mirrors upstream tsc, which fires
            // TS2304 on `function foo(x: V) { ... }` when `V` is not
            // declared anywhere. See
            // `typeParameterUsedAsTypeParameterConstraint4.ts`.
            if (has_anno) {
                try self.reportUnresolvedBodylessSignatureTypeRefs(pp.type_annotation, type_params);
            }
            const jsdoc_param_info: ?JsDocParamInfo = if (!has_anno and !is_this_param and self.sourceHasCheckJsDirective())
                if (pp.name != hir_mod.none_node_id and self.hir.kindOf(pp.name) == .identifier)
                    try self.jsDocParamInfoForFunctionParam(
                        node,
                        self.string_interner.get(hir_mod.identifierOf(self.hir, pp.name).name),
                    )
                else if (pp.name != hir_mod.none_node_id and
                    (self.hir.kindOf(pp.name) == .object_pattern or self.hir.kindOf(pp.name) == .array_pattern))
                    try self.jsDocParamInfoForFunctionParamIndex(node, value_param_index)
                else
                    null
            else
                null;
            const jsdoc_param_t: ?TypeId = if (jsdoc_param_info) |info| info.typ else null;
            const jsdoc_marks_optional = if (jsdoc_param_info) |info| info.optional else false;
            const has_jsdoc_param_type = jsdoc_param_t != null;
            if (pp.name != hir_mod.none_node_id and
                (self.hir.kindOf(pp.name) == .object_pattern or self.hir.kindOf(pp.name) == .array_pattern) and
                jsdoc_marks_optional and
                pp.default_value == hir_mod.none_node_id and
                f.body != hir_mod.none_node_id)
            {
                try self.report(pp.name, TsCodes.binding_pattern_optional_parameter, "A binding pattern parameter cannot be optional in an implementation signature.");
            }
            if (!is_this_param and self.sourceHasCheckJsDirective()) {
                // A parameter marked optional via JSDoc (`@param {T} [name]`
                // or `@param {T=}`) is not "required", so it must not trip the
                // required-after-optional check (checkJsdocParamTag1).
                const is_required_now = !pp.flags.is_optional and
                    !pp.flags.is_rest and
                    pp.default_value == hir_mod.none_node_id and
                    !jsdoc_marks_optional;
                if (is_required_now and previous_jsdoc_optional_param) {
                    const anchor = if (pp.name != hir_mod.none_node_id) pp.name else p;
                    try self.report(anchor, TsCodes.required_parameter_after_optional, "A required parameter cannot follow an optional parameter.");
                }
                previous_jsdoc_optional_param = jsdoc_marks_optional;
            }
            // `f(x = literal)` ÃÂ¢ÃÂÃÂ when no annotation is present, the
            // default value's widened type seeds the parameter (tsc
            // does the same). Used by both the parameter typing pass
            // and the TS7006 implicit-any gate below; concrete types
            // (`number`, `string`, ÃÂ¢ÃÂÃÂ¦) suppress the diagnostic, but an
            // `any` default still falls through and reports.
            var inferred_from_default = false;
            const iife_context_t: ?TypeId = if (!has_anno and pp.default_value == hir_mod.none_node_id)
                try self.iifeParameterTypeFromCallArgument(node, param_index, pp.flags.is_rest)
            else
                null;
            const jsdoc_context_param_t: ?TypeId = if (!has_anno and !has_jsdoc_param_type and !is_this_param) blk: {
                const sig = jsdoc_context_sig orelse break :blk null;
                const sig_params = self.interner.signatureParams(sig);
                if (value_param_index >= sig_params.len) break :blk null;
                break :blk sig_params[value_param_index];
            } else null;
            const contextual_tuple_param_t: ?TypeId = if (!has_anno and !has_jsdoc_param_type and !is_this_param) blk: {
                if (try self.contextualParameterTypeFromFunctionAnnotation(node, p)) |syntax_t| {
                    break :blk syntax_t;
                }
                const target_t = (self.contextualTupleElementTargetForFunction(node) catch null) orelse break :blk null;
                break :blk self.contextualParameterTypeForFunctionParam(node, p, target_t);
            } else null;
            const returned_function_context_t: ?TypeId = if (!has_anno and !has_jsdoc_param_type and !is_this_param) blk: {
                const parent = self.hir.parentOf(node);
                if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .return_stmt) break :blk null;
                break :blk self.returnedFunctionContextualParameterType(parent, node, p);
            } else null;
            const contextual_param_t: ?TypeId = if (!has_anno and
                !has_jsdoc_param_type and
                !is_this_param and
                pp.default_value == hir_mod.none_node_id)
            blk: {
                const parent = self.hir.parentOf(node);
                if (parent == hir_mod.none_node_id) break :blk null;
                switch (self.hir.kindOf(parent)) {
                    .assignment, .var_decl, .let_decl, .const_decl => {},
                    else => break :blk null,
                }
                if (try self.contextualParameterTypeFromFunctionAnnotation(node, p)) |syntax_t| {
                    break :blk syntax_t;
                }
                const target_t = self.contextualTargetTypeForFunction(node) orelse break :blk null;
                if (target_t >= self.interner.pool.typeCount()) break :blk null;
                if (self.containsFreeTypeParameter(target_t)) break :blk null;
                break :blk self.contextualParameterTypeForFunctionParam(node, p, target_t);
            } else null;
            const contextual_default_param_t: ?TypeId = if (!has_anno and !has_jsdoc_param_type and !is_this_param and
                pp.default_value != hir_mod.none_node_id)
            blk: {
                const target_t = self.contextualTargetTypeForFunction(node) orelse break :blk null;
                const context_t = self.contextualParameterTypeForFunctionParam(node, p, target_t) orelse break :blk null;
                if (self.typeIncludesUndefined(context_t)) {
                    const without_undefined = self.subtractType(context_t, types.Primitive.undefined_t) catch context_t;
                    if (without_undefined != types.Primitive.never and without_undefined != types.Primitive.none) {
                        break :blk without_undefined;
                    }
                }
                break :blk context_t;
            } else null;
            // An un-annotated callback passed to a built-in array
            // iteration method (`arr.map((x) => ÃÂ¢ÃÂÃÂ¦)`) gets its first
            // parameter contextually typed to the array element type
            // ÃÂ¢ÃÂÃÂ mirroring tsc's generic callback inference. Only the
            // IIFE path takes precedence; otherwise this seeds `x`.
            const array_callback_context_t: ?TypeId = if (!has_anno and !is_this_param and
                !pp.flags.is_rest and pp.default_value == hir_mod.none_node_id and iife_context_t == null)
                try self.arrayCallbackParameterElementType(node, param_index)
            else
                null;
            const t: TypeId = if (has_anno) blk: {
                const lowered_annotation_t = try self.lowererLowerWithTypeParams(pp.type_annotation);
                break :blk if (self.typeAnnotationShouldBecomeErrorAny(pp.type_annotation))
                    types.Primitive.any
                else
                    lowered_annotation_t;
            }
            else if (jsdoc_param_t) |jt|
                jt
            else if (jsdoc_context_param_t) |jt|
                jt
            else if (contextual_tuple_param_t) |context_t|
                context_t
            else if (returned_function_context_t) |context_t|
                context_t
            else if (contextual_param_t) |context_t|
                context_t
            else if (contextual_default_param_t) |context_t|
                context_t
            else if (pp.default_value != hir_mod.none_node_id and
                pp.name != hir_mod.none_node_id and
                self.hir.kindOf(pp.name) == .array_pattern)
                try self.checkExpression(pp.default_value)
            else if (pp.name != hir_mod.none_node_id and
                self.hir.kindOf(pp.name) == .array_pattern and
                (pp.flags.is_rest or self.arrayBindingPatternHasRest(pp.name) or pp.default_value == hir_mod.none_node_id))
                try self.arrayBindingPatternParameterType(pp.name)
            else if (pp.name != hir_mod.none_node_id and
                self.hir.kindOf(pp.name) == .object_pattern and
                !is_this_param)
                // `function f({ x: [a, b] }) {}` ÃÂ¢ÃÂÃÂ tsc infers the
                // parameter type from the BINDING PATTERN's shape
                // (`{ x: [any, any] }`). A parent default can seed
                // element types, but the pattern itself still controls
                // which members exist. Mirrors
                // `destructuringWithLiteralInitializers` and keeps
                // destructured object parameters from collapsing to
                // `any` when no annotation/default is present.
                try self.objectBindingPatternParameterType(pp.name)
            else if (pp.default_value != hir_mod.none_node_id and !is_this_param) blk_default: {
                if (js_default_is_loose_nullish) break :blk_default types.Primitive.any;
                const default_t = if (try self.nullishArrayLiteralTypeFromSyntax(pp.default_value)) |nullish_array_t|
                    nullish_array_t
                else
                    try self.checkExpression(pp.default_value);
                const widened = if (self.hir.kindOf(pp.default_value) == .array_literal and
                    self.arrayParameterElementTypeIsNullishOnly(default_t))
                    default_t
                else
                    self.widenForInference(default_t);
                if (!js_default_is_empty_array and
                    !self.typeIsAnyLike(widened) and widened != types.Primitive.none)
                {
                    inferred_from_default = true;
                }
                break :blk_default widened;
            } else if (iife_context_t) |context_t|
                context_t
            else if (array_callback_context_t) |context_t|
                context_t
            else
                types.Primitive.any;
            const declared_param_t = t;
            if (!has_anno and pp.name != hir_mod.none_node_id and self.hir.kindOf(pp.name) == .object_pattern) {
                _ = try self.checkObjectBindingComputedKeysAgainstType(pp.name, declared_param_t);
            }
            if (has_anno and pp.name != hir_mod.none_node_id) {
                const name_kind = self.hir.kindOf(pp.name);
                if (name_kind == .array_pattern or name_kind == .object_pattern) {
                    _ = try self.checkBindingPatternSourceType(pp.name, declared_param_t, hir_mod.none_node_id);
                }
            }
            if ((has_anno or jsdoc_context_param_t != null) and pp.default_value != hir_mod.none_node_id) {
                const default_t = try self.checkExpression(pp.default_value);
                const literal_ok = try self.literalExpressionAssignableToTarget(pp.default_value, declared_param_t);
                const array_literal_ok = self.hir.kindOf(pp.default_value) == .array_literal and
                    try self.arrayLiteralAssignableToTargetInner(pp.default_value, declared_param_t, false);
                const loose_nullish_ok = !self.strict_flags.strict_null_checks and
                    (default_t == types.Primitive.null_t or default_t == types.Primitive.undefined_t);
                if (!literal_ok and
                    !array_literal_ok and
                    !loose_nullish_ok and
                    (self.typeParameterAssignmentNeedsInstantiationCheck(default_t, declared_param_t) or
                        !(self.engine.isAssignableTo(default_t, declared_param_t) catch true)))
                {
                    // Plain parameters anchor at the parameter name,
                    // while constructor parameter properties anchor at
                    // the first property modifier (`public`, `readonly`,
                    // etc.) and underline the whole parameter property.
                    const anchor = if (jsdoc_context_param_t != null)
                        p
                    else if (pp.flags.is_parameter_property)
                        p
                    else if (pp.name != hir_mod.none_node_id)
                        pp.name
                    else
                        p;
                    try self.reportPlainTypeNotAssignable(
                        anchor,
                        default_t,
                        declared_param_t,
                        "Parameter initializer is not assignable to parameter type.",
                    );
                }
            }
            // TS2370 ÃÂ¢ÃÂÃÂ `function f(...x: T)` requires `T` to be an
            // array type (any tuple, `T[]`, `Array<T>`, etc.). The
            // syntax check covers `Array<T>` / `ReadonlyArray<T>`
            // even when the lib types haven't been bound for a
            // fixture; the type-level check handles bare
            // identifiers / aliases that resolve to array shapes
            // through the interner.
            if (pp.flags.is_rest and !is_this_param and has_anno and
                !self.restParamAnnotationLooksArrayLike(pp.type_annotation) and
                !self.restParamTypeIsValidArrayLike(declared_param_t))
            {
                try self.report(p, TsCodes.rest_parameter_must_be_array_type, "A rest parameter must be of an array type.");
            }
            // Without an annotation, tsc still emits TS2370 when the
            // inferred symbol type isn't assignable to a readonly any[]:
            //   * `function f(...bar = 0)` ÃÂ¢ÃÂÃÂ inferred from initializer
            //      (here `0` ÃÂ¢ÃÂÃÂ `number`), which fails the array check.
            //   * `(...arg?) => ÃÂ¢ÃÂÃÂ¦`         ÃÂ¢ÃÂÃÂ arrow-function rest with
            //      `?` widens to `any | undefined`, not an array
            //      (class methods don't trip this ÃÂ¢ÃÂÃÂ they resolve to
            //      plain `any` which IS assignable to `any[]`).
            // Mirrors `parserParameterList10.ts` and `parserParameterList11.ts`.
            if (pp.flags.is_rest and !is_this_param and !has_anno) {
                const malformed_initializer = inferred_from_default and
                    !self.restParamTypeIsValidArrayLike(declared_param_t);
                const optional_in_arrow = pp.flags.is_optional and
                    self.hir.kindOf(self.hir.parentOf(p)) == .arrow_fn;
                if (malformed_initializer or optional_in_arrow) {
                    try self.report(p, TsCodes.rest_parameter_must_be_array_type, "A rest parameter must be of an array type.");
                }
            }
            // `f(x?: T)` and `f(x: T = default)` both widen the
            // signature parameter type to include `undefined` so
            // callers can omit the arg. Inside the function body
            // however, an `?:` parameter is still observably
            // `T | undefined`, while a defaulted `= expr` parameter
            // is just `T` because the default fills in for undefined
            // before the body runs. Mirrors tsc's control-flow
            // narrowing for defaulted params.
            var signature_t: TypeId = t;
            if (pp.flags.is_optional or jsdoc_marks_optional or pp.default_value != hir_mod.none_node_id) {
                signature_t = self.unionWithUndefined(t) catch t;
            }
            const body_t: TypeId = if ((pp.flags.is_optional or jsdoc_marks_optional) and pp.default_value == hir_mod.none_node_id)
                signature_t
            else
                t;
            self.hir.setType(p, body_t);
            if (pp.name != hir_mod.none_node_id) self.hir.setType(pp.name, body_t);
            if (is_this_param) {
                if (f.flags.is_arrow) {
                    try self.report(p, TsCodes.arrow_function_cannot_have_this_parameter, "An arrow function cannot have a 'this' parameter.");
                }
                explicit_this_t = body_t;
                continue;
            }
            try param_types.append(self.gpa, signature_t);
            try param_omittable.append(self.gpa, pp.flags.is_rest or
                (!has_anno and
                    !has_jsdoc_param_type and
                    jsdoc_context_param_t == null and
                    !has_jsdoc_type_tag and
                    self.virtualSectionIsJsLike(node)) or
                pp.flags.is_optional or
                jsdoc_marks_optional or
                pp.default_value != hir_mod.none_node_id or
                self.parameterTypeAllowsVoidOmission(t));
            if (self.signature_predicates.get(t)) |param_pred| {
                try param_predicates.append(self.gpa, .{ .param_index = value_param_index, .pred = param_pred });
            }
            value_param_index += 1;
            // Suppress TS7006 when the default-value initializer is
            // an `await` expression with no operand ÃÂ¢ÃÂÃÂ i.e. the parser
            // already emitted TS2524 + TS1109 for `f(a = await)` /
            // similar inside an async function. Mirrors tsc's
            // `asyncFunctionDeclaration6/7_es*` baselines which omit
            // the implicit-any diagnostic when the initializer parse
            // failed in this specific shape.
            const default_is_await_error_placeholder = pp.default_value != hir_mod.none_node_id and
                self.hir.kindOf(pp.default_value) == .await_expr and
                hir_mod.awaitExprOf(self.hir, pp.default_value).expr == hir_mod.none_node_id;
            // `function * foo(a = yield)` ÃÂ¢ÃÂÃÂ tsc emits TS2523 ("yield
            // expressions cannot be used in a parameter initializer.")
            // and SKIPS the outer TS7006 for the parameter itself.
            // The companion TS7057 on the yield expression is emitted
            // by the parser at the same TS2523 site (so the relative
            // ordering matches tsc, and parse-recovery shapes that
            // tsc treats as already-broken ÃÂ¢ÃÂÃÂ e.g. `a = yield => ÃÂ¢ÃÂÃÂ¦`
            // in `FunctionDeclaration10_es6` ÃÂ¢ÃÂÃÂ can skip the TS7057
            // without re-deriving the recovery from the HIR).
            const default_is_yield_in_param_initializer = pp.default_value != hir_mod.none_node_id and
                self.hir.kindOf(pp.default_value) == .yield_expr;
            // Implicit-any reporting fires under noImplicitAny (hard
            // error: TS7006/TS7019) OR, when suggestions are enabled and
            // noImplicitAny is OFF, as the `.suggestion`-category hint
            // (TS7044/TS7047 "a better type may be inferred from usage").
            // Mirrors tsc `reportImplicitAny`'s `errorOrSuggestion`.
            const param_implicit_any_report = self.strict_flags.no_implicit_any or
                (self.emit_implicit_any_suggestions and !self.strict_flags.no_implicit_any);
            const constructor_default_infers_this = f.flags.is_constructor and
                pp.default_value != hir_mod.none_node_id and
                self.expressionContainsThis(pp.default_value);
            if (!has_anno and !has_jsdoc_param_type and jsdoc_context_param_t == null and
                !inferred_from_default and param_implicit_any_report and
                !default_is_await_error_placeholder and
                !default_is_yield_in_param_initializer and
                !constructor_default_infers_this and
                !accessor_has_invalid_this and
                !self.parameterInEs5ObjectLiteralSetterWithSuper(p) and
                !(self.functionOrOwnerHasLeadingJsDocParamOrTypeTag(node) and
                    !self.fnIsJsDocConstructorOverloadImplementation(node)) and
                !self.functionIsPrivateAmbientClassMember(node) and
                !self.parameterHasContextualType(node, p))
            {
                // Binding-pattern parameters (`function f([a, b]) {}` /
                // `function f({a, b}) {}`) ÃÂ¢ÃÂÃÂ tsc reports one TS7031
                // per *named* binding element rather than a single
                // TS7006 for the whole anonymous parameter. The
                // `<anonymous>` placeholder we used here previously
                // produced a single spurious diagnostic with the
                // wrong code, span, and (typically) name.
                const name_kind: hir_mod.NodeKind = if (pp.name != hir_mod.none_node_id) self.hir.kindOf(pp.name) else .identifier;
                const param_is_suggestion = !self.strict_flags.no_implicit_any;
                if (pp.name != hir_mod.none_node_id and (name_kind == .array_pattern or name_kind == .object_pattern)) {
                    // tsc does NOT issue suggestions for binding elements
                    // (the codefix doesn't support them), so the per-element
                    // TS7031 family stays error-only.
                    if (param_is_suggestion) {
                        // no-op under !noImplicitAny
                    } else
                    // A parameter-level default supplies the binding
                    // pattern's contextual type, so tsc suppresses the
                    // per-element implicit-any diagnostics there
                    // (`function f([a] = [undefined]) {}`).
                    if (pp.default_value == hir_mod.none_node_id) {
                        try self.reportImplicitAnyBindingPatternElements(pp.name, &.{});
                    } else if (name_kind == .array_pattern and
                        self.hir.kindOf(pp.default_value) == .array_literal)
                    {
                        // `function f([x, y] = [1])` ÃÂ¢ÃÂÃÂ when the default is
                        // an array literal, tsc still emits TS7031 for any
                        // binding element whose index isn't filled in by
                        // the default. Pass the literal's element nodes so
                        // each slot can be checked individually. Mirrors
                        // `destructuringWithLiteralInitializers2` lines 2/3/7/8.
                        const init_values = hir_mod.arrayLiteralElements(self.hir, pp.default_value);
                        try self.reportImplicitAnyBindingPatternElements(pp.name, init_values);
                    } else if (name_kind == .object_pattern) {
                        try self.reportImplicitAnyEmptyArrayBindingDefaults(pp.name);
                    }
                } else {
                    const raw_param_name: []const u8 = if (pp.name != hir_mod.none_node_id and name_kind == .identifier)
                        self.string_interner.get(hir_mod.identifierOf(self.hir, pp.name).name)
                    else
                        "<anonymous>";
                    const param_name = if (raw_param_name.len == 0) "(Missing)" else raw_param_name;
                    // In `.js` files (or `// @allowJs` virtual sections),
                    // a leading JSDoc `@param {T} <name>` annotates the
                    // parameter and suppresses TS7006. Mirrors upstream tsc
                    // which treats the JSDoc tag as the parameter type.
                    if (self.sourceHasCheckJsDirective() and
                        self.fnHasLeadingJsDocParam(node, param_name))
                    {
                        // Skip ÃÂ¢ÃÂÃÂ JSDoc supplies the type.
                    } else if (self.fnIsObjectLiteralSetterWithPairedGetter(node)) {
                        // Skip — a paired getter supplies the setter
                        // parameter's type (thisTypeInAccessors.ts).
                    } else if (pp.flags.is_rest) {
                        // `function f(...a) {}` ÃÂ¢ÃÂÃÂ tsc emits TS7019
                        // ("Rest parameter 'X' implicitly has an
                        // 'any[]' type.") rather than the plain TS7006
                        // implicit-any. Anchor at the parameter span
                        // (starting at the `...` token) so the column
                        // matches upstream. Under !noImplicitAny the
                        // suggestion variant TS7047 fires instead.
                        const msg = if (param_is_suggestion)
                            try std.fmt.allocPrint(
                                self.diag_arena.allocator(),
                                "Rest parameter '{s}' implicitly has an 'any[]' type, but a better type may be inferred from usage.",
                                .{param_name},
                            )
                        else
                            try std.fmt.allocPrint(
                                self.diag_arena.allocator(),
                                "Rest parameter '{s}' implicitly has an 'any[]' type.",
                                .{param_name},
                            );
                        try self.diagnostics.append(self.gpa, .{
                            .node = p,
                            .code = if (param_is_suggestion)
                                TsCodes.rest_parameter_implicitly_any_suggestion
                            else
                                TsCodes.rest_parameter_implicitly_any,
                            .message = msg,
                            .category = if (param_is_suggestion) .suggestion else .error_,
                        });
                    } else {
                        // `function f(x = x)` ÃÂ¢ÃÂÃÂ when the default value
                        // references the parameter name itself, tsc
                        // upgrades the diagnostic to TS7022 ("'X'
                        // implicitly has type 'any' because it does
                        // not have a type annotation and is referenced
                        // directly or indirectly in its own initializer.")
                        // anchored on the parameter binding. The
                        // companion TS2372 ("Parameter 'X' cannot
                        // reference itself.") still fires at the
                        // reference site. Mirrors
                        // `FunctionDeclaration3_es6`.
                        const is_self_ref_default = blk_self: {
                            if (pp.default_value == hir_mod.none_node_id) break :blk_self false;
                            if (pp.name == hir_mod.none_node_id) break :blk_self false;
                            if (self.hir.kindOf(pp.name) != .identifier) break :blk_self false;
                            const pn = hir_mod.identifierOf(self.hir, pp.name).name;
                            var refs: std.ArrayListUnmanaged(NameRef) = .empty;
                            defer refs.deinit(self.gpa);
                            self.collectIdentifierRefsWithNodes(pp.default_value, &refs) catch break :blk_self false;
                            for (refs.items) |ref| {
                                if (ref.name == pn) break :blk_self true;
                            }
                            break :blk_self false;
                        };
                        // Suppress the self-reference TS7022 form under
                        // suggestion mode: tsc reports that as a hard error
                        // (it isn't routed through the usage-suggestion
                        // path), so when noImplicitAny is OFF we simply
                        // fall back to the plain parameter suggestion.
                        const emit_self_ref = is_self_ref_default and !param_is_suggestion;
                        const code: u32 = if (emit_self_ref)
                            TsCodes.variable_self_reference_implicitly_any
                        else if (param_is_suggestion)
                            TsCodes.parameter_implicitly_any_suggestion
                        else
                            TsCodes.parameter_implicitly_any;
                        const msg = if (emit_self_ref)
                            try std.fmt.allocPrint(
                                self.diag_arena.allocator(),
                                "'{s}' implicitly has type 'any' because it does not have a type annotation and is referenced directly or indirectly in its own initializer.",
                                .{param_name},
                            )
                        else if (!param_is_suggestion and js_default_is_empty_array)
                            try std.fmt.allocPrint(
                                self.diag_arena.allocator(),
                                "Parameter '{s}' implicitly has an 'any[]' type.",
                                .{param_name},
                            )
                        else if (param_is_suggestion)
                            try std.fmt.allocPrint(
                                self.diag_arena.allocator(),
                                "Parameter '{s}' implicitly has an 'any' type, but a better type may be inferred from usage.",
                                .{param_name},
                            )
                        else
                            try std.fmt.allocPrint(
                                self.diag_arena.allocator(),
                                "Parameter '{s}' implicitly has an 'any' type.",
                                .{param_name},
                            );
                        const anchor: NodeId = if (emit_self_ref and pp.name != hir_mod.none_node_id) pp.name else p;
                        if (!self.diagnosticExists(anchor, code)) {
                            try self.diagnostics.append(self.gpa, .{
                                .node = anchor,
                                .code = code,
                                .message = msg,
                                .category = if (param_is_suggestion) .suggestion else .error_,
                            });
                        }
                    }
                }
            }
        }

        // Detect a `arg is T` / `asserts arg is T` return-type
        // before lowering ÃÂ¢ÃÂÃÂ the predicate's target type is the
        // *return type* for assignability purposes (it always
        // returns boolean), but we record the predicate separately
        // so call sites can narrow the argument.
        const is_predicate = f.return_type != hir_mod.none_node_id and
            self.hir.kindOf(f.return_type) == .type_predicate_type;
        if (is_predicate) {
            try self.checkTypePredicateConstraints(f.return_type, params);
        }
        // Bodyless-aware TS2304 sweep for return types ÃÂ¢ÃÂÃÂ fires
        // for any declared return-type annotation that references
        // an unresolved bare name (whether or not a body follows).
        // Mirrors upstream tsc, which surfaces TS2304 on return-type
        // refs like `function foo(): V` when `V` is not in scope.
        if (f.return_type != hir_mod.none_node_id) {
            try self.reportUnresolvedBodylessSignatureTypeRefs(f.return_type, type_params);
        }
        const ret_t: TypeId = if (f.return_type != hir_mod.none_node_id)
            (if (is_predicate)
                types.Primitive.boolean_t
            else if (self.typeAnnotationShouldBecomeErrorAny(f.return_type))
                types.Primitive.any
            else
                try self.lowerReturnTypeAnnotationWithCircularityGuard(node, f.return_type))
        else if (jsdoc_context_sig) |sig|
            self.interner.signatureReturn(sig) orelse types.Primitive.any
        else
            types.Primitive.any;
        if (f.body == hir_mod.none_node_id and f.return_type == hir_mod.none_node_id) {
            try self.reportImplicitAnySignatureReturn(node);
        }
        if (f.flags.is_generator and f.return_type != hir_mod.none_node_id) {
            if (ret_t == types.Primitive.void_t) {
                try self.report(f.return_type, TsCodes.generator_void_return, "A generator cannot have a 'void' type annotation.");
            } else if (self.generatorReturnAnnotationDefinitelyInvalid(ret_t)) {
                const target_name = (try self.allocSimpleTypeName(ret_t)) orelse "unknown";
                const generator_name = if (f.flags.is_async) "AsyncGenerator" else "Generator";
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Type '{s}<any, any, unknown>' is not assignable to type '{s}'.",
                    .{ generator_name, target_name },
                );
                try self.report(f.return_type, TsCodes.type_not_assignable, msg);
            } else if (self.generatorReturnAnnotationHasConflictingYieldTypes(f.return_type)) {
                const target_name = (try self.allocSimpleTypeName(ret_t)) orelse "unknown";
                const yield_t = self.generatorYieldTypeFromAnnotation(f.return_type) orelse types.Primitive.any;
                const yield_name = (try self.allocSimpleTypeName(yield_t)) orelse "any";
                const generator_name = if (f.flags.is_async) "AsyncGenerator" else "Generator";
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Type '{s}<{s}, any, any>' is not assignable to type '{s}'.",
                    .{ generator_name, yield_name, target_name },
                );
                try self.report(f.return_type, TsCodes.type_not_assignable, msg);
            } else if (self.generatorReturnAnnotationRequiresMissingGeneratorMembers(ret_t)) {
                if (self.generatorReturnAnnotationFirstRequiredExtraMember(ret_t)) |member| {
                    const target_name = (try self.allocSimpleTypeName(ret_t)) orelse "unknown";
                    const yield_t = self.generatorYieldTypeFromAnnotation(f.return_type) orelse
                        self.interner.objectNumberIndex(ret_t);
                    const yield_name = if (yield_t == types.Primitive.none)
                        "any"
                    else
                        (try self.allocSimpleTypeName(yield_t)) orelse "any";
                    const generator_name = if (f.flags.is_async) "AsyncGenerator" else "Generator";
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Property '{s}' is missing in type '{s}<{s}, any, any>' but required in type '{s}'.",
                        .{ self.string_interner.get(member.name), generator_name, yield_name, target_name },
                    );
                    try self.report(f.return_type, TsCodes.property_missing_required, msg);
                } else {
                    try self.report(f.return_type, TsCodes.type_not_assignable, "Generator return type is not assignable to the declared return type.");
                }
            }
        }

        const sig = if (explicit_this_t != types.Primitive.none)
            self.interner.internSignatureWithThisType(param_types.items, ret_t, false, false, explicit_this_t) catch return error.OutOfMemory
        else
            self.interner.internSignature(param_types.items, ret_t, false) catch return error.OutOfMemory;
        try self.recordGenericSignatureParams(sig, captured_tp_ids.items);
        for (param_nullish_array_defaults.items) |has_nullish_default| {
            if (has_nullish_default) {
                const owned = try self.gpa.dupe(bool, param_nullish_array_defaults.items);
                try self.signature_nullish_array_defaults.put(self.gpa, sig, owned);
                break;
            }
        }
        if (explicit_this_t != types.Primitive.none) try self.signature_this_params.put(self.gpa, sig, explicit_this_t);
        try self.recordSignatureMinArgs(sig, param_omittable.items);
        try self.recordSignatureParamNames(sig, params);
        try self.recordSignatureDeclNode(sig, node);
        self.hir.setType(node, sig);
        if (f.name != hir_mod.none_node_id) self.hir.setType(f.name, sig);
        // Record rest-parameter signatures so call-site argument
        // checking can expand the trailing rest into a variadic match
        // (the interner keys signatures only by their flat parameter
        // type list, so rest-ness lives in `rest_signatures`).
        if (has_rest_param) {
            try self.rest_signatures.put(self.gpa, sig, {});
        }
        for (param_predicates.items) |entry| {
            try self.signature_param_predicates.put(self.gpa, .{
                .signature = sig,
                .param_index = entry.param_index,
            }, entry.pred);
        }
        // Auto-infer variance for any type parameter that had no
        // explicit `in` / `out` modifier. We walk the signature ÃÂ¢ÃÂÃÂ
        // an occurrence of T in a param slot is contravariant, in
        // the return slot covariant. The result lives in the
        // `inferred_variance` side table since the interner keys
        // variance into the TypeId.
        if (captured_tp_ids.items.len > 0) {
            var tp_ix: usize = 0;
            for (type_params) |tp_node| {
                if (self.hir.kindOf(tp_node) != .type_parameter) continue;
                const tpp_h = hir_mod.typeParameterOf(self.hir, tp_node);
                if (tp_ix >= captured_tp_ids.items.len) break;
                const tp_id_v = captured_tp_ids.items[tp_ix];
                tp_ix += 1;
                if (tpp_h.variance != 0) continue; // explicit `in`/`out`
                const v = self.inferVariance(sig, tp_id_v);
                try self.inferred_variance.put(self.gpa, tp_id_v, v);
            }
        }
        // Record the function's generic type parameters keyed by name
        // so call sites with explicit type args (`f<T>(args)`) can
        // substitute directly. Drop any prior recording on shadow.
        if (captured_tp_ids.items.len > 0 and f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier) {
            const fn_name = hir_mod.identifierOf(self.hir, f.name).name;
            if (self.generic_fns.fetchRemove(fn_name)) |old| self.gpa.free(old.value);
            const owned = captured_tp_ids.toOwnedSlice(self.gpa) catch return error.OutOfMemory;
            try self.generic_fns.put(self.gpa, fn_name, owned);
        }
        // Overload tracking: when multiple `function f(...)` decls
        // share a name, we treat the body-less ones as overload
        // signatures. The body-bearing one is the implementation
        // (used only for body typing ÃÂ¢ÃÂÃÂ never picked by call-site
        // resolution). Ambient overload lists have no body, so every
        // signature stays visible.
        if (f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier) {
            const fn_name = hir_mod.identifierOf(self.hir, f.name).name;
            const has_body = f.body != hir_mod.none_node_id;
            const gop = try self.overloads.getOrPut(self.gpa, fn_name);
            if (!gop.found_existing) gop.value_ptr.* = .empty;
            const dop = try self.overload_decls.getOrPut(self.gpa, fn_name);
            if (!dop.found_existing) dop.value_ptr.* = .empty;
            if (!has_body) {
                try gop.value_ptr.*.append(self.gpa, sig);
                try dop.value_ptr.*.append(self.gpa, node);
            } else {
                // Implementation signature: only append if there
                // are existing overloads ÃÂ¢ÃÂÃÂ a single-decl function
                // doesn't need overload resolution.
                if (gop.value_ptr.*.items.len > 0) {
                    try gop.value_ptr.*.append(self.gpa, sig);
                    try dop.value_ptr.*.append(self.gpa, node);
                    try self.overload_has_implementation.put(self.gpa, fn_name, {});
                }
            }
        }
        // Record the predicate so call sites can narrow.
        if (is_predicate and f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier) {
            const pred = hir_mod.typePredicateOf(self.hir, f.return_type);
            const target_t: TypeId = if (pred.target_type != hir_mod.none_node_id)
                (self.lowererLowerWithTypeParams(pred.target_type) catch types.Primitive.unknown)
            else
                types.Primitive.unknown;
            const fn_name = hir_mod.identifierOf(self.hir, f.name).name;
            const fn_pred: FnPredicate = .{
                .param_index = self.normalizedPredicateParamIndex(hir_mod.fnParams(self.hir, node), pred.param_index),
                .target_type = target_t,
                .target_node = pred.target_type,
                .is_asserts = pred.is_asserts,
            };
            try self.fn_predicates.put(self.gpa, fn_name, fn_pred);
            try self.signature_predicates.put(self.gpa, sig, fn_pred);
        }
        return sig;
    }

    fn reportImplicitAnySignatureReturn(self: *Checker, fn_node: NodeId) CheckError!void {
        if (!self.strict_flags.no_implicit_any) return;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.flags.is_constructor) return;
        if (self.functionIsPrivateAmbientClassMember(fn_node)) return;
        // Setters always return void in TS ÃÂ¢ÃÂÃÂ they have no usable return
        // type, so tsc never emits TS7010 for them. Mirrors upstream
        // behavior; verified against `propertyOverridesAccessors4`
        // which contains `set sound(val: string)` and expects no TS7010.
        if (f.flags.is_setter) return;
        if (f.flags.is_getter and f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier) {
            const name_id = hir_mod.identifierOf(self.hir, f.name).name;
            const text = self.string_interner.get(name_id);
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Property '{s}' implicitly has type 'any', because its get accessor lacks a return type annotation.",
                .{text},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = f.name,
                .code = TsCodes.getter_property_implicitly_any,
                .message = msg,
            });
            return;
        }
        const name_node = if (f.name != hir_mod.none_node_id) f.name else fn_node;
        const raw = if (f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier) blk: {
            const name_id = hir_mod.identifierOf(self.hir, f.name).name;
            const text = self.string_interner.get(name_id);
            break :blk if (text.len == 0) "(Missing)" else text;
        } else "<anonymous>";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}', which lacks return-type annotation, implicitly has an 'any' return type.",
            .{raw},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = name_node,
            .code = TsCodes.function_return_implicitly_any,
            .message = msg,
        });
    }

    /// Walk an annotation node and emit TS2304 for any bare unresolved
    /// type-ref name. Used for class-field annotations and interface
    /// members where the parent decl has type parameters in
    /// `lookupNarrow` scope. Mirrors upstream tsc, which emits
    /// `Cannot find name 'X'.` for e.g. `class C<T> { z: W; }` where
    /// `W` isn't declared anywhere visible. See fixture
    /// `typeParameterUsedAsTypeParameterConstraint4.ts`.
    fn reportUnresolvedBareTypeRefsInAnnotation(
        self: *Checker,
        type_node: NodeId,
    ) CheckError!void {
        try self.reportUnresolvedBodylessSignatureTypeRefs(type_node, &.{});
    }

    fn reportUnresolvedBodylessSignatureTypeRefs(
        self: *Checker,
        type_node: NodeId,
        type_params: []const NodeId,
    ) CheckError!void {
        if (type_node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(type_node)) {
            .type_ref => {
                const r = hir_mod.typeRefOf(self.hir, type_node);
                for (hir_mod.typeRefArgs(self.hir, type_node)) |arg| {
                    try self.reportUnresolvedBodylessSignatureTypeRefs(arg, type_params);
                }
                if (self.importTypeModuleSpecifier(type_node) != null) return;
                if (r.qualifier_len != 0) {
                    if (self.typeAnnotationContainsUnresolvedRef(type_node) and
                        (try self.resolveQualifiedTypeRef(type_node)) == null)
                    {
                        try self.reportCannotFindNamespaceForQualifiedTypeRef(type_node);
                    }
                    return;
                }
                if (self.typeParamNameMatches(r.name, type_params)) return;
                if (self.nameHasEnclosingTypeParameter(r.name, type_node)) return;
                if (try self.resolveUnqualifiedImportEqualsTypeRef(type_node, r.name)) |_| return;
                if (try self.importedTypeRefForLocal(r.name, type_node)) |_| return;
                if (try self.importedReferenceLibTypeForLocal(r.name, type_node)) |_| return;
                if (try self.programExportedClassInstanceTypeForImportedName(r.name, type_node)) |_| return;
                const raw = self.string_interner.get(r.name);
                if (std.mem.eql(u8, raw, "super")) {
                    try self.reportCannotFindNamePlainOnce(type_node, r.name);
                    return;
                }
                if (r.args_len != 0) {
                    if (self.typeRefNameAcceptsTypeArgsAt(type_node, r.name, raw)) return;
                    if (self.typeRefNameExists(r.name) or self.visibleTypeDeclarationExistsAt(type_node, r.name)) {
                        try self.reportTypeNotGeneric(type_node, r.name);
                        return;
                    }
                }
                if (self.lowerBuiltinObjectType(raw) != null) return;
                if (std.mem.eql(u8, raw, "Null") or std.mem.eql(u8, raw, "Undefined")) {
                    try self.reportCannotFindNamePlainOnce(type_node, r.name);
                    return;
                }
                if (std.mem.eql(u8, raw, "any") or
                    std.mem.eql(u8, raw, "unknown") or
                    std.mem.eql(u8, raw, "never") or
                    std.mem.eql(u8, raw, "void") or
                    std.mem.eql(u8, raw, "null") or
                    std.mem.eql(u8, raw, "undefined") or
                    std.mem.eql(u8, raw, "string") or
                    std.mem.eql(u8, raw, "number") or
                    std.mem.eql(u8, raw, "boolean") or
                    std.mem.eql(u8, raw, "bigint") or
                    std.mem.eql(u8, raw, "symbol") or
                    std.mem.eql(u8, raw, "object") or
                    std.mem.eql(u8, raw, "SymbolConstructor") or
                    std.mem.eql(u8, raw, "PropertyKey") or
                    self.isBuiltinName(r.name) or
                    self.isLibEs5TypeName(raw))
                {
                    return;
                }
                if (self.namespaceTypeRefIsCrossVirtualSectionOnly(type_node, r.name)) {
                    try self.reportCannotFindNameOnce(type_node, r.name);
                    return;
                }
                if (self.typeRefNameExists(r.name)) return;
                if (self.visibleNonNamespaceTypeDeclarationExistsAt(type_node, r.name)) return;
                if (self.visibleValueOnlyDeclarationExistsAt(type_node, r.name)) {
                    try self.reportValueUsedAsTypeDidYouMeanTypeofOnce(type_node, r.name);
                    return;
                }
                // TS2709: split the visibility check. If a true type
                // declaration (interface / class / type-alias / enum)
                // exists, resolution succeeds. If only a namespace
                // declaration of the same name exists in the type
                // space, the user used a namespace as a type and we
                // emit TS2709 instead of falling through to TS2304.
                if (self.visibleJsDocTypedefNameExistsAt(type_node, r.name)) return;
                if (self.typeRefNameResolvesToValueOnlyNamespace(type_node, r.name)) {
                    const ns_name = self.string_interner.get(r.name);
                    const ns_msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Cannot use namespace '{s}' as a type.",
                        .{ns_name},
                    );
                    try self.diagnostics.append(self.gpa, .{
                        .node = type_node,
                        .code = TsCodes.namespace_used_as_type,
                        .message = ns_msg,
                    });
                    return;
                }
                try self.reportCannotFindNameOnce(type_node, r.name);
            },
            .array_type => try self.reportUnresolvedBodylessSignatureTypeRefs(hir_mod.arrayTypeOf(self.hir, type_node).element, type_params),
            .tuple_type => for (hir_mod.tupleTypeElements(self.hir, type_node)) |elem| try self.reportUnresolvedBodylessSignatureTypeRefs(elem, type_params),
            .optional_type => try self.reportUnresolvedBodylessSignatureTypeRefs(hir_mod.optionalTypeOf(self.hir, type_node).operand, type_params),
            .rest_type => try self.reportUnresolvedBodylessSignatureTypeRefs(hir_mod.restTypeOf(self.hir, type_node).operand, type_params),
            .readonly_type => try self.reportUnresolvedBodylessSignatureTypeRefs(hir_mod.readonlyTypeOf(self.hir, type_node).operand, type_params),
            .union_type => for (hir_mod.unionTypeMembers(self.hir, type_node)) |member| try self.reportUnresolvedBodylessSignatureTypeRefs(member, type_params),
            .intersection_type => for (hir_mod.intersectionTypeMembers(self.hir, type_node)) |member| try self.reportUnresolvedBodylessSignatureTypeRefs(member, type_params),
            .object_type => for (hir_mod.objectTypeMembers(self.hir, type_node)) |member| try self.reportUnresolvedBodylessSignatureTypeRefs(member, type_params),
            .interface_member => try self.reportUnresolvedBodylessSignatureTypeRefs(hir_mod.interfaceMemberOf(self.hir, type_node).type_node, type_params),
            .index_signature => {
                const ix = hir_mod.indexSignatureOf(self.hir, type_node);
                try self.reportUnresolvedBodylessSignatureTypeRefs(ix.key_type, type_params);
                try self.reportUnresolvedBodylessSignatureTypeRefs(ix.value_type, type_params);
            },
            .keyof_type => try self.reportUnresolvedBodylessSignatureTypeRefs(hir_mod.keyofTypeOf(self.hir, type_node).operand, type_params),
            .indexed_access_type => {
                const ia = hir_mod.indexedAccessTypeOf(self.hir, type_node);
                try self.reportUnresolvedBodylessSignatureTypeRefs(ia.object, type_params);
                try self.reportUnresolvedBodylessSignatureTypeRefs(ia.index, type_params);
            },
            .fn_type, .constructor_type => {
                // `(x: U) => U` and `new (x: U) => U` ÃÂ¢ÃÂÃÂ the inner fn-type
                // is itself a signature whose parameter annotations and
                // return type may reference type names from the enclosing
                // scope. Merge in any locally-declared type parameters of
                // the inner signature so `<S>(x: S) => S` doesn't trip
                // TS2304 on `S`. Mirrors upstream tsc, which fires
                // TS2304 on `function foo<T>(b: (x: U) => U) {}` for `U`.
                const ft = hir_mod.fnTypeOf(self.hir, type_node);
                const inner_type_params = self.hir.childSlice(ft.type_params_start, ft.type_params_len);
                if (inner_type_params.len == 0) {
                    for (self.hir.childSlice(ft.params_start, ft.params_len)) |p| {
                        if (self.hir.kindOf(p) != .parameter) continue;
                        const pp = hir_mod.parameterOf(self.hir, p);
                        try self.reportUnresolvedBodylessSignatureTypeRefs(pp.type_annotation, type_params);
                    }
                    try self.reportUnresolvedBodylessSignatureTypeRefs(ft.return_type, type_params);
                } else {
                    // Build merged type-param list. Heap-allocate via the
                    // checker arena so the slice lives for the recursive
                    // call only.
                    var merged: std.ArrayListUnmanaged(NodeId) = .empty;
                    defer merged.deinit(self.gpa);
                    try merged.appendSlice(self.gpa, type_params);
                    try merged.appendSlice(self.gpa, inner_type_params);
                    for (self.hir.childSlice(ft.params_start, ft.params_len)) |p| {
                        if (self.hir.kindOf(p) != .parameter) continue;
                        const pp = hir_mod.parameterOf(self.hir, p);
                        try self.reportUnresolvedBodylessSignatureTypeRefs(pp.type_annotation, merged.items);
                    }
                    try self.reportUnresolvedBodylessSignatureTypeRefs(ft.return_type, merged.items);
                }
            },
            else => {},
        }
    }

    fn checkFunctionSignatureLocalTypeVisibility(self: *Checker, fn_node: NodeId, type_params: []const NodeId) CheckError!void {
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.body == hir_mod.none_node_id or self.hir.kindOf(f.body) != .block_stmt) return;
        var local_type_names: std.AutoHashMapUnmanaged(hir_mod.StringId, NodeId) = .empty;
        defer local_type_names.deinit(self.gpa);
        for (hir_mod.blockStmts(self.hir, f.body)) |stmt| {
            const name_node: NodeId = switch (self.hir.kindOf(stmt)) {
                .interface_decl => hir_mod.interfaceOf(self.hir, stmt).name,
                .type_alias_decl => hir_mod.typeAliasOf(self.hir, stmt).name,
                .class_decl, .class_expr => hir_mod.classOf(self.hir, stmt).name,
                else => continue,
            };
            if (name_node == hir_mod.none_node_id or self.hir.kindOf(name_node) != .identifier) continue;
            try local_type_names.put(self.gpa, hir_mod.identifierOf(self.hir, name_node).name, stmt);
        }
        if (local_type_names.count() == 0) return;

        for (type_params) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            const tpp = hir_mod.typeParameterOf(self.hir, tp);
            if (local_type_names.get(tpp.name)) |body_decl| {
                try self.reportDuplicateIdentifier(tp, tpp.name);
                // tsc also flags the colliding body declaration's
                // identifier so both halves of the shadow show up in
                // baselines (e.g. `function f<T>() { interface T {} }`
                // emits TS2300 at both the `<T>` and the `interface T`
                // sites).
                const decl_name_node: NodeId = switch (self.hir.kindOf(body_decl)) {
                    .interface_decl => hir_mod.interfaceOf(self.hir, body_decl).name,
                    .type_alias_decl => hir_mod.typeAliasOf(self.hir, body_decl).name,
                    .class_decl, .class_expr => hir_mod.classOf(self.hir, body_decl).name,
                    else => hir_mod.none_node_id,
                };
                if (decl_name_node != hir_mod.none_node_id and
                    self.hir.kindOf(decl_name_node) == .identifier)
                {
                    try self.reportDuplicateIdentifier(decl_name_node, tpp.name);
                }
            }
        }

        const params = hir_mod.fnParams(self.hir, fn_node);
        for (params) |p| {
            if (self.hir.kindOf(p) != .parameter) continue;
            const pp = hir_mod.parameterOf(self.hir, p);
            if (pp.type_annotation != hir_mod.none_node_id) {
                try self.reportTypeRefsToLocalBodyTypes(pp.type_annotation, &local_type_names);
            }
        }
        if (f.return_type != hir_mod.none_node_id) {
            try self.reportTypeRefsToLocalBodyTypes(f.return_type, &local_type_names);
        }
    }

    fn reportTypeRefsToLocalBodyTypes(
        self: *Checker,
        type_node: NodeId,
        local_type_names: *const std.AutoHashMapUnmanaged(hir_mod.StringId, NodeId),
    ) CheckError!void {
        if (type_node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(type_node)) {
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, type_node);
                if (local_type_names.contains(id.name)) {
                    try self.reportCannotFindName(type_node, id.name);
                }
            },
            .type_ref => {
                const r = hir_mod.typeRefOf(self.hir, type_node);
                if (r.qualifier_len == 0 and local_type_names.contains(r.name)) {
                    try self.reportCannotFindName(type_node, r.name);
                }
                for (hir_mod.typeRefArgs(self.hir, type_node)) |arg| {
                    try self.reportTypeRefsToLocalBodyTypes(arg, local_type_names);
                }
            },
            .union_type => for (hir_mod.unionTypeMembers(self.hir, type_node)) |member| try self.reportTypeRefsToLocalBodyTypes(member, local_type_names),
            .intersection_type => for (hir_mod.intersectionTypeMembers(self.hir, type_node)) |member| try self.reportTypeRefsToLocalBodyTypes(member, local_type_names),
            .array_type => try self.reportTypeRefsToLocalBodyTypes(hir_mod.arrayTypeOf(self.hir, type_node).element, local_type_names),
            .tuple_type => for (hir_mod.tupleTypeElements(self.hir, type_node)) |elem| try self.reportTypeRefsToLocalBodyTypes(elem, local_type_names),
            .optional_type => try self.reportTypeRefsToLocalBodyTypes(hir_mod.optionalTypeOf(self.hir, type_node).operand, local_type_names),
            .rest_type => try self.reportTypeRefsToLocalBodyTypes(hir_mod.restTypeOf(self.hir, type_node).operand, local_type_names),
            .readonly_type => try self.reportTypeRefsToLocalBodyTypes(hir_mod.readonlyTypeOf(self.hir, type_node).operand, local_type_names),
            .keyof_type => try self.reportTypeRefsToLocalBodyTypes(hir_mod.keyofTypeOf(self.hir, type_node).operand, local_type_names),
            .indexed_access_type => {
                const ia = hir_mod.indexedAccessTypeOf(self.hir, type_node);
                try self.reportTypeRefsToLocalBodyTypes(ia.object, local_type_names);
                try self.reportTypeRefsToLocalBodyTypes(ia.index, local_type_names);
            },
            .conditional_type => {
                const c = hir_mod.conditionalTypeOf(self.hir, type_node);
                try self.reportTypeRefsToLocalBodyTypes(c.check, local_type_names);
                try self.reportTypeRefsToLocalBodyTypes(c.extends, local_type_names);
                try self.reportTypeRefsToLocalBodyTypes(c.true_branch, local_type_names);
                try self.reportTypeRefsToLocalBodyTypes(c.false_branch, local_type_names);
            },
            else => {},
        }
    }

    fn recordGenericSignatureParams(self: *Checker, sig: TypeId, params: []const TypeId) CheckError!void {
        if (params.len == 0) return;
        if (self.generic_signature_params.fetchRemove(sig)) |old| {
            self.gpa.free(old.value);
        }
        const owned = try self.gpa.dupe(TypeId, params);
        errdefer self.gpa.free(owned);
        try self.generic_signature_params.put(self.gpa, sig, owned);
    }

    fn recordFunctionNodeGenericSignatureParams(self: *Checker, sig: TypeId, fn_node: NodeId) CheckError!bool {
        const type_params = hir_mod.fnTypeParams(self.hir, fn_node);
        if (type_params.len == 0) return false;
        var params: std.ArrayListUnmanaged(TypeId) = .empty;
        defer params.deinit(self.gpa);
        for (type_params) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            const tp_t = self.hir.typeOf(tp);
            if (tp_t == types.Primitive.none) continue;
            try params.append(self.gpa, tp_t);
            try self.type_parameter_decl_nodes.put(self.gpa, tp_t, tp);
            const resolved_tp_t = self.resolvedTypeParameterPlaceholder(tp_t);
            if (resolved_tp_t != tp_t) {
                try self.type_parameter_decl_nodes.put(self.gpa, resolved_tp_t, tp);
            }
        }
        if (params.items.len == 0) return false;
        try self.recordGenericSignatureParams(sig, params.items);
        return true;
    }

    fn checkTopLevelDecoratorDiagnostics(self: *Checker, stmts: []const NodeId) CheckError!void {
        var i: usize = 0;
        while (i < stmts.len) {
            if (self.hir.kindOf(stmts[i]) != .decorator) {
                i += 1;
                continue;
            }
            const start = i;
            while (i < stmts.len and self.hir.kindOf(stmts[i]) == .decorator) : (i += 1) {}
            if (self.trailingExportDecoratorTarget(stmts, i)) |mixed| {
                // tsc attaches a TS1486 "Decorator used before 'export'
                // here." related-info pointing at the first leading
                // decorator (`firstDecorator`), which is `stmts[start]`.
                const msg = try self.diag_arena.allocator().dupe(u8, "Decorators may not appear after 'export' or 'export default' if they also appear before 'export'.");
                const rel = try self.diag_arena.allocator().dupe(RelatedInfo, &.{.{
                    .node = stmts[start],
                    .pos = self.hir.spanOf(stmts[start]).start,
                    .code = TsCodes.decorator_used_before_export_here,
                    .message = "Decorator used before 'export' here.",
                }});
                try self.diagnostics.append(self.gpa, .{
                    .node = mixed.decorator,
                    .pos = self.hir.spanOf(mixed.decorator).start,
                    .code = TsCodes.decorator_after_export_with_leading_decorator,
                    .message = msg,
                    .related = rel,
                });
                if (self.sourceUsesLegacyDecorators() and try self.classHasStaticPrivateIdentifierMember(mixed.target)) {
                    try self.reportAt(
                        stmts[start],
                        self.hir.spanOf(stmts[start]).start,
                        TsCodes.class_decorator_static_private_identifier,
                        "Class decorators can't be used with static private identifier. Consider removing the experimental decorator.",
                    );
                }
                for (stmts[start..i]) |decorator_node| {
                    try self.checkClassDecoratorDiagnostic(decorator_node, mixed.target);
                }
                i = mixed.after_index;
                continue;
            }
            // Decorators only apply to classes (and class members).
            // Top-level decorators attached to enums, type aliases,
            // interfaces, vars, functions, modules, or import-equals
            // must surface TS1206. Mirrors the `decoratorOn*` fixtures
            // under `conformance/decorators/invalid/`.
            const target_node = if (i < stmts.len) self.unwrapExportDecl(stmts[i]) else hir_mod.none_node_id;
            // tsc silently drops decorators preceding a `using` /
            // `await using` declaration — no TS1206 and no decorator
            // shape/arity checks either (decoratorOnUsing expects only
            // the TS1134 for a bad binding).
            if (target_node != hir_mod.none_node_id) {
                const tk = self.hir.kindOf(target_node);
                if (tk == .var_decl or tk == .let_decl or tk == .const_decl) {
                    const v = hir_mod.varDeclOf(self.hir, target_node);
                    if (v.is_using or v.is_await_using) continue;
                }
            }
            const target_invalid = blk: {
                if (target_node == hir_mod.none_node_id) break :blk true;
                const tk = self.hir.kindOf(target_node);
                break :blk tk != .class_decl and tk != .class_expr;
            };
            if (target_invalid) {
                for (stmts[start..i]) |decorator_node| {
                    // Skip when the decorator has an empty / placeholder
                    // expression (e.g. bare `@` followed by an unexpected
                    // token like `enum`): the parser already raised
                    // TS1109 'Expression expected.' at the next token,
                    // and tsc does NOT also fire TS1206. Mirrors
                    // `parserErrorRecovery_ClassElement3.ts`. The parser
                    // synthesizes a zero-width empty-name identifier in
                    // that case, so the expression node won't be
                    // `none_node_id` even though it's effectively empty.
                    const d = hir_mod.decoratorOf(self.hir, decorator_node);
                    if (d.expression == hir_mod.none_node_id) continue;
                    if (self.hir.kindOf(d.expression) == .identifier) {
                        const id = hir_mod.identifierOf(self.hir, d.expression);
                        if (self.string_interner.get(id.name).len == 0) continue;
                    }
                    try self.report(decorator_node, TsCodes.decorators_not_valid_here, "Decorators are not valid here.");
                }
                continue;
            }
            if (self.sourceUsesLegacyDecorators() and try self.classHasStaticPrivateIdentifierMember(target_node)) {
                try self.reportAt(
                    stmts[start],
                    self.hir.spanOf(stmts[start]).start,
                    TsCodes.class_decorator_static_private_identifier,
                    "Class decorators can't be used with static private identifier. Consider removing the experimental decorator.",
                );
            }
            for (stmts[start..i]) |decorator_node| {
                try self.checkClassDecoratorDiagnostic(decorator_node, target_node);
            }
        }
    }

    const TrailingExportDecoratorTarget = struct {
        decorator: NodeId,
        target: NodeId,
        after_index: usize,
    };

    fn trailingExportDecoratorTarget(self: *Checker, stmts: []const NodeId, export_index: usize) ?TrailingExportDecoratorTarget {
        if (export_index >= stmts.len) return null;
        const export_node = stmts[export_index];
        if (self.hir.kindOf(export_node) != .export_decl) return null;
        const ex = hir_mod.exportOf(self.hir, export_node);
        if (ex.decl == hir_mod.none_node_id or self.hir.kindOf(ex.decl) != .decorator) return null;
        var target_index = export_index + 1;
        while (target_index < stmts.len and self.hir.kindOf(stmts[target_index]) == .decorator) : (target_index += 1) {}
        if (target_index >= stmts.len) return null;
        const target = self.unwrapExportDecl(stmts[target_index]);
        const tk = self.hir.kindOf(target);
        if (tk != .class_decl and tk != .class_expr) return null;
        return .{
            .decorator = ex.decl,
            .target = target,
            .after_index = target_index,
        };
    }

    fn classHasStaticPrivateIdentifierMember(self: *Checker, class_node: NodeId) CheckError!bool {
        if (class_node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(class_node) != .class_decl and self.hir.kindOf(class_node) != .class_expr) return false;
        for (hir_mod.classMembers(self.hir, class_node)) |member_node| {
            switch (self.hir.kindOf(member_node)) {
                .fn_decl, .fn_expr, .arrow_fn => {
                    const fn_p = hir_mod.fnDeclOf(self.hir, member_node);
                    if (!fn_p.flags.is_static) continue;
                    const member_name = (try self.classMemberNameFromFunctionName(fn_p.name)) orelse continue;
                    if (self.memberNameIsEcmaPrivate(member_name)) return true;
                },
                .object_property => {
                    const op = hir_mod.objectPropertyOf(self.hir, member_node);
                    if (!op.is_static) continue;
                    const member_name = (try self.classMemberNameFromPropertyKey(op.key, op.is_computed)) orelse continue;
                    if (self.memberNameIsEcmaPrivate(member_name)) return true;
                },
                else => {},
            }
        }
        return false;
    }

    fn checkClassDecoratorDiagnostic(self: *Checker, decorator_node: NodeId, target_class: NodeId) CheckError!void {
        if (self.hir.kindOf(decorator_node) != .decorator) return;
        const d = hir_mod.decoratorOf(self.hir, decorator_node);
        if (d.expression == hir_mod.none_node_id) return;
        try self.reportDecoratorUsedBeforeAssignment(d.expression);
        const dec_t = try self.checkExpression(d.expression);
        // TS1238: a class identifier used directly as a decorator (e.g.
        // `@CtorDtor` where `class CtorDtor {}`) is not callable as a
        // decorator ÃÂ¢ÃÂÃÂ class statics have a construct signature but no
        // call signature. Mirrors fixture
        // `constructableDecoratorOnClass01.errors.txt`.
        if (self.decoratorExpressionIsClassIdentifier(d.expression)) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Unable to resolve signature of class decorator when called as an expression.",
                .{},
            );
            // tsc squiggle covers the decorator identifier (not the
            // leading `@`) when the decorator is a bare class
            // reference ÃÂ¢ÃÂÃÂ see constructableDecoratorOnClass01 baseline
            // which anchors at `CtorDtor` (col 2), not `@` (col 1).
            try self.diagnostics.append(self.gpa, .{
                .node = decorator_node,
                .pos = self.decoratorExpressionPos(decorator_node),
                .code = TsCodes.class_decorator_signature_unresolved,
                .message = msg,
            });
            return;
        }
        const class_runtime_arg_count: usize = if (self.sourceUsesLegacyDecorators()) 1 else 2;
        const class_runtime_arity_ok = self.decoratorRuntimeAritySatisfied(dec_t, class_runtime_arg_count, "class");
        try self.checkDecoratorRuntimeArity(
            decorator_node,
            dec_t,
            class_runtime_arg_count,
            TsCodes.class_decorator_signature_unresolved,
            "class",
        );
        if (class_runtime_arity_ok) {
            try self.checkLegacyClassDecoratorTargetAssignable(decorator_node, dec_t, target_class);
        }
    }

    fn checkLegacyClassDecoratorTargetAssignable(self: *Checker, decorator_node: NodeId, dec_t: TypeId, target_class: NodeId) CheckError!void {
        if (!self.sourceUsesLegacyDecorators()) return;
        if (target_class == hir_mod.none_node_id) return;
        if (dec_t >= self.interner.pool.typeCount()) return;
        if (!self.interner.pool.flagsOf(dec_t).is_signature) return;
        const params = self.interner.signatureParams(dec_t);
        if (params.len == 0) return;
        // The decorator is called as `dec(target)`; the class binds to the
        // first parameter slot. When that slot IS a rest parameter (no
        // fixed params precede it, e.g. `(...args: any[])`), the argument
        // binds to the rest ELEMENT type, not the array type — so
        // `@foo` with `declare function foo(...args: any[]): any` is a
        // valid class decorator (class assignable to `any`, not `any[]`).
        // Mirrors call-site rest expansion (`fixed_count = len - 1`).
        var first_param_t = params[0];
        if (params.len == 1 and self.rest_signatures.contains(dec_t)) {
            const elem_t = try self.arrayElementType(first_param_t);
            if (elem_t != types.Primitive.none) first_param_t = elem_t;
        }
        const class_arg_t = try self.legacyClassDecoratorArgumentType(target_class);
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        try self.inferLegacyClassDecoratorPrototype(first_param_t, class_arg_t, &subs);
        try self.inferFromPair(first_param_t, class_arg_t, &subs);
        const expected_t = try self.substituteType(first_param_t, &subs);
        if (try self.legacyDecoratorTargetAssignable(class_arg_t, expected_t)) return;
        try self.reportAt(
            decorator_node,
            self.decoratorExpressionPos(decorator_node),
            TsCodes.class_decorator_signature_unresolved,
            "Unable to resolve signature of class decorator when called as an expression.",
        );
    }

    fn inferLegacyClassDecoratorPrototype(
        self: *Checker,
        param_t: TypeId,
        class_arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        if (param_t >= self.interner.pool.typeCount() or class_arg_t >= self.interner.pool.typeCount()) return;
        const param_flags = self.interner.pool.flagsOf(param_t);
        const class_flags = self.interner.pool.flagsOf(class_arg_t);
        if (!param_flags.is_object_type or !class_flags.is_object_type) return;
        const prototype_name = self.string_interner.intern("prototype") catch return error.OutOfMemory;
        const param_proto_t = self.interner.objectMember(param_t, prototype_name) orelse return;
        const class_proto_t = self.interner.objectMember(class_arg_t, prototype_name) orelse return;
        try self.inferFromPair(param_proto_t, class_proto_t, subs);
    }

    fn legacyClassDecoratorArgumentType(self: *Checker, target_class: NodeId) CheckError!TypeId {
        const static_t = self.class_static_type_by_node.get(target_class) orelse return types.Primitive.none;
        const instance_t = self.classDecoratorTargetInstanceType(target_class) orelse return static_t;
        if (static_t >= self.interner.pool.typeCount()) return static_t;
        if (!self.interner.pool.flagsOf(static_t).is_object_type) return static_t;
        const prototype_name = self.string_interner.intern("prototype") catch return error.OutOfMemory;
        if (self.interner.objectMember(static_t, prototype_name) != null) return static_t;

        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        try members.appendSlice(self.gpa, self.interner.objectMembers(static_t));
        try self.refineLegacyClassDecoratorStaticMembers(target_class, &members);
        try members.append(self.gpa, .{
            .name = prototype_name,
            .type = instance_t,
            .is_optional = false,
            .is_readonly = true,
            .is_method = false,
        });
        return self.interner.internObjectTypeWithIndexAndSymbol(
            members.items,
            self.interner.objectStringIndex(static_t),
            self.interner.objectNumberIndex(static_t),
            self.interner.objectSymbolIndex(static_t),
        ) catch return error.OutOfMemory;
    }

    fn refineLegacyClassDecoratorStaticMembers(self: *Checker, target_class: NodeId, members: *std.ArrayListUnmanaged(types.ObjectMember)) CheckError!void {
        if (target_class == hir_mod.none_node_id) return;
        for (hir_mod.classMembers(self.hir, target_class)) |member_node| {
            switch (self.hir.kindOf(member_node)) {
                .fn_decl, .fn_expr, .arrow_fn => {
                    const fn_p = hir_mod.fnDeclOf(self.hir, member_node);
                    if (!fn_p.flags.is_static) continue;
                    const member_name = (try self.classMemberNameFromFunctionName(fn_p.name)) orelse continue;
                    const refined_t = self.hir.typeOf(member_node);
                    if (refined_t == types.Primitive.none) continue;
                    for (members.items) |*member| {
                        if (member.name == member_name) {
                            member.type = refined_t;
                            break;
                        }
                    }
                },
                .object_property => {
                    const op = hir_mod.objectPropertyOf(self.hir, member_node);
                    if (!op.is_static or op.value == hir_mod.none_node_id) continue;
                    const value_kind = self.hir.kindOf(op.value);
                    if (value_kind != .fn_decl and value_kind != .fn_expr and value_kind != .arrow_fn) continue;
                    const member_name = (try self.classMemberNameFromPropertyKey(op.key, op.is_computed)) orelse continue;
                    const refined_t = self.hir.typeOf(op.value);
                    if (refined_t == types.Primitive.none) continue;
                    for (members.items) |*member| {
                        if (member.name == member_name) {
                            member.type = refined_t;
                            break;
                        }
                    }
                },
                else => {},
            }
        }
    }

    fn classDecoratorTargetInstanceType(self: *Checker, target_class: NodeId) ?TypeId {
        if (target_class == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(target_class) != .class_decl and self.hir.kindOf(target_class) != .class_expr) return null;
        const c = hir_mod.classOf(self.hir, target_class);
        if (c.name != hir_mod.none_node_id and self.hir.kindOf(c.name) == .identifier) {
            const name = hir_mod.identifierOf(self.hir, c.name).name;
            if (self.class_instance_types.get(name)) |instance_t| return instance_t;
        }
        const t = self.hir.typeOf(target_class);
        if (t == types.Primitive.none or t == types.Primitive.unknown) return null;
        return t;
    }

    fn legacyDecoratorTargetAssignable(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (!(self.engine.isAssignableTo(source_t, target_t) catch false)) return false;
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return true;
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (source_flags.is_object_type and target_flags.is_object_type) {
            for (self.interner.objectMembers(target_t)) |target_member| {
                const source_member_t = self.interner.objectMember(source_t, target_member.name) orelse return false;
                if (!(try self.legacyDecoratorMemberAssignable(source_member_t, target_member.type))) return false;
            }
        }
        return true;
    }

    fn legacyDecoratorMemberAssignable(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) {
            return self.engine.isAssignableTo(source_t, target_t) catch false;
        }
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (source_flags.is_signature and target_flags.is_signature) {
            const source_ret = self.interner.signatureReturn(source_t) orelse types.Primitive.void_t;
            const target_ret = self.interner.signatureReturn(target_t) orelse types.Primitive.void_t;
            if (source_ret == types.Primitive.void_t and
                target_ret != types.Primitive.void_t and
                target_ret != types.Primitive.any and
                target_ret != types.Primitive.unknown)
            {
                return false;
            }
            return self.engine.isAssignableTo(source_ret, target_ret) catch false;
        }
        return self.engine.isAssignableTo(source_t, target_t) catch false;
    }

    fn decoratorExpressionIsClassIdentifier(self: *Checker, expr_node: NodeId) bool {
        if (expr_node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(expr_node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, expr_node);
        // A class declaration registers itself in `class_name_by_static`
        // (every class) and optionally in `class_constructor_sigs`
        // (only when the class has an explicit constructor). The
        // former is the broader signal ÃÂ¢ÃÂÃÂ every class binding lands
        // there regardless of whether the user wrote `constructor(...)`.
        var it = self.class_name_by_static.valueIterator();
        while (it.next()) |name_ptr| {
            if (name_ptr.* == id.name) return true;
        }
        return false;
    }

    fn reportDecoratorUsedBeforeAssignment(self: *Checker, expr_node: NodeId) CheckError!void {
        if (expr_node == hir_mod.none_node_id or self.hir.kindOf(expr_node) != .identifier) return;
        const id = hir_mod.identifierOf(self.hir, expr_node);
        const use_start = self.hir.spanOf(expr_node).start;
        var root = expr_node;
        while (self.hir.parentOf(root) != hir_mod.none_node_id) root = self.hir.parentOf(root);
        if (self.hir.kindOf(root) != .block_stmt) return;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.hir.spanOf(stmt).start >= use_start) break;
            if (self.hir.kindOf(stmt) != .var_decl and self.hir.kindOf(stmt) != .let_decl) continue;
            const v = hir_mod.varDeclOf(self.hir, stmt);
            if (v.is_ambient) continue;
            if (v.init != hir_mod.none_node_id or v.type_annotation == hir_mod.none_node_id) continue;
            if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, v.name).name == id.name) {
                const name_str = self.string_interner.get(id.name);
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Variable '{s}' is used before being assigned.",
                    .{name_str},
                );
                try self.diagnostics.append(self.gpa, .{
                    .node = expr_node,
                    .code = TsCodes.used_before_assignment,
                    .message = msg,
                });
                return;
            }
        }
    }

    fn checkClassMemberDecoratorDiagnostics(self: *Checker, members: []const NodeId) CheckError!void {
        var accessor_decorators: std.AutoHashMapUnmanaged(hir_mod.StringId, NodeId) = .empty;
        defer accessor_decorators.deinit(self.gpa);
        const metadata_import_check = self.decoratedMetadataImportCheckEnabled();
        var i: usize = 0;
        while (i < members.len) {
            if (self.hir.kindOf(members[i]) != .decorator) {
                i += 1;
                continue;
            }
            const start = i;
            while (i < members.len and self.hir.kindOf(members[i]) == .decorator) : (i += 1) {}
            if (i >= members.len) break;
            const target = members[i];
            for (members[start..i]) |decorator_node| {
                try self.checkClassMemberDecoratorDiagnostic(decorator_node, target);
            }
            if (self.sourceUsesLegacyDecorators()) {
                try self.checkAccessorDecoratorPairDiagnostic(target, members[start], &accessor_decorators);
            }
            if (metadata_import_check) try self.markDecoratedSignatureTypeImports(target);
        }
    }

    /// True when serialized decorator metadata would be emitted AND every
    /// file must be transpilable in isolation under an ESM emit — the exact
    /// combination under which tsc's `markEntityNameOrEntityExpressionAsReference`
    /// reports TS1272. Reading the source `// @…` directives (and the
    /// resolved strict flag) mirrors `compilerOptions.EmitDecoratorMetadata`
    /// / `GetIsolatedModules()` / `GetEmitModuleKind() >= ModuleKindES2015`.
    fn decoratedMetadataImportCheckEnabled(self: *Checker) bool {
        if (!self.sourceDirectiveValueMentions("emitDecoratorMetadata", "true")) return false;
        if (!self.sourceUsesLegacyDecorators()) return false;
        const isolated = self.strict_flags.isolated_modules or
            self.sourceDirectiveValueMentions("isolatedModules", "true") or
            self.sourceDirectiveValueMentions("verbatimModuleSyntax", "true");
        if (!isolated) return false;
        // `GetEmitModuleKind() >= ModuleKindES2015`: every modern (ESM-family)
        // module kind, i.e. the non-CommonJS-family emit formats.
        if (self.sourceEmitFormatIsCommonJsFamily()) return false;
        return true;
    }

    /// Mirror of tsgo `markDecoratorAliasReferenced`: for a decorated class
    /// member, walk the type annotations whose serialized metadata tsc would
    /// emit (method/constructor parameter types + return type, accessor type,
    /// property type) and report TS1272 for any that reference a value-import
    /// alias whose binding is actually type-only.
    fn markDecoratedSignatureTypeImports(self: *Checker, target: NodeId) CheckError!void {
        switch (self.hir.kindOf(target)) {
            .fn_decl, .fn_expr, .arrow_fn => {
                const f = hir_mod.fnDeclOf(self.hir, target);
                for (hir_mod.fnParams(self.hir, target)) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    try self.checkDecoratedMetadataTypeNode(hir_mod.parameterOf(self.hir, p).type_annotation);
                }
                try self.checkDecoratedMetadataTypeNode(f.return_type);
            },
            .object_property => {
                try self.checkDecoratedMetadataTypeNode(hir_mod.objectPropertyOf(self.hir, target).type_annotation);
            },
            else => {},
        }
    }

    /// tsc only serializes a single entity-name reference per type node for
    /// decorator metadata (`getEntityNameForDecoratorMetadata`). Home models
    /// the common case: a direct type reference whose root names an import.
    /// Unions/intersections/other type forms serialize to `Object` and so
    /// never trip TS1272 here, matching tsc's "no common entity name" result.
    fn checkDecoratedMetadataTypeNode(self: *Checker, type_node: NodeId) CheckError!void {
        if (type_node == hir_mod.none_node_id) return;
        if (self.hir.kindOf(type_node) != .type_ref) return;
        try self.reportDecoratedSignatureTypeImport(type_node);
    }

    const DecoratedSignatureImportBinding = struct {
        module: hir_mod.StringId,
        imported_name: hir_mod.StringId,
        specifier_node: NodeId,
        is_namespace: bool,
        is_type_only: bool,
    };

    /// Resolve the import declaration in `anchor`'s virtual section that binds
    /// the local name `local_name`. Mirrors the section-scoped import scan
    /// `localExportNameRuntimeStatusInSection` uses.
    fn sectionImportBindingFor(self: *Checker, anchor: NodeId, local_name: hir_mod.StringId) ?DecoratedSignatureImportBinding {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const section = self.virtualSectionStartForNode(anchor);
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.hir.kindOf(stmt) != .import_decl) continue;
            if (self.virtualSectionStartForNode(stmt) != section) continue;
            const imp = hir_mod.importOf(self.hir, stmt);
            if (imp.namespace_binding != hir_mod.none_node_id and
                self.hir.kindOf(imp.namespace_binding) == .identifier and
                hir_mod.identifierOf(self.hir, imp.namespace_binding).name == local_name)
            {
                return .{
                    .module = imp.module,
                    .imported_name = local_name,
                    .specifier_node = imp.namespace_binding,
                    .is_namespace = true,
                    .is_type_only = imp.is_type_only,
                };
            }
            for (hir_mod.importNamed(self.hir, stmt)) |spec_node| {
                if (self.hir.kindOf(spec_node) != .import_specifier) continue;
                const sp = hir_mod.importSpecifierOf(self.hir, spec_node);
                if (sp.local != local_name) continue;
                return .{
                    .module = imp.module,
                    .imported_name = sp.imported,
                    .specifier_node = spec_node,
                    .is_namespace = false,
                    .is_type_only = imp.is_type_only or sp.is_type_only,
                };
            }
        }
        return null;
    }

    fn reportDecoratedSignatureTypeImport(self: *Checker, type_ref_node: NodeId) CheckError!void {
        const r = hir_mod.typeRefOf(self.hir, type_ref_node);
        const quals = hir_mod.typeRefQualifier(self.hir, type_ref_node);
        // Root identifier of the entity name (`A.B.C` → `A`). tsc resolves
        // the root symbol; a namespace import root is a value and is exempt.
        const root_name = if (quals.len > 0) blk: {
            if (self.hir.kindOf(quals[0]) != .identifier) return;
            break :blk hir_mod.identifierOf(self.hir, quals[0]).name;
        } else r.name;
        const binding = self.sectionImportBindingFor(type_ref_node, root_name) orelse return;
        // `import * as ns` makes `ns` the module-namespace value → not flagged.
        if (binding.is_namespace) return;
        // `import type` is the sanctioned escape hatch.
        if (binding.is_type_only) return;
        const spec = self.string_interner.get(binding.module);
        if (!std.mem.startsWith(u8, spec, ".")) return;
        const status = try self.virtualRelativeModuleNamedExportRuntimeStatus(type_ref_node, spec, binding.imported_name);
        switch (status) {
            // The alias resolves to a type-only binding (a value-position
            // import of a type-only export, or of a type-only re-export):
            // `!symbolIsValue(rootSymbol)` in tsc.
            .type_only_decl, .type_only_alias => {},
            // A real value (class/const/…), or undeterminable: no error.
            .value, .ambient_const_enum, .missing, .unknown => return,
        }
        const root_text = self.string_interner.get(root_name);
        const related_msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' was imported here.",
            .{root_text},
        );
        const related = try self.diag_arena.allocator().dupe(RelatedInfo, &.{.{
            .node = binding.specifier_node,
            .code = TsCodes.name_was_imported_here,
            .message = related_msg,
        }});
        try self.diagnostics.append(self.gpa, .{
            .node = type_ref_node,
            .code = TsCodes.type_referenced_in_decorated_signature,
            .message = "A type referenced in a decorated signature must be imported with 'import type' or a namespace import when 'isolatedModules' and 'emitDecoratorMetadata' are enabled.",
            .related = related,
        });
    }

    fn checkAccessorDecoratorPairDiagnostic(
        self: *Checker,
        target: NodeId,
        decorator_node: NodeId,
        seen: *std.AutoHashMapUnmanaged(hir_mod.StringId, NodeId),
    ) CheckError!void {
        if (target == hir_mod.none_node_id) return;
        if (self.hir.kindOf(target) != .fn_decl and self.hir.kindOf(target) != .fn_expr and self.hir.kindOf(target) != .arrow_fn) return;
        const f = hir_mod.fnDeclOf(self.hir, target);
        if (!f.flags.is_getter and !f.flags.is_setter) return;
        const member_name = (try self.classMemberNameFromFunctionName(f.name)) orelse return;
        if (seen.contains(member_name)) {
            try self.report(decorator_node, TsCodes.multiple_accessor_decorators, "Decorators cannot be applied to multiple get/set accessors of the same name.");
            return;
        }
        try seen.put(self.gpa, member_name, decorator_node);
    }

    fn checkClassMemberDecoratorDiagnostic(self: *Checker, decorator_node: NodeId, target: NodeId) CheckError!void {
        if (self.hir.kindOf(decorator_node) != .decorator) return;
        const d = hir_mod.decoratorOf(self.hir, decorator_node);
        if (d.expression == hir_mod.none_node_id) return;
        if (self.stage3InvalidClassMemberDecoratorCode(target)) |code| {
            const message = if (code == TsCodes.decorator_on_method_overload)
                "A decorator can only decorate a method implementation, not an overload."
            else
                "Decorators are not valid here.";
            try self.report(decorator_node, code, message);
            return;
        }
        // Mirrors upstream `nodeCanBeDecorated`: legacy decorators cannot
        // target any named declaration whose name is a private identifier.
        // Reject the target before checking the decorator expression so the
        // grammar error does not cascade into TS1240/TS1241/TS1270/TS1271.
        if (self.sourceUsesLegacyDecorators() and try self.classMemberTargetHasEcmaPrivateName(target)) {
            try self.report(decorator_node, TsCodes.decorators_not_valid_here, "Decorators are not valid here.");
            return;
        }
        if (self.hir.kindOf(target) == .block_stmt) {
            try self.report(decorator_node, TsCodes.decorators_not_valid_here, "Decorators are not valid here.");
            return;
        }
        _ = try self.checkExpression(d.expression);
        const target_kind = self.hir.kindOf(target);
        if (target_kind == .fn_decl or target_kind == .fn_expr or target_kind == .arrow_fn) {
            const fn_p = hir_mod.fnDeclOf(self.hir, target);
            if (fn_p.flags.is_constructor) {
                try self.report(decorator_node, TsCodes.decorators_not_valid_here, "Decorators are not valid here.");
                return;
            }
            if (fn_p.body == hir_mod.none_node_id and !fn_p.flags.is_getter and !fn_p.flags.is_setter) {
                try self.report(decorator_node, TsCodes.decorator_on_method_overload, "A decorator can only decorate a method implementation, not an overload.");
                return;
            }
            if (self.sourceUsesLegacyDecorators() and !fn_p.flags.is_constructor and self.sourceHasNoLibTrueDirective()) {
                try self.reportMissingGlobalTypeOnce(decorator_node, "TypedPropertyDescriptor");
            }
            if (try self.checkDecoratorFactoryMustBeCalled(decorator_node, d.expression, self.hir.typeOf(d.expression))) return;
            try self.checkDecoratorRuntimeArity(
                decorator_node,
                self.hir.typeOf(d.expression),
                if (self.sourceUsesLegacyDecorators()) 3 else 2,
                TsCodes.method_decorator_signature_unresolved,
                "method",
            );
            try self.checkLegacyMethodDecoratorReturnType(decorator_node, d.expression, target);
            return;
        }
        if (target_kind == .object_property) {
            const op = hir_mod.objectPropertyOf(self.hir, target);
            const op_is_method = op.is_method or
                (op.value != hir_mod.none_node_id and
                    (self.hir.kindOf(op.value) == .fn_decl or self.hir.kindOf(op.value) == .fn_expr or self.hir.kindOf(op.value) == .arrow_fn) and
                    self.memberSourceLooksMethod(target));
            if (op_is_method) {
                if (try self.checkDecoratorFactoryMustBeCalled(decorator_node, d.expression, self.hir.typeOf(d.expression))) return;
                try self.checkDecoratorRuntimeArity(
                    decorator_node,
                    self.hir.typeOf(d.expression),
                    if (self.sourceUsesLegacyDecorators()) 3 else 2,
                    TsCodes.method_decorator_signature_unresolved,
                    "method",
                );
                try self.checkLegacyMethodDecoratorReturnType(decorator_node, d.expression, target);
            } else if (self.sourceUsesLegacyDecorators() and !self.classMemberSourceHasLeadingKeyword(target, "accessor")) {
                try self.checkPropertyDecoratorCallableShape(decorator_node, d.expression);
                // TS1271: a legacy *property* decorator (data field, not a
                // get/set accessor ÃÂ¢ÃÂÃÂ those use the TS1270 descriptor path)
                // must return void/any.
                if (!op.is_accessor) {
                    try self.checkLegacyDecoratorReturnVoidOrAny(decorator_node, d.expression);
                }
            } else if (!self.sourceUsesLegacyDecorators()) {
                try self.checkDecoratorRuntimeArity(
                    decorator_node,
                    self.hir.typeOf(d.expression),
                    2,
                    TsCodes.property_decorator_signature_unresolved,
                    "field",
                );
            }
        }
    }

    fn stage3InvalidClassMemberDecoratorCode(self: *Checker, target: NodeId) ?u32 {
        if (self.sourceUsesLegacyDecorators()) return null;
        switch (self.hir.kindOf(target)) {
            .fn_decl, .fn_expr, .arrow_fn => {
                const fn_p = hir_mod.fnDeclOf(self.hir, target);
                if (fn_p.body != hir_mod.none_node_id) return null;
                return if (fn_p.flags.is_getter or fn_p.flags.is_setter)
                    TsCodes.decorators_not_valid_here
                else
                    TsCodes.decorator_on_method_overload;
            },
            .object_property => {
                const op = hir_mod.objectPropertyOf(self.hir, target);
                if (op.key == hir_mod.none_node_id) return null;
                var fn_is_bodyless = false;
                var fn_is_accessor = false;
                if (op.value != hir_mod.none_node_id) {
                    const value_kind = self.hir.kindOf(op.value);
                    if (value_kind == .fn_decl or value_kind == .fn_expr or value_kind == .arrow_fn) {
                        const fn_p = hir_mod.fnDeclOf(self.hir, op.value);
                        fn_is_bodyless = fn_p.body == hir_mod.none_node_id or fn_p.flags.is_abstract;
                        fn_is_accessor = fn_p.flags.is_getter or fn_p.flags.is_setter;
                    }
                }
                const is_abstract = fn_is_bodyless or
                    self.classMemberSourceHasModifierBeforeKey(target, op.key, "abstract");
                const is_ambient = self.classMemberSourceHasModifierBeforeKey(target, op.key, "declare");
                if (!is_abstract and !is_ambient) return null;
                const is_method = op.is_method or
                    (op.value != hir_mod.none_node_id and
                        (self.hir.kindOf(op.value) == .fn_decl or
                            self.hir.kindOf(op.value) == .fn_expr or
                            self.hir.kindOf(op.value) == .arrow_fn) and
                        self.memberSourceLooksMethod(target));
                return if (is_method and !op.is_accessor and !fn_is_accessor)
                    TsCodes.decorator_on_method_overload
                else
                    TsCodes.decorators_not_valid_here;
            },
            else => return null,
        }
    }

    fn classMemberHasLeadingDecorator(self: *Checker, class_node: NodeId, target: NodeId) bool {
        var saw_decorator = false;
        for (hir_mod.classMembers(self.hir, class_node)) |member| {
            if (member == target) return saw_decorator;
            saw_decorator = self.hir.kindOf(member) == .decorator;
        }
        return false;
    }

    fn classMemberTargetHasEcmaPrivateName(self: *Checker, target: NodeId) CheckError!bool {
        const member_name = switch (self.hir.kindOf(target)) {
            .fn_decl, .fn_expr, .arrow_fn => try self.classMemberNameFromFunctionName(hir_mod.fnDeclOf(self.hir, target).name),
            .object_property => blk: {
                const op = hir_mod.objectPropertyOf(self.hir, target);
                break :blk try self.classMemberNameFromPropertyKey(op.key, op.is_computed);
            },
            else => null,
        } orelse return false;
        return self.memberNameIsEcmaPrivate(member_name);
    }

    fn sourceUsesLegacyDecorators(self: *Checker) bool {
        const src = self.source orelse return false;
        if (std.mem.indexOf(u8, src, "@experimentalDecorators: true") != null) return true;
        if (std.mem.indexOf(u8, src, "@experimentaldecorators: true") != null) return true;
        if (std.mem.indexOf(u8, src, "\"experimentalDecorators\": true") != null) return true;
        if (std.mem.indexOf(u8, src, "\"experimentalDecorators\":true") != null) return true;
        return false;
    }

    fn classMemberSourceHasLeadingKeyword(self: *Checker, node: NodeId, keyword: []const u8) bool {
        const src = self.source orelse return false;
        const span = self.hir.spanOf(node);
        if (span.start >= src.len) return false;
        var i: usize = span.start;
        while (i < src.len) : (i += 1) {
            switch (src[i]) {
                ' ', '\t', '\r', '\n' => continue,
                else => break,
            }
        }
        if (std.mem.startsWith(u8, src[i..], keyword)) {
            const end = i + keyword.len;
            if (end >= src.len) return true;
            if (!std.ascii.isAlphanumeric(src[end]) and src[end] != '_' and src[end] != '$') return true;
        }

        i = span.start;
        while (i > 0) {
            const prev = src[i - 1];
            if (prev == ' ' or prev == '\t' or prev == '\r' or prev == '\n') {
                i -= 1;
                continue;
            }
            break;
        }
        const word_end = i;
        while (i > 0) {
            const prev = src[i - 1];
            if (std.ascii.isAlphanumeric(prev) or prev == '_' or prev == '$') {
                i -= 1;
                continue;
            }
            break;
        }
        return std.mem.eql(u8, src[i..word_end], keyword);
    }

    fn classMemberSourceHasModifierBeforeKey(self: *Checker, member_node: NodeId, key_node: NodeId, keyword: []const u8) bool {
        return self.classMemberModifierPosBeforeKey(member_node, key_node, keyword) != null;
    }

    fn classMemberModifierPosBeforeKey(self: *Checker, member_node: NodeId, key_node: NodeId, keyword: []const u8) ?u32 {
        const src = self.source orelse return null;
        const member_span = self.hir.spanOf(member_node);
        const key_span = self.hir.spanOf(key_node);
        if (member_span.start >= src.len or key_span.start > src.len) return null;
        var line_start: usize = key_span.start;
        while (line_start > 0 and src[line_start - 1] != '\n' and src[line_start - 1] != '\r') {
            line_start -= 1;
        }
        const scan_start = @min(member_span.start, line_start);
        var i: usize = scan_start;
        while (i + keyword.len <= key_span.start) : (i += 1) {
            if (!std.mem.startsWith(u8, src[i..], keyword)) continue;
            const before_ok = i == scan_start or !isIdentifierPartByte(src[i - 1]);
            const end = i + keyword.len;
            const after_ok = end >= key_span.start or !isIdentifierPartByte(src[end]);
            if (before_ok and after_ok) return @intCast(i);
        }
        return null;
    }

    fn isIdentifierPartByte(ch: u8) bool {
        return std.ascii.isAlphanumeric(ch) or ch == '_' or ch == '$';
    }

    fn sourceHasNoLibTrueDirective(self: *Checker) bool {
        const src = self.source orelse return false;
        const pos = std.mem.indexOf(u8, src, "@noLib") orelse std.mem.indexOf(u8, src, "@nolib") orelse return false;
        const line_end = std.mem.indexOfScalarPos(u8, src, pos, '\n') orelse src.len;
        const line = src[pos..line_end];
        return std.mem.indexOf(u8, line, "true") != null;
    }

    fn checkNoLibRequiredGlobalTypes(self: *Checker, root: NodeId, stmts: []const NodeId) CheckError!void {
        if (!self.sourceHasNoLibTrueDirective()) return;
        const RequiredGlobal = struct { name: []const u8, arity: usize };
        const core_names = [_][]const u8{
            "Array",
            "Boolean",
            "Function",
            "IArguments",
            "Number",
            "Object",
            "RegExp",
            "String",
        };
        var core_globals_complete = true;
        for (core_names) |name| {
            if (self.topLevelGlobalTypeDecl(stmts, name) != null) continue;
            core_globals_complete = false;
            break;
        }
        const require_extended_function_globals =
            !core_globals_complete or
            self.sourceDirectiveValueMentions("declaration", "true");
        const required = [_]RequiredGlobal{
            .{ .name = "Array", .arity = 1 },
            .{ .name = "Boolean", .arity = 0 },
            .{ .name = "CallableFunction", .arity = 0 },
            .{ .name = "Function", .arity = 0 },
            .{ .name = "IArguments", .arity = 0 },
            .{ .name = "NewableFunction", .arity = 0 },
            .{ .name = "Number", .arity = 0 },
            .{ .name = "Object", .arity = 0 },
            .{ .name = "RegExp", .arity = 0 },
            .{ .name = "String", .arity = 0 },
        };
        const anchor = if (stmts.len > 0) stmts[0] else root;
        for (required) |global| {
            if (!require_extended_function_globals and
                (std.mem.eql(u8, global.name, "CallableFunction") or
                    std.mem.eql(u8, global.name, "NewableFunction")))
            {
                continue;
            }
            const decl = self.topLevelGlobalTypeDecl(stmts, global.name) orelse {
                try self.reportMissingGlobalTypeOnce(anchor, global.name);
                continue;
            };
            switch (self.hir.kindOf(decl.node)) {
                .interface_decl, .class_decl, .class_expr => {
                    const actual = self.declarationTypeParameterCount(decl.node);
                    if (actual != global.arity) {
                        try self.reportGlobalTypeWrongArity(decl.name_node, global.name, global.arity);
                    }
                },
                else => try self.reportGlobalTypeMustBeClassOrInterface(decl.name_node, global.name),
            }
        }
    }

    const GlobalTypeDecl = struct {
        node: NodeId,
        name_node: NodeId,
    };

    fn topLevelGlobalTypeDecl(self: *Checker, stmts: []const NodeId, name: []const u8) ?GlobalTypeDecl {
        for (stmts) |stmt| {
            const decl = self.unwrapExportDecl(stmt);
            const name_node = self.globalTypeDeclarationNameNode(decl) orelse continue;
            if (self.hir.kindOf(name_node) != .identifier) continue;
            const id = hir_mod.identifierOf(self.hir, name_node);
            if (!std.mem.eql(u8, self.string_interner.get(id.name), name)) continue;
            return .{ .node = decl, .name_node = name_node };
        }
        return null;
    }

    fn globalTypeDeclarationNameNode(self: *Checker, decl: NodeId) ?NodeId {
        return switch (self.hir.kindOf(decl)) {
            .interface_decl => hir_mod.interfaceOf(self.hir, decl).name,
            .class_decl, .class_expr => hir_mod.classOf(self.hir, decl).name,
            .type_alias_decl => hir_mod.typeAliasOf(self.hir, decl).name,
            .enum_decl => hir_mod.enumOf(self.hir, decl).name,
            else => null,
        };
    }

    fn declarationTypeParameterCount(self: *Checker, decl: NodeId) usize {
        return switch (self.hir.kindOf(decl)) {
            .interface_decl => blk: {
                const it = hir_mod.interfaceOf(self.hir, decl);
                break :blk self.hir.childSlice(it.type_params_start, it.type_params_len).len;
            },
            .class_decl, .class_expr => blk: {
                const cls = hir_mod.classOf(self.hir, decl);
                break :blk self.hir.childSlice(cls.type_params_start, cls.type_params_len).len;
            },
            .type_alias_decl => blk: {
                const ta = hir_mod.typeAliasOf(self.hir, decl);
                break :blk self.hir.childSlice(ta.type_params_start, ta.type_params_len).len;
            },
            else => 0,
        };
    }

    fn reportGlobalTypeMustBeClassOrInterface(self: *Checker, node: NodeId, name: []const u8) CheckError!void {
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Global type '{s}' must be a class or interface type.",
            .{name},
        );
        try self.report(node, TsCodes.global_type_must_be_class_or_interface, msg);
    }

    fn reportGlobalTypeWrongArity(self: *Checker, node: NodeId, name: []const u8, arity: usize) CheckError!void {
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Global type '{s}' must have {d} type parameter(s).",
            .{ name, arity },
        );
        try self.report(node, TsCodes.global_type_wrong_arity, msg);
    }

    fn reportMissingGlobalTypeOnce(self: *Checker, node: NodeId, name: []const u8) CheckError!void {
        for (self.diagnostics.items) |d| {
            if (d.code == TsCodes.cannot_find_global_type and missingGlobalTypeDiagnosticNames(d.message, name)) return;
        }
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Cannot find global type '{s}'.",
            .{name},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.cannot_find_global_type,
            .message = msg,
            .is_global = true,
        });
    }

    fn missingGlobalTypeDiagnosticNames(message: []const u8, name: []const u8) bool {
        const prefix = "Cannot find global type '";
        const suffix = "'.";
        if (message.len != prefix.len + name.len + suffix.len) return false;
        if (!std.mem.startsWith(u8, message, prefix)) return false;
        if (!std.mem.endsWith(u8, message, suffix)) return false;
        return std.mem.eql(u8, message[prefix.len .. prefix.len + name.len], name);
    }

    fn checkNoLibDynamicImportPromiseValue(self: *Checker, node: NodeId) CheckError!void {
        if (self.sourceHasNoLibTrueDirective() and !self.rootHasTopLevelGlobalTypeDecl(node, "Promise")) {
            try self.reportMissingGlobalTypeOnce(node, "Promise");
            try self.reportDynamicImportReturnsPromiseMissingType(node);
            return;
        }
        if (self.rootHasTopLevelGlobalValueDecl(node, "Promise")) return;
        const no_lib_missing_ctor = self.sourceHasNoLibTrueDirective() and self.rootHasTopLevelGlobalTypeDecl(node, "Promise");
        const lib_missing_ctor = self.sourceLibDirectiveExcludes("es2015");
        if (!no_lib_missing_ctor and !lib_missing_ctor) return;
        if (no_lib_missing_ctor) try self.reportMissingGlobalValueOnce(node, "Promise");
        try self.reportDynamicImportRequiresPromiseConstructor(node);
    }

    fn reportDynamicImportReturnsPromiseMissingType(self: *Checker, node: NodeId) CheckError!void {
        try self.report(
            node,
            TsCodes.dynamic_import_returns_promise_missing_type,
            "A dynamic import call returns a 'Promise'. Make sure you have a declaration for 'Promise' or include 'ES2015' in your '--lib' option.",
        );
    }

    fn reportDynamicImportRequiresPromiseConstructor(self: *Checker, node: NodeId) CheckError!void {
        try self.report(
            node,
            TsCodes.dynamic_import_requires_promise_constructor,
            "A dynamic import call in ES5 requires the 'Promise' constructor.  Make sure you have a declaration for the 'Promise' constructor or include 'ES2015' in your '--lib' option.",
        );
    }

    fn rootHasTopLevelGlobalTypeDecl(self: *Checker, anchor: NodeId, name: []const u8) bool {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        return self.topLevelGlobalTypeDecl(hir_mod.blockStmts(self.hir, root), name) != null;
    }

    fn rootHasTopLevelGlobalValueDecl(self: *Checker, anchor: NodeId, name: []const u8) bool {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            const decl = self.unwrapExportDecl(stmt);
            const name_node = self.globalValueDeclarationNameNode(decl) orelse continue;
            if (self.hir.kindOf(name_node) != .identifier) continue;
            const id = hir_mod.identifierOf(self.hir, name_node);
            if (std.mem.eql(u8, self.string_interner.get(id.name), name)) return true;
        }
        return false;
    }

    fn globalValueDeclarationNameNode(self: *Checker, decl: NodeId) ?NodeId {
        return switch (self.hir.kindOf(decl)) {
            .var_decl, .let_decl, .const_decl => hir_mod.varDeclOf(self.hir, decl).name,
            .fn_decl => hir_mod.fnDeclOf(self.hir, decl).name,
            .class_decl, .class_expr => hir_mod.classOf(self.hir, decl).name,
            .enum_decl => hir_mod.enumOf(self.hir, decl).name,
            .namespace_decl => hir_mod.namespaceOf(self.hir, decl).name,
            else => null,
        };
    }

    fn reportMissingGlobalValueOnce(self: *Checker, node: NodeId, name: []const u8) CheckError!void {
        for (self.diagnostics.items) |d| {
            if (d.code == TsCodes.cannot_find_global_value and std.mem.indexOf(u8, d.message, name) != null) return;
        }
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Cannot find global value '{s}'.",
            .{name},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.cannot_find_global_value,
            .message = msg,
        });
    }

    fn checkParameterDecoratorDiagnostics(self: *Checker, param_node: NodeId, fn_node: NodeId, param_index: usize, is_this_param: bool) CheckError!void {
        const decorators = hir_mod.parameterDecorators(self.hir, param_node);
        if (decorators.len == 0) return;
        if (is_this_param) {
            return;
        }
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        for (decorators) |decorator_node| {
            if (self.hir.kindOf(decorator_node) != .decorator) continue;
            const d = hir_mod.decoratorOf(self.hir, decorator_node);
            if (d.expression == hir_mod.none_node_id) continue;
            const dec_t = try self.checkExpression(d.expression);
            const p = hir_mod.parameterOf(self.hir, param_node);
            const standard_constructor_parameter_property = f.flags.is_constructor and p.flags.is_parameter_property;
            if (!self.sourceUsesLegacyDecorators() and !standard_constructor_parameter_property) {
                try self.report(
                    decorator_node,
                    TsCodes.decorators_not_valid_here,
                    "Decorators are not valid here.",
                );
                continue;
            }
            if (f.flags.is_constructor) {
                try self.checkConstructorParameterDecoratorSignature(decorator_node, dec_t, param_index);
            }
            // TS1271: a parameter decorator must return void/any. Parameter
            // decorators only exist under legacy (`experimentalDecorators`)
            // mode; standard decorators reject them with a grammar error.
            try self.checkLegacyDecoratorReturnVoidOrAny(decorator_node, d.expression);
        }
    }

    fn checkConstructorParameterDecoratorSignature(self: *Checker, decorator_node: NodeId, dec_t: TypeId, param_index: usize) CheckError!void {
        _ = param_index;
        if (dec_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(dec_t).is_signature) return;
        const params = self.interner.signatureParams(dec_t);
        if (params.len < 2) return;
        const property_key_t = params[1];
        if (self.typeIncludesUndefined(property_key_t)) return;
        const dec_pos = self.decoratorExpressionPos(decorator_node);
        try self.reportAt(
            decorator_node,
            dec_pos,
            TsCodes.parameter_decorator_signature_unresolved,
            "Unable to resolve signature of parameter decorator when called as an expression.",
        );
    }

    /// Decorator-anchor helper. Span starts at `@`; tsc anchors the
    /// diagnostic at the expression itself (column of the first
    /// expression character, e.g. `dec` in `@dec()`).
    fn decoratorExpressionPos(self: *Checker, decorator_node: NodeId) ?u32 {
        const span = self.hir.spanOf(decorator_node);
        if (self.source) |src| {
            if (span.start < src.len and src[span.start] == '@') {
                return @intCast(@as(usize, span.start) + 1);
            }
        }
        return null;
    }

    /// tsgo `checkDecorator` accepts a decorator return type when it is
    /// `any` (short-circuited at the top of the function) or assignable
    /// to the expected `void` return ÃÂ¢ÃÂÃÂ so `void`, `undefined`, and
    /// `never` all pass, and every other concrete type fails.
    fn decoratorReturnIsVoidOrAny(self: *Checker, ret_t: TypeId) bool {
        if (ret_t == types.Primitive.any or
            ret_t == types.Primitive.void_t or
            ret_t == types.Primitive.undefined_t or
            ret_t == types.Primitive.never) return true;
        return self.engine.isAssignableTo(ret_t, types.Primitive.void_t) catch true;
    }

    /// TS1271 for the legacy property-decorator and parameter-decorator
    /// sites: the applied decorator's return type must be `void` or
    /// `any`. `expr` is the decorator expression (`dec` in `@dec`, or the
    /// `dec()` call in `@dec()`); its checked type is the applied
    /// decorator signature, whose return type is validated. Reports the
    /// actual return type as `{0}`, anchored at the decorator expression
    /// (matching tsgo's `node.Expression()` anchor).
    fn checkLegacyDecoratorReturnVoidOrAny(self: *Checker, decorator_node: NodeId, expr: NodeId) CheckError!void {
        const dec_t = self.hir.typeOf(expr);
        if (dec_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(dec_t).is_signature) return;
        if (self.signatureIsConstruct(dec_t)) return;
        const ret_t = self.interner.signatureReturn(dec_t) orelse return;
        if (ret_t >= self.interner.pool.typeCount()) return;
        if (self.decoratorReturnIsVoidOrAny(ret_t)) return;
        // A decorator whose return type is itself a function (`@dec` where
        // `dec(): (target, key) => void` returns a decorator) is the
        // factory-returning-decorator shape: tsc resolves the bare-name
        // decorator call against the inner function's arity, so the
        // outer return never trips TS1271. Mirrors
        // `decoratorOnClassProperty11.ts`.
        if (self.interner.pool.flagsOf(ret_t).is_signature) return;
        const ret_name = (try self.simpleDiagnosticTypeName(ret_t)) orelse
            (try self.allocSimpleTypeName(ret_t)) orelse return;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Decorator function return type is '{s}' but is expected to be 'void' or 'any'.",
            .{ret_name},
        );
        if (self.privateAccessDiagnosticAlreadyReported(decorator_node, TsCodes.decorator_return_void_or_any)) return;
        try self.reportAt(decorator_node, self.decoratorExpressionPos(decorator_node), TsCodes.decorator_return_void_or_any, msg);
    }

    fn checkPropertyDecoratorCallableShape(self: *Checker, decorator_node: NodeId, expr: NodeId) CheckError!void {
        const dec_t = self.hir.typeOf(expr);
        if (dec_t >= self.interner.pool.typeCount()) return;
        if (!self.interner.pool.flagsOf(dec_t).is_signature) {
            // Non-callable property decorator (e.g. `@dec` where `dec: number`):
            // tsc emits TS1240. The shared arity emitter reports the
            // "Unable to resolve signature of property decorator..." text for
            // any concrete non-signature type (skips any/unknown).
            try self.checkDecoratorRuntimeArity(decorator_node, dec_t, 2, TsCodes.property_decorator_signature_unresolved, "property");
            return;
        }
        const params = self.interner.signatureParams(dec_t);
        const ret_t = self.interner.signatureReturn(dec_t) orelse types.Primitive.void_t;
        if (self.hir.kindOf(expr) == .identifier and params.len == 0 and ret_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(ret_t).is_signature) {
            try self.reportDecoratorFactoryMustBeCalled(decorator_node, expr);
            return;
        }
        try self.checkPropertyDecoratorSignatureArity(decorator_node, dec_t);
    }

    fn reportDecoratorFactoryMustBeCalled(self: *Checker, decorator_node: NodeId, expr: NodeId) CheckError!void {
        const id = hir_mod.identifierOf(self.hir, expr);
        const name = self.string_interner.get(id.name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' accepts too few arguments to be used as a decorator here. Did you mean to call it first and write '@{s}()'?",
            .{ name, name },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = decorator_node,
            .code = TsCodes.decorator_too_few_arguments,
            .message = msg,
        });
    }

    fn checkDecoratorFactoryMustBeCalled(self: *Checker, decorator_node: NodeId, expr: NodeId, dec_t: TypeId) CheckError!bool {
        if (self.hir.kindOf(expr) != .identifier) return false;
        if (dec_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(dec_t).is_signature) return false;
        const params = self.interner.signatureParams(dec_t);
        if (params.len != 0) return false;
        const ret_t = self.interner.signatureReturn(dec_t) orelse return false;
        if (ret_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(ret_t).is_signature) return false;
        try self.reportDecoratorFactoryMustBeCalled(decorator_node, expr);
        return true;
    }

    fn checkLegacyMethodDecoratorReturnType(self: *Checker, decorator_node: NodeId, expr: NodeId, target: NodeId) CheckError!void {
        if (!self.sourceUsesLegacyDecorators()) return;
        const dec_t = self.hir.typeOf(expr);
        if (dec_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(dec_t).is_signature) return;
        const params = self.interner.signatureParams(dec_t);
        if (params.len != 1) return;
        const ret_t = self.interner.signatureReturn(dec_t) orelse return;
        if (ret_t != params[0]) return;
        if (!self.containsFreeTypeParameter(ret_t)) return;
        const class_name = self.enclosingClassNameForMember(target) orelse return;
        const method_type = (try self.classMemberMethodTypeDisplay(target)) orelse return;
        const expected_type = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "void | TypedPropertyDescriptor<{s}>",
            .{method_type},
        );
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Decorator function return type '{s}' is not assignable to type '{s}'.",
            .{ class_name, expected_type },
        );
        try self.reportAt(decorator_node, self.decoratorExpressionPos(decorator_node), TsCodes.decorator_return_type_not_assignable, msg);
    }

    fn classMemberMethodTypeDisplay(self: *Checker, member_node: NodeId) CheckError!?[]const u8 {
        return switch (self.hir.kindOf(member_node)) {
            .fn_decl, .fn_expr, .arrow_fn => blk: {
                const fn_p = hir_mod.fnDeclOf(self.hir, member_node);
                break :blk try self.classMemberDuplicateFnTypeDisplay(fn_p);
            },
            .object_property => blk: {
                const op = hir_mod.objectPropertyOf(self.hir, member_node);
                if (op.value == hir_mod.none_node_id) break :blk null;
                if (self.hir.kindOf(op.value) != .fn_decl and
                    self.hir.kindOf(op.value) != .fn_expr and
                    self.hir.kindOf(op.value) != .arrow_fn) break :blk null;
                const fn_p = hir_mod.fnDeclOf(self.hir, op.value);
                break :blk try self.classMemberDuplicateFnTypeDisplay(fn_p);
            },
            else => null,
        };
    }

    fn enclosingClassNameForMember(self: *Checker, member_node: NodeId) ?[]const u8 {
        var cur = member_node;
        while (cur != hir_mod.none_node_id) {
            if (self.hir.kindOf(cur) == .class_decl or self.hir.kindOf(cur) == .class_expr) {
                const c = hir_mod.classOf(self.hir, cur);
                if (c.name == hir_mod.none_node_id or self.hir.kindOf(c.name) != .identifier) return null;
                return self.string_interner.get(hir_mod.identifierOf(self.hir, c.name).name);
            }
            cur = self.hir.parentOf(cur);
        }
        return null;
    }

    fn checkPropertyDecoratorSignatureArity(self: *Checker, decorator_node: NodeId, sig: TypeId) CheckError!void {
        try self.checkDecoratorRuntimeArity(
            decorator_node,
            sig,
            2,
            TsCodes.property_decorator_signature_unresolved,
            "property",
        );
    }

    fn checkDecoratorRuntimeArity(
        self: *Checker,
        decorator_node: NodeId,
        sig: TypeId,
        runtime_arg_count: usize,
        signature_unresolved_code: u32,
        kind: []const u8,
    ) CheckError!void {
        if (sig == types.Primitive.any or sig == types.Primitive.unknown or sig == types.Primitive.none) return;
        if (sig < self.interner.pool.typeCount() and !self.interner.pool.flagsOf(sig).is_signature) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Unable to resolve signature of {s} decorator when called as an expression.",
                .{kind},
            );
            try self.reportAt(decorator_node, self.decoratorExpressionPos(decorator_node), signature_unresolved_code, msg);
            return;
        }
        if (self.decoratorRuntimeAritySatisfied(sig, runtime_arg_count, kind)) return;
        const params = self.interner.signatureParams(sig);
        const min_required = self.signatureMinRequiredArgs(sig, params);
        const has_unbounded_rest = self.decoratorSignatureHasUnboundedRest(sig, params);
        const expected_count = if (runtime_arg_count < min_required) min_required else params.len;
        // Under legacy (experimentalDecorators) a legacy PROPERTY decorator
        // that ACCEPTS the runtime arg count but whose parameter TYPE can't
        // receive the call (e.g. `dec(target: Function)` — the prototype isn't
        // a Function) surfaces as the signature-unresolved code TS1240
        // ("Unable to resolve signature of property decorator when called as an
        // expression."), not the TC39 TS1278/TS1279 arity codes. A decorator
        // that genuinely wants MORE args than the runtime supplies (or has an
        // unbounded rest) is a real arity error and keeps TS1278/TS1279.
        // Mirrors decoratorOnClassProperty6.ts. (Scoped to "property";
        // method/class legacy forms are left unchanged absent a confirmed
        // baseline.)
        const arity_code = if (has_unbounded_rest)
            TsCodes.decorator_runtime_expects_at_least
        else
            TsCodes.decorator_runtime_expects;
        const arity_msg = if (has_unbounded_rest)
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "The runtime will invoke the decorator with {d} arguments, but the decorator expects at least {d}.",
                .{ runtime_arg_count, expected_count },
            )
        else
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "The runtime will invoke the decorator with {d} arguments, but the decorator expects {d}.",
                .{ runtime_arg_count, expected_count },
            );
        // Decorators are resolved as synthetic calls in both legacy and
        // standard mode. Keep the arity failure as a TS1278/TS1279 detail
        // under the decorator-kind TS1238/TS1240/TS1241 diagnostic head.
        // This is tsgo's `resolveDecorator` + `resolveCall(headMessage)`
        // behavior, including standard decorators such as
        // `@((a, b, c) => {}) class C {}`.
        const unresolved_msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Unable to resolve signature of {s} decorator when called as an expression.",
            .{kind},
        );
        const chain = try self.diag_arena.allocator().dupe(DiagnosticChainEntry, &.{.{
            .code = arity_code,
            .message = arity_msg,
        }});
        const requires_more = runtime_arg_count < min_required;
        const unresolved_pos = if (requires_more or
            (self.sourceUsesLegacyDecorators() and std.mem.eql(u8, kind, "class")))
            self.decoratorAtPos(decorator_node)
        else
            self.decoratorExpressionPos(decorator_node);
        try self.diagnostics.append(self.gpa, .{
            .node = decorator_node,
            .pos = unresolved_pos,
            .code = signature_unresolved_code,
            .message = unresolved_msg,
            .chain = chain,
        });
    }

    fn decoratorRuntimeAritySatisfied(self: *Checker, sig: TypeId, runtime_arg_count: usize, kind: []const u8) bool {
        if (sig >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(sig).is_signature) return true;
        const params = self.interner.signatureParams(sig);
        const min_required = self.signatureMinRequiredArgs(sig, params);
        const has_unbounded_rest = self.decoratorSignatureHasUnboundedRest(sig, params);
        // Standard decorators synthesize one or two arguments depending on
        // the candidate signature: min(max(parameterCount, 1), 2). The
        // diagnostic still describes the two runtime arguments. This lets a
        // one-parameter decorator intentionally ignore the context argument,
        // while zero- and three-required-parameter signatures remain errors.
        const effective_runtime_arg_count = if (self.sourceUsesLegacyDecorators())
            runtime_arg_count
        else
            @min(@max(params.len, 1), runtime_arg_count);
        if (effective_runtime_arg_count > params.len and self.decoratorSignatureAllowsExtraRuntimeArgs(kind, params)) return true;
        return effective_runtime_arg_count >= min_required and (has_unbounded_rest or effective_runtime_arg_count <= params.len);
    }

    fn decoratorSignatureHasUnboundedRest(self: *Checker, sig: TypeId, params: []const TypeId) bool {
        return self.rest_signatures.contains(sig) and params.len > 0 and self.fixedTupleLength(params[params.len - 1]) == null;
    }

    fn decoratorAtPos(self: *Checker, decorator_node: NodeId) ?u32 {
        const span = self.hir.spanOf(decorator_node);
        if (self.source) |src| {
            if (span.start < src.len and src[span.start] == '@') {
                return @intCast(span.start);
            }
        }
        return null;
    }

    fn decoratorSignatureAllowsExtraRuntimeArgs(self: *Checker, kind: []const u8, params: []const TypeId) bool {
        if (!std.mem.eql(u8, kind, "method")) return false;
        if (params.len != 2) return false;
        _ = self;
        return params[0] == types.Primitive.any or params[0] == types.Primitive.unknown;
    }

    /// Lower a class declaration into an instance object type. Each
    /// TS2725 ÃÂ¢ÃÂÃÂ `export class Object {}` is forbidden when the
    /// emit target is ES5+ and the module format is CommonJS / UMD
    /// (which would conflict with the global `Object` symbol the
    /// emitter pulls in). Fires only on classes whose name is
    /// literally `Object` and only on the export-prefixed forms
    /// (`export class Object`, `export default class Object`) since
    /// those are what tsc reports ÃÂ¢ÃÂÃÂ non-exported `class Object` is
    /// still permitted.
    fn checkClassNamedObjectInCommonJsLikeModule(self: *Checker, node: NodeId) CheckError!void {
        const c = hir_mod.classOf(self.hir, node);
        if (c.name == hir_mod.none_node_id or self.hir.kindOf(c.name) != .identifier) return;
        const id = hir_mod.identifierOf(self.hir, c.name);
        if (!std.mem.eql(u8, self.string_interner.get(id.name), "Object")) return;
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .export_decl) return;
        if (self.classHasLeadingDeclare(node)) return;
        if (self.virtualSectionIsDeclarationFile(node)) return;
        const module_label: []const u8 = if (self.sourceDirectiveValueMentions("module", "commonjs"))
            "CommonJS"
        else if (self.sourceDirectiveValueMentions("module", "umd"))
            "UMD"
        else if (self.sourceDirectiveValueMentions("module", "amd"))
            "AMD"
        else if (self.sourceDirectiveValueMentions("module", "system"))
            "System"
        else
            return;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Class name cannot be 'Object' when targeting ES5 and above with module {s}.",
            .{module_label},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = c.name,
            .code = TsCodes.class_name_object_es5_module,
            .message = msg,
        });
    }

    /// True when `decl` (a class/interface/etc. declaration node) is
    /// directly exported ÃÂ¢ÃÂÃÂ its immediate parent is an `export_decl`
    /// wrapper whose payload re-exports this declaration. Mirrors how
    /// the binder/checker treats `export class C {}` versus a bare
    /// `class C {}`.
    fn declarationNodeIsExported(self: *Checker, decl: NodeId) bool {
        const parent = self.hir.parentOf(decl);
        if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .export_decl) return false;
        return hir_mod.exportOf(self.hir, parent).decl == decl;
    }

    /// Returns the slice of statements forming the module body that
    /// directly *contains* `decl`. For a top-level declaration this is
    /// the source-file root's statement list; for one inside a
    /// `namespace`/`module` block it is that namespace's body. The
    /// container is found by walking the parent chain (a declaration's
    /// parent is its optional `export_decl` wrapper, whose parent is
    /// the enclosing block / namespace).
    fn enclosingModuleStatements(self: *Checker, decl: NodeId) ?[]const NodeId {
        var node = decl;
        while (node != hir_mod.none_node_id) {
            const parent = self.hir.parentOf(node);
            if (parent == hir_mod.none_node_id) {
                // Reached the source-file root (a `.block_stmt` with no parent).
                if (self.hir.kindOf(node) == .block_stmt) return hir_mod.blockStmts(self.hir, node);
                return null;
            }
            switch (self.hir.kindOf(parent)) {
                .namespace_decl => return hir_mod.namespaceBody(self.hir, parent),
                .block_stmt => {
                    // The source-file root is a `.block_stmt` with no parent.
                    const grand = self.hir.parentOf(parent);
                    if (grand == hir_mod.none_node_id) return hir_mod.blockStmts(self.hir, parent);
                    node = parent;
                },
                else => node = parent,
            }
        }
        return null;
    }

    /// True when `name` is declared *non-exported* in `stmts` (the
    /// statements of the enclosing module body) as a type-space
    /// binding that cannot be named from the emitted `.d.ts` ÃÂ¢ÃÂÃÂ i.e. a
    /// module-local class / interface / type-alias / enum / namespace
    /// that is NOT re-exported. Exported declarations (which CAN be
    /// referenced from a `.d.ts`) and names that don't resolve to a
    /// sibling declaration at all (globals, lib types, imports,
    /// outer-scope names) return false. This is the declaration-emit
    /// "accessibility" predicate restricted to the clearly-correct
    /// same-module case.
    fn nameIsModuleLocalPrivate(self: *Checker, stmts: []const NodeId, name: hir_mod.StringId) bool {
        var found_private = false;
        for (stmts) |raw| {
            const exported = self.hir.kindOf(raw) == .export_decl;
            const decl = self.unwrapExportDecl(raw);
            const is_type_space = switch (self.hir.kindOf(decl)) {
                .class_decl, .interface_decl, .type_alias_decl, .enum_decl, .namespace_decl => true,
                else => false,
            };
            if (!is_type_space) continue;
            const decl_name = self.declarationName(decl) orelse continue;
            if (decl_name != name) continue;
            // Any exported declaration of this name makes it nameable
            // from the `.d.ts` ÃÂ¢ÃÂÃÂ a merged declaration (e.g. interface +
            // namespace) is accessible if ANY arm is exported.
            if (exported) return false;
            found_private = true;
        }
        return found_private;
    }

    /// Declaration-emit binding-origin classification for a bare type
    /// name referenced from an exported declaration. This is the
    /// additive analysis primitive the `from external module` /
    /// `from private module` TS4xxx cluster (TS4023/4024/4026/...) needs:
    /// upstream resolves the referenced symbol, finds its declaring
    /// module via `getExternalModuleContainer`, and compares it to the
    /// enclosing module to choose between the `cannot be named`
    /// (external module) and `from private module` renderings (see
    /// `isSymbolAccessibleWorker` / `selectDiagnosticBasedOnModuleName`
    /// in typescript-go `internal/checker/symbolaccessibility.go` +
    /// `internal/transformers/declarations/diagnostics.go`).
    ///
    /// In Home the type checker runs per-file with no cross-module
    /// export symbol table (the program graph in `ts_program` resolves
    /// import *paths* but does not yet merge foreign export tables --
    /// see its `GlobalAugmentation` note: "requires shared
    /// string-interning across files which the program graph does not
    /// yet provide"). So this classifier reports only the facts a
    /// single file can establish faithfully, leaving the actual emit
    /// blocked until that cross-file resolution lands.
    const BareNameOrigin = union(enum) {
        /// Name is declared non-exported in this module body (the
        /// same-module private-name case `nameIsModuleLocalPrivate`
        /// already emits -- TS4025/4031/4060/...).
        module_local_private,
        /// Name is bound by an `import` declaration in this file; its
        /// declaring module is external. `specifier` is the verbatim
        /// module specifier text (e.g. `"./type"`). NOTE: upstream
        /// renders the *resolved module symbol name* (`"type"`), not
        /// the specifier, so faithful emission needs the resolver.
        imported_external: struct {
            specifier: hir_mod.StringId,
            /// True when the import is re-exported from this file
            /// (`export { Foo }` / `export ... from`), which makes the
            /// name accessible in the emitted `.d.ts` (no diagnostic).
            re_exported: bool,
        },
        /// Name is exported / a global / an outer-scope binding / not a
        /// sibling type declaration -- accessible or out of scope. No
        /// declaration-emit privacy diagnostic.
        accessible,
    };

    /// Classify where a bare type `name` referenced inside `stmts`
    /// (the enclosing module body) is bound. Faithful to the
    /// single-file-determinable subset; see `BareNameOrigin`.
    fn classifyBareNameOrigin(self: *Checker, stmts: []const NodeId, name: hir_mod.StringId) BareNameOrigin {
        // Module-local (non-exported) type-space binding takes priority:
        // it is the clearly-correct same-module case already handled by
        // `nameIsModuleLocalPrivate`.
        if (self.nameIsModuleLocalPrivate(stmts, name)) return .module_local_private;

        // An `import` binding means the declaring module is external.
        // Track whether the same name is re-exported so callers know it
        // is nameable from the `.d.ts` (and thus must NOT diagnose).
        var import_specifier: ?hir_mod.StringId = null;
        var re_exported = false;
        for (stmts) |raw| {
            switch (self.hir.kindOf(raw)) {
                .import_decl => {
                    if (self.importDeclBindsName(raw, name, false)) {
                        import_specifier = hir_mod.importOf(self.hir, raw).module;
                    }
                },
                .export_decl => {
                    // `export { name }` / `export { name } from "m"`.
                    // Named-export specifiers reuse the import-specifier
                    // payload (`imported` = local source name, `local` =
                    // public exported alias).
                    for (hir_mod.exportNamed(self.hir, raw)) |spec_node| {
                        if (self.hir.kindOf(spec_node) != .import_specifier) continue;
                        const spec = hir_mod.importSpecifierOf(self.hir, spec_node);
                        if (spec.imported == name or spec.local == name) re_exported = true;
                    }
                },
                else => {},
            }
        }
        if (import_specifier) |spec| {
            return .{ .imported_external = .{ .specifier = spec, .re_exported = re_exported } };
        }
        return .accessible;
    }

    // Cross-module declaration-emit privacy: when an exported
    // declaration's WRITTEN type annotation references a bare type
    // `name` that is `import`-bound in this file (and not re-exported)
    // AND that name is an exported type-space symbol in its resolved
    // source module, return the rendered module name for the `{2}`
    // diagnostic slot. The importing alias is not preserved in the
    // emitted `.d.ts`, so the type leaks a name from a "private"
    // module relative to the declaration. Mirrors upstream's
    // `selectDiagnosticBasedOnModuleName(... privateModule ...)` for the
    // ErrorModuleName-set-but-accessible case (the symbol IS named-able
    // from its own module). Requires the external resolver's
    // `moduleExport` query (the cross-file export-table merge); without
    // it we cannot establish the cross-file fact, so we stay silent.
    //
    // The `cannot be named` (TS4023/...) variant is distinguished by the
    // resolver's `cannot_be_named` flag: the name is reachable in its
    // module only as a nested member of an exported namespace, so no
    // top-level import alias can name it (upstream's `Accessibility ==
    // CannotBeNamed`). See `CrossModulePrivacy`.

    /// Outcome of the cross-module declaration-emit privacy query for a
    /// bare type `name`. Mirrors the relevant subset of upstream
    /// `selectDiagnosticBasedOnModuleName`: `ErrorModuleName` is always
    /// set (we have a resolved module), and `Accessibility` is either
    /// `NotAccessible` (the `from private module` case) or
    /// `CannotBeNamed` (the `but cannot be named` case).
    const CrossModulePrivacy = union(enum) {
        /// The name IS a top-level type-space export of its module; the
        /// importing alias is not preserved in the `.d.ts`. Renders the
        /// `from private module '{2}'` message (TS4024/4030/...).
        private_module: []const u8,
        /// The name is reachable only as a nested member of an exported
        /// namespace of its module — no importable top-level alias.
        /// Renders the `from external module {2} but cannot be named`
        /// message (TS4023/4026/...). The payload is the rendered module
        /// name for the `{2}` slot.
        cannot_be_named: []const u8,
    };

    fn crossModulePrivateNameInfo(self: *Checker, stmts: []const NodeId, name: hir_mod.StringId) ?CrossModulePrivacy {
        if (!self.strict_flags.declaration) return null;
        const resolver = self.external_resolver orelse return null;
        if (self.importer_path.len == 0) return null;

        const origin = self.classifyBareNameOrigin(stmts, name);
        switch (origin) {
            .imported_external => |ie| {
                if (ie.re_exported) return null;
                const specifier = self.string_interner.get(ie.specifier);
                const bare = self.string_interner.get(name);
                const info = resolver.moduleExport(specifier, self.importer_path, bare) orelse return null;
                // `from private module`: the name is genuinely a
                // top-level type-space export (so it has a module
                // container and a renderable `{2}`), but the written
                // alias is not preserved in the `.d.ts`.
                if (info.exported_type) return .{ .private_module = info.module_name };
                // `but cannot be named`: the name is reachable only as a
                // nested namespace member; no top-level alias can name it
                // (Accessibility == CannotBeNamed).
                if (info.cannot_be_named) return .{ .cannot_be_named = info.module_name };
                return null;
            },
            else => return null,
        }
    }

    /// Declaration-emit symbol-accessibility check for heritage clauses
    /// (TS4019 / TS4020 / TS4022). When `declaration` emit is enabled and
    /// `decl` (an exported class or interface) has an `extends` /
    /// `implements` clause that names a non-exported module-local type,
    /// the name cannot appear in the generated `.d.ts`, so we report the
    /// "has or is using private name" diagnostic anchored at the heritage
    /// type reference. Restricted to bare (unqualified) heritage names in
    /// the same module body ÃÂ¢ÃÂÃÂ the clearly-correct subset; qualified
    /// namespace-member references are intentionally left to the broader
    /// accessibility analysis.
    fn checkHeritagePrivateNames(
        self: *Checker,
        decl: NodeId,
        owner_name: ?hir_mod.StringId,
        is_class: bool,
    ) CheckError!void {
        if (!self.strict_flags.declaration) return;
        if (!self.declarationNodeIsExported(decl)) return;
        // `owner_name` is null for a default-exported anonymous class
        // (`export default class extends Private {}`). That case is still
        // diagnosable via the no-owner TS4021 form below; only the
        // owner-interpolating variants (TS4019/4020/4022) require a name.
        const stmts = self.enclosingModuleStatements(decl) orelse return;

        const HeritageEntry = struct { ref: NodeId, is_implements: bool };
        var entries: [16]HeritageEntry = undefined;
        var n: usize = 0;
        if (is_class) {
            const c = hir_mod.classOf(self.hir, decl);
            if (c.extends != hir_mod.none_node_id and n < entries.len) {
                entries[n] = .{ .ref = c.extends, .is_implements = false };
                n += 1;
            }
            for (self.hir.childSlice(c.implements_start, c.implements_len)) |impl| {
                if (n >= entries.len) break;
                entries[n] = .{ .ref = impl, .is_implements = true };
                n += 1;
            }
        } else {
            for (hir_mod.interfaceExtends(self.hir, decl)) |ext| {
                if (n >= entries.len) break;
                entries[n] = .{ .ref = ext, .is_implements = false };
                n += 1;
            }
        }

        for (entries[0..n]) |entry| {
            const root = self.heritageBareName(entry.ref) orelse continue;
            if (!self.nameIsModuleLocalPrivate(stmts, root)) continue;
            const private_str = self.string_interner.get(root);
            const alloc = self.diag_arena.allocator();
            // TS4021 — the only heritage diagnostic with no owner-name
            // slot: a default-exported anonymous class whose `extends`
            // clause names a private type. (`implements` on an anonymous
            // class still uses the owner-interpolating TS4019 upstream, so
            // it falls through to the named path and is skipped when the
            // owner is absent.)
            if (is_class and !entry.is_implements and owner_name == null) {
                const msg = try std.fmt.allocPrint(alloc, "'extends' clause of exported class has or is using private name '{s}'.", .{private_str});
                try self.report(entry.ref, TsCodes.extends_clause_class_private_name_no_owner, msg);
                continue;
            }
            const owner = owner_name orelse continue;
            const owner_str = self.string_interner.get(owner);
            const args = .{ owner_str, private_str };
            if (!is_class) {
                const msg = try std.fmt.allocPrint(alloc, "'extends' clause of exported interface '{s}' has or is using private name '{s}'.", args);
                try self.report(entry.ref, TsCodes.extends_clause_interface_private_name, msg);
            } else if (entry.is_implements) {
                const msg = try std.fmt.allocPrint(alloc, "Implements clause of exported class '{s}' has or is using private name '{s}'.", args);
                try self.report(entry.ref, TsCodes.implements_clause_private_name, msg);
            } else {
                const msg = try std.fmt.allocPrint(alloc, "'extends' clause of exported class '{s}' has or is using private name '{s}'.", args);
                try self.report(entry.ref, TsCodes.extends_clause_class_private_name, msg);
            }
        }
    }

    /// Extract the bare (unqualified) root name of a heritage type
    /// reference. Returns null for qualified names (`A.B`), expressions
    /// with type arguments only matter for the root, and non-name forms.
    fn heritageBareName(self: *Checker, ref: NodeId) ?hir_mod.StringId {
        return switch (self.hir.kindOf(ref)) {
            .identifier => hir_mod.identifierOf(self.hir, ref).name,
            .type_ref => blk: {
                const r = hir_mod.typeRefOf(self.hir, ref);
                if (r.qualifier_len != 0) break :blk null;
                break :blk r.name;
            },
            else => null,
        };
    }

    /// Bare (unqualified) root name of a type-annotation node, for the
    /// declaration-emit private-name family (TS4002/TS4016/TS4025/…).
    /// Restricted to the clearly-correct subset: a directly-named
    /// `type_ref` (or identifier) with no qualifier. A qualified `A.B`, a
    /// structural type, or any compound form returns `null` — those are
    /// intentionally left to the broader symbol-accessibility analysis
    /// rather than guessed at here. Mirrors `heritageBareName`.
    fn annotationBareName(self: *Checker, ann: NodeId) ?hir_mod.StringId {
        if (ann == hir_mod.none_node_id) return null;
        return self.heritageBareName(ann);
    }

    /// Bare (unqualified) identifier name of a parameter binding, or
    /// `null` for destructuring patterns / non-identifier names. Used to
    /// render the `{0}` parameter-name slot in the parameter-privacy
    /// diagnostics (TS4063/TS4070/TS4073/TS4078/…).
    fn parameterBareName(self: *Checker, param: NodeId) ?hir_mod.StringId {
        if (param == hir_mod.none_node_id or self.hir.kindOf(param) != .parameter) return null;
        const p = hir_mod.parameterOf(self.hir, param);
        if (p.name == hir_mod.none_node_id or self.hir.kindOf(p.name) != .identifier) return null;
        return hir_mod.identifierOf(self.hir, p.name).name;
    }

    /// TS4025 — declaration-emit symbol accessibility for an exported
    /// `var`/`let`/`const` whose explicit type annotation names a
    /// non-exported module-local type. When `--declaration` emit is on
    /// the annotated type appears in the generated `.d.ts`, so a private
    /// name there cannot be written. Anchored at the annotation.
    /// Restricted to the same-module bare-name subset, mirroring the
    /// heritage-clause path. Mirrors upstream `privacyVar.ts`.
    fn checkExportedVariablePrivateName(self: *Checker, node: NodeId) CheckError!void {
        if (!self.strict_flags.declaration) return;
        if (!self.declarationNodeIsExported(node)) return;
        const v = hir_mod.varDeclOf(self.hir, node);
        const stmts = self.enclosingModuleStatements(node) orelse return;
        try self.checkInferExtendsPrivateNamesInTypeNode(v.type_annotation, stmts);
        const root = self.annotationBareName(v.type_annotation) orelse return;
        const owner = self.declarationName(node) orelse return;
        const owner_str = self.string_interner.get(owner);
        const private_str = self.string_interner.get(root);
        if (self.nameIsModuleLocalPrivate(stmts, root)) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Exported variable '{s}' has or is using private name '{s}'.",
                .{ owner_str, private_str },
            );
            try self.report(v.type_annotation, TsCodes.exported_variable_private_name, msg);
        } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| switch (cross) {
            .private_module => |module_name| {
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Exported variable '{s}' has or is using name '{s}' from private module '{s}'.",
                    .{ owner_str, private_str, module_name },
                );
                try self.report(v.type_annotation, TsCodes.exported_variable_private_module, msg);
            },
            .cannot_be_named => |module_name| {
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Exported variable '{s}' has or is using name '{s}' from external module {s} but cannot be named.",
                    .{ owner_str, private_str, module_name },
                );
                try self.report(v.type_annotation, TsCodes.exported_variable_cannot_be_named, msg);
            },
        };
    }

    /// TS4082 — declaration-emit symbol accessibility for
    /// `export default <expr>`. The declaration transformer lowers a
    /// non-identifier default export expression into a synthetic
    /// `const _default: T; export default _default;`, so written type
    /// surfaces inside the expression must be nameable from the emitted
    /// `.d.ts`. Restricted to the same-module bare-name subset, matching
    /// the other TS4xxx privacy helpers above.
    fn checkDefaultExportExpressionPrivateName(self: *Checker, export_node: NodeId, ex: hir_mod.ExportPayload) CheckError!void {
        if (!self.strict_flags.declaration) return;
        if (!ex.is_default or ex.decl == hir_mod.none_node_id) return;

        switch (self.hir.kindOf(ex.decl)) {
            .identifier,
            .fn_decl,
            .fn_expr,
            .class_decl,
            .class_expr,
            .interface_decl,
            .enum_decl,
            .type_alias_decl,
            .var_decl,
            .let_decl,
            .const_decl,
            => return,
            else => {},
        }

        const stmts = self.enclosingModuleStatements(export_node) orelse return;
        const hit = self.defaultExportExpressionPrivateName(ex.decl, stmts) orelse return;
        const private_str = self.string_interner.get(hit.name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Default export of the module has or is using private name '{s}'.",
            .{private_str},
        );
        try self.report(hit.node, TsCodes.default_export_private_name, msg);
    }

    const DefaultExportPrivateNameHit = struct {
        node: NodeId,
        name: hir_mod.StringId,
    };

    fn defaultExportExpressionPrivateName(
        self: *Checker,
        expr: NodeId,
        stmts: []const NodeId,
    ) ?DefaultExportPrivateNameHit {
        if (expr == hir_mod.none_node_id) return null;
        switch (self.hir.kindOf(expr)) {
            .as_expr, .type_assertion, .satisfies_expr => {
                const a = hir_mod.asExpressionOf(self.hir, expr);
                if (self.annotationBareName(a.type_node)) |root| {
                    if (self.nameIsModuleLocalPrivate(stmts, root)) {
                        return .{ .node = a.type_node, .name = root };
                    }
                }
                return self.defaultExportExpressionPrivateName(a.expr, stmts);
            },
            .non_null_expr => {
                const a = hir_mod.asExpressionOf(self.hir, expr);
                return self.defaultExportExpressionPrivateName(a.expr, stmts);
            },
            .call_expr => {
                const call = hir_mod.callOf(self.hir, expr);
                if (call.callee == hir_mod.none_node_id or self.hir.kindOf(call.callee) != .identifier) return null;
                const callee_name = hir_mod.identifierOf(self.hir, call.callee).name;
                const fn_node = self.localFunctionDeclarationInStatements(stmts, callee_name) orelse return null;
                const f = hir_mod.fnDeclOf(self.hir, fn_node);
                const root = self.annotationBareName(f.return_type) orelse return null;
                if (!self.nameIsModuleLocalPrivate(stmts, root)) return null;
                return .{ .node = f.return_type, .name = root };
            },
            else => return null,
        }
    }

    /// TS4094 — `export const C = class { private x }` has an inferred
    /// anonymous class type whose private/protected members cannot be
    /// serialized in a `.d.ts`. This is intentionally limited to
    /// exported variables initialized by class expressions; exported
    /// class declarations and `export default class {}` have declaration
    /// forms that can carry those members.
    fn checkExportedAnonymousClassPrivateMembers(self: *Checker, node: NodeId) CheckError!void {
        if (!self.strict_flags.declaration) return;
        if (!self.declarationNodeIsExported(node)) return;
        const v = hir_mod.varDeclOf(self.hir, node);
        if (v.init == hir_mod.none_node_id) return;
        const init_kind = self.hir.kindOf(v.init);
        if (init_kind != .class_expr and init_kind != .class_decl) return;

        for (hir_mod.classMembers(self.hir, v.init)) |member| {
            const member_name = (try self.privateOrProtectedClassMemberName(member)) orelse continue;
            const member_str = self.string_interner.get(member_name);
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Property '{s}' of exported anonymous class type may not be private or protected.",
                .{member_str},
            );
            try self.report(self.classMemberNameAnchor(member), TsCodes.exported_anonymous_class_private_member, msg);
        }
    }

    /// TS2742/TS2883 — declaration emit cannot write a portable name for an
    /// inferred exported variable's type. This is the inferred-value
    /// sibling of the explicit-annotation privacy checks above: for
    /// `export const x = foo()` the declaration writer asks the imported
    /// `foo` signature for its return type, then rejects references that
    /// would require a module specifier containing another package's
    /// `node_modules` segment (for example `foo/node_modules/nested`).
    fn checkExportedVariableInferredPortableName(self: *Checker, node: NodeId) CheckError!void {
        if (!self.strict_flags.declaration) return;
        if (!self.declarationNodeIsExported(node)) return;
        const resolver = self.external_resolver orelse return;
        if (self.importer_path.len == 0) return;
        const v = hir_mod.varDeclOf(self.hir, node);
        if (v.type_annotation != hir_mod.none_node_id) return;
        if (v.init == hir_mod.none_node_id or self.hir.kindOf(v.init) != .call_expr) return;
        if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) return;
        const call = hir_mod.callOf(self.hir, v.init);
        if (call.callee == hir_mod.none_node_id or self.hir.kindOf(call.callee) != .identifier) return;
        const callee_name_id = hir_mod.identifierOf(self.hir, call.callee).name;
        const stmts = self.enclosingModuleStatements(node) orelse return;
        const imported = self.importedNamedBindingForLocal(stmts, callee_name_id) orelse return;
        const specifier = self.string_interner.get(imported.specifier);
        const exported_name = self.string_interner.get(imported.imported_name);
        const unsafe = resolver.inferredExportUnsafeReference(specifier, self.importer_path, exported_name) orelse return;
        const owner = hir_mod.identifierOf(self.hir, v.name).name;
        const owner_str = self.string_interner.get(owner);
        if (unsafe.symbol_name.len == 0) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "The inferred type of '{s}' cannot be named without a reference to '{s}'. This is likely not portable. A type annotation is necessary.",
                .{ owner_str, unsafe.module_specifier },
            );
            try self.report(v.name, TsCodes.inferred_type_non_portable_reference_no_symbol, msg);
            return;
        }
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "The inferred type of '{s}' cannot be named without a reference to '{s}' from '{s}'. This is likely not portable. A type annotation is necessary.",
            .{ owner_str, unsafe.symbol_name, unsafe.module_specifier },
        );
        try self.report(v.name, TsCodes.inferred_type_non_portable_reference, msg);
    }

    /// TS4118 — `export const x = make()` where `make` has an inline
    /// mapped return type over a late-bound `unique symbol` property
    /// (`{ [K in typeof sym]: T }`). The declaration writer sees an
    /// inferred object property named `[sym]` with no concrete property
    /// declaration to clone, so the type cannot be serialized. Explicit
    /// type aliases and explicit `[sym]` property signatures serialize
    /// cleanly upstream and are intentionally out of scope here.
    fn checkExportedVariableNonSerializableProperty(self: *Checker, node: NodeId) CheckError!void {
        if (!self.strict_flags.declaration) return;
        if (!self.declarationNodeIsExported(node)) return;
        const v = hir_mod.varDeclOf(self.hir, node);
        if (v.type_annotation != hir_mod.none_node_id) return;
        if (v.init == hir_mod.none_node_id or self.hir.kindOf(v.init) != .call_expr) return;
        const call = hir_mod.callOf(self.hir, v.init);
        if (call.callee == hir_mod.none_node_id or self.hir.kindOf(call.callee) != .identifier) return;
        const callee_name = hir_mod.identifierOf(self.hir, call.callee).name;
        const stmts = self.enclosingModuleStatements(node) orelse return;
        const fn_node = self.localFunctionDeclarationInStatements(stmts, callee_name) orelse return;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        const property_name = self.nonSerializableMappedReturnPropertyName(f.return_type) orelse return;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "The type of this node cannot be serialized because its property '[{s}]' cannot be serialized.",
            .{property_name},
        );
        const anchor = if (v.name != hir_mod.none_node_id) v.name else node;
        try self.report(anchor, TsCodes.nonserializable_property, msg);
    }

    fn localFunctionDeclarationInStatements(
        self: *Checker,
        stmts: []const NodeId,
        name: hir_mod.StringId,
    ) ?NodeId {
        for (stmts) |raw| {
            const decl = if (self.hir.kindOf(raw) == .export_decl) hir_mod.exportOf(self.hir, raw).decl else raw;
            if (decl == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(decl) != .fn_decl and self.hir.kindOf(decl) != .fn_expr) continue;
            const f = hir_mod.fnDeclOf(self.hir, decl);
            if (f.name == hir_mod.none_node_id or self.hir.kindOf(f.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, f.name).name == name) return decl;
        }
        return null;
    }

    fn nonSerializableMappedReturnPropertyName(self: *Checker, return_type: NodeId) ?[]const u8 {
        if (return_type == hir_mod.none_node_id or self.hir.kindOf(return_type) != .mapped_type) return null;
        const mapped = hir_mod.mappedTypeOf(self.hir, return_type);
        if (mapped.constraint == hir_mod.none_node_id or self.hir.kindOf(mapped.constraint) != .typeof_type) return null;
        const tt = hir_mod.typeofTypeOf(self.hir, mapped.constraint);
        if (tt.operand == hir_mod.none_node_id or self.hir.kindOf(tt.operand) != .identifier) return null;
        const name = hir_mod.identifierOf(self.hir, tt.operand).name;
        const name_str = self.string_interner.get(name);
        if (!self.sourceHasUniqueSymbolDeclaration(name_str)) return null;
        return name_str;
    }

    const ImportedNamedBinding = struct {
        specifier: hir_mod.StringId,
        imported_name: hir_mod.StringId,
    };

    fn importedNamedBindingForLocal(
        self: *Checker,
        stmts: []const NodeId,
        local_name: hir_mod.StringId,
    ) ?ImportedNamedBinding {
        for (stmts) |raw| {
            if (self.hir.kindOf(raw) != .import_decl) continue;
            const imp = hir_mod.importOf(self.hir, raw);
            for (hir_mod.importNamed(self.hir, raw)) |spec_node| {
                if (self.hir.kindOf(spec_node) != .import_specifier) continue;
                const spec = hir_mod.importSpecifierOf(self.hir, spec_node);
                if (spec.local != local_name) continue;
                return .{
                    .specifier = imp.module,
                    .imported_name = spec.imported,
                };
            }
        }
        return null;
    }

    /// TS4081 / TS4083 — declaration-emit symbol accessibility for an
    /// exported `type` alias. TS4083 fires when a type-parameter
    /// constraint / default names a non-exported module-local type;
    /// TS4081 fires when the aliased type itself is a bare reference to
    /// such a type. Both leak a private name into the generated `.d.ts`.
    /// Restricted to the same-module bare-name subset. Mirrors upstream
    /// `privacyTypeParameterOfTypeAlias` / `privacyTypeAlias`.
    fn checkExportedTypeAliasPrivateNames(self: *Checker, node: NodeId) CheckError!void {
        if (!self.strict_flags.declaration) return;
        if (!self.declarationNodeIsExported(node)) return;
        const stmts = self.enclosingModuleStatements(node) orelse return;
        const ta = hir_mod.typeAliasOf(self.hir, node);
        const owner = self.declarationName(node) orelse return;
        const owner_str = self.string_interner.get(owner);
        const alloc = self.diag_arena.allocator();

        for (self.hir.childSlice(ta.type_params_start, ta.type_params_len)) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            const tpp = hir_mod.typeParameterOf(self.hir, tp);
            inline for (.{ tpp.constraint, tpp.default }) |ann| {
                try self.checkInferExtendsPrivateNamesInTypeNode(ann, stmts);
                if (self.annotationBareName(ann)) |root| {
                    if (self.nameIsModuleLocalPrivate(stmts, root)) {
                        const tp_str = self.string_interner.get(tpp.name);
                        const private_str = self.string_interner.get(root);
                        const msg = try std.fmt.allocPrint(
                            alloc,
                            "Type parameter '{s}' of exported type alias has or is using private name '{s}'.",
                            .{ tp_str, private_str },
                        );
                        try self.report(ann, TsCodes.type_parameter_of_exported_type_alias_private_name, msg);
                    }
                }
            }
        }

        try self.checkInferExtendsPrivateNamesInTypeNode(ta.aliased, stmts);
        if (self.annotationBareName(ta.aliased)) |root| {
            const private_str = self.string_interner.get(root);
            if (self.nameIsModuleLocalPrivate(stmts, root)) {
                const msg = try std.fmt.allocPrint(
                    alloc,
                    "Exported type alias '{s}' has or is using private name '{s}'.",
                    .{ owner_str, private_str },
                );
                try self.report(ta.aliased, TsCodes.exported_type_alias_private_name, msg);
            } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| switch (cross) {
                // TS4084 — the aliased type comes from a private module.
                // The module render name carries its own quotes, so the
                // text is `… from module {s}.` (no extra quotes). Type
                // aliases use the no-name-check selector, so there is no
                // `cannot be named` variant.
                .private_module => |module_name| {
                    const msg = try std.fmt.allocPrint(
                        alloc,
                        "Exported type alias '{s}' has or is using private name '{s}' from module {s}.",
                        .{ owner_str, private_str, module_name },
                    );
                    try self.report(ta.aliased, TsCodes.exported_type_alias_private_module, msg);
                },
                .cannot_be_named => {},
            };
        }

        // TS4103 — `export type M = { [K in Priv]: V }` where the mapped
        // type's constraint (`Priv`) is a non-exported module-local name.
        // The bare-name body check above skips it because a mapped type
        // isn't a plain type reference. Mirrors tsc's
        // `getTypeParameterConstraintVisibilityDiagnosticMessage`
        // `KindMappedType` branch.
        if (self.hir.kindOf(ta.aliased) == .mapped_type) {
            const mt = hir_mod.mappedTypeOf(self.hir, ta.aliased);
            if (self.annotationBareName(mt.constraint)) |root| {
                if (self.nameIsModuleLocalPrivate(stmts, root)) {
                    const k_name = blk: {
                        if (mt.type_param != hir_mod.none_node_id and
                            self.hir.kindOf(mt.type_param) == .type_parameter)
                            break :blk self.string_interner.get(hir_mod.typeParameterOf(self.hir, mt.type_param).name);
                        break :blk "K";
                    };
                    const private_str = self.string_interner.get(root);
                    const msg = try std.fmt.allocPrint(
                        alloc,
                        "Type parameter '{s}' of exported mapped object type is using private name '{s}'.",
                        .{ k_name, private_str },
                    );
                    try self.report(mt.constraint, TsCodes.type_parameter_of_exported_mapped_object_type_private_name, msg);
                }
            }
        }
    }

    /// TS4002 / TS4016 / TS4083 — declaration-emit symbol accessibility
    /// for the type parameters of an exported class (`.class`), function
    /// (`.function`) or type alias (`.type_alias`). A type parameter
    /// whose `extends` constraint or default names a non-exported
    /// module-local type leaks that private name into the generated
    /// `.d.ts` signature. Anchored at the offending constraint / default
    /// reference. Restricted to the same-module bare-name subset.
    const ExportedTypeParamOwner = enum { class, interface, function };

    fn checkExportedTypeParamPrivateNames(
        self: *Checker,
        decl: NodeId,
        type_params: []const NodeId,
        owner: ExportedTypeParamOwner,
    ) CheckError!void {
        if (!self.strict_flags.declaration) return;
        if (type_params.len == 0) return;
        if (!self.declarationNodeIsExported(decl)) return;
        const stmts = self.enclosingModuleStatements(decl) orelse return;
        const code = switch (owner) {
            .class => TsCodes.type_parameter_of_exported_class_private_name,
            .interface => TsCodes.type_parameter_of_exported_interface_private_name,
            .function => TsCodes.type_parameter_of_exported_function_private_name,
        };
        const owner_kind = switch (owner) {
            .class => "class",
            .interface => "interface",
            .function => "function",
        };
        for (type_params) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            const tpp = hir_mod.typeParameterOf(self.hir, tp);
            inline for (.{ tpp.constraint, tpp.default }) |ann| {
                try self.checkInferExtendsPrivateNamesInTypeNode(ann, stmts);
                if (self.annotationBareName(ann)) |root| {
                    if (self.nameIsModuleLocalPrivate(stmts, root)) {
                        const tp_str = self.string_interner.get(tpp.name);
                        const private_str = self.string_interner.get(root);
                        const msg = try std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "Type parameter '{s}' of exported {s} has or is using private name '{s}'.",
                            .{ tp_str, owner_kind, private_str },
                        );
                        try self.report(ann, code, msg);
                    }
                }
            }
        }
    }

    /// TS4010 / TS4012 / TS4014 — a type-parameter constraint or default
    /// on a method of an exported class/interface that names a
    /// non-exported module-local type. Upstream notes type-parameter
    /// constraints are always user-written and therefore nameable, so
    /// only the private-name variant fires here (there is no
    /// "from module" / "cannot be named" cross-module form for these).
    /// `phrase` is the upstream owner phrase, e.g. "public static method
    /// from exported class". Mirrors
    /// `getTypeParameterConstraintVisibilityDiagnosticMessage`.
    fn checkMethodTypeParamPrivateNames(
        self: *Checker,
        type_params: []const NodeId,
        stmts: []const NodeId,
        code: u32,
        phrase: []const u8,
    ) CheckError!void {
        for (type_params) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            const tpp = hir_mod.typeParameterOf(self.hir, tp);
            inline for (.{ tpp.constraint, tpp.default }) |ann| {
                try self.checkInferExtendsPrivateNamesInTypeNode(ann, stmts);
                if (self.annotationBareName(ann)) |root| {
                    if (self.nameIsModuleLocalPrivate(stmts, root)) {
                        const tp_str = self.string_interner.get(tpp.name);
                        const private_str = self.string_interner.get(root);
                        const msg = try std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "Type parameter '{s}' of {s} has or is using private name '{s}'.",
                            .{ tp_str, phrase, private_str },
                        );
                        try self.report(ann, code, msg);
                    }
                }
            }
        }
    }

    /// TS4085 — an `infer U extends Private` clause inside an exported
    /// declaration's written type surface references a non-exported
    /// module-local type. Mirrors the declaration transform's
    /// `InferType` branch of `getTypeParameterConstraintVisibility...`.
    fn checkInferExtendsPrivateNamesInTypeNode(self: *Checker, node: NodeId, stmts: []const NodeId) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .infer_type => {
                const ip = hir_mod.inferTypeOf(self.hir, node);
                if (self.annotationBareName(ip.constraint)) |root| {
                    if (self.nameIsModuleLocalPrivate(stmts, root)) {
                        const infer_str = self.string_interner.get(ip.name);
                        const private_str = self.string_interner.get(root);
                        const msg = try std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "Extends clause for inferred type '{s}' has or is using private name '{s}'.",
                            .{ infer_str, private_str },
                        );
                        try self.report(ip.constraint, TsCodes.infer_extends_clause_private_name, msg);
                    }
                }
                try self.checkInferExtendsPrivateNamesInTypeNode(ip.constraint, stmts);
            },
            .type_ref => for (hir_mod.typeRefArgs(self.hir, node)) |arg| {
                try self.checkInferExtendsPrivateNamesInTypeNode(arg, stmts);
            },
            .array_type => try self.checkInferExtendsPrivateNamesInTypeNode(hir_mod.arrayTypeOf(self.hir, node).element, stmts),
            .readonly_type => try self.checkInferExtendsPrivateNamesInTypeNode(hir_mod.readonlyTypeOf(self.hir, node).operand, stmts),
            .optional_type => try self.checkInferExtendsPrivateNamesInTypeNode(hir_mod.optionalTypeOf(self.hir, node).operand, stmts),
            .union_type => for (hir_mod.unionTypeMembers(self.hir, node)) |member| {
                try self.checkInferExtendsPrivateNamesInTypeNode(member, stmts);
            },
            .intersection_type => for (hir_mod.intersectionTypeMembers(self.hir, node)) |member| {
                try self.checkInferExtendsPrivateNamesInTypeNode(member, stmts);
            },
            .tuple_type => for (hir_mod.tupleTypeElements(self.hir, node)) |elem| {
                try self.checkInferExtendsPrivateNamesInTypeNode(elem, stmts);
            },
            .rest_type => try self.checkInferExtendsPrivateNamesInTypeNode(hir_mod.restTypeOf(self.hir, node).operand, stmts),
            .keyof_type => try self.checkInferExtendsPrivateNamesInTypeNode(hir_mod.keyofTypeOf(self.hir, node).operand, stmts),
            .indexed_access_type => {
                const idx = hir_mod.indexedAccessTypeOf(self.hir, node);
                try self.checkInferExtendsPrivateNamesInTypeNode(idx.object, stmts);
                try self.checkInferExtendsPrivateNamesInTypeNode(idx.index, stmts);
            },
            .fn_type, .constructor_type => {
                const fn_t = hir_mod.fnTypeOf(self.hir, node);
                for (self.hir.childSlice(fn_t.type_params_start, fn_t.type_params_len)) |tp| {
                    try self.checkInferExtendsPrivateNamesInTypeNode(tp, stmts);
                }
                for (self.hir.childSlice(fn_t.params_start, fn_t.params_len)) |param| {
                    if (self.hir.kindOf(param) != .parameter) continue;
                    try self.checkInferExtendsPrivateNamesInTypeNode(hir_mod.parameterOf(self.hir, param).type_annotation, stmts);
                }
                try self.checkInferExtendsPrivateNamesInTypeNode(fn_t.return_type, stmts);
            },
            .object_type => for (hir_mod.objectTypeMembers(self.hir, node)) |member| {
                switch (self.hir.kindOf(member)) {
                    .object_property => try self.checkInferExtendsPrivateNamesInTypeNode(hir_mod.objectPropertyOf(self.hir, member).type_annotation, stmts),
                    .index_signature => {
                        const sig = hir_mod.indexSignatureOf(self.hir, member);
                        try self.checkInferExtendsPrivateNamesInTypeNode(sig.key_type, stmts);
                        try self.checkInferExtendsPrivateNamesInTypeNode(sig.value_type, stmts);
                    },
                    else => {},
                }
            },
            .conditional_type => {
                const c = hir_mod.conditionalTypeOf(self.hir, node);
                try self.checkInferExtendsPrivateNamesInTypeNode(c.check, stmts);
                try self.checkInferExtendsPrivateNamesInTypeNode(c.extends, stmts);
                try self.checkInferExtendsPrivateNamesInTypeNode(c.true_branch, stmts);
                try self.checkInferExtendsPrivateNamesInTypeNode(c.false_branch, stmts);
            },
            .type_predicate_type => try self.checkInferExtendsPrivateNamesInTypeNode(hir_mod.typePredicateOf(self.hir, node).target_type, stmts),
            .template_literal_type => for (hir_mod.templateLiteralTypeTypes(self.hir, node)) |part| {
                try self.checkInferExtendsPrivateNamesInTypeNode(part, stmts);
            },
            .mapped_type => {
                const m = hir_mod.mappedTypeOf(self.hir, node);
                try self.checkInferExtendsPrivateNamesInTypeNode(m.constraint, stmts);
                try self.checkInferExtendsPrivateNamesInTypeNode(m.value, stmts);
                try self.checkInferExtendsPrivateNamesInTypeNode(m.remap, stmts);
            },
            .type_parameter => {
                const tp = hir_mod.typeParameterOf(self.hir, node);
                try self.checkInferExtendsPrivateNamesInTypeNode(tp.constraint, stmts);
                try self.checkInferExtendsPrivateNamesInTypeNode(tp.default, stmts);
            },
            else => {},
        }
    }

    /// TS4060 / TS4078 — declaration-emit symbol accessibility for an
    /// exported function's signature. TS4060 fires when the explicit
    /// return-type annotation is a bare reference to a non-exported
    /// module-local type; TS4078 fires for each parameter whose
    /// annotation is. Both leak a private name into the generated
    /// `.d.ts`. Restricted to the same-module bare-name subset. Mirrors
    /// upstream `privacyFunctionReturnTypeDeclFile` /
    /// `privacyFunctionParameterDeclFile`.
    fn checkExportedFunctionPrivateNames(self: *Checker, node: NodeId) CheckError!void {
        if (!self.strict_flags.declaration) return;
        if (!self.declarationNodeIsExported(node)) return;
        const stmts = self.enclosingModuleStatements(node) orelse return;
        const f = hir_mod.fnDeclOf(self.hir, node);
        const alloc = self.diag_arena.allocator();

        try self.checkInferExtendsPrivateNamesInTypeNode(f.return_type, stmts);
        if (self.annotationBareName(f.return_type)) |root| {
            const private_str = self.string_interner.get(root);
            if (self.nameIsModuleLocalPrivate(stmts, root)) {
                const msg = try std.fmt.allocPrint(
                    alloc,
                    "Return type of exported function has or is using private name '{s}'.",
                    .{private_str},
                );
                try self.report(f.return_type, TsCodes.exported_function_return_private_name, msg);
            } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| switch (cross) {
                .private_module => |module_name| {
                    const msg = try std.fmt.allocPrint(
                        alloc,
                        "Return type of exported function has or is using name '{s}' from private module '{s}'.",
                        .{ private_str, module_name },
                    );
                    try self.report(f.return_type, TsCodes.exported_function_return_private_module, msg);
                },
                .cannot_be_named => |module_name| {
                    const msg = try std.fmt.allocPrint(
                        alloc,
                        "Return type of exported function has or is using name '{s}' from external module {s} but cannot be named.",
                        .{ private_str, module_name },
                    );
                    try self.report(f.return_type, TsCodes.exported_function_return_cannot_be_named, msg);
                },
            };
        }

        for (hir_mod.fnParams(self.hir, node)) |param| {
            if (self.hir.kindOf(param) != .parameter) continue;
            const p = hir_mod.parameterOf(self.hir, param);
            try self.checkInferExtendsPrivateNamesInTypeNode(p.type_annotation, stmts);
            const root = self.annotationBareName(p.type_annotation) orelse continue;
            const param_name = self.parameterBareName(param) orelse continue;
            const param_str = self.string_interner.get(param_name);
            const private_str = self.string_interner.get(root);
            if (self.nameIsModuleLocalPrivate(stmts, root)) {
                const msg = try std.fmt.allocPrint(
                    alloc,
                    "Parameter '{s}' of exported function has or is using private name '{s}'.",
                    .{ param_str, private_str },
                );
                try self.report(p.type_annotation, TsCodes.exported_function_param_private_name, msg);
            } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| switch (cross) {
                .private_module => |module_name| {
                    const msg = try std.fmt.allocPrint(
                        alloc,
                        "Parameter '{s}' of exported function has or is using name '{s}' from private module '{s}'.",
                        .{ param_str, private_str, module_name },
                    );
                    try self.report(p.type_annotation, TsCodes.exported_function_param_private_module, msg);
                },
                .cannot_be_named => |module_name| {
                    const msg = try std.fmt.allocPrint(
                        alloc,
                        "Parameter '{s}' of exported function has or is using name '{s}' from external module {s} but cannot be named.",
                        .{ param_str, private_str, module_name },
                    );
                    try self.report(p.type_annotation, TsCodes.exported_function_param_cannot_be_named, msg);
                },
            };
        }
    }

    /// TS4031 / TS4028 — declaration-emit symbol accessibility for the
    /// public data fields of an exported class. A public instance field
    /// whose annotation names a non-exported module-local type emits
    /// TS4031; a public *static* field emits TS4028. Both appear verbatim
    /// in the generated `.d.ts`, so a private name there cannot be
    /// written. `private`/`protected` members are exempt — tsc elides
    /// their types from the `.d.ts`. Computed/private-name keys are
    /// skipped; restricted to the same-module bare-name subset. Mirrors
    /// upstream `privacyClass.ts`.
    ///
    /// Method/accessor members of the same exported class delegate to
    /// `checkExportedClassMethodPrivateNames` (TS4040/4043/4052/4055/
    /// 4070/4073/4035/4037/4063).
    fn checkExportedClassMemberPrivateNames(self: *Checker, node: NodeId) CheckError!void {
        if (!self.strict_flags.declaration) return;
        if (!self.declarationNodeIsExported(node)) return;
        const stmts = self.enclosingModuleStatements(node) orelse return;
        const alloc = self.diag_arena.allocator();
        for (hir_mod.classMembers(self.hir, node)) |member| {
            switch (self.hir.kindOf(member)) {
                .object_property => {
                    const op = hir_mod.objectPropertyOf(self.hir, member);
                    if (op.is_method) {
                        if (op.visibility == .public and
                            (op.is_computed or self.nodeIsBracketedComputedName(op.key) or self.memberSourceLooksComputed(member)) and
                            self.hir.kindOf(op.key) == .identifier)
                        {
                            const root = hir_mod.identifierOf(self.hir, op.key).name;
                            const method_name = (try self.classMemberNameFromPropertyKey(op.key, true)) orelse root;
                            const method_str = self.string_interner.get(method_name);
                            const private_str = self.string_interner.get(root);
                            if (self.nameIsModuleLocalPrivate(stmts, root)) {
                                const code = if (op.is_static)
                                    TsCodes.public_static_method_name_private_name
                                else
                                    TsCodes.public_method_name_private_name;
                                const msg = if (op.is_static)
                                    try std.fmt.allocPrint(
                                        alloc,
                                        "Public static method '{s}' of exported class has or is using private name '{s}'.",
                                        .{ method_str, private_str },
                                    )
                                else
                                    try std.fmt.allocPrint(
                                        alloc,
                                        "Public method '{s}' of exported class has or is using private name '{s}'.",
                                        .{ method_str, private_str },
                                    );
                                try self.report(op.key, code, msg);
                            } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| {
                                switch (cross) {
                                    .private_module => |module_name| {
                                        const code = if (op.is_static)
                                            TsCodes.public_static_method_name_private_module
                                        else
                                            TsCodes.public_method_name_private_module;
                                        const msg = if (op.is_static)
                                            try std.fmt.allocPrint(
                                                alloc,
                                                "Public static method '{s}' of exported class has or is using name '{s}' from private module '{s}'.",
                                                .{ method_str, private_str, module_name },
                                            )
                                        else
                                            try std.fmt.allocPrint(
                                                alloc,
                                                "Public method '{s}' of exported class has or is using name '{s}' from private module '{s}'.",
                                                .{ method_str, private_str, module_name },
                                            );
                                        try self.report(op.key, code, msg);
                                    },
                                    .cannot_be_named => |module_name| {
                                        const code = if (op.is_static)
                                            TsCodes.public_static_method_name_cannot_be_named
                                        else
                                            TsCodes.public_method_name_cannot_be_named;
                                        const msg = if (op.is_static)
                                            try std.fmt.allocPrint(
                                                alloc,
                                                "Public static method '{s}' of exported class has or is using name '{s}' from external module {s} but cannot be named.",
                                                .{ method_str, private_str, module_name },
                                            )
                                        else
                                            try std.fmt.allocPrint(
                                                alloc,
                                                "Public method '{s}' of exported class has or is using name '{s}' from external module {s} but cannot be named.",
                                                .{ method_str, private_str, module_name },
                                            );
                                        try self.report(op.key, code, msg);
                                    },
                                }
                            }
                        }
                        if (op.value != hir_mod.none_node_id) try self.checkExportedClassMethodPrivateNames(op.value, stmts);
                        continue;
                    }
                    if (op.visibility != .public) continue;
                    try self.checkInferExtendsPrivateNamesInTypeNode(op.type_annotation, stmts);
                    const root = self.annotationBareName(op.type_annotation) orelse continue;
                    const is_local = self.nameIsModuleLocalPrivate(stmts, root);
                    const cross_module: ?CrossModulePrivacy = if (is_local) null else self.crossModulePrivateNameInfo(stmts, root);
                    if (!is_local and cross_module == null) continue;
                    const member_name = (try self.classMemberNameFromPropertyKey(op.key, op.is_computed)) orelse continue;
                    if (self.classMemberNameIsPrivateName(member_name)) continue;
                    const member_str = self.string_interner.get(member_name);
                    const private_str = self.string_interner.get(root);
                    if (is_local) {
                        if (op.is_static) {
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Public static property '{s}' of exported class has or is using private name '{s}'.",
                                .{ member_str, private_str },
                            );
                            try self.report(op.type_annotation, TsCodes.public_static_property_private_name, msg);
                        } else {
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Public property '{s}' of exported class has or is using private name '{s}'.",
                                .{ member_str, private_str },
                            );
                            try self.report(op.type_annotation, TsCodes.public_property_private_name, msg);
                        }
                    } else if (cross_module) |cross| switch (cross) {
                        .private_module => |module_name| {
                            if (op.is_static) {
                                const msg = try std.fmt.allocPrint(
                                    alloc,
                                    "Public static property '{s}' of exported class has or is using name '{s}' from private module '{s}'.",
                                    .{ member_str, private_str, module_name },
                                );
                                try self.report(op.type_annotation, TsCodes.public_static_property_private_module, msg);
                            } else {
                                const msg = try std.fmt.allocPrint(
                                    alloc,
                                    "Public property '{s}' of exported class has or is using name '{s}' from private module '{s}'.",
                                    .{ member_str, private_str, module_name },
                                );
                                try self.report(op.type_annotation, TsCodes.public_property_private_module, msg);
                            }
                        },
                        .cannot_be_named => |module_name| {
                            if (op.is_static) {
                                const msg = try std.fmt.allocPrint(
                                    alloc,
                                    "Public static property '{s}' of exported class has or is using name '{s}' from external module {s} but cannot be named.",
                                    .{ member_str, private_str, module_name },
                                );
                                try self.report(op.type_annotation, TsCodes.public_static_property_cannot_be_named, msg);
                            } else {
                                const msg = try std.fmt.allocPrint(
                                    alloc,
                                    "Public property '{s}' of exported class has or is using name '{s}' from external module {s} but cannot be named.",
                                    .{ member_str, private_str, module_name },
                                );
                                try self.report(op.type_annotation, TsCodes.public_property_cannot_be_named, msg);
                            }
                        },
                    };
                },
                .fn_decl, .fn_expr, .arrow_fn => try self.checkExportedClassMethodPrivateNames(member, stmts),
                else => {},
            }
        }
    }

    /// TS4040/4043/4052/4055/4070/4073/4063/4106/4107/4108 —
    /// declaration-emit symbol accessibility for a method / accessor /
    /// constructor member of an exported class. A return-type or
    /// parameter annotation that is a bare reference to a non-exported
    /// module-local type leaks a private name into the generated
    /// `.d.ts`. `private`/`protected` members are exempt (their bodies
    /// are elided). The diagnostic code depends on the member kind
    /// (getter / setter / method / constructor) and static-ness.
    /// Restricted to the same-module bare-name subset.
    fn checkExportedClassMethodPrivateNames(self: *Checker, member: NodeId, stmts: []const NodeId) CheckError!void {
        const f = hir_mod.fnDeclOf(self.hir, member);
        if (f.flags.is_private or f.flags.is_protected) return;
        const alloc = self.diag_arena.allocator();
        const is_static = f.flags.is_static;

        const member_name: ?hir_mod.StringId = if (f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier)
            hir_mod.identifierOf(self.hir, f.name).name
        else
            null;
        if (member_name) |mn| {
            if (self.classMemberNameIsPrivateName(mn)) return;
        }

        // Computed public method names participate in declaration-emit
        // symbol accessibility independently from their return/parameter
        // types. Mirror upstream's node-name diagnostic selector for the
        // cross-module subset Home can establish through the existing
        // resolver-backed privacy query.
        if (!f.flags.is_constructor and !f.flags.is_getter and !f.flags.is_setter and
            f.name != hir_mod.none_node_id and
            (self.nodeIsBracketedComputedName(f.name) or self.nodeIsBracketedComputedName(member) or self.memberSourceLooksComputed(member)) and
            self.hir.kindOf(f.name) == .identifier)
        {
            const root = hir_mod.identifierOf(self.hir, f.name).name;
            const method_str = if (member_name) |mn| self.string_interner.get(mn) else self.string_interner.get(root);
            const private_str = self.string_interner.get(root);
            if (self.nameIsModuleLocalPrivate(stmts, root)) {
                const code = if (is_static)
                    TsCodes.public_static_method_name_private_name
                else
                    TsCodes.public_method_name_private_name;
                const msg = if (is_static)
                    try std.fmt.allocPrint(
                        alloc,
                        "Public static method '{s}' of exported class has or is using private name '{s}'.",
                        .{ method_str, private_str },
                    )
                else
                    try std.fmt.allocPrint(
                        alloc,
                        "Public method '{s}' of exported class has or is using private name '{s}'.",
                        .{ method_str, private_str },
                    );
                try self.report(f.name, code, msg);
            } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| {
                switch (cross) {
                    .private_module => |module_name| {
                        const code = if (is_static)
                            TsCodes.public_static_method_name_private_module
                        else
                            TsCodes.public_method_name_private_module;
                        const msg = if (is_static)
                            try std.fmt.allocPrint(
                                alloc,
                                "Public static method '{s}' of exported class has or is using name '{s}' from private module '{s}'.",
                                .{ method_str, private_str, module_name },
                            )
                        else
                            try std.fmt.allocPrint(
                                alloc,
                                "Public method '{s}' of exported class has or is using name '{s}' from private module '{s}'.",
                                .{ method_str, private_str, module_name },
                            );
                        try self.report(f.name, code, msg);
                    },
                    .cannot_be_named => |module_name| {
                        const code = if (is_static)
                            TsCodes.public_static_method_name_cannot_be_named
                        else
                            TsCodes.public_method_name_cannot_be_named;
                        const msg = if (is_static)
                            try std.fmt.allocPrint(
                                alloc,
                                "Public static method '{s}' of exported class has or is using name '{s}' from external module {s} but cannot be named.",
                                .{ method_str, private_str, module_name },
                            )
                        else
                            try std.fmt.allocPrint(
                                alloc,
                                "Public method '{s}' of exported class has or is using name '{s}' from external module {s} but cannot be named.",
                                .{ method_str, private_str, module_name },
                            );
                        try self.report(f.name, code, msg);
                    },
                }
            }
        }

        // TS4010 / TS4012 — type-parameter constraints/defaults on a
        // public method that name a private module-local type. (No type
        // params on constructors/getters/setters, so this is a no-op for
        // them.)
        {
            const tps = hir_mod.fnTypeParams(self.hir, member);
            if (tps.len > 0) {
                const tp_code = if (is_static)
                    TsCodes.type_parameter_of_public_static_method_private_name
                else
                    TsCodes.type_parameter_of_public_method_private_name;
                const phrase = if (is_static)
                    "public static method from exported class"
                else
                    "public method from exported class";
                try self.checkMethodTypeParamPrivateNames(tps, stmts, tp_code, phrase);
            }
        }

        // Return type — getters and plain methods carry one in the
        // emitted `.d.ts`. Constructors and setters have no return type.
        if (!f.flags.is_constructor and !f.flags.is_setter) {
            try self.checkInferExtendsPrivateNamesInTypeNode(f.return_type, stmts);
            if (self.annotationBareName(f.return_type)) |root| {
                const private_str = self.string_interner.get(root);
                const is_local = self.nameIsModuleLocalPrivate(stmts, root);
                const cross_module: ?CrossModulePrivacy = if (is_local) null else self.crossModulePrivateNameInfo(stmts, root);
                if (f.flags.is_getter) {
                    const name_str = if (member_name) |mn| self.string_interner.get(mn) else "";
                    const kind = if (is_static) "static " else "";
                    if (is_local) {
                        const code = if (is_static)
                            TsCodes.public_static_getter_return_private_name
                        else
                            TsCodes.public_getter_return_private_name;
                        const msg = try std.fmt.allocPrint(
                            alloc,
                            "Return type of public {s}getter '{s}' from exported class has or is using private name '{s}'.",
                            .{ kind, name_str, private_str },
                        );
                        try self.report(f.return_type, code, msg);
                    } else if (cross_module) |cross| switch (cross) {
                        .private_module => |module_name| {
                            const code = if (is_static)
                                TsCodes.public_static_getter_return_private_module
                            else
                                TsCodes.public_getter_return_private_module;
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Return type of public {s}getter '{s}' from exported class has or is using name '{s}' from private module '{s}'.",
                                .{ kind, name_str, private_str, module_name },
                            );
                            try self.report(f.return_type, code, msg);
                        },
                        .cannot_be_named => |module_name| {
                            const code = if (is_static)
                                TsCodes.public_static_getter_return_cannot_be_named
                            else
                                TsCodes.public_getter_return_cannot_be_named;
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Return type of public {s}getter '{s}' from exported class has or is using name '{s}' from external module {s} but cannot be named.",
                                .{ kind, name_str, private_str, module_name },
                            );
                            try self.report(f.return_type, code, msg);
                        },
                    };
                } else {
                    const kind = if (is_static) "static " else "";
                    if (is_local) {
                        const code = if (is_static)
                            TsCodes.public_static_method_return_private_name
                        else
                            TsCodes.public_method_return_private_name;
                        const msg = try std.fmt.allocPrint(
                            alloc,
                            "Return type of public {s}method from exported class has or is using private name '{s}'.",
                            .{ kind, private_str },
                        );
                        try self.report(f.return_type, code, msg);
                    } else if (cross_module) |cross| switch (cross) {
                        .private_module => |module_name| {
                            const code = if (is_static)
                                TsCodes.public_static_method_return_private_module
                            else
                                TsCodes.public_method_return_private_module;
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Return type of public {s}method from exported class has or is using name '{s}' from private module '{s}'.",
                                .{ kind, private_str, module_name },
                            );
                            try self.report(f.return_type, code, msg);
                        },
                        .cannot_be_named => |module_name| {
                            const code = if (is_static)
                                TsCodes.public_static_method_return_cannot_be_named
                            else
                                TsCodes.public_method_return_cannot_be_named;
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Return type of public {s}method from exported class has or is using name '{s}' from external module {s} but cannot be named.",
                                .{ kind, private_str, module_name },
                            );
                            try self.report(f.return_type, code, msg);
                        },
                    };
                }
            }
        }

        for (hir_mod.fnParams(self.hir, member)) |param| {
            if (self.hir.kindOf(param) != .parameter) continue;
            const p = hir_mod.parameterOf(self.hir, param);
            try self.checkInferExtendsPrivateNamesInTypeNode(p.type_annotation, stmts);
            const root = self.annotationBareName(p.type_annotation) orelse continue;
            const private_str = self.string_interner.get(root);
            const is_local = self.nameIsModuleLocalPrivate(stmts, root);
            const cross_module: ?CrossModulePrivacy = if (is_local) null else self.crossModulePrivateNameInfo(stmts, root);
            if (!is_local and cross_module == null) continue;
            if (f.flags.is_setter) {
                const param_name = self.parameterBareName(param) orelse continue;
                const param_str = self.string_interner.get(param_name);
                const name_str = if (member_name) |mn| self.string_interner.get(mn) else "";
                const kind = if (is_static) "static " else "";
                if (is_local) {
                    const setter_code = if (is_static)
                        TsCodes.public_static_setter_param_private_name
                    else
                        TsCodes.public_setter_param_private_name;
                    const setter_msg = try std.fmt.allocPrint(
                        alloc,
                        "Parameter type of public {s}setter '{s}' from exported class has or is using private name '{s}'.",
                        .{ kind, name_str, private_str },
                    );
                    try self.report(p.type_annotation, setter_code, setter_msg);

                    const msg = try std.fmt.allocPrint(
                        alloc,
                        "Parameter '{s}' of accessor has or is using private name '{s}'.",
                        .{ param_str, private_str },
                    );
                    try self.report(p.type_annotation, TsCodes.accessor_param_private_name, msg);
                } else if (cross_module) |cross| switch (cross) {
                    .private_module => |module_name| {
                        const setter_code = if (is_static)
                            TsCodes.public_static_setter_param_private_module
                        else
                            TsCodes.public_setter_param_private_module;
                        const setter_msg = try std.fmt.allocPrint(
                            alloc,
                            "Parameter type of public {s}setter '{s}' from exported class has or is using name '{s}' from private module '{s}'.",
                            .{ kind, name_str, private_str, module_name },
                        );
                        try self.report(p.type_annotation, setter_code, setter_msg);

                        const msg = try std.fmt.allocPrint(
                            alloc,
                            "Parameter '{s}' of accessor has or is using name '{s}' from private module '{s}'.",
                            .{ param_str, private_str, module_name },
                        );
                        try self.report(p.type_annotation, TsCodes.accessor_param_private_module, msg);
                    },
                    .cannot_be_named => |module_name| {
                        const setter_code = if (is_static)
                            TsCodes.public_static_setter_param_private_module
                        else
                            TsCodes.public_setter_param_private_module;
                        const setter_msg = try std.fmt.allocPrint(
                            alloc,
                            "Parameter type of public {s}setter '{s}' from exported class has or is using name '{s}' from private module '{s}'.",
                            .{ kind, name_str, private_str, module_name },
                        );
                        try self.report(p.type_annotation, setter_code, setter_msg);

                        const msg = try std.fmt.allocPrint(
                            alloc,
                            "Parameter '{s}' of accessor has or is using name '{s}' from external module {s} but cannot be named.",
                            .{ param_str, private_str, module_name },
                        );
                        try self.report(p.type_annotation, TsCodes.accessor_param_cannot_be_named, msg);
                    },
                };
            } else {
                const param_name = self.parameterBareName(param) orelse continue;
                const param_str = self.string_interner.get(param_name);
                if (f.flags.is_constructor) {
                    if (is_local) {
                        const msg = try std.fmt.allocPrint(
                            alloc,
                            "Parameter '{s}' of constructor from exported class has or is using private name '{s}'.",
                            .{ param_str, private_str },
                        );
                        try self.report(p.type_annotation, TsCodes.constructor_param_private_name, msg);
                    } else if (cross_module) |cross| switch (cross) {
                        .private_module => |module_name| {
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Parameter '{s}' of constructor from exported class has or is using name '{s}' from private module '{s}'.",
                                .{ param_str, private_str, module_name },
                            );
                            try self.report(p.type_annotation, TsCodes.constructor_param_private_module, msg);
                        },
                        .cannot_be_named => |module_name| {
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Parameter '{s}' of constructor from exported class has or is using name '{s}' from external module {s} but cannot be named.",
                                .{ param_str, private_str, module_name },
                            );
                            try self.report(p.type_annotation, TsCodes.constructor_param_cannot_be_named, msg);
                        },
                    };
                } else {
                    const kind = if (is_static) "static " else "";
                    if (is_local) {
                        const code = if (is_static)
                            TsCodes.public_static_method_param_private_name
                        else
                            TsCodes.public_method_param_private_name;
                        const msg = try std.fmt.allocPrint(
                            alloc,
                            "Parameter '{s}' of public {s}method from exported class has or is using private name '{s}'.",
                            .{ param_str, kind, private_str },
                        );
                        try self.report(p.type_annotation, code, msg);
                    } else if (cross_module) |cross| switch (cross) {
                        .private_module => |module_name| {
                            const code = if (is_static)
                                TsCodes.public_static_method_param_private_module
                            else
                                TsCodes.public_method_param_private_module;
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Parameter '{s}' of public {s}method from exported class has or is using name '{s}' from private module '{s}'.",
                                .{ param_str, kind, private_str, module_name },
                            );
                            try self.report(p.type_annotation, code, msg);
                        },
                        .cannot_be_named => |module_name| {
                            const code = if (is_static)
                                TsCodes.public_static_method_param_cannot_be_named
                            else
                                TsCodes.public_method_param_cannot_be_named;
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Parameter '{s}' of public {s}method from exported class has or is using name '{s}' from external module {s} but cannot be named.",
                                .{ param_str, kind, private_str, module_name },
                            );
                            try self.report(p.type_annotation, code, msg);
                        },
                    };
                }
            }
        }
    }

    /// TS4033 / TS4057 / TS4075 / TS4101 — declaration-emit symbol
    /// accessibility for the members of an exported interface. A
    /// property/method signature whose annotation, return type, or a
    /// parameter type is a bare reference to a non-exported module-local
    /// type leaks a private name into the generated `.d.ts`. Restricted
    /// to the same-module bare-name subset. Mirrors upstream
    /// `privacyInterface.ts`.
    fn checkExportedInterfaceMemberPrivateNames(self: *Checker, node: NodeId) CheckError!void {
        if (!self.strict_flags.declaration) return;
        if (!self.declarationNodeIsExported(node)) return;
        const stmts = self.enclosingModuleStatements(node) orelse return;
        const alloc = self.diag_arena.allocator();
        for (hir_mod.interfaceMembers(self.hir, node)) |member| {
            // TS4048/4049 (value/return type) + TS4091/4092 (key
            // parameter type) — an index signature `[k: K]: V` of an
            // exported interface whose `V` or `K` names a private type.
            if (self.hir.kindOf(member) == .index_signature) {
                const ix = hir_mod.indexSignatureOf(self.hir, member);
                try self.checkInferExtendsPrivateNamesInTypeNode(ix.value_type, stmts);
                if (self.annotationBareName(ix.value_type)) |root| {
                    const private_str = self.string_interner.get(root);
                    if (self.nameIsModuleLocalPrivate(stmts, root)) {
                        const msg = try std.fmt.allocPrint(alloc, "Return type of index signature from exported interface has or is using private name '{s}'.", .{private_str});
                        try self.report(ix.value_type, TsCodes.index_signature_return_private_name, msg);
                    } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| switch (cross) {
                        .private_module => |module_name| {
                            const msg = try std.fmt.allocPrint(alloc, "Return type of index signature from exported interface has or is using name '{s}' from private module '{s}'.", .{ private_str, module_name });
                            try self.report(ix.value_type, TsCodes.index_signature_return_private_module, msg);
                        },
                        .cannot_be_named => {},
                    };
                }
                try self.checkInferExtendsPrivateNamesInTypeNode(ix.key_type, stmts);
                if (self.annotationBareName(ix.key_type)) |root| {
                    const private_str = self.string_interner.get(root);
                    const param_str = if (ix.key_name != 0) self.string_interner.get(ix.key_name) else "x";
                    if (self.nameIsModuleLocalPrivate(stmts, root)) {
                        const msg = try std.fmt.allocPrint(alloc, "Parameter '{s}' of index signature from exported interface has or is using private name '{s}'.", .{ param_str, private_str });
                        try self.report(ix.key_type, TsCodes.index_signature_param_private_name, msg);
                    } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| switch (cross) {
                        .private_module => |module_name| {
                            const msg = try std.fmt.allocPrint(alloc, "Parameter '{s}' of index signature from exported interface has or is using name '{s}' from private module '{s}'.", .{ param_str, private_str, module_name });
                            try self.report(ix.key_type, TsCodes.index_signature_param_private_module, msg);
                        },
                        .cannot_be_named => {},
                    };
                }
                continue;
            }
            if (self.hir.kindOf(member) != .interface_member) continue;
            const im = hir_mod.interfaceMemberOf(self.hir, member);
            if (im.is_method) {
                const key_expr = hir_mod.interfaceMemberKeyExpr(self.hir, member);
                if (key_expr != hir_mod.none_node_id and self.hir.kindOf(key_expr) == .identifier) {
                    const root = hir_mod.identifierOf(self.hir, key_expr).name;
                    const method_str = self.string_interner.get(if (im.name != 0) im.name else root);
                    const private_str = self.string_interner.get(root);
                    if (self.nameIsModuleLocalPrivate(stmts, root)) {
                        const msg = try std.fmt.allocPrint(
                            alloc,
                            "Method '{s}' of exported interface has or is using private name '{s}'.",
                            .{ method_str, private_str },
                        );
                        try self.report(key_expr, TsCodes.interface_method_name_private_name, msg);
                    } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| {
                        switch (cross) {
                            .private_module => |module_name| {
                                const msg = try std.fmt.allocPrint(
                                    alloc,
                                    "Method '{s}' of exported interface has or is using name '{s}' from private module '{s}'.",
                                    .{ method_str, private_str, module_name },
                                );
                                try self.report(key_expr, TsCodes.interface_method_name_private_module, msg);
                            },
                            .cannot_be_named => {},
                        }
                    }
                }

                // A method / call / construct signature stores its
                // `fn_type` (or `constructor_type`) in `type_node`.
                if (self.hir.kindOf(im.type_node) != .fn_type and self.hir.kindOf(im.type_node) != .constructor_type) continue;
                const ft = hir_mod.fnTypeOf(self.hir, im.type_node);
                // Distinguish a named method from a call/construct
                // signature member — the parser names the latter
                // `__call` / `__construct` (a construct signature's
                // `type_node` is a `.constructor_type`). Upstream's member
                // selector keys off the signature kind, so each gets its
                // own privacy family: named method → TS4014/4057/4056/
                // 4075/4074, call signature → TS4008/4047/4046/4067/4066,
                // construct signature → TS4006/4045/4044/4065/4064. The
                // message bodies are identical apart from the owner phrase.
                const is_construct_sig = self.hir.kindOf(im.type_node) == .constructor_type;
                const is_call_sig = !is_construct_sig and im.name != 0 and self.syntheticSignatureMemberName(im.name);
                const SigCodes = struct {
                    phrase: []const u8,
                    tp_priv: u32,
                    ret_priv: u32,
                    ret_mod: u32,
                    param_priv: u32,
                    param_mod: u32,
                };
                const codes: SigCodes = if (is_construct_sig) .{
                    .phrase = "constructor signature from exported interface",
                    .tp_priv = TsCodes.type_parameter_of_construct_signature_private_name,
                    .ret_priv = TsCodes.construct_signature_return_private_name,
                    .ret_mod = TsCodes.construct_signature_return_private_module,
                    .param_priv = TsCodes.construct_signature_param_private_name,
                    .param_mod = TsCodes.construct_signature_param_private_module,
                } else if (is_call_sig) .{
                    .phrase = "call signature from exported interface",
                    .tp_priv = TsCodes.type_parameter_of_call_signature_private_name,
                    .ret_priv = TsCodes.call_signature_return_private_name,
                    .ret_mod = TsCodes.call_signature_return_private_module,
                    .param_priv = TsCodes.call_signature_param_private_name,
                    .param_mod = TsCodes.call_signature_param_private_module,
                } else .{
                    .phrase = "method from exported interface",
                    .tp_priv = TsCodes.type_parameter_of_interface_method_private_name,
                    .ret_priv = TsCodes.interface_method_return_private_name,
                    .ret_mod = TsCodes.interface_method_return_private_module,
                    .param_priv = TsCodes.interface_method_param_private_name,
                    .param_mod = TsCodes.interface_method_param_private_module,
                };
                // Type-parameter constraints/defaults (private-name variant
                // only — constraints are always nameable upstream). Read the
                // params off the `fn_type` payload directly rather than via
                // `fnTypeParams`, which asserts a fn_decl node.
                const method_tps = self.hir.childSlice(ft.type_params_start, ft.type_params_len);
                if (method_tps.len > 0) {
                    try self.checkMethodTypeParamPrivateNames(method_tps, stmts, codes.tp_priv, codes.phrase);
                }
                try self.checkInferExtendsPrivateNamesInTypeNode(ft.return_type, stmts);
                if (self.annotationBareName(ft.return_type)) |root| {
                    const private_str = self.string_interner.get(root);
                    if (self.nameIsModuleLocalPrivate(stmts, root)) {
                        const msg = try std.fmt.allocPrint(
                            alloc,
                            "Return type of {s} has or is using private name '{s}'.",
                            .{ codes.phrase, private_str },
                        );
                        try self.report(ft.return_type, codes.ret_priv, msg);
                    } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| switch (cross) {
                        // Interfaces have no `cannot be named` variant
                        // upstream (the member selector uses the
                        // non-name-checking path).
                        .private_module => |module_name| {
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Return type of {s} has or is using name '{s}' from private module '{s}'.",
                                .{ codes.phrase, private_str, module_name },
                            );
                            try self.report(ft.return_type, codes.ret_mod, msg);
                        },
                        .cannot_be_named => {},
                    };
                }
                for (self.hir.childSlice(ft.params_start, ft.params_len)) |param| {
                    if (self.hir.kindOf(param) != .parameter) continue;
                    const p = hir_mod.parameterOf(self.hir, param);
                    try self.checkInferExtendsPrivateNamesInTypeNode(p.type_annotation, stmts);
                    const root = self.annotationBareName(p.type_annotation) orelse continue;
                    const param_name = self.parameterBareName(param) orelse continue;
                    const param_str = self.string_interner.get(param_name);
                    const private_str = self.string_interner.get(root);
                    if (self.nameIsModuleLocalPrivate(stmts, root)) {
                        const msg = try std.fmt.allocPrint(
                            alloc,
                            "Parameter '{s}' of {s} has or is using private name '{s}'.",
                            .{ param_str, codes.phrase, private_str },
                        );
                        try self.report(p.type_annotation, codes.param_priv, msg);
                    } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| switch (cross) {
                        .private_module => |module_name| {
                            const msg = try std.fmt.allocPrint(
                                alloc,
                                "Parameter '{s}' of {s} has or is using name '{s}' from private module '{s}'.",
                                .{ param_str, codes.phrase, private_str, module_name },
                            );
                            try self.report(p.type_annotation, codes.param_mod, msg);
                        },
                        .cannot_be_named => {},
                    };
                }
            } else {
                if (im.name == 0) continue; // computed — out of scope.
                if (self.recursiveRequiredMappedPropertyInfo(node, member) != null) continue;
                const member_str = self.string_interner.get(im.name);
                try self.checkInferExtendsPrivateNamesInTypeNode(im.type_node, stmts);
                const root = self.annotationBareName(im.type_node) orelse continue;
                const private_str = self.string_interner.get(root);
                if (self.nameIsModuleLocalPrivate(stmts, root)) {
                    const msg = try std.fmt.allocPrint(
                        alloc,
                        "Property '{s}' of exported interface has or is using private name '{s}'.",
                        .{ member_str, private_str },
                    );
                    try self.report(im.type_node, TsCodes.interface_property_private_name, msg);
                } else if (self.crossModulePrivateNameInfo(stmts, root)) |cross| switch (cross) {
                    .private_module => |module_name| {
                        const msg = try std.fmt.allocPrint(
                            alloc,
                            "Property '{s}' of exported interface has or is using name '{s}' from private module '{s}'.",
                            .{ member_str, private_str, module_name },
                        );
                        try self.report(im.type_node, TsCodes.interface_property_private_module, msg);
                    },
                    .cannot_be_named => {},
                };
            }
        }
    }

    /// method becomes an object member typed as a signature; each
    /// declared field becomes an object member typed as the
    /// annotation (or the initializer's type, or `any`).
    /// Constructors are walked for body typing but excluded from the
    /// instance shape ÃÂ¢ÃÂÃÂ they live on the constructor function, not
    /// on instances.
    /// TS2506 — flag classes whose `extends` chain loops back to
    /// themselves. Self-contained whole-file pass: build a
    /// className -> (extends-name, name-node) map across all class
    /// declarations, then for each class walk its base chain and emit
    /// if it reaches itself. Bounded by a step cap. Does not touch the
    /// heritage/relation logic, so no regression surface.
    fn checkCircularBaseExpressions(self: *Checker) CheckError!void {
        const Entry = struct { extends_name: ?hir_mod.StringId, name_node: NodeId, display_name: hir_mod.StringId };
        var map: std.AutoHashMapUnmanaged(hir_mod.StringId, Entry) = .empty;
        defer map.deinit(self.gpa);
        var node: NodeId = 0;
        while (node < self.hir.nodeCount()) : (node += 1) {
            const k = self.hir.kindOf(node);
            if (k != .class_decl and k != .class_expr) continue;
            const c = hir_mod.classOf(self.hir, node);
            if (c.name == hir_mod.none_node_id or self.hir.kindOf(c.name) != .identifier) continue;
            const cname = hir_mod.identifierOf(self.hir, c.name).name;
            const class_key = try self.qualifiedClassKeyForDecl(node, cname);
            const ext_name: ?hir_mod.StringId = if (c.extends != hir_mod.none_node_id)
                try self.qualifiedClassKeyForExtends(c.extends)
            else
                null;
            // First declaration wins the anchor (merged/duplicate class
            // names are a separate diagnostic).
            if (!map.contains(class_key)) {
                try map.put(self.gpa, class_key, .{ .extends_name = ext_name, .name_node = c.name, .display_name = cname });
            }
        }
        var it = map.iterator();
        while (it.next()) |entry| {
            const start = entry.key_ptr.*;
            var cur: ?hir_mod.StringId = entry.value_ptr.*.extends_name;
            var steps: usize = 0;
            const cap = map.count() + 1;
            while (cur) |c| {
                if (c == start) {
                    try self.report(
                        entry.value_ptr.*.name_node,
                        TsCodes.circular_base_expression,
                        try std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "'{s}' is referenced directly or indirectly in its own base expression.",
                            .{self.string_interner.get(entry.value_ptr.*.display_name)},
                        ),
                    );
                    break;
                }
                if (steps > cap) break;
                steps += 1;
                cur = if (map.get(c)) |e| e.extends_name else null;
            }
        }
    }

    fn internQualifiedNameFromPath(
        self: *Checker,
        path: []const hir_mod.StringId,
        name: hir_mod.StringId,
    ) CheckError!hir_mod.StringId {
        if (path.len == 0) return name;
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        defer buf.deinit(self.gpa);
        for (path) |part| {
            if (buf.items.len != 0) try buf.append(self.gpa, '.');
            try buf.appendSlice(self.gpa, self.string_interner.get(part));
        }
        try buf.append(self.gpa, '.');
        try buf.appendSlice(self.gpa, self.string_interner.get(name));
        return self.string_interner.intern(buf.items) catch return error.OutOfMemory;
    }

    fn qualifiedClassKeyForDecl(
        self: *Checker,
        class_node: NodeId,
        name: hir_mod.StringId,
    ) CheckError!hir_mod.StringId {
        var path: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer path.deinit(self.gpa);
        self.collectEnclosingNamespacePathNoFail(class_node, &path);
        return try self.internQualifiedNameFromPath(path.items, name);
    }

    fn visibleClassDeclForHeritageTypeRef(self: *Checker, type_ref_node: NodeId) ?NodeId {
        if (self.hir.kindOf(type_ref_node) != .type_ref) return null;
        const r = hir_mod.typeRefOf(self.hir, type_ref_node);
        const qualifiers = hir_mod.typeRefQualifier(self.hir, type_ref_node);
        if (qualifiers.len == 0) {
            const decl = self.findVisibleNamedTypeDecl(type_ref_node, r.name) orelse return null;
            const k = self.hir.kindOf(decl);
            return if (k == .class_decl or k == .class_expr) decl else null;
        }

        var path: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer path.deinit(self.gpa);
        for (qualifiers) |q| {
            if (self.hir.kindOf(q) != .identifier) return null;
            path.append(self.gpa, hir_mod.identifierOf(self.hir, q).name) catch return null;
        }
        const ns_node = self.findVisibleNamespaceByPath(type_ref_node, path.items) orelse return null;
        const decl = self.findVisibleTypeDeclInNamespace(ns_node, r.name, type_ref_node) orelse return null;
        const k = self.hir.kindOf(decl);
        return if (k == .class_decl or k == .class_expr) decl else null;
    }

    fn qualifiedClassKeyForExtends(self: *Checker, extends_expr: NodeId) CheckError!?hir_mod.StringId {
        if (self.hir.kindOf(extends_expr) == .type_ref) {
            const r = hir_mod.typeRefOf(self.hir, extends_expr);
            if (self.visibleClassDeclForHeritageTypeRef(extends_expr)) |decl| {
                return try self.qualifiedClassKeyForDecl(decl, r.name);
            }
            if (r.qualifier_len == 0) return r.name;
            return null;
        }
        if (self.hir.kindOf(extends_expr) == .member_access) {
            const ma = hir_mod.memberOf(self.hir, extends_expr);
            if (self.findQualifiedClassDecl(extends_expr)) |decl| {
                return try self.qualifiedClassKeyForDecl(decl, ma.name);
            }
            return null;
        }
        const name = self.classExtendsName(extends_expr) orelse return null;
        if (self.hir.kindOf(extends_expr) == .identifier) {
            if (self.findVisibleNamedClassDecl(extends_expr, name)) |decl| {
                return try self.qualifiedClassKeyForDecl(decl, name);
            }
        }
        return name;
    }

    fn appendInheritedClassMembers(
        self: *Checker,
        inherited_t: TypeId,
        is_static: bool,
        members: *std.ArrayListUnmanaged(types.ObjectMember),
        indices: *std.AutoHashMapUnmanaged(hir_mod.StringId, usize),
    ) CheckError!void {
        if (inherited_t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(inherited_t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(inherited_t)) |part| {
                try self.appendInheritedClassMembers(part, is_static, members, indices);
            }
            return;
        }
        if (!flags.is_object_type) return;
        const construct_name = self.string_interner.intern("__construct") catch return error.OutOfMemory;
        const name_name = self.string_interner.intern("name") catch return error.OutOfMemory;
        const prototype_name = self.string_interner.intern("prototype") catch return error.OutOfMemory;
        for (self.interner.objectMembers(inherited_t)) |inherited| {
            if (is_static and
                (inherited.name == construct_name or inherited.name == name_name or inherited.name == prototype_name))
            {
                continue;
            }
            if (indices.get(inherited.name)) |index| {
                var merged = members.items[index];
                // Intersection accessibility uses the least restrictive
                // constituent: any public declaration makes the effective
                // property public; otherwise private dominates protected.
                merged.visibility = if (merged.visibility == .public or inherited.visibility == .public)
                    .public
                else if (merged.visibility == .private or inherited.visibility == .private)
                    .private
                else
                    .protected;
                members.items[index] = merged;
                continue;
            }
            try indices.put(self.gpa, inherited.name, members.items.len);
            try members.append(self.gpa, inherited);
        }
    }

    fn checkClassDecl(self: *Checker, node: NodeId) CheckError!void {
        if (self.checked_class_decls.contains(node)) return;
        try self.checked_class_decls.put(self.gpa, node, {});
        defer _ = self.checked_class_decls.remove(node);

        const c = hir_mod.classOf(self.hir, node);
        const class_privacy_key = try self.classPrivacyKey(node);
        const members = hir_mod.classMembers(self.hir, node);
        try self.checkClassMemberDecoratorDiagnostics(members);
        try self.detectClassMemberDuplicates(members);
        try self.checkAccessorPairAccessibility(members);
        try self.checkClassNamedObjectInCommonJsLikeModule(node);
        try self.checkHeritagePrivateNames(node, self.declarationName(node), true);
        try self.checkExportedClassMemberPrivateNames(node);
        try self.checkJsDocTemplateBracketedName(node);
        const type_params = self.hir.childSlice(c.type_params_start, c.type_params_len);
        try self.checkExportedTypeParamPrivateNames(node, type_params, .class);
        try self.checkJsOnlyTypeParameters(node, type_params);
        const class_name_scope = c.name != hir_mod.none_node_id and
            self.hir.kindOf(c.name) == .identifier;
        if (class_name_scope) {
            const cid = hir_mod.identifierOf(self.hir, c.name);
            try self.pushNarrowScope();
            try self.recordNarrow(cid.name, types.Primitive.any);
        }
        defer if (class_name_scope) self.popNarrowScope();
        try self.checkTypeParameterDeclList(type_params);
        try self.checkUnusedTypeParameters(node, type_params, false);
        if (type_params.len > 0) try self.pushNarrowScope();
        defer if (type_params.len > 0) self.popNarrowScope();

        // Class-level JSDoc `@template T` (checkJs): a class whose only
        // type parameters come from a leading `/** @template T */` tag
        // makes `T` visible to member JSDoc annotations like
        // `/** @type {T} */`. Register them into the class narrow scope
        // so those annotations resolve `T` instead of reporting TS2304.
        // Reuses the function-signature `@template` machinery (both
        // helpers key off the node's span). Only when the class has no
        // syntactic `<T>` params. Mirrors `genericSetterInClassTypeJsDoc`.
        var class_param_ids: std.ArrayListUnmanaged(TypeId) = .empty;
        var class_param_ids_moved = false;
        defer if (!class_param_ids_moved) class_param_ids.deinit(self.gpa);
        const class_jsdoc_template_scope = self.check_js_enabled and
            type_params.len == 0 and self.fnHasJsDocTemplateTags(node);
        if (class_jsdoc_template_scope) try self.pushNarrowScope();
        defer if (class_jsdoc_template_scope) self.popNarrowScope();
        if (class_jsdoc_template_scope) {
            try self.recordJsDocTemplateTypeParams(node, &class_param_ids);
        }

        // Two-pass type-parameter binding so `class C<T extends List<T>>`
        // sees `T` while lowering its own constraint. Mirrors the
        // function-signature path above and fixes parserGenericConstraint2-7
        // baselines that flagged TS2304 on `T` inside its own constraint.
        for (type_params) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            const tpp = hir_mod.typeParameterOf(self.hir, tp);
            const placeholder = self.interner.internFreshTypeParameterWithFlags(
                tpp.name,
                types.Primitive.unknown,
                types.Primitive.none,
                types.Variance.fromHirBits(tpp.variance),
                tpp.is_const,
            ) catch return error.OutOfMemory;
            self.hir.setType(tp, placeholder);
            try self.recordNarrow(tpp.name, placeholder);
        }
        for (type_params) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            const tpp = hir_mod.typeParameterOf(self.hir, tp);
            const placeholder = self.hir.typeOf(tp);
            const constraint: TypeId = if (tpp.constraint != hir_mod.none_node_id)
                try self.lowererLowerWithTypeParams(tpp.constraint)
            else
                types.Primitive.unknown;
            const def: TypeId = if (tpp.default != hir_mod.none_node_id)
                try self.lowererLowerWithTypeParams(tpp.default)
            else
                types.Primitive.none;
            const tp_id = if (tpp.constraint == hir_mod.none_node_id and tpp.default == hir_mod.none_node_id)
                (self.lookupNarrow(tpp.name) orelse self.hir.typeOf(tp))
            else
                self.interner.internFreshTypeParameterWithFlags(
                    tpp.name,
                    constraint,
                    def,
                    types.Variance.fromHirBits(tpp.variance),
                    tpp.is_const,
                ) catch return error.OutOfMemory;
            if (placeholder != types.Primitive.none and placeholder != tp_id) {
                try self.type_parameter_placeholder_targets.put(self.gpa, placeholder, tp_id);
            }
            self.hir.setType(tp, tp_id);
            try self.recordNarrow(tpp.name, tp_id);
            try class_param_ids.append(self.gpa, tp_id);
        }

        // Pass 1: build the instance shape from signatures + field
        // annotations only (no method body walks). Methods need the
        // instance type registered in `class_instance_types` BEFORE
        // their bodies are typed so `this` resolves.
        const parent_instance_t: ?TypeId = if (c.extends != hir_mod.none_node_id) blk: {
            const bare_base_type_param = self.bareTypeNodeIsTypeParam(c.extends, type_params);
            const base_type_param_ref = self.baseClassExpressionTypeParamReferenceNode(c.extends, type_params);
            if (base_type_param_ref != hir_mod.none_node_id and !bare_base_type_param) {
                try self.report(base_type_param_ref, TsCodes.base_class_expression_type_parameter, "Base class expressions cannot reference class type parameters.");
            }
            if (self.expressionContainsThis(c.extends) and
                self.enclosingConstructorNode(c.extends) == hir_mod.none_node_id)
            {
                try self.report(c.extends, TsCodes.not_constructor_function_type, "Type 'typeof globalThis' is not a constructor function type.");
            }
            const parent_t = try self.classExtendsInstanceType(c.extends);
            try self.reportUnresolvedClassExtendsHeritage(c.extends, type_params);
            // TS2507: `class D extends foo` where `foo` is a plain
            // function (or any other non-constructable value). When the
            // extends expression resolves to a value but the resolved
            // value type carries no construct signatures, tsc emits
            // "Type '<sig>' is not a constructor function type." Mirrors
            // upstream `classExtendsValidConstructorFunction` and
            // `classExtendsShadowedConstructorFunction`.
            const invalid_constructor_type_args = try self.classExtendsCallHasInvalidTypeArgCount(c.extends);
            if (parent_t == null and !bare_base_type_param and !invalid_constructor_type_args) {
                if (self.hir.kindOf(c.extends) == .identifier) {
                    try self.reportNonConstructorClassExtends(c.extends);
                } else {
                    try self.reportNonConstructorClassExtendsExpression(c.extends);
                }
            }
            // TS2314: `class D extends C` where `C<T>` is generic ÃÂ¢ÃÂÃÂ fire
            // when the heritage is a bare class name (no type-arg list).
            // The type-ref form (`class D extends C<X, Y>`) is already
            // covered by the generic-arity check in the lowerer; this
            // branch wires up the bare-identifier form. Mirrors upstream
            // `genericTypeReferenceWithoutTypeArgument.ts(20,17)`.
            try self.reportClassExtendsMissingTypeArgs(node, c.extends);
            try self.reportClassExtendsInvalidBaseConstructorReturns(c.extends);
            break :blk parent_t;
        } else null;
        const parent_static_t: ?TypeId = if (c.extends != hir_mod.none_node_id)
            (self.classExtendsStaticType(c.extends) catch null) orelse types.Primitive.any
        else
            null;
        if (!c.is_abstract and c.extends != hir_mod.none_node_id and
            try self.classExtendsAbstractConstructTypeVariable(c.extends))
        {
            const anchor = if (c.name != hir_mod.none_node_id) c.name else node;
            try self.report(
                anchor,
                TsCodes.non_abstract_mixin_extends_abstract_constructor,
                "A mixin class that extends from a type variable containing an abstract construct signature must also be declared 'abstract'.",
            );
        }
        const no_extends_class_name: ?[]const u8 = if (c.extends == hir_mod.none_node_id)
            if (c.name != hir_mod.none_node_id and self.hir.kindOf(c.name) == .identifier)
                self.string_interner.get(hir_mod.identifierOf(self.hir, c.name).name)
            else
                "(Anonymous class)"
        else
            null;
        const override_base_class_name = self.overrideBaseClassDiagnosticNameFromExtends(c.extends);
        var instance_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer instance_members.deinit(self.gpa);
        var static_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer static_members.deinit(self.gpa);
        var ctor_sig: TypeId = types.Primitive.none;
        var has_explicit_ctor = false;
        var ctor_visibility: ConstructorVisibility = .public_;
        // Per-class accumulation of bodyless constructor overload
        // signatures. Flushed into `class_constructor_overload_sigs`
        // after the class name is known so the new-expression path
        // can consider them during arity / TS2554 checking. We only
        // collect the BODYLESS sigs here ÃÂ¢ÃÂÃÂ the implementation lands
        // in `ctor_sig` separately.
        var ctor_overload_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer ctor_overload_sigs.deinit(self.gpa);
        // Parallel to `ctor_overload_sigs` ÃÂ¢ÃÂÃÂ the bodyless ctor decl
        // node for each overload, so the ÃÂÃÂ§6.A TS2394 overload-vs-impl
        // compatibility check can anchor at the right source position.
        var ctor_overload_nodes: std.ArrayListUnmanaged(NodeId) = .empty;
        defer ctor_overload_nodes.deinit(self.gpa);
        var ctor_overload_visibilities: std.ArrayListUnmanaged(ConstructorVisibility) = .empty;
        defer ctor_overload_visibilities.deinit(self.gpa);
        // Optional source position override for JSDoc `@constructor
        // @overload` blocks. Native constructor overloads stay null and
        // anchor at the constructor declaration node.
        var ctor_overload_positions: std.ArrayListUnmanaged(?u32) = .empty;
        defer ctor_overload_positions.deinit(self.gpa);
        var ctor_overload_max_counts: std.ArrayListUnmanaged(?usize) = .empty;
        defer ctor_overload_max_counts.deinit(self.gpa);
        var ctor_impl_node: NodeId = hir_mod.none_node_id;
        var ctor_impl_visibility: ?ConstructorVisibility = null;
        // TS2392 ÃÂ¢ÃÂÃÂ every bodied constructor implementation node, so we
        // can flag each one when a class declares more than one.
        var ctor_impl_nodes: std.ArrayListUnmanaged(NodeId) = .empty;
        defer ctor_impl_nodes.deinit(self.gpa);
        // Constructor overload tracking. tsc fires TS2390 (Constructor
        // implementation is missing) when one or more `constructor()`
        // signatures appear without a body and there's no concrete
        // `constructor(...) { ÃÂ¢ÃÂÃÂ¦ }` to satisfy them.
        var ctor_first_bodyless: NodeId = hir_mod.none_node_id;
        var ctor_bodyless_count: u32 = 0;
        var ctor_impl_count: u32 = 0;
        var string_idx: TypeId = types.Primitive.none;
        var number_idx: TypeId = types.Primitive.none;
        var symbol_idx: TypeId = types.Primitive.none;
        var has_readonly_index = false;
        var static_string_idx: TypeId = types.Primitive.none;
        var static_number_idx: TypeId = types.Primitive.none;
        var static_symbol_idx: TypeId = types.Primitive.none;
        var has_static_readonly_index = false;
        var own_index_signatures: IndexSignatureDuplicateState = .{};
        var own_static_index_signatures: IndexSignatureDuplicateState = .{};
        const parent_class_name = if (c.extends != hir_mod.none_node_id) self.classExtendsName(c.extends) else null;
        // TS2675 — extending a class whose constructor is `private` is
        // only allowed within the declaring class. Mirrors upstream
        // `checkBaseTypeAccessibility` (private constructors only; the
        // protected case is permitted for subclasses). Anchored at the
        // extends-clause expression.
        if (c.extends != hir_mod.none_node_id) {
            if (parent_class_name) |base_name| {
                if (self.private_constructor_classes.contains(base_name) and
                    !self.nodeIsInsideClass(c.extends, base_name))
                {
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Cannot extend a class '{s}'. Class constructor is marked as private.",
                        .{self.string_interner.get(base_name)},
                    );
                    try self.report(c.extends, TsCodes.cannot_extend_class_private_constructor, msg);
                }
            }
        }
        // Names of class members declared `private`. After the class
        // name is known we move ownership into `class_private_members`
        // and reset this local to `.empty` so the trailing `defer` is
        // a no-op on the success path.
        var private_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer private_names.deinit(self.gpa);
        var unused_private_member_candidates: PrivateMemberCandidateMap = .empty;
        defer unused_private_member_candidates.deinit(self.gpa);
        var protected_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer protected_names.deinit(self.gpa);
        // Static-only accessibility tracking. Separate from
        // `private_names`/`protected_names` (which mix instance +
        // static for the legacy access-check path) so the heritage
        // accessibility check can reason about the static side
        // independently. Moved into `class_static_private_members`
        // / `class_static_protected_members` once the class name
        // is known.
        var static_private_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer static_private_names.deinit(self.gpa);
        var static_protected_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer static_protected_names.deinit(self.gpa);
        // Names of every member the class actually declares (any
        // accessibility), split by static-vs-instance side. Used
        // by the heritage accessibility check so it only fires on
        // members the derived class redeclares (vs. just inherits).
        var instance_member_names_local: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer instance_member_names_local.deinit(self.gpa);
        var static_member_names_local: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer static_member_names_local.deinit(self.gpa);
        // Names of class members treated as abstract (v0 heuristic:
        // bodyless methods inside an `abstract` class). Moved into
        // `class_abstract_members` once the class name is known.
        var abstract_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer abstract_names.deinit(self.gpa);
        // Parallel ordered list of abstract member names ÃÂ¢ÃÂÃÂ preserves
        // declaration order for TS2654 prose, while `abstract_names`
        // continues to serve as the fast lookup set.
        var abstract_names_order: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer abstract_names_order.deinit(self.gpa);
        var abstract_property_origins: std.AutoHashMapUnmanaged(hir_mod.StringId, hir_mod.StringId) = .empty;
        defer abstract_property_origins.deinit(self.gpa);
        var property_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer property_names.deinit(self.gpa);
        var parameter_property_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer parameter_property_names.deinit(self.gpa);
        var ctor_param_property_merges: std.AutoHashMapUnmanaged(hir_mod.StringId, ConstructorParamPropertyMerge) = .empty;
        defer ctor_param_property_merges.deinit(self.gpa);
        // Instance class fields declared with neither an initializer
        // nor a `!` definite-assignment assertion, in declaration
        // order. Under `useDefineForClassFields: true` these clobber
        // any inherited value to `undefined` at construction time, so
        // a sibling field's initializer reading `this.<name>` reads
        // `undefined` ÃÂ¢ÃÂÃÂ tsc reports TS2729 at the property-name
        // segment (see `redeclaredProperty.ts(7,12)`).
        // Maps each uninitialized instance-field name to its declaring
        // member node, so a later sibling initializer that reads it can
        // anchor a TS2728 "'X' is declared here." related-info.
        var uninit_instance_field_names: std.AutoHashMapUnmanaged(hir_mod.StringId, NodeId) = .empty;
        defer uninit_instance_field_names.deinit(self.gpa);
        // Names of instance methods declared by this class. Moved into
        // `class_method_members` once the class name is known. Used by
        // TS2423 when a subclass redeclares one of these as an accessor.
        var method_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer method_names.deinit(self.gpa);
        var accessor_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer accessor_names.deinit(self.gpa);
        var private_method_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer private_method_names.deinit(self.gpa);
        var static_private_method_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer static_private_method_names.deinit(self.gpa);
        var private_set_only_accessor_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer private_set_only_accessor_names.deinit(self.gpa);
        var static_private_set_only_accessor_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer static_private_set_only_accessor_names.deinit(self.gpa);
        var own_member_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer own_member_names.deinit(self.gpa);
        // Names the child concretely implements (methods with a body
        // or any field). Used to satisfy inherited abstract members.
        var concrete_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer concrete_names.deinit(self.gpa);
        var static_names: std.AutoHashMapUnmanaged(hir_mod.StringId, NodeId) = .empty;
        defer static_names.deinit(self.gpa);
        var method_seen: std.AutoHashMapUnmanaged(hir_mod.StringId, ClassMethodSeen) = .empty;
        defer {
            var msit = method_seen.iterator();
            while (msit.next()) |e| {
                e.value_ptr.prior_nodes.deinit(self.gpa);
                e.value_ptr.prior_abstractness.deinit(self.gpa);
                e.value_ptr.prior_visibilities.deinit(self.gpa);
            }
            method_seen.deinit(self.gpa);
        }
        var static_method_seen: std.AutoHashMapUnmanaged(hir_mod.StringId, ClassMethodSeen) = .empty;
        defer {
            var sit = static_method_seen.iterator();
            while (sit.next()) |e| {
                e.value_ptr.prior_nodes.deinit(self.gpa);
                e.value_ptr.prior_abstractness.deinit(self.gpa);
                e.value_ptr.prior_visibilities.deinit(self.gpa);
            }
            static_method_seen.deinit(self.gpa);
        }
        var previous_bodyless_method_name: ?hir_mod.StringId = null;
        var previous_bodyless_method_static = false;
        var instance_member_predicates: std.AutoHashMapUnmanaged(hir_mod.StringId, FnPredicate) = .empty;
        defer instance_member_predicates.deinit(self.gpa);
        var static_member_predicates: std.AutoHashMapUnmanaged(hir_mod.StringId, FnPredicate) = .empty;
        defer static_member_predicates.deinit(self.gpa);
        // Names that the constructor body definitely assigns via
        // `this.X = ...`. Used to suppress TS2564 for typed instance
        // fields that have no inline initializer but are assigned in
        // the constructor body (matching tsc's strict-property-init
        // detection).
        var ctor_assigned_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer ctor_assigned_names.deinit(self.gpa);
        var strict_init_candidate_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer strict_init_candidate_names.deinit(self.gpa);
        var static_block_this_assigned_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer static_block_this_assigned_names.deinit(self.gpa);

        // Pre-scan for accessor pairs: a member name with both a
        // `get` and a `set` accessor is a regular read+write property.
        // A getter alone is `readonly`. Track which names have a
        // setter so we can clear readonly when the getter lands.
        var setter_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer setter_names.deinit(self.gpa);
        var getter_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer getter_names.deinit(self.gpa);
        var static_getter_names: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer static_getter_names.deinit(self.gpa);
        // TS2676 — a get/set accessor pair for the same member must
        // agree on the `abstract` modifier. Track each accessor's
        // abstract-ness and name node keyed by (name, static-ness) so a
        // mismatched pair can be flagged on both accessor names after
        // the pre-scan. Mirrors upstream `checkAccessorDeclaration`.
        const AccessorAbstract = struct { is_abstract: bool, name_node: NodeId };
        const AccessorPairKey = struct { name: hir_mod.StringId, is_static: bool };
        var getter_abstract: std.AutoHashMapUnmanaged(AccessorPairKey, AccessorAbstract) = .empty;
        defer getter_abstract.deinit(self.gpa);
        var setter_abstract: std.AutoHashMapUnmanaged(AccessorPairKey, AccessorAbstract) = .empty;
        defer setter_abstract.deinit(self.gpa);
        for (members) |m| {
            const k = self.hir.kindOf(m);
            if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) continue;
            const fp = hir_mod.fnDeclOf(self.hir, m);
            const nid = (try self.classMemberNameFromFunctionName(fp.name)) orelse continue;
            if (fp.flags.is_getter) {
                if (fp.flags.is_static) {
                    try static_getter_names.put(self.gpa, nid, {});
                } else {
                    try getter_names.put(self.gpa, nid, {});
                }
                try getter_abstract.put(self.gpa, .{ .name = nid, .is_static = fp.flags.is_static }, .{ .is_abstract = fp.flags.is_abstract, .name_node = if (fp.name != hir_mod.none_node_id) fp.name else m });
