                }
                break :blk instance_t;
            };
            if (can_merge_interface and final_instance_t != instance_t) {
                try self.merged_class_instance_types.put(self.gpa, instance_t, final_instance_t);
            }
            // Forward-referenced classes resolve through the MERGED
            // type (see above), so record the base link under both
            // keys; `getNormalizedType` and the own-then-inherited
            // member reconstruction consult the type consumers
            // actually see (`checkJsxChildrenProperty5`'s
            // `children: Button` forward reference).
            if (parent_instance_t) |pt| {
                if (final_instance_t != instance_t and pt != final_instance_t and
                    pt < self.interner.pool.typeCount() and
                    self.interner.pool.flagsOf(pt).is_object_type)
                {
