                // type keyword. tsc's `isPrimitiveTypeName` heritage
                // branch fires this BEFORE the generic non-object TS2422,
                // with a dedicated message. Mirrors `classImplementsPrimitive`.
                if (self.heritageBareName(impl_node)) |bare| {
                    const raw = self.string_interner.get(bare);
                    const is_primitive = std.mem.eql(u8, raw, "number") or
                        std.mem.eql(u8, raw, "string") or
                        std.mem.eql(u8, raw, "boolean") or
                        std.mem.eql(u8, raw, "never") or
                        std.mem.eql(u8, raw, "unknown") or
                        std.mem.eql(u8, raw, "any");
