                // ES2018: `s` flag.
                .{ .name = self.string_interner.intern("dotAll") catch return types.Primitive.unknown, .type = boolean_t, .is_optional = false, .is_readonly = true, .is_method = false },
                // ES2022: `d` flag.
                .{ .name = self.string_interner.intern("hasIndices") catch return types.Primitive.unknown, .type = boolean_t, .is_optional = false, .is_readonly = true, .is_method = false },
                // ES2024: `v` flag.
                .{ .name = self.string_interner.intern("unicodeSets") catch return types.Primitive.unknown, .type = boolean_t, .is_optional = false, .is_readonly = true, .is_method = false },
                // Symbol-keyed methods land on the instance shape with the
                // literal `Symbol.foo` string key (mirrors how the symbol
                // global publishes its well-known names).
                .{ .name = self.string_interner.intern("Symbol.match") catch return types.Primitive.unknown, .type = sig_match, .is_optional = false, .is_readonly = false, .is_method = true },
                .{ .name = self.string_interner.intern("Symbol.replace") catch return types.Primitive.unknown, .type = sig_replace, .is_optional = false, .is_readonly = false, .is_method = true },
                .{ .name = self.string_interner.intern("Symbol.search") catch return types.Primitive.unknown, .type = sig_search, .is_optional = false, .is_readonly = false, .is_method = true },
                .{ .name = self.string_interner.intern("Symbol.split") catch return types.Primitive.unknown, .type = sig_split, .is_optional = false, .is_readonly = false, .is_method = true },
            };
            return self.interner.internObjectType(&members) catch types.Primitive.unknown;
        }
        if (std.mem.eql(u8, name, "Error")) {
            // `Error` instance shape — used when the name appears in
            // type position (`let e: Error`). The constructor side
            // lives in `errorConstructorGlobalType` and exposes the
            // same set of fields plus `prototype` / `__call`.
            const string_t = types.Primitive.string_t;
            const any_t = types.Primitive.any;
            const members = [_]types.ObjectMember{
                .{ .name = self.string_interner.intern("name") catch return types.Primitive.unknown, .type = string_t, .is_optional = false, .is_readonly = false, .is_method = false },
                .{ .name = self.string_interner.intern("message") catch return types.Primitive.unknown, .type = string_t, .is_optional = false, .is_readonly = false, .is_method = false },
                .{ .name = self.string_interner.intern("stack") catch return types.Primitive.unknown, .type = string_t, .is_optional = true, .is_readonly = false, .is_method = false },
                // ES2022: `cause: unknown` (modeled `any`).
                .{ .name = self.string_interner.intern("cause") catch return types.Primitive.unknown, .type = any_t, .is_optional = true, .is_readonly = false, .is_method = false },
            };
            return self.interner.internObjectType(&members) catch types.Primitive.unknown;
        }
        if (std.mem.eql(u8, name, "Node")) {
            const node_t = self.interner.internObjectType(&.{}) catch return types.Primitive.unknown;
            const sig_remove_child = self.interner.internSignature(&[_]TypeId{node_t}, node_t, false) catch
                return types.Primitive.unknown;
            const members = [_]types.ObjectMember{
                .{
                    .name = self.string_interner.intern("parentNode") catch return types.Primitive.unknown,
                    .type = node_t,
                    .is_optional = true,
                    .is_readonly = false,
                    .is_method = false,
                },
                .{
                    .name = self.string_interner.intern("removeChild") catch return types.Primitive.unknown,
                    .type = sig_remove_child,
                    .is_optional = false,
                    .is_readonly = false,
                    .is_method = true,
                },
            };
            return self.interner.internObjectType(&members) catch types.Primitive.unknown;
        }
        if (std.mem.eql(u8, name, "ArrayBuffer") or std.mem.eql(u8, name, "SharedArrayBuffer")) {
            const optional_number = self.interner.internUnion(&.{ types.Primitive.number_t, types.Primitive.undefined_t }) catch
                return types.Primitive.unknown;
            const slice_signature = self.interner.internSignature(
                &.{ optional_number, optional_number },
                types.Primitive.any,
                false,
            ) catch return types.Primitive.unknown;
            const tag_name = self.string_interner.intern(name) catch return types.Primitive.unknown;
            const tag_type = self.interner.internStringLiteral(tag_name) catch return types.Primitive.unknown;
            const resize_signature = self.interner.internSignature(&.{optional_number}, types.Primitive.void_t, false) catch
                return types.Primitive.unknown;
            if (std.mem.eql(u8, name, "ArrayBuffer")) {
                const transfer_signature = self.interner.internSignature(&.{optional_number}, types.Primitive.any, false) catch
                    return types.Primitive.unknown;
                const members = [_]types.ObjectMember{
                    .{ .name = self.string_interner.intern("byteLength") catch return types.Primitive.unknown, .type = types.Primitive.number_t, .is_optional = false, .is_readonly = true, .is_method = false },
                    .{ .name = self.string_interner.intern("slice") catch return types.Primitive.unknown, .type = slice_signature, .is_optional = false, .is_readonly = false, .is_method = true },
                    .{ .name = self.string_interner.intern("maxByteLength") catch return types.Primitive.unknown, .type = types.Primitive.number_t, .is_optional = false, .is_readonly = true, .is_method = false },
                    .{ .name = self.string_interner.intern("resizable") catch return types.Primitive.unknown, .type = types.Primitive.boolean_t, .is_optional = false, .is_readonly = true, .is_method = false },
                    .{ .name = self.string_interner.intern("resize") catch return types.Primitive.unknown, .type = resize_signature, .is_optional = false, .is_readonly = false, .is_method = true },
                    .{ .name = self.string_interner.intern("detached") catch return types.Primitive.unknown, .type = types.Primitive.boolean_t, .is_optional = false, .is_readonly = true, .is_method = false },
                    .{ .name = self.string_interner.intern("transfer") catch return types.Primitive.unknown, .type = transfer_signature, .is_optional = false, .is_readonly = false, .is_method = true },
                    .{ .name = self.string_interner.intern("transferToFixedLength") catch return types.Primitive.unknown, .type = transfer_signature, .is_optional = false, .is_readonly = false, .is_method = true },
                    .{ .name = self.string_interner.intern("Symbol.toStringTag") catch return types.Primitive.unknown, .type = tag_type, .is_optional = false, .is_readonly = true, .is_method = false },
                };
                return self.interner.internObjectType(&members) catch types.Primitive.unknown;
            }
            const members = [_]types.ObjectMember{
                .{ .name = self.string_interner.intern("byteLength") catch return types.Primitive.unknown, .type = types.Primitive.number_t, .is_optional = false, .is_readonly = true, .is_method = false },
                .{ .name = self.string_interner.intern("slice") catch return types.Primitive.unknown, .type = slice_signature, .is_optional = false, .is_readonly = false, .is_method = true },
                .{ .name = self.string_interner.intern("maxByteLength") catch return types.Primitive.unknown, .type = types.Primitive.number_t, .is_optional = false, .is_readonly = true, .is_method = false },
                .{ .name = self.string_interner.intern("growable") catch return types.Primitive.unknown, .type = types.Primitive.boolean_t, .is_optional = false, .is_readonly = true, .is_method = false },
                .{ .name = self.string_interner.intern("grow") catch return types.Primitive.unknown, .type = resize_signature, .is_optional = false, .is_readonly = false, .is_method = true },
                .{ .name = self.string_interner.intern("Symbol.toStringTag") catch return types.Primitive.unknown, .type = tag_type, .is_optional = false, .is_readonly = true, .is_method = false },
            };
            return self.interner.internObjectType(&members) catch types.Primitive.unknown;
        }
        const builtins = [_][]const u8{
            "Object",
            "RegExp",
            "RegExpMatchArray",
            "RegExpExecArray",
            "Error",
            "TypeError",
            "RangeError",
            "SyntaxError",
            "Function",
            "PromiseLike",
            "Iterator",
            "IteratorObject",
            "AsyncIterator",
            "AsyncIteratorObject",
            "Iterable",
            "AsyncIterable",
            "IterableIterator",
            "AsyncIterableIterator",
            "Uint8Array",
            "Uint8ClampedArray",
            "Int8Array",
            "Uint16Array",
            "Int16Array",
            "Uint32Array",
            "Int32Array",
            "Float16Array",
            "Float32Array",
            "Float64Array",
            "BigUint64Array",
            "BigInt64Array",
        };
        for (builtins) |b| {
            if (!std.mem.eql(u8, name, b)) continue;
            return self.interner.internObjectType(&.{}) catch types.Primitive.unknown;
        }
        return null;
    }

    /// Render a type-syntax node to a tsc-faithful single-line string
    /// for diagnostic prose — currently the mapped-type argument of
    /// TS2615 (`{ [P in keyof T]: undefined extends T[P] ? never : P; }`).
    /// Pure and additive: the base entry point renders the node as
    /// written, while the internal entry point can replace one bound
    /// type parameter with its concrete instantiation for TS2615.
    /// Mirrors the `.d.ts` printer's spacing and adds mapped-type bodies.
    /// Covered node kinds: type
    /// references, keyof / typeof, indexed access, conditional, union /
    /// intersection / array / tuple, literals, and mapped types; object
    /// and function type literals render as `…` placeholders until the
    /// next layer adds member printing.
    fn renderTypeNodeText(self: *Checker, node: NodeId, out: *std.ArrayListUnmanaged(u8)) std.mem.Allocator.Error!void {
        return self.renderTypeNodeTextSubstituting(node, out, null, null);
    }

    fn renderTypeNodeTextSubstituting(
        self: *Checker,
        node: NodeId,
        out: *std.ArrayListUnmanaged(u8),
        substitute_name: ?hir_mod.StringId,
        replacement_name: ?hir_mod.StringId,
    ) std.mem.Allocator.Error!void {
        const a = self.gpa;
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .identifier => {
                const name = hir_mod.identifierOf(self.hir, node).name;
                try out.appendSlice(a, self.string_interner.get(if (substitute_name == name) replacement_name orelse name else name));
            },
            .type_ref => {
                const r = hir_mod.typeRefOf(self.hir, node);
                for (hir_mod.typeRefQualifier(self.hir, node)) |q| {
                    try out.appendSlice(a, self.string_interner.get(hir_mod.identifierOf(self.hir, q).name));
                    try out.append(a, '.');
                }
                const rendered_name = if (r.qualifier_len == 0 and substitute_name == r.name)
                    replacement_name orelse r.name
                else
                    r.name;
                try out.appendSlice(a, self.string_interner.get(rendered_name));
                const args = hir_mod.typeRefArgs(self.hir, node);
                if (args.len > 0) {
                    try out.append(a, '<');
                    for (args, 0..) |arg, i| {
                        if (i > 0) try out.appendSlice(a, ", ");
                        try self.renderTypeNodeTextSubstituting(arg, out, substitute_name, replacement_name);
                    }
                    try out.append(a, '>');
                }
            },
            .keyof_type => {
                try out.appendSlice(a, "keyof ");
                try self.renderTypeNodeTextSubstituting(hir_mod.keyofTypeOf(self.hir, node).operand, out, substitute_name, replacement_name);
            },
            .typeof_type => {
                try out.appendSlice(a, "typeof ");
                try self.renderTypeNodeTextSubstituting(hir_mod.typeofTypeOf(self.hir, node).operand, out, substitute_name, replacement_name);
            },
            .indexed_access_type => {
                const ia = hir_mod.indexedAccessTypeOf(self.hir, node);
                try self.renderTypeNodeTextSubstituting(ia.object, out, substitute_name, replacement_name);
                try out.append(a, '[');
                try self.renderTypeNodeTextSubstituting(ia.index, out, substitute_name, replacement_name);
                try out.append(a, ']');
            },
            .conditional_type => {
                const c = hir_mod.conditionalTypeOf(self.hir, node);
                try self.renderTypeNodeTextSubstituting(c.check, out, substitute_name, replacement_name);
                try out.appendSlice(a, " extends ");
                try self.renderTypeNodeTextSubstituting(c.extends, out, substitute_name, replacement_name);
                try out.appendSlice(a, " ? ");
                try self.renderTypeNodeTextSubstituting(c.true_branch, out, substitute_name, replacement_name);
                try out.appendSlice(a, " : ");
                try self.renderTypeNodeTextSubstituting(c.false_branch, out, substitute_name, replacement_name);
            },
            .union_type => {
                for (hir_mod.unionTypeMembers(self.hir, node), 0..) |m, i| {
                    if (i > 0) try out.appendSlice(a, " | ");
                    try self.renderTypeNodeTextSubstituting(m, out, substitute_name, replacement_name);
                }
            },
            .intersection_type => {
                for (hir_mod.intersectionTypeMembers(self.hir, node), 0..) |m, i| {
                    if (i > 0) try out.appendSlice(a, " & ");
                    try self.renderTypeNodeTextSubstituting(m, out, substitute_name, replacement_name);
                }
            },
            .array_type => {
                try self.renderTypeNodeTextSubstituting(hir_mod.arrayTypeOf(self.hir, node).element, out, substitute_name, replacement_name);
                try out.appendSlice(a, "[]");
            },
            .tuple_type => {
                try out.append(a, '[');
                for (hir_mod.tupleTypeElements(self.hir, node), 0..) |e, i| {
                    if (i > 0) try out.appendSlice(a, ", ");
                    try self.renderTypeNodeTextSubstituting(e, out, substitute_name, replacement_name);
                }
                try out.append(a, ']');
            },
            .type_literal => {
                const lt = hir_mod.literalTypeOf(self.hir, node);
                if (lt.negative) try out.append(a, '-');
                switch (self.hir.kindOf(lt.literal)) {
                    .literal_string => {
                        try out.append(a, '"');
                        try out.appendSlice(a, self.string_interner.get(hir_mod.literalStringOf(self.hir, lt.literal).value));
                        try out.append(a, '"');
                    },
                    .literal_number => {
                        var nbuf: [40]u8 = undefined;
                        const v = hir_mod.literalNumberOf(self.hir, lt.literal);
                        // 40 bytes holds any f64 decimal — overflow is unreachable.
                        try out.appendSlice(a, std.fmt.bufPrint(&nbuf, "{d}", .{v}) catch unreachable);
                    },
                    .literal_bigint => {
                        try out.appendSlice(a, self.string_interner.get(hir_mod.literalBigIntOf(self.hir, lt.literal).digits));
                        try out.append(a, 'n');
                    },
                    .literal_bool => try out.appendSlice(a, if (hir_mod.literalBoolOf(self.hir, lt.literal)) "true" else "false"),
                    else => try out.appendSlice(a, "unknown"),
                }
            },
            .mapped_type => {
                const mt = hir_mod.mappedTypeOf(self.hir, node);
                try out.appendSlice(a, "{ ");
                switch (mt.readonly) {
                    1 => try out.appendSlice(a, "readonly "),
                    2 => try out.appendSlice(a, "-readonly "),
                    else => {},
                }
                try out.append(a, '[');
                if (mt.type_param != hir_mod.none_node_id and self.hir.kindOf(mt.type_param) == .type_parameter) {
                    try out.appendSlice(a, self.string_interner.get(hir_mod.typeParameterOf(self.hir, mt.type_param).name));
                } else {
                    try out.append(a, 'P');
                }
                try out.appendSlice(a, " in ");
                try self.renderTypeNodeTextSubstituting(mt.constraint, out, substitute_name, replacement_name);
                if (mt.remap != hir_mod.none_node_id) {
                    try out.appendSlice(a, " as ");
                    try self.renderTypeNodeTextSubstituting(mt.remap, out, substitute_name, replacement_name);
                }
                try out.append(a, ']');
                switch (mt.optional) {
                    1 => try out.append(a, '?'),
                    2 => try out.appendSlice(a, "-?"),
                    else => {},
                }
                try out.appendSlice(a, ": ");
                try self.renderTypeNodeTextSubstituting(mt.value, out, substitute_name, replacement_name);
                try out.appendSlice(a, "; }");
            },
            // Object / function type literals need member printing — a
            // follow-up layer. Placeholder keeps the renderer total.
            .object_type => try out.appendSlice(a, "{ … }"),
            .fn_type, .constructor_type => try out.appendSlice(a, "(…) => …"),
            else => try out.appendSlice(a, "unknown"),
        }
    }

    fn mappedPropertyResolutionTarget(node: NodeId, key_name: hir_mod.StringId) u64 {
        return (@as(u64, @intCast(node)) << 32) | @as(u64, @intCast(key_name));
    }

    fn renderCircularMappedTypeText(
        self: *Checker,
        node: NodeId,
        key_name: hir_mod.StringId,
        literal_key_count: usize,
        out: *std.ArrayListUnmanaged(u8),
    ) std.mem.Allocator.Error!void {
        const a = self.gpa;
        if (literal_key_count == 1 and self.hir.kindOf(node) == .mapped_type) {
            const mt = hir_mod.mappedTypeOf(self.hir, node);
            if (mt.constraint != hir_mod.none_node_id and self.hir.kindOf(mt.constraint) != .keyof_type) {
                try out.appendSlice(a, "{ [P in \"");
                try out.appendSlice(a, self.string_interner.get(key_name));
                try out.appendSlice(a, "\"]: any; }");
                return;
            }
        }
        try self.renderTypeNodeText(node, out);
    }

    fn reportMappedPropertyCircularOnce(
        self: *Checker,
        node: NodeId,
        key_name: hir_mod.StringId,
        literal_key_count: usize,
    ) CheckError!void {
        const target = mappedPropertyResolutionTarget(node, key_name);
        if (self.reported_mapped_property_cycles.contains(target)) return;
        try self.reported_mapped_property_cycles.put(self.gpa, target, {});

        var mapped_text: std.ArrayListUnmanaged(u8) = .empty;
        defer mapped_text.deinit(self.gpa);
        try self.renderCircularMappedTypeText(node, key_name, literal_key_count, &mapped_text);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type of property '{s}' circularly references itself in mapped type '{s}'.",
            .{ self.string_interner.get(key_name), mapped_text.items },
        );
        const report_node = if (self.instantiation_anchor_node != hir_mod.none_node_id)
            self.instantiation_anchor_node
        else
            node;
        try self.report(report_node, TsCodes.mapped_property_circular, msg);
    }

    fn reportInstantiatedMappedPropertyCircularOnce(
        self: *Checker,
        mapped_node: NodeId,
        key_name: hir_mod.StringId,
        member_node: NodeId,
        report_node: NodeId,
        source_param: hir_mod.StringId,
        concrete_name: hir_mod.StringId,
    ) CheckError!void {
        const target = mappedPropertyResolutionTarget(mapped_node, key_name);
        if (self.reported_mapped_property_cycles.contains(target)) return;
        try self.reported_mapped_property_cycles.put(self.gpa, target, {});

        var mapped_text: std.ArrayListUnmanaged(u8) = .empty;
        defer mapped_text.deinit(self.gpa);
        try self.renderTypeNodeTextSubstituting(
            mapped_node,
            &mapped_text,
            source_param,
            concrete_name,
        );
        const key_node = if (member_node != hir_mod.none_node_id and self.hir.kindOf(member_node) == .interface_member)
            hir_mod.interfaceMemberKeyExpr(self.hir, member_node)
        else
            hir_mod.none_node_id;
        const key_anchor = if (key_node != hir_mod.none_node_id) key_node else member_node;
        const raw_key = std.mem.trim(u8, self.nodeSourceTextOrEmpty(key_anchor), " \t\r\n");
        const property_display = if (key_node != hir_mod.none_node_id and self.hir.kindOf(key_node) == .literal_string)
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "\"{s}\"",
                .{self.string_interner.get(hir_mod.literalStringOf(self.hir, key_node).value)},
            )
        else if (raw_key.len > 0)
            raw_key
        else
            self.string_interner.get(key_name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type of property '{s}' circularly references itself in mapped type '{s}'.",
            .{ property_display, mapped_text.items },
        );
        try self.report(report_node, TsCodes.mapped_property_circular, msg);
    }

    fn lowerMappedPropertyValue(
        self: *Checker,
        node: NodeId,
        m: hir_mod.MappedTypePayload,
        type_param_name: hir_mod.StringId,
        key_lit: TypeId,
        key_name: hir_mod.StringId,
        literal_key_count: usize,
    ) CheckError!TypeId {
        const guarded = self.mapped_indexed_type_eval_depth > 0;
        const reportable_property = key_lit < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(key_lit).is_literal;
        var resolution_pushed = false;
        if (guarded) {
            const target = mappedPropertyResolutionTarget(node, key_name);
            if (!self.pushTypeResolution(target, .type)) {
                if (reportable_property) {
                    try self.reportMappedPropertyCircularOnce(node, key_name, literal_key_count);
                }
                return types.Primitive.any;
            }
            resolution_pushed = true;
        }
        errdefer {
            if (resolution_pushed) _ = self.popTypeResolution();
        }

        const prior_cycle = self.mapped_property_cycle_detected;
        if (guarded) self.mapped_property_cycle_detected = false;
        self.mapped_property_eval_depth += 1;
        defer self.mapped_property_eval_depth -= 1;

        try self.pushNarrowScope();
        defer self.popNarrowScope();
        try self.recordNarrow(type_param_name, key_lit);
        const value_t = try self.lowererLowerWithTypeParams(m.value);

        const cycle_detected = guarded and self.mapped_property_cycle_detected;
        if (guarded) self.mapped_property_cycle_detected = prior_cycle or cycle_detected;
        const resolved_cleanly = if (resolution_pushed) blk: {
            resolution_pushed = false;
            break :blk self.popTypeResolution();
        } else true;
        if (!resolved_cleanly or cycle_detected) {
            if (reportable_property) {
                try self.reportMappedPropertyCircularOnce(node, key_name, literal_key_count);
            }
            return types.Primitive.any;
        }
        return value_t;
    }

    fn instantiateMappedAliasAnyArray(
        self: *Checker,
        node: NodeId,
        info: GenericAliasInfo,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!?TypeId {
        if (self.hir.kindOf(node) != .mapped_type) return null;
        const mapped = hir_mod.mappedTypeOf(self.hir, node);
        if (mapped.remap != hir_mod.none_node_id or
            mapped.constraint == hir_mod.none_node_id or
            self.hir.kindOf(mapped.constraint) != .keyof_type)
        {
            return null;
        }
        const source_node = hir_mod.keyofTypeOf(self.hir, mapped.constraint).operand;
        const source_name = self.bareTypeNodeName(source_node) orelse return null;
        var source_param = types.Primitive.none;
        for (info.params) |param_t| {
            if (self.typeParameterName(param_t) == source_name) {
                source_param = param_t;
                break;
            }
        }
        if (source_param == types.Primitive.none or
            subs.get(source_param) != types.Primitive.any or
            !self.typeParameterHasArrayOrTupleConstraint(source_param) or
            mapped.type_param == hir_mod.none_node_id or
            self.hir.kindOf(mapped.type_param) != .type_parameter)
        {
            return null;
        }

        const key_name = hir_mod.typeParameterOf(self.hir, mapped.type_param).name;
        try self.pushNarrowScope();
        defer self.popNarrowScope();
        try self.recordNarrow(key_name, types.Primitive.number_t);
        var element_t = try self.lowererLowerWithTypeParams(mapped.value);
        if (self.strict_flags.strict_null_checks) {
            element_t = switch (mapped.optional) {
                1 => try self.unionWithUndefined(element_t),
                2 => try self.subtractUndefined(element_t),
                else => element_t,
            };
        }
        const array_t = self.interner.internArrayType(self.string_interner, element_t) catch return error.OutOfMemory;
        try self.array_origin_types.put(self.gpa, array_t, {});
        if (mapped.readonly == 1) try self.readonly_index_types.put(self.gpa, array_t, {});
        return array_t;
    }

    fn evalMappedType(self: *Checker, node: NodeId) CheckError!TypeId {
        const m = hir_mod.mappedTypeOf(self.hir, node);
        if (m.constraint == hir_mod.none_node_id or m.value == hir_mod.none_node_id) {
            // TS7039 — a well-formed mapped type with no template
            // (`{ [P in T] }`) has an implicitly-`any` template type.
            // Only under noImplicitAny; deduped per node since the
            // lowering path can run more than once during inference.
            if (m.value == hir_mod.none_node_id and
                m.constraint != hir_mod.none_node_id and
                self.strict_flags.no_implicit_any)
            {
                var already = false;
                for (self.diagnostics.items) |d| {
                    if (d.node == node and d.code == TsCodes.mapped_type_implicit_any_template) {
                        already = true;
                        break;
                    }
                }
                if (!already) {
                    try self.report(node, TsCodes.mapped_type_implicit_any_template, "Mapped object type implicitly has an 'any' template type.");
                }
            }
            // Fall back to plain lower.
            return self.lowerer.lower(node);
        }
        const constraint_t = try self.lowererLowerWithTypeParams(m.constraint);
        // The type-parameter NodeId ÃÂ¢ÃÂÃÂ its `name` is the StringId we
        // bind for the value template.
        if (m.type_param == hir_mod.none_node_id or self.hir.kindOf(m.type_param) != .type_parameter) {
            return self.lowerer.lower(node);
        }
        const tp = hir_mod.typeParameterOf(self.hir, m.type_param);
        const tp_id = self.mapped_type_params.get(m.type_param) orelse blk: {
            const fresh = self.interner.internFreshTypeParameterWithFlags(
                tp.name,
                types.Primitive.unknown,
                types.Primitive.none,
                .bivariant,
                false,
            ) catch return error.OutOfMemory;
            try self.mapped_type_params.put(self.gpa, m.type_param, fresh);
            break :blk fresh;
        };
        try self.pushNarrowScope();
        defer self.popNarrowScope();
        try self.recordNarrow(tp.name, tp_id);

        // Materialize when the constraint is a string-literal union or
        // a single string-literal type.
        var literal_keys: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer literal_keys.deinit(self.gpa);
        const homomorphic_source: ?TypeId = blk: {
            if (self.hir.kindOf(m.constraint) != .keyof_type) break :blk null;
            const k = hir_mod.keyofTypeOf(self.hir, m.constraint);
            const operand = self.lowererLowerWithTypeParams(k.operand) catch break :blk null;
            if (operand < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(operand).is_object_type)
            {
                break :blk operand;
            }
            break :blk null;
        };
        var can_materialize = self.collectStringLiteralKeys(constraint_t, &literal_keys);
        if (homomorphic_source) |source_t| {
            if (self.isTupleShapedTarget(source_t)) {
                literal_keys.clearRetainingCapacity();
                for (self.interner.objectMembers(source_t)) |member| {
                    if (!self.isNumericStringId(member.name)) continue;
                    try self.appendUniqueKeyofName(&literal_keys, member.name);
                }
                can_materialize = literal_keys.items.len > 0;
            }
        }
        if (!can_materialize or literal_keys.items.len == 0) {
            if (try self.materializeBroadMappedIndexType(node, m, tp.name, constraint_t)) |broad_t| return broad_t;
            if (m.remap == hir_mod.none_node_id) {
                try self.reportMappedTypeKeyConstraintIfNeeded(m.constraint, constraint_t);
            }
            if (m.remap == hir_mod.none_node_id and self.typeNodeIndexedAccessHasMissingKeys(m.constraint)) {
                const source_name = try self.typeSyntaxOrDiagnosticName(m.constraint, constraint_t);
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Type '{s}' is not assignable to type 'string | number | symbol'.",
                    .{source_name},
                );
                try self.reportOnce(m.constraint, TsCodes.type_not_assignable, msg);
            }
            if (self.hir.kindOf(m.constraint) == .keyof_type) {
                const k = hir_mod.keyofTypeOf(self.hir, m.constraint);
                const operand = self.lowererLowerWithTypeParams(k.operand) catch types.Primitive.unknown;
                const operand_flags = if (operand < self.interner.pool.typeCount())
                    self.interner.pool.flagsOf(operand)
                else
                    std.mem.zeroes(types.TypeFlags);
                if (operand != types.Primitive.unknown and
                    operand != types.Primitive.any and
                    !operand_flags.is_type_parameter and
                    !operand_flags.is_indexed_access and
                    !operand_flags.is_keyof)
                {
                    return operand;
                }
                if (operand_flags.is_type_parameter and self.mappedTypeHasIdentityTemplate(m)) {
                    const payload = self.interner.pool.type_parameter_payloads.items[self.interner.pool.payloadOf(operand)];
                    if (payload.constraint != types.Primitive.none and
                        payload.constraint != types.Primitive.unknown and
                        payload.constraint != types.Primitive.any and
                        payload.constraint < self.interner.pool.typeCount() and
                        self.interner.pool.flagsOf(payload.constraint).is_object_type and
                        self.interner.objectNumberIndex(payload.constraint) != types.Primitive.none)
                    {
                        return operand;
                    }
                }
                const template_t = self.lowererLowerWithTypeParams(m.value) catch types.Primitive.unknown;
                if (m.remap == hir_mod.none_node_id and
                    (operand_flags.is_type_parameter or
                        operand_flags.is_indexed_access or
                        operand_flags.is_keyof or
                        self.containsFreeTypeParameter(template_t)))
                {
                    const readonly: types.ModifierState = switch (m.readonly) {
                        1 => .add,
                        2 => .remove,
                        else => .none,
                    };
                    const optional: types.ModifierState = switch (m.optional) {
                        1 => .add,
                        2 => .remove,
                        else => .none,
                    };
                    return self.interner.internMapped(constraint_t, template_t, readonly, optional) catch return error.OutOfMemory;
                }
            } else {
                const template_t = self.lowererLowerWithTypeParams(m.value) catch types.Primitive.unknown;
                const constraint_flags = if (constraint_t < self.interner.pool.typeCount())
                    self.interner.pool.flagsOf(constraint_t)
                else
                    std.mem.zeroes(types.TypeFlags);
                if (m.remap == hir_mod.none_node_id and
                    (constraint_flags.is_template_literal or constraint_flags.is_mapped or constraint_flags.is_indexed_access))
                {
                    const readonly: types.ModifierState = switch (m.readonly) {
                        1 => .add,
                        2 => .remove,
                        else => .none,
                    };
                    const optional: types.ModifierState = switch (m.optional) {
                        1 => .add,
                        2 => .remove,
                        else => .none,
                    };
                    return self.interner.internMapped(constraint_t, template_t, readonly, optional) catch return error.OutOfMemory;
                }
                if (constraint_flags.is_intersection and
                    (self.containsFreeTypeParameter(constraint_t) or self.containsFreeTypeParameter(template_t)))
                {
                    const readonly: types.ModifierState = switch (m.readonly) {
                        1 => .add,
                        2 => .remove,
                        else => .none,
                    };
                    const optional: types.ModifierState = switch (m.optional) {
                        1 => .add,
                        2 => .remove,
                        else => .none,
                    };
                    return self.interner.internMapped(constraint_t, template_t, readonly, optional) catch return error.OutOfMemory;
                }
                return self.lowerer.lower(node);
            }
            return self.lowerer.lower(node);
        }

        var built: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer built.deinit(self.gpa);
        // Modifier values: 0 = unspecified (inherit from source),
        // 1 = add, 2 = remove. The homomorphic case
        // (`{ [K in keyof T]: ... }`) inherits the source object's
        // is_optional / is_readonly when the modifier is unspecified.
        for (literal_keys.items) |key_name| {
            const key_lit = self.interner.internStringLiteral(key_name) catch continue;
            // Lower the property value with the mapped key bound to
            // the current literal. This is more faithful than lowering
            // once and substituting afterward because recursive alias
            // arguments like `DeepReadonly<T[P]>` need `T[P]` to be
            // resolved before the nested alias instantiates.
            const value_t = try self.lowerMappedPropertyValue(
                node,
                m,
                tp.name,
                key_lit,
                key_name,
                literal_keys.items.len,
            );

            // Resolve the per-key effective name. With an `as`
            // clause (TS 4.1+ key remapping), re-lower the remap
            // with `K` bound to the current key's string literal
            // so template-literal / conditional / `Exclude<K, ÃÂ¢ÃÂÃÂ¦>`
            // shapes evaluate eagerly. If the remap reduces to
            // `never` the key is dropped; otherwise the result
            // must be a string-like literal and replaces `key_name`.
            var effective_name: hir_mod.StringId = key_name;
            if (m.remap != hir_mod.none_node_id) {
                try self.pushNarrowScope();
                try self.recordNarrow(tp.name, key_lit);
                const remap_t = self.lowererLowerWithTypeParams(m.remap) catch types.Primitive.never;
                self.popNarrowScope();
                if (remap_t == types.Primitive.never) continue;
                const rf = self.interner.pool.flagsOf(remap_t);
                // Unwrap an intersection containing a string literal
                // (e.g. `K & string` after substitution).
                const named: TypeId = blk2: {
                    if (rf.is_intersection) {
                        const ms = self.interner.intersectionMembers(remap_t);
                        for (ms) |mt| {
                            const mf = self.interner.pool.flagsOf(mt);
                            if (mf.is_literal and mf.is_string) break :blk2 mt;
                        }
                    }
                    break :blk2 remap_t;
                };
                const nf = self.interner.pool.flagsOf(named);
                if (!(nf.is_literal and nf.is_string)) continue;
                const lit = self.interner.literalOf(named);
                switch (lit) {
                    .string_lit => |sid| effective_name = sid,
                    else => continue,
                }
            }
            // Inherit source flags when homomorphic + modifier
            // unspecified; apply +/- modifiers otherwise.
            var src_optional = false;
            var src_readonly = false;
            if (homomorphic_source) |src_t| {
                if (self.interner.objectMemberInfo(src_t, key_name)) |info| {
                    src_optional = info.is_optional;
                    src_readonly = info.is_readonly;
                }
            }
            const is_optional = switch (m.optional) {
                1 => true, // +?
                2 => false, // -?
                else => src_optional, // inherit (or false when no source)
            };
            const is_readonly = switch (m.readonly) {
                1 => true,
                2 => false,
                else => src_readonly,
            };
            try built.append(self.gpa, .{
                .name = effective_name,
                .type = value_t,
                .is_optional = is_optional,
                .is_readonly = is_readonly,
                .is_method = false,
            });
        }
        const number_index = if (homomorphic_source) |source_t|
            if (self.isTupleShapedTarget(source_t) and self.interner.objectNumberIndex(source_t) != types.Primitive.none)
                try self.lowerMappedIndexValue(node, m, tp.name, types.Primitive.number_t, "number")
            else
                types.Primitive.none
        else
            types.Primitive.none;
        const obj_t = self.interner.internObjectTypeWithIndex(built.items, types.Primitive.none, number_index) catch return error.OutOfMemory;
        if (homomorphic_source) |source_t| {
            if (self.tuple_trailing_variadic_types.get(source_t)) |source_rest_t| {
                if (try self.mappedTypeForHomomorphicTupleRest(m, tp.name, tp_id, source_rest_t)) |mapped_rest_t| {
                    try self.tuple_trailing_variadic_types.put(self.gpa, obj_t, mapped_rest_t);
                    try self.markTupleOrigin(obj_t);
                }
            }
        }
        if (self.hir.kindOf(m.constraint) != .keyof_type) {
            self.interner.setTypeSymbol(obj_t, @intCast(node));
        }
        return obj_t;
    }

    fn mappedTypeForHomomorphicTupleRest(
        self: *Checker,
        m: hir_mod.MappedTypePayload,
        key_name: hir_mod.StringId,
        key_t: TypeId,
        source_rest_t: TypeId,
    ) CheckError!?TypeId {
        if (self.hir.kindOf(m.constraint) != .keyof_type) return null;
        const source_node = hir_mod.keyofTypeOf(self.hir, m.constraint).operand;
        const source_name = self.bareTypeNodeName(source_node) orelse return null;

        try self.pushNarrowScope();
        defer self.popNarrowScope();
        try self.recordNarrow(source_name, source_rest_t);
        try self.recordNarrow(key_name, key_t);

        const constraint_t = try self.lowererLowerWithTypeParams(m.constraint);
        const template_t = try self.lowererLowerWithTypeParams(m.value);
        const readonly: types.ModifierState = switch (m.readonly) {
            1 => .add,
            2 => .remove,
            else => .none,
        };
        const optional: types.ModifierState = switch (m.optional) {
            1 => .add,
            2 => .remove,
            else => .none,
        };
        return self.interner.internMapped(constraint_t, template_t, readonly, optional) catch return error.OutOfMemory;
    }

    fn materializeBroadMappedIndexType(
        self: *Checker,
        node: NodeId,
        m: hir_mod.MappedTypePayload,
        type_param_name: hir_mod.StringId,
        constraint_t: TypeId,
    ) CheckError!?TypeId {
        if (m.remap != hir_mod.none_node_id) return null;
        const has_string = self.typeContainsBroadKey(constraint_t, types.Primitive.string_t);
        const has_number = self.typeContainsBroadKey(constraint_t, types.Primitive.number_t);
        const has_symbol = self.typeContainsBroadKey(constraint_t, types.Primitive.symbol_t);
        if (!has_string and !has_number and !has_symbol) return null;

        const string_idx = if (has_string)
            try self.lowerMappedIndexValue(node, m, type_param_name, types.Primitive.string_t, "string")
        else
            types.Primitive.none;
        const number_idx = if (has_number)
            try self.lowerMappedIndexValue(node, m, type_param_name, types.Primitive.number_t, "number")
        else
            types.Primitive.none;
        const symbol_idx = if (has_symbol)
            try self.lowerMappedIndexValue(node, m, type_param_name, types.Primitive.symbol_t, "symbol")
        else
            types.Primitive.none;

        const obj_t = self.interner.internObjectTypeWithIndexAndSymbol(
            &.{},
            string_idx,
            number_idx,
            symbol_idx,
        ) catch return error.OutOfMemory;
        if (m.readonly == 1) try self.readonly_index_types.put(self.gpa, obj_t, {});
        if (self.hir.kindOf(m.constraint) != .keyof_type) {
            self.interner.setTypeSymbol(obj_t, @intCast(node));
        }
        return obj_t;
    }

    fn lowerMappedIndexValue(
        self: *Checker,
        node: NodeId,
        m: hir_mod.MappedTypePayload,
        type_param_name: hir_mod.StringId,
        index_t: TypeId,
        key_text: []const u8,
    ) CheckError!TypeId {
        const key_name = self.string_interner.intern(key_text) catch return error.OutOfMemory;
        return self.lowerMappedPropertyValue(node, m, type_param_name, index_t, key_name, 1);
    }

    fn typeContainsBroadKey(self: *Checker, t: TypeId, broad_key: TypeId) bool {
        if (t == broad_key) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeContainsBroadKey(member, broad_key)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeContainsBroadKey(member, broad_key)) return true;
            }
            return false;
        }
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.typeContainsBroadKey(constraint, broad_key);
        }
        return false;
    }

    fn reportMappedTypeKeyConstraintIfNeeded(self: *Checker, node: NodeId, constraint_t: TypeId) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        if (constraint_t >= self.interner.pool.typeCount()) return;
        if (self.typeIsAnyLike(constraint_t) or self.typeIsPropertyKeyDomain(constraint_t, 0)) return;
        if (self.infer_type_parameters.contains(constraint_t)) return;
        if (self.declaredTypeParameterConstraintAt(node)) |declared| {
            if (declared.constraint != hir_mod.none_node_id and
                (self.hir.kindOf(declared.constraint) == .keyof_type or
                    self.typeNodeKeyofBaseName(declared.constraint, 0) != null))
            {
                return;
            }
        }
        if (self.typeNodeIsHomomorphicMappedKeyProjection(node)) return;
        if (!self.interner.pool.flagsOf(constraint_t).is_type_parameter) {
            const flags = self.interner.pool.flagsOf(constraint_t);
            if (flags.is_object_type and !flags.is_union and !flags.is_intersection and
                !self.containsFreeTypeParameter(constraint_t))
            {
                try self.reportInOperandLeft(node, constraint_t);
            }
            return;
        }
        if (self.conditional_branch_check_names.items.len > 0) {
            if (self.bareTypeNodeName(node)) |constraint_name| {
                for (self.conditional_branch_check_names.items) |check_name| {
                    if (check_name == constraint_name) return;
                }
            }
        }

        const key_t = try self.propertyKeyUnionType();
        if (self.typeParameterConstraint(constraint_t)) |decl_constraint| {
            if (decl_constraint == types.Primitive.any or decl_constraint == types.Primitive.never) return;
            if (self.containsFreeTypeParameter(decl_constraint)) return;
            if (decl_constraint != types.Primitive.unknown and
                (self.engine.isAssignableTo(decl_constraint, key_t) catch false))
            {
                return;
            }
        }

        for (self.diagnostics.items) |d| {
            if (d.node == node and d.code == TsCodes.type_not_assignable) return;
        }
        try self.reportInOperandLeft(node, constraint_t);
    }

    fn collectKeyofObjectKeys(
        self: *Checker,
        t: TypeId,
        out: *std.ArrayListUnmanaged(hir_mod.StringId),
    ) CheckError!bool {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            const members = self.interner.unionMembers(t);
            if (members.len == 0) return true;
            var common: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
            defer common.deinit(self.gpa);
            if (!try self.collectKeyofObjectKeys(members[0], &common)) return false;
            for (members[1..]) |member| {
                var candidate: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
                defer candidate.deinit(self.gpa);
                if (!try self.collectKeyofObjectKeys(member, &candidate)) return false;
                var write: usize = 0;
                for (common.items) |name| {
                    var present = false;
                    for (candidate.items) |candidate_name| {
                        if (candidate_name == name) {
                            present = true;
                            break;
                        }
                    }
                    if (!present) continue;
                    common.items[write] = name;
                    write += 1;
                }
                common.items.len = write;
                if (common.items.len == 0) break;
            }
            for (common.items) |name| try self.appendUniqueKeyofName(out, name);
            return true;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                _ = try self.collectKeyofObjectKeys(member, out);
            }
            return true;
        }
        if (!flags.is_object_type) return false;
        for (self.interner.objectMembers(t)) |member| {
            if (self.string_interner.getOptional(member.name)) |name| {
                if (std.mem.startsWith(u8, name, "#")) continue;
            }
            try self.appendUniqueKeyofName(out, member.name);
        }
        if (self.isTupleShapedTarget(t) or self.typeIsArrayLikeObject(t)) {
            var elem_t = self.interner.objectNumberIndex(t);
            if (elem_t == types.Primitive.none) elem_t = types.Primitive.any;
            if (lib.arrayProto(&self.lib_cache, self.interner, self.string_interner, self.gpa, elem_t, &self.rest_signatures)) |proto| {
                for (self.interner.objectMembers(proto)) |member| {
                    try self.appendUniqueKeyofName(out, member.name);
                }
            } else |_| {}
        }
        return true;
    }

    fn keyofTypeFromOperand(self: *Checker, operand: TypeId) CheckError!TypeId {
        if (operand == types.Primitive.any or operand == types.Primitive.never) {
            return try self.propertyKeyUnionType();
        }
        if (operand == types.Primitive.unknown or
            operand == types.Primitive.void_t or
            operand == types.Primitive.undefined_t or
            operand == types.Primitive.null_t)
        {
            return types.Primitive.never;
        }
        if (operand >= self.interner.pool.typeCount()) return types.Primitive.never;

        if (self.containsFreeTypeParameter(operand) and
            self.interner.pool.flagsOf(operand).is_intersection)
        {
            return self.interner.internKeyof(operand) catch return error.OutOfMemory;
        }

        var key_names: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer key_names.deinit(self.gpa);
        var key_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer key_types.deinit(self.gpa);
        try self.collectKeyofBroadIndexKeys(operand, &key_types);
        if (try self.collectKeyofObjectKeys(operand, &key_names)) {
            for (key_names.items) |name| {
                const lit = self.interner.internStringLiteral(name) catch continue;
                try self.appendUniqueTypeId(&key_types, lit);
            }
            if (key_types.items.len == 0) return types.Primitive.never;
            if (key_types.items.len == 1) return key_types.items[0];
            return self.interner.internUnion(key_types.items) catch return error.OutOfMemory;
        }
        return self.interner.internKeyof(operand) catch return error.OutOfMemory;
    }

    fn collectKeyofBroadIndexKeys(
        self: *Checker,
        t: TypeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!void {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return;
            if (constraint == t) return;
            return try self.collectKeyofBroadIndexKeys(constraint, out);
        }
        if (flags.is_union or flags.is_intersection) {
            const members = if (flags.is_union) self.interner.unionMembers(t) else self.interner.intersectionMembers(t);
            for (members) |member| try self.collectKeyofBroadIndexKeys(member, out);
            return;
        }
        if (!flags.is_object_type) return;
        if (self.interner.objectStringIndex(t) != types.Primitive.none) {
            try self.appendUniqueTypeId(out, types.Primitive.string_t);
            try self.appendUniqueTypeId(out, types.Primitive.number_t);
        } else if (self.interner.objectNumberIndex(t) != types.Primitive.none) {
            try self.appendUniqueTypeId(out, types.Primitive.number_t);
        }
        if (self.interner.objectSymbolIndex(t) != types.Primitive.none) {
            try self.appendUniqueTypeId(out, types.Primitive.symbol_t);
        }
    }

    fn appendUniqueTypeId(
        self: *Checker,
        out: *std.ArrayListUnmanaged(TypeId),
        t: TypeId,
    ) CheckError!void {
        for (out.items) |existing| {
            if (existing == t) return;
        }
        try out.append(self.gpa, t);
    }

    fn appendUniqueKeyofName(
        self: *Checker,
        out: *std.ArrayListUnmanaged(hir_mod.StringId),
        name: hir_mod.StringId,
    ) CheckError!void {
        for (out.items) |existing| {
            if (existing == name) return;
        }
        try out.append(self.gpa, name);
    }

    fn propertyKeyUnionType(self: *Checker) CheckError!TypeId {
        return self.interner.internUnion(&.{
            types.Primitive.string_t,
            types.Primitive.number_t,
            types.Primitive.symbol_t,
        }) catch return error.OutOfMemory;
    }

    fn assignmentToKeyofRestTupleShouldWidenLiteral(self: *Checker, value_node: NodeId, target_node: NodeId) bool {
        if (value_node == hir_mod.none_node_id or self.hir.kindOf(value_node) != .literal_string) return false;
        const type_node = self.visibleAnnotatedIdentifierTypeNode(target_node) orelse return false;
        if (self.hir.kindOf(type_node) != .keyof_type) return false;
        const k = hir_mod.keyofTypeOf(self.hir, type_node);
        const tuple_node = self.tupleAnnotationSourceNode(k.operand) orelse return false;
        return self.tupleTypeHasRestElement(tuple_node);
    }

    fn mappedTypeHasIdentityTemplate(self: *Checker, m: hir_mod.MappedTypePayload) bool {
        if (m.constraint == hir_mod.none_node_id or m.value == hir_mod.none_node_id or m.type_param == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(m.constraint) != .keyof_type or self.hir.kindOf(m.value) != .indexed_access_type) return false;
        const k = hir_mod.keyofTypeOf(self.hir, m.constraint);
        const ia = hir_mod.indexedAccessTypeOf(self.hir, m.value);
        const operand_name = self.bareTypeNodeName(k.operand) orelse return false;
        const object_name = self.bareTypeNodeName(ia.object) orelse return false;
        if (operand_name != object_name) return false;
        const tp = hir_mod.typeParameterOf(self.hir, m.type_param);
        const index_name = self.bareTypeNodeName(ia.index) orelse return false;
        return index_name == tp.name;
    }

    fn bareTypeNodeName(self: *Checker, node: NodeId) ?hir_mod.StringId {
        if (node == hir_mod.none_node_id) return null;
        return switch (self.hir.kindOf(node)) {
            .identifier => hir_mod.identifierOf(self.hir, node).name,
            .type_parameter => hir_mod.typeParameterOf(self.hir, node).name,
            .type_ref => blk: {
                const r = hir_mod.typeRefOf(self.hir, node);
                if (r.qualifier_len != 0 or r.args_len != 0) break :blk null;
                break :blk r.name;
            },
            else => null,
        };
    }

    /// Walk a type and accumulate the StringIds of every string-literal
    /// member. Returns false if any member isn't a string literal ÃÂ¢ÃÂÃÂ
    /// in that case the mapped type can't be materialized eagerly.
    fn collectStringLiteralKeys(
        self: *Checker,
        t: TypeId,
        out: *std.ArrayListUnmanaged(hir_mod.StringId),
    ) bool {
        if (t == types.Primitive.never) return true;
        const flags = self.interner.pool.flagsOf(t);
        // Check `is_union` *first* because the union's propagated flag
        // set OR-folds in `is_string`/`is_literal` from each member,
        // which would otherwise misroute through the literal branch.
        if (flags.is_union) {
            const members = self.interner.unionMembers(t);
            for (members) |mt| if (!self.collectStringLiteralKeys(mt, out)) return false;
            return true;
        }
        if (flags.is_intersection) {
            const members = self.interner.intersectionMembers(t);
            if (members.len == 0) return false;
            var common: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
            defer common.deinit(self.gpa);
            if (!self.collectStringLiteralKeys(members[0], &common)) return false;
            for (members[1..]) |mt| {
                var next: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
                defer next.deinit(self.gpa);
                if (!self.collectStringLiteralKeys(mt, &next)) return false;
                var write_i: usize = 0;
                for (common.items) |candidate| {
                    var found = false;
                    for (next.items) |key| {
                        if (key == candidate) {
                            found = true;
                            break;
                        }
                    }
                    if (!found) continue;
                    common.items[write_i] = candidate;
                    write_i += 1;
                }
                common.shrinkRetainingCapacity(write_i);
            }
            for (common.items) |key| out.append(self.gpa, key) catch return false;
            return true;
        }
        if (flags.is_literal and flags.is_string) {
            const lit = self.interner.literalOf(t);
            switch (lit) {
                .string_lit => |sid| {
                    out.append(self.gpa, sid) catch return false;
                    return true;
                },
                else => return false,
            }
        }
        return false;
    }

    /// True iff `target` is shaped like a lowered tuple type ÃÂ¢ÃÂÃÂ an
    /// object with at least a `length` member plus a numeric "0"
    /// positional member (variadic tuples have only a leading "0"
    /// when there's a middle/trailing rest, so we don't require
    /// a full sequence).
    fn isTupleShapedTarget(self: *Checker, target: TypeId) bool {
        const flags = self.interner.pool.flagsOf(target);
        if (!flags.is_object_type) return false;
        // A leading positional "0" member is sufficient: lowered tuples
        // always have it, and so does a sparse numeric-key object such as
        // `{ 0: string; 5: number }`, which tsc treats as a tuple-like
        // contextual target (see `unionTypeFromArrayLiteral.ts`). Check it
        // first — these targets carry no `length` member, so requiring
        // `length` up front would wrongly reject them.
        const zero_id = self.string_interner.intern("0") catch return false;
        if (self.interner.objectMember(target, zero_id) != null) return true;
        const length_id = self.string_interner.intern("length") catch return false;
        const length_t = self.interner.objectMember(target, length_id) orelse return false;
        const length_flags = self.interner.pool.flagsOf(length_t);
        return length_flags.is_literal and length_flags.is_number;
    }

    fn objectTypeIsArrayLikeContainer(self: *Checker, target: TypeId) bool {
        if (target >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(target);
        if (!flags.is_object_type or flags.is_union or flags.is_intersection or flags.is_signature) return false;
        if (self.interner.objectNumberIndex(target) == types.Primitive.none) return false;
        const length_id = self.string_interner.intern("length") catch return false;
        return self.interner.objectMember(target, length_id) != null;
    }

    /// Positional check of an `array_literal` init against a
    /// tuple-shaped target. For each element index `i`, look up
    /// the target's member named `"i"`; if missing, fall back to
    /// the target's number-key indexer (rest slot). Returns true
    /// when every element assigns.
    fn checkArrayLiteralAgainstTuple(self: *Checker, init_node: NodeId, target: TypeId) !bool {
        return try self.arrayLiteralAssignableToTupleTarget(init_node, target, false);
    }

    fn arrayLiteralAssignableToTupleTarget(
        self: *Checker,
        init_node: NodeId,
        target: TypeId,
        emit_element_diagnostic: bool,
    ) !bool {
        const elements = hir_mod.arrayLiteralElements(self.hir, init_node);
        const fixed_prefix = self.tupleFixedPrefixCount(target);
        if (elements.len < fixed_prefix) return false;
        if (self.fixedTupleLength(target)) |len| {
            if (elements.len > len) return false;
        }
        // Collect ALL element mismatches before returning, so tuple
        // assignability emits one TS2322 per misaligned element rather
        // than stopping at the first. Mirrors upstream tsc, which on
        // `var a1: [boolean, string, number] = ["string", 1, true]`
        // emits three separate TS2322 diagnostics ÃÂ¢ÃÂÃÂ one per element.
        var any_mismatch = false;
        for (elements, 0..) |el, i| {
            if (el == hir_mod.none_node_id) continue;
            const tgt_t = self.tupleElementType(target, i);
            if (tgt_t == types.Primitive.none) {
                // A tuple-shaped target that is NOT a fixed-arity tuple —
                // a plain object with sparse numeric-named members such as
                // `{ 0: string; 5: number }` — only constrains the indices
                // it actually names; an array element at an un-named index
                // is unconstrained, so it is not a mismatch. (A genuine
                // fixed-length tuple caught any excess via the length check
                // above, so a `none` there still counts.) Mirrors
                // `unionTypeFromArrayLiteral.ts`.
                if (self.fixedTupleLength(target) == null) continue;
                any_mismatch = true;
                continue;
            }
            if (self.hir.kindOf(el) == .array_literal and self.isTupleShapedTarget(tgt_t)) {
                if (try self.arrayLiteralAssignableToTupleTarget(el, tgt_t, emit_element_diagnostic)) continue;
                any_mismatch = true;
                continue;
            }
            if (try self.literalExpressionAssignableToTarget(el, tgt_t)) continue;
            var el_t = try self.checkExpression(el);
            if (try self.contextualGenericCallResult(el, el_t, tgt_t)) |contextual_t| {
                self.removeUnknownAssignabilityDiagnosticsForNode(el);
                try self.checkContextualGenericCallFunctionArgs(el, el_t, tgt_t);
                el_t = contextual_t;
            }
            const ok = try self.checkerAssignableExpressionTo(el, el_t, tgt_t);
            if (!ok) {
                if (emit_element_diagnostic) {
                    if (try self.tryReportTupleElementObjectLiteralMismatch(el, tgt_t)) {
                        // Prefer the property-level tuple element diagnostic.
                    } else {
                        try self.reportTypeNotAssignable(el, el_t, tgt_t, "Type is not assignable to tuple element type.");
                    }
                }
                any_mismatch = true;
            }
        }
        return !any_mismatch;
    }

    fn tupleAnnotationSourceNode(self: *Checker, type_node: NodeId) ?NodeId {
        if (type_node == hir_mod.none_node_id) return null;
        switch (self.hir.kindOf(type_node)) {
            .tuple_type => return type_node,
            .readonly_type => return self.tupleAnnotationSourceNode(hir_mod.readonlyTypeOf(self.hir, type_node).operand),
            .type_ref => {
                const r = hir_mod.typeRefOf(self.hir, type_node);
                if (r.qualifier_len != 0 or r.args_len != 0) return null;
                const decl = self.findTypeAliasDeclInScope(type_node, r.name) orelse return null;
                const ta = hir_mod.typeAliasOf(self.hir, decl);
                if (self.hir.kindOf(ta.aliased) == .tuple_type) return ta.aliased;
                if (self.hir.kindOf(ta.aliased) == .union_type) {
                    var tuple_member: ?NodeId = null;
                    for (hir_mod.unionTypeMembers(self.hir, ta.aliased)) |member| {
                        const candidate = self.tupleAnnotationSourceNode(member) orelse continue;
                        if (tuple_member != null) return null;
                        tuple_member = candidate;
                    }
                    return tuple_member;
                }
                return null;
            },
            else => return null,
        }
    }

    fn visibleTupleAnnotationForIdentifier(self: *Checker, node: NodeId) ?NodeId {
        const type_node = self.visibleTupleAnnotationTypeNodeForIdentifier(node) orelse return null;
        return self.tupleAnnotationSourceNode(type_node);
    }

    fn visibleTupleAnnotationDisplayTextForIdentifier(self: *Checker, node: NodeId) ?[]const u8 {
        const tuple_node = self.visibleTupleAnnotationForIdentifier(node) orelse return null;
        if (!self.tupleTypeHasRestElement(tuple_node)) return null;
        return self.visibleAnnotatedIdentifierTypeText(node);
    }

    fn visibleTupleAnnotationTypeNodeForIdentifier(self: *Checker, node: NodeId) ?NodeId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        const type_node = self.visibleAnnotatedIdentifierTypeNode(node) orelse return null;
        _ = self.tupleAnnotationSourceNode(type_node) orelse return null;
        return type_node;
    }

    fn expressionAssignableToTypeNode(self: *Checker, expr: NodeId, type_node: NodeId) CheckError!bool {
        if (self.unionAnnotationSourceNode(type_node)) |union_node| {
            var expr_t = self.hir.typeOf(expr);
            if (expr_t == types.Primitive.none) expr_t = try self.checkExpression(expr);
            for (hir_mod.unionTypeMembers(self.hir, union_node)) |member_node| {
                if (self.hir.kindOf(expr) == .array_literal) {
                    if (self.tupleAnnotationSourceNode(member_node)) |tuple_node| {
                        if (self.tupleTypeHasRestElement(tuple_node) and
                            try self.checkArrayLiteralAgainstTupleAnnotation(expr, tuple_node))
                        {
                            return true;
                        }
                    }
                }
                const member_t = try self.lowererLowerWithTypeParams(member_node);
                if (try self.literalExpressionAssignableToTarget(expr, member_t)) return true;
                if (self.engine.isAssignableTo(expr_t, member_t) catch false) return true;
            }
            return false;
        }
        const target_t = try self.lowererLowerWithTypeParams(type_node);
        if (try self.functionExpressionAssignableToTarget(expr, target_t)) return true;
        if (self.hir.kindOf(expr) == .array_literal) {
            if (self.tupleAnnotationSourceNode(type_node)) |tuple_node| {
                if (self.tupleTypeHasRestElement(tuple_node) and
                    try self.checkArrayLiteralAgainstTupleAnnotation(expr, tuple_node))
                {
                    return true;
                }
            }
            if (try self.arrayLiteralAssignableToTarget(expr, target_t)) return true;
        }
        const expr_t = try self.checkExpression(expr);
        if (try self.literalExpressionAssignableToTarget(expr, target_t)) return true;
        return self.engine.isAssignableTo(expr_t, target_t) catch return error.OutOfMemory;
    }

    fn unionAnnotationSourceNode(self: *Checker, type_node: NodeId) ?NodeId {
        if (type_node == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(type_node) == .union_type) return type_node;
        if (self.hir.kindOf(type_node) != .type_ref) return null;
        const ref = hir_mod.typeRefOf(self.hir, type_node);
        if (ref.qualifier_len != 0 or ref.args_len != 0) return null;
        const decl = self.findTypeAliasDeclInScope(type_node, ref.name) orelse return null;
        const alias = hir_mod.typeAliasOf(self.hir, decl);
        return if (self.hir.kindOf(alias.aliased) == .union_type) alias.aliased else null;
    }

    fn tupleAnnotationMinRequiredCount(self: *Checker, tuple_node: NodeId) usize {
        if (tuple_node == hir_mod.none_node_id or self.hir.kindOf(tuple_node) != .tuple_type) return 0;
        var count: usize = 0;
        for (hir_mod.tupleTypeElements(self.hir, tuple_node)) |raw_elem| {
            var elem = raw_elem;
            var is_optional = false;
            if (self.hir.kindOf(elem) == .optional_type) {
                is_optional = true;
                elem = hir_mod.optionalTypeOf(self.hir, elem).operand;
            }
            if (self.hir.kindOf(elem) == .rest_type) continue;
            if (!is_optional) count += 1;
        }
        return count;
    }

    fn tupleAnnotationDisplayText(self: *Checker, tuple_node: NodeId) ?[]const u8 {
        const src = self.source orelse return null;
        if (tuple_node == hir_mod.none_node_id or self.hir.kindOf(tuple_node) != .tuple_type) return null;
        const span = self.hir.spanOf(tuple_node);
        if (span.end > src.len or span.start > span.end) return null;
        return src[span.start..span.end];
    }

    fn tupleAnnotationElementTypeAt(
        self: *Checker,
        tuple_node: NodeId,
        element_index: usize,
        total_count: usize,
    ) CheckError!TypeId {
        if (tuple_node == hir_mod.none_node_id or self.hir.kindOf(tuple_node) != .tuple_type) return types.Primitive.none;
        const elems = hir_mod.tupleTypeElements(self.hir, tuple_node);
        var rest_i: ?usize = null;
        for (elems, 0..) |elem, i| {
            if (self.hir.kindOf(elem) == .rest_type) {
                rest_i = i;
                break;
            }
        }
        if (rest_i) |ri| {
            const suffix_len = elems.len - ri - 1;
            if (element_index < ri) return try self.lowererLowerWithTypeParams(elems[element_index]);
            if (element_index >= total_count -| suffix_len) {
                const suffix_i = element_index - (total_count - suffix_len);
                if (suffix_i < suffix_len) return try self.lowererLowerWithTypeParams(elems[ri + 1 + suffix_i]);
            }
            return try self.lowererLowerWithTypeParams(self.tupleRestElementTypeNode(elems[ri]));
        }
        if (element_index >= elems.len) return types.Primitive.none;
        return try self.lowererLowerWithTypeParams(elems[element_index]);
    }

    fn tupleRestElementTypeNode(self: *Checker, rest_node: NodeId) NodeId {
        const rt = hir_mod.restTypeOf(self.hir, rest_node);
        if (self.hir.kindOf(rt.operand) == .array_type) {
            return hir_mod.arrayTypeOf(self.hir, rt.operand).element;
        }
        return rt.operand;
    }

    fn tupleTypeHasRestElement(self: *Checker, tuple_node: NodeId) bool {
        for (hir_mod.tupleTypeElements(self.hir, tuple_node)) |elem| {
            if (self.hir.kindOf(elem) == .rest_type) return true;
        }
        return false;
    }

    fn checkArrayLiteralAgainstTupleAnnotation(self: *Checker, init_node: NodeId, tuple_node: NodeId) CheckError!bool {
        const values = hir_mod.arrayLiteralElements(self.hir, init_node);
        const elems = hir_mod.tupleTypeElements(self.hir, tuple_node);
        var rest_i: ?usize = null;
        for (elems, 0..) |elem, i| {
            if (self.hir.kindOf(elem) == .rest_type) {
                rest_i = i;
                break;
            }
        }
        const ri = rest_i orelse return true;
        const suffix_len = elems.len - ri - 1;
        if (values.len < ri + suffix_len) return false;
        var i: usize = 0;
        while (i < ri) : (i += 1) {
            if (values[i] == hir_mod.none_node_id) continue;
            if (!try self.expressionAssignableToTypeNode(values[i], elems[i])) return false;
        }
        const rest_type_node = self.tupleRestElementTypeNode(elems[ri]);
        var mid = ri;
        const mid_end = values.len - suffix_len;
        while (mid < mid_end) : (mid += 1) {
            if (values[mid] == hir_mod.none_node_id) continue;
            if (!try self.expressionAssignableToTypeNode(values[mid], rest_type_node)) return false;
        }
        var s: usize = 0;
        while (s < suffix_len) : (s += 1) {
            const value_i = values.len - suffix_len + s;
            if (values[value_i] == hir_mod.none_node_id) continue;
            if (!try self.expressionAssignableToTypeNode(values[value_i], elems[ri + 1 + s])) return false;
        }
        return true;
    }

    fn arrayLiteralVisibleTupleAnnotationAssignmentResult(self: *Checker, value_node: NodeId, target_node: NodeId) CheckError!?bool {
        if (value_node == hir_mod.none_node_id or self.hir.kindOf(value_node) != .array_literal) return null;
        const tuple_node = self.visibleTupleAnnotationForIdentifier(target_node) orelse return null;
        if (!self.tupleTypeHasRestElement(tuple_node)) return null;
        return try self.checkArrayLiteralAgainstTupleAnnotation(value_node, tuple_node);
    }

    fn tupleAnnotationPositionMismatchChain(
        self: *Checker,
        source_pos: usize,
        source_end: usize,
        target_pos: usize,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError![]const DiagnosticChainEntry {
        const arena = self.diag_arena.allocator();
        const child = try arena.alloc(DiagnosticChainEntry, 1);
        child[0] = try self.typeNotAssignableChainEntry(source_t, target_t, false);
        const msg = if (source_pos != source_end)
            try std.fmt.allocPrint(
                arena,
                "Type at positions {d} through {d} in source is not compatible with type at position {d} in target.",
                .{ source_pos, source_end, target_pos },
            )
        else
            try std.fmt.allocPrint(
                arena,
                "Type at position {d} in source is not compatible with type at position {d} in target.",
                .{ source_pos, target_pos },
            );
        const slice = try arena.alloc(DiagnosticChainEntry, 1);
        slice[0] = .{
            .code = if (source_pos != source_end) TsCodes.tuple_range_type_incompatible else TsCodes.tuple_position_type_incompatible,
            .message = msg,
            .children = child,
        };
        return slice;
    }

    fn tryReportArrayLiteralTupleAnnotationAssignmentMismatch(
        self: *Checker,
        diag_node: NodeId,
        init_node: NodeId,
        annotation_node: NodeId,
        tuple_node: NodeId,
        target_t: TypeId,
    ) CheckError!bool {
        if (init_node == hir_mod.none_node_id or self.hir.kindOf(init_node) != .array_literal) return false;
        const values = hir_mod.arrayLiteralElements(self.hir, init_node);
        const target_required = self.tupleAnnotationMinRequiredCount(tuple_node);
        var chain = try self.tupleWidthChainForArity(values.len, values.len, target_required, null);
        if (chain.len == 0) {
            const elems = hir_mod.tupleTypeElements(self.hir, tuple_node);
            var rest_i: ?usize = null;
            for (elems, 0..) |elem, i| {
                if (self.hir.kindOf(elem) == .rest_type) {
                    rest_i = i;
                    break;
                }
            }
            const ri = rest_i orelse return false;
            const suffix_len = elems.len - ri - 1;
            if (values.len < ri + suffix_len) return false;

            var i: usize = 0;
            while (i < ri) : (i += 1) {
                if (values[i] == hir_mod.none_node_id) continue;
                const source_t = try self.checkExpression(values[i]);
                const target_elem_t = try self.lowererLowerWithTypeParams(elems[i]);
                if (self.engine.isAssignableTo(source_t, target_elem_t) catch true) continue;
                try self.reportTypeNotAssignable(values[i], source_t, target_elem_t, "Type is not assignable to tuple element type.");
                return true;
            }

            const rest_type_node = self.tupleRestElementTypeNode(elems[ri]);
            const rest_target_t = try self.lowererLowerWithTypeParams(rest_type_node);
            const mid_end = values.len - suffix_len;
            var mid = ri;
            while (mid < mid_end) : (mid += 1) {
                if (values[mid] == hir_mod.none_node_id) continue;
                const source_t = try self.checkExpression(values[mid]);
                if (self.engine.isAssignableTo(source_t, rest_target_t) catch true) continue;
                chain = try self.tupleAnnotationPositionMismatchChain(ri, mid_end - 1, ri, source_t, rest_target_t);
                break;
            }

            if (chain.len == 0) {
                var s: usize = 0;
                while (s < suffix_len) : (s += 1) {
                    const value_i = values.len - suffix_len + s;
                    if (values[value_i] == hir_mod.none_node_id) continue;
                    const source_t = try self.checkExpression(values[value_i]);
                    const target_elem_t = try self.lowererLowerWithTypeParams(elems[ri + 1 + s]);
                    if (self.engine.isAssignableTo(source_t, target_elem_t) catch true) continue;
                    chain = try self.tupleAnnotationPositionMismatchChain(value_i, value_i, ri + 1 + s, source_t, target_elem_t);
                    break;
                }
            }
        }
        if (chain.len == 0) return false;
        const expands_rest_alias = self.tupleAnnotationHasArrayAliasRest(tuple_node);
        const source_name = if (values.len == 0)
            "[]"
        else if (expands_rest_alias)
            try self.arrayLiteralTupleAnnotationDisplayName(init_node, tuple_node)
        else
            try self.arrayLiteralTupleDisplayName(init_node, target_t);
        const target_name = if (expands_rest_alias)
            (try self.tupleAnnotationDiagnosticDisplayText(tuple_node)) orelse
                (self.tupleAnnotationDisplayText(annotation_node) orelse
                    ((try self.allocSimpleTypeName(target_t)) orelse
                        (self.tupleAnnotationDisplayText(tuple_node) orelse return false)))
        else
            self.tupleAnnotationDisplayText(annotation_node) orelse
                ((try self.allocSimpleTypeName(target_t)) orelse
                    (self.tupleAnnotationDisplayText(tuple_node) orelse return false));
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' is not assignable to type '{s}'.",
            .{ source_name, target_name },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = diag_node,
            .code = TsCodes.type_not_assignable,
            .message = msg,
            .chain = chain,
        });
        return true;
    }

    fn tupleAnnotationHasArrayAliasRest(self: *Checker, tuple_node: NodeId) bool {
        if (tuple_node == hir_mod.none_node_id or self.hir.kindOf(tuple_node) != .tuple_type) return false;
        for (hir_mod.tupleTypeElements(self.hir, tuple_node)) |elem| {
            if (self.hir.kindOf(elem) != .rest_type) continue;
            const rt = hir_mod.restTypeOf(self.hir, elem);
            if (self.hir.kindOf(rt.operand) != .type_ref) return false;
            const r = hir_mod.typeRefOf(self.hir, rt.operand);
            if (r.qualifier_len != 0 or r.args_len != 0) return false;
            const decl = self.typeAliasDeclForNameAt(r.name, rt.operand) orelse return false;
            const ta = hir_mod.typeAliasOf(self.hir, decl);
            return self.hir.kindOf(ta.aliased) == .array_type;
        }
        return false;
    }

    fn arrayLiteralTupleAnnotationDisplayName(
        self: *Checker,
        array_node: NodeId,
        tuple_node: NodeId,
    ) CheckError![]const u8 {
        const values = hir_mod.arrayLiteralElements(self.hir, array_node);
        const elems = hir_mod.tupleTypeElements(self.hir, tuple_node);
        var rest_i: ?usize = null;
        for (elems, 0..) |elem, i| {
            if (self.hir.kindOf(elem) == .rest_type) {
                rest_i = i;
                break;
            }
        }
        const suffix_len = if (rest_i) |ri| elems.len - ri - 1 else 0;
        const suffix_start = values.len -| suffix_len;

        var buf: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        try buf.append(arena, '[');
        for (values, 0..) |el, i| {
            if (i > 0) try buf.appendSlice(arena, ", ");
            const display_t = if (i >= suffix_start and self.hir.kindOf(el) == .literal_bool)
                self.interner.internBooleanLiteral(hir_mod.literalBoolOf(self.hir, el))
            else blk: {
                var t = self.hir.typeOf(el);
                if (t == types.Primitive.none) t = try self.checkExpression(el);
                break :blk self.widenLiteralType(t);
            };
            try buf.appendSlice(arena, (try self.simpleDiagnosticTypeName(display_t)) orelse
                (try self.allocSimpleTypeName(display_t)) orelse
                "any");
        }
        try buf.append(arena, ']');
        return buf.items;
    }

    /// Emit TS2488 "Type 'X' must have a '[Symbol.iterator]()' method
    /// that returns an iterator." ÃÂ¢ÃÂÃÂ prefers the tsc-style prose with
    /// the source type name (e.g. `'{ 0: string; 1: true; }'`,
    /// `'() => any'`). Falls back to the shorter "Type must have ÃÂ¢ÃÂÃÂ¦"
    /// form when the type can't be named. Mirrors fixtures like
    /// `iterableArrayPattern22/23`, `YieldExpression6_es6`, and
    /// the `generatorTypeCheck21` baseline.
    fn reportIteratorRequired(self: *Checker, target_node: NodeId, source_t: TypeId) CheckError!void {
        return self.reportIteratorRequiredWithSource(target_node, source_t, hir_mod.none_node_id);
    }

    /// Variant of `reportIteratorRequired` that also takes the source
    /// expression HIR node. When the source is an `object_literal`,
    /// the helper renders the shape from the HIR directly so primitive
    /// literal values (`true`, `42`, `"foo"`) keep their literal form
    /// in the diagnostic prose, matching tsc's TS2488 baselines for
    /// `iterableArrayPattern23.ts(2,1)` (`{ 0: string; 1: true; }`) and
    /// `iterableArrayPattern24.ts(2,1)` (same RHS via a rest pattern).
    fn reportIteratorRequiredWithSource(self: *Checker, target_node: NodeId, source_t: TypeId, source_node: NodeId) CheckError!void {
        if (source_node != hir_mod.none_node_id) {
            if (self.allocObjectLiteralExpressionShape(source_node) catch null) |source_name| {
                const arena = self.diag_arena.allocator();
                const msg = std.fmt.allocPrint(arena, "Type '{s}' must have a '[Symbol.iterator]()' method that returns an iterator.", .{source_name}) catch null;
                if (msg) |m| {
                    try self.reportIteratorRequiredDiagnostic(target_node, source_t, m);
                    return;
                }
            }
        }
        if (source_t != types.Primitive.none) {
            // Prefer the literal object/tuple shape (`{ 0: string; 1: true; }`)
            // when `allocSimpleTypeName` can't summarize the type ÃÂ¢ÃÂÃÂ the
            // upstream baselines for `iterableArrayPattern22/23` and the
            // `destructuringArrayBindingPatternAndAssignment*` family use
            // the structural form for object-literal sources.
            const is_union_src = source_t < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(source_t).is_union;
            const name_opt: ?[]const u8 = blk: {
                // Unions preserve `A | B` prose (`number[] | null`) so
                // fixtures like `destructuringArrayBindingPatternAndAssignment4`
                // render the full source type instead of just one member.
                if (is_union_src) {
                    if (self.simpleDiagnosticTypeName(source_t) catch null) |n| break :blk n;
                }
                if (self.allocSimpleTypeName(source_t) catch null) |n| break :blk n;
                if (self.allocObjectTypeShape(source_t) catch null) |s| break :blk s;
                break :blk null;
            };
            if (name_opt) |source_name| {
                const arena = self.diag_arena.allocator();
                const msg = std.fmt.allocPrint(arena, "Type '{s}' must have a '[Symbol.iterator]()' method that returns an iterator.", .{source_name}) catch null;
                if (msg) |m| {
                    try self.reportIteratorRequiredDiagnostic(target_node, source_t, m);
                    return;
                }
            }
        }
        try self.reportIteratorRequiredDiagnostic(target_node, source_t, "Type must have a '[Symbol.iterator]()' method that returns an iterator.");
    }

    fn reportIteratorRequiredDiagnostic(self: *Checker, target_node: NodeId, source_t: TypeId, msg: []const u8) CheckError!void {
        const related = try self.iteratorMissingNextRelatedInfo(target_node, source_t);
        try self.diagnostics.append(self.gpa, .{
            .node = target_node,
            .code = TsCodes.yield_star_not_iterable,
            .message = msg,
            .related = related,
        });
    }

    fn iteratorMissingNextRelatedInfo(self: *Checker, target_node: NodeId, source_t: TypeId) CheckError![]const RelatedInfo {
        if (!self.iteratorMethodReturnsTypeMissingNext(source_t)) return &.{};
        return self.diag_arena.allocator().dupe(RelatedInfo, &.{.{
            .node = target_node,
            .code = TsCodes.iterator_next_missing,
            .message = "An iterator must have a 'next()' method.",
        }});
    }

    fn iteratorMethodReturnsTypeMissingNext(self: *Checker, source_t: TypeId) bool {
        return self.iteratorLikeMethodReturnsTypeMissingNext(source_t, "Symbol.iterator");
    }

    fn iteratorLikeMethodReturnsTypeMissingNext(self: *Checker, source_t: TypeId, method_name: []const u8) bool {
        if (source_t == types.Primitive.any or source_t == types.Primitive.unknown) return false;
        if (source_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(source_t);
        if (flags.is_union) {
            for (self.interner.unionMembers(source_t)) |member| {
                if (self.iteratorLikeMethodReturnsTypeMissingNext(member, method_name)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(source_t)) |member| {
                if (self.iteratorLikeMethodReturnsTypeMissingNext(member, method_name)) return true;
            }
            return false;
        }
        if (!flags.is_object_type) return false;
        const method_id = self.string_interner.intern(method_name) catch return false;
        const iter_method_t = self.interner.objectMember(source_t, method_id) orelse return false;
        const iterator_t = self.iteratorMethodReturnType(iter_method_t) orelse return false;
        if (iterator_t == types.Primitive.any or iterator_t == types.Primitive.unknown) return false;
        return !self.typeHasNextMethod(iterator_t);
    }

    /// TS2504 — async-iterator analogue of `reportIteratorRequired`.
    /// Renders the source type/shape (object-literal expression shape
    /// first, then a named/structural type) into the prose, falling
    /// back to the bare form. Anchored at the source expression.
    fn reportAsyncIteratorRequired(self: *Checker, target_node: NodeId, source_t: TypeId, source_node: NodeId) CheckError!void {
        const arena = self.diag_arena.allocator();
        if (source_node != hir_mod.none_node_id) {
            if (self.allocObjectLiteralExpressionShape(source_node) catch null) |source_name| {
                if (std.fmt.allocPrint(arena, "Type '{s}' must have a '[Symbol.asyncIterator]()' method that returns an async iterator.", .{source_name}) catch null) |m| {
                    try self.reportAsyncIteratorRequiredDiagnostic(target_node, source_t, m);
                    return;
                }
            }
        }
        if (source_t != types.Primitive.none) {
            const name_opt: ?[]const u8 = blk: {
                if (self.allocSimpleTypeName(source_t) catch null) |n| break :blk n;
                if (self.allocObjectTypeShape(source_t) catch null) |s| break :blk s;
                break :blk null;
            };
            if (name_opt) |source_name| {
                if (std.fmt.allocPrint(arena, "Type '{s}' must have a '[Symbol.asyncIterator]()' method that returns an async iterator.", .{source_name}) catch null) |m| {
                    try self.reportAsyncIteratorRequiredDiagnostic(target_node, source_t, m);
                    return;
                }
            }
        }
        try self.reportAsyncIteratorRequiredDiagnostic(target_node, source_t, "Type must have a '[Symbol.asyncIterator]()' method that returns an async iterator.");
    }

    fn reportAsyncIteratorRequiredDiagnostic(self: *Checker, target_node: NodeId, source_t: TypeId, msg: []const u8) CheckError!void {
        const related = try self.asyncIteratorMissingNextRelatedInfo(target_node, source_t);
        try self.diagnostics.append(self.gpa, .{
            .node = target_node,
            .code = TsCodes.async_iterator_required,
            .message = msg,
            .related = related,
        });
    }

    fn reportGeneratorYieldTypeNotAssignable(
        self: *Checker,
        yield_node: NodeId,
        operand_node: NodeId,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError!void {
        const diag_start = self.diagnostics.items.len;
        const diagnostic_source_t = self.widenLiteralType(source_t);
        try self.reportTypeNotAssignable(
            operand_node,
            diagnostic_source_t,
            target_t,
            "Type is not assignable to generator yield type.",
        );
        if (self.hir.kindOf(yield_node) != .yield_expr or self.diagnostics.items.len == diag_start) return;
        if (hir_mod.yieldExprOf(self.hir, yield_node).type_node == hir_mod.none_node_id) return;
        if (self.yieldStarOperandStartPos(yield_node)) |pos| {
            self.diagnostics.items[self.diagnostics.items.len - 1].pos = pos;
        }
    }

    fn yieldStarOperandStartPos(self: *Checker, yield_node: NodeId) ?u32 {
        const src = self.source orelse return null;
        const span = self.hir.spanOf(yield_node);
        if (span.start >= span.end or span.end > src.len) return null;
        var pos: usize = span.start;
        while (pos < span.end and src[pos] != '*') : (pos += 1) {}
        if (pos >= span.end) return null;
        pos += 1;
        while (pos < span.end and std.ascii.isWhitespace(src[pos])) : (pos += 1) {}
        return @intCast(pos);
    }

    fn asyncIteratorMissingNextRelatedInfo(self: *Checker, target_node: NodeId, source_t: TypeId) CheckError![]const RelatedInfo {
        if (!self.iteratorLikeMethodReturnsTypeMissingNext(source_t, "Symbol.asyncIterator")) return &.{};
        return self.diag_arena.allocator().dupe(RelatedInfo, &.{.{
            .node = target_node,
            .code = TsCodes.async_iterator_next_missing,
            .message = "An async iterator must have a 'next()' method.",
        }});
    }

    fn checkBindingPatternSourceType(self: *Checker, pattern_node: NodeId, source_t: TypeId, source_node: NodeId) CheckError!bool {
        if (pattern_node == hir_mod.none_node_id) return false;
        if (source_t == types.Primitive.any or source_t == types.Primitive.unknown or source_t == types.Primitive.none) return false;
        switch (self.hir.kindOf(pattern_node)) {
            .array_pattern => {
                const has_source_iterator = source_node != hir_mod.none_node_id and self.objectLiteralHasSymbolIteratorMethod(source_node);
                if (!has_source_iterator and !self.isDestructuringIterableSourceType(source_t)) {
                    try self.reportIteratorRequiredWithSource(pattern_node, source_t, source_node);
                    return true;
                }
                try self.checkIteratorNextSentType(pattern_node, source_t, types.Primitive.undefined_t, .array_destructuring);
            },
            .object_pattern => {
                if (self.strict_flags.strict_null_checks and
                    (source_t == types.Primitive.void_t or self.typeIncludesUndefined(source_t)) and
                    !self.typeIsAnyLike(source_t))
                {
                    try self.report(pattern_node, TsCodes.object_possibly_undefined, "Object is possibly 'undefined'.");
                    return true;
                }
            },
            else => {},
        }
        return false;
    }

    fn reportTypeNotArrayForTarget(self: *Checker, target_node: NodeId, source_t: TypeId) CheckError!void {
        const name_opt: ?[]const u8 = blk: {
            if (self.allocSimpleTypeName(source_t) catch null) |n| break :blk n;
            if (self.allocObjectTypeShape(source_t) catch null) |s| break :blk s;
            break :blk null;
        };
        const msg = if (name_opt) |source_name|
            try std.fmt.allocPrint(self.diag_arena.allocator(), "Type '{s}' is not an array type.", .{source_name})
        else
            "Type is not an array type.";
        try self.report(target_node, TsCodes.type_not_array_type, msg);
    }

    fn reportForOfDestructuredElementType(self: *Checker, target_node: NodeId, source_t: TypeId, es5_for_of: bool) CheckError!void {
        if (!es5_for_of) {
            try self.reportIteratorRequired(target_node, source_t);
            return;
        }
        const uses_iterator_protocol = self.sourceDirectiveValueMentions("downlevelIteration", "true");
        if (!uses_iterator_protocol) {
            try self.reportTypeNotArrayForTarget(target_node, source_t);
            return;
        }
        const name = (try self.simpleDiagnosticTypeName(source_t)) orelse
            (try self.allocSimpleTypeName(source_t)) orelse "unknown";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' is not an array type or does not have a '[Symbol.iterator]()' method that returns an iterator.",
            .{name},
        );
        try self.report(target_node, TsCodes.type_not_array_or_iterator_type, msg);
    }

    fn reportTypeNotArrayOrStringForForOf(self: *Checker, target_node: NodeId, source_t: TypeId, source_node: NodeId) CheckError!void {
        const name_opt: ?[]const u8 = blk: {
            if (source_node != hir_mod.none_node_id and self.hir.kindOf(source_node) == .literal_number) {
                const text = std.mem.trim(u8, self.nodeSourceTextOrEmpty(source_node), " \t\r\n");
                if (text.len != 0) break :blk text;
            }
            if (self.allocSimpleTypeName(source_t) catch null) |n| break :blk n;
            if (self.allocObjectTypeShape(source_t) catch null) |s| break :blk s;
            break :blk null;
        };
        const msg = if (name_opt) |source_name|
            try std.fmt.allocPrint(self.diag_arena.allocator(), "Type '{s}' is not an array type or a string type.", .{source_name})
        else
            "Type is not an array type or a string type.";
        try self.report(target_node, TsCodes.type_not_array_or_string_type, msg);
    }

    fn checkArrayDestructuringAssignment(self: *Checker, target_node: NodeId, source_t: TypeId, source_node: NodeId, source_offset: usize) CheckError!void {
        if (source_node != hir_mod.none_node_id and self.hir.kindOf(source_node) == .identifier) {
            const declared_source_t = self.annotatedTupleUnionForIdentifier(source_node) orelse
                (self.visibleAnnotatedIdentifierType(source_node) orelse self.typeOfIdentifierDeclared(source_node));
            if (declared_source_t != types.Primitive.none and
                declared_source_t != source_t and
                declared_source_t < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(declared_source_t).is_union)
            {
                return try self.checkArrayDestructuringAssignment(target_node, declared_source_t, hir_mod.none_node_id, source_offset);
            }
        }
        if (source_node != hir_mod.none_node_id and
            self.hir.kindOf(source_node) == .object_literal and
            !self.objectLiteralHasSymbolIteratorMethod(source_node))
        {
            try self.reportIteratorRequiredWithSource(target_node, source_t, source_node);
            return;
        }
        if (source_t != types.Primitive.any and source_t != types.Primitive.unknown and
            !self.isDestructuringIterableSourceType(source_t) and !self.objectLiteralHasSymbolIteratorMethod(source_node))
        {
            try self.reportIteratorRequiredWithSource(target_node, source_t, source_node);
            return;
        }
        try self.checkIteratorNextSentType(target_node, source_t, types.Primitive.undefined_t, .array_destructuring);
        const fallback_elem_t = try self.iterableElementType(source_t);
        const target_elements = hir_mod.arrayLiteralElements(self.hir, target_node);
        // TS2493 ÃÂ¢ÃÂÃÂ array-destructuring assignment from a fixed-width
        // tuple where the binding pattern has more positions than the
        // tuple has elements (`[a, b, c] = [1]`). The tuple-out-of-
        // bounds detector already lives in `reportTupleIndexOutOfBounds`;
        // it just wasn't wired up to assignment-pattern targets yet.
        // Matches upstream baselines for `destructuringArrayBindingPatternAndAssignment1*`.
        const tuple_length_opt = if (source_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(source_t).is_object_type)
            self.fixedTupleLength(source_t)
        else
            null;
        for (target_elements, 0..) |el, i| {
            if (el == hir_mod.none_node_id) continue;
            const k = self.hir.kindOf(el);
            if (tuple_length_opt) |tuple_length| {
                if (k != .spread and k != .assignment and source_offset + i >= tuple_length) {
                    try self.reportTupleIndexOutOfBounds(el, source_t, source_offset + i, tuple_length);
                }
            }
            const union_access = if (try self.unionTupleElementAccessAt(source_t, source_offset + i)) |access| blk: {
                if (!access.found_any and k != .spread and k != .assignment) {
                    try self.reportIndexedPropertyDoesNotExistOnType(el, access.key, source_t);
                }
                break :blk access;
            } else null;
            const elem_t = if (union_access) |access| access.value_type else self.tupleElementType(source_t, source_offset + i);
            const source_elem_t = if (try self.arrayLiteralSourceElementType(source_node, source_offset + i)) |literal_elem_t|
                literal_elem_t
            else if (elem_t != types.Primitive.none)
                elem_t
            else
                fallback_elem_t;
            if (k == .spread) {
                const sp = hir_mod.spreadOf(self.hir, el);
                // tsc fires TS2462 when a rest element appears
                // before the end of an assignment-destructuring
                // pattern (`[...a, x] = ÃÂ¢ÃÂÃÂ¦`). The parser already
                // reports this for binding patterns; the
                // assignment-pattern variant lives here.
                if (i + 1 < target_elements.len) {
                    try self.report(el, TsCodes.rest_element_must_be_last, "A rest element must be last in a destructuring pattern.");
                }
                if (self.hir.kindOf(sp.expression) == .assignment) {
                    // tsc anchors TS1186 at the `=` token rather than
                    // the assignment-pattern's target identifier. Mirrors
                    // `restElementWithInitializer2.ts(3,7)`. Falls back
                    // to the assignment span when source isn't available.
                    const eq_pos = self.restElementInitializerEqualPos(sp.expression);
                    try self.reportAt(sp.expression, eq_pos, TsCodes.rest_element_cannot_have_initializer, "A rest element cannot have an initializer.");
                    continue;
                }
                const rest_source_t = try self.arrayRestSourceType(source_node, source_offset + i, source_elem_t, source_t);
                if (self.hir.kindOf(sp.expression) == .array_literal) {
                    try self.checkArrayDestructuringAssignment(sp.expression, source_t, source_node, source_offset + i);
                } else if (self.hir.kindOf(sp.expression) == .object_literal) {
                    // When the rest-target is an object pattern over a
                    // tuple source (e.g. `[...{ 0: a, b }] = tuple`),
                    // tsc indexes the source object directly so any
                    // TS2339 it raises reports the tuple type, not its
                    // array widening. Skip the widening only when the
                    // rest starts at offset 0 ÃÂ¢ÃÂÃÂ for a non-zero offset
                    // we'd need a tuple-slice helper to preserve shape.
                    // Mirrors `restElementWithAssignmentPattern4`.
                    const object_rest_t = blk: {
                        if (source_offset + i != 0) break :blk rest_source_t;
                        if (source_t == types.Primitive.none) break :blk rest_source_t;
                        if (source_t >= self.interner.pool.typeCount()) break :blk rest_source_t;
                        const flags = self.interner.pool.flagsOf(source_t);
                        if (flags.is_tuple) break :blk source_t;
                        if (flags.is_object_type and self.fixedTupleLength(source_t) != null) break :blk source_t;
                        break :blk rest_source_t;
                    };
                    try self.checkObjectDestructuringAssignment(sp.expression, object_rest_t, hir_mod.none_node_id);
                } else {
                    try self.checkDestructuringAssignmentTarget(sp.expression, rest_source_t);
                }
                continue;
            }
            if (k == .assignment) {
                const a = hir_mod.assignmentOf(self.hir, el);
                const default_t = try self.checkExpression(a.value);
                const effective_t = try self.destructuringSourceWithDefault(source_elem_t, default_t);
                try self.checkDestructuringAssignmentTargetWithDefault(a.target, a.value, effective_t, source_elem_t, default_t);
                continue;
            }
            if (k == .identifier) {
                const target_t = self.typeOfIdentifier(el);
                if (target_t == types.Primitive.none or
                    target_t == types.Primitive.any or
                    target_t == types.Primitive.unknown)
                {
                    continue;
                }
                const ok = self.engine.isAssignableTo(source_elem_t, target_t) catch return error.OutOfMemory;
                if (!ok) {
                    // Prefer the richer "Type 'X' is not assignable to
                    // type 'Y'." prose so array-destructuring assignment
                    // TS2322 sites pick up the source / target binding
                    // names. Matches upstream baselines for
                    // `iterableArrayPattern{5,6,8}.ts` and friends.
                    try self.reportTypeNotAssignable(el, source_elem_t, target_t, "Type is not assignable to target type.");
                } else {
                    const id = hir_mod.identifierOf(self.hir, el);
                    try self.recordNarrow(id.name, source_elem_t);
                }
                continue;
            }
            if (k == .array_literal) {
                try self.checkArrayDestructuringAssignment(el, source_elem_t, hir_mod.none_node_id, 0);
            } else if (k == .object_literal) {
                try self.checkObjectDestructuringAssignment(el, source_elem_t, hir_mod.none_node_id);
            }
        }
    }

    /// The type captured by an array-destructuring REST element (`[...rest]`)
    /// starting at `start_index`. When the source is a fixed tuple, the rest
    /// captures the remaining tuple SLICE (preserving each element's type),
    /// not a widened `elem[]` — mirrors tsc's sliced-tuple rest, so
    /// `[...a] = v` / `var [...a] = v` over a tuple `v` keeps `a`'s tuple
    /// shape and stays assignable to a tuple-typed target. Returns null when
    /// the source isn't a fully-fixed (no optional/rest) tuple.
    fn tupleSliceType(self: *Checker, source_t: TypeId, start: usize) CheckError!?TypeId {
        if (source_t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(source_t).is_object_type) return null;
        const len_u64 = self.fixedTupleLength(source_t) orelse return null;
        // Only slice a fully-fixed tuple — every position 0..len present and
        // non-optional. A tuple with optional/rest elements would need a
        // richer slice; fall back to the array widening there.
        if (self.tupleFixedPrefixCount(source_t) != len_u64) return null;
        const len: usize = @intCast(len_u64);
        if (start > len) return null;
        var elems: std.ArrayListUnmanaged(TypeId) = .empty;
        defer elems.deinit(self.gpa);
        var i: usize = start;
        while (i < len) : (i += 1) {
            const et = self.tupleElementType(source_t, i);
            if (et == types.Primitive.none) return null;
            try elems.append(self.gpa, et);
        }
        return try self.internTupleFromTypes(elems.items, false);
    }

    fn arrayRestSourceType(self: *Checker, source_node: NodeId, start_index: usize, fallback_elem_t: TypeId, source_t: TypeId) CheckError!TypeId {
        if (source_node != hir_mod.none_node_id and self.hir.kindOf(source_node) == .array_literal) {
            const elements = hir_mod.arrayLiteralElements(self.hir, source_node);
            var elems: std.ArrayListUnmanaged(TypeId) = .empty;
            defer elems.deinit(self.gpa);
            if (start_index < elements.len) {
                var i = start_index;
                while (i < elements.len) : (i += 1) {
                    if (elements[i] == hir_mod.none_node_id) continue;
                    try elems.append(self.gpa, try self.checkExpression(elements[i]));
                }
            }
            const elem_t = if (elems.items.len == 0)
                types.Primitive.never
            else if (elems.items.len == 1)
                elems.items[0]
            else
                self.interner.internUnion(elems.items) catch return error.OutOfMemory;
            return self.interner.internArrayType(self.string_interner, elem_t) catch return error.OutOfMemory;
        }
        // A fixed-tuple source: the rest captures the remaining tuple slice.
        if (try self.tupleSliceType(source_t, start_index)) |slice_t| return slice_t;
        return self.interner.internArrayType(self.string_interner, fallback_elem_t) catch return error.OutOfMemory;
    }

    fn arrayLiteralSourceElementType(self: *Checker, source_node: NodeId, index: usize) CheckError!?TypeId {
        if (source_node == hir_mod.none_node_id or self.hir.kindOf(source_node) != .array_literal) return null;
        const elements = hir_mod.arrayLiteralElements(self.hir, source_node);
        if (index >= elements.len or elements[index] == hir_mod.none_node_id) return types.Primitive.never;
        return try self.checkExpression(elements[index]);
    }

    fn checkObjectDestructuringAssignment(self: *Checker, target_node: NodeId, source_t: TypeId, source_node: NodeId) CheckError!void {
        if (source_t == types.Primitive.any or source_t == types.Primitive.unknown) return;
        if (source_node != hir_mod.none_node_id and self.hir.kindOf(source_node) == .object_literal) {
            // Skip the excess-properties scan when the target pattern
            // contains a rest spread (`{...rest}`) ÃÂ¢ÃÂÃÂ the rest binding
            // accepts arbitrary keys, so flagging extras as "excess"
            // surfaces spurious TS2353 against the literal RHS.
            // Mirrors tsc on `propertyAccessChain.3.ts(25-26)`.
            var target_has_spread = false;
            for (hir_mod.objectLiteralProps(self.hir, target_node)) |tprop| {
                if (self.hir.kindOf(tprop) == .spread) {
                    target_has_spread = true;
                    break;
                }
            }
            if (!target_has_spread) {
                const expected_t = try self.objectBindingPatternExpectedType(target_node, true, false);
                if (hir_mod.objectLiteralProps(self.hir, target_node).len == 0) {
                    // An empty object *assignment pattern* is a closed
                    // freshness target. This differs from a contextual `{}`
                    // type, which accepts arbitrary properties. Upstream
                    // therefore reports every RHS key in
                    // `({} = { x: 1, y: 2 })` as excess while allowing
                    // `const value: {} = { x: 1 }`.
                    for (hir_mod.objectLiteralProps(self.hir, source_node)) |source_prop| {
                        if (self.hir.kindOf(source_prop) != .object_property) continue;
                        const op = hir_mod.objectPropertyOf(self.hir, source_prop);
                        const prop_name = self.propertyNameFromKeyNode(op.key) orelse continue;
                        try self.reportObjectLiteralExcessProperty(source_prop, prop_name, expected_t);
                    }
                } else {
                    try self.checkExcessProperties(source_node, expected_t);
                }
            }
        }
        var has_dynamic_computed_key = false;
        var has_non_final_rest = false;
        const target_props_oddl = hir_mod.objectLiteralProps(self.hir, target_node);
        for (target_props_oddl, 0..) |prop_node, prop_i| {
            if (self.hir.kindOf(prop_node) != .object_property) {
                // tsc fires TS2462 when an object-rest spread
                // (`{...rest, x} = ÃÂ¢ÃÂÃÂ¦` or `{...a, x, ...b} = ÃÂ¢ÃÂÃÂ¦`)
                // appears before the end of an assignment-pattern.
                // The parser already covers binding-pattern cases.
                if (self.hir.kindOf(prop_node) == .spread and prop_i + 1 < target_props_oddl.len) {
                    try self.report(prop_node, TsCodes.rest_element_must_be_last, "A rest element must be last in a destructuring pattern.");
                    has_non_final_rest = true;
                }
                // `({...obj?.a} = ÃÂ¢ÃÂÃÂ¦)` ÃÂ¢ÃÂÃÂ tsc fires TS2778 on the
                // optional-chain inner. Distinct from the TS2779
                // emitted for plain `({a: obj?.a} = ÃÂ¢ÃÂÃÂ¦)` because the
                // rest target shape carries different runtime
                // semantics (we'd write across many properties).
                if (self.hir.kindOf(prop_node) == .spread) {
                    const inner = hir_mod.spreadOf(self.hir, prop_node).expression;
                    if (self.expressionIsOptionalChain(inner)) {
                        try self.report(inner, TsCodes.optional_chain_object_rest_target, "The target of an object rest assignment may not be an optional property access.");
                    }
                    // TS2501 — a rest element in a destructuring
                    // assignment target cannot itself be a binding
                    // pattern: `({ ...{} } = {})` / `({ ...[] } = {})`.
                    // Upstream skips parentheses and flags an object- or
                    // array-literal spread target, anchored at the spread
                    // expression. Mirrors `checkGrammarObjectLiteralExpression`.
                    if (inner != hir_mod.none_node_id) {
                        const inner_kind = self.hir.kindOf(inner);
                        if (inner_kind == .object_literal or inner_kind == .array_literal) {
                            try self.report(inner, TsCodes.rest_element_cannot_contain_binding_pattern, "A rest element cannot contain a binding pattern.");
                        } else if (!self.expressionIsOptionalChain(inner) and
                            inner_kind != .identifier and
                            inner_kind != .member_access and
                            inner_kind != .element_access)
                        {
                            // TS2701 — tsc's `checkReferenceAssignment`
                            // requires an object-rest target to be a
                            // reference expression (identifier / property
                            // / element access). A call, binary, literal,
                            // etc. target (`({...f()} = x)`,
                            // `({a, ...r.b + r.b} = o)`) is invalid.
                            // Optional chains take TS2778 above; object /
                            // array literals take TS2501 (nested pattern).
                            // Mirrors `objectRestNegative.ts(17,9)`.
                            try self.report(inner, TsCodes.object_rest_assignment_target_invalid, "The target of an object rest assignment must be a variable or a property access.");
                        }
                    }
                    // Type the rest target's member chain so access-level
                    // diagnostics fire on the chain base — e.g. TS2806 for
                    // `({ foo: { ...this.#setOnly.foo } } = …)` where
                    // reading `this.#setOnly` is required to reach `.foo`
                    // (privateWriteOnlyAccessorRead). A direct rest target
                    // `({ ...this.#x } = …)` stays a pure write because
                    // privateAccessUse sees the spread parent chain.
                    if (!has_dynamic_computed_key and
                        inner != hir_mod.none_node_id and
                        !self.expressionIsOptionalChain(inner))
                    {
                        const inner_kind = self.hir.kindOf(inner);
                        if (inner_kind == .member_access or inner_kind == .element_access) {
                            _ = try self.checkExpression(inner);
                        }
                    }
                }
                if (self.hir.kindOf(prop_node) == .spread and
                    prop_i + 1 == target_props_oddl.len and
                    !has_non_final_rest)
                {
                    const target_for_rest = hir_mod.spreadOf(self.hir, prop_node).expression;
                    const target_kind = self.hir.kindOf(target_for_rest);
                    if (!self.expressionIsOptionalChain(target_for_rest) and
                        (target_kind == .identifier or target_kind == .member_access or target_kind == .element_access))
                    {
                        const rest_t = if (has_dynamic_computed_key)
                            self.interner.internObjectType(&.{}) catch return error.OutOfMemory
                        else
                            try self.objectRestAssignmentType(target_node, source_t, prop_i);
                        // Object-rest assignments write the residual
                        // source shape into the rest target. Check that
                        // shape even without a dynamic computed key.
                        try self.checkDestructuringAssignmentTarget(target_for_rest, rest_t);
                    }
                }
                continue;
            }
            const op = hir_mod.objectPropertyOf(self.hir, prop_node);
            if (op.value == hir_mod.none_node_id) continue;
            if (op.is_computed) {
                const key_t = try self.checkExpression(op.key);
                if (key_t != types.Primitive.any and
                    try self.reportMissingIndexForComputedBindingKey(op.key, source_t, key_t))
                {
                    has_dynamic_computed_key = true;
                }
            }
            const maybe_prop_t = try self.objectPropertyTypeForDestructuring(source_t, op.key, op.is_computed);
            if (maybe_prop_t == null and self.hir.kindOf(op.value) != .assignment) {
                const prop_name = if (op.is_computed)
                    try self.propertyNameFromComputedBindingKeyNode(op.key)
                else
                    self.propertyNameFromKeyNode(op.key);
                if (prop_name) |name| {
                    const name_str = self.string_interner.get(name);
                    // Upstream tsc widens `object` to `{}` when reporting
                    // missing-property destructuring errors ÃÂ¢ÃÂÃÂ mirrors
                    // `nonPrimitiveAccessProperty.ts(5,7)`.
                    const target_text_opt: ?[]const u8 = if (source_t == types.Primitive.object_t)
                        "{}"
                    else
                        try self.allocPropertyMissingTargetTypeName(source_t);
                    const msg = if (target_text_opt) |target_text|
                        try std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "Property '{s}' does not exist on type '{s}'.",
                            .{ name_str, target_text },
                        )
                    else
                        try std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "Property '{s}' does not exist on type.",
                            .{name_str},
                        );
                    try self.diagnostics.append(self.gpa, .{
                        .node = op.key,
                        .code = TsCodes.property_does_not_exist,
                        .message = msg,
                    });
                }
            }
            if (self.hir.kindOf(op.value) == .assignment) {
                const a = hir_mod.assignmentOf(self.hir, op.value);
                const prop_t = maybe_prop_t orelse types.Primitive.undefined_t;
                const default_t = try self.checkExpression(a.value);
                const effective_t = try self.destructuringSourceWithDefault(prop_t, default_t);
                try self.checkDestructuringAssignmentTargetWithDefault(a.target, a.value, effective_t, prop_t, default_t);
                if (op.is_shorthand and
                    self.hir.kindOf(op.key) == .identifier and
                    self.hir.kindOf(a.target) == .identifier and
                    hir_mod.identifierOf(self.hir, op.key).name == hir_mod.identifierOf(self.hir, a.target).name)
                {
                    try self.rewriteMissingShorthandPropertyDiagnostic(a.target);
                }
            } else {
                const prop_t = maybe_prop_t orelse types.Primitive.any;
                try self.checkDestructuringAssignmentTarget(op.value, prop_t);
            }
        }
    }

    fn checkDestructuringAssignmentTarget(self: *Checker, target_node: NodeId, source_t: TypeId) CheckError!void {
        switch (self.hir.kindOf(target_node)) {
            .identifier, .member_access, .element_access => {
                if (self.expressionIsOptionalChain(target_node)) {
                    try self.report(target_node, TsCodes.optional_chain_assignment_target, "The left-hand side of an assignment expression may not be an optional property access.");
                }
                const target_t = if (self.hir.kindOf(target_node) == .identifier)
                    self.typeOfIdentifierDeclared(target_node)
                else
                    try self.checkExpression(target_node);
                if (target_t == types.Primitive.none or target_t == types.Primitive.any or target_t == types.Primitive.unknown) return;
                if (target_t == types.Primitive.undefined_t and
                    self.hir.kindOf(target_node) == .identifier and
                    self.identifierIsUntypedUninitializedVar(target_node))
                {
                    return;
                }
                const source_idx = if (source_t < self.interner.pool.typeCount()) self.interner.objectNumberIndex(source_t) else types.Primitive.none;
                const target_idx = if (target_t < self.interner.pool.typeCount()) self.interner.objectNumberIndex(target_t) else types.Primitive.none;
                if (source_idx != types.Primitive.none and target_idx != types.Primitive.none and
                    !(self.engine.isAssignableTo(source_idx, target_idx) catch true))
                {
                    // Use the full source/target array shapes (not the
                    // unwrapped element types) so the TS2322 prose reads
                    // `Type 'Foo[]' is not assignable to type 'string[]'.`
                    // ÃÂ¢ÃÂÃÂ matches upstream baseline `iterableArrayPattern6`.
                    try self.reportTypeNotAssignable(target_node, source_t, target_t, "Type is not assignable to target type.");
                    return;
                }
                if (!(self.engine.isAssignableTo(source_t, target_t) catch true)) {
                    if (try self.tryReportSinglePropertyMissing(target_node, hir_mod.none_node_id, source_t, target_t)) return;
                    try self.reportTypeNotAssignable(target_node, source_t, target_t, "Type is not assignable to target type.");
                } else if (self.hir.kindOf(target_node) == .identifier and
                    source_t != types.Primitive.none and
                    source_t != types.Primitive.any and
                    source_t != types.Primitive.unknown and
                    !self.shouldKeepDeclaredFunctionTargetForDestructuring(source_t, target_t))
                {
                    const id = hir_mod.identifierOf(self.hir, target_node);
                    try self.recordNarrow(id.name, source_t);
                }
            },
            .array_literal => try self.checkArrayDestructuringAssignment(target_node, source_t, hir_mod.none_node_id, 0),
            .object_literal => try self.checkObjectDestructuringAssignment(target_node, source_t, hir_mod.none_node_id),
            else => {},
        }
    }

    /// Destructuring-assignment-target check that knows the effective
    /// source was synthesized from `(source | widened-default)`. When
    /// the union fails to assign but ONE constituent alone succeeds,
    /// tsc renders only the failing constituent. For
    /// `for ([k = false] of map)` where source elem is `string` and
    /// `k: string`, the default's widened type `boolean` is the
    /// failing side ÃÂ¢ÃÂÃÂ that's what the diagnostic mentions.
    fn checkDestructuringAssignmentTargetWithDefault(self: *Checker, target_node: NodeId, default_node: NodeId, effective_t: TypeId, source_only_t: TypeId, default_t: TypeId) CheckError!void {
        const tk = self.hir.kindOf(target_node);
        if (tk != .identifier and tk != .member_access and tk != .element_access) {
            try self.checkDestructuringAssignmentTarget(target_node, effective_t);
            return;
        }
        const target_t = if (tk == .identifier)
            self.typeOfIdentifierDeclared(target_node)
        else
            try self.checkExpression(target_node);
        if (target_t == types.Primitive.none or target_t == types.Primitive.any or target_t == types.Primitive.unknown) {
            try self.checkDestructuringAssignmentTarget(target_node, effective_t);
            return;
        }
        if (target_t == types.Primitive.undefined_t and
            tk == .identifier and
            self.identifierIsUntypedUninitializedVar(target_node))
        {
            return;
        }
        if (self.engine.isAssignableTo(effective_t, target_t) catch true) {
            try self.checkDestructuringAssignmentTarget(target_node, effective_t);
            return;
        }
        const source_no_undef = self.subtractType(source_only_t, types.Primitive.undefined_t) catch source_only_t;
        const widened_default = self.widenLiteralType(default_t);
        const source_ok = if (source_no_undef == types.Primitive.never or source_no_undef == types.Primitive.none) true else (self.engine.isAssignableTo(source_no_undef, target_t) catch true);
        const default_ok = if (widened_default == types.Primitive.never or widened_default == types.Primitive.none) true else (self.engine.isAssignableTo(widened_default, target_t) catch true);
        if (source_ok and !default_ok) {
            if (try self.tryReportObjectLiteralPropertyMismatch(default_node, target_t)) return;
            try self.reportTypeNotAssignable(target_node, widened_default, target_t, "Type is not assignable to target type.");
            return;
        }
        if (default_ok and !source_ok) {
            try self.reportTypeNotAssignable(target_node, source_no_undef, target_t, "Type is not assignable to target type.");
            return;
        }
        try self.checkDestructuringAssignmentTarget(target_node, effective_t);
    }

    fn shouldKeepDeclaredFunctionTargetForDestructuring(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
        if (source_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(source_t).is_signature) return false;
        return self.typeIsBuiltinFunctionObject(target_t);
    }

    fn typeIsBuiltinFunctionObject(self: *Checker, t: TypeId) bool {
        return self.typeIsBuiltinFunctionObjectDepth(t, 0);
    }

    fn typeIsBuiltinFunctionObjectDepth(self: *Checker, t: TypeId, depth: u8) bool {
        if (depth >= 16) return false;
        if (t >= self.interner.pool.typeCount()) return false;
        if (self.builtin_object_names.get(t)) |name| {
            if (std.mem.eql(u8, name, "Function")) return true;
        }
        if (self.decl_single_base.get(t)) |base_t| {
            if (base_t != t and self.typeIsBuiltinFunctionObjectDepth(base_t, depth + 1)) return true;
        }
        if (!self.interner.pool.flagsOf(t).is_object_type) return false;
        const call_id = self.string_interner.intern("__call") catch return false;
        const proto_call_id = self.string_interner.intern("call") catch return false;
        return self.interner.objectMember(t, call_id) != null and
            self.interner.objectMember(t, proto_call_id) != null;
    }

    fn reportConditionalTypeParameterObjectReturnMismatches(self: *Checker, value_node: NodeId, declared: TypeId) CheckError!bool {
        if (self.hir.kindOf(value_node) != .conditional) return false;
        const is_object_wrapper = if (self.builtin_object_names.get(declared)) |name|
            std.mem.eql(u8, name, "Object")
        else if (self.namedTypeForId(declared)) |name|
            std.mem.eql(u8, self.string_interner.get(name), "Object")
        else if (self.alias_display_names.get(declared)) |name|
            std.mem.eql(u8, name, "Object")
        else
            false;
        if (!is_object_wrapper) return false;

        const conditional = hir_mod.conditionalOf(self.hir, value_node);
        var reported = false;
        for ([_]NodeId{ conditional.then_branch, conditional.else_branch }) |branch| {
            const branch_t = self.hir.typeOf(branch);
            if (branch_t >= self.interner.pool.typeCount()) continue;
            if (!self.interner.pool.flagsOf(branch_t).is_type_parameter) continue;
            if (self.typeParameterConstraint(branch_t)) |constraint| {
                if (self.engine.isAssignableTo(constraint, declared) catch false) continue;
            }
            try self.reportTypeNotAssignable(branch, branch_t, declared, "Type is not assignable to function return type.");
            reported = true;
        }
        return reported;
    }

    fn objectBindingPatternExpectedType(
        self: *Checker,
        pattern_node: NodeId,
        include_empty: bool,
        untyped_binding_identifiers_as_any: bool,
    ) CheckError!TypeId {
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        const elems: []const NodeId = switch (self.hir.kindOf(pattern_node)) {
            .object_pattern => hir_mod.patternElements(self.hir, pattern_node),
            .object_literal => hir_mod.objectLiteralProps(self.hir, pattern_node),
            else => &.{},
        };
        for (elems) |elem| {
            if (self.hir.kindOf(elem) == .parameter) {
                const p = hir_mod.parameterOf(self.hir, elem);
                if (p.flags.is_rest or p.name == hir_mod.none_node_id) continue;
                const key_name = (try self.objectBindingElementKeyName(elem, p.name)) orelse continue;
                const target_node = if (p.default_value != hir_mod.none_node_id and self.hir.kindOf(p.default_value) == .assignment)
                    hir_mod.assignmentOf(self.hir, p.default_value).target
                else
                    p.name;
                const member_t = try self.destructuringTargetExpectedType(target_node, untyped_binding_identifiers_as_any);
                try members.append(self.gpa, .{ .name = key_name, .type = member_t, .is_optional = false, .is_readonly = false, .is_method = false });
            } else if (self.hir.kindOf(elem) == .object_property) {
                const op = hir_mod.objectPropertyOf(self.hir, elem);
                if (op.value == hir_mod.none_node_id) continue;
                const key_name = if (op.is_computed)
                    try self.propertyNameFromComputedBindingKeyNode(op.key)
                else
                    self.propertyNameFromKeyNode(op.key);
                const name = key_name orelse continue;
                const target_node = if (self.hir.kindOf(op.value) == .assignment)
                    hir_mod.assignmentOf(self.hir, op.value).target
                else
                    op.value;
                const member_t = try self.destructuringTargetExpectedType(target_node, untyped_binding_identifiers_as_any);
                try members.append(self.gpa, .{ .name = name, .type = member_t, .is_optional = false, .is_readonly = false, .is_method = false });
            }
        }
        if (members.items.len == 0 and !include_empty) return types.Primitive.none;
        return self.interner.internObjectType(members.items) catch return error.OutOfMemory;
    }

    fn destructuringTargetExpectedType(
        self: *Checker,
        target_node: NodeId,
        untyped_binding_identifiers_as_any: bool,
    ) CheckError!TypeId {
        if (target_node == hir_mod.none_node_id) return types.Primitive.any;
        return switch (self.hir.kindOf(target_node)) {
            .identifier, .member_access, .element_access => blk: {
                if (untyped_binding_identifiers_as_any and self.hir.kindOf(target_node) == .identifier) {
                    break :blk types.Primitive.any;
                }
                const t = if (self.hir.kindOf(target_node) == .identifier)
                    self.typeOfIdentifierDeclared(target_node)
                else
                    try self.checkExpression(target_node);
                break :blk if (t == types.Primitive.none or t == types.Primitive.undefined_t) types.Primitive.any else t;
            },
            .object_literal, .object_pattern => try self.objectBindingPatternExpectedType(target_node, true, untyped_binding_identifiers_as_any),
            .array_pattern => try self.arrayBindingPatternParameterType(target_node),
            .array_literal => self.interner.internArrayType(self.string_interner, types.Primitive.any) catch return error.OutOfMemory,
            else => types.Primitive.any,
        };
    }

    fn identifierIsUntypedUninitializedVar(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, node);
        const use_start = self.hir.spanOf(node).start;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const stmts: ?[]const NodeId = switch (self.hir.kindOf(cur)) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl => hir_mod.namespaceBody(self.hir, cur),
                else => null,
            };
            if (stmts) |items| {
                for (items) |stmt| {
                    if (self.hir.spanOf(stmt).start >= use_start) break;
                    const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
                    if (decl == hir_mod.none_node_id) continue;
                    const dk = self.hir.kindOf(decl);
                    if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
                    const v = hir_mod.varDeclOf(self.hir, decl);
                    if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, v.name).name != id.name) continue;
                    return self.varDeclIsUntypedEvolvingAnyCandidate(decl);
                }
                continue;
            }
        }
        return false;
    }

    fn recordUntypedUninitializedVarAssignment(self: *Checker, node: NodeId, value_t: TypeId) CheckError!void {
        const decl = self.previousUntypedUninitializedVarDeclInNearestScope(node) orelse return;
        const v = hir_mod.varDeclOf(self.hir, decl);
        self.hir.setType(decl, value_t);
        if (v.name != hir_mod.none_node_id) self.hir.setType(v.name, value_t);
    }

    fn previousUntypedUninitializedVarDeclInNearestScope(self: *Checker, node: NodeId) ?NodeId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        const id = hir_mod.identifierOf(self.hir, node);
        const use_start = self.hir.spanOf(node).start;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const stmts: []const NodeId = switch (self.hir.kindOf(cur)) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl => hir_mod.namespaceBody(self.hir, cur),
                else => continue,
            };
            for (stmts) |stmt| {
                if (self.hir.spanOf(stmt).start >= use_start) break;
                const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
                if (decl == hir_mod.none_node_id) continue;
                const dk = self.hir.kindOf(decl);
                if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
                const v = hir_mod.varDeclOf(self.hir, decl);
                if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
                if (hir_mod.identifierOf(self.hir, v.name).name != id.name) continue;
                if (!self.varDeclIsUntypedEvolvingAnyCandidate(decl)) return null;
                return decl;
            }
            return null;
        }
        return null;
    }

    fn varDeclIsUntypedEvolvingAnyCandidate(self: *Checker, decl: NodeId) bool {
        const dk = self.hir.kindOf(decl);
        if (dk != .var_decl and dk != .let_decl) return false;
        const v = hir_mod.varDeclOf(self.hir, decl);
        if (v.type_annotation != hir_mod.none_node_id) return false;
        if (self.varDeclHasJsDocTypeTag(decl)) return false;
        if (v.init == hir_mod.none_node_id) return true;
        return self.hir.kindOf(v.init) == .literal_undefined or self.hir.kindOf(v.init) == .literal_null;
    }

    fn varDeclIsCapturedEvolvingAnyCandidate(self: *Checker, decl: NodeId) bool {
        const dk = self.hir.kindOf(decl);
        if (dk != .var_decl and dk != .let_decl) return false;
        const v = hir_mod.varDeclOf(self.hir, decl);
        if (v.type_annotation != hir_mod.none_node_id) return false;
        if (self.varDeclHasJsDocTypeTag(decl)) return false;
        if (v.init == hir_mod.none_node_id) return true;
        return self.hir.kindOf(v.init) == .array_literal and
            hir_mod.arrayLiteralElements(self.hir, v.init).len == 0;
    }

    fn mergeDefiniteEvolvingAnyFlowTypes(self: *Checker, lhs: ?TypeId, rhs: ?TypeId) CheckError!?TypeId {
        const left = lhs orelse return null;
        const right = rhs orelse return null;
        if (left == right) return left;
        if (self.typeIsAnyLike(left) or self.typeIsAnyLike(right)) return types.Primitive.any;
        return self.interner.internUnion(&.{ left, right }) catch return error.OutOfMemory;
    }

    fn evolvingAnyFlowTypeAfterStatement(
        self: *Checker,
        stmt: NodeId,
        name: hir_mod.StringId,
        incoming: ?TypeId,
    ) CheckError!?TypeId {
        if (stmt == hir_mod.none_node_id) return incoming;
        return switch (self.hir.kindOf(stmt)) {
            .assignment => blk: {
                const assignment = hir_mod.assignmentOf(self.hir, stmt);
                if (assignment.op != null or self.hir.kindOf(assignment.target) != .identifier or
                    hir_mod.identifierOf(self.hir, assignment.target).name != name)
                {
                    break :blk incoming;
                }
                const value_t = self.hir.typeOf(assignment.value);
                break :blk if (value_t == types.Primitive.none) types.Primitive.any else value_t;
            },
            .block_stmt => blk: {
                var flow = incoming;
                for (hir_mod.blockStmts(self.hir, stmt)) |child| {
                    flow = try self.evolvingAnyFlowTypeAfterStatement(child, name, flow);
                }
                break :blk flow;
            },
            .if_stmt => blk: {
                const conditional = hir_mod.ifOf(self.hir, stmt);
                const then_t = try self.evolvingAnyFlowTypeAfterStatement(conditional.then_branch, name, incoming);
                const else_t = if (conditional.else_branch != hir_mod.none_node_id)
                    try self.evolvingAnyFlowTypeAfterStatement(conditional.else_branch, name, incoming)
                else
                    incoming;
                break :blk try self.mergeDefiniteEvolvingAnyFlowTypes(then_t, else_t);
            },
            .for_stmt => try self.evolvingAnyFlowTypeAfterStatement(hir_mod.forStmtOf(self.hir, stmt).body, name, incoming),
            .for_in_stmt, .for_of_stmt => try self.evolvingAnyFlowTypeAfterStatement(hir_mod.forInOf(self.hir, stmt).body, name, incoming),
            .while_stmt => try self.evolvingAnyFlowTypeAfterStatement(hir_mod.whileOf(self.hir, stmt).body, name, incoming),
            .do_while_stmt => try self.evolvingAnyFlowTypeAfterStatement(hir_mod.doWhileOf(self.hir, stmt).body, name, incoming),
            else => incoming,
        };
    }

    fn evolvingAnyFlowTypeBeforeNode(
        self: *Checker,
        container: NodeId,
        node: NodeId,
        name: hir_mod.StringId,
        incoming: ?TypeId,
    ) CheckError!?TypeId {
        if (container == hir_mod.none_node_id or container == node) return incoming;
        const use_span = self.hir.spanOf(node);
        return switch (self.hir.kindOf(container)) {
            .block_stmt => blk: {
                var flow = incoming;
                for (hir_mod.blockStmts(self.hir, container)) |stmt| {
                    const span = self.hir.spanOf(stmt);
                    if (span.start <= use_span.start and use_span.start <= span.end) {
                        break :blk try self.evolvingAnyFlowTypeBeforeNode(stmt, node, name, flow);
                    }
                    if (span.end <= use_span.start) {
                        flow = try self.evolvingAnyFlowTypeAfterStatement(stmt, name, flow);
                    }
                }
                break :blk flow;
            },
            .if_stmt => blk: {
                const conditional = hir_mod.ifOf(self.hir, container);
                const then_span = self.hir.spanOf(conditional.then_branch);
                if (then_span.start <= use_span.start and use_span.start <= then_span.end) {
                    break :blk try self.evolvingAnyFlowTypeBeforeNode(conditional.then_branch, node, name, incoming);
                }
                if (conditional.else_branch != hir_mod.none_node_id) {
                    const else_span = self.hir.spanOf(conditional.else_branch);
                    if (else_span.start <= use_span.start and use_span.start <= else_span.end) {
                        break :blk try self.evolvingAnyFlowTypeBeforeNode(conditional.else_branch, node, name, incoming);
                    }
                }
                break :blk incoming;
            },
            .for_stmt => blk: {
                const body = hir_mod.forStmtOf(self.hir, container).body;
                const backedge = try self.evolvingAnyFlowTypeAfterStatement(body, name, incoming);
                const loop_entry = try self.mergeDefiniteEvolvingAnyFlowTypes(incoming, backedge);
                break :blk try self.evolvingAnyFlowTypeBeforeNode(body, node, name, loop_entry orelse backedge);
            },
            .for_in_stmt, .for_of_stmt => blk: {
                const body = hir_mod.forInOf(self.hir, container).body;
                const backedge = try self.evolvingAnyFlowTypeAfterStatement(body, name, incoming);
                const loop_entry = try self.mergeDefiniteEvolvingAnyFlowTypes(incoming, backedge);
                break :blk try self.evolvingAnyFlowTypeBeforeNode(body, node, name, loop_entry orelse backedge);
            },
            .while_stmt => blk: {
                const body = hir_mod.whileOf(self.hir, container).body;
                const backedge = try self.evolvingAnyFlowTypeAfterStatement(body, name, incoming);
                const loop_entry = try self.mergeDefiniteEvolvingAnyFlowTypes(incoming, backedge);
                break :blk try self.evolvingAnyFlowTypeBeforeNode(body, node, name, loop_entry orelse backedge);
            },
            .do_while_stmt => blk: {
                const body = hir_mod.doWhileOf(self.hir, container).body;
                const backedge = try self.evolvingAnyFlowTypeAfterStatement(body, name, incoming);
                const loop_entry = try self.mergeDefiniteEvolvingAnyFlowTypes(incoming, backedge);
                break :blk try self.evolvingAnyFlowTypeBeforeNode(body, node, name, loop_entry orelse backedge);
            },
            else => incoming,
        };
    }

    fn definiteEvolvingAnyFlowTypeAt(self: *Checker, node: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        var child = node;
        var current = self.hir.parentOf(node);
        while (current != hir_mod.none_node_id) : ({
            child = current;
            current = self.hir.parentOf(current);
        }) {
            const current_kind = self.hir.kindOf(current);
            if (current_kind == .fn_decl or current_kind == .fn_expr or current_kind == .arrow_fn) {
                for (hir_mod.fnParams(self.hir, current)) |param| {
                    if (self.hir.kindOf(param) != .parameter) continue;
                    const p = hir_mod.parameterOf(self.hir, param);
                    if (p.name == hir_mod.none_node_id or self.hir.kindOf(p.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, p.name).name == name) return null;
                }
            }
            const statements: []const NodeId = switch (self.hir.kindOf(current)) {
                .block_stmt => hir_mod.blockStmts(self.hir, current),
                .namespace_decl => hir_mod.namespaceBody(self.hir, current),
                else => continue,
            };
            if (try self.definiteEvolvingAnyFlowTypeInStatements(node, child, name, statements)) |flow| return flow;
        }

        const use_span = self.hir.spanOf(node);
        var best_container = hir_mod.none_node_id;
        var best_width: u32 = std.math.maxInt(u32);
        var candidate: NodeId = 1;
        while (candidate < self.hir.nodeCount()) : (candidate += 1) {
            const kind = self.hir.kindOf(candidate);
            if (kind != .block_stmt and kind != .namespace_decl) continue;
            const span = self.hir.spanOf(candidate);
            if (span.start > use_span.start or use_span.end > span.end) continue;
            const statements = if (kind == .block_stmt)
                hir_mod.blockStmts(self.hir, candidate)
            else
                hir_mod.namespaceBody(self.hir, candidate);
            if (try self.definiteEvolvingAnyFlowTypeInStatements(node, hir_mod.none_node_id, name, statements)) |_| {
                const width = span.end - span.start;
                if (width < best_width) {
                    best_width = width;
                    best_container = candidate;
                }
            }
        }
        if (best_container != hir_mod.none_node_id) {
            const kind = self.hir.kindOf(best_container);
            const statements = if (kind == .block_stmt)
                hir_mod.blockStmts(self.hir, best_container)
            else
                hir_mod.namespaceBody(self.hir, best_container);
            return try self.definiteEvolvingAnyFlowTypeInStatements(node, hir_mod.none_node_id, name, statements);
        }
        return try self.recoveredEvolvingAnyFlowTypeAt(node, name);
    }

    fn recoveredEvolvingAnyFlowTypeAt(self: *Checker, node: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        const use_start = self.hir.spanOf(node).start;
        var declaration = hir_mod.none_node_id;
        var declaration_start: u32 = 0;
        var candidate: NodeId = 1;
        while (candidate < self.hir.nodeCount()) : (candidate += 1) {
            const kind = self.hir.kindOf(candidate);
            if (kind != .var_decl and kind != .let_decl) continue;
            const span = self.hir.spanOf(candidate);
            if (span.start >= use_start or span.start < declaration_start) continue;
            const variable = hir_mod.varDeclOf(self.hir, candidate);
            if (variable.name == hir_mod.none_node_id or self.hir.kindOf(variable.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, variable.name).name != name) continue;
            if (!self.varDeclIsUntypedEvolvingAnyCandidate(candidate)) continue;
            declaration = candidate;
            declaration_start = span.start;
        }
        if (declaration == hir_mod.none_node_id) return null;

        const recovered_variable = hir_mod.varDeclOf(self.hir, declaration);
        var flow: ?TypeId = if (recovered_variable.init == hir_mod.none_node_id)
            null
        else switch (self.hir.kindOf(recovered_variable.init)) {
            .literal_null => types.Primitive.null_t,
            .literal_undefined => types.Primitive.undefined_t,
            else => null,
        };
        candidate = 1;
        while (candidate < self.hir.nodeCount()) : (candidate += 1) {
            if (self.hir.kindOf(candidate) != .assignment) continue;
            const span = self.hir.spanOf(candidate);
            if (span.start <= declaration_start or span.start >= use_start) continue;
            const assignment = hir_mod.assignmentOf(self.hir, candidate);
            if (assignment.op != null or assignment.target == hir_mod.none_node_id or
                self.hir.kindOf(assignment.target) != .identifier or
                hir_mod.identifierOf(self.hir, assignment.target).name != name)
            {
                continue;
            }
            if (flow != null and self.nodeContainsIdentifier(assignment.value, name)) continue;
            const cached_value_t = self.hir.typeOf(assignment.value);
            const value_t = if (cached_value_t == types.Primitive.none) types.Primitive.any else cached_value_t;
            flow = if (flow == null)
                value_t
            else
                try self.mergeDefiniteEvolvingAnyFlowTypes(flow, value_t);
        }
        if (flow == null) {
            const source = self.source orelse return null;
            const name_text = self.string_interner.get(name);
            var cursor: usize = @intCast(@min(self.hir.spanOf(declaration).end, use_start));
            const raw_end: usize = @intCast(use_start);
            const end = @min(raw_end, source.len);
            while (cursor < end) {
                const relative = std.mem.indexOf(u8, source[cursor..end], name_text) orelse break;
                const found = cursor + relative;
                cursor = found + name_text.len;
                if (found > 0 and (std.ascii.isAlphanumeric(source[found - 1]) or source[found - 1] == '_' or source[found - 1] == '$')) continue;
                while (cursor < end and std.ascii.isWhitespace(source[cursor])) cursor += 1;
                if (cursor < end and source[cursor] == '=' and
                    (cursor + 1 >= end or (source[cursor + 1] != '=' and source[cursor + 1] != '>')))
                {
                    return types.Primitive.any;
                }
            }
        }
        return flow;
    }

    fn definiteEvolvingAnyFlowTypeInStatements(
        self: *Checker,
        node: NodeId,
        direct_child: NodeId,
        name: hir_mod.StringId,
        statements: []const NodeId,
    ) CheckError!?TypeId {
        const use_span = self.hir.spanOf(node);
        var declaration_index: ?usize = null;
        var use_index: ?usize = null;
        for (statements, 0..) |raw, index| {
            const span = self.hir.spanOf(raw);
            if (raw == direct_child or
                (span.start <= use_span.start and use_span.end <= span.end))
            {
                use_index = index;
            }
            const declaration = self.unwrapExportDecl(raw);
            const kind = self.hir.kindOf(declaration);
            if (kind != .var_decl and kind != .let_decl) continue;
            const variable = hir_mod.varDeclOf(self.hir, declaration);
            if (variable.name == hir_mod.none_node_id or self.hir.kindOf(variable.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, variable.name).name != name) continue;
            if (!self.varDeclIsUntypedEvolvingAnyCandidate(declaration)) return null;
            declaration_index = index;
        }
        const declaration_pos = declaration_index orelse return null;
        const use_pos = use_index orelse return null;
        if (declaration_pos >= use_pos) return null;
        const declaration = self.unwrapExportDecl(statements[declaration_pos]);
        const variable = hir_mod.varDeclOf(self.hir, declaration);
        var flow: ?TypeId = if (variable.init == hir_mod.none_node_id)
            null
        else switch (self.hir.kindOf(variable.init)) {
            .literal_null => types.Primitive.null_t,
            .literal_undefined => types.Primitive.undefined_t,
            else => null,
        };
        for (statements[declaration_pos + 1 .. use_pos]) |stmt| {
            flow = try self.evolvingAnyFlowTypeAfterStatement(stmt, name, flow);
        }
        return try self.evolvingAnyFlowTypeBeforeNode(statements[use_pos], node, name, flow);
    }

    fn untypedVarHasLaterDirectAssignment(self: *Checker, decl: NodeId, name: hir_mod.StringId) bool {
        const parent = self.hir.parentOf(decl);
        if (parent == hir_mod.none_node_id) return false;
        const stmts: []const NodeId = switch (self.hir.kindOf(parent)) {
            .block_stmt => hir_mod.blockStmts(self.hir, parent),
            .namespace_decl => hir_mod.namespaceBody(self.hir, parent),
            else => return false,
        };
        const decl_start = self.hir.spanOf(decl).start;
        for (stmts) |raw_stmt| {
            if (self.hir.spanOf(raw_stmt).start <= decl_start) continue;
            const stmt = self.unwrapExportDecl(raw_stmt);
            if (stmt == hir_mod.none_node_id or self.hir.kindOf(stmt) != .assignment) continue;
            const assignment = hir_mod.assignmentOf(self.hir, stmt);
            if (assignment.op != null or assignment.target == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(assignment.target) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, assignment.target).name == name) return true;
        }
        return false;
    }

    fn untypedVarHasLaterClassFallbackRead(self: *Checker, decl: NodeId, name: hir_mod.StringId) bool {
        const decl_end = self.hir.spanOf(decl).end;
        const section = self.virtualSectionStartForNode(decl);
        var node: NodeId = 0;
        while (node < self.hir.nodeCount()) : (node += 1) {
            if (self.hir.kindOf(node) != .identifier or self.hir.spanOf(node).start < decl_end) continue;
            if (self.virtualSectionStartForNode(node) != section) continue;
            if (hir_mod.identifierOf(self.hir, node).name != name) continue;

            const logical_node = self.hir.parentOf(node);
            if (logical_node == hir_mod.none_node_id or self.hir.kindOf(logical_node) != .logical_op) continue;
            const logical = hir_mod.logicalOf(self.hir, logical_node);
            if (logical.op != .@"or" or logical.lhs != node) continue;
            if (self.hir.kindOf(logical.rhs) != .class_expr) continue;

            const assignment_node = self.hir.parentOf(logical_node);
            if (assignment_node == hir_mod.none_node_id or self.hir.kindOf(assignment_node) != .assignment) continue;
            if (hir_mod.assignmentOf(self.hir, assignment_node).value == logical_node) return true;
        }
        return false;
    }

    /// A direct JSX spread read of an uninitialized evolving-any binding owns
    /// the error as TS2698 at the spread operand. When that is the binding's
    /// only later reference, tsc does not also emit TS7034 at the declaration.
    fn untypedVarIsReadOnlyByJsxSpread(self: *Checker, decl: NodeId, name: hir_mod.StringId) bool {
        const decl_end = self.hir.spanOf(decl).end;
        const section = self.virtualSectionStartForNode(decl);
        var saw_spread_read = false;
        var node: NodeId = 0;
        while (node < self.hir.nodeCount()) : (node += 1) {
            if (self.hir.kindOf(node) != .identifier or self.hir.spanOf(node).start < decl_end) continue;
            if (self.virtualSectionStartForNode(node) != section) continue;
            if (hir_mod.identifierOf(self.hir, node).name != name) continue;
            const parent = self.hir.parentOf(node);
            if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .jsx_spread_attribute) return false;
            if (hir_mod.jsxSpreadAttributeOf(self.hir, parent).expression != node) return false;
            saw_spread_read = true;
        }
        return saw_spread_read;
    }

    fn destructuringSourceWithDefault(self: *Checker, source_t: TypeId, default_t: TypeId) !TypeId {
        if (source_t == types.Primitive.any or source_t == types.Primitive.unknown) return source_t;
        if (default_t == types.Primitive.any or default_t == types.Primitive.unknown) return default_t;
        const without_undefined = self.subtractType(source_t, types.Primitive.undefined_t) catch source_t;
        if (without_undefined == types.Primitive.never or without_undefined == types.Primitive.none) return default_t;
        if (default_t == types.Primitive.never or default_t == types.Primitive.none) return without_undefined;
        if (without_undefined == default_t) return without_undefined;
        // Widen the literal default before unioning so a string-literal
        // default (`a = ""`) doesn't render alongside `string` in the
        // source's union prose for the destructured target's TS2322
        // diagnostic. Mirrors upstream tsc which widens initializer
        // types when computing the effective destructuring binding
        // type. Without widening, the outer union wraps the
        // already-union prop type (`string | number`) together with
        // the literal `""`; downstream assignability prose renders
        // the 2-member outer union as `(string | number) | ""` which
        // collapses textually to `string | number | ""`. See fixture
        // `restElementWithAssignmentPattern2.ts(2,10)` whose baseline
        // is `string | number`.
        const widened_default = self.widenLiteralType(default_t);
        if (widened_default == without_undefined) return without_undefined;
        // When the source already contains the widened default as a
        // union member, the union is a no-op ÃÂ¢ÃÂÃÂ return the source
        // unchanged. Without this guard the outer union ends up
        // wrapping `string | number` and `string` as siblings.
        if (self.interner.pool.flagsOf(without_undefined).is_union) {
            for (self.interner.unionMembers(without_undefined)) |member| {
                if (member == widened_default) return without_undefined;
            }
        }
        return self.interner.internUnion(&.{ without_undefined, widened_default }) catch return error.OutOfMemory;
    }

    fn objectPropertyTypeForDestructuring(self: *Checker, source_t: TypeId, key_node: NodeId, is_computed: bool) CheckError!?TypeId {
        if (is_computed) {
            if (try self.objectPropertyTypeForComputedKeyNode(source_t, key_node)) |t| return t;
        }
        const key_name = if (is_computed)
            try self.propertyNameFromComputedBindingKeyNode(key_node)
        else
            self.propertyNameFromKeyNode(key_node);
        const name = key_name orelse return null;
        return self.objectPropertyTypeByName(source_t, name);
    }

    fn objectPropertyTypeForComputedKeyNode(self: *Checker, source_t: TypeId, key_node: NodeId) CheckError!?TypeId {
        if (key_node == hir_mod.none_node_id) return null;
        const key_t = try self.checkExpression(key_node);
        return try self.objectPropertyTypeForComputedKeyType(source_t, key_t);
    }

    fn objectPropertyTypeForComputedKeyType(self: *Checker, source_t: TypeId, key_t: TypeId) CheckError!?TypeId {
        if (try self.propertyNameFromLiteralType(key_t)) |name| {
            return self.objectPropertyTypeByName(source_t, name);
        }
        if (key_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(key_t);
        if (flags.is_union) {
            var vals: std.ArrayListUnmanaged(TypeId) = .empty;
            defer vals.deinit(self.gpa);
            for (self.interner.unionMembers(key_t)) |member| {
                if (try self.objectPropertyTypeForComputedKeyType(source_t, member)) |t| {
                    try vals.append(self.gpa, t);
                }
            }
            if (vals.items.len == 0) return null;
            if (vals.items.len == 1) return vals.items[0];
            return self.interner.internUnion(vals.items) catch return error.OutOfMemory;
        }
        if (flags.is_number) {
            if (source_t < self.interner.pool.typeCount()) {
                const number_idx = self.interner.objectNumberIndex(source_t);
                if (number_idx != types.Primitive.none) return number_idx;
            }
        }
        if (flags.is_string) {
            if (source_t < self.interner.pool.typeCount()) {
                const string_idx = self.interner.objectStringIndex(source_t);
                if (string_idx != types.Primitive.none) return string_idx;
            }
        }
        return null;
    }

    fn objectPropertyTypeByName(self: *Checker, source_t: TypeId, key_name: hir_mod.StringId) ?TypeId {
        if (source_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(source_t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(source_t) orelse return null;
            if (constraint == source_t) return null;
            return self.objectPropertyTypeByName(constraint, key_name);
        }
        if (flags.is_union) {
            var vals: std.ArrayListUnmanaged(TypeId) = .empty;
            defer vals.deinit(self.gpa);
            for (self.interner.unionMembers(source_t)) |member| {
                if (self.objectPropertyTypeByName(member, key_name)) |t| {
                    vals.append(self.gpa, t) catch return null;
                }
            }
            if (vals.items.len == 0) return null;
            if (vals.items.len == 1) return vals.items[0];
            return self.interner.internUnion(vals.items) catch null;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(source_t)) |member| {
                if (self.objectPropertyTypeByName(member, key_name)) |t| return t;
            }
            return null;
        }
        if (!flags.is_object_type) return null;
        if (self.interner.objectMember(source_t, key_name)) |t| return t;
        const string_idx = self.interner.objectStringIndex(source_t);
        if (string_idx != types.Primitive.none) return string_idx;
        if (self.isNumericStringId(key_name)) {
            const number_idx = self.interner.objectNumberIndex(source_t);
            if (number_idx != types.Primitive.none) return number_idx;
        }
        return null;
    }

    fn propertyNameFromKeyNode(self: *Checker, key_node: NodeId) ?hir_mod.StringId {
        return switch (self.hir.kindOf(key_node)) {
            .identifier => hir_mod.identifierOf(self.hir, key_node).name,
            .literal_string => hir_mod.literalStringOf(self.hir, key_node).value,
            .literal_number => blk: {
                const span = self.hir.spanOf(key_node);
                const src = self.source orelse break :blk null;
                if (span.end > src.len or span.start >= span.end) break :blk null;
                break :blk self.string_interner.intern(src[span.start..span.end]) catch null;
            },
            else => null,
        };
    }

    fn propertyNameFromComputedKeyNode(self: *Checker, key_node: NodeId) CheckError!?hir_mod.StringId {
        const key_t = try self.checkExpression(key_node);
        if (try self.propertyNameFromLiteralType(key_t)) |name| return name;
        if (try self.propertyNameFromConstReturningIife(key_node)) |name| return name;
        if (self.propertyNameFromComputedKeySourceReturn(key_node)) |name| return name;
        return self.propertyNameFromKeyNode(key_node);
    }

    fn propertyNameFromComputedKeySourceReturn(self: *Checker, key_node: NodeId) ?hir_mod.StringId {
        const src = self.source orelse return null;
        const sp = self.hir.spanOf(key_node);
        if (sp.end > src.len or sp.start >= sp.end) return null;
        const text = src[sp.start..sp.end];
        const ret_idx = std.mem.indexOf(u8, text, "return") orelse return null;
        const tail = text[ret_idx + "return".len ..];
        var i: usize = 0;
        while (i < tail.len and (tail[i] == ' ' or tail[i] == '\t' or tail[i] == '\r' or tail[i] == '\n')) : (i += 1) {}
        if (i >= tail.len) return null;
        const quote = tail[i];
        if (quote != '"' and quote != '\'') return null;
        const start = i + 1;
        var end = start;
        while (end < tail.len and tail[end] != quote) : (end += 1) {}
        if (end >= tail.len or end == start) return null;
        return self.string_interner.intern(tail[start..end]) catch null;
    }

    fn propertyNameFromConstReturningIife(self: *Checker, key_node: NodeId) CheckError!?hir_mod.StringId {
        if (key_node == hir_mod.none_node_id or self.hir.kindOf(key_node) != .call_expr) return null;
        const c = hir_mod.callOf(self.hir, key_node);
        const callee = c.callee;
        const callee_kind = self.hir.kindOf(callee);
        if (callee_kind != .arrow_fn and callee_kind != .fn_expr and callee_kind != .fn_decl) return null;
        const f = hir_mod.fnDeclOf(self.hir, callee);
        const ret_expr = self.firstReturnExpressionNode(f.body) orelse return null;
        return try self.propertyNameFromConstLiteralExpression(ret_expr);
    }

    fn firstReturnExpressionNode(self: *Checker, node: NodeId) ?NodeId {
        if (node == hir_mod.none_node_id) return null;
        return switch (self.hir.kindOf(node)) {
            .return_stmt => blk: {
                const r = hir_mod.returnOf(self.hir, node);
                break :blk if (r.value == hir_mod.none_node_id) null else r.value;
            },
            .block_stmt => blk: {
                for (hir_mod.blockStmts(self.hir, node)) |stmt| {
                    if (self.firstReturnExpressionNode(stmt)) |expr| break :blk expr;
                }
                break :blk null;
            },
            .if_stmt => blk: {
                const i = hir_mod.ifOf(self.hir, node);
                if (self.firstReturnExpressionNode(i.then_branch)) |expr| break :blk expr;
                break :blk self.firstReturnExpressionNode(i.else_branch);
            },
            .try_stmt => blk: {
                const t = hir_mod.tryOf(self.hir, node);
                if (self.firstReturnExpressionNode(t.block)) |expr| break :blk expr;
                if (self.firstReturnExpressionNode(t.catch_block)) |expr| break :blk expr;
                break :blk self.firstReturnExpressionNode(t.finally_block);
            },
            .fn_decl, .fn_expr, .arrow_fn => null,
            else => node,
        };
    }

    fn propertyNameFromConstLiteralExpression(self: *Checker, node: NodeId) CheckError!?hir_mod.StringId {
        if (node == hir_mod.none_node_id) return null;
        return switch (self.hir.kindOf(node)) {
            .as_expr, .satisfies_expr, .type_assertion, .non_null_expr => blk: {
                const a = hir_mod.asExpressionOf(self.hir, node);
                break :blk try self.propertyNameFromConstLiteralExpression(a.expr);
            },
            .literal_string, .literal_number => self.propertyNameFromKeyNode(node),
            .literal_bool => if (hir_mod.literalBoolOf(self.hir, node))
                self.string_interner.intern("true") catch return error.OutOfMemory
            else
                self.string_interner.intern("false") catch return error.OutOfMemory,
            else => null,
        };
    }

    fn propertyNameFromLiteralType(self: *Checker, t: TypeId) CheckError!?hir_mod.StringId {
        if (t == types.Primitive.true_lit) return self.string_interner.intern("true") catch return error.OutOfMemory;
        if (t == types.Primitive.false_lit) return self.string_interner.intern("false") catch return error.OutOfMemory;
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_literal) return null;
        switch (self.interner.literalOfOrNull(t) orelse return null) {
            .string_lit => |sid| return sid,
            .number_lit => |bits| {
                const v: f64 = @bitCast(bits);
                var buf: [64]u8 = undefined;
                const text = if (v == @floor(v) and v >= -9007199254740991 and v <= 9007199254740991)
                    std.fmt.bufPrint(&buf, "{d}", .{@as(i64, @intFromFloat(v))}) catch return null
                else
                    std.fmt.bufPrint(&buf, "{d}", .{v}) catch return null;
                return self.string_interner.intern(text) catch return error.OutOfMemory;
            },
            else => return null,
        }
    }

    fn fixedTupleLength(self: *Checker, target: TypeId) ?u64 {
        if (target >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(target).is_object_type) return null;
        const length_id = self.string_interner.intern("length") catch return null;
        const length_t = self.interner.objectMember(target, length_id) orelse return null;
        const flags = self.interner.pool.flagsOf(length_t);
        if (!flags.is_literal or !flags.is_number) return null;
        return switch (self.interner.literalOf(length_t)) {
            .number_lit => |bits| blk: {
                const v: f64 = @bitCast(bits);
                if (v < 0 or v != @floor(v)) break :blk null;
                break :blk @as(u64, @intFromFloat(v));
            },
            else => null,
        };
    }

    fn markTupleOrigin(self: *Checker, target: TypeId) CheckError!void {
        try self.tuple_origin_types.put(self.gpa, target, {});
    }

    fn isActualTupleType(self: *Checker, target: TypeId) bool {
        if (target >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(target);
        return flags.is_tuple or self.tuple_origin_types.contains(target);
    }

    fn actualTupleLength(self: *Checker, target: TypeId) ?u64 {
        if (!self.isActualTupleType(target)) return null;
        return self.fixedTupleLength(target);
    }

    fn tupleElementType(self: *Checker, target: TypeId, index: usize) TypeId {
        if (target >= self.interner.pool.typeCount()) return types.Primitive.none;
        if (!self.interner.pool.flagsOf(target).is_object_type) return types.Primitive.none;
        var nbuf: [12]u8 = undefined;
        const name_str = std.fmt.bufPrint(&nbuf, "{d}", .{index}) catch return types.Primitive.none;
        const name = self.string_interner.intern(name_str) catch return types.Primitive.none;
        if (self.interner.objectMember(target, name)) |t| return t;
        if (self.tuple_trailing_variadic_types.get(target)) |variadic_t| {
            const prefix = self.tupleFixedPrefixCount(target);
            if (index >= prefix and variadic_t != target and variadic_t < self.interner.pool.typeCount()) {
                const relative_index = index - prefix;
                if (self.interner.pool.flagsOf(variadic_t).is_object_type) {
                    const element_t = self.tupleElementType(variadic_t, relative_index);
                    if (element_t != types.Primitive.none) return element_t;
                }
            }
        }
        if (self.tuple_trailing_rest_types.get(target)) |t| return t;
        return self.interner.objectNumberIndex(target);
    }

    fn numericIndexFromStringId(self: *Checker, name: hir_mod.StringId) ?usize {
        const text = self.string_interner.get(name);
        if (text.len == 0) return null;
        for (text) |c| {
            if (c < '0' or c > '9') return null;
        }
        return std.fmt.parseInt(usize, text, 10) catch null;
    }

    fn numericStringIdForIndex(self: *Checker, index: usize) CheckError!hir_mod.StringId {
        var nbuf: [32]u8 = undefined;
        const text = std.fmt.bufPrint(&nbuf, "{d}", .{index}) catch return error.OutOfMemory;
        return self.string_interner.intern(text) catch return error.OutOfMemory;
    }

    fn tupleLikeLiteralIndexType(self: *Checker, target: TypeId, key: hir_mod.StringId) TypeId {
        if (target >= self.interner.pool.typeCount()) return types.Primitive.none;
        if (!self.interner.pool.flagsOf(target).is_object_type) return types.Primitive.none;
        if (self.interner.objectMember(target, key)) |t| return t;
        const index = self.numericIndexFromStringId(key) orelse return types.Primitive.none;
        if (self.actualTupleLength(target)) |length| {
            if (index >= length) return types.Primitive.none;
        }
        if (self.tuple_trailing_rest_types.get(target)) |t| return t;
        return self.interner.objectNumberIndex(target);
    }

    const UnionTupleLiteralIndexAccess = struct {
        key: hir_mod.StringId,
        found_any: bool,
        missing_any: bool,
        value_type: TypeId,
    };

    fn unionTupleLiteralIndexAccess(self: *Checker, object_t: TypeId, index_t: TypeId) CheckError!?UnionTupleLiteralIndexAccess {
        const obj = self.typeParameterConstraint(object_t) orelse object_t;
        if (obj >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(obj).is_union) return null;

        var keys: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer keys.deinit(self.gpa);
        if (!self.collectKnownStringKeysFromIndexType(index_t, &keys) or keys.items.len != 1) return null;
        const key = keys.items[0];
        if (self.numericIndexFromStringId(key) == null) return null;

        var vals: std.ArrayListUnmanaged(TypeId) = .empty;
        defer vals.deinit(self.gpa);
        var found_any = false;
        var missing_any = false;
        for (self.interner.unionMembers(obj)) |member| {
            if (member >= self.interner.pool.typeCount()) return null;
            const member_flags = self.interner.pool.flagsOf(member);
            if (!member_flags.is_object_type) return null;
            const is_tuple_like = self.actualTupleLength(member) != null or
                self.objectTypeIsArrayLikeContainer(member);
            if (!is_tuple_like) return null;
            const member_t = self.tupleLikeLiteralIndexType(member, key);
            if (member_t == types.Primitive.none) {
                missing_any = true;
                continue;
            }
            found_any = true;
            try vals.append(self.gpa, member_t);
        }
        if (missing_any) try vals.append(self.gpa, types.Primitive.undefined_t);
        const value_type = if (vals.items.len == 0)
            types.Primitive.undefined_t
        else if (vals.items.len == 1)
            vals.items[0]
        else
            self.interner.internUnion(vals.items) catch return error.OutOfMemory;
        return .{
            .key = key,
            .found_any = found_any,
            .missing_any = missing_any,
            .value_type = value_type,
        };
    }

    fn unionTupleElementAccessAt(self: *Checker, object_t: TypeId, index: usize) CheckError!?UnionTupleLiteralIndexAccess {
        const index_t = self.interner.internNumberLiteral(@floatFromInt(index)) catch return error.OutOfMemory;
        return try self.unionTupleLiteralIndexAccess(object_t, index_t);
    }

    fn isTupleLikeUnionType(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(t).is_union) return false;
        var saw_tuple_like = false;
        for (self.interner.unionMembers(t)) |member| {
            if (member >= self.interner.pool.typeCount()) return false;
            if (!self.interner.pool.flagsOf(member).is_object_type) return false;
            const is_tuple_like = self.isTupleShapedTarget(member) or
                self.actualTupleLength(member) != null or
                self.interner.objectNumberIndex(member) != types.Primitive.none;
            if (!is_tuple_like) return false;
            saw_tuple_like = true;
        }
        return saw_tuple_like;
    }

    fn tupleUnionTypeFromTypeNode(self: *Checker, type_node: NodeId, depth: u8) ?TypeId {
        if (type_node == hir_mod.none_node_id or depth > 16) return null;
        switch (self.hir.kindOf(type_node)) {
            .identifier, .type_ref => {
                const alias_name = self.simpleTypeAliasNameFromTypeNode(type_node) orelse return null;
                const decl = self.typeAliasDeclForNameAt(alias_name, type_node) orelse return null;
                const ta = hir_mod.typeAliasOf(self.hir, decl);
                if (ta.type_params_len != 0 or ta.aliased == hir_mod.none_node_id) return null;
                if (self.tupleUnionTypeFromTypeNode(ta.aliased, depth + 1)) |body_t| {
                    self.registerAliasDisplayText(body_t, self.string_interner.get(alias_name)) catch {};
                    return body_t;
                }
                const lowered = self.lowererLowerWithTypeParams(ta.aliased) catch return null;
                if (!self.isTupleLikeUnionType(lowered)) return null;
                self.registerAliasDisplayText(lowered, self.string_interner.get(alias_name)) catch {};
                return lowered;
            },
            .union_type => {
                const lowered = self.lowererLowerWithTypeParams(type_node) catch return null;
                return if (self.isTupleLikeUnionType(lowered)) lowered else null;
            },
            else => return null,
        }
    }

    fn annotatedTupleUnionForIdentifier(self: *Checker, node: NodeId) ?TypeId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        if (self.visibleAnnotatedIdentifierTypeNode(node)) |type_node| {
            if (self.tupleUnionTypeFromTypeNode(type_node, 0)) |body_t| return body_t;
        }
        const annotated_t = self.visibleAnnotatedIdentifierType(node) orelse self.typeOfIdentifierDeclared(node);
        return if (self.isTupleLikeUnionType(annotated_t)) annotated_t else null;
    }

    fn tupleFixedPrefixCount(self: *Checker, target: TypeId) usize {
        if (target >= self.interner.pool.typeCount()) return 0;
        if (!self.interner.pool.flagsOf(target).is_object_type) return 0;
        var count: usize = 0;
        while (true) : (count += 1) {
            var nbuf: [12]u8 = undefined;
            const name_str = std.fmt.bufPrint(&nbuf, "{d}", .{count}) catch return count;
            const name = self.string_interner.intern(name_str) catch return count;
            const member = self.tupleElementMember(target, name) orelse return count;
            if (member.is_optional) return count;
        }
    }

    fn tupleRestMinRequiredCount(self: *Checker, target: TypeId) usize {
        // A rest parameter whose type is a UNION of tuples (e.g.
        // `...args: [string] | [number, boolean]`) accepts any branch,
        // so the minimum required element count is the SMALLEST branch
        // minimum. Without this the union collapses to one arbitrary
        // branch's length and a valid call against the shorter branch
        // spuriously trips TS2554 (cf. genericRestParameters3 line 15,
        // `f1("foo", "abc")`). Mirrors tsc's `getMinArgumentCount`,
        // which folds the rest tuple's `minLength` across the union.
        if (target < self.interner.pool.typeCount() and self.interner.pool.flagsOf(target).is_union) {
            var min_count: usize = std.math.maxInt(usize);
            for (self.interner.unionMembers(target)) |member| {
                const branch = self.tupleRestMinRequiredCount(member);
                min_count = @min(min_count, branch);
            }
            if (min_count == std.math.maxInt(usize)) return 0;
            return min_count;
        }
        var count = self.tupleFixedPrefixCount(target);
        while (count > 0) {
            const elem_t = self.tupleElementType(target, count - 1);
            if (elem_t == types.Primitive.none or !self.parameterTypeAllowsVoidOmission(elem_t)) break;
            count -= 1;
        }
        return count;
    }

    /// Maximum fixed element count of a rest-parameter tuple type,
    /// folded across a union of tuples. Returns `null` when any branch
    /// has an unbounded (variadic) tail, since that makes the overall
    /// accepted arity unbounded too. For a single fixed tuple this is
    /// just its length. Pairs with `tupleRestMinRequiredCount` so the
    /// arity range of a union-tuple rest parameter is computed
    /// correctly (cf. genericRestParameters3).
    fn restTupleMaxCount(self: *Checker, target: TypeId) ?usize {
        if (target < self.interner.pool.typeCount() and self.interner.pool.flagsOf(target).is_union) {
            var max_count: usize = 0;
            for (self.interner.unionMembers(target)) |member| {
                const branch = self.restTupleMaxCount(member) orelse return null;
                max_count = @max(max_count, branch);
            }
            return max_count;
        }
        if (self.fixedTupleLength(target)) |len| return @intCast(len);
        return null;
    }

    fn tupleElementMember(self: *Checker, target: TypeId, name: hir_mod.StringId) ?types.ObjectMember {
        if (target >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(target).is_object_type) return null;
        for (self.interner.objectMembers(target)) |member| {
            if (member.name == name) return member;
        }
        return null;
    }

    fn tupleTypeLooksReadonly(self: *Checker, target: TypeId) bool {
        const len = self.fixedTupleLength(target) orelse return false;
        if (len == 0) return false;
        var nbuf: [12]u8 = undefined;
        const zero_str = std.fmt.bufPrint(&nbuf, "{d}", .{0}) catch return false;
        const zero_name = self.string_interner.intern(zero_str) catch return false;
        if (self.tupleElementMember(target, zero_name)) |member| return member.is_readonly;
        const length_id = self.string_interner.intern("length") catch return false;
        if (self.interner.objectMemberInfo(target, length_id)) |member| return member.is_readonly;
        return false;
    }

    fn tupleWidthChainForArity(
        self: *Checker,
        source_min: usize,
        source_max: ?usize,
        target_required: usize,
        target_max: ?usize,
    ) CheckError![]const DiagnosticChainEntry {
        const arena = self.diag_arena.allocator();
        if (source_max) |max| {
            if (max < target_required) {
                const msg = try std.fmt.allocPrint(
                    arena,
                    "Source has {d} element(s) but target requires {d}.",
                    .{ max, target_required },
                );
                const slice = try arena.alloc(DiagnosticChainEntry, 1);
                slice[0] = .{ .code = TsCodes.source_tuple_too_short, .message = msg };
                return slice;
            }
        }
        if (source_min < target_required) {
            if (source_max == null or source_max.? > target_required) {
                const msg = try std.fmt.allocPrint(
                    arena,
                    "Target requires {d} element(s) but source may have fewer.",
                    .{target_required},
                );
                const slice = try arena.alloc(DiagnosticChainEntry, 1);
                slice[0] = .{ .code = TsCodes.target_requires_source_may_have_fewer, .message = msg };
                return slice;
            }
            const msg = try std.fmt.allocPrint(
                arena,
                "Source provides no match for required element at position {d} in target.",
                .{source_min},
            );
            const slice = try arena.alloc(DiagnosticChainEntry, 1);
            slice[0] = .{ .code = TsCodes.source_no_match_required_element, .message = msg };
            return slice;
        }
        if (target_max) |max| {
            if (source_max) |src_max| {
                if (src_max > max) {
                    if (source_min == src_max) {
                        const msg = try std.fmt.allocPrint(
                            arena,
                            "Source has {d} element(s) but target allows only {d}.",
                            .{ src_max, max },
                        );
                        const slice = try arena.alloc(DiagnosticChainEntry, 1);
                        slice[0] = .{ .code = TsCodes.source_tuple_too_long, .message = msg };
                        return slice;
                    }
                    const msg = try std.fmt.allocPrint(
                        arena,
                        "Target allows only {d} element(s) but source may have more.",
                        .{max},
                    );
                    const slice = try arena.alloc(DiagnosticChainEntry, 1);
                    slice[0] = .{ .code = TsCodes.target_allows_source_may_have_more, .message = msg };
                    return slice;
                }
            } else if (source_min > max) {
                const msg = try std.fmt.allocPrint(
                    arena,
                    "Source has {d} element(s) but target allows only {d}.",
                    .{ source_min, max },
                );
                const slice = try arena.alloc(DiagnosticChainEntry, 1);
                slice[0] = .{ .code = TsCodes.source_tuple_too_long, .message = msg };
                return slice;
            } else {
                const msg = try std.fmt.allocPrint(
                    arena,
                    "Target allows only {d} element(s) but source may have more.",
                    .{max},
                );
                const slice = try arena.alloc(DiagnosticChainEntry, 1);
                slice[0] = .{ .code = TsCodes.target_allows_source_may_have_more, .message = msg };
                return slice;
            }
        }
        return &.{};
    }

    fn tupleWidthElaborationChain(
        self: *Checker,
        source: TypeId,
        target: TypeId,
    ) CheckError![]const DiagnosticChainEntry {
        const source_min = self.tupleRestMinRequiredCount(source);
        const source_max = self.restTupleMaxCount(source);
        const target_required = self.tupleRestMinRequiredCount(target);
        const target_max = self.restTupleMaxCount(target);
        return try self.tupleWidthChainForArity(source_min, source_max, target_required, target_max);
    }

    fn tupleRestLooksVariadic(self: *Checker, target: TypeId) bool {
        if (self.restTupleMaxCount(target) != null) return false;
        const rest_pos = self.tupleFixedPrefixCount(target);
        const rest_t = self.tupleElementType(target, rest_pos);
        if (rest_t == types.Primitive.none) return false;
        return self.containsFreeTypeParameter(rest_t);
    }

    fn tupleSourceCannotSatisfyVariadicTarget(self: *Checker, source: TypeId, target: TypeId) bool {
        if (!self.isTupleShapedTarget(source) or !self.isTupleShapedTarget(target)) return false;
        if (!self.tupleRestLooksVariadic(target)) return false;
        if (self.tupleRestLooksVariadic(source)) return false;
        return self.tupleRestMinRequiredCount(source) >= self.tupleFixedPrefixCount(target);
    }

    fn tupleSourceVariadicMismatchChain(
        self: *Checker,
        source: TypeId,
        target: TypeId,
    ) CheckError![]const DiagnosticChainEntry {
        const target_max = self.restTupleMaxCount(target) orelse return &.{};
        if (!self.tupleRestLooksVariadic(source)) return &.{};
        const source_position = self.tupleFixedPrefixCount(source);
        if (target_max != source_position + 1) return &.{};
        const target_position = source_position;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Variadic element at position {d} in source does not match element at position {d} in target.",
            .{ source_position, target_position },
        );
        const slice = try self.diag_arena.allocator().alloc(DiagnosticChainEntry, 1);
        slice[0] = .{ .code = TsCodes.source_variadic_element_mismatch, .message = msg };
        return slice;
    }

    fn tuplePositionElaborationChain(
        self: *Checker,
        source: TypeId,
        target: TypeId,
    ) CheckError![]const DiagnosticChainEntry {
        const arena = self.diag_arena.allocator();
        const target_fixed_prefix = self.tupleFixedPrefixCount(target);
        const target_max = self.restTupleMaxCount(target);

        if (target_max == null and self.tupleSourceCannotSatisfyVariadicTarget(source, target)) {
            const msg = try std.fmt.allocPrint(
                arena,
                "Source provides no match for variadic element at position {d} in target.",
                .{target_fixed_prefix},
            );
            const slice = try arena.alloc(DiagnosticChainEntry, 1);
            slice[0] = .{ .code = TsCodes.source_no_match_variadic_element, .message = msg };
            return slice;
        }

        const source_len = self.fixedTupleLength(source) orelse return &.{};
        const source_len_usize: usize = @intCast(source_len);

        if (target_max == null and self.tupleRestLooksVariadic(target) and
            source_len_usize >= target_fixed_prefix)
        {
            const msg = try std.fmt.allocPrint(
                arena,
                "Source provides no match for variadic element at position {d} in target.",
                .{target_fixed_prefix},
            );
            const slice = try arena.alloc(DiagnosticChainEntry, 1);
            slice[0] = .{ .code = TsCodes.source_no_match_variadic_element, .message = msg };
            return slice;
        }

        if (source_len_usize == 0) return &.{};
        var source_pos: usize = 0;
        while (source_pos < source_len_usize) : (source_pos += 1) {
            const target_pos: usize = if (target_max == null and source_pos >= target_fixed_prefix)
                target_fixed_prefix
            else
                source_pos;
            const source_t = self.tupleElementType(source, source_pos);
            const target_t = self.tupleElementType(target, target_pos);
            if (source_t == types.Primitive.none or target_t == types.Primitive.none) continue;
            if (self.engine.isAssignableTo(source_t, target_t) catch true) continue;

            const child = try arena.alloc(DiagnosticChainEntry, 1);
            child[0] = try self.typeNotAssignableChainEntry(source_t, target_t, false);
            const slice = try arena.alloc(DiagnosticChainEntry, 1);
            if (target_max == null and source_pos >= target_fixed_prefix and
                target_fixed_prefix != source_len_usize - 1)
            {
                const msg = try std.fmt.allocPrint(
                    arena,
                    "Type at positions {d} through {d} in source is not compatible with type at position {d} in target.",
                    .{ target_fixed_prefix, source_len_usize - 1, target_pos },
                );
                slice[0] = .{
                    .code = TsCodes.tuple_range_type_incompatible,
                    .message = msg,
                    .children = child,
                };
            } else {
                const msg = try std.fmt.allocPrint(
                    arena,
                    "Type at position {d} in source is not compatible with type at position {d} in target.",
                    .{ source_pos, target_pos },
                );
                slice[0] = .{
                    .code = TsCodes.tuple_position_type_incompatible,
                    .message = msg,
                    .children = child,
                };
            }
            return slice;
        }
        return &.{};
    }

    fn tupleRestElementTypeAtPosition(self: *Checker, tuple_t: TypeId, position: usize) CheckError!TypeId {
        const explicit = self.tupleElementType(tuple_t, position);
        const fixed_prefix = self.tupleFixedPrefixCount(tuple_t);
        if (position < fixed_prefix or explicit == types.Primitive.none) return explicit;
        const number_idx = self.interner.objectNumberIndex(tuple_t);
        if (number_idx == types.Primitive.none) return explicit;
        if (number_idx >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(number_idx).is_union)
        {
            return number_idx;
        }

        var kept: std.ArrayListUnmanaged(TypeId) = .empty;
        defer kept.deinit(self.gpa);
        for (self.interner.unionMembers(number_idx)) |member| {
            var is_fixed_member = false;
            var i: usize = 0;
            while (i < fixed_prefix) : (i += 1) {
                if (self.tupleElementType(tuple_t, i) == member) {
                    is_fixed_member = true;
                    break;
                }
            }
            if (!is_fixed_member) try kept.append(self.gpa, member);
        }
        if (kept.items.len == 0) return number_idx;
        if (kept.items.len == 1) return kept.items[0];
        return self.interner.internUnion(kept.items) catch number_idx;
    }

    fn tupleConstraintPositionChain(
        self: *Checker,
        source: TypeId,
        target: TypeId,
    ) CheckError![]const DiagnosticChainEntry {
        if (!self.isTupleShapedTarget(source) or !self.isTupleShapedTarget(target)) return &.{};
        const source_prefix = self.tupleFixedPrefixCount(source);
        const target_prefix = self.tupleFixedPrefixCount(target);
        const compare_len = @max(source_prefix, target_prefix);
        var i: usize = 0;
        while (i < compare_len) : (i += 1) {
            const source_t = try self.tupleRestElementTypeAtPosition(source, i);
            const target_t = try self.tupleRestElementTypeAtPosition(target, i);
            if (source_t == types.Primitive.none or target_t == types.Primitive.none) continue;
            if (self.engine.isAssignableTo(source_t, target_t) catch true) continue;
            const child = try self.diag_arena.allocator().alloc(DiagnosticChainEntry, 1);
            child[0] = try self.typeNotAssignableChainEntry(source_t, target_t, false);
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Type at position {d} in source is not compatible with type at position {d} in target.",
                .{ i, i },
            );
            const slice = try self.diag_arena.allocator().alloc(DiagnosticChainEntry, 1);
            slice[0] = .{
                .code = TsCodes.tuple_position_type_incompatible,
                .message = msg,
                .children = child,
            };
            return slice;
        }
        return &.{};
    }

    fn typeArgTupleConstraintChain(
        self: *Checker,
        arg_t: TypeId,
        constraint: TypeId,
    ) CheckError![]const DiagnosticChainEntry {
        if (!self.isTupleShapedTarget(constraint)) return &.{};
        const arg_is_tuple = self.isTupleShapedTarget(arg_t);
        const arg_is_array = self.typeIsArrayLikeObject(arg_t);
        if (!arg_is_tuple and !arg_is_array) return &.{};

        const source_min = if (arg_is_tuple) self.tupleRestMinRequiredCount(arg_t) else 0;
        const source_max = if (arg_is_tuple) self.restTupleMaxCount(arg_t) else null;
        const target_required = self.tupleRestMinRequiredCount(constraint);
        const target_max = self.restTupleMaxCount(constraint);

        if (!arg_is_tuple and target_required > 0 and target_max == null) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Source provides no match for required element at position {d} in target.",
                .{source_min},
            );
            const slice = try self.diag_arena.allocator().alloc(DiagnosticChainEntry, 1);
            slice[0] = .{ .code = TsCodes.source_no_match_required_element, .message = msg };
            return slice;
        }

        const width_chain = try self.tupleWidthChainForArity(source_min, source_max, target_required, target_max);
        if (width_chain.len != 0) return width_chain;

        const fixed_position_chain = try self.tuplePositionElaborationChain(arg_t, constraint);
        if (fixed_position_chain.len != 0) return fixed_position_chain;

        return try self.tupleConstraintPositionChain(arg_t, constraint);
    }

    fn constAssertedArrayLiteral(self: *Checker, node: NodeId) ?NodeId {
        const k = self.hir.kindOf(node);
        if (k != .as_expr and k != .type_assertion) return null;
        const a = hir_mod.asExpressionOf(self.hir, node);
        if (a.type_node == hir_mod.none_node_id or !self.isAsConstMarker(a.type_node)) return null;
        if (self.hir.kindOf(a.expr) != .array_literal) return null;
        return a.expr;
    }

    fn freshReadonlyArrayLiteralAssignableToTarget(
        self: *Checker,
        source_node: NodeId,
        target_t: TypeId,
    ) CheckError!bool {
        const array_node = self.constAssertedArrayLiteral(source_node) orelse return false;
        if (self.isTupleShapedTarget(target_t)) {
            return try self.arrayLiteralAssignableToTupleTarget(array_node, target_t, true);
        }
        return try self.arrayLiteralAssignableToTarget(array_node, target_t);
    }

    fn readonlyArrayLikeAssignmentShouldFail(
        self: *Checker,
        source_node: NodeId,
        source_t: TypeId,
        target_t: TypeId,
    ) bool {
        if (self.constAssertedArrayLiteral(source_node) != null) return false;
        return self.readonlyArrayLikeAssignedToMutable(source_t, target_t);
    }

    fn readonlyArrayLikeAssignedToMutable(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
        return self.typeIsReadonlyArrayLike(source_t) and self.typeIsMutableArrayLike(target_t);
    }

    fn typeIsReadonlyArrayLike(self: *Checker, t: TypeId) bool {
        if (!self.typeIsArrayLikeObject(t)) return false;
        return self.tupleTypeLooksReadonly(t) or self.typeHasReadonlyIndexSignature(t);
    }

    fn typeIsMutableArrayLike(self: *Checker, t: TypeId) bool {
        if (!self.typeIsArrayLikeObject(t)) return false;
        return !self.tupleTypeLooksReadonly(t) and !self.typeHasReadonlyIndexSignature(t);
    }

    fn typeIsArrayLikeObject(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(t).is_object_type) return false;
        if (self.interner.objectNumberIndex(t) == types.Primitive.none) return false;
        const length_id = self.string_interner.intern("length") catch return false;
        return self.interner.objectMember(t, length_id) != null;
    }

    fn reportTupleIndexOutOfBounds(self: *Checker, index_node: NodeId, target: TypeId, index: u64, length: u64) CheckError!void {
        if (index <= std.math.maxInt(usize)) {
            if (try self.tupleAliasUnionIndexAccess(target, @intCast(index))) |access| {
                if (access.found_any) return;
                if (!self.diagnosticExists(index_node, TsCodes.property_does_not_exist)) {
                    try self.reportIndexedPropertyDoesNotExistOnType(index_node, access.key, self.tupleAliasUnionBody(target) orelse target);
                }
                return;
            }
        }
        const arena = self.diag_arena.allocator();
        var display_buf: std.ArrayListUnmanaged(u8) = .empty;
        defer display_buf.deinit(arena);
        const has_display = if (try self.simpleDiagnosticTypeName(target)) |name| blk: {
            try display_buf.appendSlice(arena, name);
            break :blk true;
        } else self.renderTupleDisplay(&display_buf, target) catch false;
        const msg = if (has_display)
            try std.fmt.allocPrint(
                arena,
                "Tuple type '{s}' of length '{d}' has no element at index '{d}'.",
                .{ display_buf.items, length, index },
            )
        else
            try std.fmt.allocPrint(
                arena,
                "Tuple type of length '{d}' has no element at index '{d}'.",
                .{ length, index },
            );
        try self.diagnostics.append(self.gpa, .{
            .node = index_node,
            .code = TsCodes.tuple_index_out_of_bounds,
            .message = msg,
        });
    }

    fn fixedTupleLiteralIndexExpression(self: *Checker, target: TypeId, index_node: NodeId) bool {
        if (self.actualTupleLength(target) == null) return false;
        if (self.hir.kindOf(index_node) == .literal_number) return true;
        if (self.hir.kindOf(index_node) != .unary_op) return false;
        const unary = hir_mod.unaryOf(self.hir, index_node);
        return unary.op == .neg and self.hir.kindOf(unary.operand) == .literal_number;
    }

    fn tupleAliasUnionBody(self: *Checker, target: TypeId) ?TypeId {
        const alias_name = self.namedTypeForId(target);
        if (alias_name) |name| {
            if (self.type_alias_bodies.get(name)) |body| {
                if (body < self.interner.pool.typeCount() and self.interner.pool.flagsOf(body).is_union) return body;
            }
        }
        const display = (self.alias_display_names.get(target) orelse (self.simpleDiagnosticTypeName(target) catch null)) orelse return null;
        if (std.mem.indexOfScalar(u8, display, '<') != null) return null;
        const display_alias_name = blk: {
            var it = self.type_alias_bodies.iterator();
            while (it.next()) |entry| {
                if (std.mem.eql(u8, self.string_interner.get(entry.key_ptr.*), display)) {
                    break :blk entry.key_ptr.*;
                }
            }
            return null;
        };
        const body = self.type_alias_bodies.get(display_alias_name) orelse return null;
        if (body >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(body).is_union) return null;
        return body;
    }

    fn tupleAliasUnionIndexAccess(self: *Checker, target: TypeId, index: usize) CheckError!?UnionTupleLiteralIndexAccess {
        const body = self.tupleAliasUnionBody(target) orelse return null;
        return try self.unionTupleElementAccessAt(body, index);
    }

    fn reportIndexedPropertyDoesNotExistOnType(self: *Checker, node: NodeId, name: hir_mod.StringId, target_t: TypeId) CheckError!void {
        const name_str = self.string_interner.get(name);
        const target_text = (try self.allocPropertyMissingTargetTypeName(target_t)) orelse "unknown";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Property '{s}' does not exist on type '{s}'.",
            .{ name_str, target_text },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.property_does_not_exist,
            .message = msg,
        });
    }

    fn renderTupleDisplay(self: *Checker, buf: *std.ArrayListUnmanaged(u8), target: TypeId) !bool {
        if (target >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(target).is_object_type) return false;
        const length = self.actualTupleLength(target) orelse return false;
        const arena = self.diag_arena.allocator();
        try buf.append(arena, '[');
        // Cap render width at 10_000 elements: protects against u64ÃÂ¢ÃÂÃÂusize
        // narrowing on 32-bit hosts and bounds diagnostic-string growth on
        // pathological tuple types (tsc itself truncates around the same
        // scale in practice).
        const render_cap: u64 = @min(length, 10_000);
        var i: u64 = 0;
        while (i < render_cap) : (i += 1) {
            if (i > 0) try buf.appendSlice(arena, ", ");
            const elem_t = self.tupleElementType(target, @intCast(i));
            if (try self.allocSimpleTypeName(elem_t)) |name| {
                try buf.appendSlice(arena, name);
            } else {
                try buf.appendSlice(arena, "any");
            }
        }
        try buf.append(arena, ']');
        return true;
    }

    /// Single binding identifier occurrence inside a destructuring
    /// pattern ÃÂ¢ÃÂÃÂ used by TS2451 duplicate-detection for `let`/`const`.
    const DestructuringBindingOccurrence = struct {
        name: hir_mod.StringId,
        node: NodeId,
        pos: u32,
    };

    /// TS2451 ÃÂ¢ÃÂÃÂ emit `Cannot redeclare block-scoped variable '{name}'.`
    /// at every position where a binding identifier appears more than
    /// once inside a `let`/`const` declaration's binding pattern.
    ///
    /// Mirrors tsc: for `let { foo1, foo1 } = ÃÂ¢ÃÂÃÂ¦`, both `foo1` positions
    /// receive their own TS2451. For `let { foo2, bar2: foo2 } = ÃÂ¢ÃÂÃÂ¦`,
    /// each LOCAL binding identifier counts (the key `bar2` is ignored;
    /// only the renamed target `foo2` is a binding). Nested patterns
    /// like `let { a: { x }, b: { x } } = ÃÂ¢ÃÂÃÂ¦` also fire on every `x`.
    /// Array patterns receive the same treatment: `let [a, a] = ÃÂ¢ÃÂÃÂ¦`.
    fn checkLetConstDestructuringDuplicates(
        self: *Checker,
        name_node: NodeId,
    ) CheckError!void {
        if (name_node == hir_mod.none_node_id) return;
        const k = self.hir.kindOf(name_node);
        if (k != .object_pattern and k != .array_pattern) return;

        var occs: std.ArrayListUnmanaged(DestructuringBindingOccurrence) = .empty;
        defer occs.deinit(self.gpa);
        try self.collectDestructuringBindingOccurrences(name_node, &occs);
        if (occs.items.len < 2) return;

        for (occs.items, 0..) |occ, i| {
            var dup = false;
            for (occs.items, 0..) |other, j| {
                if (i == j) continue;
                if (other.name == occ.name) {
                    dup = true;
                    break;
                }
            }
            if (!dup) continue;
            // Replace any parser-side TS2300 ("Duplicate identifier") at
            // the same position with TS2451. tsc emits ONLY TS2451 for
            // `let`/`const` destructuring duplicates; the parser
            // conservatively emits TS2300 because it doesn't know the
            // enclosing decl kind. Mirrors `destructuringSameNames`.
            var existing_idx: ?usize = null;
            for (self.diagnostics.items, 0..) |d, di| {
                if (d.code != TsCodes.duplicate_identifier) continue;
                const d_pos = d.pos orelse self.hir.spanOf(d.node).start;
                if (d_pos == occ.pos) {
                    existing_idx = di;
                    break;
                }
            }
            const name_str = self.string_interner.get(occ.name);
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot redeclare block-scoped variable '{s}'.",
                .{name_str},
            );
            if (existing_idx) |di| {
                self.diagnostics.items[di] = .{
                    .node = occ.node,
                    .pos = occ.pos,
                    .code = TsCodes.cannot_redeclare_block_scoped,
                    .message = msg,
                };
            } else {
                try self.diagnostics.append(self.gpa, .{
                    .node = occ.node,
                    .pos = occ.pos,
                    .code = TsCodes.cannot_redeclare_block_scoped,
                    .message = msg,
                });
            }
        }
    }

    /// Walk a binding-pattern subtree and record every LOCAL binding
    /// identifier (the binding-target name, not object-key labels) with
    /// its source span. Used by the TS2451 duplicate-binding detector
    /// for `let`/`const` destructuring patterns.
    fn collectDestructuringBindingOccurrences(
        self: *Checker,
        pattern_node: NodeId,
        out: *std.ArrayListUnmanaged(DestructuringBindingOccurrence),
    ) CheckError!void {
        if (pattern_node == hir_mod.none_node_id) return;
        const pk = self.hir.kindOf(pattern_node);
        if (pk != .object_pattern and pk != .array_pattern) return;
        for (hir_mod.patternElements(self.hir, pattern_node)) |elem| {
            if (self.hir.kindOf(elem) != .parameter) continue;
            const pp = hir_mod.parameterOf(self.hir, elem);
            // Skip synthetic computed-key carriers; they are NOT a
            // binding slot ÃÂ¢ÃÂÃÂ `{ [expr]: name }` materialises the
            // computed-key parameter separately from the binding
            // parameter for `name`.
            if (pp.flags.is_computed_binding_key) continue;
            if (pp.name == hir_mod.none_node_id) continue;
            const nk = self.hir.kindOf(pp.name);
            if (nk == .identifier) {
                const id = hir_mod.identifierOf(self.hir, pp.name);
                try out.append(self.gpa, .{
                    .name = id.name,
                    .node = pp.name,
                    .pos = self.hir.spanOf(pp.name).start,
                });
            } else if (nk == .object_pattern or nk == .array_pattern) {
                try self.collectDestructuringBindingOccurrences(pp.name, out);
            }
        }
    }

    /// True when `annot` is the HIR for a `unique symbol` type annotation.
    /// The parser folds `unique symbol` into a type_ref whose name interns
    /// to "symbol" and whose span starts at the `unique` keyword, so we
    /// confirm the prefix in the source slice. Returns false for bare
    /// `: symbol` annotations.
    fn typeAnnotationIsUniqueSymbol(self: *Checker, annot: NodeId) bool {
        if (annot == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(annot) != .type_ref) return false;
        const tr = hir_mod.typeRefOf(self.hir, annot);
        if (tr.qualifier_len != 0) return false;
        const name_str = self.string_interner.get(tr.name);
        if (!std.mem.eql(u8, name_str, "symbol")) return false;
        const src = self.source orelse return false;
        const span = self.hir.spanOf(annot);
        if (span.end > src.len) return false;
        if (span.end <= span.start) return false;
        const slice = src[span.start..span.end];
        return std.mem.startsWith(u8, slice, "unique");
    }

    /// TS1335 — flag `unique symbol` type annotations in disallowed
    /// signature positions: function/method parameters and the
    /// declared return type. Upstream's `checkGrammarUniqueSymbolType`
    /// only permits `unique symbol` on variable declarations, property
    /// declarations, and property signatures; everything else gets
    /// "'unique symbol' types are not allowed here." Anchored at the
    /// `unique` type node (the annotation).
    /// TS1334 — `unique symbol` is only allowed on a variable in a
    /// plain variable statement. A `for`/`for-in`/`for-of` loop binding
    /// or a `catch` binding annotated `unique symbol` is a variable
    /// declaration that is NOT in a variable statement → TS1334,
    /// anchored at the `unique` type node. Mirrors upstream
    /// `checkGrammarUniqueSymbolType`.
    fn reportUniqueSymbolNotInVariableStatement(self: *Checker, target: NodeId) CheckError!void {
        if (target == hir_mod.none_node_id) return;
        const k = self.hir.kindOf(target);
        if (k != .var_decl and k != .let_decl and k != .const_decl) return;
        const v = hir_mod.varDeclOf(self.hir, target);
        if (self.typeAnnotationIsUniqueSymbol(v.type_annotation)) {
            try self.report(
                v.type_annotation,
                TsCodes.unique_symbol_only_on_variable_statement,
                "'unique symbol' types are only allowed on variables in a variable statement.",
            );
        }
    }

    /// TS1335: `unique symbol` is permitted ONLY as the type of a variable
    /// declaration, a class property declaration, or an interface/type-literal
    /// property signature (tsc's `checkGrammarUniqueSymbolType`). Anywhere
    /// else — signature parameter/return/this/rest/predicate, type-parameter
    /// constraint/default, type argument, union/intersection member, array/
    /// tuple element, type alias body, … — it is "not allowed here".
    ///
    /// A single flat pass over every `unique symbol` type node applies the
    /// immediate-parent rule (Home's parser strips parentheses, so the parent
    /// is the real enclosing form). This runs in the checked path (called from
    /// `checkSourceFile`), unlike a lowerer hook which the type cache would
    /// short-circuit. The const/readonly/static/binding specifics of the
    /// allowed positions are handled separately (TS1330/1331/1332/1333/1334).
    fn checkUniqueSymbolPositionsGlobal(self: *Checker) CheckError!void {
        if (self.source == null) return;
        const n = self.hir.nodeCount();
        var id: NodeId = 0;
        while (id < n) : (id += 1) {
            if (self.hir.kindOf(id) != .type_ref) continue;
            if (!self.typeAnnotationIsUniqueSymbol(id)) continue;
            const parent = self.hir.parentOf(id);
            if (parent != hir_mod.none_node_id and
                self.hir.kindOf(parent) == .interface_member)
            {
                const im = hir_mod.interfaceMemberOf(self.hir, parent);
                const container = self.hir.parentOf(parent);
                if (im.type_node == id and
                    container != hir_mod.none_node_id and
                    self.hir.kindOf(container) == .object_type and
                    !im.is_method and
                    !im.is_readonly and
                    !self.syntheticSignatureMemberName(im.name))
                {
                    try self.report(
                        parent,
                        TsCodes.unique_symbol_iface_prop_must_be_readonly,
                        "A property of an interface or type literal whose type is a 'unique symbol' type must be 'readonly'.",
                    );
                }
            }
            const allowed = parent != hir_mod.none_node_id and switch (self.hir.kindOf(parent)) {
                .var_decl, .let_decl, .const_decl => hir_mod.varDeclOf(self.hir, parent).type_annotation == id,
                .object_property => hir_mod.objectPropertyOf(self.hir, parent).type_annotation == id,
                .interface_member => hir_mod.interfaceMemberOf(self.hir, parent).type_node == id,
                else => false,
            };
            if (allowed) continue;
            try self.report(
                id,
                TsCodes.unique_symbol_not_allowed_here,
                "'unique symbol' types are not allowed here.",
            );
        }
    }

    fn objectLiteralHasContextualFunctionProperty(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .object_literal) return false;
        for (hir_mod.objectLiteralProps(self.hir, node)) |property_node| {
            if (self.hir.kindOf(property_node) != .object_property) continue;
            const property = hir_mod.objectPropertyOf(self.hir, property_node);
            if (property.value == hir_mod.none_node_id) continue;
            const value_kind = self.hir.kindOf(property.value);
            if (value_kind == .arrow_fn or value_kind == .fn_expr or value_kind == .fn_decl) return true;
        }
        return false;
    }

    fn objectLiteralUnionMismatchReportsAtDeclaration(self: *Checker, node: NodeId, target: TypeId) bool {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .object_literal) return false;
        if (target >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(target).is_union) return false;
        return !self.objectLiteralHasContextualFunctionProperty(node);
    }

    const ObjectUnionDiagnosticTarget = struct {
        node: NodeId,
        type: TypeId,
    };

    fn bestObjectUnionDiagnosticTarget(
        self: *Checker,
        source: TypeId,
        annotation: NodeId,
    ) CheckError!?ObjectUnionDiagnosticTarget {
        if (annotation == hir_mod.none_node_id or self.hir.kindOf(annotation) != .union_type) return null;
        if (source >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(source).is_object_type) return null;
        var best: ?ObjectUnionDiagnosticTarget = null;
        var best_overlap: usize = 0;
        for (hir_mod.unionTypeMembers(self.hir, annotation)) |member_node| {
            const member_t = try self.lowererLowerWithTypeParams(member_node);
            if (member_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(member_t).is_object_type) continue;
            var overlap: usize = 0;
            for (self.interner.objectMembers(member_t)) |member| {
                if (self.interner.objectMember(source, member.name) != null) overlap += 1;
            }
            if (best == null or overlap >= best_overlap) {
                best = .{ .node = member_node, .type = member_t };
                best_overlap = overlap;
            }
        }
        return best;
    }

    fn reportObjectLiteralUnionDeclarationMismatch(
        self: *Checker,
        node: NodeId,
        annotation: NodeId,
        source: TypeId,
    ) CheckError!bool {
        const candidate = (try self.bestObjectUnionDiagnosticTarget(source, annotation)) orelse return false;
        const source_name = (try self.allocObjectTypeShapeWithUndefined(source)) orelse
            (try self.allocSimpleTypeName(source)) orelse return false;
        const target_name = try self.normalizedTypeAnnotationText(self.nodeSourceTextOrEmpty(annotation));
        const candidate_name = try self.normalizedTypeAnnotationText(self.nodeSourceTextOrEmpty(candidate.node));
        const arena = self.diag_arena.allocator();
        const message = try std.fmt.allocPrint(
            arena,
            "Type '{s}' is not assignable to type '{s}'.",
            .{ source_name, target_name },
        );
        const child_message = try std.fmt.allocPrint(
            arena,
            "Type '{s}' is not assignable to type '{s}'.",
            .{ source_name, candidate_name },
        );
        const children = try self.buildAssignabilityElaborationChain(source, candidate.type);
        const chain = try arena.alloc(DiagnosticChainEntry, 1);
        chain[0] = .{
            .code = TsCodes.type_not_assignable,
            .message = child_message,
            .children = children,
        };
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.type_not_assignable,
            .message = message,
            .chain = chain,
        });
        return true;
    }

    fn tryReportContextualFunctionUnionPropertyMismatch(
        self: *Checker,
        init_node: NodeId,
        target: TypeId,
    ) CheckError!bool {
        if (init_node == hir_mod.none_node_id or self.hir.kindOf(init_node) != .object_literal) return false;
        if (target >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(target).is_union) return false;
        const arena = self.diag_arena.allocator();
        for (hir_mod.objectLiteralProps(self.hir, init_node)) |property_node| {
            if (self.hir.kindOf(property_node) != .object_property) continue;
            const property = hir_mod.objectPropertyOf(self.hir, property_node);
            if (property.value == hir_mod.none_node_id or !self.isContextualFunctionExpressionLike(property.value)) continue;
            const property_name = self.propertyNameFromKeyNode(property.key) orelse continue;

            var signatures: std.ArrayListUnmanaged(TypeId) = .empty;
            defer signatures.deinit(self.gpa);
            var first_member: ?types.ObjectMember = null;
            for (self.interner.unionMembers(target)) |target_member_t| {
                if (target_member_t >= self.interner.pool.typeCount() or
                    !self.interner.pool.flagsOf(target_member_t).is_object_type)
                {
                    continue;
                }
                var target_member_opt: ?types.ObjectMember = null;
                for (self.interner.objectMembers(target_member_t)) |member| {
                    if (member.name == property_name) {
                        target_member_opt = member;
                        break;
                    }
                }
                const target_member = target_member_opt orelse continue;
                const signature = self.firstSignatureType(target_member.type) orelse continue;
                try signatures.append(self.gpa, signature);
                if (first_member == null) {
                    first_member = target_member;
                }
            }
            if (signatures.items.len < 2 or first_member == null) continue;
            const source_sig = try self.contextualFunctionSignatureWithInferredReturn(property.value, signatures.items[0]);
            const source_return = self.interner.signatureReturn(source_sig) orelse continue;
            var matches = false;
            for (signatures.items) |signature| {
                const target_return = self.interner.signatureReturn(signature) orelse continue;
                if (try self.checkerAssignableTo(source_return, target_return)) {
                    matches = true;
                    break;
                }
            }
            if (matches) continue;

            const source_name = (try self.allocCallableSignatureName(source_sig)) orelse return false;
            var target_name_buf: std.ArrayListUnmanaged(u8) = .empty;
            defer target_name_buf.deinit(self.gpa);
            for (signatures.items, 0..) |signature, index| {
                if (index > 0) try target_name_buf.appendSlice(self.gpa, " | ");
                try target_name_buf.append(self.gpa, '(');
                try target_name_buf.appendSlice(
                    self.gpa,
                    (try self.allocCallableSignatureName(signature)) orelse return false,
                );
                try target_name_buf.append(self.gpa, ')');
            }
            const target_name = try arena.dupe(u8, target_name_buf.items);
            const candidate_name = (try self.allocCallableSignatureName(signatures.items[0])) orelse return false;
            const message = try std.fmt.allocPrint(
                arena,
                "Type '{s}' is not assignable to type '{s}'.",
                .{ source_name, target_name },
            );
            const child_message = try std.fmt.allocPrint(
                arena,
                "Type '{s}' is not assignable to type '{s}'.",
                .{ source_name, candidate_name },
            );
            const child_children = try self.buildAssignabilityElaborationChain(source_sig, signatures.items[0]);
            const chain = try arena.alloc(DiagnosticChainEntry, 1);
            chain[0] = .{
                .code = TsCodes.type_not_assignable,
                .message = child_message,
                .children = child_children,
            };
            const anchor = if (property.key != hir_mod.none_node_id) property.key else property_node;
            try self.diagnostics.append(self.gpa, .{
                .node = anchor,
                .code = TsCodes.type_not_assignable,
                .message = message,
                .chain = chain,
            });
            if (first_member.?.decl_node != hir_mod.none_node_id) {
                const target_display = (try self.allocSimpleTypeName(target)) orelse "object";
                const related_message = try std.fmt.allocPrint(
                    arena,
                    "The expected type comes from property '{s}' which is declared here on type '{s}'",
                    .{ self.string_interner.get(first_member.?.name), target_display },
                );
                const related = try arena.alloc(RelatedInfo, 1);
                related[0] = .{
                    .node = first_member.?.decl_node,
                    .code = TsCodes.expected_type_from_property,
                    .message = related_message,
                };
                self.diagnostics.items[self.diagnostics.items.len - 1].related = related;
            }
            return true;
        }
        return false;
    }

    fn checkVarDecl(self: *Checker, node: NodeId) CheckError!void {
        const v = hir_mod.varDeclOf(self.hir, node);

        try self.checkJsDocDuplicateSatisfies(node);
        try self.checkExportedVariablePrivateName(node);
        try self.checkExportedAnonymousClassPrivateMembers(node);
        try self.checkExportedVariableInferredPortableName(node);

        // TS1332 - a `unique symbol`-typed variable must be `const`.
        // Anchored at the binding name. Applies to ambient declarations
        // too: tsc emits TS1332 for `declare let s: unique symbol`
        // (uniqueSymbolsErrors.ts(4,13)).
        const decl_kind_for_1332 = self.hir.kindOf(node);
        if ((decl_kind_for_1332 == .let_decl or decl_kind_for_1332 == .var_decl) and
            self.typeAnnotationIsUniqueSymbol(v.type_annotation))
        {
            const anchor: NodeId = if (v.name != hir_mod.none_node_id) v.name else node;
            try self.report(
                anchor,
                TsCodes.unique_symbol_var_must_be_const,
                "A variable whose type is a 'unique symbol' type must be 'const'.",
            );
        }
        // TS1333 - `unique symbol` cannot be paired with a
        // destructuring binding name (`const { x }: unique symbol`,
        // `const [a]: unique symbol`). The fresh-symbol semantics
        // require a single identifier binding so the value can be
        // observed exactly once. Independent of TS1332 (const-ness)
        // — both can fire on `let { x }: unique symbol`. Applies to
        // ambient decls too; tsc anchors at the `unique symbol` TYPE
        // node (uniqueSymbolsErrors.ts(3,19), not the binding pattern).
        if (v.name != hir_mod.none_node_id and
            self.typeAnnotationIsUniqueSymbol(v.type_annotation))
        {
            const name_kind = self.hir.kindOf(v.name);
            if (name_kind == .object_pattern or name_kind == .array_pattern) {
                try self.report(
                    v.type_annotation,
                    TsCodes.unique_symbol_binding_pattern,
                    "'unique symbol' types may not be used on a variable declaration with a binding name.",
                );
            }
        }

        // TS2451 — duplicate binding names inside a `let`/`const`
        // destructuring pattern. tsc emits one TS2451 per occurrence,
        // INCLUDING the first one, so we mirror that anchor-at-each-
        // position pattern here. Skipped for `var` (no block-scoped
        // semantics) and for ambient declarations.
        const decl_kind = self.hir.kindOf(node);
        if ((decl_kind == .let_decl or decl_kind == .const_decl) and !v.is_ambient) {
            try self.checkLetConstDestructuringDuplicates(v.name);
        }

        // TS2397 ÃÂ¢ÃÂÃÂ `var globalThis;` (or `let`/`const`) shadows the
        // built-in lexical binding. tsc lists only `globalThis` in
        // its built-in conflict allow-list, anchored at the
        // identifier name. Ambient declarations are exempt because
        // they participate in the global type rather than introducing
        // a local binding.
        if (v.name != hir_mod.none_node_id and
            self.hir.kindOf(v.name) == .identifier)
        {
            const id = hir_mod.identifierOf(self.hir, v.name);
            const name_str = self.string_interner.get(id.name);
            if (self.nodeIsTopLevelOfSourceFile(node) and
                !v.is_ambient and
                !self.virtualSectionIsDeclarationFile(node))
            {
                try self.checkCollisionWithRequireExportsInGeneratedCode(v.name, id.name);
            }
            if (!v.is_ambient and std.mem.eql(u8, name_str, "globalThis")) {
                try self.report(
                    v.name,
                    TsCodes.declaration_name_conflicts_builtin_global,
                    "Declaration name conflicts with built-in global identifier 'globalThis'.",
                );
            }
        }

        // Top-level `await using` requires module=es2022+ AND
        // target=es2017+. The parser flags `is_await_using` on the
        // const-decl shape; here we mirror tsc's TS2854 when the
        // declaration sits outside any function-like context and the
        // source's `// @target` directive picks an older target.
        // Only fire when this is the first declarator on the line
        // (anchor matches tsc ÃÂ¢ÃÂÃÂ column = `await` keyword start) and
        // we're not inside an enclosing function.
        const starts_await_using_statement = if (self.source) |src|
            self.sourceSpanStartsWithKeyword(src, self.hir.spanOf(node).start, "await")
        else
            true;
        if (v.is_await_using and starts_await_using_statement and
            !self.nodeIsInsideFunctionLike(node) and
            self.sourceTargetDisallowsTopLevelAwait())
        {
            try self.report(node, TsCodes.top_level_await_using_target_module, "Top-level 'await using' statements are only allowed when the 'module' option is set to 'es2022', 'esnext', 'system', 'node16', 'node18', 'node20', 'nodenext', or 'preserve', and the 'target' option is set to 'es2017' or higher.");
        }

        // TS2502 ÃÂ¢ÃÂÃÂ `var x: typeof x` (or via an identical-name
        // qualifier-less typeof inside a tuple / array / union).
        // The full typeof-cycle detection lives in
        // `typeAliasCircularTypeofVarDecl`; the var-side counterpart
        // here catches the direct self-reference, which tsc reports
        // even when no intermediate alias is involved.
        //
        // Skip when a prior `var <name>` already exists in the same
        // scope (same virtual section). Upstream tsc treats subsequent
        // `var x: typeof x` as referring to the *previously declared*
        // `x` so no cycle exists. Mirrors `validMultipleVariableDeclarations`
        // and similar fixtures.
        if (v.type_annotation != hir_mod.none_node_id and
            v.name != hir_mod.none_node_id and
            self.hir.kindOf(v.name) == .identifier)
        {
            if (try self.firstVisibleStaticClassTypeParamRefIn(v.type_annotation, node)) |ref_node| {
                try self.report(ref_node, TsCodes.static_member_type_parameter, "Static members cannot reference class type parameters.");
            }
            const id = hir_mod.identifierOf(self.hir, v.name);
            if (self.varDeclTypeAnnotationContainsTypeofSelf(v.type_annotation, id.name)) {
                if (!self.priorVarDeclWithSameNameExists(node, id.name)) {
                    try self.reportSelfReferencedTypeAnnotationAtName(node);
                }
            } else if (self.varDeclTypeAnnotationHasMutualTypeofCycle(node, id.name) and
                !self.diagnosticExists(v.name, TsCodes.self_referenced_type_annotation))
            {
                try self.reportSelfReferencedTypeAnnotationAtName(node);
            }
        }

        // Lower type annotation first (so we can check init against it).
        var declared_type: TypeId = types.Primitive.none;
        if (v.type_annotation != hir_mod.none_node_id) {
            const unresolved_type_annotation = self.typeAnnotationContainsUnresolvedRef(v.type_annotation);
            try self.reportUnresolvedBareTypeRefsInAnnotation(v.type_annotation);
            declared_type = if (unresolved_type_annotation)
                types.Primitive.any
            else if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier)
                try self.lowerValueTypeAnnotation(hir_mod.identifierOf(self.hir, v.name).name, v.type_annotation)
            else
                try self.lowererLowerWithTypeParams(v.type_annotation);
            declared_type = try self.adjustAmbientUnresolvedBareTypeAnnotation(v.is_ambient, v.type_annotation, declared_type);
            self.hir.setType(node, declared_type);
        } else if (try self.jsDocTypeForVarDecl(node)) |jsdoc_t| {
            declared_type = jsdoc_t;
            self.hir.setType(node, declared_type);
        }

        // Type the initializer.
        var init_type: TypeId = if (v.is_ambient) types.Primitive.any else types.Primitive.undefined_t;
        if (!v.is_ambient and
            v.init == hir_mod.none_node_id and
            v.type_annotation == hir_mod.none_node_id and
            self.hir.kindOf(node) != .const_decl and
            !self.strict_flags.strict_null_checks and
            !self.strict_flags.no_implicit_any)
        {
            // Without strict null checking, an uninitialized mutable binding
            // is an evolving `any`, not the literal `undefined` type. This is
            // the widening performed by tsgo's variable-type inference for
            // `var dec;` / `let dec;` under `strict: false`.
            init_type = types.Primitive.any;
        }
        if (!v.is_ambient and
            v.init == hir_mod.none_node_id and
            v.type_annotation == hir_mod.none_node_id and
            self.hir.kindOf(node) != .const_decl and
            self.nodeIsInsideLoop(node) and
            !self.strict_flags.no_implicit_any)
        {
            init_type = types.Primitive.any;
        }
        if (v.init != hir_mod.none_node_id) {
            const init_diag_start = self.diagnostics.items.len;
            if (v.is_ambient) {
                // Upstream tsc allows constant-value initializers
                // (literal numbers, strings, bigints, booleans, and
                // unary `-N` / `+N` numeric literals) on ambient
                // `const` and `export const` declarations ÃÂ¢ÃÂÃÂ they're
                // treated as inline literal type annotations. Mirrors
                // fixtures `typesVersions.justIndex.ts(1,18)`,
                // `typesVersions.emptyTypes`, `scopedPackagesClassic`.
                const is_const_decl = self.hir.kindOf(node) == .const_decl;
                const has_type_annotation = v.type_annotation != hir_mod.none_node_id;
                if (is_const_decl and !has_type_annotation) {
                    // Annotation-less ambient `const`: a constant literal
                    // initializer is treated as an inline literal type and
                    // is allowed; anything else is TS1254, mirroring tsc's
                    // `checkAmbientInitializer`.
                    if (!self.ambientInitializerIsConstantValue(v.init)) {
                        try self.report(v.init, TsCodes.ambient_const_initializer_must_be_literal, "A 'const' initializer in an ambient context must be a string or numeric literal or literal enum reference.");
                    }
                } else {
                    try self.report(v.init, TsCodes.ambient_initializer_not_allowed, "Initializers are not allowed in ambient contexts.");
                }
            } else {
                init_type = try self.checkExpression(v.init);
            }
            if (declared_type == types.Primitive.none and
                init_type == types.Primitive.undefined_t and
                self.virtualSectionIsJsLike(node))
            {
                init_type = types.Primitive.any;
            }
            if (declared_type == types.Primitive.none and
                self.hir.kindOf(node) == .var_decl and
                v.name != hir_mod.none_node_id and
                self.hir.kindOf(v.name) == .identifier)
            {
                const id = hir_mod.identifierOf(self.hir, v.name);
                if (try self.varInitializerReferencesOwnBinding(v.init, id.name)) {
                    init_type = types.Primitive.any;
                }
            }
            if (declared_type == types.Primitive.none and !v.is_ambient and self.hir.kindOf(node) == .const_decl) {
                init_type = try self.constInitializerType(v.init, init_type);
            }
            // `let` / `var` initializers widen fresh literal values to
            // their primitive/owning enum type (tsc's `getWidenedType`
            // for mutable declarations). A `const` keeps the narrow
            // literal type.
            if (declared_type == types.Primitive.none and
                self.hir.kindOf(node) != .const_decl and
                self.mutableInitializerShouldWidenLiteral(v.init, init_type))
            {
                init_type = try self.widenFreshLiteralType(init_type);
            }
            if (declared_type != types.Primitive.none and
                v.name != hir_mod.none_node_id and
                self.hir.kindOf(v.name) == .identifier and
                self.isContextualFunctionExpressionLike(v.init))
            {
                const id = hir_mod.identifierOf(self.hir, v.name);
                if (try self.expandoAugmentedNarrowType(id.name, v.name, init_type)) |augmented_t| {
                    init_type = augmented_t;
                }
            }
            if (declared_type != types.Primitive.none) {
                if (try self.contextualGenericCallResult(v.init, init_type, declared_type)) |contextual_t| {
                    init_type = contextual_t;
                }
                self.clearContextualAnyObjectLiteralNullishImplicitAnyDiagnostics(v.init, declared_type, init_diag_start);
                if (self.objectLiteralUnionMismatchReportsAtDeclaration(v.init, declared_type)) {
                    self.removePriorDiagnosticsInNodeSpan(v.init, TsCodes.type_not_assignable);
                }
            }
            // Anonymous class-expression assigned to a `var X = class {ÃÂ¢ÃÂÃÂ¦}`
            // (or `let`/`const`) binding: register the static-side type
            // under the binding name so TS2339 prose renders as
            // `typeof X` instead of falling back to "Property 'p' does
            // not exist on type." truncation. Mirrors upstream tsc which
            // synthesizes the class name from the variable binding when
            // the class expression itself is anonymous. The parser emits
            // class expressions as `.class_decl` nodes with no `c.name`,
            // so we accept both kinds and gate on the missing class
            // name. Fixture: `typeFromPropertyAssignment29.ts(80,14)`.
            if (v.init != hir_mod.none_node_id and
                (self.hir.kindOf(v.init) == .class_expr or self.hir.kindOf(v.init) == .class_decl) and
                v.name != hir_mod.none_node_id and
                self.hir.kindOf(v.name) == .identifier)
            {
                const ce = hir_mod.classOf(self.hir, v.init);
                if (ce.name == hir_mod.none_node_id) {
                    const id = hir_mod.identifierOf(self.hir, v.name);
                    if (!self.class_static_types.contains(id.name)) {
                        try self.class_static_types.put(self.gpa, id.name, init_type);
                    }
                    if (!self.class_name_by_static.contains(init_type)) {
                        try self.class_name_by_static.put(self.gpa, init_type, id.name);
                    }
                }
            }
            if (declared_type == types.Primitive.none and
                self.sourceHasCheckJsDirective() and
                self.virtualSectionIsJsLike(node) and
                self.hir.kindOf(v.init) == .object_literal and
                v.name != hir_mod.none_node_id and
                self.hir.kindOf(v.name) == .identifier)
            {
                const id = hir_mod.identifierOf(self.hir, v.name);
                if (self.class_static_types.get(id.name)) |class_t| {
                    const ok = (self.objectLiteralAssignableToTarget(v.init, init_type, class_t) catch false) or
                        (self.engine.isAssignableTo(init_type, class_t) catch true);
                    if (!ok) {
                        const merge_target_t = try self.checkJsAmbientClassMergeStaticType(node, id.name, class_t);
                        if (!try self.tryReportSinglePropertyMissing(v.name, v.init, init_type, merge_target_t)) {
                            try self.report(v.name, TsCodes.type_missing_properties, "Type is missing the following properties from target type.");
                        }
                    }
                }
            }
            try self.checkUsingInitializerDisposable(v.init, init_type, v.is_using, v.is_await_using);
            if (self.strict_flags.no_implicit_any and
                declared_type == types.Primitive.none and
                v.type_annotation == hir_mod.none_node_id and
                v.name != hir_mod.none_node_id and
                self.hir.kindOf(v.name) == .identifier)
            {
                const id = hir_mod.identifierOf(self.hir, v.name);
                try self.reportAnonymousFunctionReturnSelfReferenceInInitializer(v.init, id.name, true);
            }
        }
        if (v.name != hir_mod.none_node_id and
            v.init == hir_mod.none_node_id and
            !v.is_ambient)
        {
            const nk = self.hir.kindOf(v.name);
            if (nk == .object_pattern or nk == .array_pattern) {
                try self.report(v.name, TsCodes.destructuring_decl_must_have_initializer, "A destructuring declaration must have an initializer.");
                if (self.strict_flags.no_implicit_any and v.type_annotation == hir_mod.none_node_id) {
                    try self.reportImplicitAnyBindingPatternElements(v.name, &.{});
                }
            }
        }
        var array_binding_iter_diag_fired = false;
        if (v.name != hir_mod.none_node_id and
            self.hir.kindOf(v.name) == .array_pattern and
            v.init != hir_mod.none_node_id and
            ((self.hir.kindOf(v.init) == .object_literal and !self.objectLiteralHasSymbolIteratorMethod(v.init)) or
                !self.isDestructuringIterableSourceType(init_type)) and
