            } else if (nk == .array_pattern and v.init != hir_mod.none_node_id) {
                try self.checkArrayBindingPatternAgainstType(v.name, final_type);
                try self.checkArrayBindingPatternAgainstArrayLiteral(v.name, v.init);
                // Under non-strict-null mode, destructuring from
                // `[undefined, null]` widens those positions to
                // implicit `any`; strict-null mode keeps concrete
                // nullish types and does not fire TS7031. Mirrors
                // `wideningTuples5` vs.
                // `noImplicitAnyDestructuringVarDeclaration`.
                if (declared_type == types.Primitive.none and !self.strict_flags.strict_null_checks) {
                    try self.reportImplicitAnyNullishArrayBinding(v.name, v.init);
                }
            }
            if ((nk == .object_pattern or nk == .array_pattern) and
                v.init != hir_mod.none_node_id and
                !self.nodeIsDirectSourceFileStatement(node))
            {
                try self.recordBindingPatternFlowFromSource(v.name, v.init, final_type);
            }
        }
        try self.checkRepeatedVarDeclaration(node, final_type);

        // Aliased conditional narrowing: `let cond = obj.kind === "x"`.
        // Record `cond -> guard_expr_node` so a subsequent `if (cond)`
        // applies the original guard. Only fires for `const`/`let`-style
        // bindings whose init is a recognizably-narrowing expression.
        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier and
            v.init != hir_mod.none_node_id and isNarrowingGuard(self.hir, v.init))
        {
            const id = hir_mod.identifierOf(self.hir, v.name);
            try self.cond_aliases.put(self.gpa, id.name, v.init);
        }

        // Aliased-discriminant narrowing (TS 4.4): a `const` that binds a
        // discriminant property of a narrowable reference records the
        // `(object, prop)` pair so a later `if (t === "x")` narrows the
        // referenced object rather than the alias. Mirrors `controlFlowAliasing2`.
        // Two binding shapes:
        //   `const t = obj.kind`            (member-access initializer)
        //   `const { kind: t } = obj`       (renamed object-destructuring)
        try self.recordDiscriminantAliases(node, v);

        if (self.strict_flags.no_implicit_any and
            !self.strict_flags.strict_null_checks and
            declared_type == types.Primitive.none and
            v.type_annotation == hir_mod.none_node_id and
            v.init != hir_mod.none_node_id and
            v.name != hir_mod.none_node_id and
            self.hir.kindOf(v.name) == .identifier)
        {
            try self.reportImplicitAnyNullishTupleVariable(v.name, v.init);
        }

        // TS7034 vs TS7005: tsc emits the more-specific TS7034 at the
        // DECLARATION of a `var p;` with no annotation and no
        // initializer when the variable's type can't be determined
        // (the "evolving any" flow). For `declare var X;` (ambient
        // declarations) tsc emits TS7005 instead because evolving-any
        // doesn't apply to ambient names ÃÂ¢ÃÂÃÂ they're externally
        // declared and unchangeable. We mirror that split here.
        // Hard error (TS7005/TS7034) under noImplicitAny; under
        // !noImplicitAny + suggestions-enabled the matching
        // `.suggestion`-category hints TS7043/TS7046 fire instead.
        const var_implicit_any_report = self.strict_flags.no_implicit_any or
            (self.emit_implicit_any_suggestions and !self.strict_flags.no_implicit_any);
        const recovered_private_indexed_access = self.varDeclIsRecoveredPrivateIndexedAccess(node, v.name);
        if (var_implicit_any_report and
            declared_type == types.Primitive.none and
            v.type_annotation == hir_mod.none_node_id and
            v.init == hir_mod.none_node_id and
            v.name != hir_mod.none_node_id and
            self.hir.kindOf(v.name) == .identifier and
            !self.untypedVarHasLaterDirectAssignment(node, hir_mod.identifierOf(self.hir, v.name).name) and
            !self.untypedVarHasLaterClassFallbackRead(node, hir_mod.identifierOf(self.hir, v.name).name) and
            !self.untypedVarIsReadOnlyByJsxSpread(node, hir_mod.identifierOf(self.hir, v.name).name) and
            (!self.varDeclHasMalformedListSyntax(node, v.name) or recovered_private_indexed_access) and
            !self.varDeclSharesLineWithDestructuringWithoutInitializer(node) and
            (!self.varDeclIsInsideFunctionLike(node) or recovered_private_indexed_access) and
            !self.varDeclIsReservedAwaitInStaticBlock(node, v.name))
        {
            const var_is_suggestion = !self.strict_flags.no_implicit_any;
            const var_name: []const u8 = if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier)
                self.string_interner.get(hir_mod.identifierOf(self.hir, v.name).name)
            else
                "<anonymous>";
            const is_ambient = v.is_ambient;
            // `const X;` (no init) is a TS1155 syntax error, but tsc
            // still emits the implicit-any diagnostic ÃÂ¢ÃÂÃÂ and it uses
            // TS7005 (not TS7034) because const has no evolving-any
            // flow (the binding can never be reassigned to widen its
            // type). Mirrors fixture `for-of2` where `const v;` expects
            // TS7005 alongside TS1155.
            const is_const = self.hir.kindOf(node) == .const_decl;
            const use_ts7005 = is_ambient or is_const;
            const msg = if (var_is_suggestion and use_ts7005)
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Variable '{s}' implicitly has an 'any' type, but a better type may be inferred from usage.",
                    .{var_name},
                )
            else if (var_is_suggestion)
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Variable '{s}' implicitly has type 'any' in some locations, but a better type may be inferred from usage.",
                    .{var_name},
                )
            else if (use_ts7005)
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Variable '{s}' implicitly has an 'any' type.",
                    .{var_name},
                )
            else
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Variable '{s}' implicitly has type 'any' in some locations where its type cannot be determined.",
                    .{var_name},
                );
            const var_code: u32 = if (var_is_suggestion and use_ts7005)
                TsCodes.variable_implicitly_any_suggestion
            else if (var_is_suggestion)
                TsCodes.variable_implicitly_any_locations_suggestion
            else if (use_ts7005)
                TsCodes.variable_implicitly_any
            else
                TsCodes.variable_implicitly_any_declaration;
            try self.diagnostics.append(self.gpa, .{
                .node = if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) v.name else node,
                .code = var_code,
                .message = msg,
                .category = if (var_is_suggestion) .suggestion else .error_,
            });
        }
        try self.reportCapturedEvolvingAnyDiagnostics(node, declared_type);
    }

    fn checkUsingInitializerDisposable(
        self: *Checker,
        init_node: NodeId,
        init_t: TypeId,
        is_using: bool,
        is_await_using: bool,
    ) CheckError!void {
        if (init_node == hir_mod.none_node_id) return;
        if (!is_using and !is_await_using) return;
        if (!try self.checkUsingGlobalTypesAvailable(init_node, is_await_using)) return;
        const ok = if (is_await_using)
            try self.typeIsAsyncDisposableInitializer(init_t)
        else
            try self.typeIsDisposableInitializer(init_t);
        if (ok) return;
        if (is_await_using) {
            try self.report(
                init_node,
                TsCodes.await_using_initializer_disposable,
                "The initializer of an 'await using' declaration must be either an object with a '[Symbol.asyncDispose]()' or '[Symbol.dispose]()' method, or be 'null' or 'undefined'.",
            );
        } else {
            try self.report(
                init_node,
                TsCodes.using_initializer_disposable,
                "The initializer of a 'using' declaration must be either an object with a '[Symbol.dispose]()' method, or be 'null' or 'undefined'.",
            );
        }
    }

    fn checkUsingGlobalTypesAvailable(self: *Checker, node: NodeId, await_using: bool) CheckError!bool {
        if (!self.sourceHasNoLibTrueDirective() and !self.sourceLibDirectiveExcludesExplicitResourceManagement()) return true;

        var available = true;
        if (await_using) {
            available = try self.checkUsingGlobalTypeAvailable(node, "AsyncDisposable") and available;
        }
        available = try self.checkUsingGlobalTypeAvailable(node, "Disposable") and available;
        return available;
    }

    fn checkUsingGlobalTypeAvailable(self: *Checker, node: NodeId, name: []const u8) CheckError!bool {
        const root = self.rootBlockFor(node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) {
            try self.reportMissingGlobalTypeOnce(node, name);
            return false;
        }
        const decl = self.topLevelGlobalTypeDecl(hir_mod.blockStmts(self.hir, root), name) orelse {
            try self.reportMissingGlobalTypeOnce(node, name);
            return false;
        };
        switch (self.hir.kindOf(decl.node)) {
            .interface_decl, .class_decl, .class_expr => {
                const actual = self.declarationTypeParameterCount(decl.node);
                if (actual == 0) return true;
                try self.reportGlobalTypeWrongArity(decl.name_node, name, 0);
            },
            else => try self.reportGlobalTypeMustBeClassOrInterface(decl.name_node, name),
        }
        return false;
    }

    fn typeIsDisposableInitializer(self: *Checker, t: TypeId) CheckError!bool {
        if (self.typeIsAnyLike(t)) return true;
        if (t == types.Primitive.never or t == types.Primitive.null_t or t == types.Primitive.undefined_t) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!try self.typeIsDisposableInitializer(member)) return false;
            }
            return true;
        }
        return try self.typeHasCallableWellKnownMember(t, "Symbol.dispose");
    }

    fn typeIsAsyncDisposableInitializer(self: *Checker, t: TypeId) CheckError!bool {
        if (self.typeIsAnyLike(t)) return true;
        if (t == types.Primitive.never or t == types.Primitive.null_t or t == types.Primitive.undefined_t) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!try self.typeIsAsyncDisposableInitializer(member)) return false;
            }
            return true;
        }
        return (try self.typeHasCallableWellKnownMember(t, "Symbol.asyncDispose")) or
            (try self.typeHasCallableWellKnownMember(t, "Symbol.dispose"));
    }

    fn typeHasCallableWellKnownMember(self: *Checker, t: TypeId, name: []const u8) CheckError!bool {
        const member_name = self.string_interner.intern(name) catch return error.OutOfMemory;
        const member_t = (try self.lookupObjectMember(t, member_name)) orelse return false;
        return self.typeHasNonConstructCallSignature(member_t);
    }

    /// `let await;` inside a `class C { static { ... } }` block fires
    /// TS1359 (reserved-word binding) and tsc suppresses the matching
    /// TS7034 implicit-any since the binding is effectively invalid.
    fn varDeclIsReservedAwaitInStaticBlock(self: *Checker, node: NodeId, name_node: NodeId) bool {
        if (!self.nodeIsInClassStaticBlockBeforeFunction(node)) return false;
        const await_id = self.string_interner.intern("await") catch return false;
        return self.findAwaitBindingIdentifier(name_node, await_id) != null;
    }

    fn varDeclIsRecoveredPrivateIndexedAccess(self: *Checker, node: NodeId, name_node: NodeId) bool {
        if (self.hir.kindOf(node) != .const_decl or
            name_node == hir_mod.none_node_id or
            self.hir.kindOf(name_node) != .identifier)
        {
            return false;
        }
        const name = self.string_interner.get(hir_mod.identifierOf(self.hir, name_node).name);
        if (name.len < 2 or name[0] != '#') return false;
        const src = self.source orelse return false;
        const span = self.hir.spanOf(name_node);
        return span.start > 0 and span.start <= src.len and src[span.start - 1] == '[';
    }

    fn varDeclHasMalformedListSyntax(self: *Checker, node: NodeId, name_node: NodeId) bool {
        if (name_node != hir_mod.none_node_id and self.hir.kindOf(name_node) == .identifier) {
            const name = self.string_interner.get(hir_mod.identifierOf(self.hir, name_node).name);
            if (name.len == 0) return true;
        }
        const src = self.source orelse return false;
        const span = self.hir.spanOf(node);
        if (span.start >= span.end or span.end > src.len) return false;
        var i: usize = span.end;
        while (i > span.start) {
            i -= 1;
            const c = src[i];
            if (c == ';' or c == ' ' or c == '\t' or c == '\r' or c == '\n') continue;
            return c == ',';
        }
        return false;
    }

    fn varDeclSharesLineWithDestructuringWithoutInitializer(self: *Checker, node: NodeId) bool {
        const src = self.source orelse return false;
        const span = self.hir.spanOf(node);
        if (span.start > src.len) return false;
        var line_start: usize = span.start;
        while (line_start > 0 and src[line_start - 1] != '\n') : (line_start -= 1) {}
        var line_end: usize = span.start;
        while (line_end < src.len and src[line_end] != '\n') : (line_end += 1) {}
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const stmts: ?[]const NodeId = switch (self.hir.kindOf(cur)) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl => hir_mod.namespaceBody(self.hir, cur),
                else => null,
            };
            const items = stmts orelse continue;
            for (items) |stmt| {
                if (stmt == node) continue;
                const k = self.hir.kindOf(stmt);
                if (k != .var_decl and k != .let_decl and k != .const_decl) continue;
                const s = self.hir.spanOf(stmt);
                if (s.start < line_start or s.start > line_end) continue;
                const v = hir_mod.varDeclOf(self.hir, stmt);
                if (v.init != hir_mod.none_node_id or v.name == hir_mod.none_node_id) continue;
                const nk = self.hir.kindOf(v.name);
                if (nk == .object_pattern or nk == .array_pattern) return true;
            }
            return false;
        }
        return false;
    }

    /// TS2431 ÃÂ¢ÃÂÃÂ names of built-in primitive types that may not be
    /// reused as enum-declaration names. tsc rejects these outright.
    fn isReservedPrimitiveTypeName(name: []const u8) bool {
        return std.mem.eql(u8, name, "any") or
            std.mem.eql(u8, name, "number") or
            std.mem.eql(u8, name, "string") or
            std.mem.eql(u8, name, "boolean") or
            std.mem.eql(u8, name, "symbol") or
            std.mem.eql(u8, name, "bigint");
    }

    fn varDeclIsInsideFunctionLike(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .fn_decl, .fn_expr, .arrow_fn => return true,
                .source_file => return false,
                else => {},
            }
        }
        return false;
    }

    fn reportCapturedEvolvingAnyDiagnostics(self: *Checker, node: NodeId, declared_type: TypeId) CheckError!void {
        if (!self.strict_flags.no_implicit_any) return;
        if (declared_type != types.Primitive.none) return;
        if (!self.varDeclIsInsideFunctionLike(node)) return;
        if (!self.varDeclIsCapturedEvolvingAnyCandidate(node)) return;
        const v = hir_mod.varDeclOf(self.hir, node);
        if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) return;
        const id = hir_mod.identifierOf(self.hir, v.name);
        var reads: std.ArrayListUnmanaged(NodeId) = .empty;
        defer reads.deinit(self.gpa);
        if (!try self.collectCapturedEvolvingAnyReads(node, id.name, &reads)) return;
        const is_array = v.init != hir_mod.none_node_id and self.hir.kindOf(v.init) == .array_literal;
        const implicit_type = if (is_array) "any[]" else "any";
        const name_str = self.string_interner.get(id.name);
        const decl_msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Variable '{s}' implicitly has type '{s}' in some locations where its type cannot be determined.",
            .{ name_str, implicit_type },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = v.name,
            .code = TsCodes.variable_implicitly_any_declaration,
            .message = decl_msg,
        });
        if (is_array) {
            for (reads.items) |use_node| {
                const assignment = self.evolvingAnyYieldFeedbackAssignment(use_node, id.name) orelse continue;
                const target = hir_mod.assignmentOf(self.hir, assignment).target;
                if (self.diagnosticExists(target, TsCodes.type_not_assignable)) continue;
                try self.report(
                    target,
                    TsCodes.type_not_assignable,
                    "Type 'undefined' is not assignable to type 'any[]'.",
                );
            }
        }
        const use_msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Variable '{s}' implicitly has an '{s}' type.",
            .{ name_str, implicit_type },
        );
        for (reads.items) |use_node| {
            if (self.diagnosticExists(use_node, TsCodes.variable_implicitly_any)) continue;
            try self.diagnostics.append(self.gpa, .{
                .node = use_node,
                .code = TsCodes.variable_implicitly_any,
                .message = use_msg,
            });
        }
    }

    fn collectCapturedEvolvingAnyReads(
        self: *Checker,
        decl: NodeId,
        name: hir_mod.StringId,
        reads: *std.ArrayListUnmanaged(NodeId),
    ) CheckError!bool {
        const owner = self.enclosingFunctionLike(decl) orelse return false;
        const decl_end = self.hir.spanOf(decl).end;
        const section = self.virtualSectionStartForNode(decl);
        var has_captured_read = false;
        var candidate: NodeId = 0;
        while (candidate < self.hir.nodeCount()) : (candidate += 1) {
            if (self.hir.kindOf(candidate) != .identifier) continue;
            if (self.hir.spanOf(candidate).start < decl_end) continue;
            if (self.virtualSectionStartForNode(candidate) != section) continue;
            if (!self.nodeHasAncestor(candidate, owner)) continue;
            if (self.isDeclNameSlot(candidate)) continue;
            if (hir_mod.identifierOf(self.hir, candidate).name != name) continue;
            if (self.capturedEvolvingAnyReferenceIsWrite(candidate)) continue;
            try reads.append(self.gpa, candidate);
            if (self.enclosingFunctionLike(candidate) != owner or
                self.evolvingAnyYieldFeedbackAssignment(candidate, name) != null)
            {
                has_captured_read = true;
            }
        }
        return has_captured_read;
    }

    fn evolvingAnyYieldFeedbackAssignment(self: *Checker, node: NodeId, name: hir_mod.StringId) ?NodeId {
        var cur = self.hir.parentOf(node);
        var yield_node = hir_mod.none_node_id;
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .yield_expr => {
                    if (hir_mod.yieldExprOf(self.hir, cur).type_node == hir_mod.none_node_id) return null;
                    yield_node = cur;
                },
                .assignment => {
                    if (yield_node == hir_mod.none_node_id) return null;
                    const assignment = hir_mod.assignmentOf(self.hir, cur);
                    if (assignment.value != yield_node or
                        assignment.target == hir_mod.none_node_id or
                        self.hir.kindOf(assignment.target) != .identifier)
                    {
                        return null;
                    }
                    return if (hir_mod.identifierOf(self.hir, assignment.target).name == name) cur else null;
                },
                .fn_decl, .fn_expr, .arrow_fn => return null,
                else => {},
            }
        }
        return null;
    }

    fn capturedEvolvingAnyReferenceIsWrite(self: *Checker, node: NodeId) bool {
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(parent) == .assignment and hir_mod.assignmentOf(self.hir, parent).target == node) {
            return true;
        }
        if (self.hir.kindOf(parent) != .member_access) return false;
        const member = hir_mod.memberOf(self.hir, parent);
        if (member.object != node) return false;
        const method = self.string_interner.get(member.name);
        if (!std.mem.eql(u8, method, "push") and !std.mem.eql(u8, method, "unshift")) return false;
        const call = self.hir.parentOf(parent);
        return call != hir_mod.none_node_id and self.hir.kindOf(call) == .call_expr and
            hir_mod.callOf(self.hir, call).callee == parent;
    }

    fn shouldRecordDeclaredVariableFlowNarrow(
        self: *Checker,
        declared_type: TypeId,
        flow_t: TypeId,
        final_type: TypeId,
    ) CheckError!bool {
        if (declared_type == types.Primitive.none) return true;
        if (self.annotatedArrayLookupShouldUseDeclared(flow_t, final_type)) return false;
        if (self.typeIsObjectLikePredicateMember(final_type)) return false;
        if (self.primitiveAssertionMatchesWrapper(flow_t, final_type)) return false;
        if (self.isConcretePrimitiveLike(flow_t) and self.typeIsObjectLikePredicateMember(final_type)) return false;
        if (flow_t == final_type or (self.engine.isIdenticalTo(flow_t, final_type) catch false)) return true;
        if (flow_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(flow_t).is_literal) return false;
        return self.engine.isAssignableTo(flow_t, final_type) catch false;
    }

    /// True when `node` is a member-access expression statement in a checked-JS
    /// context whose leading JSDoc block declares a `@typedef` — i.e. the
    /// `/** @typedef {T} */ ns.Member;` type-declaration idiom, which tsc treats
    /// as a declaration rather than a value member access.
    fn memberExprStatementDeclaresJsDocTypedef(self: *Checker, node: NodeId) bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        if (!self.virtualSectionIsJsLike(node)) return false;
        const src = self.source orelse return false;
        const jsdoc = self.leadingJsDocBodyWithStart(src, self.hir.spanOf(node).start) orelse return false;
        return std.mem.indexOf(u8, jsdoc.body, "@typedef") != null;
    }

    fn virtualSectionIsJsLike(self: *Checker, node: NodeId) bool {
        const filename = self.virtualSectionFilenameForNode(node) orelse {
            if (self.sourceHasVirtualFilenameSections()) return false;
            return self.pathIsJsLike(self.importer_path);
        };
        return self.pathIsJsLike(filename);
    }

    fn pathIsJsLike(self: *Checker, path: []const u8) bool {
        _ = self;
        return std.mem.endsWith(u8, path, ".js") or
            std.mem.endsWith(u8, path, ".jsx") or
            std.mem.endsWith(u8, path, ".mjs") or
            std.mem.endsWith(u8, path, ".cjs");
    }

    fn pathIsAlwaysEsmJsLike(self: *Checker, path: []const u8) bool {
        _ = self;
        return std.mem.endsWith(u8, path, ".mjs");
    }

    fn jsLikeSectionHasImplicitCommonJsGlobals(self: *Checker, node: NodeId) bool {
        if (!self.virtualSectionIsJsLike(node)) return false;
        const filename = self.virtualSectionFilenameForNode(node) orelse self.importer_path;
        if (self.pathIsAlwaysEsmJsLike(filename)) return false;
        // A .cjs section is always CommonJS by extension -- keep the
        // implicit require/module globals even when it (erroneously)
        // carries top-level ESM syntax. Mirrors modulePreserve4 main3.cjs.
        if (std.mem.endsWith(u8, filename, ".cjs")) return true;
        return !self.jsLikeSectionIsExternalModule(node);
    }

    fn jsLikeSectionIsExternalModule(self: *Checker, node: NodeId) bool {
        if (!self.sourceHasVirtualFilenameSections()) return self.rootHasTopLevelExternalModuleMarker(node);

        const src = self.source orelse return false;
        const section_start = self.virtualSectionStartForNode(node);
        const section_end = self.virtualSectionEndForNode(node);
        if (section_start < section_end and section_end <= src.len) {
            if (std.mem.indexOf(u8, src[section_start..section_end], "import.meta") != null) return true;
        }

        const root = self.rootBlockFor(node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            const sp = self.hir.spanOf(stmt);
            if (sp.start < section_start or sp.start >= section_end) continue;
            switch (self.hir.kindOf(stmt)) {
                .import_decl, .export_decl => return true,
                else => {},
            }
        }
        return false;
    }

    fn sourceHasSingleJsLikeVirtualCodeSection(self: *Checker) bool {
        const src = self.source orelse return false;
        var saw_code = false;
        var saw_js = false;
        var lines = std.mem.splitScalar(u8, src, '\n');
        while (lines.next()) |raw_line| {
            const line = std.mem.trim(u8, raw_line, " \t\r");
            const marker = std.mem.indexOf(u8, line, "@filename:") orelse
                (std.mem.indexOf(u8, line, "@Filename:") orelse continue);
            const filename = std.mem.trim(u8, line[marker + "@filename:".len ..], " \t\r");
            const is_js = self.pathIsJsLike(filename);
            const is_code = is_js or
                std.mem.endsWith(u8, filename, ".ts") or
                std.mem.endsWith(u8, filename, ".tsx") or
                std.mem.endsWith(u8, filename, ".mts") or
                std.mem.endsWith(u8, filename, ".cts");
            if (!is_code) continue;
            if (saw_code) return false;
            saw_code = true;
            saw_js = is_js;
        }
        return saw_code and saw_js;
    }

    /// True when `name_node`'s source span begins with a string-literal
    /// quote (`"` or `'`). Distinguishes `module "fs" { ... }` (string
    /// name ÃÂ¢ÃÂÃÂ module augmentation, not subject to TS8006) from
    /// `namespace A { ... }` (identifier name ÃÂ¢ÃÂÃÂ TS8006 applies in JS).
    fn namespaceNameIsStringLiteral(self: *Checker, name_node: NodeId) bool {
        if (name_node == hir_mod.none_node_id) return false;
        const src = self.source orelse return false;
        const span = self.hir.spanOf(name_node);
        if (span.start >= src.len) return false;
        const c = src[span.start];
        return c == '"' or c == '\'';
    }

    /// TS8006 ÃÂ¢ÃÂÃÂ `interface` / `enum` / `namespace` / `type` declarations
    /// inside a `.js` virtual section. Mirrors upstream tsc which gates
    /// these declarations behind the TypeScript syntax. Anchored at the
    /// position of the declaration's name identifier so the column
    /// matches `index.js(4,18)` for `export interface A {}`.
    fn checkTsOnlyDeclInJs(self: *Checker, node: NodeId, kind: []const u8, name_node: NodeId) CheckError!void {
        if (!self.virtualSectionIsJsLike(node)) return;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' declarations can only be used in TypeScript files.",
            .{kind},
        );
        const anchor = if (name_node != hir_mod.none_node_id) name_node else node;
        try self.diagnostics.append(self.gpa, .{
            .node = anchor,
            .code = TsCodes.ts_only_decl_in_js,
            .message = msg,
        });
    }

    /// TS8004 for type parameter declarations that appear in JS-like
    /// virtual sections. Unlike checked-JS type annotation diagnostics,
    /// this is emitted even without `@checkJs` because the syntax itself
    /// is TS-only. The type-parameter HIR span starts at the name token
    /// for ordinary `<T>`, matching upstream's `function F<T>() { }`
    /// column at the `T`.
    fn checkJsOnlyTypeParameters(self: *Checker, owner: NodeId, type_params: []const NodeId) CheckError!void {
        if (!self.virtualSectionIsJsLike(owner)) return;
        for (type_params) |tp| {
            if (self.hir.kindOf(tp) != .type_parameter) continue;
            const span = self.hir.spanOf(tp);
            try self.diagnostics.append(self.gpa, .{
                .node = tp,
                .pos = span.start,
                .code = TsCodes.ts_only_type_parameter_in_js,
                .message = try self.diag_arena.allocator().dupe(u8, "Type parameter declarations can only be used in TypeScript files."),
            });
        }
    }

    fn checkJsOnlySignatureDeclaration(self: *Checker, node: NodeId) CheckError!void {
        if (!self.virtualSectionIsJsLike(node)) return;
        const f = hir_mod.fnDeclOf(self.hir, node);
        if (f.body != hir_mod.none_node_id) return;
        if (f.flags.is_getter or f.flags.is_setter) return;
        const anchor = if (!f.flags.is_constructor and f.name != hir_mod.none_node_id) f.name else node;
        for (self.diagnostics.items) |d| {
            if (d.code == TsCodes.ts_only_signature_decl_in_js and d.node == anchor) return;
        }
        try self.reportAt(
            anchor,
            null,
            TsCodes.ts_only_signature_decl_in_js,
            "Signature declarations can only be used in TypeScript files.",
        );
    }

    /// parserArrowFunctionExpression10/13/14/15/16/17: emit TS8010 for
    /// every parameter type annotation, every return-type annotation,
    /// and TS8009 for every `?` optional marker that appears on a
    /// function/arrow declared inside a `.js`/`.jsx`/`.mjs`/`.cjs`
    /// virtual section opted into checking via `// @allowjs: true` +
    /// `// @checkjs: true`. The TS8010 anchor lands on the type
    /// annotation's source-start (e.g. the `n` of `number`), the
    /// TS8009 anchor lands on the `?` token between the parameter
    /// name and its `:` annotation (or trailing `,`/`)`).
    fn checkJsOnlySignatureAnnotations(self: *Checker, node: NodeId) CheckError!void {
        if (!self.virtualSectionIsJsLike(node)) return;
        try self.checkJsOnlySignatureDeclaration(node);
        try self.checkJsOnlyTypeParameters(node, hir_mod.fnTypeParams(self.hir, node));
        if (!self.check_js_enabled and !self.sourceHasCheckJsDirective()) return;
        const src = self.source orelse return;
        const f = hir_mod.fnDeclOf(self.hir, node);
        const params = hir_mod.fnParams(self.hir, node);
        for (params) |p| {
            if (self.hir.kindOf(p) != .parameter) continue;
            const pp = hir_mod.parameterOf(self.hir, p);
            if (pp.flags.is_optional and !pp.flags.is_rest) {
                if (pp.name != hir_mod.none_node_id) {
                    const name_span = self.hir.spanOf(pp.name);
                    var i: usize = name_span.end;
                    while (i < src.len and (src[i] == ' ' or src[i] == '\t')) : (i += 1) {}
                    if (i < src.len and src[i] == '?') {
                        try self.diagnostics.append(self.gpa, .{
                            .node = p,
                            .pos = @intCast(i),
                            .code = TsCodes.ts_only_optional_modifier_in_js,
                            .message = try self.diag_arena.allocator().dupe(u8, "The '?' modifier can only be used in TypeScript files."),
                        });
                    }
                }
            }
            if (pp.type_annotation != hir_mod.none_node_id) {
                const t_span = self.hir.spanOf(pp.type_annotation);
                try self.diagnostics.append(self.gpa, .{
                    .node = pp.type_annotation,
                    .pos = t_span.start,
                    .code = TsCodes.ts_only_type_annotation_in_js,
                    .message = try self.diag_arena.allocator().dupe(u8, "Type annotations can only be used in TypeScript files."),
                });
            }
        }
        if (f.return_type != hir_mod.none_node_id) {
            const r_span = self.hir.spanOf(f.return_type);
            try self.diagnostics.append(self.gpa, .{
                .node = f.return_type,
                .pos = r_span.start,
                .code = TsCodes.ts_only_type_annotation_in_js,
                .message = try self.diag_arena.allocator().dupe(u8, "Type annotations can only be used in TypeScript files."),
            });
        }
    }

    /// True when the function declaration/expression at `fn_node` has
    /// a leading `/** @param ... <name> */` JSDoc tag for the given
    /// parameter name. Used to suppress TS7006 (implicit-any param) on
    /// `.js` sources where JSDoc supplies the type ÃÂ¢ÃÂÃÂ mirrors upstream
    /// tsc which lowers `@param` into the parameter's type slot.
    fn fnHasLeadingJsDocParam(self: *Checker, fn_node: NodeId, param_name: []const u8) bool {
        if (param_name.len == 0) return false;
        const src = self.source orelse return false;
        const body = self.leadingJsDocBodyForFunctionOrOwner(src, fn_node) orelse return false;
        const tags = ts_parser.jsdoc.parse(self.gpa, body) catch return false;
        defer self.gpa.free(tags);
        for (tags) |tag| {
            if (tag.kind != .param_tag) continue;
            // `@param {T} name [desc]` ÃÂ¢ÃÂÃÂ match by name.
            if (std.mem.eql(u8, tag.name, param_name)) return true;
        }
        return false;
    }

    fn functionOrOwnerHasLeadingJsDocParamOrTypeTag(self: *Checker, fn_node: NodeId) bool {
        const src = self.source orelse return false;
        const body = self.leadingJsDocBodyForFunctionOrOwner(src, fn_node) orelse return false;
        if (std.mem.indexOf(u8, body, "@param") != null) return true;
        var has_type_marker = false;
        var marker_start: usize = 0;
        while (std.mem.indexOfPos(u8, body, marker_start, "@type")) |marker| {
            const after = marker + "@type".len;
            if (after == body.len or std.ascii.isWhitespace(body[after]) or body[after] == '{') {
                has_type_marker = true;
                break;
            }
            marker_start = after;
        }
        const tags = ts_parser.jsdoc.parse(self.gpa, body) catch return has_type_marker;
        defer self.gpa.free(tags);
        var saw_type_tag = false;
        for (tags) |tag| {
            if (tag.kind == .param_tag) return true;
            if (tag.kind != .type_tag) continue;
            saw_type_tag = true;
            const type_text = std.mem.trim(u8, tag.type_text, " \t\r\n");
            // The broad builtins describe an untyped callable rather than a
            // contextual signature, so their parameters still owe TS7006.
            if (std.mem.eql(u8, type_text, "Function") or
                std.mem.eql(u8, type_text, "function")) continue;
            return true;
        }
        return has_type_marker and !saw_type_tag;
    }

    fn checkUnmatchedJsDocParameters(self: *Checker, fn_node: NodeId) CheckError!void {
        if (!self.sourceHasCheckJsDirective()) return;
        if (!self.virtualSectionIsJsLike(fn_node)) return;
        const src = self.source orelse return;
        const jsdoc = self.leadingJsDocBodyForFunctionOrOwnerWithStart(src, fn_node) orelse return;
        if (std.mem.indexOf(u8, jsdoc.body, "@param") == null) return;
        // A `@callback` definition in the same block documents the callback's
        // parameters with `@param`, not the enclosing function's — so those
        // tags must not be validated against the function's parameter list
        // (callbackOnConstructor). tsc associates them with the callback.
        if (std.mem.indexOf(u8, jsdoc.body, "@callback") != null) return;
        const tags = ts_parser.jsdoc.parse(self.gpa, jsdoc.body) catch return;
        defer self.gpa.free(tags);

        var jsdoc_param_index: usize = 0;
        const contains_arguments = try self.functionBodyReferencesArguments(fn_node);
        for (tags) |tag| {
            if (tag.kind != .param_tag) continue;
            // A dotted `@param` name (`config.additionalFiles`) documents a
            // nested PROPERTY of a destructured/object parameter, not a
            // positional parameter — tsc validates it against the parent's
            // binding-pattern shape and never counts it as a position or
            // fires TS8024. Skip it WITHOUT advancing the positional index.
            // Mirrors `destructuringParameterDeclaration9`.
            if (std.mem.indexOfScalar(u8, tag.name, '.') != null) continue;
            defer jsdoc_param_index += 1;
            if (tag.name.len == 0) continue;
            if (contains_arguments) continue;
            if (self.fnParamAtIndexIsBindingPattern(fn_node, jsdoc_param_index)) continue;
            if (self.fnHasIdentifierParamNamed(fn_node, tag.name)) continue;
            if (tag.is_name_first) continue;
            // `@param {object} opts` followed by dotted `@param opts.a` children
            // documents an object/destructured parameter and matches the
            // corresponding positional parameter regardless of its binding
            // shape — its presence of dotted descendants proves intent, so
            // don't fire TS8024 (jsDeclarationsOptionalTypeLiteralProps2).
            if (jsDocAnyDottedParamWithPrefix(tags, tag.name)) continue;

            const pos = self.sliceStartPos(src, tag.name) orelse @as(u32, @intCast(jsdoc.start));
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "JSDoc '@param' tag has name '{s}', but there is no parameter with that name.",
                .{tag.name},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = fn_node,
                .pos = pos,
                .code = TsCodes.jsdoc_param_name_no_parameter,
                .message = msg,
            });
        }
    }

    /// True if any `@param` tag has a dotted name with `prefix` as its head
    /// (`prefix.child`) — i.e. `prefix` documents an object parameter whose
    /// properties are described by the dotted children.
    fn jsDocAnyDottedParamWithPrefix(tags: []const ts_parser.jsdoc.Tag, prefix: []const u8) bool {
        if (prefix.len == 0) return false;
        for (tags) |t| {
            if (t.kind != .param_tag) continue;
            if (t.name.len > prefix.len and
                std.mem.startsWith(u8, t.name, prefix) and
                t.name[prefix.len] == '.') return true;
        }
        return false;
    }

    fn fnParamAtIndexIsBindingPattern(self: *Checker, fn_node: NodeId, wanted_index: usize) bool {
        const params = hir_mod.fnParams(self.hir, fn_node);
        if (wanted_index >= params.len) return false;
        const p = params[wanted_index];
        if (self.hir.kindOf(p) != .parameter) return false;
        const pp = hir_mod.parameterOf(self.hir, p);
        if (pp.name == hir_mod.none_node_id) return false;
        const kind = self.hir.kindOf(pp.name);
        return kind == .object_pattern or kind == .array_pattern;
    }

    /// TS1069 ÃÂ¢ÃÂÃÂ JSDoc `@template {X}` (no trailing identifier) is the
    /// canonical "user put curly braces where the type-parameter name
    /// should go" mistake. Upstream's `parseJSDocIdentifierName` is
    /// called inside `parseTemplateTagTypeParameter` with the dedicated
    /// "Unexpected token. A type parameter name was expected without
    /// curly braces." message. Home's JSDoc layer captures the
    /// `{...}` as a type-constraint slice and leaves `tag.name`
    /// empty in this shape ÃÂ¢ÃÂÃÂ recognize that combination here and
    /// surface TS1069 with upstream-faithful anchor (immediately
    /// after the closing `}`). Mirrors `jsdocOuterTypeParameters1.js`
    /// and `jsdocTemplateTag3.js` baselines.
    fn checkJsDocTemplateBracketedName(self: *Checker, fn_node: NodeId) CheckError!void {
        if (!self.sourceHasCheckJsDirective()) return;
        if (!self.virtualSectionIsJsLike(fn_node)) return;
        const src = self.source orelse return;
        const jsdoc = self.leadingJsDocBodyForFunctionOrOwnerWithStart(src, fn_node) orelse return;
        if (std.mem.indexOf(u8, jsdoc.body, "@template") == null) return;
        const tags = ts_parser.jsdoc.parse(self.gpa, jsdoc.body) catch return;
        defer self.gpa.free(tags);
        for (tags) |tag| {
            if (tag.kind != .template_tag) continue;
            if (tag.name.len != 0) continue;
            if (tag.type_text.len == 0) continue;
            _ = try self.jsDocTypeTextToTypeAt(src, tag.type_text, fn_node);
            const inner_pos = self.sliceStartPos(src, tag.type_text) orelse continue;
            const after_constraint = @as(usize, inner_pos) + tag.type_text.len + 1;
            const pos = blk: {
                const line_end = std.mem.indexOfScalarPos(u8, src, @min(after_constraint, src.len), '\n') orelse
                    break :blk @as(u32, @intCast(after_constraint));
                var next = line_end + 1;
                while (next < src.len and (src[next] == ' ' or src[next] == '\t')) : (next += 1) {}
                if (next < src.len and src[next] == '*') break :blk @as(u32, @intCast(next));
                break :blk @as(u32, @intCast(after_constraint));
            };
            try self.diagnostics.append(self.gpa, .{
                .node = fn_node,
                .pos = pos,
                .code = 1069,
                .message = "Unexpected token. A type parameter name was expected without curly braces.",
            });
        }
    }

    fn fnHasIdentifierParamNamed(self: *Checker, fn_node: NodeId, wanted: []const u8) bool {
        for (hir_mod.fnParams(self.hir, fn_node)) |p| {
            if (self.hir.kindOf(p) != .parameter) continue;
            const pp = hir_mod.parameterOf(self.hir, p);
            if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
            const name = self.string_interner.get(hir_mod.identifierOf(self.hir, pp.name).name);
            if (std.mem.eql(u8, name, wanted)) return true;
        }
        return false;
    }

    fn fnHasJsDocTemplateTags(self: *Checker, fn_node: NodeId) bool {
        const src = self.source orelse return false;
        const body = self.leadingJsDocBodyForFunctionOrOwner(src, fn_node) orelse return false;
        if (std.mem.indexOf(u8, body, "@template") == null) return false;
        const tags = ts_parser.jsdoc.parse(self.gpa, body) catch return false;
        defer self.gpa.free(tags);
        for (tags) |tag| {
            if (tag.kind == .template_tag and tag.name.len > 0) return true;
        }
        return false;
    }

    /// When `fn_node` is the value of a `Ctor.prototype.member = function …`
    /// assignment in checked JS, the constructor's class-level JSDoc
    /// `@template T` parameters are in scope for the method's own JSDoc (a
    /// method may reference `T` in its `@param`/`@return`). Record them into
    /// the current narrow scope (alongside the method's own `@template`) so
    /// those references resolve instead of tripping TS2304. Mirrors
    /// constructorFunctionMethodTypeParameters.
    fn recordEnclosingPrototypeMethodConstructorTemplates(self: *Checker, fn_node: NodeId) CheckError!void {
        if (!self.check_js_enabled) return;
        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .assignment) return;
        const a = hir_mod.assignmentOf(self.hir, parent);
        if (a.op != null or a.value != fn_node) return;
        if (a.target == hir_mod.none_node_id or self.hir.kindOf(a.target) != .member_access) return;
        const member = hir_mod.memberOf(self.hir, a.target);
        if (member.object == hir_mod.none_node_id or self.hir.kindOf(member.object) != .member_access) return;
        const proto = hir_mod.memberOf(self.hir, member.object);
        if (!std.mem.eql(u8, self.string_interner.get(proto.name), "prototype")) return;
        if (proto.object == hir_mod.none_node_id or self.hir.kindOf(proto.object) != .identifier) return;
        const ctor_name = hir_mod.identifierOf(self.hir, proto.object).name;
        const ctor_fn = self.jsConstructorFunctionDeclForName(fn_node, ctor_name) orelse return;
        if (ctor_fn == fn_node) return;
        var dummy: std.ArrayListUnmanaged(TypeId) = .empty;
        defer dummy.deinit(self.gpa);
        try self.recordJsDocTemplateTypeParams(ctor_fn, &dummy);
    }

    fn recordJsDocTemplateTypeParams(
        self: *Checker,
        fn_node: NodeId,
        captured_tp_ids: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!void {
        const src = self.source orelse return;
        const body = self.leadingJsDocBodyForFunctionOrOwner(src, fn_node) orelse return;
        if (std.mem.indexOf(u8, body, "@template") == null) return;
        var line_start: usize = 0;
        var i: usize = 0;
        while (i <= body.len) : (i += 1) {
            const at_end = i == body.len;
            if (!at_end and body[i] != '\n') continue;
            var line = std.mem.trim(u8, body[line_start..i], " \t\r");
            line_start = i + 1;
            if (line.len > 0 and line[0] == '*') {
                line = std.mem.trim(u8, line[1..], " \t\r");
            }
            if (!std.mem.startsWith(u8, line, "@template")) continue;
            if (line.len > "@template".len and isJsDocIdentChar(line["@template".len])) continue;
            var rest = std.mem.trim(u8, line["@template".len..], " \t\r");
            if (std.mem.startsWith(u8, rest, "const") and rest.len > 5 and (rest[5] == ' ' or rest[5] == '\t')) {
                rest = std.mem.trim(u8, rest[5..], " \t\r");
            }
            var variance: types.Variance = .invariant;
            if (std.mem.startsWith(u8, rest, "in ") or std.mem.startsWith(u8, rest, "in\t")) {
                rest = std.mem.trim(u8, rest[2..], " \t\r");
                if (std.mem.startsWith(u8, rest, "out ") or std.mem.startsWith(u8, rest, "out\t")) {
                    rest = std.mem.trim(u8, rest[3..], " \t\r");
                    variance = .invariant;
                } else {
                    variance = .contravariant;
                }
            } else if (std.mem.startsWith(u8, rest, "out ") or std.mem.startsWith(u8, rest, "out\t")) {
                rest = std.mem.trim(u8, rest[3..], " \t\r");
                variance = .covariant;
            }
            var constraint_text: []const u8 = "";
            if (rest.len > 0 and rest[0] == '{') {
                const type_len = jsDocBalancedBraceLen(rest);
                if (type_len == 0) continue;
                constraint_text = std.mem.trim(u8, rest[1 .. type_len - 1], " \t\r\n");
                rest = std.mem.trim(u8, rest[type_len..], " \t\r");
            }
            if (std.mem.startsWith(u8, rest, "const") and rest.len > 5 and (rest[5] == ' ' or rest[5] == '\t')) {
                rest = std.mem.trim(u8, rest[5..], " \t\r");
            }
            var pos: usize = 0;
            var parameter_index: usize = 0;
            while (pos < rest.len) {
                while (pos < rest.len and (rest[pos] == ' ' or rest[pos] == '\t' or rest[pos] == ',')) : (pos += 1) {}
                if (pos >= rest.len) break;
                var name_text: []const u8 = "";
                var default_text: []const u8 = "";
                if (rest[pos] == '[') {
                    const close = std.mem.indexOfScalarPos(u8, rest, pos + 1, ']') orelse break;
                    const inner = rest[pos + 1 .. close];
                    if (std.mem.indexOfScalar(u8, inner, '=')) |eq| {
                        name_text = std.mem.trim(u8, inner[0..eq], " \t");
                        default_text = std.mem.trim(u8, inner[eq + 1 ..], " \t");
                    } else {
                        name_text = std.mem.trim(u8, inner, " \t");
                    }
                    pos = close + 1;
                } else {
                    if (!isJsDocIdentStart(rest[pos])) break;
                    const name_start = pos;
                    pos += 1;
                    while (pos < rest.len and isJsDocIdentChar(rest[pos])) : (pos += 1) {}
                    name_text = rest[name_start..pos];
                }
                if (name_text.len == 0) break;
                const name = self.string_interner.intern(name_text) catch return error.OutOfMemory;
                const tp_id = blk: {
                    if (self.lookupNarrow(name)) |existing| break :blk existing;
                    const constraint_t = if (parameter_index == 0 and constraint_text.len > 0)
                        (try self.jsDocTypeTextToTypeAt(src, constraint_text, fn_node)) orelse types.Primitive.unknown
                    else
                        types.Primitive.unknown;
                    const default_t = try self.jsDocTemplateDefaultType(src, body, default_text, fn_node);
                    const fresh = self.interner.internFreshTypeParameterWithFlags(
                        name,
                        constraint_t,
                        default_t,
                        variance,
                        false,
                    ) catch return error.OutOfMemory;
                    try self.recordNarrow(name, fresh);
                    break :blk fresh;
                };
                try captured_tp_ids.append(self.gpa, tp_id);
                if (parameter_index == 0 and constraint_text.len > 0) {
                    try self.jsdoc_constrained_type_params.put(self.gpa, tp_id, {});
                }
                parameter_index += 1;
                while (pos < rest.len and (rest[pos] == ' ' or rest[pos] == '\t')) : (pos += 1) {}
                if (pos >= rest.len or rest[pos] != ',') break;
            }
        }
    }

    fn jsDocTemplateDefaultType(
        self: *Checker,
        src: []const u8,
        body: []const u8,
        default_text: []const u8,
        anchor: NodeId,
    ) CheckError!TypeId {
        if (default_text.len == 0) return types.Primitive.none;
        if (isJsDocIdentStart(default_text[0])) {
            var ident_len: usize = 1;
            while (ident_len < default_text.len and isJsDocIdentChar(default_text[ident_len])) : (ident_len += 1) {}
            if (ident_len == default_text.len) {
                const name = self.string_interner.intern(default_text) catch return error.OutOfMemory;
                if (self.lookupNarrow(name) == null) {
                    const tags = ts_parser.jsdoc.parse(self.gpa, body) catch return types.Primitive.none;
                    defer self.gpa.free(tags);
                    for (tags) |tag| {
                        if (tag.kind == .template_tag and std.mem.eql(u8, tag.name, default_text)) return types.Primitive.none;
                    }
                }
            }
        }
        return (try self.jsDocTypeTextToTypeAt(src, default_text, anchor)) orelse types.Primitive.none;
    }

    /// True when the var/let/const decl `node` has a leading
    /// `/** @type {T} */` JSDoc tag. Used to extend
    /// `parameterHasContextualType` so an arrow/fn initializer of a
    /// JSDoc-typed variable suppresses TS7006 on its parameters.
    fn varDeclHasJsDocTypeTag(self: *Checker, node: NodeId) bool {
        return self.varDeclLeadingJsDocTypeText(node) != null;
    }

    fn varDeclLeadingJsDocTypeText(self: *Checker, node: NodeId) ?[]const u8 {
        const src = self.source orelse return null;
        const span = self.hir.spanOf(node);
        const body = self.leadingJsDocBody(src, span.start) orelse return null;
        const tags = ts_parser.jsdoc.parse(self.gpa, body) catch return null;
        defer self.gpa.free(tags);
        for (tags) |tag| {
            if (tag.kind == .type_tag and tag.type_text.len > 0) return tag.type_text;
        }
        return null;
    }

    const JsDocParamInfo = struct {
        typ: ?TypeId,
        optional: bool,
    };

    fn jsDocParamDottedMemberName(tag: ts_parser.jsdoc.Tag, parent_name: []const u8) ?[]const u8 {
        if (parent_name.len == 0) return null;
        const suffix = if (tag.name.len > parent_name.len and
            std.mem.startsWith(u8, tag.name, parent_name) and
            tag.name[parent_name.len] == '.')
            tag.name[parent_name.len + 1 ..]
        else if (std.mem.eql(u8, tag.name, parent_name) and
            tag.description.len > 1 and
            tag.description[0] == '.')
            tag.description[1..]
        else
            return null;
        if (suffix.len == 0 or !isJsDocIdentStart(suffix[0])) return null;
        var end: usize = 1;
        while (end < suffix.len and isJsDocIdentChar(suffix[end])) : (end += 1) {}
        return suffix[0..end];
    }

    /// Reconstruct a `@param` tag's full dotted path into `buf`. The JSDoc
    /// parser splits a dotted name into `tag.name` (head) plus a leading dotted
    /// run in `tag.description` (`@param {number} xyz.bar.p` → name `xyz`,
    /// description `.bar.p`), so the full path is the head followed by that run.
    /// Returns null if it does not fit in `buf`.
    fn jsDocParamTagFullPath(tag: ts_parser.jsdoc.Tag, buf: []u8) ?[]const u8 {
        if (tag.name.len > buf.len) return null;
        @memcpy(buf[0..tag.name.len], tag.name);
        var len = tag.name.len;
        if (tag.description.len > 0 and tag.description[0] == '.') {
            var end: usize = 0;
            while (end < tag.description.len and (tag.description[end] == '.' or isJsDocIdentChar(tag.description[end]))) : (end += 1) {}
            if (len + end > buf.len) return null;
            @memcpy(buf[len .. len + end], tag.description[0..end]);
            len += end;
        }
        return buf[0..len];
    }

    /// The type declared by a `@param` tag whose full dotted path equals
    /// `full_path` exactly (a directly-documented leaf), or null when no such
    /// tag exists.
    fn jsDocLeafTypeForFullPath(
        self: *Checker,
        src: []const u8,
        tags: []const ts_parser.jsdoc.Tag,
        fn_node: NodeId,
        full_path: []const u8,
    ) CheckError!?TypeId {
        for (tags) |tag| {
            if (tag.kind != .param_tag) continue;
            var buf: [256]u8 = undefined;
            const tag_full = jsDocParamTagFullPath(tag, &buf) orelse continue;
            if (!std.mem.eql(u8, tag_full, full_path)) continue;
            if (tag.type_text.len == 0) return types.Primitive.any;
            return (try self.jsDocTypeTextToTypeAt(src, tag.type_text, fn_node)) orelse types.Primitive.any;
        }
        return null;
    }

    fn jsDocObjectParamTypeFromDottedTags(
        self: *Checker,
        src: []const u8,
        tags: []const ts_parser.jsdoc.Tag,
        fn_node: NodeId,
        parent_name: []const u8,
    ) CheckError!?TypeId {
        return self.jsDocObjectParamTypeFromDottedTagsDepth(src, tags, fn_node, parent_name, 0);
    }

    /// Build the object type documented for `parent_name` by dotted `@param`
    /// tags. Nesting is RESOLVED RECURSIVELY: `@param {number} xyz.bar.p`
    /// makes `xyz.bar` an object `{ p: number }`, mirroring tsc, rather than
    /// flatly typing the immediate child `bar` from the grandchild's leaf type
    /// (which mis-typed `xyz.bar` as `number` and tripped a spurious TS2339 on
    /// `xyz.bar.p`). An immediate child that has deeper descendants recurses;
    /// a directly-documented leaf takes its own tag's type. Pins
    /// paramTagNestedWithoutTopLevelObject3 and the general deep-nesting case.
    fn jsDocObjectParamTypeFromDottedTagsDepth(
        self: *Checker,
        src: []const u8,
        tags: []const ts_parser.jsdoc.Tag,
        fn_node: NodeId,
        parent_name: []const u8,
        depth: u8,
    ) CheckError!?TypeId {
        if (depth >= 16 or parent_name.len == 0) return null;
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        for (tags) |tag| {
            if (tag.kind != .param_tag) continue;
            var buf: [256]u8 = undefined;
            const full = jsDocParamTagFullPath(tag, &buf) orelse continue;
            // Is `tag` a descendant of `parent_name`? (`parent_name.` prefix.)
            if (full.len <= parent_name.len + 1 or
                !std.mem.startsWith(u8, full, parent_name) or
                full[parent_name.len] != '.') continue;
            const rel = full[parent_name.len + 1 ..];
            if (!isJsDocIdentStart(rel[0])) continue;
            var seg_end: usize = 1;
            while (seg_end < rel.len and isJsDocIdentChar(rel[seg_end])) : (seg_end += 1) {}
            const child_text = rel[0..seg_end];
            const child_id = self.string_interner.intern(child_text) catch return error.OutOfMemory;
            var already_added = false;
            for (members.items) |m| {
                if (m.name == child_id) {
                    already_added = true;
                    break;
                }
            }
            if (already_added) continue;

            var child_buf: [256]u8 = undefined;
            const child_full = std.fmt.bufPrint(&child_buf, "{s}.{s}", .{ parent_name, child_text }) catch continue;
            const nested = try self.jsDocObjectParamTypeFromDottedTagsDepth(src, tags, fn_node, child_full, depth + 1);
            const member_t = if (nested) |n|
                n
            else
                (try self.jsDocLeafTypeForFullPath(src, tags, fn_node, child_full)) orelse types.Primitive.any;
            const leaf_optional = if (nested == null) blk: {
                for (tags) |t2| {
                    if (t2.kind != .param_tag) continue;
                    var b2: [256]u8 = undefined;
                    const f2 = jsDocParamTagFullPath(t2, &b2) orelse continue;
                    if (std.mem.eql(u8, f2, child_full)) break :blk t2.optional;
                }
                break :blk false;
            } else false;
            try self.upsertObjectMember(&members, .{
                .name = child_id,
                .type = member_t,
                .is_optional = leaf_optional,
                .is_readonly = false,
                .is_method = false,
            });
        }
        if (members.items.len == 0) return null;
        return self.interner.internObjectType(members.items) catch return error.OutOfMemory;
    }

    fn jsDocParamInfoForFunctionParam(self: *Checker, fn_node: NodeId, param_name: []const u8) CheckError!?JsDocParamInfo {
        if (param_name.len == 0) return null;
        const src = self.source orelse return null;
        const body = self.leadingJsDocBodyForFunctionOrOwner(src, fn_node) orelse return null;
        if (std.mem.indexOf(u8, body, "@overload") != null) return null;
        const tags = ts_parser.jsdoc.parse(self.gpa, body) catch return null;
        defer self.gpa.free(tags);
        var found: ?JsDocParamInfo = null;
        for (tags) |tag| {
            if (tag.kind != .param_tag) continue;
            if (!std.mem.eql(u8, tag.name, param_name)) continue;
            // The JSDoc parser encodes a dotted `@param` name (`xyz.bar`) as
            // `name='xyz'` + `description='.bar…'`. Such a tag documents a
            // nested property, not the top-level parameter — building the
            // parameter's type from it (with no genuine `@param {object} xyz`
            // present) makes `xyz.bar` the leaf's type and the body's
            // `xyz.bar.p` spuriously trips TS2339. The parser already flags
            // TS8032 for the missing top-level object param, and tsc leaves the
            // parameter `any`. Skip dotted-child tags here; the valid case
            // (a real top-level `@param {object} xyz` plus dotted children)
            // still matches the top-level tag and gathers the children via
            // jsDocObjectParamTypeFromDottedTags. Pins
            // paramTagNestedWithoutTopLevelObject2/3/4.
            if (std.mem.startsWith(u8, tag.description, ".")) continue;
            var t: ?TypeId = null;
            if (tag.type_text.len > 0) {
                if (try self.jsDocTypeTextToTypeAt(src, tag.type_text, fn_node)) |param_t| {
                    t = if (tag.optional) try self.unionWithUndefined(param_t) else param_t;
                }
            }
            if (!tag.optional) {
                if (try self.jsDocObjectParamTypeFromDottedTags(src, tags, fn_node, tag.name)) |object_t| {
                    t = object_t;
                }
            }
            found = .{
                .typ = t,
                .optional = tag.optional,
            };
        }
        return found;
    }

    fn jsDocParamInfoForFunctionParamIndex(self: *Checker, fn_node: NodeId, param_index: u16) CheckError!?JsDocParamInfo {
        const src = self.source orelse return null;
        const body = self.leadingJsDocBodyForFunctionOrOwner(src, fn_node) orelse return null;
        if (std.mem.indexOf(u8, body, "@overload") != null) return null;
        const tags = ts_parser.jsdoc.parse(self.gpa, body) catch return null;
        defer self.gpa.free(tags);
        var current: u16 = 0;
        for (tags) |tag| {
            if (tag.kind != .param_tag) continue;
            // A dotted `@param` (parser-encoded as `name='xyz'`,
            // `description='.bar…'`) documents a nested property, not a
            // positional parameter, so it must not be counted as a position —
            // otherwise a leading dotted tag types param 0 from a nested leaf
            // and the body spuriously trips TS2339 (the missing top-level
            // object param is already TS8032; tsc leaves the parameter `any`).
            // Mirrors the by-name path. Pins paramTagNestedWithoutTopLevelObject2/3/4.
            if (std.mem.startsWith(u8, tag.description, ".")) continue;
            if (current == param_index) {
                var t: ?TypeId = null;
                if (tag.type_text.len > 0) {
                    if (try self.jsDocTypeTextToTypeAt(src, tag.type_text, fn_node)) |param_t| {
                        t = if (tag.optional) try self.unionWithUndefined(param_t) else param_t;
                    }
                }
                if (!tag.optional) {
                    if (try self.jsDocObjectParamTypeFromDottedTags(src, tags, fn_node, tag.name)) |object_t| {
                        t = object_t;
                    }
                }
                return .{
                    .typ = t,
                    .optional = tag.optional,
                };
            }
            current += 1;
        }
        return null;
    }

    fn jsDocParamTypeForFunctionParam(self: *Checker, fn_node: NodeId, param_name: []const u8) CheckError!?TypeId {
        const info = (try self.jsDocParamInfoForFunctionParam(fn_node, param_name)) orelse return null;
        return info.typ;
    }

    fn fnIsJsDocConstructorOverloadImplementation(self: *Checker, fn_node: NodeId) bool {
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (!f.flags.is_constructor or f.body == hir_mod.none_node_id) return false;
        if (!self.sourceHasCheckJsDirective()) return false;
        if (!self.virtualSectionIsJsLike(fn_node)) return false;
        const src = self.source orelse return false;
        var blocks: std.ArrayListUnmanaged(JsDocBody) = .empty;
        defer blocks.deinit(self.gpa);
        self.adjacentLeadingJsDocBlocks(src, self.hir.spanOf(fn_node).start, &blocks) catch return false;
        for (blocks.items) |block| {
            if (std.mem.indexOf(u8, block.body, "@constructor") != null and
                std.mem.indexOf(u8, block.body, "@overload") != null)
            {
                return true;
            }
        }
        return false;
    }

    fn checkJsDocOverloadImplicitAnyReturns(self: *Checker, fn_node: NodeId) CheckError!void {
        if (!self.strict_flags.no_implicit_any) return;
        if (!self.sourceHasCheckJsDirective()) return;
        if (!self.virtualSectionIsJsLike(fn_node)) return;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.flags.is_constructor) return;
        const src = self.source orelse return;
        var blocks: std.ArrayListUnmanaged(JsDocBody) = .empty;
        defer blocks.deinit(self.gpa);
        try self.adjacentLeadingJsDocBlocks(src, self.hir.spanOf(fn_node).start, &blocks);
        for (blocks.items) |block| {
            if (std.mem.indexOf(u8, block.body, "@overload") == null) continue;
            if (std.mem.indexOf(u8, block.body, "@constructor") != null) continue;
            if (jsDocBodyHasTag(block.body, "returns") or jsDocBodyHasTag(block.body, "return")) continue;
            var offset: usize = 0;
            while (std.mem.indexOf(u8, block.body[offset..], "@overload")) |rel| {
                const overload_rel = offset + rel;
                try self.reportAt(
                    fn_node,
                    @as(u32, @intCast(block.start + overload_rel + 1)),
                    TsCodes.overload_return_implicitly_any,
                    "This overload implicitly returns the type 'any' because it lacks a return type annotation.",
                );
                offset = overload_rel + "@overload".len;
            }
        }
    }

    fn jsDocBodyHasTag(body: []const u8, comptime tag: []const u8) bool {
        var rest = body;
        while (std.mem.indexOfScalar(u8, rest, '@')) |at| {
            const after = rest[at + 1 ..];
            if (std.mem.startsWith(u8, after, tag) and
                (after.len == tag.len or !std.ascii.isAlphanumeric(after[tag.len]) and after[tag.len] != '_' and after[tag.len] != '-'))
            {
                return true;
            }
            rest = after;
        }
        return false;
    }

    fn collectJsDocConstructorOverloads(
        self: *Checker,
        ctor_node: NodeId,
        overload_sigs: *std.ArrayListUnmanaged(TypeId),
        overload_nodes: *std.ArrayListUnmanaged(NodeId),
        overload_positions: *std.ArrayListUnmanaged(?u32),
        overload_max_counts: *std.ArrayListUnmanaged(?usize),
    ) CheckError!void {
        if (!self.sourceHasCheckJsDirective()) return;
        if (!self.virtualSectionIsJsLike(ctor_node)) return;
        const src = self.source orelse return;
        var blocks: std.ArrayListUnmanaged(JsDocBody) = .empty;
        defer blocks.deinit(self.gpa);
        try self.adjacentLeadingJsDocBlocks(src, self.hir.spanOf(ctor_node).start, &blocks);
        for (blocks.items) |block| {
            if (std.mem.indexOf(u8, block.body, "@constructor") == null or
                std.mem.indexOf(u8, block.body, "@overload") == null)
            {
                continue;
            }
            const sig = (try self.jsDocConstructorOverloadSignature(ctor_node, block.body)) orelse continue;
            const overload_pos: ?u32 = if (std.mem.indexOf(u8, block.body, "@overload")) |rel|
                @intCast(block.start + rel + 1)
            else
                null;
            try overload_sigs.append(self.gpa, sig);
            try overload_nodes.append(self.gpa, ctor_node);
            try overload_positions.append(self.gpa, overload_pos);
            try overload_max_counts.append(self.gpa, self.interner.signatureParams(sig).len);
        }
    }

    fn jsDocConstructorOverloadSignature(self: *Checker, ctor_node: NodeId, body: []const u8) CheckError!?TypeId {
        const src = self.source orelse return null;
        const tags = ts_parser.jsdoc.parse(self.gpa, body) catch return null;
        defer self.gpa.free(tags);
        var param_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer param_types.deinit(self.gpa);
        var omittable: std.ArrayListUnmanaged(bool) = .empty;
        defer omittable.deinit(self.gpa);
        var names: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer names.deinit(self.gpa);
        for (tags) |tag| {
            if (tag.kind != .param_tag) continue;
            const param_t = (try self.jsDocTypeTextToTypeAt(src, tag.type_text, ctor_node)) orelse types.Primitive.any;
            const effective_t = if (tag.optional) try self.unionWithUndefined(param_t) else param_t;
            try param_types.append(self.gpa, effective_t);
            try omittable.append(self.gpa, tag.optional or self.parameterTypeAllowsVoidOmission(effective_t));
            if (tag.name.len > 0) {
                const name_id = self.string_interner.intern(tag.name) catch return error.OutOfMemory;
                try names.append(self.gpa, name_id);
            }
        }
        const sig = self.interner.internSignature(param_types.items, types.Primitive.void_t, false) catch return error.OutOfMemory;
        try self.recordSignatureMinArgs(sig, omittable.items);
        if (names.items.len == param_types.items.len and names.items.len > 0) {
            const owned = names.toOwnedSlice(self.gpa) catch return error.OutOfMemory;
            if (self.signature_param_names.fetchRemove(sig)) |old| self.gpa.free(old.value);
            try self.signature_param_names.put(self.gpa, sig, owned);
        }
        return sig;
    }

    fn applyArgumentsJsDocParamTags(
        self: *Checker,
        fn_node: NodeId,
        param_types: *std.ArrayListUnmanaged(TypeId),
        param_omittable: *std.ArrayListUnmanaged(bool),
        has_rest_param: *bool,
    ) CheckError!void {
        const src = self.source orelse return;
        const span = self.hir.spanOf(fn_node);
        const jsdoc = self.leadingJsDocBodyWithStart(src, span.start) orelse return;
        const tags = ts_parser.jsdoc.parse(self.gpa, jsdoc.body) catch return;
        defer self.gpa.free(tags);
        const uses_arguments = try self.functionBodyReferencesArguments(fn_node);
        for (tags) |tag| {
            if (tag.kind != .param_tag) continue;
            const type_text = std.mem.trim(u8, tag.type_text, " \t\r\n");
            if (std.mem.startsWith(u8, type_text, "...")) {
                const elem_text = std.mem.trim(u8, type_text[3..], " \t\r\n");
                const elem_t = (try self.jsDocTypeTextToTypeAt(src, elem_text, fn_node)) orelse types.Primitive.any;
                const array_t = self.interner.internArrayType(self.string_interner, elem_t) catch return error.OutOfMemory;
                try param_types.append(self.gpa, array_t);
                try param_omittable.append(self.gpa, true);
                has_rest_param.* = true;
                return;
            }
            if (!uses_arguments) continue;
            if (tag.name.len == 0) continue;
            const pos = if (std.mem.indexOf(u8, jsdoc.body, tag.name)) |rel|
                @as(u32, @intCast(jsdoc.start + rel))
            else
                span.start;
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "JSDoc '@param' tag has name '{s}', but there is no parameter with that name. It would match 'arguments' if it had an array type.",
                .{tag.name},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = fn_node,
                .pos = pos,
                .code = TsCodes.jsdoc_param_name_matches_arguments_if_array,
                .message = msg,
            });
        }
    }

    fn functionBodyReferencesArguments(self: *Checker, fn_node: NodeId) CheckError!bool {
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.body == hir_mod.none_node_id) return false;
        var refs: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer refs.deinit(self.gpa);
        try self.collectIdentifierRefs(f.body, &refs);
        var it = refs.keyIterator();
        while (it.next()) |name| if (std.mem.eql(u8, self.string_interner.get(name.*), "arguments")) return true;
        return false;
    }

    fn checkJsDocFunctionTypeReturnAnnotations(self: *Checker, fn_node: NodeId) CheckError!void {
        if (!self.sourceHasCheckJsDirective()) return;
        const src = self.source orelse return;
        const jsdoc = self.leadingJsDocBodyForFunctionOrOwnerWithStart(src, fn_node) orelse return;
        const tags = ts_parser.jsdoc.parse(self.gpa, jsdoc.body) catch return;
        defer self.gpa.free(tags);
        for (tags) |tag| {
            if (tag.type_text.len == 0) continue;
            const fn_text = jsDocFunctionTypeMissingReturn(tag.type_text) orelse continue;
            const rel = std.mem.indexOf(u8, jsdoc.body, fn_text) orelse
                std.mem.indexOf(u8, jsdoc.body, tag.type_text) orelse
                continue;
            try self.diagnostics.append(self.gpa, .{
                .node = fn_node,
                .pos = @intCast(jsdoc.start + rel),
                .code = TsCodes.function_type_return_implicitly_any,
                .message = try self.diag_arena.allocator().dupe(u8, "Function type, which lacks return-type annotation, implicitly has an 'any' return type."),
            });
        }
    }

    fn expressionNodeAssignableToTarget(self: *Checker, value_node: NodeId, value_t: TypeId, target_t: TypeId) CheckError!bool {
        if (try self.literalExpressionAssignableToTarget(value_node, target_t)) return true;
        if (self.hir.kindOf(value_node) == .array_literal and
            try self.arrayLiteralAssignableToTarget(value_node, target_t)) return true;
        if (try self.templateExpressionAssignableToType(value_node, target_t)) return true;
        if (try self.conditionalExpressionAssignableToTarget(value_node, target_t)) return true;
        if (self.hir.kindOf(value_node) == .object_literal and
            (self.objectLiteralAssignableToTarget(value_node, value_t, target_t) catch false))
        {
            return true;
        }
        if (try self.importedNamespaceIdentifierAssignableToTarget(value_node, target_t)) return true;
        return try self.checkerAssignableTo(value_t, target_t);
    }

    fn importedNamespaceIdentifierAssignableToTarget(self: *Checker, value_node: NodeId, target_t: TypeId) CheckError!bool {
        if (value_node == hir_mod.none_node_id or self.hir.kindOf(value_node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, value_node);
        const ns_t = (try self.moduleNamespaceTypeForLocalImport(id.name, value_node)) orelse return false;
        if (try self.checkerAssignableTo(ns_t, target_t)) return true;
        return self.objectHasRequiredTargetMemberNames(ns_t, target_t);
    }

    fn objectHasRequiredTargetMemberNames(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
