        return has_string and has_number and has_symbol;
    }

    fn collectPatternIndexSignaturesForRelation(
        self: *Checker,
        t: TypeId,
        out: *std.ArrayListUnmanaged(PatternIndexSignature),
    ) CheckError!void {
