        try out.append(self.gpa, t);
    }

    fn intersectConstraintTypes(self: *Checker, a: TypeId, b: TypeId) CheckError!TypeId {
        if (a == b) return a;
        if (a == types.Primitive.never or b == types.Primitive.never) return types.Primitive.never;
        if (a == types.Primitive.any or a == types.Primitive.unknown) return b;
        if (b == types.Primitive.any or b == types.Primitive.unknown) return a;

        const a_is_union = a < self.interner.pool.typeCount() and self.interner.pool.flagsOf(a).is_union;
        const b_is_union = b < self.interner.pool.typeCount() and self.interner.pool.flagsOf(b).is_union;
