                const b_members = try self.gpa.dupe(TypeId, self.interner.unionMembers(b));
                defer self.gpa.free(b_members);
                for (b_members) |bm| {
                    try self.appendUniqueConstraintType(&parts, try self.intersectConstraintTypes(a, bm));
