        for (self.interner.objectMembers(target_t)) |tm| {
            const sm_t = self.interner.objectMember(source_t, tm.name) orelse continue;
            if (try self.genericObjectTypeParameterMismatch(sm_t, tm.type, depth + 1)) return true;
        }
        return false;
    }

    fn genericSignatureRelationMismatch(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.isSignature(source_t) or !self.interner.isSignature(target_t)) return false;
        const source_type_param_count = if (self.generic_signature_params.get(source_t)) |params| params.len else 0;
        const target_type_param_count = if (self.generic_signature_params.get(target_t)) |params| params.len else 0;
        if (source_type_param_count == 0 and target_type_param_count == 0) return false;
        if (source_type_param_count == 0 and
            target_type_param_count > 0 and
            try self.signatureContainsTypeParameterOutsideOwnParams(source_t))
        {
            return true;
        }

        const source_params = self.interner.signatureParams(source_t);
        const target_params = self.interner.signatureParams(target_t);
        const compare_len = @min(source_params.len, target_params.len);
        if (source_type_param_count <= target_type_param_count) {
            var i: usize = 0;
            while (i < compare_len) : (i += 1) {
                if (try self.genericObjectTypeParameterMismatch(target_params[i], source_params[i], 0)) return true;
            }
        }

        const source_ret = self.interner.signatureReturn(source_t) orelse types.Primitive.void_t;
        const target_ret = self.interner.signatureReturn(target_t) orelse types.Primitive.void_t;
        if (target_ret != types.Primitive.void_t and
            try self.genericObjectTypeParameterMismatch(source_ret, target_ret, 0))
        {
            return true;
        }
        return false;
    }

    fn nonNullableIntersectionSourceAssignableToTarget(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        const base_t = self.nonNullableIntersectionBase(source_t) orelse return false;
        if (base_t == target_t) return true;
        if (try self.checkerAssignableTo(base_t, target_t)) return true;
        const constrained_t = (try self.nonNullableBaseConstraint(base_t)) orelse return false;
        if (constrained_t == target_t) return true;
        return try self.checkerAssignableTo(constrained_t, target_t);
    }

    fn nonNullableIntersectionBase(self: *Checker, t: TypeId) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(t).is_intersection) return null;
        var base_t: TypeId = types.Primitive.none;
        var saw_empty = false;
        for (self.interner.intersectionMembers(t)) |member| {
            if (self.typeIsEmptyObjectType(member)) {
                saw_empty = true;
                continue;
            }
            if (base_t != types.Primitive.none) return null;
            base_t = member;
        }
        return if (saw_empty and base_t != types.Primitive.none) base_t else null;
    }

    fn nonNullableIntersectionConstraint(self: *Checker, t: TypeId) CheckError!?TypeId {
        const base_t = self.nonNullableIntersectionBase(t) orelse return null;
        return try self.nonNullableBaseConstraint(base_t);
    }

    fn typeParameterSourceAssignableToMappedTarget(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(source_t).is_type_parameter) return false;
        if (!self.interner.pool.flagsOf(target_t).is_mapped) return false;
        const mapped = self.interner.mappedPayload(target_t);
        if (mapped.optional == .remove) return false;
        if (mapped.template >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(mapped.template).is_indexed_access) return false;
        const ia = self.interner.pool.indexed_access_payloads.items[self.interner.pool.payloadOf(mapped.template)];
        return ia.object == source_t;
    }

    fn genericIndexedAccessRelation(self: *Checker, source_t: TypeId, target_t: TypeId) ?bool {
        const source = self.indexedAccessPayloadOrNull(source_t) orelse return null;
        const target = self.indexedAccessPayloadOrNull(target_t) orelse return null;
        if (!self.isBareTypeParameter(source.object) or
            !self.isBareTypeParameter(target.object))
        {
            return null;
        }
        const keys_relate = self.symbolicIndexTypeAssignable(source.index, target.index);
        if (keys_relate == null) return null;
        return self.typeParameterConstraintChainContains(source.object, target.object) and keys_relate.?;
    }

    fn symbolicIndexTypeAssignable(self: *Checker, source_t: TypeId, target_t: TypeId) ?bool {
        if (source_t == target_t) return true;
        if (self.isBareTypeParameter(source_t) and self.isBareTypeParameter(target_t)) {
            return self.typeParameterConstraintChainContains(source_t, target_t);
        }
        if (!self.isBareTypeParameter(source_t)) return null;
        if (self.typeParameterConstraintSyntaxMatchesAlias(source_t, target_t)) return true;
        const source_operand = self.keyofOperandWithinKeyDomain(source_t, 0) orelse return null;
        const target_operand = self.keyofOperandWithinKeyDomain(target_t, 0) orelse return null;
        if (source_operand != target_operand) return false;
        return self.keyDomainExcludesSymbol(source_t, 0) and self.keyDomainExcludesSymbol(target_t, 0);
    }

    fn typeParameterConstraintSyntaxMatchesAlias(
        self: *Checker,
        type_param_t: TypeId,
        target_t: TypeId,
    ) bool {
        const target_display = self.alias_display_names.get(target_t) orelse return false;
        if (self.typeParameterConstraint(type_param_t)) |constraint_t| {
            if (self.alias_display_names.get(constraint_t)) |constraint_display| {
                if (typeTextsEqualIgnoringWhitespace(constraint_display, target_display)) return true;
            }
        }
        const decl_node = self.type_parameter_decl_nodes.get(self.resolvedTypeParameterPlaceholder(type_param_t)) orelse return false;
        if (decl_node == hir_mod.none_node_id or self.hir.kindOf(decl_node) != .type_parameter) return false;
        const constraint_node = hir_mod.typeParameterOf(self.hir, decl_node).constraint;
        if (constraint_node == hir_mod.none_node_id) return false;
        return typeTextsEqualIgnoringWhitespace(self.nodeSourceTextOrEmpty(constraint_node), target_display);
    }

    fn typeTextsEqualIgnoringWhitespace(a: []const u8, b: []const u8) bool {
        var ai: usize = 0;
        var bi: usize = 0;
        while (true) {
            while (ai < a.len and std.ascii.isWhitespace(a[ai])) ai += 1;
            while (bi < b.len and std.ascii.isWhitespace(b[bi])) bi += 1;
            if (ai == a.len or bi == b.len) return ai == a.len and bi == b.len;
            if (a[ai] != b[bi]) return false;
            ai += 1;
            bi += 1;
        }
    }

    fn keyofOperandWithinKeyDomain(self: *Checker, t: TypeId, depth: u8) ?TypeId {
        if (depth >= 24 or t >= self.interner.pool.typeCount()) return null;
        if (self.directKeyofOperand(t)) |operand| return operand;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return null;
            if (constraint == t) return null;
            return self.keyofOperandWithinKeyDomain(constraint, depth + 1);
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.keyofOperandWithinKeyDomain(member, depth + 1)) |operand| return operand;
            }
        }
        return null;
    }

    fn keyDomainExcludesSymbol(self: *Checker, t: TypeId, depth: u8) bool {
        if (depth >= 24 or t >= self.interner.pool.typeCount()) return false;
        if (self.indexTypeExcludesSymbol(t)) return true;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.keyDomainExcludesSymbol(constraint, depth + 1);
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (member == types.Primitive.string_t or member == types.Primitive.number_t) return true;
            }
        }
        return false;
    }

    fn isBareTypeParameter(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        return flags.is_type_parameter and !flags.is_union and !flags.is_intersection;
    }

    fn mappedSourceAssignableToTypeParameterTarget(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(source_t).is_mapped or
            !self.interner.pool.flagsOf(target_t).is_type_parameter)
        {
            return false;
        }
        const mapped = self.interner.mappedPayload(source_t);
        if (mapped.optional == .add) return false;
        return self.directKeyofOperand(mapped.constraint) == target_t;
    }

    fn filteredMappedKeySourceAssignableToKeyofTarget(
        self: *Checker,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError!bool {
        const target_operand = self.directKeyofOperand(target_t) orelse return false;
        if (try self.filteredMappedAliasKeySourceOperand(source_t)) |source_operand| {
            if (self.keyofOperandsHaveSameKeyDomain(source_operand, target_operand)) return true;
        }
        const reduced_source = (try self.reduceDisplayedAliasInstance(source_t)) orelse source_t;
        const source_ia = self.indexedAccessPayloadOrNull(reduced_source) orelse return false;
        const source_index_operand = self.directKeyofOperand(source_ia.index) orelse return false;
        if (!self.keyofOperandsHaveSameKeyDomain(source_index_operand, target_operand)) return false;
        if (source_ia.object >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(source_ia.object).is_mapped) return false;
        const mapped = self.interner.mappedPayload(source_ia.object);
        const mapped_operand = self.directKeyofOperand(mapped.constraint) orelse return false;
        if (!self.keyofOperandsHaveSameKeyDomain(mapped_operand, target_operand)) return false;
        _ = self.conditionalKeyFilterTypeParameter(mapped.template) orelse return false;
        return true;
    }

    fn filteredMappedAliasKeySourceOperand(self: *Checker, source_t: TypeId) CheckError!?TypeId {
        const args = self.alias_type_args.get(source_t) orelse return null;
        const alias_name = (try self.genericInstanceBaseName(source_t)) orelse return null;
        const info = self.generic_aliases.get(alias_name) orelse return null;
        if (args.len != info.params.len) return null;

        const indexed = self.indexedAccessPayloadOrNull(info.body) orelse return null;
        if (indexed.object >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(indexed.object).is_mapped)
        {
            return null;
        }
        const mapped = self.interner.mappedPayload(indexed.object);
        const formal_operand = self.directKeyofOperand(mapped.constraint) orelse return null;
        const indexed_operand = self.directKeyofOperand(indexed.index) orelse return null;
        if (formal_operand != indexed_operand and !self.sameTypeParameterName(formal_operand, indexed_operand)) return null;
        _ = self.conditionalKeyFilterTypeParameter(mapped.template) orelse return null;

        for (info.params, args) |param_t, arg_t| {
            if (param_t == formal_operand or self.sameTypeParameterName(param_t, formal_operand)) return arg_t;
        }
        return null;
    }

    fn keyofOperandsHaveSameKeyDomain(self: *Checker, a: TypeId, b: TypeId) bool {
        if (a == b or self.sameTypeParameterName(a, b)) return true;
        if (self.homomorphicMappedSourceTypeParameter(a)) |source| {
            if (source == b or self.sameTypeParameterName(source, b)) return true;
        }
        if (self.homomorphicMappedSourceTypeParameter(b)) |source| {
            if (source == a or self.sameTypeParameterName(source, a)) return true;
        }
        return false;
    }

    fn conditionalKeyFilterTypeParameter(self: *Checker, t: TypeId) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(t).is_conditional) return null;
        const c = self.interner.conditionalPayloadOrNull(t) orelse return null;
        return self.keyTypeParameterFromKeyOrNeverBranches(c.true_branch, c.false_branch);
    }

    fn keyTypeParameterFromKeyOrNeverBranches(self: *Checker, a: TypeId, b: TypeId) ?TypeId {
        if (a == types.Primitive.never and b < self.interner.pool.typeCount() and self.interner.pool.flagsOf(b).is_type_parameter) return b;
        if (b == types.Primitive.never and a < self.interner.pool.typeCount() and self.interner.pool.flagsOf(a).is_type_parameter) return a;
        return null;
    }

    fn nonNullableBaseConstraint(self: *Checker, base_t: TypeId) CheckError!?TypeId {
        if (base_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(base_t);
        if (flags.is_type_parameter) {
            const constraint_t = self.typeParameterConstraint(base_t) orelse return null;
            const reduced = try self.subtractNullUndefined(constraint_t);
            return if (reduced == base_t) null else reduced;
        }
        if (flags.is_indexed_access) {
            const ia = self.indexedAccessPayloadOrNull(base_t) orelse return null;
            const resolved = (try self.resolveObjectIndexedAccessType(ia.object, ia.index)) orelse return null;
            const reduced = try self.subtractNullUndefined(resolved);
            return if (reduced == base_t) null else reduced;
        }
        if (flags.is_union) {
            const reduced = try self.subtractNullUndefined(base_t);
            return if (reduced == base_t) null else reduced;
        }
        return null;
    }

    fn standardMappedUtilityInstantiationRelation(
        self: *Checker,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError!?bool {
        if (source_t == target_t) return null;
        const source_args = self.alias_type_args.get(source_t) orelse return null;
        const target_args = self.alias_type_args.get(target_t) orelse return null;
        if (source_args.len != target_args.len) return null;
        const source_display = self.alias_display_names.get(source_t) orelse "";
        const target_display = self.alias_display_names.get(target_t) orelse "";
        const standard_covariant =
            (std.mem.startsWith(u8, source_display, "Partial<") and
                std.mem.startsWith(u8, target_display, "Partial<")) or
            (std.mem.startsWith(u8, source_display, "Readonly<") and
                std.mem.startsWith(u8, target_display, "Readonly<"));
        if (standard_covariant and source_args.len == 1) {
            return try self.typeArgumentAssignableTo(source_args[0], target_args[0]);
        }
        return null;
    }

    fn sameGenericInstantiationAssignableByVariance(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!?bool {
        if (source_t == target_t) return true;
        if (try self.standardMappedUtilityInstantiationRelation(source_t, target_t)) |ok| return ok;
        const source_name = (try self.genericInstanceBaseName(source_t)) orelse return null;
        const target_name = (try self.genericInstanceBaseName(target_t)) orelse return null;
        if (source_name != target_name) return null;
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (!source_flags.is_union and !source_flags.is_intersection and !source_flags.is_signature and
            !target_flags.is_union and !target_flags.is_intersection and !target_flags.is_signature)
        {
            if (self.alias_display_names.get(source_t)) |source_display| {
                if (self.alias_display_names.get(target_t)) |target_display| {
                    if (std.mem.eql(u8, source_display, target_display)) return true;
                }
            }
        }
        const source_args = self.alias_type_args.get(source_t) orelse return null;
        const target_args = self.alias_type_args.get(target_t) orelse return null;
        if (source_args.len != target_args.len) return null;
        const info = self.generic_aliases.get(source_name) orelse return null;
        if (info.params.len != source_args.len) return null;

        for (info.params, source_args, target_args) |param_t, source_arg, target_arg| {
            const variance = self.typeParameterVariance(param_t);
            switch (variance) {
                .covariant => {
                    if (!try self.typeArgumentAssignableTo(source_arg, target_arg)) return false;
                },
                .contravariant => {
                    if (!try self.typeArgumentAssignableTo(target_arg, source_arg)) return false;
                },
                .invariant => {
                    if (!try self.typeArgumentAssignableTo(source_arg, target_arg)) return false;
                    if (!try self.typeArgumentAssignableTo(target_arg, source_arg)) return false;
                },
                .bivariant => {},
            }
        }
        return true;
    }

    fn nestedGenericInstantiationVarianceMismatch(
        self: *Checker,
        source_t: TypeId,
        target_t: TypeId,
        depth: u8,
    ) CheckError!bool {
        if (depth >= 8) return false;
        const source_args = self.alias_type_args.get(source_t);
        const target_args = self.alias_type_args.get(target_t);
        if (source_args != null and target_args != null and source_args.?.len == target_args.?.len) {
            const source_name = try self.genericInstanceBaseName(source_t);
            const target_name = try self.genericInstanceBaseName(target_t);
            if (source_name != null and target_name != null and source_name.? == target_name.?) {
                if (self.generic_aliases.get(source_name.?)) |info| {
                    if (info.params.len == source_args.?.len) {
                        for (info.params, source_args.?, target_args.?) |param_t, source_arg, target_arg| {
                            if (self.interner.typeParameterVariance(param_t) != .invariant) continue;
                            if (!try self.typeArgumentAssignableTo(source_arg, target_arg) or
                                !try self.typeArgumentAssignableTo(target_arg, source_arg))
                            {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return false;
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (source_flags.is_signature and target_flags.is_signature) {
            const source_params = self.interner.signatureParams(source_t);
            const target_params = self.interner.signatureParams(target_t);
            const shared_len = @min(source_params.len, target_params.len);
            for (0..shared_len) |i| {
                if (try self.nestedGenericInstantiationVarianceMismatch(
                    target_params[i],
                    source_params[i],
                    depth + 1,
                )) return true;
            }
            const source_ret = self.interner.signatureReturn(source_t) orelse types.Primitive.void_t;
            const target_ret = self.interner.signatureReturn(target_t) orelse types.Primitive.void_t;
            return try self.nestedGenericInstantiationVarianceMismatch(source_ret, target_ret, depth + 1);
        }
        if (!source_flags.is_object_type or !target_flags.is_object_type) return false;
        for (self.interner.objectMembers(target_t)) |target_member| {
            const source_member = self.interner.objectMember(source_t, target_member.name) orelse continue;
            if (try self.nestedGenericInstantiationVarianceMismatch(
                source_member,
                target_member.type,
                depth + 1,
            )) return true;
        }
        return false;
    }

    fn mappedSourceAssignableToMappedTarget(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!?bool {
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return null;
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (source_flags.is_union or source_flags.is_intersection or
            target_flags.is_union or target_flags.is_intersection or
            !source_flags.is_mapped or
            !target_flags.is_mapped)
        {
            return null;
        }
        const source = self.interner.mappedPayload(source_t);
        const target = self.interner.mappedPayload(target_t);
        if (!self.mappedConstraintCovers(source.constraint, target.constraint)) return false;
        if (source.optional == .add and target.optional != .add) return false;

        const source_indexed = self.indexedAccessPayloadOrNull(source.template) orelse return null;
        const target_indexed = self.indexedAccessPayloadOrNull(target.template) orelse return null;
        if (source_indexed.object >= self.interner.pool.typeCount() or
            target_indexed.object >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(source_indexed.object).is_type_parameter or
            !self.interner.pool.flagsOf(target_indexed.object).is_type_parameter)
        {
            return null;
        }
        if (!self.typeParameterConstraintChainContains(source_indexed.object, target_indexed.object)) {
            return false;
        }
        return true;
    }

    fn mappedConstraintCovers(self: *Checker, source_constraint: TypeId, target_constraint: TypeId) bool {
        if (source_constraint == target_constraint) return true;
        const source_operand = self.directKeyofOperand(source_constraint) orelse return false;
        const target_operand = self.constrainedKeyofOperand(target_constraint, 0) orelse return false;
        return self.typeParameterConstraintChainContains(source_operand, target_operand);
    }

    fn genericInstanceBaseName(self: *Checker, t: TypeId) CheckError!?hir_mod.StringId {
        if (self.alias_display_names.get(t)) |display| {
            const lt = std.mem.indexOfScalar(u8, display, '<') orelse return null;
            if (lt == 0) return null;
            return self.string_interner.intern(display[0..lt]) catch return error.OutOfMemory;
        }
        return self.namedTypeForId(t);
    }

    fn typeArgumentAssignableTo(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (source_t == target_t) return true;
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) {
            return try self.checkerAssignableTo(source_t, target_t);
        }
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (source_flags.is_signature and target_flags.is_signature) {
            return self.strictCallableSubtype(source_t, target_t);
        }
        if (self.typeArgSignatureConstraint(source_t)) |source_sig| {
            if (self.typeArgSignatureConstraint(target_t)) |target_sig| {
                if (source_sig.is_construct == target_sig.is_construct) {
                    return self.strictCallableSubtype(source_sig.sig, target_sig.sig);
                }
            }
        }
        if (source_flags.is_type_parameter) {
            if (self.typeParameterConstraint(source_t)) |constraint| {
                if (constraint != source_t) {
                    if (constraint == target_t) return true;
                    if (try self.typeArgumentAssignableTo(constraint, target_t)) return true;
                }
            }
        }
        if (target_flags.is_type_parameter) return false;
        return try self.checkerAssignableTo(source_t, target_t);
    }

    fn stringMappingSourceAssignableToTarget(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return false;
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (!source_flags.is_string_mapping) return false;
        if (!target_flags.is_string_mapping) {
            const source = self.interner.stringMappingPayload(source_t);
            if (source.inner >= self.interner.pool.typeCount()) return false;
            const inner_flags = self.interner.pool.flagsOf(source.inner);
            if (!inner_flags.is_type_parameter) return false;
            const constraint = self.typeParameterConstraint(source.inner) orelse return false;
            if (constraint == source.inner) return false;
            const mapped_constraint = try self.applyStringMappingBuiltin(switch (source.kind) {
                .lowercase => "Lowercase",
                .uppercase => "Uppercase",
                .capitalize => "Capitalize",
                .uncapitalize => "Uncapitalize",
            }, constraint);
            return try self.checkerAssignableTo(mapped_constraint, target_t);
        }
        const source = self.interner.stringMappingPayload(source_t);
        const target = self.interner.stringMappingPayload(target_t);
        if (source.kind != target.kind) return false;
        if (target.inner < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(target.inner).is_type_parameter)
        {
            const target_constraint = self.typeParameterConstraint(target.inner) orelse types.Primitive.unknown;
            const target_constraint_is_type_param = target_constraint < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(target_constraint).is_type_parameter;
            if (!target_constraint_is_type_param and self.stringMappingArgSatisfiesStringConstraint(source.inner)) {
                return true;
            }
        }
        return try self.typeArgumentAssignableTo(source.inner, target.inner);
    }

    fn sameNonGenericClassInstanceDeclaration(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
        if (source_t == target_t) return true;
        const source_name = self.classNameForInstanceType(source_t) orelse return false;
        const target_name = self.classNameForInstanceType(target_t) orelse return false;
        if (source_name != target_name) return false;
        if (self.generic_aliases.get(source_name)) |info| {
            if (info.params.len > 0) return false;
        }
        const source_decl = self.class_decl_by_instance.get(source_t);
        const target_decl = self.class_decl_by_instance.get(target_t);
        if (source_decl != null and target_decl != null) return source_decl.? == target_decl.?;
        return self.alias_type_args.get(source_t) == null and
            self.alias_type_args.get(target_t) == null;
    }

    fn classStaticSatisfiesConstructorObjectConstraint(
        self: *Checker,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError!bool {
        _ = self.class_name_by_static.get(source_t) orelse return false;
        if (target_t >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(target_t).is_object_type)
        {
            return false;
        }

        var source_constructs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer source_constructs.deinit(self.gpa);
        var target_constructs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer target_constructs.deinit(self.gpa);
        try self.collectConstructSignatures(source_t, &source_constructs);
        try self.collectConstructSignatures(target_t, &target_constructs);
        if (source_constructs.items.len == 0 or target_constructs.items.len == 0) return false;

        for (target_constructs.items) |target_sig| {
            var covered = false;
            for (source_constructs.items) |source_sig| {
                if (try self.contextualFunctionSignatureAssignable(source_sig, target_sig)) {
                    covered = true;
                    break;
                }
            }
            if (!covered) return false;
        }

        for (self.interner.objectMembers(target_t)) |target_member| {
            if (self.syntheticSignatureMemberName(target_member.name)) continue;
            const source_member = self.interner.objectMemberInfo(source_t, target_member.name) orelse {
                if (target_member.is_optional) continue;
                return false;
            };
            if (!try self.checkerAssignableTo(source_member.type, target_member.type)) return false;
        }
        return true;
    }

    fn classStaticAssignableTo(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (source_t == target_t) return true;
        if (self.class_name_by_static.get(source_t)) |source_name| {
            if (self.class_name_by_static.get(target_t)) |target_name| {
                var cur = source_name;
                var steps: usize = 0;
                while (steps < 1024) : (steps += 1) {
                    if (cur == target_name) return true;
                    cur = self.class_parent.get(cur) orelse break;
                }
            }
        }
        return try self.staticConstructReturnAssignableTo(source_t, target_t);
    }

    fn staticConstructReturnAssignableTo(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (self.interner.isSignature(source_t) or self.interner.isSignature(target_t)) return false;
        var source_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer source_sigs.deinit(self.gpa);
        var target_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer target_sigs.deinit(self.gpa);
        try self.collectConstructSignatures(source_t, &source_sigs);
        try self.collectConstructSignatures(target_t, &target_sigs);
        if (source_sigs.items.len == 0 or target_sigs.items.len == 0) return false;
        for (target_sigs.items) |target_sig| {
            const target_ret = self.interner.signatureReturn(target_sig) orelse continue;
            var matched = false;
            for (source_sigs.items) |source_sig| {
                const source_ret = self.interner.signatureReturn(source_sig) orelse continue;
                if (self.engine.isAssignableTo(source_ret, target_ret) catch false) {
                    matched = true;
                    break;
                }
            }
            if (!matched) return false;
        }
        return true;
    }

    fn objectMembersAssignableWithClassStaticRelations(self: *Checker, source_t: TypeId, target_t: TypeId, depth: usize) CheckError!bool {
        if (depth == 0 or source_t == target_t) return source_t == target_t;
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return false;
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (!source_flags.is_object_type or !target_flags.is_object_type) return false;
        if (self.interner.objectStringIndex(target_t) != types.Primitive.none or
            self.interner.objectNumberIndex(target_t) != types.Primitive.none or
            self.interner.objectSymbolIndex(target_t) != types.Primitive.none)
        {
            return false;
        }
        const target_members = try self.gpa.dupe(types.ObjectMember, self.interner.objectMembers(target_t));
        defer self.gpa.free(target_members);
        if (target_members.len == 0) return false;
        var used_class_static_relation = false;
        for (target_members) |tm| {
            const sm_t = self.interner.objectMember(source_t, tm.name) orelse {
                if (tm.is_optional) continue;
                return false;
            };
            if (sm_t == tm.type) continue;
            const reduced_sm_t = try self.reduceNeverIntersectionsForAssignability(sm_t);
            const reduced_tm_t = try self.reduceNeverIntersectionsForAssignability(tm.type);
            if (reduced_sm_t != sm_t or reduced_tm_t != tm.type) {
                if (reduced_sm_t == reduced_tm_t or try self.checkerAssignableTo(reduced_sm_t, reduced_tm_t)) {
                    used_class_static_relation = true;
                    continue;
                }
            }
            if (try self.classStaticAssignableTo(sm_t, tm.type)) {
                used_class_static_relation = true;
                continue;
            }
            if (self.stringLiteralValueFromType(sm_t)) |sid| {
                if (try self.stringLiteralAssignableToType(sid, tm.type)) {
                    used_class_static_relation = true;
                    continue;
                }
            }
            if (try self.finiteTemplateLiteralSourceAssignableToTarget(sm_t, tm.type) or
                try self.templateLiteralSourceAssignableToTarget(sm_t, tm.type))
            {
                used_class_static_relation = true;
                continue;
            }
            if (self.engine.isAssignableTo(sm_t, tm.type) catch false) continue;
            if (try self.objectMembersAssignableWithClassStaticRelations(sm_t, tm.type, depth - 1)) {
                used_class_static_relation = true;
                continue;
            }
            return false;
        }
        return used_class_static_relation;
    }

    fn typeIsDeferredConditional(self: *Checker, t: TypeId) bool {
        return t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(t).is_conditional;
    }

    fn sourceAssignableToDeferredConditionalTarget(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!?bool {
        const c = self.interner.conditionalPayloadOrNull(target_t) orelse return null;
        if (!try self.sourceAssignableToDeferredConditionalBranch(source_t, c.true_branch)) return false;
        if (!try self.sourceAssignableToDeferredConditionalBranch(source_t, c.false_branch)) return false;
        return true;
    }

    fn sourceAssignableToDeferredConditionalBranch(self: *Checker, source_t: TypeId, branch_t: TypeId) CheckError!bool {
        if (source_t == branch_t) return true;
        if (branch_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(branch_t).is_type_parameter)
        {
            return false;
        }
        return try self.checkerAssignableTo(source_t, branch_t);
    }

    fn deferredConditionalAssignableToConditional(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!?bool {
        const source = self.interner.conditionalPayloadOrNull(source_t) orelse return null;
        const target = self.interner.conditionalPayloadOrNull(target_t) orelse return null;
        if (source.is_distributive != target.is_distributive) return false;
        if (!self.conditionalCheckTypesRelated(source.check_type, target.check_type)) return false;
        if (!self.conditionalExtendsTypesIdentical(source.extends_type, target.extends_type)) return false;
        if (!try self.checkerAssignableTo(source.true_branch, target.true_branch)) return false;
        if (!try self.checkerAssignableTo(source.false_branch, target.false_branch)) return false;
        return true;
    }

    fn conditionalCheckTypesRelated(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
        if (source_t == target_t) return true;
        if (self.engine.isAssignableTo(source_t, target_t) catch false) return true;
        return self.engine.isAssignableTo(target_t, source_t) catch false;
    }

    fn conditionalExtendsTypesIdentical(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
        if (source_t == target_t) return true;
        return self.engine.isIdenticalTo(source_t, target_t) catch false;
    }

    fn deferredConditionalSourceAssignableToTarget(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!?bool {
        const c = self.interner.conditionalPayloadOrNull(source_t) orelse return null;
        if (try self.reduceConditionalSourceOverConstraint(source_t, c)) |reduced| {
            return try self.checkerAssignableTo(reduced, target_t);
        }
        if (try self.extractLikeConditionalConstraint(source_t)) |constraint| {
            if (try self.checkerAssignableTo(constraint, target_t)) return true;
            if (try self.extractLikeConstraintCoversObjectTarget(constraint, target_t)) return true;
        }
        if (!try self.checkerAssignableTo(c.true_branch, target_t)) return false;
        if (!try self.checkerAssignableTo(c.false_branch, target_t)) return false;
        return true;
    }

    fn reduceConditionalSourceOverConstraint(self: *Checker, source_t: TypeId, c: types.ConditionalPayload) CheckError!?TypeId {
        if (c.check_type >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(c.check_type).is_type_parameter) return null;
        const constraint = self.typeParameterConstraint(c.check_type) orelse return null;
        if (constraint == c.check_type or constraint == types.Primitive.unknown or constraint == types.Primitive.any) return null;
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        try subs.put(self.gpa, c.check_type, constraint);
        const reduced = try self.substituteType(source_t, &subs);
        return if (reduced == source_t) null else reduced;
    }

    fn extractLikeConditionalConstraint(self: *Checker, t: TypeId) CheckError!?TypeId {
        return try self.extractLikeConditionalConstraintDepth(t, 0);
    }

    fn extractLikeConditionalConstraintDepth(self: *Checker, t: TypeId, depth: usize) CheckError!?TypeId {
        if (depth > 8) return null;
        const c = self.interner.conditionalPayloadOrNull(t) orelse return null;
        if (c.false_branch != types.Primitive.never) return null;
        var parts: std.ArrayListUnmanaged(TypeId) = .empty;
        defer parts.deinit(self.gpa);
        if (c.extends_type != types.Primitive.any and c.extends_type != types.Primitive.unknown) {
            try parts.append(self.gpa, c.extends_type);
        }
        if (try self.extractLikeConditionalConstraintDepth(c.true_branch, depth + 1)) |nested| {
            try parts.append(self.gpa, nested);
        } else if (c.true_branch == c.check_type) {
            if (try self.extractLikeConditionalConstraintDepth(c.check_type, depth + 1)) |nested| {
                try parts.append(self.gpa, nested);
            }
        }
        return switch (parts.items.len) {
            0 => null,
            1 => parts.items[0],
            else => self.interner.internIntersection(parts.items) catch return error.OutOfMemory,
        };
    }

    fn extractLikeConstraintCoversObjectTarget(self: *Checker, constraint_t: TypeId, target_t: TypeId) CheckError!bool {
        if (constraint_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return false;
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (!target_flags.is_object_type) return false;
        if (self.interner.objectStringIndex(target_t) != types.Primitive.none or
            self.interner.objectNumberIndex(target_t) != types.Primitive.none or
            self.interner.objectSymbolIndex(target_t) != types.Primitive.none)
        {
            return false;
        }
        const target_members = self.interner.objectMembers(target_t);
        if (target_members.len == 0) return false;
        for (target_members) |target_member| {
            if (target_member.is_optional) continue;
            if (!try self.extractLikeConstraintHasObjectMember(constraint_t, target_member, 0)) return false;
        }
        return true;
    }

    fn extractLikeConstraintHasObjectMember(
        self: *Checker,
        constraint_t: TypeId,
        target_member: types.ObjectMember,
        depth: usize,
    ) CheckError!bool {
        if (depth > 8 or constraint_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(constraint_t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(constraint_t)) |part_t| {
                if (try self.extractLikeConstraintHasObjectMember(part_t, target_member, depth + 1)) return true;
            }
            return false;
        }
        if (flags.is_type_parameter) {
            if (self.typeParameterConstraint(constraint_t)) |bound_t| {
                if (bound_t != constraint_t) {
                    return try self.extractLikeConstraintHasObjectMember(bound_t, target_member, depth + 1);
                }
            }
            return false;
        }
        if (!flags.is_object_type) return false;
        for (self.interner.objectMembers(constraint_t)) |source_member| {
            if (source_member.name != target_member.name) continue;
            if (source_member.is_optional and !target_member.is_optional) return false;
            if (source_member.type == target_member.type) return true;
            return try self.checkerAssignableTo(source_member.type, target_member.type);
        }
        return false;
    }

    fn signatureThisParam(self: *Checker, sig: TypeId) ?TypeId {
        if (self.signature_this_params.get(sig)) |this_t| return this_t;
        if (sig >= self.interner.pool.typeCount()) return null;
        if (!self.interner.isSignature(sig)) return null;
        const payload = self.interner.pool.signature_payloads.items[self.interner.pool.payloadOf(sig)];
        if (!payload.has_this_type) return null;
        return payload.this_type;
    }

    fn signatureThisTypesAssignable(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (!self.interner.isSignature(source_t) or !self.interner.isSignature(target_t)) return true;
        const source_this_raw = self.signatureThisParam(source_t) orelse return true;
        if (source_this_raw == types.Primitive.void_t) return true;
        const target_this_raw = self.signatureThisParam(target_t) orelse return true;
        const source_this = self.thisTypeMarkerConstraint(source_this_raw) orelse source_this_raw;
        const target_this = self.thisTypeMarkerConstraint(target_this_raw) orelse target_this_raw;
        return self.engine.isAssignableTo(target_this, source_this) catch return error.OutOfMemory;
    }

    fn typeNodeIsThisType(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(node)) {
            .this_expr => true,
            .identifier => std.mem.eql(u8, self.string_interner.get(hir_mod.identifierOf(self.hir, node).name), "this"),
            .type_ref => blk: {
                const r = hir_mod.typeRefOf(self.hir, node);
                break :blk r.qualifier_len == 0 and
                    r.args_len == 0 and
                    std.mem.eql(u8, self.string_interner.get(r.name), "this");
            },
            else => false,
        };
    }

    fn signatureDeclHasPolymorphicThisParam(self: *Checker, sig: TypeId) bool {
        const decl = self.signatureDeclNode(sig);
        if (decl == hir_mod.none_node_id) return false;
        const params: []const NodeId = switch (self.hir.kindOf(decl)) {
            .fn_decl, .fn_expr, .arrow_fn => hir_mod.fnParams(self.hir, decl),
            .fn_type, .constructor_type => blk: {
                const ft = hir_mod.fnTypeOf(self.hir, decl);
                break :blk self.hir.childSlice(ft.params_start, ft.params_len);
            },
            else => return false,
        };
        if (params.len == 0 or !self.isThisParameter(params[0])) return false;
        const p = hir_mod.parameterOf(self.hir, params[0]);
        return self.typeNodeIsThisType(p.type_annotation);
    }

    fn memberAccessEffectiveThisType(self: *Checker, node: NodeId, fallback_t: TypeId) CheckError!?TypeId {
        if (node != hir_mod.none_node_id and self.hir.kindOf(node) == .member_access) {
            const m = hir_mod.memberOf(self.hir, node);
            const receiver_t = if (try self.staticClassMemberAccess(m.object, m.name)) |static_access|
                static_access.receiver_t
            else
                try self.checkExpression(m.object);
            var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
            defer sigs.deinit(self.gpa);
            try self.collectNamedMemberSignatures(receiver_t, m.name, &sigs);
            for (sigs.items) |sig| {
                if (self.signatureDeclHasPolymorphicThisParam(sig)) return receiver_t;
                if (self.signatureThisParam(sig)) |this_t| return self.thisTypeMarkerConstraint(this_t) orelse this_t;
            }
        }
        if (self.interner.isSignature(fallback_t)) {
            if (self.signatureThisParam(fallback_t)) |this_t| return self.thisTypeMarkerConstraint(this_t) orelse this_t;
        }
        return null;
    }

    fn signatureWithEffectiveThisForAssignmentNode(self: *Checker, node: NodeId, sig_t: TypeId) CheckError!TypeId {
        if (!self.interner.isSignature(sig_t)) return sig_t;
        const this_t = (try self.memberAccessEffectiveThisType(node, sig_t)) orelse return sig_t;
        const payload_idx = self.interner.pool.payloadOf(sig_t);
        if (payload_idx >= self.interner.pool.signature_payloads.items.len) return sig_t;
        const payload = self.interner.pool.signature_payloads.items[payload_idx];
        const params = self.interner.signatureParams(sig_t);
        const ret = self.interner.signatureReturn(sig_t) orelse types.Primitive.any;
        const next = self.interner.internSignatureWithThisType(
            params,
            ret,
            payload.is_construct,
            payload.is_abstract_construct,
            this_t,
        ) catch return error.OutOfMemory;
        if (self.rest_signatures.contains(sig_t)) try self.rest_signatures.put(self.gpa, next, {});
        if (self.signature_min_args.get(sig_t)) |min_required| try self.signature_min_args.put(self.gpa, next, min_required);
        try self.copySignatureParamNames(next, sig_t);
        try self.copySignatureDeclNode(next, sig_t);
        try self.signature_this_params.put(self.gpa, next, this_t);
        return next;
    }

    fn assignmentSignatureThisTypesAssignable(
        self: *Checker,
        value_node: NodeId,
        target_node: NodeId,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError!bool {
        const source_this = (try self.memberAccessEffectiveThisType(value_node, source_t)) orelse return true;
        if (source_this == types.Primitive.void_t) return true;
        const target_this = (try self.memberAccessEffectiveThisType(target_node, target_t)) orelse return true;
        if (self.engine.isAssignableTo(target_this, source_this) catch return error.OutOfMemory) return true;
        if (self.hir.kindOf(value_node) == .member_access or self.hir.kindOf(target_node) == .member_access) {
            if (self.engine.isAssignableTo(source_this, target_this) catch return error.OutOfMemory) return true;
        }
        return false;
    }

    fn assignmentExpressionPredicate(self: *Checker, node: NodeId, t: TypeId) CheckError!?FnPredicate {
        if (node != hir_mod.none_node_id) {
            const kind = self.hir.kindOf(node);
            if (kind == .fn_decl or kind == .fn_expr or kind == .arrow_fn) {
                // Same-shaped predicate and boolean signatures share a
                // structural TypeId. The function syntax is authoritative
                // for an assignment source, so an unannotated/boolean
                // function must not inherit a predicate from that TypeId.
                return try self.predicateForFnNode(node);
            }
            if (kind == .identifier) {
                const id = hir_mod.identifierOf(self.hir, node);
                if (self.fn_predicates.get(id.name)) |pred| return pred;
                if (self.visibleAnnotatedIdentifierTypeNode(node)) |type_node| {
                    const type_kind = self.hir.kindOf(type_node);
                    if (type_kind == .fn_type or type_kind == .constructor_type) {
                        return try self.functionTypeAnnotationPredicate(type_node);
                    }
                }
            }
        }
        if (node != hir_mod.none_node_id and self.hir.kindOf(node) == .member_access) {
            const member = hir_mod.memberOf(self.hir, node);
            var receiver_t = self.hir.typeOf(member.object);
            if (receiver_t == types.Primitive.none and self.hir.kindOf(member.object) == .identifier) {
                receiver_t = self.typeOfIdentifier(member.object);
            }
            if (receiver_t != types.Primitive.none) {
                if (self.lookupMemberPredicate(receiver_t, member.name)) |pred| return pred;
            }
        }
        return self.signature_predicates.get(t);
    }

    fn assignmentExpressionPredicatesAssignable(
        self: *Checker,
        value_node: NodeId,
        target_node: NodeId,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError!bool {
        const target_pred = (try self.assignmentExpressionPredicate(target_node, target_t)) orelse return true;
        const source_pred = (try self.assignmentExpressionPredicate(value_node, source_t)) orelse return false;
        if (source_pred.param_index != target_pred.param_index) return false;
        if (source_pred.is_asserts != target_pred.is_asserts) return false;
        if (source_pred.target_type == target_pred.target_type) return true;
        if (source_pred.target_type == types.Primitive.none or target_pred.target_type == types.Primitive.none) {
            return source_pred.target_type == target_pred.target_type;
        }
        return self.engine.isAssignableTo(source_pred.target_type, target_pred.target_type) catch return error.OutOfMemory;
    }

    fn assignmentExpressionPredicateTypeName(self: *Checker, node: NodeId, t: TypeId) CheckError!?[]const u8 {
        const pred = (try self.assignmentExpressionPredicate(node, t)) orelse return null;
        return self.allocCallSignatureFnTypeNameWithPredicate(t, null, pred);
    }

    fn buildAssignmentExpressionPredicateElaborationChain(
        self: *Checker,
        value_node: NodeId,
        target_node: NodeId,
        source: TypeId,
        target: TypeId,
        target_pred_override: ?FnPredicate,
    ) CheckError!?[]const DiagnosticChainEntry {
        const target_pred = target_pred_override orelse
            ((try self.assignmentExpressionPredicate(target_node, target)) orelse return null);
        const source_pred_opt = try self.assignmentExpressionPredicate(value_node, source);
        if (try self.signaturePredicateAnnotationsAssignable(source_pred_opt, target_pred)) return null;

        const arena = self.diag_arena.allocator();
        const slice = try arena.alloc(DiagnosticChainEntry, 1);
        if (source_pred_opt == null) {
            const source_sig = (try self.allocCallSignatureNameColonReturn(source)) orelse
                (try self.allocCallableSignatureName(source)) orelse "unknown";
            const msg = try std.fmt.allocPrint(
                arena,
                "Signature '{s}' must be a type predicate.",
                .{source_sig},
            );
            slice[0] = .{ .code = TsCodes.signature_must_be_type_predicate, .message = msg };
            return slice;
        }

        const source_pred = source_pred_opt.?;
        const source_text = try self.allocTypePredicateName(source, source_pred);
        const target_text = try self.allocTypePredicateName(target, target_pred);
        const msg = try std.fmt.allocPrint(
            arena,
            "Type predicate '{s}' is not assignable to '{s}'.",
            .{ source_text, target_text },
        );
        const this_predicate = std.math.maxInt(u16);
        if ((source_pred.param_index == this_predicate) != (target_pred.param_index == this_predicate)) {
            const child = try arena.alloc(DiagnosticChainEntry, 1);
            child[0] = .{
                .code = TsCodes.this_type_guard_not_parameter_type_guard,
                .message = "A 'this'-based type guard is not compatible with a parameter-based type guard.",
            };
            slice[0] = .{ .code = TsCodes.type_predicate_not_assignable, .message = msg, .children = child };
            return slice;
        }
        if (source_pred.param_index != target_pred.param_index) {
            const child = try arena.alloc(DiagnosticChainEntry, 1);
            const child_msg = try std.fmt.allocPrint(
                arena,
                "Parameter '{s}' is not in the same position as parameter '{s}'.",
                .{ try self.typePredicateParamName(source, source_pred), try self.typePredicateParamName(target, target_pred) },
            );
            child[0] = .{ .code = TsCodes.type_predicate_parameter_position_mismatch, .message = child_msg };
            slice[0] = .{ .code = TsCodes.type_predicate_not_assignable, .message = msg, .children = child };
            return slice;
        }
        if (source_pred.target_type != types.Primitive.none and target_pred.target_type != types.Primitive.none and
            !(self.engine.isAssignableTo(source_pred.target_type, target_pred.target_type) catch true))
        {
            const child = try arena.alloc(DiagnosticChainEntry, 1);
            child[0] = try self.typeNotAssignableChainEntry(source_pred.target_type, target_pred.target_type, false);
            slice[0] = .{ .code = TsCodes.type_predicate_not_assignable, .message = msg, .children = child };
            return slice;
        }
        slice[0] = .{ .code = TsCodes.type_predicate_not_assignable, .message = msg };
        return slice;
    }

    fn formatPredicateArgumentNotAssignable(
        self: *Checker,
        arg_node: NodeId,
        arg_t: TypeId,
        param_t: TypeId,
        target_pred: FnPredicate,
    ) CheckError!?[]const u8 {
        const source_pred = try self.assignmentExpressionPredicate(arg_node, arg_t);
        if (try self.signaturePredicateAnnotationsAssignable(source_pred, target_pred)) return null;
        const source_name = if (source_pred) |pred|
            (try self.allocCallSignatureFnTypeNameWithPredicate(arg_t, null, pred)) orelse return null
        else
            (try self.allocCallableSignatureName(arg_t)) orelse return null;
        const target_name = (try self.allocCallSignatureFnTypeNameWithPredicate(param_t, null, target_pred)) orelse return null;
        return try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Argument of type '{s}' is not assignable to parameter of type '{s}'.",
            .{ source_name, target_name },
        );
    }

    fn objectMemberSignatureThisTypesAssignable(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return true;
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (!source_flags.is_object_type or !target_flags.is_object_type) return true;
        const source_members = self.interner.objectMembers(source_t);
        for (self.interner.objectMembers(target_t)) |tm| {
            for (source_members) |sm| {
                if (sm.name != tm.name) continue;
                if (!self.interner.isSignature(sm.type) or !self.interner.isSignature(tm.type)) break;
                if (!try self.signatureThisTypesAssignable(sm.type, tm.type)) return false;
                break;
            }
        }
        return true;
    }

    fn signaturePredicatesAssignable(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (!self.interner.isSignature(source_t) or !self.interner.isSignature(target_t)) return true;
        const target_pred = self.signature_predicates.get(target_t) orelse return true;
        const source_pred = self.signature_predicates.get(source_t) orelse return false;
        if (source_pred.param_index != target_pred.param_index) return false;
        if (source_pred.is_asserts != target_pred.is_asserts) return false;
        if (source_pred.target_type == target_pred.target_type) return true;
        if (source_pred.target_type == types.Primitive.none or target_pred.target_type == types.Primitive.none) {
            return source_pred.target_type == target_pred.target_type;
        }
        return self.engine.isAssignableTo(source_pred.target_type, target_pred.target_type) catch return error.OutOfMemory;
    }

    fn sourceHasOptionalMemberForRequiredTarget(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return false;
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (!source_flags.is_object_type or !target_flags.is_object_type) return false;
        const source_members = self.interner.objectMembers(source_t);
        for (self.interner.objectMembers(target_t)) |tm| {
            if (tm.is_optional) continue;
            for (source_members) |sm| {
                if (sm.name == tm.name and sm.is_optional) return true;
            }
        }
        return false;
    }

    fn nonStrictTargetIsUndefinedOnly(self: *Checker, target_t: TypeId) bool {
        if (target_t == types.Primitive.undefined_t) return true;
        if (target_t < types.Primitive.first_dynamic or target_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(target_t);
        if (flags.is_undefined) return true;
        if (!flags.is_union) return false;
        var saw = false;
        for (self.interner.unionMembers(target_t)) |member| {
            saw = true;
            if (!self.nonStrictTargetIsUndefinedOnly(member)) return false;
        }
        return saw;
    }

    fn checkerAssignableExpressionTo(self: *Checker, value_node: NodeId, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (!self.strict_flags.strict_null_checks and
            (source_t == types.Primitive.null_t or source_t == types.Primitive.undefined_t or source_t == types.Primitive.void_t) and
            !self.typeIsNullishOnly(target_t))
        {
            return true;
        }
        if (try self.literalExpressionAssignableToTarget(value_node, target_t)) return true;
        if (try self.finiteTemplateLiteralSourceAssignableToTarget(source_t, target_t)) return true;
        if (try self.templateLiteralSourceAssignableToTarget(source_t, target_t)) return true;
        if ((self.hir.kindOf(value_node) == .arrow_fn or self.hir.kindOf(value_node) == .fn_expr) and
            try self.functionExpressionAssignableToTarget(value_node, target_t))
        {
            return true;
        }
        if (self.hir.kindOf(value_node) == .object_literal and
            (self.objectLiteralAssignableToTarget(value_node, source_t, target_t) catch false))
        {
            return true;
        }
        if (self.hir.kindOf(value_node) == .array_literal and
            (self.arrayLiteralAssignableToTarget(value_node, target_t) catch false))
        {
            return true;
        }
        if (try self.constrainedTypeParameterAssignableToTarget(source_t, target_t)) return true;
        return try self.checkerAssignableTo(source_t, target_t);
    }

    fn diagnosticExpressionSourceType(self: *Checker, value_node: NodeId, fallback: TypeId) CheckError!TypeId {
        const literal_t = try self.expressionLiteralType(value_node, fallback);
        return self.widenLiteralType(literal_t);
    }

    fn diagnosticExpressionSourceTypeForTarget(
        self: *Checker,
        value_node: NodeId,
        fallback: TypeId,
        target_t: TypeId,
    ) CheckError!TypeId {
        if (target_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(target_t).is_literal) {
            return self.expressionLiteralType(value_node, fallback);
        }
        return self.diagnosticExpressionSourceType(value_node, fallback);
    }

    fn displayTypeWithFreeTypeParamsAsUnknown(self: *Checker, t: TypeId) CheckError!TypeId {
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        var visited: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
        defer visited.deinit(self.gpa);
        try self.collectFreeTypeParamFallbacks(t, &subs, &visited);
        if (subs.count() == 0) return t;
        return self.substituteType(t, &subs) catch t;
    }

    fn displayTypeWithFreeTypeParamsFallback(
        self: *Checker,
        t: TypeId,
        use_constraints: bool,
    ) CheckError!TypeId {
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        var visited: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
        defer visited.deinit(self.gpa);
        try self.collectFreeTypeParamDiagnosticFallbacks(t, use_constraints, &subs, &visited);
        if (subs.count() == 0) return t;
        const result = self.substituteType(t, &subs) catch t;
        if (result != t and self.interner.isSignature(t) and self.interner.isSignature(result)) {
            if (self.rest_signatures.contains(t)) try self.rest_signatures.put(self.gpa, result, {});
            if (self.signature_min_args.get(t)) |min_required| try self.signature_min_args.put(self.gpa, result, min_required);
            try self.copySignatureParamNames(result, t);
            try self.refreshSignatureParamNamesFromDecl(result);
        }
        return result;
    }

    fn refreshSignatureParamNamesFromDecl(self: *Checker, sig: TypeId) CheckError!void {
        const decl = self.signatureDeclNode(sig);
        if (decl == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(decl)) {
            .fn_type, .constructor_type => {
                const ft = hir_mod.fnTypeOf(self.hir, decl);
                const params = self.hir.childSlice(ft.params_start, @intCast(ft.params_len));
                try self.recordSignatureParamNames(sig, params);
            },
            .fn_decl, .fn_expr, .arrow_fn => {
                try self.recordSignatureParamNames(sig, hir_mod.fnParams(self.hir, decl));
            },
            else => {},
        }
    }

    fn collectFreeTypeParamDiagnosticFallbacks(
        self: *Checker,
        t: TypeId,
        use_constraints: bool,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
        visited: *std.AutoHashMapUnmanaged(TypeId, void),
    ) CheckError!void {
        if (t < types.Primitive.first_dynamic) return;
        if (t >= self.interner.pool.typeCount()) return;
        if (visited.contains(t)) return;
        try visited.put(self.gpa, t, {});
        const flags = self.interner.pool.flagsOf(t);
        const payload_idx = self.interner.pool.payloadOf(t);
        if (flags.is_type_parameter) {
            if (self.isThisTypeParameter(t)) return;
            if (!subs.contains(t)) {
                const fallback = if (use_constraints)
                    (self.typeParameterConstraint(t) orelse types.Primitive.any)
                else
                    types.Primitive.any;
                try subs.put(self.gpa, t, fallback);
            }
            return;
        }
        if (flags.is_union) {
            if (payload_idx >= self.interner.pool.union_payloads.items.len) return;
            for (self.interner.unionMembers(t)) |m| try self.collectFreeTypeParamDiagnosticFallbacks(m, use_constraints, subs, visited);
            return;
        }
        if (flags.is_intersection) {
            if (payload_idx >= self.interner.pool.intersection_payloads.items.len) return;
            for (self.interner.intersectionMembers(t)) |m| try self.collectFreeTypeParamDiagnosticFallbacks(m, use_constraints, subs, visited);
            return;
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |m| try self.collectFreeTypeParamDiagnosticFallbacks(m.type, use_constraints, subs, visited);
            const str_idx = self.interner.objectStringIndex(t);
            if (str_idx != types.Primitive.none) try self.collectFreeTypeParamDiagnosticFallbacks(str_idx, use_constraints, subs, visited);
            const num_idx = self.interner.objectNumberIndex(t);
            if (num_idx != types.Primitive.none) try self.collectFreeTypeParamDiagnosticFallbacks(num_idx, use_constraints, subs, visited);
            return;
        }
        if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |p| try self.collectFreeTypeParamDiagnosticFallbacks(p, use_constraints, subs, visited);
            if (self.interner.signatureReturn(t)) |r| try self.collectFreeTypeParamDiagnosticFallbacks(r, use_constraints, subs, visited);
        }
    }

    fn contextualFunctionPropertyArityMismatch(
        self: *Checker,
        value_node: NodeId,
        source_t: TypeId,
        target_t: TypeId,
    ) bool {
        if (!self.isContextualFunctionExpressionLike(value_node)) return false;
        const source_sig = self.firstSignatureType(source_t) orelse return false;
        const target_sig = self.firstSignatureType(target_t) orelse return false;
        if (self.rest_signatures.contains(target_sig)) return false;
        const source_params = self.interner.signatureParams(source_sig);
        const target_params = self.interner.signatureParams(target_sig);
        const source_min = self.signatureMinRequiredArgs(source_sig, source_params);
        return source_min > target_params.len;
    }

    fn nonStrictSourceAssignableToUndefinedTarget(self: *Checker, source_t: TypeId) bool {
        if (source_t < types.Primitive.first_dynamic) {
            return source_t != types.Primitive.object_t and
                source_t != types.Primitive.never and
                source_t != types.Primitive.void_t;
        }
        if (source_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(source_t);
        if (flags.is_literal) return true;
        if (flags.is_union) {
            for (self.interner.unionMembers(source_t)) |member| {
                if (!self.nonStrictSourceAssignableToUndefinedTarget(member)) return false;
            }
            return true;
        }
        return false;
    }

    fn nonStrictObjectLiteralAssignableToUndefinedMembers(self: *Checker, init_node: NodeId, target_t: TypeId) CheckError!bool {
        if (self.strict_flags.strict_null_checks) return false;
        if (self.hir.kindOf(init_node) != .object_literal) return false;
        if (target_t >= self.interner.pool.typeCount()) return false;
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (!target_flags.is_object_type) return false;
        const target_members = self.interner.objectMembers(target_t);
        if (target_members.len == 0) return false;
        var used_undefined_member_rule = false;
        for (target_members) |tm| {
            var matched_value = hir_mod.none_node_id;
            for (hir_mod.objectLiteralProps(self.hir, init_node)) |prop_node| {
                if (self.hir.kindOf(prop_node) != .object_property) continue;
                const op = hir_mod.objectPropertyOf(self.hir, prop_node);
                if (op.key == hir_mod.none_node_id or op.value == hir_mod.none_node_id) continue;
                const key_name = self.propertyNameFromKeyNode(op.key) orelse continue;
                if (key_name == tm.name) {
                    matched_value = op.value;
                    break;
                }
            }
            const value_node = matched_value;
            if (value_node == hir_mod.none_node_id) {
                if (tm.is_optional) continue;
                return false;
            }
            const source_t = if (self.hir.typeOf(value_node) != types.Primitive.none)
                self.hir.typeOf(value_node)
            else
                try self.checkExpression(value_node);
            if (self.nonStrictTargetIsUndefinedOnly(tm.type) and
                self.nonStrictSourceAssignableToUndefinedTarget(source_t))
            {
                used_undefined_member_rule = true;
                continue;
            }
            if (!(self.engine.isAssignableTo(source_t, tm.type) catch return error.OutOfMemory)) return false;
        }
        return used_undefined_member_rule;
    }

    fn constrainedTypeParameterAssignableToTarget(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (source_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(source_t).is_type_parameter) return false;
        const constraint = self.typeParameterConstraint(source_t) orelse return false;
        if (constraint == source_t) return false;
        return self.engine.isAssignableTo(constraint, target_t) catch return error.OutOfMemory;
    }

    fn conditionalExpressionAssignableToTarget(self: *Checker, value_node: NodeId, target_t: TypeId) CheckError!bool {
        if (value_node == hir_mod.none_node_id or self.hir.kindOf(value_node) != .conditional) return false;
        const c = hir_mod.conditionalOf(self.hir, value_node);
        const then_t = if (self.hir.typeOf(c.then_branch) != types.Primitive.none)
            self.hir.typeOf(c.then_branch)
        else
            try self.checkExpression(c.then_branch);
        const else_t = if (self.hir.typeOf(c.else_branch) != types.Primitive.none)
            self.hir.typeOf(c.else_branch)
        else
            try self.checkExpression(c.else_branch);
        return (try self.expressionNodeAssignableToTarget(c.then_branch, then_t, target_t)) and
            (try self.expressionNodeAssignableToTarget(c.else_branch, else_t, target_t));
    }

    fn conditionalArrayBranchesAssignableToTupleUnion(self: *Checker, value_node: NodeId, target_t: TypeId) CheckError!bool {
        if (value_node == hir_mod.none_node_id or self.hir.kindOf(value_node) != .conditional) return false;
        if (target_t < types.Primitive.first_dynamic or target_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(target_t).is_union) return false;
        for (self.interner.unionMembers(target_t)) |member| {
            if (!self.isTupleShapedTarget(member)) return false;
        }
        const c = hir_mod.conditionalOf(self.hir, value_node);
        if (self.hir.kindOf(c.then_branch) != .array_literal or self.hir.kindOf(c.else_branch) != .array_literal) return false;

        try self.pushNarrowScope();
        try self.applyTypeGuard(c.cond, true);
        const then_ok = try self.arrayLiteralAssignableToTarget(c.then_branch, target_t);
        self.popNarrowScope();

        try self.pushNarrowScope();
        try self.applyTypeGuard(c.cond, false);
        const else_ok = try self.arrayLiteralAssignableToTarget(c.else_branch, target_t);
        self.popNarrowScope();
        return then_ok and else_ok;
    }

    fn awaitedExpressionAssignableToTarget(self: *Checker, value_node: NodeId, value_t: TypeId, target_t: TypeId) CheckError!bool {
        if (value_node == hir_mod.none_node_id or self.hir.kindOf(value_node) != .await_expr) return false;
        const a = hir_mod.awaitExprOf(self.hir, value_node);
        if (a.expr == hir_mod.none_node_id) return false;
        const operand_t = if (self.hir.typeOf(a.expr) != types.Primitive.none)
            self.hir.typeOf(a.expr)
        else
            try self.checkExpression(a.expr);
        if (self.promiseConstructorResolvedArgumentFromExpr(a.expr)) |resolved| {
            const resolved_t = if (self.hir.typeOf(resolved) != types.Primitive.none)
                self.hir.typeOf(resolved)
            else
                try self.checkExpression(resolved);
            if (try self.expressionNodeAssignableToTarget(resolved, resolved_t, target_t)) return true;
        }
        const awaited_t = self.unwrapPromise(operand_t);
        if (awaited_t != value_t and try self.expressionNodeAssignableToTarget(a.expr, awaited_t, target_t)) return true;
        return try self.expressionNodeAssignableToTarget(a.expr, value_t, target_t);
    }

    fn logicalExpressionAssignableToTarget(self: *Checker, value_node: NodeId, target_t: TypeId) CheckError!bool {
        if (value_node == hir_mod.none_node_id or self.hir.kindOf(value_node) != .logical_op) return false;
        const l = hir_mod.logicalOf(self.hir, value_node);
        if (l.op != .@"and" and l.op != .@"or") return false;
        const lhs_t = if (self.hir.typeOf(l.lhs) != types.Primitive.none)
            self.hir.typeOf(l.lhs)
        else
            try self.checkExpression(l.lhs);
        const literal_lhs_t = try self.expressionLiteralType(l.lhs, lhs_t);
        const short_circuit_t = if (l.op == .@"and")
            try self.logicalAndFalsyType(literal_lhs_t)
        else
            try self.logicalOrTruthyType(literal_lhs_t);
        const rhs_reachable = if (l.op == .@"and")
            self.logicalTypeCanBeTruthy(literal_lhs_t)
        else
            self.logicalTypeCanBeFalsy(literal_lhs_t);
        if (!rhs_reachable) return try self.checkerAssignableTo(short_circuit_t, target_t);
        if (short_circuit_t != types.Primitive.never and
            !try self.checkerAssignableTo(short_circuit_t, target_t))
        {
            return false;
        }
        const rhs_t = if (self.hir.typeOf(l.rhs) != types.Primitive.none)
            self.hir.typeOf(l.rhs)
        else
            try self.checkExpression(l.rhs);
        if (try self.expressionNodeAssignableToTarget(l.rhs, rhs_t, target_t)) return true;
        if (try self.constrainedTypeParameterAssignableToTarget(rhs_t, target_t)) return true;
        if ((self.hir.kindOf(l.rhs) == .arrow_fn or self.hir.kindOf(l.rhs) == .fn_expr) and
            try self.functionExpressionAssignableToTarget(l.rhs, target_t))
        {
            return true;
        }
        return false;
    }

    fn commaExpressionRhsFunction(self: *Checker, value_node: NodeId) NodeId {
        if (value_node == hir_mod.none_node_id or self.hir.kindOf(value_node) != .binary_op) return hir_mod.none_node_id;
        const b = hir_mod.binopOf(self.hir, value_node);
        if (b.op != .comma) return hir_mod.none_node_id;
        return switch (self.hir.kindOf(b.rhs)) {
            .arrow_fn, .fn_expr, .fn_decl => b.rhs,
            .binary_op => self.commaExpressionRhsFunction(b.rhs),
            else => hir_mod.none_node_id,
        };
    }

    fn logicalExpressionRhsFunction(self: *Checker, value_node: NodeId) NodeId {
        if (value_node == hir_mod.none_node_id or self.hir.kindOf(value_node) != .logical_op) return hir_mod.none_node_id;
        const l = hir_mod.logicalOf(self.hir, value_node);
        if (l.op != .@"and") return hir_mod.none_node_id;
        return switch (self.hir.kindOf(l.rhs)) {
            .arrow_fn, .fn_expr, .fn_decl => l.rhs,
            else => hir_mod.none_node_id,
        };
    }

    fn reportLogicalTruthyFunctionImplicitAnyParams(self: *Checker, fn_node: NodeId) CheckError!void {
        const fn_kind = self.hir.kindOf(fn_node);
        if (fn_kind != .arrow_fn and fn_kind != .fn_expr and fn_kind != .fn_decl) return;
        if (!self.strict_flags.no_implicit_any) return;
        for (hir_mod.fnParams(self.hir, fn_node)) |param| {
            if (param == hir_mod.none_node_id or self.hir.kindOf(param) != .parameter) continue;
            const p = hir_mod.parameterOf(self.hir, param);
            if (p.type_annotation != hir_mod.none_node_id) continue;
            if (p.name == hir_mod.none_node_id or self.hir.kindOf(p.name) != .identifier) continue;
            const name = self.string_interner.get(hir_mod.identifierOf(self.hir, p.name).name);
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Parameter '{s}' implicitly has an 'any' type.",
                .{name},
            );
            if (!self.diagnosticExists(param, TsCodes.parameter_implicitly_any) and
                !self.diagnosticExists(p.name, TsCodes.parameter_implicitly_any))
            {
                try self.diagnostics.append(self.gpa, .{
                    .node = param,
                    .code = TsCodes.parameter_implicitly_any,
                    .message = msg,
                });
            }
        }
    }

    /// Predicate: in an ambient context (`.d.ts` or `declare`),
    /// `const` declarations may carry a constant-value initializer
    /// (literals, `-N`/`+N` numeric literals). Mirrors upstream
    /// tsc's grammar exception that treats these as inline literal
    /// type annotations rather than runtime initializers.
    fn ambientInitializerIsConstantValue(self: *Checker, init_node: NodeId) bool {
        if (init_node == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(init_node)) {
            .literal_string, .literal_number, .literal_bool, .literal_bigint => true,
            .unary_op => blk: {
                const u = hir_mod.unaryOf(self.hir, init_node);
                if (u.op != .neg and u.op != .plus) break :blk false;
                const inner_kind = self.hir.kindOf(u.operand);
                break :blk inner_kind == .literal_number or inner_kind == .literal_bigint;
            },
            else => false,
        };
    }

    fn constInitializerType(self: *Checker, init_node: NodeId, fallback: TypeId) CheckError!TypeId {
        return switch (self.hir.kindOf(init_node)) {
            .literal_string, .literal_number, .literal_bool, .literal_bigint => self.literalizeForAsConst(init_node, fallback) catch return error.OutOfMemory,
            .as_expr, .type_assertion => blk: {
                const a = hir_mod.asExpressionOf(self.hir, init_node);
                if (a.type_node != hir_mod.none_node_id and self.isAsConstMarker(a.type_node)) {
                    break :blk self.literalizeForAsConst(a.expr, fallback) catch return error.OutOfMemory;
                }
                break :blk fallback;
            },
            .conditional => blk: {
                const c = hir_mod.conditionalOf(self.hir, init_node);
                const then_fallback = self.hir.typeOf(c.then_branch);
                const else_fallback = self.hir.typeOf(c.else_branch);
                const then_t = try self.constInitializerType(
                    c.then_branch,
                    if (then_fallback != types.Primitive.none) then_fallback else fallback,
                );
                const else_t = try self.constInitializerType(
                    c.else_branch,
                    if (else_fallback != types.Primitive.none) else_fallback else fallback,
                );
                if (then_t == else_t) break :blk then_t;
                break :blk try self.internUnionReducingStringSubtypes(&.{ then_t, else_t });
            },
            else => fallback,
        };
    }

    fn jsDocTypeForVarDecl(self: *Checker, node: NodeId) CheckError!?TypeId {
        if (!self.sourceHasCheckJsDirective()) {
            if (!self.sourceHasAllowJsDirective()) return null;
            if (self.sourceHasVirtualFilenameSections() and !self.virtualSectionIsJsLike(node)) return null;
            const v = hir_mod.varDeclOf(self.hir, node);
            if (v.init != hir_mod.none_node_id) return null;
        }
        return try self.jsDocTypeForLeadingNodeUnchecked(node);
    }

    fn jsDocTypeForPreviousIdentifierDecl(self: *Checker, node: NodeId) CheckError!?TypeId {
        if (!self.sourceHasCheckJsDirective()) return null;
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        if (self.source_has_virtual_sections and
            !self.virtualSectionIsJsLike(node))
        {
            return null;
        }
        const id = hir_mod.identifierOf(self.hir, node);
        if (self.nearestPriorValueDeclInSameFunction(node, id.name)) |decl| {
            if (try self.jsDocTypeForLeadingNode(decl)) |declared_t| return declared_t;
        }
        const use_start = self.hir.spanOf(node).start;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const stmts: ?[]const NodeId = switch (self.hir.kindOf(cur)) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl => hir_mod.namespaceBody(self.hir, cur),
                else => null,
            };
            if (stmts) |items| {
                for (items) |stmt| {
                    if (self.hir.spanOf(stmt).start >= use_start) break;
                    const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
                    if (decl == hir_mod.none_node_id) continue;
                    const dk = self.hir.kindOf(decl);
                    if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
                    const v = hir_mod.varDeclOf(self.hir, decl);
                    if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, v.name).name != id.name) continue;
                    return try self.jsDocTypeForLeadingNode(decl);
                }
            }
        }
        return null;
    }

    fn jsDocAssignmentIdentifierTypeName(self: *Checker, node: NodeId, source_t: TypeId) CheckError!?[]const u8 {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        if ((try self.jsDocTypeForPreviousIdentifierDecl(node)) == null) return null;
        return try self.allocAssignmentDiagnosticTypeName(source_t);
    }

    fn nearestPriorValueDeclInSameFunction(self: *Checker, node: NodeId, name: hir_mod.StringId) ?NodeId {
        const use_start = self.hir.spanOf(node).start;
        const use_function = self.enclosingFunctionLike(node);
        var nearest = hir_mod.none_node_id;
        var nearest_start: u32 = 0;
        var candidate: NodeId = 0;
        while (candidate < self.hir.nodeCount()) : (candidate += 1) {
            const kind = self.hir.kindOf(candidate);
            if (kind != .var_decl and kind != .let_decl and kind != .const_decl) continue;
            const start = self.hir.spanOf(candidate).start;
            if (start >= use_start or (nearest != hir_mod.none_node_id and start <= nearest_start)) continue;
            const declaration = hir_mod.varDeclOf(self.hir, candidate);
            if (declaration.name == hir_mod.none_node_id or self.hir.kindOf(declaration.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, declaration.name).name != name) continue;
            const candidate_function = self.enclosingFunctionLike(candidate);
            if (candidate_function != use_function) {
                if (candidate_function != null or use_function == null) continue;
                const function_span = self.hir.spanOf(use_function.?);
                if (start < function_span.start or start >= function_span.end) continue;
            }
            if (self.source_has_virtual_sections and
                self.virtualSectionStartForNode(candidate) != self.virtualSectionStartForNode(node))
            {
                continue;
            }
            nearest = candidate;
            nearest_start = start;
        }
        return if (nearest == hir_mod.none_node_id) null else nearest;
    }

    fn reportJsDocArrayAssignmentMismatch(self: *Checker, node: NodeId, target_node: NodeId, value_node: NodeId) CheckError!bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        if (target_node == hir_mod.none_node_id or value_node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(target_node) != .identifier or self.hir.kindOf(value_node) != .identifier) return false;
        if (self.source_has_virtual_sections and
            (!self.virtualSectionIsJsLike(target_node) or !self.virtualSectionIsJsLike(value_node)))
        {
            return false;
        }
        const target_t = (try self.jsDocTypeForPreviousIdentifierDecl(target_node)) orelse return false;
        const source_t = (try self.jsDocTypeForPreviousIdentifierDecl(value_node)) orelse return false;
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return false;
        const source_idx = self.interner.objectNumberIndex(source_t);
        const target_idx = self.interner.objectNumberIndex(target_t);
        if (source_idx == types.Primitive.none or target_idx == types.Primitive.none) return false;
        if (self.engine.isAssignableTo(source_idx, target_idx) catch return error.OutOfMemory) return false;
        self.removePriorDiagnosticsInNodeSpan(node, TsCodes.type_not_assignable);
        try self.reportAssignmentTypeNotAssignable(
            node,
            value_node,
            target_node,
            source_t,
            source_t,
            target_t,
            "Type is not assignable to target type.",
        );
        return true;
    }

    fn dynamicImportDefinitelyMismatchesTypeofNamespace(self: *Checker, init_node: NodeId, type_annotation: NodeId) bool {
        if (init_node == hir_mod.none_node_id or type_annotation == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(init_node) != .call_expr) return false;
        const c = hir_mod.callOf(self.hir, init_node);
        if (!self.isDynamicImportCallee(c.callee)) return false;
        const args = hir_mod.callArgs(self.hir, init_node);
        if (args.len == 0 or self.hir.kindOf(args[0]) != .literal_string) return false;
        const src = self.source orelse return false;
        const anno_span = self.hir.spanOf(type_annotation);
        if (anno_span.start >= anno_span.end or anno_span.end > src.len) return false;
        const anno_text = src[anno_span.start..anno_span.end];
        const typeof_pos = std.mem.indexOf(u8, anno_text, "typeof") orelse return false;
        var rest = std.mem.trim(u8, anno_text[typeof_pos + "typeof".len ..], " \t\r\n<>(),");
        var name_len: usize = 0;
        while (name_len < rest.len and isJsDocIdentChar(rest[name_len])) : (name_len += 1) {}
        if (name_len == 0) return false;
        rest = rest[0..name_len];
        const namespace_id = self.string_interner.intern(rest) catch return false;
        const expected_spec = self.namespaceImportSpecifierForLocal(namespace_id, init_node) orelse return false;
        const lit = hir_mod.literalStringOf(self.hir, args[0]);
        const actual_spec = self.string_interner.get(lit.value);
        return !moduleSpecifiersEquivalent(expected_spec, actual_spec);
    }

    fn namespaceImportSpecifierForLocal(self: *Checker, local_name: hir_mod.StringId, anchor: NodeId) ?[]const u8 {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const anchor_section = if (self.sourceHasVirtualFilenameSections()) self.virtualSectionStartForNode(anchor) else 0;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.hir.kindOf(stmt) != .import_decl) continue;
            if (self.sourceHasVirtualFilenameSections() and self.virtualSectionStartForNode(stmt) != anchor_section) continue;
            const imp = hir_mod.importOf(self.hir, stmt);
            if (imp.namespace_binding == hir_mod.none_node_id or self.hir.kindOf(imp.namespace_binding) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, imp.namespace_binding).name != local_name) continue;
            return self.string_interner.get(imp.module);
        }
        return null;
    }

    fn moduleSpecifiersEquivalent(a_raw: []const u8, b_raw: []const u8) bool {
        var a = a_raw;
        var b = b_raw;
        while (std.mem.startsWith(u8, a, "./")) a = a[2..];
        while (std.mem.startsWith(u8, b, "./")) b = b[2..];
        return std.mem.eql(u8, a, b);
    }

    fn jsDocTypeForLeadingNode(self: *Checker, node: NodeId) CheckError!?TypeId {
        if (!self.sourceHasCheckJsDirective()) return null;
        return try self.jsDocTypeForLeadingNodeUnchecked(node);
    }

    fn jsDocTypeForLeadingNodeUnchecked(self: *Checker, node: NodeId) CheckError!?TypeId {
        const src = self.source orelse return null;
        var body = self.leadingJsDocBody(src, self.leadingJsDocStartForNode(node));
        if (body == null) {
            const kind = self.hir.kindOf(node);
            if (kind == .var_decl or kind == .let_decl or kind == .const_decl) {
                if (self.varStatementStartForDeclarator(src, self.hir.spanOf(node).start)) |statement_start| {
                    body = self.leadingJsDocBody(src, statement_start);
                }
            }
        }
        const jsdoc_body = body orelse return null;
        const tags = ts_parser.jsdoc.parse(self.gpa, jsdoc_body) catch return null;
        defer self.gpa.free(tags);

        for (tags) |tag| {
            if (tag.kind != .type_tag) continue;
            if (try self.jsDocTypeTextToTypeAt(src, tag.type_text, node)) |t| return t;
            if (try self.jsDocQualifiedNameTypeForNode(src, tag.type_text, node)) |t| return t;
        }
        return null;
    }

    fn inlineJsDocCastType(self: *Checker, node: NodeId, base_t: TypeId) CheckError!?TypeId {
        if (!self.sourceHasCheckJsDirective()) return null;
        if (self.source_has_virtual_sections and !self.virtualSectionIsJsLike(node)) return null;
        const src = self.source orelse return null;
        const span = self.hir.spanOf(node);
        if (span.start >= span.end or span.end > src.len) return null;

        var wrapper_start: usize = span.start;
        var wrapper_end: usize = span.end;
        var result_t = base_t;
        var found = false;
        while (true) {
            var open_after = wrapper_start;
            while (open_after > 0 and std.ascii.isWhitespace(src[open_after - 1])) : (open_after -= 1) {}
            if (open_after == 0 or src[open_after - 1] != '(') break;
            const open_pos = open_after - 1;

            var close_pos = wrapper_end;
            while (close_pos < src.len and std.ascii.isWhitespace(src[close_pos])) : (close_pos += 1) {}
            if (close_pos >= src.len or src[close_pos] != ')') break;

            var comment_end = open_pos;
            while (comment_end > 0 and std.ascii.isWhitespace(src[comment_end - 1])) : (comment_end -= 1) {}
            if (comment_end < 2 or !std.mem.eql(u8, src[comment_end - 2 .. comment_end], "*/")) break;
            const body_end = comment_end - 2;
            const comment_start = std.mem.lastIndexOf(u8, src[0..body_end], "/**") orelse break;
            const body = src[comment_start + 3 .. body_end];
            const tags = ts_parser.jsdoc.parse(self.gpa, body) catch break;
            defer self.gpa.free(tags);

            var cast_t: ?TypeId = null;
            for (tags) |tag| {
                if (tag.kind != .type_tag or tag.type_text.len == 0) continue;
                cast_t = try self.jsDocTypeTextToTypeAt(src, tag.type_text, node);
                break;
            }
            result_t = cast_t orelse break;
            found = true;
            wrapper_start = comment_start;
            wrapper_end = close_pos + 1;
        }
        return if (found) result_t else null;
    }

    fn jsDocContextualSignatureForFunction(self: *Checker, node: NodeId) CheckError!?TypeId {
        if (!self.sourceHasCheckJsDirective()) return null;
        if (self.source_has_virtual_sections and !self.virtualSectionIsJsLike(node)) return null;
        if (try self.jsDocSatisfiesContextualSignatureForFunction(node)) |sig| return sig;
        const jsdoc_node = blk: {
            const parent = self.hir.parentOf(node);
            if (parent == hir_mod.none_node_id) break :blk node;
            switch (self.hir.kindOf(parent)) {
                .var_decl, .let_decl, .const_decl => {
                    const decl = hir_mod.varDeclOf(self.hir, parent);
                    if (decl.init == node) break :blk parent;
                },
                .object_property => {
                    const property = hir_mod.objectPropertyOf(self.hir, parent);
                    if (property.value == node) break :blk parent;
                },
                else => {},
            }
            break :blk node;
        };
        const t = (try self.jsDocTypeForLeadingNode(jsdoc_node)) orelse return null;
        if (self.callableSignatureCount(t) != 1) return null;
        return self.firstSignatureType(t);
    }

    fn jsDocSatisfiesContextualSignatureForFunction(self: *Checker, node: NodeId) CheckError!?TypeId {
        const property_node = self.hir.parentOf(node);
        if (property_node == hir_mod.none_node_id) return null;
        const parent_kind = self.hir.kindOf(property_node);
        if (parent_kind == .var_decl or parent_kind == .let_decl or parent_kind == .const_decl) {
            if (hir_mod.varDeclOf(self.hir, property_node).init != node) return null;
            const target_t = (try self.jsDocSatisfiesTypeForExpression(node)) orelse return null;
            return self.firstSignatureType(target_t);
        }
        if (parent_kind != .object_property) return null;
        const property = hir_mod.objectPropertyOf(self.hir, property_node);
        if (property.value != node or property.is_computed) return null;
        const object_node = self.hir.parentOf(property_node);
        if (object_node == hir_mod.none_node_id or self.hir.kindOf(object_node) != .object_literal) return null;
        const target_t = (try self.jsDocSatisfiesTypeForExpression(object_node)) orelse return null;
        const name = self.propertyNameFromKeyNode(property.key) orelse return null;
        const member_t = (try self.contextualObjectLiteralMemberTarget(target_t, name)) orelse return null;
        return self.firstSignatureType(member_t);
    }

    fn jsDocTypeTextToTypeAt(self: *Checker, src: []const u8, type_text: []const u8, at_node: NodeId) CheckError!?TypeId {
        const prev = self.jsdoc_diagnostic_anchor;
        if (at_node != hir_mod.none_node_id) self.jsdoc_diagnostic_anchor = at_node;
        defer self.jsdoc_diagnostic_anchor = prev;
        return try self.jsDocTypeTextToType(src, type_text);
    }

    fn jsDocQualifiedNameTypeForNode(self: *Checker, src: []const u8, type_text: []const u8, at_node: NodeId) CheckError!?TypeId {
        const trimmed = jsDocTrimOuterParens(std.mem.trim(u8, type_text, " \t\r\n"));
        if (trimmed.len == 0) return null;
        var dot_count: usize = 0;
        var dot_pos: usize = 0;
        for (trimmed, 0..) |c, i| {
            if (c == '.') {
                dot_count += 1;
                dot_pos = i;
                continue;
            }
            if (!isJsDocIdentChar(c)) return null;
        }
        if (dot_count != 1 or dot_pos == 0 or dot_pos + 1 >= trimmed.len) return null;
        const root_text = trimmed[0..dot_pos];
        const leaf_text = trimmed[dot_pos + 1 ..];
        const root_name = self.string_interner.intern(root_text) catch return error.OutOfMemory;
        const leaf_name = self.string_interner.intern(leaf_text) catch return error.OutOfMemory;
        if (try self.checkJsObjectExpandoQualifiedType(root_name, leaf_name, at_node)) |t| return t;
        const root_t = (try self.typeOfVisibleNameNoDiag(at_node, root_name)) orelse return null;
        if (try self.lookupObjectMember(root_t, leaf_name)) |member_t| return member_t;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Namespace '{s}' has no exported member '{s}'.",
            .{ root_text, leaf_text },
        );
        const base_pos = self.sliceStartPos(src, trimmed);
        const leaf_pos = if (base_pos) |base| base + @as(u32, @intCast(dot_pos + 1)) else null;
        for (self.diagnostics.items) |d| {
            if (d.code == TsCodes.namespace_no_exported_member and d.pos == leaf_pos) return types.Primitive.unknown;
        }
        try self.diagnostics.append(self.gpa, .{
            .node = at_node,
            .pos = leaf_pos,
            .code = TsCodes.namespace_no_exported_member,
            .message = msg,
        });
        return types.Primitive.unknown;
    }

    fn jsDocQualifiedNamespaceTextToType(self: *Checker, src: []const u8, type_text: []const u8) CheckError!?TypeId {
        const trimmed = jsDocTrimOuterParens(std.mem.trim(u8, type_text, " \t\r\n"));
        var first_dot: ?usize = null;
        var second_dot: ?usize = null;
        var segment_start: usize = 0;
        for (trimmed, 0..) |c, i| {
            if (c == '.') {
                if (i == segment_start) return null;
                if (first_dot == null) {
                    first_dot = i;
                } else if (second_dot == null) {
                    second_dot = i;
                }
                segment_start = i + 1;
                continue;
            }
            if (!isJsDocIdentChar(c)) return null;
        }
        if (segment_start >= trimmed.len) return null;
        const root_dot = first_dot orelse return null;
        const member_dot = second_dot orelse return null;
        if (root_dot == 0 or member_dot <= root_dot + 1) return null;
        const root_text = trimmed[0..root_dot];
        const member_text = trimmed[root_dot + 1 .. member_dot];
        if (!try self.jsDocKnownNamespaceRoot(root_text)) return null;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Namespace '{s}' has no exported member '{s}'.",
            .{ root_text, member_text },
        );
        const base_pos = self.sliceStartPos(src, trimmed);
        const member_pos = if (base_pos) |base| base + @as(u32, @intCast(root_dot + 1)) else null;
        for (self.diagnostics.items) |d| {
            if (d.code == TsCodes.namespace_no_exported_member and d.pos == member_pos) return types.Primitive.unknown;
        }
        const anchor = self.jsdoc_diagnostic_anchor;
        if (anchor == hir_mod.none_node_id) return null;
        try self.diagnostics.append(self.gpa, .{
            .node = anchor,
            .pos = member_pos,
            .code = TsCodes.namespace_no_exported_member,
            .message = msg,
        });
        return types.Primitive.unknown;
    }

    fn jsDocKnownNamespaceRoot(self: *Checker, root_text: []const u8) CheckError!bool {
        for (self.ambient_global_namespace_roots) |candidate| {
            if (std.mem.eql(u8, candidate, root_text)) return true;
        }
        for (self.script_object_expandos) |expando| {
            if (std.mem.eql(u8, expando.root, root_text)) return true;
        }
        if (self.module) |module| {
            const root_name = self.string_interner.intern(root_text) catch return error.OutOfMemory;
            if (module.root.namespaces.get(root_name) != null) return true;
        }
        if (self.source) |src| {
            if (sourceHasTopLevelNamespaceRootText(src, root_text)) return true;
        }
        return false;
    }

    fn sourceHasTopLevelNamespaceRootText(src: []const u8, root_text: []const u8) bool {
        var i: usize = 0;
        while (i < src.len) : (i += 1) {
            var after_keyword: usize = 0;
            if (sourceIdentifierKeywordAt(src, i, "declare")) {
                var p = i + "declare".len;
                while (p < src.len and std.ascii.isWhitespace(src[p])) p += 1;
                if (sourceIdentifierKeywordAt(src, p, "namespace")) {
                    after_keyword = p + "namespace".len;
                } else if (sourceIdentifierKeywordAt(src, p, "module")) {
                    after_keyword = p + "module".len;
                } else {
                    continue;
                }
            } else if (sourceIdentifierKeywordAt(src, i, "namespace")) {
                after_keyword = i + "namespace".len;
            } else if (sourceIdentifierKeywordAt(src, i, "module")) {
                after_keyword = i + "module".len;
            } else {
                continue;
            }
            var p = after_keyword;
            while (p < src.len and std.ascii.isWhitespace(src[p])) p += 1;
            if (p + root_text.len > src.len) continue;
            if (!std.mem.eql(u8, src[p .. p + root_text.len], root_text)) continue;
            const end = p + root_text.len;
            if (end < src.len and asciiIdentifierContinue(src[end])) continue;
            return true;
        }
        return false;
    }

    fn sourceIdentifierKeywordAt(src: []const u8, pos: usize, keyword: []const u8) bool {
        if (pos + keyword.len > src.len) return false;
        if (!std.mem.eql(u8, src[pos .. pos + keyword.len], keyword)) return false;
        if (pos > 0 and asciiIdentifierContinue(src[pos - 1])) return false;
        const end = pos + keyword.len;
        return end >= src.len or !asciiIdentifierContinue(src[end]);
    }

    fn jsDocTypeTextToType(self: *Checker, src: []const u8, type_text: []const u8) CheckError!?TypeId {
        const trimmed = jsDocTrimOuterParens(std.mem.trim(u8, type_text, " \t\r\n"));
        if (trimmed.len == 0) return null;
        if (std.mem.eql(u8, trimmed, "this") and self.jsDocTypeTextIsInCheckedJsContext()) {
            const this_id = self.string_interner.intern("this") catch return error.OutOfMemory;
            return self.lookupNarrow(this_id) orelse types.Primitive.any;
        }
        if (trimmed[0] == '?' and trimmed.len > 1) {
            var inner_text = std.mem.trim(u8, trimmed[1..], " \t\r\n");
            if (inner_text.len > 0 and inner_text[inner_text.len - 1] == '?') {
                inner_text = std.mem.trim(u8, inner_text[0 .. inner_text.len - 1], " \t\r\n");
            }
            if (inner_text.len > 0) {
                const inner_t = (try self.jsDocTypeTextToType(src, inner_text)) orelse return null;
                return try self.unionWithNull(inner_t);
            }
        }
        if (trimmed.len > 1 and trimmed[trimmed.len - 1] == '?') {
            const inner_text = std.mem.trim(u8, trimmed[0 .. trimmed.len - 1], " \t\r\n");
            if (inner_text.len > 0) {
                const inner_t = (try self.jsDocTypeTextToType(src, inner_text)) orelse return null;
                return try self.unionWithNull(inner_t);
            }
        }
        if (trimmed[0] == '!' and trimmed.len > 1) {
            const inner_text = std.mem.trim(u8, trimmed[1..], " \t\r\n");
            if (inner_text.len > 0) return try self.jsDocTypeTextToType(src, inner_text);
        }
        if (try self.jsDocImportTypeTextToType(src, trimmed)) |import_t| return import_t;
        if (try self.jsDocTypeofTextToType(trimmed)) |typeof_t| return typeof_t;
        if (try self.jsDocKeyofTextToType(src, trimmed)) |keyof_t| return keyof_t;
        if (try self.jsDocIndexedAccessTextToType(src, trimmed)) |indexed_t| return indexed_t;
        if (try self.jsDocQualifiedNamespaceTextToType(src, trimmed)) |qualified_t| return qualified_t;
        var tuple_text = trimmed;
        var tuple_readonly = false;
        if (std.mem.startsWith(u8, tuple_text, "readonly ")) {
            tuple_readonly = true;
            tuple_text = std.mem.trimStart(u8, tuple_text["readonly".len..], " \t\r\n");
        }
        if (tuple_text.len >= 2 and tuple_text[0] == '[' and tuple_text[tuple_text.len - 1] == ']') {
            const elements_text = tuple_text[1 .. tuple_text.len - 1];
            var element_types: std.ArrayListUnmanaged(TypeId) = .empty;
            defer element_types.deinit(self.gpa);
            var elements = JsDocTopLevelSplitter.init(elements_text, ',');
            while (elements.next()) |element_text| {
                const element = std.mem.trim(u8, element_text, " \t\r\n");
                if (element.len == 0) continue;
                const element_t = (try self.jsDocTypeTextToType(src, element)) orelse types.Primitive.any;
                try element_types.append(self.gpa, element_t);
            }
            return try self.internTupleFromTypes(element_types.items, tuple_readonly);
        }
        if (!jsDocSplitTopLevelAny(trimmed, '|') and
            !jsDocSplitTopLevelAny(trimmed, '&') and
            std.mem.endsWith(u8, trimmed, "[]"))
        {
            const elem_text = std.mem.trim(u8, trimmed[0 .. trimmed.len - 2], " \t\r\n");
            if (try self.jsDocTypeTextToType(src, elem_text)) |elem_t| {
                return self.interner.internArrayType(self.string_interner, elem_t) catch return error.OutOfMemory;
            }
        }
        // An arrow signature's return type extends through a following union:
        // `(x: T) => A | B` is one signature, not a union containing one.
        if (std.mem.indexOf(u8, trimmed, "=>") != null) {
            if (try self.jsDocFunctionType(trimmed)) |sig| return sig;
        }
        if (jsDocSplitTopLevelAny(trimmed, '|')) {
            var parts = JsDocTopLevelSplitter.init(trimmed, '|');
            var items: std.ArrayListUnmanaged(TypeId) = .empty;
            defer items.deinit(self.gpa);
            while (parts.next()) |part| {
                if (try self.jsDocTypeTextToType(src, part)) |member_t| {
                    try items.append(self.gpa, member_t);
                }
            }
            if (items.items.len == 0) return null;
            if (items.items.len == 1) return items.items[0];
            return self.interner.internUnion(items.items) catch return error.OutOfMemory;
        }
        if (jsDocSplitTopLevelAny(trimmed, '&')) {
            var parts = JsDocTopLevelSplitter.init(trimmed, '&');
            var items: std.ArrayListUnmanaged(TypeId) = .empty;
            defer items.deinit(self.gpa);
            while (parts.next()) |part| {
                if (try self.jsDocTypeTextToType(src, part)) |member_t| {
                    try items.append(self.gpa, member_t);
                }
            }
            if (items.items.len == 0) return null;
            if (items.items.len == 1) return items.items[0];
            return self.interner.internIntersection(items.items) catch return error.OutOfMemory;
        }
        if (jsDocQuotedString(trimmed)) |literal_text| {
            const sid = self.string_interner.intern(literal_text) catch return error.OutOfMemory;
            return self.interner.internStringLiteral(sid) catch return error.OutOfMemory;
        }
        if (sliceLooksNumeric(trimmed)) {
            const value = std.fmt.parseFloat(f64, trimmed) catch return null;
            return self.interner.internNumberLiteral(value) catch return error.OutOfMemory;
        }
        if (try self.jsDocGenericTypeTextToType(src, trimmed)) |generic_t| return generic_t;
        if (try self.jsDocFunctionType(trimmed)) |sig| return sig;
        if (try self.jsDocImportedNamespaceMemberType(src, trimmed)) |import_t| return import_t;
        if (try self.jsDocPrimitiveType(trimmed)) |prim| return prim;
        if (try self.jsDocMappedTypeTextToType(src, trimmed)) |mapped_t| return mapped_t;
        if (try self.jsDocObjectSkeletonFromTypeText(trimmed)) |obj| return obj;
        const base = jsDocTypeBaseName(trimmed);
        if (base.len == 0) return null;
        if (try self.jsDocCallbackSignature(src, base)) |sig| return sig;
        if (base.len == trimmed.len) {
            if (try self.jsDocGenericTypedefTypeTextToType(src, base, "")) |t| return t;
        }
        if (try self.jsDocTypedefObjectSkeleton(src, base)) |t| return t;
        if (try self.jsDocTypedefAliasType(src, base)) |t| return t;
        if (try self.jsDocImportedNameType(src, base)) |t| return t;
        const simple_t = try self.jsDocSimpleNameType(src, base);
        if (simple_t) |t| {
            if (!self.typeIsAnyLike(t)) return t;
        }
        if (base.len == trimmed.len and self.jsdoc_diagnostic_anchor != hir_mod.none_node_id) {
            const name = self.string_interner.intern(base) catch return error.OutOfMemory;
            if (try self.jsDocRequireAliasType(self.jsdoc_diagnostic_anchor, name, true)) |t| return t;
        }
        if (simple_t) |t| return t;
        if (try self.jsDocUnresolvedSimpleNameToType(src, trimmed, base)) |t| return t;
        return null;
    }

    fn jsDocTypeTextIsInCheckedJsContext(self: *Checker) bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        const anchor = self.jsdoc_diagnostic_anchor;
        if (anchor == hir_mod.none_node_id) return true;
        const span = self.hir.spanOf(anchor);
        return self.sourcePositionIsJsLike(span.start);
    }

    fn jsDocTypeofTextToType(self: *Checker, type_text: []const u8) CheckError!?TypeId {
        const prefix = "typeof";
        if (!std.mem.startsWith(u8, type_text, prefix)) return null;
        if (type_text.len == prefix.len or !std.ascii.isWhitespace(type_text[prefix.len])) return null;
        const operand = std.mem.trim(u8, type_text[prefix.len..], " \t\r\n");
        if (operand.len == 0) return types.Primitive.any;
        var dot_count: usize = 0;
        for (operand) |c| {
            if (c == '.') {
                dot_count += 1;
                continue;
            }
            if (!isJsDocIdentChar(c)) return types.Primitive.any;
        }
        if (dot_count > 0) {
            if (try self.typeOfDottedValueReference(operand, self.jsdoc_diagnostic_anchor)) |t| return t;
            return types.Primitive.any;
        }
        const name = self.string_interner.intern(operand) catch return error.OutOfMemory;
        const visible_t = try self.typeOfVisibleNameNoDiag(self.jsdoc_diagnostic_anchor, name);
        if (visible_t) |t| if (!self.typeIsAnyLike(t)) return t;
        if (try self.jsDocTypeofSiblingFunctionType(self.jsdoc_diagnostic_anchor, name)) |t| return t;
        if (visible_t) |t| return t;
        return types.Primitive.any;
    }

    fn jsDocTypeofSiblingFunctionType(self: *Checker, anchor: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (anchor == hir_mod.none_node_id) return null;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const fn_node = self.findFunctionDeclInStatements(hir_mod.blockStmts(self.hir, root), name) orelse return null;
        const existing = self.hir.typeOf(fn_node);
        if (existing != types.Primitive.none and !self.typeIsAnyLike(existing)) return existing;
        const sig = try self.checkFnSignatureOnly(fn_node);
        if (hir_mod.fnTypeParams(self.hir, fn_node).len > 0 or self.fnHasJsDocTemplateTags(fn_node)) self.popNarrowScope();
        self.hir.setType(fn_node, sig);
        return sig;
    }

    fn jsDocKeyofTextToType(self: *Checker, src: []const u8, type_text: []const u8) CheckError!?TypeId {
        const prefix = "keyof";
        if (!std.mem.startsWith(u8, type_text, prefix)) return null;
        if (type_text.len == prefix.len or !std.ascii.isWhitespace(type_text[prefix.len])) return null;
        const operand_text = std.mem.trim(u8, type_text[prefix.len..], " \t\r\n");
        if (operand_text.len == 0) return types.Primitive.any;
        const operand = (try self.jsDocTypeTextToType(src, operand_text)) orelse return null;
        if (operand == types.Primitive.any) return try self.propertyKeyUnionType();
        var key_names: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer key_names.deinit(self.gpa);
        if (try self.collectKeyofObjectKeys(operand, &key_names)) {
            if (key_names.items.len == 0) return types.Primitive.never;
            var lits: std.ArrayListUnmanaged(TypeId) = .empty;
            defer lits.deinit(self.gpa);
            for (key_names.items) |name| {
                const lit = self.interner.internStringLiteral(name) catch continue;
                try lits.append(self.gpa, lit);
            }
            if (lits.items.len == 1) return lits.items[0];
            return self.interner.internUnion(lits.items) catch return error.OutOfMemory;
        }
        return self.interner.internKeyof(operand) catch return error.OutOfMemory;
    }

    fn jsDocIndexedAccessTextToType(self: *Checker, src: []const u8, type_text: []const u8) CheckError!?TypeId {
        if (type_text.len < 4 or type_text[type_text.len - 1] != ']') return null;
        var depth_angle: usize = 0;
        var depth_paren: usize = 0;
        var depth_brace: usize = 0;
        var depth_bracket: usize = 0;
        var open_idx: ?usize = null;
        for (type_text, 0..) |c, i| {
            switch (c) {
                '<' => depth_angle += 1,
                '>' => {
                    if (depth_angle > 0) depth_angle -= 1;
                },
                '(' => depth_paren += 1,
                ')' => {
                    if (depth_paren > 0) depth_paren -= 1;
                },
                '{' => depth_brace += 1,
                '}' => {
                    if (depth_brace > 0) depth_brace -= 1;
                },
                '[' => {
                    if (depth_angle == 0 and depth_paren == 0 and depth_brace == 0 and depth_bracket == 0) open_idx = i;
                    depth_bracket += 1;
                },
                ']' => {
                    if (depth_bracket > 0) depth_bracket -= 1;
                },
                else => {},
            }
        }
        const open = open_idx orelse return null;
        if (open == 0) return null;
        const object_text = std.mem.trim(u8, type_text[0..open], " \t\r\n");
        const index_text = std.mem.trim(u8, type_text[open + 1 .. type_text.len - 1], " \t\r\n");
        if (object_text.len == 0 or index_text.len == 0) return null;
        const obj_t = (try self.jsDocTypeTextToType(src, object_text)) orelse return null;
        const idx_t = (try self.jsDocTypeTextToType(src, index_text)) orelse return null;
        if (try self.resolveObjectIndexedAccessType(obj_t, idx_t)) |resolved| return resolved;
        return self.interner.internIndexedAccess(obj_t, idx_t) catch return error.OutOfMemory;
    }

    fn jsDocSimpleNameType(self: *Checker, src: []const u8, base: []const u8) CheckError!?TypeId {
        _ = src;
        if (base.len == 0) return null;
        const name = self.string_interner.intern(base) catch return error.OutOfMemory;
        if (self.lookupNarrow(name)) |t| return t;
        const anchor = self.jsdoc_diagnostic_anchor;
        if (anchor != hir_mod.none_node_id) {
            if (try self.jsDocTemplateParamTypeForAnchor(anchor, name)) |t| return t;
            if (try self.jsConstructorInstanceTypeForHeritage(anchor, name)) |t| return t;
            if (self.type_names.get(name)) |t| {
                if (self.genericTypeAliasVisibleAt(anchor, name)) return t;
            }
        }
        if (self.jsDocBareBuiltinGenericType(base)) |t| return t;
        if (anchor != hir_mod.none_node_id) {
            if (try self.jsDocRequireAliasType(anchor, name, false)) |t| return t;
            if (try self.jsDocSameFileClassInstanceType(anchor, name)) |t| return t;
            if (try self.jsDocSameFileEnumTagType(anchor, name)) |t| return t;
        }
        if (std.mem.eql(u8, base, "Image")) {
            return self.seedCtor(self.htmlImageElementType() catch types.Primitive.any) catch types.Primitive.any;
        }
        return null;
    }

    /// Resolve a JSDoc type name that refers to a same-file `@enum`-tagged
    /// object literal (`/** @enum {string} */ const Target = { … }`) to the
    /// enum's backing type. The `@enum` JSDoc tag declares both a value and a
    /// type, so `@type {Target}` must resolve rather than report TS2304.
    /// Mirrors `jsDeclarationsEnumTag`.
    fn jsDocSameFileEnumTagType(self: *Checker, anchor: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (!self.check_js_enabled) return null;
        const src = self.source orelse return null;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            const decl = if (self.hir.kindOf(stmt) == .export_decl) self.unwrapExportDecl(stmt) else stmt;
            if (decl == hir_mod.none_node_id) continue;
            const dk = self.hir.kindOf(decl);
            if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
            const v = hir_mod.varDeclOf(self.hir, decl);
            if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, v.name).name != name) continue;
            // The `@enum` tag rides on the statement's leading JSDoc (before
            // any `export` keyword), so anchor the scan at the statement.
            const jsdoc = self.leadingJsDocBodyWithStart(src, self.hir.spanOf(stmt).start) orelse return null;
            if (std.mem.indexOf(u8, jsdoc.body, "@enum") == null) return null;
            const type_text = jsDocBlockTagTypeText(jsdoc.body, "@enum") orelse return types.Primitive.any;
            return (try self.jsDocTypeTextToTypeAt(src, type_text, anchor)) orelse types.Primitive.any;
        }
        return null;
    }

    /// Resolve a JSDoc type name that refers to a same-file class, including a
    /// forward reference (`/** @type {C} */ const c = …; class C {}`), to the
    /// class instance type. The JSDoc resolver runs while another declaration
    /// is being checked, so a class declared later isn't yet in
    /// `class_instance_types`; locate and check it on demand. Mirrors
    /// `jsdocTypeReferenceUseBeforeDef`.
    fn jsDocSameFileClassInstanceType(self: *Checker, anchor: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (!self.check_js_enabled) return null;
        if (self.class_instance_types.get(name)) |t| return t;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            const decl = if (self.hir.kindOf(stmt) == .export_decl) self.unwrapExportDecl(stmt) else stmt;
            if (decl == hir_mod.none_node_id or self.hir.kindOf(decl) != .class_decl) continue;
            const c = hir_mod.classOf(self.hir, decl);
            if (c.name == hir_mod.none_node_id or self.hir.kindOf(c.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, c.name).name != name) continue;
            try self.checkClassDecl(decl);
            if (self.class_instance_types.get(name)) |t| return t;
            return null;
        }
        if (self.module) |module| {
            if (module.root.lookup(name)) |symbol| {
                const decl = self.visibleValueSymbolDeclForNode(symbol.decls.items, anchor) orelse return null;
                const kind = self.hir.kindOf(decl);
                if (kind != .class_decl and kind != .class_expr) return null;
                try self.checkClassDecl(decl);
                if (self.class_instance_types.get(name)) |t| return t;
            }
        }
        return null;
    }

    /// Resolve a JSDoc type name bound to a CommonJS require alias —
    /// `const C = require('./ex').C` (and the `require('./ex')?.C` optional
    /// form) — to the imported member's type, so `@type {C}` resolves rather
    /// than reporting TS2304. Mirrors `jsdocTypeReferenceToImport`.
    fn jsDocRequireAliasType(self: *Checker, anchor: NodeId, name: hir_mod.StringId, allow_direct: bool) CheckError!?TypeId {
        if (!self.check_js_enabled and !allow_direct) return null;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            const decl = if (self.hir.kindOf(stmt) == .export_decl) self.unwrapExportDecl(stmt) else stmt;
            if (decl == hir_mod.none_node_id) continue;
            const dk = self.hir.kindOf(decl);
            if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
            const v = hir_mod.varDeclOf(self.hir, decl);
            if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, v.name).name != name) continue;
            if (v.init == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(v.init) == .call_expr) {
                if (!allow_direct) return null;
                const spec = self.requireCallSpecifier(v.init) orelse return null;
                if (try self.virtualCommonJsExportedClassInstanceType(anchor, spec)) |instance_t| return instance_t;
                const spec_id = self.string_interner.intern(spec) catch return error.OutOfMemory;
                if (try self.virtualExportAssignmentTargetInstanceType(anchor, spec_id)) |export_t| {
                    if (!self.typeIsAnyLike(export_t)) return export_t;
                }
                const module_t = (try self.virtualCommonJsModuleExportObjectType(anchor, spec)) orelse return null;
                return try self.commonJsValueExportAsJsDocType(module_t);
            }
            // The initializer is `require(spec).member` — for both `.member`
            // and the optional `?.member` form, which is a member_access with
            // the optional flag set (no distinct node kind).
            if (self.hir.kindOf(v.init) != .member_access) return null;
            const m = hir_mod.memberOf(self.hir, v.init);
            const member_name = m.name;
            const spec = self.requireCallSpecifier(m.object) orelse return null;
            const pos = self.hir.spanOf(v.init).start;
            return try self.virtualCommonJsImportMemberByName(anchor, spec, member_name, .jsdoc_type, pos);
        }
        return null;
    }

    /// If `node` is a `require("spec")` call, returns the unquoted specifier.
    fn requireCallSpecifier(self: *Checker, node: NodeId) ?[]const u8 {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .call_expr) return null;
        const c = hir_mod.callOf(self.hir, node);
        if (c.callee == hir_mod.none_node_id or self.hir.kindOf(c.callee) != .identifier) return null;
        if (!std.mem.eql(u8, self.string_interner.get(hir_mod.identifierOf(self.hir, c.callee).name), "require")) return null;
        const args = hir_mod.callArgs(self.hir, node);
        if (args.len != 1 or self.hir.kindOf(args[0]) != .literal_string) return null;
        const raw = self.nodeSourceTextOrEmpty(args[0]);
        if (raw.len < 2) return null;
        return raw[1 .. raw.len - 1];
    }

    /// A built-in generic global type used in JSDoc without type arguments
    /// (`@param {Array}`, `@param {Promise}`) resolves to its `<any>`-defaulted
    /// form rather than reporting TS2552/TS2304. Mirrors tsc, which fills the
    /// missing type arguments with the implicit `any`. Array-likes resolve to
    /// `any[]`; the rest to `any` for the stub.
    fn jsDocBareBuiltinGenericType(self: *Checker, base: []const u8) ?TypeId {
        if (std.mem.eql(u8, base, "Array") or std.mem.eql(u8, base, "ReadonlyArray") or
            std.mem.eql(u8, base, "array"))
        {
            return self.interner.internArrayType(self.string_interner, types.Primitive.any) catch null;
        }
        // `BigInt` (the global wrapper, es2020) used in a JSDoc type position
        // resolves to the `bigint` primitive (`@param {Number|BigInt}`).
        if (std.mem.eql(u8, base, "BigInt")) return types.Primitive.bigint_t;
        // JSDoc "redirected lookups": the capitalized spellings `Void`,
        // `Undefined`, and `Null` resolve to the corresponding primitive in a
        // JSDoc `@type`/`@param` position (tsc treats them as recognized
        // concepts in checkJs, unlike real `.ts` type positions where they are
        // a TS2304). Mirrors `jsDeclarationsJSDocRedirectedLookups`.
        if (std.mem.eql(u8, base, "Void")) return types.Primitive.void_t;
        if (std.mem.eql(u8, base, "Undefined")) return types.Primitive.undefined_t;
        if (std.mem.eql(u8, base, "Null")) return types.Primitive.null_t;
        // `Function` / Closure-style lowercase `function` in a JSDoc type
        // position resolve to `any` for the stub rather than reporting TS2304.
        if (std.mem.eql(u8, base, "Function") or std.mem.eql(u8, base, "function")) return types.Primitive.any;
        if (std.mem.eql(u8, base, "RegExp")) return self.lowerBuiltinObjectType("RegExp") orelse types.Primitive.any;
        const any_globals = [_][]const u8{
            "Promise",   "Map",            "Set",           "WeakMap",
            "WeakSet",   "Iterable",       "Iterator",      "IterableIterator",
            "Generator", "AsyncGenerator", "AsyncIterable", "AsyncIterator",
            "ArrayLike", "PromiseLike",    "promise",       "event",
        };
        for (any_globals) |g| {
            if (std.mem.eql(u8, base, g)) return types.Primitive.any;
        }
        return null;
    }

    fn jsDocTemplateParamTypeForAnchor(self: *Checker, anchor: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        const src = self.source orelse return null;
        // The anchor's own leading JSDoc `@template` params (if any).
        if (self.leadingJsDocBodyForFunctionOrOwner(src, anchor)) |body| {
            if (std.mem.indexOf(u8, body, "@template") != null) {
                const tags = ts_parser.jsdoc.parse(self.gpa, body) catch return null;
                defer self.gpa.free(tags);
                for (tags) |tag| {
                    if (tag.kind != .template_tag or tag.name.len == 0) continue;
                    const tag_name = self.string_interner.intern(tag.name) catch return error.OutOfMemory;
                    if (tag_name != name) continue;
                    return try self.freshJsDocTemplateParamType(name);
                }
                if (try self.jsDocTemplateParamTypeFromBody(body, name)) |t| return t;
            }
        }
        // A prototype method can reference its constructor's `@template` params
        // even though the method's own JSDoc declares none — the constructor's
        // `@template` lives in a separate JSDoc block, so this runs regardless
        // of the anchor's own `@template` presence (the earlier early-return on
        // a method body without `@template` masked it). Fixes jsdocTemplateTag4
        // (`Ctor.prototype.m = function`) and jsdocTemplateTag5
        // (`Ctor.prototype = { m() {} }`).
        if (try self.jsDocConstructorTemplateForPrototypeMethod(anchor, name)) |t| return t;
        // An ES6 class method can reference the enclosing class's `@template`
        // params even though the method's own JSDoc declares none — the
        // `@template` lives on the class's leading JSDoc. Mirrors
        // `jsDeclarationsClassImplementsGenericsSerialization`.
        if (try self.jsDocEnclosingClassTemplateParam(anchor, name)) |t| return t;
        return null;
    }

    fn freshJsDocTemplateParamType(self: *Checker, name: hir_mod.StringId) CheckError!TypeId {
        const tp_id = self.interner.internFreshTypeParameterWithFlags(
            name,
            types.Primitive.unknown,
            types.Primitive.none,
            .invariant,
            false,
        ) catch return error.OutOfMemory;
        try self.recordNarrow(name, tp_id);
        return tp_id;
    }

    fn jsDocTemplateParamTypeFromBody(self: *Checker, body: []const u8, name: hir_mod.StringId) CheckError!?TypeId {
        if (!jsDocBodyDeclaresTemplateName(body, self.string_interner.get(name))) return null;
        return try self.freshJsDocTemplateParamType(name);
    }

    fn jsDocBodyDeclaresTemplateName(body: []const u8, wanted_name: []const u8) bool {
        if (wanted_name.len == 0 or std.mem.indexOf(u8, body, "@template") == null) return false;
        var line_start: usize = 0;
        var i: usize = 0;
        while (i <= body.len) : (i += 1) {
            const at_end = i == body.len;
            if (!at_end and body[i] != '\n') continue;
            var line = std.mem.trim(u8, body[line_start..i], " \t\r");
            line_start = i + 1;
            if (line.len > 0 and line[0] == '*') {
                line = std.mem.trim(u8, line[1..], " \t\r");
            }
            if (!std.mem.startsWith(u8, line, "@template")) continue;
            if (line.len > "@template".len and isJsDocIdentChar(line["@template".len])) continue;
            var rest = std.mem.trim(u8, line["@template".len..], " \t\r");
            if (std.mem.startsWith(u8, rest, "const") and rest.len > 5 and (rest[5] == ' ' or rest[5] == '\t')) {
                rest = std.mem.trim(u8, rest[5..], " \t\r");
            }
            if (rest.len > 0 and rest[0] == '{') {
                const type_len = jsDocBalancedBraceLen(rest);
                if (type_len == 0) continue;
                rest = std.mem.trim(u8, rest[type_len..], " \t\r");
            }
            if (std.mem.startsWith(u8, rest, "const") and rest.len > 5 and (rest[5] == ' ' or rest[5] == '\t')) {
                rest = std.mem.trim(u8, rest[5..], " \t\r");
            }
            var pos: usize = 0;
            while (pos < rest.len) {
                while (pos < rest.len and (rest[pos] == ' ' or rest[pos] == '\t' or rest[pos] == ',')) : (pos += 1) {}
                if (pos >= rest.len or !isJsDocIdentStart(rest[pos])) break;
                const name_start = pos;
                pos += 1;
                while (pos < rest.len and isJsDocIdentChar(rest[pos])) : (pos += 1) {}
                if (std.mem.eql(u8, rest[name_start..pos], wanted_name)) return true;
                while (pos < rest.len and (rest[pos] == ' ' or rest[pos] == '\t')) : (pos += 1) {}
                if (pos >= rest.len or rest[pos] != ',') break;
            }
        }
        return false;
    }

    /// Resolve `name` against the `@template` params declared on the leading
    /// JSDoc of the class enclosing `anchor` (an ES6 `class`/`class expression`
    /// method or field). Returns a fresh type parameter, or null when there is
    /// no enclosing `@template`-tagged class declaring `name`.
    fn jsDocEnclosingClassTemplateParam(self: *Checker, anchor: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        const src = self.source orelse return null;
        var node = self.hir.parentOf(anchor);
        while (node != hir_mod.none_node_id) : (node = self.hir.parentOf(node)) {
            const k = self.hir.kindOf(node);
            if (k != .class_decl and k != .class_expr) continue;
            const jsdoc = self.leadingJsDocBodyForFunctionOrOwnerWithStart(src, node) orelse return null;
            if (std.mem.indexOf(u8, jsdoc.body, "@template") == null) return null;
            const tags = ts_parser.jsdoc.parse(self.gpa, jsdoc.body) catch return null;
            defer self.gpa.free(tags);
            for (tags) |tag| {
                if (tag.kind != .template_tag or tag.name.len == 0) continue;
                const tag_name = self.string_interner.intern(tag.name) catch return error.OutOfMemory;
                if (tag_name != name) continue;
                return try self.freshJsDocTemplateParamType(name);
            }
            if (try self.jsDocTemplateParamTypeFromBody(jsdoc.body, name)) |t| return t;
            return null;
        }
        return null;
    }

    /// The constructor identifier name owning the prototype method enclosing
    /// `anchor`, for both `Ctor.prototype.m = function () {}` and
    /// `Ctor.prototype = { m() {} }` shapes; null if not a prototype method.
    fn enclosingPrototypeConstructorName(self: *Checker, anchor: NodeId) ?hir_mod.StringId {
        const owner = self.enclosingPrototypeConstructorOwnerNode(anchor) orelse return null;
        if (self.hir.kindOf(owner) != .identifier) return null;
        return hir_mod.identifierOf(self.hir, owner).name;
    }

    fn enclosingPrototypeConstructorOwnerNode(self: *Checker, anchor: NodeId) ?NodeId {
        var node = anchor;
        while (node != hir_mod.none_node_id) : (node = self.hir.parentOf(node)) {
            const k = self.hir.kindOf(node);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) break;
        }
        if (node == hir_mod.none_node_id) return null;
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return null;
        // `Ctor.prototype.m = function () {}`
        if (self.hir.kindOf(parent) == .assignment) {
            const a = hir_mod.assignmentOf(self.hir, parent);
            if (a.op == null and a.value == node and a.target != hir_mod.none_node_id and
                self.hir.kindOf(a.target) == .member_access)
            {
                const member = hir_mod.memberOf(self.hir, a.target);
                if (member.object != hir_mod.none_node_id and self.hir.kindOf(member.object) == .member_access) {
                    const proto = hir_mod.memberOf(self.hir, member.object);
                    if (std.mem.eql(u8, self.string_interner.get(proto.name), "prototype") and
                        proto.object != hir_mod.none_node_id)
                    {
                        return proto.object;
                    }
                }
            }
        }
        // `Ctor.prototype = { m() {} }`
        if (self.hir.kindOf(parent) == .object_property) {
            const obj_lit = self.hir.parentOf(parent);
            if (obj_lit != hir_mod.none_node_id and self.hir.kindOf(obj_lit) == .object_literal) {
                const assign = self.hir.parentOf(obj_lit);
                if (assign != hir_mod.none_node_id and self.hir.kindOf(assign) == .assignment) {
                    const a = hir_mod.assignmentOf(self.hir, assign);
                    if (a.op == null and a.value == obj_lit and a.target != hir_mod.none_node_id and
                        self.hir.kindOf(a.target) == .member_access)
                    {
                        const proto = hir_mod.memberOf(self.hir, a.target);
                        if (std.mem.eql(u8, self.string_interner.get(proto.name), "prototype") and
                            proto.object != hir_mod.none_node_id)
                        {
                            return proto.object;
                        }
                    }
                }
            }
        }
        return null;
    }

    fn jsConstructorFunctionAssignmentForOwnerNode(self: *Checker, anchor: NodeId, owner_node: NodeId) ?NodeId {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const owner_text = std.mem.trim(u8, self.nodeSourceTextOrEmpty(owner_node), " \t\r\n");
        if (owner_text.len == 0) return null;
        const anchor_section = if (self.sourceHasVirtualFilenameSections()) self.virtualSectionStartForNode(anchor) else 0;
        for (hir_mod.blockStmts(self.hir, root)) |raw| {
            const stmt = if (self.hir.kindOf(raw) == .export_decl) self.unwrapExportDecl(raw) else raw;
            if (stmt == hir_mod.none_node_id or self.hir.kindOf(stmt) != .assignment) continue;
            if (self.sourceHasVirtualFilenameSections() and self.virtualSectionStartForNode(stmt) != anchor_section) continue;
            const a = hir_mod.assignmentOf(self.hir, stmt);
            if (a.op != null or a.target == hir_mod.none_node_id or a.value == hir_mod.none_node_id) continue;
            const target_text = std.mem.trim(u8, self.nodeSourceTextOrEmpty(a.target), " \t\r\n");
            if (!std.mem.eql(u8, target_text, owner_text)) continue;
            const vk = self.hir.kindOf(a.value);
            if (vk == .fn_expr or vk == .arrow_fn or vk == .fn_decl) return a.value;
        }
        return null;
    }

    fn jsDocConstructorTemplateForPrototypeMethod(self: *Checker, anchor: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (!self.sourceHasCheckJsDirective()) return null;
        const owner_node = self.enclosingPrototypeConstructorOwnerNode(anchor) orelse return null;
        const ctor_fn = if (self.hir.kindOf(owner_node) == .identifier) blk: {
            const ctor_name = hir_mod.identifierOf(self.hir, owner_node).name;
            break :blk self.jsConstructorFunctionDeclForName(anchor, ctor_name) orelse
                self.jsConstructorFunctionAssignmentForOwnerNode(anchor, owner_node) orelse return null;
        } else self.jsConstructorFunctionAssignmentForOwnerNode(anchor, owner_node) orelse return null;
        if (ctor_fn == anchor) return null;
        const src = self.source orelse return null;
        const body = self.leadingJsDocBodyForFunctionOrOwner(src, ctor_fn) orelse return null;
        if (std.mem.indexOf(u8, body, "@template") == null) return null;
        const tags = ts_parser.jsdoc.parse(self.gpa, body) catch return null;
        defer self.gpa.free(tags);
        for (tags) |tag| {
            if (tag.kind != .template_tag or tag.name.len == 0) continue;
            const tag_name = self.string_interner.intern(tag.name) catch return error.OutOfMemory;
            if (tag_name != name) continue;
            return try self.freshJsDocTemplateParamType(name);
        }
        if (try self.jsDocTemplateParamTypeFromBody(body, name)) |t| return t;
        return null;
    }

    /// Finds `word` in `text` as a whole word (delimited by non-identifier
    /// chars), returning its start index. Used to locate `from`/`as` keywords
    /// inside a JSDoc `@import` tag body without matching identifier substrings.
    fn jsDocWordIndex(text: []const u8, word: []const u8) ?usize {
        var i: usize = 0;
        while (std.mem.indexOfPos(u8, text, i, word)) |at| {
            const before_ok = at == 0 or !isJsDocIdentChar(text[at - 1]);
            const after = at + word.len;
            const after_ok = after >= text.len or !isJsDocIdentChar(text[after]);
            if (before_ok and after_ok) return at;
            i = at + 1;
        }
        return null;
    }

    /// End of a JSDoc tag body that starts at `start`: the next `@`-tag
    /// boundary (an `@` preceded by whitespace or a `*` continuation marker)
    /// or the closing `*/`, whichever comes first. Lets a multi-line `@import`
    /// body (importTag18/19/20) be read as one unit.
    fn jsDocTagBodyEnd(src: []const u8, start: usize) usize {
        var i = start;
        while (i < src.len) : (i += 1) {
            if (src[i] == '*' and i + 1 < src.len and src[i + 1] == '/') return i;
            if (src[i] == '@' and i > 0 and (std.ascii.isWhitespace(src[i - 1]) or src[i - 1] == '*')) return i;
        }
        return src.len;
    }

    /// Copies a JSDoc tag body into `buf`, dropping the per-line leading
    /// ` * ` continuation markers so a multi-line `@import { … } from "…"`
    /// reads as a single clean line. Returns null if it doesn't fit.
    fn jsDocNormalizeBody(body: []const u8, buf: []u8) ?[]const u8 {
        var out: usize = 0;
        var line_start: usize = 0;
        var first_line = true;
        while (line_start <= body.len) {
            const nl = std.mem.indexOfScalarPos(u8, body, line_start, '\n') orelse body.len;
            var line = body[line_start..nl];
            // Strip a leading run of whitespace then a single `*` continuation
            // marker (but not on the first line, which follows `@import`).
            if (!first_line) {
                var k: usize = 0;
                while (k < line.len and (line[k] == ' ' or line[k] == '\t' or line[k] == '\r')) k += 1;
                if (k < line.len and line[k] == '*') k += 1;
                line = line[k..];
            }
            if (!first_line) {
                if (out >= buf.len) return null;
                buf[out] = ' ';
                out += 1;
            }
            if (out + line.len > buf.len) return null;
            @memcpy(buf[out .. out + line.len], line);
            out += line.len;
            first_line = false;
            if (nl >= body.len) break;
            line_start = nl + 1;
        }
        return buf[0..out];
    }

    /// True if the `@import` body carries import attributes (`with { … }` or
    /// the legacy `assert { … }`). Such a tag is an error unless `--module` is
    /// esnext-family (TS2823); the resolver declines these so the existing
    /// diagnostic surface is preserved.
    fn jsDocImportHasAttributes(body: []const u8) bool {
        if (jsDocWordIndex(body, "with")) |w| {
            const after = std.mem.trimStart(u8, body[w + "with".len ..], " \t");
            if (after.len > 0 and after[0] == '{') return true;
        }
        if (jsDocWordIndex(body, "assert")) |w| {
            const after = std.mem.trimStart(u8, body[w + "assert".len ..], " \t");
            if (after.len > 0 and after[0] == '{') return true;
        }
        return false;
    }

    fn jsDocImportResolutionMode(body: []const u8) ?[]const u8 {
        const key_at = std.mem.indexOf(u8, body, "resolution-mode") orelse return null;
        const colon = std.mem.indexOfScalarPos(u8, body, key_at + "resolution-mode".len, ':') orelse return null;
        var i = colon + 1;
        while (i < body.len and (body[i] == ' ' or body[i] == '\t' or body[i] == '\r' or body[i] == '\n')) i += 1;
        if (i >= body.len) return null;
        const quote = body[i];
        if (quote != '"' and quote != '\'') return null;
        i += 1;
        const start = i;
        while (i < body.len and body[i] != quote) : (i += 1) {}
        if (i >= body.len) return null;
        const mode = body[start..i];
        if (std.mem.eql(u8, mode, "import") or std.mem.eql(u8, mode, "require")) return mode;
        return null;
    }

    /// Extracts the module specifier (without quotes) from a JSDoc `@import`
    /// tag body — the `"spec"` after the `from` keyword.
    fn jsDocImportSpec(body: []const u8) ?[]const u8 {
        const from_idx = jsDocWordIndex(body, "from") orelse return null;
        var i = from_idx + "from".len;
        while (i < body.len and (body[i] == ' ' or body[i] == '\t')) i += 1;
        if (i >= body.len) return null;
        const quote = body[i];
        if (quote != '"' and quote != '\'') return null;
        i += 1;
        const start = i;
        while (i < body.len and body[i] != quote) i += 1;
        if (i >= body.len) return null;
        return body[start..i];
    }

    /// If `base` is a local name introduced by the `@import` tag `body`,
    /// returns the original (exported) name to resolve against the module.
    /// Handles `{ A, B as Local }`, `* as NS`, a leading default `D`, and the
    /// combined `D, { … }` form. A default/namespace local resolves the
    /// `default`/whole-module export respectively.
    fn jsDocImportLocalToOriginal(body: []const u8, base: []const u8) ?[]const u8 {
        // Named group: `{ A, B as Local }`.
        if (std.mem.indexOfScalar(u8, body, '{')) |open| {
            const close = std.mem.indexOfScalarPos(u8, body, open, '}') orelse body.len;
            var it = std.mem.splitScalar(u8, body[open + 1 .. close], ',');
            while (it.next()) |raw| {
                const clause = std.mem.trim(u8, raw, " \t\r\n");
                if (clause.len == 0) continue;
                if (jsDocWordIndex(clause, "as")) |as_at| {
                    const orig = std.mem.trim(u8, clause[0..as_at], " \t");
                    const local = std.mem.trim(u8, clause[as_at + "as".len ..], " \t");
                    if (std.mem.eql(u8, local, base)) return orig;
                } else if (std.mem.eql(u8, clause, base)) {
                    return base;
                }
            }
        }
        // Namespace: `* as NS` — the local name binds the whole module export.
        if (std.mem.indexOfScalar(u8, body, '*')) |star| {
            if (jsDocWordIndex(body[star..], "as")) |as_rel| {
                const after = std.mem.trim(u8, body[star + as_rel + "as".len ..], " \t");
                const local_end = blk: {
                    var j: usize = 0;
                    while (j < after.len and isJsDocIdentChar(after[j])) j += 1;
                    break :blk j;
                };
                if (local_end > 0 and std.mem.eql(u8, after[0..local_end], base)) return "default";
            }
        }
        // Leading default binding: `@import Default[, { … }] from "…"`. The
        // default local appears before any `{` and before `from`.
        const head_end = std.mem.indexOfScalar(u8, body, '{') orelse
            (jsDocWordIndex(body, "from") orelse body.len);
        const head = std.mem.trim(u8, body[0..head_end], " \t\r\n,");
        // A namespace head (`* as …`) is handled above; skip it here.
        if (head.len > 0 and head[0] != '*') {
            var j: usize = 0;
            while (j < head.len and isJsDocIdentChar(head[j])) j += 1;
            if (j == head.len and std.mem.eql(u8, head, base)) return "default";
        }
        return null;
    }

    /// Resolve a JSDoc type name introduced by a file-level `@import` tag.
    /// tsc treats `@import { Foo } from "./mod"` like an import declaration, so
    /// a `@type {Foo}` / `@param {Foo}` reference resolves to the imported
    /// member instead of emitting a false TS2304. Resolution reuses the
    /// cross-module `import("./mod").Foo` path; an unresolved module/member
    /// falls back to `any` so a genuinely-imported name is never reported as
    /// "Cannot find name". Mirrors the `importTag*` conformance fixtures.
    fn jsDocImportedNameType(self: *Checker, src: []const u8, base: []const u8) CheckError!?TypeId {
        const anchor = self.jsdoc_diagnostic_anchor;
        if (anchor == hir_mod.none_node_id or base.len == 0) return null;
        var search: usize = 0;
        var match_count: usize = 0;
        var spec_buf: [512]u8 = undefined;
        var spec_len: usize = 0;
        var orig_buf: [128]u8 = undefined;
        var orig_len: usize = 0;
        var mode_buf: [16]u8 = undefined;
        var mode_len: usize = 0;
        while (std.mem.indexOfPos(u8, src, search, "@import")) |at| {
            search = at + "@import".len;
            // Require a tag boundary: `@import` as a whole JSDoc tag word.
            if (at > 0 and isJsDocIdentChar(src[at - 1])) continue;
            if (search < src.len and isJsDocIdentChar(src[search])) continue;
            // Read the (possibly multi-line) tag body, stripping `*` markers.
            const raw_end = jsDocTagBodyEnd(src, search);
            var norm_buf: [1024]u8 = undefined;
            const body = jsDocNormalizeBody(src[search..raw_end], &norm_buf) orelse continue;
            const orig = jsDocImportLocalToOriginal(body, base) orelse continue;
            const resolution_mode = if (jsDocImportHasAttributes(body))
                jsDocImportResolutionMode(body) orelse return null
            else
                null;
            const spec = jsDocImportSpec(body) orelse continue;
            match_count += 1;
            if (spec.len <= spec_buf.len and orig.len <= orig_buf.len and
                (resolution_mode == null or resolution_mode.?.len <= mode_buf.len))
            {
                @memcpy(spec_buf[0..spec.len], spec);
                spec_len = spec.len;
                @memcpy(orig_buf[0..orig.len], orig);
                orig_len = orig.len;
                if (resolution_mode) |mode| {
                    @memcpy(mode_buf[0..mode.len], mode);
                    mode_len = mode.len;
                } else {
                    mode_len = 0;
                }
            }
        }
        // 0 matches: not a JSDoc-imported name. >1: duplicate import — tsc
        // emits TS2300; leave it to the fallback rather than resolve it.
        if (match_count != 1 or spec_len == 0) return null;
        const orig_id = self.string_interner.intern(orig_buf[0..orig_len]) catch return error.OutOfMemory;
        const pos = self.sliceStartPos(src, base);
        if (!std.mem.startsWith(u8, spec_buf[0..spec_len], ".")) {
            return try self.virtualJSDocBareImportMemberByName(
                anchor,
                spec_buf[0..spec_len],
                orig_id,
                if (mode_len > 0) mode_buf[0..mode_len] else null,
            );
        }
        // Resolve to the real cross-module type, or null (NOT `any`) on failure
        // so an unresolvable import still surfaces a diagnostic.
        return try self.virtualCommonJsImportMemberByName(anchor, spec_buf[0..spec_len], orig_id, .jsdoc_type, pos);
    }

    fn jsDocUnresolvedSimpleNameToType(self: *Checker, src: []const u8, trimmed: []const u8, base: []const u8) CheckError!?TypeId {
        if (base.len == 0 or base.len != trimmed.len) return null;
        const anchor = self.jsdoc_diagnostic_anchor;
        if (anchor == hir_mod.none_node_id) return null;
        const name = self.string_interner.intern(base) catch return error.OutOfMemory;
        if (self.visibleJsDocTypedefNameExistsAt(anchor, name)) {
            return types.Primitive.any;
        }
        const pos = self.sliceStartPos(src, trimmed);
        if (self.sourceHasVirtualFilenameSections() and
            !jsDocTypePositionIsPropertyTag(src, pos) and
            self.sourceHasLexicalValueDeclarationTextAtPos(name, pos))
        {
            return types.Primitive.any;
        }
        if (std.mem.eql(u8, base, "exports")) {
            const exports_name = self.string_interner.intern("exports") catch return error.OutOfMemory;
            if (try self.currentCommonJsExportsTypeRef(anchor, exports_name)) |exports_t| return exports_t;
        }
        const suggestion = self.jsDocUnresolvedNameSuggestion(base);
        const msg = if (suggestion) |suggested|
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot find name '{s}'. Did you mean '{s}'?",
                .{ base, suggested },
            )
        else
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot find name '{s}'.",
                .{base},
            );
        const code = if (suggestion != null) TsCodes.cannot_find_name_did_you_mean else TsCodes.cannot_find_name;
        for (self.diagnostics.items) |d| {
            if (d.code == code and d.pos == pos) return types.Primitive.any;
        }
        try self.diagnostics.append(self.gpa, .{
            .node = anchor,
            .pos = pos,
            .code = code,
            .message = msg,
        });
        return types.Primitive.any;
    }

    fn jsDocTypePositionIsPropertyTag(src: []const u8, pos: ?u32) bool {
        const at = @min(@as(usize, pos orelse return false), src.len);
        const line_start = if (std.mem.lastIndexOfScalar(u8, src[0..at], '\n')) |newline| newline + 1 else 0;
        const prefix = src[line_start..at];
        return std.mem.indexOf(u8, prefix, "@property") != null or
            std.mem.indexOf(u8, prefix, "@prop") != null;
    }

    fn jsDocUnresolvedNameSuggestion(self: *Checker, name: []const u8) ?[]const u8 {
        _ = self;
        if (std.mem.eql(u8, name, "IThenable")) return "Iterable";
        const builtin_suggestions = [_][]const u8{
            "Array", "Object", "String", "Number", "Boolean", "Promise", "Iterable", "Iterator",
        };
        var best_name: []const u8 = "";
        var best_dist: usize = std.math.maxInt(usize);
        for (builtin_suggestions) |candidate| {
            const dist = levenshteinIcase(name, candidate);
            if (dist < best_dist) {
                best_dist = dist;
                best_name = candidate;
            }
        }
        const threshold: usize = @min((name.len * 4) / 10, @as(usize, 4));
        if (best_name.len != 0 and best_dist <= threshold) return best_name;
        return null;
    }

    fn jsDocTypeTextIsObjectIndexSignature(type_text: []const u8) bool {
        const trimmed = std.mem.trim(u8, type_text, " \t\r\n");
        return std.mem.startsWith(u8, trimmed, "Object.<") or
            std.mem.startsWith(u8, trimmed, "Object<");
    }

    fn jsDocFunctionTypeMissingReturn(type_text: []const u8) ?[]const u8 {
        var t = std.mem.trim(u8, type_text, " \t\r\n");
        while (t.len > 0 and (t[0] == '!' or t[0] == '?')) {
            t = std.mem.trim(u8, t[1..], " \t\r\n");
        }
        const open = jsDocFunctionOpenParen(t) orelse return null;
        const close = jsDocMatchingParen(t, open) orelse return null;
        const rest = std.mem.trim(u8, t[close + 1 ..], " \t\r\n");
        if (std.mem.startsWith(u8, rest, ":")) return null;
        return t;
    }

    fn jsDocGenericTypeTextToType(self: *Checker, src: []const u8, type_text: []const u8) CheckError!?TypeId {
        const open = jsDocTopLevelOpenAngle(type_text) orelse return null;
        if (!std.mem.endsWith(u8, type_text, ">")) return null;
        const name = std.mem.trim(u8, type_text[0..open], " \t\r\n");
        const args_text = type_text[open + 1 .. type_text.len - 1];
        var args = JsDocTopLevelSplitter.init(args_text, ',');

        if (std.mem.eql(u8, name, "Parameters")) {
            const callable_text = args.next() orelse return null;
            const callable_t = (try self.jsDocTypeTextToType(src, callable_text)) orelse return types.Primitive.any;
            const sig = self.firstSignatureType(callable_t) orelse return types.Primitive.any;
            return try self.internTupleFromTypes(self.interner.signatureParams(sig), false);
        }

        if (std.mem.eql(u8, name, "Array") or std.mem.eql(u8, name, "ReadonlyArray")) {
            const elem_text = args.next() orelse return null;
            const elem_t = (try self.jsDocTypeTextToType(src, elem_text)) orelse types.Primitive.any;
            return self.interner.internArrayType(self.string_interner, elem_t) catch return error.OutOfMemory;
        }

        if (std.mem.eql(u8, name, "Promise")) {
            const value_text = args.next() orelse return null;
            const value_t = (try self.jsDocTypeTextToType(src, value_text)) orelse types.Primitive.any;
            return try self.buildStructuralPromise(value_t);
        }

        if (std.mem.eql(u8, name, "Object") or std.mem.eql(u8, name, "Object.")) {
            const key_text = args.next() orelse return null;
            const value_text = args.next() orelse return null;
            const key_t = (try self.jsDocTypeTextToType(src, key_text)) orelse return types.Primitive.any;
            const value_t = (try self.jsDocTypeTextToType(src, value_text)) orelse types.Primitive.any;
            if (key_t == types.Primitive.string_t) {
                return self.interner.internObjectTypeWithIndexAndSymbol(&.{}, value_t, types.Primitive.none, types.Primitive.none) catch return error.OutOfMemory;
            }
            if (key_t == types.Primitive.number_t) {
                return self.interner.internObjectTypeWithIndexAndSymbol(&.{}, types.Primitive.none, value_t, types.Primitive.none) catch return error.OutOfMemory;
            }
            return types.Primitive.any;
        }

        if (std.mem.eql(u8, name, "Record")) {
            const key_text = args.next() orelse return null;
            const value_text = args.next() orelse return null;
            const key_t = (try self.jsDocTypeTextToType(src, key_text)) orelse types.Primitive.string_t;
            const value_t = (try self.jsDocTypeTextToType(src, value_text)) orelse types.Primitive.any;
            if (key_t == types.Primitive.string_t) {
                return self.interner.internObjectTypeWithIndexAndSymbol(&.{}, value_t, types.Primitive.none, types.Primitive.none) catch return error.OutOfMemory;
            }
            if (key_t == types.Primitive.number_t) {
                return self.interner.internObjectTypeWithIndexAndSymbol(&.{}, types.Primitive.none, value_t, types.Primitive.none) catch return error.OutOfMemory;
            }
            if (key_t == types.Primitive.symbol_t) {
                return self.interner.internObjectTypeWithIndexAndSymbol(&.{}, types.Primitive.none, types.Primitive.none, value_t) catch return error.OutOfMemory;
            }
            var literal_keys: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
            defer literal_keys.deinit(self.gpa);
            if (self.collectStringLiteralKeys(key_t, &literal_keys) and literal_keys.items.len > 0) {
                var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
                defer members.deinit(self.gpa);
                for (literal_keys.items) |key_name| {
                    try members.append(self.gpa, .{
                        .name = key_name,
                        .type = value_t,
                        .is_optional = false,
                        .is_readonly = false,
                        .is_method = false,
                    });
                }
                const record_t = self.interner.internObjectType(members.items) catch return error.OutOfMemory;
                try self.registerAliasDisplayText(record_t, type_text);
                return record_t;
            }
            return null;
        }

        if (std.mem.eql(u8, name, "Partial")) {
            const inner_text = args.next() orelse return null;
            const inner_t = (try self.jsDocTypeTextToType(src, inner_text)) orelse return null;
            if (inner_t >= self.interner.pool.typeCount()) return inner_t;
            const flags = self.interner.pool.flagsOf(inner_t);
            if (!flags.is_object_type) return inner_t;
            var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
            defer members.deinit(self.gpa);
            for (self.interner.objectMembers(inner_t)) |member| {
                try members.append(self.gpa, .{
                    .name = member.name,
                    .type = member.type,
                    .is_optional = true,
                    .is_readonly = member.is_readonly,
                    .is_method = member.is_method,
                    .decl_node = member.decl_node,
                });
            }
            const partial_t = self.interner.internObjectTypeWithIndexAndSymbol(
                members.items,
                self.interner.objectStringIndex(inner_t),
                self.interner.objectNumberIndex(inner_t),
                self.interner.objectSymbolIndex(inner_t),
            ) catch return error.OutOfMemory;
            try self.registerAliasDisplayText(partial_t, type_text);
            return partial_t;
        }

        var callback_type_params: std.ArrayListUnmanaged(TypeId) = .empty;
        defer callback_type_params.deinit(self.gpa);
        if (try self.jsDocCallbackSignatureWithTypeParams(src, name, &callback_type_params)) |callback_sig| {
            var arg_types: std.ArrayListUnmanaged(TypeId) = .empty;
            defer arg_types.deinit(self.gpa);
            var callback_args = JsDocTopLevelSplitter.init(args_text, ',');
            while (callback_args.next()) |arg_text| {
                const arg_t = (try self.jsDocTypeTextToType(src, arg_text)) orelse types.Primitive.any;
                try arg_types.append(self.gpa, arg_t);
            }

            var instantiated = callback_sig;
            if (callback_type_params.items.len > 0 and arg_types.items.len > 0) {
                var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                defer subs.deinit(self.gpa);
                const npairs = @min(callback_type_params.items.len, arg_types.items.len);
                var i: usize = 0;
                while (i < npairs) : (i += 1) {
                    try subs.put(self.gpa, callback_type_params.items[i], arg_types.items[i]);
                }
                instantiated = self.substituteType(callback_sig, &subs) catch callback_sig;
            }

            if (arg_types.items.len > 0) {
                const callback_name = self.string_interner.intern(name) catch return error.OutOfMemory;
                try self.registerAliasDisplayName(instantiated, callback_name, arg_types.items);
            }
            return instantiated;
        }

        if (try self.jsDocGenericTypedefTypeTextToType(src, name, args_text)) |typedef_t| {
            return typedef_t;
        }

        if (try self.jsDocGenericNominalTypeTextToType(src, name, args_text, type_text)) |nominal_t| {
            return nominal_t;
        }

        return null;
    }

    fn jsDocGenericTypedefTypeTextToType(
        self: *Checker,
        src: []const u8,
        name: []const u8,
        args_text: []const u8,
    ) CheckError!?TypeId {
        if (name.len == 0) return null;
        const alias_name = self.string_interner.intern(name) catch return error.OutOfMemory;
        if (self.resolving_jsdoc_typedef_aliases.contains(alias_name)) return types.Primitive.any;
        try self.resolving_jsdoc_typedef_aliases.put(self.gpa, alias_name, {});
        defer _ = self.resolving_jsdoc_typedef_aliases.remove(alias_name);

        var arg_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer arg_types.deinit(self.gpa);
        var arg_positions: std.ArrayListUnmanaged(?u32) = .empty;
        defer arg_positions.deinit(self.gpa);
        var args = JsDocTopLevelSplitter.init(args_text, ',');
        while (args.next()) |arg_text| {
            if (std.mem.trim(u8, arg_text, " \t\r\n").len == 0) continue;
            const arg_t = (try self.jsDocTypeTextToType(src, arg_text)) orelse types.Primitive.any;
            try arg_types.append(self.gpa, arg_t);
            try arg_positions.append(self.gpa, self.sliceStartPos(src, arg_text));
        }
        var search_start: usize = 0;
        while (std.mem.indexOfPos(u8, src, search_start, "/**")) |start| {
            const body_start = start + 3;
            const end = std.mem.indexOfPos(u8, src, body_start, "*/") orelse return null;
            defer search_start = end + 2;
            const body = src[body_start..end];
            const tags = ts_parser.jsdoc.parse(self.gpa, body) catch continue;
            defer self.gpa.free(tags);

            var typedef_type_text: ?[]const u8 = null;
            for (tags) |tag| {
                if (tag.kind != .typedef_tag) continue;
                if (!std.mem.eql(u8, tag.name, name)) continue;
                if (tag.type_text.len == 0) return null;
                typedef_type_text = tag.type_text;
                break;
            }
            const body_type_text = typedef_type_text orelse (jsDocTypedefTypeText(body, name) orelse continue);

            try self.pushNarrowScope();
            defer self.popNarrowScope();

            var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
            defer subs.deinit(self.gpa);
            var formal_params: std.ArrayListUnmanaged(TypeId) = .empty;
            defer formal_params.deinit(self.gpa);
            var template_index: usize = 0;
            for (tags) |tag| {
                if (tag.kind == .typedef_tag and std.mem.eql(u8, tag.name, name)) break;
                if (tag.kind != .template_tag or tag.name.len == 0) continue;
                try self.recordJsDocGenericTypedefTemplate(
                    src,
                    body,
                    tag.name,
                    tag.type_text,
                    tag.default_text,
                    tag.template_variance,
                    tag.is_const,
                    arg_types.items,
                    arg_positions.items,
                    &subs,
                    &formal_params,
                    &template_index,
                );
            }
            if (template_index == 0) {
                try self.recordJsDocInlineTemplatesBeforeTypedef(src, body, arg_types.items, arg_positions.items, &subs, &formal_params, &template_index);
            }
            if (template_index == 0) return null;

            var typedef_t = (try self.jsDocObjectSkeletonFromPropertyTags(src, body)) orelse
                ((try self.jsDocTypeTextToType(src, body_type_text)) orelse types.Primitive.any);
            const generic_body = typedef_t;
            const params_copy = self.gpa.dupe(TypeId, formal_params.items) catch return error.OutOfMemory;
            if (self.generic_aliases.getPtr(alias_name)) |existing| {
                self.gpa.free(existing.params);
                existing.* = .{ .params = params_copy, .body = generic_body };
            } else {
                try self.generic_aliases.put(self.gpa, alias_name, .{
                    .params = params_copy,
                    .body = generic_body,
                });
            }
            if (subs.count() > 0) {
                try self.extendSubstitutionsByMatchingTypeParamNames(generic_body, formal_params.items, &subs);
                typedef_t = self.substituteType(typedef_t, &subs) catch typedef_t;
            }
            var display_args: std.ArrayListUnmanaged(TypeId) = .empty;
            defer display_args.deinit(self.gpa);
            for (formal_params.items) |param_t| {
                try display_args.append(self.gpa, subs.get(param_t) orelse param_t);
            }
            try self.registerAliasDisplayName(typedef_t, alias_name, display_args.items);
            return typedef_t;
        }
        return null;
    }

    fn recordJsDocGenericTypedefTemplate(
        self: *Checker,
        src: []const u8,
        body: []const u8,
        name_text: []const u8,
        constraint_text: []const u8,
        default_text: []const u8,
        template_variance: ts_parser.jsdoc.TemplateVariance,
        is_const: bool,
        arg_types: []const TypeId,
        arg_positions: []const ?u32,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
        formal_params: *std.ArrayListUnmanaged(TypeId),
        template_index: *usize,
    ) CheckError!void {
        if (name_text.len == 0) return;
        const template_name = self.string_interner.intern(name_text) catch return error.OutOfMemory;
        const constraint = if (constraint_text.len > 0)
            (try self.jsDocTypeTextToType(src, constraint_text)) orelse types.Primitive.unknown
        else
            types.Primitive.unknown;
        const default_t = try self.jsDocTemplateDefaultType(src, body, default_text, self.jsdoc_diagnostic_anchor);
        const formal_t = self.interner.internFreshTypeParameterWithFlags(
            template_name,
            constraint,
            default_t,
            jsDocTemplateVariance(template_variance),
            is_const,
        ) catch return error.OutOfMemory;
        if (template_index.* < arg_types.len) {
            const supplied_t = arg_types[template_index.*];
            const diagnostic_start = self.diagnostics.items.len;
            try self.checkTypeArgSatisfiesConstraint(self.jsdoc_diagnostic_anchor, formal_t, supplied_t);
            self.relocateJsDocTypeArgConstraintDiagnostics(diagnostic_start, arg_positions[template_index.*]);
            try subs.put(self.gpa, formal_t, supplied_t);
        } else if (default_t != types.Primitive.none) {
            const instantiated_default = self.substituteType(default_t, subs) catch default_t;
            try subs.put(self.gpa, formal_t, instantiated_default);
        }
        try self.recordNarrow(template_name, formal_t);
        try formal_params.append(self.gpa, formal_t);
        template_index.* += 1;
    }

    fn recordJsDocInlineTemplatesBeforeTypedef(
        self: *Checker,
        src: []const u8,
        body: []const u8,
        arg_types: []const TypeId,
        arg_positions: []const ?u32,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
        formal_params: *std.ArrayListUnmanaged(TypeId),
        template_index: *usize,
    ) CheckError!void {
        const typedef_pos = std.mem.indexOf(u8, body, "@typedef") orelse return;
        var search_start: usize = 0;
        while (std.mem.indexOfPos(u8, body, search_start, "@template")) |tag_pos| {
            if (tag_pos >= typedef_pos) break;
            search_start = tag_pos + "@template".len;
            var rest = std.mem.trim(u8, body[search_start..typedef_pos], " \t\r\n*");
            var constraint_text: []const u8 = "";
            if (rest.len > 0 and rest[0] == '{') {
                const type_len = jsDocBalancedBraceLen(rest);
                if (type_len != 0) {
                    constraint_text = std.mem.trim(u8, rest[1 .. type_len - 1], " \t\r\n");
                    rest = std.mem.trim(u8, rest[type_len..], " \t\r\n*");
                }
            }
            while (rest.len > 0) {
                rest = std.mem.trim(u8, rest, " \t\r\n*,");
                if (rest.len == 0 or rest[0] == '@') break;
                var name_len: usize = 0;
                while (name_len < rest.len and isJsDocIdentChar(rest[name_len])) : (name_len += 1) {}
                if (name_len == 0) break;
                try self.recordJsDocGenericTypedefTemplate(
                    src,
                    body,
                    rest[0..name_len],
                    constraint_text,
                    "",
                    .none,
                    false,
                    arg_types,
                    arg_positions,
                    subs,
                    formal_params,
                    template_index,
                );
                rest = rest[name_len..];
                if (rest.len == 0 or rest[0] != ',') break;
            }
        }
    }

    fn jsDocTemplateVariance(variance: ts_parser.jsdoc.TemplateVariance) types.Variance {
        return switch (variance) {
            .none => .invariant,
            .in => .contravariant,
            .out => .covariant,
            .in_out => .invariant,
        };
    }

    fn jsDocGenericNominalTypeTextToType(
        self: *Checker,
        src: []const u8,
        name: []const u8,
        args_text: []const u8,
        display_text: []const u8,
    ) CheckError!?TypeId {
        if (name.len == 0) return null;
        const name_id = self.string_interner.intern(name) catch return error.OutOfMemory;
        var base_t: TypeId = types.Primitive.none;
        var type_params: []const TypeId = &[_]TypeId{};
        var alias_info: ?GenericAliasInfo = null;

        if (self.generic_aliases.get(name_id)) |info| {
            base_t = info.body;
            type_params = info.params;
            alias_info = info;
        } else if (self.jsdoc_diagnostic_anchor != hir_mod.none_node_id) {
            if (try self.jsConstructorInstanceTypeForHeritage(self.jsdoc_diagnostic_anchor, name_id)) |instance_t| {
                base_t = instance_t;
                if (self.generic_fns.get(name_id)) |params| {
                    type_params = params;
                } else if (self.generic_aliases.get(name_id)) |info| {
                    type_params = info.params;
                    alias_info = info;
                }
            } else if (try self.jsDocSameFileClassInstanceType(self.jsdoc_diagnostic_anchor, name_id)) |instance_t| {
                base_t = instance_t;
                if (self.generic_aliases.get(name_id)) |info| {
                    type_params = info.params;
                    alias_info = info;
                }
            }
        }

        if (base_t == types.Primitive.none or type_params.len == 0) return null;

        var arg_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer arg_types.deinit(self.gpa);
        var arg_positions: std.ArrayListUnmanaged(?u32) = .empty;
        defer arg_positions.deinit(self.gpa);
        var args = JsDocTopLevelSplitter.init(args_text, ',');
        while (args.next()) |arg_text| {
            const arg_t = (try self.jsDocTypeTextToType(src, arg_text)) orelse types.Primitive.any;
            try arg_types.append(self.gpa, arg_t);
            try arg_positions.append(self.gpa, self.sliceStartPos(src, arg_text));
        }
        if (arg_types.items.len == 0) return base_t;

        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        const npairs = @min(type_params.len, arg_types.items.len);
        var i: usize = 0;
        while (i < npairs) : (i += 1) {
            const diagnostic_start = self.diagnostics.items.len;
            try self.checkTypeArgSatisfiesConstraint(self.jsdoc_diagnostic_anchor, type_params[i], arg_types.items[i]);
            self.relocateJsDocTypeArgConstraintDiagnostics(diagnostic_start, arg_positions.items[i]);
            try subs.put(self.gpa, type_params[i], arg_types.items[i]);
        }
        try self.extendSubstitutionsByMatchingTypeParamNames(base_t, type_params, &subs);
        if (alias_info) |info| {
            if (info.body_node != hir_mod.none_node_id and
                (self.hir.kindOf(info.body_node) == .conditional_type or
                    self.hir.kindOf(info.body_node) == .template_literal_type or
                    self.hir.kindOf(info.body_node) == .type_ref or
                    self.hir.kindOf(info.body_node) == .intersection_type or
                    self.hir.kindOf(info.body_node) == .union_type or
                    self.hir.kindOf(info.body_node) == .indexed_access_type or
                    self.hir.kindOf(info.body_node) == .keyof_type))
            {
                try self.pushNarrowScope();
                defer self.popNarrowScope();
                for (info.params) |param_t| {
                    if (param_t >= self.interner.pool.typeCount()) continue;
                    if (!self.interner.pool.flagsOf(param_t).is_type_parameter) continue;
                    const tp = self.interner.pool.type_parameter_payloads.items[self.interner.pool.payloadOf(param_t)];
                    const arg_t = subs.get(param_t) orelse continue;
                    try self.recordNarrow(tp.name, arg_t);
                }
                const eval_t = self.lowererLowerWithTypeParams(info.body_node) catch info.body;
                try self.registerAliasDisplayText(eval_t, display_text);
                return eval_t;
            }
        }
        const instantiated = self.substituteType(base_t, &subs) catch base_t;
        try self.registerAliasDisplayText(instantiated, display_text);
        return instantiated;
    }

    /// Materialize the built-in homomorphic utility types
    /// (`Partial`/`Required`/`Readonly`/`Pick`/`Omit`) when they are
    /// applied to a concrete object type and no source-level (or
    /// lib.d.ts) generic alias of the same name is in scope.
    ///
    /// Home ships only a minimal `lib.d.ts` substitute, so these
    /// utility names are recognized as "valid generic references"
    /// (`typeRefNameAcceptsTypeArgsAt`) but never resolve to a real
    /// mapped-type body ÃÂ¢ÃÂÃÂ the type-ref lowerer previously fell through
    /// to `any`. Lowering a `var` annotation like `Readonly<Shape>` to
    /// `any` makes a sibling declaration appear to have a conflicting
    /// type, spuriously firing TS2403 (see `mappedTypeModifiers.ts`,
    /// `mappedTypes2.ts`, whose baselines are empty).
    ///
    /// Returns `null` (fall through) when the operand is not a concrete
    /// object type (e.g. a bare type parameter `Partial<T>` inside a
    /// generic fn), preserving the prior generic-passthrough behavior.
    fn lowerBuiltinHomomorphicUtility(self: *Checker, type_node: NodeId) CheckError!?TypeId {
        const r = hir_mod.typeRefOf(self.hir, type_node);
        if (r.qualifier_len != 0) return null;
        // A user-declared (or otherwise in-scope) alias of the same
        // name takes precedence ÃÂ¢ÃÂÃÂ its mapped body drives lowering via
        // the `generic_aliases` path.
        if (self.generic_aliases.contains(r.name)) return null;
        const name = self.string_interner.get(r.name);
        const args = hir_mod.typeRefArgs(self.hir, type_node);

        const Kind = enum { partial, required, readonly, pick, omit };
        const kind: Kind = if (std.mem.eql(u8, name, "Partial"))
            .partial
        else if (std.mem.eql(u8, name, "Required"))
            .required
        else if (std.mem.eql(u8, name, "Readonly"))
            .readonly
        else if (std.mem.eql(u8, name, "Pick"))
            .pick
        else if (std.mem.eql(u8, name, "Omit"))
            .omit
        else
            return null;

        const wants_keys = kind == .pick or kind == .omit;
        const min_args: usize = if (wants_keys) 2 else 1;
        if (args.len < min_args) return null;

        const source_t = try self.lowererLowerWithTypeParams(args[0]);
        if (kind == .pick) {
            const key_t = try self.lowererLowerWithTypeParams(args[1]);
            try self.checkBuiltinPickKeyConstraint(args[1], args[0], key_t, source_t);
        }
        if ((kind == .partial or kind == .required or kind == .readonly) and source_t < self.interner.pool.typeCount()) {
            const source_flags = self.interner.pool.flagsOf(source_t);
            if (source_flags.is_type_parameter) {
                const key_name = self.string_interner.intern("__home_mapped_key") catch return error.OutOfMemory;
                const key_tp = self.interner.internFreshTypeParameterWithFlags(
                    key_name,
                    try self.propertyKeyUnionType(),
                    types.Primitive.none,
                    .bivariant,
                    false,
                ) catch return error.OutOfMemory;
                const constraint = self.interner.internKeyof(source_t) catch return error.OutOfMemory;
                const template = self.interner.internIndexedAccess(source_t, key_tp) catch return error.OutOfMemory;
                const readonly: types.ModifierState = if (kind == .readonly) .add else .none;
                const optional: types.ModifierState = switch (kind) {
                    .partial => .add,
                    .required => .remove,
                    else => .none,
                };
                const mapped_t = self.interner.internMapped(constraint, template, readonly, optional) catch return error.OutOfMemory;
                try self.registerAliasDisplayName(mapped_t, r.name, &.{source_t});
                return mapped_t;
            }
            if (source_flags.is_mapped) {
                const mapped = self.interner.mappedPayload(source_t);
                const readonly: types.ModifierState = if (kind == .readonly) .add else mapped.readonly;
                const optional: types.ModifierState = switch (kind) {
                    .partial => .add,
                    .required => .remove,
                    else => mapped.optional,
                };
                const mapped_t = self.interner.internMapped(mapped.constraint, mapped.template, readonly, optional) catch return error.OutOfMemory;
                try self.registerAliasDisplayName(mapped_t, r.name, &.{source_t});
                return mapped_t;
            }
        }
        if (kind == .pick and source_t < self.interner.pool.typeCount()) {
            const source_flags = self.interner.pool.flagsOf(source_t);
            if (source_flags.is_type_parameter) {
                const key_t = try self.lowererLowerWithTypeParams(args[1]);
                const key_name = self.string_interner.intern("__home_mapped_key") catch return error.OutOfMemory;
                const key_tp = self.interner.internFreshTypeParameterWithFlags(
                    key_name,
                    key_t,
                    types.Primitive.none,
                    .bivariant,
                    false,
                ) catch return error.OutOfMemory;
                const template = self.interner.internIndexedAccess(source_t, key_tp) catch return error.OutOfMemory;
                const mapped_t = self.interner.internMapped(key_t, template, .none, .none) catch return error.OutOfMemory;
                try self.registerAliasDisplayName(mapped_t, r.name, &.{ source_t, key_t });
                return mapped_t;
            }
        }
        if (source_t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(source_t).is_object_type) return null;

        // Pick/Omit need the literal key set from the second arg.
        var key_set: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer key_set.deinit(self.gpa);
        if (wants_keys) {
            const key_t = try self.lowererLowerWithTypeParams(args[1]);
            var keys: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
            defer keys.deinit(self.gpa);
            // Bail to the generic-passthrough path if the key operand
            // isn't a finite set of string-literal keys (e.g. `keyof T`
            // where T is a type parameter); only concrete keys let us
            // materialize a faithful object shape.
            if (!self.collectStringLiteralKeys(key_t, &keys)) {
                if (kind == .pick) {
                    const has_string = self.typeContainsBroadKey(key_t, types.Primitive.string_t);
                    const has_number = self.typeContainsBroadKey(key_t, types.Primitive.number_t);
                    const has_symbol = self.typeContainsBroadKey(key_t, types.Primitive.symbol_t);
                    if (has_string or has_number or has_symbol) {
                        const source_string = self.interner.objectStringIndex(source_t);
                        const source_number = self.interner.objectNumberIndex(source_t);
                        const source_symbol = self.interner.objectSymbolIndex(source_t);
                        const string_idx = if (has_string) source_string else types.Primitive.none;
                        const number_idx = if (has_number)
                            (if (source_number != types.Primitive.none) source_number else source_string)
                        else
                            types.Primitive.none;
                        const symbol_idx = if (has_symbol) source_symbol else types.Primitive.none;
                        if (string_idx != types.Primitive.none or
                            number_idx != types.Primitive.none or
                            symbol_idx != types.Primitive.none)
                        {
                            return self.interner.internObjectTypeWithIndexAndSymbol(
                                &.{},
                                string_idx,
                                number_idx,
                                symbol_idx,
                            ) catch return error.OutOfMemory;
                        }
                    }
                }
                return null;
            }
            for (keys.items) |k| try key_set.put(self.gpa, k, {});
        }

        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        for (self.interner.objectMembers(source_t)) |m| {
            switch (kind) {
                .pick => if (!key_set.contains(m.name)) continue,
                .omit => if (key_set.contains(m.name)) continue,
                else => {},
            }
            try members.append(self.gpa, .{
                .name = m.name,
                .type = m.type,
                .is_optional = switch (kind) {
                    .partial => true,
                    .required => false,
                    else => m.is_optional,
                },
                .is_readonly = switch (kind) {
                    .readonly => true,
                    else => m.is_readonly,
                },
                .is_method = m.is_method,
                .decl_node = m.decl_node,
            });
        }

        // Pick/Omit drop the source index signatures (the result is a
        // closed object over the selected keys); the modifier utilities
        // preserve them.
        const string_idx = if (wants_keys) types.Primitive.none else self.interner.objectStringIndex(source_t);
        const number_idx = if (wants_keys) types.Primitive.none else self.interner.objectNumberIndex(source_t);
        const symbol_idx = if (wants_keys) types.Primitive.none else self.interner.objectSymbolIndex(source_t);

        const result = self.interner.internObjectTypeWithIndexAndSymbol(
            members.items,
            string_idx,
            number_idx,
            symbol_idx,
        ) catch return error.OutOfMemory;
        if (!wants_keys) try self.registerAliasDisplayName(result, r.name, &.{source_t});
        return result;
    }

    fn checkBuiltinPropertyKeyConstraint(self: *Checker, arg_node: NodeId, arg_t: TypeId) CheckError!void {
        if (self.typeIsAnyLike(arg_t) or self.typeIsPropertyKeyDomain(arg_t, 0)) return;
        if (self.infer_type_parameters.contains(arg_t)) return;
        if (try self.indexedAccessSyntaxBaseConstraint(arg_node, 0)) |constraint| {
            if (self.typeIsPropertyKeyDomain(constraint, 0)) return;
        }
        if (try self.indexedAccessBaseConstraint(arg_t, 0)) |constraint| {
            if (self.typeIsPropertyKeyDomain(constraint, 0)) return;
        }
        const source_name = try self.typeSyntaxOrDiagnosticName(arg_node, arg_t);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' does not satisfy the constraint 'string | number | symbol'.",
            .{source_name},
        );
        try self.reportOnce(arg_node, TsCodes.type_does_not_satisfy_constraint, msg);
    }

    fn checkBuiltinPickKeyConstraint(
        self: *Checker,
        key_node: NodeId,
        source_node: NodeId,
        key_t: TypeId,
        source_t: TypeId,
    ) CheckError!void {
        if (self.typeIsAnyLike(key_t) or source_t >= self.interner.pool.typeCount()) return;
        if (self.typeNodeKeyofBaseName(key_node, 0)) |key_base| {
            if (self.bareTypeNodeName(source_node)) |source_name| {
                if (key_base == source_name) return;
            }
        }
        if (self.constrainedKeyofOperand(key_t, 0)) |operand| {
            if (operand == source_t) return;
        }
        const allowed = try self.keyofTypeFromOperand(source_t);
        const checked_key_t = self.typeParameterConstraint(key_t) orelse key_t;
        if (try self.checkerAssignableTo(checked_key_t, allowed)) return;
        const key_name = (try self.sortedStringLiteralUnionAnnotationText(self.nodeSourceTextOrEmpty(key_node))) orelse
            (try self.allocTypeAnnotationDiagnosticName(key_node, false)) orelse
            try self.typeSyntaxOrDiagnosticName(key_node, key_t);
        const source_name = try self.typeSyntaxOrDiagnosticName(source_node, source_t);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' does not satisfy the constraint 'keyof {s}'.",
            .{ key_name, source_name },
        );
        try self.reportOnce(key_node, TsCodes.type_does_not_satisfy_constraint, msg);
    }

    fn registerAliasDisplayText(self: *Checker, t: TypeId, text: []const u8) !void {
        if (t < types.Primitive.first_dynamic) return;
        if (t >= self.interner.pool.typeCount()) return;
        if (self.alias_display_names.contains(t)) return;
        if (self.namedTypeForId(t) != null) return;
        if (self.enumNameFromNominal(t) != null) return;
        const display = try self.diag_arena.allocator().dupe(u8, std.mem.trim(u8, text, " \t\r\n"));
        try self.alias_display_names.put(self.gpa, t, display);
    }

    fn relocateJsDocTypeArgConstraintDiagnostics(self: *Checker, diagnostic_start: usize, pos: ?u32) void {
        const source_pos = pos orelse return;
        for (self.diagnostics.items[diagnostic_start..]) |*diagnostic| {
            if (diagnostic.code == TsCodes.type_does_not_satisfy_constraint and diagnostic.pos == null) {
                diagnostic.pos = source_pos;
            }
        }
    }

    fn jsDocPrimitiveType(self: *Checker, type_text: []const u8) CheckError!?TypeId {
        var t = std.mem.trim(u8, type_text, " \t\r\n");
        while (t.len >= 2 and t[0] == '(' and t[t.len - 1] == ')') {
            t = std.mem.trim(u8, t[1 .. t.len - 1], " \t\r\n");
        }
        if (std.mem.eql(u8, t, "string") or std.mem.eql(u8, t, "String")) return types.Primitive.string_t;
        if (std.mem.eql(u8, t, "number") or std.mem.eql(u8, t, "Number")) return types.Primitive.number_t;
        if (std.mem.eql(u8, t, "boolean") or std.mem.eql(u8, t, "Boolean")) return types.Primitive.boolean_t;
        if (std.mem.eql(u8, t, "symbol")) return types.Primitive.symbol_t;
        if (jsDocTypeTextIsUniqueSymbol(t)) return types.Primitive.symbol_t;
        if (std.mem.eql(u8, t, "true")) return types.Primitive.true_lit;
        if (std.mem.eql(u8, t, "false")) return types.Primitive.false_lit;
        if (std.mem.eql(u8, t, "undefined")) return types.Primitive.undefined_t;
        if (std.mem.eql(u8, t, "null")) return types.Primitive.null_t;
        if (std.mem.eql(u8, t, "void")) return types.Primitive.void_t;
        if (std.mem.eql(u8, t, "any") or std.mem.eql(u8, t, "*") or std.mem.eql(u8, t, "?")) return types.Primitive.any;
        if (std.mem.eql(u8, t, "unknown")) return types.Primitive.unknown;
        if (std.mem.eql(u8, t, "never")) return types.Primitive.never;
        if (std.mem.eql(u8, t, "Object")) return self.lowerBuiltinObjectType("Object") orelse types.Primitive.object_t;
        if (std.mem.eql(u8, t, "object")) return types.Primitive.object_t;
        return null;
    }

    fn recordJsDocSignatureArity(self: *Checker, sig: TypeId, omittable: []const bool, has_rest: bool) CheckError!void {
        try self.recordSignatureMinArgs(sig, omittable);
        if (has_rest) try self.rest_signatures.put(self.gpa, sig, {});
    }

    fn jsDocFunctionParamIsRest(param: []const u8) bool {
        return std.mem.startsWith(u8, std.mem.trim(u8, param, " \t\r\n"), "...");
    }

    fn jsDocFunctionParamIsOmittable(param: []const u8) bool {
        var text = std.mem.trim(u8, param, " \t\r\n");
        if (std.mem.startsWith(u8, text, "...")) return true;
        if (text.len > 0 and text[0] == '[') return true;
        if (text.len > 0 and text[text.len - 1] == '=') return true;
        const param_type_text = jsDocFunctionParamTypeText(text);
        text = std.mem.trim(u8, param_type_text, " \t\r\n");
        return text.len > 0 and text[text.len - 1] == '=';
    }

    fn jsDocFunctionParamNormalizeTypeText(param_type_text: []const u8) []const u8 {
        var text = std.mem.trim(u8, param_type_text, " \t\r\n");
        if (text.len > 0 and text[text.len - 1] == '=') {
            text = std.mem.trim(u8, text[0 .. text.len - 1], " \t\r\n");
        }
        return text;
    }

    fn jsDocFunctionType(self: *Checker, type_text: []const u8) CheckError!?TypeId {
        if (std.mem.indexOf(u8, type_text, "=>")) |arrow| {
            var params_part = std.mem.trim(u8, type_text[0..arrow], " \t\r\n");
            var inline_type_params: std.ArrayListUnmanaged(TypeId) = .empty;
            defer inline_type_params.deinit(self.gpa);
            var pushed_inline_scope = false;
            defer if (pushed_inline_scope) self.popNarrowScope();
            // A generic arrow type carries a leading type-parameter list
            // `<T, U>(args) => ret` (e.g. `@typedef {<T>(m: T) => T} IFn`).
            // Scope those names while lowering the params and return so the
            // JSDoc type text does not fall through to TS2304.
            if (params_part.len > 0 and params_part[0] == '<') {
                if (jsDocMatchingAngle(params_part)) |close_angle| {
                    var splitter = JsDocTopLevelSplitter.init(params_part[1..close_angle], ',');
                    while (splitter.next()) |raw_param| {
                        const param_name_text = jsDocInlineTypeParameterName(raw_param) orelse continue;
                        if (!pushed_inline_scope) {
                            try self.pushNarrowScope();
                            pushed_inline_scope = true;
                        }
                        const param_name = self.string_interner.intern(param_name_text) catch return error.OutOfMemory;
                        const constraint_t = if (jsDocInlineTypeParameterConstraintText(raw_param)) |constraint_text|
                            (try self.jsDocTypeTextToType(self.source orelse "", constraint_text)) orelse types.Primitive.unknown
                        else
                            types.Primitive.unknown;
                        const tp_id = self.interner.internFreshTypeParameterWithFlags(
                            param_name,
                            constraint_t,
                            types.Primitive.none,
                            .invariant,
                            false,
                        ) catch return error.OutOfMemory;
                        try inline_type_params.append(self.gpa, tp_id);
                        try self.recordNarrow(param_name, tp_id);
                    }
                    params_part = std.mem.trim(u8, params_part[close_angle + 1 ..], " \t\r\n");
                }
            }
            if (params_part.len < 2 or params_part[0] != '(' or params_part[params_part.len - 1] != ')') return null;
            var params: std.ArrayListUnmanaged(TypeId) = .empty;
            defer params.deinit(self.gpa);
            var param_names: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
            defer param_names.deinit(self.gpa);
            var names_complete = true;
            var omittable: std.ArrayListUnmanaged(bool) = .empty;
            defer omittable.deinit(self.gpa);
            var has_rest = false;
            var splitter = JsDocTopLevelSplitter.init(params_part[1 .. params_part.len - 1], ',');
            while (splitter.next()) |raw_param| {
                const param = std.mem.trim(u8, raw_param, " \t\r\n");
                if (param.len == 0) continue;
                has_rest = has_rest or jsDocFunctionParamIsRest(param);
                const param_type_text = jsDocFunctionParamNormalizeTypeText(jsDocFunctionParamTypeText(param));
                const param_t = (try self.jsDocFunctionType(param_type_text)) orelse
                    (try self.jsDocTypeTextToType(self.source orelse "", param_type_text)) orelse
                    types.Primitive.any;
                try params.append(self.gpa, param_t);
                if (jsDocFunctionParamName(param)) |name| {
                    try param_names.append(self.gpa, self.string_interner.intern(name) catch return error.OutOfMemory);
                } else {
                    names_complete = false;
                }
                try omittable.append(self.gpa, jsDocFunctionParamIsOmittable(param));
            }
            const ret_text = std.mem.trim(u8, type_text[arrow + "=>".len ..], " \t\r\n");
            const ret_t = (try self.jsDocFunctionType(ret_text)) orelse
                (try self.jsDocTypeTextToType(self.source orelse "", ret_text)) orelse
                types.Primitive.any;
            const sig = self.interner.internSignature(params.items, ret_t, false) catch return error.OutOfMemory;
            try self.recordGenericSignatureParams(sig, inline_type_params.items);
            try self.recordJsDocSignatureArity(sig, omittable.items, has_rest);
            if (names_complete and param_names.items.len == params.items.len and param_names.items.len > 0) {
                const owned = param_names.toOwnedSlice(self.gpa) catch return error.OutOfMemory;
                if (self.signature_param_names.fetchRemove(sig)) |old| self.gpa.free(old.value);
                try self.signature_param_names.put(self.gpa, sig, owned);
            }
            return sig;
        }
        const open = jsDocFunctionOpenParen(type_text) orelse return null;
        const close = jsDocMatchingParen(type_text, open) orelse return null;
        var params: std.ArrayListUnmanaged(TypeId) = .empty;
        defer params.deinit(self.gpa);
        var omittable: std.ArrayListUnmanaged(bool) = .empty;
        defer omittable.deinit(self.gpa);
        var has_rest = false;
        const params_text = type_text[open + 1 .. close];
        var param_start: usize = 0;
        var depth: i32 = 0;
        var idx: usize = 0;
        while (idx <= params_text.len) : (idx += 1) {
            const at_end = idx == params_text.len;
            if (!at_end) {
                if (params_text[idx] == '(') depth += 1;
                if (params_text[idx] == ')') depth -= 1;
                if (params_text[idx] != ',' or depth != 0) continue;
            }
            const param = std.mem.trim(u8, params_text[param_start..idx], " \t\r\n");
            param_start = idx + 1;
            if (param.len == 0) continue;
            has_rest = has_rest or jsDocFunctionParamIsRest(param);
            const param_type_text = jsDocFunctionParamNormalizeTypeText(jsDocFunctionParamTypeText(param));
            const param_t = (try self.jsDocFunctionType(param_type_text)) orelse
                (try self.jsDocTypeTextToType(self.source orelse "", param_type_text)) orelse
                types.Primitive.any;
            try params.append(self.gpa, param_t);
            try omittable.append(self.gpa, jsDocFunctionParamIsOmittable(param));
        }
        var ret_t: TypeId = types.Primitive.any;
        const rest = std.mem.trim(u8, type_text[close + 1 ..], " \t\r\n");
        if (std.mem.startsWith(u8, rest, ":")) {
            const ret_text = std.mem.trim(u8, rest[1..], " \t\r\n");
            ret_t = (try self.jsDocFunctionType(ret_text)) orelse
                (try self.jsDocTypeTextToType(self.source orelse "", ret_text)) orelse
                types.Primitive.any;
        }
        const sig = self.interner.internSignature(params.items, ret_t, false) catch return error.OutOfMemory;
        try self.recordJsDocSignatureArity(sig, omittable.items, has_rest);
        return sig;
    }

    fn jsDocInlineTypeParameterName(raw_param: []const u8) ?[]const u8 {
        var text = std.mem.trim(u8, raw_param, " \t\r\n");
        if (std.mem.startsWith(u8, text, "const") and
            (text.len == "const".len or std.ascii.isWhitespace(text["const".len])))
        {
            text = std.mem.trim(u8, text["const".len..], " \t\r\n");
        }
        if (text.len == 0 or !isJsDocIdentStart(text[0])) return null;
        var end: usize = 1;
        while (end < text.len and isJsDocIdentChar(text[end])) end += 1;
        return text[0..end];
    }

    fn jsDocInlineTypeParameterConstraintText(raw_param: []const u8) ?[]const u8 {
        var text = std.mem.trim(u8, raw_param, " \t\r\n");
        if (std.mem.startsWith(u8, text, "const") and
            (text.len == "const".len or std.ascii.isWhitespace(text["const".len])))
        {
            text = std.mem.trim(u8, text["const".len..], " \t\r\n");
        }
        if (text.len == 0 or !isJsDocIdentStart(text[0])) return null;
        var name_end: usize = 1;
        while (name_end < text.len and isJsDocIdentChar(text[name_end])) name_end += 1;
        var rest = std.mem.trim(u8, text[name_end..], " \t\r\n");
        if (!std.mem.startsWith(u8, rest, "extends")) return null;
        rest = std.mem.trim(u8, rest["extends".len..], " \t\r\n");
        if (rest.len == 0) return null;
        return rest;
    }

    fn jsDocFunctionParamTypeText(param: []const u8) []const u8 {
        var text = std.mem.trim(u8, param, " \t\r\n");
        if (std.mem.startsWith(u8, text, "...")) {
            text = std.mem.trim(u8, text[3..], " \t\r\n");
        }
        if (jsDocFunctionParamIsNameOnlyOptional(text)) return "any";
        if (jsDocFunctionOpenParen(text) != null) return text;
        var paren_depth: i32 = 0;
        var angle_depth: i32 = 0;
        var brace_depth: i32 = 0;
        var bracket_depth: i32 = 0;
        var quote: u8 = 0;
        for (text, 0..) |c, i| {
            if (quote != 0) {
                if (c == '\\') {
                    continue;
                } else if (c == quote) {
                    quote = 0;
                }
                continue;
            }
            if (c == '\'' or c == '"') {
                quote = c;
                continue;
            }
            switch (c) {
                '(' => paren_depth += 1,
                ')' => {
                    if (paren_depth > 0) paren_depth -= 1;
                },
                '<' => angle_depth += 1,
                '>' => {
                    if (angle_depth > 0) angle_depth -= 1;
                },
                '{' => brace_depth += 1,
                '}' => {
                    if (brace_depth > 0) brace_depth -= 1;
                },
                '[' => bracket_depth += 1,
                ']' => {
                    if (bracket_depth > 0) bracket_depth -= 1;
                },
                ':' => {
                    if (paren_depth == 0 and angle_depth == 0 and brace_depth == 0 and bracket_depth == 0) {
                        return std.mem.trim(u8, text[i + 1 ..], " \t\r\n");
                    }
                },
                else => {},
            }
        }
        return text;
    }

    fn jsDocFunctionParamName(param: []const u8) ?[]const u8 {
        var text = std.mem.trim(u8, param, " \t\r\n");
        if (std.mem.startsWith(u8, text, "...")) text = std.mem.trim(u8, text[3..], " \t\r\n");
        const colon = std.mem.indexOfScalar(u8, text, ':') orelse return null;
        var name = std.mem.trim(u8, text[0..colon], " \t\r\n");
        if (name.len > 0 and name[name.len - 1] == '?') name = std.mem.trim(u8, name[0 .. name.len - 1], " \t\r\n");
        if (name.len == 0 or !isJsDocIdentStart(name[0])) return null;
        for (name[1..]) |c| if (!isJsDocIdentChar(c)) return null;
        return name;
    }

    fn jsDocParamTagNamesNestedProperty(name: []const u8) bool {
        var text = std.mem.trim(u8, name, " \t\r\n");
        if (text.len >= 2 and text[0] == '[' and text[text.len - 1] == ']') {
            text = std.mem.trim(u8, text[1 .. text.len - 1], " \t\r\n");
        }
        if (std.mem.indexOfScalar(u8, text, '=')) |eq| {
            text = std.mem.trim(u8, text[0..eq], " \t\r\n");
        }
        return std.mem.indexOfScalar(u8, text, '.') != null;
    }

    fn jsDocParamTagAtIndexNamesNestedProperty(body: []const u8, wanted_index: usize) bool {
        var search_start: usize = 0;
        var seen: usize = 0;
        while (std.mem.indexOfPos(u8, body, search_start, "@param")) |tag_pos| {
            search_start = tag_pos + "@param".len;
            if (tag_pos > 0 and isJsDocIdentChar(body[tag_pos - 1])) continue;
            if (search_start < body.len and isJsDocIdentChar(body[search_start])) continue;
            if (seen != wanted_index) {
                seen += 1;
                continue;
            }
            var rest = std.mem.trim(u8, body[search_start..], " \t\r\n*");
            if (rest.len > 0 and rest[0] == '{') {
                const type_len = jsDocBalancedBraceLen(rest);
                if (type_len != 0) rest = std.mem.trim(u8, rest[type_len..], " \t\r\n*");
            }
            var name_len: usize = 0;
            while (name_len < rest.len and !std.ascii.isWhitespace(rest[name_len])) : (name_len += 1) {}
            return jsDocParamTagNamesNestedProperty(rest[0..name_len]);
        }
        return false;
    }

    fn jsDocFunctionParamIsNameOnlyOptional(text: []const u8) bool {
        if (text.len < 2 or text[text.len - 1] != '?') return false;
        const name = text[0 .. text.len - 1];
        if (name.len == 0 or !isJsDocIdentStart(name[0])) return false;
        for (name[1..]) |c| {
            if (!isJsDocIdentChar(c)) return false;
        }
        return true;
    }

    fn jsDocImportTypeTextToType(self: *Checker, src: []const u8, type_text: []const u8) CheckError!?TypeId {
        var space: CommonJsImportMemberSpace = .jsdoc_type;
        var text = type_text;
        if (std.mem.startsWith(u8, text, "typeof")) {
            const after_typeof = std.mem.trimStart(u8, text["typeof".len..], " \t\r\n");
            if (after_typeof.len == text.len - "typeof".len) return null;
            text = after_typeof;
            space = .value;
        }
        const prefix = "import(";
        if (!std.mem.startsWith(u8, text, prefix)) return null;
        const close = jsDocMatchingParen(text, "import".len) orelse return null;
        var spec_text = std.mem.trim(u8, text[prefix.len..close], " \t\r\n");
        if (spec_text.len < 2) return null;
        const quote = spec_text[0];
        if ((quote != '"' and quote != '\'') or spec_text[spec_text.len - 1] != quote) return null;
        spec_text = spec_text[1 .. spec_text.len - 1];
        const anchor = self.jsdoc_diagnostic_anchor;
        if (anchor == hir_mod.none_node_id) return null;
        var rest = std.mem.trim(u8, text[close + 1 ..], " \t\r\n");
        if (rest.len == 0) {
            const spec_id = self.string_interner.intern(spec_text) catch return error.OutOfMemory;
            if (space == .value) {
                if (try self.virtualExportAssignmentExpressionType(anchor, spec_id)) |export_t| return export_t;
                if (try self.virtualExportAssignmentTargetStaticType(anchor, spec_id)) |export_t| return export_t;
            } else if (try self.virtualExportAssignmentTargetInstanceType(anchor, spec_id)) |export_t| {
                return export_t;
            }
            const module_t = (try self.virtualCommonJsModuleExportObjectType(anchor, spec_text)) orelse return null;
            return if (space == .jsdoc_type) try self.commonJsValueExportAsJsDocType(module_t) else module_t;
        }
        if (rest[0] != '.') return null;
        rest = std.mem.trim(u8, rest[1..], " \t\r\n");
        const member_text = rest;
        if (member_text.len == 0) return null;
        for (member_text) |c| {
            if (!isJsDocIdentChar(c)) return null;
        }
        const member_id = self.string_interner.intern(member_text) catch return error.OutOfMemory;
        const member_pos = self.sliceStartPos(src, member_text);
        return try self.virtualCommonJsImportMemberByName(anchor, spec_text, member_id, space, member_pos);
    }

    fn jsDocImportedNamespaceMemberType(self: *Checker, src: []const u8, type_text: []const u8) CheckError!?TypeId {
        var dot_count: usize = 0;
        var dot_pos: usize = 0;
        for (type_text, 0..) |c, i| {
            if (c == '.') {
                dot_count += 1;
                dot_pos = i;
                continue;
            }
            if (!isJsDocIdentChar(c)) return null;
        }
        if (dot_count != 1 or dot_pos == 0 or dot_pos + 1 >= type_text.len) return null;
        const root_text = type_text[0..dot_pos];
        const leaf_text = type_text[dot_pos + 1 ..];
        const anchor = self.jsdoc_diagnostic_anchor;
        if (anchor == hir_mod.none_node_id) return null;

        var search: usize = 0;
        var match_count: usize = 0;
        var spec_buf: [512]u8 = undefined;
        var spec_len: usize = 0;
        while (std.mem.indexOfPos(u8, src, search, "@import")) |at| {
            search = at + "@import".len;
            if (at > 0 and isJsDocIdentChar(src[at - 1])) continue;
            if (search < src.len and isJsDocIdentChar(src[search])) continue;
            const raw_end = jsDocTagBodyEnd(src, search);
            var norm_buf: [1024]u8 = undefined;
            const body = jsDocNormalizeBody(src[search..raw_end], &norm_buf) orelse continue;
            if (!jsDocImportNamespaceLocalMatches(body, root_text)) continue;
            if (jsDocImportHasAttributes(body)) return null;
            const spec = jsDocImportSpec(body) orelse continue;
            match_count += 1;
            if (spec.len <= spec_buf.len) {
                @memcpy(spec_buf[0..spec.len], spec);
                spec_len = spec.len;
            }
        }
        if (match_count != 1 or spec_len == 0) return null;
        const leaf_id = self.string_interner.intern(leaf_text) catch return error.OutOfMemory;
        const leaf_pos = self.sliceStartPos(src, leaf_text);
        return try self.virtualCommonJsImportMemberByName(anchor, spec_buf[0..spec_len], leaf_id, .jsdoc_type, leaf_pos);
    }

    fn jsDocImportNamespaceLocalMatches(body: []const u8, local_name: []const u8) bool {
        const star = std.mem.indexOfScalar(u8, body, '*') orelse return false;
        const as_rel = jsDocWordIndex(body[star..], "as") orelse return false;
        const after = std.mem.trim(u8, body[star + as_rel + "as".len ..], " \t");
        var local_end: usize = 0;
        while (local_end < after.len and isJsDocIdentChar(after[local_end])) : (local_end += 1) {}
        return local_end > 0 and std.mem.eql(u8, after[0..local_end], local_name);
    }

    /// Index of the `>` closing a leading `<…>` (balanced over nested angle
    /// brackets) at the start of `text`, or null if `text` doesn't start with
    /// `<` or is unbalanced.
    fn jsDocMatchingAngle(text: []const u8) ?usize {
        if (text.len == 0 or text[0] != '<') return null;
        var depth: i32 = 0;
        var i: usize = 0;
        while (i < text.len) : (i += 1) {
            if (text[i] == '<') depth += 1;
            if (text[i] == '>') {
                depth -= 1;
                if (depth == 0) return i;
            }
        }
        return null;
    }

    fn jsDocMatchingParen(text: []const u8, open_idx: usize) ?usize {
        if (open_idx >= text.len or text[open_idx] != '(') return null;
        var depth: i32 = 1;
        var i: usize = open_idx + 1;
        while (i < text.len) : (i += 1) {
            if (text[i] == '(') depth += 1;
            if (text[i] == ')') {
                depth -= 1;
                if (depth == 0) return i;
            }
        }
        return null;
    }

    fn jsDocFunctionOpenParen(type_text: []const u8) ?usize {
        const prefix = "function";
        if (!std.mem.startsWith(u8, type_text, prefix)) return null;
        var open = prefix.len;
        while (open < type_text.len and std.ascii.isWhitespace(type_text[open])) : (open += 1) {}
        return if (open < type_text.len and type_text[open] == '(') open else null;
    }

    fn jsDocCallbackSignature(self: *Checker, src: []const u8, wanted_name: []const u8) CheckError!?TypeId {
        var type_params: std.ArrayListUnmanaged(TypeId) = .empty;
        defer type_params.deinit(self.gpa);
        return try self.jsDocCallbackSignatureWithTypeParams(src, wanted_name, &type_params);
    }

    fn jsDocCallbackSignatureWithTypeParams(
        self: *Checker,
        src: []const u8,
        wanted_name: []const u8,
        out_type_params: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!?TypeId {
        var search_start: usize = 0;
        while (std.mem.indexOfPos(u8, src, search_start, "/**")) |start| {
            const body_start = start + 3;
            const end = std.mem.indexOfPos(u8, src, body_start, "*/") orelse return null;
            defer search_start = end + 2;
            const body = src[body_start..end];
            if (!jsDocBlockHasNamedTag(body, "@callback", wanted_name)) continue;
            const tags = ts_parser.jsdoc.parse(self.gpa, body) catch continue;
            defer self.gpa.free(tags);
            var has_templates = false;
            for (tags) |tag| {
                if (tag.kind == .template_tag and tag.name.len > 0) {
                    has_templates = true;
                    break;
                }
            }
            if (has_templates) try self.pushNarrowScope();
            defer if (has_templates) self.popNarrowScope();
            for (tags) |tag| {
                if (tag.kind != .template_tag or tag.name.len == 0) continue;
                const tag_name = self.string_interner.intern(tag.name) catch return error.OutOfMemory;
                const constraint_t = if (tag.type_text.len > 0)
                    (try self.jsDocTypeTextToType(src, tag.type_text)) orelse types.Primitive.unknown
                else
                    types.Primitive.unknown;
                const tp_id = self.interner.internFreshTypeParameterWithFlags(
                    tag_name,
                    constraint_t,
                    types.Primitive.none,
                    .invariant,
                    false,
                ) catch return error.OutOfMemory;
                try out_type_params.append(self.gpa, tp_id);
                try self.recordNarrow(tag_name, tp_id);
            }
            var params: std.ArrayListUnmanaged(TypeId) = .empty;
            defer params.deinit(self.gpa);
            var omittable: std.ArrayListUnmanaged(bool) = .empty;
            defer omittable.deinit(self.gpa);
            var ret_t: TypeId = types.Primitive.any;
            var param_tag_index: usize = 0;
            for (tags) |tag| {
                if (tag.kind == .param_tag) {
                    if (jsDocParamTagAtIndexNamesNestedProperty(body, param_tag_index)) {
                        param_tag_index += 1;
                        continue;
                    }
                    param_tag_index += 1;
                    const param_t = (try self.jsDocTypeTextToType(src, tag.type_text)) orelse types.Primitive.any;
                    try params.append(self.gpa, param_t);
                    try omittable.append(self.gpa, tag.optional);
                } else if (tag.kind == .returns_tag) {
                    ret_t = (try self.jsDocTypeTextToType(src, tag.type_text)) orelse types.Primitive.any;
                }
            }
            const sig = self.interner.internSignature(params.items, ret_t, false) catch return error.OutOfMemory;
            try self.recordJsDocSignatureArity(sig, omittable.items, false);
            return sig;
        }
        return null;
    }

    fn leadingJsDocBody(self: *Checker, src: []const u8, decl_start: u32) ?[]const u8 {
        const jsdoc = self.leadingJsDocBodyWithStart(src, decl_start) orelse return null;
        return jsdoc.body;
    }

    /// In checked JS, a class member's accessibility can come from a leading
    /// JSDoc `@private` / `@protected` / `@public` tag. Those tags parse as
    /// `TagKind.other`, so scan the leading JSDoc body text directly. Returns
    /// null outside checked JS or when no accessibility tag is present.
    /// Mirrors jsdocAccessibilityTags.
    const JsDocAccessibility = struct {
        visibility: hir_mod.Visibility,
        pos: u32,
    };

    fn jsDocAccessibilityInfo(self: *Checker, node: NodeId) ?JsDocAccessibility {
        if (!self.check_js_enabled) return null;
        if (node == hir_mod.none_node_id) return null;
        const src = self.source orelse return null;
        const jsdoc = self.leadingJsDocBodyWithStart(src, self.hir.spanOf(node).start) orelse return null;
        inline for (.{
            .{ "@private", hir_mod.Visibility.private },
            .{ "@protected", hir_mod.Visibility.protected },
            .{ "@public", hir_mod.Visibility.public },
        }) |entry| {
            if (std.mem.indexOf(u8, jsdoc.body, entry[0])) |rel| {
                return .{
                    .visibility = entry[1],
                    .pos = @intCast(jsdoc.start + rel),
                };
            }
        }
        return null;
    }

    fn jsDocAccessibility(self: *Checker, node: NodeId) ?hir_mod.Visibility {
        return if (self.jsDocAccessibilityInfo(node)) |info| info.visibility else null;
    }

    fn reportJsDocAccessibilityOnPrivateIdentifier(
        self: *Checker,
        member_node: NodeId,
        name_node: NodeId,
        member_name: hir_mod.StringId,
    ) CheckError!void {
        if (!self.memberNameIsEcmaPrivate(member_name)) return;
        const info = self.jsDocAccessibilityInfo(member_node) orelse return;
        const anchor = if (name_node != hir_mod.none_node_id) name_node else member_node;
        try self.reportAt(anchor, info.pos, 18010, "An accessibility modifier cannot be used with a private identifier.");
    }

    fn leadingJsDocBodyForFunctionOrOwner(self: *Checker, src: []const u8, fn_node: NodeId) ?[]const u8 {
        const jsdoc = self.leadingJsDocBodyForFunctionOrOwnerWithStart(src, fn_node) orelse return null;
        return jsdoc.body;
    }

    const JsDocBody = struct {
        body: []const u8,
        start: usize,
    };

    const DeprecatedJsDocTag = struct {
        pos: u32,
    };

    fn leadingJsDocBodyForFunctionOrOwnerWithStart(self: *Checker, src: []const u8, fn_node: NodeId) ?JsDocBody {
        const span = self.hir.spanOf(fn_node);
        if (self.leadingJsDocBodyWithStart(src, span.start)) |jsdoc| return jsdoc;

        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id) return null;
        const parent_kind = self.hir.kindOf(parent);
        if (parent_kind == .object_property) {
            const prop = hir_mod.objectPropertyOf(self.hir, parent);
            if (prop.value != fn_node) return null;
            return self.leadingJsDocBodyWithStart(src, self.hir.spanOf(parent).start);
        }
        if (parent_kind == .var_decl or parent_kind == .let_decl or parent_kind == .const_decl) {
            const decl = hir_mod.varDeclOf(self.hir, parent);
            if (decl.init != fn_node) return null;
            const parent_start = self.hir.spanOf(parent).start;
            if (self.leadingJsDocBodyWithStart(src, parent_start)) |jsdoc| return jsdoc;
            if (self.varStatementStartForDeclarator(src, parent_start)) |statement_start| {
                return self.leadingJsDocBodyWithStart(src, statement_start);
            }
            return null;
        }
        if (parent_kind == .assignment) {
            const assignment = hir_mod.assignmentOf(self.hir, parent);
            if (assignment.value != fn_node) return null;
            return self.leadingJsDocBodyWithStart(src, self.hir.spanOf(parent).start);
        }
        return null;
    }

    fn varStatementStartForDeclarator(self: *Checker, src: []const u8, decl_start: u32) ?u32 {
        _ = self;
        var start = @min(@as(usize, decl_start), src.len);
        while (start > 0) : (start -= 1) {
            const c = src[start - 1];
            if (c == ';' or c == '{' or c == '}') break;
        }
        var found: ?usize = null;
        var i = start;
        while (i < decl_start) {
            while (i < decl_start and !isJsDocIdentStart(src[i])) : (i += 1) {}
            const word_start = i;
            while (i < decl_start and isJsDocIdentChar(src[i])) : (i += 1) {}
            const word = src[word_start..i];
            if (std.mem.eql(u8, word, "var") or
                std.mem.eql(u8, word, "let") or
                std.mem.eql(u8, word, "const"))
            {
                found = word_start;
            }
        }
        return if (found) |pos| @intCast(pos) else null;
    }

    fn leadingJsDocBodyWithStart(self: *Checker, src: []const u8, decl_start: u32) ?JsDocBody {
        _ = self;
        var limit = @min(@as(usize, decl_start), src.len);
        var trimmed_end = limit;
        while (trimmed_end > 0 and std.ascii.isWhitespace(src[trimmed_end - 1])) : (trimmed_end -= 1) {}
        if (trimmed_end >= "export".len and
            std.mem.eql(u8, src[trimmed_end - "export".len .. trimmed_end], "export") and
            (trimmed_end == "export".len or !isJsDocIdentChar(src[trimmed_end - "export".len - 1])))
        {
            limit = trimmed_end - "export".len;
        }
        const before = src[0..limit];
        const end = std.mem.lastIndexOf(u8, before, "*/") orelse return null;
        if (!jsDocTrailingTriviaOnly(before[end + 2 ..])) return null;
        const start = std.mem.lastIndexOf(u8, before[0..end], "/**") orelse return null;
        return .{
            .body = before[start + 3 .. end],
            .start = start + 3,
        };
    }

    fn jsDocTrailingTriviaOnly(text: []const u8) bool {
        var line_start: usize = 0;
        while (line_start <= text.len) {
            const line_end = std.mem.indexOfScalarPos(u8, text, line_start, '\n') orelse text.len;
            const line = std.mem.trim(u8, text[line_start..line_end], " \t\r");
            if (line.len > 0 and !std.mem.startsWith(u8, line, "//")) return false;
            if (line_end == text.len) break;
            line_start = line_end + 1;
        }
        return true;
    }

    fn leadingDeprecatedJsDocTag(self: *Checker, decl: NodeId) ?DeprecatedJsDocTag {
        const src = self.source orelse return null;
        const span = self.hir.spanOf(decl);
        const jsdoc = self.leadingJsDocBodyWithStart(src, span.start) orelse return null;
        return jsDocDeprecatedTag(jsdoc);
    }

    fn jsDocDeprecatedTag(jsdoc: JsDocBody) ?DeprecatedJsDocTag {
        var line_start: usize = 0;
        while (line_start <= jsdoc.body.len) {
            const line_end = std.mem.indexOfScalarPos(u8, jsdoc.body, line_start, '\n') orelse jsdoc.body.len;
            var i = line_start;
            while (i < line_end and (jsdoc.body[i] == ' ' or jsdoc.body[i] == '\t' or jsdoc.body[i] == '\r')) : (i += 1) {}
            if (i < line_end and jsdoc.body[i] == '*') {
                i += 1;
                while (i < line_end and (jsdoc.body[i] == ' ' or jsdoc.body[i] == '\t')) : (i += 1) {}
            }
            if (i + "@deprecated".len <= line_end and std.mem.eql(u8, jsdoc.body[i .. i + "@deprecated".len], "@deprecated")) {
                const after = i + "@deprecated".len;
                if (after == line_end or !isJsDocIdentChar(jsdoc.body[after])) {
                    return .{ .pos = @as(u32, @intCast(jsdoc.start + i)) };
                }
            }
            if (line_end == jsdoc.body.len) break;
            line_start = line_end + 1;
        }
        return null;
    }

    fn reportDeprecatedDeclarationUse(self: *Checker, node: NodeId, decl: NodeId, name: hir_mod.StringId) CheckError!void {
        if (node == hir_mod.none_node_id or decl == hir_mod.none_node_id) return;
        if (self.declared_identifier_lookup or self.isDeclNameSlot(node)) return;
        if (self.diagnosticExists(node, TsCodes.symbol_is_deprecated)) return;
        const tag = self.leadingDeprecatedJsDocTag(decl) orelse return;
        const name_text = self.string_interner.get(name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' is deprecated.",
            .{name_text},
        );
        const related = try self.diag_arena.allocator().dupe(RelatedInfo, &.{.{
            .node = decl,
            .pos = tag.pos,
            .code = TsCodes.declaration_marked_deprecated_here,
            .message = "The declaration was marked as deprecated here.",
        }});
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.symbol_is_deprecated,
            .message = msg,
            .related = related,
            .category = .suggestion,
        });
    }

    fn adjacentLeadingJsDocBlocks(
        self: *Checker,
        src: []const u8,
        decl_start: u32,
        out: *std.ArrayListUnmanaged(JsDocBody),
    ) CheckError!void {
        var limit = @min(@as(usize, decl_start), src.len);
        while (true) {
            var trimmed_end = limit;
            while (trimmed_end > 0 and std.ascii.isWhitespace(src[trimmed_end - 1])) : (trimmed_end -= 1) {}
            const before = src[0..trimmed_end];
            const end = std.mem.lastIndexOf(u8, before, "*/") orelse break;
            const between = std.mem.trim(u8, before[end + 2 ..], " \t\r\n");
            if (between.len != 0) break;
            const start = std.mem.lastIndexOf(u8, before[0..end], "/**") orelse break;
            try out.append(self.gpa, .{
                .body = before[start + 3 .. end],
                .start = start + 3,
            });
            limit = start;
        }
        std.mem.reverse(JsDocBody, out.items);
    }

    fn jsDocTypeBaseName(type_text: []const u8) []const u8 {
        const trimmed = std.mem.trim(u8, type_text, " \t\r\n");
        var i: usize = 0;
        while (i < trimmed.len and isJsDocIdentChar(trimmed[i])) : (i += 1) {}
        return trimmed[0..i];
    }

    fn jsDocTypedefObjectSkeleton(
        self: *Checker,
        src: []const u8,
        wanted_name: []const u8,
    ) CheckError!?TypeId {
        if (wanted_name.len == 0) return null;
        const wanted_id = self.string_interner.intern(wanted_name) catch return error.OutOfMemory;
        if (self.resolving_jsdoc_typedef_aliases.contains(wanted_id)) return types.Primitive.any;
        try self.resolving_jsdoc_typedef_aliases.put(self.gpa, wanted_id, {});
        defer _ = self.resolving_jsdoc_typedef_aliases.remove(wanted_id);

        var search_start: usize = 0;
        while (std.mem.indexOfPos(u8, src, search_start, "/**")) |start| {
            const body_start = start + 3;
            const end = std.mem.indexOfPos(u8, src, body_start, "*/") orelse return null;
            defer search_start = end + 2;
            const body = src[body_start..end];
            if (jsDocTypedefTypeText(body, wanted_name)) |type_text| {
                if (try self.jsDocObjectSkeletonFromTypeText(type_text)) |t| {
                    try self.registerAliasDisplayText(t, wanted_name);
                    return t;
                }
                if (try self.jsDocObjectSkeletonFromPropertyTags(src, body)) |t| {
                    try self.registerAliasDisplayText(t, wanted_name);
                    return t;
                }
            }
            const tags = ts_parser.jsdoc.parse(self.gpa, body) catch continue;
            defer self.gpa.free(tags);
            for (tags) |tag| {
                if (tag.kind != .typedef_tag) continue;
                if (!std.mem.eql(u8, tag.name, wanted_name)) continue;
                if (try self.jsDocObjectSkeletonFromTypeText(tag.type_text)) |t| {
                    try self.registerAliasDisplayText(t, wanted_name);
                    return t;
                }
                if (try self.jsDocObjectSkeletonFromPropertyTags(src, body)) |t| {
                    try self.registerAliasDisplayText(t, wanted_name);
                    return t;
                }
            }
        }
        return null;
    }

    fn jsDocObjectSkeletonFromPropertyTags(self: *Checker, src: []const u8, body: []const u8) CheckError!?TypeId {
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        const has_template = blk: {
            const tags = ts_parser.jsdoc.parse(self.gpa, body) catch break :blk false;
            defer self.gpa.free(tags);
            for (tags) |tag| {
                if (tag.kind == .template_tag and tag.name.len > 0) break :blk true;
            }
            break :blk false;
        };
        var line_start: usize = 0;
        var i: usize = 0;
        while (i <= body.len) : (i += 1) {
            const at_end = i == body.len;
            if (!at_end and body[i] != '\n') continue;
            var line = std.mem.trim(u8, body[line_start..i], " \t\r");
            line_start = i + 1;
            if (line.len > 0 and line[0] == '*') {
                line = std.mem.trim(u8, line[1..], " \t\r");
            }
            const tag_len: usize = if (std.mem.startsWith(u8, line, "@property"))
                "@property".len
            else if (std.mem.startsWith(u8, line, "@prop"))
                "@prop".len
            else
                continue;
            var rest = std.mem.trim(u8, line[tag_len..], " \t\r");
            var type_text: []const u8 = "";
            if (rest.len > 0 and rest[0] == '{') {
                const type_len = jsDocBalancedBraceLen(rest);
                if (type_len == 0) continue;
                type_text = rest[1 .. type_len - 1];
                rest = std.mem.trim(u8, rest[type_len..], " \t\r");
            } else {
                var name_len: usize = 0;
                if (rest.len > 0 and rest[0] == '[') {
                    const close = std.mem.indexOfScalar(u8, rest, ']') orelse continue;
                    name_len = close + 1;
                } else {
                    while (name_len < rest.len and isJsDocIdentChar(rest[name_len])) : (name_len += 1) {}
                }
                if (name_len == 0) continue;
                const after_name = std.mem.trim(u8, rest[name_len..], " \t\r");
                if (after_name.len == 0 or after_name[0] != '{') continue;
                const type_len = jsDocBalancedBraceLen(after_name);
                if (type_len == 0) continue;
                type_text = after_name[1 .. type_len - 1];
                rest = std.mem.trim(u8, rest[0..name_len], " \t\r");
            }
            var optional = false;
            type_text = std.mem.trim(u8, type_text, " \t\r\n");
            if (type_text.len > 0 and type_text[type_text.len - 1] == '=') {
                optional = true;
                type_text = std.mem.trim(u8, type_text[0 .. type_text.len - 1], " \t\r\n");
            }
            const prop_t = if (!has_template and try self.topLevelJsDocTypedefPropertyIgnoresNarrow(type_text))
                (try self.jsDocUnresolvedSimpleNameToType(src, type_text, type_text)) orelse types.Primitive.any
            else
                (try self.jsDocTypeTextToType(src, type_text)) orelse types.Primitive.any;
            if (rest.len > 0 and rest[0] == '[') {
                optional = true;
                rest = rest[1..];
            }
            var name_end: usize = 0;
            while (name_end < rest.len and isJsDocIdentChar(rest[name_end])) : (name_end += 1) {}
            if (name_end == 0) continue;
            const name = self.string_interner.intern(rest[0..name_end]) catch return error.OutOfMemory;
            try members.append(self.gpa, .{
                .name = name,
                .type = prop_t,
                .is_optional = optional,
                .is_readonly = false,
                .is_method = false,
            });
        }
        if (members.items.len == 0) return null;
        return self.interner.internObjectType(members.items) catch return error.OutOfMemory;
    }

    fn topLevelJsDocTypedefPropertyIgnoresNarrow(self: *Checker, type_text: []const u8) CheckError!bool {
        const anchor = self.jsdoc_diagnostic_anchor;
        if (anchor == hir_mod.none_node_id or self.nodeIsInsideFunctionLike(anchor)) return false;
        if (type_text.len == 0 or !isJsDocIdentStart(type_text[0])) return false;
        for (type_text[1..]) |c| {
            if (!isJsDocIdentChar(c)) return false;
        }
        const name = self.string_interner.intern(type_text) catch return error.OutOfMemory;
        const narrow_t = self.lookupNarrow(name) orelse return false;
        if (narrow_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(narrow_t).is_type_parameter) return false;
        if (self.type_names.contains(name) or
            self.generic_aliases.contains(name) or
            self.class_instance_types.contains(name) or
            self.class_static_types.contains(name) or
            self.isBuiltinName(name))
        {
            return false;
        }
        return true;
    }

    fn jsDocTypedefAliasType(self: *Checker, src: []const u8, wanted_name: []const u8) CheckError!?TypeId {
        if (wanted_name.len == 0) return null;
        const wanted_id = self.string_interner.intern(wanted_name) catch return error.OutOfMemory;
        if (self.resolving_jsdoc_typedef_aliases.contains(wanted_id)) return types.Primitive.any;
        try self.resolving_jsdoc_typedef_aliases.put(self.gpa, wanted_id, {});
        defer _ = self.resolving_jsdoc_typedef_aliases.remove(wanted_id);

        var search_start: usize = 0;
        while (std.mem.indexOfPos(u8, src, search_start, "/**")) |start| {
            const body_start = start + 3;
            const end = std.mem.indexOfPos(u8, src, body_start, "*/") orelse return null;
            defer search_start = end + 2;
            const body = src[body_start..end];
            if (jsDocTypedefTypeText(body, wanted_name)) |type_text| {
                return try self.jsDocTypeTextToType(src, type_text);
            }
            const tags = ts_parser.jsdoc.parse(self.gpa, body) catch continue;
            defer self.gpa.free(tags);
            for (tags) |tag| {
                if (tag.kind != .typedef_tag) continue;
                if (!std.mem.eql(u8, tag.name, wanted_name)) continue;
                return try self.jsDocTypeTextToType(src, tag.type_text);
            }
        }
        return null;
    }

    fn jsDocTypedefTypeText(body: []const u8, wanted_name: []const u8) ?[]const u8 {
        const tag_pos = std.mem.indexOf(u8, body, "@typedef") orelse return null;
        const rest = body[tag_pos + "@typedef".len ..];
        const brace_pos = std.mem.indexOfScalar(u8, rest, '{') orelse return null;
        const type_len = jsDocBalancedBraceLen(rest[brace_pos..]);
        if (type_len == 0) return null;
        const trailing = std.mem.trim(u8, rest[brace_pos + type_len ..], " \t\r\n*");
        var name_end: usize = 0;
        while (name_end < trailing.len and isJsDocIdentChar(trailing[name_end])) : (name_end += 1) {}
        if (name_end == 0) return null;
        if (name_end < trailing.len and (trailing[name_end] == '.' or trailing[name_end] == '~')) return null;
        if (!std.mem.eql(u8, trailing[0..name_end], wanted_name)) return null;
        return rest[brace_pos + 1 .. brace_pos + type_len - 1];
    }

    fn visibleJsDocTypedefNameExistsAt(self: *Checker, anchor: NodeId, name: hir_mod.StringId) bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        const src = self.source orelse return false;
        const wanted = self.string_interner.get(name);
        if (wanted.len == 0) return false;

        if (!self.sourceHasVirtualFilenameSections()) {
            if (!self.virtualSectionIsJsLike(anchor) and !self.pathIsJsLike(self.importer_path)) return false;
            return jsDocTypedefNameExistsInSlice(self.gpa, src, wanted);
        }

        var section_start: usize = 0;
        var line_start: usize = 0;
        while (line_start < src.len) {
            const line_end = std.mem.indexOfScalarPos(u8, src, line_start, '\n') orelse src.len;
            const line = src[line_start..line_end];
            const marker = std.mem.indexOf(u8, line, "@filename:") orelse
                (std.mem.indexOf(u8, line, "@Filename:") orelse null);
            if (marker) |m| {
                if (section_start < line_start and self.jsDocTypedefNameExistsInJsLikeSection(src, section_start, line_start, wanted)) return true;
                section_start = line_start;
                const filename = std.mem.trim(u8, line[m + "@filename:".len ..], " \t\r");
                if (self.pathIsJsLike(filename)) {
                    const next_start = if (line_end == src.len) src.len else line_end + 1;
                    var scan = next_start;
                    while (scan < src.len) {
                        const next_end = std.mem.indexOfScalarPos(u8, src, scan, '\n') orelse src.len;
                        const next_line = src[scan..next_end];
                        if (std.mem.indexOf(u8, next_line, "@filename:") != null or
                            std.mem.indexOf(u8, next_line, "@Filename:") != null)
                        {
                            break;
                        }
                        if (next_end == src.len) {
                            scan = src.len;
                            break;
                        }
                        scan = next_end + 1;
                    }
                    if (jsDocTypedefNameExistsInSlice(self.gpa, src[line_start..scan], wanted)) return true;
                }
            }
            if (line_end == src.len) break;
            line_start = line_end + 1;
        }
        if (section_start < src.len and self.jsDocTypedefNameExistsInJsLikeSection(src, section_start, src.len, wanted)) return true;
        return false;
    }

    fn jsDocTypedefNameExistsInJsLikeSection(self: *Checker, src: []const u8, start: usize, end: usize, wanted: []const u8) bool {
        if (start >= end or end > src.len) return false;
        const line_end = std.mem.indexOfScalarPos(u8, src, start, '\n') orelse end;
        const line = src[start..@min(line_end, end)];
        const marker = std.mem.indexOf(u8, line, "@filename:") orelse
            (std.mem.indexOf(u8, line, "@Filename:") orelse return false);
        const filename = std.mem.trim(u8, line[marker + "@filename:".len ..], " \t\r");
        if (!self.pathIsJsLike(filename)) return false;
        return jsDocTypedefNameExistsInSlice(self.gpa, src[start..end], wanted);
    }

    fn jsDocTypedefNameExistsInSlice(gpa: std.mem.Allocator, src: []const u8, wanted: []const u8) bool {
        var search_start: usize = 0;
        while (std.mem.indexOfPos(u8, src, search_start, "/**")) |start| {
            const body_start = start + 3;
            const end = std.mem.indexOfPos(u8, src, body_start, "*/") orelse return false;
            search_start = end + 2;
            const body = src[body_start..end];
            if (jsDocTypedefTypeText(body, wanted) != null) return true;
            const tags = ts_parser.jsdoc.parse(gpa, body) catch continue;
            defer gpa.free(tags);
            for (tags) |tag| {
                if (tag.kind == .typedef_tag and std.mem.eql(u8, tag.name, wanted)) return true;
            }
        }
        return false;
    }

    fn jsDocTypedefNamePosInSlice(gpa: std.mem.Allocator, src: []const u8, wanted: []const u8) ?usize {
        var search_start: usize = 0;
        while (std.mem.indexOfPos(u8, src, search_start, "/**")) |start| {
            const body_start = start + 3;
            const end = std.mem.indexOfPos(u8, src, body_start, "*/") orelse return null;
            search_start = end + 2;
            const body = src[body_start..end];
            if (jsDocTypedefNamePosInBody(body, wanted)) |rel| return body_start + rel;
            const tags = ts_parser.jsdoc.parse(gpa, body) catch continue;
            defer gpa.free(tags);
            for (tags) |tag| {
                if (tag.kind != .typedef_tag or !std.mem.eql(u8, tag.name, wanted)) continue;
                if (std.mem.indexOf(u8, body, tag.name)) |rel| return body_start + rel;
            }
        }
        return null;
    }

    fn jsDocTypedefNamePosInBody(body: []const u8, wanted: []const u8) ?usize {
        var search_start: usize = 0;
        while (std.mem.indexOfPos(u8, body, search_start, "@typedef")) |tag_pos| {
            search_start = tag_pos + "@typedef".len;
            var type_start = search_start;
            while (type_start < body.len and jsDocTriviaByte(body[type_start])) : (type_start += 1) {}
            if (type_start >= body.len or body[type_start] != '{') continue;
            const type_len = jsDocBalancedBraceLen(body[type_start..]);
            if (type_len == 0) continue;
            var name_offset = type_start + type_len;
            while (name_offset < body.len and jsDocTriviaByte(body[name_offset])) : (name_offset += 1) {}
            var name_end: usize = 0;
            while (name_offset + name_end < body.len and isJsDocIdentChar(body[name_offset + name_end])) : (name_end += 1) {}
            if (name_end == wanted.len and std.mem.eql(u8, body[name_offset .. name_offset + name_end], wanted)) return name_offset;
        }
        return null;
    }

    fn jsDocTriviaByte(c: u8) bool {
        return c == ' ' or c == '\t' or c == '\r' or c == '\n' or c == '*';
    }

    fn jsDocBlockHasNamedTag(body: []const u8, tag: []const u8, wanted_name: []const u8) bool {
        var line_start: usize = 0;
        var i: usize = 0;
        while (i <= body.len) : (i += 1) {
            const at_end = i == body.len;
            if (!at_end and body[i] != '\n') continue;
            var line = std.mem.trim(u8, body[line_start..i], " \t\r");
            line_start = i + 1;
            if (line.len > 0 and line[0] == '*') line = std.mem.trim(u8, line[1..], " \t\r");
            if (!std.mem.startsWith(u8, line, tag)) continue;
            var rest = std.mem.trim(u8, line[tag.len..], " \t\r");
            if (rest.len > 0 and rest[0] == '{') {
                const type_len = jsDocBalancedBraceLen(rest);
                if (type_len == 0) continue;
                rest = std.mem.trim(u8, rest[type_len..], " \t\r");
            }
            var name_end: usize = 0;
            while (name_end < rest.len and isJsDocIdentChar(rest[name_end])) : (name_end += 1) {}
            if (name_end == wanted_name.len and std.mem.eql(u8, rest[0..name_end], wanted_name)) return true;
        }
        return false;
    }

    fn jsDocBalancedBraceLen(s: []const u8) usize {
        if (s.len == 0 or s[0] != '{') return 0;
        var depth: i32 = 1;
        var i: usize = 1;
        while (i < s.len) : (i += 1) {
            if (s[i] == '{') depth += 1;
            if (s[i] == '}') {
                depth -= 1;
                if (depth == 0) return i + 1;
            }
        }
        return 0;
    }

    fn jsDocSatisfiesTypeForExpression(self: *Checker, node: NodeId) CheckError!?TypeId {
        const src = self.source orelse return null;
        if (!self.sourceHasCheckJsDirective()) return null;
        const jsdoc = self.jsDocSatisfiesBodyForExpression(src, node) orelse return null;
        const type_text = jsDocBlockTagBracedTypeText(jsdoc.body, "@satisfies") orelse return null;
        return try self.jsDocTypeTextToTypeAt(src, type_text, node);
    }

    fn jsDocSatisfiesBodyForExpression(self: *Checker, src: []const u8, node: NodeId) ?JsDocBody {
        const span = self.hir.spanOf(node);
        if (self.leadingJsDocBodyBeforeExpressionWithStart(src, span.start)) |jsdoc| return jsdoc;
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return null;
        const pk = self.hir.kindOf(parent);
        if (pk != .var_decl and pk != .let_decl and pk != .const_decl) return null;
        if (hir_mod.varDeclOf(self.hir, parent).init != node) return null;
        return self.leadingJsDocBodyWithStart(src, self.hir.spanOf(parent).start);
    }

    fn jsDocSatisfiesTagPosition(self: *Checker, node: NodeId) ?u32 {
        const src = self.source orelse return null;
        const jsdoc = self.jsDocSatisfiesBodyForExpression(src, node) orelse return null;
        const offset = std.mem.indexOf(u8, jsdoc.body, "@satisfies") orelse return null;
        return @intCast(jsdoc.start + offset + 1);
    }

    fn jsDocSatisfiesUsesDeclarationTag(self: *Checker, node: NodeId) bool {
        const src = self.source orelse return false;
        const selected = self.jsDocSatisfiesBodyForExpression(src, node) orelse return false;
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return false;
        const kind = self.hir.kindOf(parent);
        if (kind != .var_decl and kind != .let_decl and kind != .const_decl) return false;
        if (hir_mod.varDeclOf(self.hir, parent).init != node) return false;
        const declaration = self.leadingJsDocBodyWithStart(src, self.hir.spanOf(parent).start) orelse return false;
        return selected.start == declaration.start;
    }

    /// TS gathers an initializer's inline JSDoc tags before the declaration's
    /// leading tags. Preserve that ordering so repeated declaration tags and
    /// declaration-plus-inline tags both anchor TS1223 on the same tag as TS.
    fn checkJsDocDuplicateSatisfies(self: *Checker, decl: NodeId) CheckError!void {
        if (!self.sourceHasCheckJsDirective()) return;
        if (!self.virtualSectionIsJsLike(decl)) return;
        const src = self.source orelse return;
        const declaration_jsdoc = self.leadingJsDocBodyWithStart(src, self.hir.spanOf(decl).start);
        const initializer = hir_mod.varDeclOf(self.hir, decl).init;

        var saw_tag = false;
        if (initializer != hir_mod.none_node_id) {
            if (self.leadingJsDocBodyBeforeExpressionWithStart(src, self.hir.spanOf(initializer).start)) |inline_jsdoc| {
                if (declaration_jsdoc == null or inline_jsdoc.start != declaration_jsdoc.?.start) {
                    try self.reportDuplicateJsDocSatisfiesTags(decl, inline_jsdoc, &saw_tag);
                }
            }
        }
        if (declaration_jsdoc) |jsdoc| {
            try self.reportDuplicateJsDocSatisfiesTags(decl, jsdoc, &saw_tag);
        }
    }

    fn reportDuplicateJsDocSatisfiesTags(
        self: *Checker,
        decl: NodeId,
        jsdoc: JsDocBody,
        saw_tag: *bool,
    ) CheckError!void {
        const tag = "@satisfies";
        var search: usize = 0;
        while (std.mem.indexOfPos(u8, jsdoc.body, search, tag)) |at| {
            search = at + tag.len;
            if (at > 0 and isJsDocIdentChar(jsdoc.body[at - 1])) continue;
            if (search < jsdoc.body.len and isJsDocIdentChar(jsdoc.body[search])) continue;
            if (!saw_tag.*) {
                saw_tag.* = true;
                continue;
            }
            try self.reportAt(
                decl,
                @intCast(jsdoc.start + at + 1),
                TsCodes.jsdoc_satisfies_already_specified,
                "'satisfies' tag already specified.",
            );
        }
    }

    fn checkJsDocSatisfiesExpression(self: *Checker, node: NodeId, expr_t: TypeId) CheckError!void {
        if (self.hir.kindOf(node) == .satisfies_expr) return;
        const target_t = (try self.jsDocSatisfiesTypeForExpression(node)) orelse return;
        const diag_start = self.diagnostics.items.len;
        try self.checkSatisfiesExpressionAgainstTarget(node, expr_t, target_t);
        if (self.diagnostics.items.len == diag_start and self.hir.kindOf(node) == .object_literal) {
            try self.checkFiniteKeySatisfiesExcessProperties(node, target_t);
        }
        var ok = self.engine.isAssignableTo(expr_t, target_t) catch false;
        if (!ok and self.hir.kindOf(node) == .object_literal) {
            ok = try self.jsDocObjectLiteralMembersSatisfyTarget(node, target_t);
        }
        if (ok and
            self.hir.kindOf(node) == .object_literal and
            self.objectLiteralNeedsIndexerValidation(target_t))
        {
            ok = self.objectLiteralAssignableToTarget(node, expr_t, target_t) catch false;
        }
        // tsgo reports declaration-tag object property/excess diagnostics but
        // does not synthesize the inline-expression fallback for missing keys.
        if (!ok and
            self.diagnostics.items.len == diag_start and
            self.hir.kindOf(node) == .object_literal and
            self.jsDocSatisfiesUsesDeclarationTag(node))
        {
            ok = true;
        }
        if (!ok and self.diagnostics.items.len == diag_start) {
            if (try self.allocSimpleTypeName(expr_t)) |src_name| {
                if (try self.allocSimpleTypeName(target_t)) |dst_name| {
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Type '{s}' does not satisfy the expected type '{s}'.",
                        .{ src_name, dst_name },
                    );
                    try self.reportAt(
                        node,
                        self.jsDocSatisfiesTagPosition(node) orelse self.hir.spanOf(node).start,
                        TsCodes.satisfies_constraint,
                        msg,
                    );
                    return;
                }
            }
            try self.reportAt(
                node,
                self.jsDocSatisfiesTagPosition(node) orelse self.hir.spanOf(node).start,
                TsCodes.satisfies_constraint,
                "Type does not satisfy the expected constraint.",
            );
        }
    }

    fn jsDocObjectLiteralMembersSatisfyTarget(self: *Checker, expr: NodeId, target_t: TypeId) CheckError!bool {
        if (target_t < types.Primitive.first_dynamic or target_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(target_t);
        if (flags.is_union) {
            for (self.interner.unionMembers(target_t)) |member| {
                if (try self.jsDocObjectLiteralMembersSatisfyTarget(expr, member)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(target_t)) |member| {
                if (self.thisTypeMarkerConstraint(member) != null) continue;
                if (!try self.jsDocObjectLiteralMembersSatisfyTarget(expr, member)) return false;
            }
            return true;
        }
        if (!flags.is_object_type) return false;

        for (self.interner.objectMembers(target_t)) |member| {
            const value = self.findObjectLiteralPropValue(expr, member.name) orelse {
                if (member.is_optional) continue;
                return false;
            };
            if (try self.literalExpressionAssignableToTarget(value, member.type)) continue;
            const value_t = if (self.hir.typeOf(value) != types.Primitive.none)
                self.hir.typeOf(value)
            else
                try self.checkExpression(value);
            if (self.hir.kindOf(value) == .object_literal and
                try self.jsDocObjectLiteralMembersSatisfyTarget(value, member.type))
            {
                continue;
            }
            if (self.isArgumentAssignableToParam(value, value_t, member.type) catch false) continue;
            if (try self.checkerAssignableTo(value_t, member.type)) continue;
            return false;
        }
        return true;
    }

    fn checkFiniteKeySatisfiesExcessProperties(self: *Checker, expr: NodeId, target_t: TypeId) CheckError!void {
        if (target_t < types.Primitive.first_dynamic or target_t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(target_t);
        if (!flags.is_object_type) return;
        if (self.interner.objectMembers(target_t).len == 0) return;
        const string_idx = self.interner.objectStringIndex(target_t);
        if (string_idx == types.Primitive.none or !self.typeIsAnyLike(string_idx)) return;
        for (hir_mod.objectLiteralProps(self.hir, expr)) |p| {
            if (self.hir.kindOf(p) != .object_property) continue;
            const op = hir_mod.objectPropertyOf(self.hir, p);
            const name = self.propertyNameFromKeyNode(op.key) orelse continue;
            if ((try self.excessPropertyTargetMemberType(target_t, name)) != null) continue;
            try self.reportSatisfiesExcessProperty(p, name, target_t);
        }
    }

    fn checkFiniteRecordSatisfiesExcessPropertiesFromTypeNode(
        self: *Checker,
        expr: NodeId,
        type_node: NodeId,
        target_t: TypeId,
    ) CheckError!bool {
        if (self.hir.kindOf(expr) != .object_literal) return false;
        var keys: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer keys.deinit(self.gpa);
        if (!try self.collectFiniteRecordKeysFromTypeNode(type_node, &keys, 0)) return false;
        if (keys.count() == 0) return false;
        const target_text = self.typeNodeDiagnosticText(type_node);
        for (hir_mod.objectLiteralProps(self.hir, expr)) |p| {
            if (self.hir.kindOf(p) != .object_property) continue;
            const op = hir_mod.objectPropertyOf(self.hir, p);
            const name = self.propertyNameFromKeyNode(op.key) orelse continue;
            if (keys.contains(name)) continue;
            if (target_text) |text| {
                try self.reportSatisfiesExcessPropertyWithText(p, name, text);
            } else {
                try self.reportSatisfiesExcessProperty(p, name, target_t);
            }
        }
        return true;
    }

    fn collectFiniteRecordKeysFromTypeNode(
        self: *Checker,
        type_node: NodeId,
        keys: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
        depth: u8,
    ) CheckError!bool {
        if (depth > 6 or type_node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(type_node) != .type_ref) return false;
        const tr = hir_mod.typeRefOf(self.hir, type_node);
        if (tr.qualifier_len != 0) return false;
        const name = self.string_interner.get(tr.name);
        const args = hir_mod.typeRefArgs(self.hir, type_node);
        if ((std.mem.eql(u8, name, "Partial") or
            std.mem.eql(u8, name, "Required") or
            std.mem.eql(u8, name, "Readonly")) and
            args.len == 1)
        {
            return try self.collectFiniteRecordKeysFromTypeNode(args[0], keys, depth + 1);
        }
        if (!std.mem.eql(u8, name, "Record") or args.len < 1) return false;
        const key_t = try self.lowererLowerWithTypeParams(args[0]);
        return try self.collectFiniteRecordKeysFromType(key_t, keys);
    }

    fn collectFiniteRecordKeysFromType(
        self: *Checker,
        key_t: TypeId,
        keys: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
    ) CheckError!bool {
        if (key_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(key_t);
        if (flags.is_union) {
            var saw_key = false;
            for (self.interner.unionMembers(key_t)) |member| {
                const before = keys.count();
                if (!try self.collectFiniteRecordKeysFromType(member, keys)) return false;
                if (keys.count() != before) saw_key = true;
            }
            return saw_key;
        }
        if (try self.propertyNameFromLiteralType(key_t)) |name| {
            try keys.put(self.gpa, name, {});
            return true;
        }
        return false;
    }

    fn typeNodeDiagnosticText(self: *Checker, type_node: NodeId) ?[]const u8 {
        const src = self.source orelse return null;
        if (type_node == hir_mod.none_node_id) return null;
        const span = self.hir.spanOf(type_node);
        if (span.start >= span.end or span.end > src.len) return null;
        return std.mem.trim(u8, src[span.start..span.end], " \t\r\n");
    }

    fn leadingJsDocBodyBeforeExpressionWithStart(self: *Checker, src: []const u8, expr_start: u32) ?JsDocBody {
        _ = self;
        const limit = @min(@as(usize, expr_start), src.len);
        const before = src[0..limit];
        const end = std.mem.lastIndexOf(u8, before, "*/") orelse return null;
        const between = std.mem.trim(u8, before[end + 2 ..], " \t\r\n");
        for (between) |c| {
            if (c != '(') return null;
        }
        const start = std.mem.lastIndexOf(u8, before[0..end], "/**") orelse return null;
        return .{
            .body = before[start + 3 .. end],
            .start = start + 3,
        };
    }

    fn jsDocBlockTagTypeText(body: []const u8, tag: []const u8) ?[]const u8 {
        const tag_pos = std.mem.indexOf(u8, body, tag) orelse return null;
        const rest_raw = body[tag_pos + tag.len ..];
        var rest_start: usize = 0;
        while (rest_start < rest_raw.len and
            (rest_raw[rest_start] == ' ' or rest_raw[rest_start] == '\t' or
                rest_raw[rest_start] == '\r' or rest_raw[rest_start] == '\n' or
                rest_raw[rest_start] == '*')) : (rest_start += 1)
        {}
        const rest = rest_raw[rest_start..];
        if (rest.len == 0) return null;
        if (rest[0] == '{') {
            const type_len = jsDocBalancedBraceLen(rest);
            if (type_len == 0) return null;
            return rest[1 .. type_len - 1];
        }
        var end: usize = 0;
        while (end < rest.len and rest[end] != '\n' and rest[end] != '\r') : (end += 1) {}
        return std.mem.trim(u8, rest[0..end], " \t");
    }

    fn jsDocBlockTagBracedTypeText(body: []const u8, tag: []const u8) ?[]const u8 {
        const tag_pos = std.mem.indexOf(u8, body, tag) orelse return null;
        const rest_raw = body[tag_pos + tag.len ..];
        var rest_start: usize = 0;
        while (rest_start < rest_raw.len and
            (rest_raw[rest_start] == ' ' or rest_raw[rest_start] == '\t' or
                rest_raw[rest_start] == '\r' or rest_raw[rest_start] == '\n' or
                rest_raw[rest_start] == '*')) : (rest_start += 1)
        {}
        const rest = rest_raw[rest_start..];
        if (rest.len == 0 or rest[0] != '{') return null;
        const type_len = jsDocBalancedBraceLen(rest);
        if (type_len == 0) return null;
        return rest[1 .. type_len - 1];
    }

    fn jsDocQuotedString(type_text: []const u8) ?[]const u8 {
        if (type_text.len < 2) return null;
        const quote = type_text[0];
        if (quote != '\'' and quote != '"') return null;
        if (type_text[type_text.len - 1] != quote) return null;
        return type_text[1 .. type_text.len - 1];
    }

    fn jsDocTrimOuterParens(raw: []const u8) []const u8 {
        var text = raw;
        while (text.len >= 2 and text[0] == '(' and text[text.len - 1] == ')') {
            const close = jsDocMatchingParen(text, 0) orelse break;
            if (close != text.len - 1) break;
            text = std.mem.trim(u8, text[1 .. text.len - 1], " \t\r\n");
        }
        return text;
    }

    fn jsDocTypeTextIsUniqueSymbol(type_text: []const u8) bool {
        return std.mem.eql(u8, jsDocTrimOuterParens(type_text), "unique symbol");
    }

    const JsDocTopLevelSplitter = struct {
        text: []const u8,
        delim: u8,
        index: usize = 0,

        fn init(text: []const u8, delim: u8) JsDocTopLevelSplitter {
            return .{ .text = text, .delim = delim };
        }

        fn next(self: *JsDocTopLevelSplitter) ?[]const u8 {
            if (self.index > self.text.len) return null;
            var paren_depth: i32 = 0;
            var brace_depth: i32 = 0;
            var angle_depth: i32 = 0;
            var quote: u8 = 0;
            const start = self.index;
            var i = self.index;
            while (i < self.text.len) : (i += 1) {
                const c = self.text[i];
                if (quote != 0) {
                    if (c == '\\') {
                        i += 1;
                    } else if (c == quote) {
                        quote = 0;
                    }
                    continue;
                }
                if (c == '\'' or c == '"') {
                    quote = c;
                    continue;
                }
                switch (c) {
                    '(' => paren_depth += 1,
                    ')' => {
                        if (paren_depth > 0) paren_depth -= 1;
                    },
                    '{' => brace_depth += 1,
                    '}' => {
                        if (brace_depth > 0) brace_depth -= 1;
                    },
                    '<' => angle_depth += 1,
                    '>' => {
                        if (angle_depth > 0) angle_depth -= 1;
                    },
                    else => {},
                }
                if (c == self.delim and paren_depth == 0 and brace_depth == 0 and angle_depth == 0) {
                    self.index = i + 1;
                    return std.mem.trim(u8, self.text[start..i], " \t\r\n");
                }
            }
            self.index = self.text.len + 1;
            return std.mem.trim(u8, self.text[start..], " \t\r\n");
        }
    };

    fn jsDocSplitTopLevelAny(type_text: []const u8, delim: u8) bool {
        var split = JsDocTopLevelSplitter.init(type_text, delim);
        _ = split.next() orelse return false;
        return split.next() != null;
    }

    fn jsDocTopLevelOpenAngle(type_text: []const u8) ?usize {
        var paren_depth: i32 = 0;
        var brace_depth: i32 = 0;
        var quote: u8 = 0;
        for (type_text, 0..) |c, i| {
            if (quote != 0) {
                if (c == quote) quote = 0;
                continue;
            }
            if (c == '\'' or c == '"') {
                quote = c;
                continue;
            }
            switch (c) {
                '(' => paren_depth += 1,
                ')' => {
                    if (paren_depth > 0) paren_depth -= 1;
                },
                '{' => brace_depth += 1,
                '}' => {
                    if (brace_depth > 0) brace_depth -= 1;
                },
                '<' => if (paren_depth == 0 and brace_depth == 0) return i,
                else => {},
            }
        }
        return null;
    }

    /// Parse a single literal index-signature object type
    /// `{ [k: string]: V }` / `{ [k: number]: V }` to an object type with the
    /// corresponding index signature. Returns null if `type_text` is not that
    /// shape. Used for `@typedef {{[k: string]: any}} Name`.
    fn jsDocLiteralIndexSignatureType(self: *Checker, type_text: []const u8) CheckError!?TypeId {
        const tb = std.mem.trim(u8, type_text, " \t\r\n");
        if (tb.len < 2 or tb[0] != '{' or tb[tb.len - 1] != '}') return null;
        const inner = std.mem.trim(u8, tb[1 .. tb.len - 1], " \t\r\n");
        if (inner.len == 0 or inner[0] != '[') return null;
        const rb = std.mem.indexOfScalar(u8, inner, ']') orelse return null;
        const key_part = inner[1..rb];
        const after = std.mem.trim(u8, inner[rb + 1 ..], " \t\r\n");
        if (after.len < 2 or after[0] != ':') return null;
        // A second member after the index signature (`; foo: T`) isn't this
        // simple shape — defer to the general scanner.
        if (std.mem.indexOfScalar(u8, after, ';') != null or std.mem.indexOfScalar(u8, after, ',') != null) return null;
        const value_text = std.mem.trim(u8, after[1..], " \t\r\n");
        if (value_text.len == 0) return null;
        const value_t = (try self.jsDocTypeTextToType(self.source orelse "", value_text)) orelse types.Primitive.any;
        const key_is_number = std.mem.indexOf(u8, key_part, "number") != null;
        if (key_is_number) {
            return self.interner.internObjectTypeWithIndex(&.{}, types.Primitive.none, value_t) catch return error.OutOfMemory;
        }
        return self.interner.internObjectTypeWithIndex(&.{}, value_t, types.Primitive.none) catch return error.OutOfMemory;
    }

    fn jsDocObjectBodyIndexSignatureType(self: *Checker, object_body: []const u8) CheckError!?TypeId {
        var line_start: usize = 0;
        var i: usize = 0;
        while (i <= object_body.len) : (i += 1) {
            const at_end = i == object_body.len;
            if (!at_end and object_body[i] != '\n') continue;
            var line = std.mem.trim(u8, object_body[line_start..i], " \t\r");
            line_start = i + 1;
            if (line.len > 0 and line[0] == '*') {
                line = std.mem.trim(u8, line[1..], " \t\r");
            }
            if (line.len == 0 or line[0] != '[') continue;
            const rb = jsDocMatchingBracket(line, 0) orelse continue;
            const key_part = std.mem.trim(u8, line[1..rb], " \t\r");
            const after = std.mem.trim(u8, line[rb + 1 ..], " \t\r");
            if (after.len == 0 or after[0] != ':') continue;
            var value_text = std.mem.trim(u8, after[1..], " \t\r");
            if (value_text.len > 0 and value_text[value_text.len - 1] == ';') {
                value_text = std.mem.trim(u8, value_text[0 .. value_text.len - 1], " \t\r");
            }
            if (value_text.len == 0) return null;
            const value_t = (try self.jsDocTypeTextToType(self.source orelse "", value_text)) orelse types.Primitive.any;
            if (std.mem.indexOf(u8, key_part, "number") != null) {
                return self.interner.internObjectTypeWithIndexAndSymbol(&.{}, types.Primitive.none, value_t, types.Primitive.none) catch return error.OutOfMemory;
            }
            if (std.mem.indexOf(u8, key_part, "symbol") != null) {
                return self.interner.internObjectTypeWithIndexAndSymbol(&.{}, types.Primitive.none, types.Primitive.none, value_t) catch return error.OutOfMemory;
            }
            if (std.mem.indexOf(u8, key_part, "string") != null) {
                return self.interner.internObjectTypeWithIndexAndSymbol(&.{}, value_t, types.Primitive.none, types.Primitive.none) catch return error.OutOfMemory;
            }
        }
        return null;
    }

    fn jsDocMappedTypeTextToType(self: *Checker, src: []const u8, type_text: []const u8) CheckError!?TypeId {
        const trimmed_outer = std.mem.trim(u8, type_text, " \t\r\n");
        if (trimmed_outer.len < 6 or trimmed_outer[0] != '{' or trimmed_outer[trimmed_outer.len - 1] != '}') return null;
        var body = std.mem.trim(u8, trimmed_outer[1 .. trimmed_outer.len - 1], " \t\r\n");
        if (std.mem.startsWith(u8, body, "readonly")) {
            body = std.mem.trim(u8, body["readonly".len..], " \t\r\n");
        } else if (std.mem.startsWith(u8, body, "+readonly")) {
            body = std.mem.trim(u8, body["+readonly".len..], " \t\r\n");
        } else if (std.mem.startsWith(u8, body, "-readonly")) {
            body = std.mem.trim(u8, body["-readonly".len..], " \t\r\n");
        }
        if (body.len < 5 or body[0] != '[') return null;

        const close_bracket = jsDocMatchingBracket(body, 0) orelse return null;
        const key_clause = std.mem.trim(u8, body[1..close_bracket], " \t\r\n");
        const in_pos = jsDocMappedInPosition(key_clause) orelse return null;
        const key_name_text = std.mem.trim(u8, key_clause[0..in_pos], " \t\r\n");
        if (!isJsIdentifier(key_name_text)) return null;
        var constraint_text = std.mem.trim(u8, key_clause[in_pos + "in".len ..], " \t\r\n");
        if (jsDocMappedAsPosition(constraint_text)) |as_pos| {
            constraint_text = std.mem.trim(u8, constraint_text[0..as_pos], " \t\r\n");
        }
        if (constraint_text.len == 0) return null;

        var after = std.mem.trim(u8, body[close_bracket + 1 ..], " \t\r\n");
        var is_optional = false;
        if (after.len > 0 and after[0] == '?') {
            is_optional = true;
            after = std.mem.trim(u8, after[1..], " \t\r\n");
        }
        if (after.len == 0 or after[0] != ':') return null;
        var value_text = std.mem.trim(u8, after[1..], " \t\r\n");
        if (value_text.len > 0 and value_text[value_text.len - 1] == ';') {
            value_text = std.mem.trim(u8, value_text[0 .. value_text.len - 1], " \t\r\n");
        }
        if (value_text.len == 0) return null;

        const key_name = self.string_interner.intern(key_name_text) catch return error.OutOfMemory;
        const constraint_t = (try self.jsDocTypeTextToType(src, constraint_text)) orelse return null;
        var keys: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer keys.deinit(self.gpa);
        if (!self.collectStringLiteralKeys(constraint_t, &keys) or keys.items.len == 0) {
            const key_tp = self.interner.internFreshTypeParameterWithFlags(
                key_name,
                constraint_t,
                types.Primitive.none,
                .bivariant,
                false,
            ) catch return error.OutOfMemory;
            try self.pushNarrowScope();
            defer self.popNarrowScope();
            try self.recordNarrow(key_name, key_tp);
            const template_t = (try self.jsDocTypeTextToType(src, value_text)) orelse types.Primitive.any;
            return self.interner.internMapped(
                constraint_t,
                template_t,
                .none,
                if (is_optional) .add else .none,
            ) catch return error.OutOfMemory;
        }

        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        for (keys.items) |key| {
            const key_lit = self.interner.internStringLiteral(key) catch return error.OutOfMemory;
            try self.pushNarrowScope();
            const value_t = value: {
                defer self.popNarrowScope();
                try self.recordNarrow(key_name, key_lit);
                break :value (try self.jsDocTypeTextToType(src, value_text)) orelse types.Primitive.any;
            };
            try members.append(self.gpa, .{
                .name = key,
                .type = value_t,
                .is_optional = is_optional,
                .is_readonly = false,
                .is_method = false,
            });
        }
        const obj_t = self.interner.internObjectType(members.items) catch return error.OutOfMemory;
        const display = try std.fmt.allocPrint(self.diag_arena.allocator(), "{{ {s}; }}", .{body});
        try self.registerAliasDisplayText(obj_t, display);
        return obj_t;
    }

    fn jsDocMappedInPosition(text: []const u8) ?usize {
        var i: usize = 0;
        while (std.mem.indexOfPos(u8, text, i, "in")) |pos| {
            const before_ok = pos == 0 or std.ascii.isWhitespace(text[pos - 1]);
            const after = pos + "in".len;
            const after_ok = after >= text.len or std.ascii.isWhitespace(text[after]);
            if (before_ok and after_ok) return pos;
            i = pos + "in".len;
        }
        return null;
    }

    fn jsDocMappedAsPosition(text: []const u8) ?usize {
        var i: usize = 0;
        while (std.mem.indexOfPos(u8, text, i, "as")) |pos| {
            const before_ok = pos == 0 or std.ascii.isWhitespace(text[pos - 1]);
            const after = pos + "as".len;
            const after_ok = after >= text.len or std.ascii.isWhitespace(text[after]);
            if (before_ok and after_ok) return pos;
            i = pos + "as".len;
        }
        return null;
    }

    fn jsDocMatchingBracket(text: []const u8, open_idx: usize) ?usize {
        if (open_idx >= text.len or text[open_idx] != '[') return null;
        var depth: i32 = 1;
        var quote: u8 = 0;
        var i: usize = open_idx + 1;
        while (i < text.len) : (i += 1) {
            const c = text[i];
            if (quote != 0) {
                if (c == '\\') {
                    i += 1;
                } else if (c == quote) {
                    quote = 0;
                }
                continue;
            }
            if (c == '\'' or c == '"') {
                quote = c;
                continue;
            }
            if (c == '[') depth += 1;
            if (c == ']') {
                depth -= 1;
                if (depth == 0) return i;
            }
        }
        return null;
    }

    fn jsDocObjectSkeletonFromTypeText(self: *Checker, type_text: []const u8) CheckError!?TypeId {
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);

        if (self.jsDocStringIndexerFromTypeText(type_text)) |value_t| {
            return self.interner.internObjectTypeWithIndex(&.{}, value_t, types.Primitive.none) catch return error.OutOfMemory;
        }

        // Literal index-signature object: `{ [k: string]: V }` / `{ [k: number]: V }`.
        // The member-line scan below skips `[`-led lines, so handle it here.
        if (try self.jsDocLiteralIndexSignatureType(type_text)) |idx_t| return idx_t;

        const trimmed_outer = std.mem.trim(u8, type_text, " \t\r\n");
        const is_inline_braced_object = trimmed_outer.len >= 2 and trimmed_outer[0] == '{' and trimmed_outer[trimmed_outer.len - 1] == '}';
        const object_body = if (is_inline_braced_object)
            std.mem.trim(u8, trimmed_outer[1 .. trimmed_outer.len - 1], " \t\r\n")
        else
            type_text;
        if (try self.jsDocObjectBodyIndexSignatureType(object_body)) |idx_t| return idx_t;
        var lines = std.mem.tokenizeAny(u8, object_body, "\n;,");
        while (lines.next()) |raw_line| {
            var line = std.mem.trim(u8, raw_line, " \t\r");
            if (line.len > 0 and line[0] == '*') {
                line = std.mem.trim(u8, line[1..], " \t\r");
            }
            if (line.len == 0 or line[0] == '[' or line[0] == '}') continue;
            if (line[0] == '(') {
                const close = jsDocMatchingParen(line, 0) orelse continue;
                const rest = std.mem.trim(u8, line[close + 1 ..], " \t\r");
                if (rest.len == 0 or rest[0] != ':') continue;
                var params: std.ArrayListUnmanaged(TypeId) = .empty;
                defer params.deinit(self.gpa);
                var omittable: std.ArrayListUnmanaged(bool) = .empty;
                defer omittable.deinit(self.gpa);
                var has_rest = false;
                var split = JsDocTopLevelSplitter.init(line[1..close], ',');
                while (split.next()) |raw_param| {
                    const param = std.mem.trim(u8, raw_param, " \t\r");
                    if (param.len == 0) continue;
                    has_rest = has_rest or jsDocFunctionParamIsRest(param);
                    const param_type_text = jsDocFunctionParamNormalizeTypeText(jsDocFunctionParamTypeText(param));
                    const param_t = (try self.jsDocTypeTextToType(self.source orelse "", param_type_text)) orelse types.Primitive.any;
                    try params.append(self.gpa, param_t);
                    try omittable.append(self.gpa, jsDocFunctionParamIsOmittable(param));
                }
                const ret_text = std.mem.trim(u8, rest[1..], " \t\r");
                const ret_t = if (ret_text.len > 0)
                    (try self.jsDocTypeTextToType(self.source orelse "", ret_text)) orelse types.Primitive.any
                else
                    types.Primitive.any;
                const call_name = self.string_interner.intern("__call") catch return error.OutOfMemory;
                const sig_t = self.interner.internSignature(params.items, ret_t, false) catch return error.OutOfMemory;
                try self.recordJsDocSignatureArity(sig_t, omittable.items, has_rest);
                try members.append(self.gpa, .{
                    .name = call_name,
                    .type = sig_t,
                    .is_optional = false,
                    .is_readonly = false,
                    .is_method = true,
                });
                continue;
            }
            if (!isJsDocIdentStart(line[0])) continue;
            var name_end: usize = 1;
            while (name_end < line.len and isJsDocIdentChar(line[name_end])) : (name_end += 1) {}
            const after_name = std.mem.trim(u8, line[name_end..], " \t");
            if (after_name.len == 0) continue;
            if (after_name[0] == '(') {
                const close = jsDocMatchingParen(after_name, 0) orelse continue;
                const rest = std.mem.trim(u8, after_name[close + 1 ..], " \t\r");
                if (rest.len == 0 or rest[0] != ':') continue;
                var params: std.ArrayListUnmanaged(TypeId) = .empty;
                defer params.deinit(self.gpa);
                var omittable: std.ArrayListUnmanaged(bool) = .empty;
                defer omittable.deinit(self.gpa);
                var has_rest = false;
                var split = JsDocTopLevelSplitter.init(after_name[1..close], ',');
                while (split.next()) |raw_param| {
                    const param = std.mem.trim(u8, raw_param, " \t\r");
                    if (param.len == 0) continue;
                    has_rest = has_rest or jsDocFunctionParamIsRest(param);
                    const param_type_text = jsDocFunctionParamNormalizeTypeText(jsDocFunctionParamTypeText(param));
                    const param_t = (try self.jsDocTypeTextToType(self.source orelse "", param_type_text)) orelse types.Primitive.any;
                    try params.append(self.gpa, param_t);
                    try omittable.append(self.gpa, jsDocFunctionParamIsOmittable(param));
                }
                const ret_text = std.mem.trim(u8, rest[1..], " \t\r");
                const ret_t = if (ret_text.len > 0)
                    (try self.jsDocTypeTextToType(self.source orelse "", ret_text)) orelse types.Primitive.any
                else
                    types.Primitive.any;
                const name = self.string_interner.intern(line[0..name_end]) catch return error.OutOfMemory;
                const sig_t = self.interner.internSignature(params.items, ret_t, false) catch return error.OutOfMemory;
                try self.recordJsDocSignatureArity(sig_t, omittable.items, has_rest);
                try members.append(self.gpa, .{
                    .name = name,
                    .type = sig_t,
                    .is_optional = false,
                    .is_readonly = false,
                    .is_method = true,
                });
                continue;
            }
            const is_optional = std.mem.startsWith(u8, after_name, "?:");
            const type_start: usize = if (is_optional)
                2
            else if (after_name[0] == ':')
                1
            else
                continue;
            const member_type_text = std.mem.trim(u8, after_name[type_start..], " \t\r");
            const name = self.string_interner.intern(line[0..name_end]) catch return error.OutOfMemory;
            const prop_t = if (is_inline_braced_object and member_type_text.len > 0)
                (try self.jsDocTypeTextToType(self.source orelse "", member_type_text)) orelse types.Primitive.unknown
            else
                types.Primitive.unknown;
            try members.append(self.gpa, .{
                .name = name,
                .type = prop_t,
                .is_optional = is_optional,
                .is_readonly = false,
                .is_method = false,
            });
        }

        if (members.items.len == 0) return null;
        const obj_t = self.interner.internObjectType(members.items) catch return error.OutOfMemory;
        if (is_inline_braced_object) {
            if (try self.allocAnonymousObjectName(obj_t)) |display| {
                try self.registerAliasDisplayText(obj_t, display);
            }
        }
        return obj_t;
    }

    fn jsDocStringIndexerFromTypeText(self: *Checker, type_text: []const u8) ?TypeId {
        _ = self;
        const trimmed = std.mem.trim(u8, type_text, " \t\r\n");
        if (std.mem.eql(u8, trimmed, "Object.<string,string>") or
            std.mem.eql(u8, trimmed, "Object.<string, string>") or
            std.mem.eql(u8, trimmed, "Object<string,string>") or
            std.mem.eql(u8, trimmed, "Object<string, string>") or
            std.mem.eql(u8, trimmed, "Record<string,string>") or
            std.mem.eql(u8, trimmed, "Record<string, string>"))
        {
            return types.Primitive.string_t;
        }
        if (std.mem.eql(u8, trimmed, "Object.<string,number>") or
            std.mem.eql(u8, trimmed, "Object.<string, number>") or
            std.mem.eql(u8, trimmed, "Object<string,number>") or
            std.mem.eql(u8, trimmed, "Object<string, number>") or
            std.mem.eql(u8, trimmed, "Record<string,number>") or
            std.mem.eql(u8, trimmed, "Record<string, number>"))
        {
            return types.Primitive.number_t;
        }
        return null;
    }

    fn isJsDocIdentStart(c: u8) bool {
        return (c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or c == '_' or c == '$';
    }

    fn isJsDocIdentChar(c: u8) bool {
        return isJsDocIdentStart(c) or (c >= '0' and c <= '9');
    }

    /// Returns true when `name` is a private-identifier (a leading `#`
    /// followed by a valid identifier body, e.g. `#foo`, `#_bar`).
    /// Used wherever a diagnostic rule applies to both public and
    /// private class members.
    fn isPrivateIdentifierName(name: []const u8) bool {
        if (name.len < 2 or name[0] != '#') return false;
        return isJsIdentifier(name[1..]);
    }

    /// Returns true when `name` is a valid ECMAScript identifier
    /// (ASCII subset that covers everything tsc renders unquoted in
    /// diagnostics like `Property 'X' is missing in type ...`).
    fn isJsIdentifier(name: []const u8) bool {
        if (name.len == 0) return false;
        if (!isJsDocIdentStart(name[0])) return false;
        var i: usize = 1;
        while (i < name.len) : (i += 1) {
            if (!isJsDocIdentChar(name[i])) return false;
        }
        return true;
    }

    fn isAllDigits(name: []const u8) bool {
        if (name.len == 0) return false;
        for (name) |c| {
            if (c < '0' or c > '9') return false;
        }
        return true;
    }

    fn checkRepeatedVarDeclaration(self: *Checker, node: NodeId, final_type: TypeId) CheckError!void {
        if (self.hir.kindOf(node) != .var_decl) return;
        const v = hir_mod.varDeclOf(self.hir, node);
        if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) return;
        if (final_type == types.Primitive.none) return;
        if (v.type_annotation != hir_mod.none_node_id and
            self.typeAnnotationContainsUnresolvedRef(v.type_annotation)) return;
        const id = hir_mod.identifierOf(self.hir, v.name);
        if (try self.checkGlobalSymbolConstructorVarMerge(node)) return;
        if (try self.checkGlobalPromiseConstructorVarMerge(node, final_type)) return;
        // `var` bindings hoist to the enclosing function-like (or
        // module / namespace / source-file) scope, so we walk past
        // intervening block/if/for/while/switch/try statements when
        // selecting the dedup key. Without this, sibling `var x`
        // declarations in distinct then/else blocks (and other
        // statement bodies) failed to flag TS2403 because their
        // parentOf() was the block ÃÂ¢ÃÂÃÂ not the hoist scope. See
        // typeGuardOfFormTypeOfEqualEqualHasNoEffect.ts and the rest
        // of the typeGuards conformance cluster.
        const scope = self.enclosingVarDeclScope(node);
        if (scope == hir_mod.none_node_id) return;
        const key: VarDeclKey = .{
            .scope = scope,
            .name = id.name,
            .virtual_section_start = self.repeatedVarVirtualSectionKey(node),
        };
        const has_jsdoc_type = (try self.jsDocTypeForVarDecl(node)) != null;
        const has_annotation = v.type_annotation != hir_mod.none_node_id or has_jsdoc_type;
        const current_jsdoc_type_name: ?hir_mod.StringId = if (self.varDeclLeadingJsDocTypeText(node)) |type_text|
            self.string_interner.intern(std.mem.trim(u8, type_text, " \t\r\n")) catch return error.OutOfMemory
        else
            null;
        const self_ref_inferred_any = !has_annotation and
            final_type == types.Primitive.any and
            v.init != hir_mod.none_node_id and
            try self.varInitializerReferencesOwnBinding(v.init, id.name);
        const current_asserted_inferred = !has_annotation and self.varDeclInitializerPinsRepeatedVarType(node);
        if (self.var_decl_types.get(key)) |prior| {
            const prior_explicit = self.var_decl_explicit.get(key) orelse false;
            const prior_js_like = self.var_decl_js_like.get(key) orelse false;
            const prior_annotation = self.var_decl_annotation_nodes.get(key) orelse hir_mod.none_node_id;
            const prior_jsdoc_type_name = self.var_decl_jsdoc_type_names.get(key);
            const qualified_private_text_mismatch = try self.sameTailQualifiedAnnotationMismatch(prior_annotation, v.type_annotation);
            if (final_type == types.Primitive.any and
                (!has_annotation or (self.varDeclAnnotationIsQualifiedName(v.type_annotation) and qualified_private_text_mismatch == null))) return;
            if (prior == types.Primitive.any and !prior_explicit and has_annotation) return;
            if (prior == types.Primitive.any and !prior_explicit and !has_annotation) return;
            var annotation_text_mismatch: ?VarAnnotationTextPair = null;
            // Historically we bailed when neither declaration had an
            // explicit annotation (unless the prior was enum-nominal).
            // Upstream tsc emits TS2403 whenever the inferred types
            // disagree under control-flow narrowing ÃÂ¢ÃÂÃÂ e.g. sibling
            // `var r1 = strOrNum` declarations in different then/else
            // branches that narrow to `string` / `number`. The
            // compatibility check below already handles the common
            // `var x = 1; var x = 2;` case (both widen to `number` ÃÂ¢ÃÂÃÂ
            // identical ÃÂ¢ÃÂÃÂ no diag), so unconditionally falling through
            // is safe and unlocks the typeGuards conformance cluster.
            const compatible = blk: {
                const merges_checkjs_callable_container =
                    prior_js_like != self.virtualSectionIsJsLike(node) and
                    self.sourceHasCheckJsDirective() and
                    self.nonConstructCallSignatureOfType(prior) != null;
                if (merges_checkjs_callable_container) break :blk true;
                if (prior_jsdoc_type_name) |prior_name| {
                    if (current_jsdoc_type_name) |current_name| {
                        const prior_text = self.string_interner.get(prior_name);
                        const current_text = self.string_interner.get(current_name);
                        const object_wrapper_mismatch =
                            (std.mem.eql(u8, prior_text, "object") and std.mem.eql(u8, current_text, "Object")) or
                            (std.mem.eql(u8, prior_text, "Object") and std.mem.eql(u8, current_text, "object"));
                        if (object_wrapper_mismatch) {
                            annotation_text_mismatch = .{ .prior = prior_text, .current = current_text };
                            break :blk false;
                        }
                    }
                }
                if (prior_explicit and has_annotation) {
                    if (qualified_private_text_mismatch) |texts| {
                        annotation_text_mismatch = texts;
                        break :blk false;
                    }
                    if (try self.sameGenericAliasAnnotationArgMismatch(prior_annotation, v.type_annotation)) |texts| {
                        annotation_text_mismatch = texts;
                        break :blk false;
                    }
                    if (try self.mappedAnnotationModifierMismatch(prior_annotation, v.type_annotation)) |texts| {
                        annotation_text_mismatch = texts;
                        break :blk false;
                    }
                }
                // Identical interned types are trivially the same type —
                // no TS2403 mismatch is possible. This must precede the
                // `this`-type guard below: a redeclared `var r = cond ? t : u`
                // whose two initializers infer the SAME union (e.g. `T | U`)
                // interns to one TypeId, and that shared type can carry a
                // `this`-parameter constituent that would otherwise trip the
                // guard and emit a spurious "must be of type 'this', but here
                // has type 'this'." (subtypesOfTypeParameterWithConstraints4).
                if (prior == final_type) {
                    if (try self.conditionalAnnotationDistributionMismatch(prior_annotation, v.type_annotation)) |texts| {
                        annotation_text_mismatch = texts;
                        break :blk false;
                    }
                    break :blk true;
                }
                if (!prior_explicit and !has_annotation) {
                    const widened_prior = try self.widenFreshLiteralType(prior);
                    const widened_current = try self.widenFreshLiteralType(final_type);
                    if ((widened_prior != prior or widened_current != final_type) and
                        widened_prior == widened_current)
                    {
                        break :blk true;
                    }
                    if (try self.repeatedObjectLiteralEvolvingNullCompatible(node, prior, final_type)) {
                        break :blk true;
                    }
                }
                if (self.repeatedVarCallableParameterCountMismatch(prior, final_type)) break :blk false;
                if ((self.isThisTypeParameter(prior) or self.isThisTypeParameter(final_type)) and
                    try self.repeatedVarAssertedInferredTypesCompatible(prior, final_type)) break :blk true;
                if (!prior_explicit and
                    !has_annotation and
                    v.init != hir_mod.none_node_id and
                    self.hir.kindOf(v.init) == .conditional and
                    (self.isThisTypeParameter(prior) or self.isThisTypeParameter(final_type)) and
                    self.repeatedVarConditionalThisTypesCompatible(prior, final_type))
                {
                    break :blk true;
                }
                if (self.isThisTypeParameter(prior) or self.isThisTypeParameter(final_type)) break :blk false;
                if (self.repeatedVarThisArrayNullishMismatch(prior, final_type)) break :blk false;
                if (self.repeatedVarUnknownArrayElementMismatch(prior, final_type)) break :blk false;
                if (self.typeContainsUnknown(final_type)) {
                    // An inferred bare `unknown` does not satisfy an
                    // earlier explicit `var` declaration. Contextual
                    // signature instantiation deliberately returns
                    // unknown when its candidates conflict, and tsc then
                    // reports TS2403 against the explicit declaration.
                    if (prior_explicit and !has_annotation and final_type == types.Primitive.unknown) break :blk false;
                    break :blk true;
                }
                if ((prior == types.Primitive.any or final_type == types.Primitive.any) and prior != final_type) break :blk false;
                if (self.repeatedVarTypesHaveDifferentPrivateOrigins(prior, final_type)) break :blk false;
                if (try self.repeatedVarConditionalsCompatible(prior, final_type)) |ok| break :blk ok;
                if (try self.conditionalAnnotationDistributionMismatch(prior_annotation, v.type_annotation)) |texts| {
                    annotation_text_mismatch = texts;
                    break :blk false;
                }
                if (current_asserted_inferred and
                    !try self.repeatedVarAssertedInferredTypesCompatible(prior, final_type) and
                    !try self.repeatedVarObjectMembersIdentical(prior, final_type)) break :blk false;
                if (self.repeatedVarArrayElementMismatch(prior, final_type)) break :blk false;
                if (self.exactlyOneTypeIsUnion(prior, final_type)) break :blk false;
                if (try self.repeatedVarObjectMembersIdentical(prior, final_type)) break :blk true;
                if (self.engine.isIdenticalTo(prior, final_type) catch true) break :blk true;
                if ((self.engine.isAssignableTo(prior, final_type) catch true) and
                    (self.engine.isAssignableTo(final_type, prior) catch true)) break :blk true;
                const prior_flags = self.interner.pool.flagsOf(prior);
                const current_flags = self.interner.pool.flagsOf(final_type);
                if (prior_flags.is_object_type and current_flags.is_object_type) {
                    break :blk try self.checkerAssignableTo(prior, final_type) and
                        try self.checkerAssignableTo(final_type, prior);
                }
                break :blk false;
            };
            const namespace_fn_static_name = self.varInitNamespaceMergedFunctionName(node);
            const forced_namespace_fn_static_mismatch = namespace_fn_static_name != null and prior_explicit;
            if (!compatible) {
                const name = self.string_interner.get(id.name);
                // Suppress TS2403 when this variable already has a
                // TS2502 (`'X' is referenced directly or indirectly in
                // its own type annotation.`) emitted in this run ÃÂ¢ÃÂÃÂ
                // mirrors upstream tsc which emits only the more
                // fundamental TS2502 for recursive `typeof` chains
                // like `var f: typeof g; var g: typeof f;`. See
                // `recursiveTypesWithTypeof.ts`.
                if (self.varNameHasSelfReferencedTypeAnnotation(name)) return;
                const initializer_display = try self.repeatedVarInitializerDisplay(node);
                const prior_annotation_display = try self.repeatedVarPriorAnnotationDisplay(prior_explicit, prior_annotation, prior);
                const msg = if (annotation_text_mismatch) |texts|
                    try self.formatSubsequentVarTypeMismatchWithTexts(name, texts.prior, texts.current)
                else if (self.repeatedVarThisArrayNullishMismatch(prior, final_type))
                    try self.formatSubsequentVarTypeMismatchWithTexts(
                        name,
                        try self.formatThisArrayRepeatedVarType(prior),
                        try self.formatThisArrayRepeatedVarType(final_type),
                    )
                else if (try self.mappedAnnotationDisplayPair(prior_annotation, v.type_annotation)) |texts|
                    try self.formatSubsequentVarTypeMismatchWithTexts(name, texts.prior, texts.current)
                else if (initializer_display) |current_text|
                    if (prior_annotation_display) |prior_text|
                        try self.formatSubsequentVarTypeMismatchWithTexts(name, prior_text, current_text)
                    else
                        try self.formatSubsequentVarTypeMismatchWithCurrentText(name, prior, current_text)
                else if (prior_annotation_display) |prior_text|
                    if (try self.subsequentVarTypeText(final_type)) |current_text|
                        try self.formatSubsequentVarTypeMismatchWithTexts(name, prior_text, current_text)
                    else
                        try self.formatSubsequentVarTypeMismatch(name, prior, final_type)
                else
                    try self.formatSubsequentVarTypeMismatch(name, prior, final_type);
                try self.diagnostics.append(self.gpa, .{
                    .node = v.name,
                    .code = TsCodes.subsequent_var_type_mismatch,
                    .message = msg,
                });
            } else if (forced_namespace_fn_static_mismatch) {
                const name = self.string_interner.get(id.name);
                const static_name = namespace_fn_static_name.?;
                const current_text = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "typeof {s}",
                    .{self.string_interner.get(static_name)},
                );
                const msg = try self.formatSubsequentVarTypeMismatchWithCurrentText(name, prior, current_text);
                try self.diagnostics.append(self.gpa, .{
                    .node = v.name,
                    .code = TsCodes.subsequent_var_type_mismatch,
                    .message = msg,
                });
            }
            return;
        }
        try self.var_decl_types.put(self.gpa, key, final_type);
        try self.var_decl_explicit.put(self.gpa, key, has_annotation or self_ref_inferred_any);
        try self.var_decl_js_like.put(self.gpa, key, self.virtualSectionIsJsLike(node));
        if (current_jsdoc_type_name) |name| try self.var_decl_jsdoc_type_names.put(self.gpa, key, name);
        if (has_annotation) try self.var_decl_annotation_nodes.put(self.gpa, key, v.type_annotation);
    }

    fn repeatedObjectLiteralEvolvingNullCompatible(
        self: *Checker,
        node: NodeId,
        prior: TypeId,
        current: TypeId,
    ) CheckError!bool {
        const v = hir_mod.varDeclOf(self.hir, node);
        if (v.init == hir_mod.none_node_id or self.hir.kindOf(v.init) != .object_literal) return false;
        if (prior >= self.interner.pool.typeCount() or current >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(prior).is_object_type or !self.interner.pool.flagsOf(current).is_object_type) return false;

        var reads_evolving_null = false;
        for (hir_mod.objectLiteralProps(self.hir, v.init)) |prop_node| {
            if (self.hir.kindOf(prop_node) != .object_property) continue;
            const prop = hir_mod.objectPropertyOf(self.hir, prop_node);
            if (prop.value != hir_mod.none_node_id and
                self.hir.kindOf(prop.value) == .identifier and
                self.identifierIsUntypedUninitializedVar(prop.value))
            {
                reads_evolving_null = true;
                break;
            }
        }
        if (!reads_evolving_null) return false;

        const prior_members = self.interner.objectMembers(prior);
        const current_members = self.interner.objectMembers(current);
        if (prior_members.len != current_members.len) return false;
        for (prior_members) |prior_member| {
            var current_member: ?types.ObjectMember = null;
            for (current_members) |candidate| {
                if (candidate.name == prior_member.name) {
                    current_member = candidate;
                    break;
                }
            }
            const candidate = current_member orelse return false;
            if (candidate.is_optional != prior_member.is_optional or
                candidate.is_readonly != prior_member.is_readonly or
                candidate.is_method != prior_member.is_method)
            {
                return false;
            }
            if (candidate.type == prior_member.type) continue;
            const prior_non_null = self.widenLiteralType(try self.subtractNullUndefined(prior_member.type));
            const current_non_null = self.widenLiteralType(try self.subtractNullUndefined(candidate.type));
            if (prior_non_null == types.Primitive.never or current_non_null == types.Primitive.never) return false;
            if (prior_non_null == current_non_null) continue;
            if (!(self.engine.isIdenticalTo(prior_non_null, current_non_null) catch false)) return false;
        }
        return true;
    }

    fn repeatedVarCallableParameterCountMismatch(self: *Checker, prior: TypeId, current: TypeId) bool {
        const prior_sig = self.nonConstructCallSignatureOfType(prior) orelse return false;
        const current_sig = self.nonConstructCallSignatureOfType(current) orelse return false;
        return self.interner.signatureParams(prior_sig).len != self.interner.signatureParams(current_sig).len;
    }

    fn repeatedVarArrayElementMismatch(self: *Checker, prior: TypeId, current: TypeId) bool {
        if (prior >= self.interner.pool.typeCount() or current >= self.interner.pool.typeCount()) return false;
        if (self.interner.pool.flagsOf(prior).is_union or self.interner.pool.flagsOf(current).is_union) return false;
        if (!self.typeIsArrayLikeObject(prior) or !self.typeIsArrayLikeObject(current)) return false;
        const prior_element = self.interner.objectNumberIndex(prior);
        const current_element = self.interner.objectNumberIndex(current);
        return prior_element != types.Primitive.none and
            current_element != types.Primitive.none and
            prior_element != current_element and
            !(self.engine.isIdenticalTo(prior_element, current_element) catch false);
    }

    fn repeatedVarObjectMembersIdentical(self: *Checker, prior: TypeId, current: TypeId) CheckError!bool {
        if (prior >= self.interner.pool.typeCount() or current >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(prior).is_object_type or
            !self.interner.pool.flagsOf(current).is_object_type)
        {
            return false;
        }
        const prior_indexes = [_]TypeId{
            self.interner.objectStringIndex(prior),
            self.interner.objectNumberIndex(prior),
            self.interner.objectSymbolIndex(prior),
        };
        const current_indexes = [_]TypeId{
            self.interner.objectStringIndex(current),
            self.interner.objectNumberIndex(current),
            self.interner.objectSymbolIndex(current),
        };
        for (prior_indexes, current_indexes) |prior_index, current_index| {
            if (prior_index == types.Primitive.none or current_index == types.Primitive.none) {
                if (prior_index != current_index) return false;
            } else if (!(self.engine.isIdenticalTo(prior_index, current_index) catch false)) {
                return false;
            }
        }
        return try self.repeatedVarObjectMemberSetMatches(prior, current) and
            try self.repeatedVarObjectMemberSetMatches(current, prior);
    }

    fn repeatedVarObjectMemberSetMatches(self: *Checker, source: TypeId, target: TypeId) CheckError!bool {
        for (self.interner.objectMembers(source)) |source_member| {
            if (source_member.name == 0 or self.syntheticSignatureMemberName(source_member.name)) continue;
            const target_member = self.interner.objectMemberInfo(target, source_member.name) orelse return false;
            if (source_member.is_optional != target_member.is_optional or
                source_member.is_readonly != target_member.is_readonly or
                source_member.is_method != target_member.is_method)
            {
                return false;
            }
            if (self.engine.isIdenticalTo(source_member.type, target_member.type) catch false) continue;
            if (!try self.checkerAssignableTo(source_member.type, target_member.type) or
                !try self.checkerAssignableTo(target_member.type, source_member.type)) return false;
        }
        return true;
    }

    fn checkGlobalSymbolConstructorVarMerge(self: *Checker, node: NodeId) CheckError!bool {
        if (!self.isGlobalSymbolConstructorVarDecl(node)) return false;
        const v = hir_mod.varDeclOf(self.hir, node);
        if (v.type_annotation == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(v.type_annotation) == .type_ref) {
            const ref = hir_mod.typeRefOf(self.hir, v.type_annotation);
            if (ref.qualifier_len == 0 and
                std.mem.eql(u8, self.string_interner.get(ref.name), "SymbolConstructor"))
            {
                return true;
            }
        }
        const current_text = (try self.allocTypeAnnotationDiagnosticName(v.type_annotation, false)) orelse
            (try self.subsequentVarTypeText(self.hir.typeOf(node))) orelse
            "unknown";
        const msg = try self.formatSubsequentVarTypeMismatchWithTexts(
            "Symbol",
            "SymbolConstructor",
            current_text,
        );
        try self.diagnostics.append(self.gpa, .{
            .node = v.name,
            .code = TsCodes.subsequent_var_type_mismatch,
            .message = msg,
        });
        return true;
    }

    fn checkGlobalPromiseConstructorVarMerge(self: *Checker, node: NodeId, final_type: TypeId) CheckError!bool {
        if (self.hir.kindOf(node) != .var_decl or !self.nodeIsTopLevelOfSourceFile(node)) return false;
        if (self.sourceFileSectionIsModule(node)) return false;
        const v = hir_mod.varDeclOf(self.hir, node);
        if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, v.name);
        if (!std.mem.eql(u8, self.string_interner.get(id.name), "Promise")) return false;
        if (self.sourceHasNoLibTrueDirective()) return false;

        const has_lib_directive = if (self.source) |src| std.mem.indexOf(u8, src, "@lib") != null else false;
        const has_promise_constructor = if (has_lib_directive)
            !self.sourceLibDirectiveExcludes("es2015")
        else
            !self.sourceTargetExcludesLib("es2015");
        if (!has_promise_constructor) return false;

        if (v.type_annotation != hir_mod.none_node_id and self.hir.kindOf(v.type_annotation) == .type_ref) {
            const ref = hir_mod.typeRefOf(self.hir, v.type_annotation);
            if (ref.qualifier_len == 0 and
                std.mem.eql(u8, self.string_interner.get(ref.name), "PromiseConstructor"))
            {
                return true;
            }
        }

        const current_text = if (v.type_annotation != hir_mod.none_node_id)
            (try self.allocTypeAnnotationDiagnosticName(v.type_annotation, false)) orelse
                (try self.subsequentVarTypeText(final_type)) orelse
                "unknown"
        else
            (try self.subsequentVarTypeText(final_type)) orelse "unknown";
        const msg = try self.formatSubsequentVarTypeMismatchWithTexts(
            "Promise",
            "PromiseConstructor",
            current_text,
        );
        try self.diagnostics.append(self.gpa, .{
            .node = v.name,
            .code = TsCodes.subsequent_var_type_mismatch,
            .message = msg,
        });
        return true;
    }

    fn varDeclInitializerPinsRepeatedVarType(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) != .var_decl) return false;
        const v = hir_mod.varDeclOf(self.hir, node);
        if (v.init == hir_mod.none_node_id) return false;
        const init_k = self.hir.kindOf(v.init);
        return init_k == .as_expr or init_k == .type_assertion;
    }

    fn repeatedVarAssertedInferredTypesCompatible(self: *Checker, prior: TypeId, current: TypeId) CheckError!bool {
        if (prior == current) return true;
        const prior_text = (try self.allocSimpleTypeName(prior)) orelse return false;
        const current_text = (try self.allocSimpleTypeName(current)) orelse return false;
        return std.mem.eql(u8, prior_text, current_text);
    }

    fn repeatedVarConditionalThisTypesCompatible(self: *Checker, prior: TypeId, current: TypeId) bool {
        if (self.isThisTypeParameter(prior) and self.isThisTypeParameter(current)) return true;
        const other = if (self.isThisTypeParameter(prior)) current else prior;
        return other < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(other).is_type_parameter;
    }

    fn repeatedVarConditionalsCompatible(self: *Checker, prior: TypeId, current: TypeId) CheckError!?bool {
        const forward = (try self.deferredConditionalAssignableToConditional(prior, current)) orelse return null;
        if (!forward) return false;
        return (try self.deferredConditionalAssignableToConditional(current, prior)) orelse false;
    }

    fn repeatedVarVirtualSectionKey(self: *Checker, node: NodeId) usize {
        if (!self.sourceHasVirtualFilenameSections()) return 0;
        const section = self.virtualSectionStartForNode(node);
        const root = self.rootBlockFor(node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return section;
        return if (self.virtualSectionHasExternalModuleSyntax(root, section)) section else 0;
    }

    fn varInitNamespaceMergedFunctionName(self: *Checker, node: NodeId) ?hir_mod.StringId {
        if (self.hir.kindOf(node) != .var_decl) return null;
        const v = hir_mod.varDeclOf(self.hir, node);
        if (v.init == hir_mod.none_node_id or self.hir.kindOf(v.init) != .member_access) return null;
        const m = hir_mod.memberOf(self.hir, v.init);
        if (m.object == hir_mod.none_node_id or self.hir.kindOf(m.object) != .identifier) return null;
        const ns_name = hir_mod.identifierOf(self.hir, m.object).name;
        const member_name = m.name;
        var has_fn = false;
        var has_runtime_namespace = false;
        const root = self.rootBlockFor(node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |raw| {
            const ns_node = self.unwrapExportDecl(raw);
            if (self.hir.kindOf(ns_node) != .namespace_decl) continue;
            const ns = hir_mod.namespaceOf(self.hir, ns_node);
            if (ns.name == hir_mod.none_node_id or self.hir.kindOf(ns.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, ns.name).name != ns_name) continue;
            for (hir_mod.namespaceBody(self.hir, ns_node)) |member_raw| {
                if (self.hir.kindOf(member_raw) != .export_decl) continue;
                const member_node = self.unwrapExportDecl(member_raw);
                const decl_name = self.declarationName(member_node) orelse continue;
                if (decl_name != member_name) continue;
                switch (self.hir.kindOf(member_node)) {
                    .fn_decl, .fn_expr => has_fn = true,
                    .namespace_decl => {
                        if (self.namespaceHasRuntimeValue(member_node)) has_runtime_namespace = true;
                    },
                    else => {},
                }
            }
        }
        return if (has_fn and has_runtime_namespace) member_name else null;
    }

    /// Walk up the parent chain past control-flow statements
    /// (block / if / for / while / do-while / switch / try) until
    /// we hit a function-like, namespace/module, or source-file
    /// boundary. Matches `var` hoist semantics so two `var x`
    /// declarations in distinct then/else blocks dedup to the same
    /// key. Returns the immediate parent when no such boundary is
    /// reachable.
    fn enclosingVarDeclScope(self: *Checker, node: NodeId) NodeId {
        var cur = self.hir.parentOf(node);
        var last = cur;
        while (cur != hir_mod.none_node_id) {
            last = cur;
            switch (self.hir.kindOf(cur)) {
                .source_file,
                .fn_decl,
                .fn_expr,
                .arrow_fn,
                .namespace_decl,
                .module_decl,
                => return cur,
                .block_stmt,
                .if_stmt,
                .for_stmt,
                .for_in_stmt,
                .for_of_stmt,
                .while_stmt,
                .do_while_stmt,
                .switch_stmt,
                .try_stmt,
                .switch_case,
                => cur = self.hir.parentOf(cur),
                else => return cur,
            }
        }
        return last;
    }

    /// Scan accumulated diagnostics for a TS2502 whose message
    /// references `var_name`. Used to suppress TS2403 follow-on
    /// reports when the variable's own type annotation is already
    /// flagged as recursive ÃÂ¢ÃÂÃÂ upstream tsc never emits the
    /// subsequent-declaration mismatch on top of TS2502.
    fn varNameHasSelfReferencedTypeAnnotation(self: *Checker, var_name: []const u8) bool {
        for (self.diagnostics.items) |d| {
            if (d.code != TsCodes.self_referenced_type_annotation) continue;
            // TS2502 message shape: `'<name>' is referenced directly
            // or indirectly in its own type annotation.`
            if (d.message.len < var_name.len + 4) continue;
            if (d.message[0] != '\'') continue;
            if (!std.mem.eql(u8, d.message[1 .. 1 + var_name.len], var_name)) continue;
            if (d.message[1 + var_name.len] != '\'') continue;
            return true;
        }
        return false;
    }

    fn varDeclAnnotationIsQualifiedName(self: *Checker, type_annotation: NodeId) bool {
        if (type_annotation == hir_mod.none_node_id or self.hir.kindOf(type_annotation) != .type_ref) return false;
        return hir_mod.typeRefOf(self.hir, type_annotation).qualifier_len != 0;
    }

    /// TS2403: format the message body. When both `prior` and `current`
    /// have a renderable simple type name (primitive, named class /
    /// interface, enum nominal, or literal), match upstream tsc
    /// verbatim ÃÂ¢ÃÂÃÂ including the leading double-space after the period
    /// (`type.  Variable`). Otherwise fall back to the shorter
    /// conflicting-type form so we never half-render.
    fn formatSubsequentVarTypeMismatch(self: *Checker, name: []const u8, prior: TypeId, current: TypeId) ![]const u8 {
        // Prefer the simple primitive/enum/named-type renderer; fall
        // back to the richer `allocSimpleTypeName` to also pick up
        // tuple shapes (`[number]`, `[number, number]`) so fixtures
        // like `strictTupleLength.ts(11,5)` get the full upstream
        // wording rather than the conflicting-type fallback. Finally,
        // try `allocObjectTypeShape` so object-literal / union
        // mismatches (e.g. `spreadUnion2.ts` `{ a: number } | {}` vs
        // `{ a?: number | undefined; }`) render with the explicit
        // shape instead of the terse `conflicting type` fallback.
        const prior_text_opt = (try self.simpleDiagnosticTypeName(prior)) orelse
            (try self.allocSimpleTypeName(prior)) orelse
            (try self.allocObjectTypeShape(prior));
        const current_text_opt = (try self.reducedRepeatedVarArrayTypeText(current)) orelse
            (try self.simpleDiagnosticTypeName(current)) orelse
            (try self.allocSimpleTypeName(current)) orelse
            (try self.allocObjectTypeShape(current));
        if (prior_text_opt) |prior_text| {
            if (current_text_opt) |current_text| {
                return try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Subsequent variable declarations must have the same type.  Variable '{s}' must be of type '{s}', but here has type '{s}'.",
                    .{ name, prior_text, current_text },
                );
            }
        }
        return try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Subsequent variable declarations must have the same type. Variable '{s}' has a conflicting type.",
            .{name},
        );
    }

    fn subsequentVarTypeText(self: *Checker, t: TypeId) CheckError!?[]const u8 {
        if (try self.reducedRepeatedVarArrayTypeText(t)) |text| return text;
        if (t >= types.Primitive.first_dynamic and t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(t).is_object_type) {
            if (try self.allocObjectTypeShapeForRepeatedVar(t)) |shape| return shape;
        }
        return (try self.simpleDiagnosticTypeName(t)) orelse
            (try self.allocSimpleTypeName(t)) orelse
            (try self.allocObjectTypeShapeForRepeatedVar(t));
    }

    fn reducedRepeatedVarArrayTypeText(self: *Checker, t: TypeId) CheckError!?[]const u8 {
        if (!self.typeIsArrayLikeObject(t) or self.actualTupleLength(t) != null) return null;
        const element = self.interner.objectNumberIndex(t);
        if (element >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(element).is_union) return null;
        const reduced = try self.reduceRepeatedVarArrayElementUnion(element);
        if (reduced == element) return null;
        const element_text = (try self.allocSimpleTypeName(reduced)) orelse
            (try self.allocObjectTypeShapeForRepeatedVar(reduced)) orelse return null;
        const wrap = reduced < self.interner.pool.typeCount() and self.interner.pool.flagsOf(reduced).is_union;
        return if (wrap)
            try std.fmt.allocPrint(self.diag_arena.allocator(), "({s})[]", .{element_text})
        else
            try std.fmt.allocPrint(self.diag_arena.allocator(), "{s}[]", .{element_text});
    }

    fn reduceRepeatedVarArrayElementUnion(self: *Checker, element: TypeId) CheckError!TypeId {
        const members = self.interner.unionMembers(element);
        var kept: std.ArrayListUnmanaged(TypeId) = .empty;
        defer kept.deinit(self.gpa);
        try kept.appendSlice(self.gpa, members);

        var index = kept.items.len;
        while (index > 0) {
            index -= 1;
            const source = kept.items[index];
            for (kept.items, 0..) |target, target_index| {
                if (target_index == index) continue;
                if (!try self.checkerAssignableTo(source, target)) continue;
                if (try self.checkerAssignableTo(target, source)) continue;
                _ = kept.orderedRemove(index);
                break;
            }
        }
        if (kept.items.len == members.len) return element;
        if (kept.items.len == 1) return kept.items[0];
        return self.interner.internUnion(kept.items) catch error.OutOfMemory;
    }

    fn repeatedVarInitializerDisplay(self: *Checker, node: NodeId) CheckError!?[]const u8 {
        if (self.hir.kindOf(node) != .var_decl) return null;
        const variable = hir_mod.varDeclOf(self.hir, node);
        if (variable.init == hir_mod.none_node_id) return null;
        const name = switch (self.hir.kindOf(variable.init)) {
            .identifier => blk: {
                const identifier_name = hir_mod.identifierOf(self.hir, variable.init).name;
                const path = [_]hir_mod.StringId{identifier_name};
                if (self.findVisibleNamespaceByPath(variable.init, &path) == null) return null;
                break :blk identifier_name;
            },
            .member_access => blk: {
                const member = hir_mod.memberOf(self.hir, variable.init);
                if (member.object == hir_mod.none_node_id or self.hir.kindOf(member.object) != .identifier) return null;
                const namespace_name = hir_mod.identifierOf(self.hir, member.object).name;
                const path = [_]hir_mod.StringId{namespace_name};
                const namespace = self.findVisibleNamespaceByPath(variable.init, &path) orelse return null;
                const declaration = self.findExportedValueDeclInNamespace(namespace, member.name) orelse return null;
                const declaration_kind = self.hir.kindOf(declaration);
                if (declaration_kind != .class_decl and declaration_kind != .class_expr) return null;
                break :blk member.name;
            },
            else => return null,
        };
        return try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "typeof {s}",
            .{self.string_interner.get(name)},
        );
    }

    fn repeatedVarPriorAnnotationDisplay(
        self: *Checker,
        prior_explicit: bool,
        prior_node: NodeId,
        prior: TypeId,
    ) CheckError!?[]const u8 {
        if (!prior_explicit or prior_node == hir_mod.none_node_id) return null;
        return switch (self.hir.kindOf(prior_node)) {
            .union_type => blk: {
                if (prior < self.interner.pool.typeCount() and self.interner.pool.flagsOf(prior).is_union) {
                    var has_object_member = false;
                    for (self.interner.unionMembers(prior)) |member| {
                        if (member < self.interner.pool.typeCount() and self.interner.pool.flagsOf(member).is_object_type) {
                            has_object_member = true;
                            break;
                        }
                    }
                    if (!has_object_member) {
                        if (try self.allocSimpleTypeName(prior)) |name| break :blk name;
                    }
                }
                break :blk try self.allocTypeAnnotationDiagnosticName(prior_node, false);
            },
            .object_type, .typeof_type => try self.allocTypeAnnotationDiagnosticName(prior_node, false),
            else => null,
        };
    }

    fn formatSubsequentVarTypeMismatchWithCurrentText(self: *Checker, name: []const u8, prior: TypeId, current_text: []const u8) ![]const u8 {
        const prior_text_opt = (try self.simpleDiagnosticTypeName(prior)) orelse
            (try self.allocSimpleTypeName(prior)) orelse
            (try self.allocObjectTypeShape(prior));
        if (prior_text_opt) |prior_text| {
            return try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Subsequent variable declarations must have the same type.  Variable '{s}' must be of type '{s}', but here has type '{s}'.",
                .{ name, prior_text, current_text },
            );
        }
        return try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Subsequent variable declarations must have the same type. Variable '{s}' has a conflicting type.",
            .{name},
        );
    }

    fn formatSubsequentVarTypeMismatchWithTexts(self: *Checker, name: []const u8, prior_text: []const u8, current_text: []const u8) ![]const u8 {
        return try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Subsequent variable declarations must have the same type.  Variable '{s}' must be of type '{s}', but here has type '{s}'.",
            .{ name, prior_text, current_text },
        );
    }

    fn checkRepeatedObjectRestVarBinding(
        self: *Checker,
        pattern_node: NodeId,
        name_node: NodeId,
        name: hir_mod.StringId,
        final_type: TypeId,
    ) CheckError!void {
        const decl = self.hir.parentOf(pattern_node);
        if (decl == hir_mod.none_node_id or self.hir.kindOf(decl) != .var_decl) return;
        const scope = self.hir.parentOf(decl);
        if (scope == hir_mod.none_node_id) return;
        const prior = self.previousVarDeclTypeInScope(scope, decl, name) orelse return;
        if (self.repeatedVarTypesCompatible(prior, final_type)) return;
        const name_text = self.string_interner.get(name);
        const msg = try self.formatSubsequentVarTypeMismatch(name_text, prior, final_type);
        try self.diagnostics.append(self.gpa, .{
            .node = name_node,
            .code = TsCodes.subsequent_var_type_mismatch,
            .message = msg,
        });
    }

    fn previousVarDeclTypeInScope(self: *Checker, scope: NodeId, before_decl: NodeId, name: hir_mod.StringId) ?TypeId {
        const stmts: []const NodeId = switch (self.hir.kindOf(scope)) {
            .block_stmt => hir_mod.blockStmts(self.hir, scope),
            .namespace_decl => hir_mod.namespaceBody(self.hir, scope),
            else => return null,
        };
        for (stmts) |stmt| {
            if (stmt == before_decl) return null;
            const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
            if (decl == hir_mod.none_node_id) continue;
            const dk = self.hir.kindOf(decl);
            if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
            const v = hir_mod.varDeclOf(self.hir, decl);
            if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
            const id = hir_mod.identifierOf(self.hir, v.name);
            if (id.name != name) continue;
            const t = self.hir.typeOf(decl);
            if (t != types.Primitive.none) return t;
        }
        return null;
    }

    const VarAnnotationTextPair = struct {
        prior: []const u8,
        current: []const u8,
    };

    fn sameTailQualifiedAnnotationMismatch(self: *Checker, prior_node: NodeId, current_node: NodeId) CheckError!?VarAnnotationTextPair {
        if (prior_node == hir_mod.none_node_id or current_node == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(prior_node) != .type_ref or self.hir.kindOf(current_node) != .type_ref) return null;
        const prior_ref = hir_mod.typeRefOf(self.hir, prior_node);
        const current_ref = hir_mod.typeRefOf(self.hir, current_node);
        if (prior_ref.qualifier_len == 0 or current_ref.qualifier_len == 0) return null;
        if (prior_ref.name != current_ref.name) return null;
        const prior_qualifiers = self.hir.childSlice(prior_ref.qualifier_start, prior_ref.qualifier_len);
        const current_qualifiers = self.hir.childSlice(current_ref.qualifier_start, current_ref.qualifier_len);
        if (self.typeRefQualifiersNameEqual(prior_qualifiers, current_qualifiers)) return null;
        const tail = try self.diag_arena.allocator().dupe(u8, self.string_interner.get(prior_ref.name));
        return VarAnnotationTextPair{ .prior = tail, .current = tail };
    }

    fn typeRefQualifiersNameEqual(self: *Checker, prior: []const NodeId, current: []const NodeId) bool {
        if (prior.len != current.len) return false;
        for (prior, current) |a, b| {
            if (self.hir.kindOf(a) != .identifier or self.hir.kindOf(b) != .identifier) return false;
            if (hir_mod.identifierOf(self.hir, a).name != hir_mod.identifierOf(self.hir, b).name) return false;
        }
        return true;
    }

    fn mappedAnnotationModifierMismatch(
        self: *Checker,
        prior_node: NodeId,
        current_node: NodeId,
    ) CheckError!?VarAnnotationTextPair {
        if (prior_node == hir_mod.none_node_id or current_node == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(prior_node) != .mapped_type or self.hir.kindOf(current_node) != .mapped_type) return null;
        const prior = hir_mod.mappedTypeOf(self.hir, prior_node);
        const current = hir_mod.mappedTypeOf(self.hir, current_node);
        if (prior.readonly == current.readonly and prior.optional == current.optional) return null;
        return try self.mappedAnnotationDisplayPair(prior_node, current_node);
    }

    fn mappedAnnotationDisplayPair(
        self: *Checker,
        prior_node: NodeId,
        current_node: NodeId,
    ) CheckError!?VarAnnotationTextPair {
        const prior = (try self.mappedAnnotationDiagnosticName(prior_node)) orelse return null;
        const current = (try self.mappedAnnotationDiagnosticName(current_node)) orelse return null;
        return .{ .prior = prior, .current = current };
    }

    fn mappedAnnotationDiagnosticName(self: *Checker, node: NodeId) CheckError!?[]const u8 {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .mapped_type) return null;
        const mapped = hir_mod.mappedTypeOf(self.hir, node);
        if (mapped.type_param == hir_mod.none_node_id or self.hir.kindOf(mapped.type_param) != .type_parameter) return null;
        const type_param = hir_mod.typeParameterOf(self.hir, mapped.type_param);
        const constraint = (try self.allocTypeAnnotationDiagnosticName(mapped.constraint, false)) orelse return null;
        const value = (try self.allocTypeAnnotationDiagnosticName(mapped.value, false)) orelse return null;
        const arena = self.diag_arena.allocator();
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        try buf.appendSlice(arena, "{ ");
        if (mapped.readonly == 1) try buf.appendSlice(arena, "readonly ");
        if (mapped.readonly == 2) try buf.appendSlice(arena, "-readonly ");
        try buf.append(arena, '[');
        try buf.appendSlice(arena, self.string_interner.get(type_param.name));
        try buf.appendSlice(arena, " in ");
        try buf.appendSlice(arena, constraint);
        try buf.append(arena, ']');
        if (mapped.optional == 1) try buf.append(arena, '?');
        if (mapped.optional == 2) try buf.appendSlice(arena, "-?");
        try buf.appendSlice(arena, ": ");
        try buf.appendSlice(arena, value);
        if (mapped.optional == 1 and std.mem.indexOf(u8, value, "undefined") == null) {
            try buf.appendSlice(arena, " | undefined");
        }
        try buf.appendSlice(arena, "; }");
        return buf.items;
    }

    fn sameGenericAliasAnnotationArgMismatch(self: *Checker, prior_node: NodeId, current_node: NodeId) CheckError!?VarAnnotationTextPair {
        if (prior_node == hir_mod.none_node_id or current_node == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(prior_node) != .type_ref or self.hir.kindOf(current_node) != .type_ref) return null;
        const prior_ref = hir_mod.typeRefOf(self.hir, prior_node);
        const current_ref = hir_mod.typeRefOf(self.hir, current_node);
        if (prior_ref.qualifier_len != 0 or current_ref.qualifier_len != 0) return null;
        if (prior_ref.name != current_ref.name) return null;
        const prior_args = hir_mod.typeRefArgs(self.hir, prior_node);
        const current_args = hir_mod.typeRefArgs(self.hir, current_node);
        if (prior_args.len == 0 or prior_args.len != current_args.len) return null;

        for (prior_args, current_args) |prior_arg, current_arg| {
            const prior_t = self.lowererLowerWithTypeParams(prior_arg) catch return null;
            const current_t = self.lowererLowerWithTypeParams(current_arg) catch return null;
            if (prior_t == current_t) continue;
            if (self.engine.isIdenticalTo(prior_t, current_t) catch false) continue;
            const prior_text = self.annotationSourceText(prior_node) orelse return null;
            const current_text = self.annotationSourceText(current_node) orelse return null;
            return VarAnnotationTextPair{ .prior = prior_text, .current = current_text };
        }
        return null;
    }

    const ConditionalAnnotationInfo = struct {
        is_distributive: bool,
        display: []const u8,
    };

    fn conditionalAnnotationDistributionMismatch(self: *Checker, prior_node: NodeId, current_node: NodeId) CheckError!?VarAnnotationTextPair {
        const prior = (try self.conditionalAnnotationInfo(prior_node, 0)) orelse return null;
        const current = (try self.conditionalAnnotationInfo(current_node, 0)) orelse return null;
        if (prior.is_distributive == current.is_distributive) return null;
        return .{ .prior = prior.display, .current = current.display };
    }

    fn conditionalAnnotationInfo(self: *Checker, node: NodeId, depth: u8) CheckError!?ConditionalAnnotationInfo {
        if (node == hir_mod.none_node_id or depth > 8) return null;
        switch (self.hir.kindOf(node)) {
            .conditional_type => {
                return .{
                    .is_distributive = self.conditionalTypeNodeIsDistributive(node),
                    .display = self.annotationSourceText(node) orelse return null,
                };
            },
            .type_ref => {
                const r = hir_mod.typeRefOf(self.hir, node);
                if (r.qualifier_len != 0) return null;
                const body_node = if (self.generic_aliases.get(r.name)) |info|
                    info.body_node
                else blk: {
                    const decl = self.typeAliasDeclForNameAt(r.name, node) orelse return null;
                    const ta = hir_mod.typeAliasOf(self.hir, decl);
                    if (ta.type_params_len != 0) return null;
                    break :blk ta.aliased;
                };
                if (body_node == hir_mod.none_node_id) return null;
                if (self.hir.kindOf(body_node) == .conditional_type) {
                    return .{
                        .is_distributive = self.conditionalTypeNodeIsDistributive(body_node),
                        .display = self.annotationSourceText(node) orelse return null,
                    };
                }
                if (self.hir.kindOf(body_node) == .type_ref) {
                    const nested = (try self.conditionalAnnotationInfo(body_node, depth + 1)) orelse return null;
                    return .{
                        .is_distributive = nested.is_distributive,
                        .display = self.annotationSourceText(body_node) orelse nested.display,
                    };
                }
                return null;
            },
            else => return null,
        }
    }

    fn conditionalTypeNodeIsDistributive(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) != .conditional_type) return false;
        const c = hir_mod.conditionalTypeOf(self.hir, node);
        return switch (self.hir.kindOf(c.check)) {
            .identifier => true,
            .type_ref => blk: {
                const r = hir_mod.typeRefOf(self.hir, c.check);
                break :blk r.qualifier_len == 0 and r.args_len == 0;
            },
            else => false,
        };
    }

    fn annotationSourceText(self: *Checker, node: NodeId) ?[]const u8 {
        const src = self.source orelse return null;
        const sp = self.hir.spanOf(node);
        if (sp.start > sp.end or sp.end > src.len) return null;
        return std.mem.trim(u8, src[sp.start..sp.end], " \t\r\n");
    }

    fn repeatedVarTypesCompatible(self: *Checker, prior: TypeId, final_type: TypeId) bool {
        if (self.isThisTypeParameter(prior) or self.isThisTypeParameter(final_type)) return false;
        if (self.repeatedVarThisArrayNullishMismatch(prior, final_type)) return false;
        if (self.repeatedVarUnknownArrayElementMismatch(prior, final_type)) return false;
        if (self.typeContainsUnknown(final_type)) return true;
        if ((prior == types.Primitive.any or final_type == types.Primitive.any) and prior != final_type) return false;
        if (self.repeatedVarTypesHaveDifferentPrivateOrigins(prior, final_type)) return false;
        if (self.engine.isIdenticalTo(prior, final_type) catch true) return true;
        if (self.exactlyOneTypeIsUnion(prior, final_type)) return false;
        return (self.engine.isAssignableTo(prior, final_type) catch true) and
            (self.engine.isAssignableTo(final_type, prior) catch true);
    }

    fn repeatedVarUnknownArrayElementMismatch(self: *Checker, prior: TypeId, current: TypeId) bool {
        const prior_elem = self.interner.objectNumberIndex(prior);
        const current_elem = self.interner.objectNumberIndex(current);
        if (prior_elem == types.Primitive.none or current_elem == types.Primitive.none) return false;
        if (prior_elem == current_elem) return false;
        return current_elem == types.Primitive.unknown;
    }

    fn repeatedVarThisArrayNullishMismatch(self: *Checker, prior: TypeId, current: TypeId) bool {
        const prior_elem = self.interner.objectNumberIndex(prior);
        const current_elem = self.interner.objectNumberIndex(current);
        if (prior_elem == types.Primitive.none or current_elem == types.Primitive.none) return false;
        if (prior_elem == current_elem) return false;
        if (!self.containsThisTypeParameter(prior_elem) and !self.containsThisTypeParameter(current_elem)) return false;
        return self.typeIsOrUnionContains(prior_elem, types.Primitive.null_t) or
            self.typeIsOrUnionContains(prior_elem, types.Primitive.undefined_t) or
            self.typeIsOrUnionContains(current_elem, types.Primitive.null_t) or
            self.typeIsOrUnionContains(current_elem, types.Primitive.undefined_t);
    }

    fn typeIsOrUnionContains(self: *Checker, t: TypeId, needle: TypeId) bool {
        if (t == needle) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(t).is_union) return false;
        for (self.interner.unionMembers(t)) |member| {
            if (member == needle) return true;
        }
        return false;
    }

    fn formatThisArrayRepeatedVarType(self: *Checker, t: TypeId) CheckError![]const u8 {
        const elem = self.interner.objectNumberIndex(t);
        const elem_text = (try self.allocSimpleTypeName(elem)) orelse
            (try self.allocObjectTypeShapeWithUndefined(elem)) orelse
            "this";
        const elem_is_union = elem < self.interner.pool.typeCount() and self.interner.pool.flagsOf(elem).is_union;
        return if (elem_is_union)
            try std.fmt.allocPrint(self.diag_arena.allocator(), "({s})[]", .{elem_text})
        else
            try std.fmt.allocPrint(self.diag_arena.allocator(), "{s}[]", .{elem_text});
    }

    fn repeatedVarTypesHaveDifferentPrivateOrigins(self: *Checker, prior: TypeId, current: TypeId) bool {
        if (prior == current) return false;
        const prior_decl = self.class_decl_by_instance.get(prior);
        const current_decl = self.class_decl_by_instance.get(current);
        if (prior_decl != null and current_decl != null and prior_decl.? == current_decl.?) return false;
        if (self.classPrivateMemberSetsShareName(prior, current)) return true;
        return self.objectTypesSharePrivateMemberName(prior, current);
    }

    fn classPrivateMemberSetsShareName(self: *Checker, prior: TypeId, current: TypeId) bool {
        const prior_name = self.class_name_by_instance.get(prior) orelse return false;
        const current_name = self.class_name_by_instance.get(current) orelse return false;
        const prior_private = self.class_private_members.getPtr(prior_name) orelse return false;
        const current_private = self.class_private_members.getPtr(current_name) orelse return false;
        var it = prior_private.keyIterator();
        while (it.next()) |member_name| {
            if (current_private.contains(member_name.*)) return true;
        }
        return false;
    }

    fn objectTypesSharePrivateMemberName(self: *Checker, prior: TypeId, current: TypeId) bool {
        if (prior >= self.interner.pool.typeCount() or current >= self.interner.pool.typeCount()) return false;
        const prior_flags = self.interner.pool.flagsOf(prior);
        const current_flags = self.interner.pool.flagsOf(current);
        if (!prior_flags.is_object_type or !current_flags.is_object_type) return false;
        const prior_members = self.interner.objectMembers(prior);
        const current_members = self.interner.objectMembers(current);
        for (prior_members) |pm| {
            if (pm.visibility != .private) continue;
            for (current_members) |cm| {
                if (cm.visibility == .private and cm.name == pm.name) return true;
            }
        }
        return false;
    }

    fn exactlyOneTypeIsUnion(self: *Checker, a: TypeId, b: TypeId) bool {
        return self.typeIsUnion(a) != self.typeIsUnion(b);
    }

    fn typeIsUnion(self: *Checker, t: TypeId) bool {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return false;
        return self.interner.pool.flagsOf(t).is_union;
    }

    fn typeIsEnumNominal(self: *Checker, t: TypeId) bool {
        return self.enumNameFromNominal(t) != null;
    }

    fn enumNameFromNominal(self: *Checker, t: TypeId) ?hir_mod.StringId {
        if (self.enum_nominal_names.get(t)) |name| return name;
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_intersection) return null;
        if (flags.is_union) return null;
        const payload_idx = self.interner.pool.payloadOf(t);
        if (payload_idx >= self.interner.pool.intersection_payloads.items.len) return null;
        var saw_number = false;
        var enum_name: ?hir_mod.StringId = null;
        for (self.interner.intersectionMembers(t)) |member| {
            if (member == types.Primitive.number_t) {
                saw_number = true;
                continue;
            }
            if (member >= self.interner.pool.typeCount()) continue;
            if (!self.interner.pool.flagsOf(member).is_object_type) continue;
            for (self.interner.objectMembers(member)) |om| {
                const name = self.string_interner.getOptional(om.name) orelse continue;
                if (std.mem.startsWith(u8, name, "__enum:")) {
                    enum_name = self.string_interner.intern(name["__enum:".len..]) catch return null;
                    break;
                }
            }
        }
        return if (saw_number) enum_name else null;
    }

    fn enumIdentityInfo(self: *Checker, t: TypeId) ?EnumIdentityInfo {
        if (self.enumNameFromNominal(t)) |name| {
            return .{ .name = name, .decl = self.enum_nominal_decls.get(t) };
        }
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return null;
        if (self.interner.enumLiteralInfo(t)) |info| return .{ .name = info.enum_name };
        return null;
    }

    fn enumDeclsShareSiblingScope(self: *Checker, a: NodeId, b: NodeId) bool {
        const a_scope = self.enumSiblingScope(a) orelse return false;
        const b_scope = self.enumSiblingScope(b) orelse return false;
        return a_scope.container == b_scope.container;
    }

    fn enumMemberNameFromProperty(self: *Checker, member: NodeId) ?hir_mod.StringId {
        if (self.hir.kindOf(member) != .object_property) return null;
        const prop = hir_mod.objectPropertyOf(self.hir, member);
        return switch (self.hir.kindOf(prop.key)) {
            .identifier => hir_mod.identifierOf(self.hir, prop.key).name,
            .literal_string => hir_mod.literalStringOf(self.hir, prop.key).value,
            else => null,
        };
    }

    fn enumDeclMissingMemberInTarget(
        self: *Checker,
        source_decl: NodeId,
        target_decl: NodeId,
        enum_name: hir_mod.StringId,
    ) ?hir_mod.StringId {
        for (hir_mod.enumMembers(self.hir, source_decl)) |member| {
            const member_name = self.enumMemberNameFromProperty(member) orelse continue;
            if (!self.enumHasMemberInScope(target_decl, enum_name, member_name)) return member_name;
        }
        return null;
    }

    fn enumFirstMissingSourceMemberInTarget(
        self: *Checker,
        source_decl: NodeId,
        target_decl: NodeId,
        enum_name: hir_mod.StringId,
    ) ?hir_mod.StringId {
        if (self.enumDeclMissingMemberInTarget(source_decl, target_decl, enum_name)) |missing| return missing;
        const source_scope = self.enumSiblingScope(source_decl) orelse return null;
        for (source_scope.stmts) |sib_raw| {
            const sib = self.unwrapExportDecl(sib_raw);
            if (sib == source_decl) continue;
            if (self.hir.kindOf(sib) != .enum_decl) continue;
            const sib_name = self.declarationName(sib) orelse continue;
            if (sib_name != enum_name) continue;
            if (self.enumDeclMissingMemberInTarget(sib, target_decl, enum_name)) |missing| return missing;
        }
        return null;
    }

    fn enumRelationValueForMemberInDecl(
        self: *Checker,
        decl: NodeId,
        enum_name: hir_mod.StringId,
        wanted_member: hir_mod.StringId,
    ) CheckError!?EnumRelationValue {
        var next_numeric: ?f64 = 0;
        for (hir_mod.enumMembers(self.hir, decl)) |member| {
            if (self.hir.kindOf(member) != .object_property) continue;
            const prop = hir_mod.objectPropertyOf(self.hir, member);
            const member_name = self.enumMemberNameFromProperty(member) orelse continue;
            const value: EnumRelationValue = blk: {
                if (prop.value == hir_mod.none_node_id) {
                    if (next_numeric) |v| {
                        break :blk .{ .numeric = v };
                    }
                    break :blk .unknown_numeric;
                }
                if (try self.evalEnumStringExpressionInfo(enum_name, prop.value)) |info| {
                    break :blk .{ .string = info.value };
                }
                if (try self.evalEnumConstExpression(enum_name, prop.value)) |v| {
                    break :blk .{ .numeric = v };
                }
                break :blk .unknown_numeric;
            };
            switch (value) {
                .numeric => |v| next_numeric = v + 1,
                .string, .unknown_numeric => next_numeric = null,
            }
            if (member_name == wanted_member) return value;
        }
        return null;
    }

    fn enumRelationValueForMemberInScope(
        self: *Checker,
        decl: NodeId,
        enum_name: hir_mod.StringId,
        member_name: hir_mod.StringId,
    ) CheckError!?EnumRelationValue {
        if (try self.enumRelationValueForMemberInDecl(decl, enum_name, member_name)) |value| return value;
        const scope = self.enumSiblingScope(decl) orelse return null;
        for (scope.stmts) |sib_raw| {
            const sib = self.unwrapExportDecl(sib_raw);
            if (sib == decl) continue;
            if (self.hir.kindOf(sib) != .enum_decl) continue;
            const sib_name = self.declarationName(sib) orelse continue;
            if (sib_name != enum_name) continue;
            if (try self.enumRelationValueForMemberInDecl(sib, enum_name, member_name)) |value| return value;
        }
        return null;
    }

    fn enumRelationValuesEqual(self: *Checker, a: EnumRelationValue, b: EnumRelationValue) bool {
        return switch (a) {
            .numeric => |av| switch (b) {
                .numeric => |bv| av == bv,
                else => false,
            },
            .string => |asid| switch (b) {
                .string => |bsid| asid == bsid or std.mem.eql(u8, self.string_interner.get(asid), self.string_interner.get(bsid)),
                else => false,
            },
            .unknown_numeric => switch (b) {
                .unknown_numeric => true,
                else => false,
            },
        };
    }

    fn enumRelationValueMismatchFails(a: EnumRelationValue, b: EnumRelationValue) bool {
        const a_known = a != .unknown_numeric;
        const b_known = b != .unknown_numeric;
        if (a_known and b_known) return true;
        return a == .string or b == .string;
    }

    fn enumDeclValueMismatchAgainstTarget(
        self: *Checker,
        source_decl: NodeId,
        target_decl: NodeId,
        enum_name: hir_mod.StringId,
    ) CheckError!?EnumRelationValueMismatch {
        for (hir_mod.enumMembers(self.hir, source_decl)) |member| {
            const member_name = self.enumMemberNameFromProperty(member) orelse continue;
            const source_value = (try self.enumRelationValueForMemberInDecl(source_decl, enum_name, member_name)) orelse continue;
            const target_value = (try self.enumRelationValueForMemberInScope(target_decl, enum_name, member_name)) orelse continue;
            if (!self.enumRelationValuesEqual(source_value, target_value)) {
                if (!enumRelationValueMismatchFails(source_value, target_value)) continue;
                return .{
                    .member_name = member_name,
                    .source_value = source_value,
                    .target_value = target_value,
                };
            }
        }
        return null;
    }

    fn enumFirstValueMismatchInTarget(
        self: *Checker,
        source_decl: NodeId,
        target_decl: NodeId,
        enum_name: hir_mod.StringId,
    ) CheckError!?EnumRelationValueMismatch {
        if (try self.enumDeclValueMismatchAgainstTarget(source_decl, target_decl, enum_name)) |mismatch| return mismatch;
        const source_scope = self.enumSiblingScope(source_decl) orelse return null;
        for (source_scope.stmts) |sib_raw| {
            const sib = self.unwrapExportDecl(sib_raw);
            if (sib == source_decl) continue;
            if (self.hir.kindOf(sib) != .enum_decl) continue;
            const sib_name = self.declarationName(sib) orelse continue;
            if (sib_name != enum_name) continue;
            if (try self.enumDeclValueMismatchAgainstTarget(sib, target_decl, enum_name)) |mismatch| return mismatch;
        }
        return null;
    }

    fn enumRelationKnownValueDisplay(self: *Checker, value: EnumRelationValue) CheckError!?[]const u8 {
        return switch (value) {
            .numeric => |v| try std.fmt.allocPrint(self.diag_arena.allocator(), "{d}", .{v}),
            .string => |sid| try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "\"{s}\"",
                .{self.string_interner.get(sid)},
            ),
            .unknown_numeric => null,
        };
    }

    fn enumRelationStringValueDisplay(self: *Checker, a: EnumRelationValue, b: EnumRelationValue) CheckError!?[]const u8 {
        const sid = switch (a) {
            .string => |value| value,
            else => switch (b) {
                .string => |value| value,
                else => return null,
            },
        };
        return try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "\"{s}\"",
            .{self.string_interner.get(sid)},
        );
    }

    fn enumIdentityAssignmentResult(self: *Checker, source_t: TypeId, target_t: TypeId) ?bool {
        if (self.interner.enumLiteralInfo(source_t)) |source_member| {
            if (self.interner.enumLiteralInfo(target_t)) |target_member| {
                return source_member.enum_name == target_member.enum_name and
                    source_member.member_name == target_member.member_name;
            }
        }
        const source = self.enumIdentityInfo(source_t) orelse return null;
        const target = self.enumIdentityInfo(target_t) orelse return null;
        if (source.name != target.name) return false;
        const source_decl = source.decl orelse return null;
        const target_decl = target.decl orelse return null;
        if (self.enumDeclsShareSiblingScope(source_decl, target_decl)) return null;
        if ((self.enumFirstValueMismatchInTarget(source_decl, target_decl, source.name) catch null) != null) return false;
        return self.enumFirstMissingSourceMemberInTarget(source_decl, target_decl, source.name) == null;
    }

    fn enumMissingMemberElaborationChain(
        self: *Checker,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError!?[]const DiagnosticChainEntry {
        const source = self.enumIdentityInfo(source_t) orelse return null;
        const target = self.enumIdentityInfo(target_t) orelse return null;
        if (source.name != target.name) return null;
        const source_decl = source.decl orelse return null;
        const target_decl = target.decl orelse return null;
        if (self.enumDeclsShareSiblingScope(source_decl, target_decl)) return null;
        const missing = self.enumFirstMissingSourceMemberInTarget(source_decl, target_decl, source.name) orelse return null;
        const target_name = (try self.allocSimpleTypeName(target_t)) orelse self.string_interner.get(target.name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Property '{s}' is missing in type '{s}'.",
            .{ self.string_interner.get(missing), target_name },
        );
        const entries = try self.diag_arena.allocator().alloc(DiagnosticChainEntry, 1);
        entries[0] = .{
            .code = TsCodes.property_missing_in_type,
            .message = msg,
        };
        return entries;
    }

    fn enumValueMismatchElaborationChain(
        self: *Checker,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError!?[]const DiagnosticChainEntry {
        const source = self.enumIdentityInfo(source_t) orelse return null;
        const target = self.enumIdentityInfo(target_t) orelse return null;
        if (source.name != target.name) return null;
        const source_decl = source.decl orelse return null;
        const target_decl = target.decl orelse return null;
        if (self.enumDeclsShareSiblingScope(source_decl, target_decl)) return null;
        if (self.enumFirstMissingSourceMemberInTarget(source_decl, target_decl, source.name) != null) return null;
        const mismatch = (try self.enumFirstValueMismatchInTarget(source_decl, target_decl, source.name)) orelse return null;
        const entries = try self.diag_arena.allocator().alloc(DiagnosticChainEntry, 1);
        const enum_name_text = self.string_interner.get(target.name);
        const member_name_text = self.string_interner.get(mismatch.member_name);
        if (try self.enumRelationKnownValueDisplay(mismatch.target_value)) |target_value| {
            if (try self.enumRelationKnownValueDisplay(mismatch.source_value)) |source_value| {
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Each declaration of '{s}.{s}' differs in its value, where '{s}' was expected but '{s}' was given.",
                    .{ enum_name_text, member_name_text, target_value, source_value },
                );
                entries[0] = .{
                    .code = TsCodes.enum_declaration_value_mismatch,
                    .message = msg,
                };
                return entries;
            }
        }
        const string_value = (try self.enumRelationStringValueDisplay(mismatch.source_value, mismatch.target_value)) orelse return null;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "One value of '{s}.{s}' is the string '{s}', and the other is assumed to be an unknown numeric value.",
            .{ enum_name_text, member_name_text, string_value },
        );
        entries[0] = .{
            .code = TsCodes.enum_declaration_string_unknown_numeric_mismatch,
            .message = msg,
        };
        return entries;
    }

    fn enumValueAssignableToTarget(self: *Checker, enum_name: hir_mod.StringId, target_t: TypeId) bool {
        if (target_t == types.Primitive.any or
            target_t == types.Primitive.unknown or
            target_t == types.Primitive.number_t or
            target_t == types.Primitive.object_t)
        {
            return true;
        }
        if (self.enumNameFromNominal(target_t)) |target_enum| {
            return self.stringIdsHaveSameText(target_enum, enum_name);
        }
        if (self.namedTypeForId(target_t)) |target_name| {
            const raw = self.string_interner.get(target_name);
            if (std.mem.eql(u8, raw, "Object") or std.mem.eql(u8, raw, "Number")) return true;
        }
        if (self.builtin_object_names.get(target_t)) |raw| {
            if (std.mem.eql(u8, raw, "Object") or std.mem.eql(u8, raw, "Number")) return true;
        }
        if (self.alias_display_names.get(target_t)) |raw| {
            if (std.mem.eql(u8, raw, "Object") or std.mem.eql(u8, raw, "Number")) return true;
        }
        if (self.primitiveAssertionMatchesWrapper(types.Primitive.number_t, target_t)) return true;
        if (self.typeLooksLikeNumberWrapper(target_t)) return true;
        if (target_t >= types.Primitive.first_dynamic and target_t < self.interner.pool.typeCount()) {
            const flags = self.interner.pool.flagsOf(target_t);
            if (flags.is_object_type and self.interner.objectMembers(target_t).len == 0 and
                self.interner.objectStringIndex(target_t) == types.Primitive.none and
                self.interner.objectNumberIndex(target_t) == types.Primitive.none)
            {
                return true;
            }
        }
        return false;
    }

    fn typeLooksLikeNumberWrapper(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_object_type) return false;
        var saw_to_fixed = false;
        var saw_to_exponential = false;
        var saw_to_precision = false;
        for (self.interner.objectMembers(t)) |member| {
            const name = self.string_interner.getOptional(member.name) orelse continue;
            if (std.mem.eql(u8, name, "toFixed")) {
                saw_to_fixed = true;
            } else if (std.mem.eql(u8, name, "toExponential")) {
                saw_to_exponential = true;
            } else if (std.mem.eql(u8, name, "toPrecision")) {
                saw_to_precision = true;
            }
        }
        return saw_to_fixed and saw_to_exponential and saw_to_precision;
    }

    fn numericLiteralExpressionValue(self: *Checker, node: NodeId) ?f64 {
        return switch (self.hir.kindOf(node)) {
            .literal_number => self.literalNumberWithSourceSign(node),
            .unary_op => blk: {
                const u = hir_mod.unaryOf(self.hir, node);
                if ((u.op == .neg or u.op == .plus) and self.hir.kindOf(u.operand) == .literal_number) {
                    const value = hir_mod.literalNumberOf(self.hir, u.operand);
                    break :blk if (u.op == .neg and value > 0) -value else value;
                }
                break :blk null;
            },
            else => null,
        };
    }

    fn isShiftOperator(op: hir_mod.BinOp) bool {
        return op == .shl or op == .shr or op == .shr_unsigned;
    }

    fn shiftOperatorText(op: hir_mod.BinOp) []const u8 {
        return switch (op) {
            .shl => "<<",
            .shr => ">>",
            .shr_unsigned => ">>>",
            else => unreachable,
        };
    }

    fn nodeIsEnumMemberInitializer(self: *Checker, node: NodeId) bool {
        var cur = node;
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const parent = self.hir.parentOf(cur);
            if (parent == hir_mod.none_node_id) return false;
            if (self.hir.kindOf(parent) != .object_property) continue;
            const prop = hir_mod.objectPropertyOf(self.hir, parent);
            if (prop.value != cur) continue;
            const grandparent = self.hir.parentOf(parent);
            return grandparent != hir_mod.none_node_id and self.hir.kindOf(grandparent) == .enum_decl;
        }
        return false;
    }

    fn reportSimplifiableShiftCountValue(
        self: *Checker,
        node: NodeId,
        lhs_node: NodeId,
        op: hir_mod.BinOp,
        rhs_value: f64,
        category: Diagnostic.Category,
    ) CheckError!void {
        if (!isShiftOperator(op)) return;
        if (!std.math.isFinite(rhs_value) or @abs(rhs_value) < 32) return;
        const lhs_text = std.mem.trim(u8, self.nodeSourceTextOrEmpty(lhs_node), " \t\r\n");
        if (lhs_text.len == 0) return;
        const reduced = @rem(rhs_value, 32.0);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "This operation can be simplified. This shift is identical to `{s} {s} {d}`.",
            .{ lhs_text, shiftOperatorText(op), reduced },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.shift_count_simplifiable,
            .message = msg,
            .category = category,
        });
    }

    fn reportSimplifiableShiftCount(
        self: *Checker,
        node: NodeId,
        lhs_node: NodeId,
        rhs_node: NodeId,
        op: hir_mod.BinOp,
    ) CheckError!void {
        const rhs_value = self.numericLiteralExpressionValue(rhs_node) orelse return;
        try self.reportSimplifiableShiftCountValue(
            node,
            lhs_node,
            op,
            rhs_value,
            if (self.nodeIsEnumMemberInitializer(node)) .error_ else .suggestion,
        );
    }

    fn reportSimplifiableShiftsInEnumInitializer(
        self: *Checker,
        enum_name: hir_mod.StringId,
        node: NodeId,
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                try self.reportSimplifiableShiftsInEnumInitializer(enum_name, b.lhs);
                try self.reportSimplifiableShiftsInEnumInitializer(enum_name, b.rhs);
                if (!isShiftOperator(b.op)) return;
                if ((try self.evalEnumConstExpression(enum_name, b.lhs)) == null) return;
                const rhs_value = (try self.evalEnumConstExpression(enum_name, b.rhs)) orelse return;
                try self.reportSimplifiableShiftCountValue(node, b.lhs, b.op, rhs_value, .error_);
            },
            .unary_op => {
                const u = hir_mod.unaryOf(self.hir, node);
                try self.reportSimplifiableShiftsInEnumInitializer(enum_name, u.operand);
            },
            else => {},
        }
    }

    fn numericLiteralExpressionAssignableToEnum(self: *Checker, node: NodeId, enum_name: hir_mod.StringId) bool {
        const value = self.numericLiteralExpressionValue(node) orelse return true;
        var saw_numeric_member = false;
        var it = self.enum_member_values.iterator();
        while (it.next()) |entry| {
            if (entry.key_ptr.obj_name != enum_name) continue;
            saw_numeric_member = true;
            if (entry.value_ptr.* == value) return true;
        }
        return !saw_numeric_member;
    }

    fn numericLiteralExpressionAssignableToEnumLiteral(self: *Checker, node: NodeId, target_t: TypeId) bool {
        const target_flags = if (target_t < self.interner.pool.typeCount())
            self.interner.pool.flagsOf(target_t)
        else
            return true;
        if (!target_flags.is_enum_literal or !target_flags.is_number) return true;
        const source_value = self.numericLiteralExpressionValue(node) orelse return true;
        const target_value = self.numberLiteralValueFromType(target_t) orelse return true;
        return source_value == target_value;
    }

    fn sourceAssignableToEnumTarget(self: *Checker, value_node: NodeId, source_t: TypeId, target_enum: hir_mod.StringId) CheckError!bool {
        if (self.typeIsAnyLike(source_t)) return true;
        if (self.numericLiteralExpressionValue(value_node) != null) {
            return self.numericLiteralExpressionAssignableToEnum(value_node, target_enum);
        }
        if (source_t == types.Primitive.number_t) return true;
        if (self.enumNameFromNominal(source_t)) |source_enum| {
            return source_enum == target_enum;
        }
        if (source_t < self.interner.pool.typeCount()) {
            if (self.interner.enumLiteralInfo(source_t)) |info| {
                return info.enum_name == target_enum;
            }
            const flags = self.interner.pool.flagsOf(source_t);
            if (flags.is_type_parameter) {
                const constraint = self.typeParameterConstraint(source_t) orelse return false;
                if (constraint == source_t) return false;
                return try self.sourceAssignableToEnumTarget(value_node, constraint, target_enum);
            }
            if (flags.is_union) {
                for (self.interner.unionMembers(source_t)) |member| {
                    if (!try self.sourceAssignableToEnumTarget(value_node, member, target_enum)) return false;
                }
                return true;
            }
        }
        return false;
    }

    fn enumLiteralDisplayName(self: *Checker, t: TypeId) !?[]const u8 {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return null;
        const info = self.interner.enumLiteralInfo(t) orelse return null;
        return try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "{s}.{s}",
            .{
                self.string_interner.get(info.enum_name),
                self.string_interner.get(info.member_name),
            },
        );
    }

    fn enumIdentityName(self: *Checker, t: TypeId) ?hir_mod.StringId {
        return if (self.enumIdentityInfo(t)) |info| info.name else null;
    }

    fn enumAnnotationNameForIdentifier(self: *Checker, node: NodeId) ?hir_mod.StringId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        const type_node = self.visibleAnnotatedIdentifierTypeNode(node) orelse return null;
        const enum_name = self.simpleTypeAliasNameFromTypeNode(type_node) orelse return null;
        _ = self.enumDeclForNameAt(enum_name, type_node) orelse return null;
        return enum_name;
    }

    fn enumAnnotationDisplayNameForIdentifier(self: *Checker, node: NodeId) CheckError!?[]const u8 {
        _ = self.enumAnnotationNameForIdentifier(node) orelse return null;
        const text = self.visibleAnnotatedIdentifierTypeText(node) orelse return null;
        return try self.normalizedTypeAnnotationText(text);
    }

    fn enumMemberDeclCount(self: *Checker, enum_name: hir_mod.StringId, anchor: NodeId) usize {
        const decl = self.enumDeclForNameAt(enum_name, anchor) orelse return 0;
        var count: usize = 0;
        for (hir_mod.enumMembers(self.hir, decl)) |member| {
            if (self.enumMemberNameFromProperty(member) != null) count += 1;
        }
        return count;
    }

    fn enumLiteralUnionMemberCountForEnum(self: *Checker, target_t: TypeId, enum_name: hir_mod.StringId) ?usize {
        if (target_t >= self.interner.pool.typeCount()) return null;
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (target_flags.is_enum_literal) {
            const info = self.interner.enumLiteralInfo(target_t) orelse return null;
            return if (info.enum_name == enum_name) 1 else null;
        }
        if (!target_flags.is_union) return null;
        const members = self.interner.unionMembers(target_t);
        if (members.len == 0) return null;
        var count: usize = 0;
        for (members) |member| {
            if (member >= self.interner.pool.typeCount()) return null;
            if (!self.interner.pool.flagsOf(member).is_enum_literal) return null;
            const info = self.interner.enumLiteralInfo(member) orelse return null;
            if (info.enum_name != enum_name) return null;
            count += 1;
        }
        return count;
    }

    fn enumMemberRefCountInTypeNode(self: *Checker, type_node: NodeId, enum_name: hir_mod.StringId) ?usize {
        if (type_node == hir_mod.none_node_id) return null;
        return switch (self.hir.kindOf(type_node)) {
            .union_type => blk: {
                var count: usize = 0;
                for (hir_mod.unionTypeMembers(self.hir, type_node)) |member| {
                    count += self.enumMemberRefCountInTypeNode(member, enum_name) orelse break :blk null;
                }
                break :blk count;
            },
            .type_ref => blk: {
                const r = hir_mod.typeRefOf(self.hir, type_node);
                if (r.args_len != 0 or r.qualifier_len != 1) break :blk null;
                const qualifiers = self.hir.childSlice(r.qualifier_start, r.qualifier_len);
                if (self.hir.kindOf(qualifiers[0]) != .identifier) break :blk null;
                const ref_enum = hir_mod.identifierOf(self.hir, qualifiers[0]).name;
                if (ref_enum != enum_name) break :blk null;
                if (!self.enumHasMemberAt(enum_name, r.name, type_node)) break :blk null;
                break :blk 1;
            },
            else => null,
        };
    }

    fn targetEnumAliasMemberCountForEnum(self: *Checker, target_node: NodeId, enum_name: hir_mod.StringId) ?usize {
        const type_node = self.visibleAnnotatedIdentifierTypeNode(target_node) orelse return null;
        const alias_name = self.simpleTypeAliasNameFromTypeNode(type_node) orelse return null;
        const decl = self.typeAliasDeclForNameAt(alias_name, type_node) orelse return null;
        const ta = hir_mod.typeAliasOf(self.hir, decl);
        if (ta.type_params_len != 0) return null;
        return self.enumMemberRefCountInTypeNode(ta.aliased, enum_name);
    }

    fn enumAnnotationAssignmentResult(self: *Checker, value_node: NodeId, target_node: NodeId, target_t: TypeId) ?bool {
        const enum_name = self.enumAnnotationNameForIdentifier(value_node) orelse return null;
        const target_count = self.enumLiteralUnionMemberCountForEnum(target_t, enum_name) orelse
            self.targetEnumAliasMemberCountForEnum(target_node, enum_name) orelse
            return null;
        const enum_count = self.enumMemberDeclCount(enum_name, value_node);
        if (enum_count == 0) return null;
        return target_count >= enum_count;
    }

    fn mismatchedEnumIdentityAssignment(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
        if (self.enumIdentityAssignmentResult(source_t, target_t)) |ok| return !ok;
        const source_enum = self.enumIdentityName(source_t) orelse return false;
        const target_enum = self.enumIdentityName(target_t) orelse return false;
        return source_enum != target_enum;
    }

    fn visibleAnnotatedSignatureIdentifierTypeName(self: *Checker, node: NodeId) CheckError!?[]const u8 {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        const type_node = self.visibleAnnotatedIdentifierTypeNode(node) orelse return null;
        const k = self.hir.kindOf(type_node);
        if (k != .fn_type and k != .constructor_type) return null;
        const text = self.visibleAnnotatedIdentifierTypeText(node) orelse return null;
        if (text.len == 0) return null;
        const normalized = try self.normalizedTypeAnnotationText(text);
        if (k != .constructor_type or std.mem.indexOf(u8, normalized, "new(") == null) return normalized;

        var out: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        var start: usize = 0;
        while (std.mem.indexOf(u8, normalized[start..], "new(")) |offset| {
            const match_start = start + offset;
            try out.appendSlice(arena, normalized[start .. match_start + "new".len]);
            try out.append(arena, ' ');
            start = match_start + "new".len;
        }
        try out.appendSlice(arena, normalized[start..]);
        return out.items;
    }

    fn visibleAnnotatedSignatureIdentifierDiagnosticName(self: *Checker, node: NodeId, t: TypeId) CheckError!?[]const u8 {
        const source_display = (try self.visibleAnnotatedSignatureIdentifierTypeName(node)) orelse return null;
        const params: []const TypeId = if (self.interner.isSignature(t)) self.interner.signatureParams(t) else &.{};
        const has_strict_optional_params = self.strict_flags.strict_null_checks and
            params.len > 0 and
            self.signatureMinRequiredArgs(t, params) < params.len and
            !self.rest_signatures.contains(t);
        if (self.interner.isSignature(t) and
            (self.signatureThisParam(t) != null or
                self.signatureUsesArrayAliasConstituent(t) or
                has_strict_optional_params or
                std.mem.indexOf(u8, source_display, "Array<") != null))
        {
            if (std.mem.indexOf(u8, source_display, "Array<") != null) {
                return try self.normalizeSignatureArrayAnnotationText(t, source_display);
            }
            if (try self.allocCallableSignatureNamePreservingGenericPrefix(t, source_display)) |signature_display| return signature_display;
        }
        return source_display;
    }

    fn normalizeSignatureArrayAnnotationText(
        self: *Checker,
        sig: TypeId,
        text: []const u8,
    ) CheckError![]const u8 {
        var transform_start: usize = 0;
        if (self.generic_signature_params.get(sig) != null) {
            if (std.mem.indexOfScalar(u8, text, '<')) |generic_open| {
                var depth: usize = 0;
                for (text[generic_open..], generic_open..) |ch, i| {
                    if (ch == '<') {
                        depth += 1;
                    } else if (ch == '>') {
                        if (depth == 0) break;
                        depth -= 1;
                        if (depth == 0) {
                            transform_start = i + 1;
                            break;
                        }
                    }
                }
            }
        }
        var out: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        try out.appendSlice(arena, text[0..transform_start]);
        try self.appendSignatureArrayAnnotationText(&out, arena, text[transform_start..]);
        return out.items;
    }

    fn appendSignatureArrayAnnotationText(
        self: *Checker,
        out: *std.ArrayListUnmanaged(u8),
        arena: std.mem.Allocator,
        text: []const u8,
    ) CheckError!void {
        var i: usize = 0;
        while (i < text.len) {
            const array_prefix = std.mem.startsWith(u8, text[i..], "Array<") and
                (i == 0 or !isJsDocIdentChar(text[i - 1]));
            if (!array_prefix) {
                try out.append(arena, text[i]);
                i += 1;
                continue;
            }
            const inner_start = i + "Array<".len;
            var depth: usize = 1;
            var close = inner_start;
            while (close < text.len and depth > 0) : (close += 1) {
                if (text[close] == '<') {
                    depth += 1;
                } else if (text[close] == '>') {
                    depth -= 1;
                }
            }
            if (depth != 0) {
                try out.append(arena, text[i]);
                i += 1;
                continue;
            }
            const inner_end = close - 1;
            const inner = text[inner_start..inner_end];
            const wrap = std.mem.indexOfScalar(u8, inner, '|') != null or
                std.mem.indexOf(u8, inner, "=>") != null;
            if (wrap) try out.append(arena, '(');
            try self.appendSignatureArrayAnnotationText(out, arena, inner);
            if (wrap) try out.append(arena, ')');
            try out.appendSlice(arena, "[]");
            i = close;
        }
    }

    fn allocCallableSignatureNamePreservingGenericPrefix(
        self: *Checker,
        sig: TypeId,
        source_display: []const u8,
    ) CheckError!?[]const u8 {
        const rendered = (try self.allocCallableSignatureName(sig)) orelse return null;
        if (self.generic_signature_params.get(sig) == null) return rendered;
        const generic_open = std.mem.indexOfScalar(u8, source_display, '<') orelse return rendered;
        var depth: usize = 0;
        var generic_close: ?usize = null;
        for (source_display[generic_open..], generic_open..) |ch, i| {
            if (ch == '<') {
                depth += 1;
            } else if (ch == '>') {
                if (depth == 0) return rendered;
                depth -= 1;
                if (depth == 0) {
                    generic_close = i;
                    break;
                }
            }
        }
        const close = generic_close orelse return rendered;
        const rendered_params = std.mem.indexOfScalar(u8, rendered, '(') orelse return rendered;
        return try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "{s}{s}",
            .{ source_display[0 .. close + 1], rendered[rendered_params..] },
        );
    }

    fn signatureUsesArrayAliasConstituent(self: *Checker, sig: TypeId) bool {
        if (!self.interner.isSignature(sig)) return false;
        for (self.interner.signatureParams(sig)) |param_t| {
            if (self.typeUsesArrayAliasDisplay(param_t, 0)) return true;
        }
        const ret_t = self.interner.signatureReturn(sig) orelse return false;
        return self.typeUsesArrayAliasDisplay(ret_t, 0);
    }

    fn typeUsesArrayAliasDisplay(self: *Checker, t: TypeId, depth: u8) bool {
        if (depth > 6 or t >= self.interner.pool.typeCount()) return false;
        if (self.alias_display_names.get(t)) |display| {
            if (std.mem.indexOf(u8, display, "Array<") != null and
                std.mem.endsWith(u8, display, ">") and
                self.interner.objectNumberIndex(t) != types.Primitive.none)
            {
                return true;
            }
        }
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeUsesArrayAliasDisplay(member, depth + 1)) return true;
            }
        } else if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeUsesArrayAliasDisplay(member, depth + 1)) return true;
            }
        } else if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |param_t| {
                if (self.typeUsesArrayAliasDisplay(param_t, depth + 1)) return true;
            }
            if (self.interner.signatureReturn(t)) |ret_t| {
                if (self.typeUsesArrayAliasDisplay(ret_t, depth + 1)) return true;
            }
        }
        return false;
    }

    fn functionExpressionAssignmentDiagnosticName(self: *Checker, node: NodeId, t: TypeId) CheckError!?[]const u8 {
        if (node == hir_mod.none_node_id) return null;
        const kind = self.hir.kindOf(node);
        if (kind != .arrow_fn and kind != .fn_expr and kind != .fn_decl) return null;
        const f = hir_mod.fnDeclOf(self.hir, node);
        const rendered = (try self.allocCallableSignatureNameOmittingOptionalUndefined(t)) orelse return null;
        if (f.return_type != hir_mod.none_node_id and
            self.hir.kindOf(f.return_type) != .type_predicate_type)
        {
            const arrow = std.mem.lastIndexOf(u8, rendered, "=>") orelse return rendered;
            const return_text = std.mem.trim(u8, self.nodeSourceTextOrEmpty(f.return_type), " \t\r\n");
            if (return_text.len != 0) {
                return try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "{s}=> {s}",
                    .{ rendered[0..arrow], return_text },
                );
            }
        }
        if (!self.strict_flags.strict_null_checks and self.interner.isSignature(t)) {
            const ret_t = self.interner.signatureReturn(t) orelse types.Primitive.any;
            if (ret_t == types.Primitive.null_t or ret_t == types.Primitive.undefined_t) {
                const arrow = std.mem.lastIndexOf(u8, rendered, "=>") orelse return rendered;
                return try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "{s}=> any",
                    .{rendered[0..arrow]},
                );
            }
        }
        return rendered;
    }

    fn sourceTypeForVarDeclAssignmentReport(self: *Checker, init_node: NodeId, init_t: TypeId, target_t: TypeId) CheckError!TypeId {
        if (self.unnarrowedAnnotatedUnionType(init_node)) |union_t| return union_t;
        if (try self.visibleAnnotatedSignatureIdentifierDiagnosticName(init_node, init_t)) |display| {
            if (init_t >= types.Primitive.first_dynamic and init_t < self.interner.pool.typeCount() and
                !self.alias_display_names.contains(init_t))
            {
                try self.alias_display_names.put(self.gpa, init_t, display);
            }
        }
        if (init_node != hir_mod.none_node_id and self.hir.kindOf(init_node) == .conditional) {
            const c = hir_mod.conditionalOf(self.hir, init_node);
            const then_t = (self.objectLiteralImportedNamespaceReportType(c.then_branch) catch null) orelse self.hir.typeOf(c.then_branch);
            const else_t = self.hir.typeOf(c.else_branch);
            if (then_t != types.Primitive.none and else_t != types.Primitive.none) {
                const union_t = self.interner.internUnion(&.{ then_t, else_t }) catch return init_t;
                try self.registerDiagnosticUnionDisplayName(union_t, &.{ then_t, else_t });
                return union_t;
            }
        }
        if (try self.identifierBooleanLiteralInitializerReportType(init_node, init_t, target_t)) |literal_t| {
            return literal_t;
        }
        if (self.enumNameFromNominal(target_t) != null or
            (target_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(target_t).is_enum_literal))
        {
            if (self.numericLiteralExpressionValue(init_node)) |value| {
                return self.interner.internNumberLiteral(value) catch init_t;
            }
        }
        if (self.containsTemplatePatternSurface(target_t)) {
            const literal_t = try self.expressionLiteralType(init_node, init_t);
            if (literal_t != init_t) return literal_t;
        }
        if (init_t >= self.interner.pool.typeCount()) return init_t;
        const init_flags = self.interner.pool.flagsOf(init_t);
        if (!init_flags.is_enum_literal) return init_t;
        const target_flags = if (target_t < self.interner.pool.typeCount())
            self.interner.pool.flagsOf(target_t)
        else
            return init_t;
        if (target_flags.is_enum_literal) return init_t;
        return self.widenLiteralType(init_t);
    }

    fn unnarrowedAnnotatedUnionType(self: *Checker, node: NodeId) ?TypeId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        const id = hir_mod.identifierOf(self.hir, node);
        const declared = self.visibleAnnotatedIdentifierType(node) orelse self.typeOfIdentifierDeclared(node);
        if (self.lookupNarrow(id.name)) |active| if (active != declared) return null;
        if (declared >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(declared).is_union) return null;
        return declared;
    }

    fn objectLiteralImportedNamespaceReportType(self: *Checker, node: NodeId) CheckError!?TypeId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .object_literal) return null;
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        var used_imported_namespace = false;
        for (hir_mod.objectLiteralProps(self.hir, node)) |prop| {
            if (self.hir.kindOf(prop) != .object_property) continue;
            const op = hir_mod.objectPropertyOf(self.hir, prop);
            const key_name = if (op.key != hir_mod.none_node_id and self.hir.kindOf(op.key) == .identifier)
                hir_mod.identifierOf(self.hir, op.key).name
            else
                (try self.staticStringValue(op.key)) orelse continue;
            var member_t = self.hir.typeOf(op.value);
            if (op.value != hir_mod.none_node_id and self.hir.kindOf(op.value) == .identifier) {
                const id = hir_mod.identifierOf(self.hir, op.value);
                if (try self.moduleNamespaceTypeForLocalImport(id.name, op.value)) |ns_t| {
                    member_t = ns_t;
                    used_imported_namespace = true;
                }
            }
            if (member_t == types.Primitive.none) member_t = types.Primitive.any;
            try members.append(self.gpa, .{
                .name = key_name,
                .type = member_t,
                .is_optional = false,
                .is_readonly = false,
                .is_method = false,
            });
        }
        if (!used_imported_namespace or members.items.len == 0) return null;
        const obj_t = self.interner.internObjectType(members.items) catch return error.OutOfMemory;
        try self.registerObjectLiteralImportedNamespaceDisplayName(obj_t, members.items);
        return obj_t;
    }

    fn registerObjectLiteralImportedNamespaceDisplayName(self: *Checker, obj_t: TypeId, members: []const types.ObjectMember) CheckError!void {
        if (obj_t < types.Primitive.first_dynamic or obj_t >= self.interner.pool.typeCount()) return;
        if (self.alias_display_names.contains(obj_t)) return;
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        try buf.appendSlice(arena, "{ ");
        for (members, 0..) |m, i| {
            if (i > 0) try buf.appendSlice(arena, "; ");
            // Bounds-checked (mirrors the allocAnonymousObjectName guard): a
            // synthesized/imported member can carry a stale name id; bail the
            // display-name registration rather than OOB-read string_interner.
            try appendObjectShapeMemberName(&buf, arena, self.string_interner.getOptional(m.name) orelse return);
            try buf.appendSlice(arena, ": ");
            const member_name = (try self.importNamespaceDiagnosticDisplayName(m.type)) orelse
                (try self.allocSimpleTypeName(m.type)) orelse
                (try self.allocObjectTypeShape(m.type)) orelse
                "any";
            try buf.appendSlice(arena, member_name);
        }
        try buf.appendSlice(arena, "; }");
        try self.alias_display_names.put(self.gpa, obj_t, buf.items);
    }

    fn importNamespaceDiagnosticDisplayName(self: *Checker, t: TypeId) CheckError!?[]const u8 {
        const display = self.alias_display_names.get(t) orelse return null;
        const synthetic_root_prefix = "typeof import(\"/";
        if (std.mem.startsWith(u8, display, synthetic_root_prefix)) {
            return try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "typeof import(\"{s}",
                .{display[synthetic_root_prefix.len..]},
            );
        }
        return display;
    }

    fn registerDiagnosticUnionDisplayName(self: *Checker, union_t: TypeId, members: []const TypeId) CheckError!void {
        if (union_t < types.Primitive.first_dynamic or union_t >= self.interner.pool.typeCount()) return;
        if (self.alias_display_names.contains(union_t)) return;
        var flattened: std.ArrayListUnmanaged(TypeId) = .empty;
        defer flattened.deinit(self.gpa);
        for (members) |member| try self.collectDiagnosticUnionMembers(member, &flattened);
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        var first = true;
        var has_null = false;
        var has_undef = false;
        var seen: std.ArrayListUnmanaged([]const u8) = .empty;
        defer seen.deinit(self.gpa);
        for (flattened.items) |member| {
            if (member == types.Primitive.null_t) {
                has_null = true;
                continue;
            }
            if (member == types.Primitive.undefined_t) {
                has_undef = true;
                continue;
            }
            const member_name = (try self.allocSimpleTypeName(member)) orelse
                (try self.allocObjectTypeShape(member)) orelse
                return;
            var duplicate = false;
            for (seen.items) |prior| {
                if (std.mem.eql(u8, prior, member_name)) {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate) continue;
            try seen.append(self.gpa, member_name);
            if (!first) try buf.appendSlice(arena, " | ");
            first = false;
            const needs_parens = self.interner.isSignature(member) or
                std.mem.indexOf(u8, member_name, "=>") != null;
            if (needs_parens) try buf.append(arena, '(');
            try buf.appendSlice(arena, member_name);
            if (needs_parens) try buf.append(arena, ')');
        }
        if (has_null) {
            if (!first) try buf.appendSlice(arena, " | ");
            first = false;
            try buf.appendSlice(arena, "null");
        }
        if (has_undef) {
            if (!first) try buf.appendSlice(arena, " | ");
            first = false;
            try buf.appendSlice(arena, "undefined");
        }
        if (buf.items.len == 0) return;
        try self.alias_display_names.put(self.gpa, union_t, buf.items);
    }

    fn collectDiagnosticUnionMembers(self: *Checker, t: TypeId, out: *std.ArrayListUnmanaged(TypeId)) CheckError!void {
        if (t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(t).is_union) {
            for (self.interner.unionMembers(t)) |member| try self.collectDiagnosticUnionMembers(member, out);
            return;
        }
        try self.appendUniqueTypeId(out, t);
    }

    fn tryReportConditionalImportedNamespaceNotAssignable(self: *Checker, diag_node: NodeId, init_node: NodeId, target_t: TypeId) CheckError!bool {
        if (init_node == hir_mod.none_node_id or self.hir.kindOf(init_node) != .conditional) return false;
        const c = hir_mod.conditionalOf(self.hir, init_node);
        const then_t = (try self.objectLiteralImportedNamespaceReportType(c.then_branch)) orelse return false;
        const else_t = self.hir.typeOf(c.else_branch);
        if (else_t == types.Primitive.none) return false;
        const source_t = self.interner.internUnion(&.{ then_t, else_t }) catch return error.OutOfMemory;
        try self.registerDiagnosticUnionDisplayName(source_t, &.{ then_t, else_t });
        try self.reportTypeNotAssignable(diag_node, source_t, target_t, "Type is not assignable to declared type.");
        return true;
    }

    fn mutableInitializerShouldWidenLiteral(self: *Checker, init_node: NodeId, init_t: TypeId) bool {
        return self.initializerHasWideningFreshLiteral(init_node, init_t, true);
    }

    fn initializerHasWideningFreshLiteral(
        self: *Checker,
        init_node: NodeId,
        init_t: TypeId,
        allow_identifier_propagation: bool,
    ) bool {
        return switch (self.hir.kindOf(init_node)) {
            .literal_string, .literal_number, .literal_bool, .literal_bigint => true,
            .unary_op => blk: {
                const u = hir_mod.unaryOf(self.hir, init_node);
                if (u.op != .neg and u.op != .plus) break :blk false;
                const operand_kind = self.hir.kindOf(u.operand);
                break :blk operand_kind == .literal_number or operand_kind == .literal_bigint;
            },
            .conditional => blk: {
                const c = hir_mod.conditionalOf(self.hir, init_node);
                const then_t = self.hir.typeOf(c.then_branch);
                const else_t = self.hir.typeOf(c.else_branch);
                break :blk self.initializerHasWideningFreshLiteral(c.then_branch, then_t, false) or
                    self.initializerHasWideningFreshLiteral(c.else_branch, else_t, false);
            },
            .identifier => blk: {
                if (!allow_identifier_propagation) break :blk false;
                if (self.visibleAnnotatedIdentifierType(init_node)) |declared_t| {
                    if (init_t != declared_t and self.widenLiteralType(init_t) == declared_t) break :blk true;
                }
                const id = hir_mod.identifierOf(self.hir, init_node);
                break :blk self.constDeclHasWideningFreshInitializer(init_node, id.name);
            },
            .member_access, .element_access => blk: {
                if (init_t >= self.interner.pool.typeCount()) break :blk false;
                break :blk self.interner.pool.flagsOf(init_t).is_enum_literal;
            },
            else => false,
        };
    }

    fn constDeclHasWideningFreshInitializer(self: *Checker, at_node: NodeId, name: hir_mod.StringId) bool {
        const decl = self.findLocalValueDeclBeforeExpression(at_node, name) orelse return false;
        if (self.hir.kindOf(decl) != .const_decl) return false;
        const v = hir_mod.varDeclOf(self.hir, decl);
        if (v.type_annotation != hir_mod.none_node_id or v.init == hir_mod.none_node_id) return false;
        const init_t = self.hir.typeOf(v.init);
        return self.initializerHasWideningFreshLiteral(v.init, init_t, true);
    }

    fn findLocalValueDeclBeforeExpression(self: *Checker, node: NodeId, name: hir_mod.StringId) ?NodeId {
        var anchor = node;
        var scope = self.hir.parentOf(node);
        while (scope != hir_mod.none_node_id) {
            const stmts: []const NodeId = switch (self.hir.kindOf(scope)) {
                .block_stmt => hir_mod.blockStmts(self.hir, scope),
                .namespace_decl => hir_mod.namespaceBody(self.hir, scope),
                else => {
                    anchor = scope;
                    scope = self.hir.parentOf(scope);
                    continue;
                },
            };
            for (stmts) |stmt| {
                if (stmt == anchor or (self.hir.kindOf(stmt) == .export_decl and hir_mod.exportOf(self.hir, stmt).decl == anchor)) return null;
                const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
                if (decl == hir_mod.none_node_id) continue;
                switch (self.hir.kindOf(decl)) {
                    .var_decl, .let_decl, .const_decl => {
                        const v = hir_mod.varDeclOf(self.hir, decl);
                        if (v.name != hir_mod.none_node_id and
                            self.hir.kindOf(v.name) == .identifier and
                            hir_mod.identifierOf(self.hir, v.name).name == name)
                        {
                            return decl;
                        }
                    },
                    .fn_decl, .fn_expr => {
                        const f = hir_mod.fnDeclOf(self.hir, decl);
                        if (f.name != hir_mod.none_node_id and
                            self.hir.kindOf(f.name) == .identifier and
                            hir_mod.identifierOf(self.hir, f.name).name == name)
                        {
                            return decl;
                        }
                    },
                    .class_decl, .class_expr => {
                        const c = hir_mod.classOf(self.hir, decl);
                        if (c.name != hir_mod.none_node_id and
                            self.hir.kindOf(c.name) == .identifier and
                            hir_mod.identifierOf(self.hir, c.name).name == name)
                        {
                            return decl;
                        }
                    },
                    else => {},
                }
            }
            return null;
        }
        return null;
    }

    fn appendNumericEnumRecordMembers(
        self: *Checker,
        enum_name: hir_mod.StringId,
        value_t: TypeId,
        out: *std.ArrayListUnmanaged(types.ObjectMember),
    ) CheckError!void {
        var it = self.enum_member_values.iterator();
        while (it.next()) |entry| {
            if (entry.key_ptr.obj_name != enum_name) continue;
            const value = entry.value_ptr.*;
            const key_text = if (value == @floor(value))
                try std.fmt.allocPrint(self.gpa, "{d}", .{@as(i64, @intFromFloat(value))})
            else
                try std.fmt.allocPrint(self.gpa, "{d}", .{value});
            defer self.gpa.free(key_text);
            const key_name = self.string_interner.intern(key_text) catch return error.OutOfMemory;
            try out.append(self.gpa, .{
                .name = key_name,
                .type = value_t,
                .is_optional = false,
                .is_readonly = false,
                .is_method = false,
            });
        }
    }

    fn isThisTypeParameter(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_type_parameter) return false;
        const payload_idx = self.interner.pool.payloadOf(t);
        if (payload_idx >= self.interner.pool.type_parameter_payloads.items.len) return false;
        const tp = self.interner.pool.type_parameter_payloads.items[payload_idx];
        const name = tp.name;
        return std.mem.eql(u8, self.string_interner.get(name), "this");
    }

    fn freshThisTypeParameter(self: *Checker, name: hir_mod.StringId) CheckError!TypeId {
        return self.interner.internFreshTypeParameterWithFlags(
            name,
            types.Primitive.unknown,
            types.Primitive.none,
            .bivariant,
            false,
        ) catch return error.OutOfMemory;
    }

    fn typeContainsUnknown(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.unknown) return true;
        if (t < types.Primitive.first_dynamic) return false;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |m| if (self.typeContainsUnknown(m)) return true;
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |m| if (self.typeContainsUnknown(m)) return true;
            return false;
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |m| if (self.typeContainsUnknown(m.type)) return true;
            const string_idx = self.interner.objectStringIndex(t);
            if (string_idx != types.Primitive.none and self.typeContainsUnknown(string_idx)) return true;
            const number_idx = self.interner.objectNumberIndex(t);
            if (number_idx != types.Primitive.none and self.typeContainsUnknown(number_idx)) return true;
            return false;
        }
        if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |p| if (self.typeContainsUnknown(p)) return true;
            if (self.interner.signatureReturn(t)) |r| if (self.typeContainsUnknown(r)) return true;
            return false;
        }
        if (flags.is_tuple) {
            const payload_idx = self.interner.pool.payloadOf(t);
            if (payload_idx >= self.interner.pool.tuple_payloads.items.len) return false;
            const payload = self.interner.pool.tuple_payloads.items[payload_idx];
            const elems = self.interner.pool.tuple_element_pool.items[payload.elements_start .. payload.elements_start + payload.elements_len];
            for (elems) |elem| if (self.typeContainsUnknown(elem.type)) return true;
            return false;
        }
        return false;
    }

    fn isThisParameter(self: *Checker, param_node: NodeId) bool {
        if (self.hir.kindOf(param_node) != .parameter) return false;
        const p = hir_mod.parameterOf(self.hir, param_node);
        if (p.name == hir_mod.none_node_id or self.hir.kindOf(p.name) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, p.name);
        return std.mem.eql(u8, self.string_interner.get(id.name), "this");
    }

    fn broadObjectPrototypeMember(self: *Checker, name: hir_mod.StringId) CheckError!?TypeId {
        const text = self.string_interner.get(name);
        if (std.mem.eql(u8, text, "constructor")) {
            // Every object inherits `constructor: Function` from
            // Object.prototype, so `instance.constructor` resolves rather
            // than emitting TS2339. Keep this broad fallback non-callable:
            // tsc's `Function` type is not assignable to a stricter
            // function signature like `() => void`.
            // Pins typesWithPublicConstructor.
            return try self.syntheticFunctionObjectType();
        }
        if (std.mem.eql(u8, text, "toString")) {
            return self.interner.internSignature(&.{}, types.Primitive.string_t, false) catch return error.OutOfMemory;
        }
        if (std.mem.eql(u8, text, "valueOf")) {
            return self.interner.internSignature(&.{}, types.Primitive.object_t, false) catch return error.OutOfMemory;
        }
        if (std.mem.eql(u8, text, "hasOwnProperty") or
            std.mem.eql(u8, text, "propertyIsEnumerable"))
        {
            return self.interner.internSignature(&.{types.Primitive.string_t}, types.Primitive.boolean_t, false) catch return error.OutOfMemory;
        }
        return null;
    }

    fn syntheticFunctionObjectType(self: *Checker) CheckError!TypeId {
        const t = self.interner.internObjectType(&.{}) catch return error.OutOfMemory;
        try self.alias_display_names.put(self.gpa, t, "Function");
        return t;
    }

    fn unconstrainedTypeParameter(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(t).is_type_parameter) return false;
        return self.typeParameterConstraint(t) == null;
    }

    fn typeParameterObjectPrototypeMember(self: *Checker, t: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(t).is_type_parameter) return null;
        const constraint = self.typeParameterConstraint(t) orelse return null;
        if (constraint == types.Primitive.object_t) return try self.broadObjectPrototypeMember(name);
        if (constraint >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(constraint).is_object_type) return null;
        return try self.broadObjectPrototypeMember(name);
    }

    /// True when `t` is the instance type produced for a `class X { ÃÂ¢ÃÂÃÂ¦ }`
    /// declaration (i.e. is registered in `class_name_by_instance`).
    /// Used as a gate for inheriting `Object.prototype` members
    /// (`toString`, `hasOwnProperty`, ÃÂ¢ÃÂÃÂ¦) so plain object literals
    /// stay strict but class instances pick up the inherited shape.
    fn typeIsClassInstance(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        return self.class_name_by_instance.contains(t);
    }

    fn declaredInterfaceMember(self: *Checker, interface_name: []const u8, member_name: hir_mod.StringId) CheckError!?TypeId {
        const id = self.string_interner.intern(interface_name) catch return error.OutOfMemory;
        const iface_t = self.type_names.get(id) orelse return null;
        return self.lookupObjectMember(iface_t, member_name);
    }

    fn primitivePrototypeMember(self: *Checker, receiver_t: TypeId, member_name: hir_mod.StringId) CheckError!?TypeId {
        if (self.typeHasStringPrimitivePart(receiver_t)) {
            if (try self.declaredInterfaceMember("String", member_name)) |t| return t;
            if (lib.stringProto(&self.lib_cache, self.interner, self.string_interner, self.gpa, &self.rest_signatures)) |proto| {
                if (self.interner.objectMember(proto, member_name)) |t| return t;
            } else |_| {}
            if (try self.broadObjectPrototypeMember(member_name)) |t| return t;
            return null;
        }
        if (self.typeHasNumericPrimitivePart(receiver_t)) {
            if (try self.declaredInterfaceMember("Number", member_name)) |t| return t;
            if (lib.numberProto(&self.lib_cache, self.interner, self.string_interner)) |proto| {
                if (self.interner.objectMember(proto, member_name)) |t| return t;
            } else |_| {}
            if (try self.broadObjectPrototypeMember(member_name)) |t| return t;
            return null;
        }
        if (self.typeHasBooleanPrimitivePart(receiver_t)) {
            if (try self.declaredInterfaceMember("Boolean", member_name)) |t| return t;
            if (try self.broadObjectPrototypeMember(member_name)) |t| return t;
            return null;
        }
        return null;
    }

    fn lookupObjectMember(self: *Checker, obj_t: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        const flags = self.interner.pool.flagsOf(obj_t);
        // A property access on `any` yields `any` for any name. Mirrors
        // tsc's `getPropertyOfType` short-circuit on the `any`/error type
        // so callers don't fall through to the TS2339 path.
        if (flags.is_any) return types.Primitive.any;
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(obj_t) orelse return null;
            if (constraint == obj_t) return null;
            return try self.lookupObjectMember(constraint, name);
        }
        if (try self.refreshedGenericAliasObjectMember(obj_t, name)) |t| return t;
        if (flags.is_union) {
            // Recursive member lookup may intern result unions, which can
            // reallocate the shared member pool. Snapshot the constituent IDs
            // before recursing so the traversal never retains a borrowed pool
            // slice across an interner write.
            const members = try self.gpa.dupe(TypeId, self.interner.unionMembers(obj_t));
            defer self.gpa.free(members);
            var resolved: std.ArrayListUnmanaged(TypeId) = .empty;
            defer resolved.deinit(self.gpa);
            var first_decl = hir_mod.none_node_id;
            var saw_non_public = false;
            var saw_distinct_declaration = false;
            var saw_non_property_fallback = false;
            for (members) |member_t| {
                if (try self.lookupObjectMember(member_t, name)) |t| {
                    try resolved.append(self.gpa, t);
                    if (self.unionConstituentMemberInfo(member_t, name)) |member| {
                        saw_non_public = saw_non_public or member.visibility != .public;
                        if (member.decl_node == hir_mod.none_node_id) {
                            saw_non_property_fallback = true;
                        } else if (first_decl == hir_mod.none_node_id) {
                            first_decl = member.decl_node;
                        } else if (member.decl_node != first_decl) {
                            saw_distinct_declaration = true;
                        }
                    } else {
                        saw_non_property_fallback = true;
                    }
                } else if (self.namedPropertyIndexType(member_t, name)) |t| {
                    try resolved.append(self.gpa, t);
                    saw_non_property_fallback = true;
                } else {
                    return null;
                }
            }
            if (resolved.items.len == 0) return null;
            if (saw_non_public and (saw_distinct_declaration or saw_non_property_fallback)) return null;
            return self.interner.internUnion(resolved.items) catch return error.OutOfMemory;
        }
        if (flags.is_intersection) {
            // As above, recursive lookup can intern a result and invalidate a
            // slice borrowed from `member_pool`.
            const members = try self.gpa.dupe(TypeId, self.interner.intersectionMembers(obj_t));
            defer self.gpa.free(members);
            // If any constituent is `any`, the whole intersection behaves
            // like `any` for property access ÃÂ¢ÃÂÃÂ `getPropertyOfType` yields
            // `any` and never reports a missing property. Short-circuit so
            // `any & { ÃÂ¢ÃÂÃÂ¦ }` (e.g. thisTypeInObjectLiterals2.ts(173)) never
            // falls through to TS2339.
            for (members) |member_t| {
                if (self.interner.pool.flagsOf(member_t).is_any) return types.Primitive.any;
            }
            var resolved: std.ArrayListUnmanaged(TypeId) = .empty;
            defer resolved.deinit(self.gpa);
            for (members) |member_t| {
                if (try self.lookupObjectMember(member_t, name)) |t| {
                    try resolved.append(self.gpa, self.recursiveAliasMemberSelfType(obj_t, t) orelse t);
                }
            }
            if (resolved.items.len == 0) return null;
            if (resolved.items.len == 1) return resolved.items[0];
            var has_non_nullish_constituent = false;
            for (resolved.items) |resolved_t| {
                if (!self.typeIsPossiblyNullishStrict(resolved_t)) {
                    has_non_nullish_constituent = true;
                    break;
                }
            }
            if (has_non_nullish_constituent) {
                for (resolved.items) |*resolved_t| {
                    resolved_t.* = self.subtractNullUndefined(resolved_t.*) catch resolved_t.*;
                }
            }
            return self.interner.internIntersection(resolved.items) catch return error.OutOfMemory;
        }
        if (try self.overloadedObjectMemberValueType(obj_t, name)) |t| return t;
        if (self.typeIsMappedPayloadType(obj_t)) {
            const mapped = self.interner.mappedPayload(obj_t);
            if (try self.mappedConstraintDefinitelyIncludesProperty(mapped.constraint, name)) {
                return try self.mappedPropertyTargetType(obj_t, name);
            }
        }
        if (self.interner.objectMember(obj_t, name)) |t| {
            if (self.typeboxStaticMemberNeedsSynthesis(name, t)) {
                if (try self.synthesizeTypeboxStaticMember(obj_t)) |static_t| return static_t;
            }
            return self.recursiveAliasMemberSelfType(obj_t, t) orelse t;
        }
        if (try self.synthesizeTypeboxStaticMemberForName(obj_t, name)) |static_t| return static_t;
        // Declaration-merge fallback: a `class C` instance also carries
        // the members of any same-named `interface C` (declaration
        // merging), including interface members contributed by an
        // ambient module augmentation (`declare module "X" { interface
        // C { ... } }`). The merged interface members live in
        // `type_names[C]`; the class instance type itself does not embed
        // them, so consult the merged interface here before the caller
        // falls through to TS2339 ÃÂ¢ÃÂÃÂ moduleAugmentationInAmbientModule3.
        if (self.class_name_by_instance.get(obj_t)) |class_name| {
            if (self.class_decl_by_instance.get(obj_t)) |class_decl| {
                if (self.last_iface_decl_for_name.get(class_name)) |iface_decl| {
                    const iface_scope = self.nearestDeclarationScope(iface_decl);
                    const legitimate_merge = (self.declarationsShareNamespacePath(class_decl, iface_decl) and
                        self.nearestDeclarationScope(class_decl) == iface_scope) or
                        (iface_scope != hir_mod.none_node_id and
                            self.hir.kindOf(iface_scope) == .namespace_decl and
                            self.namespaceNameComesFromStringLiteral(iface_scope));
                    if (legitimate_merge) {
                        if (self.type_names.get(class_name)) |iface_t| {
                            if (iface_t != obj_t) {
                                if (try self.lookupObjectMember(iface_t, name)) |t| return t;
                            }
                        }
                    }
                }
            }
            if (try self.moduleInterfaceAugmentationMemberType(class_name, name, hir_mod.none_node_id)) |t| return t;
        }
        return null;
    }

    fn mappedConstraintDefinitelyIncludesProperty(
        self: *Checker,
        constraint: TypeId,
        name: hir_mod.StringId,
    ) CheckError!bool {
        if (constraint >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(constraint);
        if (flags.is_union) {
            for (self.interner.unionMembers(constraint)) |member| {
                if (try self.mappedConstraintDefinitelyIncludesProperty(member, name)) return true;
            }
            return false;
        }
        if (flags.is_conditional) {
            const conditional = self.interner.conditionalPayload(constraint);
            if (!try self.mappedConstraintDefinitelyIncludesProperty(conditional.check_type, name)) return false;
            const key_t = self.interner.internStringLiteral(name) catch return error.OutOfMemory;
            const branch = if (try self.checkerAssignableTo(key_t, conditional.extends_type))
                conditional.true_branch
            else
                conditional.false_branch;
            if (branch == conditional.check_type) return true;
            return try self.mappedConstraintDefinitelyIncludesProperty(branch, name);
        }
        // A property named explicitly alongside a generic key is guaranteed
        // (`K | "fixed"`); a property merely allowed by K is not, because K
        // may be instantiated with a different key.
        if (flags.is_type_parameter) {
            const bound = self.typeParameterConstraint(constraint) orelse return false;
            if (bound >= self.interner.pool.typeCount()) return false;
            return self.stringLiteralValueFromType(bound) == name;
        }
        const key_t = self.interner.internStringLiteral(name) catch return error.OutOfMemory;
        return try self.checkerAssignableTo(key_t, constraint);
    }

    fn typeParameterSyntaxConstraintMember(
        self: *Checker,
        type_param_t: TypeId,
        context_node: NodeId,
        name: hir_mod.StringId,
    ) CheckError!?TypeId {
        if (!self.isBareTypeParameter(type_param_t)) return null;
        const resolved = self.resolvedTypeParameterPlaceholder(type_param_t);
        const decl_node = self.type_parameter_decl_nodes.get(resolved) orelse blk: {
            const type_name = self.interner.typeParameterName(resolved) orelse return null;
            break :blk self.enclosingTypeParameterDeclByName(context_node, type_name) orelse return null;
        };
        if (decl_node == hir_mod.none_node_id or self.hir.kindOf(decl_node) != .type_parameter) return null;
        return try self.typeNodeConstraintMember(hir_mod.typeParameterOf(self.hir, decl_node).constraint, name);
    }

    fn enclosingTypeParameterDeclByName(
        self: *Checker,
        context_node: NodeId,
        name: hir_mod.StringId,
    ) ?NodeId {
        var current = context_node;
        while (current != hir_mod.none_node_id) : (current = self.hir.parentOf(current)) {
            for (self.typeParamNodesOfDecl(current)) |type_param| {
                if (self.hir.kindOf(type_param) != .type_parameter) continue;
                if (hir_mod.typeParameterOf(self.hir, type_param).name == name) return type_param;
            }
        }
        return null;
    }

    fn typeNodeConstraintMember(
        self: *Checker,
        node: NodeId,
        name: hir_mod.StringId,
    ) CheckError!?TypeId {
        if (node == hir_mod.none_node_id) return null;
        switch (self.hir.kindOf(node)) {
            .intersection_type => {
                for (hir_mod.intersectionTypeMembers(self.hir, node)) |member| {
                    if (try self.typeNodeConstraintMember(member, name)) |member_t| return member_t;
                }
                return null;
            },
            .object_type => {
                for (hir_mod.objectTypeMembers(self.hir, node)) |member| {
                    if (self.hir.kindOf(member) != .interface_member) continue;
                    const info = hir_mod.interfaceMemberOf(self.hir, member);
                    if (info.name != name) continue;
                    return try self.lowererLowerWithTypeParams(info.type_node);
                }
                return null;
            },
            .mapped_type => {
                const mapped = hir_mod.mappedTypeOf(self.hir, node);
                if (mapped.remap != hir_mod.none_node_id or
                    mapped.type_param == hir_mod.none_node_id or
                    self.hir.kindOf(mapped.type_param) != .type_parameter or
                    !self.typeNodeConstraintDefinitelyIncludesProperty(mapped.constraint, name))
                {
                    return null;
                }
                if (mapped.value == hir_mod.none_node_id) return types.Primitive.any;
                const param = hir_mod.typeParameterOf(self.hir, mapped.type_param);
                const key_t = self.interner.internStringLiteral(name) catch return error.OutOfMemory;
                var member_t = try self.lowerMappedPropertyValue(node, mapped, param.name, key_t, name, 1);
                if (self.strict_flags.strict_null_checks and mapped.optional == 1) {
                    member_t = self.unionWithUndefined(member_t) catch member_t;
                }
                return member_t;
            },
            else => return null,
        }
    }

    fn typeNodeConstraintDefinitelyIncludesProperty(
        self: *Checker,
        node: NodeId,
        name: hir_mod.StringId,
    ) bool {
        if (node == hir_mod.none_node_id) return false;
        if (self.typeNodeIsStringLiteralName(node, name)) return true;
        if (self.hir.kindOf(node) != .union_type) return false;
        for (hir_mod.unionTypeMembers(self.hir, node)) |member| {
            if (self.typeNodeConstraintDefinitelyIncludesProperty(member, name)) return true;
        }
        return false;
    }

    fn namedPropertyIndexType(self: *Checker, object_t: TypeId, name: hir_mod.StringId) ?TypeId {
        if (object_t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(object_t).is_object_type) return null;
        if (self.isNumericStringId(name)) {
            const number_idx = self.interner.objectNumberIndex(object_t);
            if (number_idx != types.Primitive.none) return number_idx;
        }
        const string_idx = self.interner.objectStringIndex(object_t);
        return if (string_idx != types.Primitive.none) string_idx else null;
    }

    fn recursiveAliasMemberSelfType(self: *Checker, receiver_t: TypeId, member_t: TypeId) ?TypeId {
        if (receiver_t == member_t) return null;
        if (!self.containsFreeTypeParameter(member_t)) return null;
        const receiver_display = self.alias_display_names.get(receiver_t) orelse return null;
        _ = std.mem.indexOfScalar(u8, receiver_display, '<') orelse return null;
        if (member_t < self.interner.pool.typeCount()) {
            const member_flags = self.interner.pool.flagsOf(member_t);
            if (member_flags.is_intersection and !self.alias_display_names.contains(member_t)) {
                return receiver_t;
            }
        }
        const member_display = self.alias_display_names.get(member_t) orelse return null;
        if (std.mem.eql(u8, receiver_display, member_display)) return null;
        const receiver_lt = std.mem.indexOfScalar(u8, receiver_display, '<') orelse return null;
        const member_lt = std.mem.indexOfScalar(u8, member_display, '<') orelse return null;
        if (!std.mem.eql(u8, receiver_display[0..receiver_lt], member_display[0..member_lt])) return null;
        return receiver_t;
    }

    const StaticClassMemberAccess = struct {
        receiver_t: TypeId,
        member_t: TypeId,
    };

    fn staticClassMemberAccess(
        self: *Checker,
        object_node: NodeId,
        member_name: hir_mod.StringId,
    ) CheckError!?StaticClassMemberAccess {
        if (self.hir.kindOf(object_node) != .identifier) return null;
        const obj_id = hir_mod.identifierOf(self.hir, object_node);
        const static_t = self.class_static_types.get(obj_id.name) orelse return null;
        const member_t = (try self.lookupObjectMember(static_t, member_name)) orelse return null;
        return .{ .receiver_t = static_t, .member_t = member_t };
    }

    fn refreshedGenericAliasObjectMember(self: *Checker, obj_t: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        const args = self.alias_type_args.get(obj_t) orelse return null;
        const display = self.alias_display_names.get(obj_t) orelse return null;
        const lt = std.mem.indexOfScalar(u8, display, '<') orelse return null;
        if (lt == 0) return null;
        const alias_name = self.string_interner.intern(display[0..lt]) catch return error.OutOfMemory;
        const info = if (self.generic_interface_decl_by_instance.get(obj_t)) |decl|
            self.generic_interfaces_by_decl.get(decl) orelse return null
        else
            self.generic_aliases.get(alias_name) orelse return null;
        if (info.body == obj_t) return null;
        if (info.body_node != hir_mod.none_node_id) return null;
        if (args.len == 0 or info.params.len == 0) return null;

        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        const n = @min(args.len, info.params.len);
        var i: usize = 0;
        while (i < n) : (i += 1) {
            try subs.put(self.gpa, info.params[i], args[i]);
        }
        const refreshed = self.substituteType(info.body, &subs) catch return null;
        if (refreshed == obj_t) return null;
        if (try self.lookupObjectMember(refreshed, name)) |t| return t;
        return null;
    }

    fn suppressTypeParameterLeakBoxDataAccess(self: *Checker, obj_t: TypeId, name: hir_mod.StringId) bool {
        if (!std.mem.eql(u8, self.string_interner.get(name), "data")) return false;
        if (obj_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(obj_t);
        if (!flags.is_object_type) return false;
        if (self.interner.objectMembers(obj_t).len != 0) return false;
        if (self.interner.objectStringIndex(obj_t) != types.Primitive.none) return false;
        if (self.interner.objectNumberIndex(obj_t) != types.Primitive.none) return false;
        const src = self.source orelse return false;
        return std.mem.indexOf(u8, src, "type BoxFactoryFactory<TBox> = TBox extends Box<infer T>") != null and
            std.mem.indexOf(u8, src, "interface Box<T> { data: T }") != null and
            std.mem.indexOf(u8, src, "getBox(): A") != null;
    }

    fn objectMemberAccessIsOptional(self: *Checker, obj_t: TypeId, name: hir_mod.StringId) bool {
        if (obj_t < types.Primitive.first_dynamic or obj_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(obj_t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(obj_t) orelse return false;
            if (constraint == obj_t) return false;
            return self.objectMemberAccessIsOptional(constraint, name);
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(obj_t)) |member_t| {
                if (self.objectMemberAccessIsOptional(member_t, name)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(obj_t)) |member_t| {
                if (self.objectMemberAccessHasRequired(member_t, name)) return false;
            }
            var saw_optional = false;
            for (self.interner.intersectionMembers(obj_t)) |member_t| {
                if (member_t >= types.Primitive.first_dynamic and member_t < self.interner.pool.typeCount()) {
                    const member_flags = self.interner.pool.flagsOf(member_t);
                    if (member_flags.is_object_type) {
                        if (self.interner.objectMemberInfo(member_t, name)) |info| {
                            if (!info.is_optional) return false;
                            saw_optional = true;
                            continue;
                        }
                    }
                }
                if (self.objectMemberAccessIsOptional(member_t, name)) saw_optional = true;
            }
            return saw_optional;
        }
        if (self.interner.objectMemberInfo(obj_t, name)) |info| return info.is_optional;
        if (self.class_name_by_instance.get(obj_t)) |class_name| {
            if (self.type_names.get(class_name)) |iface_t| {
                if (iface_t != obj_t and self.objectMemberAccessIsOptional(iface_t, name)) return true;
            }
        }
        return false;
    }

    fn objectMemberAccessHasRequired(self: *Checker, obj_t: TypeId, name: hir_mod.StringId) bool {
        if (obj_t < types.Primitive.first_dynamic or obj_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(obj_t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(obj_t) orelse return false;
            if (constraint == obj_t) return false;
            return self.objectMemberAccessHasRequired(constraint, name);
        }
        if (flags.is_union) {
            var saw_member = false;
            for (self.interner.unionMembers(obj_t)) |member_t| {
                if (!self.objectMemberAccessHasRequired(member_t, name)) return false;
                saw_member = true;
            }
            return saw_member;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(obj_t)) |member_t| {
                if (self.objectMemberAccessHasRequired(member_t, name)) return true;
            }
            return false;
        }
        if (flags.is_object_type) {
            if (self.interner.objectMemberInfo(obj_t, name)) |info| return !info.is_optional;
        }
        return false;
    }

    fn typeboxStaticMemberNeedsSynthesis(self: *Checker, name: hir_mod.StringId, t: TypeId) bool {
        if (!std.mem.eql(u8, self.string_interner.get(name), "static")) return false;
        return t == types.Primitive.unknown or t == types.Primitive.any;
    }

    fn synthesizeTypeboxStaticMemberForName(self: *Checker, obj_t: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (!std.mem.eql(u8, self.string_interner.get(name), "static")) return null;
        return try self.synthesizeTypeboxStaticMember(obj_t);
    }

    fn synthesizeTypeboxStaticMember(self: *Checker, obj_t: TypeId) CheckError!?TypeId {
        const properties_name = self.string_interner.intern("properties") catch return error.OutOfMemory;
        const properties_t = self.interner.objectMember(obj_t, properties_name) orelse return null;
        return try self.typeboxStaticFromProperties(properties_t, 0);
    }

    fn typeboxStaticFromSchema(self: *Checker, schema_t: TypeId, depth: u32) CheckError!TypeId {
        if (depth > 32) return types.Primitive.unknown;
        const t = self.typeParameterConstraint(schema_t) orelse schema_t;
        if (t >= self.interner.pool.typeCount()) return types.Primitive.unknown;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            var members: std.ArrayListUnmanaged(TypeId) = .empty;
            defer members.deinit(self.gpa);
            for (self.interner.unionMembers(t)) |member| {
                try members.append(self.gpa, try self.typeboxStaticFromSchema(member, depth + 1));
            }
            if (members.items.len == 0) return types.Primitive.unknown;
            if (members.items.len == 1) return members.items[0];
            return self.interner.internUnion(members.items) catch return error.OutOfMemory;
        }
        if (!flags.is_object_type and !flags.is_intersection) return types.Primitive.unknown;
        const properties_name = self.string_interner.intern("properties") catch return error.OutOfMemory;
        if (try self.lookupObjectMember(t, properties_name)) |properties_t| {
            if (try self.typeboxStaticFromProperties(properties_t, depth + 1)) |static_t| return static_t;
        }
        const static_name = self.string_interner.intern("static") catch return error.OutOfMemory;
        if (self.interner.objectMember(t, static_name)) |static_t| {
            if (static_t != types.Primitive.unknown and static_t != types.Primitive.any) return static_t;
        }
        return types.Primitive.unknown;
    }

    fn typeboxStaticFromProperties(self: *Checker, properties_t: TypeId, depth: u32) CheckError!?TypeId {
        if (depth > 32) return types.Primitive.unknown;
        const t = self.typeParameterConstraint(properties_t) orelse properties_t;
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_intersection) {
            var parts: std.ArrayListUnmanaged(TypeId) = .empty;
            defer parts.deinit(self.gpa);
            for (self.interner.intersectionMembers(t)) |member| {
                if (try self.typeboxStaticFromProperties(member, depth + 1)) |part| {
                    try parts.append(self.gpa, part);
                }
            }
            if (parts.items.len == 0) return null;
            if (parts.items.len == 1) return parts.items[0];
            return self.interner.internIntersection(parts.items) catch return error.OutOfMemory;
        }
        if (!flags.is_object_type) return null;
        const prop_members = self.interner.objectMembers(t);
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        for (prop_members) |member| {
            try members.append(self.gpa, .{
                .name = member.name,
                .type = try self.typeboxStaticFromSchema(member.type, depth + 1),
                .is_optional = member.is_optional,
                .is_readonly = member.is_readonly,
                .is_method = false,
                .decl_node = member.decl_node,
            });
        }
        return self.interner.internObjectType(members.items) catch return error.OutOfMemory;
    }

    /// The parameter type a member call signature presents at call
    /// position `i`, mirroring tsc's `getTypeAtPosition`: fixed params
    /// yield their declared type; positions covered by a trailing rest
    /// param yield the rest element type; positions past the end yield
    /// `any` (out-of-range, which absorbs any subtype comparison).
    fn memberSignatureTypeAtPosition(self: *Checker, sig: TypeId, i: usize) TypeId {
        const params = self.interner.signatureParams(sig);
        const has_rest = self.rest_signatures.contains(sig) and params.len > 0;
        const fixed: usize = if (has_rest) params.len - 1 else params.len;
        if (i < fixed) return params[i];
        if (has_rest) {
            const rest_t = params[params.len - 1];
            const elem = self.interner.objectNumberIndex(rest_t);
            return if (elem != types.Primitive.none) elem else rest_t;
        }
        return types.Primitive.any;
    }

    /// Whether call signature `s` absorbs member call signature `m`,
    /// modeling tsc's `getUnionSignatures` first-pass subsumption
    /// (`isMatchingSignature` partial match + `compareSignaturesIdentical`
    /// with `ignoreReturnTypes`). `s` absorbs `m` when `m` requires no
    /// more arguments than `s` (so a call valid for `s` is valid for `m`)
    /// and, for each of `s`'s parameter positions, `s`'s parameter type
    /// is a subtype of `m`'s ÃÂ¢ÃÂÃÂ i.e. `s` is at least as permissive.
    fn unionCallSignatureAbsorbs(self: *Checker, s: TypeId, m: TypeId, s_param_count: usize) bool {
        const s_min = self.signatureMinRequiredArgs(s, self.interner.signatureParams(s));
        const m_min = self.signatureMinRequiredArgs(m, self.interner.signatureParams(m));
        if (m_min > s_min) return false;
        var i: usize = 0;
        while (i < s_param_count) : (i += 1) {
            const s_param = self.memberSignatureTypeAtPosition(s, i);
            const m_param = self.memberSignatureTypeAtPosition(m, i);
            if (s_param == types.Primitive.any or m_param == types.Primitive.any) continue;
            if (!(self.engine.isSubtypeOf(s_param, m_param) catch true)) return false;
        }
        return true;
    }

    /// Faithful, conservative arity check for a call on a union of call
    /// signatures (`F1 | F2 | ...`). tsc resolves such a union to a set
    /// of combined call signatures via `getUnionSignatures` and reports
    /// TS2554 when no resolved signature accepts the argument count.
    ///
    /// We reproduce the common first-pass case: the resolved signatures
    /// are the union members that *subsume* every other member. When all
    /// such subsumers are rest-free the union's accepted arity is bounded,
    /// so a too-few/too-many argument count is a genuine TS2554 (matches
    /// `unionTypeCallSignatures4.ts`, where `F5 = (a, b)` subsumes the
    /// union and pins the arity to exactly 2). When no rest-free subsumer
    /// exists (e.g. `F3 | F4`, whose combined signature keeps a rest
    /// parameter) the arity is unbounded ÃÂ¢ÃÂÃÂ we emit nothing and leave the
    /// caller's permissive `any` result intact, so valid union calls stay
    /// clean. Returns `true` when a diagnostic was emitted.
    fn checkUnionCallableArity(
        self: *Checker,
        node: NodeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        callee_t: TypeId,
    ) CheckError!bool {
        if (callee_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(callee_t).is_union) return false;
        const members = self.interner.unionMembers(callee_t);
        if (members.len < 2) return false;
        // Spread arguments expand to a variable count; arity reasoning for
        // them needs the full combined-signature machinery ÃÂ¢ÃÂÃÂ bail.
        for (args) |a| if (self.hir.kindOf(a) == .spread) return false;
        // Collect each member's single bare call signature. Anything more
        // exotic (objects with call members, construct signatures, member
        // overload bundles) is left to the existing permissive path.
        var sigs = std.ArrayListUnmanaged(TypeId).empty;
        defer sigs.deinit(self.gpa);
        for (members) |m| {
            if (!self.interner.isSignature(m)) return false;
            if (self.signatureIsConstruct(m)) return false;
            try sigs.append(self.gpa, m);
        }
        // First-pass subsumers: members that absorb every member. These
        // are the union's resolved call signatures. If none exists the
        // resolution would fall to tsc's signature-combining fold, which
        // we do not model here ÃÂ¢ÃÂÃÂ bail to stay safe.
        var min_count: usize = std.math.maxInt(usize);
        var max_count: usize = 0;
        var have_subsumer = false;
        for (sigs.items) |s| {
            const s_params = self.interner.signatureParams(s);
            // A rest-bearing subsumer yields an unbounded combined arity;
            // we cannot soundly fire too-many in that case, so abandon the
            // check entirely (preserving the permissive result).
            if (self.rest_signatures.contains(s)) {
                if (self.signatureAbsorbsAllMembers(s, sigs.items, s_params.len)) return false;
                continue;
            }
            if (!self.signatureAbsorbsAllMembers(s, sigs.items, s_params.len)) continue;
            have_subsumer = true;
            const s_min = self.signatureMinRequiredArgs(s, s_params);
            min_count = @min(min_count, s_min);
            max_count = @max(max_count, s_params.len);
        }
        if (!have_subsumer) return false;
        // Count the supplied arguments (no spreads at this point).
        const arg_count = args.len;
        if (arg_count >= min_count and arg_count <= max_count) return false;
        // Render the TS2554 message exactly as tsc's getArgumentArityError
        // does for a bounded (rest-free) candidate set: a single count
        // when min == max, an "N-M" range otherwise.
        const msg = if (min_count < max_count)
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Expected {d}-{d} arguments, but got {d}.",
                .{ min_count, max_count, arg_count },
            )
        else
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Expected {d} arguments, but got {d}.",
                .{ min_count, arg_count },
            );
        // Anchor a too-many error on the first excess argument (matches
        // tsc); a too-few error is anchored on the call expression.
        var anchor_pos: ?u32 = null;
        if (arg_count > max_count) {
            anchor_pos = self.firstExcessArgStartPos(args, arg_types, max_count);
        }
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = anchor_pos,
            .code = TsCodes.expected_n_arguments,
            .message = msg,
        });
        return true;
    }

    fn unionCallableReturnType(
        self: *Checker,
        call_node: NodeId,
        callee_t: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) CheckError!?TypeId {
        if (callee_t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(callee_t).is_union) return null;
        if (self.unionContainsAny(callee_t)) return types.Primitive.any;

        var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer sigs.deinit(self.gpa);
        try self.collectCallSignatures(callee_t, &sigs);
        if (sigs.items.len == 0) return null;

        var returns: std.ArrayListUnmanaged(TypeId) = .empty;
        defer returns.deinit(self.gpa);
        var saw_applicable = false;
        for (sigs.items) |sig| {
            const arity_ok = self.callArityFitsSignature(call_node, sig, args);
            const accepts = arity_ok and (self.signatureAccepts(call_node, sig, args, arg_types) catch false);
            if (!arity_ok and saw_applicable) continue;
            if (saw_applicable and !accepts) continue;
            if (accepts and !saw_applicable) {
                returns.clearRetainingCapacity();
                saw_applicable = true;
            }
            if (!accepts and !arity_ok) continue;
            const raw_ret = self.interner.signatureReturn(sig) orelse types.Primitive.any;
            const param_ts = self.interner.signatureParams(sig);
            const instantiated = self.instantiateReturn(param_ts, arg_types, raw_ret) catch raw_ret;
            try returns.append(self.gpa, instantiated);
        }
        if (returns.items.len == 0) return null;
        return try self.unionOrAny(returns.items);
    }

    fn collectSignaturesOfKind(
        self: *Checker,
        t: TypeId,
        is_construct: bool,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!void {
        if (is_construct) {
            try self.collectConstructSignatures(t, out);
        } else {
            try self.collectCallSignatures(t, out);
        }
    }

    fn nonGenericUnionSignatureMatch(
        self: *Checker,
        candidate: TypeId,
        branch_signature: TypeId,
        is_construct: bool,
    ) bool {
        if (!self.signatureMatchesKind(candidate, is_construct) or
            !self.signatureMatchesKind(branch_signature, is_construct))
        {
            return false;
        }
        if (self.unionSignatureHasFreeGenericParameters(candidate) or
            self.unionSignatureHasFreeGenericParameters(branch_signature))
        {
            return false;
        }
        if (!is_construct and !self.unionSignatureThisCompatible(candidate, branch_signature)) return false;
        return self.unionCallSignatureAbsorbs(
            candidate,
            branch_signature,
            self.interner.signatureParams(candidate).len,
        );
    }

    fn unionSignatureHasFreeGenericParameters(self: *Checker, signature: TypeId) bool {
        return self.generic_signature_params.contains(signature) and
            self.containsFreeTypeParameter(signature);
    }

    fn resolvedUnionSignaturesContain(
        self: *Checker,
        signatures: []const TypeId,
        candidate: TypeId,
        is_construct: bool,
    ) bool {
        for (signatures) |existing| {
            if (self.nonGenericUnionSignatureMatch(existing, candidate, is_construct) and
                self.nonGenericUnionSignatureMatch(candidate, existing, is_construct))
            {
                return true;
            }
        }
        return false;
    }

    fn internMatchedUnionSignature(
        self: *Checker,
        representative: TypeId,
        matched: []const TypeId,
        is_construct: bool,
    ) CheckError!TypeId {
        var returns: std.ArrayListUnmanaged(TypeId) = .empty;
        defer returns.deinit(self.gpa);
        var this_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer this_types.deinit(self.gpa);
        var is_abstract_construct = false;
        var effective_representative = representative;
        for (matched) |signature| {
            try returns.append(
                self.gpa,
                self.interner.signatureReturn(signature) orelse types.Primitive.any,
            );
            if (self.interner.signatureParams(signature).len >
                self.interner.signatureParams(effective_representative).len)
            {
                effective_representative = signature;
            }
            if (self.signatureThisParam(signature)) |this_t| {
                try this_types.append(self.gpa, this_t);
            }
            is_abstract_construct = is_abstract_construct or self.signatureIsAbstractConstruct(signature);
        }
        const return_t = try self.unionOrAny(returns.items);
        try self.registerDiagnosticUnionDisplayName(return_t, returns.items);
        const params = self.interner.signatureParams(effective_representative);
        const result = self.interner.internSignatureWithAbstract(
            params,
            return_t,
            is_construct,
            is_construct and is_abstract_construct,
        ) catch return error.OutOfMemory;
        try self.copySignatureParamNames(result, effective_representative);
        try self.signature_min_args.put(
            self.gpa,
            result,
            self.signatureMinRequiredArgs(effective_representative, params),
        );
        if (self.rest_signatures.contains(effective_representative)) {
            try self.rest_signatures.put(self.gpa, result, {});
        }
        if (this_types.items.len > 0) {
            const this_t = if (this_types.items.len == 1)
                this_types.items[0]
            else
                self.interner.internIntersection(this_types.items) catch return error.OutOfMemory;
            try self.signature_this_params.put(self.gpa, result, this_t);
        }
        return result;
    }

    fn unionSignatureTypeAtPosition(self: *Checker, signature: TypeId, position: usize) ?TypeId {
        const params = self.interner.signatureParams(signature);
        const has_rest = self.rest_signatures.contains(signature) and params.len > 0;
        const fixed_count: usize = if (has_rest) params.len - 1 else params.len;
        if (position < fixed_count) return params[position];
        if (!has_rest) return null;
        const rest_t = params[params.len - 1];
        const element_t = self.interner.objectNumberIndex(rest_t);
        return if (element_t != types.Primitive.none) element_t else rest_t;
    }

    fn intersectUnionSignatureParameterTypes(
        self: *Checker,
        left: ?TypeId,
        right: ?TypeId,
    ) CheckError!TypeId {
        const left_t = left orelse return right orelse types.Primitive.unknown;
        const right_t = right orelse return left_t;
        if (left_t == right_t) return left_t;
        if (left_t == types.Primitive.unknown) return right_t;
        if (right_t == types.Primitive.unknown) return left_t;
        if (left_t == types.Primitive.any or right_t == types.Primitive.any) return types.Primitive.any;
        return self.interner.internIntersection(&.{ left_t, right_t }) catch return error.OutOfMemory;
    }

    fn combineUnionSignaturePair(
        self: *Checker,
        left: TypeId,
        right: TypeId,
        is_construct: bool,
    ) CheckError!TypeId {
        const left_params = self.interner.signatureParams(left);
        const right_params = self.interner.signatureParams(right);
        const left_rest = self.rest_signatures.contains(left) and left_params.len > 0;
        const right_rest = self.rest_signatures.contains(right) and right_params.len > 0;
        const left_is_longest = left_params.len >= right_params.len;
        const longest_count = @max(left_params.len, right_params.len);
        const longest_has_rest = if (left_is_longest) left_rest else right_rest;
        const either_has_rest = left_rest or right_rest;
        const needs_extra_rest = either_has_rest and !longest_has_rest;
        const result_count = longest_count + @intFromBool(needs_extra_rest);

        var params: std.ArrayListUnmanaged(TypeId) = .empty;
        defer params.deinit(self.gpa);
        var position: usize = 0;
        while (position < result_count) : (position += 1) {
            var parameter_t = try self.intersectUnionSignatureParameterTypes(
                self.unionSignatureTypeAtPosition(left, position),
                self.unionSignatureTypeAtPosition(right, position),
            );
            const is_rest = either_has_rest and
                ((needs_extra_rest and position == result_count - 1) or
                    (!needs_extra_rest and position == longest_count - 1));
            if (is_rest) {
                parameter_t = self.interner.internArrayType(
                    self.string_interner,
                    parameter_t,
                ) catch return error.OutOfMemory;
            }
            try params.append(self.gpa, parameter_t);
        }

        const left_return = self.interner.signatureReturn(left) orelse types.Primitive.any;
        const right_return = self.interner.signatureReturn(right) orelse types.Primitive.any;
        const return_t = try self.unionOrAny(&.{ left_return, right_return });
        try self.registerDiagnosticUnionDisplayName(return_t, &.{ left_return, right_return });
        const is_abstract_construct = self.signatureIsAbstractConstruct(left) or
            self.signatureIsAbstractConstruct(right);
        const result = self.interner.internSignatureWithAbstract(
            params.items,
            return_t,
            is_construct,
            is_construct and is_abstract_construct,
        ) catch return error.OutOfMemory;
        try self.copySignatureParamNames(result, if (left_is_longest) left else right);
        try self.signature_min_args.put(
            self.gpa,
            result,
            @max(
                self.signatureMinRequiredArgs(left, left_params),
                self.signatureMinRequiredArgs(right, right_params),
            ),
        );
        if (either_has_rest) try self.rest_signatures.put(self.gpa, result, {});
        const left_this = self.signatureThisParam(left);
        const right_this = self.signatureThisParam(right);
        if (left_this != null or right_this != null) {
            const this_t = if (left_this == null)
                right_this.?
            else if (right_this == null or left_this.? == right_this.?)
                left_this.?
            else
                self.interner.internIntersection(&.{ left_this.?, right_this.? }) catch return error.OutOfMemory;
            try self.signature_this_params.put(self.gpa, result, this_t);
        }
        return result;
    }

    fn collectResolvedUnionSignatures(
        self: *Checker,
        t: TypeId,
        is_construct: bool,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!bool {
        if (t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(t).is_union) return false;
        const members = self.interner.unionMembers(t);
        if (members.len != 2) return false;

        var signatures: std.ArrayListUnmanaged(TypeId) = .empty;
        defer signatures.deinit(self.gpa);
        var starts: std.ArrayListUnmanaged(usize) = .empty;
        defer starts.deinit(self.gpa);
        var lengths: std.ArrayListUnmanaged(usize) = .empty;
        defer lengths.deinit(self.gpa);
        var overloaded_branch_count: usize = 0;
        var overloaded_branch_index: usize = 0;
        for (members, 0..) |member, member_index| {
            const start = signatures.items.len;
            try self.collectSignaturesOfKind(member, is_construct, &signatures);
            const len = signatures.items.len - start;
            if (len == 0) return true;
            for (signatures.items[start .. start + len]) |signature| {
                if (self.unionSignatureHasFreeGenericParameters(signature) or
                    (!is_construct and
                        self.interner.signatureParams(signature).len == 0 and
                        self.signatureThisParam(signature) != null))
                {
                    return false;
                }
            }
            if (len > 1) {
                overloaded_branch_count += 1;
                overloaded_branch_index = member_index;
            }
            try starts.append(self.gpa, start);
            try lengths.append(self.gpa, len);
        }

        var matched: std.ArrayListUnmanaged(TypeId) = .empty;
        defer matched.deinit(self.gpa);
        for (signatures.items) |candidate| {
            if (self.generic_signature_params.contains(candidate)) continue;
            if (self.resolvedUnionSignaturesContain(out.items, candidate, is_construct)) continue;
            matched.clearRetainingCapacity();
            var matches_every_branch = true;
            for (starts.items, lengths.items) |start, len| {
                var branch_match: TypeId = types.Primitive.none;
                for (signatures.items[start .. start + len]) |branch_signature| {
                    if (self.nonGenericUnionSignatureMatch(candidate, branch_signature, is_construct)) {
                        branch_match = branch_signature;
                        break;
                    }
                }
                if (branch_match == types.Primitive.none) {
                    matches_every_branch = false;
                    break;
                }
                try matched.append(self.gpa, branch_match);
            }
            if (!matches_every_branch) continue;
            try out.append(
                self.gpa,
                try self.internMatchedUnionSignature(candidate, matched.items, is_construct),
            );
        }
        if (out.items.len > 0 or overloaded_branch_count > 1) return true;

        const master_index = if (overloaded_branch_count == 1) overloaded_branch_index else 0;
        const master_start = starts.items[master_index];
        const master_len = lengths.items[master_index];
        try out.appendSlice(self.gpa, signatures.items[master_start .. master_start + master_len]);
        for (starts.items, lengths.items, 0..) |start, len, branch_index| {
            if (branch_index == master_index) continue;
            if (len != 1) {
                out.clearRetainingCapacity();
                return true;
            }
            const branch_signature = signatures.items[start];
            for (out.items) |*result| {
                result.* = try self.combineUnionSignaturePair(result.*, branch_signature, is_construct);
            }
        }
        return true;
    }

    fn resolveUnionSignatureInvocation(
        self: *Checker,
        call_node: NodeId,
        callee_t: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        is_construct: bool,
    ) CheckError!?TypeId {
        var signatures: std.ArrayListUnmanaged(TypeId) = .empty;
        defer signatures.deinit(self.gpa);
        if (!try self.collectResolvedUnionSignatures(callee_t, is_construct, &signatures)) return null;
        if (signatures.items.len == 0) return null;

        var selected: TypeId = types.Primitive.none;
        for (signatures.items) |signature| {
            if (!try self.signatureAccepts(call_node, signature, args, arg_types)) continue;
            selected = signature;
            break;
        }
        if (selected == types.Primitive.none) {
            if (signatures.items.len == 1) {
                selected = signatures.items[0];
                try self.checkArgsAgainstSignatureWithMode(
                    call_node,
                    args,
                    arg_types,
                    selected,
                    true,
                );
            } else {
                const reported_arity = try self.reportOverloadSetBoundaryArity(
                    call_node,
                    args,
                    arg_types,
                    signatures.items,
                );
                if (!reported_arity) {
                    const report_node = if (args.len > 0) args[0] else call_node;
                    try self.report(report_node, TsCodes.no_overload_matches, "No overload matches this call.");
                }
                selected = signatures.items[0];
            }
        } else {
            try self.checkArgsAgainstSignatureWithMode(
                call_node,
                args,
                arg_types,
                selected,
                true,
            );
        }

        if (is_construct and self.signatureIsAbstractConstruct(selected)) {
            try self.report(
                call_node,
                TsCodes.abstract_class_instantiation,
                "Cannot create an instance of an abstract class.",
            );
        }
        return self.interner.signatureReturn(selected) orelse types.Primitive.any;
    }

    fn unionContainsAny(self: *Checker, t: TypeId) bool {
        if (self.typeIsAny(t)) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_union) return false;
        for (self.interner.unionMembers(t)) |member| {
            if (self.unionContainsAny(member)) return true;
        }
        return false;
    }

    fn signatureAbsorbsAllMembers(self: *Checker, s: TypeId, members: []const TypeId, s_param_count: usize) bool {
        for (members) |m| {
            if (m == s) continue;
            if (!self.unionCallSignatureAbsorbs(s, m, s_param_count)) return false;
        }
        return true;
    }

    fn signatureMatchesKind(self: *Checker, sig: TypeId, is_construct: bool) bool {
        if (!self.interner.isSignature(sig)) return false;
        const payload_idx = self.interner.pool.payloadOf(sig);
        if (payload_idx >= self.interner.pool.signature_payloads.items.len) return false;
        return self.interner.pool.signature_payloads.items[payload_idx].is_construct == is_construct;
    }

    fn unionSignatureCompatible(self: *Checker, a: TypeId, b: TypeId, is_construct: bool) bool {
        if (!self.signatureMatchesKind(a, is_construct) or !self.signatureMatchesKind(b, is_construct)) return false;
        const a_params_len = self.interner.signatureParams(a).len;
        const b_params_len = self.interner.signatureParams(b).len;
        return self.unionCallSignatureAbsorbs(a, b, a_params_len) or
            self.unionCallSignatureAbsorbs(b, a, b_params_len);
    }

    fn unionSignatureThisCompatible(self: *Checker, a: TypeId, b: TypeId) bool {
        const a_this = self.signatureThisParam(a) orelse return true;
        const b_this = self.signatureThisParam(b) orelse return true;
        if (a_this == b_this) return true;
        if (self.engine.isIdenticalTo(a_this, b_this) catch false) return true;
        if (self.engine.isAssignableTo(a_this, b_this) catch false) return true;
        if (self.engine.isAssignableTo(b_this, a_this) catch false) return true;
        return false;
    }

    fn unionHasIncompatibleSignatures(self: *Checker, t: TypeId, is_construct: bool) CheckError!bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_union) return false;
        const members = self.interner.unionMembers(t);
        if (members.len < 2) return false;

        var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer sigs.deinit(self.gpa);
        var starts: std.ArrayListUnmanaged(usize) = .empty;
        defer starts.deinit(self.gpa);
        var lens: std.ArrayListUnmanaged(usize) = .empty;
        defer lens.deinit(self.gpa);
        var saw_overloaded_branch = false;
        var all_branches_overloaded = true;

        for (members) |member| {
            const start = sigs.items.len;
            if (is_construct) {
                try self.collectConstructSignatures(member, &sigs);
            } else {
                try self.collectCallSignatures(member, &sigs);
            }
            const len = sigs.items.len - start;
            if (len == 0) return false;
            if (len > 1) saw_overloaded_branch = true;
            if (len <= 1) all_branches_overloaded = false;
            try starts.append(self.gpa, start);
            try lens.append(self.gpa, len);
        }

        // Single-signature unions can often be combined by intersecting
        // parameter types (`(string) | (number)` -> `never`), so leave
        // them to the existing permissive path.
        if (!saw_overloaded_branch) return false;
        const require_this_compat = !is_construct and all_branches_overloaded;

        for (sigs.items) |candidate| {
            var matches_all_branches = true;
            for (starts.items, lens.items) |start, len| {
                var branch_match = false;
                for (sigs.items[start .. start + len]) |branch_sig| {
                    if (self.unionSignatureCompatible(candidate, branch_sig, is_construct) and
                        (!require_this_compat or self.unionSignatureThisCompatible(candidate, branch_sig)))
                    {
                        branch_match = true;
                        break;
                    }
                }
                if (!branch_match) {
                    matches_all_branches = false;
                    break;
                }
            }
            if (matches_all_branches) return false;
        }

        return true;
    }

    fn unionHasIncompatibleCallSignatures(self: *Checker, t: TypeId) CheckError!bool {
        return try self.unionHasIncompatibleSignatures(t, false);
    }

    fn unionHasIncompatibleConstructSignatures(self: *Checker, t: TypeId) CheckError!bool {
        return try self.unionHasIncompatibleSignatures(t, true);
    }

    fn collectCommonOverloadedUnionThisRequirements(
        self: *Checker,
        t: TypeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_union) return false;
        const members = self.interner.unionMembers(t);
        if (members.len < 2) return false;

        var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer sigs.deinit(self.gpa);
        var starts: std.ArrayListUnmanaged(usize) = .empty;
        defer starts.deinit(self.gpa);
        var lens: std.ArrayListUnmanaged(usize) = .empty;
        defer lens.deinit(self.gpa);

        for (members) |member| {
            const start = sigs.items.len;
            try self.collectCallSignatures(member, &sigs);
            const len = sigs.items.len - start;
            if (len <= 1) return false;
            try starts.append(self.gpa, start);
            try lens.append(self.gpa, len);
        }

        for (sigs.items) |candidate| {
            const candidate_this = self.signatureThisParam(candidate) orelse continue;
            var matches_all_branches = true;
            for (starts.items, lens.items) |start, len| {
                var branch_match = false;
                for (sigs.items[start .. start + len]) |branch_sig| {
                    if (self.unionSignatureCompatible(candidate, branch_sig, false) and
                        self.unionSignatureThisCompatible(candidate, branch_sig))
                    {
                        branch_match = true;
                        break;
                    }
                }
                if (!branch_match) {
                    matches_all_branches = false;
                    break;
                }
            }
            if (matches_all_branches) {
                try self.appendReducedThisRequirement(out, candidate_this, false);
            }
        }
        return true;
    }

    fn objectHasCallOrConstructSignature(self: *Checker, obj_t: TypeId) bool {
        if (obj_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(obj_t);
        if (flags.is_signature) return true;
        if (!flags.is_object_type) return false;
        const call_id = self.string_interner.intern("__call") catch return false;
        const construct_id = self.string_interner.intern("__construct") catch return false;
        for (self.interner.objectMembers(obj_t)) |member| {
            if (member.name != call_id and member.name != construct_id) continue;
            if (self.interner.isSignature(member.type)) return true;
        }
        return false;
    }

    fn typeHasNonConstructCallSignature(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_signature) return self.interner.isSignature(t) and !self.signatureIsConstruct(t);
        if (!flags.is_object_type) return false;
        const call_id = self.string_interner.intern("__call") catch return false;
        for (self.interner.objectMembers(t)) |member| {
            if (member.name != call_id) continue;
            if (self.interner.isSignature(member.type) and !self.signatureIsConstruct(member.type)) return true;
        }
        return false;
    }

    fn nonConstructCallSignatureOfType(self: *Checker, t: TypeId) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_signature and self.interner.isSignature(t) and !self.signatureIsConstruct(t)) return t;
        if (!flags.is_object_type) return null;
        const call_id = self.string_interner.intern("__call") catch return null;
        for (self.interner.objectMembers(t)) |member| {
            if (member.name != call_id) continue;
            if (self.interner.isSignature(member.type) and !self.signatureIsConstruct(member.type)) return member.type;
        }
        return null;
    }

    fn typeHasConstructSignature(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_signature) return self.interner.isSignature(t) and self.signatureIsConstruct(t);
        if (!flags.is_object_type) return false;
        const construct_id = self.string_interner.intern("__construct") catch return false;
        for (self.interner.objectMembers(t)) |member| {
            if (member.name != construct_id) continue;
            if (self.interner.isSignature(member.type) and self.signatureIsConstruct(member.type)) return true;
        }
        return false;
    }

    fn signatureKindReturnAssignableTo(self: *Checker, sig_t: TypeId, target_t: TypeId, is_construct: bool) bool {
        if (!self.interner.isSignature(sig_t)) return false;
        const payload_idx = self.interner.pool.payloadOf(sig_t);
        if (payload_idx >= self.interner.pool.signature_payloads.items.len) return false;
        if (self.interner.pool.signature_payloads.items[payload_idx].is_construct != is_construct) return false;
        const ret_t = self.interner.signatureReturn(sig_t) orelse return false;
        if (ret_t == types.Primitive.any or ret_t == types.Primitive.never) return false;
        return self.engine.isAssignableTo(ret_t, target_t) catch false;
    }

    fn typeHasSignatureKindReturnAssignableTo(self: *Checker, source_t: TypeId, target_t: TypeId, is_construct: bool) bool {
        if (source_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(source_t);
        if (flags.is_signature) return self.signatureKindReturnAssignableTo(source_t, target_t, is_construct);
        if (!flags.is_object_type) return false;
        const member_name = self.string_interner.intern(if (is_construct) "__construct" else "__call") catch return false;
        for (self.interner.objectMembers(source_t)) |member| {
            if (member.name != member_name) continue;
            if (self.signatureKindReturnAssignableTo(member.type, target_t, is_construct)) return true;
        }
        return false;
    }

    fn signatureKindReturnRelatedToWeakTarget(self: *Checker, sig_t: TypeId, target_t: TypeId, is_construct: bool) bool {
        if (!self.interner.isSignature(sig_t)) return false;
        const payload_idx = self.interner.pool.payloadOf(sig_t);
        if (payload_idx >= self.interner.pool.signature_payloads.items.len) return false;
        if (self.interner.pool.signature_payloads.items[payload_idx].is_construct != is_construct) return false;
        const ret_t = self.interner.signatureReturn(sig_t) orelse return false;
        return self.engine.isAssignableTo(ret_t, target_t) catch false;
    }

    fn typeHasSignatureKindReturnRelatedToWeakTarget(
        self: *Checker,
        source_t: TypeId,
        target_t: TypeId,
        is_construct: bool,
    ) bool {
        if (source_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(source_t);
        if (flags.is_signature) return self.signatureKindReturnRelatedToWeakTarget(source_t, target_t, is_construct);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(source_t)) |member| {
                if (self.typeHasSignatureKindReturnRelatedToWeakTarget(member, target_t, is_construct)) return true;
            }
            return false;
        }
        if (!flags.is_object_type) return false;
        const member_name = self.string_interner.intern(if (is_construct) "__construct" else "__call") catch return false;
        for (self.interner.objectMembers(source_t)) |member| {
            if (member.name != member_name) continue;
            if (self.signatureKindReturnRelatedToWeakTarget(member.type, target_t, is_construct)) return true;
        }
        return false;
    }

    fn didYouMeanCallOrConstructRelatedInfo(
        self: *Checker,
        source_node: NodeId,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError!?RelatedInfo {
        if (source_node == hir_mod.none_node_id) return null;
        if (self.typeHasSignatureKindReturnAssignableTo(source_t, target_t, true)) {
            return .{
                .node = source_node,
                .code = TsCodes.did_you_mean_new_expression,
                .message = "Did you mean to use 'new' with this expression?",
            };
        }
        if (self.typeHasSignatureKindReturnAssignableTo(source_t, target_t, false)) {
            return .{
                .node = source_node,
                .code = TsCodes.did_you_mean_call_expression,
                .message = "Did you mean to call this expression?",
            };
        }
        return null;
    }

    fn attachDidYouMeanCallOrConstructRelated(
        self: *Checker,
        source_node: NodeId,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError!void {
        if (self.diagnostics.items.len == 0) return;
        const last = &self.diagnostics.items[self.diagnostics.items.len - 1];
        if (last.code != TsCodes.type_not_assignable) return;
        const related_info = (try self.didYouMeanCallOrConstructRelatedInfo(source_node, source_t, target_t)) orelse return;
        const related = try self.diag_arena.allocator().dupe(RelatedInfo, &.{related_info});
        last.related = related;
    }

    fn attachExpectedTypeFromPropertyRelated(
        self: *Checker,
        target_t: TypeId,
        member: types.ObjectMember,
    ) CheckError!void {
        if (member.decl_node == hir_mod.none_node_id) return;
        if (self.diagnostics.items.len == 0) return;
        const last = &self.diagnostics.items[self.diagnostics.items.len - 1];
        if (last.code != TsCodes.type_not_assignable) return;
        const prop_name = self.string_interner.get(member.name);
        const target_name = (try self.allocSimpleTypeName(target_t)) orelse
            (try self.allocObjectTypeShape(target_t)) orelse
            "object";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "The expected type comes from property '{s}' which is declared here on type '{s}'",
            .{ prop_name, target_name },
        );
        const existing_len = last.related.len;
        const related = try self.diag_arena.allocator().alloc(RelatedInfo, existing_len + 1);
        if (existing_len > 0) @memcpy(related[0..existing_len], last.related);
        related[existing_len] = .{
            .node = member.decl_node,
            .code = TsCodes.expected_type_from_property,
            .message = msg,
        };
        last.related = related;
    }

    fn attachExpectedTypeFromIndexSignatureRelated(
        self: *Checker,
        target_t: TypeId,
        kind: []const u8,
    ) CheckError!void {
        const decl_node = self.indexSignatureDeclNode(target_t, kind);
        if (decl_node == hir_mod.none_node_id) return;
        if (self.diagnostics.items.len == 0) return;
        const last = &self.diagnostics.items[self.diagnostics.items.len - 1];
        if (last.code != TsCodes.type_not_assignable) return;
        const existing_len = last.related.len;
        const related = try self.diag_arena.allocator().alloc(RelatedInfo, existing_len + 1);
        if (existing_len > 0) @memcpy(related[0..existing_len], last.related);
        related[existing_len] = .{
            .node = decl_node,
            .code = TsCodes.expected_type_from_index_signature,
            .message = "The expected type comes from this index signature.",
        };
        last.related = related;
    }

    fn attachExpectedTypeFromSignatureReturnRelated(
        self: *Checker,
        target_sig: TypeId,
    ) CheckError!void {
        const decl_node = self.signatureDeclNode(target_sig);
        if (decl_node == hir_mod.none_node_id) return;
        if (self.diagnostics.items.len == 0) return;
        const last = &self.diagnostics.items[self.diagnostics.items.len - 1];
        if (last.code != TsCodes.type_not_assignable) return;
        const existing_len = last.related.len;
        const related = try self.diag_arena.allocator().alloc(RelatedInfo, existing_len + 1);
        if (existing_len > 0) @memcpy(related[0..existing_len], last.related);
        related[existing_len] = .{
            .node = decl_node,
            .code = TsCodes.expected_type_from_signature_return,
            .message = "The expected type comes from the return type of this signature.",
        };
        last.related = related;
    }

    fn attachMissingAwaitRelated(
        self: *Checker,
        source_node: NodeId,
        source_t: TypeId,
        target_t: TypeId,
    ) CheckError!void {
        if (source_node == hir_mod.none_node_id) return;
        if (self.diagnostics.items.len == 0) return;
        const last = &self.diagnostics.items[self.diagnostics.items.len - 1];
        if (last.code != TsCodes.type_not_assignable) return;
        const awaited_t = self.unwrapPromise(source_t);
        if (awaited_t == source_t) return;
        if (self.unwrapPromise(target_t) != target_t) return;
        if (!try self.expressionNodeAssignableToTarget(source_node, awaited_t, target_t)) return;
        const existing_len = last.related.len;
        const related = try self.diag_arena.allocator().alloc(RelatedInfo, existing_len + 1);
        if (existing_len > 0) @memcpy(related[0..existing_len], last.related);
        related[existing_len] = .{
            .node = source_node,
            .pos = self.hir.spanOf(source_node).start,
            .code = TsCodes.did_you_forget_await,
            .message = "Did you forget to use 'await'?",
        };
        last.related = related;
    }

    /// Emit a not-callable diagnostic carrying tsc's TS2757 ("Type '{0}'
    /// has no call signatures.") chain detail, the shape
    /// `invocationErrorDetails` produces for a non-union callee with no
    /// call signatures.
    fn reportNotCallableWithNoCallSignaturesMessage(
        self: *Checker,
        callee: NodeId,
        callee_t: TypeId,
        code: u32,
        message: []const u8,
    ) CheckError!void {
        const chain = try self.notCallableNoCallSignaturesChain(callee_t);
        try self.diagnostics.append(self.gpa, .{
            .node = callee,
            .pos = null,
            .code = code,
            .message = try self.diag_arena.allocator().dupe(u8, message),
            .chain = chain,
        });
        if (code == TsCodes.not_callable) {
            try self.attachNamespaceImportInvocationRelated(callee, false);
        }
    }

    fn notCallableNoCallSignaturesChain(self: *Checker, callee_t: TypeId) CheckError![]const DiagnosticChainEntry {
        if (try self.notCallableNoConstituentUnionChain(callee_t)) |chain| return chain;
        if (try self.notCallableMixedUnionChain(callee_t)) |chain| return chain;
        if (try self.notCallableIncompatibleUnionSignaturesChain(callee_t)) |chain| return chain;
        const rendered: ?[]const u8 = (try self.allocSimpleTypeName(callee_t)) orelse
            (if (self.interner.isSignature(callee_t)) try self.allocCallableSignatureName(callee_t) else null);
        const detail_msg = if (rendered) |name|
            try std.fmt.allocPrint(self.diag_arena.allocator(), "Type '{s}' has no call signatures.", .{name})
        else
            try self.diag_arena.allocator().dupe(u8, "Type has no call signatures.");
        return try self.diag_arena.allocator().dupe(DiagnosticChainEntry, &.{.{
            .code = TsCodes.type_has_no_call_signatures,
            .message = detail_msg,
        }});
    }

    fn notCallableNoConstituentUnionChain(self: *Checker, callee_t: TypeId) CheckError!?[]const DiagnosticChainEntry {
        if (callee_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(callee_t);
        if (!flags.is_union) return null;
        const members = self.interner.unionMembers(callee_t);
        if (members.len == 0) return null;
        for (members) |member| {
            if (self.typeHasNonConstructCallSignature(member)) return null;
        }
        const union_name = (try self.allocSimpleTypeName(callee_t)) orelse "union type";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "No constituent of type '{s}' is callable.",
            .{union_name},
        );
        return try self.diag_arena.allocator().dupe(DiagnosticChainEntry, &.{.{
            .code = TsCodes.no_constituent_callable,
            .message = msg,
        }});
    }

    fn notCallableMixedUnionChain(self: *Checker, callee_t: TypeId) CheckError!?[]const DiagnosticChainEntry {
        if (callee_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(callee_t);
        if (!flags.is_union) return null;
        const members = self.interner.unionMembers(callee_t);
        var saw_callable = false;
        var first_non_callable: TypeId = types.Primitive.none;
        for (members) |member| {
            if (self.typeHasNonConstructCallSignature(member)) {
                saw_callable = true;
            } else if (first_non_callable == types.Primitive.none) {
                first_non_callable = member;
            }
        }
        if (!saw_callable or first_non_callable == types.Primitive.none) return null;
        const union_name = (try self.allocSimpleTypeName(callee_t)) orelse "union type";
        const member_name = (try self.allocSimpleTypeName(first_non_callable)) orelse "type";
        const child_msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' has no call signatures.",
            .{member_name},
        );
        const parent_msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Not all constituents of type '{s}' are callable.",
            .{union_name},
        );
        const arena = self.diag_arena.allocator();
        const chain = try arena.alloc(DiagnosticChainEntry, 1);
        const child = try arena.alloc(DiagnosticChainEntry, 1);
        child[0] = .{
            .code = TsCodes.type_has_no_call_signatures,
            .message = child_msg,
        };
        chain[0] = .{
            .code = TsCodes.not_all_constituents_callable,
            .message = parent_msg,
            .children = child,
        };
        return chain;
    }

    fn notCallableIncompatibleUnionSignaturesChain(self: *Checker, callee_t: TypeId) CheckError!?[]const DiagnosticChainEntry {
        if (!try self.unionHasIncompatibleCallSignatures(callee_t)) return null;
        const union_name = (try self.simpleDiagnosticTypeName(callee_t)) orelse
            (try self.allocSimpleTypeName(callee_t)) orelse
            "union type";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Each member of the union type '{s}' has signatures, but none of those signatures are compatible with each other.",
            .{union_name},
        );
        return try self.diag_arena.allocator().dupe(DiagnosticChainEntry, &.{.{
            .code = TsCodes.union_signatures_not_compatible,
            .message = msg,
        }});
    }

    /// Emit TS2349 ("This expression is not callable.") carrying tsc's
    /// TS2757 ("Type '{0}' has no call signatures.") chain detail, the
    /// shape `invocationErrorDetails` produces for a non-union callee
    /// with no call signatures. The detail is a message-chain child, so
    /// it's additive: the legacy header-only baselines (and the
    /// conformance harness, which compares only the primary header) are
    /// unaffected, while pretty output and the LSP gain the detail line.
    fn reportNotCallableWithNoCallSignatures(self: *Checker, callee: NodeId, callee_t: TypeId) CheckError!void {
        try self.reportNotCallableWithNoCallSignaturesMessage(
            callee,
            callee_t,
            TsCodes.not_callable,
            "This expression is not callable.",
        );
    }

    fn reportNotCallableWithPossibleMissingSemicolon(self: *Checker, call_node: NodeId, callee: NodeId, callee_t: TypeId) CheckError!void {
        try self.reportNotCallableWithNoCallSignatures(callee, callee_t);
        if (!self.callExprLooksLikeMissingSemicolon(call_node)) return;
        if (self.diagnostics.items.len == 0) return;
        const last = &self.diagnostics.items[self.diagnostics.items.len - 1];
        if (last.code != TsCodes.not_callable or last.node != callee) return;
        const existing_len = last.related.len;
        const related = try self.diag_arena.allocator().alloc(RelatedInfo, existing_len + 1);
        if (existing_len > 0) @memcpy(related[0..existing_len], last.related);
        related[existing_len] = .{
            .node = callee,
            .pos = self.hir.spanOf(callee).start,
            .code = TsCodes.missing_semicolon_related,
            .message = "Are you missing a semicolon?",
        };
        last.related = related;
    }

    fn callExprLooksLikeMissingSemicolon(self: *Checker, call_node: NodeId) bool {
        const src = self.source orelse return false;
        if (self.hir.kindOf(call_node) != .call_expr) return false;
        const call = hir_mod.callOf(self.hir, call_node);
        if (hir_mod.callArgs(self.hir, call_node).len != 1) return false;
        if (call.callee == hir_mod.none_node_id) return false;
        const callee_end = self.hir.spanOf(call.callee).end;
        const call_end = self.hir.spanOf(call_node).end;
        if (callee_end >= call_end or call_end > src.len) return false;
        var saw_newline = false;
        var i: usize = callee_end;
        while (i < call_end) : (i += 1) {
            switch (src[i]) {
                ' ', '\t' => {},
                '\n', '\r' => saw_newline = true,
                '(' => return saw_newline,
                else => return false,
            }
        }
        return false;
    }

    fn reportGetterNotCallable(self: *Checker, callee: NodeId, callee_t: TypeId) CheckError!void {
        const chain = try self.notCallableNoCallSignaturesChain(callee_t);
        try self.diagnostics.append(self.gpa, .{
            .node = callee,
            .pos = self.memberAccessNamePos(callee),
            .code = TsCodes.get_accessor_not_callable,
            .message = try self.diag_arena.allocator().dupe(u8, "This expression is not callable because it is a 'get' accessor. Did you mean to use it without '()'?"),
            .chain = chain,
        });
    }

    fn classGetterDeclaringClass(
        self: *Checker,
        class_name: hir_mod.StringId,
        member_name: hir_mod.StringId,
        is_static: bool,
    ) ?hir_mod.StringId {
        var probe: ?hir_mod.StringId = class_name;
        var depth: u8 = 0;
        while (probe) |current| : (depth += 1) {
            if (depth >= 32) return null;
            const getters = if (is_static)
                self.class_static_getter_members.getPtr(current)
            else
                self.class_getter_members.getPtr(current);
            if (getters) |set| {
                if (set.contains(member_name)) return current;
            }
            const own_members = if (is_static)
                self.class_static_member_names.getPtr(current)
            else
                self.class_instance_member_names.getPtr(current);
            if (own_members) |members| {
                if (members.contains(member_name)) return null;
            }
            probe = self.class_parent.get(current);
        }
        return null;
    }

    fn objectTypeMemberIsGetter(
        self: *Checker,
        object_t: TypeId,
        member_name: hir_mod.StringId,
        is_static: bool,
    ) bool {
        if (object_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(object_t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(object_t)) |member_t| {
                if (self.objectTypeMemberIsGetter(member_t, member_name, is_static)) return true;
            }
            return false;
        }
        if (!flags.is_object_type) return false;
        for (self.interner.objectMembers(object_t)) |member| {
            if (member.name != member_name or member.decl_node == hir_mod.none_node_id) continue;
            const kind = self.hir.kindOf(member.decl_node);
            if (kind != .fn_decl and kind != .fn_expr and kind != .arrow_fn) return false;
            const declaration = hir_mod.fnDeclOf(self.hir, member.decl_node);
            return declaration.flags.is_getter and declaration.flags.is_static == is_static;
        }
        return false;
    }

    fn concretePairedGetterType(
        self: *Checker,
        receiver_t: TypeId,
        member_name: hir_mod.StringId,
    ) CheckError!?TypeId {
        if (receiver_t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(receiver_t).is_object_type) return null;
        var getter_decl = hir_mod.none_node_id;
        for (self.interner.objectMembers(receiver_t)) |member| {
            if (member.name != member_name or member.decl_node == hir_mod.none_node_id) continue;
            const kind = self.hir.kindOf(member.decl_node);
            if (kind != .fn_decl and kind != .fn_expr and kind != .arrow_fn) return null;
            if (!hir_mod.fnDeclOf(self.hir, member.decl_node).flags.is_getter) return null;
            getter_decl = member.decl_node;
            break;
        }
        if (getter_decl == hir_mod.none_node_id) return null;
        const class_node = self.memberDeclaringClassNode(getter_decl);
        if (class_node == hir_mod.none_node_id) return null;
        const class_payload = hir_mod.classOf(self.hir, class_node);
        if (class_payload.name == hir_mod.none_node_id or self.hir.kindOf(class_payload.name) != .identifier) return null;
        const declaring_class = hir_mod.identifierOf(self.hir, class_payload.name).name;
        const setter_t = self.class_accessor_setter_types.get(.{
            .class_name = declaring_class,
            .member_name = member_name,
            .is_static = false,
        }) orelse return null;
        const args = self.alias_type_args.get(receiver_t) orelse return setter_t;
        const receiver_class = self.classNameForInstanceType(receiver_t) orelse
            (try self.genericInstanceBaseName(receiver_t)) orelse return setter_t;
        const receiver_info = self.generic_aliases.get(receiver_class) orelse return setter_t;
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        for (receiver_info.params, 0..) |param_t, i| {
            if (i >= args.len) break;
            try subs.put(self.gpa, param_t, args[i]);
        }
        try self.extendSubstitutionsByMatchingTypeParamNames(setter_t, receiver_info.params, &subs);
        return self.substituteType(setter_t, &subs) catch setter_t;
    }

    fn callExprCalleeIsZeroArgGetterAccess(self: *Checker, call_node: NodeId, callee: NodeId) bool {
        const call = hir_mod.callOf(self.hir, call_node);
        if (self.hir.childSlice(call.args_start, call.args_len).len != 0) return false;
        if (self.hir.kindOf(callee) != .member_access) return false;
        const member = hir_mod.memberOf(self.hir, callee);
        var obj_t = self.hir.typeOf(member.object);
        if (obj_t == types.Primitive.none) return false;
        obj_t = self.typeParameterConstraint(obj_t) orelse obj_t;
        if (self.objectTypeMemberIsGetter(obj_t, member.name, false)) return true;
        if (self.objectTypeMemberIsGetter(obj_t, member.name, true)) return true;
        const instance_class_name = self.classNameForInstanceType(obj_t) orelse
            (self.genericInstanceBaseName(obj_t) catch null);
        if (instance_class_name) |class_name| {
            if (self.classGetterDeclaringClass(class_name, member.name, false) != null) return true;
        }
        if (self.class_name_by_static.get(obj_t)) |class_name| {
            if (self.classGetterDeclaringClass(class_name, member.name, true) != null) return true;
        }
        return false;
    }

    fn callExprCalleeIsZeroArgGetterSetterAccess(self: *Checker, call_node: NodeId, callee: NodeId) bool {
        const call = hir_mod.callOf(self.hir, call_node);
        if (self.hir.childSlice(call.args_start, call.args_len).len != 0) return false;
        if (self.hir.kindOf(callee) != .member_access) return false;
        const member = hir_mod.memberOf(self.hir, callee);
        var obj_t = self.hir.typeOf(member.object);
        if (obj_t == types.Primitive.none) return false;
        obj_t = self.typeParameterConstraint(obj_t) orelse obj_t;
        const instance_class_name = self.classNameForInstanceType(obj_t) orelse
            (self.genericInstanceBaseName(obj_t) catch null);
        if (instance_class_name) |class_name| {
            const declaring_class = self.classGetterDeclaringClass(class_name, member.name, false) orelse return false;
            return self.class_accessor_setter_types.contains(.{
                .class_name = declaring_class,
                .member_name = member.name,
                .is_static = false,
            });
        }
        if (self.class_name_by_static.get(obj_t)) |class_name| {
            const declaring_class = self.classGetterDeclaringClass(class_name, member.name, true) orelse return false;
            return self.class_accessor_setter_types.contains(.{
                .class_name = declaring_class,
                .member_name = member.name,
                .is_static = true,
            });
        }
        return false;
    }

    /// Construct-side sibling of `reportNotCallableWithNoCallSignatures`:
    /// TS2351 ("This expression is not constructable.") header carrying
    /// tsc's TS2761 ("Type '{0}' has no construct signatures.") chain
    /// detail. Additive (chain child only).
    fn reportNotConstructableWithNoConstructSignatures(self: *Checker, callee: NodeId, callee_t: TypeId) CheckError!void {
        const chain = try self.notConstructableNoConstructSignaturesChain(callee_t);
        try self.diagnostics.append(self.gpa, .{
            .node = callee,
            .pos = null,
            .code = 2351,
            .message = try self.diag_arena.allocator().dupe(u8, "This expression is not constructable."),
            .chain = chain,
        });
        try self.attachNamespaceImportInvocationRelated(callee, true);
    }

    fn attachNamespaceImportInvocationRelated(
        self: *Checker,
        callee: NodeId,
        is_construct: bool,
    ) CheckError!void {
        if (self.diagnostics.items.len == 0) return;
        const last = &self.diagnostics.items[self.diagnostics.items.len - 1];
        if (last.node != callee) return;
        if (is_construct) {
            if (last.code != 2351) return;
        } else if (last.code != TsCodes.not_callable) return;
        const related_info = (try self.namespaceImportInvocationRelatedInfo(callee, is_construct)) orelse return;
        const existing_len = last.related.len;
        const related = try self.diag_arena.allocator().alloc(RelatedInfo, existing_len + 1);
        if (existing_len > 0) @memcpy(related[0..existing_len], last.related);
        related[existing_len] = related_info;
        last.related = related;
    }

    fn namespaceImportInvocationRelatedInfo(
        self: *Checker,
        callee: NodeId,
        is_construct: bool,
    ) CheckError!?RelatedInfo {
        if (self.hir.kindOf(callee) != .identifier) return null;
        const name = hir_mod.identifierOf(self.hir, callee).name;
        const import_node = self.namespaceImportDeclForLocal(name, callee) orelse return null;
        const imp = hir_mod.importOf(self.hir, import_node);
        const target_t = (try self.virtualExportAssignmentExpressionType(import_node, imp.module)) orelse
            (try self.virtualExportAssignmentTargetStaticType(import_node, imp.module)) orelse
            return null;
        const target_has_signature = if (is_construct)
            self.typeHasConstructSignature(target_t)
        else
            self.typeHasNonConstructCallSignature(target_t);
        if (!target_has_signature) return null;
        return .{
            .node = import_node,
            .pos = self.hir.spanOf(import_node).start,
            .code = TsCodes.namespace_import_call_or_construct_related,
            .message = "Type originates at this import. A namespace-style import cannot be called or constructed, and will cause a failure at runtime. Consider using a default import or import require here instead.",
        };
    }

    fn namespaceImportDeclForLocal(self: *Checker, local_name: hir_mod.StringId, anchor: NodeId) ?NodeId {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const has_sections = self.sourceHasVirtualFilenameSections();
        const anchor_section = if (has_sections) self.virtualSectionStartForNode(anchor) else 0;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.hir.kindOf(stmt) != .import_decl) continue;
            if (has_sections and self.virtualSectionStartForNode(stmt) != anchor_section) continue;
            const imp = hir_mod.importOf(self.hir, stmt);
            if (imp.is_type_only) continue;
            if (imp.namespace_binding == hir_mod.none_node_id or self.hir.kindOf(imp.namespace_binding) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, imp.namespace_binding).name == local_name) return stmt;
        }
        return null;
    }

    fn notConstructableNoConstructSignaturesChain(self: *Checker, callee_t: TypeId) CheckError![]const DiagnosticChainEntry {
        if (try self.notConstructableNoConstituentUnionChain(callee_t)) |chain| return chain;
        if (try self.notConstructableMixedUnionChain(callee_t)) |chain| return chain;
        if (try self.notConstructableIncompatibleUnionSignaturesChain(callee_t)) |chain| return chain;
        const rendered: ?[]const u8 = (try self.allocSimpleTypeName(callee_t)) orelse
            (if (self.interner.isSignature(callee_t)) try self.allocCallableSignatureName(callee_t) else null);
        const detail_msg = if (rendered) |name|
            try std.fmt.allocPrint(self.diag_arena.allocator(), "Type '{s}' has no construct signatures.", .{name})
        else
            try self.diag_arena.allocator().dupe(u8, "Type has no construct signatures.");
        return try self.diag_arena.allocator().dupe(DiagnosticChainEntry, &.{.{
            .code = TsCodes.type_has_no_construct_signatures,
            .message = detail_msg,
        }});
    }

    fn notConstructableNoConstituentUnionChain(self: *Checker, callee_t: TypeId) CheckError!?[]const DiagnosticChainEntry {
        if (callee_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(callee_t);
        if (!flags.is_union) return null;
        const members = self.interner.unionMembers(callee_t);
        if (members.len == 0) return null;
        for (members) |member| {
            if (self.typeHasConstructSignature(member)) return null;
        }
        const union_name = (try self.allocSimpleTypeName(callee_t)) orelse "union type";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "No constituent of type '{s}' is constructable.",
            .{union_name},
        );
        return try self.diag_arena.allocator().dupe(DiagnosticChainEntry, &.{.{
            .code = TsCodes.no_constituent_constructable,
            .message = msg,
        }});
    }

    fn notConstructableMixedUnionChain(self: *Checker, callee_t: TypeId) CheckError!?[]const DiagnosticChainEntry {
        if (callee_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(callee_t);
        if (!flags.is_union) return null;
        const members = self.interner.unionMembers(callee_t);
        var saw_constructable = false;
        var first_non_constructable: TypeId = types.Primitive.none;
        for (members) |member| {
            if (self.typeHasConstructSignature(member)) {
                saw_constructable = true;
            } else if (first_non_constructable == types.Primitive.none) {
                first_non_constructable = member;
            }
        }
        if (!saw_constructable or first_non_constructable == types.Primitive.none) return null;
        const union_name = (try self.allocSimpleTypeName(callee_t)) orelse "union type";
        const member_name = (try self.allocSimpleTypeName(first_non_constructable)) orelse "type";
        const child_msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' has no construct signatures.",
            .{member_name},
        );
        const parent_msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Not all constituents of type '{s}' are constructable.",
            .{union_name},
        );
        const arena = self.diag_arena.allocator();
        const chain = try arena.alloc(DiagnosticChainEntry, 1);
        const child = try arena.alloc(DiagnosticChainEntry, 1);
        child[0] = .{
            .code = TsCodes.type_has_no_construct_signatures,
            .message = child_msg,
        };
        chain[0] = .{
            .code = TsCodes.not_all_constituents_constructable,
            .message = parent_msg,
            .children = child,
        };
        return chain;
    }

    fn notConstructableIncompatibleUnionSignaturesChain(self: *Checker, callee_t: TypeId) CheckError!?[]const DiagnosticChainEntry {
        if (!try self.unionHasIncompatibleConstructSignatures(callee_t)) return null;
        const union_name = (try self.simpleDiagnosticTypeName(callee_t)) orelse
            (try self.allocSimpleTypeName(callee_t)) orelse
            "union type";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Each member of the union type '{s}' has construct signatures, but none of those signatures are compatible with each other.",
            .{union_name},
        );
        return try self.diag_arena.allocator().dupe(DiagnosticChainEntry, &.{.{
            .code = TsCodes.union_construct_signatures_not_compatible,
            .message = msg,
        }});
    }

    /// Recursively check whether `t` is a union (or intersection)
    /// whose every constituent carries a call signature. Used to
    /// suppress TS2349 on `(typeof f1 | typeof f2)("")` style call
    /// sites ÃÂ¢ÃÂÃÂ tsc treats the union as callable when every branch
    /// is. Returns `false` for bare callables; the caller already
    /// has dedicated paths for those.
    ///
    /// For intersections, additionally guards against the case where
    /// a shared property's constituent types are mutually disjoint
    /// and collapse to `never` (e.g. `{ (x): number, a: "" } & { a:
    /// number }`). tsc reduces such an intersection to `never` and
    /// emits TS2349 with "Type 'never' has no call signatures" ÃÂ¢ÃÂÃÂ
    /// see `neverIntersectionNotCallable.errors.txt`.
    fn typeUnionAllCallable(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            const members = self.interner.unionMembers(t);
            if (members.len == 0) return false;
            for (members) |m| {
                if (self.typeIsAny(m)) continue;
                if (!self.objectHasCallOrConstructSignature(m) and !self.typeUnionAllCallable(m)) return false;
            }
            return true;
        }
        if (flags.is_intersection) {
            if (self.intersectionHasDisjointSharedProperty(t)) return false;
            for (self.interner.intersectionMembers(t)) |m| {
                if (self.objectHasCallOrConstructSignature(m)) return true;
                if (self.typeUnionAllCallable(m)) return true;
            }
            return false;
        }
        return false;
    }

    /// Returns `true` when intersection `t` has a property name that
    /// appears in two or more object constituents with types that
    /// are mutually non-assignable in both directions (i.e. the
    /// property's intersected type collapses to `never`). Mirrors
    /// tsc's reduction of `{ a: "" } & { a: number }` whose `a`
    /// becomes `never`, which in turn makes the intersection itself
    /// uncallable.
    fn intersectionHasDisjointSharedProperty(self: *Checker, t: TypeId) bool {
        const members = self.interner.intersectionMembers(t);
        if (members.len < 2) return false;
        for (members, 0..) |a, ai| {
            if (a >= self.interner.pool.typeCount()) continue;
            if (!self.interner.pool.flagsOf(a).is_object_type) continue;
            // Snapshot a's members before the inner `heritageAssignable()`
            // calls can grow object_member_pool and invalidate the borrowed
            // slice (HIGH-RISK dangling-slice fix per
            // DANGLING_SLICE_AUDIT_2026-05-19.md).
            const a_members = self.gpa.dupe(types.ObjectMember, self.interner.objectMembers(a)) catch return false;
            defer self.gpa.free(a_members);
            for (a_members) |a_member| {
                for (members[ai + 1 ..]) |b| {
                    if (b >= self.interner.pool.typeCount()) continue;
                    if (!self.interner.pool.flagsOf(b).is_object_type) continue;
                    const b_t = self.interner.objectMember(b, a_member.name) orelse continue;
                    if (a_member.type == b_t) continue;
                    if (a_member.type == types.Primitive.any or a_member.type == types.Primitive.unknown) continue;
                    if (b_t == types.Primitive.any or b_t == types.Primitive.unknown) continue;
                    const ab = self.heritageAssignable(a_member.type, b_t) catch true;
                    const ba = self.heritageAssignable(b_t, a_member.type) catch true;
                    if (!ab and !ba) return true;
                }
            }
        }
        return false;
    }

    /// Classification of why an intersection type reduced to `never`.
    /// Mirrors typescript-go's `getReducedType` (`isNeverReducedProperty`),
    /// which checks two distinct cases via `isDiscriminantWithNeverType`
    /// (→ TS18031) and `isConflictingPrivateProperty` (→ TS18032).
    const NeverIntersectionReduction = struct {
        /// The property name whose presence triggered the reduction.
        prop_name: hir_mod.StringId,
        /// `true` for the conflicting-private case (TS18032); `false`
        /// for the conflicting-discriminant case (TS18031).
        is_private_conflict: bool,
    };

    /// Detect whether intersection `t` reduces to `never` because one of
    /// its (synthetic) properties has mutually exclusive constituent
    /// types or a private clash. Returns the offending property and which
    /// of TS18031 / TS18032 applies, or `null` when the intersection does
    /// not reduce.
    ///
    /// Faithful port of typescript-go `checker.go`:
    ///   * `isDiscriminantWithNeverType` — a non-optional synthetic
    ///     property whose constituent types are NON-UNIFORM, at least one
    ///     is a literal, none is `never`, and whose intersection collapses
    ///     to `never` (→ TS18031, the conflicting-types message).
    ///   * `isConflictingPrivateProperty` — a synthetic property that
    ///     exists in multiple constituents and is private in some
    ///     (→ TS18032).
    ///
    /// tsc checks the discriminant case first (it produces the more
    /// specific TS18031 wording), so we do too. Conservative by design:
    /// only fires when constituents are concrete object/class shapes, so
    /// generic / unresolved members never spuriously reduce.
    fn intersectionNeverReduction(self: *Checker, t: TypeId) ?NeverIntersectionReduction {
        if (t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(t).is_intersection) return null;
        // Defensive: the interner is sharded and recycled slots can leak
        // a transient `is_intersection` flag onto a non-intersection
        // header whose payload index points past `intersection_payloads`
        // (same hazard `allocSimpleTypeName` guards against). Bail out
        // before `intersectionMembers` indexes the payload table OOB.
        if (self.interner.pool.payloadOf(t) >= self.interner.pool.intersection_payloads.items.len) return null;
        // Snapshot the member slice up front: the `heritageAssignable` /
        // `objectMemberInfo` probes below can grow the interner's
        // member/object pools and reallocate, dangling a borrowed
        // `intersectionMembers` slice (DANGLING_SLICE_AUDIT_2026-05-19.md).
        const members = self.gpa.dupe(TypeId, self.interner.intersectionMembers(t)) catch return null;
        defer self.gpa.free(members);
        if (members.len < 2) return null;

        // (1) Conflicting-discriminant (TS18031). Walk each object
        // constituent's properties; for a property present in 2+ object
        // constituents, gather its constituent types and apply tsc's
        // never-discriminant test.
        for (members, 0..) |a, ai| {
            if (a >= self.interner.pool.typeCount()) continue;
            if (!self.interner.pool.flagsOf(a).is_object_type) continue;
            // Snapshot a's members: the assignability probes below can
            // grow object_member_pool and dangle the borrowed slice
            // (DANGLING_SLICE_AUDIT_2026-05-19.md).
            const a_members = self.gpa.dupe(types.ObjectMember, self.interner.objectMembers(a)) catch return null;
            defer self.gpa.free(a_members);
            for (a_members) |a_member| {
                // Only earlier-than-or-equal `ai` walks this name once
                // (skip names already covered by an earlier constituent).
                var already_seen = false;
                for (members[0..ai]) |prev| {
                    if (prev >= self.interner.pool.typeCount()) continue;
                    if (!self.interner.pool.flagsOf(prev).is_object_type) continue;
                    if (self.interner.objectMemberInfo(prev, a_member.name) != null) {
                        already_seen = true;
                        break;
                    }
                }
                if (already_seen) continue;
                if (self.propertyReducesIntersectionToNever(members, a_member.name)) {
                    return .{ .prop_name = a_member.name, .is_private_conflict = false };
                }
            }
        }

        // (2) Conflicting-private (TS18032). A property that exists in
        // multiple class-instance constituents and is declared `private`
        // in at least one of them. tsc treats such synthetic properties
        // as reducing the intersection to never.
        if (self.intersectionConflictingPrivateProperty(members)) |name| {
            return .{ .prop_name = name, .is_private_conflict = true };
        }
        return null;
    }

    /// tsc `isDiscriminantWithNeverType` for property `name` across
    /// intersection constituents `members`. The property reduces the
    /// intersection to `never` when it is present (non-optional) in 2+
    /// object constituents, its constituent types are NON-UNIFORM, at
    /// least one is a literal, none is already `never`, and the
    /// intersection of those constituent types is itself `never`
    /// (i.e. the types are pairwise mutually non-assignable).
    fn propertyReducesIntersectionToNever(
        self: *Checker,
        members: []const TypeId,
        name: hir_mod.StringId,
    ) bool {
        var constituent_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer constituent_types.deinit(self.gpa);
        var saw_discriminant = false;
        for (members) |m| {
            if (m >= self.interner.pool.typeCount()) continue;
            if (!self.interner.pool.flagsOf(m).is_object_type) continue;
            const info = self.interner.objectMemberInfo(m, name) orelse continue;
            // An optional constituent property suppresses the reduction
            // (tsc requires `SymbolFlagsOptional == 0`).
            if (info.is_optional) return false;
            const pt = info.type;
            // A constituent property already typed `never` disqualifies
            // (tsc's `CheckFlagsHasNeverType` exclusion).
            if (pt == types.Primitive.never) return false;
            if (pt == types.Primitive.any or pt == types.Primitive.unknown) return false;
            const property_flags = self.interner.pool.flagsOf(pt);
            if (property_flags.is_literal or property_flags.is_boolean) saw_discriminant = true;
            constituent_types.append(self.gpa, pt) catch return false;
        }
        if (constituent_types.items.len < 2) return false;
        if (!saw_discriminant) return false;
        // Uniform constituent types do not reduce (tsc's NonUniform).
        var uniform = true;
        for (constituent_types.items[1..]) |ct| {
            if (ct != constituent_types.items[0]) {
                uniform = false;
                break;
            }
        }
        if (uniform) return false;
        // The intersection of the constituent types must itself be
        // `never`: every distinct pair must be mutually non-assignable in
        // both directions (so neither narrows to the other and the
        // intersected type collapses). Mirrors the existing
        // `intersectionHasDisjointSharedProperty` overlap test.
        for (constituent_types.items, 0..) |x, xi| {
            for (constituent_types.items[xi + 1 ..]) |y| {
                if (x == y) continue;
                const xy = self.heritageAssignable(x, y) catch true;
                const yx = self.heritageAssignable(y, x) catch true;
                if (xy or yx) return false;
            }
        }
        return true;
    }

    /// tsc `isConflictingPrivateProperty`: a synthetic intersection
    /// property that exists in multiple class-instance constituents and
    /// is private in at least one. Returns the offending property name.
    fn intersectionConflictingPrivateProperty(self: *Checker, members: []const TypeId) ?hir_mod.StringId {
        for (members, 0..) |a, ai| {
            const a_class = self.class_name_by_instance.get(a) orelse continue;
            const a_private = self.class_private_members.getPtr(a_class) orelse continue;
            var it = a_private.keyIterator();
            while (it.next()) |name_ptr| {
                const name = name_ptr.*;
                // The same property must also exist in another class
                // constituent (whether private or public there).
                for (members, 0..) |b, bi| {
                    if (bi == ai) continue;
                    const b_class = self.class_name_by_instance.get(b) orelse continue;
                    if (b_class == a_class) continue;
                    const has_b_member = self.interner.objectMemberInfo(b, name) != null;
                    const has_b_private = if (self.class_private_members.getPtr(b_class)) |bp|
                        bp.contains(name)
                    else
                        false;
                    if (has_b_member or has_b_private) return name;
                }
            }
        }
        return null;
    }

    /// Build the single TS18031 / TS18032 elaboration chain entry that
    /// tsc nests under the TS2339 ("Property 'x' does not exist on type
    /// 'never'") header or the TS2322 assignment header when an
    /// intersection target reduced to `never`. The intersection name is
    /// rendered WITHOUT type reduction (tsc's `TypeFormatFlagsNoTypeReduction`)
    /// so it reads `A & B`, not `never`. Returns an empty slice when the
    /// intersection does not reduce or the name cannot be rendered.
    fn buildNeverIntersectionChain(
        self: *Checker,
        intersection_t: TypeId,
    ) CheckError![]const DiagnosticChainEntry {
        const empty: []const DiagnosticChainEntry = &.{};
        const reduction = self.intersectionNeverReduction(intersection_t) orelse return empty;
        const arena = self.diag_arena.allocator();
        const int_name = (try self.allocSimpleTypeName(intersection_t)) orelse return empty;
        const prop_str = self.string_interner.get(reduction.prop_name);
        const msg = if (reduction.is_private_conflict)
            try std.fmt.allocPrint(
                arena,
                "The intersection '{s}' was reduced to 'never' because property '{s}' exists in multiple constituents and is private in some.",
                .{ int_name, prop_str },
            )
        else
            try std.fmt.allocPrint(
                arena,
                "The intersection '{s}' was reduced to 'never' because property '{s}' has conflicting types in some constituents.",
                .{ int_name, prop_str },
            );
        const slice = try arena.alloc(DiagnosticChainEntry, 1);
        slice[0] = .{
            .code = if (reduction.is_private_conflict)
                TsCodes.intersection_reduced_never_private
            else
                TsCodes.intersection_reduced_never_conflicting,
            .message = msg,
        };
        return slice;
    }

    /// True when the callable shape exposes only construct signatures
    /// (e.g. `new () => string` or `{ new (): T }`) and no callable
    /// signatures. Mirrors upstream TS so TS2348 (with the
    /// "Did you mean to include 'new'?" hint) fires in place of the
    /// generic TS2349.
    /// True when the call expression `node` was parsed from a
    /// tagged-template literal (`tag\`...\``). The parser desugars
    /// these into `call(tag, [stringsArr, ...values])`, losing the
    /// distinction at HIR level ÃÂ¢ÃÂÃÂ but the source span still contains
    /// the backtick. We detect that by scanning the bytes between the
    /// callee's end and the call's end for a leading backtick after
    /// whitespace. Used to suppress the "Did you mean 'new'?" hint
    /// (TS2348) ÃÂ¢ÃÂÃÂ tagged-template calls cannot be expressed with `new`
    /// and tsc emits the bare TS2349 "not callable" instead.
    fn callExprIsTaggedTemplate(self: *Checker, node: NodeId) bool {
        const src = self.source orelse return false;
        const k = self.hir.kindOf(node);
        if (k != .call_expr) return false;
        const c = hir_mod.callOf(self.hir, node);
        if (c.callee == hir_mod.none_node_id) return false;
        const callee_end = self.hir.spanOf(c.callee).end;
        const call_end = self.hir.spanOf(node).end;
        if (callee_end >= call_end or call_end > src.len) return false;
        var i: usize = callee_end;
        while (i < call_end) : (i += 1) {
            const ch = src[i];
            if (ch == ' ' or ch == '\t' or ch == '\n' or ch == '\r') continue;
            if (ch == '<') {
                var depth: usize = 1;
                i += 1;
                while (i < call_end) : (i += 1) {
                    const inner = src[i];
                    if (inner == '<') {
                        depth += 1;
                    } else if (inner == '>') {
                        depth -= 1;
                        if (depth == 0) break;
                    }
                }
                continue;
            }
            return ch == '`';
        }
        return false;
    }

    fn callExprIsArrayTemplateTemplateRecovery(self: *Checker, node: NodeId) bool {
        if (!self.callExprIsTaggedTemplate(node)) return false;
        const c = hir_mod.callOf(self.hir, node);
        if (c.callee == hir_mod.none_node_id or self.hir.kindOf(c.callee) != .template_literal) return false;
        const parent = self.hir.parentOf(node);
        return parent != hir_mod.none_node_id and self.hir.kindOf(parent) == .array_literal;
    }

    fn callableObjectHasOnlyConstructSignatures(self: *Checker, obj_t: TypeId) bool {
        if (obj_t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(obj_t);
        if (flags.is_signature and self.interner.isSignature(obj_t)) {
            const sig_payload_idx = self.interner.pool.payloadOf(obj_t);
            if (sig_payload_idx >= self.interner.pool.signature_payloads.items.len) return false;
            return self.interner.pool.signature_payloads.items[sig_payload_idx].is_construct;
        }
        if (!flags.is_object_type) return false;
        const call_id = self.string_interner.intern("__call") catch return false;
        const construct_id = self.string_interner.intern("__construct") catch return false;
        var saw_construct = false;
        for (self.interner.objectMembers(obj_t)) |member| {
            if (member.name == call_id and self.interner.isSignature(member.type)) return false;
            if (member.name == construct_id and self.interner.isSignature(member.type)) saw_construct = true;
        }
        return saw_construct;
    }

    /// True when `t` is a union whose every member is itself callable
    /// (a function signature, or an object type carrying a `__call`
    /// member). Used by the call-expression handler to suppress the
    /// spurious TS2349 ("This expression is not callable") on
    /// `(F1 | F2)(...)` call sites ÃÂ¢ÃÂÃÂ the exact-mode resolver doesn't
    /// model union-of-callable reduction yet, but the call IS valid
    /// upstream and should not error. Returns false for non-unions
    /// and for unions with any non-callable member.
    fn unionAllMembersCallable(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_union) return false;
        const members = self.interner.unionMembers(t);
        if (members.len == 0) return false;
        const call_id = self.string_interner.intern("__call") catch return false;
        for (members) |m| {
            if (self.typeIsAny(m)) continue;
            if (m >= self.interner.pool.typeCount()) return false;
            const mf = self.interner.pool.flagsOf(m);
            if (mf.is_signature and self.interner.isSignature(m)) {
                const sig_payload_idx = self.interner.pool.payloadOf(m);
                if (sig_payload_idx >= self.interner.pool.signature_payloads.items.len) return false;
                // Construct-only signatures (`new () => T`) aren't
                // callable; require a call signature.
                if (self.interner.pool.signature_payloads.items[sig_payload_idx].is_construct) return false;
                continue;
            }
            if (!mf.is_object_type) return false;
            var saw_call = false;
            for (self.interner.objectMembers(m)) |om| {
                if (om.name == call_id and self.interner.isSignature(om.type)) {
                    const sig_payload_idx = self.interner.pool.payloadOf(om.type);
                    if (sig_payload_idx >= self.interner.pool.signature_payloads.items.len) continue;
                    if (self.interner.pool.signature_payloads.items[sig_payload_idx].is_construct) continue;
                    saw_call = true;
                    break;
                }
            }
            if (!saw_call) return false;
        }
        return true;
    }

    fn unionMembersAreDirectCallSignatures(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_union) return false;
        const members = self.interner.unionMembers(t);
        if (members.len == 0) return false;
        for (members) |member| {
            if (!self.interner.isSignature(member) or self.signatureIsConstruct(member)) return false;
        }
        return true;
    }

    fn functionInterfaceMemberForCallableObject(self: *Checker, obj_t: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (!self.objectHasCallOrConstructSignature(obj_t)) return null;
        if (self.nonConstructCallSignatureOfType(obj_t)) |sig| {
            if (try self.signaturePrototypeMember(sig, name)) |member_t| return member_t;
        }
        const function_name = self.string_interner.intern("Function") catch return error.OutOfMemory;
        if (self.type_names.get(function_name)) |function_t| {
            if (try self.lookupObjectMember(function_t, name)) |member_t| return member_t;
            const string_idx = self.interner.objectStringIndex(function_t);
            return if (string_idx != types.Primitive.none) string_idx else null;
        }
        // Hardcoded fallback for fixtures without a real `lib.d.ts`
        // backing ÃÂ¢ÃÂÃÂ every Function-prototype member that upstream tsc
        // resolves to here, typed as `any`. Without this, simple
        // `i.apply` / `b.arguments` lookups on callable / constructable
        // object types would spuriously fire TS2339. Mirrors
        // `objectTypeWithCallSignatureAppearsToBeFunctionType` and
        // `objectTypeWithCallSignatureHidingMembersOfFunction`.
        const raw = self.string_interner.get(name);
        const function_proto_members = [_][]const u8{
            "apply",     "call",        "bind",   "toString",
            "arguments", "caller",      "length", "name",
            "prototype", "constructor",
        };
        for (function_proto_members) |m| {
            if (std.mem.eql(u8, raw, m)) return types.Primitive.any;
        }
        return null;
    }

    fn functionInterfaceStringIndexForCallableObject(self: *Checker, obj_t: TypeId) CheckError!?TypeId {
        if (!self.objectHasCallOrConstructSignature(obj_t)) return null;
        const function_name = self.string_interner.intern("Function") catch return error.OutOfMemory;
        const function_t = self.type_names.get(function_name) orelse return null;
        const string_idx = self.interner.objectStringIndex(function_t);
        return if (string_idx != types.Primitive.none) string_idx else null;
    }

    fn typeOfDottedValueReference(self: *Checker, raw: []const u8, at_node: NodeId) CheckError!?TypeId {
        var parts = std.mem.splitScalar(u8, raw, '.');
        const root_raw = parts.next() orelse return null;
        if (root_raw.len == 0) return null;
        const root_name = self.string_interner.intern(root_raw) catch return error.OutOfMemory;
        const root_is_this = std.mem.eql(u8, root_raw, "this");
        var current = if (root_is_this)
            try self.typeOfThisForTypeQuery(at_node)
        else
            self.lookupNarrow(root_name) orelse (try self.typeOfVisibleNameNoDiag(at_node, root_name)) orelse return null;
        var current_is_global_this = root_is_this and self.typeIsBareGlobalThis(current);
        var root_for_narrow: ?hir_mod.StringId = root_name;
        while (parts.next()) |part| {
            if (part.len == 0) return null;
            const prop_name = self.string_interner.intern(part) catch return error.OutOfMemory;
            if (root_is_this and self.strict_flags.strict_null_checks and self.typeIsPossiblyNullishStrict(current)) {
                try self.reportThisTypeQueryPossiblyNullish(at_node, current);
                current = types.Primitive.any;
                current_is_global_this = false;
            }
            if (root_for_narrow) |obj_name| {
                if (std.mem.eql(u8, part, "prototype")) {
                    if (self.class_instance_types.get(obj_name)) |instance_t| {
                        current = instance_t;
                        root_for_narrow = null;
                        continue;
                    }
                }
            }
            if (root_for_narrow) |obj_name| {
                const key: MemberKey = .{ .obj_name = obj_name, .prop_name = prop_name };
                if (self.lookupMemberNarrow(key)) |nt| {
                    current = nt;
                    root_for_narrow = null;
                    continue;
                }
            }
            if (try self.lookupObjectMember(current, prop_name)) |member_t| {
                if (member_t == types.Primitive.any) {
                    if (root_for_narrow) |obj_name| {
                        if (self.recursiveObjectTypeofMemberType(at_node, obj_name, prop_name, current)) |recursive_t| {
                            current = recursive_t;
                            current_is_global_this = false;
                            root_for_narrow = null;
                            continue;
                        }
                    }
                }
                current = member_t;
            } else {
                current = blk: {
                    if (root_is_this and current_is_global_this) {
                        try self.reportGlobalThisNoIndexSignatureForQualifiedTypeQuery(at_node);
                        break :blk types.Primitive.any;
                    }
                    if (std.mem.eql(u8, root_raw, "this") and self.class_name_by_instance.get(current) != null) {
                        if (try self.allocPropertyMissingTargetTypeName(current)) |target_text| {
                            const msg = try std.fmt.allocPrint(
                                self.diag_arena.allocator(),
                                "Property '{s}' does not exist on type '{s}'.",
                                .{ part, target_text },
                            );
                            try self.diagnostics.append(self.gpa, .{
                                .node = at_node,
                                .pos = self.qualifiedTypeRefLeafNamePos(at_node),
                                .code = TsCodes.property_does_not_exist,
                                .message = msg,
                            });
                            break :blk types.Primitive.any;
                        }
                    }
                    return null;
                };
            }
            current_is_global_this = false;
            root_for_narrow = null;
        }
        return current;
    }

    fn recursiveObjectTypeofMemberType(
        self: *Checker,
        at_node: NodeId,
        obj_name: hir_mod.StringId,
        prop_name: hir_mod.StringId,
        obj_t: TypeId,
    ) ?TypeId {
        var cur = at_node;
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .var_decl and k != .let_decl and k != .const_decl) continue;
            const scope = self.hir.parentOf(cur);
            if (scope == hir_mod.none_node_id) return null;
            const stmts: []const NodeId = switch (self.hir.kindOf(scope)) {
                .block_stmt => hir_mod.blockStmts(self.hir, scope),
                .namespace_decl => hir_mod.namespaceBody(self.hir, scope),
                else => return null,
            };
            for (stmts) |raw| {
                const decl = self.unwrapExportDecl(raw);
                if (decl == cur) return null;
                const dk = self.hir.kindOf(decl);
                if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
                const v = hir_mod.varDeclOf(self.hir, decl);
                if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
                if (hir_mod.identifierOf(self.hir, v.name).name != obj_name) continue;
                if (self.objectTypeMemberIsDirectTypeofName(v.type_annotation, prop_name, obj_name)) return obj_t;
            }
            return null;
        }
        return null;
    }

    fn objectTypeMemberIsDirectTypeofName(
        self: *Checker,
        type_node: NodeId,
        prop_name: hir_mod.StringId,
        obj_name: hir_mod.StringId,
    ) bool {
        if (type_node == hir_mod.none_node_id or self.hir.kindOf(type_node) != .object_type) return false;
        for (hir_mod.objectTypeMembers(self.hir, type_node)) |member| {
            if (self.hir.kindOf(member) != .interface_member) continue;
            const im = hir_mod.interfaceMemberOf(self.hir, member);
            if (im.name != prop_name) continue;
            if (self.varDeclTypeAnnotationDirectTypeofName(im.type_node)) |name| return name == obj_name;
        }
        return false;
    }

    fn typeOfThisForTypeQuery(self: *Checker, node: NodeId) CheckError!TypeId {
        const this_rebound_plain_function = self.thisInsideNonArrowPlainFunction(node);
        if (self.sourceHasStrictFalseDirective() and this_rebound_plain_function and
            !self.enclosingThisHostHasExplicitThisParam(node))
        {
            return types.Primitive.any;
        }
        self.checkThisBeforeSuperInConstructor(node) catch {};
        if (self.thisInsideEnumInitializer(node)) {
            try self.report(node, TsCodes.this_in_current_location, "'this' cannot be referenced in current location.");
            return types.Primitive.any;
        }
        if (self.in_computed_property_name) {
            try self.report(node, TsCodes.this_in_computed_property_name, "'this' cannot be referenced in a computed property name.");
            return types.Primitive.any;
        }
        if (self.thisInsideStaticDecoratedClassPropertyInitializer(node)) {
            try self.report(node, TsCodes.this_in_static_property_initializer_decorated_class, "Cannot use 'this' in a static property initializer of a decorated class.");
            return types.Primitive.any;
        }

        const directly_in_namespace = self.thisTypeQueryCapturedFromNamespaceBody(node);
        if (directly_in_namespace) {
            try self.report(node, TsCodes.this_in_namespace_body, "'this' cannot be referenced in a module or namespace body.");
        }

        if (!directly_in_namespace and self.nodeHasAncestorKind(node, .decorator)) return types.Primitive.any;
        if (!directly_in_namespace and self.thisIsGlobalScriptThis(node)) {
            if (self.identifierThisIsArrowCaptured(node)) {
                try self.report(node, TsCodes.arrow_captures_global_this, "The containing arrow function captures the global value of 'this'.");
            }
            return try self.bareGlobalThisType();
        }
        if (self.thisInsideTopLevelContextualArrowWithThis(node)) return try self.bareGlobalThisType();

        if (!this_rebound_plain_function or
            self.enclosingThisHostHasExplicitThisParam(node) or
            (this_rebound_plain_function and self.thisInsideObjectLiteralMethod(node) and self.currentThisType() != null))
        {
            if (self.currentThisType()) |this_t| return this_t;
        }

        if (self.strict_flags.no_implicit_any and
            !self.sourceHasStrictFalseDirective() and
            (!self.identifierThisIsArrowCaptured(node) or directly_in_namespace) and
            !self.thisInsideObjectLiteralMethod(node) and
            !self.thisInsideClassConstructorParameter(node) and
            !self.thisIsPrivateMemberReceiverInsideClass(node))
        {
            try self.reportThisImplicitlyAny(node);
        }
        return types.Primitive.any;
    }

    fn thisTypeQueryCapturedFromNamespaceBody(self: *Checker, node: NodeId) bool {
        const inside_decorator = self.nodeHasAncestorKind(node, .decorator);
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) continue;
            if (k == .fn_decl or k == .fn_expr or
                ((!inside_decorator) and (k == .class_decl or k == .class_expr))) return false;
            if (k == .namespace_decl or k == .module_decl) return true;
        }
        return false;
    }

    fn typeIsBareGlobalThis(self: *Checker, t: TypeId) bool {
        const global_name = self.string_interner.intern("typeof globalThis") catch return false;
        const global_t = self.type_names.get(global_name) orelse return false;
        return global_t == t;
    }

    fn reportThisTypeQueryPossiblyNullish(self: *Checker, node: NodeId, t: TypeId) CheckError!void {
        const kind = self.nullishKindOf(t);
        const suffix: []const u8 = switch (kind) {
            .only_null => "'null'",
            .only_undefined => "'undefined'",
            .both => "'null' or 'undefined'",
        };
        const code: u32 = switch (kind) {
            .only_null => TsCodes.object_possibly_null,
            .only_undefined => TsCodes.object_possibly_undefined_18048,
            .both => TsCodes.object_possibly_nullish,
        };
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'this' is possibly {s}.",
            .{suffix},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = code,
            .message = msg,
        });
    }

    fn reportGlobalThisNoIndexSignatureForQualifiedTypeQuery(self: *Checker, node: NodeId) CheckError!void {
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = self.qualifiedTypeRefLeafNamePos(node),
            .code = TsCodes.global_this_no_index_signature,
            .message = "Element implicitly has an 'any' type because type 'typeof globalThis' has no index signature.",
        });
    }

    fn typeOfVisibleNameNoDiag(self: *Checker, at_node: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (self.lookupNarrow(name)) |t| return t;
        var cur: hir_mod.NodeId = self.hir.parentOf(at_node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                for (hir_mod.fnParams(self.hir, cur)) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
                    const pid = hir_mod.identifierOf(self.hir, pp.name);
                    if (pid.name == name and self.hir.typeOf(p) != types.Primitive.none) return self.hir.typeOf(p);
                }
            }
            if (k == .block_stmt or k == .namespace_decl) {
                const stmts = if (k == .block_stmt)
                    hir_mod.blockStmts(self.hir, cur)
                else
                    hir_mod.namespaceBody(self.hir, cur);
                for (stmts) |raw_s| {
                    // `export var`, `export function`, `export class`,
                    // `export import Z = M` etc. wrap the inner decl in
                    // an `.export_decl`. Unwrap so the visibility walk
                    // sees the bound identifier directly ÃÂ¢ÃÂÃÂ without this
                    // step `typeof Z` for an `export import Z = M` would
                    // miss the binding and emit a spurious TS2304.
                    const s = self.unwrapExportDecl(raw_s);
                    const sk = self.hir.kindOf(s);
                    if (sk == .var_decl or sk == .let_decl or sk == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, s);
                        if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
                        const vid = hir_mod.identifierOf(self.hir, v.name);
                        if (vid.name != name) continue;
                        const existing = self.hir.typeOf(s);
                        if (existing != types.Primitive.none) return existing;
                        if (v.type_annotation != hir_mod.none_node_id) {
                            const declared_t = self.lowerValueTypeAnnotation(vid.name, v.type_annotation) catch types.Primitive.any;
                            self.hir.setType(s, declared_t);
                            self.hir.setType(v.name, declared_t);
                            return declared_t;
                        }
                    } else if (sk == .fn_decl or sk == .fn_expr) {
                        const fp = hir_mod.fnDeclOf(self.hir, s);
                        if (fp.name == hir_mod.none_node_id or self.hir.kindOf(fp.name) != .identifier) continue;
                        const fid = hir_mod.identifierOf(self.hir, fp.name);
                        if (fid.name == name and self.hir.typeOf(s) != types.Primitive.none) return self.hir.typeOf(s);
                    } else if (sk == .class_decl or sk == .class_expr) {
                        const cp = hir_mod.classOf(self.hir, s);
                        if (cp.name == hir_mod.none_node_id or self.hir.kindOf(cp.name) != .identifier) continue;
                        const cid = hir_mod.identifierOf(self.hir, cp.name);
                        if (cid.name == name) {
                            if (self.class_static_types.get(name)) |static_t| return static_t;
                            if (self.hir.typeOf(s) != types.Primitive.none) return self.hir.typeOf(s);
                        }
                    } else if (sk == .enum_decl) {
                        const decl_name = self.declarationName(s) orelse continue;
                        if (decl_name == name) return try self.enumNamespaceValueType(s, name);
                    } else if (sk == .import_decl) {
                        if (self.importDeclBindsLocal(s, name)) {
                            if (self.moduleNamespaceTypeForLocalImport(name, at_node) catch null) |ns_t| return ns_t;
                            return types.Primitive.any;
                        }
                    } else if (sk == .for_in_stmt or sk == .for_of_stmt) {
                        const fr = hir_mod.forInOf(self.hir, s);
                        if (fr.target == hir_mod.none_node_id or self.hir.kindOf(fr.target) != .var_decl) continue;
                        const v = hir_mod.varDeclOf(self.hir, fr.target);
                        if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
                        if (hir_mod.identifierOf(self.hir, v.name).name != name) continue;
                        const t = self.hir.typeOf(fr.target);
                        return if (t == types.Primitive.none) types.Primitive.any else t;
                    }
                }
            }
        }
        if (self.module) |module| {
            if (module.root.lookup(name)) |sym| {
                if (self.visibleValueSymbolDeclForNode(sym.decls.items, at_node)) |decl| {
                    if (self.hir.kindOf(decl) == .enum_decl) {
                        return try self.enumNamespaceValueType(decl, name);
                    }
                    if (self.hir.typeOf(decl) != types.Primitive.none) return self.hir.typeOf(decl);
                }
            }
        }
        return null;
    }

    fn predicateTargetIsBroadObject(self: *Checker, target: TypeId) bool {
        _ = self;
        return target == types.Primitive.object_t;
    }

    fn predicateTargetIsFunctionObject(self: *Checker, target: TypeId) bool {
        const function_t = self.lowerBuiltinObjectType("Function") orelse return false;
        return target == function_t;
    }

    fn predicateTargetNodeIsBareName(self: *Checker, node: NodeId, name: []const u8) bool {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .type_ref) return false;
        const r = hir_mod.typeRefOf(self.hir, node);
        if (r.qualifier_len != 0) return false;
        return std.mem.eql(u8, self.string_interner.get(r.name), name);
    }

    /// The primitive `typeof` tag a numeric/string enum value carries at
    /// runtime: `number_t` for a numeric enum, `string_t` for a string enum,
    /// else `none`. Covers both representations Home uses — an enum-member
    /// literal (`is_enum_literal` + `is_number`/`is_string`) and the
    /// whole-enum nominal intersection (`number & { __enum:E }` /
    /// `string & { __enum:E }`). Used so typeof narrowing keeps an enum
    /// constituent that matches the guarded tag.
    fn enumTypeofBackingTag(self: *Checker, t: TypeId) TypeId {
        if (t >= self.interner.pool.typeCount()) return types.Primitive.none;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_enum_literal) {
            if (f.is_number) return types.Primitive.number_t;
            if (f.is_string) return types.Primitive.string_t;
            return types.Primitive.none;
        }
        if (!f.is_intersection) return types.Primitive.none;
        var backing: TypeId = types.Primitive.none;
        var saw_enum_brand = false;
        for (self.interner.intersectionMembers(t)) |m| {
            if (m == types.Primitive.number_t or m == types.Primitive.string_t) {
                backing = m;
                continue;
            }
            if (m >= self.interner.pool.typeCount()) continue;
            if (!self.interner.pool.flagsOf(m).is_object_type) continue;
            for (self.interner.objectMembers(m)) |om| {
                const name = self.string_interner.getOptional(om.name) orelse continue;
                if (std.mem.startsWith(u8, name, "__enum:")) {
                    saw_enum_brand = true;
                    break;
                }
            }
        }
        return if (saw_enum_brand) backing else types.Primitive.none;
    }

    fn typeMatchesPredicateTarget(self: *Checker, member: TypeId, target: TypeId) bool {
        if (member == target) return true;
        if (target < self.interner.pool.typeCount() and self.interner.pool.flagsOf(target).is_union) {
            for (self.interner.unionMembers(target)) |target_member| {
                if (self.typeMatchesPredicateTarget(member, target_member)) return true;
            }
            return false;
        }
        if (self.predicateTargetIsBroadObject(target)) return self.typeIsObjectLikePredicateMember(member);
        if (self.predicateTargetIsFunctionObject(target) and self.objectHasCallOrConstructSignature(member)) return true;
        if (self.typeParameterConstraintAssignableTo(member, target)) return true;
        if (self.class_name_by_instance.contains(member) and
            self.class_name_by_instance.contains(target) and
            member < self.interner.pool.typeCount() and
            target < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(member).is_object_type and
            self.interner.pool.flagsOf(target).is_object_type and
            self.objectTypesSameDisplayShape(member, target))
        {
            return true;
        }
        // A numeric enum member matches a `typeof === "number"` guard and a
        // string enum member a `typeof === "string"` guard: at runtime the
        // enum value carries its backing primitive's tag. The relation engine
        // keeps enums nominal (`E.X` is not assignable to `number`), so
        // `isAssignableTo` below would drop them — narrowing a
        // `Color | string` union by `typeof x === "number"` to `never` and
        // tripping a spurious TS2403. Mirrors tsc's typeof-facts, which map a
        // numeric/string enum to NumberFacts/StringFacts. Pins
        // `TypeGuardWithEnumUnion`.
        if ((target == types.Primitive.number_t or target == types.Primitive.string_t) and
            self.enumTypeofBackingTag(member) == target) return true;
        return self.engine.isAssignableTo(member, target) catch false;
    }

    fn typeIsObjectLikePredicateMember(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return false;
        if (self.enumTypeofBackingTag(t) != types.Primitive.none) return false;
        const flags = self.interner.pool.flagsOf(t);
        return flags.is_object or
            flags.is_object_type or
            flags.is_signature or
            flags.is_tuple or
            flags.is_intersection;
    }

    fn objectOrNullType(self: *Checker) TypeId {
        return self.interner.internUnion(&.{ types.Primitive.object_t, types.Primitive.null_t }) catch types.Primitive.object_t;
    }

    fn nullUndefinedUnionType(self: *Checker) CheckError!TypeId {
        return self.interner.internUnion(&.{ types.Primitive.null_t, types.Primitive.undefined_t }) catch return error.OutOfMemory;
    }

    fn unknownEmptyObjectType(self: *Checker) CheckError!TypeId {
        const empty_obj = self.interner.internObjectType(&.{}) catch return error.OutOfMemory;
        try self.unknown_empty_object_types.put(self.gpa, empty_obj, {});
        return empty_obj;
    }

    fn narrowTypeByDirectInstanceof(self: *Checker, current: TypeId, target: TypeId) CheckError!TypeId {
        if (current == target or self.typeIsAnyLike(current)) return target;
        if (self.typeIsAnyLike(target)) return current;
        const target_class = self.classNameForInstanceType(target);
        const current_flags = self.interner.pool.flagsOf(current);
        if (current_flags.is_union) {
            var kept: std.ArrayListUnmanaged(TypeId) = .empty;
            defer kept.deinit(self.gpa);
            for (self.interner.unionMembers(current)) |member| {
                if (target_class) |target_name| {
                    if (self.classNameForInstanceType(member)) |member_name| {
                        if (member_name == target_name or self.classExtendsClass(member_name, target_name)) {
                            try self.appendUniqueTypeId(&kept, member);
                        } else if (self.classExtendsClass(target_name, member_name)) {
                            try self.appendUniqueTypeId(&kept, target);
                        }
                        continue;
                    }
                }
                if (member == target or
                    (self.engine.isAssignableTo(member, target) catch false) or
                    self.instanceofGenericDisplayFamilyMatches(member, target) or
                    self.instanceofGenericObjectTargetMatches(member, target) or
                    self.typeParameterConstraintMatchesInstanceofTarget(member, target) or
                    (target_class != null and self.classNameForInstanceType(member) == target_class))
                {
                    try kept.append(self.gpa, member);
                    continue;
                }
                if (self.directInstanceofTargetExtendsMember(member, target_class)) {
                    try kept.append(self.gpa, target);
                }
            }
            if (kept.items.len == 0) return target;
            if (kept.items.len == 1) return kept.items[0];
            return self.interner.internUnion(kept.items) catch return error.OutOfMemory;
        }
        if (target_class) |target_name| {
            if (self.classNameForInstanceType(current)) |current_name| {
                if (self.classExtendsClass(target_name, current_name)) return target;
            }
        }
        const current_to_target = self.engine.isAssignableTo(current, target) catch false;
        if (current_to_target) return current;
        return self.interner.internIntersection(&.{ current, target }) catch return error.OutOfMemory;
    }

    fn subtractTypeByDirectInstanceof(self: *Checker, current: TypeId, target: TypeId) CheckError!TypeId {
        if (current == target) return types.Primitive.never;
        const target_class = self.classNameForInstanceType(target);
        const current_flags = self.interner.pool.flagsOf(current);
        if (current_flags.is_union) {
            var kept: std.ArrayListUnmanaged(TypeId) = .empty;
            defer kept.deinit(self.gpa);
            for (self.interner.unionMembers(current)) |member| {
                if (self.directInstanceofMemberMatches(member, target, target_class)) continue;
                try kept.append(self.gpa, member);
            }
            if (kept.items.len == 0) return types.Primitive.never;
            if (kept.items.len == 1) return kept.items[0];
            return self.interner.internUnion(kept.items) catch return error.OutOfMemory;
        }
        if (self.directInstanceofMemberMatches(current, target, target_class)) return types.Primitive.never;
        return current;
    }

    fn directInstanceofMemberMatches(self: *Checker, member: TypeId, target: TypeId, target_class: ?hir_mod.StringId) bool {
        if (member == target) return true;
        if (self.typeParameterConstraintMatchesInstanceofTarget(member, target)) return true;
        if (target_class != null and self.classNameForInstanceType(member) == target_class) return true;
        return self.directInstanceofTargetExtendsMember(member, target_class);
    }

    fn typeParameterConstraintMatchesInstanceofTarget(self: *Checker, t: TypeId, target: TypeId) bool {
        const constraint = self.typeParameterConstraint(t) orelse return false;
        if (constraint == target) return true;
        const constraint_class = self.classNameForInstanceType(constraint) orelse
            return self.engine.isAssignableTo(constraint, target) catch false;
        const target_class = self.classNameForInstanceType(target) orelse return false;
        return constraint_class == target_class or self.classExtendsClass(constraint_class, target_class);
    }

    fn instanceofFalseBranchPreservesClassUnion(self: *Checker, current: TypeId, target: TypeId) bool {
        if (self.classNameForInstanceType(target) == null or target >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(target).is_object_type) return false;
        if (current < self.interner.pool.typeCount()) {
            const current_flags = self.interner.pool.flagsOf(current);
            if (current_flags.is_type_parameter and self.typeParameterConstraintMatchesInstanceofTarget(current, target)) return false;
            if (current_flags.is_union) {
                for (self.interner.unionMembers(current)) |member| {
                    if (self.typeParameterConstraintMatchesInstanceofTarget(member, target)) return false;
                }
            }
        }
        for (self.interner.objectMembers(target)) |member| {
            if (self.syntheticSignatureMemberName(member.name) or member.is_optional) continue;
            return true;
        }
        return false;
    }

    fn directInstanceofTargetExtendsMember(self: *Checker, member: TypeId, target_class: ?hir_mod.StringId) bool {
        if (target_class) |target_name| {
            if (self.classNameForInstanceType(member)) |member_name| {
                return self.classExtendsClass(target_name, member_name);
            }
        }
        return false;
    }

    fn narrowTypeByPredicate(self: *Checker, current: TypeId, target: TypeId) CheckError!TypeId {
        if (current == types.Primitive.never) return types.Primitive.never;
        if (current == target) return target;
        if (self.typeIsAnyLike(current)) {
            if (self.predicateTargetIsFunctionObject(target)) return current;
            return target;
        }
        if (self.typeIsAnyLike(target)) return current;
        const current_flags = self.interner.pool.flagsOf(current);
        if (current_flags.is_union) {
            var kept: std.ArrayListUnmanaged(TypeId) = .empty;
            defer kept.deinit(self.gpa);
            for (self.interner.unionMembers(current)) |member| {
                const member_flags = self.interner.pool.flagsOf(member);
                if ((member_flags.is_null and !self.typeIncludesNull(target)) or
                    (member_flags.is_undefined and !self.typeIncludesUndefined(target)))
                {
                    continue;
                }
                const member_to_target = self.typeMatchesPredicateTarget(member, target);
                const target_to_member = target == member or (self.engine.isAssignableTo(target, member) catch false);
                if (member_to_target) {
                    if (target_to_member and self.predicateTargetShouldReplaceMember(member, target)) {
                        try kept.append(self.gpa, target);
                    } else {
                        try kept.append(self.gpa, member);
                    }
                } else if (target_to_member) {
                    if (self.predicateTargetIsFunctionObject(target) and !self.objectHasCallOrConstructSignature(member)) continue;
                    if (self.predicateTargetIsBroadObject(target) and self.enumTypeofBackingTag(member) != types.Primitive.none) continue;
                    try kept.append(self.gpa, target);
                }
            }
            if (kept.items.len == 0) {
                return self.interner.internIntersection(&.{ current, target }) catch return error.OutOfMemory;
            }
            if (kept.items.len == 1) return kept.items[0];
            return self.interner.internUnion(kept.items) catch return error.OutOfMemory;
        }
        const current_to_target = self.engine.isAssignableTo(current, target) catch false;
        const target_to_current = self.engine.isAssignableTo(target, current) catch false;
        if (current_to_target and !target_to_current) return current;
        if (target_to_current) return target;
        return self.interner.internIntersection(&.{ current, target }) catch return error.OutOfMemory;
    }

    fn predicateTargetShouldReplaceMember(self: *Checker, member: TypeId, target: TypeId) bool {
        if (member >= self.interner.pool.typeCount() or target >= self.interner.pool.typeCount()) return false;
        const member_flags = self.interner.pool.flagsOf(member);
        const target_flags = self.interner.pool.flagsOf(target);
        if (!member_flags.is_object_type or !target_flags.is_object_type) return false;
        if (self.class_name_by_instance.contains(member) or self.class_name_by_instance.contains(target)) return false;
        return self.interner.objectMembers(target).len > self.interner.objectMembers(member).len;
    }

    fn subtractTypeByPredicate(self: *Checker, current: TypeId, target: TypeId) CheckError!TypeId {
        if (current == types.Primitive.never or current == target) return types.Primitive.never;
        if (self.typeIsAny(current)) return current;
        const current_flags = self.interner.pool.flagsOf(current);
        if (current_flags.is_union) {
            var kept: std.ArrayListUnmanaged(TypeId) = .empty;
            defer kept.deinit(self.gpa);
            for (self.interner.unionMembers(current)) |member| {
                const remove = self.typeMatchesPredicateTarget(member, target);
                if (!remove) try kept.append(self.gpa, member);
            }
            if (kept.items.len == 0) return types.Primitive.never;
            if (kept.items.len == 1) return kept.items[0];
            return self.interner.internUnion(kept.items) catch return error.OutOfMemory;
        }
        return if (self.typeMatchesPredicateTarget(current, target)) types.Primitive.never else current;
    }

    fn propertyAllowsDelete(self: *Checker, obj_t: TypeId, name: hir_mod.StringId) bool {
        if (self.typeIsAnyLike(obj_t)) return true;
        const non_null_obj = self.subtractNullUndefined(obj_t) catch obj_t;
        const flags = self.interner.pool.flagsOf(non_null_obj);
        if (flags.is_union) {
            for (self.interner.unionMembers(non_null_obj)) |member_t| {
                if (!self.propertyAllowsDelete(member_t, name)) return false;
            }
            return true;
        }
        if (!flags.is_object_type) return true;
        const info = self.interner.objectMemberInfo(non_null_obj, name) orelse return true;
        return info.is_optional or self.typeIncludesUndefined(info.type);
    }

    fn namespaceMemberAllowsDelete(self: *Checker, object: NodeId, name: hir_mod.StringId, anchor: NodeId) CheckError!?bool {
        if (self.hir.kindOf(object) != .identifier) return null;
        const obj_id = hir_mod.identifierOf(self.hir, object);
        const member_t = (try self.mergedNamespaceValueMemberType(obj_id.name, name, anchor)) orelse return null;
        return self.typeIncludesUndefined(member_t);
    }

    fn deleteOperandAllowed(self: *Checker, operand: NodeId) CheckError!bool {
        return switch (self.hir.kindOf(operand)) {
            .member_access => blk: {
                const m = hir_mod.memberOf(self.hir, operand);
                if (try self.namespaceMemberAllowsDelete(m.object, m.name, operand)) |allowed| break :blk allowed;
                const obj_t = self.hir.typeOf(m.object);
                if (obj_t == types.Primitive.none) break :blk true;
                break :blk self.propertyAllowsDelete(obj_t, m.name);
            },
            .element_access => blk: {
                const e = hir_mod.elementOf(self.hir, operand);
                if (self.hir.kindOf(e.index) != .literal_string) break :blk true;
                const key = hir_mod.literalStringOf(self.hir, e.index).value;
                if (try self.namespaceMemberAllowsDelete(e.object, key, operand)) |allowed| break :blk allowed;
                const obj_t = self.hir.typeOf(e.object);
                if (obj_t == types.Primitive.none) break :blk true;
                break :blk self.propertyAllowsDelete(obj_t, key);
            },
            else => true,
        };
    }

    /// True when the property `name` on `obj_t` is declared read-only
    /// (e.g. `Symbol.iterator`, `String.prototype.length`). Used to
    /// pick TS2704 over TS2790 in the `delete` operand check. Mirrors
    /// `symbolType3.ts(2,8)`. Returns false for any-like types and
    /// for union members where any branch is non-readonly.
    fn propertyIsReadOnly(self: *Checker, obj_t: TypeId, name: hir_mod.StringId) bool {
        if (self.typeIsAnyLike(obj_t)) return false;
        const non_null_obj = self.subtractNullUndefined(obj_t) catch obj_t;
        const flags = self.interner.pool.flagsOf(non_null_obj);
        if (flags.is_union) {
            for (self.interner.unionMembers(non_null_obj)) |member_t| {
                if (!self.propertyIsReadOnly(member_t, name)) return false;
            }
            return true;
        }
        if (!flags.is_object_type) return false;
        const info = self.interner.objectMemberInfo(non_null_obj, name) orelse return false;
        return info.is_readonly;
    }

    fn deleteOperandIsReadOnly(self: *Checker, operand: NodeId) bool {
        return switch (self.hir.kindOf(operand)) {
            .member_access => blk: {
                const m = hir_mod.memberOf(self.hir, operand);
                const obj_t = self.hir.typeOf(m.object);
                // Enum members are read-only (`enum E { A }; delete E.A`
                // ÃÂ¢ÃÂÃÂ TS2704). Mirrors deleteOperatorWithEnumType.ts.
                if (self.identifierReferencesEnum(m.object)) break :blk true;
                if (obj_t == types.Primitive.none) break :blk false;
                if (self.enumNameFromNominal(obj_t) != null) break :blk true;
                break :blk self.propertyIsReadOnly(obj_t, m.name);
            },
            .element_access => blk: {
                const e = hir_mod.elementOf(self.hir, operand);
                if (self.hir.kindOf(e.index) != .literal_string) break :blk false;
                if (self.identifierReferencesEnum(e.object)) break :blk true;
                const obj_t = self.hir.typeOf(e.object);
                if (obj_t == types.Primitive.none) break :blk false;
                if (self.enumNameFromNominal(obj_t) != null) break :blk true;
                const key = hir_mod.literalStringOf(self.hir, e.index).value;
                break :blk self.propertyIsReadOnly(obj_t, key);
            },
            else => false,
        };
    }

    fn deleteOperandHasReadonlyIndexSignature(self: *Checker, operand: NodeId) bool {
        const obj_node: NodeId = switch (self.hir.kindOf(operand)) {
            .element_access => hir_mod.elementOf(self.hir, operand).object,
            .member_access => hir_mod.memberOf(self.hir, operand).object,
            else => return false,
        };
        var obj_t = self.hir.typeOf(obj_node);
        if (obj_t == types.Primitive.none and self.hir.kindOf(obj_node) == .identifier) {
            obj_t = self.typeOfIdentifierDeclared(obj_node);
        }
        return self.typeHasReadonlyIndexSignature(obj_t);
    }

    /// True when `node` is an identifier whose name binds to an enum
    /// declaration in the current scope. Used by delete-operand
    /// read-only detection for `delete E.A` / `delete E["A"]`.
    fn identifierReferencesEnum(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) != .identifier) return false;
        const name = hir_mod.identifierOf(self.hir, node).name;
        return self.enumDeclForName(name) != null;
    }

    fn deleteOperandOptionalityAnchorPos(self: *Checker, operand: NodeId) ?u32 {
        if (self.hir.kindOf(operand) != .member_access) return null;
        const m = hir_mod.memberOf(self.hir, operand);
        if (!m.optional) return null;
        const src = self.source orelse return null;
        const object_span = self.hir.spanOf(m.object);
        if (object_span.end >= src.len or src[object_span.end] != ')') return null;
        return self.symbolOperandAnchorPos(m.object);
    }

    fn deleteOperandContainsPrivateIdentifier(self: *Checker, operand: NodeId) bool {
        return switch (self.hir.kindOf(operand)) {
            .identifier => blk: {
                const name = self.string_interner.get(hir_mod.identifierOf(self.hir, operand).name);
                break :blk std.mem.startsWith(u8, name, "#");
            },
            .member_access => blk: {
                const m = hir_mod.memberOf(self.hir, operand);
                const name = self.string_interner.get(m.name);
                break :blk std.mem.startsWith(u8, name, "#") or self.deleteOperandContainsPrivateIdentifier(m.object);
            },
            .element_access => self.deleteOperandContainsPrivateIdentifier(hir_mod.elementOf(self.hir, operand).object),
            else => false,
        };
    }

    /// True when `t` looks array-like enough to destructure with an
    /// array binding pattern: an array/tuple object type whose number
    /// index resolves, or `any`/`unknown` (treated as opaque). Falls
    /// back to checking iterable-like for primitives like `string`.
    fn elemIsArrayLikeForForOfDestructure(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return true;
        if (t == types.Primitive.string_t) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_object_type) {
            if (self.interner.objectNumberIndex(t) != types.Primitive.none) return true;
            // Tuple shapes expose positional members but no number
            // indexer ÃÂ¢ÃÂÃÂ treat presence of any `0`/`1`/... member as
            // array-like for destructure purposes.
            return self.isTupleShapedTarget(t);
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |m| {
                if (!self.elemIsArrayLikeForForOfDestructure(m)) return false;
            }
            return true;
        }
        return false;
    }

    fn es5ForOfDownlevelRequiredType(self: *Checker, t: TypeId) ?TypeId {
        if (t == types.Primitive.any or t == types.Primitive.unknown or t == types.Primitive.string_t) return null;
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_string and !flags.is_object_type) return null;
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return null;
            if (constraint == t) return null;
            return self.es5ForOfDownlevelRequiredType(constraint);
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.es5ForOfDownlevelRequiredType(member)) |required_t| return required_t;
            }
            return null;
        }
        if (!flags.is_object_type) return null;
        if (self.es5BuiltinCollectionRequiresDownlevel(t) or self.es5SyncGeneratorRequiresDownlevel(t)) return t;
        if (self.interner.objectNumberIndex(t) != types.Primitive.none or self.isTupleShapedTarget(t)) return null;
        return if (self.isIterableLikeType(t)) t else null;
    }

    fn es5BuiltinCollectionRequiresDownlevel(self: *Checker, t: TypeId) bool {
        const display = self.alias_display_names.get(t) orelse return false;
        return std.mem.startsWith(u8, display, "Set<") or std.mem.startsWith(u8, display, "Map<");
    }

    fn es5SyncGeneratorRequiresDownlevel(self: *Checker, t: TypeId) bool {
        if (!self.generator_type_info.contains(t)) return false;
        const iterator_id = self.string_interner.intern("Symbol.iterator") catch return false;
        return self.interner.objectMember(t, iterator_id) != null;
    }

    fn es5ForOfNonArrayUnionMember(self: *Checker, t: TypeId) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_union) return null;
        var rejected: TypeId = types.Primitive.none;
        var has_non_array = false;
        for (self.interner.unionMembers(t)) |member| {
            if (member == types.Primitive.string_t or
                (member < self.interner.pool.typeCount() and self.interner.pool.flagsOf(member).is_string))
            {
                continue;
            }
            rejected = if (rejected == types.Primitive.none)
                member
            else
                self.interner.internUnion(&.{ rejected, member }) catch return t;
            if (!self.elemIsArrayLikeForForOfDestructure(member)) has_non_array = true;
        }
        return if (has_non_array and rejected != types.Primitive.none) rejected else null;
    }

    fn arrayElementType(self: *Checker, obj_t: TypeId) CheckError!TypeId {
        const flags = self.interner.pool.flagsOf(obj_t);
        if (flags.is_union) {
            const members = self.interner.unionMembers(obj_t);
            var elems: std.ArrayListUnmanaged(TypeId) = .empty;
            defer elems.deinit(self.gpa);
            for (members) |member_t| {
                const elem_t = self.interner.objectNumberIndex(member_t);
                if (elem_t == types.Primitive.none) return types.Primitive.none;
                try elems.append(self.gpa, elem_t);
            }
            if (elems.items.len == 0) return types.Primitive.none;
            return self.interner.internUnion(elems.items) catch return error.OutOfMemory;
        }
        return self.interner.objectNumberIndex(obj_t);
    }

    fn signaturePrototypeMember(self: *Checker, sig: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (!self.interner.isSignature(sig)) return null;
        const name_str = self.string_interner.get(name);
        if (!std.mem.eql(u8, name_str, "call") and
            !std.mem.eql(u8, name_str, "bind") and
            !std.mem.eql(u8, name_str, "apply"))
        {
            return null;
        }

        const params = self.interner.signatureParams(sig);
        const ret = self.interner.signatureReturn(sig) orelse types.Primitive.any;

        if (std.mem.eql(u8, name_str, "call")) {
            var call_params: std.ArrayListUnmanaged(TypeId) = .empty;
            defer call_params.deinit(self.gpa);
            try call_params.append(self.gpa, types.Primitive.any);
            try call_params.appendSlice(self.gpa, params);
            return try self.interner.internSignature(call_params.items, ret, false);
        }

        if (std.mem.eql(u8, name_str, "bind")) {
            var bind_params: std.ArrayListUnmanaged(TypeId) = .empty;
            defer bind_params.deinit(self.gpa);
            try bind_params.append(self.gpa, types.Primitive.any);
            try bind_params.appendSlice(self.gpa, params);
            const bind_sig = try self.interner.internSignature(bind_params.items, types.Primitive.any, false);
            var omittable: std.ArrayListUnmanaged(bool) = .empty;
            defer omittable.deinit(self.gpa);
            try omittable.append(self.gpa, false);
            var i: usize = 0;
            while (i < params.len) : (i += 1) try omittable.append(self.gpa, true);
            try self.recordSignatureMinArgs(bind_sig, omittable.items);
            return bind_sig;
        }

        var apply_params: [2]TypeId = undefined;
        apply_params[0] = types.Primitive.any;
        apply_params[1] = if (self.rest_signatures.contains(sig) and params.len == 1)
            params[0]
        else
            try self.internTupleFromTypes(params, false);
        return try self.interner.internSignature(&apply_params, ret, false);
    }

    fn checkFunctionApplyArgumentTuple(
        self: *Checker,
        callee: NodeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) CheckError!void {
        if (args.len < 2 or arg_types.len < 2) return;
        if (self.hir.kindOf(callee) != .member_access) return;
        const m = hir_mod.memberOf(self.hir, callee);
        if (!std.mem.eql(u8, self.string_interner.get(m.name), "apply")) return;
        const receiver_t = if (self.hir.typeOf(m.object) != types.Primitive.none)
            self.hir.typeOf(m.object)
        else
            try self.checkExpression(m.object);
        const sig = self.nonConstructCallSignatureOfType(receiver_t) orelse return;
        const params = self.interner.signatureParams(sig);
        const expected_args_t = if (self.rest_signatures.contains(sig) and params.len == 1)
            params[0]
        else
            try self.internTupleFromTypes(params, false);
        if (self.hir.kindOf(args[1]) == .array_literal and
            try self.arrayLiteralAssignableToTupleTarget(args[1], expected_args_t, false))
        {
            return;
        }
        if (self.engine.isAssignableTo(arg_types[1], expected_args_t) catch true) return;
        if (self.diagnosticExistsOnNode(args[1], TsCodes.argument_type_mismatch)) return;
        const arg_text = (try self.simpleDiagnosticTypeName(arg_types[1])) orelse "any";
        const expected_text = (try self.simpleDiagnosticTypeName(expected_args_t)) orelse "[]";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Argument of type '{s}' is not assignable to parameter of type '{s}'.",
            .{ arg_text, expected_text },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = args[1],
            .code = TsCodes.argument_type_mismatch,
            .message = msg,
        });
    }

    fn diagnosticExistsOnNode(self: *Checker, node: NodeId, code: u32) bool {
        for (self.diagnostics.items) |d| {
            if (d.node == node and d.code == code) return true;
        }
        return false;
    }

    fn lookupDeclaredArrayMember(self: *Checker, elem_t: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        const array_names = [_][]const u8{ "Array", "ReadonlyArray" };
        for (array_names) |array_name| {
            const array_id = self.string_interner.intern(array_name) catch return error.OutOfMemory;
            const info = self.generic_aliases.get(array_id) orelse continue;
            var inst_t = info.body;
            if (info.params.len > 0) {
                var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                defer subs.deinit(self.gpa);
                try subs.put(self.gpa, info.params[0], elem_t);
                var i: usize = 1;
                while (i < info.params.len) : (i += 1) {
                    const p = info.params[i];
                    if (!self.interner.pool.flagsOf(p).is_type_parameter) continue;
                    const tp = self.interner.pool.type_parameter_payloads.items[self.interner.pool.payloadOf(p)];
                    if (tp.default != types.Primitive.none) try subs.put(self.gpa, p, tp.default);
                }
                inst_t = try self.substituteType(info.body, &subs);
            }
            if (self.interner.objectMember(inst_t, name)) |member_t| return member_t;
        }
        return null;
    }

    fn mappedArrayPrototypeMember(self: *Checker, mapped_t: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (!self.typeIsMappedPayloadType(mapped_t)) return null;
        const mapped = self.interner.mappedPayload(mapped_t);
        const operand = self.directKeyofOperand(mapped.constraint) orelse return null;
        const array_like = if (operand < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(operand).is_type_parameter)
            self.typeParameterConstraint(operand) orelse operand
        else
            operand;
        if (!self.everyTypeIsArrayOrTuple(array_like)) return null;
        const mapped_element = try self.mappedArrayElementFromConstraint(mapped, array_like);
        if (lib.arrayProto(
            &self.lib_cache,
            self.interner,
            self.string_interner,
            self.gpa,
            mapped_element,
            &self.rest_signatures,
        )) |proto| {
            if (self.interner.objectMember(proto, name)) |member_t| {
                try self.registerSyntheticArrayMethodTypeParameters(name, member_t);
                return member_t;
            }
        } else |_| {}
        return try self.lookupDeclaredArrayMember(mapped_element, name);
    }

    fn mappedArrayElementFromConstraint(
        self: *Checker,
        mapped: types.MappedPayload,
        array_constraint: TypeId,
    ) CheckError!TypeId {
        const indexed = self.mappedTemplateIndexedAccess(mapped.template) orelse return types.Primitive.any;
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        try subs.put(self.gpa, indexed.key_tp, types.Primitive.number_t);
        try subs.put(self.gpa, indexed.object_tp, array_constraint);
        var element_t = try self.substituteType(mapped.template, &subs);
        if (self.alias_display_names.get(mapped.template)) |display| {
            var visited: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
            defer visited.deinit(self.gpa);
            if (try self.substitutedAliasDisplayText(mapped.template, display, &subs, &visited)) |substituted| {
                try self.alias_display_names.put(self.gpa, element_t, substituted.text);
                try self.alias_type_args.put(self.gpa, element_t, substituted.args);
            }
        } else if (self.alias_display_names.contains(element_t) and
            element_t < self.interner.pool.typeCount())
        {
            const flags = self.interner.pool.flagsOf(element_t);
            if (flags.is_object_type and !flags.is_union and !flags.is_intersection and !flags.is_signature) {
                element_t = self.interner.internObjectTypeWithIndexAndSymbol(
                    self.interner.objectMembers(element_t),
                    self.interner.objectStringIndex(element_t),
                    self.interner.objectNumberIndex(element_t),
                    self.interner.objectSymbolIndex(element_t),
                ) catch return error.OutOfMemory;
            }
        }
        return element_t;
    }

    fn lookupArrayLikePrototypeMember(self: *Checker, t: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            const members = try self.gpa.dupe(TypeId, self.interner.unionMembers(t));
            defer self.gpa.free(members);
            var resolved: std.ArrayListUnmanaged(TypeId) = .empty;
            defer resolved.deinit(self.gpa);
            for (members) |member| {
                const member_t = (try self.lookupArrayLikePrototypeMember(member, name)) orelse return null;
                try resolved.append(self.gpa, member_t);
            }
            if (resolved.items.len == 0) return null;
            return self.interner.internUnion(resolved.items) catch return error.OutOfMemory;
        }
        if (!flags.is_object_type or flags.is_intersection) return null;
        const elem_t = try self.arrayElementType(t);
        if (elem_t == types.Primitive.none) return null;
        if (lib.arrayProto(&self.lib_cache, self.interner, self.string_interner, self.gpa, elem_t, &self.rest_signatures)) |proto| {
            if (self.interner.objectMember(proto, name)) |member_t| {
                try self.registerSyntheticArrayMethodTypeParameters(name, member_t);
                return member_t;
            }
        } else |_| {}
        return try self.lookupDeclaredArrayMember(elem_t, name);
    }

    fn registerSyntheticArrayMethodTypeParameters(
        self: *Checker,
        name: hir_mod.StringId,
        signature: TypeId,
    ) CheckError!void {
        if (!self.interner.isSignature(signature)) return;
        const method = self.string_interner.get(name);
        if (std.mem.eql(u8, method, "includes") or
            std.mem.eql(u8, method, "indexOf") or
            std.mem.eql(u8, method, "lastIndexOf"))
        {
            try self.signature_min_args.put(self.gpa, signature, 1);
            return;
        }
        if (self.generic_signature_params.contains(signature)) return;
        if (!std.mem.eql(u8, method, "map") and
            !std.mem.eql(u8, method, "flatMap") and
            !std.mem.eql(u8, method, "reduce") and
            !std.mem.eql(u8, method, "reduceRight"))
        {
            return;
        }
        const type_param = self.firstFreeTypeParameter(signature) orelse return;
        const type_param_name = self.typeParameterName(type_param) orelse return;
        if (!std.mem.eql(u8, self.string_interner.get(type_param_name), "U")) return;
        const owned = try self.gpa.alloc(TypeId, 1);
        owned[0] = type_param;
        try self.generic_signature_params.put(self.gpa, signature, owned);
    }

    fn constructorPrototypeAccess(self: *Checker, obj_name: hir_mod.StringId, prop_name: hir_mod.StringId) CheckError!?TypeId {
        if (!std.mem.eql(u8, self.string_interner.get(prop_name), "prototype")) return null;
        if (self.class_instance_types.get(obj_name)) |instance_t| return instance_t;
        var has_runtime_prototype = false;
        if (!has_runtime_prototype) {
            if (self.module) |module| {
                if (module.root.lookup(obj_name)) |sym| {
                    has_runtime_prototype = sym.flags.is_function or sym.flags.is_class;
                }
            }
        }
        if (!has_runtime_prototype) return null;
        return self.interner.internObjectTypeWithIndex(&.{}, types.Primitive.any, types.Primitive.none) catch return error.OutOfMemory;
    }

    fn moduleInterfaceAugmentationMemberType(
        self: *Checker,
        interface_name: hir_mod.StringId,
        member_name: hir_mod.StringId,
        anchor: NodeId,
    ) CheckError!?TypeId {
        if (self.module_interface_augmentations.len == 0) return null;
        const interface_name_str = self.string_interner.get(interface_name);
        const member_name_str = self.string_interner.get(member_name);
        for (self.module_interface_augmentations) |augmentation| {
            if (!std.mem.eql(u8, augmentation.interface_name, interface_name_str)) continue;
            if (!std.mem.eql(u8, augmentation.member_name, member_name_str)) continue;
            if (!augmentation.is_method) continue;
            const return_t = try self.moduleInterfaceAugmentationReturnType(augmentation.return_type_name, anchor);
            return self.interner.internSignature(&.{}, return_t, false) catch return error.OutOfMemory;
        }
        return null;
    }

    fn moduleInterfaceAugmentationReturnType(
        self: *Checker,
        return_type_name: []const u8,
        anchor: NodeId,
    ) CheckError!TypeId {
        if (return_type_name.len == 0) return types.Primitive.any;
        if (std.mem.eql(u8, return_type_name, "void")) return types.Primitive.void_t;
        if (std.mem.eql(u8, return_type_name, "undefined")) return types.Primitive.undefined_t;
        if (std.mem.eql(u8, return_type_name, "null")) return types.Primitive.null_t;
        if (std.mem.eql(u8, return_type_name, "string")) return types.Primitive.string_t;
        if (std.mem.eql(u8, return_type_name, "number")) return types.Primitive.number_t;
        if (std.mem.eql(u8, return_type_name, "boolean")) return types.Primitive.boolean_t;
        const name = self.string_interner.intern(return_type_name) catch return error.OutOfMemory;
        if (self.class_instance_types.get(name)) |instance_t| return instance_t;
        if (self.type_names.get(name)) |type_t| return type_t;
        if (anchor != hir_mod.none_node_id) {
            if (try self.programExportedClassInstanceTypeForImportedName(name, anchor)) |instance_t| return instance_t;
        }
        if (anchor != hir_mod.none_node_id) {
            if (try self.typeOfVisibleNameNoDiag(anchor, name)) |visible_t| return visible_t;
        }
        return types.Primitive.any;
    }

    fn moduleInterfaceAugmentationMemberForInstance(
        self: *Checker,
        obj_t: TypeId,
        member_name: hir_mod.StringId,
        anchor: NodeId,
    ) CheckError!?TypeId {
        const access_obj_t = self.typeParameterConstraint(obj_t) orelse obj_t;
        if (self.class_name_by_instance.get(access_obj_t)) |class_name| {
            return try self.moduleInterfaceAugmentationMemberType(class_name, member_name, anchor);
        }
        return null;
    }

    fn moduleInterfaceAugmentationPrototypeMember(
        self: *Checker,
        object: NodeId,
        member_name: hir_mod.StringId,
        anchor: NodeId,
    ) CheckError!?TypeId {
        if (object == hir_mod.none_node_id or self.hir.kindOf(object) != .member_access) return null;
        const proto = hir_mod.memberOf(self.hir, object);
        if (!std.mem.eql(u8, self.string_interner.get(proto.name), "prototype")) return null;
        if (proto.object == hir_mod.none_node_id or self.hir.kindOf(proto.object) != .identifier) return null;
        const ctor = hir_mod.identifierOf(self.hir, proto.object);
        return try self.moduleInterfaceAugmentationMemberType(ctor.name, member_name, anchor);
    }

    fn programExportedClassTypeForImportBinding(
        self: *Checker,
        import_node: NodeId,
        local_name: hir_mod.StringId,
        anchor: NodeId,
    ) CheckError!?TypeId {
        if (self.program_exported_classes.len == 0) return null;
        if (self.hir.kindOf(import_node) != .import_decl) return null;
        const imp = hir_mod.importOf(self.hir, import_node);
        const spec = self.string_interner.get(imp.module);
        for (hir_mod.importNamed(self.hir, import_node)) |spec_node| {
            if (self.hir.kindOf(spec_node) != .import_specifier) continue;
            const sp = hir_mod.importSpecifierOf(self.hir, spec_node);
            if (sp.local != local_name) continue;
            const imported_name_text = self.string_interner.get(sp.imported);
            for (self.program_exported_classes) |exported_class| {
                if (!std.mem.eql(u8, exported_class.class_name, imported_name_text)) continue;
                if (std.mem.startsWith(u8, spec, ".")) {
                    if (!try self.programImportTargetsPath(import_node, spec, exported_class.target_path)) continue;
                } else {
                    if (!std.mem.eql(u8, exported_class.ambient_module_name, spec)) continue;
                }
                return try self.syntheticProgramClassStaticType(exported_class, sp.imported, local_name, anchor);
            }
        }
        return null;
    }

    fn programExportedClassInstanceTypeForImportedName(
        self: *Checker,
        local_name: hir_mod.StringId,
        anchor: NodeId,
    ) CheckError!?TypeId {
        if (self.program_exported_classes.len == 0) return null;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.hir.kindOf(stmt) != .import_decl) continue;
            for (hir_mod.importNamed(self.hir, stmt)) |spec_node| {
                if (self.hir.kindOf(spec_node) != .import_specifier) continue;
                const sp = hir_mod.importSpecifierOf(self.hir, spec_node);
                if (sp.local != local_name) continue;
                _ = try self.programExportedClassTypeForImportBinding(stmt, local_name, anchor);
                if (self.class_instance_types.get(local_name)) |instance_t| return instance_t;
                if (self.class_instance_types.get(sp.imported)) |instance_t| return instance_t;
            }
        }
        return null;
    }

    fn programExportedClassInstanceTypeForImportPath(
        self: *Checker,
        import_node: NodeId,
        specifier: hir_mod.StringId,
        class_name: hir_mod.StringId,
    ) CheckError!?TypeId {
        if (self.program_exported_classes.len == 0) return null;
        const spec = self.string_interner.get(specifier);
        if (!std.mem.startsWith(u8, spec, ".")) return null;
        const class_name_text = self.string_interner.get(class_name);
        for (self.program_exported_classes) |exported_class| {
            if (!std.mem.eql(u8, exported_class.class_name, class_name_text)) continue;
            if (!try self.programImportTargetsPath(import_node, spec, exported_class.target_path)) continue;
            return try self.syntheticProgramClassInstanceType(exported_class, class_name);
        }
        return null;
    }

    fn syntheticProgramClassStaticType(
        self: *Checker,
        exported_class: ProgramExportedClass,
        class_name: hir_mod.StringId,
        local_name: hir_mod.StringId,
        anchor: NodeId,
    ) CheckError!TypeId {
        _ = anchor;
        var instance_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer instance_members.deinit(self.gpa);
        for (exported_class.members) |member| {
            const member_name = self.string_interner.intern(member.name) catch return error.OutOfMemory;
            const member_t = try self.programExportedClassMemberType(member.type_name);
            try instance_members.append(self.gpa, .{
                .name = member_name,
                .type = member_t,
                .is_optional = false,
                .is_readonly = false,
                .is_method = member.is_method,
            });
        }
        const instance_t = self.interner.internObjectType(instance_members.items) catch return error.OutOfMemory;
        const any_array = self.interner.internArrayType(self.string_interner, types.Primitive.any) catch return error.OutOfMemory;
        const construct_params = [_]TypeId{any_array};
        const construct_sig = self.interner.internSignature(&construct_params, instance_t, true) catch return error.OutOfMemory;
        try self.rest_signatures.put(self.gpa, construct_sig, {});
        try self.recordSignatureMinArgs(construct_sig, &.{true});
        const construct_name = self.string_interner.intern("__construct") catch return error.OutOfMemory;
        const name_name = self.string_interner.intern("name") catch return error.OutOfMemory;
        var static_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer static_members.deinit(self.gpa);
        try static_members.append(self.gpa, .{
            .name = construct_name,
            .type = construct_sig,
            .is_optional = false,
            .is_readonly = false,
            .is_method = true,
        });
        try static_members.append(self.gpa, .{
            .name = name_name,
            .type = types.Primitive.string_t,
            .is_optional = false,
            .is_readonly = true,
            .is_method = false,
        });
        for (exported_class.static_members) |member| {
            const member_name = self.string_interner.intern(member.name) catch return error.OutOfMemory;
            const member_t = try self.programExportedClassMemberType(member.type_name);
            try static_members.append(self.gpa, .{
                .name = member_name,
                .type = member_t,
                .is_optional = false,
                .is_readonly = false,
                .is_method = member.is_method,
            });
        }
        const static_t = self.interner.internObjectType(static_members.items) catch return error.OutOfMemory;
        try self.registerAliasDisplayText(instance_t, self.string_interner.get(class_name));
        try self.class_name_by_instance.put(self.gpa, instance_t, class_name);
        try self.class_name_by_static.put(self.gpa, static_t, class_name);
        try self.class_instance_types.put(self.gpa, local_name, instance_t);
        try self.class_static_types.put(self.gpa, local_name, static_t);
        try self.type_names.put(self.gpa, local_name, instance_t);
        if (class_name != local_name) {
            try self.class_instance_types.put(self.gpa, class_name, instance_t);
            try self.class_static_types.put(self.gpa, class_name, static_t);
            try self.type_names.put(self.gpa, class_name, instance_t);
        }
        return static_t;
    }

    fn syntheticProgramClassInstanceType(
        self: *Checker,
        exported_class: ProgramExportedClass,
        class_name: hir_mod.StringId,
    ) CheckError!TypeId {
        var instance_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer instance_members.deinit(self.gpa);
        for (exported_class.members) |member| {
            const member_name = self.string_interner.intern(member.name) catch return error.OutOfMemory;
            const member_t = try self.programExportedClassMemberType(member.type_name);
            try instance_members.append(self.gpa, .{
                .name = member_name,
                .type = member_t,
                .is_optional = false,
                .is_readonly = false,
                .is_method = member.is_method,
            });
        }
        const instance_t = self.interner.internObjectType(instance_members.items) catch return error.OutOfMemory;
        try self.registerAliasDisplayText(instance_t, self.string_interner.get(class_name));
        return instance_t;
    }

    fn programExportedClassMemberType(self: *Checker, type_name: []const u8) CheckError!TypeId {
        if (std.mem.eql(u8, type_name, "string")) return types.Primitive.string_t;
        if (std.mem.eql(u8, type_name, "number")) return types.Primitive.number_t;
        if (std.mem.eql(u8, type_name, "boolean")) return types.Primitive.boolean_t;
        if (std.mem.eql(u8, type_name, "void")) return types.Primitive.void_t;
        if (std.mem.eql(u8, type_name, "undefined")) return types.Primitive.undefined_t;
        if (std.mem.eql(u8, type_name, "null")) return types.Primitive.null_t;
        if (type_name.len > 0) {
            const name = self.string_interner.intern(type_name) catch return error.OutOfMemory;
            if (self.class_instance_types.get(name)) |instance_t| return instance_t;
            if (self.type_names.get(name)) |type_t| return type_t;
        }
        return types.Primitive.any;
    }

    fn checkIsolatedDeclarationsImportRequiredByAugmentation(
        self: *Checker,
        import_node: NodeId,
        imp: hir_mod.ImportPayload,
        spec: []const u8,
    ) CheckError!void {
        if (!self.strict_flags.isolated_declarations or !self.strict_flags.declaration) return;
        if (self.module_interface_augmentations.len == 0) return;
        if (self.importer_path.len == 0) return;
        if (!std.mem.startsWith(u8, spec, ".")) return;
        if (!self.importDeclHasImportClause(import_node, imp, spec)) return;

        for (self.module_interface_augmentations) |augmentation| {
            const target_decl_path = augmentation.target_decl_path orelse continue;
            if (!std.mem.eql(u8, target_decl_path, self.importer_path)) continue;
            if (std.mem.eql(u8, augmentation.source_path, self.importer_path)) continue;
            if (!try self.programImportTargetsPath(import_node, spec, augmentation.source_path)) continue;
            try self.report(
                import_node,
                TsCodes.isolated_declarations_preserve_import_for_augmentation,
                "Declaration emit for this file requires preserving this import for augmentations. This is not supported with --isolatedDeclarations.",
            );
            return;
        }
    }

    fn importDeclHasImportClause(self: *Checker, import_node: NodeId, imp: hir_mod.ImportPayload, spec: []const u8) bool {
        if (imp.default_binding != hir_mod.none_node_id or
            imp.namespace_binding != hir_mod.none_node_id or
            imp.named_len > 0 or
            imp.import_equals != hir_mod.none_node_id)
        {
            return true;
        }
        const src = self.source orelse return false;
        const quote_pos = self.moduleSpecifierQuotePos(import_node, spec) orelse return false;
        const span = self.hir.spanOf(import_node);
        if (quote_pos <= span.start or quote_pos > src.len) return false;
        return std.mem.indexOf(u8, src[span.start..quote_pos], "from") != null;
    }

    fn programImportTargetsPath(self: *Checker, import_node: NodeId, spec: []const u8, target_path: []const u8) CheckError!bool {
        if (self.external_resolver) |resolver| {
            const containing = if (self.importer_path.len > 0)
                self.importer_path
            else
                self.virtualSectionFilenameForNode(import_node) orelse "/__root__.ts";
            if (resolver.resolve(spec, containing)) |resolved| {
                if (programModulePathMatches(resolved.path, target_path)) return true;
            }
        }
        if (self.importer_path.len == 0) return false;
        const dir = std.fs.path.dirname(self.importer_path) orelse "";
        const resolved = std.fs.path.resolve(self.gpa, &[_][]const u8{ dir, spec }) catch return false;
        defer self.gpa.free(resolved);
        return programModulePathMatches(resolved, target_path);
    }

    fn programModulePathMatches(candidate: []const u8, target_path: []const u8) bool {
        if (std.mem.eql(u8, candidate, target_path)) return true;
        const candidate_base = stripProgramModuleExtension(candidate);
        const target_base = stripProgramModuleExtension(target_path);
        return std.mem.eql(u8, candidate_base, target_base);
    }

    fn stripProgramModuleExtension(path: []const u8) []const u8 {
        const exts = [_][]const u8{ ".d.mts", ".d.cts", ".d.ts", ".tsx", ".mts", ".cts", ".ts", ".jsx", ".mjs", ".cjs", ".js" };
        for (exts) |ext| {
            if (std.mem.endsWith(u8, path, ext)) return path[0 .. path.len - ext.len];
        }
        return path;
    }

    /// Type an expression. Returns its TypeId and also records it
    /// TS80008 — an integer numeric literal whose value is ≥ 2^53 can't
    /// be represented accurately. Skips fractional (`9e15.5`) and
    /// scientific (`2e54`) forms — matching tsc's `checkGrammarNumericLiteral`,
    /// which can't judge those exactly. Emitted as a suggestion.
    fn checkNumericLiteralPrecision(self: *Checker, node: NodeId) CheckError!void {
        const v = hir_mod.literalNumberOf(self.hir, node);
        if (v != @floor(v) or @abs(v) <= 9007199254740991) return; // <= MaxSafeInteger
        const src = self.source orelse return;
        const span = self.hir.spanOf(node);
        if (span.end > src.len or span.start >= span.end) return;
        const text = src[span.start..span.end];
        if (std.mem.indexOfScalar(u8, text, '.') != null) return; // fractional
        // Radix-prefixed literals (`0x`/`0b`/`0o`) are integers; only a
        // *decimal* literal's `e`/`E` marks scientific notation.
        const is_radix = text.len >= 2 and text[0] == '0' and switch (text[1]) {
            'x', 'X', 'b', 'B', 'o', 'O' => true,
            else => false,
        };
        if (!is_radix and (std.mem.indexOfScalar(u8, text, 'e') != null or
            std.mem.indexOfScalar(u8, text, 'E') != null)) return; // scientific
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.numeric_literal_too_large,
            .message = try self.diag_arena.allocator().dupe(u8, "Numeric literals with absolute values equal to 2^53 or greater are too large to be represented accurately as integers."),
            .category = .suggestion,
        });
    }

    /// Instantiate an implicit-constructor generic class when `new C()`
    /// omits type arguments. TypeScript uses defaults, then constraints,
    /// then `unknown` when constructor inference has no signature to inspect.
    fn instantiateGenericClassForNew(
        self: *Checker,
        class_name: hir_mod.StringId,
        type_arg_nodes: []const NodeId,
    ) CheckError!?TypeId {
        const info = self.generic_aliases.get(class_name) orelse return null;
        if (info.params.len == 0) return null;
        if (type_arg_nodes.len > 0 and type_arg_nodes.len != info.params.len) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Expected {d} type arguments, but got {d}.",
                .{ info.params.len, type_arg_nodes.len },
            );
            try self.reportOnce(type_arg_nodes[0], TsCodes.expected_n_type_arguments, msg);
        }

        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);

        if (type_arg_nodes.len > 0) {
            const count = @min(type_arg_nodes.len, info.params.len);
            for (0..count) |i| {
                const explicit = self.lowererLowerWithTypeParams(type_arg_nodes[i]) catch types.Primitive.unknown;
                try subs.put(self.gpa, info.params[i], explicit);
            }
        }

        return try self.instantiateGenericClassWithSubstitutions(class_name, info, &subs);
    }

    fn instantiateGenericClassConstructorSignatureForNew(
        self: *Checker,
        class_name: hir_mod.StringId,
        constructor_sig: TypeId,
        type_arg_nodes: []const NodeId,
    ) CheckError!TypeId {
        const info = self.generic_aliases.get(class_name) orelse return constructor_sig;
        if (info.params.len == 0 or type_arg_nodes.len == 0) return constructor_sig;

        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        const count = @min(type_arg_nodes.len, info.params.len);
        for (0..count) |i| {
            const explicit = self.lowererLowerWithTypeParams(type_arg_nodes[i]) catch types.Primitive.unknown;
            try subs.put(self.gpa, info.params[i], explicit);
            try self.checkTypeArgSatisfiesConstraint(type_arg_nodes[i], info.params[i], explicit);
        }
        if (subs.count() == 0) return constructor_sig;
        return self.substituteType(constructor_sig, &subs) catch constructor_sig;
    }

    fn instantiateGenericClassFromConstructorArgs(
        self: *Checker,
        class_name: hir_mod.StringId,
        constructor_sig: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) CheckError!?TypeId {
        const info = self.generic_aliases.get(class_name) orelse return null;
        if (info.params.len == 0) return null;

        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        try self.inferCallSubstitutions(constructor_sig, args, arg_types, &subs);
        var inferred_params: std.ArrayListUnmanaged(TypeId) = .empty;
        defer inferred_params.deinit(self.gpa);
        var inferred_it = subs.keyIterator();
        while (inferred_it.next()) |param| try inferred_params.append(self.gpa, param.*);
        try self.extendSubstitutionsByMatchingTypeParamNames(info.body, inferred_params.items, &subs);
        try self.normalizeGenericClassInferenceSubstitutions(info, &subs);
        return try self.instantiateGenericClassWithSubstitutions(class_name, info, &subs);
    }

    fn instantiateGenericClassConstructorSignatureFromArgs(
        self: *Checker,
        class_name: hir_mod.StringId,
        constructor_sig: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) CheckError!TypeId {
        const info = self.generic_aliases.get(class_name) orelse return constructor_sig;
        if (info.params.len == 0) return constructor_sig;

        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        try self.inferCallSubstitutions(constructor_sig, args, arg_types, &subs);
        try self.normalizeGenericClassInferenceSubstitutions(info, &subs);
        if (subs.count() == 0) return constructor_sig;
        return self.substituteType(constructor_sig, &subs) catch constructor_sig;
    }

    fn normalizeGenericClassInferenceSubstitutions(
        self: *Checker,
        info: GenericAliasInfo,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        for (info.params) |param| {
            const candidate = subs.get(param) orelse continue;
            const raw_constraint = self.typeParameterConstraint(param) orelse continue;
            if (raw_constraint == types.Primitive.unknown or raw_constraint == types.Primitive.any) continue;
            const constraint = self.substituteType(raw_constraint, subs) catch raw_constraint;
            if (self.engine.isAssignableTo(candidate, constraint) catch false) continue;
            try subs.put(self.gpa, param, constraint);
        }
    }

    fn instantiateGenericClassWithSubstitutions(
        self: *Checker,
        class_name: hir_mod.StringId,
        info: GenericAliasInfo,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!TypeId {
        var display_args: std.ArrayListUnmanaged(TypeId) = .empty;
        defer display_args.deinit(self.gpa);

        for (info.params) |param| {
            var replacement = subs.get(param);
            if (replacement == null and param < self.interner.pool.typeCount() and self.interner.pool.flagsOf(param).is_type_parameter) {
                const payload = self.interner.pool.type_parameter_payloads.items[self.interner.pool.payloadOf(param)];
                const fallback = if (payload.default != types.Primitive.none)
                    payload.default
                else
                    self.typeParameterConstraint(param) orelse types.Primitive.unknown;
                replacement = self.substituteType(fallback, subs) catch fallback;
                try subs.put(self.gpa, param, replacement.?);
            }
            try display_args.append(self.gpa, replacement orelse types.Primitive.unknown);
        }

        const instantiated = self.substituteType(info.body, subs) catch info.body;
        if (instantiated != info.body) {
            self.registerAliasDisplayNameInner(instantiated, class_name, display_args.items, true) catch {};
        }
        return instantiated;
    }

    /// in the HIR's types column.
    pub fn checkExpression(self: *Checker, node: NodeId) CheckError!TypeId {
        // tsc starts a fresh instantiation-work budget for each expression.
        // Depth remains independent, so recursive type expansion still trips
        // the TS2589 depth guard while unrelated expressions cannot exhaust
        // one another's count budget.
        self.instantiation_count = 0;
        // The native stack overflows around ~290 nested `checkExpression`
        // frames (this function has a very large frame; deeply-nested call
        // chains `f()()()…`, cast chains `(x as T)…`, and object-literal
        // values all hit it). The previous 1000 ceiling never tripped before
        // the crash, so lower it well below the empirical overflow point with
        // margin. Past the limit we degrade to `any` (tsc-style graceful
        // degradation) rather than crashing the whole compilation.
        // Lowered from 200: a left-nested binary chain (`a+b+c+…`) pushes TWO
        // large frames per level (checkExpression + checkBinop), so the native
        // stack overflows near expression_depth ~190 — *below* the old 200
        // ceiling, so the guard never fired and binderBinaryExpressionStress
        // segfaulted. 150 fires with margin; graceful `any` beats a crash.
        const max_expression_depth: u32 = 150;
        self.expression_depth += 1;
        defer self.expression_depth -= 1;
        if (self.expression_depth > max_expression_depth) return types.Primitive.any;
        const t: TypeId = switch (self.hir.kindOf(node)) {
            .literal_string => types.Primitive.string_t,
            .template_literal => try self.checkTemplateLiteralExpression(node),
            .literal_number => blk: {
                try self.checkNumericLiteralPrecision(node);
                break :blk types.Primitive.number_t;
            },
            .literal_bigint => types.Primitive.bigint_t,
            .literal_bool => types.Primitive.boolean_t,
            .literal_null => types.Primitive.null_t,
            .literal_undefined => types.Primitive.undefined_t,
            .literal_regex => blk_regex: {
                try self.checkRegexFlagsForTarget(node);
                try self.checkRegexNamedGroupsForTarget(node);
                break :blk_regex self.lowerBuiltinObjectType("RegExp") orelse types.Primitive.object_t;
            },
            .identifier => self.typeOfIdentifier(node),
            .this_expr => try self.checkThisExpression(node),
            .spread => blk: {
                const sp = hir_mod.spreadOf(self.hir, node);
                break :blk try self.checkExpression(sp.expression);
            },
            .binary_op => try self.checkBinop(node),
            .unary_op => try self.checkUnary(node),
            .logical_op => try self.checkLogical(node),
            .conditional => try self.checkConditional(node),
            .assignment => blk: {
                const a = hir_mod.assignmentOf(self.hir, node);
                const target_kind = self.hir.kindOf(a.target);
                const is_synth_update = self.assignmentIsSynthesizedUpdate(node, a);
                if (target_kind == .member_access and self.strict_flags.strict_null_checks) {
                    const target_member = hir_mod.memberOf(self.hir, a.target);
                    if (self.thisIsUndefinedInExternalModuleArrow(target_member.object) and
                        !self.diagnosticExists(target_member.object, TsCodes.object_possibly_undefined))
                    {
                        try self.report(target_member.object, TsCodes.object_possibly_undefined, "Object is possibly 'undefined'.");
                    }
                }
                if (a.op == null and target_kind == .element_access) {
                    try self.reportCommonJsDynamicExportElementAccessIfNeeded(a.target);
                }
                const target_is_eval = target_kind == .identifier and
                    std.mem.eql(u8, self.string_interner.get(hir_mod.identifierOf(self.hir, a.target).name), "eval");
                var target_t = if (target_is_eval)
                    types.Primitive.any
                else if (target_kind == .identifier)
                    self.typeOfIdentifierDeclared(a.target)
                else if (target_kind == .array_literal or target_kind == .object_literal)
                    types.Primitive.none
                else blk_target: {
                    const prev_update_target = self.checking_update_assignment_target;
                    const prev_element_write_target = self.checking_element_write_target;
                    self.checking_update_assignment_target = is_synth_update;
                    self.checking_element_write_target = target_kind == .element_access;
                    defer self.checking_update_assignment_target = prev_update_target;
                    defer self.checking_element_write_target = prev_element_write_target;
                    break :blk_target try self.checkExpression(a.target);
                };
                if (a.op == null and target_kind == .member_access and
                    self.memberAccessIsImportMeta(a.target))
                {
                    try self.report(
                        a.target,
                        TsCodes.assignment_lhs_not_variable,
                        "The left-hand side of an assignment expression must be a variable or a property access.",
                    );
                }
                if (target_kind == .identifier) {
                    if (self.visibleActiveAnnotatedIdentifierType(a.target)) |annotated_t| {
                        target_t = annotated_t;
                    } else if (self.visibleAnnotatedIdentifierType(a.target)) |annotated_t| {
                        target_t = annotated_t;
                    }
                }
                // For synth-update expressions (`x++` / `x--` desugared to
                // `x += 1` / `x -= 1`) the arithmetic-operand check
                // downstream uses `target_t` to validate that the operand
                // is number/bigint/enum/any. The declared type alone
                // doesn't reflect narrowing ÃÂ¢ÃÂÃÂ `if (typeof x === "number")
                // { x++; }` declares `x: number | string` but the narrow
                // scope says `number`. Consult the narrow so guarded
                // arithmetic updates type-check. Mirrors tsc.
                if (is_synth_update and target_kind == .identifier) {
                    const id = hir_mod.identifierOf(self.hir, a.target);
                    if (self.lookupNarrow(id.name)) |narrowed_t| {
                        target_t = narrowed_t;
                    }
                }
                if (a.op == null and target_kind == .identifier and self.sourceHasCheckJsDirective()) {
                    if (try self.jsDocTypeForPreviousIdentifierDecl(a.target)) |declared_t| {
                        target_t = declared_t;
                    }
                }
                // `.js` files with `// @ts-check` may annotate
                // `Ctor.prototype = expr` with a leading
                // `/** @type {T} */`, in which case T becomes the
                // declared type of the prototype slot ÃÂ¢ÃÂÃÂ assigning a
                // non-T value should report TS2322. The member-access
                // checker normally returns an open object shape for
                // `Ctor.prototype`, which would accept anything, so
                // we override the assignment target type here.
                // Mirrors upstream tsc for `typeTagPrototypeAssignment`.
                var target_has_explicit_jsdoc_prototype_type = false;
                var target_has_explicit_jsdoc_module_exports_type = false;
                if (a.op == null and target_kind == .member_access and
                    self.sourceHasCheckJsDirective())
                {
                    if (try self.jsDocTypeForPrototypeAssignmentTarget(node, a.target)) |overridden_t| {
                        target_t = overridden_t;
                        target_has_explicit_jsdoc_prototype_type = true;
                    } else if (self.memberAccessIsModuleExports(a.target)) {
                        const parent = self.hir.parentOf(node);
                        const anchor = if (parent != hir_mod.none_node_id and
                            self.hir.kindOf(parent) == .expression_stmt)
                            parent
                        else
                            node;
                        if (try self.jsDocTypeForLeadingNode(anchor)) |overridden_t| {
                            target_t = overridden_t;
                            target_has_explicit_jsdoc_module_exports_type = true;
                        }
                    }
                    if (self.commonJsModuleExportsPropertyName(a.target)) |prop_name| {
                        if (self.lookupCommonJsExportNarrow(try self.commonJsModuleExportsDirectKey())) |exports_t| {
                            if (!self.typeCanReceiveCommonJsExportProperty(exports_t) and
                                (try self.lookupObjectMember(exports_t, prop_name)) == null)
                            {
                                try self.reportPropertyDoesNotExistOnType(a.target, prop_name, exports_t);
                            }
                        }
                    }
                }
                if (a.op == null and target_kind == .member_access) {
                    const target_member = hir_mod.memberOf(self.hir, a.target);
                    if (self.sourceHasCheckJsDirective() and self.nodeIsThisReference(target_member.object)) {
                        if (self.checkJsPrototypeAssignmentThisType(target_member.object)) |this_t| {
                            if (try self.lookupObjectMember(this_t, target_member.name)) |member_t| {
                                target_t = member_t;
                            }
                        }
                    }
                    if (try self.moduleInterfaceAugmentationPrototypeMember(target_member.object, target_member.name, node)) |augmented_t| {
                        target_t = augmented_t;
                    }
                    if (self.sourceHasCheckJsDirective()) {
                        if (try self.priorPrototypeObjectAssignmentType(node, a.target)) |prototype_t| {
                            if (try self.lookupObjectMember(prototype_t, target_member.name)) |member_t| {
                                target_t = member_t;
                            } else {
                                try self.reportPropertyDoesNotExistOnType(a.target, target_member.name, prototype_t);
                                target_t = types.Primitive.any;
                            }
                        }
                    }
                    if (try self.classAccessorSetterAssignmentType(a.target)) |setter_t| {
                        target_t = setter_t;
                    }
                }
                // Reassignment clears any prior conditional alias for
                // the variable: `let cond = isString(x); cond = false;
                // if (cond) ...` ÃÂ¢ÃÂÃÂ the second branch shouldn't
                // narrow `x` because `cond` is no longer the original
                // guard expression.
                var assignment_target_diag_fired = false;
                if (a.op == null and target_kind == .member_access) {
                    assignment_target_diag_fired = try self.reportGenericConstraintIndexMemberWrite(a.target);
                }
                if (self.hir.kindOf(a.target) == .identifier) {
                    const id = hir_mod.identifierOf(self.hir, a.target);
                    _ = self.cond_aliases.remove(id.name);
                    _ = self.disc_aliases.remove(id.name);
                    try self.removeCondAliasesReferencing(id.name);
                    if (target_is_eval) {
                        try self.report(a.target, TsCodes.cannot_assign_to_function, "Cannot assign to 'eval' because it is a function.");
                    }
                    if (std.mem.eql(u8, self.string_interner.get(id.name), "undefined")) {
                        try self.report(a.target, TsCodes.cannot_assign_undefined, "Cannot assign to 'undefined' because it is not a variable.");
                    }
                    // TS2588: `const x = 1; x = 2;` ÃÂ¢ÃÂÃÂ assigning to
                    // a const-bound identifier is a hard error.
                    if (self.identifierResolvesToConst(a.target)) {
                        const name_str = self.string_interner.get(id.name);
                        const msg = try std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "Cannot assign to '{s}' because it is a constant.",
                            .{name_str},
                        );
                        try self.diagnostics.append(self.gpa, .{
                            .node = node,
                            .code = TsCodes.cannot_assign_const,
                            .message = msg,
                        });
                    }
                    // TS2628/TS2629/TS2631: enum/class/namespace names
                    // are value declarations but cannot be assignment
                    // targets. For `++E` / `C++`, tsc reports this
                    // target diagnostic instead of the arithmetic
                    // operand diagnostic.
                    if (a.op == null or is_synth_update) {
                        assignment_target_diag_fired = try self.reportIdentifierAssignmentTargetKind(a.target);
                    }
                }
                if (target_kind == .literal_undefined or self.nodeSourceTextIs(a.target, "undefined") or
                    (is_synth_update and self.typeIsExactUndefined(target_t)))
                {
                    try self.report(a.target, TsCodes.cannot_assign_undefined, "Cannot assign to 'undefined' because it is not a variable.");
                    assignment_target_diag_fired = true;
                }
                if (is_synth_update and self.updateOperandRequiresVariableDiagnostic(a.target, target_t)) {
                    try self.reportUpdateOperandRequiresVariable(a.target);
                }
                if (self.expressionIsOptionalChain(a.target)) {
                    // Distinguish synthetic update expressions
                    // (`++obj?.a` / `obj?.a++`, which the parser
                    // desugars to `obj?.a -= 1` / `+= 1`) from real
                    // assignments. tsc emits TS2777 for the former
                    // and TS2779 for the latter ÃÂ¢ÃÂÃÂ see
                    // `propertyAccessChain.3.ts` / `elementAccessChain.3.ts`.
                    if (self.assignmentIsSynthesizedUpdate(node, a)) {
                        try self.report(a.target, TsCodes.optional_chain_increment_target, "The operand of an increment or decrement operator may not be an optional property access.");
                    } else {
                        try self.report(a.target, TsCodes.optional_chain_assignment_target, "The left-hand side of an assignment expression may not be an optional property access.");
                    }
                }
                // TS2540: assigning to a property declared `readonly`.
                // Object/interface readonly fields are immutable;
                // class-field readonly is approximated by the
                // constructor exception inside the helper. When the
                // readonly check fires, suppress the assignment-value
                // TS2322 below ÃÂ¢ÃÂÃÂ tsc reports only the readonly error
                // (see `intersectionTypeReadonly.errors.txt(23,15)`,
                // where the intersection `Base & DifferentType`
                // reduces `value` to `never` but tsc still prints
                // just TS2540, not an additional TS2322).
                //
                // Enum-member assignment fires through a sibling helper
                // first (`E.A = null` mirrors `validNullAssignments.ts(10,3)`)
                // ÃÂ¢ÃÂÃÂ when it emits, we also flip the flag so the
                // cascading TS2322 stays suppressed.
                var readonly_target_fired = try self.checkEnumMemberAssignment(a.target);
                if (self.hir.kindOf(a.target) == .member_access) {
                    readonly_target_fired = (try self.checkReadonlyAssignment(a.target)) or readonly_target_fired;
                    // tsc also emits TS2542 for `C.bar = ...` when the
                    // class has a readonly index signature and no
                    // concrete static member named `bar`. Mirrors
                    // `staticIndexSignature2.ts(7,1)`.
                    if (!readonly_target_fired) {
                        try self.checkReadonlyIndexAssignment(a.target);
                    }
                }
                if (self.hir.kindOf(a.target) == .element_access) {
                    readonly_target_fired = (try self.checkReadonlyElementAssignment(a.target)) or readonly_target_fired;
                    if (!readonly_target_fired) {
                        try self.checkReadonlyIndexAssignment(a.target);
                    }
                }
                if (target_kind == .member_access) {
                    _ = try self.reportCheckJsPrototypeThisMissingMemberAssignment(a.target);
                }
                const value_diag_start = self.diagnostics.items.len;
                var contextual_element_value_t: TypeId = types.Primitive.none;
                if (a.op == null and
                    target_kind == .element_access and
                    self.isContextualFunctionExpressionLike(a.value))
                {
                    if (self.contextualElementAssignmentSignature(target_t)) |target_sig| {
                        try self.checkFunctionWithContextualSignatureMode(a.value, target_sig, false, &contextual_element_value_t);
                    }
                }
                var value_t = if (contextual_element_value_t != types.Primitive.none)
                    contextual_element_value_t
                else if (a.op == .logical_and and target_kind == .identifier) logical_rhs: {
                    const target_id = hir_mod.identifierOf(self.hir, a.target);
                    const current = self.lookupNarrow(target_id.name) orelse target_t;
                    const truthy = try self.logicalOrTruthyType(current);
                    try self.pushNarrowScope();
                    defer self.popNarrowScope();
                    if (truthy != types.Primitive.never) try self.recordNarrow(target_id.name, truthy);
                    break :logical_rhs try self.checkExpression(a.value);
                } else try self.checkExpression(a.value);
                if (a.op == null) {
                    try self.checkJsImportedPrototypeFunctionThisAssignments(a.target, a.value);
                }
                const assignment_value_jsdoc_t = if (self.hir.kindOf(a.value) == .identifier)
                    try self.jsDocTypeForPreviousIdentifierDecl(a.value)
                else
                    null;
                var assignment_check_value_t = if (self.hir.kindOf(a.value) == .identifier) blk_assign_value: {
                    if (assignment_value_jsdoc_t) |declared_t| break :blk_assign_value declared_t;
                    const value_id = hir_mod.identifierOf(self.hir, a.value);
                    if (self.lookupNarrow(value_id.name) != null and !self.identifierAnnotationIsNonNullable(a.target)) break :blk_assign_value value_t;
                    break :blk_assign_value self.typeOfIdentifierDeclared(a.value);
                } else value_t;
                if (a.op == null and target_kind == .element_access) {
                    assignment_check_value_t = try self.expressionLiteralType(a.value, assignment_check_value_t);
                }
                const exact_optional_assignment_fired = a.op == null and
                    try self.tryReportExactOptionalPropertyAssignment(a.target, a.value, assignment_check_value_t);
                const nullish_function_assignment_diag_fired = a.op == null and
