                                    break :blk try self.optionalChainResult(types.Primitive.any, call_is_optional_chain);
                                }
                            }
                            if (visible_len == 1 and self.callArityFitsSignature(node, overloads[0], args)) {
                                const effective_sig = if (overload_type_arg_nodes.len > 0) blk_eff: {
                                    var used_explicit_type_args = false;
                                    break :blk_eff try self.instantiateSignatureWithExplicitTypeArgs(node, overloads[0], overload_type_arg_nodes, &used_explicit_type_args);
                                } else try self.instantiateSignatureFromArgs(overloads[0], args, arg_types.items);
                                const diag_start = self.diagnostics.items.len;
                                try self.checkArgsAgainstSignature(node, args, arg_types.items, effective_sig);
                                if (has_impl) {
                                    try self.attachOverloadImplementationSuccessRelated(
                                        node,
                                        overload_list.items[visible_len],
                                        args,
                                        arg_types.items,
                                        diag_start,
                                    );
                                }
                                if (self.interner.signatureReturn(effective_sig)) |ret| break :blk try self.optionalChainResult(ret, call_is_optional_chain);
                                break :blk try self.optionalChainResult(types.Primitive.any, call_is_optional_chain);
                            }
                            var selected_applicable: TypeId = types.Primitive.none;
                            for (overloads) |sig| {
                                if (overload_type_arg_nodes.len > 0 and overload_type_arg_count_matches and
                                    !self.signatureTypeArgCountMatches(sig, overload_type_arg_nodes.len)) continue;
                                const effective_sig = if (overload_type_arg_nodes.len > 0) blk_eff: {
                                    var used_explicit_type_args = false;
                                    break :blk_eff try self.instantiateSignatureWithExplicitTypeArgs(node, sig, overload_type_arg_nodes, &used_explicit_type_args);
                                } else try self.instantiateSignatureFromArgs(sig, args, arg_types.items);
                                const prefers_rest_for_array_spread =
                                    self.callHasNonTupleSpread(args, arg_types.items) and
                                    self.rest_signatures.contains(effective_sig) and
                                    (selected_applicable == types.Primitive.none or
                                        !self.rest_signatures.contains(selected_applicable));
                                if (try self.signatureAccepts(node, effective_sig, args, arg_types.items) and
                                    (selected_applicable == types.Primitive.none or
                                        prefers_rest_for_array_spread or
                                        self.signatureHasMoreExactAnyMatches(effective_sig, selected_applicable, args, arg_types.items)))
                                {
                                    selected_applicable = effective_sig;
                                }
                            }
                            if (selected_applicable != types.Primitive.none) {
                                try self.checkArgsAgainstSignature(node, args, arg_types.items, selected_applicable);
                                if (self.interner.signatureReturn(selected_applicable)) |ret| break :blk try self.optionalChainResult(ret, call_is_optional_chain);
                            }
                            // No overload accepted these args. When the
                            // failure is purely arity-based (the call's
                            // argument count falls between two overload
                            // arities but matches none), emit TS2575 with
                            // the neighbouring arities; otherwise fall back
                            // to the generic TS2769.
                            if (self.overloadArityError(node, overloads, args)) |ar| {
                                const msg = try std.fmt.allocPrint(
                                    self.diag_arena.allocator(),
                                    "No overload expects {d} arguments, but overloads do exist that expect either {d} or {d} arguments.",
                                    .{ ar.arg_count, ar.max_below, ar.min_above },
                                );
                                try self.diagnostics.append(self.gpa, .{
                                    .node = node,
                                    .pos = self.tooFewArgsAnchorPos(node),
                                    .code = TsCodes.no_overload_expects_n_args_but_others_exist,
                                    .message = msg,
                                });
                            } else {
                                const diag_start = self.diagnostics.items.len;
                                try self.reportNoOverloadMatchesWithOverloads(node, args, arg_types.items, overloads);
                                if (has_impl) {
                                    try self.attachOverloadImplementationSuccessRelated(
                                        node,
                                        overload_list.items[visible_len],
                                        args,
                                        arg_types.items,
                                        diag_start,
                                    );
                                }
                            }
                            if (self.interner.signatureReturn(overload_list.items[0])) |ret| break :blk try self.optionalChainResult(ret, call_is_optional_chain);
                            break :blk try self.optionalChainResult(types.Primitive.any, call_is_optional_chain);
                        }
                    }
                }
                // Explicit type arguments (`f<T>(args)`): if the
                // callee resolves to a generic fn we recorded, lower
                // each explicit arg, build a substitution, and
                // substitute against the signature. Substituted
                // signature drives both arg-checking (so TS2345
                // fires against the explicit-instantiated parameter
                // types) and the return type.
                var effective_callee_t = callee_t;
                var recovered_declared_signature = false;
                if (type_arg_nodes.len > 0) {
                    if (self.localFunctionValueSignatureForCall(c.callee)) |sig| {
                        effective_callee_t = sig;
                        recovered_declared_signature = true;
                    }
                }
                const call_member_id = self.string_interner.intern("__call") catch return error.OutOfMemory;
                if (!self.interner.isSignature(effective_callee_t)) {
                    if (self.interner.objectMember(effective_callee_t, call_member_id)) |call_member_t| {
                        effective_callee_t = call_member_t;
                    }
                }
                if (self.hir.kindOf(c.callee) == .member_access) {
                    const m = hir_mod.memberOf(self.hir, c.callee);
                    const receiver_t = if (try self.staticClassMemberAccess(m.object, m.name)) |static_access|
                        static_access.receiver_t
