                        const prev_type_arg_constraint_subs = self.current_type_arg_constraint_subs;
                        self.current_type_arg_constraint_subs = &subs;
                        defer self.current_type_arg_constraint_subs = prev_type_arg_constraint_subs;
                        const n = @min(type_params.len, type_arg_nodes.len);
                        for (0..n) |i| {
                            const explicit_t = self.lowererLowerWithTypeParams(type_arg_nodes[i]) catch types.Primitive.unknown;
                            try subs.put(self.gpa, type_params[i], explicit_t);
                            try self.checkTypeArgSatisfiesConstraint(type_arg_nodes[i], type_params[i], explicit_t);
                        }
                        if (subs.count() > 0) {
                            effective_callee_t = self.substituteType(callee_t, &subs) catch callee_t;
                            used_explicit_type_args = true;
                        }
                    }
                }
                if (type_arg_nodes.len > 0 and !callee_had_generic_record and self.interner.isSignature(effective_callee_t)) {
                    if (self.generic_signature_params.get(effective_callee_t)) |type_params| {
                        callee_had_generic_record = true;
                        if (type_arg_nodes.len != type_params.len) {
                            const msg = try std.fmt.allocPrint(
                                self.diag_arena.allocator(),
                                "Expected {d} type arguments, but got {d}.",
                                .{ type_params.len, type_arg_nodes.len },
                            );
                            try self.diagnostics.append(self.gpa, .{
                                .node = type_arg_nodes[0],
                                .code = TsCodes.expected_n_type_arguments,
                                .message = msg,
                            });
                        }
                        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                        defer subs.deinit(self.gpa);
                        const prev_type_arg_constraint_subs = self.current_type_arg_constraint_subs;
                        self.current_type_arg_constraint_subs = &subs;
                        defer self.current_type_arg_constraint_subs = prev_type_arg_constraint_subs;
                        const n = @min(type_params.len, type_arg_nodes.len);
                        for (0..n) |i| {
                            const explicit_t = self.lowererLowerWithTypeParams(type_arg_nodes[i]) catch types.Primitive.unknown;
                            try subs.put(self.gpa, type_params[i], explicit_t);
                            try self.checkTypeArgSatisfiesConstraint(type_arg_nodes[i], type_params[i], explicit_t);
                        }
                        if (subs.count() > 0) {
                            effective_callee_t = self.substituteType(effective_callee_t, &subs) catch effective_callee_t;
                            used_explicit_type_args = true;
                        }
                    }
                }
                // Recursive call within the function's own body, or
                // forward reference to a generic function whose signature
                // hasn't yet been resolved on this scope (callee_t is
                // `any`/`unknown`). The pre-pass registered the function's
                // type parameters in `generic_fns`; treat that as proof
                // that the callee accepts type arguments and skip the
                // TS2347 fallback below. Mirrors fixtures
                // `typeParameterAsTypeArgument` where the recursive
                // `foo<U, U>(...)` inside `function foo<T, U>` would
                // otherwise wrongly flag.
                if (type_arg_nodes.len > 0 and !callee_had_generic_record and
                    (callee_t == types.Primitive.any or callee_t == types.Primitive.unknown) and
                    self.hir.kindOf(c.callee) == .identifier)
                {
                    const callee_name = hir_mod.identifierOf(self.hir, c.callee).name;
                    if (self.generic_fns.get(callee_name)) |_| {
                        callee_had_generic_record = true;
                    }
                }
                if (type_arg_nodes.len > 0 and !callee_had_generic_record) {
                    if (effective_callee_t == types.Primitive.any or effective_callee_t == types.Primitive.unknown) {
                        if (!self.callCalleeAlreadyHasUnresolvedNameDiagnostic(c.callee) and
                            !self.callCalleeAlreadyHasMissingPropertyDiagnostic(c.callee))
