                    } else if (self.interner.isSignature(effective_callee_t)) {
                        var signature_is_generic = self.containsFreeTypeParameter(effective_callee_t);
                        if (signature_is_generic and self.hir.kindOf(c.callee) == .member_access) {
                            // Free type parameters that all belong to the
                            // receiver's generic class don't make the method
                            // itself generic: `(new C2()).f<number>(…)` on
                            // `class C2<T, U> { f(x: T, y: U): T }` still
                            // reports 'Expected 0 type arguments' in tsc
                            // (callGenericFunctionWithIncorrectNumberOfTypeArguments).
