                            const m_callee = hir_mod.memberOf(self.hir, c.callee);
                            const recv_t = self.hir.typeOf(m_callee.object);
                            if (self.class_name_by_instance.get(recv_t)) |recv_class| {
                                if (self.generic_aliases.get(recv_class)) |ga| {
                                    var class_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                                    defer class_subs.deinit(self.gpa);
                                    for (ga.params) |p| try class_subs.put(self.gpa, p, types.Primitive.unknown);
