                            const n = @min(param_ts.len, arg_types.items.len);
                            // TypeScript gathers candidates from ordinary
                            // arguments before context-sensitive callbacks.
                            // A callback may therefore be checked using a
                            // type fixed by a later scalar argument.
                            for (0..2) |phase| {
                                for (0..n) |i| {
                                    const is_contextual_callback = self.functionExpressionHasContextSensitiveParameters(args[i]);
                                    if ((phase == 0) == is_contextual_callback) continue;
                                    const param_t = param_ts[i];
                                    if (param_t >= self.interner.pool.typeCount()) continue;
                                    if (self.interner.pool.flagsOf(param_t).is_signature) {
                                        const param_pred = self.signature_param_predicates.get(.{
                                            .signature = effective_callee_t,
                                            .param_index = @intCast(i),
                                        });
                                        try self.inferFromPartiallyAnnotatedFunctionArgument(param_t, args[i], &call_subs);
                                        if (!try self.inferFromPredicateSignatureArgument(param_t, param_pred, args[i], arg_types.items[i], &call_subs)) {
                                            if (self.signatureHasBareGenericRestParam(param_t)) {
                                                try self.inferFromArgument(param_t, arg_types.items[i], args[i], &call_subs);
                                            } else if (arg_types.items[i] < self.interner.pool.typeCount() and
                                                self.interner.pool.flagsOf(arg_types.items[i]).is_signature)
                                            {
                                                const inference_arg_t = try self.genericInferenceFunctionArgumentType(args[i], arg_types.items[i]);
                                                try self.inferFromPair(param_t, inference_arg_t, &call_subs);
                                            } else if (self.signatureIsConstruct(param_t)) {
                                                _ = try self.inferFromConstructSignatureArgument(param_t, arg_types.items[i], &call_subs);
                                            } else {
                                                _ = try self.inferFromOverloadedCallableArgument(param_t, arg_types.items[i], &call_subs);
