                        defer subs.deinit(self.gpa);
                        try self.inferFromPair(target, attrs_t, &subs);
                        if (subs.count() > 0) {
                            effective_target = self.substituteType(target, &subs) catch target;
                        }
                    }
                    const required_props_ok = try self.jsxRequiredPropsAssignable(effective_target, attrs_t);
                    if (attr_members.items.len == 0 and required_props_ok) {
                        // A JSX element expression evaluates to
                        // `JSX.Element` in tsc regardless of how the
                        // attributes check resolved — falling through
                        // to the synthetic-Element tail keeps nested
                        // children (`<Tag><div /></Tag>`) typed as
                        // `Element` in the synthesized children member
                        // (`checkJsxChildrenProperty15` k4/k5).
                        if (try self.jsxLibElementSyntheticType()) |t| return t;
                        return types.Primitive.any;
                    }
                    const has_generic_spread = generic_spread_types.items.len > 0;
                    const explicit_attrs_t = try self.jsxExplicitAttributesBagType(explicit_attrs.items);
                    const attrs_match_overload = try self.jsxAttributesMatchOverload(
                        el.tag,
                        attrs_t,
                        has_spread_attr,
                        has_generic_spread,
                        explicit_attrs_t,
                    );
                    const interface_overloads = try self.jsxTagInterfaceOverloads(el.tag);
                    const attrs_match_sigs = if (interface_overloads) |sigs|
                        try self.jsxAttributesMatchSignatures(
                            el.tag,
                            sigs,
                            attrs_t,
                            has_spread_attr,
                            has_generic_spread,
                            explicit_attrs_t,
                        )
                    else
                        false;
                    // Overload applicability above accounts for every
                    // spread's non-fresh bag. The fallback single-target
                    // path still excess-checks explicit attributes added
                    // alongside a concrete spread; only a generic spread
                    // makes the whole synthesized target indeterminate.
                    const attrs_have_no_excess = has_generic_spread or
                        try self.jsxAttrsHaveNoExcessMembersForTarget(el.tag, attrs_t, effective_target);
                    const attrs_values_assignable = try self.jsxAttributeBagValuesAssignable(attrs_t, effective_target);
                    if (self.jsxTagHasVisibleOverloads(el.tag) and !attrs_match_overload) {
                        const report_anchor = if (overload_value_mismatch_anchor) |anchor|
                            anchor
                        else if (has_spread_attr and !has_generic_spread)
                            try self.jsxAttrsStructuralMismatchAnchor(el.tag, attrs, effective_target)
                        else
                            el.tag;
                        try self.report(
                            report_anchor,
                            TsCodes.no_overload_matches,
                            "No overload matches this call.",
                        );
                        return types.Primitive.any;
                    }
                    if (interface_overloads != null and !attrs_match_sigs) {
                        try self.report(
                            self.jsxNoOverloadAnchor(el.tag, overload_value_mismatch_anchor),
                            TsCodes.no_overload_matches,
                            "No overload matches this call.",
                        );
                        return types.Primitive.any;
                    }
                    // tsgo's `elaborateJsxComponents` replaces the
                    // bag-level relation error with the per-child
                    // elaborations whenever at least one child produced
                    // a diagnostic (`checkJsxChildrenProperty5`: the
                    // TS2740s at the children stand alone, no whole-bag
                    // TS2322 at the element).
                    // The JSX-specific passes above already validate every
                    // present attribute value (including index signatures),
                    // and these two predicates cover required and excess
                    // members. Do not let the generic object relater veto a
                    // clean bag merely because it cannot normalize a props
                    // intersection such as `Props & { children?: ReactNode }`.
                    if ((!attrs_have_no_excess or !required_props_ok or !attrs_values_assignable) and
                        !attrs_match_overload and
                        !attrs_match_sigs and
                        !child_relation_reported and
                        !(props_target_had_free and attrs_values_assignable and
                            try self.jsxRequiredPropsCovered(raw_props_t orelse target, attrs_t)))
                    {
                        // JSX class elements resolve through the
                        // class's construct signatures; a bag mismatch
                        // reports tsgo's `resolveCall` TS2769 only
                        // when more than one candidate exists
                        // (react16.d.ts's two-constructor `Component`
                        // in `checkJsxChildrenCanBeTupleType`). A
                        // single candidate — e.g. a fixture-local
                        // `class Component<T, U> {}` — falls through to
                        // the plain single-signature bag errors below
                        // (`tsxSpreadAttributesResolution2`).
                        if (tag_is_class_component and self.jsxTagClassConstructSignatureCount(el.tag) >= 2) {
                            try self.report(
                                self.jsxNoOverloadAnchor(el.tag, overload_value_mismatch_anchor),
                                TsCodes.no_overload_matches,
                                "No overload matches this call.",
                            );
                            return types.Primitive.any;
                        }
                        if (self.jsxTagHasVisibleOverloads(el.tag)) {
                            try self.report(
                                self.jsxNoOverloadAnchor(el.tag, overload_value_mismatch_anchor),
                                TsCodes.no_overload_matches,
                                "No overload matches this call.",
                            );
                            return types.Primitive.any;
                        }
                        // Prefer tsc's more-specific TS2741
                        // ("Property 'X' is missing in type ... but
                        // required in type ...") when the gap is a
                        // single required-property miss. Mirrors
                        // upstream's preference (`renamed.ts` etc.)
                        // and matches `tsxAttributeResolution3` line
                        // 23 (`<test1 {...obj3} />` with obj3 missing
                        // the required `x` from `Attribs1`). Falls
                        // through to the structural TS2322 below when
                        // the gap isn't single-required.
                        // tsgo's missing-property elaboration reports
                        // against the single props constituent that
                        // declares the gap (e.g. `{ x: boolean; }` from
                        // the `{ x: boolean; } & {}` union-SFC props
                        // intersection — `tsxUnionElementType6` line
                        // 22), so flatten intersections of object
                        // members before the TS2741 attempt. The source
                        // renders from the display bag so hyphenated
                        // `data-*` members show up (`line 23`'s
                        // `{ "data-prop": true; }`).
                        const elaboration_target = self.mergeJsxAttrsTargetForElaboration(effective_target) catch effective_target;
                        const construct_interface_tag = !tag_is_class_component and try self.jsxTagUsesConstructSignatures(el.tag);
                        const class_missing_target = if (tag_is_class_component)
                            try self.jsxFirstMissingAttrsConstituent(display_attrs_t, effective_target)
                        else
                            null;
                        const fired_missing = if (class_missing_target) |missing_target|
                            try self.tryReportJsxChildMissingProperties(el.tag, display_attrs_t, missing_target)
                        else if (construct_interface_tag)
                            false
                        else
                            self.tryReportSinglePropertyMissing(el.tag, hir_mod.none_node_id, display_attrs_t, elaboration_target) catch false;
                        const fired_weak = !fired_missing and tag_is_class_component and
                            try self.tryReportJsxWeakTypeNoOverlap(
                                el.tag,
                                display_attrs_t,
                                elaboration_target,
                                effective_target,
                            );
                        if (!fired_missing and !fired_weak) {
                            // Prefer tsc's structural-shape wording
                            // (`Type 'X' is not assignable to type 'Y'.`)
                            // when both attrs_t and the (substituted)
                            // target render cleanly via the existing
                            // type-name helpers. Falls back to the
                            // simplified JSX-specific message when
                            // either side fails to render ÃÂ¢ÃÂÃÂ better than
                            // emitting a misshapen structural message.
                            const src_text = (try self.allocAnonymousObjectName(display_attrs_t)) orelse
                                (try self.allocSimpleTypeName(display_attrs_t));
                            const mismatch_constituent = if (tag_is_class_component and
                                attrs_have_no_excess and
                                try self.jsxRequiredPropsCovered(effective_target, attrs_t) and
                                !attrs_values_assignable)
                                try self.jsxFirstIncompatibleAttrsConstituent(display_attrs_t, effective_target)
                            else
                                null;
                            const tgt_text = if (mismatch_constituent) |constituent|
                                (try self.allocSimpleTypeName(constituent)) orelse
                                    (try self.allocAnonymousObjectName(constituent))
                            else
                                try self.allocJsxAttrsTargetName(el.tag, effective_target);
                            if (src_text != null and tgt_text != null) {
                                const msg = try std.fmt.allocPrint(
                                    self.diag_arena.allocator(),
                                    "Type '{s}' is not assignable to type '{s}'.",
                                    .{ src_text.?, tgt_text.? },
                                );
                                try self.diagnostics.append(self.gpa, .{
                                    .node = try self.jsxAttrsStructuralMismatchAnchor(el.tag, attrs, effective_target),
                                    .code = TsCodes.type_not_assignable,
                                    .message = msg,
                                });
                            } else {
                                try self.report(el.tag, TsCodes.type_not_assignable, "JSX attributes are not assignable to the target props type.");
                            }
                        }
                    }
                }
            }
        }
        // `<div>...</div>` (or any other JSX element) evaluates to
        // JSX.Element when the program declares the lib's
        // `react.d.ts` triple-slash reference ÃÂ¢ÃÂÃÂ we don't actually
        // load the lib, so synthesise an empty named type registered
        // as `Element` so diagnostic prose renders the correct shape
        // (`{ children: Element; }` rather than `{ children: any; }`).
        // Falls through to `any` for fixtures with no lib reference.
        if (try self.jsxLibElementSyntheticType()) |t| return t;
        return types.Primitive.any;
    }

    fn checkedExpressionType(self: *Checker, node: NodeId) CheckError!TypeId {
        const existing = self.hir.typeOf(node);
        if (existing != types.Primitive.none) return existing;
        return try self.checkExpression(node);
    }

    fn appendOrReplaceObjectMember(
        self: *Checker,
        members: *std.ArrayListUnmanaged(types.ObjectMember),
        member: types.ObjectMember,
    ) CheckError!void {
        for (members.items) |*existing| {
            if (existing.name == member.name) {
                existing.* = member;
                return;
            }
        }
        try members.append(self.gpa, member);
    }

    /// tsgo spread symbols retain their originating declarations. Its
    /// property enumeration consequently follows source declaration
    /// position, not the order in which spread folds happened. Keep the
    /// same ordering only for diagnostic display bags; relation bags retain
    /// their runtime last-write-wins construction.
    fn sortJsxDisplayMembersByDeclarationOrder(self: *Checker, members: []types.ObjectMember) void {
        std.sort.insertion(types.ObjectMember, members, self, jsxDisplayMemberDeclarationLessThan);
    }

    fn jsxDisplayMemberDeclarationLessThan(self: *Checker, lhs: types.ObjectMember, rhs: types.ObjectMember) bool {
        if (lhs.decl_node == hir_mod.none_node_id) return false;
        if (rhs.decl_node == hir_mod.none_node_id) return true;
        return self.hir.spanOf(lhs.decl_node).start < self.hir.spanOf(rhs.decl_node).start;
    }

    fn appendJsxSpreadMembers(
        self: *Checker,
        members: *std.ArrayListUnmanaged(types.ObjectMember),
        spread_t: TypeId,
    ) CheckError!void {
        if (spread_t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(spread_t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(spread_t) orelse return;
            if (constraint != spread_t) try self.appendJsxSpreadMembers(members, constraint);
            return;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(spread_t)) |member_t| {
                try self.appendJsxSpreadMembers(members, member_t);
            }
            return;
        }
        if (flags.is_union) return;
        if (!flags.is_object_type) return;
        for (self.interner.objectMembers(spread_t)) |member| {
            try self.appendOrReplaceObjectMember(members, member);
        }
    }

    fn appendJsxSpreadMembersFromExpression(
        self: *Checker,
        members: *std.ArrayListUnmanaged(types.ObjectMember),
        expr: NodeId,
        spread_t: TypeId,
        props_t: ?TypeId,
        tag: NodeId,
    ) CheckError!void {
        const object_expr = self.unwrapJsxSpreadObjectExpression(expr);
        if (object_expr == hir_mod.none_node_id or self.hir.kindOf(object_expr) != .object_literal) {
            return try self.appendJsxSpreadMembers(members, spread_t);
        }
        for (hir_mod.objectLiteralProps(self.hir, object_expr)) |prop| {
            if (self.hir.kindOf(prop) == .spread) {
                const sp = hir_mod.spreadOf(self.hir, prop);
                const inner_t = try self.checkedExpressionType(sp.expression);
                try self.appendJsxSpreadMembers(members, inner_t);
                continue;
            }
            if (self.hir.kindOf(prop) != .object_property) continue;
            const op = hir_mod.objectPropertyOf(self.hir, prop);
            if (op.is_computed) continue;
            const name = self.propertyNameFromKeyNode(op.key) orelse continue;
            const prop_t = try self.jsxContextualPropType(props_t, tag, name);
            const value_t = if (op.value == hir_mod.none_node_id)
                types.Primitive.true_lit
            else if (prop_t != null and self.jsxValueIsFunctionLike(op.value))
                prop_t.?
            else blk: {
                const raw = if (op.value != hir_mod.none_node_id and self.hir.typeOf(op.value) != types.Primitive.none)
                    self.hir.typeOf(op.value)
                else
                    try self.checkExpression(op.value);
                const flowed = try self.flowTypeForAssignmentValue(op.value, raw);
                break :blk self.jsxSpreadObjectMemberValueType(op.value, flowed, prop_t);
            };
            try self.appendOrReplaceObjectMember(members, .{
                .name = name,
                .type = value_t,
                .is_optional = false,
                .is_readonly = false,
                .is_method = false,
                .decl_node = prop,
            });
        }
    }

    fn jsxSpreadObjectMemberValueType(
        self: *Checker,
        value: NodeId,
        flowed: TypeId,
        prop_t: ?TypeId,
    ) TypeId {
        if (value == hir_mod.none_node_id or flowed >= self.interner.pool.typeCount()) return flowed;
        if (!self.interner.pool.flagsOf(flowed).is_literal) return flowed;
        // Boolean object-literal members stay fresh through tsgo's spread
        // construction. String/number members retain freshness only when
        // the contextual prop contains that exact literal.
        if (self.hir.kindOf(value) == .literal_bool) return flowed;
        return self.jsxDiagnosticBagMemberType(value, flowed, prop_t);
    }

    fn jsxSpreadTypeIsValid(self: *Checker, t: TypeId) CheckError!bool {
        if (self.typeIsAnyLike(t)) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_never or flags.is_null or flags.is_undefined or flags.is_void) return false;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!try self.jsxSpreadTypeIsValid(member)) return false;
            }
            return true;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (try self.jsxSpreadTypeIsValid(member)) return true;
            }
            return false;
        }
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return true;
            if (constraint == t) return false;
            return try self.jsxSpreadTypeIsValid(constraint);
        }
        return flags.is_object_type or flags.is_object or flags.is_signature;
    }

    fn jsxSpreadChildTypeIsValid(self: *Checker, t: TypeId) CheckError!bool {
        if (self.typeIsAnyLike(t)) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!try self.jsxSpreadChildTypeIsValid(member)) return false;
            }
            return true;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (try self.jsxSpreadChildTypeIsValid(member)) return true;
            }
            return false;
        }
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return true;
            if (constraint == t) return false;
            return try self.jsxSpreadChildTypeIsValid(constraint);
        }
        return try self.arrayElementType(t) != types.Primitive.none;
    }

    fn objectSpreadSourceIsValid(self: *Checker, t: TypeId) CheckError!bool {
        if (self.typeIsAny(t)) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_never) return true;
        // For unions/intersections, the OR'd flags include
        // is_null/is_undefined/is_void from constituents ÃÂ¢ÃÂÃÂ defer to the
        // dedicated union/intersection branches below which inspect
        // each member individually. Only reject the bare nullish
        // primitives outright. Mirrors `spreadUnion2.ts(o1..o5)` where
        // `{ a: number } | undefined` is a valid spread source.
        if (!flags.is_union and !flags.is_intersection) {
            if (flags.is_null or flags.is_undefined or flags.is_void) return false;
        }
        if (flags.is_boolean and t == types.Primitive.false_lit) return true;
        if (flags.is_union) {
            var saw_spreadable = false;
            for (self.interner.unionMembers(t)) |member| {
                if (member == types.Primitive.null_t or member == types.Primitive.undefined_t or member == types.Primitive.false_lit) continue;
                // Type parameters constrained to nullish-only types
                // (`T extends undefined`, `T extends null`) collapse to
                // their constraint within the union ÃÂ¢ÃÂÃÂ TS does NOT
                // report TS2698 if the rest of the union is spreadable.
                // Mirrors `spreadObjectOrFalsy.ts(f4/f5/f6)`.
                if (member < self.interner.pool.typeCount()) {
                    const mflags = self.interner.pool.flagsOf(member);
                    if (mflags.is_type_parameter) {
                        if (self.typeParameterConstraint(member)) |constraint| {
                            if (constraint != member and constraint < self.interner.pool.typeCount()) {
                                const cflags = self.interner.pool.flagsOf(constraint);
                                if (cflags.is_undefined or cflags.is_null or cflags.is_void) continue;
                            }
                        }
                    }
                    // Intersections that include `undefined` / `null` /
                    // `void` reduce to `never` at runtime ÃÂ¢ÃÂÃÂ also skip
                    // them inside a union (mirrors `f2: T | T & undefined`).
                    if (mflags.is_intersection) {
                        var has_nullish = false;
                        for (self.interner.intersectionMembers(member)) |im| {
                            if (im == types.Primitive.null_t or
                                im == types.Primitive.undefined_t or
                                im == types.Primitive.void_t)
                            {
                                has_nullish = true;
                                break;
                            }
                        }
                        if (has_nullish) continue;
                    }
                }
                if (!try self.objectSpreadSourceIsValid(member)) return false;
                saw_spreadable = true;
            }
            // A union composed entirely of nullish/falsy members
            // (`null | undefined`, `null | undefined | false`) has no
            // spreadable inhabitant and must surface TS2698. Mirrors
            // `spreadUnion3.ts(19/20)`'s `nullAndUndefinedUnion`.
            return saw_spreadable;
        }
        if (flags.is_intersection) {
            // TS2698 wave-2: an intersection that includes a hard
            // nullish member (`null`, `undefined`, `void`) collapses
            // to `never` in upstream's relation engine ÃÂ¢ÃÂÃÂ `T &
            // undefined` has no inhabitants, so spreading it must
            // surface as TS2698 rather than silently passing because
            // a sibling type-parameter member happened to clear the
            // per-member check. Mirrors `spreadObjectOrFalsy.ts`
            // lines 5/13 (`f1<T>(a: T & undefined)`,
            // `f3<T extends undefined>(a: T)`).
            for (self.interner.intersectionMembers(t)) |member| {
                if (member == types.Primitive.null_t or
                    member == types.Primitive.undefined_t or
                    member == types.Primitive.void_t)
                {
                    return false;
                }
            }
            for (self.interner.intersectionMembers(t)) |member| {
                if (try self.objectSpreadSourceIsValid(member)) return true;
            }
            return false;
        }
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return true;
            if (constraint == t) return true;
            return try self.objectSpreadSourceIsValid(constraint);
        }
        return flags.is_object_type or flags.is_object or flags.is_signature;
    }

    /// Collect the spread-equivalent members of a union spread source
    /// (e.g. `{ x: number } | { x: string }`): a property is part of
    /// the effective output if every non-nullish branch contributes
    /// the same name as a required member. Optionality of an entry in
    /// any branch downgrades the overall required-ness, so it won't
    /// trigger TS2783. Skips nullish/never branches that contribute
    /// nothing at runtime. Output is empty for unions where any
    /// non-nullish branch lacks object members (any-like, signature,
    /// etc.) ÃÂ¢ÃÂÃÂ matching tsc's conservative behavior.
    /// True when `t` is a union whose every member is a (non-nullish)
    /// object type — the shape that distributes when spread.
    fn unionIsAllObjectTypesNonNullish(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(t).is_union) return false;
        const members = self.interner.unionMembers(t);
        if (members.len == 0) return false;
        for (members) |m| {
            if (m == types.Primitive.null_t or m == types.Primitive.undefined_t or
                m == types.Primitive.void_t) return false;
            if (m >= self.interner.pool.typeCount()) return false;
            if (!self.interner.pool.flagsOf(m).is_object_type) return false;
        }
        return true;
    }

    fn distSpreadUpsert(
        self: *Checker,
        list: *std.ArrayListUnmanaged(types.ObjectMember),
        m: types.ObjectMember,
    ) CheckError!void {
        for (list.items) |*existing| {
            if (existing.name == m.name) {
                existing.* = m;
                return;
            }
        }
        try list.append(self.gpa, m);
    }

    fn removeObjectMemberByName(list: *std.ArrayListUnmanaged(types.ObjectMember), name: hir_mod.StringId) void {
        var i: usize = 0;
        while (i < list.items.len) : (i += 1) {
            if (list.items[i].name != name) continue;
            std.mem.copyForwards(types.ObjectMember, list.items[i..], list.items[i + 1 ..]);
            list.items.len -= 1;
            return;
        }
    }

    /// Build the distributed union for an object literal containing a
    /// union spread: the cartesian product of the spread-union branches,
    /// each folded with the literal's data properties and plain object
    /// spreads in source order (last-wins), yields one object type per
    /// combination. Returns the union of those (deduped), or null when
    /// the cross product is unbounded (>64) or empty. `Seg` is the
    /// caller's local segment struct (passed comptime). Mirrors tsc's
    /// `getSpreadType` distribution over a union operand
    /// (`spreadUnion.ts`).
    fn buildDistributedObjectSpread(self: *Checker, comptime Seg: type, segments: []const Seg) CheckError!?TypeId {
        var branch_lists: std.ArrayListUnmanaged([]TypeId) = .empty;
        defer {
            for (branch_lists.items) |bl| self.gpa.free(bl);
            branch_lists.deinit(self.gpa);
        }
        var total: usize = 1;
        for (segments) |seg| {
            if (seg.is_spread and seg.src_is_union) {
                const ums = self.interner.unionMembers(seg.src_t);
                if (ums.len == 0) return null;
                // Own the branch list so later interning can't invalidate it.
                try branch_lists.append(self.gpa, try self.gpa.dupe(TypeId, ums));
                total *|= ums.len;
                if (total > 64) return null;
            }
        }
        if (total == 0 or branch_lists.items.len == 0) return null;

        var result_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer result_types.deinit(self.gpa);

        var combo: usize = 0;
        while (combo < total) : (combo += 1) {
            var fold_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
            defer fold_members.deinit(self.gpa);
            var str_idx: TypeId = types.Primitive.none;
            var num_idx: TypeId = types.Primitive.none;
            var sym_idx: TypeId = types.Primitive.none;
            var rem = combo;
            var branch_idx: usize = 0;
            for (segments) |seg| {
                if (!seg.is_spread) {
                    try self.distSpreadUpsert(&fold_members, .{
                        .name = seg.name,
                        .type = seg.member_t,
                        .is_optional = false,
                        .is_readonly = false,
                        .is_method = seg.is_method,
                    });
                    continue;
                }
                const src: TypeId = if (seg.src_is_union) blk: {
                    const ums = branch_lists.items[branch_idx];
                    const choice = ums[rem % ums.len];
                    rem /= ums.len;
                    branch_idx += 1;
                    break :blk choice;
                } else seg.src_t;
                const src_members = try self.gpa.dupe(types.ObjectMember, self.interner.objectMembers(src));
                defer self.gpa.free(src_members);
                for (src_members) |m| try self.distSpreadUpsert(&fold_members, m);
                const s = self.interner.objectStringIndex(src);
                if (s != types.Primitive.none) str_idx = s;
                const n = self.interner.objectNumberIndex(src);
                if (n != types.Primitive.none) num_idx = n;
                const y = self.interner.objectSymbolIndex(src);
                if (y != types.Primitive.none) sym_idx = y;
            }
            const ot = self.interner.internObjectTypeWithIndexAndSymbol(fold_members.items, str_idx, num_idx, sym_idx) catch return error.OutOfMemory;
            var seen = false;
            for (result_types.items) |existing| {
                if (existing == ot) {
                    seen = true;
                    break;
                }
            }
            if (!seen) try result_types.append(self.gpa, ot);
        }
        if (result_types.items.len == 0) return null;
        if (result_types.items.len == 1) return result_types.items[0];
        return self.interner.internUnion(result_types.items) catch return error.OutOfMemory;
    }

    fn collectUnionSpreadCommonMembers(
        self: *Checker,
        union_t: TypeId,
        out: *std.ArrayListUnmanaged(types.ObjectMember),
    ) CheckError!void {
        if (union_t >= self.interner.pool.typeCount()) return;
        if (!self.interner.pool.flagsOf(union_t).is_union) return;
        const members = self.interner.unionMembers(union_t);
        // Counts: how many non-nullish branches contributed the name;
        // required_in_all becomes false if any branch had it optional.
        var name_counts: std.AutoHashMapUnmanaged(hir_mod.StringId, u32) = .empty;
        defer name_counts.deinit(self.gpa);
        var name_required: std.AutoHashMapUnmanaged(hir_mod.StringId, bool) = .empty;
        defer name_required.deinit(self.gpa);
        var name_first_member: std.AutoHashMapUnmanaged(hir_mod.StringId, types.ObjectMember) = .empty;
        defer name_first_member.deinit(self.gpa);

        var contributing: u32 = 0;
        for (members) |branch| {
            if (branch == types.Primitive.null_t or
                branch == types.Primitive.undefined_t or
                branch == types.Primitive.void_t or
                branch == types.Primitive.never) continue;
            if (branch >= self.interner.pool.typeCount()) return;
            const bf = self.interner.pool.flagsOf(branch);
            if (!bf.is_object_type) return;
            contributing += 1;
            for (self.interner.objectMembers(branch)) |bm| {
                const prev = name_counts.get(bm.name) orelse 0;
                try name_counts.put(self.gpa, bm.name, prev + 1);
                const prev_req = name_required.get(bm.name) orelse true;
                try name_required.put(self.gpa, bm.name, prev_req and !bm.is_optional);
                if (!name_first_member.contains(bm.name)) {
                    try name_first_member.put(self.gpa, bm.name, bm);
                }
            }
        }
        if (contributing == 0) return;
        var it = name_counts.iterator();
        while (it.next()) |entry| {
            if (entry.value_ptr.* != contributing) continue;
            const required = name_required.get(entry.key_ptr.*) orelse true;
            var m = name_first_member.get(entry.key_ptr.*) orelse continue;
            m.is_optional = !required;
            try out.append(self.gpa, m);
        }
    }

    fn objectSpreadEffectiveType(self: *Checker, expr: NodeId, fallback: TypeId) CheckError!TypeId {
        if (expr == hir_mod.none_node_id) return fallback;
        const k = self.hir.kindOf(expr);
        if (k == .logical_op) {
            const l = hir_mod.logicalOf(self.hir, expr);
            if (l.op != .@"and") return fallback;
            const rhs_t = if (self.hir.typeOf(l.rhs) != types.Primitive.none)
                self.hir.typeOf(l.rhs)
            else
                try self.checkExpression(l.rhs);
            if (try self.objectSpreadSourceIsValid(rhs_t)) return rhs_t;
            return fallback;
        }
        if (k == .conditional) {
            // For `cond ? thenExpr : elseExpr` we use whichever branch
            // is a valid spread source ÃÂ¢ÃÂÃÂ at least one nullish branch
            // is OK (matches `objectSpreadIndexSignature.ts(14)`'s
            // `...b ? indexed3 : undefined`).
            const c = hir_mod.conditionalOf(self.hir, expr);
            const tt = if (self.hir.typeOf(c.then_branch) != types.Primitive.none)
                self.hir.typeOf(c.then_branch)
            else
                try self.checkExpression(c.then_branch);
            const ff = if (self.hir.typeOf(c.else_branch) != types.Primitive.none)
                self.hir.typeOf(c.else_branch)
            else
                try self.checkExpression(c.else_branch);
            const tt_ok = try self.objectSpreadSourceIsValid(tt);
            const ff_ok = try self.objectSpreadSourceIsValid(ff);
            if (tt_ok and ff_ok) return fallback;
            if (tt_ok) return tt;
            if (ff_ok) return ff;
            return fallback;
        }
        return fallback;
    }

    fn mergeObjectLiteralIndexType(self: *Checker, current: *TypeId, next: TypeId) CheckError!void {
        if (next == types.Primitive.none) return;
        if (current.* == types.Primitive.none) {
            current.* = next;
            return;
        }
        current.* = self.interner.internUnion(&.{ current.*, next }) catch return error.OutOfMemory;
    }

    /// Returns true when the spread expression might contribute no
    /// members at runtime, e.g. `...(t ? a : {})` or `...(x && a)`.
    /// In those cases TS2783 (duplicate-property overwrite) should not
    /// fire even when an explicit property earlier shares a name with
    /// one of the spread's possible members ÃÂ¢ÃÂÃÂ the spread is not
    /// guaranteed to overwrite. Walks through type assertions and
    /// parenthesized expressions so source-level grouping is
    /// transparent.
    fn spreadExpressionMayContributeNothing(self: *Checker, expr: NodeId) bool {
        var cur = expr;
        while (cur != hir_mod.none_node_id) {
            switch (self.hir.kindOf(cur)) {
                .conditional => return true,
                .logical_op => {
                    const l = hir_mod.logicalOf(self.hir, cur);
                    // `a && b` (LHS may be falsy ÃÂ¢ÃÂÃÂ spread evaluates `a`).
                    // `a || b` and `a ?? b` similarly may pick either side.
                    _ = l;
                    return true;
                },
                .type_assertion, .as_expr, .satisfies_expr, .non_null_expr => {
                    const inner = hir_mod.asExpressionOf(self.hir, cur);
                    cur = inner.expr;
                },
                else => return false,
            }
        }
        return false;
    }

    fn jsxAttributeAssignable(self: *Checker, value_t: TypeId, prop_t: TypeId) CheckError!bool {
        if (prop_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(prop_t).is_intersection)
        {
            var saw_callable = false;
            for (self.interner.intersectionMembers(prop_t)) |member| {
                if (self.firstSignatureType(member) == null) continue;
                saw_callable = true;
                if (!try self.jsxAttributeAssignable(value_t, member)) return false;
            }
            if (saw_callable) return true;
        }
        if (self.firstSignatureType(value_t)) |value_sig| {
            if (self.containsFreeTypeParameter(prop_t)) return true;
            if (self.firstSignatureType(prop_t)) |prop_sig| {
                const value_params = self.interner.signatureParams(value_sig);
                const prop_params = self.interner.signatureParams(prop_sig);
                if (value_params.len <= prop_params.len) {
                    var i: usize = 0;
                    while (i < value_params.len) : (i += 1) {
                        if (prop_params[i] < self.interner.pool.typeCount()) {
                            const pf = self.interner.pool.flagsOf(prop_params[i]);
                            if (pf.is_type_parameter or pf.is_any or pf.is_unknown) continue;
                        }
                        if (!(self.engine.isAssignableTo(prop_params[i], value_params[i]) catch true)) return false;
                    }
                    const prop_return = self.interner.signatureReturn(prop_sig) orelse types.Primitive.any;
                    if (prop_return != types.Primitive.void_t and
                        prop_return != types.Primitive.any and
                        prop_return != types.Primitive.unknown)
                    {
                        const value_return = self.interner.signatureReturn(value_sig) orelse types.Primitive.any;
                        if (!(self.engine.isAssignableTo(value_return, prop_return) catch true)) return false;
                    }
                    return true;
                }
            }
        }
        return self.engine.isAssignableTo(value_t, prop_t) catch true;
    }

    fn allocJsxCallableIntersectionDiagnosticName(
        self: *Checker,
        target: TypeId,
        source: TypeId,
    ) CheckError!?[]const u8 {
        if (target >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(target).is_intersection) return null;
        var callable_count: usize = 0;
        var equivalent: ?TypeId = null;
        for (self.interner.intersectionMembers(target)) |member| {
            if (self.firstSignatureType(member) == null) continue;
            callable_count += 1;
            if (try self.jsxAttributeAssignable(source, member) and
                try self.jsxAttributeAssignable(member, source))
            {
                equivalent = member;
            }
        }
        if (callable_count <= 1) return null;
        const equivalent_member = equivalent orelse return try self.allocSimpleTypeName(target);
        const first_name = (try self.allocSimpleTypeName(equivalent_member)) orelse return try self.allocSimpleTypeName(target);
        var result = try std.fmt.allocPrint(self.diag_arena.allocator(), "({s})", .{first_name});
        for (self.interner.intersectionMembers(target)) |member| {
            if (member == equivalent_member) continue;
            const member_name = (try self.allocSimpleTypeName(member)) orelse return try self.allocSimpleTypeName(target);
            result = if (self.firstSignatureType(member) != null)
                try std.fmt.allocPrint(self.diag_arena.allocator(), "{s} & ({s})", .{ result, member_name })
            else
                try std.fmt.allocPrint(self.diag_arena.allocator(), "{s} & {s}", .{ result, member_name });
        }
        return result;
    }

    fn jsxAttributeLiteralAssignable(self: *Checker, value: NodeId, prop_t: TypeId) CheckError!bool {
        if (value == hir_mod.none_node_id) return false;
        var inner = value;
        if (self.hir.kindOf(value) == .jsx_expression) {
            const ex = hir_mod.jsxExpressionOf(self.hir, value);
            if (ex.expression == hir_mod.none_node_id) return false;
            inner = ex.expression;
        }
        return try self.literalExpressionAssignableToTarget(inner, prop_t);
    }

    fn jsxAttributeDiagnosticValueType(self: *Checker, value: NodeId, fallback: TypeId, prop_t: TypeId) CheckError!TypeId {
        if (value == hir_mod.none_node_id) {
            return if (self.typeHasLiteralConstituent(prop_t))
                types.Primitive.true_lit
            else
                self.widenForInference(types.Primitive.true_lit);
        }
        const widened = self.widenForInference(fallback);
        // A quoted JSX initializer is contextually literal-preserving
        // when the prop is a literal union (`x="f"` against `"a" | "b"`
        // reports `"f"`, not `string`). Braced expressions follow the
        // same rule through their inner expression.
        const literal_source = if (self.hir.kindOf(value) != .jsx_expression)
            try self.expressionLiteralType(value, widened)
        else blk: {
            const ex = hir_mod.jsxExpressionOf(self.hir, value);
            if (ex.expression == hir_mod.none_node_id) break :blk widened;
            break :blk try self.expressionLiteralType(ex.expression, widened);
        };
        return if (self.typeHasMatchingLiteralFamily(prop_t, literal_source))
            literal_source
        else
            widened;
    }

    fn typeHasMatchingLiteralFamily(self: *Checker, target: TypeId, source: TypeId) bool {
        if (target >= self.interner.pool.typeCount() or source >= self.interner.pool.typeCount()) return false;
        const source_flags = self.interner.pool.flagsOf(source);
        if (!source_flags.is_literal) return false;
        const target_flags = self.interner.pool.flagsOf(target);
        if (target_flags.is_union or target_flags.is_intersection) {
            const members = if (target_flags.is_union)
                self.interner.unionMembers(target)
            else
                self.interner.intersectionMembers(target);
            for (members) |member| {
                if (self.typeHasMatchingLiteralFamily(member, source)) return true;
            }
            return false;
        }
        return target_flags.is_literal and
            ((source_flags.is_string and target_flags.is_string) or
                (source_flags.is_number and target_flags.is_number) or
                (source_flags.is_boolean and target_flags.is_boolean) or
                (source_flags.is_bigint and target_flags.is_bigint));
    }

    fn typeHasLiteralConstituent(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union or flags.is_intersection) {
            const members = if (flags.is_union)
                self.interner.unionMembers(t)
            else
                self.interner.intersectionMembers(t);
            for (members) |member| {
                if (self.typeHasLiteralConstituent(member)) return true;
            }
            return false;
        }
        return flags.is_literal;
    }

    fn jsxTagVisibleOverloads(self: *Checker, tag: NodeId) ?[]const TypeId {
        if (tag == hir_mod.none_node_id or self.hir.kindOf(tag) != .identifier) return null;
        const tag_name = hir_mod.identifierOf(self.hir, tag).name;
        const overload_list = self.overloads.get(tag_name) orelse return null;
        const has_impl = self.overload_has_implementation.contains(tag_name);
        const visible_len = if (has_impl and overload_list.items.len > 0) overload_list.items.len - 1 else overload_list.items.len;
        if (visible_len == 0) return null;
        return overload_list.items[0..visible_len];
    }

    fn jsxTagHasVisibleOverloads(self: *Checker, tag: NodeId) bool {
        const overloads = self.jsxTagVisibleOverloads(tag) orelse return false;
        return overloads.len > 1;
    }

    /// Whether the JSX tag names a class component. Class elements
    /// resolve through the class's construct signatures, so a bag
    /// mismatch surfaces as TS2769 ("No overload matches this call.")
    /// only when more than one candidate exists — see
    /// `jsxTagClassConstructSignatureCount`.
    fn jsxTagIsClassComponent(self: *Checker, tag: NodeId) bool {
        if (tag == hir_mod.none_node_id or self.hir.kindOf(tag) != .identifier) return false;
        const name = hir_mod.identifierOf(self.hir, tag).name;
        return self.class_instance_types.contains(name);
    }

    fn jsxTagUsesConstructSignatures(self: *Checker, tag: NodeId) CheckError!bool {
        if (self.jsxTagIsIntrinsic(tag)) return false;
        const tag_t = try self.checkedExpressionType(tag);
        var signatures: std.ArrayListUnmanaged(TypeId) = .empty;
        defer signatures.deinit(self.gpa);
        try self.collectConstructSignatures(tag_t, &signatures);
        return signatures.items.len > 0;
    }

    /// Number of construct signatures a JSX class element resolves
    /// through, mirroring tsc's constructor inheritance: a class
    /// without a declared constructor picks up the base class's
    /// constructors, falling back to one synthesized default
    /// constructor at the root. `resolveCall` only reports TS2769
    /// ("No overload matches this call.") when more than one
    /// candidate exists, so react16.d.ts's two-constructor
    /// `Component` makes subclass elements report TS2769
    /// (`checkJsxChildrenCanBeTupleType`) while a fixture-local
    /// `class Component<T, U> {}` leaves a single candidate and the
    /// bag mismatch reports plain TS2322/TS2739
    /// (`tsxSpreadAttributesResolution2`).
    fn jsxTagClassConstructSignatureCount(self: *Checker, tag: NodeId) usize {
        if (tag == hir_mod.none_node_id or self.hir.kindOf(tag) != .identifier) return 1;
        const name = hir_mod.identifierOf(self.hir, tag).name;
        const instance_t = self.class_instance_types.get(name) orelse return 1;
        const decl = self.class_decl_by_instance.get(instance_t) orelse return 1;
        return self.jsxClassDeclConstructSignatureCount(decl, 0);
    }

    fn jsxClassDeclConstructSignatureCount(self: *Checker, decl: NodeId, depth: usize) usize {
        if (depth >= 8) return 1;
        var ctor_count: usize = 0;
        for (hir_mod.classMembers(self.hir, decl)) |member| {
            if (self.fnDeclIsConstructor(member)) ctor_count += 1;
        }
        if (ctor_count > 0) return ctor_count;

        const class_info = hir_mod.classOf(self.hir, decl);
        if (class_info.extends == hir_mod.none_node_id) return 1;
        const base_decl_opt = switch (self.hir.kindOf(class_info.extends)) {
            .type_ref => self.visibleClassDeclForHeritageTypeRef(class_info.extends),
            .member_access => self.findQualifiedClassDecl(class_info.extends),
            .identifier => self.findVisibleNamedClassDecl(
                class_info.extends,
                hir_mod.identifierOf(self.hir, class_info.extends).name,
            ),
            else => null,
        };
        const base_decl = base_decl_opt orelse {
            if (self.sourceHasReact16JsxReference()) {
                const base_name: ?hir_mod.StringId = switch (self.hir.kindOf(class_info.extends)) {
                    .type_ref => hir_mod.typeRefOf(self.hir, class_info.extends).name,
                    .member_access => hir_mod.memberOf(self.hir, class_info.extends).name,
                    .identifier => hir_mod.identifierOf(self.hir, class_info.extends).name,
                    else => null,
                };
                if (base_name) |candidate| {
                    if (std.mem.eql(u8, self.string_interner.get(candidate), "Component")) return 2;
                }
            }
            return 1;
        };
        return self.jsxClassDeclConstructSignatureCount(base_decl, depth + 1);
    }

    fn jsxOverloadPropType(self: *Checker, tag: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        const overloads = self.jsxTagVisibleOverloads(tag) orelse return null;
        for (overloads) |sig| {
            const params = self.interner.signatureParams(sig);
            if (params.len == 0) continue;
            if (try self.jsxTargetPropType(params[0], name)) |prop_t| return prop_t;
        }
        return null;
    }

    fn jsxContextualPropType(self: *Checker, props_t: ?TypeId, tag: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (props_t) |target| {
            if (try self.jsxTargetPropType(target, name)) |prop_t| return prop_t;
        }
        return try self.jsxOverloadPropType(tag, name);
    }

    fn jsxTargetPropType(self: *Checker, target: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (target >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(target);
        if (!flags.is_intersection) return try self.lookupObjectMember(target, name);

        var member_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer member_types.deinit(self.gpa);
        const constituents = try self.gpa.dupe(TypeId, self.interner.intersectionMembers(target));
        defer self.gpa.free(constituents);
        for (constituents) |member| {
            if (try self.jsxTargetPropType(member, name)) |member_t| {
                var seen = false;
                for (member_types.items) |existing| {
                    if (existing == member_t) {
                        seen = true;
                        break;
                    }
                }
                if (!seen) try member_types.append(self.gpa, member_t);
            }
        }
        if (member_types.items.len == 0) return null;
        if (member_types.items.len == 1) return member_types.items[0];
        return self.interner.internIntersection(member_types.items) catch return error.OutOfMemory;
    }

    fn jsxValueIsFunctionLike(self: *Checker, value: NodeId) bool {
        if (value == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(value)) {
            .arrow_fn, .fn_expr, .fn_decl => true,
            else => false,
        };
    }

    fn jsxAttributeExpression(self: *Checker, value: NodeId) NodeId {
        if (value == hir_mod.none_node_id) return hir_mod.none_node_id;
        if (self.hir.kindOf(value) != .jsx_expression) return value;
        return hir_mod.jsxExpressionOf(self.hir, value).expression;
    }

    fn jsxFunctionHasCompleteParameterAnnotations(self: *Checker, fn_node: NodeId) bool {
        if (!self.jsxValueIsFunctionLike(fn_node)) return false;
        const params = hir_mod.fnParams(self.hir, fn_node);
        if (params.len == 0) return true;
        for (params) |param_node| {
            const param = hir_mod.parameterOf(self.hir, param_node);
            if (param.type_annotation == hir_mod.none_node_id) return false;
        }
        return true;
    }

    fn jsxAppendInferenceAttribute(
        self: *Checker,
        members: *std.ArrayListUnmanaged(types.ObjectMember),
        attr: NodeId,
        want_annotated_callback: bool,
    ) CheckError!void {
        if (self.hir.kindOf(attr) != .jsx_attribute) return;
        const a = hir_mod.jsxAttributeOf(self.hir, attr);
        const name = self.string_interner.get(a.name);
        if (std.mem.eql(u8, name, "key") or std.mem.startsWith(u8, name, "data-")) return;

        const expr = self.jsxAttributeExpression(a.value);
        const is_inline_fn = expr != hir_mod.none_node_id and self.jsxValueIsFunctionLike(expr);
        const is_annotated_callback = is_inline_fn and self.jsxFunctionHasCompleteParameterAnnotations(expr);
        if (want_annotated_callback != is_annotated_callback) return;
        if (is_inline_fn and !is_annotated_callback) return;

        const value_t = try self.checkJsxAttributeValue(a.value);
        const bag_t = try self.jsxAttributeBagValueType(a.value, value_t);
        try self.appendOrReplaceObjectMember(members, .{
            .name = a.name,
            .type = self.widenForInference(bag_t),
            .is_optional = false,
            .is_readonly = false,
            .is_method = false,
        });
    }

    /// JSX generic inference is ordered like a call inference context:
    /// explicitly annotated callbacks provide fixed contravariant evidence
    /// first, ordinary attributes and spreads follow, and context-sensitive
    /// callbacks are checked only after those substitutions are applied.
    fn jsxInstantiatePropsFromAttributes(
        self: *Checker,
        attrs: []const NodeId,
        target: TypeId,
    ) CheckError!TypeId {
        if (!self.containsFreeTypeParameter(target)) return target;

        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        var all_evidence: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer all_evidence.deinit(self.gpa);

        for ([_]bool{ true, false }) |want_annotated_callback| {
            var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
            defer members.deinit(self.gpa);
            for (attrs) |attr| {
                if (!want_annotated_callback and self.hir.kindOf(attr) == .jsx_spread_attribute) {
                    const spread = hir_mod.jsxSpreadAttributeOf(self.hir, attr);
                    const spread_t = try self.checkedExpressionType(spread.expression);
                    try self.appendJsxSpreadMembers(&members, spread_t);
                    continue;
                }
                try self.jsxAppendInferenceAttribute(&members, attr, want_annotated_callback);
            }
            if (members.items.len == 0) continue;
            for (members.items) |member| try self.appendOrReplaceObjectMember(&all_evidence, member);
            const evidence_t = self.interner.internObjectType(members.items) catch return error.OutOfMemory;
            try self.inferFromPair(target, evidence_t, &subs);
        }

        var effective_target = if (subs.count() > 0)
            self.substituteType(target, &subs) catch target
        else
            target;
        for (attrs) |attr| {
            if (self.hir.kindOf(attr) != .jsx_attribute) continue;
            const a = hir_mod.jsxAttributeOf(self.hir, attr);
            const expr = self.jsxAttributeExpression(a.value);
            if (expr == hir_mod.none_node_id or !self.jsxValueIsFunctionLike(expr)) continue;
            if (self.jsxFunctionHasCompleteParameterAnnotations(expr)) continue;
            const prop_t = (try self.jsxTargetPropType(effective_target, a.name)) orelse continue;
            const contextual_sig = self.firstSignatureType(prop_t) orelse continue;
            var inferred_sig = types.Primitive.none;
            try self.checkFunctionWithContextualSignatureMode(expr, contextual_sig, false, &inferred_sig);
            if (inferred_sig == types.Primitive.none) continue;
            try self.appendOrReplaceObjectMember(&all_evidence, .{
                .name = a.name,
                .type = inferred_sig,
                .is_optional = false,
                .is_readonly = false,
                .is_method = false,
            });
        }

        if (all_evidence.items.len > 0) {
            const full_evidence_t = self.interner.internObjectType(all_evidence.items) catch return error.OutOfMemory;
            try self.inferFromPair(target, full_evidence_t, &subs);
            // A bare catch-all type parameter in an intersection owns the
            // complete JSX attributes bag. Keep that fixed candidate after
            // structural inference visits the named props constituents.
            try self.jsxFixDirectPropsInference(target, full_evidence_t, &subs);
            effective_target = self.substituteType(target, &subs) catch effective_target;
        }
        // `getSpreadType` retains an otherwise-bare generic spread as
        // the inference source. In particular, `<Component {...props} />`
        // for `Component<T>(props: T)` and `props: U` infers `T = U`,
        // even when U has no constraint and therefore contributes no
        // materialized object members.
        try self.jsxFixDirectPropsInferenceFromBareGenericSpread(target, attrs, &subs);
        try self.normalizeJsxInferenceConstraints(target, &subs);
        var fallback_visited: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
        defer fallback_visited.deinit(self.gpa);
        try self.collectJsxUnfixedTypeParamFallbacks(target, &subs, &fallback_visited);
        if (subs.count() == 0) return target;
        return self.substituteType(target, &subs) catch effective_target;
    }

    fn jsxFixDirectPropsInferenceFromBareGenericSpread(
        self: *Checker,
        target: TypeId,
        attrs: []const NodeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        if (attrs.len != 1 or target >= self.interner.pool.typeCount()) return;
        const target_flags = self.interner.pool.flagsOf(target);
        if (!target_flags.is_type_parameter or target_flags.is_union or target_flags.is_intersection) return;
        if (self.hir.kindOf(attrs[0]) != .jsx_spread_attribute) return;
        const spread = hir_mod.jsxSpreadAttributeOf(self.hir, attrs[0]);
        const source = try self.checkedExpressionType(spread.expression);
        if (source >= self.interner.pool.typeCount()) return;
        const source_flags = self.interner.pool.flagsOf(source);
        if (!source_flags.is_type_parameter or source_flags.is_union or source_flags.is_intersection) return;
        try subs.put(self.gpa, target, source);
    }

    /// A bare generic spread remains its source type parameter through
    /// JSX call inference. With React's `JSX.IntrinsicAttributes` in
    /// scope, an unconstrained `U` cannot satisfy the managed target
    /// `IntrinsicAttributes & U`; a constrained object type can.
    fn reportJsxBareGenericSpreadIntrinsicAttributesMismatch(
        self: *Checker,
        tag: NodeId,
        attrs: []const NodeId,
        raw_target: ?TypeId,
        instantiated_target: ?TypeId,
    ) CheckError!void {
        if (!self.jsxHasIntrinsicAttributesDecl(tag) or attrs.len != 1) return;
        const target = raw_target orelse return;
        if (target >= self.interner.pool.typeCount()) return;
        const target_flags = self.interner.pool.flagsOf(target);
        if (!target_flags.is_type_parameter or target_flags.is_union or target_flags.is_intersection) return;
        if (self.hir.kindOf(attrs[0]) != .jsx_spread_attribute) return;
        const spread = hir_mod.jsxSpreadAttributeOf(self.hir, attrs[0]);
        const source = try self.checkedExpressionType(spread.expression);
        if (source >= self.interner.pool.typeCount()) return;
        const source_flags = self.interner.pool.flagsOf(source);
        if (!source_flags.is_type_parameter or source_flags.is_union or source_flags.is_intersection) return;
        if (self.typeParameterConstraint(source) != null) return;
        if (instantiated_target == null or instantiated_target.? != source) return;

        const source_name = (try self.allocSimpleTypeName(source)) orelse return;
        const message = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' is not assignable to type 'IntrinsicAttributes & {s}'.",
            .{ source_name, source_name },
        );
        const chain = try self.diag_arena.allocator().dupe(DiagnosticChainEntry, &.{.{
            .code = TsCodes.type_not_assignable,
            .message = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Type '{s}' is not assignable to type 'IntrinsicAttributes'.",
                .{source_name},
            ),
        }});
        var related: []const RelatedInfo = &.{};
        if (self.typeParameterDeclForType(source)) |decl| {
            related = try self.diag_arena.allocator().dupe(RelatedInfo, &.{.{
                .node = decl,
                .code = TsCodes.type_parameter_might_need_extends_constraint,
                .message = "This type parameter might need an `extends JSX.IntrinsicAttributes` constraint.",
            }});
        }
        try self.diagnostics.append(self.gpa, .{
            .node = tag,
            .code = TsCodes.type_not_assignable,
            .message = message,
            .chain = chain,
            .related = related,
        });
    }

    /// Finalize JSX inference candidates using tsgo's `getInferredType`
    /// constraint rule: an inferred candidate that does not satisfy the
    /// instantiated constraint is discarded and the constraint itself
    /// becomes the inferred type.
    fn normalizeJsxInferenceConstraints(
        self: *Checker,
        target: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        var visited: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
        defer visited.deinit(self.gpa);
        try self.normalizeJsxInferenceConstraintsInner(target, subs, &visited);
    }

    fn normalizeJsxInferenceConstraintsInner(
        self: *Checker,
        t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
        visited: *std.AutoHashMapUnmanaged(TypeId, void),
    ) CheckError!void {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return;
        if (visited.contains(t)) return;
        try visited.put(self.gpa, t, {});
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                try self.normalizeJsxInferenceConstraintsInner(member, subs, visited);
            }
            return;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                try self.normalizeJsxInferenceConstraintsInner(member, subs, visited);
            }
            return;
        }
        if (flags.is_type_parameter) {
            if (self.isThisTypeParameter(t)) return;
            const candidate = subs.get(t) orelse return;
            const raw_constraint = self.typeParameterConstraint(t) orelse return;
            if (raw_constraint == t) return;
            const constraint = self.substituteType(raw_constraint, subs) catch raw_constraint;
            if (!(self.engine.isAssignableTo(candidate, constraint) catch false)) {
                try subs.put(self.gpa, t, constraint);
            }
            return;
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |member| {
                try self.normalizeJsxInferenceConstraintsInner(member.type, subs, visited);
            }
            const string_index = self.interner.objectStringIndex(t);
            if (string_index != types.Primitive.none) {
                try self.normalizeJsxInferenceConstraintsInner(string_index, subs, visited);
            }
            const number_index = self.interner.objectNumberIndex(t);
            if (number_index != types.Primitive.none) {
                try self.normalizeJsxInferenceConstraintsInner(number_index, subs, visited);
            }
            return;
        }
        if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |param_t| {
                try self.normalizeJsxInferenceConstraintsInner(param_t, subs, visited);
            }
            if (self.interner.signatureReturn(t)) |return_t| {
                try self.normalizeJsxInferenceConstraintsInner(return_t, subs, visited);
            }
        }
    }

    fn collectJsxUnfixedTypeParamFallbacks(
        self: *Checker,
        t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
        visited: *std.AutoHashMapUnmanaged(TypeId, void),
    ) CheckError!void {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return;
        if (visited.contains(t)) return;
        try visited.put(self.gpa, t, {});
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) {
            if (self.isThisTypeParameter(t) or subs.contains(t)) return;
            const payload_idx = self.interner.pool.payloadOf(t);
            const fallback = if (payload_idx < self.interner.pool.type_parameter_payloads.items.len) blk: {
                const payload = self.interner.pool.type_parameter_payloads.items[payload_idx];
                break :blk if (payload.default != types.Primitive.none)
                    self.substituteType(payload.default, subs) catch payload.default
                else if (self.typeParameterConstraint(t)) |raw_constraint|
                    self.substituteType(raw_constraint, subs) catch raw_constraint
                else
                    types.Primitive.unknown;
            } else types.Primitive.unknown;
            try subs.put(self.gpa, t, fallback);
            return;
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                try self.collectJsxUnfixedTypeParamFallbacks(member, subs, visited);
            }
            return;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                try self.collectJsxUnfixedTypeParamFallbacks(member, subs, visited);
            }
            return;
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |member| {
                try self.collectJsxUnfixedTypeParamFallbacks(member.type, subs, visited);
            }
            const string_index = self.interner.objectStringIndex(t);
            if (string_index != types.Primitive.none) {
                try self.collectJsxUnfixedTypeParamFallbacks(string_index, subs, visited);
            }
            const number_index = self.interner.objectNumberIndex(t);
            if (number_index != types.Primitive.none) {
                try self.collectJsxUnfixedTypeParamFallbacks(number_index, subs, visited);
            }
            return;
        }
        if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |param_t| {
                try self.collectJsxUnfixedTypeParamFallbacks(param_t, subs, visited);
            }
            if (self.interner.signatureReturn(t)) |return_t| {
                try self.collectJsxUnfixedTypeParamFallbacks(return_t, subs, visited);
            }
        }
    }

    fn jsxFixDirectPropsInference(
        self: *Checker,
        target: TypeId,
        evidence: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        if (target >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(target);
        if (flags.is_type_parameter and !flags.is_union and !flags.is_intersection) {
            try subs.put(self.gpa, target, evidence);
            return;
        }
        if (!flags.is_intersection) return;
        for (self.interner.intersectionMembers(target)) |member| {
            if (member >= self.interner.pool.typeCount()) continue;
            const member_flags = self.interner.pool.flagsOf(member);
            if (member_flags.is_intersection) {
                try self.jsxFixDirectPropsInference(member, evidence, subs);
                continue;
            }
            if (!member_flags.is_type_parameter or member_flags.is_union or member_flags.is_intersection) continue;
            try subs.put(self.gpa, member, evidence);
        }
    }

    fn unwrapJsxSpreadObjectExpression(self: *Checker, expr: NodeId) NodeId {
        var cur = expr;
        while (cur != hir_mod.none_node_id) {
            switch (self.hir.kindOf(cur)) {
                .spread => cur = hir_mod.spreadOf(self.hir, cur).expression,
                .as_expr, .type_assertion, .satisfies_expr, .non_null_expr => cur = hir_mod.asExpressionOf(self.hir, cur).expr,
                else => return cur,
            }
        }
        return hir_mod.none_node_id;
    }

    fn checkJsxSpreadContextualCallbacks(self: *Checker, expr: NodeId, props_t: ?TypeId, tag: NodeId) CheckError!void {
        const object_expr = self.unwrapJsxSpreadObjectExpression(expr);
        if (object_expr == hir_mod.none_node_id or self.hir.kindOf(object_expr) != .object_literal) return;
        for (hir_mod.objectLiteralProps(self.hir, object_expr)) |prop| {
            if (self.hir.kindOf(prop) != .object_property) continue;
            const op = hir_mod.objectPropertyOf(self.hir, prop);
            if (op.is_computed) continue;
            const name = self.propertyNameFromKeyNode(op.key) orelse continue;
            const prop_t = (try self.jsxContextualPropType(props_t, tag, name)) orelse continue;
            if (op.value != hir_mod.none_node_id and self.jsxValueIsFunctionLike(op.value)) {
                if (self.firstSignatureType(prop_t)) |sig| {
                    try self.checkFunctionWithContextualSignature(op.value, sig);
                } else if (self.typeIsAnyLike(prop_t)) {
                    self.removeImplicitAnyDiagnosticsWithin(op.value);
                }
            }
        }
    }

    fn jsxNoOverloadAnchor(self: *Checker, tag: NodeId, value_mismatch: ?NodeId) NodeId {
        _ = self;
        // `resolveJsxOpeningLikeElement` reports applicability failures
        // against the JSX tag name. Attribute-level elaborations may hang
        // below that diagnostic. When a post-spread explicit value causes
        // the mismatch, JSX elaboration moves the TS2769 head to that
        // attribute. Structural post-spread failures are anchored
        // separately by `jsxAttrsStructuralMismatchAnchor`.
        return value_mismatch orelse tag;
    }

    /// Construct (preferred) or call signatures of a non-union tag
    /// type, returned only when there are at least two. tsgo's
    /// `resolveCall` reports TS2769 ("No overload matches this call.")
    /// only with multiple candidates; a single failing signature
    /// reports the plain assignability error instead. Union tag types
    /// collapse into one composite signature via `getUnionSignatures`,
    /// so they never take this path (`tsxUnionElementType3/6` keep
    /// TS2322/TS2741), and an `ElementAttributesProperty`-driven tag
    /// resolves props from the instance type rather than the
    /// constructor parameter list (`tsxElementResolution11/12`), so
    /// both are excluded here. Mirrors `tsxElementResolution9`, where
    /// `<Obj1 />` against `new(n: string)` / `new(n: number)` reports
    /// TS2769 anchored at the tag.
    fn jsxTagInterfaceOverloads(self: *Checker, tag: NodeId) CheckError!?[]TypeId {
        if (self.jsxTagVisibleOverloads(tag) != null) return null; // declared overloads own the TS2769 path
        if (tag == hir_mod.none_node_id) return null;
        // Intrinsic tags (`<test1>`) name `JSX.IntrinsicElements`
        // members, not in-scope values — evaluating the tag as an
        // expression would report spurious TS2304 "Cannot find name".
        if (self.jsxTagIsIntrinsic(tag)) return null;
        if ((try self.jsxElementAttributesPropertyDecl(tag)) != null) return null;
        const tag_t = try self.checkedExpressionType(tag);
        if (tag_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(tag_t);
        if (flags.is_union or flags.is_any or flags.is_unknown or flags.is_intersection) return null;
        var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer sigs.deinit(self.gpa);
        try self.collectConstructSignatures(tag_t, &sigs);
        if (sigs.items.len == 0) try self.collectCallSignatures(tag_t, &sigs);
        if (sigs.items.len < 2) return null;
        return try self.diag_arena.allocator().dupe(TypeId, sigs.items);
    }

    fn jsxAttributesMatchSignatures(
        self: *Checker,
        anchor: NodeId,
        sigs: []const TypeId,
        attrs_t: TypeId,
        has_spread: bool,
        has_generic_spread: bool,
        explicit_attrs_t: TypeId,
    ) CheckError!bool {
        for (sigs) |sig| {
            const params = self.interner.signatureParams(sig);
            if (params.len == 0) {
                if (try self.jsxAttrsBagHasOnlyIgnoredMembers(attrs_t)) return true;
                continue;
            }
            var target = params[0];
            const target_had_free = self.containsFreeTypeParameter(target);
            if (target_had_free) {
                var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                defer subs.deinit(self.gpa);
                try self.inferFromPair(target, attrs_t, &subs);
                if (subs.count() > 0) {
                    target = self.substituteType(target, &subs) catch target;
                }
            }
            const excess_attrs_t = if (has_spread) explicit_attrs_t else attrs_t;
            const no_excess = has_generic_spread or
                try self.jsxAttrsHaveNoExcessMembersForTarget(anchor, excess_attrs_t, target);
            if (no_excess and self.engine.isAssignableTo(attrs_t, target) catch false) return true;
            if (no_excess and
                try self.jsxRequiredPropsAssignable(target, attrs_t) and
                try self.jsxAttributeBagValuesAssignable(attrs_t, target))
            {
                return true;
            }
            if (no_excess and target_had_free and try self.jsxRequiredPropsAssignable(target, attrs_t)) return true;
        }
        return false;
    }

    /// tsc reports a value-vs-intersection mismatch against the FIRST
    /// constituent that fails (the relater descends into intersection
    /// targets and keeps the first sub-error), never against the whole
    /// intersection. Mirrors `tsxUnionElementType3` line 34, where
    /// `x="Hi"` against the `{ x: number; } & { x: string; }` props
    /// intersection's `number & string` member renders as
    /// `Type 'string' is not assignable to type 'number'.`
    fn firstFailingIntersectionMember(self: *Checker, value_t: TypeId, target_t: TypeId) CheckError!TypeId {
        if (target_t >= self.interner.pool.typeCount()) return target_t;
        if (!self.interner.pool.flagsOf(target_t).is_intersection) return target_t;
        for (self.interner.intersectionMembers(target_t)) |member| {
            if (!(self.engine.isAssignableTo(value_t, member) catch false)) return member;
        }
        return target_t;
    }

    fn jsxAttrsStructuralMismatchAnchor(self: *Checker, tag: NodeId, attrs: []const NodeId, target: TypeId) CheckError!NodeId {
        var saw_spread = false;
        for (attrs) |attr| {
            switch (self.hir.kindOf(attr)) {
                .jsx_spread_attribute => saw_spread = true,
                .jsx_attribute => {
                    if (!saw_spread) continue;
                    const a = hir_mod.jsxAttributeOf(self.hir, attr);
                    if ((try self.lookupObjectMember(target, a.name)) == null) return attr;
                },
                else => {},
            }
        }
        return tag;
    }

    fn jsxAttributesMatchOverload(
        self: *Checker,
        tag: NodeId,
        attrs_t: TypeId,
        has_spread: bool,
        has_generic_spread: bool,
        explicit_attrs_t: TypeId,
    ) CheckError!bool {
        const overloads = self.jsxTagVisibleOverloads(tag) orelse return false;
        for (overloads) |sig| {
            const params = self.interner.signatureParams(sig);
            if (params.len == 0) {
                if (try self.jsxAttrsBagHasOnlyIgnoredMembers(attrs_t)) return true;
                continue;
            }
            var target = params[0];
            const target_had_free = self.containsFreeTypeParameter(target);
            if (target_had_free) {
                var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                defer subs.deinit(self.gpa);
                try self.inferFromPair(target, attrs_t, &subs);
                if (subs.count() > 0) {
                    target = self.substituteType(target, &subs) catch target;
                }
            }
            const excess_attrs_t = if (has_spread) explicit_attrs_t else attrs_t;
            const no_excess = has_generic_spread or
                try self.jsxAttrsHaveNoExcessMembersForTarget(tag, excess_attrs_t, target);
            if (no_excess and self.engine.isAssignableTo(attrs_t, target) catch false) return true;
            if (no_excess and
                try self.jsxRequiredPropsAssignable(target, attrs_t) and
                try self.jsxAttributeBagValuesAssignable(attrs_t, target))
            {
                return true;
            }
            if (no_excess and target_had_free and try self.jsxRequiredPropsAssignable(target, attrs_t)) return true;
        }
        return false;
    }

    fn jsxExplicitAttributesBagType(self: *Checker, attrs: []const NodeId) CheckError!TypeId {
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        for (attrs) |attr| {
            if (self.hir.kindOf(attr) != .jsx_attribute) continue;
            const jsx_attr = hir_mod.jsxAttributeOf(self.hir, attr);
            try self.appendOrReplaceObjectMember(&members, .{
                .name = jsx_attr.name,
                .type = types.Primitive.any,
                .is_optional = false,
                .is_readonly = false,
                .is_method = false,
            });
        }
        return self.interner.internObjectType(members.items) catch return error.OutOfMemory;
    }

    fn jsxAttrsBagHasOnlyIgnoredMembers(self: *Checker, attrs_t: TypeId) CheckError!bool {
        if (attrs_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(attrs_t).is_object_type) return false;
        const key_name = self.string_interner.intern("key") catch return error.OutOfMemory;
        for (self.interner.objectMembers(attrs_t)) |member| {
            if (member.name == key_name) continue;
            if (std.mem.indexOfScalar(u8, self.string_interner.get(member.name), '-') != null) continue;
            return false;
        }
        return true;
    }

    fn jsxAttrsHaveNoExcessMembersForTarget(self: *Checker, anchor: NodeId, attrs_t: TypeId, target: TypeId) CheckError!bool {
        if (target >= self.interner.pool.typeCount() or attrs_t >= self.interner.pool.typeCount()) return true;
        const target_flags = self.interner.pool.flagsOf(target);
        if (target_flags.is_any or target_flags.is_unknown or target_flags.is_type_parameter) return true;
        if (target_flags.is_union) {
            for (self.interner.unionMembers(target)) |member| {
                if (try self.jsxAttrsHaveNoExcessMembersForTarget(anchor, attrs_t, member)) return true;
            }
            return false;
        }
        // When a `JSX.IntrinsicAttributes` declaration is in scope,
        // tsc's real attributes target is `IntrinsicAttributes & T`
        // whose `key` member makes the intersection non-empty — an
        // otherwise-empty `T` must NOT be exempted from excess
        // checking (`checkJsxChildrenProperty15` flags `children`
        // against `IntrinsicAttributes & {}`). Home doesn't load the
        // react lib, so the IntrinsicAttributes half never
        // materialises structurally; gate the empty-target exemption
        // on the declaration being OUT of scope instead.
        const ia_in_scope = self.jsxHasIntrinsicAttributesDecl(anchor);
        var any_string_index = false;
        if (target_flags.is_intersection) {
            // tsgo's excess-property relation flattens intersection
            // targets: an attribute is excess only when it is unmatched
            // in EVERY constituent (a member declared by any single
            // constituent is matched), and never when the flattened
            // intersection declares no members at all. Fall through to
            // the per-attribute scan below, where
            // `lookupObjectMember` performs the any-constituent lookup
            // (`checkJsxChildrenProperty15`'s
            // `IntrinsicAttributes & {}` still flags `children`).
            var total_members: usize = 0;
            for (self.interner.intersectionMembers(target)) |member| {
                if (member >= self.interner.pool.typeCount()) continue;
                const member_flags = self.interner.pool.flagsOf(member);
                if (!member_flags.is_object_type) continue;
                total_members += self.interner.objectMembers(member).len;
                if (self.interner.objectStringIndex(member) != types.Primitive.none) any_string_index = true;
            }
            if (total_members == 0 and !any_string_index and !ia_in_scope) return true;
        } else {
            if (!target_flags.is_object_type) return true;
            // An EMPTY object target (`{}`) accepts any attributes bag
            // when no IntrinsicAttributes declaration is in scope —
            // with no declared members there is nothing to be excess
            // against (`checkJsxChildrenProperty10/11`,
            // `<Button>...</Button>` with `props: {}`).
            if (!ia_in_scope and
                self.interner.objectMembers(target).len == 0 and
                self.interner.objectStringIndex(target) == types.Primitive.none and
                self.interner.objectNumberIndex(target) == types.Primitive.none) return true;
        }
        if (!target_flags.is_object_type and !target_flags.is_intersection) return true;
        const attrs_flags = self.interner.pool.flagsOf(attrs_t);
        if (!attrs_flags.is_object_type) return true;
        const key_name = self.string_interner.intern("key") catch return error.OutOfMemory;
        const target_has_string_index = any_string_index or
            (target_flags.is_object_type and self.interner.objectStringIndex(target) != types.Primitive.none);
        // `lookupObjectMember` may instantiate a generic alias and grow the
        // object-member pool. Snapshot the attribute members so that growth
        // cannot invalidate this loop's borrowed slice and turn a later name
        // into a poisoned StringId.
        var attr_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer attr_members.deinit(self.gpa);
        try attr_members.appendSlice(self.gpa, self.interner.objectMembers(attrs_t));
        for (attr_members.items) |attr_member| {
            if (attr_member.name == key_name) continue;
            // tsgo's `isIgnoredJsxProperty` exempts every hyphenated
            // JSX name from excess-property checking, not only the
            // conventional `data-*` family.
            if (std.mem.indexOfScalar(u8, self.string_interner.get(attr_member.name), '-') != null) continue;
            if ((try self.lookupObjectMember(target, attr_member.name)) != null) continue;
            if (target_has_string_index) continue;
            return false;
        }
        return true;
    }

    fn jsxRequiredPropsAssignable(self: *Checker, target: TypeId, attrs_t: TypeId) CheckError!bool {
        if (target >= self.interner.pool.typeCount()) return true;
        const flags = self.interner.pool.flagsOf(target);
        if (flags.is_type_parameter) return true;
        if (flags.is_union) {
            for (self.interner.unionMembers(target)) |member| {
                if (try self.jsxRequiredPropsAssignable(member, attrs_t)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(target)) |member| {
                if (!try self.jsxRequiredPropsAssignable(member, attrs_t)) return false;
            }
            return true;
        }
        if (!flags.is_object_type) return false;
        for (self.interner.objectMembers(target)) |member| {
            if (member.is_optional) continue;
            const attr_t = self.interner.objectMember(attrs_t, member.name) orelse {
                if (try self.broadObjectPrototypeMember(member.name)) |inherited_t| {
                    if (self.containsFreeTypeParameter(member.type) or
                        try self.jsxAttributeAssignable(inherited_t, member.type))
                    {
                        continue;
                    }
                }
                return false;
            };
            if (self.containsFreeTypeParameter(member.type)) continue;
            if (!try self.jsxAttributeAssignable(attr_t, member.type)) return false;
        }
        return true;
    }

    fn jsxAttributeBagValuesAssignable(self: *Checker, attrs_t: TypeId, target: TypeId) CheckError!bool {
        if (attrs_t >= self.interner.pool.typeCount() or target >= self.interner.pool.typeCount()) return true;
        const attrs_flags = self.interner.pool.flagsOf(attrs_t);
        if (!attrs_flags.is_object_type) return true;

        // lookupObjectMember may instantiate aliases and grow the interner.
        // Keep an owned snapshot while validating spread-provided members.
        var attrs: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer attrs.deinit(self.gpa);
        try attrs.appendSlice(self.gpa, self.interner.objectMembers(attrs_t));
        const key_name = self.string_interner.intern("key") catch return error.OutOfMemory;
        for (attrs.items) |attr| {
            if (attr.name == key_name) continue;
            if (try self.lookupObjectMember(target, attr.name)) |prop_t| {
                if (!try self.jsxAttributeAssignable(attr.type, prop_t)) return false;
                continue;
            }
            if (!try self.jsxAttributeAssignableToTargetIndexes(attr.type, target)) return false;
        }
        return true;
    }

    fn jsxAttributeAssignableToTargetIndexes(self: *Checker, attr_t: TypeId, target: TypeId) CheckError!bool {
        if (target >= self.interner.pool.typeCount()) return true;
        const flags = self.interner.pool.flagsOf(target);
        if (flags.is_any or flags.is_unknown or flags.is_type_parameter) return true;
        if (flags.is_union) {
            for (self.interner.unionMembers(target)) |member| {
                if (try self.jsxAttributeAssignableToTargetIndexes(attr_t, member)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(target)) |member| {
                if (!try self.jsxAttributeAssignableToTargetIndexes(attr_t, member)) return false;
            }
            return true;
        }
        if (!flags.is_object_type) return true;
        const index_t = self.interner.objectStringIndex(target);
        if (index_t == types.Primitive.none) return true;
        return try self.jsxAttributeAssignable(attr_t, index_t);
    }


    fn jsxRequiredPropsCovered(self: *Checker, target: TypeId, attrs_t: TypeId) CheckError!bool {
        if (target >= self.interner.pool.typeCount()) return true;
        const flags = self.interner.pool.flagsOf(target);
        if (flags.is_type_parameter) return true;
        if (flags.is_union) {
            for (self.interner.unionMembers(target)) |member| {
                if (try self.jsxRequiredPropsCovered(member, attrs_t)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(target)) |member| {
                if (!try self.jsxRequiredPropsCovered(member, attrs_t)) return false;
            }
            return true;
        }
        if (!flags.is_object_type) return false;
        for (self.interner.objectMembers(target)) |member| {
            if (member.is_optional) continue;
            if (self.interner.objectMember(attrs_t, member.name) != null) continue;
            if ((try self.broadObjectPrototypeMember(member.name)) != null) continue;
            return false;
        }
        return true;
    }

    fn checkJsxSpreadOverwritesExplicitAttrs(
        self: *Checker,
        spread_t: TypeId,
        spread_node: NodeId,
        attrs: []const NodeId,
    ) CheckError!void {
        if (spread_t >= self.interner.pool.typeCount()) return;
        // tsc only warns about an overwritten attribute when the spread
        // *definitely* supplies that property. A `{...a}` spread whose type
        // is `any`/`unknown` (e.g. `tsxEmitSpreadAttribute` declares the
        // spread args as `any`) does not — `getPropertyOfType` on `any`
        // yields `any` for every name, which would otherwise flag every
        // explicit attribute placed before the spread. Skip those.
        {
            const sflags = self.interner.pool.flagsOf(spread_t);
            if (sflags.is_any or sflags.is_unknown) return;
        }
        for (attrs) |attr| {
            if (self.hir.kindOf(attr) != .jsx_attribute) continue;
            const a = hir_mod.jsxAttributeOf(self.hir, attr);
            if ((try self.lookupObjectMember(spread_t, a.name)) != null) {
                // tsc names the duplicated attribute: `'x' is
                // specified more than once, so this usage will be
                // overwritten.` Match that wording so exact-mode
                // baselines (e.g. `tsxAttributeResolution3`) line up.
                try self.reportPropertyOverwriteWithSpreadRelated(attr, spread_node, a.name);
            }
        }
    }

    fn reportPropertyOverwriteWithSpreadRelated(
        self: *Checker,
        overwritten_node: NodeId,
        spread_node: NodeId,
        name: hir_mod.StringId,
    ) CheckError!void {
        const name_str = self.string_interner.get(name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' is specified more than once, so this usage will be overwritten.",
            .{name_str},
        );
        const related = try self.diag_arena.allocator().dupe(RelatedInfo, &.{.{
            .node = spread_node,
            .code = TsCodes.spread_always_overwrites_property,
            .message = "This spread always overwrites this property.",
        }});
        try self.diagnostics.append(self.gpa, .{
            .node = overwritten_node,
            .code = TsCodes.jsx_attribute_overwritten,
            .message = msg,
            .related = related,
        });
    }

    /// Returns true when the props target carries at least one named
    /// member that ISN'T `children`. Empty `{}` and a props type that
    /// only declares `children` both return false ÃÂ¢ÃÂÃÂ the former opts
    /// out of excess-property checks entirely, the latter is already
    /// handled by the dedicated `children`-member lookup. Mirrors
    /// `checkJsxChildrenProperty10` baseline where `props: {}` doesn't
    /// trigger TS2353 on the JSX children block.
    fn jsxPropsTargetHasNonChildrenMember(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.jsxPropsTargetHasNonChildrenMember(constraint);
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.jsxPropsTargetHasNonChildrenMember(member)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.jsxPropsTargetHasNonChildrenMember(member)) return true;
            }
            return false;
        }
        if (!flags.is_object_type) return false;
        for (self.interner.objectMembers(t)) |m| {
            const name = self.string_interner.get(m.name);
            if (!std.mem.eql(u8, name, "children")) return true;
        }
        return false;
    }

    fn jsxPropsTargetHasNamedMembers(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.jsxPropsTargetHasNamedMembers(constraint);
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.jsxPropsTargetHasNamedMembers(member)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.jsxPropsTargetHasNamedMembers(member)) return true;
            }
            return false;
        }
        return flags.is_object_type;
    }

    fn jsxPropsTargetIsAnyLike(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.jsxPropsTargetIsAnyLike(member)) return true;
            }
        }
        return false;
    }

    fn jsxPropsHasNamedMember(self: *Checker, t: TypeId, name: hir_mod.StringId) CheckError!bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return try self.jsxPropsHasNamedMember(constraint, name);
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (try self.jsxPropsHasNamedMember(member, name)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (try self.jsxPropsHasNamedMember(member, name)) return true;
            }
            return false;
        }
        if (self.interner.objectMember(t, name) != null) return true;
        // String index signature (`{ [k: string]: V }`) accepts ANY
        // string-keyed attribute ÃÂ¢ÃÂÃÂ without this fallback the upstream
        // TS2353 "JSX attribute does not exist on target props." was
        // misfiring on indexer-typed component props
        // (`tsxAttributeResolution10` baseline).
        return flags.is_object_type and self.interner.objectStringIndex(t) != types.Primitive.none;
    }

    fn jsxChildrenTypeAllowsCount(self: *Checker, t: TypeId, count: usize) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_any) return true;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.jsxChildrenTypeAllowsCount(member, count)) return true;
            }
            return false;
        }
        if (self.fixedTupleLength(t)) |length| return count <= length;
        if (flags.is_object_type and self.interner.objectNumberIndex(t) != types.Primitive.none) return true;
        return count <= 1;
    }

    fn jsxChildrenTypeRequiresMoreThanCount(self: *Checker, t: TypeId, count: usize) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_any) return false;
        if (flags.is_union) {
            var saw_member = false;
            for (self.interner.unionMembers(t)) |member| {
                saw_member = true;
                if (!self.jsxChildrenTypeRequiresMoreThanCount(member, count)) return false;
            }
            return saw_member;
        }
        if (self.fixedTupleLength(t) != null) return self.tupleFixedPrefixCount(t) > count;
        return false;
    }

    fn jsxChildrenTypeAllowsString(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_any or flags.is_string) return true;
        if (flags.is_literal and flags.is_string) return true;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.jsxChildrenTypeAllowsString(member)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.jsxChildrenTypeAllowsString(member)) return true;
            }
            return false;
        }
        const elem_t = self.interner.objectNumberIndex(t);
        return elem_t != types.Primitive.none and self.jsxChildrenTypeAllowsString(elem_t);
    }

    /// Member type for the synthesized `children` member of the JSX
    /// attributes bag, mirroring tsgo's `checkJsxChildren` +
    /// `createJsxAttributesTypeFromAttributesProperty`: whitespace-only
    /// text and empty `{}` expressions don't count; text contributes
    /// `string`; element and expression children contribute their own
    /// type (a nested JSX element types as `JSX.Element`). A single
    /// child contributes its type directly; several children
    /// contribute an array of the union
    /// (`checkJsxChildrenProperty15`: `children: Element` /
    /// `children: Element[]`). When the contextual `children` prop is
    /// a tuple (`[ReactNode, ReactNode]` in
    /// `checkJsxChildrenCanBeTupleType`) the children group as a tuple
    /// instead so element-wise assignability sees the same shape.
    fn jsxChildrenMemberType(self: *Checker, children: []const NodeId, contextual_children_t: ?TypeId) CheckError!TypeId {
        var child_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer child_types.deinit(self.gpa);
        for (children) |child| {
            switch (self.hir.kindOf(child)) {
                // React ignores whitespace-only JSX text.
                .jsx_text => {
                    const text = self.nodeSourceTextOrEmpty(child);
                    if (std.mem.trim(u8, text, " \t\r\n").len == 0) continue;
                    try child_types.append(self.gpa, types.Primitive.string_t);
                },
                .literal_string => {
                    const text = self.nodeSourceTextOrEmpty(child);
                    if (std.mem.trim(u8, text, " \t\r\n").len == 0) continue;
                    try child_types.append(self.gpa, types.Primitive.string_t);
                },
                .jsx_expression => {
                    const ex = hir_mod.jsxExpressionOf(self.hir, child);
                    if (ex.expression == hir_mod.none_node_id) continue;
                    try child_types.append(self.gpa, try self.checkedExpressionType(child));
                },
                else => try child_types.append(self.gpa, try self.checkedExpressionType(child)),
            }
        }
        if (child_types.items.len == 0) return types.Primitive.any;
        if (child_types.items.len == 1) return child_types.items[0];
        if (contextual_children_t) |ctx| {
            var wants_tuple = self.actualTupleLength(ctx) != null;
            if (!wants_tuple and ctx < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(ctx).is_union)
            {
                for (self.interner.unionMembers(ctx)) |member| {
                    if (self.actualTupleLength(member) != null) {
                        wants_tuple = true;
                        break;
                    }
                }
            }
            if (wants_tuple) return try self.internTupleFromTypes(child_types.items, false);
        }
        const union_t = self.interner.internUnion(child_types.items) catch return error.OutOfMemory;
        return self.interner.internArrayType(self.string_interner, union_t) catch return error.OutOfMemory;
    }

    /// Collect an object type's members in tsc's `getPropertiesOfType`
    /// order for class instances: the subclass's own members first (in
    /// interned order), then the base chain's members recursively,
    /// skipping names already seen. Home merges inherited members into
    /// the subclass object type inherited-first, so the own subset is
    /// recovered by dropping members whose `decl_node` matches a member
    /// of the recorded base type (inherited members are copied verbatim
    /// and keep their original declaration node). Members with no
    /// declaration node are synthetic (e.g. the synthetic
    /// React.Component surface) and also count as inherited — a
    /// source-declared override always carries its own node
    /// (`checkJsxChildrenProperty5`: `render, setState, …` not
    /// `setState, forceUpdate, render, …`).
    fn objectMembersOwnThenInherited(
        self: *Checker,
        t: TypeId,
        out: *std.ArrayListUnmanaged(types.ObjectMember),
    ) CheckError!void {
        var seen: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer seen.deinit(self.gpa);
        try self.collectObjectMembersOwnThenInherited(t, &seen, out, 0);
    }

    fn collectObjectMembersOwnThenInherited(
        self: *Checker,
        t: TypeId,
        seen: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
        out: *std.ArrayListUnmanaged(types.ObjectMember),
        depth: usize,
    ) CheckError!void {
        if (depth > 16) return;
        if (t >= self.interner.pool.typeCount()) return;
        if (!self.interner.pool.flagsOf(t).is_object_type) return;
        const members = self.interner.objectMembers(t);
        if (self.decl_single_base.get(t)) |bt| {
            if (bt < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(bt).is_object_type)
            {
                var inherited_decls: std.AutoHashMapUnmanaged(NodeId, void) = .empty;
                defer inherited_decls.deinit(self.gpa);
                for (self.interner.objectMembers(bt)) |bm| {
                    if (bm.decl_node != hir_mod.none_node_id)
                        try inherited_decls.put(self.gpa, bm.decl_node, {});
                }
                for (members) |m| {
                    if (m.decl_node == hir_mod.none_node_id or
                        inherited_decls.contains(m.decl_node)) continue;
                    if (seen.contains(m.name)) continue;
                    try seen.put(self.gpa, m.name, {});
                    try out.append(self.gpa, m);
                }
                try self.collectObjectMembersOwnThenInherited(bt, seen, out, depth + 1);
                return;
            }
        }
        for (members) |m| {
            if (seen.contains(m.name)) continue;
            try seen.put(self.gpa, m.name, {});
            try out.append(self.gpa, m);
        }
    }

    /// tsc's `getNormalizedType` single step: a type whose declaration
    /// adds zero own members and exactly one base normalises to that
    /// base. Own members are recovered the same way as in
    /// `collectObjectMembersOwnThenInherited` — any member whose
    /// `decl_node` is not a verbatim copy of a base member blocks
    /// normalisation. Explicit display bases (the synthetic
    /// JSX.Element registration) win over the structural rule.
    fn normalizedRelationBase(self: *Checker, t: TypeId) CheckError!?TypeId {
        if (self.relation_display_base.get(t)) |explicit| {
            if (explicit != t) return explicit;
            return null;
        }
        const bt = self.decl_single_base.get(t) orelse return null;
        if (bt == t or bt >= self.interner.pool.typeCount()) return null;
        if (t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(t).is_object_type) return null;
        if (!self.interner.pool.flagsOf(bt).is_object_type) return null;
        var inherited_decls: std.AutoHashMapUnmanaged(NodeId, void) = .empty;
        defer inherited_decls.deinit(self.gpa);
        for (self.interner.objectMembers(bt)) |bm| {
            if (bm.decl_node != hir_mod.none_node_id)
                try inherited_decls.put(self.gpa, bm.decl_node, {});
        }
        for (self.interner.objectMembers(t)) |m| {
            if (m.decl_node != hir_mod.none_node_id and
                inherited_decls.contains(m.decl_node)) continue;
            return null;
        }
        return bt;
    }

    /// Render a type the way tsc's relation elaborations render it:
    /// `getNormalizedType` collapses a type whose declaration adds no
    /// own members and exactly one base to that base — looping — before
    /// `typeToString` runs inside TS2739/TS2740 prose, while TS2322
    /// heads keep the original spelling (`checkJsxChildrenProperty5`:
    /// a standalone `Element` child renders `ReactElement<any>` in the
    /// missing-properties message). Types without a display base render
    /// normally.
    fn normalizedRelationDisplayName(self: *Checker, t: TypeId) CheckError!?[]const u8 {
        var current = t;
        var hops: usize = 0;
        while (hops < 8) : (hops += 1) {
            const next = (try self.normalizedRelationBase(current)) orelse break;
            current = next;
        }
        return try self.allocSimpleTypeName(current);
    }

    /// TS2741/TS2739/TS2740 elaboration for a JSX child that doesn't
    /// fit the declared `children` type — the faithful port of tsgo's
    /// `elaborateElement` → `reportUnmatchedProperties` →
    /// `getUnmatchedProperties(source, target, requireOptionalProperties=true, …)`.
    /// Every target member the source lacks is listed (methods
    /// included, own members before inherited via
    /// `objectMembersOwnThenInherited`); the source renders through
    /// `getNormalizedType` (see `relation_display_base`). Returns true
    /// when a diagnostic was emitted.
    fn tryReportJsxChildMissingProperties(self: *Checker, anchor: NodeId, source: TypeId, target: TypeId) CheckError!bool {
        if (target >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(target).is_object_type) return false;
        if (source == types.Primitive.any or source == types.Primitive.unknown or
            source == types.Primitive.none)
        {
            return false;
        }
        if (source >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(source).is_object_type) return false;

        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        try self.objectMembersOwnThenInherited(target, &members);

        var missing: [8]hir_mod.StringId = undefined;
        var missing_listed: usize = 0;
        var missing_total: usize = 0;
        for (members.items) |tm| {
            if ((try self.lookupObjectMember(source, tm.name)) != null) continue;
            missing_total += 1;
            if (missing_listed < missing.len) {
                missing[missing_listed] = tm.name;
                missing_listed += 1;
            }
        }
        if (missing_total == 0) return false;

        const target_name = (try self.allocSimpleTypeName(target)) orelse return false;
        const source_name = (try self.normalizedRelationDisplayName(source)) orelse return false;

        if (missing_total == 1) {
            const prop_text = try self.formatMissingPropertyNameForDiagnostic(
                self.string_interner.get(missing[0]),
                target_name,
            );
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Property '{s}' is missing in type '{s}' but required in type '{s}'.",
                .{ prop_text, source_name, target_name },
            );
            try self.report(anchor, TsCodes.property_missing_required, msg);
            return true;
        }
        const list_count = if (missing_total > 5) @as(usize, 4) else missing_total;
        var names_buf: std.ArrayListUnmanaged(u8) = .empty;
        defer names_buf.deinit(self.gpa);
        var i: usize = 0;
        while (i < list_count and i < missing_listed) : (i += 1) {
            if (i > 0) try names_buf.appendSlice(self.gpa, ", ");
            try names_buf.appendSlice(self.gpa, self.formatPropertyNameForDiagnostic(self.string_interner.get(missing[i])));
        }
        if (missing_total > 5) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Type '{s}' is missing the following properties from type '{s}': {s}, and {d} more.",
                .{ source_name, target_name, names_buf.items, missing_total - 4 },
            );
            try self.report(anchor, TsCodes.type_missing_properties_truncated, msg);
        } else {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Type '{s}' is missing the following properties from type '{s}': {s}",
                .{ source_name, target_name, names_buf.items },
            );
            try self.report(anchor, TsCodes.type_missing_properties, msg);
        }
        return true;
    }

    /// Per-child relation check against the declared `children` type.
    /// Returns true when a diagnostic was reported for this child so
    /// the caller can suppress the whole-bag TS2322/TS2741 — tsgo's
    /// `elaborateJsxComponents` replaces the bag-level error with the
    /// per-child elaborations (`checkJsxChildrenProperty5`). Tuple
    /// children targets check element-wise (arity is diagnosed
    /// separately); `{}` children anchor at the inner expression.
    fn checkJsxChildAssignableToChildrenType(self: *Checker, child: NodeId, child_index: usize, children_t: TypeId) CheckError!bool {
        if (self.typeIsAnyLike(children_t)) return false;
        const target_t = if (self.actualTupleLength(children_t) != null)
            self.tupleElementType(children_t, child_index)
        else
            children_t;
        if (target_t == types.Primitive.none) return false;
        if (self.typeIsAnyLike(target_t)) return false;
        const child_t = try self.checkedExpressionType(child);
        if (self.typeIsAny(child_t)) return false;
        if (try self.jsxChildLiteralAssignableToTarget(child, target_t)) return false;
        if (self.engine.isAssignableTo(child_t, target_t) catch false) return false;
        if (target_t < self.interner.pool.typeCount()) {
            const elem_t = self.interner.objectNumberIndex(target_t);
            if (elem_t != types.Primitive.none and (self.engine.isAssignableTo(child_t, elem_t) catch false)) return false;
        }
        var anchor = child;
        if (self.hir.kindOf(child) == .jsx_expression) {
            const ex = hir_mod.jsxExpressionOf(self.hir, child);
            if (ex.expression != hir_mod.none_node_id) anchor = ex.expression;
        }
        if (try self.tryReportJsxChildMissingProperties(anchor, child_t, target_t)) return true;
        try self.reportTypeNotAssignable(anchor, child_t, target_t, "JSX child is not assignable to the target children type.");
        return true;
    }

    fn jsxChildLiteralAssignableToTarget(self: *Checker, child: NodeId, target_t: TypeId) CheckError!bool {
        var inner = child;
        if (self.hir.kindOf(child) == .jsx_expression) {
            const ex = hir_mod.jsxExpressionOf(self.hir, child);
            if (ex.expression == hir_mod.none_node_id) return target_t == types.Primitive.undefined_t or self.typeIncludesUndefined(target_t);
            inner = ex.expression;
        }
        return try self.literalExpressionAssignableToTarget(inner, target_t);
    }

    fn checkJsxAttributeValue(self: *Checker, value: NodeId) CheckError!TypeId {
        if (value == hir_mod.none_node_id) return types.Primitive.true_lit;
        if (self.hir.kindOf(value) == .jsx_expression) {
            const ex = hir_mod.jsxExpressionOf(self.hir, value);
            if (ex.expression == hir_mod.none_node_id) return types.Primitive.undefined_t;
            return try self.checkExpression(ex.expression);
        }
        return try self.checkExpression(value);
    }

    fn jsxAttributeBagValueType(self: *Checker, value: NodeId, fallback: TypeId) CheckError!TypeId {
        if (value == hir_mod.none_node_id) return types.Primitive.true_lit;
        var inner = value;
        if (self.hir.kindOf(value) == .jsx_expression) {
            const ex = hir_mod.jsxExpressionOf(self.hir, value);
            if (ex.expression == hir_mod.none_node_id) return types.Primitive.undefined_t;
            inner = ex.expression;
        }
        return try self.flowTypeForAssignmentValue(inner, fallback);
    }

    /// Member type for the display-only attrs bag (whole-bag TS2322 /
    /// TS2741 source rendering), mirroring tsgo's
    /// `createJsxAttributesTypeFromAttributesProperty` +
    /// `checkExpressionForMutableLocation`:
    ///   * shorthand `<Foo x />` — the regular `true` literal
    ///     (`checkJsxAttribute` returns `trueType`; never widened).
    ///   * expression values — widened via
    ///     `getWidenedLiteralLikeTypeForContextualType`: kept only when
    ///     the contextual prop type contains the same literal,
    ///     otherwise widened (`10` → `number`, `"hi"` → `string`).
    fn jsxDiagnosticBagMemberType(self: *Checker, value: NodeId, bag_t: TypeId, contextual_prop_t: ?TypeId) TypeId {
        if (value == hir_mod.none_node_id) return bag_t;
        if (bag_t >= self.interner.pool.typeCount()) return bag_t;
        if (!self.interner.pool.flagsOf(bag_t).is_literal) return bag_t;
        if (contextual_prop_t) |pt| {
            if (pt == bag_t) return bag_t;
            if (pt < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(pt).is_union)
            {
                for (self.interner.unionMembers(pt)) |member| {
                    if (member == bag_t) return bag_t;
                }
            }
        }
        return self.widenForInference(bag_t);
    }

    const JsxContextualAttributeResult = struct {
        value_type: ?TypeId = null,
        reported_error: bool = false,
    };

    fn checkJsxContextualAttributeValue(self: *Checker, value: NodeId, prop_t: TypeId) CheckError!JsxContextualAttributeResult {
        if (value == hir_mod.none_node_id) return .{};
        if (self.hir.kindOf(value) != .jsx_expression) return .{};
        const ex = hir_mod.jsxExpressionOf(self.hir, value);
        if (ex.expression == hir_mod.none_node_id) return .{};
        const k = self.hir.kindOf(ex.expression);
        if (k == .arrow_fn or k == .fn_expr or k == .fn_decl) {
            const sig = self.firstSignatureType(prop_t) orelse return .{};
            var inferred_t = types.Primitive.none;
            try self.checkFunctionWithContextualSignatureMode(ex.expression, sig, false, &inferred_t);
            return .{ .value_type = if (inferred_t != types.Primitive.none) inferred_t else null };
        }
        if (k != .array_literal) return .{};

        const elem_target = try self.arrayElementType(prop_t);
        if (elem_target == types.Primitive.none or self.typeIsAnyLike(elem_target)) return .{};
        var reported = false;
        for (hir_mod.arrayLiteralElements(self.hir, ex.expression)) |element| {
            if (element == hir_mod.none_node_id or self.hir.kindOf(element) == .spread) continue;
            if (try self.literalExpressionAssignableToTarget(element, elem_target)) continue;
            const element_t = try self.checkedExpressionType(element);
            if (self.engine.isAssignableTo(element_t, elem_target) catch false) continue;
            try self.reportTypeNotAssignable(
                element,
                self.widenForInference(element_t),
                elem_target,
                "JSX array element is not assignable to the contextual element type.",
            );
            reported = true;
        }
        return .{ .reported_error = reported };
    }

    fn firstSignatureType(self: *Checker, t: TypeId) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.firstSignatureType(member)) |sig| return sig;
            }
            return null;
        }
        if (flags.is_signature) return t;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.firstSignatureType(member)) |sig| return sig;
            }
        }
        if (flags.is_object_type) {
            const call_member_id = self.string_interner.intern("__call") catch return null;
            for (self.interner.objectMembers(t)) |member| {
                if (member.name == call_member_id and self.interner.isSignature(member.type)) return member.type;
            }
        }
        return null;
    }

    fn contextualElementAssignmentSignature(self: *Checker, t: TypeId) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_union and !flags.is_intersection) {
            if (self.callableSignatureCount(t) != 1) return null;
            return self.firstSignatureType(t);
        }
        var selected: TypeId = types.Primitive.none;
        const members = if (flags.is_union) self.interner.unionMembers(t) else self.interner.intersectionMembers(t);
        for (members) |member| {
            const signature = self.firstSignatureType(member) orelse return null;
            if (selected == types.Primitive.none) {
                selected = signature;
                continue;
            }
            const selected_params = self.interner.signatureParams(selected);
            const candidate_params = self.interner.signatureParams(signature);
            if (selected_params.len != candidate_params.len) return null;
            if (self.rest_signatures.contains(selected) != self.rest_signatures.contains(signature)) return null;
            if ((self.signature_min_args.get(selected) orelse selected_params.len) !=
                (self.signature_min_args.get(signature) orelse candidate_params.len))
            {
                return null;
            }
            for (selected_params, candidate_params) |selected_param, candidate_param| {
                if (!(self.engine.isIdenticalTo(selected_param, candidate_param) catch false)) return null;
            }
        }
        return if (selected != types.Primitive.none) selected else null;
    }

    fn callableSignatureCount(self: *Checker, t: TypeId) usize {
        if (t >= self.interner.pool.typeCount()) return 0;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_intersection) {
            var count: usize = 0;
            for (self.interner.intersectionMembers(t)) |member| count += self.callableSignatureCount(member);
            return count;
        }
        if (flags.is_signature) return 1;
        if (flags.is_union) {
            var count: usize = 0;
            for (self.interner.unionMembers(t)) |member| count += self.callableSignatureCount(member);
            return count;
        }
        if (!flags.is_object_type) return 0;
        const call_member_id = self.string_interner.intern("__call") catch return 0;
        var count: usize = 0;
        for (self.interner.objectMembers(t)) |member| {
            if (member.name == call_member_id and self.interner.isSignature(member.type)) count += 1;
        }
        return count;
    }

    fn signatureHasCallableParameter(self: *Checker, sig: TypeId) bool {
        if (sig >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(sig).is_signature) return false;
        for (self.interner.signatureParams(sig)) |param_t| {
            if (self.firstSignatureType(param_t) != null) return true;
        }
        return false;
    }

    fn checkFunctionWithContextualSignature(self: *Checker, fn_node: NodeId, sig: TypeId) CheckError!void {
        try self.checkFunctionWithContextualSignatureMode(fn_node, sig, true, null);
    }

    fn checkFunctionWithContextualSignatureMode(
        self: *Checker,
        fn_node: NodeId,
        sig: TypeId,
        check_return_assignability: bool,
        inferred_signature_out: ?*TypeId,
    ) CheckError!void {
        const params = hir_mod.fnParams(self.hir, fn_node);
        const param_ts = self.interner.signatureParams(sig);
        self.removeImplicitAnyDiagnosticsWithin(fn_node);
        try self.pushNarrowScope();
        defer self.popNarrowScope();
        const n = @min(params.len, param_ts.len);
        const effective_param_ts = try self.gpa.dupe(TypeId, param_ts[0..n]);
        defer self.gpa.free(effective_param_ts);
        for (0..n) |i| {
            const pp = hir_mod.parameterOf(self.hir, params[i]);
            if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
            const id = hir_mod.identifierOf(self.hir, pp.name);
            var effective_param_t = param_ts[i];
            if (pp.type_annotation != hir_mod.none_node_id) {
                effective_param_t = self.lowererLowerWithTypeParams(pp.type_annotation) catch effective_param_t;
                if (self.objectAnnotationName(pp.type_annotation) != null and
                    effective_param_t >= types.Primitive.first_dynamic and effective_param_t < self.interner.pool.typeCount())
                {
                    self.builtin_object_names.put(self.gpa, effective_param_t, "Object") catch {};
                }
                if (pp.flags.is_optional or pp.default_value != hir_mod.none_node_id) {
                    effective_param_t = self.unionWithUndefined(effective_param_t) catch effective_param_t;
                }
            }
            effective_param_ts[i] = effective_param_t;
            try self.recordNarrow(id.name, effective_param_t);
            self.hir.setType(params[i], effective_param_t);
            self.hir.setType(pp.name, effective_param_t);
        }
        if (self.hir.kindOf(fn_node) != .arrow_fn) {
            if (self.signatureThisParam(sig)) |this_t_raw| {
                const this_id = self.string_interner.intern("this") catch return error.OutOfMemory;
                const this_t = self.thisTypeMarkerConstraint(this_t_raw) orelse this_t_raw;
                try self.recordNarrow(this_id, this_t);
            }
        }
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.body == hir_mod.none_node_id) return;
        self.function_body_depth += 1;
        defer self.function_body_depth -= 1;
        if (self.hir.kindOf(f.body) == .block_stmt) {
            for (hir_mod.blockStmts(self.hir, f.body)) |s| try self.checkStatement(s);
            if (inferred_signature_out) |out| {
                var return_expressions: std.ArrayListUnmanaged(NodeId) = .empty;
                defer return_expressions.deinit(self.gpa);
                try self.collectReturnExpressions(f.body, &return_expressions);

                var return_types: std.ArrayListUnmanaged(TypeId) = .empty;
                defer return_types.deinit(self.gpa);
                for (return_expressions.items) |expression| {
                    const expression_t = if (self.hir.typeOf(expression) != types.Primitive.none)
                        self.hir.typeOf(expression)
                    else
                        try self.checkExpression(expression);
                    try self.appendUniqueTypeId(&return_types, expression_t);
                }
                const return_t = switch (return_types.items.len) {
                    0 => types.Primitive.void_t,
                    1 => return_types.items[0],
                    else => self.interner.internUnion(return_types.items) catch return error.OutOfMemory,
                };
                const inferred_sig = self.interner.internSignature(effective_param_ts, return_t, false) catch return error.OutOfMemory;
                try self.recordSignatureParamNames(inferred_sig, params[0..n]);
                self.hir.setType(fn_node, inferred_sig);
                out.* = inferred_sig;
            }
        } else {
            const body_t = (try self.contextualFunctionBodyExpressionType(f.body, params[0..n], effective_param_ts)) orelse
                try self.checkExpression(f.body);
            if (inferred_signature_out) |out| {
                const inferred_sig = self.interner.internSignature(effective_param_ts, body_t, false) catch return error.OutOfMemory;
                try self.recordSignatureParamNames(inferred_sig, params[0..n]);
                self.hir.setType(fn_node, inferred_sig);
                out.* = inferred_sig;
            }
            const ret_t = self.interner.signatureReturn(sig) orelse types.Primitive.any;
            if (check_return_assignability and
                ret_t != types.Primitive.void_t and
                ret_t != types.Primitive.any and
                ret_t != types.Primitive.unknown and
                body_t != types.Primitive.none and
                body_t != types.Primitive.any and
                body_t != types.Primitive.unknown and
                !(self.engine.isAssignableTo(body_t, ret_t) catch true))
            {
                const src_text = (try self.simpleDiagnosticTypeName(body_t)) orelse "type";
                const target_text = (try self.simpleDiagnosticTypeName(ret_t)) orelse "type";
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Type '{s}' is not assignable to type '{s}'.",
                    .{ src_text, target_text },
                );
                try self.diagnostics.append(self.gpa, .{
                    .node = f.body,
                    .code = TsCodes.type_not_assignable,
                    .message = msg,
                });
            }
        }
    }

    fn contextualFunctionBodyExpressionType(
        self: *Checker,
        body_node: NodeId,
        params: []const NodeId,
        param_ts: []const TypeId,
    ) CheckError!?TypeId {
        if (body_node == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(body_node) == .identifier) {
            const body_id = hir_mod.identifierOf(self.hir, body_node);
            for (params, 0..) |param, i| {
                const pp = hir_mod.parameterOf(self.hir, param);
                if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
                if (hir_mod.identifierOf(self.hir, pp.name).name == body_id.name) return param_ts[i];
            }
            return null;
        }
        if (self.hir.kindOf(body_node) == .member_access) {
            const m = hir_mod.memberOf(self.hir, body_node);
            if (m.object == hir_mod.none_node_id or self.hir.kindOf(m.object) != .identifier) return null;
            const obj_id = hir_mod.identifierOf(self.hir, m.object);
            for (params, 0..) |param, i| {
                const pp = hir_mod.parameterOf(self.hir, param);
                if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
                if (hir_mod.identifierOf(self.hir, pp.name).name != obj_id.name) continue;
                const receiver_t = param_ts[i];
                if (try self.primitivePrototypeMember(receiver_t, m.name)) |member_t| return member_t;
                if (receiver_t < types.Primitive.first_dynamic or receiver_t >= self.interner.pool.typeCount()) return null;
                return try self.lookupObjectMember(receiver_t, m.name);
            }
        }
        return null;
    }

    fn jsxPropsType(self: *Checker, node: NodeId, tag: NodeId, attr_count: usize) CheckError!?TypeId {
        if (tag == hir_mod.none_node_id) return null;
        if (self.jsxTagIsIntrinsic(tag)) {
            const id = hir_mod.identifierOf(self.hir, tag);
            return try self.jsxIntrinsicPropsType(tag, id.name);
        }
        if (self.jsxClassInstanceTypeForTag(tag)) |instance_t| {
            // tsc only treats `instance.props` as the JSX attrs target
            // when `JSX.ElementAttributesProperty` is declared (and the
            // `.lib/react` files supply that declaration). When the
            // fixture declares neither a `JSX` namespace nor references
            // `/.lib/react.d.ts`, tsc falls back to `any` for the JSX
            // attrs target ÃÂ¢ÃÂÃÂ `tsxTypeErrors` is the canonical case.
            // Without this guard we structurally check JSX attrs against
            // the raw `MyClass['props']` shape and emit spurious TS2322
            // pairs that tsc's baseline doesn't carry.
            if ((try self.jsxHasNamespaceDecl(tag)) or self.sourceHasReactJsxReference()) {
                if (try self.jsxElementAttributesPropertyName(tag)) |props_name| {
                    if (try self.lookupObjectMember(instance_t, props_name)) |props_t| return try self.jsxComposeIntrinsicClassAttributes(tag, instance_t, props_t);
                    if (attr_count > 0) {
                        const props_text = self.string_interner.get(props_name);
                        const msg = try std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "JSX element class does not support attributes because it does not have a '{s}' property.",
                            .{props_text},
                        );
                        try self.report(tag, TsCodes.jsx_class_no_attributes_property, msg);
                        return types.Primitive.any;
                    }
                } else {
                    const props_name = self.string_interner.intern("props") catch return error.OutOfMemory;
                    if (try self.lookupObjectMember(instance_t, props_name)) |props_t| return try self.jsxComposeIntrinsicClassAttributes(tag, instance_t, props_t);
                }
            } else {
                return types.Primitive.any;
            }
        }
        if (self.hir.kindOf(tag) == .identifier) {
            const tag_name = hir_mod.identifierOf(self.hir, tag).name;
            if (self.overloads.get(tag_name)) |overload_list| {
                const has_impl = self.overload_has_implementation.contains(tag_name);
                const visible_len = if (has_impl and overload_list.items.len > 0) overload_list.items.len - 1 else overload_list.items.len;
                var prop_types: std.ArrayListUnmanaged(TypeId) = .empty;
                defer prop_types.deinit(self.gpa);
                var saw_zero_param = false;
                for (overload_list.items[0..visible_len]) |sig| {
                    const params = self.interner.signatureParams(sig);
                    if (params.len == 0) {
                        saw_zero_param = true;
                        continue;
                    }
                    try prop_types.append(self.gpa, params[0]);
                }
                if (saw_zero_param and attr_count == 0) return types.Primitive.any;
                if (prop_types.items.len > 0) {
                    if (prop_types.items.len == 1) return prop_types.items[0];
                    return self.interner.internUnion(prop_types.items) catch return error.OutOfMemory;
                }
            }
            if (try self.jsxLogicalComponentPropsType(tag, tag_name)) |props_t| return props_t;
            if (try self.jsxForwardFunctionPropsType(tag, tag_name)) |props_t| return props_t;
        }
        const tag_t = try self.checkExpression(tag);
        if (try self.propertyNameFromLiteralType(tag_t)) |intrinsic_name| {
            return try self.jsxIntrinsicPropsType(tag, intrinsic_name);
        }
        if (try self.lookupObjectMember(tag_t, self.string_interner.intern("props") catch return error.OutOfMemory)) |props_t| {
            return props_t;
        }
        var construct_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer construct_sigs.deinit(self.gpa);
        try self.collectConstructSignatures(tag_t, &construct_sigs);
        if (construct_sigs.items.len > 0) {
            var sig = construct_sigs.items[0];
            if ((try self.jsxHasNamespaceDecl(tag)) or self.sourceHasReactJsxReference()) {
                if (try self.jsxElementAttributesPropertyName(tag)) |props_name| {
                    for (construct_sigs.items) |candidate| {
                        const candidate_instance = self.interner.signatureReturn(candidate) orelse continue;
                        const candidate_props = (try self.lookupObjectMember(candidate_instance, props_name)) orelse continue;
                        if (self.containsFreeTypeParameter(candidate_props)) continue;
                        sig = candidate;
                        break;
                    }
                }
            }
            // tsgo `getJsxPropsTypeFromClassType`: when a JSX namespace
            // (or the react lib reference) is in scope, the props target
            // for a construct-signature tag is driven by
            // `JSX.ElementAttributesProperty`:
            //   * interface absent — the signature's first parameter
            //     (the legacy constructor-props shape,
            //     `tsxElementResolution9`);
            //   * interface declared but EMPTY — the signature's return
            //     (instance) type itself (`tsxElementResolution11`);
            //   * interface `{ pr: T }` — the instance's `pr` member
            //     type (`tsxElementResolution12`); an instance lacking
            //     `pr` with at least one attribute reports TS2607
            //     anchored at the element's opening `<`.
            if ((try self.jsxHasNamespaceDecl(tag)) or self.sourceHasReactJsxReference()) {
                if ((try self.jsxElementAttributesPropertyDecl(tag)) != null) {
                    const instance_t = self.interner.signatureReturn(sig) orelse types.Primitive.any;
                    if (self.typeIsAnyLike(instance_t)) return types.Primitive.any;
                    if (try self.jsxElementAttributesPropertyName(tag)) |props_name| {
                        if (try self.lookupObjectMember(instance_t, props_name)) |member_t| return member_t;
                        if (attr_count > 0) {
                            const props_text = self.string_interner.get(props_name);
                            const msg = try std.fmt.allocPrint(
                                self.diag_arena.allocator(),
                                "JSX element class does not support attributes because it does not have a '{s}' property.",
                                .{props_text},
                            );
                            const anchor = if (node != hir_mod.none_node_id) node else tag;
                            try self.report(anchor, TsCodes.jsx_class_no_attributes_property, msg);
                        }
                        return types.Primitive.unknown;
                    }
                    // Empty `ElementAttributesProperty` — the instance
                    // type itself is the attributes target.
                    return instance_t;
                }
            }
            const params = self.interner.signatureParams(sig);
            if (params.len > 0) return params[0];
            return types.Primitive.any;
        }
        var call_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer call_sigs.deinit(self.gpa);
        try self.collectCallSignatures(tag_t, &call_sigs);
        if (call_sigs.items.len > 0) {
            const params = self.interner.signatureParams(call_sigs.items[0]);
            if (params.len > 0) return params[0];
            return types.Primitive.any;
        }
        return null;
    }

    /// Locate the `JSX.ElementAttributesProperty` interface declaration
    /// visible from `anchor`, or null when the JSX namespace or the
    /// interface is absent. tsgo distinguishes "interface missing"
    /// (`InternalSymbolNameMissing` → constructor-parameter props) from
    /// "interface present but empty" (`""` → instance-type props), so the
    /// declaration itself must be observable, not just its member name.
    fn jsxElementAttributesPropertyDecl(self: *Checker, anchor: NodeId) CheckError!?NodeId {
        const jsx_name = self.string_interner.intern("JSX") catch return error.OutOfMemory;
        const attrs_name = self.string_interner.intern("ElementAttributesProperty") catch return error.OutOfMemory;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const ns_node = self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), &[_]hir_mod.StringId{jsx_name}) orelse return null;
        const decl = self.findNamedTypeDeclInNamespace(ns_node, attrs_name) orelse return null;
        if (self.hir.kindOf(decl) != .interface_decl) return null;
        return decl;
    }

    fn jsxElementAttributesPropertyName(self: *Checker, anchor: NodeId) CheckError!?hir_mod.StringId {
        const decl = (try self.jsxElementAttributesPropertyDecl(anchor)) orelse return null;

        var count: usize = 0;
        var only_name: hir_mod.StringId = 0;
        for (hir_mod.interfaceMembers(self.hir, decl)) |member| {
            if (self.hir.kindOf(member) != .interface_member) continue;
            const im = hir_mod.interfaceMemberOf(self.hir, member);
            if (im.name == 0) continue;
            count += 1;
            only_name = im.name;
        }
        if (count == 1) return only_name;
        if (count > 1) {
            const pos = self.declarationNameSpanStart(decl) orelse self.hir.spanOf(decl).start;
            if (!self.hasDiagnosticAtPosition(TsCodes.jsx_global_type_multiple_properties, pos)) {
                try self.reportAt(
                    decl,
                    pos,
                    TsCodes.jsx_global_type_multiple_properties,
                    "The global type 'JSX.ElementAttributesProperty' may not have more than one property.",
                );
            }
        }
        return null;
    }

    fn jsxForwardFunctionPropsType(self: *Checker, anchor: NodeId, tag_name: hir_mod.StringId) CheckError!?TypeId {
        return try self.jsxNamedFunctionPropsType(anchor, tag_name);
    }

    fn jsxNamedFunctionPropsType(self: *Checker, anchor: NodeId, tag_name: hir_mod.StringId) CheckError!?TypeId {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
            if (decl == hir_mod.none_node_id or self.hir.kindOf(decl) != .fn_decl) continue;
            const f = hir_mod.fnDeclOf(self.hir, decl);
            if (f.name == hir_mod.none_node_id or self.hir.kindOf(f.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, f.name).name != tag_name) continue;
            const params = hir_mod.fnParams(self.hir, decl);
            if (params.len == 0) return self.interner.internObjectType(&.{}) catch return error.OutOfMemory;
            // Reuse the declaration's signature while it is available:
            // its parameter types were lowered inside the function's
            // generic scope, preserving `T` plus its constraint. Re-lowering
            // `param: T` here at the JSX use site has no active declaration
            // type-parameter scope and collapses T to `unknown`.
            const signature = self.hir.typeOf(decl);
            if (signature != types.Primitive.none and
                signature < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(signature).is_signature)
            {
                const signature_params = self.interner.signatureParams(signature);
                if (signature_params.len > 0) return signature_params[0];
            }
            const first = hir_mod.parameterOf(self.hir, params[0]);
            if (first.type_annotation == hir_mod.none_node_id) return types.Primitive.any;
            try self.ensureTypeRefDeclChecked(first.type_annotation, root);
            return try self.lowererLowerWithTypeParams(first.type_annotation);
        }
        return null;
    }

    fn jsxLogicalComponentPropsType(self: *Checker, anchor: NodeId, tag_name: hir_mod.StringId) CheckError!?TypeId {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
            if (decl == hir_mod.none_node_id) continue;
            const dk = self.hir.kindOf(decl);
            if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
            const v = hir_mod.varDeclOf(self.hir, decl);
            if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, v.name).name != tag_name) continue;
            if (v.init == hir_mod.none_node_id or self.hir.kindOf(v.init) != .logical_op) return null;
            var prop_types: std.ArrayListUnmanaged(TypeId) = .empty;
            defer prop_types.deinit(self.gpa);
            try self.collectJsxLogicalComponentProps(anchor, v.init, &prop_types);
            if (prop_types.items.len == 0) return null;
            if (prop_types.items.len == 1) return prop_types.items[0];
            return self.interner.internIntersection(prop_types.items) catch return error.OutOfMemory;
        }
        return null;
    }

    fn collectJsxLogicalComponentProps(
        self: *Checker,
        anchor: NodeId,
        node: NodeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        if (self.hir.kindOf(node) == .logical_op) {
            const l = hir_mod.logicalOf(self.hir, node);
            try self.collectJsxLogicalComponentProps(anchor, l.lhs, out);
            try self.collectJsxLogicalComponentProps(anchor, l.rhs, out);
            return;
        }
        if (self.hir.kindOf(node) != .identifier) return;
        const id = hir_mod.identifierOf(self.hir, node);
        const props_t = (try self.jsxNamedFunctionPropsType(anchor, id.name)) orelse
            self.jsxClassPropsTypeForName(id.name) orelse
            return;
        try out.append(self.gpa, props_t);
    }

    fn jsxClassPropsTypeForName(self: *Checker, tag_name: hir_mod.StringId) ?TypeId {
        const instance_t = self.class_instance_types.get(tag_name) orelse return null;
        const props_name = self.string_interner.intern("props") catch return null;
        return self.lookupObjectMember(instance_t, props_name) catch null;
    }

    fn ensureTypeRefDeclChecked(self: *Checker, type_node: NodeId, root: NodeId) CheckError!void {
        switch (self.hir.kindOf(type_node)) {
            .type_ref => {
                const r = hir_mod.typeRefOf(self.hir, type_node);
                if (r.qualifier_len != 0) return;
                if (self.type_names.contains(r.name) or self.generic_aliases.contains(r.name)) return;
                for (hir_mod.blockStmts(self.hir, root)) |stmt| {
                    const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
                    if (decl == hir_mod.none_node_id) continue;
                    switch (self.hir.kindOf(decl)) {
                        .interface_decl => {
                            const it = hir_mod.interfaceOf(self.hir, decl);
                            if (it.name != hir_mod.none_node_id and
                                self.hir.kindOf(it.name) == .identifier and
                                hir_mod.identifierOf(self.hir, it.name).name == r.name)
                            {
                                try self.checkInterfaceDecl(decl);
                                return;
                            }
                        },
                        .type_alias_decl => {
                            const ta = hir_mod.typeAliasOf(self.hir, decl);
                            if (ta.name != hir_mod.none_node_id and
                                self.hir.kindOf(ta.name) == .identifier and
                                hir_mod.identifierOf(self.hir, ta.name).name == r.name)
                            {
                                try self.checkTypeAliasDecl(decl);
                                return;
                            }
                        },
                        else => {},
                    }
                }
            },
            .union_type => for (hir_mod.unionTypeMembers(self.hir, type_node)) |member| try self.ensureTypeRefDeclChecked(member, root),
            .intersection_type => for (hir_mod.intersectionTypeMembers(self.hir, type_node)) |member| try self.ensureTypeRefDeclChecked(member, root),
            .array_type => try self.ensureTypeRefDeclChecked(hir_mod.arrayTypeOf(self.hir, type_node).element, root),
            .readonly_type => try self.ensureTypeRefDeclChecked(hir_mod.readonlyTypeOf(self.hir, type_node).operand, root),
            else => {},
        }
    }

    fn jsxTagIsIntrinsic(self: *Checker, tag: NodeId) bool {
        if (tag == hir_mod.none_node_id or self.hir.kindOf(tag) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, tag);
        const name = self.string_interner.get(id.name);
        if (std.mem.eql(u8, name, "this")) return false;
        // tsgo `isJsxIntrinsicTagName` = `IsIdentifier && IsIntrinsicJsxName`
        // OR any `JsxNamespacedName`: namespaced tags (`svg:path`, `A:foo`)
        // are intrinsic regardless of leading case, and `IsIntrinsicJsxName`
        // also accepts dashed names (`my-element`). Case gates only plain
        // identifiers.
        if (std.mem.indexOfScalar(u8, name, ':') != null) return true;
        if (std.mem.indexOfScalar(u8, name, '-') != null) return true;
        return name.len > 0 and std.ascii.isLower(name[0]);
    }

    fn checkJsxNamespacedComponentTag(self: *Checker, tag: NodeId) CheckError!void {
        if (!self.jsx_transform_enabled) return;
        if (tag == hir_mod.none_node_id or self.hir.kindOf(tag) != .identifier) return;
        const id = hir_mod.identifierOf(self.hir, tag);
        const name = self.string_interner.get(id.name);
        const colon = std.mem.indexOfScalar(u8, name, ':') orelse return;
        if (colon == 0) return;
        if (std.ascii.isLower(name[0])) return;
        try self.report(tag, TsCodes.jsx_component_namespaced_name, "React components cannot include JSX namespace names");
    }

    fn checkJsxNamespacedPropertyAccessTag(self: *Checker, tag: NodeId) CheckError!void {
        if (tag == hir_mod.none_node_id or self.hir.kindOf(tag) != .member_access) return;
        const m = hir_mod.memberOf(self.hir, tag);
        if (self.hir.kindOf(m.object) == .member_access) {
            try self.checkJsxNamespacedPropertyAccessTag(m.object);
            return;
        }
        if (self.hir.kindOf(m.object) != .identifier) return;
        const id = hir_mod.identifierOf(self.hir, m.object);
        const name = self.string_interner.get(id.name);
        if (std.mem.indexOfScalar(u8, name, ':') == null) return;
        try self.report(m.object, TsCodes.jsx_property_access_namespaced_name, "JSX property access expressions cannot include JSX namespace names");
    }

    fn jsxComponentTypeInvalid(self: *Checker, tag: NodeId) CheckError!bool {
        if (tag == hir_mod.none_node_id) return false;
        if (self.jsxClassInstanceTypeForTag(tag)) |_| return false;
        const tag_t = try self.checkedExpressionType(tag);
        return !(try self.jsxComponentTypeIsValid(tag_t));
    }

    fn jsxClassInstanceTypeForTag(self: *Checker, tag: NodeId) ?TypeId {
        if (tag == hir_mod.none_node_id or self.hir.kindOf(tag) != .identifier) return null;
        const id = hir_mod.identifierOf(self.hir, tag);
        return self.class_instance_types.get(id.name);
    }

    fn jsxComponentTypeIsValid(self: *Checker, t: TypeId) CheckError!bool {
        if (self.typeIsAnyLike(t)) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_string) return true;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!try self.jsxComponentTypeIsValid(member)) return false;
            }
            return true;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (try self.jsxComponentTypeIsValid(member)) return true;
            }
            return false;
        }
        if (flags.is_signature) {
            const ret = self.interner.signatureReturn(t) orelse types.Primitive.any;
            if (self.strict_flags.strict_null_checks and
                (ret == types.Primitive.undefined_t or ret == types.Primitive.void_t))
            {
                return false;
            }
            return true;
        }
        if (!flags.is_object_type) return false;
        const props_name = self.string_interner.intern("props") catch return error.OutOfMemory;
        if ((try self.lookupObjectMember(t, props_name)) != null) return true;
        var construct_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer construct_sigs.deinit(self.gpa);
        try self.collectConstructSignatures(t, &construct_sigs);
        if (construct_sigs.items.len > 0) return true;
        var call_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer call_sigs.deinit(self.gpa);
        try self.collectCallSignatures(t, &call_sigs);
        return call_sigs.items.len > 0;
    }

    /// Resolve the lowered type of a source-declared `JSX.ElementType`
    /// type alias / interface, mirroring upstream
    /// `getJsxElementTypeTypeAt` (which looks up the `ElementType`
    /// symbol on the resolved JSX namespace). Returns `null` when no
    /// JSX namespace is in scope, when it declares no `ElementType`
    /// member, or when the declaration fails to lower — in every
    /// such case upstream `getJsxElementTypeTypeAt` returns nil and
    /// the TS18053/TS2786 relation check is skipped entirely (the
    /// other JSX legality paths take over). Faithful: this is the
    /// gate that keeps the new diagnostic from firing on the
    /// overwhelming majority of fixtures that never declare
    /// `JSX.ElementType`.
    fn jsxElementTypeConstraint(self: *Checker, anchor: NodeId) CheckError!?TypeId {
        const jsx_name = self.string_interner.intern("JSX") catch return error.OutOfMemory;
        const element_type_name = self.string_interner.intern("ElementType") catch return error.OutOfMemory;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const ns_node = self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), &[_]hir_mod.StringId{jsx_name}) orelse return null;
        const decl = self.findNamedTypeDeclInNamespace(ns_node, element_type_name) orelse return null;
        switch (self.hir.kindOf(decl)) {
            .type_alias_decl => {
                const alias_type_node = hir_mod.typeAliasOf(self.hir, decl).aliased;
                if (alias_type_node == hir_mod.none_node_id) return null;
                const t = try self.lowererLowerWithTypeParams(alias_type_node);
                if (t == types.Primitive.none or t == types.Primitive.unknown) return null;
                return t;
            },
            .interface_decl => {
                var iface_t = self.hir.typeOf(decl);
                if (iface_t == types.Primitive.none or iface_t == types.Primitive.unknown) {
                    try self.checkInterfaceDecl(decl);
                    iface_t = self.hir.typeOf(decl);
                }
                if (iface_t == types.Primitive.none or iface_t == types.Primitive.unknown) return null;
                return iface_t;
            },
            else => return null,
        }
    }

    fn jsxElementConstraint(self: *Checker, anchor: NodeId) CheckError!?TypeId {
        const jsx_name = self.string_interner.intern("JSX") catch return error.OutOfMemory;
        const element_name = self.string_interner.intern("Element") catch return error.OutOfMemory;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) {
            return try self.jsxLibElementSyntheticType();
        }
        const ns_node = self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), &[_]hir_mod.StringId{jsx_name}) orelse
            return try self.jsxLibElementSyntheticType();
        const decl = self.findNamedTypeDeclInNamespace(ns_node, element_name) orelse return null;
        switch (self.hir.kindOf(decl)) {
            .type_alias_decl => {
                const alias_type_node = hir_mod.typeAliasOf(self.hir, decl).aliased;
                if (alias_type_node == hir_mod.none_node_id) return null;
                const t = try self.lowererLowerWithTypeParams(alias_type_node);
                if (t == types.Primitive.none or t == types.Primitive.unknown) return null;
                return t;
            },
            .interface_decl => {
                var iface_t = self.hir.typeOf(decl);
                if (iface_t == types.Primitive.none or iface_t == types.Primitive.unknown) {
                    try self.checkInterfaceDecl(decl);
                    iface_t = self.hir.typeOf(decl);
                }
                if (iface_t == types.Primitive.none or iface_t == types.Primitive.unknown) return null;
                return iface_t;
            },
            else => return null,
        }
    }

    fn jsxElementClassConstraint(self: *Checker, anchor: NodeId) CheckError!?TypeId {
        const jsx_name = self.string_interner.intern("JSX") catch return error.OutOfMemory;
        const element_class_name = self.string_interner.intern("ElementClass") catch return error.OutOfMemory;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const ns_node = self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), &[_]hir_mod.StringId{jsx_name}) orelse return null;
        const decl = self.findNamedTypeDeclInNamespace(ns_node, element_class_name) orelse return null;
        switch (self.hir.kindOf(decl)) {
            .type_alias_decl => {
                const alias_type_node = hir_mod.typeAliasOf(self.hir, decl).aliased;
                if (alias_type_node == hir_mod.none_node_id) return null;
                const t = try self.lowererLowerWithTypeParams(alias_type_node);
                if (t == types.Primitive.none or t == types.Primitive.unknown) return null;
                return t;
            },
            .interface_decl => {
                var iface_t = self.hir.typeOf(decl);
                if (iface_t == types.Primitive.none or iface_t == types.Primitive.unknown) {
                    try self.checkInterfaceDecl(decl);
                    iface_t = self.hir.typeOf(decl);
                }
                if (iface_t == types.Primitive.none or iface_t == types.Primitive.unknown) return null;
                return iface_t;
            },
            else => return null,
        }
    }

    /// The type of a JSX tag for the `JSX.ElementType` relation check.
    /// Intrinsic tags (lowercase identifiers) are checked as their
    /// string-literal name type — mirroring upstream
    /// `getStringLiteralType(tagName.Text())` — while component tags
    /// use the resolved expression type of the tag reference. Returns
    /// `Primitive.none` when no meaningful type can be computed.
    fn jsxTagConstraintType(self: *Checker, tag: NodeId) CheckError!TypeId {
        if (tag == hir_mod.none_node_id) return types.Primitive.none;
        if (self.jsxTagIsIntrinsic(tag)) {
            const id = hir_mod.identifierOf(self.hir, tag);
            return self.interner.internStringLiteral(id.name) catch return error.OutOfMemory;
        }
        return try self.checkedExpressionType(tag);
    }

    /// Render the JSX tag's type for the TS18053 chain message, e.g.
    /// `"span"` for an intrinsic tag's string-literal type. Falls back
    /// to the generic simple / anonymous-object renderers for
    /// component tag types. Returns `null` when nothing renders, in
    /// which case the caller suppresses the chained sub-message.
    fn allocJsxTagTypeName(self: *Checker, t: TypeId) CheckError!?[]const u8 {
        if (t < self.interner.pool.typeCount()) {
            const flags = self.interner.pool.flagsOf(t);
            if (flags.is_literal and flags.is_string) {
                switch (self.interner.literalOf(t)) {
                    .string_lit => |sid| {
                        const text = self.string_interner.get(sid);
                        return std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "\"{s}\"",
                            .{text},
                        ) catch return error.OutOfMemory;
                    },
                    else => {},
                }
            }
        }
        if (try self.allocSimpleTypeName(t)) |name| return name;
        return try self.allocAnonymousObjectName(t);
    }

    /// Faithful port of the `getJsxElementTypeTypeAt` relation check in
    /// upstream `checkJsxOpeningLikeElementOrOpeningFragment`: when the
    /// source declares `JSX.ElementType`, the tag's type must be
    /// assignable to it. On failure, emit the primary TS2786
    /// (`'{0}' cannot be used as a JSX component.`) anchored at the
    /// tag, with the TS18053 sub-message (`Its type '{0}' is not a
    /// valid JSX element type.`) chained beneath it — matching the
    /// upstream `NewDiagnosticChain` shape where TS2786 is the head
    /// code and TS18053 the nested relation message.
    fn checkJsxElementTypeConstraint(self: *Checker, el_tag: NodeId) CheckError!void {
        if (el_tag == hir_mod.none_node_id) return;
        const constraint = (try self.jsxElementTypeConstraint(el_tag)) orelse return;
        const tag_t = try self.jsxTagConstraintType(el_tag);
        if (tag_t == types.Primitive.none) return;
        // `any`/`unknown` tag types and free type parameters always
        // satisfy the constraint (mirrors the relater short-circuits).
        if (self.typeIsAnyLike(tag_t)) return;
        if (self.containsFreeTypeParameter(tag_t)) return;
        if (self.engine.isAssignableTo(tag_t, constraint) catch true) return;

        const tag_text = self.nodeSourceTextOrEmpty(el_tag);
        if (tag_text.len == 0) return;

        const arena = self.diag_arena.allocator();
        const primary_msg = std.fmt.allocPrint(
            arena,
            "'{s}' cannot be used as a JSX component.",
            .{tag_text},
        ) catch return error.OutOfMemory;

        var chain: []const DiagnosticChainEntry = &.{};
        if (try self.allocJsxTagTypeName(tag_t)) |tag_type_name| {
            const sub_msg = std.fmt.allocPrint(
                arena,
                "Its type '{s}' is not a valid JSX element type.",
                .{tag_type_name},
            ) catch return error.OutOfMemory;
            const entries = arena.alloc(DiagnosticChainEntry, 1) catch return error.OutOfMemory;
            entries[0] = .{
                .code = TsCodes.jsx_element_type_not_valid,
                .message = sub_msg,
            };
            chain = entries;
        }

        try self.diagnostics.append(self.gpa, .{
            .node = el_tag,
            .code = TsCodes.jsx_component_not_valid,
            .message = primary_msg,
            .chain = chain,
        });
    }

    fn checkJsxFunctionReturnElementBound(self: *Checker, tag: NodeId) CheckError!void {
        if (tag == hir_mod.none_node_id or self.jsxTagIsIntrinsic(tag)) return;
        const element_t = (try self.jsxElementConstraint(tag)) orelse return;

        var call_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer call_sigs.deinit(self.gpa);
        try self.collectJsxTagCallSignatures(tag, &call_sigs);
        if (call_sigs.items.len == 0) return;

        for (call_sigs.items) |sig| {
            const ret_t = self.interner.signatureReturn(sig) orelse types.Primitive.any;
            if (self.typeIsAnyLike(ret_t)) return;
            if (self.engine.isAssignableTo(ret_t, element_t) catch true) return;
        }

        const tag_text = self.nodeSourceTextOrEmpty(tag);
        if (tag_text.len == 0) return;
        const ret_t = self.interner.signatureReturn(call_sigs.items[0]) orelse types.Primitive.any;
        const ret_name = (try self.allocSimpleTypeName(ret_t)) orelse
            (try self.allocAnonymousObjectName(ret_t)) orelse return;
        const arena = self.diag_arena.allocator();
        const primary_msg = std.fmt.allocPrint(
            arena,
            "'{s}' cannot be used as a JSX component.",
            .{tag_text},
        ) catch return error.OutOfMemory;
        const chain_msg = std.fmt.allocPrint(
            arena,
            "Its return type '{s}' is not a valid JSX element.",
            .{ret_name},
        ) catch return error.OutOfMemory;
        const chain = arena.alloc(DiagnosticChainEntry, 1) catch return error.OutOfMemory;
        chain[0] = .{
            .code = TsCodes.jsx_return_type_not_valid,
            .message = chain_msg,
        };
        try self.diagnostics.append(self.gpa, .{
            .node = tag,
            .code = TsCodes.jsx_component_not_valid,
            .message = primary_msg,
            .chain = chain,
        });
    }

    fn checkJsxClassInstanceElementBound(self: *Checker, tag: NodeId) CheckError!void {
        if (tag == hir_mod.none_node_id or self.jsxTagIsIntrinsic(tag)) return;
        if ((try self.jsxElementTypeConstraint(tag)) != null) return;
        const class_t = (try self.jsxElementClassConstraint(tag)) orelse return;

        var instance_t = self.jsxClassInstanceTypeForTag(tag) orelse types.Primitive.none;
        if (instance_t == types.Primitive.none) {
            const tag_t = try self.checkedExpressionType(tag);
            var construct_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
            defer construct_sigs.deinit(self.gpa);
            try self.collectConstructSignatures(tag_t, &construct_sigs);
            if (construct_sigs.items.len == 0) return;
            instance_t = self.interner.signatureReturn(construct_sigs.items[0]) orelse types.Primitive.any;
        }

        if (self.typeIsAnyLike(instance_t)) return;
        if (self.engine.isAssignableTo(instance_t, class_t) catch true) return;

        const tag_text = self.nodeSourceTextOrEmpty(tag);
        if (tag_text.len == 0) return;
        const instance_name = (try self.allocSimpleTypeName(instance_t)) orelse
            (try self.allocAnonymousObjectName(instance_t)) orelse return;
        const arena = self.diag_arena.allocator();
        const primary_msg = std.fmt.allocPrint(
            arena,
            "'{s}' cannot be used as a JSX component.",
            .{tag_text},
        ) catch return error.OutOfMemory;
        const chain_msg = std.fmt.allocPrint(
            arena,
            "Its instance type '{s}' is not a valid JSX element.",
            .{instance_name},
        ) catch return error.OutOfMemory;
        const chain = arena.alloc(DiagnosticChainEntry, 1) catch return error.OutOfMemory;
        chain[0] = .{
            .code = TsCodes.jsx_instance_type_not_valid,
            .message = chain_msg,
        };
        try self.diagnostics.append(self.gpa, .{
            .node = tag,
            .code = TsCodes.jsx_component_not_valid,
            .message = primary_msg,
            .chain = chain,
        });
    }

    fn checkJsxMixedElementBound(self: *Checker, tag: NodeId) CheckError!bool {
        if (tag == hir_mod.none_node_id or self.jsxTagIsIntrinsic(tag)) return false;
        if ((try self.jsxElementTypeConstraint(tag)) != null) return false;
        const element_t = (try self.jsxElementConstraint(tag)) orelse return false;
        const class_t = (try self.jsxElementClassConstraint(tag)) orelse return false;
        const tag_t = try self.checkedExpressionType(tag);
        if (tag_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(tag_t).is_union) return false;

        var element_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer element_types.deinit(self.gpa);
        var saw_call = false;
        var saw_construct = false;
        for (self.interner.unionMembers(tag_t)) |member| {
            var construct_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
            defer construct_sigs.deinit(self.gpa);
            try self.collectConstructSignatures(member, &construct_sigs);
            if (construct_sigs.items.len > 0) {
                saw_construct = true;
                try element_types.append(self.gpa, self.interner.signatureReturn(construct_sigs.items[0]) orelse types.Primitive.any);
                continue;
            }

            var call_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
            defer call_sigs.deinit(self.gpa);
            try self.collectCallSignatures(member, &call_sigs);
            if (call_sigs.items.len > 0) {
                saw_call = true;
                try element_types.append(self.gpa, self.interner.signatureReturn(call_sigs.items[0]) orelse types.Primitive.any);
                continue;
            }
            return false;
        }
        if (!saw_call or !saw_construct or element_types.items.len == 0) return false;

        const mixed_element_t = if (element_types.items.len == 1)
            element_types.items[0]
        else
            self.interner.internUnion(element_types.items) catch return error.OutOfMemory;
        if (self.typeIsAnyLike(mixed_element_t)) return true;
        const target_t = self.interner.internUnion(&.{ element_t, class_t }) catch return error.OutOfMemory;
        if (self.engine.isAssignableTo(mixed_element_t, target_t) catch true) return true;

        const tag_text = self.nodeSourceTextOrEmpty(tag);
        if (tag_text.len == 0) return true;
        const element_name = (try self.simpleDiagnosticTypeName(mixed_element_t)) orelse
            (try self.allocSimpleTypeName(mixed_element_t)) orelse
            (try self.allocAnonymousObjectName(mixed_element_t)) orelse return true;
        const arena = self.diag_arena.allocator();
        const primary_msg = std.fmt.allocPrint(
            arena,
            "'{s}' cannot be used as a JSX component.",
            .{tag_text},
        ) catch return error.OutOfMemory;
        const chain_msg = std.fmt.allocPrint(
            arena,
            "Its element type '{s}' is not a valid JSX element.",
            .{element_name},
        ) catch return error.OutOfMemory;
        const chain = arena.alloc(DiagnosticChainEntry, 1) catch return error.OutOfMemory;
        chain[0] = .{
            .code = TsCodes.jsx_element_not_valid,
            .message = chain_msg,
        };
        try self.diagnostics.append(self.gpa, .{
            .node = tag,
            .code = TsCodes.jsx_component_not_valid,
            .message = primary_msg,
            .chain = chain,
        });
        return true;
    }

    fn checkJsxFactoryTagArity(self: *Checker, tag: NodeId) CheckError!void {
        if (tag == hir_mod.none_node_id or self.jsxTagIsIntrinsic(tag)) return;

        const factory_name = self.jsxFactoryNameText();
        if (factory_name.len == 0) return;

        var tag_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer tag_sigs.deinit(self.gpa);
        try self.collectJsxTagCallSignatures(tag, &tag_sigs);
        if (tag_sigs.items.len == 0) {
            if (try self.reportJsxFactoryTagArityBySyntax(tag, factory_name)) return;
            return;
        }

        const factory_t = (try self.jsxFactoryType(tag, factory_name)) orelse {
            if (try self.reportJsxFactoryTagArityBySyntax(tag, factory_name)) return;
            return;
        };

        var factory_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer factory_sigs.deinit(self.gpa);
        try self.collectCallSignatures(factory_t, &factory_sigs);
        if (factory_sigs.items.len == 0) {
            if (try self.reportJsxFactoryTagArityBySyntax(tag, factory_name)) return;
            return;
        }

        var found_factory_tag_signature = false;
        var max_factory_tag_args: usize = 0;
        for (factory_sigs.items) |factory_sig| {
            const factory_params = self.interner.signatureParams(factory_sig);
            if (factory_params.len == 0) continue;

            var tag_param_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
            defer tag_param_sigs.deinit(self.gpa);
            try self.collectCallSignatures(factory_params[0], &tag_param_sigs);
            for (tag_param_sigs.items) |param_sig| {
                found_factory_tag_signature = true;
                if (self.rest_signatures.contains(param_sig)) return;
                const params = self.interner.signatureParams(param_sig);
                max_factory_tag_args = @max(max_factory_tag_args, params.len);
            }
        }
        if (!found_factory_tag_signature) {
            if (try self.reportJsxFactoryTagArityBySyntax(tag, factory_name)) return;
            return;
        }

        var min_tag_args: usize = std.math.maxInt(usize);
        var min_tag_sig: TypeId = types.Primitive.none;
        for (tag_sigs.items) |tag_sig| {
            const params = self.interner.signatureParams(tag_sig);
            const min_required = self.jsxTagSignatureMinRequiredArgs(tag_sig, params);
            if (min_required < min_tag_args) {
                min_tag_args = min_required;
                min_tag_sig = tag_sig;
            }
        }
        if (min_tag_args == std.math.maxInt(usize) or min_tag_args <= max_factory_tag_args) {
            if (try self.reportJsxFactoryTagArityBySyntax(tag, factory_name)) return;
            return;
        }

        try self.reportJsxFactoryTagArity(tag, self.signatureDeclNode(min_tag_sig), min_tag_args, factory_name, max_factory_tag_args);
    }

    fn reportJsxFactoryTagArityBySyntax(self: *Checker, tag: NodeId, factory_name: []const u8) CheckError!bool {
        const tag_info = self.jsxNamedFunctionTagMinArgs(tag) orelse return false;
        const max_factory_tag_args = self.jsxFactorySyntacticMaxTagArgs(tag, factory_name) orelse return false;
        if (tag_info.min_required <= max_factory_tag_args) return false;
        try self.reportJsxFactoryTagArity(tag, tag_info.decl, tag_info.min_required, factory_name, max_factory_tag_args);
        return true;
    }

    const JsxTagSyntaxArity = struct {
        decl: NodeId,
        min_required: usize,
    };

    fn jsxNamedFunctionTagMinArgs(self: *Checker, tag: NodeId) ?JsxTagSyntaxArity {
        if (tag == hir_mod.none_node_id) return null;
        const tag_text = self.nodeSourceTextOrEmpty(tag);
        if (tag_text.len == 0) return null;
        const tag_name = self.string_interner.intern(tag_text) catch return null;
        const root = self.rootBlockFor(tag);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |raw| {
            const decl = self.unwrapExportDecl(raw);
            if (decl == hir_mod.none_node_id or self.hir.kindOf(decl) != .fn_decl) continue;
            const f = hir_mod.fnDeclOf(self.hir, decl);
            if (f.name == hir_mod.none_node_id or self.hir.kindOf(f.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, f.name).name != tag_name) continue;
            return .{ .decl = decl, .min_required = self.syntaxRequiredValueParameterCount(decl) };
        }
        return null;
    }

    fn jsxFactorySyntacticMaxTagArgs(self: *Checker, anchor: NodeId, factory_name: []const u8) ?usize {
        const root_name = self.jsxFactoryRootName(factory_name) orelse return null;
        const factory_id = self.string_interner.intern(root_name) catch return null;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |raw| {
            const decl = self.unwrapExportDecl(raw);
            if (decl == hir_mod.none_node_id or self.hir.kindOf(decl) != .fn_decl) continue;
            const f = hir_mod.fnDeclOf(self.hir, decl);
            if (f.name == hir_mod.none_node_id or self.hir.kindOf(f.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, f.name).name != factory_id) continue;
            const params = hir_mod.fnParams(self.hir, decl);
            if (params.len == 0) return null;
            const first = hir_mod.parameterOf(self.hir, params[0]);
            const anno = first.type_annotation;
            if (anno == hir_mod.none_node_id) return null;
            const k = self.hir.kindOf(anno);
            if (k != .fn_type and k != .constructor_type) return null;
            return self.syntaxValueParameterCount(anno);
        }
        return null;
    }

    fn syntaxRequiredValueParameterCount(self: *Checker, fn_like: NodeId) usize {
        var value_param_index: usize = 0;
        var min_required: usize = 0;
        const params = self.functionLikeParams(fn_like) orelse return 0;
        for (params) |param| {
            if (self.isThisParameter(param)) continue;
            const p = hir_mod.parameterOf(self.hir, param);
            defer value_param_index += 1;
            if (p.flags.is_rest or p.flags.is_optional or p.default_value != hir_mod.none_node_id) continue;
            min_required = value_param_index + 1;
        }
        return min_required;
    }

    fn syntaxValueParameterCount(self: *Checker, fn_like: NodeId) usize {
        var count: usize = 0;
        const params = self.functionLikeParams(fn_like) orelse return 0;
        for (params) |param| {
            if (self.isThisParameter(param)) continue;
            count += 1;
        }
        return count;
    }

    fn functionLikeParams(self: *Checker, fn_like: NodeId) ?[]const NodeId {
        switch (self.hir.kindOf(fn_like)) {
            .fn_decl, .fn_expr, .arrow_fn => return hir_mod.fnParams(self.hir, fn_like),
            .fn_type, .constructor_type => {
                const ft = hir_mod.fnTypeOf(self.hir, fn_like);
                return self.hir.childSlice(ft.params_start, ft.params_len);
            },
            else => return null,
        }
    }

    fn reportJsxFactoryTagArity(
        self: *Checker,
        tag: NodeId,
        decl_node: NodeId,
        min_tag_args: usize,
        factory_name: []const u8,
        max_factory_tag_args: usize,
    ) CheckError!void {
        const tag_text = self.nodeSourceTextOrEmpty(tag);
        if (tag_text.len == 0) return;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Tag '{s}' expects at least '{d}' arguments, but the JSX factory '{s}' provides at most '{d}'.",
            .{ tag_text, min_tag_args, factory_name, max_factory_tag_args },
        );
        var related: []const RelatedInfo = &.{};
        if (decl_node != hir_mod.none_node_id) {
            related = try self.declaredHereRelated(decl_node, tag_text);
        }
        try self.diagnostics.append(self.gpa, .{
            .node = tag,
            .code = TsCodes.jsx_factory_tag_too_few_args,
            .message = msg,
            .related = related,
        });
    }

    fn jsxTagSignatureMinRequiredArgs(self: *Checker, sig: TypeId, params: []const TypeId) usize {
        const decl = self.signatureDeclNode(sig);
        if (decl == hir_mod.none_node_id) return self.signatureMinRequiredArgs(sig, params);
        switch (self.hir.kindOf(decl)) {
            .fn_decl, .fn_expr, .arrow_fn => {},
            else => return self.signatureMinRequiredArgs(sig, params),
        }

        var value_param_index: usize = 0;
        var min_required: usize = 0;
        for (hir_mod.fnParams(self.hir, decl)) |param| {
            if (self.isThisParameter(param)) continue;
            const p = hir_mod.parameterOf(self.hir, param);
            defer value_param_index += 1;
            if (p.flags.is_rest or p.flags.is_optional or p.default_value != hir_mod.none_node_id) continue;
            min_required = value_param_index + 1;
        }
        return @min(min_required, params.len);
    }

    fn collectJsxTagCallSignatures(
        self: *Checker,
        tag: NodeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!void {
        if (tag == hir_mod.none_node_id) return;
        if (self.hir.kindOf(tag) == .identifier) {
            const tag_name = hir_mod.identifierOf(self.hir, tag).name;
            if (self.overloads.get(tag_name)) |overload_list| {
                const has_impl = self.overload_has_implementation.contains(tag_name);
                const visible_len = if (has_impl and overload_list.items.len > 0) overload_list.items.len - 1 else overload_list.items.len;
                for (overload_list.items[0..visible_len]) |sig| try out.append(self.gpa, sig);
                if (visible_len > 0) return;
            }
        }
        const tag_t = try self.checkedExpressionType(tag);
        try self.collectCallSignatures(tag_t, out);
    }

    fn jsxFactoryNameText(self: *Checker) []const u8 {
        return self.sourceJsxFactoryPragmaValue() orelse self.jsx_factory_name;
    }

    fn jsxFragmentFactoryNameText(self: *Checker) []const u8 {
        return self.sourceJsxFragPragmaValue() orelse self.jsx_fragment_factory_name;
    }

    fn sourceJsxFactoryPragmaValue(self: *Checker) ?[]const u8 {
        const src = self.source orelse return null;
        var lines = std.mem.splitScalar(u8, src, '\n');
        while (lines.next()) |line_raw| {
            const line = std.mem.trim(u8, line_raw, " \t\r/*");
            if (jsxDirectiveLineValue(line, "@jsxFactory")) |value| return value;
            if (jsxDirectiveLineValue(line, "@jsx")) |value| return value;
        }
        return null;
    }

    fn sourceJsxFragPragmaValue(self: *Checker) ?[]const u8 {
        const src = self.source orelse return null;
        var lines = std.mem.splitScalar(u8, src, '\n');
        while (lines.next()) |line_raw| {
            const line = std.mem.trim(u8, line_raw, " \t\r/*");
            if (jsxDirectiveLineValue(line, "@jsxFrag")) |value| return value;
            if (jsxDirectiveLineValue(line, "@jsxfrag")) |value| return value;
        }
        return null;
    }

    fn jsxDirectiveLineValue(line: []const u8, marker: []const u8) ?[]const u8 {
        if (!std.mem.startsWith(u8, line, marker)) return null;
        var rest = line[marker.len..];
        if (rest.len == 0) return null;
        const first = rest[0];
        if (first != ' ' and first != '\t' and first != ':') return null;
        rest = std.mem.trim(u8, rest, " \t:");
        if (std.mem.indexOfAny(u8, rest, " \t*/\r")) |end| rest = rest[0..end];
        if (rest.len == 0) return null;
        return rest;
    }

    fn jsxFactoryRootName(self: *Checker, factory_name: []const u8) ?[]const u8 {
        _ = self;
        var parts = std.mem.splitScalar(u8, factory_name, '.');
        const first_raw = parts.next() orelse return null;
        const first = std.mem.trim(u8, first_raw, " \t\r\n");
        if (first.len == 0) return null;
        return first;
    }

    fn jsxFactoryType(self: *Checker, anchor: NodeId, factory_name: []const u8) CheckError!?TypeId {
        var parts = std.mem.splitScalar(u8, factory_name, '.');
        const first = self.jsxFactoryRootName(factory_name) orelse return null;
        const first_name = self.string_interner.intern(first) catch return error.OutOfMemory;
        var current = (try self.jsxRootValueType(anchor, first_name)) orelse return null;
        while (parts.next()) |raw_part| {
            const part = std.mem.trim(u8, raw_part, " \t\r\n");
            if (part.len == 0) return null;
            const member_name = self.string_interner.intern(part) catch return error.OutOfMemory;
            current = (try self.lookupObjectMember(current, member_name)) orelse return null;
        }
        return current;
    }

    fn jsxRootValueType(self: *Checker, anchor: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (try self.overloadedFunctionValueType(name)) |overloaded_t| return overloaded_t;
        if (self.class_static_types.get(name)) |static_t| return static_t;

        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |raw| {
            const decl = self.unwrapExportDecl(raw);
            if (decl == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(decl) == .import_decl) {
                // `import X = require("…")` and value-space import bindings
                // put `X` in scope, satisfying the classic JSX factory
                // lookup (tsgo `resolveName` finds the alias).
                // `declarationName` does not cover import declarations, so
                // match the bindings directly.
                const imp = hir_mod.importOf(self.hir, decl);
                if (imp.import_equals != hir_mod.none_node_id) {
                    if (self.importEqualsAliasName(decl)) |alias| {
                        if (alias == name and self.importEqualsTargetHasRuntimeValue(decl, 0)) return types.Primitive.any;
                    }
                    continue;
                }
                if (!imp.is_type_only) {
                    if (imp.namespace_binding != hir_mod.none_node_id and self.hir.kindOf(imp.namespace_binding) == .identifier) {
                        if (hir_mod.identifierOf(self.hir, imp.namespace_binding).name == name) return types.Primitive.any;
                    }
                    if (imp.default_binding != hir_mod.none_node_id and self.hir.kindOf(imp.default_binding) == .identifier) {
                        if (hir_mod.identifierOf(self.hir, imp.default_binding).name == name) return types.Primitive.any;
                    }
                    for (hir_mod.importNamed(self.hir, decl)) |spec_node| {
                        const spec = hir_mod.importSpecifierOf(self.hir, spec_node);
                        if (!spec.is_type_only and spec.local == name) return types.Primitive.any;
                    }
                }
                continue;
            }
            const decl_name = self.declarationName(decl) orelse continue;
            if (decl_name != name) continue;

            switch (self.hir.kindOf(decl)) {
                .fn_decl, .fn_expr => {
                    var t = self.hir.typeOf(decl);
                    if (t == types.Primitive.none) {
                        try self.checkFnSignatureOnlyNoBody(decl);
                        t = self.hir.typeOf(decl);
                    }
                    if (try self.overloadedFunctionValueType(name)) |overloaded_t| return overloaded_t;
                    if (t != types.Primitive.none) return t;
                },
                .var_decl, .let_decl, .const_decl => {
                    var t = self.hir.typeOf(decl);
                    const v = hir_mod.varDeclOf(self.hir, decl);
                    if (t == types.Primitive.none and v.type_annotation != hir_mod.none_node_id) {
                        t = try self.lowerValueTypeAnnotation(name, v.type_annotation);
                        self.hir.setType(decl, t);
                        if (v.name != hir_mod.none_node_id) self.hir.setType(v.name, t);
                    }
                    if (t == types.Primitive.none and v.init != hir_mod.none_node_id) {
                        t = try self.checkedExpressionType(v.init);
                        self.hir.setType(decl, t);
                        if (v.name != hir_mod.none_node_id) self.hir.setType(v.name, t);
                    }
                    if (t != types.Primitive.none) return t;
                },
                .class_decl, .class_expr => {
                    if (self.class_static_types.get(name)) |static_t| return static_t;
                    try self.checkClassDecl(decl);
                    if (self.class_static_types.get(name)) |static_t| return static_t;
                    const t = self.hir.typeOf(decl);
                    if (t != types.Primitive.none) return t;
                },
                .namespace_decl => {
                    if (self.namespaceHasRuntimeValue(decl)) return try self.namespaceValueObjectType(decl);
                },
                else => {},
            }
        }
        return null;
    }

    fn jsxIntrinsicPropsType(self: *Checker, anchor: NodeId, tag_name: hir_mod.StringId) CheckError!?TypeId {
        const jsx_name = self.string_interner.intern("JSX") catch return error.OutOfMemory;
        const intrinsic_name = self.string_interner.intern("IntrinsicElements") catch return error.OutOfMemory;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const ns_node = self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), &[_]hir_mod.StringId{jsx_name}) orelse {
            if (self.sourceHasReactJsxReference()) return try self.jsxReactIntrinsicPropsType();
            return null;
        };
        const decl = self.findNamedTypeDeclInNamespace(ns_node, intrinsic_name) orelse return null;
        if (self.hir.kindOf(decl) == .interface_decl) {
            for (hir_mod.interfaceMembers(self.hir, decl)) |member| {
                if (self.hir.kindOf(member) != .interface_member) continue;
                const im = hir_mod.interfaceMemberOf(self.hir, member);
                if (im.name != tag_name) continue;
                if (im.type_node != hir_mod.none_node_id) {
                    return try self.lowererLowerWithTypeParams(im.type_node);
                }
                return types.Primitive.any;
            }
        }
        var intrinsic_t = self.hir.typeOf(decl);
        if (intrinsic_t == types.Primitive.none or intrinsic_t == types.Primitive.unknown) {
            if (self.hir.kindOf(decl) == .interface_decl) try self.checkInterfaceDecl(decl);
            intrinsic_t = self.hir.typeOf(decl);
        }
        if (intrinsic_t == types.Primitive.none or intrinsic_t == types.Primitive.unknown) return null;
        if (try self.lookupObjectMember(intrinsic_t, tag_name)) |props_t| return props_t;
        const string_idx = self.interner.objectStringIndex(intrinsic_t);
        if (string_idx != types.Primitive.none) return string_idx;
        const number_idx = self.interner.objectNumberIndex(intrinsic_t);
        if (number_idx != types.Primitive.none and self.isNumericStringId(tag_name)) return number_idx;
        return null;
    }

    fn jsxReactIntrinsicPropsType(self: *Checker) CheckError!TypeId {
        const children_name = self.string_interner.intern("children") catch return error.OutOfMemory;
        const class_name = self.string_interner.intern("className") catch return error.OutOfMemory;
        const key_name = self.string_interner.intern("key") catch return error.OutOfMemory;
        const react_node_t = try self.jsxReactNodeSyntheticType();
        const key_t = self.interner.internUnion(&[_]TypeId{
            types.Primitive.string_t,
            types.Primitive.number_t,
        }) catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{
            .{
                .name = children_name,
                .type = react_node_t,
                .is_optional = true,
                .is_readonly = false,
                .is_method = false,
            },
            .{
                .name = class_name,
                .type = types.Primitive.string_t,
                .is_optional = true,
                .is_readonly = false,
                .is_method = false,
            },
            .{
                .name = key_name,
                .type = key_t,
                .is_optional = true,
                .is_readonly = false,
                .is_method = false,
            },
        };
        return self.interner.internObjectTypeWithIndex(&members, types.Primitive.any, types.Primitive.none) catch return error.OutOfMemory;
    }

    fn jsxReactNodeSyntheticType(self: *Checker) CheckError!TypeId {
        const name = self.string_interner.intern("ReactNode") catch return error.OutOfMemory;
        if (self.type_names.get(name)) |existing| return existing;
        const element_t = (try self.jsxLibElementSyntheticType()) orelse
            (self.interner.internObjectType(&.{}) catch return error.OutOfMemory);
        // The legacy fixture lib types `ReactFragment = {} |
        // Array<...>`, while React 18 removed the broad `{}` arm.
        // Preserve the legacy arm so function children remain valid
        // there, but do not make React 18's `ReactNode` an
        // unknown-like union.
        const fragment_array_t = self.interner.internObjectTypeWithIndex(&.{}, types.Primitive.none, element_t) catch return error.OutOfMemory;
        const fragment_t = if (self.sourceHasReact18JsxReference())
            fragment_array_t
        else blk: {
            const fragment_empty_t = self.interner.internObjectType(&.{}) catch return error.OutOfMemory;
            break :blk self.interner.internUnion(&[_]TypeId{ fragment_empty_t, fragment_array_t }) catch return error.OutOfMemory;
        };
        const members = [_]TypeId{
            element_t,
            types.Primitive.string_t,
            types.Primitive.number_t,
            fragment_t,
            types.Primitive.boolean_t,
            types.Primitive.null_t,
            types.Primitive.undefined_t,
        };
        const react_node_t = self.interner.internUnion(&members) catch return error.OutOfMemory;
        try self.registerAliasDisplayText(react_node_t, "ReactNode");
        try self.type_names.put(self.gpa, name, react_node_t);
        return react_node_t;
    }

    /// `/// <reference path="/.lib/react16.d.ts" />` specifically —
    /// react16 declares `readonly props: Readonly<{ children?:
    /// ReactNode }> & Readonly<P>` while the older fixture
    /// `react.d.ts` declares `props: P & { children?: ReactNode }`;
    /// the JSX managed-attrs prose keeps each lib's constituent order.
    fn sourceHasReact16JsxReference(self: *Checker) bool {
        const src = self.source orelse return false;
        return std.mem.indexOf(u8, src, "/.lib/react16") != null;
    }

    fn sourceHasReact18JsxReference(self: *Checker) bool {
        const src = self.source orelse return false;
        return std.mem.indexOf(u8, src, "/.lib/react18/") != null;
    }

    /// `{ children?: ReactNode | undefined }` — the children
    /// augmentation both fixture react libs mix into a component
    /// instance's `props`. The member type carries `| undefined` the
    /// way tsc renders optional members, matching the managed-attrs
    /// target prose (`tsxSpreadAttributesResolution2` line 26 and
    /// `tsxAttributeResolution15` line 13:
    /// `{ children?: ReactNode | undefined; }`).
    fn jsxReactChildrenPropObjectType(self: *Checker) CheckError!TypeId {
        const children_name = self.string_interner.intern("children") catch return error.OutOfMemory;
        const react_node_t = try self.jsxReactNodeSyntheticType();
        const children_t = self.unionWithUndefined(react_node_t) catch react_node_t;
        const members = [_]types.ObjectMember{.{
            .name = children_name,
            .type = children_t,
            .is_optional = true,
            .is_readonly = false,
            .is_method = false,
        }};
        return self.interner.internObjectType(&members) catch return error.OutOfMemory;
    }

    /// Whether the JSX managed-attrs target for a class element should
    /// compose the synthesized `IntrinsicClassAttributes<T>`
    /// constituent. True only for react-lib fixtures without an
    /// in-source JSX namespace: fixtures that declare their own JSX
    /// namespace get exactly the constituents they declare
    /// (`tsxAttributeResolution12` declares no
    /// `IntrinsicClassAttributes`, so its target stays
    /// `IntrinsicAttributes & { reqd: any; }`).
    fn jsxSynthesizeIntrinsicClassAttributes(self: *Checker, anchor: NodeId) bool {
        if (!self.sourceHasReactJsxReference()) return false;
        if (!(self.jsxHasNamespaceDecl(anchor) catch false)) return true;
        return self.jsxHasIntrinsicClassAttributesDecl(anchor) catch false;
    }

    fn jsxHasIntrinsicClassAttributesDecl(self: *Checker, anchor: NodeId) CheckError!bool {
        const jsx_name = self.string_interner.intern("JSX") catch return error.OutOfMemory;
        const class_attrs_name = self.string_interner.intern("IntrinsicClassAttributes") catch return error.OutOfMemory;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        const ns_node = self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), &[_]hir_mod.StringId{jsx_name}) orelse return false;
        return self.findNamedTypeDeclInNamespace(ns_node, class_attrs_name) != null;
    }

    /// Compose tsc's class-element managed-attrs target
    /// `IntrinsicClassAttributes<Instance> & props` (the
    /// `IntrinsicAttributes` half stays rendering-only — see
    /// `allocJsxAttrsTargetName`). The synthesized constituent carries
    /// `key?: string | number` and `ref?: string | ((instance:
    /// Instance) => any)`, mirroring the fixture libs'
    /// `IntrinsicClassAttributes<T> extends React.ClassAttributes<T>`
    /// (`tsxAttributeResolution15`'s `ref` attribute stops being an
    /// excess property and contextually types the callback parameter).
    fn jsxComposeIntrinsicClassAttributes(self: *Checker, tag: NodeId, instance_t: TypeId, props_t: TypeId) CheckError!TypeId {
        if (!self.jsxSynthesizeIntrinsicClassAttributes(tag)) return props_t;
        if (self.typeIsAnyLike(props_t)) return props_t;
        if (instance_t >= self.interner.pool.typeCount()) return props_t;
        if (!self.interner.pool.flagsOf(instance_t).is_object_type) return props_t;
        const ica_t = try self.jsxIntrinsicClassAttributesSyntheticType(instance_t);
        const pair = [_]TypeId{ ica_t, props_t };
        return self.interner.internIntersection(&pair) catch return props_t;
    }

    fn jsxIntrinsicClassAttributesSyntheticType(self: *Checker, instance_t: TypeId) CheckError!TypeId {
        if (self.jsx_ica_by_instance.get(instance_t)) |t| return t;
        const key_name = self.string_interner.intern("key") catch return error.OutOfMemory;
        const ref_name = self.string_interner.intern("ref") catch return error.OutOfMemory;
        const key_t = self.interner.internUnion(&[_]TypeId{
            types.Primitive.string_t,
            types.Primitive.number_t,
        }) catch return error.OutOfMemory;
        const ref_params = [_]TypeId{instance_t};
        const ref_fn_t = self.interner.internSignature(&ref_params, types.Primitive.any, false) catch return error.OutOfMemory;
        const ref_t = self.interner.internUnion(&[_]TypeId{
            types.Primitive.string_t,
            ref_fn_t,
        }) catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{
            .{
                .name = key_name,
                .type = key_t,
                .is_optional = true,
                .is_readonly = false,
                .is_method = false,
            },
            .{
                .name = ref_name,
                .type = ref_t,
                .is_optional = true,
                .is_readonly = false,
                .is_method = false,
            },
        };
        const t = self.interner.internObjectType(&members) catch return error.OutOfMemory;
        const class_text = (try self.allocSimpleTypeName(instance_t)) orelse
            (try self.allocAnonymousObjectName(instance_t)) orelse "unknown";
        const text = try std.fmt.allocPrint(self.diag_arena.allocator(), "IntrinsicClassAttributes<{s}>", .{class_text});
        try self.registerAliasDisplayText(t, text);
        try self.jsx_ica_by_instance.put(self.gpa, instance_t, t);
        return t;
    }

    fn jsxHasIntrinsicElementsDecl(self: *Checker, anchor: NodeId) CheckError!bool {
        const jsx_name = self.string_interner.intern("JSX") catch return error.OutOfMemory;
        const intrinsic_name = self.string_interner.intern("IntrinsicElements") catch return error.OutOfMemory;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        const ns_node = self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), &[_]hir_mod.StringId{jsx_name}) orelse return false;
        return self.findNamedTypeDeclInNamespace(ns_node, intrinsic_name) != null;
    }

    fn jsxHasNamespaceDecl(self: *Checker, anchor: NodeId) CheckError!bool {
        const jsx_name = self.string_interner.intern("JSX") catch return error.OutOfMemory;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        return self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), &[_]hir_mod.StringId{jsx_name}) != null;
    }

    fn nodeIsSuperReference(self: *Checker, node: NodeId) bool {
        const kind = self.hir.kindOf(node);
        if (kind == .super_expr) return true;
        if (kind == .identifier) {
            const id = hir_mod.identifierOf(self.hir, node);
            return std.mem.eql(u8, self.string_interner.get(id.name), "super");
        }
        return false;
    }

    /// True when `node` is lexically inside any declaration that
    /// introduces type parameters (a generic function/method, class, or
    /// interface). Used to decide whether a free type parameter appearing
    /// in a computed type is a legitimate in-scope parameter or an
    /// artifact of incomplete generic substitution.
    fn hasEnclosingTypeParameters(self: *Checker, node: NodeId) bool {
        var cur = node;
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .fn_decl, .fn_expr, .arrow_fn => {
                    if (hir_mod.fnDeclOf(self.hir, cur).type_params_len > 0) return true;
                },
                .class_decl, .class_expr => {
                    if (hir_mod.classOf(self.hir, cur).type_params_len > 0) return true;
                },
                .interface_decl => {
                    if (hir_mod.interfaceOf(self.hir, cur).type_params_len > 0) return true;
                },
                else => {},
            }
        }
        return false;
    }

    /// Object type for a `super.<member>` / `super[expr]` access. In a
    /// constructor `super` itself is the base CONSTRUCTOR type (so
    /// `super(...)` works), but property access must go through the base
    /// INSTANCE type, recorded under a reserved narrow key. Falls back to
    /// the plain `super` binding (`default_t`) for instance/static methods.
    fn superPropertyObjectType(self: *Checker, default_t: TypeId) TypeId {
        const sp_id = self.string_interner.intern("\x01super_property") catch return default_t;
        return self.lookupNarrow(sp_id) orelse default_t;
    }

    /// True when `node` appears inside a `@decorator(...)` expression
    /// attached to a class member of a class declaration that itself
    /// has `extends`. tsc surfaces TS2660 ("'super' can only be
    /// referenced in members of derived classes or object literal
    /// expressions.") instead of the generic TS2335 for this position
    /// because the decorator runs at class-definition time, lexically
    /// inside the derived class but outside any member. Mirrors
    /// fixture `decoratorOnClassMethod12`.
    fn nodeInsideDecoratorOnDerivedClassMember(self: *Checker, node: NodeId) bool {
        var cur: NodeId = node;
        while (cur != hir_mod.none_node_id) {
            const parent = self.hir.parentOf(cur);
            if (parent == hir_mod.none_node_id) return false;
            if (self.hir.kindOf(parent) == .decorator) {
                // Decorator nodes parent directly to the enclosing
                // class node (the parser appends them to the class's
                // `members` slice). Walk up one more level looking
                // for a class with `extends`.
                var grand = self.hir.parentOf(parent);
                while (grand != hir_mod.none_node_id) {
                    const k = self.hir.kindOf(grand);
                    if (k == .class_decl or k == .class_expr) {
                        const c = hir_mod.classOf(self.hir, grand);
                        return c.extends != hir_mod.none_node_id;
                    }
                    grand = self.hir.parentOf(grand);
                }
                return false;
            }
            cur = parent;
        }
        return false;
    }

    /// Distinguish TS2660 from TS2335 for invalid `super`
    /// references. TS2335 is reserved for class members whose nearest
    /// enclosing class simply lacks `extends`; `super` in object
    /// literals, top-level/non-member code, decorators, or nested
    /// non-arrow functions inside a derived class uses TS2660.
    fn superReferenceShouldReportNotInDerivedMember(self: *Checker, node: NodeId) bool {
        if (self.nodeInsideDecoratorOnDerivedClassMember(node)) return true;

        var cur: NodeId = node;
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .object_literal => return true,
                .class_decl, .class_expr => {
                    const c = hir_mod.classOf(self.hir, cur);
                    return c.extends != hir_mod.none_node_id;
                },
                else => {},
            }
        }
        return true;
    }

    fn superReferenceOwnedByNonDerivedClass(self: *Checker, node: NodeId) bool {
        const class_node = self.enclosingSuperClass(node);
        if (class_node == hir_mod.none_node_id) return false;
        return hir_mod.classOf(self.hir, class_node).extends == hir_mod.none_node_id;
    }

    fn superReferenceLexicalChainIsBroken(self: *Checker, node: NodeId) bool {
        if (self.in_computed_property_name) return false;
        if (!self.superReferenceShouldReportNotInDerivedMember(node)) return false;
        return self.enclosingSuperClass(node) == hir_mod.none_node_id;
    }

    fn superPropertyAccessHasIllegalDerivedMemberContainer(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            switch (k) {
                .arrow_fn => {
                    const parent = self.hir.parentOf(cur);
                    if (parent == hir_mod.none_node_id) return false;
                    const pk = self.hir.kindOf(parent);
                    if (pk == .class_decl or pk == .class_expr or pk == .object_literal) return true;
                },
                .fn_decl, .fn_expr => {
                    const f = hir_mod.fnDeclOf(self.hir, cur);
                    const parent = self.hir.parentOf(cur);
                    if (parent == hir_mod.none_node_id) return false;
                    const pk = self.hir.kindOf(parent);
                    if (pk == .class_decl or pk == .class_expr or pk == .object_literal) {
                        return !(f.flags.is_method or f.flags.is_constructor or f.flags.is_getter or f.flags.is_setter);
                    }
                    return false;
                },
                .object_property => return false,
                .block_stmt => {
                    const parent = self.hir.parentOf(cur);
                    if (parent == hir_mod.none_node_id) return false;
                    const pk = self.hir.kindOf(parent);
                    if (pk == .class_decl or pk == .class_expr) return false;
                },
                .class_decl, .class_expr => return false,
                else => {},
            }
        }
        return false;
    }

    fn reportSuperPropertyAccessOnlyInDerivedMember(self: *Checker, node: NodeId) CheckError!void {
        try self.report(node, TsCodes.super_property_access_only_in_derived, "'super' property access is permitted only in a constructor, member function, or member accessor of a derived class.");
    }

    fn superReferenceInEs5ObjectLiteralMember(self: *Checker, node: NodeId) bool {
        if (!self.sourceTargetMentionsEs5()) return false;
        var cur: NodeId = node;
        var first_fn: NodeId = hir_mod.none_node_id;
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .fn_decl, .fn_expr, .arrow_fn => {
                    if (first_fn != hir_mod.none_node_id) return false;
                    first_fn = cur;
                },
                .object_property => {
                    const op = hir_mod.objectPropertyOf(self.hir, cur);
                    if (first_fn == hir_mod.none_node_id or op.value != first_fn) return false;
                    // Class members are also represented as `object_property`
                    // nodes; TS2659 is object-LITERAL-specific, and `super` in
                    // a class method is unrestricted. Only treat this as an
                    // object-literal member when its container is an object
                    // literal (`superSymbolIndexedAccess5/6` are class methods).
                    if (self.hir.kindOf(self.hir.parentOf(cur)) != .object_literal) return false;
                    if (op.is_method or self.memberSourceLooksMethod(cur)) return true;
                    const value_kind = self.hir.kindOf(op.value);
                    if (value_kind != .fn_decl and value_kind != .fn_expr and value_kind != .arrow_fn) return false;
                    const f = hir_mod.fnDeclOf(self.hir, op.value);
                    return f.flags.is_getter or f.flags.is_setter;
                },
                .class_decl, .class_expr => return false,
                else => {},
            }
        }
        return false;
    }

    fn reportSuperOnlyObjectLiteralMethodsEs2015(self: *Checker, node: NodeId) CheckError!void {
        try self.report(node, TsCodes.super_only_object_literal_methods_es2015, "'super' is only allowed in members of object literal expressions when option 'target' is 'ES2015' or higher.");
    }

    /// Walks parents of `node` and returns the enclosing class
    /// declaration whose lexical static `super` binding governs this
    /// node ÃÂ¢ÃÂÃÂ or `none_node_id` if the node is not inside a static
    /// member that inherits super. Crossing a non-arrow function or a
    /// nested class breaks the static-super chain (mirrors JS arrow
    /// lexical inheritance: `super` flows through arrows, not through
    /// `function () {}` or `class {}` bodies). Static `{ ÃÂ¢ÃÂÃÂ¦ }` blocks
    /// declared as class members are detected by checking whether the
    /// block is one of the parent class's `members` slice.
    fn enclosingStaticSuperClass(self: *Checker, node: NodeId) NodeId {
        var prev: NodeId = node;
        var cur = self.hir.parentOf(node);
        var saw_static_member = false;
        while (cur != hir_mod.none_node_id) {
            const k = self.hir.kindOf(cur);
            switch (k) {
                .object_property => {
                    const op = hir_mod.objectPropertyOf(self.hir, cur);
                    if (op.is_static) saw_static_member = true;
                },
                .fn_decl, .fn_expr => {
                    const fp = hir_mod.fnDeclOf(self.hir, cur);
                    if (fp.flags.is_static) saw_static_member = true;
                    if (!fp.flags.is_arrow) return hir_mod.none_node_id;
                },
                .arrow_fn => {},
                .class_decl, .class_expr => {
                    // `static { ÃÂ¢ÃÂÃÂ¦ }` blocks are stored as bare
                    // `block_stmt` nodes in `classMembers`. Detect
                    // by scanning the members slice ÃÂ¢ÃÂÃÂ if the last
                    // child we walked through (prev) is one of them
                    // and is a block_stmt, this access lives inside
                    // a static block.
                    if (!saw_static_member and self.hir.kindOf(prev) == .block_stmt) {
                        for (hir_mod.classMembers(self.hir, cur)) |m| {
                            if (m == prev) {
                                saw_static_member = true;
                                break;
                            }
                        }
                    }
                    if (!saw_static_member) return hir_mod.none_node_id;
                    return cur;
                },
                else => {},
            }
            prev = cur;
            cur = self.hir.parentOf(cur);
        }
        return hir_mod.none_node_id;
    }

    fn classOrAncestorHasInstanceProperty(self: *Checker, class_name: hir_mod.StringId, member_name: hir_mod.StringId) bool {
        var current: ?hir_mod.StringId = class_name;
        var steps: usize = 0;
        while (current) |name| : (steps += 1) {
            if (steps >= 1024) return false;
            if (self.class_property_members.getPtr(name)) |props| {
                if (props.contains(member_name)) return true;
            }
            current = self.class_parent.get(name);
        }
        return false;
    }

    /// TS2855 -- an instance class field declared by the parent class
    /// chain cannot be accessed via `super.field`. Methods and
    /// accessors remain legal; static `super.field` is checked against
    /// the parent static side and is deliberately skipped here.
    fn reportSuperClassFieldAccess(
        self: *Checker,
        super_obj_node: NodeId,
        member_node: NodeId,
        member_name: hir_mod.StringId,
    ) CheckError!void {
        // ES5 lowers `super.field` through a helper and reports TS2340
        // for data properties. TS2855 is the ES2015+ diagnostic.
        if (self.sourceTargetMentionsEs5()) return;
        if (self.enclosingStaticSuperClass(super_obj_node) != hir_mod.none_node_id) return;
        const enclosing = self.enclosingSuperClass(super_obj_node);
        if (enclosing == hir_mod.none_node_id) return;
        if (self.hir.kindOf(enclosing) != .class_decl and self.hir.kindOf(enclosing) != .class_expr) return;
        const c = hir_mod.classOf(self.hir, enclosing);
        if (c.extends == hir_mod.none_node_id) return;
        const base_name = self.classExtendsName(c.extends) orelse return;
        if (!self.classOrAncestorHasInstanceProperty(base_name, member_name)) return;
        for (self.diagnostics.items) |d| {
            if (d.node == member_node and d.code == TsCodes.class_field_via_super) return;
        }
        const member_span = self.hir.spanOf(member_node);
        const name_str = self.string_interner.get(member_name);
        const name_pos: ?u32 = if (member_span.end >= name_str.len)
            member_span.end - @as(u32, @intCast(name_str.len))
        else
            null;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Class field '{s}' defined by the parent class is not accessible in the child class via super.",
            .{name_str},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = member_node,
            .pos = name_pos,
            .code = TsCodes.class_field_via_super,
            .message = msg,
        });
    }

    /// TS2340 ÃÂ¢ÃÂÃÂ `Only public and protected methods of the base class
    /// are accessible via the 'super' keyword.` Fires for `super.X`
    /// where the access is in a static initializer / static method of
    /// a derived class, `X` is a data property (not a method) on the
    /// base class, and the emit target is ES5. Mirrors tsc fixtures
    /// `typeOfThisInStaticMembers{3,4,7,9,10,11}` and `classStaticBlock5`.
    fn reportSuperPropertyNotMethodInStatic(
        self: *Checker,
        super_obj_node: NodeId,
        super_t: TypeId,
        member_node: NodeId,
        member_name: hir_mod.StringId,
    ) CheckError!void {
        if (!self.sourceTargetMentionsEs5()) return;
        for (self.diagnostics.items) |d| {
            if (d.node == member_node and d.code == TsCodes.class_field_via_super) return;
            if (d.node == member_node and d.code == TsCodes.super_only_methods_accessible) return;
        }
        if (super_t >= self.interner.pool.typeCount()) return;
        if (!self.interner.pool.flagsOf(super_t).is_object_type) return;
        // Anchor must live inside a derived class ÃÂ¢ÃÂÃÂ both static AND
        // instance contexts qualify under target=es5 (tsc emits
        // TS2340 for `super.X` data-property access regardless of
        // static-ness when the lowering target predates `Reflect.get`).
        const enclosing = self.enclosingSuperClass(super_obj_node);
        if (enclosing == hir_mod.none_node_id) return;
        if (self.hir.kindOf(enclosing) != .class_decl and self.hir.kindOf(enclosing) != .class_expr) return;
        const c = hir_mod.classOf(self.hir, enclosing);
        if (c.extends == hir_mod.none_node_id) return;
        const obj_members = self.interner.objectMembers(super_t);
        var found_member: ?types.ObjectMember = null;
        for (obj_members) |om| {
            if (om.name == member_name) {
                found_member = om;
                break;
            }
        }
        const om = found_member orelse return;
        if (om.is_method) return;
        const member_span = self.hir.spanOf(member_node);
        const name_str = self.string_interner.get(member_name);
        const name_pos: ?u32 = if (member_span.end >= name_str.len)
            member_span.end - @as(u32, @intCast(name_str.len))
        else
            null;
        try self.diagnostics.append(self.gpa, .{
            .node = member_node,
            .pos = name_pos,
            .code = TsCodes.super_only_methods_accessible,
            .message = "Only public and protected methods of the base class are accessible via the 'super' keyword.",
        });
    }

    /// TS2513 — an abstract method cannot be reached through `super`.
    /// Upstream `checkPropertyAccessibilityAtLocation` flags a
    /// `super.member` access when the resolved member carries the
    /// `abstract` modifier. The member is resolved on the immediate
    /// base class, so `class B extends A { bar() { super.foo(); } }`
    /// is fine when `A.foo` is concrete, while `class C extends B`
    /// (where `B` re-declares `foo` abstract) errors. We consult the
    /// per-class abstract-member table — which already propagates
    /// inherited-but-unimplemented abstracts — keyed by the base
    /// class name, and anchor at the member name. Mirrors fixture
    /// `classAbstractSuperCalls.ts`.
    fn reportSuperAbstractMethodAccess(self: *Checker, super_obj_node: NodeId, member_node: NodeId, member_name: hir_mod.StringId) CheckError!void {
        const enclosing = self.enclosingSuperClass(super_obj_node);
        if (enclosing == hir_mod.none_node_id) return;
        if (self.hir.kindOf(enclosing) != .class_decl and self.hir.kindOf(enclosing) != .class_expr) return;
        const c = hir_mod.classOf(self.hir, enclosing);
        if (c.extends == hir_mod.none_node_id) return;
        const base_name = self.classExtendsName(c.extends) orelse return;
        const base_abs = self.class_abstract_members.getPtr(base_name) orelse return;
        if (!base_abs.contains(member_name)) return;
        // A `super.foo()` callee member-access node is visited more
        // than once (callee resolution + expression walk); dedupe by
        // node so each distinct access reports a single TS2513.
        for (self.diagnostics.items) |d| {
            if (d.node == member_node and d.code == TsCodes.abstract_method_via_super) return;
        }
        const member_span = self.hir.spanOf(member_node);
        const name_str = self.string_interner.get(member_name);
        const name_pos: ?u32 = if (member_span.end >= name_str.len)
            member_span.end - @as(u32, @intCast(name_str.len))
        else
            null;
        const base_str = self.string_interner.get(base_name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Abstract method '{s}' in class '{s}' cannot be accessed via super expression.",
            .{ name_str, base_str },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = member_node,
            .pos = name_pos,
            .code = TsCodes.abstract_method_via_super,
            .message = msg,
        });
    }

    /// Same as `enclosingStaticSuperClass` but accepts either static
    /// or instance member contexts ÃÂ¢ÃÂÃÂ provided we stay within a class
    /// whose lexical super chain hasn't been broken by a non-arrow
    /// function or nested class boundary.
    fn enclosingSuperClass(self: *Checker, node: NodeId) NodeId {
        var prev: NodeId = node;
        var cur = self.hir.parentOf(node);
        var saw_member = false;
        var skip_decorated_class = false;
        while (cur != hir_mod.none_node_id) {
            const k = self.hir.kindOf(cur);
            switch (k) {
                .decorator => {
                    skip_decorated_class = true;
                },
                .object_property => {
                    saw_member = true;
                },
                .fn_decl, .fn_expr => {
                    const fp = hir_mod.fnDeclOf(self.hir, cur);
                    const is_class_member = fp.flags.is_method or fp.flags.is_constructor or
                        fp.flags.is_getter or fp.flags.is_setter;
                    if (is_class_member) {
                        saw_member = true;
                        // Class member methods anchor the super chain
                        // ÃÂ¢ÃÂÃÂ keep walking to find the enclosing class.
                    } else if (!fp.flags.is_arrow) {
                        // Bare function expression / declaration breaks
                        // the lexical super chain (`function () { super.x }`
                        // doesn't see the enclosing class's super).
                        return hir_mod.none_node_id;
                    }
                },
                .arrow_fn => {},
                .class_decl, .class_expr => {
                    if (skip_decorated_class) {
                        skip_decorated_class = false;
                        saw_member = false;
                        prev = cur;
                        cur = self.hir.parentOf(cur);
                        continue;
                    }
                    if (!saw_member and self.hir.kindOf(prev) == .block_stmt) {
                        for (hir_mod.classMembers(self.hir, cur)) |m| {
                            if (m == prev) {
                                saw_member = true;
                                break;
                            }
                        }
                    }
                    if (!saw_member) return hir_mod.none_node_id;
                    return cur;
                },
                else => {},
            }
            prev = cur;
            cur = self.hir.parentOf(cur);
        }
        return hir_mod.none_node_id;
    }

    fn pushNarrowScope(self: *Checker) !void {
        const empty: std.AutoHashMapUnmanaged(hir_mod.StringId, TypeId) = .empty;
        try self.narrow_scopes.append(self.gpa, empty);
        const empty_mem: std.AutoHashMapUnmanaged(MemberKey, TypeId) = .empty;
        try self.member_narrow_scopes.append(self.gpa, empty_mem);
    }

    fn popNarrowScope(self: *Checker) void {
        if (self.narrow_scopes.items.len == 0) return;
        var top = self.narrow_scopes.items[self.narrow_scopes.items.len - 1];
        top.deinit(self.gpa);
        _ = self.narrow_scopes.pop();
        if (self.member_narrow_scopes.items.len == 0) return;
        var mtop = self.member_narrow_scopes.items[self.member_narrow_scopes.items.len - 1];
        mtop.deinit(self.gpa);
        _ = self.member_narrow_scopes.pop();
    }

    /// Look up the topmost narrowed type for a member access keyed
    /// by `(obj_name, prop_name)`. Walks the scope stack inner ÃÂ¢ÃÂÃÂ
    /// outer.
    fn lookupMemberNarrow(self: *Checker, key: MemberKey) ?TypeId {
        var i = self.member_narrow_scopes.items.len;
        const floor = @min(self.narrow_lookup_floor, i);
        while (i > floor) {
            i -= 1;
            if (self.member_narrow_scopes.items[i].get(key)) |t| return t;
        }
        return null;
    }

    fn recordMemberNarrow(self: *Checker, key: MemberKey, t: TypeId) !void {
        if (self.member_narrow_scopes.items.len == 0) return;
        var top = &self.member_narrow_scopes.items[self.member_narrow_scopes.items.len - 1];
        try top.put(self.gpa, key, t);
    }

    fn lookupCommonJsExportNarrow(self: *Checker, key: MemberKey) ?TypeId {
        if (self.lookupMemberNarrow(key)) |t| return t;
        return self.commonjs_export_narrows.get(key);
    }

    fn recordCommonJsExportNarrow(self: *Checker, key: MemberKey, t: TypeId) !void {
        if (self.member_narrow_scopes.items.len > 0) {
            try self.recordMemberNarrow(key, t);
        }
        try self.commonjs_export_narrows.put(self.gpa, key, t);
    }

    fn commonJsModuleExportsDirectKey(self: *Checker) CheckError!MemberKey {
        const module_name = self.string_interner.intern("module") catch return error.OutOfMemory;
        const exports_name = self.string_interner.intern("exports") catch return error.OutOfMemory;
        return .{ .obj_name = module_name, .prop_name = exports_name };
    }

    fn reportCommonJsExportMissingMember(self: *Checker, node: NodeId, name: hir_mod.StringId) CheckError!void {
        const name_text = self.string_interner.get(name);
        const target_text = try self.currentCommonJsModuleTypeName(node);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Property '{s}' does not exist on type '{s}'.",
            .{ name_text, target_text },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = self.memberAccessNamePos(node),
            .code = TsCodes.property_does_not_exist,
            .message = msg,
        });
    }

    fn reportCommonJsExportImplicitAnyMember(self: *Checker, node: NodeId, name: hir_mod.StringId) CheckError!void {
        const name_text = self.string_interner.get(name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Member '{s}' implicitly has an 'any' type.",
            .{name_text},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = self.memberAccessNamePos(node),
            .code = TsCodes.member_implicitly_any,
            .message = msg,
        });
    }

    fn currentCommonJsModuleTypeName(self: *Checker, node: NodeId) CheckError![]const u8 {
        const filename = self.virtualSectionFilenameForNode(node) orelse
            if (self.importer_path.len > 0) self.importer_path else "module";
        var display = filename;
        while (std.mem.startsWith(u8, display, "/")) display = display[1..];
        const exts = [_][]const u8{ ".d.ts", ".ts", ".tsx", ".mts", ".cts", ".js", ".jsx", ".mjs", ".cjs" };
        for (exts) |ext| {
            if (std.mem.endsWith(u8, display, ext)) {
                display = display[0 .. display.len - ext.len];
                break;
            }
        }
        return try std.fmt.allocPrint(self.diag_arena.allocator(), "typeof import(\"{s}\")", .{display});
    }

    fn currentCommonJsModuleTypeNameWithExtension(self: *Checker, node: NodeId) CheckError![]const u8 {
        const filename = self.virtualSectionFilenameForNode(node) orelse
            if (self.importer_path.len > 0) self.importer_path else "module";
        var display = filename;
        while (std.mem.startsWith(u8, display, "/")) display = display[1..];
        return try std.fmt.allocPrint(self.diag_arena.allocator(), "typeof import(\"{s}\")", .{display});
    }

    fn currentCommonJsExportsTypeRef(self: *Checker, type_node: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (!self.sourceHasCheckJsDirective()) return null;
        if (!std.mem.eql(u8, self.string_interner.get(name), "exports")) return null;
        if (!self.virtualSectionIsJsLike(type_node) and
            !(self.importer_path.len == 0 and !self.sourceHasVirtualFilenameSections()))
        {
            return null;
        }
        if (self.virtualSectionFilenameForNode(type_node)) |filename| {
            if (try self.virtualCommonJsModuleExportObjectType(type_node, filename)) |exports_t| {
                if (exports_t >= types.Primitive.first_dynamic and exports_t < self.interner.pool.typeCount() and
                    !self.alias_display_names.contains(exports_t))
                {
                    try self.alias_display_names.put(self.gpa, exports_t, try self.currentCommonJsModuleTypeName(type_node));
                }
                return exports_t;
            }
        }
        const exports_t = self.lookupCommonJsExportNarrow(try self.commonJsModuleExportsDirectKey()) orelse return null;
        if (exports_t >= types.Primitive.first_dynamic and exports_t < self.interner.pool.typeCount() and
            !self.alias_display_names.contains(exports_t))
        {
            try self.alias_display_names.put(self.gpa, exports_t, try self.currentCommonJsModuleTypeName(type_node));
        }
        return exports_t;
    }

    fn typeCanReceiveCommonJsExportProperty(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.any or t == types.Primitive.unknown or t == types.Primitive.object_t) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_object_type or flags.is_intersection or flags.is_type_parameter) return true;
        // `module.exports = function () {}; module.exports.x = …` — a function
        // value can receive CommonJS expando properties (it's the canonical
        // pattern). Callable types (function/arrow signatures) qualify.
        return flags.is_signature or self.objectHasCallOrConstructSignature(t);
    }

    fn recordCheckJsObjectExpandoNarrow(self: *Checker, key: MemberKey, t: TypeId) !void {
        if (self.member_narrow_scopes.items.len > 0) {
            try self.recordMemberNarrow(key, t);
        }
        try self.checkjs_object_expando_narrows.put(self.gpa, key, t);
    }

    fn commonJsExportMemberKey(self: *Checker, node: NodeId) CheckError!?MemberKey {
        if (!self.sourceHasCheckJsDirective()) return null;
        const prop_name = self.propertyAccessName(node) orelse return null;
        const object = self.propertyAccessObject(node) orelse return null;
        if (self.hir.kindOf(object) == .identifier) {
            const obj_id = hir_mod.identifierOf(self.hir, object);
            if (std.mem.eql(u8, self.string_interner.get(obj_id.name), "exports")) {
                return .{ .obj_name = obj_id.name, .prop_name = prop_name };
            }
            return null;
        }
        if (self.nodeIsModuleExportsAccess(object)) {
            const module_exports = self.string_interner.intern("module.exports") catch return error.OutOfMemory;
            return .{ .obj_name = module_exports, .prop_name = prop_name };
        }
        return null;
    }

    fn commonJsExportAssignmentIsUndefinedDeclaration(self: *Checker, value: NodeId, value_t: TypeId) bool {
        if (value_t == types.Primitive.undefined_t) return true;
        if (self.hir.kindOf(value) == .literal_undefined) return true;
        return self.expressionIsVoidValue(value);
    }

    fn expressionIsVoidValue(self: *Checker, value: NodeId) bool {
        return value != hir_mod.none_node_id and
            self.hir.kindOf(value) == .unary_op and
            hir_mod.unaryOf(self.hir, value).op == .void_;
    }

    fn assignmentTargetValueIsVoidExpression(self: *Checker, target: NodeId) bool {
        var cur = target;
        while (cur != hir_mod.none_node_id) {
            const parent = self.hir.parentOf(cur);
            if (parent == hir_mod.none_node_id) return false;
            if (self.hir.kindOf(parent) == .assignment) {
                const assignment = hir_mod.assignmentOf(self.hir, parent);
                return assignment.op == null and
                    assignment.target == cur and
                    self.expressionIsVoidValue(assignment.value);
            }
            switch (self.hir.kindOf(parent)) {
                .member_access, .element_access => cur = parent,
                else => return false,
            }
        }
        return false;
    }

    fn futureCommonJsExportAssignmentValue(self: *Checker, node: NodeId, key: MemberKey) CheckError!?NodeId {
        const root = self.rootBlockFor(node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const use_start = self.hir.spanOf(node).start;
        const section = if (self.sourceHasVirtualFilenameSections()) self.virtualSectionStartForNode(node) else 0;
        for (hir_mod.blockStmts(self.hir, root)) |raw| {
            if (self.hir.spanOf(raw).start <= use_start) continue;
            if (self.sourceHasVirtualFilenameSections() and self.virtualSectionStartForNode(raw) != section) continue;
            const stmt = self.unwrapExportDecl(raw);
            if (stmt == hir_mod.none_node_id or self.hir.kindOf(stmt) != .assignment) continue;
            const later = hir_mod.assignmentOf(self.hir, stmt);
            if (later.op != null or later.target == hir_mod.none_node_id or later.value == hir_mod.none_node_id) continue;
            const later_key = (try self.commonJsExportMemberKey(later.target)) orelse continue;
            if (later_key.obj_name != key.obj_name or later_key.prop_name != key.prop_name) continue;
            if (self.expressionIsVoidValue(later.value) or self.hir.kindOf(later.value) == .literal_undefined) continue;
            return later.value;
        }
        return null;
    }

    fn checkJsAmbientClassMergeStaticType(
        self: *Checker,
        declaration: NodeId,
        class_name: hir_mod.StringId,
        class_t: TypeId,
    ) CheckError!TypeId {
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        var seen: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer seen.deinit(self.gpa);

        const root = self.rootBlockFor(declaration);
        if (root != hir_mod.none_node_id and self.hir.kindOf(root) == .block_stmt) {
            for (hir_mod.blockStmts(self.hir, root)) |stmt| {
                if (self.hir.kindOf(stmt) != .assignment or !self.virtualSectionIsJsLike(stmt)) continue;
                const assignment = hir_mod.assignmentOf(self.hir, stmt);
                if (assignment.op != null or self.hir.kindOf(assignment.target) != .member_access) continue;
                const member = hir_mod.memberOf(self.hir, assignment.target);
                if (self.hir.kindOf(member.object) != .identifier or
                    hir_mod.identifierOf(self.hir, member.object).name != class_name) continue;
                try seen.put(self.gpa, member.name, {});
                try members.append(self.gpa, .{
                    .name = member.name,
                    .type = types.Primitive.unknown,
                    .is_optional = false,
                    .is_readonly = false,
                    .is_method = false,
                });
            }
        }

        if (class_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(class_t).is_object_type) {
            for (self.interner.objectMembers(class_t)) |member| {
                const name = self.string_interner.get(member.name);
                if (std.mem.eql(u8, name, "name") or
                    std.mem.eql(u8, name, "length") or
                    std.mem.eql(u8, name, "__call") or
                    std.mem.eql(u8, name, "__construct") or
                    seen.contains(member.name)) continue;
                try seen.put(self.gpa, member.name, {});
                try members.append(self.gpa, member);
            }
        }

        const merged_t = self.interner.internObjectType(members.items) catch return error.OutOfMemory;
        try self.class_name_by_static.put(self.gpa, merged_t, class_name);
        return merged_t;
    }

    fn literalCommonJsExportAssignmentType(self: *Checker, value: NodeId) CheckError!?TypeId {
        return switch (self.hir.kindOf(value)) {
            .literal_string, .literal_number, .literal_bool, .unary_op => blk: {
                const lit_t = try self.expressionLiteralType(value, types.Primitive.none);
                if (lit_t == types.Primitive.none) break :blk null;
                break :blk lit_t;
            },
            else => null,
        };
    }

    fn checkJsObjectLiteralExpandoMemberKey(self: *Checker, node: NodeId) CheckError!?MemberKey {
        if (!self.sourceHasCheckJsDirective()) return null;
        const prop_name = self.propertyAccessName(node) orelse return null;
        const object = self.propertyAccessObject(node) orelse return null;
        if (self.memberAccessObjectIsGlobalThisThis(object)) {
            const this_name = self.string_interner.intern("this") catch return error.OutOfMemory;
            return .{ .obj_name = this_name, .prop_name = prop_name };
        }
        if (self.hir.kindOf(object) != .identifier) return null;
        const obj_id = hir_mod.identifierOf(self.hir, object);
        const obj_name = self.string_interner.get(obj_id.name);
        if (std.mem.eql(u8, obj_name, "exports") or std.mem.eql(u8, obj_name, "module")) return null;
        if (self.localNameIsImportBinding(obj_id.name, object)) {
            if (self.strict_flags.no_implicit_any) return null;
            const import_t = (try self.virtualImportTypeForLocal(obj_id.name, object)) orelse return null;
            if (self.objectHasCallOrConstructSignature(import_t) or self.typeUnionAllCallable(import_t)) return null;
            return .{ .obj_name = obj_id.name, .prop_name = prop_name };
        }
        if (!self.identifierNamesUntypedObjectLiteralBindingInScope(obj_id.name, node)) return null;
        return .{ .obj_name = obj_id.name, .prop_name = prop_name };
    }

    fn checkJsObjectExpandoTypeRef(self: *Checker, type_node: NodeId) CheckError!?TypeId {
        if (!self.sourceHasCheckJsDirective()) return null;
        if (self.hir.kindOf(type_node) != .type_ref) return null;
        const r = hir_mod.typeRefOf(self.hir, type_node);
        if (r.qualifier_len != 1) return null;
        const qualifiers = hir_mod.typeRefQualifier(self.hir, type_node);
        if (qualifiers.len != 1 or self.hir.kindOf(qualifiers[0]) != .identifier) return null;
        const root_id = hir_mod.identifierOf(self.hir, qualifiers[0]);
        return try self.checkJsObjectExpandoQualifiedType(root_id.name, r.name, type_node);
    }

    fn checkJsObjectExpandoQualifiedType(
        self: *Checker,
        root_name: hir_mod.StringId,
        member_name: hir_mod.StringId,
        anchor: NodeId,
    ) CheckError!?TypeId {
        const key: MemberKey = .{ .obj_name = root_name, .prop_name = member_name };
        const value_t = self.checkjs_object_expando_narrows.get(key) orelse
            (try self.checkJsObjectExpandoAssignmentValueType(root_name, member_name, anchor)) orelse blk: {
            if (try self.programScriptObjectExpandoInstanceType(root_name, member_name)) |instance_t| {
                try self.recordObjectExpandoInstanceDisplay(instance_t, member_name);
                return instance_t;
            }
            break :blk null;
        } orelse
            return null;
        const instance_t = if (try self.constructReturnType(value_t)) |constructed|
            constructed
        else
            try self.checkJsObjectExpandoPrototypeInstanceType(root_name, member_name, anchor);
        try self.recordObjectExpandoInstanceDisplay(instance_t, member_name);
        return instance_t;
    }

    fn programScriptObjectExpandoInstanceType(
        self: *Checker,
        root_name: hir_mod.StringId,
        member_name: hir_mod.StringId,
    ) CheckError!?TypeId {
        const root_text = self.string_interner.get(root_name);
        const member_text = self.string_interner.get(member_name);
        for (self.script_object_expandos) |expando| {
            if (!std.mem.eql(u8, expando.root, root_text)) continue;
            if (!std.mem.eql(u8, expando.member, member_text)) continue;
            return self.interner.internObjectType(&.{}) catch return error.OutOfMemory;
        }
        return null;
    }

    fn checkJsObjectExpandoAssignmentValueType(
        self: *Checker,
        root_name: hir_mod.StringId,
        member_name: hir_mod.StringId,
        anchor: NodeId,
    ) CheckError!?TypeId {
        if (!self.identifierNamesUntypedObjectLiteralBindingInScope(root_name, anchor)) return null;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        // Scan the whole section, not just statements before the use: a JSDoc
        // type reference to an object-expando member (`@type {NS.Member}`) may
        // FORWARD-reference an `NS.Member = …` assignment that appears later in
        // source order, which tsc still resolves. Pins
        // jsdocTypeReferenceToMergedClass.
        const anchor_section = self.virtualSectionStartForNode(anchor);
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.sourceHasVirtualFilenameSections() and self.virtualSectionStartForNode(stmt) != anchor_section) continue;
            const node = self.unwrapExportDecl(stmt);
            if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .assignment) continue;
            const a = hir_mod.assignmentOf(self.hir, node);
            if (a.op != null or a.target == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(a.target) != .member_access) continue;
            const target = hir_mod.memberOf(self.hir, a.target);
            if (target.name != member_name) continue;
            if (target.object == hir_mod.none_node_id or self.hir.kindOf(target.object) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, target.object).name != root_name) continue;
            if (a.value == hir_mod.none_node_id) return types.Primitive.any;
            const value_t = self.hir.typeOf(a.value);
            if (value_t != types.Primitive.none and value_t != types.Primitive.unknown) return value_t;
            return try self.checkExpression(a.value);
        }
        return null;
    }

    fn checkJsObjectExpandoPrototypeInstanceType(
        self: *Checker,
        root_name: hir_mod.StringId,
        member_name: hir_mod.StringId,
        anchor: NodeId,
    ) CheckError!TypeId {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) {
            return self.interner.internObjectType(&.{}) catch return error.OutOfMemory;
        }
        // Prototype assignments (`NS.Member.prototype = { … }`) may likewise
        // appear after a forward `@type {NS.Member}` reference, so scan the
        // whole section rather than stopping at the use point.
        const anchor_section = self.virtualSectionStartForNode(anchor);
        const prototype_name = self.string_interner.intern("prototype") catch return error.OutOfMemory;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.sourceHasVirtualFilenameSections() and self.virtualSectionStartForNode(stmt) != anchor_section) continue;
            const node = self.unwrapExportDecl(stmt);
            if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .assignment) continue;
            const a = hir_mod.assignmentOf(self.hir, node);
            if (a.op != null or a.target == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(a.target) != .member_access) continue;
            const proto_access = hir_mod.memberOf(self.hir, a.target);
            if (proto_access.name != prototype_name) continue;
            if (proto_access.object == hir_mod.none_node_id or self.hir.kindOf(proto_access.object) != .member_access) continue;
            const ctor_access = hir_mod.memberOf(self.hir, proto_access.object);
            if (ctor_access.name != member_name) continue;
            if (ctor_access.object == hir_mod.none_node_id or self.hir.kindOf(ctor_access.object) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, ctor_access.object).name != root_name) continue;
            if (a.value == hir_mod.none_node_id or self.hir.kindOf(a.value) != .object_literal) break;
            const proto_t = self.hir.typeOf(a.value);
            if (proto_t != types.Primitive.none and proto_t != types.Primitive.unknown) return proto_t;
            return try self.checkExpression(a.value);
        }
        return self.interner.internObjectType(&.{}) catch return error.OutOfMemory;
    }

    fn recordObjectExpandoInstanceDisplay(self: *Checker, instance_t: TypeId, name: hir_mod.StringId) !void {
        if (instance_t < types.Primitive.first_dynamic or instance_t >= self.interner.pool.typeCount()) return;
        if (self.alias_display_names.contains(instance_t)) return;
        try self.alias_display_names.put(self.gpa, instance_t, self.string_interner.get(name));
    }

    fn identifierNamesUntypedObjectLiteralBindingInScope(self: *Checker, name: hir_mod.StringId, from_node: NodeId) bool {
        const use_start = self.hir.spanOf(from_node).start;
        const has_sections = self.sourceHasVirtualFilenameSections();
        const section_start = if (has_sections) self.virtualSectionStartForNode(from_node) else 0;
        var cur = self.hir.parentOf(from_node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                for (hir_mod.fnParams(self.hir, cur)) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, pp.name).name == name) return false;
                }
            }
            const stmts: ?[]const NodeId = switch (k) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl => hir_mod.namespaceBody(self.hir, cur),
                else => null,
            };
            if (stmts) |items| {
                for (items) |stmt| {
                    if (self.hir.spanOf(stmt).start > use_start) break;
                    const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
                    if (decl == hir_mod.none_node_id) continue;
                    if (has_sections and self.virtualSectionStartForNode(decl) != section_start) continue;
                    const dk = self.hir.kindOf(decl);
                    if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
                    const v = hir_mod.varDeclOf(self.hir, decl);
                    if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, v.name).name != name) continue;
                    if (v.type_annotation != hir_mod.none_node_id or self.varDeclHasJsDocTypeTag(decl)) return false;
                    return v.init != hir_mod.none_node_id and self.hir.kindOf(v.init) == .object_literal;
                }
            }
        }
        return false;
    }

    fn memberAccessIsModuleExports(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) != .member_access) return false;
        return self.nodeIsModuleExportsAccess(node);
    }

    fn nodeIsModuleExportsAccess(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        if (self.propertyAccessName(node)) |name| {
            if (!std.mem.eql(u8, self.string_interner.get(name), "exports")) return false;
        } else return false;
        const object = self.propertyAccessObject(node) orelse return false;
        if (self.hir.kindOf(object) != .identifier) return false;
        const obj_id = hir_mod.identifierOf(self.hir, object);
        return std.mem.eql(u8, self.string_interner.get(obj_id.name), "module");
    }

    fn propertyAccessName(self: *Checker, node: NodeId) ?hir_mod.StringId {
        return switch (self.hir.kindOf(node)) {
            .member_access => blk: {
                const m = hir_mod.memberOf(self.hir, node);
                if (m.optional) break :blk null;
                break :blk m.name;
            },
            .element_access => blk: {
                const e = hir_mod.elementOf(self.hir, node);
                if (e.optional or e.index == hir_mod.none_node_id) break :blk null;
                if (self.hir.kindOf(e.index) != .literal_string) break :blk null;
                break :blk hir_mod.literalStringOf(self.hir, e.index).value;
            },
            else => null,
        };
    }

    fn propertyAccessObject(self: *Checker, node: NodeId) ?NodeId {
        return switch (self.hir.kindOf(node)) {
            .member_access => blk: {
                const m = hir_mod.memberOf(self.hir, node);
                if (m.object == hir_mod.none_node_id) break :blk null;
                break :blk m.object;
            },
            .element_access => blk: {
                const e = hir_mod.elementOf(self.hir, node);
                if (e.object == hir_mod.none_node_id) break :blk null;
                break :blk e.object;
            },
            else => null,
        };
    }

    fn recordMemberPredicatesForReceiver(
        self: *Checker,
        receiver_t: TypeId,
        predicates: *const std.AutoHashMapUnmanaged(hir_mod.StringId, FnPredicate),
    ) !void {
        var it = predicates.iterator();
        while (it.next()) |entry| {
            try self.recordMemberPredicate(receiver_t, entry.key_ptr.*, entry.value_ptr.*);
        }
    }

    /// Build the `this is T` predicate carried by a function/arrow node's
    /// return-type annotation, independent of its (possibly collision-prone,
    /// predicate-erased) signature TypeId. Used to register a per-member
    /// predicate for an anonymous arrow class field (`isElite = (): this is
    /// ArrowElite => …`), which never lands in `signature_predicates` (that
    /// path keys on the function NAME, which an arrow field lacks). Mirrors
    /// `typeGuardFunctionOfFormThis`.
    fn predicateForFnNode(self: *Checker, fn_node: NodeId) CheckError!?FnPredicate {
        const k = self.hir.kindOf(fn_node);
        if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) return null;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (f.return_type == hir_mod.none_node_id or self.hir.kindOf(f.return_type) != .type_predicate_type) return null;
        const pred = hir_mod.typePredicateOf(self.hir, f.return_type);
        const target_t: TypeId = if (pred.target_type != hir_mod.none_node_id)
            (self.lowererLowerWithTypeParams(pred.target_type) catch types.Primitive.unknown)
        else
            types.Primitive.unknown;
        return FnPredicate{
            .param_index = self.normalizedPredicateParamIndex(hir_mod.fnParams(self.hir, fn_node), pred.param_index),
            .target_type = target_t,
            .target_node = pred.target_type,
            .is_asserts = pred.is_asserts,
        };
    }

    fn normalizedPredicateParamIndex(self: *Checker, params: []const NodeId, raw_index: u16) u16 {
        if (raw_index == std.math.maxInt(u16)) return raw_index;
        var value_index: u16 = 0;
        for (params, 0..) |param, raw| {
            if (raw == raw_index) return value_index;
            if (!self.isThisParameter(param)) value_index +|= 1;
        }
        return raw_index;
    }

    fn recordMemberPredicate(
        self: *Checker,
        receiver_t: TypeId,
        member_name: hir_mod.StringId,
        pred: FnPredicate,
    ) !void {
        try self.member_predicates.put(self.gpa, .{
            .receiver_type = receiver_t,
            .member_name = member_name,
        }, pred);
    }

    fn copyMemberPredicatesFromReceiver(
        self: *Checker,
        receiver_t: TypeId,
        parent_t: TypeId,
    ) !void {
        if (parent_t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(parent_t);
        if (flags.is_type_parameter) {
            if (self.typeParameterConstraint(parent_t)) |constraint| {
                if (constraint != parent_t) try self.copyMemberPredicatesFromReceiver(receiver_t, constraint);
            }
            return;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(parent_t)) |member| {
                try self.copyMemberPredicatesFromReceiver(receiver_t, member);
            }
            return;
        }
        if (!flags.is_object_type) return;
        for (self.interner.objectMembers(parent_t)) |member| {
            if (self.member_predicates.contains(.{ .receiver_type = receiver_t, .member_name = member.name })) continue;
            if (self.lookupMemberPredicate(parent_t, member.name)) |pred| {
                try self.recordMemberPredicate(receiver_t, member.name, pred);
            }
        }
    }

    fn lookupMemberPredicate(
        self: *Checker,
        receiver_t: TypeId,
        member_name: hir_mod.StringId,
    ) ?FnPredicate {
        if (self.member_predicates.get(.{ .receiver_type = receiver_t, .member_name = member_name })) |pred| {
            return pred;
        }
        if (receiver_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(receiver_t);
        if (flags.is_type_parameter) {
            if (self.typeParameterConstraint(receiver_t)) |constraint| {
                if (constraint != receiver_t) return self.lookupMemberPredicate(constraint, member_name);
            }
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(receiver_t)) |member| {
                if (self.lookupMemberPredicate(member, member_name)) |pred| return pred;
            }
        }
        if (flags.is_union) {
            var found: ?FnPredicate = null;
            for (self.interner.unionMembers(receiver_t)) |member| {
                const pred = self.lookupMemberPredicate(member, member_name) orelse return null;
                if (found) |prior| {
                    if (prior.target_type != pred.target_type or prior.target_node != pred.target_node or
                        prior.param_index != pred.param_index or prior.is_asserts != pred.is_asserts)
                    {
                        return null;
                    }
                } else {
                    found = pred;
                }
            }
            return found;
        }
        return null;
    }

    /// Look up the topmost narrowed type for `name`, walking the
    /// scope stack from inner-most to outer-most.
    fn lookupNarrow(self: *Checker, name: hir_mod.StringId) ?TypeId {
        var i = self.narrow_scopes.items.len;
        const floor = @min(self.narrow_lookup_floor, i);
        while (i > floor) {
            i -= 1;
            if (self.narrow_scopes.items[i].get(name)) |t| return t;
        }
        while (i > 0) {
            i -= 1;
            if (self.narrow_scopes.items[i].get(name)) |t| {
                const name_str = self.string_interner.get(name);
                if (std.mem.eql(u8, name_str, "this") or std.mem.eql(u8, name_str, "super")) return t;
                if (t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(t).is_type_parameter) return t;
            }
        }
        return null;
    }

    fn typeOfIdentifierDeclared(self: *Checker, node: NodeId) TypeId {
        const old_floor = self.narrow_lookup_floor;
        const old_declared_lookup = self.declared_identifier_lookup;
        self.narrow_lookup_floor = self.narrow_scopes.items.len;
        self.declared_identifier_lookup = true;
        defer {
            self.narrow_lookup_floor = old_floor;
            self.declared_identifier_lookup = old_declared_lookup;
        }
        return self.typeOfIdentifier(node);
    }

    fn directNamespaceVariableAnnotationText(self: *Checker, node: NodeId) ?[]const u8 {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        const id = hir_mod.identifierOf(self.hir, node);
        const use_start = self.hir.spanOf(node).start;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .fn_decl, .fn_expr, .arrow_fn, .class_decl, .class_expr => return null,
                .namespace_decl => {
                    for (hir_mod.namespaceBody(self.hir, cur)) |stmt| {
                        if (self.hir.spanOf(stmt).start > use_start) break;
                        const decl = self.unwrapExportDecl(stmt);
                        const kind = self.hir.kindOf(decl);
                        if (kind != .var_decl and kind != .let_decl and kind != .const_decl) continue;
                        const variable = hir_mod.varDeclOf(self.hir, decl);
                        if (variable.name == hir_mod.none_node_id or self.hir.kindOf(variable.name) != .identifier) continue;
                        if (hir_mod.identifierOf(self.hir, variable.name).name != id.name) continue;
                        if (variable.type_annotation == hir_mod.none_node_id) return null;
                        const type_kind = self.hir.kindOf(variable.type_annotation);
                        if (type_kind != .type_ref and type_kind != .identifier) return null;
                        const text = std.mem.trim(u8, self.nodeSourceTextOrEmpty(variable.type_annotation), " \t\r\n");
                        return if (text.len > 0) text else null;
                    }
                    return null;
                },
                else => {},
            }
        }
        return null;
    }

    fn visibleActiveAnnotatedIdentifierType(self: *Checker, node: NodeId) ?TypeId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        const id = hir_mod.identifierOf(self.hir, node);
        const use_start = self.hir.spanOf(node).start;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                for (hir_mod.fnParams(self.hir, cur)) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, pp.name).name != id.name) continue;
                    return self.lowerActiveValueTypeAnnotation(id.name, pp.type_annotation) catch types.Primitive.any;
                }
            }
            const stmts: ?[]const NodeId = switch (k) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl => hir_mod.namespaceBody(self.hir, cur),
                else => null,
            };
            if (stmts) |items| {
                for (items) |stmt| {
                    if (self.hir.spanOf(stmt).start > use_start) break;
                    const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
                    if (decl == hir_mod.none_node_id) continue;
                    const dk = self.hir.kindOf(decl);
                    if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
                    const v = hir_mod.varDeclOf(self.hir, decl);
                    if (v.name == hir_mod.none_node_id) continue;
                    const name_kind = self.hir.kindOf(v.name);
                    if (name_kind == .identifier) {
                        if (hir_mod.identifierOf(self.hir, v.name).name != id.name) continue;
                        const active_t = (self.lowerActiveValueTypeAnnotation(id.name, v.type_annotation) catch types.Primitive.any) orelse return null;
                        return self.adjustAmbientUnresolvedBareTypeAnnotation(v.is_ambient, v.type_annotation, active_t) catch types.Primitive.any;
                    }
                    if (name_kind == .object_pattern or name_kind == .array_pattern) {
                        const declared_t = (self.lowerActiveValueTypeAnnotation(id.name, v.type_annotation) catch types.Primitive.any) orelse continue;
                        if (self.typeOfPatternBinding(v.name, declared_t, id.name)) |bt| return bt;
                    }
                }
            }
        }
        var nearest_annotation = hir_mod.none_node_id;
        var nearest_start: u32 = 0;
        var candidate: NodeId = 1;
        while (candidate < self.hir.nodeCount()) : (candidate += 1) {
            if (self.hir.kindOf(candidate) != .parameter) continue;
            const span = self.hir.spanOf(candidate);
            if (span.start > use_start) continue;
            const parameter = hir_mod.parameterOf(self.hir, candidate);
            if (parameter.name == hir_mod.none_node_id or self.hir.kindOf(parameter.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, parameter.name).name != id.name) continue;
            if (parameter.type_annotation == hir_mod.none_node_id) continue;
            if (nearest_annotation == hir_mod.none_node_id or span.start >= nearest_start) {
                nearest_start = span.start;
                nearest_annotation = parameter.type_annotation;
            }
        }
        if (nearest_annotation != hir_mod.none_node_id) {
            return self.lowerActiveValueTypeAnnotation(id.name, nearest_annotation) catch types.Primitive.any;
        }
        if (self.recoveredSourceParameterAnnotationType(node, id.name)) |recovered_t| return recovered_t;
        if (self.module) |module| {
            if (module.root.lookup(id.name)) |sym| {
                if (sym.decls.items.len == 0) return null;
                const decl = sym.decls.items[0];
                const dk = self.hir.kindOf(decl);
                if (dk != .var_decl and dk != .let_decl and dk != .const_decl) return null;
                const v = hir_mod.varDeclOf(self.hir, decl);
                if (v.name != hir_mod.none_node_id) {
                    const name_kind = self.hir.kindOf(v.name);
                    if (name_kind == .object_pattern or name_kind == .array_pattern) {
                        const declared_t = (self.lowerActiveValueTypeAnnotation(id.name, v.type_annotation) catch types.Primitive.any) orelse return null;
                        if (self.typeOfPatternBinding(v.name, declared_t, id.name)) |bt| return bt;
                    }
                }
                const active_t = (self.lowerActiveValueTypeAnnotation(id.name, v.type_annotation) catch types.Primitive.any) orelse return null;
                return self.adjustAmbientUnresolvedBareTypeAnnotation(v.is_ambient, v.type_annotation, active_t) catch types.Primitive.any;
            }
        }
        return null;
    }

    fn recoveredSourceParameterAnnotationType(self: *Checker, node: NodeId, name: hir_mod.StringId) ?TypeId {
        const source = self.source orelse return null;
        const raw_use_start: usize = @intCast(self.hir.spanOf(node).start);
        const use_start = @min(raw_use_start, source.len);
        const name_text = self.string_interner.get(name);
        if (name_text.len == 0 or use_start < name_text.len) return null;
        var search_end = use_start;
        while (std.mem.lastIndexOf(u8, source[0..search_end], name_text)) |found| {
            if (found > 0 and (std.ascii.isAlphanumeric(source[found - 1]) or source[found - 1] == '_' or source[found - 1] == '$')) {
                search_end = found;
                continue;
            }
            var cursor = found + name_text.len;
            while (cursor < use_start and std.ascii.isWhitespace(source[cursor])) cursor += 1;
            const optional = cursor < use_start and source[cursor] == '?';
            if (optional) cursor += 1;
            while (cursor < use_start and std.ascii.isWhitespace(source[cursor])) cursor += 1;
            if (cursor >= use_start or source[cursor] != ':') {
                search_end = found;
                continue;
            }
            if (!sourceParameterDeclarationContainsUse(source, found, use_start)) {
                search_end = found;
                continue;
            }
            cursor += 1;
            while (cursor < use_start and std.ascii.isWhitespace(source[cursor])) cursor += 1;
            const type_start = cursor;
            while (cursor < use_start and
                (std.ascii.isAlphanumeric(source[cursor]) or source[cursor] == '_' or source[cursor] == '$')) cursor += 1;
            if (cursor == type_start) {
                search_end = found;
                continue;
            }
            const type_end = cursor;
            while (cursor < use_start and std.ascii.isWhitespace(source[cursor])) cursor += 1;
            if (cursor >= use_start or
                (source[cursor] != ',' and source[cursor] != ')' and source[cursor] != '='))
            {
                search_end = found;
                continue;
            }
            const type_name = self.string_interner.intern(source[type_start..type_end]) catch return null;
            const base = self.contextualCallParameterTypeForRecoveredAnnotation(node, type_name) orelse
                self.recoveredNamedTypeAt(node, type_name) orelse {
                search_end = found;
                continue;
            };
            return if (optional) self.unionWithUndefined(base) catch base else base;
        }
        return null;
    }

    fn contextualCallParameterTypeForRecoveredAnnotation(
        self: *Checker,
        argument: NodeId,
        annotation_name: hir_mod.StringId,
    ) ?TypeId {
        const call_node = self.hir.parentOf(argument);
        if (call_node == hir_mod.none_node_id) return null;
        const call_kind = self.hir.kindOf(call_node);
        if (call_kind != .call_expr and call_kind != .new_expr) return null;
        const call = hir_mod.callOf(self.hir, call_node);
        if (self.hir.kindOf(call.callee) != .identifier) return null;
        const callee_name = hir_mod.identifierOf(self.hir, call.callee).name;
        const checked_callee_signature = blk: {
            const checked_t = self.hir.typeOf(call.callee);
            break :blk if (self.interner.isSignature(checked_t)) checked_t else types.Primitive.none;
        };
        var argument_index: ?usize = null;
        for (hir_mod.callArgs(self.hir, call_node), 0..) |candidate, index| {
            if (candidate == argument) {
                argument_index = index;
                break;
            }
        }
        const index = argument_index orelse return null;

        var declaration: NodeId = 1;
        while (declaration < self.hir.nodeCount()) : (declaration += 1) {
            const kind = self.hir.kindOf(declaration);
            if (kind != .fn_decl and kind != .fn_expr) continue;
            const function = hir_mod.fnDeclOf(self.hir, declaration);
            if (function.name == hir_mod.none_node_id or self.hir.kindOf(function.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, function.name).name != callee_name) continue;
            const params = hir_mod.fnParams(self.hir, declaration);
            if (index >= params.len or self.hir.kindOf(params[index]) != .parameter) continue;
            const parameter = hir_mod.parameterOf(self.hir, params[index]);
            if (parameter.type_annotation == hir_mod.none_node_id or self.hir.kindOf(parameter.type_annotation) != .type_ref) continue;
            const reference = hir_mod.typeRefOf(self.hir, parameter.type_annotation);
            if (reference.qualifier_len != 0 or reference.name != annotation_name) continue;
            const annotation_t = self.lowererLowerWithTypeParams(parameter.type_annotation) catch types.Primitive.none;
            if (checked_callee_signature != types.Primitive.none) {
                const checked_parameter_types = self.interner.signatureParams(checked_callee_signature);
                if (index < checked_parameter_types.len) {
                    const checked_parameter_t = checked_parameter_types[index];
                    if (!self.alias_display_names.contains(checked_parameter_t)) {
                        self.alias_display_names.put(
                            self.gpa,
                            checked_parameter_t,
                            self.string_interner.get(annotation_name),
                        ) catch {};
                    }
                    return checked_parameter_t;
                }
            }
            if (annotation_t != types.Primitive.none and
                annotation_t != types.Primitive.unknown and
                annotation_t != types.Primitive.any)
            {
                return annotation_t;
            }
            const signature = self.hir.typeOf(declaration);
            if (!self.interner.isSignature(signature)) continue;
            const parameter_types = self.interner.signatureParams(signature);
            if (index < parameter_types.len) return parameter_types[index];
        }
        return null;
    }

    fn recoveredNamedTypeAt(self: *Checker, anchor: NodeId, name: hir_mod.StringId) ?TypeId {
        if (self.findVisibleNamedTypeDecl(anchor, name)) |declaration| {
            const declaration_t = self.hir.typeOf(declaration);
            if (declaration_t != types.Primitive.none) return declaration_t;
        }

        const use_start = self.hir.spanOf(anchor).start;
        var nearest = hir_mod.none_node_id;
        var nearest_start: u32 = 0;
        var candidate: NodeId = 1;
        while (candidate < self.hir.nodeCount()) : (candidate += 1) {
            const kind = self.hir.kindOf(candidate);
            if (kind != .interface_decl and kind != .type_alias_decl and
                kind != .class_decl and kind != .class_expr) continue;
            const span = self.hir.spanOf(candidate);
            if (span.start >= use_start or span.start < nearest_start) continue;
            if (self.declarationName(candidate) != name) continue;
            nearest = candidate;
            nearest_start = span.start;
        }
        if (nearest != hir_mod.none_node_id) {
            const declaration_t = self.hir.typeOf(nearest);
            if (declaration_t != types.Primitive.none) return declaration_t;
        }
        return self.type_names.get(name);
    }

    fn sourceParameterDeclarationContainsUse(source: []const u8, name_start: usize, use_start: usize) bool {
        var open_search_end = name_start;
        while (std.mem.lastIndexOfScalar(u8, source[0..open_search_end], '(')) |open_paren| {
            open_search_end = open_paren;
            var depth: usize = 1;
            var cursor = open_paren + 1;
            while (cursor < source.len and depth > 0) : (cursor += 1) {
                if (source[cursor] == '(') depth += 1;
                if (source[cursor] == ')') depth -= 1;
            }
            if (depth != 0) continue;
            const close_paren = cursor - 1;
            if (close_paren < name_start) continue;
            const body_open = std.mem.indexOfScalarPos(u8, source, close_paren + 1, '{') orelse continue;
            if (body_open >= use_start) continue;
            if (std.mem.indexOfScalar(u8, source[close_paren + 1 .. body_open], ';') != null) continue;
            depth = 1;
            cursor = body_open + 1;
            while (cursor < use_start and depth > 0) : (cursor += 1) {
                if (source[cursor] == '{') depth += 1;
                if (source[cursor] == '}') depth -= 1;
            }
            if (depth > 0) return true;
        }
        return false;
    }

    fn sourceUseIsInsideTruthyIdentifierGuard(self: *Checker, node: NodeId, name: hir_mod.StringId) bool {
        const source = self.source orelse return false;
        const raw_use_start: usize = @intCast(self.hir.spanOf(node).start);
        const use_start = @min(raw_use_start, source.len);
        const name_text = self.string_interner.get(name);
        var search_end = use_start;
        while (std.mem.lastIndexOf(u8, source[0..search_end], "if")) |if_start| {
            search_end = if_start;
            if (if_start > 0 and (std.ascii.isAlphanumeric(source[if_start - 1]) or source[if_start - 1] == '_' or source[if_start - 1] == '$')) continue;
            var cursor = if_start + 2;
            while (cursor < use_start and std.ascii.isWhitespace(source[cursor])) cursor += 1;
            if (cursor >= use_start or source[cursor] != '(') continue;
            const close = std.mem.indexOfScalarPos(u8, source, cursor + 1, ')') orelse continue;
            if (close >= use_start) continue;
            const condition = std.mem.trim(u8, source[cursor + 1 .. close], " \t\r\n");
            if (!std.mem.eql(u8, condition, name_text)) continue;
            const open_brace = std.mem.indexOfScalarPos(u8, source, close + 1, '{') orelse continue;
            if (open_brace >= use_start) continue;
            var depth: usize = 1;
            cursor = open_brace + 1;
            while (cursor < use_start and depth > 0) : (cursor += 1) {
                if (source[cursor] == '{') depth += 1;
                if (source[cursor] == '}') depth -= 1;
            }
            if (depth > 0) return true;
        }
        return false;
    }

    fn sourceHasDirectSelfConditionalAssignmentBeforeUse(self: *Checker, node: NodeId, name: hir_mod.StringId) bool {
        const source = self.source orelse return false;
        const raw_use_start: usize = @intCast(self.hir.spanOf(node).start);
        const use_start = @min(raw_use_start, source.len);
        const statement_end = std.mem.lastIndexOfScalar(u8, source[0..use_start], ';') orelse return false;
        const prior_end = std.mem.lastIndexOfScalar(u8, source[0..statement_end], ';');
        const statement_start = if (prior_end) |end| end + 1 else 0;
        const statement = std.mem.trim(u8, source[statement_start..statement_end], " \t\r\n");
        const name_text = self.string_interner.get(name);
        var search_start: usize = 0;
        var cursor: usize = 0;
        while (std.mem.indexOfPos(u8, statement, search_start, name_text)) |name_start| {
            search_start = name_start + name_text.len;
            if (name_start > 0 and (std.ascii.isAlphanumeric(statement[name_start - 1]) or statement[name_start - 1] == '_' or statement[name_start - 1] == '$')) continue;
            const name_end = name_start + name_text.len;
            if (name_end < statement.len and (std.ascii.isAlphanumeric(statement[name_end]) or statement[name_end] == '_' or statement[name_end] == '$')) continue;
            cursor = name_end;
            while (cursor < statement.len and std.ascii.isWhitespace(statement[cursor])) cursor += 1;
            if (cursor >= statement.len or statement[cursor] != '=') continue;
            if (cursor + 1 < statement.len and (statement[cursor + 1] == '=' or statement[cursor + 1] == '>')) continue;
            break;
        } else return false;
        const rhs = statement[cursor + 1 ..];
        return std.mem.indexOfScalar(u8, rhs, '?') != null and
            std.mem.indexOfScalar(u8, rhs, ':') != null and
            std.mem.indexOf(u8, rhs, name_text) != null;
    }

    fn visibleAnnotatedIdentifierType(self: *Checker, node: NodeId) ?TypeId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        const id = hir_mod.identifierOf(self.hir, node);
        const use_start = self.hir.spanOf(node).start;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                for (hir_mod.fnParams(self.hir, cur)) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, pp.name).name != id.name) continue;
                    if (pp.type_annotation == hir_mod.none_node_id) return null;
                    return self.lowerValueTypeAnnotation(id.name, pp.type_annotation) catch types.Primitive.any;
                }
            }
            const stmts: ?[]const NodeId = switch (k) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl => hir_mod.namespaceBody(self.hir, cur),
                else => null,
            };
            if (stmts) |items| {
                for (items) |stmt| {
                    if (self.hir.spanOf(stmt).start > use_start) break;
                    const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
                    if (decl == hir_mod.none_node_id) continue;
                    const dk = self.hir.kindOf(decl);
                    if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
                    const v = hir_mod.varDeclOf(self.hir, decl);
                    if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, v.name).name != id.name) continue;
                    if (v.type_annotation == hir_mod.none_node_id) return null;
                    const annotated_t = self.lowerValueTypeAnnotation(id.name, v.type_annotation) catch types.Primitive.any;
                    return self.adjustAmbientUnresolvedBareTypeAnnotation(v.is_ambient, v.type_annotation, annotated_t) catch types.Primitive.any;
                }
            }
        }
        if (self.module) |module| {
            if (module.root.lookup(id.name)) |sym| {
                if (sym.decls.items.len == 0) return null;
                const decl = sym.decls.items[0];
                const dk = self.hir.kindOf(decl);
                if (dk != .var_decl and dk != .let_decl and dk != .const_decl) return null;
                const v = hir_mod.varDeclOf(self.hir, decl);
                if (v.type_annotation == hir_mod.none_node_id) return null;
                const annotated_t = self.lowerValueTypeAnnotation(id.name, v.type_annotation) catch types.Primitive.any;
                return self.adjustAmbientUnresolvedBareTypeAnnotation(v.is_ambient, v.type_annotation, annotated_t) catch types.Primitive.any;
            }
        }
        return null;
    }

    fn visibleUnannotatedVariableIdentifier(self: *Checker, node: NodeId) bool {
        return self.visibleUnannotatedVariableIdentifierNode(node) != null;
    }

    /// Like [`visibleUnannotatedVariableIdentifier`] but only true when the
    /// referenced variable is *genuinely* implicit-any: it has neither a type
    /// annotation nor an initializer. A `const path = "..."` is unannotated
    /// syntactically yet gets a concrete type from its initializer, so it must
    /// not drive the TS7057 implicit-any-yield diagnostic (tsc suppresses it
    /// because the yield operand's type is observed, not `any`). Mirrors
    /// `importCallExpressionReturnPromiseOfAny`.
    fn yieldOperandIsImplicitAnyIdentifier(self: *Checker, node: NodeId) bool {
        const name = self.visibleUnannotatedVariableIdentifierNode(node) orelse return false;
        const decl = self.hir.parentOf(name);
        if (decl == hir_mod.none_node_id) return true;
        switch (self.hir.kindOf(decl)) {
            .var_decl, .let_decl, .const_decl => {
                return hir_mod.varDeclOf(self.hir, decl).init == hir_mod.none_node_id;
            },
            else => return true,
        }
    }

    fn visibleUnannotatedVariableIdentifierNode(self: *Checker, node: NodeId) ?NodeId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        const id = hir_mod.identifierOf(self.hir, node);
        const use_start = self.hir.spanOf(node).start;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                for (hir_mod.fnParams(self.hir, cur)) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, pp.name).name != id.name) continue;
                    if (pp.type_annotation == hir_mod.none_node_id) return pp.name;
                    return null;
                }
            }
            const stmts: ?[]const NodeId = switch (k) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl => hir_mod.namespaceBody(self.hir, cur),
                else => null,
            };
            if (stmts) |items| {
                for (items) |stmt| {
                    if (self.hir.spanOf(stmt).start > use_start) break;
                    const decl = self.unwrapExportDecl(stmt);
                    const dk = self.hir.kindOf(decl);
                    if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
                    const v = hir_mod.varDeclOf(self.hir, decl);
                    if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, v.name).name != id.name) continue;
                    if (v.type_annotation == hir_mod.none_node_id) return v.name;
                    return null;
                }
            }
        }
        if (self.module) |module| {
            if (module.root.lookup(id.name)) |sym| {
                if (sym.decls.items.len == 0) return null;
                const decl = sym.decls.items[0];
                const dk = self.hir.kindOf(decl);
                if (dk != .var_decl and dk != .let_decl and dk != .const_decl) return null;
                const v = hir_mod.varDeclOf(self.hir, decl);
                if (v.type_annotation == hir_mod.none_node_id) return v.name;
                return null;
            }
        }
        return null;
    }

    fn visibleAnnotatedIdentifierTypeText(self: *Checker, node: NodeId) ?[]const u8 {
        const type_node = self.visibleAnnotatedIdentifierTypeNode(node) orelse return null;
        return self.nodeSourceTextOrEmpty(type_node);
    }

    fn topLevelAnnotatedVarTypeNodeBefore(self: *Checker, node: NodeId, name: hir_mod.StringId) ?NodeId {
        const root = self.rootBlockFor(node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        const use_start = self.hir.spanOf(node).start;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.hir.spanOf(stmt).start > use_start) break;
            const decl = self.unwrapExportDecl(stmt);
            const dk = self.hir.kindOf(decl);
            if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
            const v = hir_mod.varDeclOf(self.hir, decl);
            if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, v.name).name != name) continue;
            if (v.type_annotation == hir_mod.none_node_id) return null;
            return v.type_annotation;
        }
        return null;
    }

    fn visibleAnnotatedIdentifierTypeNode(self: *Checker, node: NodeId) ?NodeId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        const id = hir_mod.identifierOf(self.hir, node);
        const use_start = self.hir.spanOf(node).start;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                for (hir_mod.fnParams(self.hir, cur)) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, pp.name).name != id.name) continue;
                    if (pp.type_annotation == hir_mod.none_node_id) return null;
                    return pp.type_annotation;
                }
            }
            const stmts: ?[]const NodeId = switch (k) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl => hir_mod.namespaceBody(self.hir, cur),
                else => null,
            };
            if (stmts) |items| {
                for (items) |stmt| {
                    if (self.hir.spanOf(stmt).start > use_start) break;
                    const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
                    if (decl == hir_mod.none_node_id) continue;
                    const dk = self.hir.kindOf(decl);
                    if (dk != .var_decl and dk != .let_decl and dk != .const_decl) continue;
                    const v = hir_mod.varDeclOf(self.hir, decl);
                    if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, v.name).name != id.name) continue;
                    if (v.type_annotation == hir_mod.none_node_id) return null;
                    return v.type_annotation;
                }
            }
        }
        if (self.topLevelAnnotatedVarTypeNodeBefore(node, id.name)) |type_node| return type_node;
        if (self.module) |module| {
            if (module.root.lookup(id.name)) |sym| {
                if (sym.decls.items.len == 0) return null;
                const decl = sym.decls.items[0];
                const dk = self.hir.kindOf(decl);
                if (dk != .var_decl and dk != .let_decl and dk != .const_decl) return null;
                const v = hir_mod.varDeclOf(self.hir, decl);
                if (v.type_annotation == hir_mod.none_node_id) return null;
                return v.type_annotation;
            }
        }
        return null;
    }

    fn expressionRootHasUnresolvedAnnotation(self: *Checker, node: NodeId) bool {
        var root = node;
        while (root != hir_mod.none_node_id) {
            switch (self.hir.kindOf(root)) {
                .member_access => root = hir_mod.memberOf(self.hir, root).object,
                .element_access => root = hir_mod.elementOf(self.hir, root).object,
                .non_null_expr => root = hir_mod.asExpressionOf(self.hir, root).expr,
                .identifier => {
                    const type_node = self.visibleAnnotatedIdentifierTypeNode(root) orelse return false;
                    return self.typeAnnotationShouldBecomeErrorAny(type_node);
                },
                else => return false,
            }
        }
        return false;
    }

    fn simpleTypeAliasNameFromTypeNode(self: *Checker, type_node: NodeId) ?hir_mod.StringId {
        if (type_node == hir_mod.none_node_id) return null;
        return switch (self.hir.kindOf(type_node)) {
            .identifier => hir_mod.identifierOf(self.hir, type_node).name,
            .type_ref => blk: {
                const tr = hir_mod.typeRefOf(self.hir, type_node);
                if (tr.qualifier_len != 0 or tr.args_len != 0) break :blk null;
                break :blk tr.name;
            },
            else => null,
        };
    }

    fn localTypeAliasDeclForNameAt(self: *Checker, name: hir_mod.StringId, anchor: NodeId) ?NodeId {
        if (anchor == hir_mod.none_node_id) return null;
        var cur: NodeId = self.hir.parentOf(anchor);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const stmts: []const NodeId = switch (self.hir.kindOf(cur)) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl, .module_decl => hir_mod.namespaceBody(self.hir, cur),
                else => continue,
            };
            for (stmts) |raw| {
                const decl = self.unwrapExportDecl(raw);
                if (self.hir.kindOf(decl) != .type_alias_decl) continue;
                const ta = hir_mod.typeAliasOf(self.hir, decl);
                if (ta.name == hir_mod.none_node_id or self.hir.kindOf(ta.name) != .identifier) continue;
                if (hir_mod.identifierOf(self.hir, ta.name).name == name) return decl;
            }
        }
        return null;
    }

    fn typeAliasDeclForNameAt(self: *Checker, name: hir_mod.StringId, anchor: NodeId) ?NodeId {
        if (self.localTypeAliasDeclForNameAt(name, anchor)) |decl| return decl;
        if (self.module) |module| {
            if (module.root.lookup(name)) |sym| {
                if (sym.decls.items.len == 0) return null;
                const decl = sym.decls.items[0];
                if (self.hir.kindOf(decl) == .type_alias_decl) return decl;
            }
        }
        return null;
    }

    fn typeAliasBodyIsSingleLiteral(self: *Checker, body: NodeId) bool {
        return self.typeAliasBodyIsSingleLiteralDeep(body, 0);
    }

    fn typeAliasBodyIsSingleLiteralDeep(self: *Checker, body: NodeId, depth: usize) bool {
        if (body == hir_mod.none_node_id) return false;
        if (depth > 16) return false;
        if (self.typeAliasBodySourceIsEnumMemberRef(body)) return true;
        return switch (self.hir.kindOf(body)) {
            .type_literal => self.typeAliasBodyIsSingleLiteralDeep(hir_mod.literalTypeOf(self.hir, body).literal, depth + 1),
            .literal_string,
            .literal_number,
            .literal_bool,
            .literal_bigint,
            .literal_null,
            .literal_undefined,
            => true,
            .unary_op => blk: {
                const u = hir_mod.unaryOf(self.hir, body);
                break :blk (u.op == .neg or u.op == .plus) and self.hir.kindOf(u.operand) == .literal_number;
            },
            .type_ref => blk: {
                const r = hir_mod.typeRefOf(self.hir, body);
                if (r.qualifier_len == 0 and r.args_len == 0) {
                    const decl = self.typeAliasDeclForNameAt(r.name, body) orelse break :blk false;
                    const ta = hir_mod.typeAliasOf(self.hir, decl);
                    if (ta.type_params_len != 0) break :blk false;
                    break :blk self.typeAliasBodyIsSingleLiteralDeep(ta.aliased, depth + 1);
                }
                if (r.qualifier_len == 0 and r.args_len == 1 and stringMappingKindFromName(self.string_interner.get(r.name)) != null) {
                    const args = hir_mod.typeRefArgs(self.hir, body);
                    break :blk self.typeAliasBodyIsSingleLiteralDeep(args[0], depth + 1);
                }
                if (r.args_len != 0 or r.qualifier_len != 1) break :blk false;
                const qualifiers = self.hir.childSlice(r.qualifier_start, r.qualifier_len);
                if (self.hir.kindOf(qualifiers[0]) != .identifier) break :blk false;
                const enum_name = hir_mod.identifierOf(self.hir, qualifiers[0]).name;
                break :blk self.enumHasMemberAt(enum_name, r.name, body);
            },
            else => false,
        };
    }

    fn typeAliasBodySourceIsEnumMemberRef(self: *Checker, body: NodeId) bool {
        const text = std.mem.trim(u8, self.nodeSourceTextOrEmpty(body), " \t\r\n");
        const dot = std.mem.indexOfScalar(u8, text, '.') orelse return false;
        if (std.mem.indexOfScalar(u8, text[dot + 1 ..], '.') != null) return false;
        const enum_text = text[0..dot];
        const member_text = text[dot + 1 ..];
        if (enum_text.len == 0 or member_text.len == 0) return false;
        const enum_name = self.string_interner.intern(enum_text) catch return false;
        const member_name = self.string_interner.intern(member_text) catch return false;
        return self.enumHasMemberAt(enum_name, member_name, body);
    }

    fn annotatedIdentifierIsSingleLiteralAlias(self: *Checker, node: NodeId) bool {
        const type_node = self.visibleAnnotatedIdentifierTypeNode(node) orelse return false;
        const alias_name = self.simpleTypeAliasNameFromTypeNode(type_node) orelse return false;
        const decl = self.typeAliasDeclForNameAt(alias_name, type_node) orelse return false;
        const ta = hir_mod.typeAliasOf(self.hir, decl);
        if (ta.type_params_len != 0) return false;
        return self.typeAliasBodyIsSingleLiteral(ta.aliased);
    }

    fn singleLiteralAliasEnumMemberDisplayName(self: *Checker, node: NodeId) CheckError!?[]const u8 {
        const type_node = self.visibleAnnotatedIdentifierTypeNode(node) orelse return null;
        const alias_name = self.simpleTypeAliasNameFromTypeNode(type_node) orelse return null;
        const decl = self.typeAliasDeclForNameAt(alias_name, type_node) orelse return null;
        const ta = hir_mod.typeAliasOf(self.hir, decl);
        if (ta.type_params_len != 0) return null;
        if (!self.typeAliasBodySourceIsEnumMemberRef(ta.aliased)) return null;
        return try self.normalizedTypeAnnotationText(self.nodeSourceTextOrEmpty(ta.aliased));
    }

    fn switchDiscriminantIdentifierDisplayName(self: *Checker, node: NodeId) CheckError!?[]const u8 {
        if (try self.singleLiteralAliasEnumMemberDisplayName(node)) |name| return name;
        const text = self.visibleAnnotatedIdentifierTypeText(node) orelse return null;
        if (!isSimpleTypeAliasName(text)) {
            if (try self.sortedStringLiteralUnionAnnotationText(text)) |sorted| return sorted;
            if (std.mem.indexOfScalar(u8, text, '|') != null) return try self.normalizedTypeAnnotationText(text);
            return null;
        }
        const type_node = self.visibleAnnotatedIdentifierTypeNode(node) orelse return null;
        const alias_name = self.simpleTypeAliasNameFromTypeNode(type_node) orelse return null;
        _ = self.typeAliasDeclForNameAt(alias_name, type_node) orelse return null;
        return try self.normalizedTypeAnnotationText(text);
    }

    fn sortedStringLiteralUnionAnnotationText(self: *Checker, text: []const u8) CheckError!?[]const u8 {
        if (std.mem.indexOfScalar(u8, text, '|') == null) return null;
        var parts = std.mem.splitScalar(u8, text, '|');
        var values: std.ArrayListUnmanaged([]const u8) = .empty;
        defer values.deinit(self.gpa);
        while (parts.next()) |part| {
            const trimmed = std.mem.trim(u8, part, " \t\r\n");
            if (trimmed.len < 2 or trimmed[0] != '"' or trimmed[trimmed.len - 1] != '"') return null;
            try values.append(self.gpa, trimmed);
        }
        if (values.items.len < 2) return null;
        std.mem.sort([]const u8, values.items, {}, lessThanStringLiteralText);
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        for (values.items, 0..) |value, i| {
            if (i > 0) try buf.appendSlice(arena, " | ");
            try buf.appendSlice(arena, value);
        }
        return buf.items;
    }

    fn lessThanStringLiteralText(_: void, a: []const u8, b: []const u8) bool {
        return std.mem.lessThan(u8, a, b);
    }

    fn functionTypeAnnotationPredicate(self: *Checker, type_node: NodeId) CheckError!?FnPredicate {
        if (type_node == hir_mod.none_node_id) return null;
        const k = self.hir.kindOf(type_node);
        if (k != .fn_type and k != .constructor_type) return null;
        const ft = hir_mod.fnTypeOf(self.hir, type_node);
        if (ft.return_type == hir_mod.none_node_id or
            self.hir.kindOf(ft.return_type) != .type_predicate_type)
        {
            return null;
        }
        const pred = hir_mod.typePredicateOf(self.hir, ft.return_type);
        const target_t: TypeId = if (pred.target_type != hir_mod.none_node_id)
            (try self.lowererLowerWithTypeParams(pred.target_type))
        else
            types.Primitive.unknown;
        const params = self.hir.childSlice(ft.params_start, ft.params_len);
        return .{
            .param_index = self.normalizedPredicateParamIndex(params, pred.param_index),
            .target_type = target_t,
            .target_node = pred.target_type,
            .is_asserts = pred.is_asserts,
        };
    }

    fn signaturePredicateAnnotationsAssignable(
        self: *Checker,
        source_pred_opt: ?FnPredicate,
        target_pred: FnPredicate,
    ) CheckError!bool {
        const source_pred = source_pred_opt orelse return false;
        if (source_pred.param_index != target_pred.param_index) return false;
        if (source_pred.is_asserts != target_pred.is_asserts) return false;
        if (source_pred.target_type == target_pred.target_type) return true;
        if (source_pred.target_type == types.Primitive.none or target_pred.target_type == types.Primitive.none) {
            return source_pred.target_type == target_pred.target_type;
        }
        return self.engine.isAssignableTo(source_pred.target_type, target_pred.target_type) catch return error.OutOfMemory;
    }

    fn varDeclSignaturePredicateAssignmentInfo(
        self: *Checker,
        init_node: NodeId,
        target_type_node: NodeId,
        init_t: TypeId,
        declared_t: TypeId,
    ) CheckError!?SignaturePredicateAssignmentInfo {
        if (target_type_node == hir_mod.none_node_id) return null;
        if (!self.interner.isSignature(init_t) or !self.interner.isSignature(declared_t)) return null;
        if (init_node == hir_mod.none_node_id or self.hir.kindOf(init_node) != .identifier) return null;
        const target_pred = (try self.functionTypeAnnotationPredicate(target_type_node)) orelse return null;
        const source_type_node = self.visibleAnnotatedIdentifierTypeNode(init_node) orelse return null;
        const source_pred = try self.functionTypeAnnotationPredicate(source_type_node);
        if (try self.signaturePredicateAnnotationsAssignable(source_pred, target_pred)) return null;
        return .{
            .source_type_node = source_type_node,
            .target_type_node = target_type_node,
            .source_pred = source_pred,
            .target_pred = target_pred,
        };
    }

    fn varDeclSignaturePredicateAssignmentMismatches(
        self: *Checker,
        init_node: NodeId,
        target_type_node: NodeId,
        init_t: TypeId,
        declared_t: TypeId,
    ) CheckError!bool {
        return (try self.varDeclSignaturePredicateAssignmentInfo(init_node, target_type_node, init_t, declared_t)) != null;
    }

    fn trimmedTypeNodeText(self: *Checker, node: NodeId) []const u8 {
        return std.mem.trim(u8, self.nodeSourceTextOrEmpty(node), " \t\r\n");
    }

    fn functionTypeAnnotationSignatureText(self: *Checker, node: NodeId) CheckError![]const u8 {
        const text = self.trimmedTypeNodeText(node);
        const arrow = std.mem.indexOf(u8, text, "=>") orelse return text;
        const left = std.mem.trim(u8, text[0..arrow], " \t\r\n");
        const right = std.mem.trim(u8, text[arrow + 2 ..], " \t\r\n");
        return try std.fmt.allocPrint(self.diag_arena.allocator(), "{s}: {s}", .{ left, right });
    }

    fn buildSignaturePredicateAnnotationChain(
        self: *Checker,
        source_sig: TypeId,
        target_sig: TypeId,
        info: SignaturePredicateAssignmentInfo,
    ) CheckError![]const DiagnosticChainEntry {
        const arena = self.diag_arena.allocator();
        const slice = try arena.alloc(DiagnosticChainEntry, 1);
        if (info.source_pred == null) {
            const source_sig_text = try self.functionTypeAnnotationSignatureText(info.source_type_node);
            const msg = try std.fmt.allocPrint(
                arena,
                "Signature '{s}' must be a type predicate.",
                .{source_sig_text},
            );
            slice[0] = .{ .code = TsCodes.signature_must_be_type_predicate, .message = msg };
            return slice;
        }
        const source_pred = info.source_pred.?;
        const source_text = try self.allocTypePredicateName(source_sig, source_pred);
        const target_text = try self.allocTypePredicateName(target_sig, info.target_pred);
        const msg = try std.fmt.allocPrint(
            arena,
            "Type predicate '{s}' is not assignable to '{s}'.",
            .{ source_text, target_text },
        );
        const this_predicate = std.math.maxInt(u16);
        if ((source_pred.param_index == this_predicate) != (info.target_pred.param_index == this_predicate)) {
            const child = try arena.alloc(DiagnosticChainEntry, 1);
            child[0] = .{
                .code = TsCodes.this_type_guard_not_parameter_type_guard,
                .message = "A 'this'-based type guard is not compatible with a parameter-based type guard.",
            };
            slice[0] = .{ .code = TsCodes.type_predicate_not_assignable, .message = msg, .children = child };
            return slice;
        }
        if (source_pred.param_index != info.target_pred.param_index) {
            const child = try arena.alloc(DiagnosticChainEntry, 1);
            const child_msg = try std.fmt.allocPrint(
                arena,
                "Parameter '{s}' is not in the same position as parameter '{s}'.",
                .{ try self.typePredicateParamName(source_sig, source_pred), try self.typePredicateParamName(target_sig, info.target_pred) },
            );
            child[0] = .{ .code = TsCodes.type_predicate_parameter_position_mismatch, .message = child_msg };
            slice[0] = .{ .code = TsCodes.type_predicate_not_assignable, .message = msg, .children = child };
            return slice;
        }
        if (source_pred.target_type != types.Primitive.none and info.target_pred.target_type != types.Primitive.none and
            !(self.engine.isAssignableTo(source_pred.target_type, info.target_pred.target_type) catch true))
        {
            const child = try arena.alloc(DiagnosticChainEntry, 1);
            child[0] = try self.typeNotAssignableChainEntry(source_pred.target_type, info.target_pred.target_type, false);
            slice[0] = .{ .code = TsCodes.type_predicate_not_assignable, .message = msg, .children = child };
            return slice;
        }
        slice[0] = .{ .code = TsCodes.type_predicate_not_assignable, .message = msg };
        return slice;
    }

    fn tryReportVarDeclSignaturePredicateAssignment(
        self: *Checker,
        node: NodeId,
        init_node: NodeId,
        target_type_node: NodeId,
        init_t: TypeId,
        declared_t: TypeId,
    ) CheckError!bool {
        const info = (try self.varDeclSignaturePredicateAssignmentInfo(init_node, target_type_node, init_t, declared_t)) orelse return false;
        const source_name = self.trimmedTypeNodeText(info.source_type_node);
        const target_name = self.trimmedTypeNodeText(info.target_type_node);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' is not assignable to type '{s}'.",
            .{ source_name, target_name },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.type_not_assignable,
            .message = msg,
            .chain = try self.buildSignaturePredicateAnnotationChain(init_t, declared_t, info),
            .related = try self.sourceTypeParameterConstraintHintRelated(init_t, declared_t),
        });
        return true;
    }

    fn nullableAnnotationDiagnosticNameForIdentifier(self: *Checker, node: NodeId, keep_top_level_nullish: bool) CheckError!?[]const u8 {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return null;
        const id = hir_mod.identifierOf(self.hir, node);
        if (self.lookupNarrow(id.name) != null) return null;
        const type_node = self.visibleAnnotatedIdentifierTypeNode(node) orelse return null;
        const text = self.nodeSourceTextOrEmpty(type_node);
        if (std.mem.indexOf(u8, text, "null") == null and std.mem.indexOf(u8, text, "undefined") == null) return null;
        return try self.allocTypeAnnotationDiagnosticName(type_node, !keep_top_level_nullish);
    }

    fn allocTypeAnnotationDiagnosticName(self: *Checker, type_node: NodeId, strip_top_level_nullish: bool) CheckError!?[]const u8 {
        if (type_node == hir_mod.none_node_id) return null;
        const arena = self.diag_arena.allocator();
        return switch (self.hir.kindOf(type_node)) {
            .union_type => blk: {
                var buf: std.ArrayListUnmanaged(u8) = .empty;
                var first = true;
                var has_null = false;
                var has_undefined = false;
                var empty_object_count: usize = 0;
                for (hir_mod.unionTypeMembers(self.hir, type_node)) |member| {
                    const member_name = (try self.allocTypeAnnotationDiagnosticName(member, false)) orelse return null;
                    if (std.mem.eql(u8, member_name, "null")) {
                        has_null = true;
                        continue;
                    }
                    if (std.mem.eql(u8, member_name, "undefined")) {
                        has_undefined = true;
                        continue;
                    }
                    if (std.mem.eql(u8, member_name, "{}")) {
                        empty_object_count += 1;
                        continue;
                    }
                    if (!first) try buf.appendSlice(arena, " | ");
                    first = false;
                    const member_kind = self.hir.kindOf(member);
                    const needs_parens = member_kind == .fn_type or member_kind == .constructor_type;
                    if (needs_parens) try buf.append(arena, '(');
                    try buf.appendSlice(arena, member_name);
                    if (needs_parens) try buf.append(arena, ')');
                }
                while (empty_object_count > 0) : (empty_object_count -= 1) {
                    if (!first) try buf.appendSlice(arena, " | ");
                    first = false;
                    try buf.appendSlice(arena, "{}");
                }
                if (has_null and !strip_top_level_nullish) {
                    if (!first) try buf.appendSlice(arena, " | ");
                    first = false;
                    try buf.appendSlice(arena, "null");
                }
                if (has_undefined and !strip_top_level_nullish) {
                    if (!first) try buf.appendSlice(arena, " | ");
                    first = false;
                    try buf.appendSlice(arena, "undefined");
                }
                if (buf.items.len == 0) return null;
                break :blk buf.items;
            },
            .object_type => blk: {
                const object_members = hir_mod.objectTypeMembers(self.hir, type_node);
                if (object_members.len == 0) break :blk try arena.dupe(u8, "{}");
                var buf: std.ArrayListUnmanaged(u8) = .empty;
                try buf.appendSlice(arena, "{ ");
                var first = true;
                for (object_members) |member| {
                    if (self.hir.kindOf(member) != .interface_member) return null;
                    const im = hir_mod.interfaceMemberOf(self.hir, member);
                    if (im.name == 0 or im.type_node == hir_mod.none_node_id) return null;
                    const member_type = (try self.allocTypeAnnotationDiagnosticName(im.type_node, false)) orelse return null;
                    if (!first) try buf.append(arena, ' ');
                    first = false;
                    try buf.appendSlice(arena, self.string_interner.get(im.name));
                    if (im.is_optional) try buf.append(arena, '?');
                    try buf.appendSlice(arena, ": ");
                    try buf.appendSlice(arena, member_type);
                    try buf.appendSlice(arena, ";");
                }
                if (!first) try buf.append(arena, ' ');
                try buf.append(arena, '}');
                break :blk buf.items;
            },
            .fn_type, .constructor_type => blk: {
                const ft = hir_mod.fnTypeOf(self.hir, type_node);
                var buf: std.ArrayListUnmanaged(u8) = .empty;
                if (self.hir.kindOf(type_node) == .constructor_type) try buf.appendSlice(arena, "new ");
                try buf.append(arena, '(');
                for (self.hir.childSlice(ft.params_start, ft.params_len), 0..) |param_node, i| {
                    if (self.hir.kindOf(param_node) != .parameter) return null;
                    const param = hir_mod.parameterOf(self.hir, param_node);
                    if (param.name == hir_mod.none_node_id or self.hir.kindOf(param.name) != .identifier) return null;
                    if (param.type_annotation == hir_mod.none_node_id) return null;
                    const param_type = (try self.allocTypeAnnotationDiagnosticName(param.type_annotation, false)) orelse return null;
                    if (i > 0) try buf.appendSlice(arena, ", ");
                    if (param.flags.is_rest) try buf.appendSlice(arena, "...");
                    try buf.appendSlice(arena, self.string_interner.get(hir_mod.identifierOf(self.hir, param.name).name));
                    if (param.flags.is_optional) try buf.append(arena, '?');
                    try buf.appendSlice(arena, ": ");
                    try buf.appendSlice(arena, param_type);
                }
                try buf.appendSlice(arena, ") => ");
                const return_type = (try self.allocTypeAnnotationDiagnosticName(ft.return_type, false)) orelse return null;
                try buf.appendSlice(arena, return_type);
                break :blk buf.items;
            },
            .typeof_type => blk: {
                // `typeof undefined` denotes the `undefined` type itself —
                // tsc collapses the query and renders it as `undefined`,
                // never the raw `typeof undefined` query text. Other
                // typeof queries keep their source text. Mirrors
                // validUndefinedAssignments / invalidUndefinedValues.
                const tt = hir_mod.typeofTypeOf(self.hir, type_node);
                if (tt.operand != hir_mod.none_node_id and
                    self.hir.kindOf(tt.operand) == .identifier and
                    std.mem.eql(u8, self.string_interner.get(hir_mod.identifierOf(self.hir, tt.operand).name), "undefined"))
                {
                    break :blk try arena.dupe(u8, "undefined");
                }
                const text = std.mem.trim(u8, self.nodeSourceTextOrEmpty(type_node), " \t\r\n");
                if (text.len == 0) return null;
                break :blk try arena.dupe(u8, text);
            },
            else => blk: {
                const text = std.mem.trim(u8, self.nodeSourceTextOrEmpty(type_node), " \t\r\n");
                if (text.len == 0) return null;
                break :blk try arena.dupe(u8, text);
            },
        };
    }

    /// Detect simple type guards in `cond` and write their
    /// narrowing into the current scope.
    ///
    /// Recognized:
    ///   typeof X === "string" / "number" / "boolean" / "bigint" /
    ///                "symbol" / "undefined" / "object"
    ///     and the !== negation (with `when_true` flipped)
    ///   X === null / X !== null
    ///   X === undefined / X !== undefined
    /// True if `sig` accepts the given `arg_types` ÃÂ¢ÃÂÃÂ i.e., the call
    /// would type-check without TS2554 / TS2345. Used by overload
    /// resolution to pick an applicable signature.
    fn signatureAccepts(self: *Checker, call_node: NodeId, sig: TypeId, args: []const NodeId, arg_types: []const TypeId) !bool {
        const params = self.interner.signatureParams(sig);
        const is_variadic = self.rest_signatures.contains(sig) and params.len > 0;
        const fixed_count: usize = if (is_variadic) params.len - 1 else params.len;
        const fixed_min_required: usize = @min(self.signatureMinRequiredArgsForCall(sig, params, call_node), fixed_count);
        const rest_min_required: usize = if (is_variadic and params.len > 0) self.tupleRestMinRequiredCount(params[params.len - 1]) else 0;
        const min_required: usize = fixed_min_required + rest_min_required;
        var effective_count: usize = 0;
        for (args, 0..) |arg, arg_i| {
            effective_count += if (self.hir.kindOf(arg) == .spread)
                self.spreadArgArityContribution(arg_types[arg_i])
            else
                1;
        }
        if (effective_count < min_required) return false;
        if (!is_variadic and effective_count > params.len) return false;
        for (args, 0..) |arg, arg_i| {
            const fixed_pos = self.fixedParamPositionBeforeArg(args, arg_types, arg_i);
            if (fixed_pos >= fixed_count) break;
            const param_t = params[fixed_pos];
            if (param_t >= self.interner.pool.typeCount()) continue;
            if (self.interner.pool.flagsOf(param_t).is_type_parameter) continue;
            if (self.taggedTemplateStringsArrayArg(call_node, args, arg_i, param_t)) continue;
            if (try self.literalExpressionAssignableToTarget(arg, param_t)) continue;
            if (try self.templateExpressionAssignableToType(arg, param_t)) continue;
            const arg_t = arg_types[arg_i];
            if (self.hir.kindOf(arg) == .object_literal and
                (self.objectLiteralAssignableToTargetInner(arg, arg_t, param_t, false) catch false))
            {
                continue;
            }
            if (self.hir.kindOf(arg) == .spread) {
                if (!self.isTupleShapedTarget(arg_t)) {
                    if (self.fixedSpreadNeedsTupleDiagnostic(arg_t, params, fixed_pos, fixed_count, min_required)) return true;
                    const elem_t = self.interner.objectNumberIndex(arg_t);
                    if (elem_t != types.Primitive.none and (self.engine.isAssignableTo(elem_t, param_t) catch false)) continue;
                    return false;
                }
                var tuple_i: usize = 0;
                while (fixed_pos + tuple_i < fixed_count) : (tuple_i += 1) {
                    const elem_t = self.tupleElementType(arg_t, tuple_i);
                    if (elem_t == types.Primitive.none) break;
                    if (params[fixed_pos + tuple_i] >= self.interner.pool.typeCount()) continue;
                    if (self.interner.pool.flagsOf(params[fixed_pos + tuple_i]).is_type_parameter) continue;
                    if (!(self.engine.isAssignableTo(elem_t, params[fixed_pos + tuple_i]) catch false)) return false;
                }
                continue;
            }
            if (try self.overloadedIdentifierAssignableToParam(arg, param_t)) |overload_ok| {
                if (!overload_ok) return false;
                continue;
            }
            const ok = self.engine.isAssignableTo(arg_t, param_t) catch false;
            if (!ok) return false;
        }
        if (is_variadic) {
            const rest_arr_t = params[params.len - 1];
            if (rest_arr_t >= self.interner.pool.typeCount()) return true;
            const elem_t = self.interner.objectNumberIndex(rest_arr_t);
            const target_t = if (elem_t == types.Primitive.none) rest_arr_t else elem_t;
            if (target_t >= self.interner.pool.typeCount()) return true;
            if (self.interner.pool.flagsOf(target_t).is_type_parameter) return true;
            for (args, 0..) |arg, arg_i| {
                if (self.fixedParamPositionBeforeArg(args, arg_types, arg_i) < fixed_count) continue;
                var arg_t = arg_types[arg_i];
                {
                    if (self.taggedTemplateStringsArrayArg(call_node, args, arg_i, target_t)) continue;
                    if (try self.literalExpressionAssignableToTarget(arg, target_t)) continue;
                    if (try self.templateExpressionAssignableToType(arg, target_t)) continue;
                    if (self.hir.kindOf(arg) == .spread) {
                        const spread_elem_t = if (self.isTupleShapedTarget(arg_t))
                            self.tupleRestTailElementType(arg_t)
                        else
                            self.interner.objectNumberIndex(arg_t);
                        if (spread_elem_t != types.Primitive.none) arg_t = spread_elem_t;
                    }
                    if (!(try self.restArgumentAssignable(arg_t, target_t))) return false;
                }
            }
        }
        return true;
    }

    fn reportNoOverloadMatchesWithLastOverload(
        self: *Checker,
        call_node: NodeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        last_sig: TypeId,
    ) CheckError!void {
        const effective_sig = self.instantiateSignatureFromArgs(last_sig, args, arg_types) catch last_sig;
        const chain = (try self.lastOverloadArgumentErrorChain(call_node, args, arg_types, effective_sig)) orelse &.{};
        const error_node = if (try self.signatureArgumentErrorEntry(call_node, args, arg_types, effective_sig)) |arg_error|
            arg_error.node
        else
            call_node;
        var related: []const RelatedInfo = &.{};
        if (chain.len != 0) {
            const decl = self.signatureDeclNode(last_sig);
            if (decl != hir_mod.none_node_id) {
                related = try self.diag_arena.allocator().dupe(RelatedInfo, &.{.{
                    .node = decl,
                    .pos = self.declarationNameSpanStart(decl),
                    .code = TsCodes.last_overload_declared_here,
                    .message = "The last overload is declared here.",
                }});
            }
        }
        try self.diagnostics.append(self.gpa, .{
            .node = error_node,
            .code = TsCodes.no_overload_matches,
            .message = "No overload matches this call.",
            .chain = chain,
            .related = related,
        });
    }

    fn reportNoOverloadMatchesWithOverloads(
        self: *Checker,
        call_node: NodeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        overloads: []const TypeId,
    ) CheckError!void {
        if (overloads.len >= 2 and overloads.len <= 3) {
            const chain = try self.overloadArgumentErrorChains(call_node, args, arg_types, overloads);
            if (chain.len > 0) {
                const effective_last = self.instantiateSignatureFromArgs(overloads[overloads.len - 1], args, arg_types) catch overloads[overloads.len - 1];
                const error_node = if (try self.signatureArgumentErrorEntry(call_node, args, arg_types, effective_last)) |arg_error|
                    arg_error.node
                else
                    call_node;
                try self.diagnostics.append(self.gpa, .{
                    .node = error_node,
                    .code = TsCodes.no_overload_matches,
                    .message = "No overload matches this call.",
                    .chain = chain,
                });
                return;
            }
        }
        try self.reportNoOverloadMatchesWithLastOverload(call_node, args, arg_types, overloads[overloads.len - 1]);
    }

    fn overloadArgumentErrorChains(
        self: *Checker,
        call_node: NodeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        overloads: []const TypeId,
    ) CheckError![]const DiagnosticChainEntry {
        const arena = self.diag_arena.allocator();
        const entries = try arena.alloc(DiagnosticChainEntry, overloads.len);
        var count: usize = 0;
        for (overloads, 0..) |sig, i| {
            const effective_sig = self.instantiateSignatureFromArgs(sig, args, arg_types) catch sig;
            const arg_error = (try self.signatureArgumentErrorEntry(call_node, args, arg_types, effective_sig)) orelse continue;
            const children = try arena.alloc(DiagnosticChainEntry, 1);
            children[0] = arg_error.entry;
            const sig_text = (try self.allocCallSignatureNameColonReturn(sig)) orelse "unknown";
            const msg = try std.fmt.allocPrint(
                arena,
                "Overload {d} of {d}, '{s}', gave the following error.",
                .{ i + 1, overloads.len, sig_text },
            );
            entries[count] = .{
                .code = TsCodes.overload_n_error,
                .message = msg,
                .children = children,
            };
            count += 1;
        }
        return entries[0..count];
    }

    fn attachOverloadImplementationSuccessRelated(
        self: *Checker,
        call_node: NodeId,
        implementation_sig: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        diag_start: usize,
    ) CheckError!void {
        if (self.diagnostics.items.len == diag_start) return;
        const effective_impl = self.instantiateSignatureFromArgs(implementation_sig, args, arg_types) catch implementation_sig;
        if (!try self.signatureAccepts(call_node, effective_impl, args, arg_types)) return;
        const decl = self.signatureDeclNode(implementation_sig);
        if (decl == hir_mod.none_node_id) return;
        var last = &self.diagnostics.items[self.diagnostics.items.len - 1];
        const existing_len = last.related.len;
        const related = try self.diag_arena.allocator().alloc(RelatedInfo, existing_len + 1);
        if (existing_len > 0) @memcpy(related[0..existing_len], last.related);
        related[existing_len] = .{
            .node = decl,
            .pos = self.declarationNameSpanStart(decl),
            .code = TsCodes.overload_implementation_not_visible,
            .message = "The call would have succeeded against this implementation, but implementation signatures of overloads are not externally visible.",
        };
        last.related = related;
    }

    fn lastOverloadArgumentErrorChain(
        self: *Checker,
        call_node: NodeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        sig: TypeId,
    ) CheckError!?[]const DiagnosticChainEntry {
        const arg_error = (try self.signatureArgumentErrorEntry(call_node, args, arg_types, sig)) orelse return null;
        const arena = self.diag_arena.allocator();
        const outer = try arena.alloc(DiagnosticChainEntry, 1);
        const child = try arena.alloc(DiagnosticChainEntry, 1);
        child[0] = arg_error.entry;
        outer[0] = .{
            .code = TsCodes.last_overload_error,
            .message = "The last overload gave the following error.",
            .children = child,
        };
        return outer;
    }

    const SignatureArgumentError = struct {
        node: NodeId,
        entry: DiagnosticChainEntry,
    };

    fn signatureArgumentErrorEntry(
        self: *Checker,
        call_node: NodeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        sig: TypeId,
    ) CheckError!?SignatureArgumentError {
        const param_ts = self.interner.signatureParams(sig);
        const is_variadic = self.rest_signatures.contains(sig) and param_ts.len > 0;
        const fixed_count: usize = if (is_variadic) param_ts.len - 1 else param_ts.len;
        const min_required = self.signatureMinRequiredArgsForCall(sig, param_ts, call_node);
        for (args, 0..) |arg, arg_i| {
            const fixed_pos = self.fixedParamPositionBeforeArg(args, arg_types, arg_i);
            if (fixed_pos >= fixed_count) break;
            const param_t = param_ts[fixed_pos];
            if (param_t >= self.interner.pool.typeCount()) continue;
            if (self.interner.pool.flagsOf(param_t).is_type_parameter) continue;
            if (self.taggedTemplateStringsArrayArg(call_node, args, arg_i, param_t)) continue;
            if (try self.literalExpressionAssignableToTarget(arg, param_t)) continue;
            if (try self.templateExpressionAssignableToType(arg, param_t)) continue;

            var arg_t = arg_types[arg_i];
            if (self.hir.kindOf(arg) == .spread) {
                const elem_t = self.interner.objectNumberIndex(arg_t);
                if (elem_t != types.Primitive.none) arg_t = elem_t;
            }
            if (try self.sameEnclosingTypeParameterDisplay(arg, arg_t, param_t)) continue;
            if (self.engine.isAssignableTo(arg_t, param_t) catch false) continue;

            const raw_display_param_t = if (fixed_pos >= min_required and self.typeIncludesUndefined(param_t)) blk: {
                const without_undefined = self.subtractType(param_t, types.Primitive.undefined_t) catch param_t;
                break :blk if (without_undefined == types.Primitive.never or without_undefined == types.Primitive.none)
                    param_t
                else
                    without_undefined;
            } else param_t;
            const display_param_t = self.identifierFunctionReferenceDiagnosticTarget(
                arg,
                try self.templateLiteralDiagnosticTarget(raw_display_param_t),
            );
            if (display_param_t < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(display_param_t).is_template_literal)
            {
                arg_t = self.expressionLiteralType(arg, arg_t) catch arg_t;
            }
            const diagnostic_arg_t = if (self.interner.isSignature(display_param_t))
                self.identifierFunctionInitializerDiagnosticType(arg, arg_t)
            else
                arg_t;
            const msg = if (try self.formatNullishLiteralArgumentNotAssignable(arg, param_t)) |literal_msg|
                literal_msg
            else
                try self.formatArgumentNotAssignable(diagnostic_arg_t, display_param_t, arg_i);

            return .{
                .node = arg,
                .entry = .{
                    .code = TsCodes.argument_type_mismatch,
                    .message = msg,
                },
            };
        }
        return null;
    }

    fn typeIsFunctionObjectLike(self: *Checker, t: TypeId) CheckError!bool {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return true;
        const function_t = self.lowerBuiltinObjectType("Function") orelse return false;
        if (t == function_t) return true;
        return self.engine.isAssignableTo(t, function_t) catch false;
    }

    fn taggedTemplateStringsArrayArg(self: *Checker, call_node: NodeId, args: []const NodeId, arg_i: usize, param_t: TypeId) bool {
        if (arg_i != 0 or args.len == 0) return false;
        if (self.hir.kindOf(args[0]) != .array_literal) return false;
        if (!self.callExprIsTaggedTemplate(call_node)) return false;
        return self.typeIsTemplateStringsArray(param_t);
    }

    fn typeIsTemplateStringsArray(self: *Checker, t: TypeId) bool {
        const name = self.namedTypeForId(t) orelse return false;
        return std.mem.eql(u8, self.string_interner.get(name), "TemplateStringsArray");
    }

    fn signatureIsConstruct(self: *Checker, sig: TypeId) bool {
        if (!self.interner.isSignature(sig)) return false;
        const payload_idx = self.interner.pool.payloadOf(sig);
        if (payload_idx >= self.interner.pool.signature_payloads.items.len) return false;
        return self.interner.pool.signature_payloads.items[payload_idx].is_construct;
    }

    fn signatureIsAbstractConstruct(self: *Checker, sig: TypeId) bool {
        if (!self.interner.isSignature(sig)) return false;
        const payload_idx = self.interner.pool.payloadOf(sig);
        if (payload_idx >= self.interner.pool.signature_payloads.items.len) return false;
        const payload = self.interner.pool.signature_payloads.items[payload_idx];
        return payload.is_construct and payload.is_abstract_construct;
    }

    fn collectConstructSignatures(
        self: *Checker,
        t: TypeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!void {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                try self.collectConstructSignatures(member, out);
            }
            return;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                try self.collectConstructSignatures(member, out);
            }
            return;
        }
        if (self.interner.isSignature(t)) {
            if (self.signatureIsConstruct(t)) try out.append(self.gpa, t);
            return;
        }
        if (flags.is_type_parameter) {
            if (self.typeParameterConstraint(t)) |constraint| {
                if (constraint != t) try self.collectConstructSignatures(constraint, out);
            }
            return;
        }
        if (!flags.is_object_type) return;

        const construct_member_id = self.string_interner.intern("__construct") catch return error.OutOfMemory;
        for (self.interner.objectMembers(t)) |member| {
            if (member.name == construct_member_id and self.interner.isSignature(member.type)) {
                try out.append(self.gpa, member.type);
            }
        }
    }

    fn checkInferredArrayConstructorArguments(
        self: *Checker,
        node: NodeId,
        callee_node: NodeId,
        callee_t: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) CheckError!?TypeId {
        if (callee_node == hir_mod.none_node_id or self.hir.kindOf(callee_node) != .identifier) return null;
        if (hir_mod.callTypeArgs(self.hir, node).len != 0 or args.len <= 1 or args.len != arg_types.len) return null;
        const callee = hir_mod.identifierOf(self.hir, callee_node);
        if (!std.mem.eql(u8, self.string_interner.get(callee.name), "Array")) return null;
        const array_global = lib.arrayGlobal(
            &self.lib_cache,
            self.interner,
            self.string_interner,
            self.gpa,
            &self.rest_signatures,
        ) catch return null;
        if (callee_t != array_global) return null;

        const base_element_t = try self.widenFreshLiteralType(arg_types[0]);
        var saw_null = false;
        var saw_undefined = false;
        for (arg_types[1..], 1..) |arg_t, arg_index| {
            if (arg_t == types.Primitive.null_t) {
                saw_null = true;
                continue;
            }
            if (arg_t == types.Primitive.undefined_t or arg_t == types.Primitive.void_t) {
                saw_undefined = true;
                continue;
            }
            const target_t = try self.inferredArrayConstructorElementType(base_element_t, saw_null, saw_undefined);
            const widened_arg_t = try self.widenFreshLiteralType(arg_t);
            if (self.engine.isAssignableTo(widened_arg_t, target_t) catch false) continue;
            const diagnostic_arg_t = self.expressionLiteralType(args[arg_index], arg_t) catch arg_t;
            try self.diagnostics.append(self.gpa, .{
                .node = args[arg_index],
                .code = TsCodes.argument_type_mismatch,
                .message = try self.formatArgumentNotAssignable(diagnostic_arg_t, target_t, arg_index),
            });
            break;
        }
        const element_t = try self.inferredArrayConstructorElementType(base_element_t, saw_null, saw_undefined);
        return self.interner.internArrayType(self.string_interner, element_t) catch return error.OutOfMemory;
    }

    fn inferredArrayConstructorElementType(
        self: *Checker,
        base: TypeId,
        saw_null: bool,
        saw_undefined: bool,
    ) CheckError!TypeId {
        if (saw_null and saw_undefined) {
            return self.interner.internUnion(&.{ base, types.Primitive.null_t, types.Primitive.undefined_t }) catch return error.OutOfMemory;
        }
        if (saw_null) return self.unionWithNull(base) catch return error.OutOfMemory;
        if (saw_undefined) return self.unionWithUndefined(base) catch return error.OutOfMemory;
        return base;
    }

    fn checkNewConstructSignatures(
        self: *Checker,
        node: NodeId,
        callee_node: NodeId,
        callee_t: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) CheckError!?TypeId {
        var construct_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer construct_sigs.deinit(self.gpa);
        try self.collectConstructSignatures(callee_t, &construct_sigs);
        // Use declared *overload* constructor signatures for the named
        // class when present. The implementation signature is the one
        // that ends up in the static type's `__construct` member, but it
        // is not visible to external `new C(...)` resolution.
        if (callee_node != hir_mod.none_node_id and self.hir.kindOf(callee_node) == .identifier) {
            const callee_id = hir_mod.identifierOf(self.hir, callee_node);
            if (self.class_constructor_overload_sigs.get(callee_id.name)) |overload_list| {
                construct_sigs.clearRetainingCapacity();
                try construct_sigs.appendSlice(self.gpa, overload_list.items);
            }
        }
        if (construct_sigs.items.len == 0) return null;

        const type_arg_nodes = hir_mod.callTypeArgs(self.hir, node);
        var selected_sig: TypeId = construct_sigs.items[0];
        var selected_decl_sig: TypeId = construct_sigs.items[0];
        var found_applicable = false;
        var saw_generic_record = false;

        for (construct_sigs.items) |sig| {
            var effective_sig = sig;
            const sig_is_generic = self.generic_signature_params.get(sig) != null;
            if (type_arg_nodes.len > 0) {
                if (callee_node != hir_mod.none_node_id and self.hir.kindOf(callee_node) == .identifier) {
                    const class_name = hir_mod.identifierOf(self.hir, callee_node).name;
                    if (self.generic_aliases.contains(class_name)) {
                        effective_sig = try self.instantiateGenericClassConstructorSignatureForNew(
                            class_name,
                            sig,
                            type_arg_nodes,
                        );
                        saw_generic_record = true;
                    } else {
                        var used_explicit_type_args = false;
                        effective_sig = try self.instantiateSignatureWithExplicitTypeArgs(node, sig, type_arg_nodes, &used_explicit_type_args);
                        if (sig_is_generic) saw_generic_record = true;
                    }
                } else {
                    var used_explicit_type_args = false;
                    effective_sig = try self.instantiateSignatureWithExplicitTypeArgs(node, sig, type_arg_nodes, &used_explicit_type_args);
                    if (sig_is_generic) saw_generic_record = true;
                }
            } else {
                if (sig_is_generic) {
                    effective_sig = try self.instantiateSignatureFromArgs(sig, args, arg_types);
                }
                if (callee_node != hir_mod.none_node_id and self.hir.kindOf(callee_node) == .identifier) {
                    const class_name = hir_mod.identifierOf(self.hir, callee_node).name;
                    effective_sig = try self.instantiateGenericClassConstructorSignatureFromArgs(
                        class_name,
                        effective_sig,
                        args,
                        arg_types,
                    );
                }
            }

            if (try self.signatureAccepts(node, effective_sig, args, arg_types)) {
                selected_sig = effective_sig;
                selected_decl_sig = sig;
                found_applicable = true;
                break;
            }
            if (selected_sig == construct_sigs.items[0]) selected_sig = effective_sig;
        }
        const selected_is_abstract_construct = self.signatureIsAbstractConstruct(selected_sig);
        if (selected_is_abstract_construct and
            !self.newCalleeIsAbstractClass(callee_node) and
            !self.newCalleeIsKnownConcreteClass(callee_node))
        {
            try self.report(
                node,
                TsCodes.abstract_class_instantiation,
                "Cannot create an instance of an abstract class.",
            );
        }

        if (type_arg_nodes.len > 0 and !saw_generic_record and !self.newCalleeAcceptsTypeArguments(callee_node)) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Expected 0 type arguments, but got {d}.",
                .{type_arg_nodes.len},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = type_arg_nodes[0],
                .code = TsCodes.expected_n_type_arguments,
                .message = msg,
            });
        }

        if (!found_applicable and construct_sigs.items.len > 1) {
            var report_no_overload = true;
            var reported_arity = false;
            if (callee_node != hir_mod.none_node_id and self.hir.kindOf(callee_node) == .identifier) {
                const callee_id = hir_mod.identifierOf(self.hir, callee_node);
                if (self.class_constructor_overload_sigs.get(callee_id.name)) |overload_list| {
                    var any_visible_arity_fits = false;
                    for (overload_list.items) |ovl_sig| {
                        if (self.callArityFitsSignature(node, ovl_sig, args)) {
                            any_visible_arity_fits = true;
                            break;
                        }
                    }
                    if (!any_visible_arity_fits) {
                        reported_arity = try self.reportOverloadSetBoundaryArity(node, args, arg_types, overload_list.items);
                        selected_sig = if (overload_list.items.len > 0)
                            overload_list.items[0]
                        else
                            self.class_constructor_sigs.get(callee_id.name) orelse construct_sigs.items[construct_sigs.items.len - 1];
                        report_no_overload = false;
                    }
                }
            }
            if (report_no_overload) {
                const report_node = if (args.len > 0)
                    args[0]
                else if (callee_node != hir_mod.none_node_id)
                    callee_node
                else
                    node;
                try self.report(report_node, TsCodes.no_overload_matches, "No overload matches this call.");
            } else if (!reported_arity and !self.newCalleeIsAbstractClass(callee_node) and !selected_is_abstract_construct) {
                try self.checkArgsAgainstSignature(node, args, arg_types, selected_sig);
            }
        } else if (!self.newCalleeIsAbstractClass(callee_node) and !selected_is_abstract_construct) {
            // Skip arg-arity / arg-type checks (TS2554/TS2345) when
            // constructing an abstract class ÃÂ¢ÃÂÃÂ tsc reports only
            // TS2511 in that case. See `classAbstractInstantiations1`.
            try self.checkArgsAgainstSignature(node, args, arg_types, selected_sig);
        }
        if (type_arg_nodes.len == 0) {
            try self.checkInferredGenericClassConstructorConstraints(
                callee_node,
                selected_decl_sig,
                args,
                arg_types,
            );
        }

        var cns_ret = self.interner.signatureReturn(selected_sig) orelse types.Primitive.any;
        if (type_arg_nodes.len == 0 and
            callee_node != hir_mod.none_node_id and
            self.hir.kindOf(callee_node) == .identifier)
        {
            const class_name = hir_mod.identifierOf(self.hir, callee_node).name;
            if (try self.instantiateGenericClassFromConstructorArgs(class_name, selected_decl_sig, args, arg_types)) |inferred_instance| {
                cns_ret = inferred_instance;
            }
        }
        if (type_arg_nodes.len > 0 and
            callee_node != hir_mod.none_node_id and
            self.hir.kindOf(callee_node) == .identifier)
        {
            const class_name = hir_mod.identifierOf(self.hir, callee_node).name;
            if (try self.instantiateGenericClassForNew(class_name, type_arg_nodes)) |explicit_instance| {
                cns_ret = explicit_instance;
            }
        }
        if (type_arg_nodes.len > 0 and
            callee_node != hir_mod.none_node_id and
            self.hir.kindOf(callee_node) == .identifier)
        {
            const callee_id = hir_mod.identifierOf(self.hir, callee_node);
            if (std.mem.eql(u8, self.string_interner.get(callee_id.name), "Array")) {
                const elem_t = self.lowererLowerWithTypeParams(type_arg_nodes[0]) catch types.Primitive.any;
                cns_ret = self.interner.internArrayType(self.string_interner, elem_t) catch return error.OutOfMemory;
            }
        }
        // Register `C<number>` display on the instantiated construct
        // return so TS2322/TS2345 render the concrete type arguments
        // rather than the bare class name. Only for an explicit
        // `new C<args>()` over a named class. override_named_guard=true
        // because the instance keeps a `class_name_by_instance` entry.
        if (type_arg_nodes.len > 0 and
            callee_node != hir_mod.none_node_id and
            self.hir.kindOf(callee_node) == .identifier and
            cns_ret >= types.Primitive.first_dynamic and
            cns_ret < self.interner.pool.typeCount() and
            self.alias_display_names.get(cns_ret) == null)
        {
            const class_name = hir_mod.identifierOf(self.hir, callee_node).name;
            if (std.mem.eql(u8, self.string_interner.get(class_name), "Array")) return cns_ret;
            var arg_list: std.ArrayListUnmanaged(TypeId) = .empty;
            defer arg_list.deinit(self.gpa);
            for (type_arg_nodes) |tn| {
                const at = self.lowererLowerWithTypeParams(tn) catch types.Primitive.unknown;
                arg_list.append(self.gpa, at) catch break;
            }
            if (arg_list.items.len > 0) {
                self.registerAliasDisplayNameInner(cns_ret, class_name, arg_list.items, true) catch {};
            }
        }
        return cns_ret;
    }

    fn checkInferredGenericClassConstructorConstraints(
        self: *Checker,
        callee_node: NodeId,
        constructor_sig: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) CheckError!void {
        if (callee_node == hir_mod.none_node_id or self.hir.kindOf(callee_node) != .identifier) return;
        const class_name = hir_mod.identifierOf(self.hir, callee_node).name;
        const info = self.generic_aliases.get(class_name) orelse return;
        if (info.params.len == 0 or !self.interner.isSignature(constructor_sig)) return;

        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        try self.inferCallSubstitutions(constructor_sig, args, arg_types, &subs);
        const params = self.interner.signatureParams(constructor_sig);
        const inherited_overloads = self.class_constructor_overload_sigs.contains(class_name) and
            !self.class_constructor_sigs.contains(class_name);
        const constraint_count = if (inherited_overloads)
            @min(self.signatureMinRequiredArgs(constructor_sig, params), @min(args.len, arg_types.len))
        else
            @min(params.len, @min(args.len, arg_types.len));
        try self.checkGenericSignatureArgumentConstraints(
            args[0..constraint_count],
            arg_types[0..constraint_count],
            params[0..constraint_count],
            &subs,
        );
    }

    fn checkSuperConstructSignature(
        self: *Checker,
        call_node: NodeId,
        super_t: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) CheckError!void {
        if (super_t == types.Primitive.any or super_t == types.Primitive.unknown) return;
        var construct_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer construct_sigs.deinit(self.gpa);
        try self.collectConstructSignatures(super_t, &construct_sigs);
        var resolved_local_base_class = false;
        if (construct_sigs.items.len == 0) {
            const enclosing_class = self.enclosingSuperClass(call_node);
            if (enclosing_class != hir_mod.none_node_id and
                (self.hir.kindOf(enclosing_class) == .class_decl or
                    self.hir.kindOf(enclosing_class) == .class_expr))
            {
                const class_info = hir_mod.classOf(self.hir, enclosing_class);
                if (class_info.extends != hir_mod.none_node_id) {
                    if (self.classExtendsName(class_info.extends)) |base_name| {
                        if (self.hir.kindOf(class_info.extends) == .identifier) {
                            if (self.findVisibleNamedClassDecl(call_node, base_name)) |base_decl| {
                                resolved_local_base_class = true;
                                if (self.class_static_type_by_node.get(base_decl)) |base_static_t| {
                                    try self.collectConstructSignatures(base_static_t, &construct_sigs);
                                }
                            }
                        }
                        if (self.class_constructor_sigs.get(base_name)) |declared_sig| {
                            if (construct_sigs.items.len == 0) {
                                try construct_sigs.append(self.gpa, declared_sig);
                            }
                        }
                    }
                }
            }
        }
        if (construct_sigs.items.len == 0) {
            if (resolved_local_base_class) return;
            try self.report(call_node, TsCodes.call_target_no_signatures, "Call target does not contain any signatures.");
            return;
        }

        var selected_sig: TypeId = construct_sigs.items[0];
        var found_applicable = false;
        for (construct_sigs.items) |sig| {
            const effective_sig = try self.instantiateSignatureFromArgs(sig, args, arg_types);
            if (try self.signatureAccepts(call_node, effective_sig, args, arg_types)) {
                selected_sig = effective_sig;
                found_applicable = true;
                break;
            }
            if (selected_sig == construct_sigs.items[0]) selected_sig = effective_sig;
        }

        if (!found_applicable and construct_sigs.items.len > 1) {
            try self.report(call_node, TsCodes.no_overload_matches, "No overload matches this call.");
            return;
        }
        try self.checkArgsAgainstSignature(call_node, args, arg_types, selected_sig);
    }

    fn newCalleeIsAbstractClass(self: *Checker, callee_node: NodeId) bool {
        if (callee_node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(callee_node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, callee_node);
        return self.abstract_classes.contains(id.name);
    }

    fn newCalleeIsKnownConcreteClass(self: *Checker, callee_node: NodeId) bool {
        if (callee_node == hir_mod.none_node_id or self.hir.kindOf(callee_node) != .identifier) return false;
        const name = hir_mod.identifierOf(self.hir, callee_node).name;
        return self.class_abstractness_seen.contains(name) and !self.abstract_classes.contains(name);
    }

    fn newCalleeAcceptsTypeArguments(self: *Checker, callee_node: NodeId) bool {
        if (callee_node == hir_mod.none_node_id or self.hir.kindOf(callee_node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, callee_node);
        const name = self.string_interner.get(id.name);
        if (std.mem.eql(u8, name, "Array") or
            std.mem.eql(u8, name, "Map") or
            std.mem.eql(u8, name, "Set") or
            std.mem.eql(u8, name, "WeakMap") or
            std.mem.eql(u8, name, "WeakSet") or
            std.mem.eql(u8, name, "Promise"))
        {
            return true;
        }
        return self.generic_aliases.contains(id.name);
    }

    fn inferPromiseConstructorPayload(self: *Checker, args: []const NodeId) CheckError!?TypeId {
        if (self.promiseConstructorResolvedArgument(args)) |resolved| {
            return try self.checkExpression(resolved);
        }
        return null;
    }

    fn contextualPromiseConstructorPayload(self: *Checker, node: NodeId) ?TypeId {
        const target_t = self.contextualTargetTypeForExpression(node) orelse
            self.enclosingReturnTargetType(node) orelse
            return null;
        return switch (self.promiseLikeResult(target_t)) {
            .promised => |payload| payload,
            .none, .malformed => null,
        };
    }

    fn checkPromiseConstructorResolveCalls(
        self: *Checker,
        args: []const NodeId,
        payload_t: TypeId,
    ) CheckError!void {
        if (args.len == 0) return;
        const executor = args[0];
        const k = self.hir.kindOf(executor);
        if (k != .arrow_fn and k != .fn_expr and k != .fn_decl) return;
        const params = hir_mod.fnParams(self.hir, executor);
        if (params.len == 0) return;
        const first_param = hir_mod.parameterOf(self.hir, params[0]);
        if (first_param.name == hir_mod.none_node_id or self.hir.kindOf(first_param.name) != .identifier) return;
        const resolve_name = hir_mod.identifierOf(self.hir, first_param.name).name;
        if (!self.parameterTypeAllowsVoidOmission(payload_t)) {
            try self.reportPromiseResolveZeroArgCalls(executor, resolve_name);
        }
        try self.reportPromiseResolveArgumentMismatches(executor, resolve_name, payload_t);
    }

    fn reportPromiseResolveArgumentMismatches(
        self: *Checker,
        executor: NodeId,
        resolve_name: hir_mod.StringId,
        payload_t: TypeId,
    ) CheckError!void {
        const promise_like_t = try self.buildStructuralPromiseLike(payload_t);
        const target_t = self.interner.internUnion(&.{ payload_t, promise_like_t }) catch return error.OutOfMemory;
        try self.registerDiagnosticUnionDisplayName(target_t, &.{ payload_t, promise_like_t });

        const node_count: NodeId = std.math.cast(NodeId, self.hir.kinds.items.len) orelse std.math.maxInt(NodeId);
        var node: NodeId = 1;
        while (node < node_count) : (node += 1) {
            if (self.hir.kindOf(node) != .call_expr) continue;
            if (!self.callIsInsideFunction(node, executor)) continue;
            const c = hir_mod.callOf(self.hir, node);
            if (self.hir.kindOf(c.callee) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, c.callee).name != resolve_name) continue;
            const call_args = hir_mod.callArgs(self.hir, node);
            if (call_args.len == 0) continue;
            const value_node = call_args[0];
            if (self.diagnosticExistsOnNode(value_node, TsCodes.argument_type_mismatch)) continue;
            const value_t = try self.checkExpression(value_node);
            if (self.isArgumentAssignableToParam(value_node, value_t, target_t) catch true) continue;
            try self.diagnostics.append(self.gpa, .{
                .node = value_node,
                .code = TsCodes.argument_type_mismatch,
                .message = try self.formatArgumentNotAssignable(value_t, target_t, 0),
            });
        }
    }

    fn reportPromiseResolveZeroArgCalls(
        self: *Checker,
        executor: NodeId,
        resolve_name: hir_mod.StringId,
    ) CheckError!void {
        const node_count: NodeId = std.math.cast(NodeId, self.hir.kinds.items.len) orelse std.math.maxInt(NodeId);
        var node: NodeId = 1;
        while (node < node_count) : (node += 1) {
            if (self.hir.kindOf(node) != .call_expr) continue;
            if (!self.callIsInsideFunction(node, executor)) continue;
            const c = hir_mod.callOf(self.hir, node);
            if (self.hir.kindOf(c.callee) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, c.callee).name != resolve_name) continue;
            if (hir_mod.callArgs(self.hir, node).len != 0) continue;
            if (self.hasPromiseResolveArityDiagnostic(node)) continue;
            const is_js = self.virtualSectionIsJsLike(node);
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = if (is_js)
                    TsCodes.expected_one_argument_promise_jsdoc_hint
                else
                    TsCodes.expected_n_arguments_promise_void_hint,
                .message = if (is_js)
                    "Expected 1 argument, but got 0. 'new Promise()' needs a JSDoc hint to produce a 'resolve' that can be called without arguments."
                else
                    "Expected 1 arguments, but got 0. Did you forget to include 'void' in your type argument to 'Promise'?",
            });
        }
    }

    fn callIsInsideFunction(self: *Checker, call_node: NodeId, fn_node: NodeId) bool {
        var cur = self.hir.parentOf(call_node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            if (cur == fn_node) return true;
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) return false;
        }
        return false;
    }

    fn hasPromiseResolveArityDiagnostic(self: *Checker, node: NodeId) bool {
        for (self.diagnostics.items) |d| {
            if (d.node != node) continue;
            if (d.code == TsCodes.expected_n_arguments or
                d.code == TsCodes.expected_n_arguments_promise_void_hint or
                d.code == TsCodes.expected_one_argument_promise_jsdoc_hint) return true;
        }
        return false;
    }

    fn callIsPromiseConstructorResolve(self: *Checker, call_node: NodeId) bool {
        if (self.hir.kindOf(call_node) != .call_expr) return false;
        const c = hir_mod.callOf(self.hir, call_node);
        if (self.hir.kindOf(c.callee) != .identifier) return false;
        const call_name = hir_mod.identifierOf(self.hir, c.callee).name;
        var cur = self.hir.parentOf(call_node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) continue;
            const fn_node = cur;
            const parent = self.hir.parentOf(fn_node);
            if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .new_expr) return false;
            const new_call = hir_mod.callOf(self.hir, parent);
            if (self.hir.kindOf(new_call.callee) != .identifier) return false;
            const new_id = hir_mod.identifierOf(self.hir, new_call.callee);
            if (!std.mem.eql(u8, self.string_interner.get(new_id.name), "Promise")) return false;
            const params = hir_mod.fnParams(self.hir, fn_node);
            if (params.len == 0) return false;
            const first_param = hir_mod.parameterOf(self.hir, params[0]);
            if (first_param.name == hir_mod.none_node_id or self.hir.kindOf(first_param.name) != .identifier) return false;
            return hir_mod.identifierOf(self.hir, first_param.name).name == call_name;
        }
        return false;
    }

    fn promiseConstructorResolvedArgumentFromExpr(self: *Checker, expr: NodeId) ?NodeId {
        if (expr == hir_mod.none_node_id or self.hir.kindOf(expr) != .new_expr) return null;
        const c = hir_mod.callOf(self.hir, expr);
        if (self.hir.kindOf(c.callee) != .identifier) return null;
        const id = hir_mod.identifierOf(self.hir, c.callee);
        if (!std.mem.eql(u8, self.string_interner.get(id.name), "Promise")) return null;
        return self.promiseConstructorResolvedArgument(hir_mod.callArgs(self.hir, expr));
    }

    fn promiseResolveCallArgument(self: *Checker, expr: NodeId) ?NodeId {
        if (expr == hir_mod.none_node_id or self.hir.kindOf(expr) != .call_expr) return null;
        const call = hir_mod.callOf(self.hir, expr);
        if (self.hir.kindOf(call.callee) != .member_access) return null;
        const member = hir_mod.memberOf(self.hir, call.callee);
        if (!std.mem.eql(u8, self.string_interner.get(member.name), "resolve")) return null;
        if (self.hir.kindOf(member.object) != .identifier) return null;
        const object = hir_mod.identifierOf(self.hir, member.object);
        if (!std.mem.eql(u8, self.string_interner.get(object.name), "Promise")) return null;
        const args = hir_mod.callArgs(self.hir, expr);
        return if (args.len == 0) null else args[0];
    }

    fn promiseConstructorResolvedArgument(self: *Checker, args: []const NodeId) ?NodeId {
        if (args.len == 0) return null;
        const executor = args[0];
        const k = self.hir.kindOf(executor);
        if (k != .arrow_fn and k != .fn_expr and k != .fn_decl) return null;
        const f = hir_mod.fnDeclOf(self.hir, executor);
        const params = hir_mod.fnParams(self.hir, executor);
        if (params.len == 0) return null;
        const first_param = hir_mod.parameterOf(self.hir, params[0]);
        if (first_param.name == hir_mod.none_node_id or self.hir.kindOf(first_param.name) != .identifier) return null;
        const resolve_name = hir_mod.identifierOf(self.hir, first_param.name).name;
        return self.firstCallArgumentNodeToIdentifier(f.body, resolve_name);
    }

    fn firstCallArgumentToIdentifier(self: *Checker, node: NodeId, callee_name: hir_mod.StringId) CheckError!?TypeId {
        if (self.firstCallArgumentNodeToIdentifier(node, callee_name)) |arg| {
            return try self.checkExpression(arg);
        }
        return null;
    }

    fn firstCallArgumentNodeToIdentifier(self: *Checker, node: NodeId, callee_name: hir_mod.StringId) ?NodeId {
        if (node == hir_mod.none_node_id) return null;
        switch (self.hir.kindOf(node)) {
            .call_expr => {
                const c = hir_mod.callOf(self.hir, node);
                if (self.hir.kindOf(c.callee) == .identifier and
                    hir_mod.identifierOf(self.hir, c.callee).name == callee_name)
                {
                    const args = hir_mod.callArgs(self.hir, node);
                    if (args.len > 0) return args[0];
                    return null;
                }
                if (self.firstCallArgumentNodeToIdentifier(c.callee, callee_name)) |arg| return arg;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.firstCallArgumentNodeToIdentifier(arg, callee_name)) |found| return found;
                }
                return null;
            },
            .return_stmt => {
                const r = hir_mod.returnOf(self.hir, node);
                return self.firstCallArgumentNodeToIdentifier(r.value, callee_name);
            },
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |stmt| {
                    if (self.firstCallArgumentNodeToIdentifier(stmt, callee_name)) |arg| return arg;
                }
                return null;
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                if (self.firstCallArgumentNodeToIdentifier(i.then_branch, callee_name)) |arg| return arg;
                return self.firstCallArgumentNodeToIdentifier(i.else_branch, callee_name);
            },
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                if (self.firstCallArgumentNodeToIdentifier(l.lhs, callee_name)) |arg| return arg;
                return self.firstCallArgumentNodeToIdentifier(l.rhs, callee_name);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                if (self.firstCallArgumentNodeToIdentifier(c.then_branch, callee_name)) |arg| return arg;
                return self.firstCallArgumentNodeToIdentifier(c.else_branch, callee_name);
            },
            else => return null,
        }
    }

    fn collectCallSignatures(
        self: *Checker,
        t: TypeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!void {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                try self.collectCallSignatures(member, out);
            }
            return;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                try self.collectCallSignatures(member, out);
            }
            return;
        }
        if (self.interner.isSignature(t)) {
            if (!self.signatureIsConstruct(t)) try out.append(self.gpa, t);
            return;
        }
        if (!flags.is_object_type) return;

        const call_member_id = self.string_interner.intern("__call") catch return error.OutOfMemory;
        for (self.interner.objectMembers(t)) |member| {
            if (member.name == call_member_id and self.interner.isSignature(member.type)) {
                try out.append(self.gpa, member.type);
            }
        }
    }

    fn orderedIntersectionTypeNode(self: *Checker, type_node: NodeId, depth: usize) ?NodeId {
        if (type_node == hir_mod.none_node_id or depth > 8) return null;
        if (self.hir.kindOf(type_node) == .intersection_type) return type_node;
        if (self.hir.kindOf(type_node) != .type_ref) return null;
        const tr = hir_mod.typeRefOf(self.hir, type_node);
        if (tr.qualifier_len != 0 or tr.args_len != 0) return null;
        const alias_decl = self.findTypeAliasDeclInScope(type_node, tr.name) orelse return null;
        const alias = hir_mod.typeAliasOf(self.hir, alias_decl);
        return self.orderedIntersectionTypeNode(alias.aliased, depth + 1);
    }

    fn collectOrderedIntersectionCallSignatures(
        self: *Checker,
        type_node: NodeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!bool {
        const intersection_node = self.orderedIntersectionTypeNode(type_node, 0) orelse return false;
        for (hir_mod.intersectionTypeMembers(self.hir, intersection_node)) |member_node| {
            if (self.orderedIntersectionTypeNode(member_node, 0)) |nested| {
                for (hir_mod.intersectionTypeMembers(self.hir, nested)) |nested_member| {
                    const member_t = try self.lowererLowerWithTypeParams(nested_member);
                    try self.collectCallSignatures(member_t, out);
                }
            } else {
                const member_t = try self.lowererLowerWithTypeParams(member_node);
                try self.collectCallSignatures(member_t, out);
            }
        }
        return out.items.len > 1;
    }

    fn collectNamedMemberSignatures(
        self: *Checker,
        t: TypeId,
        name: hir_mod.StringId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!void {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(t);
        if (try self.refreshedGenericAliasObjectMember(t, name)) |member_t| {
            try self.collectCallSignatures(member_t, out);
            return;
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                try self.collectNamedMemberSignatures(member, name, out);
            }
            return;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                try self.collectNamedMemberSignatures(member, name, out);
            }
            return;
        }
        if (!flags.is_object_type) return;
        for (self.interner.objectMembers(t)) |member| {
            if (member.name == name) {
                try self.collectCallSignatures(member.type, out);
            }
        }
        const num_idx = try self.arrayElementType(t);
        if (num_idx != types.Primitive.none) {
            if (lib.arrayProto(&self.lib_cache, self.interner, self.string_interner, self.gpa, num_idx, &self.rest_signatures)) |proto| {
                for (self.interner.objectMembers(proto)) |member| {
                    if (member.name == name) {
                        try self.registerSyntheticArrayMethodTypeParameters(name, member.type);
                        try self.collectCallSignatures(member.type, out);
                    }
                }
            } else |_| {}
        }
    }

    fn signatureParamTypeForArgIndex(self: *Checker, sig: TypeId, args: []const NodeId, arg_types: []const TypeId, arg_i: usize) TypeId {
        const params = self.interner.signatureParams(sig);
        if (params.len == 0) return types.Primitive.any;
        const is_variadic = self.rest_signatures.contains(sig);
        const fixed_count: usize = if (is_variadic) params.len - 1 else params.len;
        const fixed_pos = self.fixedParamPositionBeforeArg(args, arg_types, arg_i);
        if (fixed_pos < fixed_count) return params[fixed_pos];
        if (is_variadic) {
            const rest_t = params[params.len - 1];
            const elem_t = self.interner.objectNumberIndex(rest_t);
            return if (elem_t != types.Primitive.none) elem_t else rest_t;
        }
        return types.Primitive.any;
    }

    fn signatureMoreSpecificForArgs(
        self: *Checker,
        candidate: TypeId,
        current: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) bool {
        if (candidate == current) return false;
        if (self.signatureHasMoreExactAnyMatches(candidate, current, args, arg_types)) return true;
        if (self.signatureHasMoreExactAnyMatches(current, candidate, args, arg_types)) return false;

        var saw_strict = false;
        for (args, 0..) |_, arg_i| {
            const cand_param = self.signatureParamTypeForArgIndex(candidate, args, arg_types, arg_i);
            const cur_param = self.signatureParamTypeForArgIndex(current, args, arg_types, arg_i);
            if (cand_param == cur_param) continue;
            if (cand_param == types.Primitive.any or cur_param == types.Primitive.any) continue;
            const cand_to_cur = self.engine.isSubtypeOf(cand_param, cur_param) catch false;
            const cur_to_cand = self.engine.isSubtypeOf(cur_param, cand_param) catch false;
            if (cand_to_cur and !cur_to_cand) {
                saw_strict = true;
                continue;
            }
            if (cur_to_cand and !cand_to_cur) return false;
        }
        return saw_strict;
    }

    fn signatureHasMoreExactAnyMatches(
        self: *Checker,
        candidate: TypeId,
        current: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) bool {
        var candidate_any_matches: usize = 0;
        var current_any_matches: usize = 0;
        for (arg_types, 0..) |arg_t, arg_i| {
            if (arg_t != types.Primitive.any) continue;
            if (self.signatureParamTypeForArgIndex(candidate, args, arg_types, arg_i) == types.Primitive.any) candidate_any_matches += 1;
            if (self.signatureParamTypeForArgIndex(current, args, arg_types, arg_i) == types.Primitive.any) current_any_matches += 1;
        }
        return candidate_any_matches > current_any_matches;
    }

    fn checkInstantiationExpressionTypeArguments(
        self: *Checker,
        node: NodeId,
        callee_t: TypeId,
        type_arg_nodes: []const NodeId,
    ) CheckError!TypeId {
        if (type_arg_nodes.len == 0) return callee_t;

        const callee = hir_mod.callOf(self.hir, node).callee;
        if (self.hir.kindOf(callee) == .identifier) {
            const name = self.string_interner.get(hir_mod.identifierOf(self.hir, callee).name);
            if (std.mem.eql(u8, name, "Array")) {
                if (type_arg_nodes.len == 1) return callee_t;
                try self.reportInstantiationExpressionNoApplicable(node, type_arg_nodes, "ArrayConstructor");
                return callee_t;
            }
        }

        var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer sigs.deinit(self.gpa);
        try self.collectCallSignatures(callee_t, &sigs);
        try self.collectConstructSignatures(callee_t, &sigs);

        var has_applicable = false;
        for (sigs.items) |sig| {
            if (!self.signatureTypeArgCountMatches(sig, type_arg_nodes.len)) continue;
            has_applicable = true;
            var used_explicit_type_args = false;
            _ = try self.instantiateSignatureWithExplicitTypeArgs(
                node,
                sig,
                type_arg_nodes,
                &used_explicit_type_args,
            );
        }

        var diagnostic_t = callee_t;
        var diagnostic_sigs = sigs.items;
        if (has_applicable and
            callee_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(callee_t).is_union)
        {
            var found_non_applicable = false;
            for (self.interner.unionMembers(callee_t)) |member| {
                var member_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
                defer member_sigs.deinit(self.gpa);
                try self.collectCallSignatures(member, &member_sigs);
                try self.collectConstructSignatures(member, &member_sigs);
                if (member_sigs.items.len == 0) continue;
                var member_applicable = false;
                for (member_sigs.items) |sig| {
                    if (self.signatureTypeArgCountMatches(sig, type_arg_nodes.len)) {
                        member_applicable = true;
                        break;
                    }
                }
                if (member_applicable) continue;
                diagnostic_t = member;
                diagnostic_sigs = try self.diag_arena.allocator().dupe(TypeId, member_sigs.items);
                found_non_applicable = true;
                break;
            }
            if (!found_non_applicable) {
                return try self.filteredInstantiationExpressionType(node, callee_t, type_arg_nodes);
            }
        } else if (has_applicable) {
            return try self.filteredInstantiationExpressionType(node, callee_t, type_arg_nodes);
        }

        if (callee_t == types.Primitive.any or callee_t == types.Primitive.unknown) return callee_t;
        const annotated_type_text: ?[]const u8 = if (!has_applicable and self.hir.kindOf(callee) == .identifier) blk: {
            const annotation = self.visibleAnnotatedIdentifierTypeNode(callee) orelse break :blk null;
            if (self.hir.kindOf(annotation) != .union_type) break :blk null;
            break :blk try self.allocTypeAnnotationDiagnosticName(annotation, false);
        } else null;
        const type_text = annotated_type_text orelse
            (try self.instantiationExpressionDiagnosticTypeName(diagnostic_t, diagnostic_sigs)) orelse
            "unknown";
        try self.reportInstantiationExpressionNoApplicable(node, type_arg_nodes, type_text);
        return try self.filteredInstantiationExpressionType(node, callee_t, type_arg_nodes);
    }

    fn filteredInstantiationExpressionType(
        self: *Checker,
        node: NodeId,
        t: TypeId,
        type_arg_nodes: []const NodeId,
    ) CheckError!TypeId {
        if (t < types.Primitive.first_dynamic or t >= self.interner.pool.typeCount()) return t;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union or flags.is_intersection) {
            const source_members = if (flags.is_union)
                self.interner.unionMembers(t)
            else
                self.interner.intersectionMembers(t);
            const snapshot = try self.gpa.dupe(TypeId, source_members);
            defer self.gpa.free(snapshot);
            var members: std.ArrayListUnmanaged(TypeId) = .empty;
            defer members.deinit(self.gpa);
            for (snapshot) |member| {
                try members.append(
                    self.gpa,
                    try self.filteredInstantiationExpressionType(node, member, type_arg_nodes),
                );
            }
            return if (flags.is_union)
                self.interner.internUnion(members.items) catch t
            else
                self.interner.internIntersection(members.items) catch t;
        }
        if (self.interner.isSignature(t)) {
            if (!self.signatureTypeArgCountMatches(t, type_arg_nodes.len)) {
                return self.interner.internObjectType(&.{}) catch t;
            }
            var used_explicit_type_args = false;
            return try self.instantiateSignatureWithExplicitTypeArgsUnchecked(
                node,
                t,
                type_arg_nodes,
                &used_explicit_type_args,
            );
        }
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return t;
            if (constraint == t) return t;
            return try self.filteredInstantiationExpressionType(node, constraint, type_arg_nodes);
        }
        if (!flags.is_object_type) return t;

        const call_name = self.string_interner.intern("__call") catch return error.OutOfMemory;
        const construct_name = self.string_interner.intern("__construct") catch return error.OutOfMemory;
        const source_members = self.interner.objectMembers(t);
        const snapshot = try self.gpa.dupe(types.ObjectMember, source_members);
        defer self.gpa.free(snapshot);
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        var changed = false;
        for (snapshot) |member| {
            if ((member.name == call_name or member.name == construct_name) and
                self.interner.isSignature(member.type))
            {
                changed = true;
                if (!self.signatureTypeArgCountMatches(member.type, type_arg_nodes.len)) continue;
                var instantiated = member;
                var used_explicit_type_args = false;
                instantiated.type = try self.instantiateSignatureWithExplicitTypeArgsUnchecked(
                    node,
                    member.type,
                    type_arg_nodes,
                    &used_explicit_type_args,
                );
                try members.append(self.gpa, instantiated);
                continue;
            }
            try members.append(self.gpa, member);
        }
        if (!changed) return t;
        const string_index = self.interner.objectStringIndex(t);
        const number_index = self.interner.objectNumberIndex(t);
        const symbol_index = self.interner.objectSymbolIndex(t);
        return if (string_index == types.Primitive.none and
            number_index == types.Primitive.none and
            symbol_index == types.Primitive.none)
            self.interner.internObjectType(members.items) catch t
        else
            self.interner.internObjectTypeWithIndexAndSymbol(
                members.items,
                string_index,
                number_index,
                symbol_index,
            ) catch t;
    }

    fn reportInstantiationExpressionNoApplicable(
        self: *Checker,
        node: NodeId,
        type_arg_nodes: []const NodeId,
        type_text: []const u8,
    ) CheckError!void {
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' has no signatures for which the type argument list is applicable.",
            .{type_text},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = if (type_arg_nodes.len > 0) self.hir.spanOf(type_arg_nodes[0]).start else null,
            .code = TsCodes.no_signatures_for_type_arg_list,
            .message = msg,
        });
    }

    fn instantiationExpressionDiagnosticTypeName(
        self: *Checker,
        t: TypeId,
        sigs: []const TypeId,
    ) CheckError!?[]const u8 {
        if (sigs.len > 1) {
            var buf: std.ArrayListUnmanaged(u8) = .empty;
            const arena = self.diag_arena.allocator();
            try buf.appendSlice(arena, "{ ");
            for (sigs) |sig| {
                const fn_text = (try self.allocCallableSignatureName(sig)) orelse return null;
                const arrow = std.mem.lastIndexOf(u8, fn_text, " => ") orelse return null;
                try buf.appendSlice(arena, fn_text[0..arrow]);
                try buf.appendSlice(arena, ": ");
                try buf.appendSlice(arena, fn_text[arrow + " => ".len ..]);
                try buf.appendSlice(arena, "; ");
            }
            try buf.append(arena, '}');
            return buf.items;
        }
        return (try self.allocSimpleTypeName(t)) orelse
            (try self.allocObjectTypeShape(t)) orelse
            (try self.simpleDiagnosticTypeName(t));
    }

    fn resolveOverloadedObjectCall(
        self: *Checker,
        call_node: NodeId,
        callee: NodeId,
        callee_t: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        call_is_optional_chain: bool,
    ) CheckError!?TypeId {
        var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer sigs.deinit(self.gpa);
        var preserve_intersection_order = false;
        if (self.hir.kindOf(callee) != .member_access and
            callee_t < self.interner.pool.typeCount() and
            self.unionMembersAreDirectCallSignatures(callee_t))
        {
            return null;
        }
        if (self.hir.kindOf(callee) == .member_access) {
            const m = hir_mod.memberOf(self.hir, callee);
            const receiver_t = if (try self.staticClassMemberAccess(m.object, m.name)) |static_access|
                static_access.receiver_t
            else
                try self.checkExpression(m.object);
            try self.collectNamedMemberSignatures(receiver_t, m.name, &sigs);
        } else {
            if (self.visibleAnnotatedIdentifierTypeNode(callee)) |type_node| {
                preserve_intersection_order = try self.collectOrderedIntersectionCallSignatures(type_node, &sigs);
            }
            if (!preserve_intersection_order) {
                sigs.clearRetainingCapacity();
                try self.collectCallSignatures(callee_t, &sigs);
            }
        }
        if (sigs.items.len == 0) return null;
        if (sigs.items.len == 1) {
            const sig = sigs.items[0];
            if (!self.containsFreeTypeParameter(sig) or !try self.argumentsContainOverloadedCallable(arg_types)) return null;
            const effective_sig = try self.instantiateSignatureFromArgs(sig, args, arg_types);
            try self.checkArgsAgainstSignature(call_node, args, arg_types, effective_sig);
            var ret = self.interner.signatureReturn(effective_sig) orelse types.Primitive.any;
            ret = try self.instantiateMemberThisReturn(callee, ret);
            return try self.optionalChainResult(ret, call_is_optional_chain);
        }
        const type_arg_nodes = hir_mod.callTypeArgs(self.hir, call_node);
        if (type_arg_nodes.len > 0) {
            var first_matching_arity: TypeId = types.Primitive.none;
            for (sigs.items) |sig| {
                const type_params = self.generic_signature_params.get(sig) orelse continue;
                if (type_params.len != type_arg_nodes.len) continue;
                var used_explicit_type_args = false;
                const effective_sig = try self.instantiateSignatureWithExplicitTypeArgs(call_node, sig, type_arg_nodes, &used_explicit_type_args);
                if (first_matching_arity == types.Primitive.none) first_matching_arity = effective_sig;
                if (try self.signatureAccepts(call_node, effective_sig, args, arg_types)) {
                    try self.checkArgsAgainstSignature(call_node, args, arg_types, effective_sig);
                    var ret = self.interner.signatureReturn(effective_sig) orelse types.Primitive.any;
                    ret = try self.instantiateMemberThisReturn(callee, ret);
                    return try self.optionalChainResult(ret, call_is_optional_chain);
                }
            }
            if (first_matching_arity != types.Primitive.none) {
                try self.checkArgsAgainstSignature(call_node, args, arg_types, first_matching_arity);
                var ret = self.interner.signatureReturn(first_matching_arity) orelse types.Primitive.any;
                ret = try self.instantiateMemberThisReturn(callee, ret);
                return try self.optionalChainResult(ret, call_is_optional_chain);
            }
            return null;
        }
        var selected_applicable: TypeId = types.Primitive.none;
        for (sigs.items) |sig| {
            const effective_sig = try self.instantiateSignatureFromArgs(sig, args, arg_types);
            if (!try self.signatureAccepts(call_node, effective_sig, args, arg_types)) continue;
            if (preserve_intersection_order) {
                selected_applicable = effective_sig;
                break;
            }
            if (selected_applicable == types.Primitive.none or
                self.signatureMoreSpecificForArgs(effective_sig, selected_applicable, args, arg_types))
            {
                selected_applicable = effective_sig;
            }
        }
        if (selected_applicable != types.Primitive.none) {
            try self.checkArgsAgainstSignature(call_node, args, arg_types, selected_applicable);
            const ret = self.interner.signatureReturn(selected_applicable) orelse types.Primitive.any;
            const param_ts = self.interner.signatureParams(selected_applicable);
            var instantiated = self.instantiateReturn(param_ts, arg_types, ret) catch ret;
            instantiated = try self.instantiateMemberThisReturn(callee, instantiated);
            return try self.optionalChainResult(instantiated, call_is_optional_chain);
        }
        if (self.overloadArityError(call_node, sigs.items, args)) |ar| {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "No overload expects {d} arguments, but overloads do exist that expect either {d} or {d} arguments.",
                .{ ar.arg_count, ar.max_below, ar.min_above },
            );
            try self.diagnostics.append(self.gpa, .{
                .node = call_node,
                .pos = self.tooFewArgsAnchorPos(call_node),
                .code = TsCodes.no_overload_expects_n_args_but_others_exist,
                .message = msg,
            });
        } else {
            const report_node = if (args.len > 0) args[0] else call_node;
            try self.report(report_node, TsCodes.no_overload_matches, "No overload matches this call.");
        }
        var ret = self.interner.signatureReturn(sigs.items[0]) orelse types.Primitive.any;
        ret = try self.instantiateMemberThisReturn(callee, ret);
        return try self.optionalChainResult(ret, call_is_optional_chain);
    }

    fn argumentsContainOverloadedCallable(self: *Checker, arg_types: []const TypeId) CheckError!bool {
        var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer sigs.deinit(self.gpa);
        for (arg_types) |arg_t| {
            sigs.clearRetainingCapacity();
            try self.collectCallSignatures(arg_t, &sigs);
            if (sigs.items.len > 1) return true;
        }
        return false;
    }

    fn checkMethodThisCompatibility(self: *Checker, call_node: NodeId, callee: NodeId, callee_t: TypeId) CheckError!void {
        if (self.hir.kindOf(callee) != .member_access) return;
        const m = hir_mod.memberOf(self.hir, callee);
        const receiver_t = if (try self.staticClassMemberAccess(m.object, m.name)) |static_access|
            static_access.receiver_t
        else
            try self.checkExpression(m.object);
        var saw_this_param = false;
        var unmet_this: std.ArrayListUnmanaged(TypeId) = .empty;
        defer unmet_this.deinit(self.gpa);
        var common_overload_this: std.ArrayListUnmanaged(TypeId) = .empty;
        defer common_overload_this.deinit(self.gpa);
        if (try self.collectCommonOverloadedUnionThisRequirements(callee_t, &common_overload_this)) {
            if (common_overload_this.items.len == 0) return;
            saw_this_param = true;
            for (common_overload_this.items) |this_t| {
                if (try self.thisContextAssignableTo(receiver_t, this_t)) return;
                try unmet_this.append(self.gpa, this_t);
            }
        } else {
            // When the receiver is a union of method-bearing types each
            // declaring its own `this: this`, the per-signature `this`
            // type is keyed on the (interned) signature TypeId ÃÂ¢ÃÂÃÂ which
            // collides across union branches that share an identical
            // shape. Walk the union explicitly so each branch contributes
            // its own `this` type to the unmet set.
            const receiver_is_union = receiver_t >= types.Primitive.first_dynamic and
                receiver_t < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(receiver_t).is_union;
            if (receiver_is_union) {
                for (self.interner.unionMembers(receiver_t)) |branch| {
                    var branch_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
                    defer branch_sigs.deinit(self.gpa);
                    try self.collectNamedMemberSignatures(branch, m.name, &branch_sigs);
                    for (branch_sigs.items) |sig| {
                        const this_t = self.signatureThisParam(sig) orelse continue;
                        saw_this_param = true;
                        var effective_this: TypeId = this_t;
                        // The signature_this_params map is keyed only on
                        // signature TypeId, so when two union members
                        // share an identical method signature shape only
                        // the last branch's `this`-type is retained. If
                        // the cached `this_t` matches one of the union
                        // members (suggesting `this: this`/`this: <self>`),
                        // use the current branch as its effective `this`
                        // so each branch contributes its own type to the
                        // unmet set.
                        if (this_t != branch) {
                            var this_t_is_union_member = false;
                            for (self.interner.unionMembers(receiver_t)) |other| {
                                if (other == this_t) {
                                    this_t_is_union_member = true;
                                    break;
                                }
                            }
                            if (this_t_is_union_member) effective_this = branch;
                        }
                        // Check the actual receiver (the union) against
                        // the effective `this`-type for this branch.
                        if (try self.thisContextAssignableTo(receiver_t, effective_this)) continue;
                        var seen = false;
                        for (unmet_this.items) |existing| {
                            if (existing == effective_this) {
                                seen = true;
                                break;
                            }
                        }
                        if (!seen) try unmet_this.append(self.gpa, effective_this);
                    }
                }
                if (!saw_this_param) return;
                if (unmet_this.items.len == 0) return;
            } else {
                var call_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
                defer call_sigs.deinit(self.gpa);
                try self.collectCallSignatures(callee_t, &call_sigs);
                for (call_sigs.items) |sig| {
                    const this_t = self.signatureThisParam(sig) orelse continue;
                    saw_this_param = true;
                    if (try self.thisContextAssignableTo(receiver_t, this_t)) return;
                    // Track unique unmet `this` types ÃÂ¢ÃÂÃÂ when the receiver is
                    // a union of method-bearing types each requiring its own
                    // `this`, upstream tsc intersects them in the diagnostic.
                    var seen = false;
                    for (unmet_this.items) |existing| {
                        if (existing == this_t) {
                            seen = true;
                            break;
                        }
                    }
                    if (!seen) try unmet_this.append(self.gpa, this_t);
                }
                if (!saw_this_param) return;
            }
        }
        // Prefer the upstream-shaped TS2684 with both `of type 'X'`
        // and `of type 'Y'` clauses when we can name both sides.
        // Falls back to the generic wording when the engine lacks a
        // simple type name for either side.
        if (unmet_this.items.len > 0) {
            const recv_name = try self.methodThisReceiverDisplayName(m.object, receiver_t);
            const this_name: ?[]const u8 = blk: {
                if (unmet_this.items.len == 1) {
                    break :blk try self.allocSimpleTypeName(unmet_this.items[0]);
                }
                var buf: std.ArrayListUnmanaged(u8) = .empty;
                const arena = self.diag_arena.allocator();
                for (unmet_this.items, 0..) |this_t, i| {
                    const part = (try self.allocSimpleTypeName(this_t)) orelse break :blk null;
                    if (i > 0) try buf.appendSlice(arena, " & ");
                    try buf.appendSlice(arena, part);
                }
                break :blk buf.items;
            };
            if (recv_name != null and this_name != null) {
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "The 'this' context of type '{s}' is not assignable to method's 'this' of type '{s}'.",
                    .{ recv_name.?, this_name.? },
                );
                try self.report(call_node, TsCodes.this_context_not_assignable, msg);
                return;
            }
        }
        try self.report(call_node, TsCodes.this_context_not_assignable, "The 'this' context is not assignable to method's 'this' type.");
    }

    fn thisContextAssignableTo(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        const source_args = self.alias_type_args.get(source_t);
        const target_args = self.alias_type_args.get(target_t);
        if (source_args != null and target_args != null and source_args.?.len == target_args.?.len) {
            const source_name = try self.genericInstanceBaseName(source_t);
            const target_name = try self.genericInstanceBaseName(target_t);
            if (source_name != null and target_name != null and source_name.? == target_name.?) {
                if (self.generic_aliases.get(source_name.?)) |info| {
                    if (info.params.len == source_args.?.len) {
                        for (info.params, source_args.?, target_args.?) |param_t, source_arg, target_arg| {
                            const variance = self.typeParameterVariance(param_t);
                            const unresolved_used_variance = variance == .bivariant and
                                self.typeContainsInferenceTarget(info.body, param_t, 0);
                            switch (variance) {
                                .covariant => if (!try self.typeArgumentAssignableTo(source_arg, target_arg)) return false,
                                .contravariant => if (!try self.typeArgumentAssignableTo(target_arg, source_arg)) return false,
                                .invariant => {
                                    if (!try self.typeArgumentAssignableTo(source_arg, target_arg)) return false;
                                    if (!try self.typeArgumentAssignableTo(target_arg, source_arg)) return false;
                                },
                                .bivariant => if (unresolved_used_variance and
                                    !try self.typeArgumentAssignableTo(source_arg, target_arg)) return false,
                            }
                        }
                        return true;
                    }
                }
            }
        }
        return try self.checkerAssignableTo(source_t, target_t);
    }

    fn methodThisReceiverDisplayName(self: *Checker, receiver_node: NodeId, receiver_t: TypeId) CheckError!?[]const u8 {
        if (try self.simpleNamedUnionAnnotationDisplay(receiver_node)) |display| return display;
        if (self.visibleAnnotatedIdentifierTypeNode(receiver_node)) |type_node| {
            if (self.hir.kindOf(type_node) == .object_type) {
                if (try self.allocTypeAnnotationDiagnosticName(type_node, false)) |display| return display;
            }
            const raw = self.nodeSourceTextOrEmpty(type_node);
            if (std.mem.indexOfScalar(u8, raw, '{') != null) {
                if (try self.normalizedBindingPatternSourceText(type_node)) |display| return display;
            }
        }
        if (self.visibleAnnotatedIdentifierType(receiver_node)) |annotated_t| {
            if (annotated_t < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(annotated_t).is_union)
            {
                if (try self.allocSimpleTypeName(annotated_t)) |name| return name;
            }
        }
        return try self.allocSimpleTypeName(receiver_t);
    }

    fn simpleNamedUnionAnnotationDisplay(self: *Checker, node: NodeId) CheckError!?[]const u8 {
        const source_name = self.visibleAnnotatedIdentifierTypeText(node) orelse return null;
        if (std.mem.indexOfScalar(u8, source_name, '|') == null) return null;
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer names.deinit(self.gpa);
        var parts = std.mem.splitScalar(u8, source_name, '|');
        while (parts.next()) |part| {
            const name = std.mem.trim(u8, part, " \t\r\n");
            if (!isSimpleTypeAliasName(name)) return null;
            try names.append(self.gpa, name);
        }
        if (names.items.len < 2) return null;
        std.mem.sort([]const u8, names.items, {}, lessThanStringLiteralText);
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        for (names.items, 0..) |name, i| {
            if (i > 0) try buf.appendSlice(arena, " | ");
            try buf.appendSlice(arena, name);
        }
        return buf.items;
    }

    fn appendReducedThisRequirement(
        self: *Checker,
        requirements: *std.ArrayListUnmanaged(TypeId),
        candidate: TypeId,
        keep_stricter: bool,
    ) CheckError!void {
        var i: usize = 0;
        while (i < requirements.items.len) {
            const existing = requirements.items[i];
            if (existing == candidate or (self.engine.isIdenticalTo(existing, candidate) catch false)) return;
            const candidate_to_existing = self.engine.isAssignableTo(candidate, existing) catch false;
            const existing_to_candidate = self.engine.isAssignableTo(existing, candidate) catch false;
            if (keep_stricter) {
                if (candidate_to_existing and !existing_to_candidate) {
                    _ = requirements.orderedRemove(i);
                    continue;
                }
                if (existing_to_candidate and !candidate_to_existing) return;
            } else {
                if (existing_to_candidate and !candidate_to_existing) {
                    _ = requirements.orderedRemove(i);
                    continue;
                }
                if (candidate_to_existing and !existing_to_candidate) return;
            }
            i += 1;
        }
        try requirements.append(self.gpa, candidate);
    }

    fn collectBranchBareCallThisRequirements(
        self: *Checker,
        call_node: NodeId,
        branch_t: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!void {
        var branch_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer branch_sigs.deinit(self.gpa);
        try self.collectCallSignatures(branch_t, &branch_sigs);
        for (branch_sigs.items) |sig| {
            if (!try self.signatureAccepts(call_node, sig, args, arg_types)) continue;
            const this_t = self.signatureThisParam(sig) orelse {
                out.clearRetainingCapacity();
                return;
            };
            try self.appendReducedThisRequirement(out, this_t, false);
        }
    }

    fn checkBareCallThisCompatibility(
        self: *Checker,
        call_node: NodeId,
        callee_t: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) CheckError!void {
        var call_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer call_sigs.deinit(self.gpa);
        try self.collectCallSignatures(callee_t, &call_sigs);

        var explicit_this_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer explicit_this_types.deinit(self.gpa);

        if (callee_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(callee_t).is_union) {
            for (self.interner.unionMembers(callee_t)) |member| {
                var branch_this_types: std.ArrayListUnmanaged(TypeId) = .empty;
                defer branch_this_types.deinit(self.gpa);
                try self.collectBranchBareCallThisRequirements(call_node, member, args, arg_types, &branch_this_types);
                for (branch_this_types.items) |this_t| {
                    try self.appendReducedThisRequirement(&explicit_this_types, this_t, true);
                }
            }
        } else {
            for (call_sigs.items) |sig| {
                if (!try self.signatureAccepts(call_node, sig, args, arg_types)) continue;
                const this_t = self.signatureThisParam(sig) orelse {
                    explicit_this_types.clearRetainingCapacity();
                    break;
                };
                if (self.engine.isAssignableTo(types.Primitive.void_t, this_t) catch false) {
                    explicit_this_types.clearRetainingCapacity();
                    break;
                }
                try self.appendReducedThisRequirement(&explicit_this_types, this_t, true);
            }
        }
        if (explicit_this_types.items.len == 0) return;
        const expected_this = if (explicit_this_types.items.len == 1)
            explicit_this_types.items[0]
        else
            self.interner.internIntersection(explicit_this_types.items) catch return error.OutOfMemory;
        if (self.engine.isAssignableTo(types.Primitive.void_t, expected_this) catch false) return;
        const display_this = (try self.intersectionCombinedConstraint(expected_this)) orelse expected_this;
        if (try self.allocSimpleTypeName(display_this)) |this_name| {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "The 'this' context of type 'void' is not assignable to method's 'this' of type '{s}'.",
                .{this_name},
            );
            try self.report(call_node, TsCodes.this_context_not_assignable, msg);
            return;
        }
        try self.report(call_node, TsCodes.this_context_not_assignable, "The 'this' context of type 'void' is not assignable to method's 'this' type.");
    }

    fn callCalleeHasSyntacticThisReceiver(self: *Checker, callee: NodeId) bool {
        var cur = callee;
        while (true) {
            switch (self.hir.kindOf(cur)) {
                .member_access, .element_access => return true,
                .non_null_expr => {
                    cur = hir_mod.asExpressionOf(self.hir, cur).expr;
                    continue;
                },
                else => return false,
            }
        }
    }

    fn callCalleeAlreadyHasUnresolvedNameDiagnostic(self: *Checker, callee: NodeId) bool {
        const root = self.calleeRootIdentifier(callee) orelse return false;
        for (self.diagnostics.items) |d| {
            if (d.node != root) continue;
            switch (d.code) {
                TsCodes.cannot_find_name,
                TsCodes.cannot_find_name_did_you_mean,
                TsCodes.cannot_find_node_name,
                TsCodes.cannot_find_jquery_name,
                2868,
                => return true,
                else => {},
            }
        }
        return false;
    }

    /// When the call's member-access callee already triggered a TS2339
    /// ("Property 'x' does not exist on type 'Y'."), suppress the
    /// follow-on TS2347 ÃÂ¢ÃÂÃÂ tsc emits only the property-existence error
    /// in that case. Matches `parserSuperExpression3`.
    fn callCalleeAlreadyHasMissingPropertyDiagnostic(self: *Checker, callee: NodeId) bool {
        for (self.diagnostics.items) |d| {
            if (d.code != TsCodes.property_does_not_exist) continue;
            if (d.node == callee or self.nodeIsAncestorOf(callee, d.node)) return true;
        }
        return false;
    }

    /// Namespace and qualified-member resolution can finalize TS2339 after
    /// the call/new path has already emitted TS2347. Keep only the primary
    /// missing-property diagnostic when it lands inside the callee span.
    fn removeUntypedTypeArgumentCascadesAfterMissingProperty(self: *Checker) void {
        var i: usize = 0;
        while (i < self.diagnostics.items.len) {
            const diagnostic = self.diagnostics.items[i];
            if (diagnostic.code != TsCodes.untyped_function_type_args) {
                i += 1;
                continue;
            }
            const kind = self.hir.kindOf(diagnostic.node);
            if (kind != .call_expr and kind != .new_expr) {
                i += 1;
                continue;
            }
            const callee = hir_mod.callOf(self.hir, diagnostic.node).callee;
            const span = self.hir.spanOf(callee);
            var has_primary = false;
            for (self.diagnostics.items) |other| {
                if (other.code != TsCodes.property_does_not_exist) continue;
                const pos = other.pos orelse self.hir.spanOf(other.node).start;
                if (pos >= span.start and pos <= span.end) {
                    has_primary = true;
                    break;
                }
            }
            if (has_primary) {
                _ = self.diagnostics.orderedRemove(i);
            } else {
                i += 1;
            }
        }
    }

    fn calleeRootIdentifier(self: *Checker, callee: NodeId) ?NodeId {
        var cur = callee;
        while (true) {
            switch (self.hir.kindOf(cur)) {
                .identifier => return cur,
                .member_access => {
                    cur = hir_mod.memberOf(self.hir, cur).object;
                    continue;
                },
                .element_access => {
                    cur = hir_mod.elementOf(self.hir, cur).object;
                    continue;
                },
                .non_null_expr => {
                    cur = hir_mod.asExpressionOf(self.hir, cur).expr;
                    continue;
                },
                .call_expr => {
                    if (self.isInstantiationExpressionCall(cur)) {
                        cur = hir_mod.callOf(self.hir, cur).callee;
                        continue;
                    }
                    return null;
                },
                else => return null,
            }
        }
    }

    fn addExplicitTypeArgNameSubstitutions(
        self: *Checker,
        t: TypeId,
        type_params: []const TypeId,
        explicit_types: []const TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
        root: bool,
    ) CheckError!void {
        if (t >= self.interner.pool.typeCount()) return;
        const flags = self.interner.pool.flagsOf(t);
        const payload_idx = self.interner.pool.payloadOf(t);
        if (flags.is_type_parameter) {
            const name = self.interner.typeParameterName(t) orelse return;
            for (type_params, 0..) |param_t, i| {
                const param_name = self.interner.typeParameterName(param_t) orelse continue;
                if (name == param_name) {
                    try subs.put(self.gpa, t, explicit_types[i]);
                    return;
                }
            }
            return;
        }
        if (flags.is_union) {
            if (payload_idx >= self.interner.pool.union_payloads.items.len) return;
            const members = self.interner.unionMembers(t);
            const snapshot = try self.gpa.dupe(TypeId, members);
            defer self.gpa.free(snapshot);
            for (snapshot) |member| {
                try self.addExplicitTypeArgNameSubstitutions(member, type_params, explicit_types, subs, false);
            }
            return;
        }
        if (flags.is_intersection) {
            if (payload_idx >= self.interner.pool.intersection_payloads.items.len) return;
            const members = self.interner.intersectionMembers(t);
            const snapshot = try self.gpa.dupe(TypeId, members);
            defer self.gpa.free(snapshot);
            for (snapshot) |member| {
                try self.addExplicitTypeArgNameSubstitutions(member, type_params, explicit_types, subs, false);
            }
            return;
        }
        if (flags.is_signature) {
            if (payload_idx >= self.interner.pool.signature_payloads.items.len) return;
            if (!root and self.generic_signature_params.get(t) != null) return;
            const params = self.interner.signatureParams(t);
            const snapshot = try self.gpa.dupe(TypeId, params);
            defer self.gpa.free(snapshot);
            for (snapshot) |param_t| {
                try self.addExplicitTypeArgNameSubstitutions(param_t, type_params, explicit_types, subs, false);
            }
            if (self.interner.signatureReturn(t)) |ret| {
                try self.addExplicitTypeArgNameSubstitutions(ret, type_params, explicit_types, subs, false);
            }
            return;
        }
        if (flags.is_object_type) {
            if (payload_idx >= self.interner.pool.object_type_payloads.items.len) return;
            const members = self.interner.objectMembers(t);
            const snapshot = try self.gpa.dupe(types.ObjectMember, members);
            defer self.gpa.free(snapshot);
            for (snapshot) |member| {
                try self.addExplicitTypeArgNameSubstitutions(member.type, type_params, explicit_types, subs, false);
            }
            const str_idx = self.interner.objectStringIndex(t);
            const num_idx = self.interner.objectNumberIndex(t);
            const sym_idx = self.interner.objectSymbolIndex(t);
            if (str_idx != types.Primitive.none) try self.addExplicitTypeArgNameSubstitutions(str_idx, type_params, explicit_types, subs, false);
            if (num_idx != types.Primitive.none) try self.addExplicitTypeArgNameSubstitutions(num_idx, type_params, explicit_types, subs, false);
            if (sym_idx != types.Primitive.none) try self.addExplicitTypeArgNameSubstitutions(sym_idx, type_params, explicit_types, subs, false);
        }
    }

    fn instantiateSignatureWithExplicitTypeArgs(
        self: *Checker,
        call_node: NodeId,
        sig: TypeId,
        type_arg_nodes: []const NodeId,
        used_explicit_type_args: *bool,
    ) CheckError!TypeId {
        return try self.instantiateSignatureWithExplicitTypeArgsInner(
            call_node,
            sig,
            type_arg_nodes,
            used_explicit_type_args,
            true,
        );
    }

    fn instantiateSignatureWithExplicitTypeArgsUnchecked(
        self: *Checker,
        call_node: NodeId,
        sig: TypeId,
        type_arg_nodes: []const NodeId,
        used_explicit_type_args: *bool,
    ) CheckError!TypeId {
        return try self.instantiateSignatureWithExplicitTypeArgsInner(
            call_node,
            sig,
            type_arg_nodes,
            used_explicit_type_args,
            false,
        );
    }

    fn instantiateSignatureWithExplicitTypeArgsInner(
        self: *Checker,
        call_node: NodeId,
        sig: TypeId,
        type_arg_nodes: []const NodeId,
        used_explicit_type_args: *bool,
        check_constraints: bool,
    ) CheckError!TypeId {
        _ = call_node;
        used_explicit_type_args.* = false;
        if (type_arg_nodes.len == 0) return sig;
        const type_params = self.generic_signature_params.get(sig) orelse return sig;
        if (type_arg_nodes.len != type_params.len) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Expected {d} type arguments, but got {d}.",
                .{ type_params.len, type_arg_nodes.len },
            );
            try self.diagnostics.append(self.gpa, .{
                .node = type_arg_nodes[0],
                .code = TsCodes.expected_n_type_arguments,
                .message = msg,
            });
        }
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        const n = @min(type_params.len, type_arg_nodes.len);
        var explicit_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer explicit_types.deinit(self.gpa);
        const prev_type_arg_constraint_subs = self.current_type_arg_constraint_subs;
        self.current_type_arg_constraint_subs = &subs;
        defer self.current_type_arg_constraint_subs = prev_type_arg_constraint_subs;
        for (0..n) |i| {
            const explicit_t = self.lowererLowerWithTypeParams(type_arg_nodes[i]) catch types.Primitive.unknown;
            // TS2344: Verify the explicit type arg satisfies the
            // parameter's `extends` constraint. Mirrors upstream
            // `nonPrimitiveInGeneric.ts(25,8)` where
            // `bound2<number>()` violates `T extends object`.
            try subs.put(self.gpa, type_params[i], explicit_t);
            if (check_constraints) {
                try self.checkTypeArgSatisfiesConstraint(type_arg_nodes[i], type_params[i], explicit_t);
            }
            try explicit_types.append(self.gpa, explicit_t);
        }
        if (explicit_types.items.len > 0) {
            try self.addExplicitTypeArgNameSubstitutions(
                sig,
                type_params[0..explicit_types.items.len],
                explicit_types.items,
                &subs,
                true,
            );
        }
        if (subs.count() == 0) return sig;
        used_explicit_type_args.* = true;
        return self.substituteType(sig, &subs) catch sig;
    }

    fn instantiateSignatureFromArgs(
        self: *Checker,
        sig: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) CheckError!TypeId {
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        try self.inferCallSubstitutions(sig, args, arg_types, &subs);
        if (subs.count() == 0) return sig;
        try self.normalizeCallInferenceSubstitutions(sig, &subs);
        try self.applyInferredConditionalConstraintsFromCallArgs(self.interner.signatureParams(sig), arg_types, &subs);
        try self.applyInferredConditionalConstraintsToSubs(sig, &subs);
        return self.substituteType(sig, &subs) catch sig;
    }

    fn normalizeCallInferenceSubstitutions(
        self: *Checker,
        sig: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        const declared_params = self.generic_signature_params.get(sig) orelse &.{};
        for (self.interner.signatureParams(sig)) |param_t| {
            if (param_t >= self.interner.pool.typeCount()) continue;
            const param_flags = self.interner.pool.flagsOf(param_t);
            if (!param_flags.is_object_type or param_flags.is_union or param_flags.is_intersection) continue;
            for (declared_params) |declared_param| {
                const name = self.typeParameterName(declared_param) orelse continue;
                const constraint = self.typeParameterConstraint(declared_param) orelse continue;
                if (constraint >= self.interner.pool.typeCount() or
                    !self.interner.pool.flagsOf(constraint).is_object_type)
                {
                    continue;
                }
                var occurrences: usize = 0;
                for (self.interner.objectMembers(param_t)) |member| {
                    if (self.typeParameterName(member.type) != name) continue;
                    occurrences += 1;
                }
                if (occurrences < 2) continue;

                var inferred = subs.get(declared_param);
                if (inferred == null) {
                    var it = subs.iterator();
                    while (it.next()) |entry| {
                        if (self.typeParameterName(entry.key_ptr.*) == name) {
                            inferred = entry.value_ptr.*;
                            break;
                        }
                    }
                }
                const inferred_t = inferred orelse continue;
                try subs.put(self.gpa, declared_param, inferred_t);
                for (self.interner.objectMembers(param_t)) |member| {
                    if (self.typeParameterName(member.type) == name) {
                        try subs.put(self.gpa, member.type, inferred_t);
                    }
                }
                if (self.interner.signatureReturn(sig)) |return_t| {
                    if (self.typeParameterName(return_t) == name) {
                        try subs.put(self.gpa, return_t, inferred_t);
                    }
                }
            }
        }
        var inferred_params: std.ArrayListUnmanaged(TypeId) = .empty;
        defer inferred_params.deinit(self.gpa);
        var inferred_it = subs.keyIterator();
        while (inferred_it.next()) |param_ptr| {
            const param_t = param_ptr.*;
            if (param_t >= self.interner.pool.typeCount()) continue;
            if (!self.interner.pool.flagsOf(param_t).is_type_parameter) continue;
            try inferred_params.append(self.gpa, param_t);
        }
        for (inferred_params.items) |inferred_param| {
            if (!self.typeContainsMappedConstraintParameter(sig, inferred_param, 0)) continue;
            const candidate = subs.get(inferred_param) orelse continue;
            if (candidate == types.Primitive.never) continue;
            const raw_constraint = self.typeParameterConstraint(inferred_param) orelse continue;
            if (raw_constraint == inferred_param or
                raw_constraint == types.Primitive.any or
                raw_constraint == types.Primitive.unknown or
                raw_constraint == types.Primitive.none)
            {
                continue;
            }
            const constraint = self.substituteType(raw_constraint, subs) catch raw_constraint;
            if (self.engine.isAssignableTo(candidate, constraint) catch false) continue;
            const fallback = try self.substituteInferenceConstraintPreservingKeyof(raw_constraint, subs);
            try subs.put(self.gpa, inferred_param, fallback);
        }
        for (declared_params) |declared_param| {
            if (!self.jsdoc_constrained_type_params.contains(declared_param)) continue;
            const candidate = subs.get(declared_param) orelse continue;
            const raw_constraint = self.typeParameterConstraint(declared_param) orelse continue;
            if (raw_constraint == types.Primitive.any or
                raw_constraint == types.Primitive.unknown or
                raw_constraint == types.Primitive.none)
            {
                continue;
            }
            const constraint = self.substituteType(raw_constraint, subs) catch raw_constraint;
            if (self.engine.isAssignableTo(candidate, constraint) catch false) continue;
            try subs.put(self.gpa, declared_param, constraint);
        }
    }

    fn substituteInferenceConstraintPreservingKeyof(
        self: *Checker,
        constraint_t: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!TypeId {
        if (constraint_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(constraint_t).is_keyof)
        {
            const payload_idx = self.interner.pool.payloadOf(constraint_t);
            if (payload_idx < self.interner.pool.keyof_payloads.items.len) {
                const operand = self.interner.pool.keyof_payloads.items[payload_idx].operand;
                const substituted_operand = try self.substituteType(operand, subs);
                return self.interner.internKeyof(substituted_operand) catch return error.OutOfMemory;
            }
        }
        return try self.substituteType(constraint_t, subs);
    }

    fn signatureHasMappedConstraintTypeParameter(self: *Checker, sig: TypeId) bool {
        if (!self.interner.isSignature(sig)) return false;
        for (self.interner.signatureParams(sig)) |param_t| {
            if (self.typeContainsAnyMappedConstraintTypeParameter(param_t, 0)) return true;
        }
        return false;
    }

    fn typeContainsAnyMappedConstraintTypeParameter(self: *Checker, t: TypeId, depth: u8) bool {
        if (depth >= 12 or t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (self.typeIsMappedPayloadType(t)) {
            const mapped = self.interner.mappedPayload(t);
            return mapped.constraint < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(mapped.constraint).is_type_parameter;
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeContainsAnyMappedConstraintTypeParameter(member, depth + 1)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeContainsAnyMappedConstraintTypeParameter(member, depth + 1)) return true;
            }
            return false;
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |member| {
                if (self.typeContainsAnyMappedConstraintTypeParameter(member.type, depth + 1)) return true;
            }
        }
        return false;
    }

    fn typeContainsMappedConstraintParameter(
        self: *Checker,
        t: TypeId,
        type_param: TypeId,
        depth: u8,
    ) bool {
        if (depth >= 12 or t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (self.typeIsMappedPayloadType(t)) {
            const mapped = self.interner.mappedPayload(t);
            if (mapped.constraint == type_param) return true;
            return self.typeContainsMappedConstraintParameter(mapped.template, type_param, depth + 1);
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeContainsMappedConstraintParameter(member, type_param, depth + 1)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeContainsMappedConstraintParameter(member, type_param, depth + 1)) return true;
            }
            return false;
        }
        if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |param_t| {
                if (self.typeContainsMappedConstraintParameter(param_t, type_param, depth + 1)) return true;
            }
            if (self.interner.signatureReturn(t)) |return_t| {
                return self.typeContainsMappedConstraintParameter(return_t, type_param, depth + 1);
            }
            return false;
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |member| {
                if (self.typeContainsMappedConstraintParameter(member.type, type_param, depth + 1)) return true;
            }
        }
        return false;
    }

    fn genericCallUnboundDiagnosticType(
        self: *Checker,
        sig: TypeId,
        target_t: TypeId,
    ) CheckError!TypeId {
        const type_params = self.generic_signature_params.get(sig) orelse return target_t;
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        for (type_params) |param_t| {
            if (param_t >= self.interner.pool.typeCount()) continue;
            const flags = self.interner.pool.flagsOf(param_t);
            if (!flags.is_type_parameter) continue;
            const payload = self.interner.pool.type_parameter_payloads.items[self.interner.pool.payloadOf(param_t)];
            const raw_fallback = if (payload.default != types.Primitive.none)
                payload.default
            else if (payload.constraint != types.Primitive.none and
                payload.constraint != types.Primitive.unknown and
                payload.constraint != param_t)
                payload.constraint
            else
                types.Primitive.unknown;
            const fallback = self.substituteType(raw_fallback, &subs) catch raw_fallback;
            try subs.put(self.gpa, param_t, fallback);
        }
        if (subs.count() == 0) return target_t;
        return self.substituteType(target_t, &subs) catch target_t;
    }

    fn genericCallDiagnosticDisplayType(
        self: *Checker,
        call_node: NodeId,
        target_t: TypeId,
    ) CheckError!TypeId {
        if (call_node == hir_mod.none_node_id or self.hir.kindOf(call_node) != .call_expr) return target_t;
        const call = hir_mod.callOf(self.hir, call_node);
        if (call.callee == hir_mod.none_node_id or self.hir.kindOf(call.callee) != .identifier) return target_t;
        const callee_id = hir_mod.identifierOf(self.hir, call.callee);
        const type_params = self.generic_fns.get(callee_id.name) orelse return target_t;
        if (!self.typeContainsConstructSignatureReferencingParams(target_t, type_params)) return target_t;
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        for (type_params) |param_t| {
            if (param_t >= self.interner.pool.typeCount()) continue;
            if (!self.interner.pool.flagsOf(param_t).is_type_parameter) continue;
            const payload_idx = self.interner.pool.payloadOf(param_t);
            const fallback = if (payload_idx < self.interner.pool.type_parameter_payloads.items.len) blk: {
                const tp = self.interner.pool.type_parameter_payloads.items[payload_idx];
                break :blk if (tp.default != types.Primitive.none) tp.default else types.Primitive.unknown;
            } else types.Primitive.unknown;
            try subs.put(self.gpa, param_t, fallback);
        }
        if (subs.count() == 0) return target_t;
        return self.substituteType(target_t, &subs) catch target_t;
    }

    fn typeContainsConstructSignatureReferencingParams(
        self: *Checker,
        t: TypeId,
        params: []const TypeId,
    ) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) {
            for (params) |param_t| {
                if (t == param_t) return true;
            }
            return false;
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeContainsConstructSignatureReferencingParams(member, params)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeContainsConstructSignatureReferencingParams(member, params)) return true;
            }
            return false;
        }
        if (self.interner.isSignature(t)) {
            if (!self.signatureIsConstruct(t)) return false;
            for (self.interner.signatureParams(t)) |param_t| {
                if (self.typeContainsConstructSignatureReferencingParams(param_t, params)) return true;
            }
            if (self.interner.signatureReturn(t)) |ret| {
                if (self.typeContainsConstructSignatureReferencingParams(ret, params)) return true;
            }
            return false;
        }
        if (!flags.is_object_type) return false;
        for (self.interner.objectMembers(t)) |member| {
            if (self.typeContainsConstructSignatureReferencingParams(member.type, params)) return true;
        }
        const str_idx = self.interner.objectStringIndex(t);
        if (str_idx != types.Primitive.none and
            self.typeContainsConstructSignatureReferencingParams(str_idx, params)) return true;
        const num_idx = self.interner.objectNumberIndex(t);
        if (num_idx != types.Primitive.none and
            self.typeContainsConstructSignatureReferencingParams(num_idx, params)) return true;
        return false;
    }

    /// Post-statement narrowing for native `??=` / `||=` assignments.
    /// Their assignment-expression type already combines the retained
    /// LHS branch with the RHS, so it is also the target's flow type
    /// after the statement. `&&=` keeps the original falsy branch and
    /// therefore does not narrow on its own.
    ///
    /// The older lowered `target = target <op> value` shape remains
    /// supported for HIR produced by external callers.
    fn applyLogicalAssignmentFlow(self: *Checker, stmt: NodeId) !void {
        if (self.hir.kindOf(stmt) != .assignment) return;
        const a = hir_mod.assignmentOf(self.hir, stmt);
        if (self.hir.kindOf(a.target) != .identifier) return;
        const target_id = hir_mod.identifierOf(self.hir, a.target);
        if (a.op == .logical_or or a.op == .nullish_coalesce) {
            var result_t = self.hir.typeOf(stmt);
            if (result_t == types.Primitive.none) result_t = try self.checkExpression(stmt);
            if (result_t != types.Primitive.none) try self.recordNarrow(target_id.name, result_t);
            return;
        }
        if (a.op != null) return;
        if (self.hir.kindOf(a.value) != .logical_op) return;
        const l = hir_mod.logicalOf(self.hir, a.value);
        // Only act when the operator's lhs is the same identifier as
        // the assignment target ÃÂ¢ÃÂÃÂ that's the lowered `x = x ?? rhs`
        // shape produced by `parseLogicalAssign`.
        if (self.hir.kindOf(l.lhs) != .identifier) return;
        const lhs_id = hir_mod.identifierOf(self.hir, l.lhs);
        if (lhs_id.name != target_id.name) return;
        switch (l.op) {
            .nullish => {
                // For `??=` reuse the assignment value's type ÃÂ¢ÃÂÃÂ it's
                // already `(target minus null|undefined) | rhs_type`
                // because checkLogical specially handles `??`.
                const value_t = self.hir.typeOf(a.value);
                if (value_t == types.Primitive.none) return;
                try self.recordNarrow(target_id.name, value_t);
            },
            .@"or" => {
                // checkLogical produces `lhs | rhs` for `||`,
                // which doesn't actually narrow. Compute a v0
                // approximation: drop null/undefined from the lhs
                // and union with the rhs. That covers the common
                // `string | null | undefined` shapes without modeling
                // full truthiness.
                const lhs_t = self.hir.typeOf(l.lhs);
                const rhs_t = self.hir.typeOf(l.rhs);
                if (lhs_t == types.Primitive.none or rhs_t == types.Primitive.none) return;
                const lhs_non_null = self.subtractNullUndefined(lhs_t) catch lhs_t;
                const narrowed = self.interner.internUnion(&.{ lhs_non_null, rhs_t }) catch return;
                try self.recordNarrow(target_id.name, narrowed);
            },
            .@"and" => {},
        }
    }

    fn applyExhaustiveBranchAssignmentFlow(
        self: *Checker,
        then_branch: NodeId,
        else_branch: NodeId,
    ) !void {
        const name = self.lastExhaustiveAssignmentCandidate(then_branch) orelse return;
        const then_t = (try self.definiteNonNullAssignmentType(then_branch, name)) orelse return;
        const else_t = (try self.definiteNonNullAssignmentType(else_branch, name)) orelse return;
        const joined = if (then_t == else_t)
            then_t
        else if (then_t == types.Primitive.any or else_t == types.Primitive.any)
            types.Primitive.any
        else if (then_t == types.Primitive.unknown or else_t == types.Primitive.unknown)
            types.Primitive.unknown
        else
            try self.interner.internUnion(&.{ then_t, else_t });
        try self.recordNarrow(name, joined);
    }

    fn lastExhaustiveAssignmentCandidate(self: *Checker, node: NodeId) ?hir_mod.StringId {
        return switch (self.hir.kindOf(node)) {
            .assignment => blk: {
                const assignment = hir_mod.assignmentOf(self.hir, node);
                if (self.hir.kindOf(assignment.target) != .identifier) break :blk null;
                break :blk hir_mod.identifierOf(self.hir, assignment.target).name;
            },
            .block_stmt => blk: {
                const statements = hir_mod.blockStmts(self.hir, node);
                var index = statements.len;
                while (index > 0) {
                    index -= 1;
                    if (self.lastExhaustiveAssignmentCandidate(statements[index])) |name| break :blk name;
                }
                break :blk null;
            },
            .if_stmt => blk: {
                const statement = hir_mod.ifOf(self.hir, node);
                if (statement.else_branch == hir_mod.none_node_id) break :blk null;
                const then_name = self.lastExhaustiveAssignmentCandidate(statement.then_branch) orelse break :blk null;
                const else_name = self.lastExhaustiveAssignmentCandidate(statement.else_branch) orelse break :blk null;
                break :blk if (then_name == else_name) then_name else null;
            },
            else => null,
        };
    }

    fn statementMayAssignIdentifier(self: *Checker, node: NodeId, name: hir_mod.StringId) bool {
        return switch (self.hir.kindOf(node)) {
            .assignment => blk: {
                const assignment = hir_mod.assignmentOf(self.hir, node);
                break :blk self.hir.kindOf(assignment.target) == .identifier and
                    hir_mod.identifierOf(self.hir, assignment.target).name == name;
            },
            .block_stmt => blk: {
                for (hir_mod.blockStmts(self.hir, node)) |statement| {
                    if (self.statementMayAssignIdentifier(statement, name)) break :blk true;
                }
                break :blk false;
            },
            .if_stmt => blk: {
                const statement = hir_mod.ifOf(self.hir, node);
                break :blk self.statementMayAssignIdentifier(statement.then_branch, name) or
                    (statement.else_branch != hir_mod.none_node_id and
                        self.statementMayAssignIdentifier(statement.else_branch, name));
            },
            else => false,
        };
    }

    fn definiteNonNullAssignmentType(
        self: *Checker,
        node: NodeId,
        name: hir_mod.StringId,
    ) !?TypeId {
        return switch (self.hir.kindOf(node)) {
            .assignment => blk: {
                const assignment = hir_mod.assignmentOf(self.hir, node);
                if (self.hir.kindOf(assignment.target) != .identifier or
                    hir_mod.identifierOf(self.hir, assignment.target).name != name)
                {
                    break :blk null;
                }
                const value_kind = self.hir.kindOf(assignment.value);
                if (value_kind == .literal_null or value_kind == .literal_undefined) break :blk null;
                const value_t = self.hir.typeOf(assignment.value);
                if (value_t == types.Primitive.none or self.typeIsPossiblyNullishStrict(value_t)) break :blk null;
                break :blk value_t;
            },
            .block_stmt => blk: {
                const statements = hir_mod.blockStmts(self.hir, node);
                var index = statements.len;
                while (index > 0) {
                    index -= 1;
                    const statement = statements[index];
                    if (!self.statementMayAssignIdentifier(statement, name)) continue;
                    break :blk try self.definiteNonNullAssignmentType(statement, name);
                }
                break :blk null;
            },
            .if_stmt => blk: {
                const statement = hir_mod.ifOf(self.hir, node);
                if (statement.else_branch == hir_mod.none_node_id) break :blk null;
                const then_t = (try self.definiteNonNullAssignmentType(statement.then_branch, name)) orelse break :blk null;
                const else_t = (try self.definiteNonNullAssignmentType(statement.else_branch, name)) orelse break :blk null;
                if (then_t == else_t) break :blk then_t;
                if (then_t == types.Primitive.any or else_t == types.Primitive.any) break :blk types.Primitive.any;
                if (then_t == types.Primitive.unknown or else_t == types.Primitive.unknown) break :blk types.Primitive.unknown;
                break :blk try self.interner.internUnion(&.{ then_t, else_t });
            },
            else => null,
        };
    }

    const NullishGuardKind = enum { null_only, undefined_only, null_or_undefined };

    const NullishGuard = struct {
        name: hir_mod.StringId,
        ident_node: NodeId,
        kind: NullishGuardKind,
    };

    const DiscriminantTarget = struct {
        name: hir_mod.StringId,
        t: TypeId,
    };

    fn applyNullishGuardAssignmentFlow(self: *Checker, cond: NodeId, then_branch: NodeId) !void {
        const guard = self.nullishEqualityGuard(cond) orelse return;
        const value_node = self.singleAssignmentValueToIdentifier(then_branch, guard.name) orelse return;
        var assigned_t = self.hir.typeOf(value_node);
        if (assigned_t == types.Primitive.none) assigned_t = try self.checkExpression(value_node);
        const current = self.lookupNarrow(guard.name) orelse self.typeOfIdentifier(guard.ident_node);
        const false_t = try self.subtractNullishGuardedType(current, guard.kind);
        const narrowed = if (false_t == types.Primitive.never)
            assigned_t
        else if (assigned_t == types.Primitive.never)
            false_t
        else
            self.interner.internUnion(&.{ false_t, assigned_t }) catch return error.OutOfMemory;
        try self.recordNarrow(guard.name, narrowed);
    }

    fn applyNegatedInstanceofAssignmentFlow(self: *Checker, cond: NodeId, then_branch: NodeId) !void {
        if (self.hir.kindOf(cond) != .unary_op) return;
        const u = hir_mod.unaryOf(self.hir, cond);
        if (u.op != .not or self.hir.kindOf(u.operand) != .binary_op) return;
        const b = hir_mod.binopOf(self.hir, u.operand);
        if (b.op != .instanceof or self.hir.kindOf(b.lhs) != .identifier) return;
        const id = hir_mod.identifierOf(self.hir, b.lhs);
        const target = (try self.directInstanceofTargetType(b.rhs)) orelse return;
        const value_node = self.singleAssignmentValueToIdentifier(then_branch, id.name) orelse return;
        var assigned_t = self.hir.typeOf(value_node);
        if (assigned_t == types.Primitive.none) assigned_t = try self.checkExpression(value_node);
        if (assigned_t == types.Primitive.none or assigned_t == types.Primitive.any or assigned_t == types.Primitive.unknown) return;
        if (!(try self.assignmentFlowValueFitsTarget(assigned_t, target))) return;
        const current = self.lookupNarrow(id.name) orelse self.typeOfIdentifier(b.lhs);
        const false_t = try self.narrowTypeByDirectInstanceof(current, target);
        const narrowed = if (false_t == assigned_t)
            assigned_t
        else if (false_t == types.Primitive.never)
            assigned_t
        else if (assigned_t == types.Primitive.never)
            false_t
        else
            self.interner.internUnion(&.{ false_t, assigned_t }) catch return error.OutOfMemory;
        try self.recordNarrow(id.name, narrowed);
    }

    fn applyInstanceofFallthroughJoin(self: *Checker, condition: NodeId) CheckError!void {
        if (self.hir.kindOf(condition) != .binary_op) return;
        const binary = hir_mod.binopOf(self.hir, condition);
        if (binary.op != .instanceof or self.hir.kindOf(binary.lhs) != .identifier) return;
        const id = hir_mod.identifierOf(self.hir, binary.lhs);
        const current = self.lookupNarrow(id.name) orelse self.typeOfIdentifierDeclared(binary.lhs);
        if (current >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(current).is_intersection) return;
        const target = (try self.directInstanceofTargetType(binary.rhs)) orelse return;
        if (self.classNameForInstanceType(target) == null) return;
        const joined = self.interner.internUnion(&.{ target, current }) catch return error.OutOfMemory;
        try self.recordNarrow(id.name, joined);
    }

    fn directInstanceofTargetType(self: *Checker, rhs: NodeId) CheckError!?TypeId {
        if (self.hir.kindOf(rhs) == .identifier) {
            const rhs_id = hir_mod.identifierOf(self.hir, rhs);
            self.ensureForwardVisibleTypeDeclChecked(rhs, rhs_id.name) catch {};
            if (self.class_instance_types.get(rhs_id.name)) |inst| return inst;
            const rhs_name = self.string_interner.get(rhs_id.name);
            if (std.mem.eql(u8, rhs_name, "RegExp") or
                std.mem.eql(u8, rhs_name, "Date") or
                std.mem.eql(u8, rhs_name, "Error"))
            {
                return self.lowerBuiltinObjectType(rhs_name) orelse types.Primitive.object_t;
            }
        }

        var rhs_t = self.hir.typeOf(rhs);
        if (rhs_t == types.Primitive.none) rhs_t = try self.checkExpression(rhs);
        const has_instance_name = self.string_interner.intern("Symbol.hasInstance") catch return error.OutOfMemory;
        if (self.instanceofRhsDeclaresMember(rhs, has_instance_name)) {
            if (try self.instanceofHasInstanceSignature(rhs_t)) |sig| {
                if (self.signature_predicates.get(sig)) |pred| {
                    const target = try self.resolvePredicateTarget(pred);
                    return try self.preserveNamedInstanceofTargetNode(pred.target_node, target);
                }
            }
        }

        const prototype_name = self.string_interner.intern("prototype") catch return error.OutOfMemory;
        if (try self.lookupObjectMember(rhs_t, prototype_name)) |prototype_t| {
            if (!self.typeIsAnyLike(prototype_t)) {
                if (try self.explicitInstanceofPrototypeTarget(rhs, prototype_name, prototype_t)) |explicit| return explicit;
            }
        }

        var construct_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer construct_sigs.deinit(self.gpa);
        try self.collectConstructSignatures(rhs_t, &construct_sigs);
        if (construct_sigs.items.len == 0) return null;
        var returns: std.ArrayListUnmanaged(TypeId) = .empty;
        defer returns.deinit(self.gpa);
        for (construct_sigs.items) |sig| {
            var ret = self.interner.signatureReturn(sig) orelse types.Primitive.any;
            const generic_type_params = self.generic_signature_params.get(sig);
            if (generic_type_params) |type_params| {
                var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                defer subs.deinit(self.gpa);
                for (type_params) |param_t| try subs.put(self.gpa, param_t, types.Primitive.any);
                ret = self.substituteType(ret, &subs) catch ret;
            }
            if (self.signature_decl_nodes.get(sig)) |decl| {
                if (self.hir.kindOf(decl) == .fn_type or self.hir.kindOf(decl) == .constructor_type) {
                    ret = try self.preserveNamedInstanceofTargetNode(hir_mod.fnTypeOf(self.hir, decl).return_type, ret);
                }
            }
            try self.appendUniqueTypeId(&returns, ret);
        }
        if (returns.items.len == 1) return returns.items[0];
        return self.interner.internUnion(returns.items) catch return error.OutOfMemory;
    }

    fn preserveNamedInstanceofTargetNode(self: *Checker, node: NodeId, fallback: TypeId) CheckError!TypeId {
        if (node == hir_mod.none_node_id) return fallback;
        if (self.hir.kindOf(node) == .union_type) {
            var members: std.ArrayListUnmanaged(TypeId) = .empty;
            defer members.deinit(self.gpa);
            for (hir_mod.unionTypeMembers(self.hir, node)) |member_node| {
                const lowered = self.lowererLowerWithTypeParams(member_node) catch types.Primitive.unknown;
                const preserved = try self.preserveNamedInstanceofTargetNode(member_node, lowered);
                try members.append(self.gpa, self.namedInstanceofTargetForShape(preserved));
            }
            if (members.items.len == 0) return fallback;
            if (members.items.len == 1) return members.items[0];
            return self.interner.internUnion(members.items) catch return error.OutOfMemory;
        }
        if (self.hir.kindOf(node) != .type_ref or hir_mod.typeRefArgs(self.hir, node).len != 0) return fallback;
        const name = hir_mod.typeRefOf(self.hir, node).name;
        return self.type_names.get(name) orelse fallback;
    }

    fn explicitInstanceofPrototypeTarget(
        self: *Checker,
        rhs: NodeId,
        prototype_name: hir_mod.StringId,
        fallback: TypeId,
    ) CheckError!?TypeId {
        if (self.hir.kindOf(rhs) != .identifier) return null;
        const annotation = self.visibleAnnotatedIdentifierTypeNode(rhs) orelse return null;
        if (self.hir.kindOf(annotation) == .type_ref) {
            const ref = hir_mod.typeRefOf(self.hir, annotation);
            const decl = self.findVisibleNamedTypeDecl(annotation, ref.name) orelse return null;
            if (self.hir.kindOf(decl) != .interface_decl) return null;
            const member = self.interfaceMemberByName(decl, prototype_name) orelse return null;
            const type_node = hir_mod.interfaceMemberOf(self.hir, member).type_node;
            return try self.preserveNamedInstanceofTargetNode(type_node, fallback);
        }
        const text = self.nodeSourceTextOrEmpty(annotation);
        if (std.mem.indexOf(u8, text, "prototype") == null) return null;
        return self.namedInstanceofTargetForShape(fallback);
    }

    fn instanceofRhsDeclaresMember(self: *Checker, rhs: NodeId, member_name: hir_mod.StringId) bool {
        if (self.hir.kindOf(rhs) != .identifier) return false;
        const annotation = self.visibleAnnotatedIdentifierTypeNode(rhs) orelse return false;
        if (self.hir.kindOf(annotation) == .type_ref) {
            const ref = hir_mod.typeRefOf(self.hir, annotation);
            const decl = self.findVisibleNamedTypeDecl(annotation, ref.name) orelse return false;
            return self.hir.kindOf(decl) == .interface_decl and self.interfaceMemberByName(decl, member_name) != null;
        }
        return std.mem.indexOf(u8, self.nodeSourceTextOrEmpty(annotation), self.string_interner.get(member_name)) != null;
    }

    fn instanceofGenericDisplayFamilyMatches(self: *Checker, current: TypeId, target: TypeId) bool {
        const current_name = self.knownTypeDisplayName(current) orelse return false;
        const target_name = self.knownTypeDisplayName(target) orelse return false;
        const current_open = std.mem.indexOfScalar(u8, current_name, '<') orelse return false;
        const target_open = std.mem.indexOfScalar(u8, target_name, '<') orelse return false;
        return current_open == target_open and std.mem.eql(u8, current_name[0..current_open], target_name[0..target_open]);
    }

    fn instanceofGenericObjectTargetMatches(self: *Checker, current: TypeId, target: TypeId) bool {
        const target_name = self.knownTypeDisplayName(target) orelse return false;
        if (std.mem.indexOfScalar(u8, target_name, '<') == null) return false;
        return self.objectHasRequiredTargetMemberNames(current, target);
    }

    fn declaredGenericInstanceofConstituent(self: *Checker, lhs: NodeId, rhs: NodeId, target: TypeId) CheckError!?TypeId {
        const target_class = self.classNameForInstanceType(target) orelse blk: {
            if (self.hir.kindOf(rhs) != .identifier) break :blk null;
            const rhs_name = hir_mod.identifierOf(self.hir, rhs).name;
            if (!self.class_instance_types.contains(rhs_name)) break :blk null;
            break :blk rhs_name;
        };
        const target_base = if (target_class == null) blk: {
            const target_name = self.knownTypeDisplayName(target) orelse return null;
            const target_open = std.mem.indexOfScalar(u8, target_name, '<') orelse return null;
            break :blk target_name[0..target_open];
        } else "";
        const annotation = self.visibleAnnotatedIdentifierTypeNode(lhs) orelse return null;
        if (self.hir.kindOf(annotation) != .union_type) return null;

        var matches: std.ArrayListUnmanaged(TypeId) = .empty;
        defer matches.deinit(self.gpa);
        for (hir_mod.unionTypeMembers(self.hir, annotation)) |member_node| {
            if (self.hir.kindOf(member_node) != .type_ref) continue;
            const ref = hir_mod.typeRefOf(self.hir, member_node);
            if (hir_mod.typeRefArgs(self.hir, member_node).len == 0) continue;
            if (target_class) |class_name| {
                if (ref.name != class_name) continue;
            } else if (!std.mem.eql(u8, self.string_interner.get(ref.name), target_base)) {
                continue;
            }
            try matches.append(self.gpa, self.lowererLowerWithTypeParams(member_node) catch types.Primitive.unknown);
        }
        if (matches.items.len == 0) return null;
        if (matches.items.len == 1) return matches.items[0];
        return self.interner.internUnion(matches.items) catch return error.OutOfMemory;
    }

    fn namedInstanceofTargetForShape(self: *Checker, target: TypeId) TypeId {
        const name = self.objectTypeHasNamedShape(target, true) orelse
            self.objectTypeHasNamedShape(target, false) orelse
            return target;
        return self.type_names.get(name) orelse target;
    }

    fn nullishEqualityGuard(self: *Checker, cond: NodeId) ?NullishGuard {
        if (self.hir.kindOf(cond) != .binary_op) return null;
        const b = hir_mod.binopOf(self.hir, cond);
        if (b.op != .eq and b.op != .eq_strict) return null;
        if (self.hir.kindOf(b.lhs) == .identifier) {
            if (self.nullishGuardKindForNode(b.rhs, b.op)) |kind| {
                return .{ .name = hir_mod.identifierOf(self.hir, b.lhs).name, .ident_node = b.lhs, .kind = kind };
            }
        }
        if (self.hir.kindOf(b.rhs) == .identifier) {
            if (self.nullishGuardKindForNode(b.lhs, b.op)) |kind| {
                return .{ .name = hir_mod.identifierOf(self.hir, b.rhs).name, .ident_node = b.rhs, .kind = kind };
            }
        }
        return null;
    }

    fn nullishGuardKindForNode(self: *Checker, node: NodeId, op: hir_mod.BinOp) ?NullishGuardKind {
        return switch (self.hir.kindOf(node)) {
            .literal_null => if (op == .eq) .null_or_undefined else .null_only,
            .literal_undefined => if (op == .eq) .null_or_undefined else .undefined_only,
            .identifier => blk: {
                const id = hir_mod.identifierOf(self.hir, node);
                if (!std.mem.eql(u8, self.string_interner.get(id.name), "undefined")) break :blk null;
                break :blk if (op == .eq) .null_or_undefined else .undefined_only;
            },
            else => null,
        };
    }

    fn singleAssignmentValueToIdentifier(self: *Checker, node: NodeId, name: hir_mod.StringId) ?NodeId {
        const stmt = if (self.hir.kindOf(node) == .block_stmt) blk: {
            const stmts = hir_mod.blockStmts(self.hir, node);
            if (stmts.len != 1) return null;
            break :blk stmts[0];
        } else node;
        if (self.hir.kindOf(stmt) != .assignment) return null;
        const a = hir_mod.assignmentOf(self.hir, stmt);
        if (a.op != null or self.hir.kindOf(a.target) != .identifier) return null;
        if (hir_mod.identifierOf(self.hir, a.target).name != name) return null;
        return a.value;
    }

    fn subtractNullishGuardedType(self: *Checker, t: TypeId, kind: NullishGuardKind) !TypeId {
        return switch (kind) {
            .null_only => self.subtractType(t, types.Primitive.null_t) catch t,
            .undefined_only => self.subtractType(t, types.Primitive.undefined_t) catch t,
            .null_or_undefined => try self.subtractNullUndefined(t),
        };
    }

    /// Assertion-function flow narrowing. If `stmt` is a call to a
    /// function whose return type is `asserts arg is T`, record
    /// `arg -> T` in the surrounding narrow scope so subsequent
    /// statements in the same block see the narrowed type.
    fn applyAssertionFlow(self: *Checker, stmt: NodeId) !void {
        const k = self.hir.kindOf(stmt);
        if (k != .call_expr) return;
        const c = hir_mod.callOf(self.hir, stmt);
        if (self.hir.kindOf(c.callee) != .identifier) return;
        const callee_id = hir_mod.identifierOf(self.hir, c.callee);
        const pred = self.fn_predicates.get(callee_id.name) orelse return;
        if (!pred.is_asserts) return;
        const args = hir_mod.callArgs(self.hir, stmt);
        if (pred.param_index >= args.len) return;
        const arg = args[pred.param_index];
        if (self.hir.kindOf(arg) != .identifier) return;
        const arg_id = hir_mod.identifierOf(self.hir, arg);
        // Predicate-less `asserts arg` (no `is T`): narrow to a
        // truthy approximation by subtracting `null | undefined`
        // from the current type.
        if (pred.target_type == types.Primitive.unknown or pred.target_type == types.Primitive.none) {
            const current = self.lookupNarrow(arg_id.name) orelse self.typeOfIdentifier(arg);
            const narrowed = self.subtractNullUndefined(current) catch current;
            try self.recordNarrow(arg_id.name, narrowed);
            return;
        }
        const current = self.lookupNarrow(arg_id.name) orelse self.typeOfIdentifier(arg);
        const target = try self.instantiatePredicateTarget(stmt, pred);
        try self.recordNarrow(arg_id.name, try self.narrowTypeByPredicate(current, target));
    }

    fn checkAssertionCallTarget(
        self: *Checker,
        call_node: NodeId,
        callee: NodeId,
        callee_t: TypeId,
        effective_callee_t: TypeId,
    ) CheckError!void {
        const pred = self.assertionPredicateForCallTarget(callee, callee_t, effective_callee_t) orelse return;
        if (!pred.is_asserts) return;
        if (!self.assertionCallTargetIsQualifiedName(callee)) {
            try self.reportOnce(
                call_node,
                TsCodes.assertion_call_target_must_be_qualified_name,
                "Assertions require the call target to be an identifier or qualified name.",
            );
            return;
        }
        if (self.assertionCallTargetUnannotatedName(callee)) |related_node| {
            const related = try self.assertionCallTargetAnnotationRelatedInfo(related_node);
            if (!self.diagnosticExists(call_node, TsCodes.assertion_call_target_needs_explicit_annotations)) {
                try self.diagnostics.append(self.gpa, .{
                    .node = call_node,
                    .code = TsCodes.assertion_call_target_needs_explicit_annotations,
                    .message = "Assertions require every name in the call target to be declared with an explicit type annotation.",
                    .related = related,
                });
            }
        }
    }

    fn assertionPredicateForCallTarget(
        self: *Checker,
        callee: NodeId,
        callee_t: TypeId,
        effective_callee_t: TypeId,
    ) ?FnPredicate {
        switch (self.hir.kindOf(callee)) {
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, callee);
                if (self.fn_predicates.get(id.name)) |pred| return pred;
            },
            .member_access => {
                const m = hir_mod.memberOf(self.hir, callee);
                const receiver_t = self.hir.typeOf(m.object);
                if (receiver_t != types.Primitive.none) {
                    if (self.lookupMemberPredicate(receiver_t, m.name)) |pred| return pred;
                }
            },
            else => {},
        }
        if (self.signature_predicates.get(effective_callee_t)) |pred| return pred;
        if (effective_callee_t != callee_t) {
            if (self.signature_predicates.get(callee_t)) |pred| return pred;
        }
        return null;
    }

    fn assertionCallTargetIsQualifiedName(self: *Checker, callee: NodeId) bool {
        return switch (self.hir.kindOf(callee)) {
            .identifier, .this_expr => true,
            .member_access => self.assertionCallTargetIsQualifiedName(hir_mod.memberOf(self.hir, callee).object),
            else => false,
        };
    }

    fn assertionCallTargetUnannotatedName(self: *Checker, callee: NodeId) ?NodeId {
        return switch (self.hir.kindOf(callee)) {
            .identifier => blk: {
                const id = hir_mod.identifierOf(self.hir, callee);
                if (self.fn_predicates.get(id.name)) |pred| {
                    if (pred.is_asserts) break :blk null;
                }
                break :blk self.visibleUnannotatedVariableIdentifierNode(callee);
            },
            .this_expr => null,
            .member_access => blk: {
                const object = hir_mod.memberOf(self.hir, callee).object;
                break :blk self.assertionCallTargetUnannotatedName(object);
            },
            else => callee,
        };
    }

    fn assertionCallTargetAnnotationRelatedInfo(self: *Checker, name_node: NodeId) CheckError![]const RelatedInfo {
        const name_text = self.nodeSourceTextOrEmpty(name_node);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' needs an explicit type annotation.",
            .{name_text},
        );
        return self.diag_arena.allocator().dupe(RelatedInfo, &.{.{
            .node = name_node,
            .code = TsCodes.assertion_call_target_name_needs_annotation,
            .message = msg,
        }});
    }

    fn resolvePredicateTarget(self: *Checker, pred: FnPredicate) CheckError!TypeId {
        if (pred.target_type != types.Primitive.unknown or pred.target_node == hir_mod.none_node_id) return pred.target_type;
        return self.lowererLowerWithTypeParams(pred.target_node) catch pred.target_type;
    }

    fn instantiatePredicateTarget(self: *Checker, call_node: NodeId, pred: FnPredicate) CheckError!TypeId {
        const base_target = try self.resolvePredicateTarget(pred);
        if (!self.containsFreeTypeParameter(base_target)) return base_target;
        if (self.hir.kindOf(call_node) != .call_expr) return base_target;
        const c = hir_mod.callOf(self.hir, call_node);
        var callee_t = self.hir.typeOf(c.callee);
        if (callee_t == types.Primitive.none) callee_t = try self.checkExpression(c.callee);
        const call_member_id = self.string_interner.intern("__call") catch return error.OutOfMemory;
        if (!self.interner.isSignature(callee_t)) {
            if (self.interner.objectMember(callee_t, call_member_id)) |call_member_t| {
                callee_t = call_member_t;
            }
        }
        if (!self.interner.isSignature(callee_t)) return base_target;
        const args = hir_mod.callArgs(self.hir, call_node);
        var arg_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer arg_types.deinit(self.gpa);
        for (args) |arg| {
            var arg_t = self.hir.typeOf(arg);
            if (arg_t == types.Primitive.none) arg_t = try self.checkExpression(arg);
            try arg_types.append(self.gpa, arg_t);
        }
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        try self.inferPredicateCallSubstitutions(callee_t, args, arg_types.items, base_target, &subs);
        if (subs.count() == 0) return base_target;
        return self.substituteType(base_target, &subs) catch base_target;
    }

    fn inferPredicateCallSubstitutions(
        self: *Checker,
        sig: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        predicate_target: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) !void {
        if (!self.interner.isSignature(sig)) return;
        const param_ts = self.interner.signatureParams(sig);
        const n = @min(param_ts.len, arg_types.len);
        for (0..n) |i| {
            const param_t = param_ts[i];
            if (param_t >= self.interner.pool.typeCount()) continue;
            const param_flags = self.interner.pool.flagsOf(param_t);
            if (param_flags.is_signature and self.containsFreeTypeParameter(param_t)) {
                if (try self.inferFromPredicateSignatureArgument(param_t, null, args[i], arg_types[i], subs)) continue;
                if (self.interner.signatureReturn(param_t)) |param_ret| {
                    if (param_ret != types.Primitive.boolean_t) {
                        if (self.interner.signatureReturn(arg_types[i])) |arg_ret| {
                            try self.inferFromPair(param_ret, arg_ret, subs);
                        }
                    }
                }
            } else if (!param_flags.is_signature) {
                try self.inferFromArgument(param_t, arg_types[i], args[i], subs);
            }
        }
        if (subs.count() != 0) return;
        const target_tp = self.firstFreeTypeParameter(predicate_target) orelse return;
        for (args) |arg| {
            if (self.hir.kindOf(arg) != .identifier) continue;
            const id = hir_mod.identifierOf(self.hir, arg);
            const arg_pred = self.fn_predicates.get(id.name) orelse continue;
            if (self.containsFreeTypeParameter(arg_pred.target_type)) continue;
            try subs.put(self.gpa, target_tp, arg_pred.target_type);
            return;
        }
    }

    fn inferFromPredicateSignatureArgument(
        self: *Checker,
        param_sig: TypeId,
        param_pred_override: ?FnPredicate,
        arg_node: NodeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) !bool {
        const param_pred = param_pred_override orelse (self.signature_predicates.get(param_sig) orelse return false);
        if (!self.containsFreeTypeParameter(param_pred.target_type)) return false;
        var arg_target: ?TypeId = null;
        if (self.hir.kindOf(arg_node) == .identifier) {
            const arg_id = hir_mod.identifierOf(self.hir, arg_node);
            if (self.fn_predicates.get(arg_id.name)) |arg_pred| {
                arg_target = arg_pred.target_type;
            }
        }
        if (arg_target == null) {
            if (self.signature_predicates.get(arg_t)) |arg_pred| {
                arg_target = arg_pred.target_type;
            }
        }
        const target = arg_target orelse return false;
        if (self.containsFreeTypeParameter(target)) return false;
        try self.inferFromPair(param_pred.target_type, target, subs);
        return true;
    }

    fn inferFromPartiallyAnnotatedFunctionArgument(
        self: *Checker,
        param_sig: TypeId,
        arg_node: NodeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        if (param_sig >= self.interner.pool.typeCount()) return;
        if (!self.interner.pool.flagsOf(param_sig).is_signature) return;
        if (!self.containsFreeTypeParameter(param_sig)) return;
        if (!self.isContextualFunctionExpressionLike(arg_node)) return;

        const target_params = self.interner.signatureParams(param_sig);
        if (target_params.len == 0) return;
        const target_has_rest = self.rest_signatures.contains(param_sig);
        const fixed_target_count = if (target_has_rest) target_params.len - 1 else target_params.len;

        // A bare generic rest target must collect the callback's complete
        // positional signature before per-annotation inference runs. If the
        // scalar pass binds `TS` from the first annotated parameter first,
        // `(...args: TS) => void` incorrectly becomes `...args: number`
        // instead of `...args: [number, number]`.
        const source_sig = self.hir.typeOf(arg_node);
        if (source_sig < self.interner.pool.typeCount() and self.interner.isSignature(source_sig)) {
            try self.inferRestTupleFromSignatureParams(
                param_sig,
                target_params,
                source_sig,
                self.interner.signatureParams(source_sig),
                subs,
            );
        }

        const params = hir_mod.fnParams(self.hir, arg_node);
        var value_param_count: usize = 0;
        var has_unannotated_rest_param = false;
        for (params) |p| {
            if (self.hir.kindOf(p) != .parameter) continue;
            if (self.isThisParameter(p)) continue;
            const pp = hir_mod.parameterOf(self.hir, p);
            if (pp.flags.is_rest and pp.type_annotation == hir_mod.none_node_id) has_unannotated_rest_param = true;
            value_param_count += 1;
        }
        if (!target_has_rest and value_param_count > target_params.len) return;

        var value_index: usize = 0;
        for (params) |p| {
            if (self.hir.kindOf(p) != .parameter) continue;
            if (self.isThisParameter(p)) continue;
            const pp = hir_mod.parameterOf(self.hir, p);
            defer value_index += 1;
            if (pp.type_annotation == hir_mod.none_node_id) continue;

            var source_t = self.lowererLowerWithTypeParams(pp.type_annotation) catch continue;
            if (pp.flags.is_optional or pp.default_value != hir_mod.none_node_id) {
                source_t = self.unionWithUndefined(source_t) catch source_t;
            }

            if (pp.flags.is_rest) {
                const source_elem_t = self.interner.objectNumberIndex(source_t);
                const rest_source_t = if (source_elem_t != types.Primitive.none) source_elem_t else source_t;
                if (value_index < fixed_target_count) {
                    var i = value_index;
                    while (i < fixed_target_count) : (i += 1) {
                        try self.inferFromPair(target_params[i], rest_source_t, subs);
                    }
                }
                if (target_has_rest) {
                    const rest_target_t = target_params[target_params.len - 1];
                    const rest_elem_t = self.interner.objectNumberIndex(rest_target_t);
                    try self.inferFromPair(if (rest_elem_t != types.Primitive.none) rest_elem_t else rest_target_t, rest_source_t, subs);
                }
                continue;
            }

            if (target_has_rest and has_unannotated_rest_param and !pp.flags.is_rest) continue;
            if (value_index < fixed_target_count) {
                try self.inferFromPair(target_params[value_index], source_t, subs);
            } else if (target_has_rest) {
                const rest_target_t = target_params[target_params.len - 1];
                const rest_elem_t = self.interner.objectNumberIndex(rest_target_t);
                try self.inferFromPair(if (rest_elem_t != types.Primitive.none) rest_elem_t else rest_target_t, source_t, subs);
            }
        }
    }

    fn genericInferenceFunctionArgumentType(self: *Checker, arg_node: NodeId, fallback: TypeId) CheckError!TypeId {
        if (!self.isContextualFunctionExpressionLike(arg_node)) return fallback;
        return self.functionExpressionInferenceSignature(arg_node, fallback, false);
    }

    fn functionExpressionInferenceSignature(
        self: *Checker,
        fn_node: NodeId,
        fallback: TypeId,
        preserve_direct_literal_return: bool,
    ) CheckError!TypeId {
        if (!self.isContextualFunctionExpressionLike(fn_node)) return fallback;
        if (!self.interner.isSignature(fallback)) return fallback;

        const borrowed_params = self.interner.signatureParams(fallback);
        const param_ts = try self.gpa.dupe(TypeId, borrowed_params);
        defer self.gpa.free(param_ts);
        var value_index: usize = 0;
        for (hir_mod.fnParams(self.hir, fn_node)) |param_node| {
            if (self.hir.kindOf(param_node) != .parameter) continue;
            if (self.isThisParameter(param_node)) continue;
            if (value_index >= param_ts.len) break;
            const param = hir_mod.parameterOf(self.hir, param_node);
            if (param.type_annotation != hir_mod.none_node_id) {
                var explicit_t = self.lowererLowerWithTypeParams(param.type_annotation) catch param_ts[value_index];
                if (self.objectAnnotationName(param.type_annotation) != null and
                    explicit_t >= types.Primitive.first_dynamic and explicit_t < self.interner.pool.typeCount())
                {
                    self.builtin_object_names.put(self.gpa, explicit_t, "Object") catch {};
                }
                if (param.flags.is_optional or param.default_value != hir_mod.none_node_id) {
                    explicit_t = self.unionWithUndefined(explicit_t) catch explicit_t;
                }
                param_ts[value_index] = explicit_t;
            }
            value_index += 1;
        }

        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        var ret_t = self.interner.signatureReturn(fallback) orelse types.Primitive.any;
        if (f.body != hir_mod.none_node_id and self.hir.kindOf(f.body) != .block_stmt) {
            const body_t = if (self.hir.typeOf(f.body) != types.Primitive.none)
                self.hir.typeOf(f.body)
            else
                try self.checkExpression(f.body);
            if (self.isContextualFunctionExpressionLike(f.body)) {
                ret_t = try self.functionExpressionInferenceSignature(f.body, body_t, true);
            } else if (preserve_direct_literal_return or self.hir.kindOf(f.body) == .conditional) {
                ret_t = try self.expressionLiteralType(f.body, body_t);
                if (self.hir.kindOf(f.body) == .conditional) {
                    ret_t = try self.valueNodeLiteralType(f.body, ret_t);
                }
            } else {
                ret_t = body_t;
            }
            if (!self.strict_flags.strict_null_checks and
                (ret_t == types.Primitive.null_t or ret_t == types.Primitive.undefined_t))
            {
                ret_t = types.Primitive.any;
            }
        }

        const sig = self.interner.internSignature(param_ts, ret_t, false) catch return error.OutOfMemory;
        try self.copySignatureParamNames(sig, fallback);
        if (self.rest_signatures.contains(fallback)) try self.rest_signatures.put(self.gpa, sig, {});
        if (self.signature_min_args.get(fallback)) |min_args| try self.signature_min_args.put(self.gpa, sig, min_args);
        return sig;
    }

    fn recordPredicateNarrowForExpression(self: *Checker, expr: NodeId, target: TypeId, when_true: bool) !bool {
        if (self.hir.kindOf(expr) == .identifier) {
            const id = hir_mod.identifierOf(self.hir, expr);
            const current = self.lookupNarrow(id.name) orelse self.typeOfIdentifier(expr);
            const narrowed = if (when_true)
                try self.narrowTypeByPredicate(current, target)
            else
                (self.subtractTypeByPredicate(current, target) catch current);
            try self.recordNarrow(id.name, narrowed);
            return true;
        }
        if (self.hir.kindOf(expr) == .member_access) {
            const m = hir_mod.memberOf(self.hir, expr);
            if (self.hir.kindOf(m.object) != .identifier) return false;
            const obj_id = hir_mod.identifierOf(self.hir, m.object);
            const key: MemberKey = .{ .obj_name = obj_id.name, .prop_name = m.name };
            const obj_t = self.lookupNarrow(obj_id.name) orelse self.typeOfIdentifier(m.object);
            const current = self.lookupMemberNarrow(key) orelse
                ((try self.lookupObjectMember(obj_t, m.name)) orelse self.hir.typeOf(expr));
            if (current == types.Primitive.none) return false;
            const narrowed = if (when_true)
                try self.narrowTypeByPredicate(current, target)
            else
                (self.subtractTypeByPredicate(current, target) catch current);
            try self.recordMemberNarrow(key, narrowed);
            return true;
        }
        return false;
    }

    const TypeofComparison = struct {
        name: hir_mod.StringId,
        node: NodeId,
        target: TypeId,
        is_equal: bool,
    };

    fn typeofNarrowType(self: *Checker, lit_str: []const u8, fallback: TypeId) CheckError!TypeId {
        if (std.mem.eql(u8, lit_str, "function")) {
            return self.lowerBuiltinObjectType("Function") orelse fallback;
        }
        return fallback;
    }

    fn applyTypeofExpressionGuard(
        self: *Checker,
        operand: NodeId,
        comparison: NodeId,
        positive: bool,
    ) CheckError!bool {
        if (try self.applyTypeofPropertyGuard(operand, comparison, positive)) return true;
        if (self.hir.kindOf(operand) != .identifier) return false;

        const id = hir_mod.identifierOf(self.hir, operand);
        const type_name = (try self.staticStringValue(comparison)) orelse return true;
        const lit_str = self.string_interner.get(type_name);
        const narrowed = typeOfTypeofString(lit_str) orelse
            (if (std.mem.eql(u8, lit_str, "Object")) types.Primitive.object_t else return true);
        const target = try self.typeofNarrowType(lit_str, narrowed);
        if (!self.identifierHasNarrowableValueBinding(operand)) return true;
        const declared = self.visibleAnnotatedIdentifierType(operand) orelse
            self.typeOfIdentifierDeclared(operand);
        const current = self.lookupNarrow(id.name) orelse declared;
        if (self.strict_flags.strict_null_checks and
            !positive and
            current == declared and
            self.identifierHasPendingUsedBeforeAssignmentDecl(operand)) return true;
        if (positive) {
            if (std.mem.eql(u8, lit_str, "object") and self.typeIsAny(current)) {
                try self.recordNarrow(id.name, current);
                return true;
            }
            const next = if (std.mem.eql(u8, lit_str, "object") and self.typeIncludesNull(current))
                self.objectOrNullType()
            else if (self.typeofObjectLikePositiveBranchIsNever(current, lit_str))
                types.Primitive.never
            else
                try self.narrowTypeByPredicate(current, target);
            try self.recordNarrow(id.name, next);
        } else {
            var subbed = self.subtractTypeByPredicate(current, target) catch current;
            if (std.mem.eql(u8, lit_str, "object") and self.typeIncludesNull(subbed)) {
                subbed = self.subtractTypeByPredicate(subbed, types.Primitive.null_t) catch subbed;
            }
            try self.recordNarrow(id.name, subbed);
        }
        return true;
    }

    fn identifierHasNarrowableValueBinding(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, node);
        if (self.isNodeCommonJsGlobalName(id.name)) {
            if (self.sourceHasVarDeclarationText(id.name)) return true;
            if (self.globalAugmentedValueType(id.name, node) catch null != null) return true;
            if (self.module) |module| {
                if (module.root.lookup(id.name) != null) return true;
            }
            return false;
        }
        if (self.isBuiltinName(id.name)) return true;
        if (self.sourceHasVarDeclarationText(id.name)) return true;
        if (self.globalAugmentedValueType(id.name, node) catch null != null) return true;
        if (self.module) |module| {
            if (module.root.lookup(id.name) != null) return true;
        }

        const use_start = self.hir.spanOf(node).start;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const kind = self.hir.kindOf(cur);
            if (kind == .fn_decl or kind == .fn_expr or kind == .arrow_fn) {
                for (hir_mod.fnParams(self.hir, cur)) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, pp.name).name == id.name) return true;
                }
            } else if (kind == .try_stmt) {
                const ts = hir_mod.tryOf(self.hir, cur);
                if (ts.catch_param != hir_mod.none_node_id and self.hir.kindOf(ts.catch_param) == .identifier) {
                    if (hir_mod.identifierOf(self.hir, ts.catch_param).name == id.name) return true;
                }
            }

            const stmts: ?[]const NodeId = switch (kind) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl => hir_mod.namespaceBody(self.hir, cur),
                else => null,
            };
            if (stmts) |items| {
                for (items) |stmt| {
                    if (self.hir.spanOf(stmt).start >= use_start) break;
                    const decl = if (self.hir.kindOf(stmt) == .export_decl) hir_mod.exportOf(self.hir, stmt).decl else stmt;
                    if (decl == hir_mod.none_node_id) continue;
                    switch (self.hir.kindOf(decl)) {
                        .var_decl, .let_decl, .const_decl => {
                            const v = hir_mod.varDeclOf(self.hir, decl);
                            if (v.name != hir_mod.none_node_id and
                                self.hir.kindOf(v.name) == .identifier and
                                hir_mod.identifierOf(self.hir, v.name).name == id.name)
                            {
                                return true;
                            }
                        },
                        .fn_decl, .fn_expr => {
                            const f = hir_mod.fnDeclOf(self.hir, decl);
                            if (f.name != hir_mod.none_node_id and
                                self.hir.kindOf(f.name) == .identifier and
                                hir_mod.identifierOf(self.hir, f.name).name == id.name)
                            {
                                return true;
                            }
                        },
                        .class_decl, .class_expr => {
                            const c = hir_mod.classOf(self.hir, decl);
                            if (c.name != hir_mod.none_node_id and
                                self.hir.kindOf(c.name) == .identifier and
                                hir_mod.identifierOf(self.hir, c.name).name == id.name)
                            {
                                return true;
                            }
                        },
                        .import_decl => if (self.importDeclBindsLocal(decl, id.name)) return true,
                        else => {},
                    }
                }
            }
        }
        return false;
    }

    fn typeofComparison(self: *Checker, node: NodeId) CheckError!?TypeofComparison {
        if (self.hir.kindOf(node) == .unary_op) {
            const u = hir_mod.unaryOf(self.hir, node);
            if (u.op == .not) {
                var comparison = (try self.typeofComparison(u.operand)) orelse return null;
                comparison.is_equal = !comparison.is_equal;
                return comparison;
            }
        }
        if (self.hir.kindOf(node) != .binary_op) return null;
        const b = hir_mod.binopOf(self.hir, node);
        const is_equal = b.op == .eq_strict or b.op == .eq;
        const is_not_equal = b.op == .neq_strict or b.op == .neq;
        if (!is_equal and !is_not_equal) return null;
        if (self.hir.kindOf(b.lhs) != .unary_op) return null;
        const u = hir_mod.unaryOf(self.hir, b.lhs);
        if (u.op != .typeof or self.hir.kindOf(u.operand) != .identifier) return null;
        const type_name = (try self.staticStringValue(b.rhs)) orelse return null;
        const lit_str = self.string_interner.get(type_name);
        const base = typeOfTypeofString(lit_str) orelse return null;
        return .{
            .name = hir_mod.identifierOf(self.hir, u.operand).name,
            .node = u.operand,
            .target = try self.typeofNarrowType(lit_str, base),
            .is_equal = is_equal,
        };
    }

    fn collectTypeofChainTargets(
        self: *Checker,
        node: NodeId,
        op: hir_mod.LogicalOp,
        want_equal: bool,
        name: *?hir_mod.StringId,
        first_node: *NodeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!bool {
        if (self.hir.kindOf(node) == .logical_op) {
            const l = hir_mod.logicalOf(self.hir, node);
            if (l.op != op) return false;
            return (try self.collectTypeofChainTargets(l.lhs, op, want_equal, name, first_node, out)) and
                (try self.collectTypeofChainTargets(l.rhs, op, want_equal, name, first_node, out));
        }
        const cmp = (try self.typeofComparison(node)) orelse return false;
        if (cmp.is_equal != want_equal) return false;
        if (name.*) |existing| {
            if (existing != cmp.name) return false;
        } else {
            name.* = cmp.name;
            first_node.* = cmp.node;
        }
        try out.append(self.gpa, cmp.target);
        return true;
    }

    fn applyTypeofTargetUnion(self: *Checker, name: hir_mod.StringId, node: NodeId, targets: []const TypeId) CheckError!bool {
        if (targets.len == 0) return false;
        const target = if (targets.len == 1)
            targets[0]
        else
            self.interner.internUnion(targets) catch return error.OutOfMemory;
        const current = self.lookupNarrow(name) orelse self.typeOfIdentifier(node);
        const narrowed = try self.narrowTypeByPredicate(current, target);
        try self.recordNarrow(name, narrowed);
        return true;
    }

    fn applyTrueOrTypeofChain(self: *Checker, lhs: NodeId, rhs: NodeId) CheckError!bool {
        var targets: std.ArrayListUnmanaged(TypeId) = .empty;
        defer targets.deinit(self.gpa);
        var name: ?hir_mod.StringId = null;
        var first_node: NodeId = hir_mod.none_node_id;
        if (!try self.collectTypeofChainTargets(lhs, .@"or", true, &name, &first_node, &targets)) return false;
        if (!try self.collectTypeofChainTargets(rhs, .@"or", true, &name, &first_node, &targets)) return false;
        return try self.applyTypeofTargetUnion(name orelse return false, first_node, targets.items);
    }

    const EqualityComparison = struct {
        name: hir_mod.StringId,
        node: NodeId,
        target: TypeId,
        is_equal: bool,
    };

    fn equalityComparison(self: *Checker, node: NodeId) CheckError!?EqualityComparison {
        if (self.hir.kindOf(node) != .binary_op) return null;
        const b = hir_mod.binopOf(self.hir, node);
        const is_equal = b.op == .eq_strict or b.op == .eq;
        const is_not_equal = b.op == .neq_strict or b.op == .neq;
        if (!is_equal and !is_not_equal) return null;
        const identifier_node, const literal_node = if (self.hir.kindOf(b.lhs) == .identifier)
            .{ b.lhs, b.rhs }
        else if (self.hir.kindOf(b.rhs) == .identifier)
            .{ b.rhs, b.lhs }
        else
            return null;
        const target = (try self.expressionNarrowLiteralType(literal_node)) orelse return null;
        return .{
            .name = hir_mod.identifierOf(self.hir, identifier_node).name,
            .node = identifier_node,
            .target = target,
            .is_equal = is_equal,
        };
    }

    fn collectEqualityChainTargets(
        self: *Checker,
        node: NodeId,
        op: hir_mod.LogicalOp,
        want_equal: bool,
        name: *?hir_mod.StringId,
        first_node: *NodeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!bool {
        if (self.hir.kindOf(node) == .logical_op) {
            const l = hir_mod.logicalOf(self.hir, node);
            if (l.op != op) return false;
            return (try self.collectEqualityChainTargets(l.lhs, op, want_equal, name, first_node, out)) and
                (try self.collectEqualityChainTargets(l.rhs, op, want_equal, name, first_node, out));
        }
        const cmp = (try self.equalityComparison(node)) orelse return false;
        if (cmp.is_equal != want_equal) return false;
        if (name.*) |existing| {
            if (existing != cmp.name) return false;
        } else {
            name.* = cmp.name;
            first_node.* = cmp.node;
        }
        try out.append(self.gpa, cmp.target);
        return true;
    }

    fn applyTrueOrEqualityChain(self: *Checker, lhs: NodeId, rhs: NodeId) CheckError!bool {
        var targets: std.ArrayListUnmanaged(TypeId) = .empty;
        defer targets.deinit(self.gpa);
        var name: ?hir_mod.StringId = null;
        var first_node: NodeId = hir_mod.none_node_id;
        if (!try self.collectEqualityChainTargets(lhs, .@"or", true, &name, &first_node, &targets)) return false;
        if (!try self.collectEqualityChainTargets(rhs, .@"or", true, &name, &first_node, &targets)) return false;
        return try self.applyTypeofTargetUnion(name orelse return false, first_node, targets.items);
    }

    /// Try to narrow `pred1(x) || pred2(x) [|| ...]` where every
    /// disjunct is a call to a registered type-predicate function and
    /// every argument is the SAME identifier. The truthy branch
    /// narrows the identifier to the union of each predicate's target
    /// type. Mirrors upstream tsc's `controlFlowBinaryOrExpression`
    /// baseline where `if (isNodeList(o) || isHTMLCollection(o))`
    /// admits `o.length` because `o` becomes `NodeList | HTMLCollection`.
    fn applyTrueOrPredicateCallChain(self: *Checker, lhs: NodeId, rhs: NodeId) CheckError!bool {
        var name: ?hir_mod.StringId = null;
        var first_node: NodeId = hir_mod.none_node_id;
        var targets: std.ArrayListUnmanaged(TypeId) = .empty;
        defer targets.deinit(self.gpa);
        if (!try self.collectPredicateCallChainTargets(lhs, &name, &first_node, &targets)) return false;
        if (!try self.collectPredicateCallChainTargets(rhs, &name, &first_node, &targets)) return false;
        const arg_name = name orelse return false;
        if (targets.items.len == 0) return false;
        const union_target = if (targets.items.len == 1)
            targets.items[0]
        else
            self.interner.internUnion(targets.items) catch return error.OutOfMemory;
        const current = self.lookupNarrow(arg_name) orelse self.typeOfIdentifier(first_node);
        const narrowed = try self.narrowTypeByPredicate(current, union_target);
        try self.recordNarrow(arg_name, narrowed);
        return true;
    }

    fn collectPredicateCallChainTargets(
        self: *Checker,
        node: NodeId,
        name: *?hir_mod.StringId,
        first_node: *NodeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!bool {
        // `a || b` recurses into both sides so chains of length 3+
        // collapse into a single union narrow.
        if (self.hir.kindOf(node) == .logical_op) {
            const l = hir_mod.logicalOf(self.hir, node);
            if (l.op != .@"or") return false;
            return (try self.collectPredicateCallChainTargets(l.lhs, name, first_node, out)) and
                (try self.collectPredicateCallChainTargets(l.rhs, name, first_node, out));
        }
        if (self.hir.kindOf(node) != .call_expr) return false;
        const c = hir_mod.callOf(self.hir, node);
        if (self.hir.kindOf(c.callee) != .identifier) return false;
        const callee_id = hir_mod.identifierOf(self.hir, c.callee);
        const pred = self.fn_predicates.get(callee_id.name) orelse return false;
        const args = hir_mod.callArgs(self.hir, node);
        if (pred.param_index >= args.len) return false;
        const arg = args[pred.param_index];
        if (self.hir.kindOf(arg) != .identifier) return false;
        const arg_id = hir_mod.identifierOf(self.hir, arg);
        if (name.*) |existing| {
            if (existing != arg_id.name) return false;
        } else {
            name.* = arg_id.name;
            first_node.* = arg;
        }
        const target = try self.instantiatePredicateTarget(node, pred);
        try out.append(self.gpa, target);
        return true;
    }

    fn applyFalseAndTypeofChain(self: *Checker, lhs: NodeId, rhs: NodeId) CheckError!bool {
        var targets: std.ArrayListUnmanaged(TypeId) = .empty;
        defer targets.deinit(self.gpa);
        var name: ?hir_mod.StringId = null;
        var first_node: NodeId = hir_mod.none_node_id;
        if (!try self.collectTypeofChainTargets(lhs, .@"and", false, &name, &first_node, &targets)) return false;
        if (!try self.collectTypeofChainTargets(rhs, .@"and", false, &name, &first_node, &targets)) return false;
        return try self.applyTypeofTargetUnion(name orelse return false, first_node, targets.items);
    }

    fn applyFalseAndEqualityChain(self: *Checker, lhs: NodeId, rhs: NodeId) CheckError!bool {
        var targets: std.ArrayListUnmanaged(TypeId) = .empty;
        defer targets.deinit(self.gpa);
        var name: ?hir_mod.StringId = null;
        var first_node: NodeId = hir_mod.none_node_id;
        if (!try self.collectEqualityChainTargets(lhs, .@"and", false, &name, &first_node, &targets)) return false;
        if (!try self.collectEqualityChainTargets(rhs, .@"and", false, &name, &first_node, &targets)) return false;
        return try self.applyTypeofTargetUnion(name orelse return false, first_node, targets.items);
    }

    fn nodeIsNullLiteralish(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) == .literal_null) return true;
        if (self.hir.kindOf(node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, node);
        return std.mem.eql(u8, self.string_interner.get(id.name), "null");
    }

    fn nodeIsUndefinedLiteralish(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) == .literal_undefined) return true;
        if (self.hir.kindOf(node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, node);
        return std.mem.eql(u8, self.string_interner.get(id.name), "undefined");
    }

    const FlowNarrowSnapshot = struct {
        names: std.AutoHashMapUnmanaged(hir_mod.StringId, TypeId) = .empty,
        members: std.AutoHashMapUnmanaged(MemberKey, TypeId) = .empty,

        fn deinit(snapshot: *FlowNarrowSnapshot, gpa: std.mem.Allocator) void {
            snapshot.names.deinit(gpa);
            snapshot.members.deinit(gpa);
        }
    };

    fn snapshotGuardBranch(
        self: *Checker,
        first: NodeId,
        first_when_true: bool,
        second: ?NodeId,
    ) CheckError!FlowNarrowSnapshot {
        try self.pushNarrowScope();
        defer self.popNarrowScope();
        try self.applyTypeGuard(first, first_when_true);
        if (second) |node| try self.applyTypeGuard(node, true);

        var snapshot: FlowNarrowSnapshot = .{};
        errdefer snapshot.deinit(self.gpa);
        var name_it = self.narrow_scopes.items[self.narrow_scopes.items.len - 1].iterator();
        while (name_it.next()) |entry| {
            try snapshot.names.put(self.gpa, entry.key_ptr.*, entry.value_ptr.*);
        }
        var member_it = self.member_narrow_scopes.items[self.member_narrow_scopes.items.len - 1].iterator();
        while (member_it.next()) |entry| {
            try snapshot.members.put(self.gpa, entry.key_ptr.*, entry.value_ptr.*);
        }
        return snapshot;
    }

    fn applyTrueOrBranchJoin(self: *Checker, lhs: NodeId, rhs: NodeId) CheckError!void {
        var lhs_true = try self.snapshotGuardBranch(lhs, true, null);
        defer lhs_true.deinit(self.gpa);
        var rhs_true = try self.snapshotGuardBranch(lhs, false, rhs);
        defer rhs_true.deinit(self.gpa);

        var name_it = lhs_true.names.iterator();
        while (name_it.next()) |entry| {
            const rhs_t = rhs_true.names.get(entry.key_ptr.*) orelse continue;
            const joined = try self.internConditionalUnion(&.{ entry.value_ptr.*, rhs_t });
            try self.recordNarrow(entry.key_ptr.*, joined);
        }
        var member_it = lhs_true.members.iterator();
        while (member_it.next()) |entry| {
            const rhs_t = rhs_true.members.get(entry.key_ptr.*) orelse continue;
            const joined = try self.internConditionalUnion(&.{ entry.value_ptr.*, rhs_t });
            try self.recordMemberNarrow(entry.key_ptr.*, joined);
        }
    }

    fn unknownEqualityNarrowCandidate(self: *Checker, node: NodeId) CheckError!?TypeId {
        if (try self.expressionNarrowLiteralType(node)) |literal_t| return literal_t;
        var candidate_t = self.hir.typeOf(node);
        if (candidate_t == types.Primitive.none) candidate_t = try self.checkExpression(node);
        if (candidate_t == types.Primitive.none or
            candidate_t == types.Primitive.any or
            candidate_t == types.Primitive.unknown)
        {
            return null;
        }
        if (candidate_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(candidate_t);
        if (flags.is_union or flags.is_intersection) return null;
        return candidate_t;
    }

    fn applyUnknownEqualityGuard(
        self: *Checker,
        unknown_node: NodeId,
        other_node: NodeId,
        op: hir_mod.BinOp,
        positive: bool,
    ) CheckError!bool {
        if (self.hir.kindOf(unknown_node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, unknown_node);
        const current = self.lookupNarrow(id.name) orelse self.typeOfIdentifier(unknown_node);
        if (current != types.Primitive.unknown) return false;
        if (self.nodeIsNullLiteralish(other_node) or self.nodeIsUndefinedLiteralish(other_node)) return false;
        if (op == .eq or op == .neq) return true;
        if (!positive) return true;
        const candidate_t = (try self.unknownEqualityNarrowCandidate(other_node)) orelse return true;
        try self.recordNarrow(id.name, candidate_t);
        return true;
    }

    fn applyAssignmentNullishEqualityGuard(
        self: *Checker,
        assignment_node: NodeId,
        nullish_node: NodeId,
        op: hir_mod.BinOp,
        positive: bool,
    ) CheckError!bool {
        if (self.hir.kindOf(assignment_node) != .assignment) return false;
        const assignment = hir_mod.assignmentOf(self.hir, assignment_node);
        if (assignment.op != null or self.hir.kindOf(assignment.target) != .identifier) return false;

        const compares_null = self.nodeIsNullLiteralish(nullish_node);
        const compares_undefined = self.nodeIsUndefinedLiteralish(nullish_node);
        if (!compares_null and !compares_undefined) return false;

        var current = self.hir.typeOf(assignment.value);
        if (current == types.Primitive.none) current = try self.checkExpression(assignment.value);
        const narrowed = if (positive) blk_positive: {
            if (op == .eq or op == .neq) {
                break :blk_positive try self.nullUndefinedUnionType();
            }
            break :blk_positive if (compares_null)
                types.Primitive.null_t
            else
                types.Primitive.undefined_t;
        } else blk_negative: {
            var result = if (compares_null)
                self.subtractType(current, types.Primitive.null_t) catch current
            else
                self.subtractType(current, types.Primitive.undefined_t) catch current;
            if (op == .eq or op == .neq) {
                result = if (compares_null)
                    self.subtractType(result, types.Primitive.undefined_t) catch result
                else
                    self.subtractType(result, types.Primitive.null_t) catch result;
            }
            break :blk_negative result;
        };
        try self.recordNarrow(hir_mod.identifierOf(self.hir, assignment.target).name, narrowed);
        return true;
    }

    fn applyTypeGuard(self: *Checker, cond: NodeId, when_true: bool) !void {
        // Aliased conditional narrowing: `if (cond)` where `cond`
        // was bound to a guard expression. Expand the alias and
        // recurse on the original expression so all the existing
        // guard logic applies — this narrows any reference the guard
        // mentions (e.g. `const ok = isFoo(x); if (ok) { /* x: Foo */ }`).
        //
        // The alias expansion is ADDITIVE: it narrows the inner
        // reference but MUST NOT suppress `cond`'s OWN truthiness
        // narrowing. Upstream tsc applies `getTypeWithFacts(..., Truthy)`
        // to the reference regardless of any alias machinery, so a
        // const initialized from a non-predicate call (the common
        // `const f = g(); if (f) { f.bar }` shape, where `g(): T | null`)
        // still strips `null | undefined` from `f` in the truthy
        // branch. Falling through (instead of returning) lets the
        // bare-identifier truthy path below run for `cond` itself.
        if (self.hir.kindOf(cond) == .identifier) {
            const id = hir_mod.identifierOf(self.hir, cond);
            if (self.cond_aliases.get(id.name)) |aliased| {
                try self.applyTypeGuard(aliased, when_true);
                // Continue to the bare-identifier truthy/falsy narrow
                // for `cond` itself rather than returning here.
            }
        }
        // `if (Array.isArray(x))` ÃÂ¢ÃÂÃÂ built-in narrowing for the
        // canonical array predicate. We don't yet have a fully-shaped
        // `Array<any>` reference type wired up here, so we narrow the
        // argument to `Primitive.object_t` (arrays are objects). This
        // mirrors the approximation used elsewhere (e.g. `instanceof`)
        // and lets `let arr = x` after the guard pick up an object
        // type rather than the original `any`/union.
        if (self.hir.kindOf(cond) == .call_expr) {
            const c = hir_mod.callOf(self.hir, cond);
            if (self.hir.kindOf(c.callee) == .member_access) {
                const m = hir_mod.memberOf(self.hir, c.callee);
                if (self.hir.kindOf(m.object) == .identifier) {
                    const obj_id = hir_mod.identifierOf(self.hir, m.object);
                    const obj_name = self.string_interner.get(obj_id.name);
                    const prop_name = self.string_interner.get(m.name);
                    if (std.mem.eql(u8, obj_name, "Array") and
                        std.mem.eql(u8, prop_name, "isArray"))
                    {
                        const args = hir_mod.callArgs(self.hir, cond);
                        if (args.len >= 1 and self.hir.kindOf(args[0]) == .identifier) {
                            const arg_id = hir_mod.identifierOf(self.hir, args[0]);
                            if (when_true) {
                                try self.recordNarrow(arg_id.name, types.Primitive.object_t);
                            } else {
                                const current = self.lookupNarrow(arg_id.name) orelse self.typeOfIdentifier(args[0]);
                                const narrowed = self.subtractType(current, types.Primitive.object_t) catch current;
                                try self.recordNarrow(arg_id.name, narrowed);
                            }
                            return;
                        }
                    }
                }
            }
        }
        // `if (obj.isFoo())` where the method return type is
        // `this is Foo`. Predicate metadata is attached to the
        // method's signature, so narrow the receiver expression.
        if (self.hir.kindOf(cond) == .call_expr) {
            const c = hir_mod.callOf(self.hir, cond);
            if (self.hir.kindOf(c.callee) == .member_access) {
                const m = hir_mod.memberOf(self.hir, c.callee);
                var receiver_t = self.hir.typeOf(m.object);
                if (receiver_t == types.Primitive.none) receiver_t = try self.checkExpression(m.object);
                if (self.lookupMemberPredicate(receiver_t, m.name)) |pred| {
                    if (pred.param_index == 0xFFFF) {
                        const target = try self.resolvePredicateTarget(pred);
                        if (try self.recordPredicateNarrowForExpression(m.object, target, when_true)) return;
                    }
                }
                var callee_t = self.hir.typeOf(c.callee);
                if (callee_t == types.Primitive.none) callee_t = try self.checkExpression(c.callee);
                if (self.signature_predicates.get(callee_t)) |pred| {
                    if (pred.param_index == 0xFFFF) {
                        const target = try self.resolvePredicateTarget(pred);
                        if (try self.recordPredicateNarrowForExpression(m.object, target, when_true)) return;
                    }
                }
                if (self.fn_predicates.get(m.name)) |pred| {
                    if (pred.param_index == 0xFFFF) {
                        const target = try self.resolvePredicateTarget(pred);
                        if (try self.recordPredicateNarrowForExpression(m.object, target, when_true)) return;
                    }
                }
            }
        }
        // `if (isFoo(x))` ÃÂ¢ÃÂÃÂ type-predicate call narrowing. When the
        // condition is a call to a predicate function and the argument
        // at the predicate's parameter index is an identifier, narrow
        // the identifier in the then-branch to the predicate's target
        // type (or subtract it in the else-branch).
        if (self.hir.kindOf(cond) == .call_expr) {
            const c = hir_mod.callOf(self.hir, cond);
            if (self.hir.kindOf(c.callee) == .identifier) {
                const callee_id = hir_mod.identifierOf(self.hir, c.callee);
                if (self.fn_predicates.get(callee_id.name)) |pred| {
                    const args = hir_mod.callArgs(self.hir, cond);
                    if (pred.param_index < args.len) {
                        const arg = args[pred.param_index];
                        if (self.hir.kindOf(arg) == .identifier) {
                            const arg_id = hir_mod.identifierOf(self.hir, arg);
                            const target = try self.instantiatePredicateTarget(cond, pred);
                            if (when_true) {
                                const current = self.lookupNarrow(arg_id.name) orelse self.typeOfIdentifier(arg);
                                const narrowed = if (self.typeIsAnyLike(current) and
                                    (self.predicateTargetNodeIsBareName(pred.target_node, "Object") or
                                        self.predicateTargetNodeIsBareName(pred.target_node, "Function")))
                                    current
                                else
                                    try self.narrowTypeByPredicate(current, target);
                                try self.recordNarrow(arg_id.name, narrowed);
                            } else {
                                const current = self.lookupNarrow(arg_id.name) orelse self.typeOfIdentifier(arg);
                                const narrowed = self.subtractTypeByPredicate(current, target) catch current;
                                try self.recordNarrow(arg_id.name, narrowed);
                            }
                            return;
                        }
                    }
                }
            }
        }
        if (self.hir.kindOf(cond) == .assignment) {
            const a = hir_mod.assignmentOf(self.hir, cond);
            const is_logical_assignment = a.op == .logical_or or
                a.op == .logical_and or
                a.op == .nullish_coalesce;
            if (is_logical_assignment and self.hir.kindOf(a.target) == .identifier) {
                const target_id = hir_mod.identifierOf(self.hir, a.target);
                var result_t = self.hir.typeOf(cond);
                if (result_t == types.Primitive.none) result_t = try self.checkExpression(cond);
                const narrowed = if (when_true)
                    self.subtractNullUndefined(result_t) catch result_t
                else
                    try self.logicalAndFalsyType(result_t);
                if (narrowed != types.Primitive.none) try self.recordNarrow(target_id.name, narrowed);
                if (when_true and a.op == .logical_and) {
                    try self.applyTypeGuard(a.value, true);
                }
                return;
            }
        }
        // Bare-identifier truthiness narrowing: `if (x)` / `!x`.
        // Truthy branches remove nullish constituents; falsy branches use
        // the logical-expression partitioner so broad primitives become
        // their representable falsy units (`boolean` -> `false`, etc.).
        if (self.hir.kindOf(cond) == .identifier) {
            const id = hir_mod.identifierOf(self.hir, cond);
            const declared_current = self.lookupNarrow(id.name) orelse self.typeOfIdentifier(cond);
            const current = if (self.identifierIsUntypedUninitializedVar(cond))
                (try self.enclosingLoopAssignmentFlowType(cond, id.name, declared_current)) orelse declared_current
            else
                declared_current;
            const narrowed = if (when_true)
                if (current == types.Primitive.unknown)
                    try self.unknownEmptyObjectType()
                else
                    self.subtractNullUndefined(current) catch current
            else
                try self.logicalAndFalsyType(current);
            if (narrowed != current) try self.recordNarrow(id.name, narrowed);
            return;
        }
        if (self.hir.kindOf(cond) == .member_access) {
            try self.applyTruthyMemberValueGuard(cond, when_true);
            try self.applyTruthyDiscriminantGuard(cond, when_true);
            return;
        }
        if (self.hir.kindOf(cond) == .logical_op) {
            const l = hir_mod.logicalOf(self.hir, cond);
            switch (l.op) {
                .@"and" => {
                    if (when_true) {
                        try self.applyTypeGuard(l.lhs, true);
                        try self.applyTypeGuard(l.rhs, true);
                    } else if (try self.applyFalseAndTypeofChain(l.lhs, l.rhs)) {
                        return;
                    } else if (try self.applyFalseAndEqualityChain(l.lhs, l.rhs)) {
                        return;
                    }
                    return;
                },
                .@"or" => {
                    if (when_true) {
                        if (try self.applyTrueOrTypeofChain(l.lhs, l.rhs)) return;
                        if (try self.applyTrueOrEqualityChain(l.lhs, l.rhs)) return;
                        if (try self.applyTrueOrPredicateCallChain(l.lhs, l.rhs)) return;
                        try self.applyTrueOrBranchJoin(l.lhs, l.rhs);
                    } else {
                        try self.applyTypeGuard(l.lhs, false);
                        try self.applyTypeGuard(l.rhs, false);
                    }
                    return;
                },
                .nullish => return,
            }
        }
        // Same shape but via element_access with a string-literal
        // index: `if (obj["x"])` / `obj["x"] && rhs`. The
        // (obj_name, prop_name) MemberKey is identical to the dot
        // form, so any later `obj.x` access inside the branch picks
        // up the same narrow ÃÂ¢ÃÂÃÂ and vice versa.
        if (self.hir.kindOf(cond) == .element_access and when_true) {
            const e = hir_mod.elementOf(self.hir, cond);
            if (self.hir.kindOf(e.object) == .identifier and
                self.hir.kindOf(e.index) == .literal_string)
            {
                const obj_id = hir_mod.identifierOf(self.hir, e.object);
                const lit = hir_mod.literalStringOf(self.hir, e.index);
                const key: MemberKey = .{ .obj_name = obj_id.name, .prop_name = lit.value };
                const obj_t = self.lookupNarrow(obj_id.name) orelse self.typeOfIdentifier(e.object);
                const looked_up = (try self.lookupObjectMember(obj_t, lit.value));
                var static_t = looked_up orelse types.Primitive.none;
                if (static_t != types.Primitive.none and
                    self.strict_flags.strict_null_checks and
                    self.objectMemberAccessIsOptional(obj_t, lit.value))
                {
                    static_t = self.unionWithUndefined(static_t) catch static_t;
                }
                const current = self.lookupMemberNarrow(key) orelse static_t;
                if (current != types.Primitive.none) {
                    const narrowed = self.subtractNullUndefined(current) catch current;
                    if (narrowed != current) try self.recordMemberNarrow(key, narrowed);
                }
                return;
            }
        }
        if (self.hir.kindOf(cond) == .unary_op) {
            const u = hir_mod.unaryOf(self.hir, cond);
            if (u.op == .not) return self.applyTypeGuard(u.operand, !when_true);
        }
        if (self.hir.kindOf(cond) != .binary_op) return;
        const b = hir_mod.binopOf(self.hir, cond);

        if (b.op == .instanceof and self.nodeIsThisReference(b.lhs)) {
            const target = (try self.directInstanceofTargetType(b.rhs)) orelse return;
            const this_id = self.string_interner.intern("this") catch return error.OutOfMemory;
            const current = self.currentThisType() orelse (try self.checkExpression(b.lhs));
            const narrowed = if (when_true)
                try self.narrowTypeByDirectInstanceof(current, target)
            else if (self.instanceofFalseBranchPreservesClassUnion(current, target))
                current
            else
                self.subtractTypeByDirectInstanceof(current, target) catch current;
            try self.recordNarrow(this_id, narrowed);
            return;
        }

        // `x instanceof Foo` narrows through the RHS's effective instance
        // type: Symbol.hasInstance predicate, prototype, construct return,
        // or named class instance, in that order.
        if (b.op == .instanceof and self.hir.kindOf(b.lhs) == .identifier) {
            const id = hir_mod.identifierOf(self.hir, b.lhs);
            const direct_target = try self.directInstanceofTargetType(b.rhs);
            const target = direct_target orelse types.Primitive.object_t;
            var rhs_is_array = false;
            if (self.hir.kindOf(b.rhs) == .identifier) {
                const rhs_id = hir_mod.identifierOf(self.hir, b.rhs);
                const rhs_name = self.string_interner.get(rhs_id.name);
                rhs_is_array = std.mem.eql(u8, rhs_name, "Array") or
                    std.mem.eql(u8, rhs_name, "ReadonlyArray");
            }
            const current = self.lookupNarrow(id.name) orelse self.typeOfIdentifier(b.lhs);
            // `x instanceof Array` ÃÂ¢ÃÂÃÂ narrow union to its array
            // constituents (and the false branch keeps non-array
            // constituents). Falls through to the object-predicate
            // path when no array constituents are present so the
            // existing partitioning behavior applies.
            if (rhs_is_array) {
                const cur_flags = self.interner.pool.flagsOf(current);
                if (cur_flags.is_union) {
                    var kept: std.ArrayListUnmanaged(TypeId) = .empty;
                    defer kept.deinit(self.gpa);
                    var subtracted: std.ArrayListUnmanaged(TypeId) = .empty;
                    defer subtracted.deinit(self.gpa);
                    for (self.interner.unionMembers(current)) |member| {
                        const elem = self.interner.objectNumberIndex(member);
                        if (elem != types.Primitive.none) {
                            try kept.append(self.gpa, member);
                        } else {
                            try subtracted.append(self.gpa, member);
                        }
                    }
                    if (when_true and kept.items.len > 0) {
                        const narrowed = if (kept.items.len == 1)
                            kept.items[0]
                        else
                            self.interner.internUnion(kept.items) catch current;
                        try self.recordNarrow(id.name, narrowed);
                        return;
                    } else if (!when_true and subtracted.items.len > 0 and kept.items.len > 0) {
                        const narrowed = if (subtracted.items.len == 1)
                            subtracted.items[0]
                        else
                            self.interner.internUnion(subtracted.items) catch current;
                        try self.recordNarrow(id.name, narrowed);
                        return;
                    }
                } else if (when_true and self.interner.objectNumberIndex(current) != types.Primitive.none) {
                    // Already an array ÃÂ¢ÃÂÃÂ keep as-is.
                    try self.recordNarrow(id.name, current);
                    return;
                }
            }
            // `x instanceof Function` and `x instanceof Object` are
            // structurally too loose to refine `any` ÃÂ¢ÃÂÃÂ every callable
            // / object value matches, and tsc deliberately leaves
            // `any` as `any` so subsequent `.prop` / `()` accesses
            // stay tolerated. Mirrors `narrowFromAnyWithInstanceof.ts`
            // where the `Function` / `Object` branches keep `x.prop`
            // and `x(args)` legal.
            if (self.typeIsAnyLike(current) and self.hir.kindOf(b.rhs) == .identifier) {
                const rhs_id = hir_mod.identifierOf(self.hir, b.rhs);
                const rhs_name = self.string_interner.get(rhs_id.name);
                if (std.mem.eql(u8, rhs_name, "Function") or std.mem.eql(u8, rhs_name, "Object")) {
                    try self.recordNarrow(id.name, current);
                    return;
                }
            }
            if (direct_target != null) {
                if (self.typeIsAnyLike(target)) return;
                if (when_true) {
                    if (try self.declaredGenericInstanceofConstituent(b.lhs, b.rhs, target)) |declared_member| {
                        try self.recordNarrow(id.name, declared_member);
                        return;
                    }
                    const narrowed = try self.narrowTypeByDirectInstanceof(current, target);
                    try self.recordNarrow(id.name, narrowed);
                } else {
                    const narrowed = if (self.instanceofFalseBranchPreservesClassUnion(current, target))
                        current
                    else
                        self.subtractTypeByDirectInstanceof(current, target) catch current;
                    try self.recordNarrow(id.name, narrowed);
                }
                return;
            }
            if (when_true) {
                const narrowed = self.narrowTypeByPredicate(current, target) catch target;
                try self.recordNarrow(id.name, narrowed);
            } else {
                const narrowed = self.subtractTypeByPredicate(current, target) catch current;
                try self.recordNarrow(id.name, narrowed);
            }
            return;
        }

        // `"foo" in x` narrows `x` to the variants of its union that
        // declare `foo`. Identifier-rooted member paths participate too,
        // so `"foo" in x.inner.value` narrows that stable reference in
        // the branch. The else branch keeps variants without the member.
        if (b.op == .in and self.nodeIsNarrowableReference(b.rhs)) {
            const property_name = (try self.staticStringValue(b.lhs)) orelse return;
            switch (self.hir.kindOf(b.rhs)) {
                .identifier => {
                    const rhs_id = hir_mod.identifierOf(self.hir, b.rhs);
                    const current = self.lookupNarrow(rhs_id.name) orelse self.typeOfIdentifier(b.rhs);
                    const narrowed = self.narrowByPropertyPresence(current, property_name, when_true) catch current;
                    if (narrowed != current) try self.recordNarrow(rhs_id.name, narrowed);
                },
                .member_access => {
                    const key = self.identifierRootedMemberKey(b.rhs) orelse return;
                    var current = self.lookupMemberNarrow(key) orelse self.hir.typeOf(b.rhs);
                    if (current == types.Primitive.none) current = try self.checkExpression(b.rhs);
                    const narrowed = self.narrowByPropertyPresence(current, property_name, when_true) catch current;
                    if (narrowed != current) try self.recordMemberNarrow(key, narrowed);
                },
                else => unreachable,
            }
            return;
        }

        const equality_op = b.op == .eq_strict or b.op == .neq_strict or b.op == .eq or b.op == .neq;
        if (!equality_op) return;
        // `positive` = "this branch represents the equality
        // matching" (i.e. `===` in then, `!==` in else).
        const positive = (b.op == .eq_strict or b.op == .eq) == when_true;
        if (try self.applyAssignmentNullishEqualityGuard(b.lhs, b.rhs, b.op, positive)) return;
        if (try self.applyAssignmentNullishEqualityGuard(b.rhs, b.lhs, b.op, positive)) return;

        // Discriminated union narrowing: `x.kind === "circle"`.
        // LHS is a member access, RHS is a literal. We walk the
        // member access's object's static type ÃÂ¢ÃÂÃÂ if it's a union of
        // object types, keep the variants whose discriminant prop's
        // type matches the RHS literal.
        if (self.hir.kindOf(b.lhs) == .member_access) {
            if (try self.expressionNarrowLiteralType(b.rhs)) |rhs_lit_t| {
                const optional_undefined_matches = rhs_lit_t == types.Primitive.undefined_t or
                    ((b.op == .eq or b.op == .neq) and self.nodeIsNullLiteralish(b.rhs));
                try self.applyDiscriminatedNarrowWithLiteralType(b.lhs, rhs_lit_t, positive, optional_undefined_matches);
            }
            // Don't return ÃÂ¢ÃÂÃÂ fall through so other guards still try
            // to match (rare overlap, but keeps the logic
            // additive).
        }
        // Aliased-discriminant narrowing: `const t = obj.kind; if (t === "a")`
        // (and the reversed `if ("a" === t)`). When one operand is an
        // identifier bound to a discriminant property of a reference, narrow
        // the *referenced object* through the recorded alias rather than the
        // alias variable. Mirrors `controlFlowAliasing2`.
        {
            const alias_id: ?hir_mod.StringId = if (self.hir.kindOf(b.lhs) == .identifier)
                hir_mod.identifierOf(self.hir, b.lhs).name
            else if (self.hir.kindOf(b.rhs) == .identifier)
                hir_mod.identifierOf(self.hir, b.rhs).name
            else
                null;
            const lit_operand: NodeId = if (self.hir.kindOf(b.lhs) == .identifier) b.rhs else b.lhs;
            if (alias_id) |aid| {
                if (self.disc_aliases.get(aid)) |alias| {
                    if (try self.expressionNarrowLiteralType(lit_operand)) |lit_t| {
                        try self.applyDiscriminatedNarrowByObjectAndProp(alias.object, alias.prop, lit_t, positive);
                    }
                    // Fall through so the alias variable itself still narrows.
                }
            }
        }
        // `typeof x === "kind"` and the operand-order-independent
        // `"kind" === typeof x` share the same narrowing semantics.
        if (self.hir.kindOf(b.lhs) == .unary_op) {
            const u = hir_mod.unaryOf(self.hir, b.lhs);
            if (u.op == .typeof and try self.applyTypeofExpressionGuard(u.operand, b.rhs, positive)) return;
        }
        if (self.hir.kindOf(b.rhs) == .unary_op) {
            const u = hir_mod.unaryOf(self.hir, b.rhs);
            if (u.op == .typeof and try self.applyTypeofExpressionGuard(u.operand, b.lhs, positive)) return;
        }
        if (try self.applyUnknownEqualityGuard(b.lhs, b.rhs, b.op, positive)) return;
        if (try self.applyUnknownEqualityGuard(b.rhs, b.lhs, b.op, positive)) return;
        // X === <literal> / X !== <literal> ÃÂ¢ÃÂÃÂ narrow X to the
        // literal type in the positive branch, subtract it in the
        // negative branch. Covers `s === "hello"`, `n === 42`,
        // `b === true`, `x === 42n`, `x === -42n` (parsed as
        // `unary_op(neg, literal_bigint(42))`). Discriminated-union
        // narrowing above handles the member-access case
        // (`x.kind === "circle"`); this branch handles the
        // bare-identifier case.
        const rhs_is_neg_bigint = blk: {
            if (self.hir.kindOf(b.rhs) != .unary_op) break :blk false;
            const u = hir_mod.unaryOf(self.hir, b.rhs);
            break :blk u.op == .neg and self.hir.kindOf(u.operand) == .literal_bigint;
        };
        if (self.hir.kindOf(b.lhs) == .identifier and
            ((try self.expressionNarrowLiteralType(b.rhs)) != null or
                self.hir.kindOf(b.rhs) == .literal_bigint or
                rhs_is_neg_bigint))
        {
            const id = hir_mod.identifierOf(self.hir, b.lhs);
            const lit_t: TypeId = blk: {
                if (rhs_is_neg_bigint) {
                    const u = hir_mod.unaryOf(self.hir, b.rhs);
                    const lit = hir_mod.literalBigIntOf(self.hir, u.operand);
                    const digits_str = self.string_interner.get(lit.digits);
                    // Build "-<digits>" so the rendered literal is
                    // `-<digits>n` and equality of TypeIds tracks
                    // sign + magnitude.
                    var buf: [64]u8 = undefined;
                    if (digits_str.len + 1 > buf.len) return;
                    buf[0] = '-';
                    @memcpy(buf[1 .. 1 + digits_str.len], digits_str);
                    const neg_digits_id = self.string_interner.intern(buf[0 .. 1 + digits_str.len]) catch return;
                    break :blk self.interner.internBigIntLiteral(neg_digits_id) catch return;
                }
                if (try self.expressionNarrowLiteralType(b.rhs)) |lit| break :blk lit;
                switch (self.hir.kindOf(b.rhs)) {
                    .literal_bigint => {
                        const lit = hir_mod.literalBigIntOf(self.hir, b.rhs);
                        break :blk self.interner.internBigIntLiteral(lit.digits) catch return;
                    },
                    else => unreachable,
                }
            };
            const current = self.lookupNarrow(id.name) orelse self.typeOfIdentifier(b.lhs);
            if (positive) {
                try self.recordNarrow(id.name, try self.narrowTypeByPredicate(current, lit_t));
            } else {
                const narrowed = self.subtractTypeByPredicate(current, lit_t) catch current;
                try self.recordNarrow(id.name, narrowed);
            }
            return;
        }
        // X === null / X !== null / X == null / X != null
        if (self.hir.kindOf(b.lhs) == .identifier and
            self.nodeIsNullLiteralish(b.rhs))
        {
            const id = hir_mod.identifierOf(self.hir, b.lhs);
            if (positive) {
                const narrowed = if (b.op == .eq)
                    try self.nullUndefinedUnionType()
                else
                    types.Primitive.null_t;
                try self.recordNarrow(id.name, narrowed);
            } else {
                // X !== null in then-branch ÃÂ¢ÃÂÃÂ subtract null from X's
                // current static type. If X was `string | null`, the
                // narrowed type is `string`. If X was just `null`,
                // the narrowed type is `never` (unreachable).
                const current = self.lookupNarrow(id.name) orelse self.typeOfIdentifier(b.lhs);
                const without_null = if (current == types.Primitive.unknown)
                    try self.unknownEmptyObjectType()
                else
                    self.subtractType(current, types.Primitive.null_t) catch current;
                const narrowed = if (b.op == .eq or b.op == .neq)
                    self.subtractType(without_null, types.Primitive.undefined_t) catch without_null
                else
                    without_null;
                try self.recordNarrow(id.name, narrowed);
            }
            return;
        }
        if (self.hir.kindOf(b.rhs) == .identifier and
            self.nodeIsNullLiteralish(b.lhs))
        {
            const id = hir_mod.identifierOf(self.hir, b.rhs);
            if (positive) {
                const narrowed = if (b.op == .eq)
                    try self.nullUndefinedUnionType()
                else
                    types.Primitive.null_t;
                try self.recordNarrow(id.name, narrowed);
            } else {
                const current = self.lookupNarrow(id.name) orelse self.typeOfIdentifier(b.rhs);
                const without_null = if (current == types.Primitive.unknown)
                    try self.unknownEmptyObjectType()
                else
                    self.subtractType(current, types.Primitive.null_t) catch current;
                const narrowed = if (b.op == .eq or b.op == .neq)
                    self.subtractType(without_null, types.Primitive.undefined_t) catch without_null
                else
                    without_null;
                try self.recordNarrow(id.name, narrowed);
            }
            return;
        }
        // X === undefined / X !== undefined / X == undefined / X != undefined (literal_undefined +
        // identifier 'undefined' both occur in source code).
        if (self.hir.kindOf(b.lhs) == .identifier and
            self.nodeIsUndefinedLiteralish(b.rhs))
        {
            const lhs = hir_mod.identifierOf(self.hir, b.lhs);
            if (positive) {
                const narrowed = if (b.op == .eq)
                    try self.nullUndefinedUnionType()
                else
                    types.Primitive.undefined_t;
                try self.recordNarrow(lhs.name, narrowed);
            } else {
                const current = self.lookupNarrow(lhs.name) orelse self.typeOfIdentifier(b.lhs);
                const without_undefined = if (current == types.Primitive.unknown)
                    try self.unknownEmptyObjectType()
                else
                    self.subtractType(current, types.Primitive.undefined_t) catch current;
                const narrowed = if (b.op == .eq or b.op == .neq)
                    self.subtractType(without_undefined, types.Primitive.null_t) catch without_undefined
                else
                    without_undefined;
                try self.recordNarrow(lhs.name, narrowed);
            }
            return;
        }
        if (self.hir.kindOf(b.rhs) == .identifier and
            self.nodeIsUndefinedLiteralish(b.lhs))
        {
            const rhs = hir_mod.identifierOf(self.hir, b.rhs);
            if (positive) {
                const narrowed = if (b.op == .eq)
                    try self.nullUndefinedUnionType()
                else
                    types.Primitive.undefined_t;
                try self.recordNarrow(rhs.name, narrowed);
            } else {
                const current = self.lookupNarrow(rhs.name) orelse self.typeOfIdentifier(b.rhs);
                const without_undefined = if (current == types.Primitive.unknown)
                    try self.unknownEmptyObjectType()
                else
                    self.subtractType(current, types.Primitive.undefined_t) catch current;
                const narrowed = if (b.op == .eq or b.op == .neq)
                    self.subtractType(without_undefined, types.Primitive.null_t) catch without_undefined
                else
                    without_undefined;
                try self.recordNarrow(rhs.name, narrowed);
            }
            return;
        }

        // Member-access narrowing on an identifier-rooted access:
        //   obj.x === null / obj.x !== null
        //   obj.x === undefined / obj.x !== undefined
        //   obj.x === <literal> / obj.x !== <literal>
        // The narrow is keyed by `(obj_name, prop_name)` so the
        // `member_access` typing path sees it inside the branch.
        if (self.hir.kindOf(b.lhs) == .member_access) {
            const m = hir_mod.memberOf(self.hir, b.lhs);
            if (self.hir.kindOf(m.object) == .identifier) {
                const obj_id = hir_mod.identifierOf(self.hir, m.object);
                const key: MemberKey = .{ .obj_name = obj_id.name, .prop_name = m.name };
                // RHS == null
                if (self.hir.kindOf(b.rhs) == .literal_null) {
                    const obj_static = self.lookupNarrow(obj_id.name) orelse self.typeOfIdentifier(m.object);
                    if (obj_static < self.interner.pool.typeCount()) {
                        const obj_flags = self.interner.pool.flagsOf(obj_static);
                        if (obj_flags.is_union or obj_flags.is_intersection) {
                            try self.applyDiscriminatedNarrowByType(
                                obj_id.name,
                                obj_static,
                                m.name,
                                types.Primitive.null_t,
                                positive,
                            );
                        }
                    }
                    if (positive) {
                        try self.recordMemberNarrow(key, types.Primitive.null_t);
                    } else {
                        const obj_t = self.typeOfIdentifier(m.object);
                        const current = self.lookupMemberNarrow(key) orelse
                            (self.interner.objectMember(obj_t, m.name) orelse types.Primitive.any);
                        const narrowed = self.subtractType(current, types.Primitive.null_t) catch current;
                        try self.recordMemberNarrow(key, narrowed);
                    }
                    return;
                }
                // RHS == identifier 'undefined'
                if (self.hir.kindOf(b.rhs) == .identifier) {
                    const rhs2 = hir_mod.identifierOf(self.hir, b.rhs);
                    const rhs2_name = self.string_interner.get(rhs2.name);
                    if (std.mem.eql(u8, rhs2_name, "undefined")) {
                        const obj_static = self.lookupNarrow(obj_id.name) orelse self.typeOfIdentifier(m.object);
                        try self.applyDiscriminatedNarrowByType(obj_id.name, obj_static, m.name, types.Primitive.undefined_t, positive);
                        if (positive) {
                            try self.recordMemberNarrow(key, types.Primitive.undefined_t);
                        } else {
                            const obj_t = self.typeOfIdentifier(m.object);
                            const current = self.lookupMemberNarrow(key) orelse
                                (self.interner.objectMember(obj_t, m.name) orelse types.Primitive.any);
                            const narrowed = self.subtractType(current, types.Primitive.undefined_t) catch current;
                            try self.recordMemberNarrow(key, narrowed);
                        }
                        return;
                    }
                }
                // RHS == primitive literal (string/number/bool).
                // The discriminated-union path above narrows the
                // whole object when its type is a union; this
                // records a property-level narrow so non-union
                // object roots also see the literal type.
                if (try self.expressionNarrowLiteralType(b.rhs)) |lit_t| {
                    if (positive) {
                        try self.recordMemberNarrow(key, lit_t);
                    } else {
                        const obj_t = self.typeOfIdentifier(m.object);
                        const current = self.lookupMemberNarrow(key) orelse
                            (self.interner.objectMember(obj_t, m.name) orelse types.Primitive.any);
                        const narrowed = self.subtractType(current, lit_t) catch current;
                        try self.recordMemberNarrow(key, narrowed);
                    }
                    return;
                }
            }
        }
    }

    fn enclosingLoopAssignmentFlowType(
        self: *Checker,
        node: NodeId,
        name: hir_mod.StringId,
        initial: TypeId,
    ) CheckError!?TypeId {
        const containing_function = self.enclosingFunctionLike(node);
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const kind = self.hir.kindOf(cur);
            if (kind != .for_stmt and kind != .for_in_stmt and kind != .for_of_stmt and
                kind != .while_stmt and kind != .do_while_stmt)
            {
                continue;
            }
            const loop_span = self.hir.spanOf(cur);
            var flow = initial;
            var found = false;
            var candidate: NodeId = 0;
            while (candidate < self.hir.nodeCount()) : (candidate += 1) {
                if (self.hir.kindOf(candidate) != .assignment) continue;
                const span = self.hir.spanOf(candidate);
                if (span.start < loop_span.start or span.end > loop_span.end) continue;
                if (self.enclosingFunctionLike(candidate) != containing_function) continue;
                const assignment = hir_mod.assignmentOf(self.hir, candidate);
                if (assignment.target == hir_mod.none_node_id or
                    self.hir.kindOf(assignment.target) != .identifier)
                {
                    continue;
                }
                if (hir_mod.identifierOf(self.hir, assignment.target).name != name) continue;
                var value_t = self.hir.typeOf(assignment.value);
                if (value_t == types.Primitive.none) value_t = try self.checkExpression(assignment.value);
                if (value_t == types.Primitive.any or flow == types.Primitive.any) return types.Primitive.any;
                if (value_t != flow) flow = self.interner.internUnion(&.{ flow, value_t }) catch return error.OutOfMemory;
                found = true;
            }
            return if (found) flow else null;
        }
        return null;
    }

    fn typeofObjectLikePositiveBranchIsNever(self: *Checker, current: TypeId, lit_str: []const u8) bool {
        if (std.mem.eql(u8, lit_str, "object") or std.mem.eql(u8, lit_str, "function")) return false;
        if (current == types.Primitive.object_t) return true;
        if (current >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(current);
        // A union is narrowed member-by-member (narrowTypeByPredicate), never
        // collapsed wholesale here. Guard against a union that OR-s in an
        // `is_intersection`/`is_object_type` flag from a constituent — e.g.
        // `Color | string`, whose numeric-enum member is the nominal
        // intersection `number & { __enum:Color }` — which would otherwise
        // misfire this object-like-never shortcut and drop the whole union to
        // `never`. Pins `TypeGuardWithEnumUnion`.
        if (flags.is_union) return false;
        return flags.is_object_type or flags.is_signature or flags.is_tuple or flags.is_intersection;
    }

    fn applyTypeofPropertyGuard(self: *Checker, operand: NodeId, rhs: NodeId, positive: bool) CheckError!bool {
        const type_name = (try self.staticStringValue(rhs)) orelse return false;
        const lit_str = self.string_interner.get(type_name);
        const narrowed = typeOfTypeofString(lit_str) orelse return false;
        const target = try self.memberNarrowTargetFromAccess(operand) orelse return false;
        const current = self.lookupMemberNarrow(target.key) orelse target.current;
        if (current == types.Primitive.none) return false;
        const next = if (positive)
            narrowed
        else
            (self.subtractType(current, narrowed) catch current);
        try self.recordMemberNarrow(target.key, next);
        return true;
    }

    const MemberNarrowTarget = struct {
        key: MemberKey,
        current: TypeId,
    };

    fn memberNarrowTargetFromAccess(self: *Checker, access: NodeId) CheckError!?MemberNarrowTarget {
        switch (self.hir.kindOf(access)) {
            .member_access => {
                const m = hir_mod.memberOf(self.hir, access);
                if (self.hir.kindOf(m.object) != .identifier) return null;
                const obj_id = hir_mod.identifierOf(self.hir, m.object);
                const key: MemberKey = .{ .obj_name = obj_id.name, .prop_name = m.name };
                const obj_t = self.lookupNarrow(obj_id.name) orelse self.typeOfIdentifier(m.object);
                const current = (try self.lookupObjectMember(obj_t, m.name)) orelse self.hir.typeOf(access);
                return .{ .key = key, .current = current };
            },
            .element_access => {
                const e = hir_mod.elementOf(self.hir, access);
                if (self.hir.kindOf(e.object) != .identifier) return null;
                const prop_name = (try self.staticStringValue(e.index)) orelse return null;
                const obj_id = hir_mod.identifierOf(self.hir, e.object);
                const key: MemberKey = .{ .obj_name = obj_id.name, .prop_name = prop_name };
                const obj_t = self.lookupNarrow(obj_id.name) orelse self.typeOfIdentifier(e.object);
                const current = (try self.lookupObjectMember(obj_t, prop_name)) orelse self.hir.typeOf(access);
                return .{ .key = key, .current = current };
            },
            else => return null,
        }
    }

    fn staticStringValue(self: *Checker, node: NodeId) CheckError!?hir_mod.StringId {
        return switch (self.hir.kindOf(node)) {
            .literal_string => hir_mod.literalStringOf(self.hir, node).value,
            .template_literal => try self.templateLiteralConcreteString(node),
            else => null,
        };
    }

    /// Discriminated-union narrowing. `lhs` is a member access
    /// `obj.disc`; `rhs_lit` is the literal we're comparing against.
    /// If `obj` is a union of object types and one of its members'
    /// `disc` field matches `rhs_lit`, we narrow `obj` to that member.
    fn applyDiscriminatedNarrow(self: *Checker, lhs: NodeId, rhs_lit: NodeId, positive: bool) !void {
        const lit_t = (try self.expressionNarrowLiteralType(rhs_lit)) orelse return;
        try self.applyDiscriminatedNarrowWithLiteralType(lhs, lit_t, positive, lit_t == types.Primitive.undefined_t);
    }

    fn applyDiscriminatedNarrowWithLiteralType(
        self: *Checker,
        lhs: NodeId,
        lit_t: TypeId,
        positive: bool,
        optional_undefined_matches: bool,
    ) !void {
        if (!positive and self.expressionIsOptionalChain(lhs)) {
            try self.applyNegativeOptionalDiscriminatedNarrow(lhs, lit_t, optional_undefined_matches);
            return;
        }
        const m = hir_mod.memberOf(self.hir, lhs);
        try self.applyDiscriminatedNarrowByObjectAndProp(m.object, m.name, lit_t, positive);
    }

    fn applyNegativeOptionalDiscriminatedNarrow(
        self: *Checker,
        lhs: NodeId,
        lit_t: TypeId,
        optional_undefined_matches: bool,
    ) CheckError!void {
        const m = hir_mod.memberOf(self.hir, lhs);
        switch (self.hir.kindOf(m.object)) {
            .member_access => {
                const key = self.identifierRootedMemberKey(m.object) orelse return;
                const static_t = (try self.identifierRootedMemberStaticType(m.object)) orelse return;
                const narrowed = try self.negativeOptionalDiscriminatedNarrowResult(static_t, m.name, lit_t, optional_undefined_matches);
                if (narrowed != static_t) try self.recordMemberNarrow(key, narrowed);
            },
            .identifier => {
                const obj_id = hir_mod.identifierOf(self.hir, m.object);
                const static_t = self.typeOfIdentifier(m.object);
                const narrowed = try self.negativeOptionalDiscriminatedNarrowResult(static_t, m.name, lit_t, optional_undefined_matches);
                if (narrowed != static_t) try self.recordNarrow(obj_id.name, narrowed);
            },
            else => {},
        }
    }

    fn negativeOptionalDiscriminatedNarrowResult(
        self: *Checker,
        static_t: TypeId,
        prop_name: hir_mod.StringId,
        lit_t: TypeId,
        optional_undefined_matches: bool,
    ) CheckError!TypeId {
        if (static_t >= self.interner.pool.typeCount()) return static_t;
        const flags = self.interner.pool.flagsOf(static_t);
        const single_buf = [_]TypeId{static_t};
        const members: []const TypeId = if (flags.is_union)
            self.interner.unionMembers(static_t)
        else
            single_buf[0..];
        var keep: std.ArrayListUnmanaged(TypeId) = .empty;
        defer keep.deinit(self.gpa);
        for (members) |variant| {
            const variant_flags = self.interner.pool.flagsOf(variant);
            if (!variant_flags.is_object_type) {
                // A nullish receiver short-circuits to `undefined`; retain it
                // exactly when that value makes the comparison fail.
                if ((variant_flags.is_null or variant_flags.is_undefined) and !optional_undefined_matches) {
                    try keep.append(self.gpa, variant);
                }
                continue;
            }
            const info = self.interner.objectMemberInfo(variant, prop_name) orelse {
                try keep.append(self.gpa, variant);
                continue;
            };
            var definitely_matches = self.engine.isAssignableTo(info.type, lit_t) catch false;
            if (info.is_optional and !optional_undefined_matches) definitely_matches = false;
            if (!definitely_matches) try keep.append(self.gpa, variant);
        }
        if (keep.items.len == 0) return types.Primitive.never;
        if (keep.items.len == 1) return keep.items[0];
        return self.interner.internUnion(keep.items) catch return error.OutOfMemory;
    }

    /// Narrow a reference `object` by its discriminant property `prop`
    /// matching `lit_t`. `object` is either a bare identifier (narrowed via
    /// the identifier scope) or an identifier-rooted member path such as
    /// `this.test` (narrowed via a MemberKey). Shared by direct
    /// `obj.kind === lit` guards and aliased forms (`const t = obj.kind`).
    fn applyDiscriminatedNarrowByObjectAndProp(
        self: *Checker,
        object: NodeId,
        prop: hir_mod.StringId,
        lit_t: TypeId,
        positive: bool,
    ) CheckError!void {
        switch (self.hir.kindOf(object)) {
            .member_access => {
                const key = self.identifierRootedMemberKey(object) orelse return;
                const static_t = (try self.identifierRootedMemberStaticType(object)) orelse return;
                if (static_t == types.Primitive.never) return;
                const f = self.interner.pool.flagsOf(static_t);
                if (!f.is_union and !f.is_object_type) return;
                if (try self.discriminatedNarrowResult(static_t, prop, lit_t, positive)) |narrowed| {
                    try self.recordMemberNarrow(key, narrowed);
                }
            },
            .identifier => {
                const obj_id = hir_mod.identifierOf(self.hir, object);
                const static_t = self.typeOfIdentifier(object);
                if (static_t == types.Primitive.never) return;
                const f = self.interner.pool.flagsOf(static_t);
                if (!f.is_union and !f.is_object_type) return;
                try self.applyDiscriminatedNarrowByType(obj_id.name, static_t, prop, lit_t, positive);
            },
            else => {},
        }
    }

    /// Record any aliased-discriminant bindings introduced by a `const`/`let`
    /// declaration (`const t = obj.kind` or `const { kind: t } = obj`) so a
    /// later `if (t === lit)` narrows the referenced object. Mirrors
    /// `controlFlowAliasing2`.
    fn recordDiscriminantAliases(self: *Checker, node: NodeId, v: hir_mod.VarDeclPayload) CheckError!void {
        _ = node;
        if (v.init == hir_mod.none_node_id) return;
        // Shape 1: `const t = obj.kind`.
        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier and
            self.hir.kindOf(v.init) == .member_access and self.memberAccessHasNarrowableObject(v.init))
        {
            const m = hir_mod.memberOf(self.hir, v.init);
            const id = hir_mod.identifierOf(self.hir, v.name);
            try self.disc_aliases.put(self.gpa, id.name, .{ .object = m.object, .prop = m.name });
            return;
        }
        // Shape 2: `const { kind: t } = obj` (renamed object-destructuring).
        // Each rename pair is an `is_rename_binding_key` parameter (key in
        // `default_value`) followed by the binding target.
        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .object_pattern and
            self.nodeIsNarrowableReference(v.init))
        {
            const elems = hir_mod.patternElements(self.hir, v.name);
            var i: usize = 0;
            while (i + 1 < elems.len) : (i += 1) {
                if (self.hir.kindOf(elems[i]) != .parameter) continue;
                const kp = hir_mod.parameterOf(self.hir, elems[i]);
                if (!kp.flags.is_rename_binding_key) continue;
                if (kp.default_value == hir_mod.none_node_id or
                    self.hir.kindOf(kp.default_value) != .identifier) continue;
                const key_name = hir_mod.identifierOf(self.hir, kp.default_value).name;
                if (self.hir.kindOf(elems[i + 1]) != .parameter) continue;
                const tp = hir_mod.parameterOf(self.hir, elems[i + 1]);
                if (tp.name == hir_mod.none_node_id or self.hir.kindOf(tp.name) != .identifier) continue;
                const target_name = hir_mod.identifierOf(self.hir, tp.name).name;
                try self.disc_aliases.put(self.gpa, target_name, .{ .object = v.init, .prop = key_name });
            }
        }
    }

    /// True if `node` is a reference whose discriminant can be narrowed — a
    /// bare identifier or an identifier-rooted member path (`this.test`).
    fn nodeIsNarrowableReference(self: *Checker, node: NodeId) bool {
        return switch (self.hir.kindOf(node)) {
            .identifier => true,
            .member_access => self.identifierRootedMemberKey(node) != null,
            else => false,
        };
    }

    /// True if `node` is a member access whose object is itself a
    /// narrowable identifier-rooted reference — a bare identifier or a
    /// `this.<prop>`/`obj.<prop>` path. Decides whether `const t = <node>`
    /// qualifies as an aliased-discriminant source.
    fn memberAccessHasNarrowableObject(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) != .member_access) return false;
        const m = hir_mod.memberOf(self.hir, node);
        return switch (self.hir.kindOf(m.object)) {
            .identifier => true,
            .member_access => self.identifierRootedMemberKey(m.object) != null,
            else => false,
        };
    }

    /// Build the flow key for an identifier-rooted member path. Direct
    /// accesses retain `(ident, prop)`; deeper paths intern the dotted tail,
    /// so `x.outer.prop` becomes `(x, "outer.prop")`. This lets repeated HIR
    /// nodes for the same stable path share a narrow across a branch.
    fn identifierRootedMemberKey(self: *Checker, node: NodeId) ?MemberKey {
        if (self.hir.kindOf(node) != .member_access) return null;
        var segments: [32]hir_mod.StringId = undefined;
        var segment_count: usize = 0;
        var current = node;
        while (self.hir.kindOf(current) == .member_access) {
            if (segment_count == segments.len) return null;
            const member = hir_mod.memberOf(self.hir, current);
            segments[segment_count] = member.name;
            segment_count += 1;
            current = member.object;
        }
        if (self.hir.kindOf(current) != .identifier or segment_count == 0) return null;
        const root_name = hir_mod.identifierOf(self.hir, current).name;
        if (segment_count == 1) return .{ .obj_name = root_name, .prop_name = segments[0] };

        var path_buf: [1024]u8 = undefined;
        var path_len: usize = 0;
        var i = segment_count;
        while (i > 0) {
            i -= 1;
            const segment = self.string_interner.get(segments[i]);
            const separator_len: usize = if (path_len == 0) 0 else 1;
            if (path_len + separator_len + segment.len > path_buf.len) return null;
            if (separator_len != 0) {
                path_buf[path_len] = '.';
                path_len += 1;
            }
            @memcpy(path_buf[path_len .. path_len + segment.len], segment);
            path_len += segment.len;
        }
        const path_name = self.string_interner.intern(path_buf[0..path_len]) catch return null;
        return .{ .obj_name = root_name, .prop_name = path_name };
    }

    /// Static (un-narrowed) member type of an `<ident>.<prop>` reference,
    /// resolved from the base identifier's type, ignoring recorded narrows.
    fn identifierRootedMemberStaticType(self: *Checker, node: NodeId) CheckError!?TypeId {
        const m = hir_mod.memberOf(self.hir, node);
        var base_t = self.hir.typeOf(m.object);
        if (base_t == types.Primitive.none) base_t = try self.checkExpression(m.object);
        if (base_t == types.Primitive.none) return null;
        return self.lookupObjectMember(base_t, m.name) catch null;
    }

    /// Compute the narrowed union/object type for a discriminant match
    /// without recording it (the recording target differs between identifier
    /// and member-path references). Returns null when nothing matches.
    fn discriminatedNarrowResult(
        self: *Checker,
        static_t: TypeId,
        prop_name: hir_mod.StringId,
        lit_t: TypeId,
        positive: bool,
    ) CheckError!?TypeId {
        const flags = self.interner.pool.flagsOf(static_t);
        const single_buf = [_]TypeId{static_t};
        const members: []const TypeId = if (flags.is_union)
            self.interner.unionMembers(static_t)
        else
            single_buf[0..];
        var keep: std.ArrayListUnmanaged(TypeId) = .empty;
        defer keep.deinit(self.gpa);
        for (members) |variant| {
            if (!self.interner.pool.flagsOf(variant).is_object_type) continue;
            const disc_t = self.interner.objectMember(variant, prop_name) orelse continue;
            const matches = try self.discriminantTypeMatchesLiteral(disc_t, lit_t);
            if (matches == positive) try keep.append(self.gpa, variant);
        }
        if (keep.items.len == 0) return types.Primitive.never;
        if (keep.items.len == 1) return keep.items[0];
        return self.interner.internUnion(keep.items) catch null;
    }

    fn applyTruthyDiscriminantGuard(self: *Checker, member_node: NodeId, when_true: bool) !void {
        const m = hir_mod.memberOf(self.hir, member_node);
        const target: DiscriminantTarget = switch (self.hir.kindOf(m.object)) {
            .identifier => blk: {
                const obj_id = hir_mod.identifierOf(self.hir, m.object);
                break :blk .{ .name = obj_id.name, .t = self.typeOfIdentifier(m.object) };
            },
            .assignment => blk: {
                const a = hir_mod.assignmentOf(self.hir, m.object);
                if (a.op != null or self.hir.kindOf(a.target) != .identifier) return;
                const target_id = hir_mod.identifierOf(self.hir, a.target);
                var assigned_t = self.hir.typeOf(m.object);
                if (assigned_t == types.Primitive.none) assigned_t = try self.checkExpression(m.object);
                break :blk .{ .name = target_id.name, .t = assigned_t };
            },
            else => return,
        };
        const narrowed = (try self.narrowUnionByPropertyTruthiness(target.t, m.name, when_true)) orelse return;
        if (narrowed != target.t) try self.recordNarrow(target.name, narrowed);
    }

    fn narrowUnionByPropertyTruthiness(
        self: *Checker,
        union_t: TypeId,
        prop_name: hir_mod.StringId,
        when_true: bool,
    ) CheckError!?TypeId {
        if (union_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(union_t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(union_t) orelse return null;
            if (constraint == union_t) return null;
            return try self.narrowUnionByPropertyTruthiness(constraint, prop_name, when_true);
        }
        if (!flags.is_union) return null;

        const members = try self.gpa.dupe(TypeId, self.interner.unionMembers(union_t));
        defer self.gpa.free(members);
        var kept: std.ArrayListUnmanaged(TypeId) = .empty;
        defer kept.deinit(self.gpa);
        for (members) |variant| {
            var prop_t: TypeId = types.Primitive.unknown;
            if (variant < self.interner.pool.typeCount()) {
                if (self.interner.objectMemberInfo(variant, prop_name)) |info| {
                    prop_t = info.type;
                    if (info.is_optional) prop_t = self.unionWithUndefined(prop_t) catch prop_t;
                } else if (self.namedPropertyIndexType(variant, prop_name)) |index_t| {
                    prop_t = index_t;
                }
            }
            const possible = if (when_true)
                self.logicalTypeCanBeTruthy(prop_t)
            else
                self.logicalTypeCanBeFalsy(prop_t);
            if (possible) try kept.append(self.gpa, variant);
        }
        if (kept.items.len == members.len) return union_t;
        if (kept.items.len == 0) return types.Primitive.never;
        if (kept.items.len == 1) return kept.items[0];
        return self.interner.internUnion(kept.items) catch return error.OutOfMemory;
    }

    fn applyTruthyMemberValueGuard(self: *Checker, member_node: NodeId, when_true: bool) CheckError!void {
        if (!when_true) return;
        const key = self.identifierRootedMemberKey(member_node) orelse return;
        var current = self.lookupMemberNarrow(key) orelse self.hir.typeOf(member_node);
        if (current == types.Primitive.none) current = try self.checkExpression(member_node);
        const narrowed = self.subtractNullUndefined(current) catch current;
        if (narrowed != current) try self.recordMemberNarrow(key, narrowed);
    }

    fn applyDiscriminatedNarrowByType(
        self: *Checker,
        obj_name: hir_mod.StringId,
        static_t: TypeId,
        prop_name: hir_mod.StringId,
        lit_t: TypeId,
        positive: bool,
    ) !void {
        // Treat a single-object narrow as a one-element union so the
        // exhaustion logic below collapses it to `never` when the
        // last remaining variant is also subtracted (the
        // exhaustiveness-marker pattern in switch defaults).
        if (static_t == types.Primitive.never) return;
        const flags = self.interner.pool.flagsOf(static_t);
        const is_union = flags.is_union;
        const is_object = flags.is_object_type;
        const is_intersection = flags.is_intersection;
        if (!is_union and !is_object and !is_intersection) return;
        if (is_intersection) {
            if (try self.narrowIntersectionByDiscriminant(static_t, prop_name, lit_t, positive)) |narrowed| {
                try self.recordNarrow(obj_name, narrowed);
            }
            return;
        }
        const single_buf = [_]TypeId{static_t};
        const members: []const TypeId = if (is_union)
            self.interner.unionMembers(static_t)
        else
            single_buf[0..];
        var keep: std.ArrayListUnmanaged(TypeId) = .empty;
        defer keep.deinit(self.gpa);
        for (members) |variant| {
            if (!self.interner.pool.flagsOf(variant).is_object_type) continue;
            const disc_t = self.interner.objectMember(variant, prop_name) orelse continue;
            // Match: the variant's discriminant is exactly the literal.
            if (try self.discriminantTypeMatchesLiteral(disc_t, lit_t)) {
                if (positive) {
                    try keep.append(self.gpa, variant);
                }
            } else {
                if (!positive) {
                    try keep.append(self.gpa, variant);
                }
            }
        }
        const narrowed: TypeId = if (keep.items.len == 0)
            // Exhausted: every variant was excluded. The discriminant
            // is `never` ÃÂ¢ÃÂÃÂ TS uses this for exhaustiveness checks
            // (e.g. `let x: never = s` in a switch's default branch
            // after every case is covered).
            types.Primitive.never
        else if (keep.items.len == 1)
            keep.items[0]
        else
            self.interner.internUnion(keep.items) catch return;
        try self.recordNarrow(obj_name, narrowed);
    }

    fn narrowIntersectionByDiscriminant(
        self: *Checker,
        static_t: TypeId,
        prop_name: hir_mod.StringId,
        lit_t: TypeId,
        positive: bool,
    ) CheckError!?TypeId {
        if (static_t >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(static_t).is_intersection)
        {
            return null;
        }
        var members_out: std.ArrayListUnmanaged(TypeId) = .empty;
        defer members_out.deinit(self.gpa);
        var changed = false;
        for (self.interner.intersectionMembers(static_t)) |member| {
            if (member >= self.interner.pool.typeCount() or
                !self.interner.pool.flagsOf(member).is_union)
            {
                try members_out.append(self.gpa, member);
                continue;
            }
            const narrowed = try self.narrowUnionByDiscriminant(member, prop_name, lit_t, positive);
            if (narrowed == null) {
                try members_out.append(self.gpa, member);
                continue;
            }
            if (narrowed.? == types.Primitive.never) return types.Primitive.never;
            changed = true;
            try members_out.append(self.gpa, narrowed.?);
        }
        if (!changed) return null;
        if (members_out.items.len == 1) return members_out.items[0];
        return self.interner.internIntersection(members_out.items) catch static_t;
    }

    fn narrowUnionByDiscriminant(
        self: *Checker,
        union_t: TypeId,
        prop_name: hir_mod.StringId,
        lit_t: TypeId,
        positive: bool,
    ) CheckError!?TypeId {
        if (union_t >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(union_t).is_union)
        {
            return null;
        }
        var keep: std.ArrayListUnmanaged(TypeId) = .empty;
        defer keep.deinit(self.gpa);
        var saw_discriminant = false;
        for (self.interner.unionMembers(union_t)) |variant| {
            if (variant >= self.interner.pool.typeCount() or
                !self.interner.pool.flagsOf(variant).is_object_type)
            {
                continue;
            }
            const disc_t = self.interner.objectMember(variant, prop_name) orelse continue;
            saw_discriminant = true;
            const matches = try self.discriminantTypeMatchesLiteral(disc_t, lit_t);
            if (matches == positive) try keep.append(self.gpa, variant);
        }
        if (!saw_discriminant) return null;
        if (keep.items.len == 0) return types.Primitive.never;
        if (keep.items.len == 1) return keep.items[0];
        return self.interner.internUnion(keep.items) catch union_t;
    }

    fn discriminantTypeMatchesLiteral(self: *Checker, disc_t: TypeId, lit_t: TypeId) CheckError!bool {
        if (disc_t == lit_t) return true;
        if (self.engine.isAssignableTo(lit_t, disc_t) catch false) return true;
        if (self.engine.isAssignableTo(disc_t, lit_t) catch false) return true;
        if (lit_t >= types.Primitive.first_dynamic and lit_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(lit_t).is_literal)
        {
            switch (self.interner.literalOf(lit_t)) {
                .string_lit => |sid| return try self.stringLiteralAssignableToType(sid, disc_t),
                else => {},
            }
        }
        return false;
    }

    fn isUnitDiscriminantType(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.null_t or
            t == types.Primitive.undefined_t or
            t == types.Primitive.true_lit or
            t == types.Primitive.false_lit)
        {
            return true;
        }
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        return flags.is_literal and !flags.is_union and !flags.is_intersection;
    }

    fn sharedRequiredUnitDiscriminant(
        self: *Checker,
        members: []const TypeId,
    ) CheckError!?hir_mod.StringId {
        var first_union: TypeId = types.Primitive.none;
        for (members) |member| {
            if (member < self.interner.pool.typeCount() and self.interner.pool.flagsOf(member).is_union) {
                first_union = member;
                break;
            }
        }
        if (first_union == types.Primitive.none) return null;
        const first_variants = try self.gpa.dupe(TypeId, self.interner.unionMembers(first_union));
        defer self.gpa.free(first_variants);
        if (first_variants.len == 0) return null;
        const first_variant = first_variants[0];
        if (first_variant >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(first_variant).is_object_type)
        {
            return null;
        }
        const first_properties = try self.gpa.dupe(types.ObjectMember, self.interner.objectMembers(first_variant));
        defer self.gpa.free(first_properties);
        candidate: for (first_properties) |property| {
            if (property.is_optional or !self.isUnitDiscriminantType(property.type)) continue;
            var union_count: usize = 0;
            for (members) |member| {
                if (member >= self.interner.pool.typeCount() or
                    !self.interner.pool.flagsOf(member).is_union)
                {
                    continue;
                }
                union_count += 1;
                const variants = try self.gpa.dupe(TypeId, self.interner.unionMembers(member));
                defer self.gpa.free(variants);
                for (variants) |variant| {
                    if (variant >= self.interner.pool.typeCount() or
                        !self.interner.pool.flagsOf(variant).is_object_type)
                    {
                        continue :candidate;
                    }
                    const info = self.interner.objectMemberInfo(variant, property.name) orelse continue :candidate;
                    if (info.is_optional or !self.isUnitDiscriminantType(info.type)) continue :candidate;
                }
            }
            if (union_count >= 2) return property.name;
        }
        return null;
    }

    fn reduceIntersectionBySharedUnitDiscriminant(
        self: *Checker,
        members: []const TypeId,
    ) CheckError!?TypeId {
        const prop_name = (try self.sharedRequiredUnitDiscriminant(members)) orelse return null;
        var first_union_index: ?usize = null;
        for (members, 0..) |member, index| {
            if (member < self.interner.pool.typeCount() and self.interner.pool.flagsOf(member).is_union) {
                first_union_index = index;
                break;
            }
        }
        const base_index = first_union_index orelse return null;
        const base_variants = try self.gpa.dupe(TypeId, self.interner.unionMembers(members[base_index]));
        defer self.gpa.free(base_variants);
        var reduced_members: std.ArrayListUnmanaged(TypeId) = .empty;
        defer reduced_members.deinit(self.gpa);

        for (base_variants) |base_variant| {
            const base_info = self.interner.objectMemberInfo(base_variant, prop_name) orelse continue;
            var parts: std.ArrayListUnmanaged(TypeId) = .empty;
            defer parts.deinit(self.gpa);
            try parts.append(self.gpa, base_variant);
            var compatible = true;
            for (members, 0..) |member, index| {
                if (index == base_index) continue;
                if (member >= self.interner.pool.typeCount() or
                    !self.interner.pool.flagsOf(member).is_union)
                {
                    try parts.append(self.gpa, member);
                    continue;
                }
                const variants = try self.gpa.dupe(TypeId, self.interner.unionMembers(member));
                defer self.gpa.free(variants);
                var matches: std.ArrayListUnmanaged(TypeId) = .empty;
                defer matches.deinit(self.gpa);
                for (variants) |variant| {
                    const info = self.interner.objectMemberInfo(variant, prop_name) orelse continue;
                    if (try self.discriminantTypeMatchesLiteral(info.type, base_info.type)) {
                        try matches.append(self.gpa, variant);
                    }
                }
                if (matches.items.len == 0) {
                    compatible = false;
                    break;
                }
                const selected = if (matches.items.len == 1)
                    matches.items[0]
                else
                    self.interner.internUnion(matches.items) catch return error.OutOfMemory;
                try parts.append(self.gpa, selected);
            }
            if (!compatible) continue;
            const reduced = if (parts.items.len == 1)
                parts.items[0]
            else
                self.interner.internIntersection(parts.items) catch return error.OutOfMemory;
            try reduced_members.append(self.gpa, reduced);
        }
        if (reduced_members.items.len == 0) return types.Primitive.never;
        if (reduced_members.items.len == 1) return reduced_members.items[0];
        return self.interner.internUnion(reduced_members.items) catch return error.OutOfMemory;
    }

    fn recordNarrow(self: *Checker, name: hir_mod.StringId, t: TypeId) !void {
        if (self.narrow_scopes.items.len == 0) return;
        var top = &self.narrow_scopes.items[self.narrow_scopes.items.len - 1];
        try top.put(self.gpa, name, t);
    }

    /// Resolve the type of a binding identifier inside a destructuring
    /// pattern. `pattern_node` is the `object_pattern` / `array_pattern`
    /// HIR node that stands in for the parameter or var-decl name.
    /// `container_t` is the lowered type of the parameter / initializer.
    /// `target_name` is the identifier whose type we want.
    ///
    /// For object patterns: looks up `target_name` as a member of
    /// `container_t`. The property's optionality (`a?: number`) shows
    /// up either as an `is_optional` ObjectMember flag or as `T |
    /// undefined` already; if the binding has a default expression,
    /// strip `undefined` from the result so `{ a = 1 }: { a?: T }`
    /// types `a` as `T`.
    ///
    /// For array patterns: looks up the matching tuple element by
    /// position. Optional/rest elements receive the same default
    /// stripping treatment.
    fn typeOfPatternBinding(
        self: *Checker,
        pattern_node: NodeId,
        container_t: TypeId,
        target_name: hir_mod.StringId,
    ) ?TypeId {
        const pk = self.hir.kindOf(pattern_node);
        const elements = hir_mod.patternElements(self.hir, pattern_node);
        if (pk == .object_pattern) {
            for (elements) |e| {
                if (self.hir.kindOf(e) != .parameter) continue;
                const ep = hir_mod.parameterOf(self.hir, e);
                if (ep.name == hir_mod.none_node_id) continue;
                const name_kind = self.hir.kindOf(ep.name);
                if (name_kind == .identifier) {
                    const eid = hir_mod.identifierOf(self.hir, ep.name);
                    if (eid.name != target_name) continue;
                    // Found the binding. Look up the property in
                    // `container_t`. The lowered type for `{ a?: T }`
                    // marks the member optional but stores T directly;
                    // union with `undefined` to reflect callers passing
                    // `{}`.
                    var member_t: TypeId = types.Primitive.any;
                    if (ep.flags.is_computed_binding_key and ep.default_value != hir_mod.none_node_id) {
                        member_t = (self.objectPropertyTypeForComputedKeyNode(container_t, ep.default_value) catch null) orelse types.Primitive.any;
                    } else if (self.interner.objectMemberInfo(container_t, eid.name)) |info| {
                        member_t = info.type;
                        if (info.is_optional) {
                            member_t = self.unionWithUndefined(member_t) catch member_t;
                        }
                    }
                    if (ep.default_value != hir_mod.none_node_id) {
                        member_t = self.subtractType(member_t, types.Primitive.undefined_t) catch member_t;
                    }
                    return member_t;
                }
                if (name_kind == .object_pattern or name_kind == .array_pattern) {
                    var nested_container_t: TypeId = types.Primitive.any;
                    if (self.objectBindingElementKeyName(e, ep.name) catch null) |key_name| {
                        nested_container_t = self.objectPropertyTypeByName(container_t, key_name) orelse types.Primitive.any;
                    }
                    if (self.typeOfPatternBinding(ep.name, nested_container_t, target_name)) |bt| {
                        return bt;
                    }
                }
            }
            return null;
        }
        if (pk == .array_pattern) {
            // Walk elements in order, tracking the tuple index. Rest
            // elements are skipped for v0 (no slice typing).
            const flags = self.interner.pool.flagsOf(container_t);
            var idx: u32 = 0;
            for (elements) |e| {
                if (self.hir.kindOf(e) != .parameter) continue;
                const ep = hir_mod.parameterOf(self.hir, e);
                if (ep.name == hir_mod.none_node_id) continue;
                const name_kind = self.hir.kindOf(ep.name);
                if (name_kind == .object_pattern or name_kind == .array_pattern) {
                    var elem_container_t: TypeId = types.Primitive.any;
                    if (!ep.flags.is_rest) {
                        const union_elem = self.unionTupleElementAccessAt(container_t, @intCast(idx)) catch null;
                        if (union_elem) |access| {
                            elem_container_t = access.value_type;
                        } else if (flags.is_tuple) {
                            const tuple_t = self.tupleElementType(container_t, idx);
                            if (tuple_t != types.Primitive.none) {
                                elem_container_t = tuple_t;
                            } else {
                                const payload = self.interner.pool.tuple_payloads.items[self.interner.pool.payloadOf(container_t)];
                                const elems = self.interner.pool.tuple_element_pool.items[payload.elements_start .. payload.elements_start + payload.elements_len];
                                if (idx < elems.len) elem_container_t = elems[idx].type;
                            }
                        }
                    }
                    if (ep.default_value != hir_mod.none_node_id) {
                        const default_t = if (self.nodeContainsIdentifier(ep.default_value, target_name))
                            types.Primitive.any
                        else
                            self.checkExpression(ep.default_value) catch types.Primitive.any;
                        elem_container_t = if (elem_container_t == types.Primitive.any)
                            default_t
                        else
                            self.destructuringSourceWithDefault(elem_container_t, default_t) catch elem_container_t;
                    }
                    if (self.typeOfPatternBinding(ep.name, elem_container_t, target_name)) |bt| {
                        return bt;
                    }
                    if (!ep.flags.is_rest) idx += 1;
                    continue;
                }
                if (name_kind != .identifier) {
                    if (!ep.flags.is_rest) idx += 1;
                    continue;
                }
                const eid = hir_mod.identifierOf(self.hir, ep.name);
                if (eid.name != target_name) {
                    if (!ep.flags.is_rest) idx += 1;
                    continue;
                }
                if (ep.flags.is_rest) return types.Primitive.any;
                var elem_t: TypeId = types.Primitive.any;
                if (self.unionTupleElementAccessAt(container_t, @intCast(idx)) catch null) |access| {
                    elem_t = access.value_type;
                } else if (flags.is_tuple) {
                    const payload = self.interner.pool.tuple_payloads.items[self.interner.pool.payloadOf(container_t)];
                    const elems = self.interner.pool.tuple_element_pool.items[payload.elements_start .. payload.elements_start + payload.elements_len];
                    if (idx < elems.len) {
                        const te = elems[idx];
                        elem_t = te.type;
                        if (te.is_optional) {
                            elem_t = self.unionWithUndefined(elem_t) catch elem_t;
                        }
                    }
                }
                if (ep.default_value != hir_mod.none_node_id) {
                    const default_t = if (self.nodeContainsIdentifier(ep.default_value, target_name))
                        types.Primitive.any
                    else
                        self.checkExpression(ep.default_value) catch types.Primitive.any;
                    elem_t = self.destructuringSourceWithDefault(elem_t, default_t) catch elem_t;
                }
                return elem_t;
            }
            return null;
        }
        return null;
    }

    fn widenNullishBindingElementType(self: *Checker, source_node: NodeId, elem_t: TypeId) TypeId {
        if (self.strict_flags.strict_null_checks) return elem_t;
        if (source_node != hir_mod.none_node_id) {
            const k = self.hir.kindOf(source_node);
            if (k == .literal_null or k == .literal_undefined) return types.Primitive.any;
        }
        if (elem_t == types.Primitive.null_t or elem_t == types.Primitive.undefined_t) {
            return types.Primitive.any;
        }
        return elem_t;
    }

    fn typeOfPatternBindingFromSource(
        self: *Checker,
        pattern_node: NodeId,
        source_node: NodeId,
        source_t: TypeId,
        target_name: hir_mod.StringId,
    ) CheckError!?TypeId {
        if (pattern_node == hir_mod.none_node_id) return null;
        // Cycle guard: a self-referential destructuring binding re-enters
        // here for the same pattern (via checkExpression on the source →
        // typeOfIdentifier → resolveValueDeclInStmt). Bail to null so the
        // caller falls through to the container-shape resolution path.
        if (self.pattern_binding_source_in_progress.contains(pattern_node)) return null;
        self.pattern_binding_source_in_progress.put(self.gpa, pattern_node, {}) catch {};
        defer _ = self.pattern_binding_source_in_progress.remove(pattern_node);
        const effective_source_t = self.annotatedTupleUnionForIdentifier(source_node) orelse source_t;
        return switch (self.hir.kindOf(pattern_node)) {
            .array_pattern => blk: {
                const source_elements: []const NodeId = if (source_node != hir_mod.none_node_id and self.hir.kindOf(source_node) == .array_literal)
                    hir_mod.arrayLiteralElements(self.hir, source_node)
                else
                    &.{};
                const fallback_elem_t = try self.iterableElementType(effective_source_t);
                for (hir_mod.patternElements(self.hir, pattern_node), 0..) |elem, i| {
                    if (self.hir.kindOf(elem) != .parameter) continue;
                    const p = hir_mod.parameterOf(self.hir, elem);
                    if (p.name == hir_mod.none_node_id) continue;
                    var elem_node: NodeId = hir_mod.none_node_id;
                    var elem_t: TypeId = types.Primitive.any;
                    if (i < source_elements.len and source_elements[i] != hir_mod.none_node_id) {
                        elem_node = source_elements[i];
                        elem_t = self.hir.typeOf(elem_node);
                        if (elem_t == types.Primitive.none and self.nodeContainsIdentifier(elem_node, target_name)) {
                            elem_t = types.Primitive.any;
                        } else if (elem_t == types.Primitive.none and self.hir.kindOf(elem_node) != .identifier) {
                            elem_t = try self.checkExpression(elem_node);
                        }
                    } else if (p.default_value != hir_mod.none_node_id) {
                        elem_node = p.default_value;
                        elem_t = self.hir.typeOf(elem_node);
                        if (elem_t == types.Primitive.none and self.nodeContainsIdentifier(elem_node, target_name)) {
                            elem_t = types.Primitive.any;
                        } else if (elem_t == types.Primitive.none and self.hir.kindOf(elem_node) != .identifier) {
                            elem_t = try self.checkExpression(elem_node);
                        }
                    } else {
                        if (try self.unionTupleElementAccessAt(effective_source_t, i)) |access| {
                            elem_t = access.value_type;
                        } else {
                            const tuple_t = self.tupleElementType(effective_source_t, i);
                            elem_t = if (tuple_t != types.Primitive.none) tuple_t else fallback_elem_t;
                        }
                    }
                    if (p.flags.is_rest) {
                        elem_t = try self.arrayRestSourceType(source_node, i, elem_t, source_t);
                    }
                    elem_t = self.widenNullishBindingElementType(elem_node, elem_t);
                    if (elem_t == types.Primitive.none or elem_t == types.Primitive.any or elem_t == types.Primitive.unknown) continue;
                    switch (self.hir.kindOf(p.name)) {
                        .identifier => if (hir_mod.identifierOf(self.hir, p.name).name == target_name) break :blk elem_t,
                        .array_pattern, .object_pattern => {
                            if (try self.typeOfPatternBindingFromSource(p.name, elem_node, elem_t, target_name)) |bt| break :blk bt;
                        },
                        .assignment => {
                            const a = hir_mod.assignmentOf(self.hir, p.name);
                            if (try self.typeOfPatternBindingFromSource(a.target, elem_node, elem_t, target_name)) |bt| break :blk bt;
                        },
                        else => {},
                    }
                }
                break :blk null;
            },
            .array_literal => blk: {
                const target_elements = hir_mod.arrayLiteralElements(self.hir, pattern_node);
                const source_elements: []const NodeId = if (source_node != hir_mod.none_node_id and self.hir.kindOf(source_node) == .array_literal)
                    hir_mod.arrayLiteralElements(self.hir, source_node)
                else
                    &.{};
                const fallback_elem_t = try self.iterableElementType(effective_source_t);
                for (target_elements, 0..) |target, i| {
                    if (target == hir_mod.none_node_id) continue;
                    var elem_node: NodeId = hir_mod.none_node_id;
                    var elem_t: TypeId = types.Primitive.any;
                    if (i < source_elements.len and source_elements[i] != hir_mod.none_node_id) {
                        elem_node = source_elements[i];
                        elem_t = self.hir.typeOf(elem_node);
                        if (elem_t == types.Primitive.none and self.nodeContainsIdentifier(elem_node, target_name)) {
                            elem_t = types.Primitive.any;
                        } else if (elem_t == types.Primitive.none and self.hir.kindOf(elem_node) != .identifier) {
                            elem_t = try self.checkExpression(elem_node);
                        }
                    } else {
                        if (try self.unionTupleElementAccessAt(effective_source_t, i)) |access| {
                            elem_t = access.value_type;
                        } else {
                            const tuple_t = self.tupleElementType(effective_source_t, i);
                            elem_t = if (tuple_t != types.Primitive.none) tuple_t else fallback_elem_t;
                        }
                    }
                    elem_t = self.widenNullishBindingElementType(elem_node, elem_t);
                    if (elem_t == types.Primitive.none or elem_t == types.Primitive.any or elem_t == types.Primitive.unknown) continue;
                    switch (self.hir.kindOf(target)) {
                        .identifier => if (hir_mod.identifierOf(self.hir, target).name == target_name) break :blk elem_t,
                        .array_literal, .object_literal, .array_pattern, .object_pattern => {
                            if (try self.typeOfPatternBindingFromSource(target, elem_node, elem_t, target_name)) |bt| break :blk bt;
                        },
                        .assignment => {
                            const a = hir_mod.assignmentOf(self.hir, target);
                            var default_t = self.hir.typeOf(a.value);
                            if (default_t == types.Primitive.none and self.nodeContainsIdentifier(a.value, target_name)) {
                                default_t = types.Primitive.any;
                            } else if (default_t == types.Primitive.none and self.hir.kindOf(a.value) != .identifier) {
                                default_t = try self.checkExpression(a.value);
                            }
                            if (default_t == types.Primitive.none) default_t = types.Primitive.any;
                            const effective_t = try self.destructuringSourceWithDefault(elem_t, default_t);
                            if (try self.typeOfPatternBindingFromSource(a.target, a.value, effective_t, target_name)) |bt| break :blk bt;
                        },
                        else => {},
                    }
                }
                break :blk null;
            },
            .object_pattern => blk: {
                for (hir_mod.patternElements(self.hir, pattern_node)) |elem| {
                    if (self.hir.kindOf(elem) != .parameter) continue;
                    const p = hir_mod.parameterOf(self.hir, elem);
                    if (p.name == hir_mod.none_node_id) continue;
                    if (p.flags.is_rest) {
                        const rest_t = try self.objectRestBindingType(pattern_node, source_t);
                        if (rest_t == types.Primitive.any or rest_t == types.Primitive.unknown or rest_t == types.Primitive.none) continue;
                        switch (self.hir.kindOf(p.name)) {
                            .identifier => if (hir_mod.identifierOf(self.hir, p.name).name == target_name) break :blk rest_t,
                            .array_pattern, .object_pattern => {
                                if (try self.typeOfPatternBindingFromSource(p.name, hir_mod.none_node_id, rest_t, target_name)) |bt| break :blk bt;
                            },
                            .assignment => {
                                const a = hir_mod.assignmentOf(self.hir, p.name);
                                if (try self.typeOfPatternBindingFromSource(a.target, hir_mod.none_node_id, rest_t, target_name)) |bt| break :blk bt;
                            },
                            else => {},
                        }
                        continue;
                    }
                    var prop_t: TypeId = types.Primitive.any;
                    if (p.flags.is_computed_binding_key and p.default_value != hir_mod.none_node_id) {
                        prop_t = (try self.objectPropertyTypeForComputedKeyNode(source_t, p.default_value)) orelse types.Primitive.any;
                    } else if (try self.objectBindingElementKeyName(elem, p.name)) |key_name| {
                        prop_t = self.objectPropertyTypeByName(source_t, key_name) orelse types.Primitive.any;
                    }
                    if (prop_t == types.Primitive.any or prop_t == types.Primitive.unknown or prop_t == types.Primitive.none) continue;
                    switch (self.hir.kindOf(p.name)) {
                        .identifier => if (hir_mod.identifierOf(self.hir, p.name).name == target_name) break :blk prop_t,
                        .array_pattern, .object_pattern => {
                            if (try self.typeOfPatternBindingFromSource(p.name, hir_mod.none_node_id, prop_t, target_name)) |bt| break :blk bt;
                        },
                        .assignment => {
                            const a = hir_mod.assignmentOf(self.hir, p.name);
                            if (try self.typeOfPatternBindingFromSource(a.target, hir_mod.none_node_id, prop_t, target_name)) |bt| break :blk bt;
                        },
                        else => {},
                    }
                }
                break :blk null;
            },
            .object_literal => blk: {
                for (hir_mod.objectLiteralProps(self.hir, pattern_node)) |prop_node| {
                    if (self.hir.kindOf(prop_node) != .object_property) continue;
                    const op = hir_mod.objectPropertyOf(self.hir, prop_node);
                    if (op.value == hir_mod.none_node_id) continue;
                    var prop_t: TypeId = types.Primitive.any;
                    if (op.is_computed) {
                        prop_t = (try self.objectPropertyTypeForComputedKeyNode(source_t, op.key)) orelse types.Primitive.any;
                    } else if (self.propertyNameFromKeyNode(op.key)) |key_name| {
                        prop_t = self.objectPropertyTypeByName(source_t, key_name) orelse types.Primitive.any;
                    }
                    if (prop_t == types.Primitive.any or prop_t == types.Primitive.unknown or prop_t == types.Primitive.none) continue;
                    switch (self.hir.kindOf(op.value)) {
                        .identifier => if (hir_mod.identifierOf(self.hir, op.value).name == target_name) break :blk prop_t,
                        .array_literal, .object_literal, .array_pattern, .object_pattern => {
                            if (try self.typeOfPatternBindingFromSource(op.value, hir_mod.none_node_id, prop_t, target_name)) |bt| break :blk bt;
                        },
                        .assignment => {
                            const a = hir_mod.assignmentOf(self.hir, op.value);
                            if (try self.typeOfPatternBindingFromSource(a.target, hir_mod.none_node_id, prop_t, target_name)) |bt| break :blk bt;
                        },
                        else => {},
                    }
                }
                break :blk null;
            },
            .identifier => if (hir_mod.identifierOf(self.hir, pattern_node).name == target_name) source_t else null,
            .assignment => blk: {
                const a = hir_mod.assignmentOf(self.hir, pattern_node);
                break :blk try self.typeOfPatternBindingFromSource(a.target, source_node, source_t, target_name);
            },
            else => null,
        };
    }

    fn annotatedArrayLookupShouldUseDeclared(self: *Checker, current_t: TypeId, declared_t: TypeId) bool {
        if ((current_t == types.Primitive.any or current_t == types.Primitive.unknown) and
            declared_t != types.Primitive.any and
            declared_t != types.Primitive.unknown and
            declared_t != types.Primitive.none)
        {
            return true;
        }
        if (current_t >= self.interner.pool.typeCount() or declared_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(current_t).is_object_type or
            !self.interner.pool.flagsOf(declared_t).is_object_type)
        {
            return false;
        }
        const current_elem = self.interner.objectNumberIndex(current_t);
        const declared_elem = self.interner.objectNumberIndex(declared_t);
        if (current_elem == types.Primitive.none or declared_elem == types.Primitive.none) return false;
        if (declared_elem == types.Primitive.any or declared_elem == types.Primitive.unknown) return false;
        return current_elem == types.Primitive.any or current_elem == types.Primitive.unknown or current_elem == types.Primitive.never;
    }

    fn arrayElementAssignmentResult(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!?bool {
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return null;
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (!source_flags.is_object_type or !target_flags.is_object_type) return null;
        if (source_flags.is_union or source_flags.is_intersection or source_flags.is_signature or
            target_flags.is_union or target_flags.is_intersection or target_flags.is_signature)
        {
            return null;
        }
        if (source_flags.is_tuple or target_flags.is_tuple) return null;
        if (self.fixedTupleLength(source_t) != null or self.fixedTupleLength(target_t) != null) return null;
        if (self.array_origin_types.contains(target_t) and
            !self.objectTypeIsArrayLikeContainer(source_t))
        {
            return false;
        }
        const source_elem = self.interner.objectNumberIndex(source_t);
        const target_elem = if (self.generator_type_info.get(target_t)) |iterable|
            iterable.yield_type
        else
            self.interner.objectNumberIndex(target_t);
        if (source_elem == types.Primitive.none or target_elem == types.Primitive.none) return null;
        if (source_elem == types.Primitive.any or source_elem == types.Primitive.unknown or
            target_elem == types.Primitive.any or target_elem == types.Primitive.unknown)
        {
            return true;
        }
        if (self.isObjectLikeType(source_elem) and self.isConcretePrimitiveLike(target_elem)) return false;
        if (self.objectTypeMissingRequiredMember(source_elem, target_elem)) return false;
        return try self.indexSignatureValueAssignable(source_elem, target_elem);
    }

    fn objectTypeMissingRequiredMember(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(source_t).is_object_type or
            !self.interner.pool.flagsOf(target_t).is_object_type)
        {
            return false;
        }
        const source_members = self.interner.objectMembers(source_t);
        for (self.interner.objectMembers(target_t)) |tm| {
            if (tm.is_optional or tm.is_method) continue;
            var found = false;
            for (source_members) |sm| {
                if (sm.name == tm.name) {
                    found = true;
                    break;
                }
            }
            if (!found) return true;
        }
        return false;
    }

    /// Try to resolve `id` against a single sibling statement `s`
    /// (a `let`/`const`/`var`, `function`, `class`, or `import`
    /// declaration). Returns the bound type when `s` declares the
    /// name, or null otherwise. Shared by the block-scope and the
    /// switch-body scope walks in `typeOfIdentifier` ÃÂ¢ÃÂÃÂ declarations
    /// written directly inside a `case`/`default` clause share the
    /// enclosing switch's block scope per the ECMAScript spec, so
    /// they resolve exactly like sibling block statements.
    fn resolveValueDeclInStmt(
        self: *Checker,
        s: NodeId,
        node: NodeId,
        id: hir_mod.IdentifierPayload,
    ) CheckError!?TypeId {
        const decl = self.unwrapExportDecl(s);
        if (!self.valueDeclVisibleFromNode(decl, node)) return null;
        const sk = self.hir.kindOf(decl);
        if (sk == .var_decl or sk == .let_decl or sk == .const_decl) {
            const v = hir_mod.varDeclOf(self.hir, decl);
            if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                const vid = hir_mod.identifierOf(self.hir, v.name);
                if (vid.name == id.name) {
                    self.reportDeprecatedDeclarationUse(node, decl, id.name) catch {};
                    if (sk == .var_decl and
                        self.strict_flags.strict_null_checks and
                        !v.is_ambient and
                        v.type_annotation == hir_mod.none_node_id and
                        v.init == hir_mod.none_node_id)
                    {
                        return types.Primitive.undefined_t;
                    }
                    if (self.nodeIsCallCallee(node) and v.init != hir_mod.none_node_id) {
                        const init_kind = self.hir.kindOf(v.init);
                        if ((init_kind == .fn_decl or init_kind == .fn_expr or init_kind == .arrow_fn) and
                            self.fnHasJsDocClassOrConstructorTag(v.init))
                        {
                            if (try self.jsConstructorStaticTypeForHeritage(node, id.name)) |constructor_t| return constructor_t;
                        }
                    }
                    const t = self.hir.typeOf(decl);
                    if (v.type_annotation != hir_mod.none_node_id and
                        (self.declared_identifier_lookup or t == types.Primitive.none))
                    {
                        const declared_t = self.lowerVarDeclTypeAnnotationForIdentifierLookup(id.name, v) catch types.Primitive.any;
                        self.hir.setType(decl, declared_t);
                        self.hir.setType(v.name, declared_t);
                        return declared_t;
                    }
                    if (v.type_annotation != hir_mod.none_node_id and t != types.Primitive.none) {
                        const declared_t = self.lowerVarDeclTypeAnnotationForIdentifierLookup(id.name, v) catch types.Primitive.any;
                        if (self.annotatedArrayLookupShouldUseDeclared(t, declared_t)) {
                            self.hir.setType(decl, declared_t);
                            self.hir.setType(v.name, declared_t);
                            return declared_t;
                        }
                    }
                    if (t != types.Primitive.none) return t;
                }
            } else if (v.name != hir_mod.none_node_id) {
                const vk = self.hir.kindOf(v.name);
                if (vk == .object_pattern or vk == .array_pattern or vk == .object_literal or vk == .array_literal) {
                    const container_t = if (self.hir.typeOf(decl) != types.Primitive.none)
                        self.hir.typeOf(decl)
                    else
                        types.Primitive.any;
                    if (v.type_annotation != hir_mod.none_node_id) {
                        const declared_t = self.lowerVarDeclTypeAnnotationForIdentifierLookup(id.name, v) catch types.Primitive.any;
                        if (self.typeOfPatternBinding(v.name, declared_t, id.name)) |bt| {
                            return bt;
                        }
                    }
                    if (v.init != hir_mod.none_node_id) {
                        if (self.typeOfPatternBindingFromSource(v.name, v.init, container_t, id.name) catch null) |bt| {
                            return bt;
                        }
                    }
                    if (self.typeOfPatternBinding(v.name, container_t, id.name)) |bt| {
                        return bt;
                    }
                }
            }
        } else if (sk == .fn_decl or sk == .fn_expr) {
            const fp = hir_mod.fnDeclOf(self.hir, decl);
            if (fp.name != hir_mod.none_node_id and self.hir.kindOf(fp.name) == .identifier) {
                const fid = hir_mod.identifierOf(self.hir, fp.name);
                if (fid.name == id.name) {
                    self.reportDeprecatedDeclarationUse(node, decl, id.name) catch {};
                    if (self.nodeIsCallCallee(node) and self.fnHasJsDocClassOrConstructorTag(decl)) {
                        if (try self.jsConstructorStaticTypeForHeritage(node, id.name)) |constructor_t| return constructor_t;
                    }
                    if (self.overloadedFunctionValueType(id.name) catch null) |overload_t| {
                        return try self.expandoAugmentedFunctionValueType(id.name, node, overload_t);
                    }
                    const t = self.hir.typeOf(decl);
                    if (t != types.Primitive.none) return try self.expandoAugmentedFunctionValueType(id.name, node, t);
                    if (try self.ensurePlainFunctionSignature(decl)) |sig| {
                        return try self.expandoAugmentedFunctionValueType(id.name, node, sig);
                    }
                    // The name IS declared by a sibling function in this
                    // block scope, but its signature type hasn't been
                    // assigned yet (this happens when the reference is
                    // resolved before the nested declaration is checked ÃÂ¢ÃÂÃÂ
                    // e.g. `return bar;` for a nested `function bar` inside
                    // a class method body, cf. wrappedAndRecursiveConstraints3).
                    // tsc never emits TS2304 for a declared binding, so fall
                    // back to `any` rather than letting the unresolved-name
                    // chain fire.
                    _ = self.reportReturnTypeAnnotationCircularIfActive(decl);
                    return types.Primitive.any;
                }
            }
        } else if (sk == .class_decl or sk == .class_expr) {
            const cp = hir_mod.classOf(self.hir, decl);
            if (cp.name != hir_mod.none_node_id and self.hir.kindOf(cp.name) == .identifier) {
                const cid = hir_mod.identifierOf(self.hir, cp.name);
                if (cid.name == id.name) {
                    self.reportDeprecatedDeclarationUse(node, decl, id.name) catch {};
                    if (self.class_static_types.get(id.name)) |static_t| return static_t;
                    const t = self.hir.typeOf(decl);
                    if (t != types.Primitive.none) return t;
                    // Declared by a sibling class in this block scope but
                    // not yet typed ÃÂ¢ÃÂÃÂ same rationale as the function case
                    // above: a declared binding must not surface TS2304.
                    return types.Primitive.any;
                }
            }
        } else if (sk == .import_decl) {
            if (self.importDeclBindsLocal(decl, id.name)) {
                if (self.moduleNamespaceTypeForLocalImport(id.name, node) catch null) |ns_t| return ns_t;
                if (self.virtualImportTypeForLocal(id.name, node) catch null) |import_t| return import_t;
                if (try self.programExportedClassTypeForImportBinding(decl, id.name, node)) |class_t| return class_t;
                return types.Primitive.any;
            }
        } else if (sk == .for_in_stmt or sk == .for_of_stmt) {
            const fr = hir_mod.forInOf(self.hir, decl);
            if (fr.target != hir_mod.none_node_id and self.hir.kindOf(fr.target) == .var_decl) {
                const v = hir_mod.varDeclOf(self.hir, fr.target);
                if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier and
                    hir_mod.identifierOf(self.hir, v.name).name == id.name)
                {
                    const t = self.hir.typeOf(fr.target);
                    return if (t == types.Primitive.none) types.Primitive.any else t;
                }
            }
        }
        return null;
    }

    fn identifierReadsUninitializedVar(self: *Checker, node: NodeId, name: hir_mod.StringId) bool {
        if (self.isDeclNameSlot(node)) return false;
        const section = self.virtualSectionStartForNode(node);
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const kind = self.hir.kindOf(cur);
            const stmts: []const NodeId = switch (kind) {
                .block_stmt => hir_mod.blockStmts(self.hir, cur),
                .namespace_decl => hir_mod.namespaceBody(self.hir, cur),
                else => continue,
            };
            for (stmts) |raw| {
                if (self.sourceHasVirtualFilenameSections() and
                    self.virtualSectionStartForNode(raw) != section) continue;
                const decl = self.unwrapExportDecl(raw);
                if (self.hir.kindOf(decl) != .var_decl) continue;
                const variable = hir_mod.varDeclOf(self.hir, decl);
                if (variable.is_ambient or
                    variable.type_annotation != hir_mod.none_node_id or
                    variable.init != hir_mod.none_node_id or
                    variable.name == hir_mod.none_node_id or
                    self.hir.kindOf(variable.name) != .identifier) continue;
                if (hir_mod.identifierOf(self.hir, variable.name).name == name) return true;
            }
        }
        return false;
    }

    fn valueDeclVisibleFromNode(self: *Checker, decl: NodeId, node: NodeId) bool {
        if (!self.sourceHasVirtualFilenameSections()) return true;
        if (decl == hir_mod.none_node_id or node == hir_mod.none_node_id) return true;
        if (self.virtualSectionStartForNode(decl) == self.virtualSectionStartForNode(node)) return true;
        const root = self.rootBlockFor(node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        const decl_section = self.virtualSectionStartForNode(decl);
        if (self.virtualSectionIsDeclarationFile(decl)) {
            return !self.virtualSectionHasExternalModuleSyntax(root, decl_section);
        }
        if (self.declarationSourceHasLeadingDeclare(decl)) return true;
        const node_section = self.virtualSectionStartForNode(node);
        return !self.virtualSectionHasExternalModuleSyntax(root, decl_section) and
            !self.virtualSectionHasExternalModuleSyntax(root, node_section);
    }

    fn visibleValueSymbolDeclForNode(self: *Checker, decls: []const NodeId, node: NodeId) ?NodeId {
        for (decls) |decl| {
            if (!self.valueDeclVisibleFromNode(decl, node)) continue;
            return decl;
        }
        return null;
    }

    /// True when statement `s` is a `let`/`const`/`var`, `function`,
    /// or `class` declaration introducing the value name `name`.
    /// Used to suppress TS2304 for switch-case-scoped bindings that
    /// are declared but not yet resolvable to a concrete type.
    fn stmtDeclaresValueName(self: *Checker, s: NodeId, name: hir_mod.StringId) bool {
        switch (self.hir.kindOf(s)) {
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, s);
                if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                    return hir_mod.identifierOf(self.hir, v.name).name == name;
                }
            },
            .fn_decl, .fn_expr => {
                const f = hir_mod.fnDeclOf(self.hir, s);
                if (f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier) {
                    return hir_mod.identifierOf(self.hir, f.name).name == name;
                }
            },
            .class_decl, .class_expr => {
                const c = hir_mod.classOf(self.hir, s);
                if (c.name != hir_mod.none_node_id and self.hir.kindOf(c.name) == .identifier) {
                    return hir_mod.identifierOf(self.hir, c.name).name == name;
                }
            },
            else => {},
        }
        return false;
    }

    /// Resolve an identifier reference's type. Walks up the HIR
    /// parent chain looking for an enclosing function whose
    /// parameter list declares this name; then falls back to the
    /// binder's module-level scope. This is a Phase 3 simplification
    /// ÃÂ¢ÃÂÃÂ proper lexical scoping per the binder's Scope graph lands
    /// in a follow-up; this covers the high-frequency patterns
    /// (function parameter use, top-level decl reference).
    const ConstructorFieldLocalRef = struct {
        field_name: hir_mod.StringId,
        /// True when the reference sits inside the field's TYPE annotation
        /// (`y: typeof x`) rather than its initializer — selects TS2844.
        in_type: bool = false,
    };

    const ConstructorLocalKind = enum {
        plain,
        parameter_property,
    };

    fn constructorFieldLocalRef(self: *Checker, node: NodeId, name: hir_mod.StringId) ?ConstructorFieldLocalRef {
        if (self.isDeclNameSlot(node)) return null;
        if (self.sourceHasUseDefineForClassFieldsTrueDirective()) return null;
        var prev = node;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : ({
            prev = cur;
            cur = self.hir.parentOf(cur);
        }) {
            const cur_kind = self.hir.kindOf(cur);
            if (cur_kind == .fn_decl or cur_kind == .fn_expr or cur_kind == .arrow_fn) {
                if (self.functionLocalsContain(cur, name)) return null;
            }
            if (cur_kind != .object_property) continue;
            const class_node = self.hir.parentOf(cur);
            if (class_node == hir_mod.none_node_id) continue;
            const class_kind = self.hir.kindOf(class_node);
            if (class_kind != .class_decl and class_kind != .class_expr) continue;
            const op = hir_mod.objectPropertyOf(self.hir, cur);
            if (op.is_static) return null;
            // The reference is in the type annotation (TS2844) or the
            // initializer (TS2301). `prev` is the direct child of the
            // property we ascended through. A type-position reference is
            // valid even when there's no initializer.
            const in_type = op.type_annotation != hir_mod.none_node_id and prev == op.type_annotation;
            if (!in_type and op.value == hir_mod.none_node_id) return null;
            const field_name = (self.classMemberNameFromPropertyKey(op.key, op.is_computed) catch null) orelse return null;
            const local_kind = self.classConstructorLocalKind(class_node, name) orelse return null;
            // A parameter property is also an instance member. In a value
            // initializer, `x` is therefore diagnosed through TS2663 with
            // the `this.x` suggestion; type queries retain TS2844.
            if (!in_type and local_kind == .parameter_property) return null;
            return .{ .field_name = field_name, .in_type = in_type };
        }
        return null;
    }

    fn classConstructorLocalKind(self: *Checker, class_node: NodeId, name: hir_mod.StringId) ?ConstructorLocalKind {
        var locals: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer locals.deinit(self.gpa);
        for (hir_mod.classMembers(self.hir, class_node)) |member| {
            const k = self.hir.kindOf(member);
            if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) continue;
            const f = hir_mod.fnDeclOf(self.hir, member);
            if (!f.flags.is_constructor or f.body == hir_mod.none_node_id) continue;
            for (hir_mod.fnParams(self.hir, member)) |param| {
                if (self.hir.kindOf(param) != .parameter) continue;
                const p = hir_mod.parameterOf(self.hir, param);
                locals.clearRetainingCapacity();
                self.collectBindingNames(p.name, &locals) catch return null;
                if (locals.contains(name)) {
                    return if (p.flags.is_parameter_property) .parameter_property else .plain;
                }
            }
            locals.clearRetainingCapacity();
            self.collectConstructorLocalNames(f.body, &locals) catch return null;
            if (locals.contains(name)) return .plain;
            break;
        }
        return null;
    }

    fn functionLocalsContain(self: *Checker, fn_node: NodeId, name: hir_mod.StringId) bool {
        var locals: std.AutoHashMapUnmanaged(hir_mod.StringId, void) = .empty;
        defer locals.deinit(self.gpa);
        for (hir_mod.fnParams(self.hir, fn_node)) |param| {
            if (self.hir.kindOf(param) != .parameter) continue;
            const p = hir_mod.parameterOf(self.hir, param);
            self.collectBindingNames(p.name, &locals) catch return false;
        }
        if (locals.contains(name)) return true;
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        self.collectConstructorLocalNames(f.body, &locals) catch return false;
        return locals.contains(name);
    }

    fn collectConstructorLocalNames(
        self: *Checker,
        node: NodeId,
        out: *std.AutoHashMapUnmanaged(hir_mod.StringId, void),
    ) CheckError!void {
        if (node == hir_mod.none_node_id) return;
        switch (self.hir.kindOf(node)) {
            .block_stmt => for (hir_mod.blockStmts(self.hir, node)) |s| try self.collectConstructorLocalNames(s, out),
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, node);
                try self.collectBindingNames(v.name, out);
            },
            .fn_decl, .fn_expr => {
                const f = hir_mod.fnDeclOf(self.hir, node);
                if (f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier) {
                    try out.put(self.gpa, hir_mod.identifierOf(self.hir, f.name).name, {});
                }
            },
            .class_decl, .class_expr => {
                const c = hir_mod.classOf(self.hir, node);
                if (c.name != hir_mod.none_node_id and self.hir.kindOf(c.name) == .identifier) {
                    try out.put(self.gpa, hir_mod.identifierOf(self.hir, c.name).name, {});
                }
            },
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                try self.collectConstructorLocalNames(i.then_branch, out);
                try self.collectConstructorLocalNames(i.else_branch, out);
            },
            .for_stmt => {
                const fr = hir_mod.forStmtOf(self.hir, node);
                try self.collectConstructorLocalNames(fr.init, out);
                try self.collectConstructorLocalNames(fr.body, out);
            },
            .for_in_stmt, .for_of_stmt => {
                const fr = hir_mod.forInOf(self.hir, node);
                try self.collectConstructorLocalNames(fr.target, out);
                try self.collectConstructorLocalNames(fr.body, out);
            },
            .while_stmt => try self.collectConstructorLocalNames(hir_mod.whileOf(self.hir, node).body, out),
            .do_while_stmt => try self.collectConstructorLocalNames(hir_mod.doWhileOf(self.hir, node).body, out),
            .switch_stmt => for (hir_mod.switchCases(self.hir, node)) |case| try self.collectConstructorLocalNames(case, out),
            .switch_case => for (hir_mod.switchCaseStmts(self.hir, node)) |s| try self.collectConstructorLocalNames(s, out),
            .try_stmt => {
                const ts = hir_mod.tryOf(self.hir, node);
                try self.collectConstructorLocalNames(ts.block, out);
                try self.collectConstructorLocalNames(ts.catch_block, out);
                try self.collectConstructorLocalNames(ts.finally_block, out);
            },
            .arrow_fn => return,
            else => {},
        }
    }

    fn reportFieldInitializerConstructorLocalOnce(
        self: *Checker,
        node: NodeId,
        info: ConstructorFieldLocalRef,
        name: hir_mod.StringId,
    ) !void {
        const code: u32 = if (info.in_type)
            TsCodes.field_type_constructor_local
        else
            TsCodes.field_initializer_constructor_local;
        for (self.diagnostics.items) |d| {
            if (d.node == node and d.code == code) return;
        }
        const lead = if (info.in_type) "Type" else "Initializer";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "{s} of instance member variable '{s}' cannot reference identifier '{s}' declared in the constructor.",
            .{ lead, self.string_interner.get(info.field_name), self.string_interner.get(name) },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = code,
            .message = msg,
        });
    }

    fn typeOfIdentifier(self: *Checker, node: NodeId) TypeId {
        const id = hir_mod.identifierOf(self.hir, node);
        const name_str = self.string_interner.get(id.name);
        const is_this = std.mem.eql(u8, name_str, "this");
        const this_rebound_plain_function = is_this and self.thisInsideNonArrowPlainFunction(node);
        if (std.mem.eql(u8, name_str, "await") and self.identifierHasClassStaticAwaitContext(node)) {
            if (self.identifierIsObjectLiteralShorthand(node)) {
                self.reportAt(node, self.hir.spanOf(node).end + 1, 1005, "':' expected.") catch {};
            } else {
                self.reportStaticBlockAwaitIdentifier(node) catch {};
            }
            return types.Primitive.any;
        }
        // ECMAScript private-name LHS of `in` operator
        // (`#field in obj`) is a dedicated syntactic form (ES2022
        // brand check). The identifier is not a regular value
        // reference, so suppress the normal TS2304 lookup-failure
        // path. Mirrors upstream `privateNameInInExpression*`
        // baselines which expect no TS2304 here.
        if (std.mem.startsWith(u8, name_str, "#") and self.privateIdentifierIsInExpressionLhs(node)) {
            return types.Primitive.any;
        }
        // Field initializers are evaluated in the constructor's lexical
        // environment under legacy class-field semantics. Check this before
        // narrow/module lookup so an outer binding with the same name cannot
        // hide the constructor-local TS2301.
        if (self.constructorFieldLocalRef(node, id.name)) |info| {
            self.reportFieldInitializerConstructorLocalOnce(node, info, id.name) catch {};
            return types.Primitive.any;
        }
        if (is_this and
            self.sourceHasStrictFalseDirective() and
            this_rebound_plain_function and
            !self.enclosingThisHostHasExplicitThisParam(node))
        {
            return types.Primitive.any;
        }
        // TS17009 ÃÂ¢ÃÂÃÂ `this` referenced inside a derived class
        // constructor BEFORE the first `super(...)` call. Has to
        // run BEFORE the narrow-lookup early return below so it
        // fires even when `this` resolves to the class instance
        // type. Mirrors `superCallBeforeThisAccessing{3,6,7}`.
        if (is_this) {
            self.checkThisBeforeSuperInConstructor(node) catch {};
        }

        if (is_this and self.thisInsideEnumInitializer(node)) {
            self.report(node, TsCodes.this_in_current_location, "'this' cannot be referenced in current location.") catch {};
            return types.Primitive.any;
        }

        // Report the illegal computed-name reference before narrow lookup,
        // then retain the owning class type for the rest of the expression.
        if (is_this and self.in_computed_property_name) {
            self.report(node, TsCodes.this_in_computed_property_name, "'this' cannot be referenced in a computed property name.") catch {};
        }
        if (is_this and
            self.thisInsideStaticDecoratedClassPropertyInitializer(node) and
            !self.diagnosticExists(node, TsCodes.this_in_static_property_initializer_decorated_class))
        {
            self.report(node, TsCodes.this_in_static_property_initializer_decorated_class, "Cannot use 'this' in a static property initializer of a decorated class.") catch {};
        }

        // NOTE: TS2334 ("'this' cannot be referenced in a static property
        // initializer.") is a catalog entry but upstream
        // `checkThisExpression` (checker.ts) no longer emits it ÃÂ¢ÃÂÃÂ modern
        // TypeScript (post ES2022 native class fields) treats `this` in
        // static field initializers as valid, where it refers to the
        // class constructor. The `thisInsideStaticPropertyInitializer`
        // predicate below is retained as a utility for future
        // narrowed-context use; emission would over-fire on upstream
        // baselines like `typeOfThisInStaticMembers2` (which explicitly
        // marks `static foo = this;` as `// ok`).

        if (is_this and
            !self.sourceHasStrictFalseDirective() and
            self.thisInsideClassFieldFunctionExpression(node) and
            !self.thisIsPrivateMemberReceiverInsideClass(node))
        {
            self.report(node, TsCodes.this_implicitly_any, "'this' implicitly has type 'any' because it does not have a type annotation.") catch {};
            return types.Primitive.any;
        }
        if (is_this) {
            if (self.assignedFunctionExpressionEffectiveThis(node)) |this_t| return this_t;
        }

        // Narrowed binding from an enclosing type-guard takes
        // precedence over the static type. A plain function rebinds
        // `this` to an implicit any, so its narrow is normally skipped —
        // UNLESS the function declares an explicit `this: T` parameter,
        // in which case that declared type is the bound `this`.
        if (!this_rebound_plain_function or
            (is_this and self.enclosingThisHostHasExplicitThisParam(node)) or
            (is_this and this_rebound_plain_function and self.thisInsideObjectLiteralMethod(node) and self.currentThisType() != null))
        {
            if (!self.isDeclNameSlot(node)) {
                if (self.visibleAnnotatedIdentifierTypeNode(node)) |type_node| {
                    if (self.typeAnnotationShouldBecomeErrorAny(type_node)) return types.Primitive.any;
                }
            }
            if (!self.isDeclNameSlot(node)) {
                const is_evolving_untyped = self.identifierIsUntypedUninitializedVar(node);
                const visible_annotation_node = self.visibleAnnotatedIdentifierTypeNode(node);
                if (self.recoveredSourceParameterAnnotationType(node, id.name)) |declared_t| {
                    const declared_non_null = self.subtractNullUndefined(declared_t) catch declared_t;
                    const narrow_t = self.lookupNarrow(id.name);
                    const has_incompatible_weak_narrow = if (narrow_t) |flow_t|
                        self.engine.weakTypeNoCommonProperties(flow_t, declared_t) or
                            self.engine.weakTypeNoCommonProperties(flow_t, declared_non_null)
                    else
                        false;
                    if (visible_annotation_node == null or has_incompatible_weak_narrow) {
                        if (narrow_t) |flow_t| {
                            if (!has_incompatible_weak_narrow and
                                (self.checkerAssignableTo(flow_t, declared_t) catch false)) return flow_t;
                        }
                        return declared_t;
                    }
                }
                if (is_evolving_untyped and
                    (self.sourceUseIsInsideTruthyIdentifierGuard(node, id.name) or
                        self.sourceHasDirectSelfConditionalAssignmentBeforeUse(node, id.name)))
                {
                    return types.Primitive.any;
                }
                if (!is_evolving_untyped and self.sourceHasDirectSelfConditionalAssignmentBeforeUse(node, id.name)) {
                    if ((self.recoveredEvolvingAnyFlowTypeAt(node, id.name) catch null) != null) return types.Primitive.any;
                }
                if (self.visibleActiveAnnotatedIdentifierType(node) == null) {
                    if (self.definiteEvolvingAnyFlowTypeAt(node, id.name) catch null) |flow_t| {
                        if (self.lookupNarrow(id.name)) |narrow_t| {
                            if (narrow_t != types.Primitive.any and
                                (self.checkerAssignableTo(narrow_t, flow_t) catch false))
                            {
                                return narrow_t;
                            }
                        }
                        return flow_t;
                    }
                }
            }
            if (self.lookupNarrow(id.name)) |t| {
                // Expando-function augmentation also applies to the narrowed
                // flow type: a function-valued binding that receives
                // `name.prop = ÃÂ¢ÃÂÃÂ¦` assignments carries those properties on
                // every reference, not just on the bare declared type. Without
                // this the narrow (the plain signature) would shadow the
                // augmented type for later reads. Skip the LHS object of an
                // expando assignment so we don't recurse needlessly.
                if (!self.isDeclNameSlot(node)) {
                    if (self.expandoAugmentedNarrowType(id.name, node, t) catch null) |aug_t| return aug_t;
                }
                if ((t == types.Primitive.any or t == types.Primitive.unknown) and !self.isDeclNameSlot(node)) {
                    if (self.visibleActiveAnnotatedIdentifierType(node)) |declared_t| {
                        if (declared_t != types.Primitive.any and declared_t != types.Primitive.unknown) return declared_t;
                    }
                } else if (!self.isDeclNameSlot(node)) {
                    if (self.visibleActiveAnnotatedIdentifierType(node)) |declared_t| {
                        const declared_non_null = self.subtractNullUndefined(declared_t) catch declared_t;
                        if (self.engine.weakTypeNoCommonProperties(t, declared_t) or
                            self.engine.weakTypeNoCommonProperties(t, declared_non_null)) return declared_t;
                        if (declared_t != types.Primitive.any and
                            declared_t != types.Primitive.unknown and
                            declared_t != types.Primitive.none and
                            !self.unionContainsExactType(declared_t, t) and
                            !self.instanceofFallthroughUnionCoversIntersection(t, declared_t) and
                            !self.narrowedNamedTypeFitsDeclaredUnion(node, declared_t, t) and
                            !(self.checkerAssignableTo(t, declared_t) catch true))
                        {
                            return declared_t;
                        }
                    }
                }
                if (t == types.Primitive.any and
                    self.strict_flags.strict_null_checks and
                    self.identifierReadsUninitializedVar(node, id.name))
                {
                    return types.Primitive.undefined_t;
                }
                return t;
            }
        }
        if (self.resolving_value_types.contains(id.name)) {
            if (!self.isDeclNameSlot(node)) {
                if (self.visibleActiveAnnotatedIdentifierType(node)) |declared_t| return declared_t;
            }
            return types.Primitive.any;
        }

        if (is_this) {
            if (self.isDeclNameSlot(node) or
                self.nodeIsThisParameterName(node) or
                self.enclosingThisHostHasThisParam(node) or
                self.thisInsideDecoratorInitializerCallback(node)) return types.Primitive.any;
            if (self.nodeInsideAmbientVarInitializer(node)) return types.Primitive.any;
            const inside_decorator = self.nodeHasAncestorKind(node, .decorator);
            if (self.thisInsideCheckJsConstructorFunction(node)) return types.Primitive.any;
            if (self.checkJsPrototypeAssignmentThisType(node)) |this_t| return this_t;
            if (self.thisInsideCheckJsPrototypeAssignmentFunction(node)) return types.Primitive.any;
            if (self.thisInsideCheckJsFunctionWithThisTag(node)) return types.Primitive.any;
            if (self.thisInsideCheckJsCallbackWithThis(node)) return types.Primitive.any;
            // TS2331: `this` referenced directly inside a namespace
            // body (without an intervening function/class frame) is
            // illegal ÃÂ¢ÃÂÃÂ mirrors upstream tsc for `thisTypeErrors.ts(36)`
            // (`namespace N1 { export var y = this; }`). Pairs with
            // the implicit-any TS2683 below.
            const directly_in_namespace = self.thisDirectlyInsideNamespaceBody(node);
            if (directly_in_namespace) {
                self.report(node, TsCodes.this_in_namespace_body, "'this' cannot be referenced in a module or namespace body.") catch {};
            }
            if (!directly_in_namespace and inside_decorator) return types.Primitive.any;
            // `this` inside a namespace body must still surface the
            // implicit-any TS2683 ÃÂ¢ÃÂÃÂ tsc reports both TS2331 + TS2683
            // (`thisTypeErrors.ts(36,20)`). Skip the global-script
            // early-return in that case so the TS2683 emit below runs.
            if (!directly_in_namespace and self.thisIsGlobalScriptThis(node)) {
                // TS7041 — a `this` that resolves to the global value
                // (no enclosing class/method/object frame) but is
                // captured by an arrow function. tsc fires this in place
                // of the generic TS2683 because the captured `this` will
                // silently be the runtime global at call time. A bare
                // top-level `this` (not arrow-captured) is legitimate in a
                // global script, so this is gated on arrow capture.
                if (self.identifierThisIsArrowCaptured(node)) {
                    self.report(node, TsCodes.arrow_captures_global_this, "The containing arrow function captures the global value of 'this'.") catch {};
                }
                return self.bareGlobalThisType() catch types.Primitive.any;
            }
            if (!directly_in_namespace and self.thisInsideTopLevelContextualArrowWithThis(node)) {
                return self.bareGlobalThisType() catch types.Primitive.any;
            }
            if (!directly_in_namespace and
                self.identifierThisIsArrowCaptured(node) and
                self.thisInsideTopLevelArrow(node) and
                self.sourceFileSectionIsModule(node))
            {
                return types.Primitive.undefined_t;
            }
            if (!self.sourceHasStrictFalseDirective() and
                !self.identifierThisIsArrowCaptured(node) and
                !self.thisInsideObjectLiteralMethod(node) and
                !self.thisInsideClassConstructorParameter(node) and
                !self.thisIsPrivateMemberReceiverInsideClass(node))
            {
                self.reportThisImplicitlyAny(node) catch {};
            }
            return types.Primitive.any;
        }
        if (std.mem.eql(u8, name_str, "new.target")) {
            return types.Primitive.any;
        }
        // `arguments` referenced from an arrow function (no enclosing
        // `function` body to bind it to) is invalid for ES5 ÃÂ¢ÃÂÃÂ tsc
        // emits TS2496 explaining the down-emit can't synthesize an
        // `arguments` slot inside the resulting `function () { ÃÂ¢ÃÂÃÂ¦ }`.
        // This check has to run BEFORE the regular
        // `hasNonArrowFunctionAncestor` early-return: that helper
        // considers any non-arrow ancestor sufficient to bind
        // `arguments`, but tsc fires TS2496 whenever the *innermost*
        // enclosing function is an arrow regardless of what's above.
        if (std.mem.eql(u8, name_str, "arguments") and
            !self.argumentsResolvesToLocalBinding(node, id.name))
        {
            const ctx = self.argumentsClassContext(node);
            switch (ctx) {
                .none => {},
                .property_initializer => {
                    for (self.diagnostics.items) |d| {
                        if (d.code == TsCodes.arguments_in_class_field_or_static_block and d.node == node) return types.Primitive.any;
                    }
                    const msg = self.diag_arena.allocator().dupe(u8, "'arguments' cannot be referenced in property initializers or class static initialization blocks.") catch return types.Primitive.any;
                    self.diagnostics.append(self.gpa, .{
                        .node = node,
                        .code = TsCodes.arguments_in_class_field_or_static_block,
                        .message = msg,
                    }) catch return types.Primitive.any;
                    return types.Primitive.any;
                },
                .static_block => {
                    if (self.staticBlockClassDeclaresArguments(node)) |class_node| {
                        const class_name = self.classDisplayNameFromNode(class_node) catch null;
                        defer if (class_name) |name| self.gpa.free(name);
                        const display = class_name orelse "C";
                        const msg = std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "Cannot find name 'arguments'. Did you mean the static member '{s}.arguments'?",
                            .{display},
                        ) catch return types.Primitive.any;
                        self.diagnostics.append(self.gpa, .{
                            .node = node,
                            .code = TsCodes.cannot_find_name_static_member,
                            .message = msg,
                        }) catch return types.Primitive.any;
                        return types.Primitive.any;
                    }
                    for (self.diagnostics.items) |d| {
                        if (d.code == TsCodes.arguments_in_class_field_or_static_block and d.node == node) return types.Primitive.any;
                    }
                    const msg = self.diag_arena.allocator().dupe(u8, "'arguments' cannot be referenced in property initializers or class static initialization blocks.") catch return types.Primitive.any;
                    self.diagnostics.append(self.gpa, .{
                        .node = node,
                        .code = TsCodes.arguments_in_class_field_or_static_block,
                        .message = msg,
                    }) catch return types.Primitive.any;
                    return types.Primitive.any;
                },
            }
        }
        if (std.mem.eql(u8, name_str, "arguments") and
            self.argumentsInsideArrowOnlyChain(node) and
            self.sourceTargetMentionsEs5() and
            !self.argumentsResolvesToLocalBinding(node, id.name))
        {
            const msg = self.diag_arena.allocator().dupe(u8, "The 'arguments' object cannot be referenced in an arrow function in ES5. Consider using a standard function expression.") catch return types.Primitive.any;
            self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = TsCodes.arguments_in_arrow_es5,
                .message = msg,
            }) catch return types.Primitive.any;
            return self.argumentsObjectType() catch types.Primitive.any;
        }
        if (std.mem.eql(u8, name_str, "arguments") and
            self.argumentsInsideAsyncNonArrowFunction(node) and
            self.sourceTargetMentionsEs5() and
            !self.argumentsResolvesToLocalBinding(node, id.name))
        {
            const msg = self.diag_arena.allocator().dupe(u8, "The 'arguments' object cannot be referenced in an async function or method in ES5. Consider using a standard function or method.") catch return types.Primitive.any;
            self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = TsCodes.arguments_in_async_es5,
                .message = msg,
            }) catch return types.Primitive.any;
            return self.argumentsObjectType() catch types.Primitive.any;
        }
        if (std.mem.eql(u8, name_str, "arguments") and self.hasNonArrowFunctionAncestor(node)) {
            return self.argumentsObjectType() catch types.Primitive.any;
        }
        if (!self.isDeclNameSlot(node) and !self.nodeHasAncestorKind(node, .typeof_type) and !self.isComputedKeyInAmbientClassMember(node) and !self.isBuiltinName(id.name) and self.typeOnlyImportLocal(id.name, node)) {
            if (self.typeOnlyValueUseCoveredByVerbatimDefaultExport(node)) return types.Primitive.any;
            const msg = std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "'{s}' cannot be used as a value because it was imported using 'import type'.",
                .{name_str},
            ) catch return types.Primitive.any;
            self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = TsCodes.type_only_import_used_as_value,
                .message = msg,
            }) catch return types.Primitive.any;
            return types.Primitive.any;
        }
        // TS1362 — a name imported normally but exported type-only by its
        // source module, used as a value (cross-module sibling of TS1361).
        if (!self.isDeclNameSlot(node) and !self.nodeHasAncestorKind(node, .typeof_type) and !self.isComputedKeyInAmbientClassMember(node) and self.nameIsCrossModuleTypeOnlyExport(id.name, node)) {
            const msg = std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "'{s}' cannot be used as a value because it was exported using 'export type'.",
                .{name_str},
            ) catch return types.Primitive.any;
            // Re-query the resolver (only on this rare firing path) to
            // anchor the TS1377 "was exported here" cross-file related-info.
            var related: []const RelatedInfo = &.{};
            if (self.external_resolver) |resolver| {
                if (self.plainNamedImportModule(id.name, node)) |mod_id| {
                    if (resolver.moduleExport(self.string_interner.get(mod_id), self.importer_path, name_str)) |info| {
                        related = self.exportedHereRelatedInfo(name_str, info);
                    }
                }
            }
            self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = TsCodes.type_only_export_used_as_value,
                .message = msg,
                .related = related,
            }) catch return types.Primitive.any;
            const parent = self.hir.parentOf(node);
            if (parent != hir_mod.none_node_id and self.hir.kindOf(parent) == .call_expr) {
                const call = hir_mod.callOf(self.hir, parent);
                if (call.callee == node) {
                    self.report(node, TsCodes.not_callable, "This expression is not callable.") catch return types.Primitive.any;
                }
            }
            return types.Primitive.any;
        }
        // Walk up the parent chain searching for parameters or
        // sibling let/const/var decls in scope.
        var cur: hir_mod.NodeId = self.hir.parentOf(node);
        var saw_namespace_scope = false;
        while (cur != hir_mod.none_node_id) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn or k == .fn_type or k == .constructor_type) {
                // Walk parameters and check the same name.
                const params = if (k == .fn_type or k == .constructor_type) blk: {
                    const ft = hir_mod.fnTypeOf(self.hir, cur);
                    break :blk self.hir.childSlice(ft.params_start, @intCast(ft.params_len));
                } else hir_mod.fnParams(self.hir, cur);
                for (params) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id) continue;
                    const pn_kind = self.hir.kindOf(pp.name);
                    if (pn_kind == .identifier) {
                        const pid = hir_mod.identifierOf(self.hir, pp.name);
                        if (pid.name == id.name) return self.hir.typeOf(p);
                    } else if (pn_kind == .object_pattern or pn_kind == .array_pattern) {
                        // Destructuring parameter binding. Walk the
                        // pattern's elements: each element is a
                        // `parameter` whose own `name` is the bound
                        // identifier. When it matches, resolve the
                        // property's type through the parameter's
                        // annotation (object: by key; array: by
                        // index) and strip `undefined` if a default
                        // expression is present.
                        if (self.typeOfPatternBinding(pp.name, self.hir.typeOf(p), id.name)) |bt| {
                            return bt;
                        }
                    }
                }
                // Don't continue past the function ÃÂ¢ÃÂÃÂ outer scopes
                // would shadow but we still want module-level
                // fallback below.
            }
            if (k == .for_stmt) {
                const fr = hir_mod.forStmtOf(self.hir, cur);
                if (fr.init != hir_mod.none_node_id) {
                    const init_kind = self.hir.kindOf(fr.init);
                    if (init_kind == .var_decl or init_kind == .let_decl or init_kind == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, fr.init);
                        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                            const vid = hir_mod.identifierOf(self.hir, v.name);
                            if (vid.name == id.name) {
                                if (self.declared_identifier_lookup and v.type_annotation != hir_mod.none_node_id) {
                                    const declared_t = self.lowerVarDeclTypeAnnotationForIdentifierLookup(id.name, v) catch types.Primitive.any;
                                    self.hir.setType(fr.init, declared_t);
                                    self.hir.setType(v.name, declared_t);
                                    return declared_t;
                                }
                                const t = self.hir.typeOf(fr.init);
                                if (t != types.Primitive.none) return t;
                                if (v.type_annotation != hir_mod.none_node_id) {
                                    const declared_t = self.lowerVarDeclTypeAnnotationForIdentifierLookup(id.name, v) catch types.Primitive.any;
                                    self.hir.setType(fr.init, declared_t);
                                    self.hir.setType(v.name, declared_t);
                                    return declared_t;
                                }
                            }
                        } else if (v.name != hir_mod.none_node_id) {
                            const vk = self.hir.kindOf(v.name);
                            if (vk == .object_pattern or vk == .array_pattern) {
                                const container_t = if (self.hir.typeOf(fr.init) != types.Primitive.none)
                                    self.hir.typeOf(fr.init)
                                else
                                    types.Primitive.any;
                                if (self.typeOfPatternBinding(v.name, container_t, id.name)) |bt| {
                                    return bt;
                                }
                            }
                        }
                    }
                }
            }
            if (k == .block_stmt) {
                // Look for a sibling var_decl/let_decl/const_decl
                // before this node.
                const stmts = hir_mod.blockStmts(self.hir, cur);
                for (stmts) |s| {
                    if (self.resolveValueDeclInStmt(s, node, id) catch null) |t| return t;
                }
            }
            if (k == .switch_stmt) {
                // Declarations written directly inside a `case`/
                // `default` clause (no surrounding `{}`) share the
                // switch's single block scope per the ECMAScript
                // spec, so a `case X: let y = ÃÂ¢ÃÂÃÂ¦;` binding is visible
                // to every reference in the same (and later) clauses.
                // Without this, such references surfaced spurious
                // TS2304 ÃÂ¢ÃÂÃÂ the parent walk only scanned `block_stmt`
                // siblings, never the case-clause statement lists.
                var declared_untyped = false;
                for (hir_mod.switchCases(self.hir, cur)) |case_node| {
                    for (hir_mod.switchCaseStmts(self.hir, case_node)) |s| {
                        if (self.resolveValueDeclInStmt(s, node, id) catch null) |t| return t;
                        // Track a name that IS declared here but has
                        // no resolved type yet (e.g. an untyped `let`
                        // whose initializer type is still pending).
                        // tsc never reports TS2304 for a declared
                        // binding, so fall back to `any` below.
                        if (!declared_untyped and self.stmtDeclaresValueName(s, id.name)) {
                            declared_untyped = true;
                        }
                    }
                }
                if (declared_untyped) return types.Primitive.any;
            }
            if (k == .namespace_decl) {
                saw_namespace_scope = true;
                const stmts = hir_mod.namespaceBody(self.hir, cur);
                for (stmts) |raw_s| {
                    // Unwrap `export <decl>`. Exported namespace
                    // members are visible inside the body the same
                    // as non-exported ones, but they're wrapped in
                    // an `export_decl` node so the raw kind checks
                    // below would miss them. Without this, the
                    // post-walk fallback chain emits spurious
                    // TS2304 for every `export class` /
                    // `export function` body reference (cf.
                    // parserRealSource4 cascade).
                    const s = self.unwrapExportDecl(raw_s);
                    const sk = self.hir.kindOf(s);
                    if (sk == .var_decl or sk == .let_decl or sk == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, s);
                        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                            const vid = hir_mod.identifierOf(self.hir, v.name);
                            if (vid.name == id.name) {
                                const t = self.hir.typeOf(s);
                                if (v.type_annotation != hir_mod.none_node_id and
                                    (self.declared_identifier_lookup or t == types.Primitive.none))
                                {
                                    const declared_t = self.lowerVarDeclTypeAnnotationForIdentifierLookup(id.name, v) catch types.Primitive.any;
                                    self.hir.setType(s, declared_t);
                                    self.hir.setType(v.name, declared_t);
                                    return declared_t;
                                }
                                if (v.type_annotation != hir_mod.none_node_id and t != types.Primitive.none) {
                                    const declared_t = self.lowerVarDeclTypeAnnotationForIdentifierLookup(id.name, v) catch types.Primitive.any;
                                    if (self.annotatedArrayLookupShouldUseDeclared(t, declared_t)) {
                                        self.hir.setType(s, declared_t);
                                        self.hir.setType(v.name, declared_t);
                                        return declared_t;
                                    }
                                }
                                if (t != types.Primitive.none) return t;
                                // Name IS declared in the namespace
                                // but no type info ÃÂ¢ÃÂÃÂ fall back to
                                // `any` rather than letting the
                                // post-walk TS2304 chain fire.
                                return types.Primitive.any;
                            }
                        }
                    } else if (sk == .fn_decl or sk == .fn_expr) {
                        const fp = hir_mod.fnDeclOf(self.hir, s);
                        if (fp.name != hir_mod.none_node_id and self.hir.kindOf(fp.name) == .identifier) {
                            const fid = hir_mod.identifierOf(self.hir, fp.name);
                            if (fid.name == id.name) {
                                if (self.overloadedFunctionValueType(id.name) catch null) |overload_t| return overload_t;
                                const t = self.hir.typeOf(s);
                                if (t != types.Primitive.none) return self.expandoAugmentedFunctionValueType(id.name, node, t) catch t;
                                if (self.ensurePlainFunctionSignature(s) catch null) |sig| {
                                    return self.expandoAugmentedFunctionValueType(id.name, node, sig) catch sig;
                                }
                                _ = self.reportReturnTypeAnnotationCircularIfActive(s);
                                return types.Primitive.any;
                            }
                        }
                    } else if (sk == .class_decl or sk == .class_expr) {
                        const cp = hir_mod.classOf(self.hir, s);
                        if (cp.name != hir_mod.none_node_id and self.hir.kindOf(cp.name) == .identifier) {
                            const cid = hir_mod.identifierOf(self.hir, cp.name);
                            if (cid.name == id.name) {
                                if (self.class_static_types.get(id.name)) |static_t| return static_t;
                                const t = self.hir.typeOf(s);
                                if (t != types.Primitive.none) return t;
                                return types.Primitive.any;
                            }
                        }
                    } else if (sk == .enum_decl) {
                        // `enum X` / `export enum X` inside a namespace
                        // binds the runtime enum object in value space.
                        // The declaration node still stores the enum's
                        // type-space value (`number`/member union), so a
                        // bare value reference must synthesize `typeof X`.
                        if (self.declarationName(s)) |dname| {
                            if (dname == id.name) {
                                self.reportConstEnumInvalidIdentifierUseIfNeeded(node, s);
                                return self.enumNamespaceValueType(s, id.name) catch types.Primitive.any;
                            }
                        }
                    } else if (sk == .namespace_decl or sk == .module_decl) {
                        // Nested namespaces / modules bind a value
                        // name in the enclosing namespace.
                        if (self.declarationName(s)) |dname| {
                            if (dname == id.name) {
                                const t = self.hir.typeOf(s);
                                if (t != types.Primitive.none) return t;
                                return types.Primitive.any;
                            }
                        }
                    } else if (sk == .import_decl) {
                        if (self.importDeclBindsLocal(s, id.name)) {
                            if (self.moduleNamespaceTypeForLocalImport(id.name, node) catch null) |ns_t| return ns_t;
                            if (self.virtualImportTypeForLocal(id.name, node) catch null) |import_t| return import_t;
                            return types.Primitive.any;
                        }
                    }
                }
                // Merged-namespace fallback: the name isn't declared in
                // THIS namespace's own body, but a dotted name like
                // `namespace my.data.foo {}` shares its `my.data` prefix
                // with a separate `namespace my.data {}` declaration that
                // tsc merges into the same scope. A value exported there
                // (e.g. `buz`) is visible here. See
                // `mergedModuleDeclarationCodeGen3`.
                if (self.mergedEnclosingNamespaceDeclaresValueName(cur, id.name) catch false) {
                    return types.Primitive.any;
                }
            }
            if (k == .for_in_stmt or k == .for_of_stmt) {
                // The loop binding lives directly on the for node;
                // it isn't a sibling in any block. Match against
                // the binding's name slot if it's a let/const/var
                // form, or directly when it's a bare identifier
                // (the parser emits this for `for (let n of ...)`).
                const fr = hir_mod.forInOf(self.hir, cur);
                if (fr.target != hir_mod.none_node_id) {
                    const tk = self.hir.kindOf(fr.target);
                    if (tk == .var_decl or tk == .let_decl or tk == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, fr.target);
                        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                            const vid = hir_mod.identifierOf(self.hir, v.name);
                            if (vid.name == id.name) {
                                const t = self.hir.typeOf(fr.target);
                                if (t != types.Primitive.none) return t;
                            }
                        }
                    } else if (tk == .identifier) {
                        const vid = hir_mod.identifierOf(self.hir, fr.target);
                        if (vid.name == id.name) {
                            if (!self.declared_identifier_lookup) {
                                const t = self.hir.typeOf(fr.target);
                                if (t != types.Primitive.none) return t;
                            }
                        }
                    } else if (tk == .object_pattern or tk == .array_pattern) {
                        const container_t = if (self.hir.typeOf(fr.target) != types.Primitive.none)
                            self.hir.typeOf(fr.target)
                        else
                            types.Primitive.any;
                        if (self.typeOfPatternBinding(fr.target, container_t, id.name)) |bt| {
                            return bt;
                        }
                    }
                }
            }
            if (k == .try_stmt) {
                const ts = hir_mod.tryOf(self.hir, cur);
                if (ts.catch_param != hir_mod.none_node_id) {
                    const ck = self.hir.kindOf(ts.catch_param);
                    if (ck == .identifier) {
                        const cid = hir_mod.identifierOf(self.hir, ts.catch_param);
                        if (cid.name == id.name) {
                            return if (self.strict_flags.use_unknown_in_catch_variables)
                                types.Primitive.unknown
                            else
                                types.Primitive.any;
                        }
                    } else if (ck == .object_pattern or ck == .array_pattern) {
                        if (self.typeOfPatternBinding(ts.catch_param, types.Primitive.any, id.name)) |bt| {
                            return bt;
                        }
                    }
                }
            }
            cur = self.hir.parentOf(cur);
        }

        if (saw_namespace_scope and !self.report_unresolved_in_namespace_scope) {
            // tsc resolves namespace-body value identifiers against
            // the same fallback chain non-namespace identifiers use:
            // module root scope, built-in globals, lib types. When
            // the name is still unresolved after that chain,
            // upstream baselines emit TS2304. The historical
            // behavior here was a hard early-return to `any` which
            // suppressed every TS2304 inside a namespace body ÃÂ¢ÃÂÃÂ
            // parserRealSource5-14 had huge diffs dominated by
            // these missing reports.
            //
            // Preserve the two pre-existing special-case reports
            // (the bare `let` keyword and an errant assignment-
            // modifier target). Otherwise fall through to the
            // shared chain below so TS2304 fires when appropriate.
            // The namespace-body walk above already handled valid
            // local references (including `export <decl>` via the
            // `unwrapExportDecl` call), so reaching this point
            // means the name truly is unresolved.
            if (!self.isDeclNameSlot(node) and std.mem.eql(u8, self.string_interner.get(id.name), "let")) {
                self.reportCannotFindNamePlainOnce(node, id.name) catch {};
                return types.Primitive.any;
            }
            if (!self.isDeclNameSlot(node) and self.namespaceScopeHasErrantModifierAssignmentTarget(node, id.name)) {
                self.reportCannotFindNamePlainOnce(node, id.name) catch {};
                return types.Primitive.any;
            }
        }

        if (self.moduleNamespaceTypeForLocalImport(id.name, node) catch null) |ns_t| return ns_t;
        if (self.virtualImportTypeForLocal(id.name, node) catch null) |import_t| return import_t;
        if (self.virtualDefaultImportTypeForLocal(id.name, node) catch null) |import_t| return import_t;
        if (self.globalAugmentedValueType(id.name, node) catch null) |global_t| return global_t;
        if (!self.isDeclNameSlot(node)) {
            if (self.umdGlobalNamespaceValueType(id.name, node) catch null) |umd_t| return umd_t;
        }
        if (!self.isDeclNameSlot(node) and
            std.mem.eql(u8, name_str, "global") and
            self.rootHasDeclareGlobalAugmentation(node))
        {
            self.reportCannotFindNameOnce(node, id.name) catch {};
            return types.Primitive.any;
        }
        if (self.checkJsTopLevelThisExpandoName(id.name, node)) return types.Primitive.any;
        if (self.nodeIsCallCallee(node)) {
            if (self.jsDocConstructOnlyStaticTypeForIdentifier(node, id.name) catch null) |constructor_t| return constructor_t;
        }
        if (!self.isDeclNameSlot(node) and
            self.sourceHasCheckJsDirective() and
            self.virtualSectionIsJsLike(node))
        {
            if (self.jsConstructorStaticTypeForHeritage(node, id.name) catch null) |constructor_t| return constructor_t;
        }
        if (!self.isDeclNameSlot(node)) {
            if (self.overloadedFunctionValueType(id.name) catch null) |overload_t| return overload_t;
        }
        if (self.enumDeclForNameAt(id.name, node)) |decl| {
            self.reportConstEnumInvalidIdentifierUseIfNeeded(node, decl);
            return self.enumNamespaceValueType(decl, id.name) catch types.Primitive.any;
        }
        if (!self.isDeclNameSlot(node)) {
            const root = self.rootBlockFor(node);
            if (root != hir_mod.none_node_id and self.hir.kindOf(root) == .block_stmt) {
                const one = [_]hir_mod.StringId{id.name};
                if (self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), &one)) |ns_node| {
                    if (self.namespaceHasRuntimeValue(ns_node)) {
                        const ns_t = self.namespaceValueObjectType(ns_node) catch types.Primitive.any;
                        if (self.class_static_types.get(id.name)) |static_t| {
                            const members = [_]TypeId{ static_t, ns_t };
                            return self.interner.internIntersection(&members) catch static_t;
                        }
                        if (self.ambientNamespaceMergedFunctionValueType(ns_node, id.name, node, ns_t) catch null) |merged_t| {
                            return merged_t;
                        }
                        return ns_t;
                    }
                }
            }
        }
        if (self.identifierIsExportEqualsTarget(node)) {
            if (self.findNamedDeclInVirtualSection(node, id.name)) |decl| {
                self.ensureExportAssignmentTargetChecked(decl) catch {};
                if (self.class_static_types.get(id.name)) |static_t| return static_t;
                const t = self.hir.typeOf(decl);
                if (t != types.Primitive.none) return t;
                return types.Primitive.any;
            }
        }
        if (!self.isDeclNameSlot(node)) {
            const root = self.rootBlockFor(node);
            if (root != hir_mod.none_node_id and self.hir.kindOf(root) == .block_stmt) {
                const use_start = self.hir.spanOf(node).start;
                for (hir_mod.blockStmts(self.hir, root)) |stmt| {
                    if (self.hir.spanOf(stmt).start > use_start) break;
                    if (self.resolveValueDeclInStmt(stmt, node, id) catch null) |t| return t;
                }
            }
        }
        if (!self.isDeclNameSlot(node) and self.sourceHasVarDeclarationText(id.name)) return types.Primitive.any;
        if (!self.isDeclNameSlot(node) and !self.nodeHasAncestorKind(node, .typeof_type)) {
            if (self.findLaterTopLevelVarLikeDeclInSameSection(node, id.name)) |later| {
                switch (self.hir.kindOf(later)) {
                    .let_decl, .const_decl => {
                        self.reportBlockScopedUsedBeforeDeclarationSimple(node, id.name) catch {};
                        if (!self.diagnosticExists(node, TsCodes.used_before_assignment)) {
                            self.reportUsedBeforeAssignmentSimple(node, id.name) catch {};
                        }
                        return types.Primitive.any;
                    },
                    else => {},
                }
            }
        }

        // Module-level fallback.
        if (self.module) |module| {
            if (!self.isDeclNameSlot(node) and self.moduleNameIsNamespaceOnlyValue(module, id.name)) {
                // `export = N;` where `N` is a namespace is the
                // CommonJS namespace-export form; tsc does not
                // flag it with TS2708 since the assignment targets
                // the module shape, not a runtime value slot.
                if (!self.identifierIsExportEqualsTarget(node)) {
                    self.reportNamespaceAsValue(node, id.name) catch {};
                }
                return types.Primitive.any;
            }
            if (module.root.lookup(id.name)) |sym| {
                if (self.visibleValueSymbolDeclForNode(sym.decls.items, node)) |initial_decl| {
                    var decl = initial_decl;
                    if (!self.isDeclNameSlot(node)) {
                        for (sym.decls.items) |candidate| {
                            if (!self.valueDeclVisibleFromNode(candidate, node)) continue;
                            const ck = self.hir.kindOf(candidate);
                            if (ck == .import_specifier or
                                ck == .var_decl or ck == .let_decl or ck == .const_decl or
                                ck == .class_decl or ck == .class_expr or
                                ck == .enum_decl or
                                ck == .fn_decl or ck == .fn_expr or
                                ck == .arrow_fn or
                                ((ck == .namespace_decl or ck == .module_decl) and self.namespaceHasRuntimeValue(candidate)))
                            {
                                decl = candidate;
                                break;
                            }
                        }
                    }
                    if (self.hir.kindOf(decl) == .import_specifier) {
                        const parent = self.hir.parentOf(decl);
                        if (parent != hir_mod.none_node_id and self.hir.kindOf(parent) == .import_decl) {
                            const imp = hir_mod.importOf(self.hir, parent);
                            const spec_text = self.string_interner.get(imp.module);
                            const sp = hir_mod.importSpecifierOf(self.hir, decl);
                            if (self.virtualBareModuleExportType(parent, spec_text, sp.imported) catch null) |import_t| return import_t;
                            if (self.programExportedClassTypeForImportBinding(parent, id.name, node) catch null) |class_t| return class_t;
                        }
                    }
                    if (self.moduleNamespaceTypeForImportBinding(decl) catch null) |ns_t| return ns_t;
                    if (self.hir.kindOf(decl) == .class_decl or self.hir.kindOf(decl) == .class_expr) {
                        if (self.class_static_types.get(id.name)) |static_t| return static_t;
                    }
                    if (self.namespaceIsDeclareGlobalAugmentation(decl)) {
                        self.reportCannotFindNameOnce(node, id.name) catch {};
                        return types.Primitive.any;
                    }
                    self.reportDeprecatedDeclarationUse(node, decl, id.name) catch {};
                    if (self.hir.kindOf(decl) == .enum_decl) {
                        self.reportConstEnumInvalidIdentifierUseIfNeeded(node, decl);
                        return self.enumNamespaceValueType(decl, id.name) catch types.Primitive.any;
                    }
                    if (self.hir.kindOf(decl) == .fn_decl or self.hir.kindOf(decl) == .fn_expr) {
                        if (self.overloadedFunctionValueType(id.name) catch null) |overload_t| return overload_t;
                    }
                    if (self.hir.kindOf(decl) == .namespace_decl or self.hir.kindOf(decl) == .module_decl) {
                        if (self.namespaceHasRuntimeValue(decl)) {
                            return self.namespaceValueObjectType(decl) catch types.Primitive.any;
                        }
                    }
                    const dk = self.hir.kindOf(decl);
                    if (dk == .var_decl or dk == .let_decl or dk == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, decl);
                        if (self.declared_identifier_lookup and v.type_annotation != hir_mod.none_node_id) {
                            const declared_t = self.lowerVarDeclTypeAnnotationForIdentifierLookup(id.name, v) catch types.Primitive.any;
                            self.hir.setType(decl, declared_t);
                            if (v.name != hir_mod.none_node_id) self.hir.setType(v.name, declared_t);
                            return declared_t;
                        }
                        if (self.forwardTypeofValueDeclType(node, decl, id.name) catch null) |forward_t| return forward_t;
                    }
                    const t = self.hir.typeOf(decl);
                    if (t != types.Primitive.none) {
                        if (dk == .var_decl or dk == .let_decl or dk == .const_decl) {
                            const v = hir_mod.varDeclOf(self.hir, decl);
                            if (v.name != hir_mod.none_node_id) {
                                const vk = self.hir.kindOf(v.name);
                                if (vk == .object_pattern or vk == .array_pattern) {
                                    if (v.type_annotation != hir_mod.none_node_id) {
                                        const declared_t = self.lowerVarDeclTypeAnnotationForIdentifierLookup(id.name, v) catch types.Primitive.any;
                                        if (self.typeOfPatternBinding(v.name, declared_t, id.name)) |bt| return bt;
                                    }
                                    if (v.init != hir_mod.none_node_id) {
                                        if (self.typeOfPatternBindingFromSource(v.name, v.init, t, id.name) catch null) |bt| return bt;
                                    }
                                    if (self.typeOfPatternBinding(v.name, t, id.name)) |bt| return bt;
                                }
                            }
                        }
                        if (dk == .fn_decl or dk == .fn_expr) {
                            return self.expandoAugmentedFunctionValueType(id.name, node, t) catch t;
                        }
                        return t;
                    }
                    if (dk == .fn_decl or dk == .fn_expr) {
                        _ = self.reportReturnTypeAnnotationCircularIfActive(decl);
                    }
                    if (dk == .var_decl or dk == .let_decl or dk == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, decl);
                        if (v.type_annotation != hir_mod.none_node_id) {
                            const declared_t = self.lowerVarDeclTypeAnnotationForIdentifierLookup(id.name, v) catch types.Primitive.any;
                            self.hir.setType(decl, declared_t);
                            if (v.name != hir_mod.none_node_id) self.hir.setType(v.name, declared_t);
                            return declared_t;
                        }
                    }
                    return types.Primitive.any;
                }
            }
            // Module is bound and the name is unknown ÃÂ¢ÃÂÃÂ emit TS2304
            // unless the identifier is a recognized built-in (e.g.
            // `console`, `undefined`, global constructors). Skip
            // declaration name slots to avoid flagging the very
            // identifier that introduces the name.
            if (!self.isDeclNameSlot(node) and self.isNodeCommonJsGlobalName(id.name)) {
                if (self.rootHasVarDeclarationNamed(node, id.name) or self.sourceHasVarDeclarationText(id.name)) return types.Primitive.any;
                if (self.moduleHasRuntimeNamespacePrefix(module, id.name)) return types.Primitive.any;
                if (self.identifierNamesEnclosingClassExpression(node, id.name)) return types.Primitive.any;
                // In JS-like CommonJS script files, `module` /
                // `require` are part of the implicit environment under
                // tsc's `--allowJs` policy. Once the same `.js` section
                // becomes an external module via top-level import/export
                // (or by `.mjs` extension), upstream no longer injects
                // those globals and reports TS2591 instead.
                if (self.jsLikeSectionHasImplicitCommonJsGlobals(node)) return types.Primitive.any;
                self.reportCannotFindNodeName(node, id.name) catch {};
                return types.Primitive.any;
            }
            if (!self.isDeclNameSlot(node) and self.isBunRuntimeGlobalName(id.name)) {
                if (self.rootHasVarDeclarationNamed(node, id.name) or self.sourceHasVarDeclarationText(id.name)) return types.Primitive.any;
                if (self.moduleHasRuntimeNamespacePrefix(module, id.name)) return types.Primitive.any;
                if (self.identifierNamesEnclosingClassExpression(node, id.name)) return types.Primitive.any;
                if (self.virtualSectionIsJsLike(node)) return types.Primitive.any;
                self.reportCannotFindBunName(node, id.name) catch {};
                return types.Primitive.any;
            }
            if (!self.isDeclNameSlot(node)) {
                // TS2583 ÃÂ¢ÃÂÃÂ lib-gated builtin (e.g. SharedArrayBuffer)
                // is referenced under a target/lib that excludes the
                // declaring tier. Fires *before* the isBuiltinName
                // short-circuit so users get the actionable "change
                // your lib to es2017 or later" guidance.
                if (self.libGatedName(self.string_interner.get(id.name))) |required| {
                    // An explicit `@lib` directive fully determines which libs
                    // are available; `--target` only seeds the default lib set
                    // when `@lib` is absent. So when `@lib` is present, ignore
                    // the target-based exclusion (e.g. `@target: es2015` +
                    // `@lib: esnext` still has Atomics — `esnextSharedMemory`).
                    const has_lib_directive = if (self.source) |s| std.mem.indexOf(u8, s, "@lib") != null else false;
                    const lib_excluded = if (has_lib_directive)
                        self.sourceLibDirectiveExcludes(required)
                    else
                        self.sourceTargetExcludesLib(required);
                    if (lib_excluded) {
                        if (!self.rootHasVarDeclarationNamed(node, id.name) and
                            !self.sourceHasVarDeclarationText(id.name) and
                            !self.moduleHasRuntimeNamespacePrefix(module, id.name) and
                            !self.identifierNamesEnclosingClassExpression(node, id.name) and
                            !self.virtualSectionIsJsLike(node))
                        {
                            self.reportCannotFindNameTargetLibrary(node, id.name, required) catch {};
                            return types.Primitive.any;
                        }
                    }
                }
                if (self.reportLibGatedTypeOnlyValueIfNeeded(node, id.name) catch false) return types.Primitive.any;
                if (self.sourceLibDirectiveExcludesDomElement() and self.domGatedGlobalName(self.string_interner.get(id.name))) {
                    if (!self.rootHasVarDeclarationNamed(node, id.name) and
                        !self.sourceHasVarDeclarationText(id.name) and
                        !self.moduleHasRuntimeNamespacePrefix(module, id.name) and
                        !self.identifierNamesEnclosingClassExpression(node, id.name) and
                        !self.virtualSectionIsJsLike(node))
                    {
                        self.reportCannotFindNameDomLibrary(node, id.name) catch {};
                        return types.Primitive.any;
                    }
                }
            }
            if (!self.isDeclNameSlot(node) and self.identifierIsAccessibilityMemberRoot(node, id.name)) return types.Primitive.any;
            if (!self.isDeclNameSlot(node) and
                (!self.isBuiltinName(id.name) or self.identifierIsPrivateCommonJsExportsReceiver(node, id.name)))
