    fn identifierIsAccessibilityMemberRoot(self: *Checker, node: NodeId, name: hir_mod.StringId) bool {
        const name_str = self.string_interner.get(name);
        if (!(std.mem.eql(u8, name_str, "public") or
            std.mem.eql(u8, name_str, "private") or
            std.mem.eql(u8, name_str, "protected") or
            std.mem.eql(u8, name_str, "static")))
        {
            return false;
        }
        const parent = self.hir.parentOf(node);
        if (parent != hir_mod.none_node_id) {
            switch (self.hir.kindOf(parent)) {
                .member_access => if (hir_mod.memberOf(self.hir, parent).object == node) return true,
                .element_access => if (hir_mod.elementOf(self.hir, parent).object == node) return true,
                else => {},
            }
        }
        const src = self.source orelse return false;
        const sp = self.hir.spanOf(node);
        if (sp.end > src.len) return false;
        var i: usize = sp.end;
        while (i < src.len and (src[i] == ' ' or src[i] == '\t' or src[i] == '\r' or src[i] == '\n')) : (i += 1) {}
        if (i >= src.len) return false;
        return src[i] == '.' or src[i] == '[';
    }

    fn identifierIsPrivateCommonJsExportsReceiver(
        self: *Checker,
        node: NodeId,
        name: hir_mod.StringId,
    ) bool {
        if (!std.mem.eql(u8, self.string_interner.get(name), "exports")) return false;
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .member_access) return false;
        const member = hir_mod.memberOf(self.hir, parent);
        return member.object == node and self.memberNameIsEcmaPrivate(member.name);
    }

    fn identifierNamesEnclosingClassExpression(self: *Checker, node: NodeId, name: hir_mod.StringId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .class_decl and k != .class_expr) continue;
            const c = hir_mod.classOf(self.hir, cur);
            if (c.name == hir_mod.none_node_id or self.hir.kindOf(c.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, c.name).name == name) return true;
        }
        return false;
    }

    fn checkJsTopLevelThisExpandoName(self: *Checker, name: hir_mod.StringId, node: NodeId) bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        if (self.isDeclNameSlot(node)) return false;
        const root = self.rootBlockFor(node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (self.topLevelThisAssignmentName(stmt)) |assigned| {
                if (assigned == name) return true;
            }
        }
        return false;
    }

    fn topLevelThisAssignmentName(self: *Checker, node: NodeId) ?hir_mod.StringId {
        const local = self.unwrapExportDecl(node);
        if (local == hir_mod.none_node_id or self.hir.kindOf(local) != .assignment) return null;
        const a = hir_mod.assignmentOf(self.hir, local);
        if (a.target == hir_mod.none_node_id or self.hir.kindOf(a.target) != .member_access) return null;
        const m = hir_mod.memberOf(self.hir, a.target);
        if (m.object == hir_mod.none_node_id or self.hir.kindOf(m.object) != .identifier) return null;
        const obj = hir_mod.identifierOf(self.hir, m.object);
        if (!std.mem.eql(u8, self.string_interner.get(obj.name), "this")) return null;
        return m.name;
    }

    /// True when `object_node` is a bare identifier naming a type-only
    /// namespace (one with no runtime value side) — i.e. a namespace
    /// being used as a value, which tsc flags with TS2708. Used to
    /// suppress the redundant missing-member TS2339 on `typeof M`.
    fn memberAccessObjectIsNamespaceAsValue(self: *Checker, object_node: NodeId) bool {
        if (object_node == hir_mod.none_node_id or self.hir.kindOf(object_node) != .identifier) return false;
        const module = self.module orelse return false;
        const id = hir_mod.identifierOf(self.hir, object_node);
        return self.moduleNameIsNamespaceOnlyValue(module, id.name);
    }

    fn moduleNameIsNamespaceOnlyValue(
        self: *Checker,
        module: *const binder_mod.Module,
        name: hir_mod.StringId,
    ) bool {
        _ = module.root.namespaces.get(name) orelse return false;
        const value_sym = module.root.values.get(name) orelse return true;
        for (value_sym.decls.items) |decl| {
            if (self.hir.kindOf(decl) != .namespace_decl) return false;
            if (self.namespaceHasRuntimeValue(decl)) return false;
        }
        return true;
    }

    fn moduleHasRuntimeNamespacePrefix(
        self: *Checker,
        module: *const binder_mod.Module,
        name: hir_mod.StringId,
    ) bool {
        const prefix = self.string_interner.get(name);
        var it = module.root.namespaces.iterator();
        while (it.next()) |entry| {
            const ns_name = self.string_interner.get(entry.key_ptr.*);
            if (ns_name.len <= prefix.len) continue;
            if (!std.mem.startsWith(u8, ns_name, prefix)) continue;
            if (ns_name[prefix.len] != '.') continue;
            const sym = entry.value_ptr.*;
            for (sym.decls.items) |decl| {
                if (self.namespaceHasRuntimeValue(decl)) return true;
            }
        }
        return false;
    }

    fn namespaceHasRuntimeValue(self: *Checker, node: NodeId) bool {
        return self.namespaceHasRuntimeValueDepth(node, 0);
    }

    fn namespaceHasRuntimeValueDepth(self: *Checker, node: NodeId, depth: u8) bool {
        if (depth > 32) return false;
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .namespace_decl) return false;
        if (self.declarationSourceHasLeadingDeclare(node) or self.virtualSectionIsDeclarationFile(node)) return true;
        for (hir_mod.namespaceBody(self.hir, node)) |raw| {
            const s = self.unwrapExportDecl(raw);
            switch (self.hir.kindOf(s)) {
                .var_decl,
                .let_decl,
                .const_decl,
                .fn_decl,
                .fn_expr,
                .class_decl,
                .class_expr,
                .enum_decl,
                => return true,
                .block_stmt => return true,
                .namespace_decl => if (self.namespaceHasRuntimeValueDepth(s, depth + 1)) return true,
                .import_decl => if (self.importEqualsTargetHasRuntimeValue(s, depth + 1)) return true,
                else => {},
            }
        }
        return false;
    }

    fn importEqualsAliasName(self: *Checker, import_node: NodeId) ?hir_mod.StringId {
        if (import_node == hir_mod.none_node_id or self.hir.kindOf(import_node) != .import_decl) return null;
        const imp = hir_mod.importOf(self.hir, import_node);
        if (imp.import_equals == hir_mod.none_node_id) return null;
        if (imp.default_binding == hir_mod.none_node_id or self.hir.kindOf(imp.default_binding) != .identifier) return null;
        return hir_mod.identifierOf(self.hir, imp.default_binding).name;
    }

    fn importDeclHasExportKeyword(self: *Checker, import_node: NodeId) bool {
        if (import_node == hir_mod.none_node_id or self.hir.kindOf(import_node) != .import_decl) return false;
        const src = self.source orelse return false;
        const sp = self.hir.spanOf(import_node);
        if (sp.start >= sp.end or sp.end > src.len) return false;
        const text = std.mem.trim(u8, src[sp.start..sp.end], " \t\r\n");
        if (std.mem.startsWith(u8, text, "export") and
            (text.len == "export".len or !isAsciiWordChar(text["export".len]))) return true;
        var line_start: usize = sp.start;
        while (line_start > 0 and src[line_start - 1] != '\n' and src[line_start - 1] != '\r') : (line_start -= 1) {}
        const prefix = std.mem.trim(u8, src[line_start..sp.start], " \t\r\n");
        return std.mem.eql(u8, prefix, "export");
    }

    fn importEqualsTargetHasRuntimeValue(self: *Checker, import_node: NodeId, depth: u8) bool {
        if (depth > 32) return false;
        if (import_node == hir_mod.none_node_id or self.hir.kindOf(import_node) != .import_decl) return false;
        // Cycle guard: the target-resolution path
        // (`importEqualsTargetDecl -> findNamedValueDeclInNamespace ->
        // declCreatesRuntimeValue`) resets the numeric depth to 0 each
        // hop, so a self-referential import (`import string =
        // test.istring`) would recurse forever past the depth cap.
        // Re-entry for the same import node means we're mid-resolution
        // on a cycle → it cannot establish a runtime value.
        if (self.import_equals_runtime_in_progress.contains(import_node)) return false;
        self.import_equals_runtime_in_progress.put(self.gpa, import_node, {}) catch {};
        defer _ = self.import_equals_runtime_in_progress.remove(import_node);
        const imp = hir_mod.importOf(self.hir, import_node);
        if (imp.import_equals == hir_mod.none_node_id or self.hir.kindOf(imp.import_equals) != .type_ref) return false;
        const r = hir_mod.typeRefOf(self.hir, imp.import_equals);
        const qualifiers = hir_mod.typeRefQualifier(self.hir, imp.import_equals);
        if (qualifiers.len == 0) {
            return self.unqualifiedImportEqualsTargetHasRuntimeValue(r.name, depth + 1);
        }
        const target = self.importEqualsTargetDecl(imp.import_equals) orelse return false;
        if (self.declCreatesRuntimeValue(target, depth + 1)) return true;
        return self.importEqualsMergedTargetHasRuntimeValue(imp.import_equals, depth + 1);
    }

    fn importEqualsMergedTargetHasRuntimeValue(self: *Checker, type_ref_node: NodeId, depth: u8) bool {
        if (depth > 32 or type_ref_node == hir_mod.none_node_id or self.hir.kindOf(type_ref_node) != .type_ref) return false;
        const ref = hir_mod.typeRefOf(self.hir, type_ref_node);
        const qualifiers = hir_mod.typeRefQualifier(self.hir, type_ref_node);
        if (qualifiers.len == 0) return false;
        var path: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer path.deinit(self.gpa);
        for (qualifiers) |qualifier| {
            if (self.hir.kindOf(qualifier) != .identifier) return false;
            path.append(self.gpa, hir_mod.identifierOf(self.hir, qualifier).name) catch return false;
        }
        const root = self.rootBlockFor(type_ref_node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        const parent_namespace = self.findNamespaceByPath(hir_mod.blockStmts(self.hir, root), path.items) orelse return false;
        for (hir_mod.namespaceBody(self.hir, parent_namespace)) |raw| {
            const decl = self.unwrapExportDecl(raw);
            const name = self.declarationName(decl) orelse continue;
            if (name != ref.name) continue;
            if (self.declCreatesRuntimeValue(decl, depth + 1)) return true;
        }
        return false;
    }

    fn unqualifiedImportEqualsTargetHasRuntimeValue(self: *Checker, name: hir_mod.StringId, depth: u8) bool {
        if (depth > 32) return false;
        const root = if (self.hir.nodeCount() > 1) self.rootBlockFor(1) else hir_mod.none_node_id;
        const stmts = if (root != hir_mod.none_node_id and self.hir.kindOf(root) == .block_stmt)
            hir_mod.blockStmts(self.hir, root)
        else
            &[_]NodeId{};
        for (stmts) |raw| {
            const decl = self.unwrapExportDecl(raw);
            const decl_name = self.declarationName(decl) orelse continue;
            if (decl_name != name) continue;
            if (self.declCreatesRuntimeValue(decl, depth + 1)) return true;
        }
        return false;
    }

    fn declCreatesRuntimeValue(self: *Checker, decl: NodeId, depth: u8) bool {
        if (depth > 32) return false;
        return switch (self.hir.kindOf(decl)) {
            .var_decl,
            .let_decl,
            .const_decl,
            .fn_decl,
            .fn_expr,
            .class_decl,
            .class_expr,
            .enum_decl,
            => true,
            .namespace_decl => self.namespaceHasRuntimeValueDepth(decl, depth + 1),
            .import_decl => self.importEqualsTargetHasRuntimeValue(decl, depth + 1),
            else => false,
        };
    }

    fn reportNamespaceAsValue(
        self: *Checker,
        node: NodeId,
        name: hir_mod.StringId,
    ) !void {
        const name_str = self.string_interner.get(name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Cannot use namespace '{s}' as a value.",
            .{name_str},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.namespace_as_value,
            .message = msg,
        });
    }

    /// True when `node` is the target identifier of an
    /// `export = <ident>;` statement. The parser models export
    /// assignment as an `export_decl` whose `decl` slot points
    /// directly at the assigned expression (no `from` module,
    /// no named specifiers). Used to suppress TS2708 ÃÂ¢ÃÂÃÂ a CJS
    /// namespace export is allowed even when the named binding
    /// has no runtime value.
    fn identifierIsExportEqualsTarget(self: *Checker, node: NodeId) bool {
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(parent) != .export_decl) return false;
        const ex = hir_mod.exportOf(self.hir, parent);
        if (ex.decl != node) return false;
        if (ex.named_len != 0) return false;
        if (ex.is_default) return false;
        const module_str = self.string_interner.get(ex.module);
        return module_str.len == 0;
    }

    /// Does this name refer to a class declaration with one or more
    /// type parameters in the current source? Used by the `new C<...>()`
    /// validity check to short-circuit TS2347 when the class is generic
    /// but its constructor sig hasn't been recorded (the class member
    /// pass and call-expr pass aren't ordered, and a class without an
    /// explicit constructor never lands in `class_constructor_sigs`).
    fn classNameRefersToGenericDecl(self: *Checker, name: hir_mod.StringId, ctx_node: NodeId) bool {
        const root = self.rootBlockFor(ctx_node);
        if (self.hir.kindOf(root) != .block_stmt) return false;
        const stmts = hir_mod.blockStmts(self.hir, root);
        for (stmts) |s| {
            const k = self.hir.kindOf(s);
            const decl = if (k == .class_decl) s else blk: {
                if (k != .export_decl) break :blk hir_mod.none_node_id;
                const ex = hir_mod.exportOf(self.hir, s);
                if (ex.decl == hir_mod.none_node_id) break :blk hir_mod.none_node_id;
                if (self.hir.kindOf(ex.decl) != .class_decl) break :blk hir_mod.none_node_id;
                break :blk ex.decl;
            };
            if (decl == hir_mod.none_node_id) continue;
            const c = hir_mod.classOf(self.hir, decl);
            if (c.name == hir_mod.none_node_id or self.hir.kindOf(c.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, c.name).name != name) continue;
            if (c.type_params_len > 0) return true;
        }
        return false;
    }

    /// Recognize a small set of common globals that should not
    /// trigger TS2304 even though we don't have a real lib.d.ts
    /// loaded yet. The list intentionally errs on the conservative
    /// side; expand as more globals are encountered.
    /// True if `name_str` is a built-in global whose declaration
    /// lives in a lib later than ES5 (e.g. `SharedArrayBuffer` ships
    /// in `lib.es2017.sharedmemory.d.ts`). Returns the minimum lib
    /// string the user needs to enable, or null when the name is not
    /// lib-gated. Used to emit TS2583 ("Cannot find name 'X'. Do you
    /// need to change your target library?") in fixtures that pin
    /// `@lib: es5` explicitly. Conservative: only the names whose
    /// upstream baselines we actually need are listed here.
    fn libGatedName(self: *const Checker, name_str: []const u8) ?[]const u8 {
        _ = self;
        const Entry = struct { name: []const u8, required: []const u8 };
        const gated = [_]Entry{
            .{ .name = "SharedArrayBuffer", .required = "es2017" },
            .{ .name = "Atomics", .required = "es2017" },
        };
        for (gated) |g| {
            if (std.mem.eql(u8, name_str, g.name)) return g.required;
        }
        return null;
    }

    fn libGatedTypeOnlyValueName(self: *const Checker, name_str: []const u8) ?[]const u8 {
        _ = self;
        if (std.mem.eql(u8, name_str, "Symbol")) return "es2015";
        if (std.mem.eql(u8, name_str, "Promise")) return "es2015";
        return null;
    }

    fn reportLibGatedTypeOnlyValueIfNeeded(self: *Checker, node: NodeId, name: hir_mod.StringId) CheckError!bool {
        const required = self.libGatedTypeOnlyValueName(self.string_interner.get(name)) orelse return false;
        if (!self.sourceTargetExcludesLib(required) and !self.sourceLibDirectiveExcludes(required)) return false;
        if (self.rootHasVarDeclarationNamed(node, name) or self.sourceHasVarDeclarationText(name)) return false;
        if (self.module) |module| {
            if (self.moduleHasRuntimeNamespacePrefix(module, name)) return false;
        }
        if (self.identifierNamesEnclosingClassExpression(node, name)) return false;
        if (self.virtualSectionIsJsLike(node)) return false;
        try self.reportTypeOnlyUsedAsValueTargetLibrary(node, name, required);
        return true;
    }

    fn domGatedGlobalName(self: *const Checker, name_str: []const u8) bool {
        _ = self;
        return std.mem.eql(u8, name_str, "console");
    }

    /// True when the source-file lib directive (e.g. `// @lib: es5`)
    /// excludes the minimum-required lib tier reported by
    /// `libGatedName`. Mirrors `sourceLibDirectiveNeedsIterableIterator`
    /// in spirit; the comparison is intentionally name-prefix based
    /// (any `es2017*` lib counts as covering es2017, etc.).
    fn sourceLibDirectiveExcludes(self: *Checker, required: []const u8) bool {
        const src = self.source orelse return false;
        const lib_pos = std.mem.indexOf(u8, src, "@lib") orelse return false;
        const line_end = std.mem.indexOfScalarPos(u8, src, lib_pos, '\n') orelse src.len;
        var buf: [256]u8 = undefined;
        const raw_line = std.mem.trim(u8, src[lib_pos..line_end], " \t\r");
        const n = @min(raw_line.len, buf.len);
        const line = std.ascii.lowerString(buf[0..n], raw_line[0..n]);
        return !libLineCoversRequired(line, required);
    }

    fn sourceLibDirectiveExcludesExplicitResourceManagement(self: *Checker) bool {
        const src = self.source orelse return false;
        const lib_pos = std.mem.indexOf(u8, src, "@lib") orelse return false;
        const line_end = std.mem.indexOfScalarPos(u8, src, lib_pos, '\n') orelse src.len;
        var buf: [256]u8 = undefined;
        const raw_line = std.mem.trim(u8, src[lib_pos..line_end], " \t\r");
        const n = @min(raw_line.len, buf.len);
        const line = std.ascii.lowerString(buf[0..n], raw_line[0..n]);
        const colon = std.mem.indexOfScalar(u8, line, ':') orelse return true;
        var libs = std.mem.splitScalar(u8, line[colon + 1 ..], ',');
        while (libs.next()) |raw_lib| {
            const selected_lib = std.mem.trim(u8, raw_lib, " \t\r");
            if (std.mem.eql(u8, selected_lib, "esnext") or std.mem.eql(u8, selected_lib, "esnext.disposable")) return false;
        }
        return true;
    }

    fn sourceLibDirectiveExcludesDomElement(self: *Checker) bool {
        if (self.sourceHasNoLibTrueDirective()) return true;
        if (self.sourceHasReferenceLibDirective("dom")) return false;
        const src = self.source orelse return false;
        const lib_pos = std.mem.indexOf(u8, src, "@lib") orelse return false;
        const line_end = std.mem.indexOfScalarPos(u8, src, lib_pos, '\n') orelse src.len;
        var buf: [256]u8 = undefined;
        const raw_line = std.mem.trim(u8, src[lib_pos..line_end], " \t\r");
        const n = @min(raw_line.len, buf.len);
        const line = std.ascii.lowerString(buf[0..n], raw_line[0..n]);
        return std.mem.indexOf(u8, line, "dom") == null;
    }

    /// True if a lib-gated builtin (e.g. `SharedArrayBuffer`) is
    /// unavailable in the active emit target. Pinned to the small set
    /// of `--target` strings tsc reports TS2583 against; defaults to
    /// false when no `@target` directive is present (the harness
    /// runs in target=esnext, which covers everything).
    fn sourceTargetExcludesLib(self: *Checker, required: []const u8) bool {
        const src = self.source orelse return false;
        const target_pos = std.mem.indexOf(u8, src, "@target") orelse return false;
        const line_end = std.mem.indexOfScalarPos(u8, src, target_pos, '\n') orelse src.len;
        var buf: [256]u8 = undefined;
        const raw_line = std.mem.trim(u8, src[target_pos..line_end], " \t\r");
        const n = @min(raw_line.len, buf.len);
        const line = std.ascii.lowerString(buf[0..n], raw_line[0..n]);
        if (libLineCoversRequired(line, required)) return false;
        const required_rank = libTierRank(required) orelse return false;
        if (std.mem.indexOf(u8, line, "es3") != null or std.mem.indexOf(u8, line, "es5") != null) return true;
        if (required_rank > 2015 and (std.mem.indexOf(u8, line, "es6") != null or std.mem.indexOf(u8, line, "es2015") != null)) return true;
        if (required_rank > 2016 and std.mem.indexOf(u8, line, "es2016") != null) return true;
        if (required_rank > 2017 and std.mem.indexOf(u8, line, "es2017") != null) return true;
        if (required_rank > 2018 and std.mem.indexOf(u8, line, "es2018") != null) return true;
        if (required_rank > 2019 and std.mem.indexOf(u8, line, "es2019") != null) return true;
        return false;
    }

    fn libTierRank(required: []const u8) ?u16 {
        if (std.mem.eql(u8, required, "es2015") or std.mem.eql(u8, required, "es6")) return 2015;
        if (std.mem.eql(u8, required, "es2016")) return 2016;
        if (std.mem.eql(u8, required, "es2017")) return 2017;
        if (std.mem.eql(u8, required, "es2018")) return 2018;
        if (std.mem.eql(u8, required, "es2019")) return 2019;
        if (std.mem.eql(u8, required, "es2020")) return 2020;
        if (std.mem.eql(u8, required, "es2021")) return 2021;
        if (std.mem.eql(u8, required, "es2022")) return 2022;
        if (std.mem.eql(u8, required, "es2023")) return 2023;
        if (std.mem.eql(u8, required, "es2024")) return 2024;
        return null;
    }

    fn libLineCoversRequired(line: []const u8, required: []const u8) bool {
        if (std.mem.indexOf(u8, line, "esnext") != null) return true;
        const required_rank = libTierRank(required) orelse return false;
        if (required_rank <= 2015 and (std.mem.indexOf(u8, line, "es6") != null or std.mem.indexOf(u8, line, "es2015") != null)) return true;
        if (required_rank <= 2016 and std.mem.indexOf(u8, line, "es2016") != null) return true;
        if (required_rank <= 2017 and std.mem.indexOf(u8, line, "es2017") != null) return true;
        if (required_rank <= 2018 and std.mem.indexOf(u8, line, "es2018") != null) return true;
        if (required_rank <= 2019 and std.mem.indexOf(u8, line, "es2019") != null) return true;
        if (required_rank <= 2020 and std.mem.indexOf(u8, line, "es2020") != null) return true;
        if (required_rank <= 2021 and std.mem.indexOf(u8, line, "es2021") != null) return true;
        if (required_rank <= 2022 and std.mem.indexOf(u8, line, "es2022") != null) return true;
        if (required_rank <= 2023 and std.mem.indexOf(u8, line, "es2023") != null) return true;
        if (required_rank <= 2024 and std.mem.indexOf(u8, line, "es2024") != null) return true;
        return false;
    }

    fn libGatedPropertyMember(self: *Checker, receiver_t: TypeId, member_name: hir_mod.StringId) ?[]const u8 {
        const name = self.string_interner.get(member_name);
        if (self.typeHasStringPrimitivePart(receiver_t)) {
            if (std.mem.eql(u8, name, "includes")) return "es2015";
        }
        // `Object.values` / `Object.entries` arrived in es2017 — under
        // an earlier lib the (always-seeded) member reports TS2550.
        // Mirrors `useObjectValuesAndEntries3`.
        if (receiver_t != types.Primitive.none and receiver_t == self.lib_cache.object_global) {
            if (std.mem.eql(u8, name, "values") or std.mem.eql(u8, name, "entries")) return "es2017";
        }
        return null;
    }

    fn reportLibGatedPropertyAccess(self: *Checker, node: hir_mod.NodeId, receiver_t: TypeId, member_name: hir_mod.StringId) CheckError!bool {
        const required = self.libGatedPropertyMember(receiver_t, member_name) orelse return false;
        const has_lib_directive = if (self.source) |src| std.mem.indexOf(u8, src, "@lib") != null else false;
        if (has_lib_directive) {
            if (!self.sourceLibDirectiveExcludes(required)) return false;
        } else if (!self.sourceTargetExcludesLib(required)) return false;

        const prop_name = self.string_interner.get(member_name);
        const receiver_name = if (receiver_t != types.Primitive.none and receiver_t == self.lib_cache.object_global)
            "ObjectConstructor"
        else
            (try self.allocSimpleTypeName(receiver_t)) orelse "type";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Property '{s}' does not exist on type '{s}'. Do you need to change your target library? Try changing the 'lib' compiler option to '{s}' or later.",
            .{ prop_name, receiver_name, required },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = self.memberAccessNamePos(node),
            .code = TsCodes.property_does_not_exist_target_library,
            .message = msg,
        });
        return true;
    }

    fn isBuiltinName(self: *const Checker, name: hir_mod.StringId) bool {
        const s = self.string_interner.get(name);
        if (std.mem.eql(u8, s, "ITextWriter")) {
            const src = self.source orelse return true;
            const lib_pos = std.mem.indexOf(u8, src, "@lib") orelse return true;
            const line_end = std.mem.indexOfScalarPos(u8, src, lib_pos, '\n') orelse src.len;
            return std.mem.indexOf(u8, src[lib_pos..line_end], "scripthost") != null;
        }
        if (std.mem.eql(u8, s, "Iterator") or
            std.mem.eql(u8, s, "fetch") or
            std.mem.eql(u8, s, "Image")) return true;
        const builtins = [_][]const u8{
            // Core globals / values.
            "console",                "undefined",                    "NaN",
            "Infinity",               "globalThis",                   "this",
            "new.target",             "window",                       "self",
            "top",                    "document",
