    /// Common type-only names from `lib.es5.d.ts` (and friends) that
    /// appear in v0 fixtures as bodyless-signature type annotations.
    /// Without this whitelist, `reportUnresolvedBodylessSignatureTypeRefs`
    /// emits a spurious TS2304 for e.g. `PropertyDescriptor`,
    /// `DecoratorContext`, `ClassDecorator`, etc., which TS recognizes
    /// from the default lib. Add new names here as fixtures surface
    /// them; the list is intentionally narrow (no value-namespace
    /// entries ÃÂ¢ÃÂÃÂ those live in `isBuiltinName`).
    fn isLibEs5TypeName(self: *const Checker, raw: []const u8) bool {
        _ = self;
        const names = [_][]const u8{
            "PropertyDescriptor",
            "PropertyDescriptorMap",
            "DecoratorContext",
            "ClassDecorator",
            "ClassFieldDecoratorContext",
            "ClassGetterDecoratorContext",
            "ClassSetterDecoratorContext",
            "ClassMethodDecoratorContext",
            "ClassAccessorDecoratorContext",
            "ClassAccessorDecoratorTarget",
            "ClassAccessorDecoratorResult",
            "ClassDecoratorContext",
            "ClassMemberDecoratorContext",
            "PropertyKey",
            "ThisType",
            "FlatArray",
            "Thenable",
            "Lock",
        };
        for (names) |n| {
            if (std.mem.eql(u8, raw, n)) return true;
        }
        return false;
    }

    fn isDefaultLibTypeOnlyFallbackName(self: *const Checker, raw: []const u8) bool {
        if (!self.isLibEs5TypeName(raw)) return false;
        // `ThisType<T>` has contextual-this semantics modeled explicitly in
        // the generic type-ref path; the rest are safe structural placeholders
        // until the full default lib is loaded.
        return !std.mem.eql(u8, raw, "ThisType");
    }

    fn isNodeCommonJsGlobalName(self: *const Checker, name: hir_mod.StringId) bool {
        const s = self.string_interner.get(name);
        const names = [_][]const u8{
            "module",
            "require",
        };
        for (names) |n| {
            if (std.mem.eql(u8, s, n)) return true;
        }
        return false;
    }

    fn isKnownNodeBuiltinSpecifier(self: *const Checker, spec: []const u8) bool {
        _ = self;
        if (!std.mem.startsWith(u8, spec, "node:")) return false;
        const name = spec["node:".len..];
        const builtins = [_][]const u8{
            "assert",
            "async_hooks",
            "buffer",
            "child_process",
            "cluster",
            "console",
            "constants",
            "crypto",
            "dgram",
            "diagnostics_channel",
            "dns",
            "domain",
            "events",
            "fs",
            "http",
            "http2",
            "https",
            "inspector",
            "module",
            "net",
            "os",
            "path",
            "perf_hooks",
            "process",
            "punycode",
            "querystring",
            "readline",
            "repl",
            "stream",
            "string_decoder",
            "timers",
            "tls",
            "trace_events",
            "tty",
            "url",
            "util",
            "v8",
            "vm",
            "worker_threads",
            "zlib",
        };
        for (builtins) |builtin| {
            if (std.mem.eql(u8, name, builtin)) return true;
            if (name.len > builtin.len and name[builtin.len] == '/' and std.mem.eql(u8, name[0..builtin.len], builtin)) return true;
        }
        return false;
    }

    fn calleeIdentifierIsParenthesized(self: *Checker, callee: NodeId) bool {
        const src = self.source orelse return false;
        const span = self.hir.spanOf(callee);
        if (span.start == 0 or span.start > src.len) return false;
        var i: usize = span.start;
        while (i > 0) {
            i -= 1;
            switch (src[i]) {
                ' ', '\t', '\r', '\n' => continue,
                '(' => return true,
                else => return false,
            }
        }
        return false;
    }

    /// Upstream rejects the special `arguments` binding in class fields
    /// and static blocks. Arrow functions are transparent for this walk;
    /// ordinary functions bind their own `arguments` object and stop it.
    /// Bitset returned by `argumentsClassContext`: which class-member
    /// position (if any) the nearest non-arrow ancestor of an
    /// `arguments` reference resolves to.
    const ArgumentsClassContext = enum { none, property_initializer, static_block };

    fn argumentsClassContext(self: *Checker, node: NodeId) ArgumentsClassContext {
        var cur = node;
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (cur != node and (k == .fn_decl or k == .fn_expr or k == .arrow_fn)) {
                const f = hir_mod.fnDeclOf(self.hir, cur);
                if (!f.flags.is_arrow) return .none;
            }
            if (k == .object_property) {
                const parent = self.hir.parentOf(cur);
                if (parent != hir_mod.none_node_id) {
                    const pk = self.hir.kindOf(parent);
                    if (pk == .class_decl or pk == .class_expr) return .property_initializer;
                }
            } else if (k == .block_stmt) {
                const parent = self.hir.parentOf(cur);
                if (parent != hir_mod.none_node_id) {
                    const pk = self.hir.kindOf(parent);
                    if (pk == .class_decl or pk == .class_expr) {
                        for (hir_mod.classMembers(self.hir, parent)) |member| {
                            if (member == cur) return .static_block;
                        }
                    }
                }
            }
        }
        return .none;
    }

    fn argumentsInClassPropertyInitializerOrStaticBlock(self: *Checker, node: NodeId) bool {
        return self.argumentsClassContext(node) != .none;
    }

    fn staticBlockClassDeclaresArguments(self: *Checker, node: NodeId) ?NodeId {
        const arguments_name = self.string_interner.intern("arguments") catch return null;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const kind = self.hir.kindOf(cur);
            if (kind != .class_decl and kind != .class_expr) continue;
            for (hir_mod.classMembers(self.hir, cur)) |member| {
                if (self.hir.kindOf(member) != .block_stmt) continue;
                for (hir_mod.blockStmts(self.hir, member)) |stmt| {
                    const stmt_kind = self.hir.kindOf(stmt);
                    if (stmt_kind != .var_decl and stmt_kind != .let_decl and stmt_kind != .const_decl) continue;
                    const declaration = hir_mod.varDeclOf(self.hir, stmt);
                    if (declaration.name == hir_mod.none_node_id or self.hir.kindOf(declaration.name) != .identifier) continue;
                    if (hir_mod.identifierOf(self.hir, declaration.name).name == arguments_name) return cur;
                }
            }
            return null;
        }
        return null;
    }

    fn hasNonArrowFunctionAncestor(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) continue;
            const f = hir_mod.fnDeclOf(self.hir, cur);
            if (!f.flags.is_arrow) return true;
        }
        return false;
    }

    fn argumentsObjectType(self: *Checker) CheckError!TypeId {
        const name = self.string_interner.intern("IArguments") catch return error.OutOfMemory;
        if (self.type_names.get(name)) |t| return t;
        const length_name = self.string_interner.intern("length") catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{.{
            .name = length_name,
            .type = types.Primitive.number_t,
            .is_optional = false,
            .is_readonly = false,
            .is_method = false,
        }};
        // lib.es5's `IArguments` carries a numeric index signature
        // (`[index: number]: any`), so `arguments[i]` is a valid `any` access.
        // Without it, indexing `arguments` under `noImplicitAny` over-reports
        // TS7053. Pins paramTagOnFunctionUsingArguments.
        const t = self.interner.internObjectTypeWithIndex(&members, types.Primitive.none, types.Primitive.any) catch return error.OutOfMemory;
        try self.type_names.put(self.gpa, name, t);
        if (!self.builtin_object_names.contains(t)) {
            try self.builtin_object_names.put(self.gpa, t, "IArguments");
        }
        return t;
    }

    /// True when the nearest enclosing function-like ancestor of
    /// `node` is an arrow function (i.e. `arguments` here would
    /// resolve through the lexical chain instead of binding to a
    /// local `arguments` slot). Used to gate TS2496 (`arguments` in
    /// arrow function in ES5): tsc rejects every `arguments`
    /// reference whose innermost containing function is an arrow,
    /// regardless of whether further out there's a real function ÃÂ¢ÃÂÃÂ
    /// the down-emit can't synthesize an `arguments` slot inside the
    /// resulting `function () { ÃÂ¢ÃÂÃÂ¦ }`. Top-level `() => arguments`
    /// also matches: `cur` is `none_node_id` after the arrow, so the
    /// `saw_arrow` flag still answers "yes, I was inside an arrow".
    fn argumentsInsideArrowOnlyChain(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) continue;
            const f = hir_mod.fnDeclOf(self.hir, cur);
            return f.flags.is_arrow;
        }
        return false;
    }

    fn argumentsInsideAsyncNonArrowFunction(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const kind = self.hir.kindOf(cur);
            if (kind != .fn_decl and kind != .fn_expr and kind != .arrow_fn) continue;
            const function = hir_mod.fnDeclOf(self.hir, cur);
            return function.flags.is_async and !function.flags.is_arrow;
        }
        return false;
    }

    /// True when the identifier reference (e.g. `arguments`) resolves
    /// to a parameter of the *immediate* enclosing function/arrow,
    /// rather than the runtime `arguments` object. Used to suppress
    /// TS2496 only for `(arguments) => arguments` where the inner
    /// reference shadows the slot directly via its own arrow's
    /// parameter list. A reference one level out (e.g.
    /// `(arguments) => () => arguments` ÃÂ¢ÃÂÃÂ fixture 07) must still emit
    /// TS2496 because the inner arrow has no `arguments` parameter
    /// and the down-emit cannot synthesize a slot for it. Mirrors
    /// `emitArrowFunctionWhenUsingArguments08` (suppress) vs
    /// `ÃÂ¢ÃÂÃÂ¦07` (emit).
    fn argumentsResolvesToLocalBinding(self: *Checker, node: NodeId, name_id: hir_mod.StringId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) continue;
            const params = hir_mod.fnParams(self.hir, cur);
            for (params) |p| {
                if (self.hir.kindOf(p) != .parameter) continue;
                const pp = hir_mod.parameterOf(self.hir, p);
                if (pp.name == hir_mod.none_node_id) continue;
                if (self.hir.kindOf(pp.name) != .identifier) continue;
                const pid = hir_mod.identifierOf(self.hir, pp.name);
                if (pid.name == name_id) return true;
            }
            // Only inspect the innermost enclosing function ÃÂ¢ÃÂÃÂ references
            // that escape it via the lexical chain still want TS2496
            // when the surrounding ES5 emit can't synthesize a slot.
            return false;
        }
        return false;
    }

    const MapEntryTypes = struct {
        key: TypeId,
        value: TypeId,
        invalid_mixed_value_entries: bool = false,
    };

    fn inferMapEntryTypes(self: *Checker, args: []const NodeId) CheckError!MapEntryTypes {
        if (args.len == 0 or self.hir.kindOf(args[0]) != .array_literal) {
            return .{ .key = types.Primitive.any, .value = types.Primitive.any };
        }
        var key_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer key_types.deinit(self.gpa);
        var value_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer value_types.deinit(self.gpa);
        var first_value_t: TypeId = types.Primitive.none;
        var invalid_mixed_value_entries = false;
        for (hir_mod.arrayLiteralElements(self.hir, args[0])) |entry_node| {
            if (entry_node == hir_mod.none_node_id or self.hir.kindOf(entry_node) != .array_literal) continue;
            const entry_elems = hir_mod.arrayLiteralElements(self.hir, entry_node);
            if (entry_elems.len < 2) continue;
            const raw_key_t = try self.checkExpression(entry_elems[0]);
            const key_t = if (raw_key_t < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(raw_key_t).is_enum_literal)
                self.widenLiteralType(raw_key_t)
            else
                raw_key_t;
            try key_types.append(self.gpa, key_t);
            const raw_value_t = try self.checkExpression(entry_elems[1]);
            const value_t = if (raw_value_t < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(raw_value_t).is_enum_literal)
                self.widenLiteralType(raw_value_t)
            else
                raw_value_t;
            try value_types.append(self.gpa, value_t);
            if (first_value_t == types.Primitive.none) {
                first_value_t = value_t;
            } else if (!(self.engine.isAssignableTo(value_t, first_value_t) catch true)) {
                invalid_mixed_value_entries = true;
            }
        }
        return .{
            .key = try self.unionOrAny(key_types.items),
            .value = try self.unionMapValueTypes(value_types.items),
            .invalid_mixed_value_entries = invalid_mixed_value_entries,
        };
    }

    fn unionMapValueTypes(self: *Checker, items: []const TypeId) CheckError!TypeId {
        if (items.len == 0) return types.Primitive.any;
        var elem_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer elem_types.deinit(self.gpa);
        for (items) |item| {
            const elem_t = self.interner.objectNumberIndex(item);
            if (elem_t == types.Primitive.none) return try self.unionOrAny(items);
            try elem_types.append(self.gpa, elem_t);
        }
        const elem_t = try self.inferArrayLiteralElementType(elem_types.items);
        return self.interner.internArrayType(self.string_interner, elem_t) catch error.OutOfMemory;
    }

    fn unionOrAny(self: *Checker, items: []const TypeId) CheckError!TypeId {
        if (items.len == 0) return types.Primitive.any;
        if (items.len == 1) return items[0];
        return self.interner.internUnion(items) catch return error.OutOfMemory;
    }

    fn symbolGlobalType(self: *Checker) CheckError!TypeId {
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        const include_declared_augmentations = !self.symbol_global_building;
        if (include_declared_augmentations) self.symbol_global_building = true;
        defer if (include_declared_augmentations) {
            self.symbol_global_building = false;
        };

        const empty_params = [_]types.TypeId{};
        const symbol_ctor = self.interner.internSignature(&empty_params, types.Primitive.symbol_t, false) catch return error.OutOfMemory;
        const string_params = [_]types.TypeId{types.Primitive.string_t};
        const symbol_for = self.interner.internSignature(&string_params, types.Primitive.symbol_t, false) catch return error.OutOfMemory;
        // Name `Symbol.for`'s parameter `key` so diagnostics render
        // `(key: string) => symbol` (e.g. the TS2538 in `symbolProperty53`).
        {
            const key_name = self.string_interner.intern("key") catch return error.OutOfMemory;
            const for_param_names = self.gpa.dupe(hir_mod.StringId, &.{key_name}) catch return error.OutOfMemory;
            if (self.signature_param_names.fetchRemove(symbol_for)) |old| self.gpa.free(old.value);
            self.signature_param_names.put(self.gpa, symbol_for, for_param_names) catch {};
        }

        const call_id = self.string_interner.intern("__call") catch return error.OutOfMemory;
        try members.append(self.gpa, .{ .name = call_id, .type = symbol_ctor, .is_optional = false, .is_readonly = true, .is_method = true });
        const for_id = self.string_interner.intern("for") catch return error.OutOfMemory;
        try members.append(self.gpa, .{ .name = for_id, .type = symbol_for, .is_optional = false, .is_readonly = true, .is_method = true });
        const key_for_params = [_]types.TypeId{types.Primitive.symbol_t};
        const symbol_key_for = self.interner.internSignature(&key_for_params, types.Primitive.string_t, false) catch return error.OutOfMemory;
        const key_for_id = self.string_interner.intern("keyFor") catch return error.OutOfMemory;
        try members.append(self.gpa, .{ .name = key_for_id, .type = symbol_key_for, .is_optional = false, .is_readonly = true, .is_method = true });

        // `Symbol.prototype: Symbol`. We don't model the `Symbol`
        // instance interface explicitly; an opaque empty-object type
        // is enough for `[Symbol.prototype]` to trigger TS2464 (the
        // type isn't string/number/symbol/any). Mirrors upstream tsc
        // on `symbolProperty54.ts(2,5)`.
        const prototype_id = self.string_interner.intern("prototype") catch return error.OutOfMemory;
        const empty_obj = self.interner.internObjectType(&[_]types.ObjectMember{}) catch return error.OutOfMemory;
        try members.append(self.gpa, .{ .name = prototype_id, .type = empty_obj, .is_optional = false, .is_readonly = true, .is_method = false });

        const well_known = [_][]const u8{
            "asyncIterator",
            "hasInstance",
            "isConcatSpreadable",
            "iterator",
            "match",
            "matchAll",
            "replace",
            "search",
            "species",
            "split",
            "metadata",
            "asyncDispose",
            "dispose",
            "toPrimitive",
            "toStringTag",
            "unscopables",
