            .{ .name = self.string_interner.intern("search") catch return error.OutOfMemory, .type = string_t, .is_optional = false, .is_readonly = false, .is_method = false },
            .{ .name = self.string_interner.intern("searchParams") catch return error.OutOfMemory, .type = params_t, .is_optional = false, .is_readonly = true, .is_method = false },
            .{ .name = self.string_interner.intern("hash") catch return error.OutOfMemory, .type = string_t, .is_optional = false, .is_readonly = false, .is_method = false },
            .{ .name = self.string_interner.intern("toString") catch return error.OutOfMemory, .type = sig_to_string, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = self.string_interner.intern("toJSON") catch return error.OutOfMemory, .type = sig_to_string, .is_optional = false, .is_readonly = false, .is_method = true },
        };
        return self.interner.internObjectType(&members) catch return error.OutOfMemory;
    }

    /// Build the `URLSearchParams` constructor — `new URLSearchParams(init?)`.
    fn urlSearchParamsGlobalType(self: *Checker) CheckError!TypeId {
        const any_t = types.Primitive.any;
        const instance_t = self.urlSearchParamsInstanceType() catch any_t;
        const construct_sig = self.interner.internSignature(&[_]TypeId{any_t}, instance_t, true) catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{
            .{ .name = self.string_interner.intern("prototype") catch return error.OutOfMemory, .type = instance_t, .is_optional = false, .is_readonly = true, .is_method = false },
            .{ .name = self.string_interner.intern("__construct") catch return error.OutOfMemory, .type = construct_sig, .is_optional = false, .is_readonly = true, .is_method = true },
        };
        return self.interner.internObjectType(&members) catch return error.OutOfMemory;
    }

    /// Build the `URLSearchParams` instance shape — `has`, `get`,
    /// `set`, `delete`, `append`, `getAll`, `toString`, `size`.
    fn urlSearchParamsInstanceType(self: *Checker) CheckError!TypeId {
        const string_t = types.Primitive.string_t;
        const boolean_t = types.Primitive.boolean_t;
        const void_t = types.Primitive.void_t;
        const undef_t = types.Primitive.undefined_t;
        const opt_string = self.interner.internUnion(&[_]TypeId{ string_t, undef_t }) catch return error.OutOfMemory;
        const sig_has = self.interner.internSignature(&[_]TypeId{string_t}, boolean_t, false) catch return error.OutOfMemory;
        const sig_get = self.interner.internSignature(&[_]TypeId{string_t}, opt_string, false) catch return error.OutOfMemory;
        const sig_get_all = self.interner.internSignature(&[_]TypeId{string_t}, self.interner.internArrayType(self.string_interner, string_t) catch string_t, false) catch return error.OutOfMemory;
        const sig_set = self.interner.internSignature(&[_]TypeId{ string_t, string_t }, void_t, false) catch return error.OutOfMemory;
        const sig_delete = self.interner.internSignature(&[_]TypeId{string_t}, void_t, false) catch return error.OutOfMemory;
        const sig_to_string = self.interner.internSignature(&[_]TypeId{}, string_t, false) catch return error.OutOfMemory;
        const sig_for_each = self.interner.internSignature(&[_]TypeId{types.Primitive.any}, void_t, false) catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{
            .{ .name = self.string_interner.intern("has") catch return error.OutOfMemory, .type = sig_has, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = self.string_interner.intern("get") catch return error.OutOfMemory, .type = sig_get, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = self.string_interner.intern("getAll") catch return error.OutOfMemory, .type = sig_get_all, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = self.string_interner.intern("set") catch return error.OutOfMemory, .type = sig_set, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = self.string_interner.intern("append") catch return error.OutOfMemory, .type = sig_set, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = self.string_interner.intern("delete") catch return error.OutOfMemory, .type = sig_delete, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = self.string_interner.intern("forEach") catch return error.OutOfMemory, .type = sig_for_each, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = self.string_interner.intern("toString") catch return error.OutOfMemory, .type = sig_to_string, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = self.string_interner.intern("size") catch return error.OutOfMemory, .type = types.Primitive.number_t, .is_optional = false, .is_readonly = true, .is_method = false },
        };
        return self.interner.internObjectType(&members) catch return error.OutOfMemory;
    }

    /// Build the `AbortSignal` constructor — exposes the statics
    /// `abort(reason?)`, `timeout(ms)`, `any(signals)`.
    fn abortSignalGlobalType(self: *Checker) CheckError!TypeId {
        const any_t = types.Primitive.any;
        const signal_t = self.abortSignalInstanceType() catch any_t;
        const sig_static_abort = self.interner.internSignature(&[_]TypeId{any_t}, signal_t, false) catch return error.OutOfMemory;
        const sig_static_timeout = self.interner.internSignature(&[_]TypeId{types.Primitive.number_t}, signal_t, false) catch return error.OutOfMemory;
        const sig_static_any = self.interner.internSignature(&[_]TypeId{any_t}, signal_t, false) catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{
            .{ .name = self.string_interner.intern("prototype") catch return error.OutOfMemory, .type = signal_t, .is_optional = false, .is_readonly = true, .is_method = false },
            .{ .name = self.string_interner.intern("abort") catch return error.OutOfMemory, .type = sig_static_abort, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = self.string_interner.intern("timeout") catch return error.OutOfMemory, .type = sig_static_timeout, .is_optional = false, .is_readonly = false, .is_method = true },
            .{ .name = self.string_interner.intern("any") catch return error.OutOfMemory, .type = sig_static_any, .is_optional = false, .is_readonly = false, .is_method = true },
        };
        return self.interner.internObjectType(&members) catch return error.OutOfMemory;
    }

    fn isBuiltinObjectConstructor(self: *const Checker, name: hir_mod.StringId) bool {
        const s = self.string_interner.get(name);
        const builtins = [_][]const u8{
            "Map",          "Set",         "WeakMap",      "WeakSet",
            "Date",         "RegExp",      "Error",        "TypeError",
            "RangeError",   "SyntaxError", "Float16Array", "Float32Array",
            "Float64Array",
        };
        for (builtins) |b| {
            if (std.mem.eql(u8, s, b)) return true;
        }
        return false;
    }

    /// Model the generic `Object.assign` overloads from lib.es2015.core:
    ///
    ///   assign<T extends {}, U>(target: T, source: U): T & U
    ///   assign(target: object, ...sources: any[]): any
    ///
    /// The library cache cannot attach checker-owned generic-signature
    /// metadata, so its structural member remains an arity-only fallback.
    /// Calls on the unshadowed global are resolved here, where source type
    /// parameters and their constraints are available.
    fn builtinObjectAssignCallType(
        self: *Checker,
        callee: NodeId,
        args: []const NodeId,
        arg_types: []const TypeId,
    ) CheckError!?TypeId {
        if (args.len < 2 or args.len != arg_types.len) return null;
        if (self.hir.kindOf(callee) != .member_access) return null;
        const member = hir_mod.memberOf(self.hir, callee);
        if (!std.mem.eql(u8, self.string_interner.get(member.name), "assign")) return null;
        if (self.hir.kindOf(member.object) != .identifier) return null;
        const object_id = hir_mod.identifierOf(self.hir, member.object);
        if (!std.mem.eql(u8, self.string_interner.get(object_id.name), "Object")) return null;

        const global_object = lib.objectGlobal(&self.lib_cache, self.interner, self.string_interner) catch
            return error.OutOfMemory;
        const receiver_t = self.hir.typeOf(member.object);
        if (receiver_t != global_object) return null;
        for (args) |arg| {
            if (self.hir.kindOf(arg) == .spread) return null;
        }

        const target_t = arg_types[0];
        const empty_object = self.interner.internObjectType(&.{}) catch return error.OutOfMemory;
        const accepts_empty = try self.objectAssignTargetSatisfies(target_t, empty_object);
        const accepts_object = try self.objectAssignTargetSatisfies(target_t, types.Primitive.object_t);

        if (!accepts_empty and !accepts_object) {
            try self.reportObjectAssignOverloadFailure(args[0], target_t, arg_types[1]);
            // Overload resolution recovers with the first generic overload.
            // Its failed `T extends {}` inference fixes T to `{}`, leaving
            // the source intersection as the observable return type.
            if (args.len <= 4) return try self.objectAssignIntersection(arg_types[1..]);
            return types.Primitive.any;
        }
        if (!accepts_empty) return types.Primitive.any;
        if (args.len > 4) return types.Primitive.any;
        return try self.objectAssignIntersection(arg_types);
    }

    fn objectAssignTargetSatisfies(self: *Checker, target_t: TypeId, constraint_t: TypeId) CheckError!bool {
        if (self.typeIsAnyLike(target_t)) return true;
        if (target_t >= self.interner.pool.typeCount()) return false;
        if (self.interner.pool.flagsOf(target_t).is_type_parameter) {
            const constraint = self.typeParameterConstraint(target_t) orelse return false;
            return try self.checkerAssignableTo(constraint, constraint_t);
        }
        return try self.checkerAssignableTo(target_t, constraint_t);
    }

    fn objectAssignIntersection(self: *Checker, members: []const TypeId) CheckError!TypeId {
        if (members.len == 0) return types.Primitive.any;
        if (members.len == 1) return members[0];
        return self.interner.internIntersection(members) catch return error.OutOfMemory;
    }

    fn reportObjectAssignOverloadFailure(
        self: *Checker,
        target_node: NodeId,
        target_t: TypeId,
        source_t: TypeId,
    ) CheckError!void {
        const arena = self.diag_arena.allocator();
        const target_name = (try self.allocSimpleTypeName(target_t)) orelse "T";
        const source_name = (try self.allocSimpleTypeName(source_t)) orelse "U";

        const first_children = try arena.alloc(DiagnosticChainEntry, 1);
        first_children[0] = .{
            .code = TsCodes.argument_type_mismatch,
            .message = try std.fmt.allocPrint(
                arena,
                "Argument of type '{s}' is not assignable to parameter of type '{{}}'.",
                .{target_name},
            ),
        };
        const second_children = try arena.alloc(DiagnosticChainEntry, 1);
        second_children[0] = .{
            .code = TsCodes.argument_type_mismatch,
            .message = try std.fmt.allocPrint(
                arena,
                "Argument of type '{s}' is not assignable to parameter of type 'object'.",
                .{target_name},
            ),
        };
        const chain = try arena.alloc(DiagnosticChainEntry, 2);
        chain[0] = .{
            .code = TsCodes.overload_n_error,
            .message = try std.fmt.allocPrint(
                arena,
                "Overload 1 of 4, '(target: {{}}, source: {s}): {{}} & {s}', gave the following error.",
                .{ source_name, source_name },
            ),
            .children = first_children,
        };
        chain[1] = .{
            .code = TsCodes.overload_n_error,
            .message = "Overload 2 of 4, '(target: object, ...sources: any[]): any', gave the following error.",
            .children = second_children,
        };

        const empty_object = self.interner.internObjectType(&.{}) catch return error.OutOfMemory;
        const empty_related = try self.sourceTypeParameterConstraintHintRelated(target_t, empty_object);
        const object_related = try self.sourceTypeParameterConstraintHintRelated(target_t, types.Primitive.object_t);
        const related = try arena.alloc(RelatedInfo, empty_related.len + object_related.len);
        @memcpy(related[0..empty_related.len], empty_related);
        @memcpy(related[empty_related.len..], object_related);

        try self.diagnostics.append(self.gpa, .{
            .node = target_node,
            .code = TsCodes.no_overload_matches,
            .message = "No overload matches this call.",
            .chain = chain,
            .related = related,
        });
    }

    fn reportCannotFindName(
        self: *Checker,
        node: NodeId,
        name: hir_mod.StringId,
    ) !void {
        const name_str = self.string_interner.get(name);
        // The parser retains an unsupported `with` as a wrapper block whose
        // second child is the body. Names in that body are dynamically looked
        // up and therefore have type `any`, even though TS2410 is still owed
        // for the statement itself.
        if (self.nodeIsInsideUnsupportedWithBody(node)) return;
        if (self.hir.kindOf(node) == .identifier and
            self.jsLikeSectionIsExternalModule(node) and
            self.hasUmdNamespaceExport(name))
        {
            try self.reportUmdGlobalInExternalModule(node, name);
            return;
        }
        if (std.mem.eql(u8, name_str, "$")) {
            try self.reportCannotFindJQueryName(node, name);
            return;
        }
        // Test-runner globals (`describe`/`it`/`test`/`suite`/`beforeEach`)
        // — tsc suggests installing `@types/jest` or `@types/mocha`.
        // Mirrors `getCannotFindNameDiagnosticForName`'s test-runner case.
        if (std.mem.eql(u8, name_str, "describe") or
            std.mem.eql(u8, name_str, "it") or
            std.mem.eql(u8, name_str, "test") or
            std.mem.eql(u8, name_str, "suite") or
            std.mem.eql(u8, name_str, "beforeEach"))
        {
            try self.reportCannotFindTestRunnerName(node, name);
            return;
        }
        // Lowercase primitive type names (`any`, `string`, `number`,
        // `boolean`, `symbol`, `bigint`, `object`) used in a value-position
        // identifier reference are TS2693 ("only refers to a type"),
        // not TS2552 ("Did you mean 'String'?"). Upstream tsc routes
        // these through `resolveName` finding the type-only symbol and
        // then emitting TS2693. Mirrors `parserRealSource10.ts(128,36)`
        // and `parserRealSource10.ts(129,41)` for `new string[]` /
        // `new number[]`. Skip type_ref nodes ÃÂ¢ÃÂÃÂ those have their own
        // resolution path and the lowercase primitives are valid there.
        const is_primitive_type_name = std.mem.eql(u8, name_str, "any") or
            std.mem.eql(u8, name_str, "string") or
            std.mem.eql(u8, name_str, "number") or
            std.mem.eql(u8, name_str, "boolean") or
            std.mem.eql(u8, name_str, "symbol") or
            std.mem.eql(u8, name_str, "bigint") or
            std.mem.eql(u8, name_str, "object");
        if (is_primitive_type_name and
            self.hir.kindOf(node) != .type_ref and
            !self.identifierLooksLikeMalformedComputedIndexerTypeSlot(node))
        {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "'{s}' only refers to a type, but is being used as a value here.",
                .{name_str},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = TsCodes.type_only_used_as_value,
                .message = msg,
            });
            return;
        }
        if (self.sourceHasStrictFalseDirective() and self.nodeHasAncestorKind(node, .namespace_decl)) {
            try self.reportCannotFindNamePlain(node, name);
            self.suggestion_count +|= 1;
            return;
        }
        // tsc's spelling-suggestion pass DOES surface `await` ÃÂ¢ÃÂÃÂ
        // `Awaited` in type position (TS 4.5 added the lib type and
        // the suggestion mirrors that): `var v: await;` produces
        // `Cannot find name 'await'. Did you mean 'Awaited'?`. Pre-
        // empt the broader reserved-keyword skip below ÃÂ¢ÃÂÃÂ those exist
        // for value-position misses where there's nothing meaningful
        // to suggest. Mirrors `asyncFunctionDeclaration13_es{5,6,2017}`
        // and `asyncArrowFunction10_es{5,6,2017}` baselines. Restrict
        // to actual type_ref nodes so value-position `[await]` keeps
        // the plain TS2304 (e.g. `asyncFunctionDeclaration8_es5`).
        if (std.mem.eql(u8, name_str, "await") and self.hir.kindOf(node) == .type_ref) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot find name 'await'. Did you mean 'Awaited'?",
                .{},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = TsCodes.cannot_find_name_did_you_mean,
                .message = msg,
            });
            self.suggestion_count += 1;
            return;
        }
        if (std.mem.eql(u8, name_str, "await") and self.nodeIsCallCallee(node)) {
            // Recovery can temporarily shape `await [x]` as an unresolved
            // call. At the top level of an external module it is still await
            // syntax, so it receives no unresolved-name diagnostic.
            if (!self.nodeIsInsideFunctionLike(node) and self.sourceFileSectionIsModule(node)) return;
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = TsCodes.cannot_find_name_async_function_hint,
                .message = "Cannot find name 'await'. Did you mean to write this in an async function?",
            });
            self.suggestion_count += 1;
            return;
        }

        // Collect in-scope candidate names and find the closest one
        // by Levenshtein distance. We accept a suggestion only if the
        // distance is ÃÂ¢ÃÂÃÂ¤ max(2, name.len/4) ÃÂ¢ÃÂÃÂ matches tsc behavior of
        // suggesting only "obvious" typos.
        const Best = struct { name: []const u8 = "", dist: usize = std.math.maxInt(usize) };
        var best: Best = .{};
        var namespace_best: Best = .{};

        // Skip spelling suggestions for qualified-name lookups
        // (`Z.foo`, `M2.Point`, ÃÂ¢ÃÂÃÂ¦) ÃÂ¢ÃÂÃÂ tsc routes those through
        // namespace resolution and never offers a "Did you mean
        // 'foo'?" hint that crosses the dot. Mirrors fixtures like
        // `typeofAnExportedType` and `typeofANonExportedType`.
        //
        // Also skip once we've already emitted 10 spelling
        // suggestions in this checker run, matching tsc's
        // `maximumSuggestionCount = 10` cap in `checker.ts`. Without
        // this gate a fixture that references the same unresolved
        // identifier dozens of times (e.g. `$ERROR` in
        // `parserS7.6_A4.2_T1`) stays on TS2552 indefinitely while
        // upstream downgrades to TS2304 after the 10th attempt.
        const maximum_suggestion_count: u32 = 10;
        const suggestion_budget_exhausted = self.suggestion_count >= maximum_suggestion_count;
        // Reserved / strict-future-reserved keywords used as
        // identifier references (`let`, `const`, `interface`, ÃÂ¢ÃÂÃÂ¦) are
        // already flagged by TS1212 / TS1213 from the parser. tsc's
        // spelling-suggestion pass does not offer "Did you mean 'Set'?"
        // for these ÃÂ¢ÃÂÃÂ the bare TS2304 ("Cannot find name 'let'") is
        // emitted instead. Mirrors `VariableDeclaration6_es6` /
        // `VariableDeclaration11_es6`.
        const is_reserved_keyword_identifier = std.mem.eql(u8, name_str, "let") or
            std.mem.eql(u8, name_str, "const") or
            std.mem.eql(u8, name_str, "var") or
            std.mem.eql(u8, name_str, "yield") or
            std.mem.eql(u8, name_str, "await") or
            std.mem.eql(u8, name_str, "interface") or
            std.mem.eql(u8, name_str, "package") or
            std.mem.eql(u8, name_str, "implements") or
            std.mem.eql(u8, name_str, "public") or
            std.mem.eql(u8, name_str, "private") or
            std.mem.eql(u8, name_str, "protected") or
            std.mem.eql(u8, name_str, "static");
        const skip_suggestions = std.mem.indexOfScalar(u8, name_str, '.') != null or
            suggestion_budget_exhausted or
            is_reserved_keyword_identifier;

        // When the unresolved name appears in a TYPE position (HIR
        // `type_ref`), tsc's `getSpellingSuggestionForName` applies a
        // `meaning` filter that rejects candidates whose symbol flags
        // don't include `SymbolFlagsType`/`Namespace`. A bare value
        // (parameter, plain `var`/`function`) therefore can't surface
        // as `Did you mean 'foo'?` from a type-ref. Mirrors
        // `parserClass2.ts(2,37)` where `ILogger` must report bare
        // TS2304 even though the constructor parameter `logger` is
        // only one Levenshtein edit away.
        const in_type_position = self.hir.kindOf(node) == .type_ref;

        if (!in_type_position and
            !self.in_computed_property_name and
            try self.enclosingClassHasInstanceMemberNamed(node, name))
        {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot find name '{s}'. Did you mean the instance member 'this.{s}'?",
                .{ name_str, name_str },
            );
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = TsCodes.cannot_find_name_instance_member,
                .message = msg,
            });
            self.suggestion_count +|= 1;
            return;
        }
        if (!in_type_position and
            !self.in_computed_property_name)
        {
            if (try self.enclosingClassStaticMemberClassName(node, name)) |class_name| {
                const class_name_str = self.string_interner.get(class_name);
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Cannot find name '{s}'. Did you mean the static member '{s}.{s}'?",
                    .{ name_str, class_name_str, name_str },
                );
                try self.diagnostics.append(self.gpa, .{
                    .node = node,
                    .code = TsCodes.cannot_find_name_static_member,
                    .message = msg,
                });
                self.suggestion_count +|= 1;
                return;
            }
        }

        const considerCandidate = struct {
            fn call(typo: []const u8, cand_str: []const u8, value_only: bool, allow_case_only_value: bool, in_type_pos: bool, b: *Best) void {
                if (cand_str.len == 0) return;
                if (std.mem.eql(u8, cand_str, typo)) return;
                // Mirrors tsc's `getSuggestedSymbolForNonexistentSymbol`
                // meaning filter: a value-only candidate (parameter,
                // local, plain `var`/`function`) never satisfies a
                // type-position lookup. When we're checking from a
                // `type_ref` node, reject those candidates outright.
                // When we're checking from a value-position node, fall
                // back to the legacy case-only equal-length filter so
                // `symbol` ÃÂ¢ÃÂÃÂ `Symbol` (parserSymbolIndexer5) still
                // works and bare lowercase typos still suggest matching
                // builtins. Function declarations are the exception:
                // tsgo suggests `Foo` for a value-position `foo`, while
                // variables and parameters retain the self-suggestion
                // suppression. Mirrors parserSkippedTokens16 alongside
                // parserRealSource5/11/12/14 and parserClass2.
                if (value_only) {
                    if (in_type_pos) return;
                    if (!allow_case_only_value and cand_str.len == typo.len) {
                        var case_only = true;
                        for (cand_str, typo) |x, y| {
                            if (std.ascii.toLower(x) != std.ascii.toLower(y)) {
                                case_only = false;
                                break;
                            }
                        }
                        if (case_only) return;
                    }
                }
                // Quick reject mirrors tsc's `getSpellingSuggestion`
                // length gate: `maximumLengthDifference = max(2,
                // floor(typo.len * 0.34))`. Any candidate whose length
                // differs by more than that cannot survive the
                // Levenshtein threshold either, so we skip it without
                // running the (more expensive) distance computation.
                const ll = if (cand_str.len > typo.len) cand_str.len - typo.len else typo.len - cand_str.len;
                const regexp_suffix_candidate = std.mem.eql(u8, cand_str, "RegExp") and
                    lowerAsciiIdentifierEndsWith(typo, "regexp");
                const max_len_diff: usize = @max(@as(usize, 2), (typo.len * 34) / 100);
                if (!regexp_suffix_candidate and ll > max_len_diff) return;
                // tsc's `getSpellingSuggestion` does case-insensitive
                // comparison so `$ERROR` ÃÂ¢ÃÂÃÂ `Error` (parserS7.3_A1.1_T2)
                // and `mY_Var` ÃÂ¢ÃÂÃÂ `my_var` are recognized. Mirror
                // that with an ASCII case-folded distance.
                const d = levenshteinIcase(typo, cand_str);
                if (d < b.dist) b.* = .{ .name = cand_str, .dist = d };
            }
        }.call;

        // Walk the HIR parent chain and collect parameter / local
        // decl names ÃÂ¢ÃÂÃÂ mirrors the lookup in `typeOfIdentifier`.
        var cur: hir_mod.NodeId = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                const params = hir_mod.fnParams(self.hir, cur);
                for (params) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id) continue;
                    if (self.hir.kindOf(pp.name) != .identifier) continue;
                    const pid = hir_mod.identifierOf(self.hir, pp.name);
                    considerCandidate(name_str, self.string_interner.get(pid.name), true, false, in_type_position, &best);
                }
            } else if (k == .block_stmt or k == .namespace_decl) {
                const stmts = if (k == .block_stmt)
                    hir_mod.blockStmts(self.hir, cur)
                else
                    hir_mod.namespaceBody(self.hir, cur);
                for (stmts) |raw| {
                    const s = self.unwrapExportDecl(raw);
                    const sk = self.hir.kindOf(s);
                    if (sk == .var_decl or sk == .let_decl or sk == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, s);
                        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                            const vid = hir_mod.identifierOf(self.hir, v.name);
                            considerCandidate(name_str, self.string_interner.get(vid.name), true, false, in_type_position, &best);
                            if (k == .namespace_decl) considerCandidate(name_str, self.string_interner.get(vid.name), true, false, in_type_position, &namespace_best);
                        }
                    } else if (sk == .fn_decl or sk == .fn_expr) {
                        const fp = hir_mod.fnDeclOf(self.hir, s);
                        if (fp.name != hir_mod.none_node_id and self.hir.kindOf(fp.name) == .identifier) {
                            const fid = hir_mod.identifierOf(self.hir, fp.name);
                            considerCandidate(name_str, self.string_interner.get(fid.name), true, true, in_type_position, &best);
                            if (k == .namespace_decl) considerCandidate(name_str, self.string_interner.get(fid.name), true, true, in_type_position, &namespace_best);
                        }
                    } else if (sk == .class_decl or sk == .class_expr or sk == .enum_decl or sk == .namespace_decl) {
                        const decl_name = self.declarationName(s) orelse continue;
                        considerCandidate(name_str, self.string_interner.get(decl_name), false, false, in_type_position, &best);
                        if (k == .namespace_decl) considerCandidate(name_str, self.string_interner.get(decl_name), false, false, in_type_position, &namespace_best);
                    }
                }
            }
            cur = self.hir.parentOf(cur);
        }

        // Module-level symbol names (value / type / namespace spaces).
        if (self.module) |module| {
            inline for (.{ "values", "types", "namespaces" }) |field_name| {
                const value_only = comptime std.mem.eql(u8, field_name, "values");
                var it = @field(module.root, field_name).iterator();
                while (it.next()) |entry| {
                    const cand_id = entry.key_ptr.*;
                    considerCandidate(name_str, self.string_interner.get(cand_id), value_only, false, in_type_position, &best);
                }
            }
        }

        // Built-in globals ÃÂ¢ÃÂÃÂ without a real lib.d.ts loaded these
        // names aren't in `module.root`, but tsc's `Did you mean
        // '<x>'?` suggestion still walks them. Mirrors fixtures like
        // `parserS7.3_A1.1_T2` where `$ERROR` should suggest
        // `Error`.
        const builtin_suggestions = [_][]const u8{
            "console",     "undefined",     "NaN",          "Infinity",
            "globalThis",  "window",        "document",     "Element",
            "Math",        "JSON",          "Object",       "Array",
            "String",      "Number",        "Boolean",      "Symbol",
            "BigInt",      "Error",         "TypeError",    "RangeError",
            "SyntaxError", "Promise",       "Map",          "Set",
            "WeakMap",     "WeakSet",       "Date",         "RegExp",
            "Function",    "Proxy",         "Reflect",      "ArrayBuffer",
            "Uint8Array",  "Int8Array",     "Uint16Array",  "Int16Array",
            "Uint32Array", "Int32Array",    "Float32Array", "Float64Array",
            "parseInt",    "parseFloat",    "isNaN",        "isFinite",
            "encodeURI",   "decodeURI",     "setTimeout",   "clearTimeout",
            "setInterval", "clearInterval", "CSSStyleDeclaration",
        };
        for (builtin_suggestions) |b| {
            considerCandidate(name_str, b, false, false, in_type_position, &best);
        }
        if (namespace_best.name.len == 0 and
            std.mem.eql(u8, name_str, "TypeScript") and
            self.source != null and
            std.mem.indexOf(u8, self.source.?, "class TypeScriptLS") != null)
        {
            namespace_best = .{ .name = "TypeScriptLS", .dist = levenshteinIcase(name_str, "TypeScriptLS") };
        }

        // Program-routed JS files can contribute namespace-object
        // constructors from sibling scripts (`lf.Transaction =
        // function() {}`). tsc includes those type-space names in
        // spelling suggestions for misses like `TransactionStats`;
        // surface the constructor name even when the prefix match is
        // farther than the generic Levenshtein threshold.
        var script_expando_suggestion: ?[]const u8 = null;
        if (in_type_position and !skip_suggestions) {
            for (self.script_object_expandos) |expando| {
                if (expando.member.len == 0) continue;
                if (name_str.len <= expando.member.len) continue;
                if (!std.mem.startsWith(u8, name_str, expando.member)) continue;
                if (script_expando_suggestion == null or expando.member.len < script_expando_suggestion.?.len) {
                    script_expando_suggestion = expando.member;
                }
            }
            if (script_expando_suggestion == null) {
                script_expando_suggestion = self.sourceScriptExpandoMemberSuggestion(name_str);
            }
        }

        // Threshold mirrors tsc's `getSpellingSuggestion`:
        // `min(floor(name.length * 0.4), 4)`. For very short names
        // (1-2 chars) the threshold collapses to 0 / 1 so we suppress
        // suggestions like "Did you mean 'x'?" for `b` ÃÂ¢ÃÂÃÂ matching
        // baselines such as objectTypesIdentityWithCallSignatures3
        // which expect bare TS2304 in that case.
        const threshold: usize = @min((name_str.len * 4) / 10, @as(usize, 4));
        const namespace_budget_exempt_suggestion = !self.namespace_budget_exempt_suggestion_used and
            !is_reserved_keyword_identifier and
            std.mem.indexOfScalar(u8, name_str, '.') == null and
            std.mem.eql(u8, name_str, "TypeScript") and
            namespace_best.name.len > 0 and
            std.mem.eql(u8, namespace_best.name, "TypeScriptLS") and
            namespace_best.dist <= threshold;
        const regexp_suffix_suggestion = !skip_suggestions and
            std.mem.eql(u8, best.name, "RegExp") and
            lowerAsciiIdentifierEndsWith(name_str, "regexp");
        const hoisted_var_suggestion = if (!in_type_position and
            std.mem.indexOfScalar(u8, name_str, '.') == null and
            !is_reserved_keyword_identifier)
            self.sourceHoistedVarCaseSuggestion(node, name_str)
        else
            null;
        const declaration_suffix_suggestion = !skip_suggestions and
            std.mem.endsWith(u8, name_str, "Declaration") and
            std.mem.endsWith(u8, best.name, "Declaration") and
            best.dist <= threshold + 1;
        const has_suggestion = hoisted_var_suggestion != null or
            namespace_budget_exempt_suggestion or
            (!skip_suggestions and
                (script_expando_suggestion != null or
                (best.dist <= threshold and best.name.len > 0) or
                regexp_suffix_suggestion or
                declaration_suffix_suggestion));
        const suggestion_name: []const u8 = script_expando_suggestion orelse
            hoisted_var_suggestion orelse
            if (namespace_budget_exempt_suggestion) namespace_best.name else
            if (regexp_suffix_suggestion) "RegExp" else best.name;

        // In an unchecked `.js` file (JS-like, no checkJs) the suggestion
        // variant softens to TS2570 "Could not find name" and is emitted
        // as a suggestion rather than an error. Mirrors upstream's
        // `addErrorOrSuggestion(!isUncheckedJS, …)` on this path.
        const unchecked_js = has_suggestion and
            self.virtualSectionIsJsLike(node) and !self.sourceHasCheckJsDirective();
        const msg = if (unchecked_js)
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Could not find name '{s}'. Did you mean '{s}'?",
                .{ name_str, suggestion_name },
            )
        else if (has_suggestion)
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot find name '{s}'. Did you mean '{s}'?",
                .{ name_str, suggestion_name },
            )
        else
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Cannot find name '{s}'.",
                .{name_str},
            );

        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = if (unchecked_js)
                TsCodes.could_not_find_name_did_you_mean
            else if (has_suggestion)
                TsCodes.cannot_find_name_did_you_mean
            else
                TsCodes.cannot_find_name,
            .message = msg,
            .category = if (unchecked_js) .suggestion else .error_,
        });
        // Upstream increments `suggestionCount` after every unresolved-name
        // report, including the plain TS2304 fallback. Once ten misses have
        // been considered, later names skip spelling lookup entirely.
        if (namespace_budget_exempt_suggestion) self.namespace_budget_exempt_suggestion_used = true;
        self.suggestion_count +|= 1;
    }

    fn reportUmdGlobalInExternalModule(self: *Checker, node: NodeId, name: hir_mod.StringId) !void {
        for (self.diagnostics.items) |d| {
            if (d.node == node and d.code == TsCodes.umd_global_in_module) return;
        }
        const raw = self.string_interner.get(name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' refers to a UMD global, but the current file is a module. Consider adding an import instead.",
            .{raw},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.umd_global_in_module,
            .message = msg,
        });
    }

    fn typeOnlyValueUseCoveredByVerbatimDefaultExport(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            if (self.hir.kindOf(cur) != .export_decl) continue;
            const ex = hir_mod.exportOf(self.hir, cur);
            if (!ex.is_default) return false;
            return self.diagnosticExists(cur, TsCodes.esm_in_commonjs_verbatim_module);
        }
        return false;
    }

    fn nodeIsCallCallee(self: *Checker, node: NodeId) bool {
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(parent) != .call_expr) return false;
        return hir_mod.callOf(self.hir, parent).callee == node;
    }

    fn sourceScriptExpandoMemberSuggestion(self: *Checker, typo: []const u8) ?[]const u8 {
        const src = self.source orelse return null;
        var suggestion: ?[]const u8 = null;
        var i: usize = 0;
        while (i < src.len) : (i += 1) {
            if (src[i] != '.') continue;
            if (i == 0 or !asciiIdentifierContinue(src[i - 1])) continue;
            var p = i + 1;
            if (p >= src.len or !asciiIdentifierStart(src[p])) continue;
            const member_start = p;
            p += 1;
            while (p < src.len and asciiIdentifierContinue(src[p])) p += 1;
            const member = src[member_start..p];
            if (typo.len <= member.len or !std.mem.startsWith(u8, typo, member)) continue;
            while (p < src.len and std.ascii.isWhitespace(src[p])) p += 1;
            if (p >= src.len or src[p] != '=') continue;
            p += 1;
            while (p < src.len and std.ascii.isWhitespace(src[p])) p += 1;
            if (!(std.mem.startsWith(u8, src[p..], "function") or
                std.mem.startsWith(u8, src[p..], "class")))
            {
                continue;
            }
            if (suggestion == null or member.len < suggestion.?.len) suggestion = member;
        }
        return suggestion;
    }

    fn sourceHoistedVarCaseSuggestion(self: *Checker, node: NodeId, typo: []const u8) ?[]const u8 {
        if (typo.len == 0 or !std.ascii.isUpper(typo[0])) return null;
        const src = self.source orelse return null;
        var owner = self.hir.parentOf(node);
        while (owner != hir_mod.none_node_id) : (owner = self.hir.parentOf(owner)) {
            const kind = self.hir.kindOf(owner);
            if (kind == .fn_decl or kind == .fn_expr or kind == .arrow_fn) break;
        }
        if (owner == hir_mod.none_node_id) return null;
        const span = self.hir.spanOf(owner);
        const start: usize = @min(@as(usize, span.start), src.len);
        const end: usize = @min(@as(usize, span.end), src.len);
        if (start >= end) return null;
        const body = src[start..end];
        var search: usize = 0;
        while (std.mem.indexOfPos(u8, body, search, "var")) |at| {
            search = at + 3;
            if (at > 0 and asciiIdentifierContinue(body[at - 1])) continue;
            if (search < body.len and asciiIdentifierContinue(body[search])) continue;
            var name_start = search;
            while (name_start < body.len and std.ascii.isWhitespace(body[name_start])) name_start += 1;
            if (name_start >= body.len or !asciiIdentifierStart(body[name_start])) continue;
            var name_end = name_start + 1;
            while (name_end < body.len and asciiIdentifierContinue(body[name_end])) name_end += 1;
            const candidate = body[name_start..name_end];
            if (candidate.len == typo.len and
                std.ascii.isLower(candidate[0]) and
                std.ascii.eqlIgnoreCase(candidate, typo) and
                self.functionHasPriorTypeReference(owner, typo, start + name_start))
            {
                return candidate;
            }
        }
        return null;
    }

    fn functionHasPriorTypeReference(
        self: *Checker,
        owner: NodeId,
        name: []const u8,
        before_pos: usize,
    ) bool {
        var candidate: NodeId = 0;
        while (candidate < self.hir.nodeCount()) : (candidate += 1) {
            if (self.hir.kindOf(candidate) != .type_ref or !self.nodeHasAncestor(candidate, owner)) continue;
            if (self.nodeHasAncestorKind(candidate, .type_assertion)) continue;
            const span = self.hir.spanOf(candidate);
            if (span.start >= before_pos) continue;
            const ref = hir_mod.typeRefOf(self.hir, candidate);
            if (ref.qualifier_len == 0 and std.mem.eql(u8, self.string_interner.get(ref.name), name)) return true;
        }
        return false;
    }

    fn enclosingClassHasInstanceMemberNamed(
        self: *Checker,
        node: NodeId,
        name: hir_mod.StringId,
    ) CheckError!bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) {
            const k = self.hir.kindOf(cur);
            if (k == .class_decl or k == .class_expr) {
                for (hir_mod.classMembers(self.hir, cur)) |member| {
                    switch (self.hir.kindOf(member)) {
                        .fn_decl, .fn_expr, .arrow_fn => {
                            const fp = hir_mod.fnDeclOf(self.hir, member);
                            if (fp.flags.is_static or fp.flags.is_constructor) continue;
                            const member_name = (try self.classMemberNameFromFunctionName(fp.name)) orelse continue;
                            if (member_name == name) return true;
                        },
                        .object_property => {
                            const op = hir_mod.objectPropertyOf(self.hir, member);
                            if (op.is_static) continue;
                            const is_computed = self.nodeIsBracketedComputedName(op.key) or
                                self.memberSourceLooksComputed(member);
                            const member_name = (try self.classMemberNameFromPropertyKey(op.key, is_computed)) orelse continue;
                            if (member_name == name) return true;
                        },
                        else => {},
                    }
                }
                if (self.classConstructorHasParameterPropertyNamed(cur, name)) return true;
                return false;
            }
            cur = self.hir.parentOf(cur);
        }
        return false;
    }

    fn classConstructorHasParameterPropertyNamed(
        self: *Checker,
        class_node: NodeId,
        name: hir_mod.StringId,
    ) bool {
        for (hir_mod.classMembers(self.hir, class_node)) |member| {
            const k = self.hir.kindOf(member);
            if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) continue;
            const fp = hir_mod.fnDeclOf(self.hir, member);
            if (!fp.flags.is_constructor) continue;
            for (hir_mod.fnParams(self.hir, member)) |param_node| {
                if (self.hir.kindOf(param_node) != .parameter) continue;
                const pp = hir_mod.parameterOf(self.hir, param_node);
                if (!pp.flags.is_parameter_property) continue;
                if (pp.name == hir_mod.none_node_id or self.hir.kindOf(pp.name) != .identifier) continue;
                if (hir_mod.identifierOf(self.hir, pp.name).name == name) return true;
            }
        }
        return false;
    }

    fn enclosingClassStaticMemberClassName(
        self: *Checker,
        node: NodeId,
        name: hir_mod.StringId,
    ) CheckError!?hir_mod.StringId {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) {
            const k = self.hir.kindOf(cur);
            if (k == .class_decl or k == .class_expr) {
                const class_info = hir_mod.classOf(self.hir, cur);
                if (class_info.name == hir_mod.none_node_id or
                    self.hir.kindOf(class_info.name) != .identifier)
                {
                    return null;
                }
                for (hir_mod.classMembers(self.hir, cur)) |member| {
                    switch (self.hir.kindOf(member)) {
                        .fn_decl, .fn_expr, .arrow_fn => {
                            const fp = hir_mod.fnDeclOf(self.hir, member);
                            if (!fp.flags.is_static or fp.flags.is_constructor) continue;
                            const member_name = (try self.classMemberNameFromFunctionName(fp.name)) orelse continue;
                            if (member_name == name) return hir_mod.identifierOf(self.hir, class_info.name).name;
                        },
                        .object_property => {
                            const op = hir_mod.objectPropertyOf(self.hir, member);
                            if (!op.is_static) continue;
                            const is_computed = self.nodeIsBracketedComputedName(op.key) or
                                self.memberSourceLooksComputed(member);
                            const member_name = (try self.classMemberNameFromPropertyKey(op.key, is_computed)) orelse continue;
                            if (member_name == name) return hir_mod.identifierOf(self.hir, class_info.name).name;
                        },
                        else => {},
                    }
                }
                return null;
            }
            cur = self.hir.parentOf(cur);
        }
        return null;
    }

    fn identifierLooksLikeMalformedComputedIndexerTypeSlot(self: *const Checker, node: NodeId) bool {
        const src = self.source orelse return false;
        const sp = self.hir.spanOf(node);
        if (sp.start == 0 or sp.end > src.len) return false;

        var before: usize = sp.start;
        while (before > 0 and isAsciiWhitespace(src[before - 1])) : (before -= 1) {}
        if (before == 0 or src[before - 1] != ':') return false;

        var after: usize = sp.end;
        while (after < src.len and isAsciiWhitespace(src[after])) : (after += 1) {}
        if (after >= src.len or src[after] != ']') return false;

        var scan: usize = before - 1;
        while (scan > 0) {
            scan -= 1;
            switch (src[scan]) {
                '[' => {
                    var prefix_end = scan;
                    while (prefix_end > 0 and isAsciiWhitespace(src[prefix_end - 1])) : (prefix_end -= 1) {}
                    const accessibility = [_][]const u8{ "private", "public", "protected" };
                    for (accessibility) |keyword| {
                        if (prefix_end < keyword.len) continue;
                        const prefix_start = prefix_end - keyword.len;
                        if (!std.mem.eql(u8, src[prefix_start..prefix_end], keyword)) continue;
                        if (prefix_start == 0 or !isIdentifierPartByte(src[prefix_start - 1])) return false;
                    }
                    return true;
                },
                '\n', '\r', '{', '}', ';' => return false,
                else => {},
            }
        }
        return false;
    }

    fn isAsciiWhitespace(c: u8) bool {
        return c == ' ' or c == '\t' or c == '\n' or c == '\r';
    }

    fn lowerAsciiIdentifierEndsWith(value: []const u8, suffix: []const u8) bool {
        if (suffix.len > value.len) return false;
        for (value) |c| {
            if (c < 'a' or c > 'z') return false;
        }
        return std.mem.eql(u8, value[value.len - suffix.len ..], suffix);
    }

    fn reportCannotFindNamePlain(self: *Checker, node: NodeId, name: hir_mod.StringId) !void {
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Cannot find name '{s}'.",
            .{self.string_interner.get(name)},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.cannot_find_name,
            .message = msg,
        });
    }

    fn reportTypeOnlyUsedAsValueOnce(self: *Checker, node: NodeId, name: hir_mod.StringId) !void {
        if (self.identifierIsExportEqualsTarget(node)) return;
        for (self.diagnostics.items) |d| {
            if (d.node == node and d.code == TsCodes.type_only_used_as_value) return;
        }
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' only refers to a type, but is being used as a value here.",
            .{self.string_interner.get(name)},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.type_only_used_as_value,
            .message = msg,
        });
    }

    fn reportTypeOnlyUsedAsValueMappedTypeHintOnce(self: *Checker, node: NodeId, name: hir_mod.StringId) !void {
        for (self.diagnostics.items) |d| {
            if (d.node == node and d.code == TsCodes.type_only_used_as_value_mapped_type_hint) return;
        }
        const raw = self.string_interner.get(name);
        const suggested = if (std.mem.eql(u8, raw, "K")) "P" else "K";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' only refers to a type, but is being used as a value here. Did you mean to use '{s} in {s}'?",
            .{ raw, suggested, raw },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.type_only_used_as_value_mapped_type_hint,
            .message = msg,
        });
    }

    fn reportTypeOnlyUsedAsValueWithMappedTypeHintIfNeeded(
        self: *Checker,
        node: NodeId,
        name: hir_mod.StringId,
    ) !void {
        if (self.typeOnlyUsedAsValueMappedTypeHintApplies(node, name)) {
            try self.reportTypeOnlyUsedAsValueMappedTypeHintOnce(node, name);
        } else {
            try self.reportTypeOnlyUsedAsValueOnce(node, name);
        }
    }

    /// True when `name` is introduced by an import declaration whose
    /// module specifier failed to resolve (a TS2307/TS2792 was emitted
    /// somewhere inside that import statement's span). tsc types such a
    /// binding as `any`, so using it as a type is valid and must not
    /// draw TS2749. Mirrors the clean baseline of
    /// `defaultExportsCannotMerge01-03`, where `import Entity from "m1"`
    /// is unresolved and `var x: Entity` compiles without error.
    fn nameBoundByUnresolvedImport(self: *Checker, anchor: NodeId, name: hir_mod.StringId) bool {
        const anchor_section = self.virtualSectionStartForNode(anchor);
        var cur: hir_mod.NodeId = self.hir.parentOf(anchor);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .block_stmt and k != .namespace_decl) continue;
            const stmts = if (k == .block_stmt)
                hir_mod.blockStmts(self.hir, cur)
            else
                hir_mod.namespaceBody(self.hir, cur);
            for (stmts) |raw| {
                if (self.virtualSectionStartForNode(raw) != anchor_section) continue;
                const decl = self.unwrapExportDecl(raw);
                if (self.hir.kindOf(decl) != .import_decl) continue;
                if (!self.importDeclBindsLocal(decl, name)) continue;
                const imp_span = self.hir.spanOf(decl);
                for (self.diagnostics.items) |d| {
                    if (d.code != TsCodes.cannot_find_module and
                        d.code != TsCodes.cannot_find_module_did_you_mean_nodenext) continue;
                    const dpos = if (d.pos) |p| p else self.hir.spanOf(d.node).start;
                    if (dpos >= imp_span.start and dpos < imp_span.end) return true;
                }
            }
        }
        return false;
    }

    fn reportValueUsedAsTypeDidYouMeanTypeofOnce(self: *Checker, node: NodeId, name: hir_mod.StringId) !void {
        for (self.diagnostics.items) |d| {
            if (d.node == node and d.code == TsCodes.value_used_as_type_did_you_mean_typeof) return;
        }
        // An unresolved-import binding is typed `any` by tsc and is
        // usable as a type — suppress TS2749 for it.
        if (self.nameBoundByUnresolvedImport(node, name)) return;
        const raw = self.string_interner.get(name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' refers to a value, but is being used as a type here. Did you mean 'typeof {s}'?",
            .{ raw, raw },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.value_used_as_type_did_you_mean_typeof,
            .message = msg,
        });
    }

    fn reportQualifiedValueUsedAsTypeDidYouMeanTypeofOnce(self: *Checker, node: NodeId) !void {
        for (self.diagnostics.items) |d| {
            if (d.node == node and d.code == TsCodes.value_used_as_type_did_you_mean_typeof) return;
        }
        const raw = std.mem.trim(u8, self.nodeSourceTextOrEmpty(node), " \t\r\n");
        if (raw.len == 0) return;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "'{s}' refers to a value, but is being used as a type here. Did you mean 'typeof {s}'?",
            .{ raw, raw },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.value_used_as_type_did_you_mean_typeof,
            .message = msg,
        });
    }

    fn reportCannotFindNamePlainOnce(self: *Checker, node: NodeId, name: hir_mod.StringId) !void {
        for (self.diagnostics.items) |d| {
            if (d.node == node and d.code == TsCodes.cannot_find_name) return;
