    /// Classic two-row Levenshtein edit distance. Computes the
    /// minimum number of single-character insertions, deletions, or
    /// substitutions to transform `a` into `b`. O(|a|ÃÂÃÂ·|b|) time,
    /// O(min(|a|,|b|)) space. Used for "did you mean?" suggestions.
    fn levenshtein(a: []const u8, b: []const u8) usize {
        if (a.len == 0) return b.len;
        if (b.len == 0) return a.len;
        // Bound the DP arrays ÃÂ¢ÃÂÃÂ identifier names rarely exceed 128
        // bytes; anything over the cap is treated as max-distance to
        // avoid heap allocation in the hot diagnostic path.
        const cap: usize = 128;
        if (a.len + 1 > cap or b.len + 1 > cap) return std.math.maxInt(usize);
        var prev: [cap]usize = undefined;
        var curr: [cap]usize = undefined;
        var j: usize = 0;
        while (j <= b.len) : (j += 1) prev[j] = j;
        var i: usize = 1;
        while (i <= a.len) : (i += 1) {
            curr[0] = i;
            var k: usize = 1;
            while (k <= b.len) : (k += 1) {
                const cost: usize = if (a[i - 1] == b[k - 1]) 0 else 1;
                const del = prev[k] + 1;
                const ins = curr[k - 1] + 1;
                const sub = prev[k - 1] + cost;
                var m = del;
                if (ins < m) m = ins;
                if (sub < m) m = sub;
                curr[k] = m;
            }
            std.mem.copyForwards(usize, prev[0 .. b.len + 1], curr[0 .. b.len + 1]);
        }
        return prev[b.len];
    }

    /// Case-insensitive (ASCII) Levenshtein. Mirrors the
    /// `equateStringsCaseInsensitive` flag tsc passes to its
    /// `getSpellingSuggestion` helper ÃÂ¢ÃÂÃÂ substitutions that differ
    /// only in ASCII case cost 0, so `$ERROR` ÃÂ¢ÃÂÃÂ `Error` measures
    /// distance 1 (the leading `$`), well within the threshold.
    fn levenshteinIcase(a: []const u8, b: []const u8) usize {
        if (a.len == 0) return b.len;
        if (b.len == 0) return a.len;
        const cap: usize = 128;
        if (a.len + 1 > cap or b.len + 1 > cap) return std.math.maxInt(usize);
        var prev: [cap]usize = undefined;
        var curr: [cap]usize = undefined;
        var j: usize = 0;
        while (j <= b.len) : (j += 1) prev[j] = j;
        var i: usize = 1;
        while (i <= a.len) : (i += 1) {
            curr[0] = i;
            var k: usize = 1;
            while (k <= b.len) : (k += 1) {
                const ai = std.ascii.toLower(a[i - 1]);
                const bk = std.ascii.toLower(b[k - 1]);
                const cost: usize = if (ai == bk) 0 else 1;
                const del = prev[k] + 1;
                const ins = curr[k - 1] + 1;
                const sub = prev[k - 1] + cost;
                var m = del;
                if (ins < m) m = ins;
                if (sub < m) m = sub;
                curr[k] = m;
            }
            std.mem.copyForwards(usize, prev[0 .. b.len + 1], curr[0 .. b.len + 1]);
        }
        return prev[b.len];
    }

    /// tsgo's spelling suggestions charge substitutions as two edits, while
    /// insertions and deletions cost one and case-only differences cost zero.
    fn spellingSuggestionDistanceIcase(a: []const u8, b: []const u8) usize {
        if (a.len == 0) return b.len;
        if (b.len == 0) return a.len;
        const cap: usize = 128;
        if (a.len + 1 > cap or b.len + 1 > cap) return std.math.maxInt(usize);
        var prev: [cap]usize = undefined;
        var curr: [cap]usize = undefined;
        for (0..b.len + 1) |i| prev[i] = i;
        for (1..a.len + 1) |i| {
            curr[0] = i;
            for (1..b.len + 1) |j| {
                const same = std.ascii.toLower(a[i - 1]) == std.ascii.toLower(b[j - 1]);
                const del = prev[j] + 1;
                const ins = curr[j - 1] + 1;
                const sub = prev[j - 1] + @as(usize, if (same) 0 else 2);
                curr[j] = @min(del, @min(ins, sub));
            }
            std.mem.copyForwards(usize, prev[0 .. b.len + 1], curr[0 .. b.len + 1]);
        }
        return prev[b.len];
    }

    /// Returns true when the identifier reference resolves to a
    /// `const`-declared symbol at the source ÃÂ¢ÃÂÃÂ used by TS2588 to
    /// flag assignment to a constant. Walks the same parent-chain
    /// as `typeOfIdentifier` but checks the *kind* of declaration
    /// rather than its type.
    fn identifierResolvesToConst(self: *Checker, node: NodeId) bool {
        const id = hir_mod.identifierOf(self.hir, node);
        var cur: hir_mod.NodeId = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) {
            const k = self.hir.kindOf(cur);
            // Parameter binding shadows outer const decls; if a
            // parameter with this name is in scope, it isn't const.
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                const params = hir_mod.fnParams(self.hir, cur);
                for (params) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id) continue;
                    if (self.hir.kindOf(pp.name) != .identifier) continue;
                    const pid = hir_mod.identifierOf(self.hir, pp.name);
                    if (pid.name == id.name) return false;
                }
            }
            if (k == .for_stmt) {
                const fr = hir_mod.forStmtOf(self.hir, cur);
                if (self.forInitializerDeclKindForName(fr.init, id.name)) |decl_kind| {
                    return decl_kind == .const_decl;
                }
            }
            if (k == .for_in_stmt or k == .for_of_stmt) {
                const fr = hir_mod.forInOf(self.hir, cur);
                const tk = self.hir.kindOf(fr.target);
                if (tk == .var_decl or tk == .let_decl or tk == .const_decl) {
                    const v = hir_mod.varDeclOf(self.hir, fr.target);
                    if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                        const tid = hir_mod.identifierOf(self.hir, v.name);
                        if (tid.name == id.name) return tk == .const_decl;
                    }
                }
            }
            if (k == .block_stmt) {
                const stmts = hir_mod.blockStmts(self.hir, cur);
                for (stmts) |s| {
                    const sk = self.hir.kindOf(s);
                    if (sk == .var_decl or sk == .let_decl or sk == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, s);
                        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                            const vid = hir_mod.identifierOf(self.hir, v.name);
                            if (vid.name == id.name) return sk == .const_decl;
                        }
                    }
                }
            }
            cur = self.hir.parentOf(cur);
        }
        // Module-level fallback via the binder's symbol table.
        if (self.module) |module| {
            if (module.root.lookup(id.name)) |sym| {
                return sym.flags.is_const;
            }
        }
        return false;
    }

    fn forInitializerDeclKindForName(self: *Checker, init_node: NodeId, name: hir_mod.StringId) ?hir_mod.NodeKind {
        if (init_node == hir_mod.none_node_id) return null;
        const k = self.hir.kindOf(init_node);
        if (k == .var_decl or k == .let_decl or k == .const_decl) {
            const v = hir_mod.varDeclOf(self.hir, init_node);
            if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                const id = hir_mod.identifierOf(self.hir, v.name);
                if (id.name == name) return k;
            }
            return null;
        }
        if (k == .block_stmt) {
            for (hir_mod.blockStmts(self.hir, init_node)) |stmt| {
                const sk = self.hir.kindOf(stmt);
                if (sk != .var_decl and sk != .let_decl and sk != .const_decl) continue;
                const v = hir_mod.varDeclOf(self.hir, stmt);
                if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
                const id = hir_mod.identifierOf(self.hir, v.name);
                if (id.name == name) return sk;
            }
        }
        return null;
    }

    /// True when `node` is an identifier whose name resolves at module
    /// scope to a value-side import alias (`import { x } from "m"`,
    /// `import d from "m"`, `import * as ns from "m"`) and isn't
    /// shadowed by an inner parameter or `var`/`let`/`const`. Used by
    /// the assignment-statement classifier to emit TS2632
    /// (`import { x } from "m"; x = 1;`). Mirrors upstream tsc, which
    /// fires this when an assignment target resolves to an alias symbol
    /// that is not a variable. Assigning to an import's *property*
    /// (`ns.x = 1`) is a member-access target and never reaches here,
    /// matching upstream (that case is TS2540, not TS2632).
    fn identifierResolvesToValueImport(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, node);
        var cur: hir_mod.NodeId = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) {
            const k = self.hir.kindOf(cur);
            // A parameter binding with this name shadows the import.
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                const params = hir_mod.fnParams(self.hir, cur);
                for (params) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id) continue;
                    if (self.hir.kindOf(pp.name) != .identifier) continue;
                    const pid = hir_mod.identifierOf(self.hir, pp.name);
                    if (pid.name == id.name) return false;
                }
            }
            // An inner `var`/`let`/`const` with this name shadows the
            // import (a legal rebind in a nested block).
            if (k == .block_stmt) {
                for (hir_mod.blockStmts(self.hir, cur)) |s| {
                    const sk = self.hir.kindOf(s);
                    if (sk == .var_decl or sk == .let_decl or sk == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, s);
                        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                            const vid = hir_mod.identifierOf(self.hir, v.name);
                            if (vid.name == id.name) return false;
                        }
                    }
                }
            }
            cur = self.hir.parentOf(cur);
        }
        // Module-level: the value-space symbol must be an import alias.
        const module = self.module orelse return false;
        const sym = module.root.values.get(id.name) orelse return false;
        return sym.flags.is_import;
    }

    /// True when `node` is an identifier whose name resolves to a
    /// `namespace`/`module` declaration AND has no separate value-side
    /// binding (e.g. `var M = ...` redeclaring the namespace name).
    fn identifierResolvesToNamespaceOnly(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, node);
        // Local shadow: a `var`/`let`/`const`/parameter with the same
        // name in scope means the identifier is a value, not the
        // namespace.
        var cur: hir_mod.NodeId = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                const params = hir_mod.fnParams(self.hir, cur);
                for (params) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id) continue;
                    if (self.hir.kindOf(pp.name) != .identifier) continue;
                    const pid = hir_mod.identifierOf(self.hir, pp.name);
                    if (pid.name == id.name) return false;
                }
            }
            if (k == .block_stmt) {
                for (hir_mod.blockStmts(self.hir, cur)) |s| {
                    const sk = self.hir.kindOf(s);
                    if (sk == .var_decl or sk == .let_decl or sk == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, s);
                        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                            const vid = hir_mod.identifierOf(self.hir, v.name);
                            if (vid.name == id.name) return false;
                        }
                    } else if (sk == .fn_decl) {
                        const fd = hir_mod.fnDeclOf(self.hir, s);
                        if (fd.name != hir_mod.none_node_id and self.hir.kindOf(fd.name) == .identifier) {
                            const fid = hir_mod.identifierOf(self.hir, fd.name);
                            if (fid.name == id.name) return false;
                        }
                    } else if (sk == .class_decl) {
                        const cd = hir_mod.classOf(self.hir, s);
                        if (cd.name != hir_mod.none_node_id and self.hir.kindOf(cd.name) == .identifier) {
                            const cid = hir_mod.identifierOf(self.hir, cd.name);
                            if (cid.name == id.name) return false;
                        }
                    }
                }
            }
            cur = self.hir.parentOf(cur);
        }
        // Module-level: a namespace decl exists, and there is no
        // value-binding shadow (var/let/const/fn/class with the same
        // name).
        const module = self.module orelse return false;
        if (module.root.namespaces.get(id.name) == null) return false;
        if (module.root.values.get(id.name)) |sym| {
            for (sym.decls.items) |decl| {
                const dk = self.hir.kindOf(decl);
                // namespace_decl entries are also recorded in `values`
                // when they have runtime members, so we must not bail
                // on those ÃÂ¢ÃÂÃÂ only on real value-side declarations.
                if (dk == .namespace_decl or dk == .module_decl) continue;
                return false;
            }
        }
        return true;
    }

    fn identifierResolvesToRuntimeNamespace(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) == .identifier) {
            const id = hir_mod.identifierOf(self.hir, node);
            var cur = self.hir.parentOf(node);
            while (cur != hir_mod.none_node_id) {
                if (self.hir.kindOf(cur) == .namespace_decl) {
                    if (self.findNamedValueDeclInNamespace(cur, id.name)) |decl| {
                        return self.hir.kindOf(decl) == .namespace_decl and self.namespaceHasRuntimeValue(decl);
                    }
                }
                const parent = self.hir.parentOf(cur);
                if (parent == cur) break;
                cur = parent;
            }
        }
        if (!self.identifierResolvesToNamespaceOnly(node)) return false;
        const module = self.module orelse return false;
        const id = hir_mod.identifierOf(self.hir, node);
        return !self.moduleNameIsNamespaceOnlyValue(module, id.name);
    }

    /// True when `node` is an identifier whose name resolves at module
    /// scope to a particular value-side declaration kind (class, enum,
    /// or function), or ÃÂ¢ÃÂÃÂ for `interface_t` ÃÂ¢ÃÂÃÂ to a type-only binding,
    /// and isn't shadowed by an inner parameter or `var`/`let`/`const`.
    /// Used by the assignment-statement classifier to emit TS2628
    /// (`enum E { ÃÂ¢ÃÂÃÂ¦ }; E = 1`), TS2629 (`class C { }; C = 1`), TS2630
    /// (`function fn() { }; fn = 1`), and TS2693 (`interface I { };
    /// I = 1`). Mirrors `assignments.ts` baselines.
    ///
    /// Unlike `identifierResolvesToNamespaceOnly`, this helper does NOT
    /// treat sibling `class`/`fn` decls in the top-level block as
    /// shadows ÃÂ¢ÃÂÃÂ that "shadow" IS the very declaration whose name
    /// we're trying to detect. Only inner-block `var`/`let`/`const`
    /// (which can legally shadow a class/function name) actually
    /// rebind the slot.
    fn identifierResolvesToValueDeclKind(
        self: *Checker,
        node: NodeId,
        comptime DeclKind: enum { class, function_t, enum_t, interface_t },
    ) bool {
        if (self.hir.kindOf(node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, node);
        var cur: hir_mod.NodeId = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                const params = hir_mod.fnParams(self.hir, cur);
                for (params) |p| {
                    if (self.hir.kindOf(p) != .parameter) continue;
                    const pp = hir_mod.parameterOf(self.hir, p);
                    if (pp.name == hir_mod.none_node_id) continue;
                    if (self.hir.kindOf(pp.name) != .identifier) continue;
                    const pid = hir_mod.identifierOf(self.hir, pp.name);
                    if (pid.name == id.name) return false;
                }
            }
            if (k == .block_stmt) {
                for (hir_mod.blockStmts(self.hir, cur)) |s| {
                    const sk = self.hir.kindOf(s);
                    if (sk == .var_decl or sk == .let_decl or sk == .const_decl) {
                        const v = hir_mod.varDeclOf(self.hir, s);
                        if (v.name != hir_mod.none_node_id and self.hir.kindOf(v.name) == .identifier) {
                            const vid = hir_mod.identifierOf(self.hir, v.name);
                            if (vid.name == id.name) return false;
                        }
                    }
                }
            }
            cur = self.hir.parentOf(cur);
        }
        const module = self.module orelse return false;
        switch (DeclKind) {
            .interface_t => {
                // Interfaces / type-aliases only live in the type
                // table. TS2693 fires when the identifier resolves to
                // *only* a type (no value-side binding, no namespace
                // alias).
                if (module.root.types.get(id.name) == null) return false;
                if (module.root.values.get(id.name) != null) return false;
                if (module.root.namespaces.get(id.name) != null) return false;
                return true;
            },
            else => {
                const sym = module.root.values.get(id.name) orelse return false;
                if (sym.decls.items.len == 0) return false;
                return switch (DeclKind) {
                    .class => sym.flags.is_class,
                    .function_t => sym.flags.is_function and !sym.flags.is_class,
                    .enum_t => sym.flags.is_enum,
                    .interface_t => unreachable,
                };
            },
        }
    }

    /// Conservative gate for TS2367: return true only when both
    /// sides look like concrete primitives (string / number / boolean
    /// / bigint / symbol / void) or literals of those. Nullish equality
    /// probes are intentionally exempt: TS's comparable relation
    /// permits `x === null` / `x === undefined` style checks even
    /// when `x` is currently a non-nullish primitive under
    /// `strictNullChecks`. Skips unions, intersections, object
    /// types, type parameters, any/unknown/never, and other compound
    /// shapes ÃÂ¢ÃÂÃÂ TS allows many of those comparisons even when they
    /// look unrelated, and our `isComparableTo` is too coarse to
    /// reproduce TS's `comparableRelation` exactly.
    fn shouldCheckNoOverlap(self: *Checker, a: TypeId, b: TypeId) bool {
        if (self.isNullishType(a) or self.isNullishType(b)) return false;
        if (a == types.Primitive.void_t or b == types.Primitive.void_t) {
            const other = if (a == types.Primitive.void_t) b else a;
            return self.isConcretePrimitiveLike(other) or self.enumNameFromNominal(other) != null;
        }
        return self.isConcretePrimitiveLike(a) and self.isConcretePrimitiveLike(b);
    }

    fn typesHaveComparableOverlap(self: *Checker, a: TypeId, b: TypeId) CheckError!bool {
        return self.typesHaveComparableOverlapLimit(a, b, 0);
    }

    fn typesHaveComparableOverlapLimit(self: *Checker, a: TypeId, b: TypeId, depth: u8) CheckError!bool {
        if (a == b) return true;
        if (depth > 32) return true;
        if (self.typeIsAnyLike(a) or self.typeIsAnyLike(b)) return true;
        if (self.isNullishType(a) or self.isNullishType(b)) return true;
        if (a == types.Primitive.void_t or b == types.Primitive.void_t) return false;
        if (self.enumNumberLiteralOverlap(a, b)) |ok| return ok;
        if (self.enumNumberLiteralOverlap(b, a)) |ok| return ok;
        if (a >= self.interner.pool.typeCount() or b >= self.interner.pool.typeCount()) return true;

        const af = self.interner.pool.flagsOf(a);
        const bf = self.interner.pool.flagsOf(b);
        if (self.classPrivateComparableMismatch(a, b)) return false;
        if (af.is_union) {
            for (self.interner.unionMembers(a)) |member| {
                if (try self.typesHaveComparableOverlapLimit(member, b, depth + 1)) return true;
            }
            return false;
        }
        if (bf.is_union) {
            for (self.interner.unionMembers(b)) |member| {
                if (try self.typesHaveComparableOverlapLimit(a, member, depth + 1)) return true;
            }
            return false;
        }
        if (af.is_intersection) {
            var saw_concrete = false;
            for (self.interner.intersectionMembers(a)) |member| {
                if (!self.isConcretePrimitiveLike(member)) continue;
                saw_concrete = true;
                if (!try self.typesHaveComparableOverlapLimit(member, b, depth + 1)) return false;
            }
            if (saw_concrete) return true;
            if (self.intersectionContainsObjectLike(a)) {
                return self.engine.isComparableTo(a, b) catch true;
            }
            for (self.interner.intersectionMembers(a)) |member| {
                if (try self.typesHaveComparableOverlapLimit(member, b, depth + 1)) return true;
            }
            return false;
        }
        if (bf.is_intersection) {
            var saw_concrete = false;
            for (self.interner.intersectionMembers(b)) |member| {
                if (!self.isConcretePrimitiveLike(member)) continue;
                saw_concrete = true;
                if (!try self.typesHaveComparableOverlapLimit(a, member, depth + 1)) return false;
            }
            if (saw_concrete) return true;
            if (self.intersectionContainsObjectLike(b)) {
                return self.engine.isComparableTo(a, b) catch true;
            }
            for (self.interner.intersectionMembers(b)) |member| {
                if (try self.typesHaveComparableOverlapLimit(a, member, depth + 1)) return true;
            }
            return false;
        }
        if (self.weakObjectPrimitiveMayOverlap(a, b) or self.weakObjectPrimitiveMayOverlap(b, a)) return true;
        if (self.objectPrimitiveHasNoOverlap(a, b) or self.objectPrimitiveHasNoOverlap(b, a)) return false;
        // `void` has no overlap with any concrete primitive or enum ÃÂ¢ÃÂÃÂ
        // tsc fires TS2367 for `number == void`, `string == void`, etc.
        // (See comparisonOperatorWithNoRelationshipPrimitiveType.ts.)
        // Only suppressed for any/unknown/null/undefined (handled above).
        if (af.is_void and (self.isConcretePrimitiveLike(b) or self.enumNameFromNominal(b) != null)) return false;
        if (bf.is_void and (self.isConcretePrimitiveLike(a) or self.enumNameFromNominal(a) != null)) return false;
        if (self.isConcretePrimitiveLike(a) and self.isConcretePrimitiveLike(b)) {
            return self.engine.isComparableTo(a, b) catch true;
        }
        if (af.is_signature and bf.is_signature) {
            return try self.signaturesHaveComparableOverlap(a, b, depth + 1);
        }
        if (af.is_object_type and bf.is_object_type) {
            if (self.objectTypeIsCallOrConstructOnly(a) or
                self.objectTypeIsCallOrConstructOnly(b))
            {
                return try self.signatureObjectTypesHaveComparableOverlap(a, b, depth + 1);
            }
            if (try self.objectTypesHaveIndependentOverlap(a, b, depth + 1)) return true;
        }
        // Bare signature types (method-shorthand, function types) need
        // the same bidirectional comparable-overlap treatment as
        // call-signature-only object types ÃÂ¢ÃÂÃÂ params related in either
        // direction at each position must not generate TS2365.
        if (af.is_signature and bf.is_signature) {
            return try self.signaturesHaveComparableOverlap(a, b, depth + 1);
        }
        if (self.isObjectLikeType(a) or self.isObjectLikeType(b)) {
            return self.engine.isComparableTo(a, b) catch true;
        }
        // Two distinct type parameters with no relating constraint
        // have no provable overlap ÃÂ¢ÃÂÃÂ tsc emits TS2367 for `t == u`
        // where T and U are sibling type parameters. Mirrors fixtures
        // like comparisonOperatorWithTypeParameter.ts.
        if (af.is_type_parameter and bf.is_type_parameter and a != b) {
            if (!self.typeParameterConstraintsRelate(a, b)) return false;
        }
        return true;
    }

    fn typeParameterConstraintsRelate(self: *Checker, a: TypeId, b: TypeId) bool {
        // Allow comparison when one parameter's constraint chain
        // reaches the other (e.g., `U extends T`), or when they share
        // a common ancestor constraint type.
        if (self.typeParameterConstraintReaches(a, b)) return true;
        if (self.typeParameterConstraintReaches(b, a)) return true;
        return false;
    }

    fn typeParameterConstraintReaches(self: *Checker, from: TypeId, target: TypeId) bool {
        var cur = from;
        var depth: u8 = 0;
        while (depth < 16) : (depth += 1) {
            const constraint = self.typeParameterConstraint(cur) orelse return false;
            if (constraint == target) return true;
            if (constraint == cur) return false;
            const cf = self.interner.pool.flagsOf(constraint);
            if (!cf.is_type_parameter) return false;
            cur = constraint;
        }
        return false;
    }

    fn enumNumberLiteralOverlap(self: *Checker, enum_t: TypeId, lit_t: TypeId) ?bool {
        const enum_name = self.enumNameFromNominal(enum_t) orelse return null;
        const value = self.numberLiteralValueFromType(lit_t) orelse return null;
        var it = self.enum_member_values.iterator();
        while (it.next()) |entry| {
            if (entry.key_ptr.obj_name == enum_name and entry.value_ptr.* == value) return true;
        }
        return false;
    }

    fn numberLiteralValueFromType(self: *Checker, t: TypeId) ?f64 {
        if (t >= self.interner.pool.typeCount()) return null;
        const f = self.interner.pool.flagsOf(t);
        if (!f.is_literal or !f.is_number) return null;
        return switch (self.interner.literalOf(t)) {
            .number_lit => |bits| @as(f64, @bitCast(bits)),
            else => null,
        };
    }

    fn objectPrimitiveHasNoOverlap(self: *Checker, maybe_obj: TypeId, maybe_prim: TypeId) bool {
        if (!self.isConcretePrimitiveLike(maybe_prim)) return false;
        return self.assertionObjectConstituentHasNoPrimitiveOverlap(maybe_obj, maybe_prim);
    }

    fn weakObjectPrimitiveMayOverlap(self: *Checker, maybe_obj: TypeId, maybe_prim: TypeId) bool {
        if (!self.isConcretePrimitiveLike(maybe_prim)) return false;
        return self.objectTypeIsWeak(maybe_obj);
    }

    fn isObjectLikeType(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        return f.is_object_type or f.is_signature or f.is_tuple;
    }

    fn objectTypeIsWeak(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (!f.is_object_type) return false;
        if (self.classNameForInstanceType(t)) |class_name| {
            if (self.classHasPrivateMembers(class_name)) return false;
        }
        if (self.objectTypeIsCallOrConstructOnly(t)) return false;
        if (self.interner.objectStringIndex(t) != types.Primitive.none or
            self.interner.objectNumberIndex(t) != types.Primitive.none or
            self.interner.objectSymbolIndex(t) != types.Primitive.none)
        {
            return false;
        }
        for (self.interner.objectMembers(t)) |member| {
            if (!member.is_optional) return false;
        }
        return true;
    }

    /// True when `t` is an object whose every member is a call
    /// (`__call`) or construct (`__construct`) signature ÃÂ¢ÃÂÃÂ i.e. the
    /// type denotes a function value with no instance properties.
    fn objectTypeIsCallOrConstructOnly(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (!f.is_object_type) return false;
        const members = self.interner.objectMembers(t);
        if (members.len == 0) return false;
        const call_id = self.string_interner.intern("__call") catch return false;
        const construct_id = self.string_interner.intern("__construct") catch return false;
        for (members) |m| {
            if (m.name != call_id and m.name != construct_id) return false;
        }
        return true;
    }

    fn signatureObjectTypesHaveComparableOverlap(self: *Checker, a: TypeId, b: TypeId, depth: u8) CheckError!bool {
        const call_id = self.string_interner.intern("__call") catch return true;
        const construct_id = self.string_interner.intern("__construct") catch return true;
        var saw_signature_pair = false;
        for (self.interner.objectMembers(a)) |am| {
            if (am.name != call_id and am.name != construct_id) continue;
            const bm = self.interner.objectMemberInfo(b, am.name) orelse continue;
            saw_signature_pair = true;
            if (try self.signaturesHaveComparableOverlap(am.type, bm.type, depth + 1)) return true;
        }
        return !saw_signature_pair and
            !self.objectTypeIsCallOrConstructOnly(a) and
            !self.objectTypeIsCallOrConstructOnly(b);
    }

    fn signaturesHaveComparableOverlap(self: *Checker, a: TypeId, b: TypeId, depth: u8) CheckError!bool {
        if (!self.interner.isSignature(a) or !self.interner.isSignature(b)) return true;
        if (self.containsFreeTypeParameter(a) or self.containsFreeTypeParameter(b)) return true;
        const ar = self.interner.signatureReturn(a) orelse types.Primitive.any;
        const br = self.interner.signatureReturn(b) orelse types.Primitive.any;
        if (ar != types.Primitive.void_t and br != types.Primitive.void_t and
            !try self.typesHaveComparableOverlapLimit(ar, br, depth + 1))
        {
            return false;
        }
        const ap = self.interner.signatureParams(a);
        const bp = self.interner.signatureParams(b);
        const compare_len = @min(ap.len, bp.len);
        var i: usize = 0;
        while (i < compare_len) : (i += 1) {
            if (!try self.signatureParameterTypesHaveComparableOverlap(ap[i], bp[i], depth + 1)) return false;
        }
        return true;
    }

    fn signatureParameterTypesHaveComparableOverlap(self: *Checker, a: TypeId, b: TypeId, depth: u8) CheckError!bool {
        const a_elem = self.interner.objectNumberIndex(a);
        const b_elem = self.interner.objectNumberIndex(b);
        if (a_elem != types.Primitive.none and b_elem != types.Primitive.none) {
            return try self.typesHaveComparableOverlapLimit(a_elem, b_elem, depth + 1);
        }
        return try self.typesHaveComparableOverlapLimit(a, b, depth + 1);
    }

    fn objectTypesHaveIndependentOverlap(self: *Checker, a: TypeId, b: TypeId, depth: u8) CheckError!bool {
        if (self.classPrivateComparableMismatch(a, b)) return false;
        var saw_common = false;
        for (self.interner.objectMembers(a)) |am| {
            const bm = self.interner.objectMemberInfo(b, am.name) orelse continue;
            saw_common = true;
            if (am.is_optional or bm.is_optional) continue;
            if (self.interner.isSignature(am.type) and self.interner.isSignature(bm.type)) {
                if (!try self.signaturesHaveComparableOverlap(am.type, bm.type, depth + 1)) return false;
                continue;
            }
            if (!try self.typesHaveComparableOverlapLimit(am.type, bm.type, depth + 1)) return false;
        }
        if (try self.objectIndexSignaturesHaveComparableOverlap(a, b, depth + 1)) |index_overlap| {
            return index_overlap;
        }
        return saw_common or self.objectTypeIsWeak(a) or self.objectTypeIsWeak(b);
    }

    fn objectIndexSignaturesHaveComparableOverlap(self: *Checker, a: TypeId, b: TypeId, depth: u8) CheckError!?bool {
        var saw_pair = false;
        const a_string = self.interner.objectStringIndex(a);
        const b_string = self.interner.objectStringIndex(b);
        if (a_string != types.Primitive.none and b_string != types.Primitive.none) {
            saw_pair = true;
            if (try self.typesHaveComparableOverlapLimit(a_string, b_string, depth + 1)) return true;
        }
        const a_number = self.interner.objectNumberIndex(a);
        const b_number = self.interner.objectNumberIndex(b);
        if (a_number != types.Primitive.none and b_number != types.Primitive.none) {
            saw_pair = true;
            if (try self.typesHaveComparableOverlapLimit(a_number, b_number, depth + 1)) return true;
        }
        if (a_number != types.Primitive.none and b_string != types.Primitive.none) {
            saw_pair = true;
            if (try self.typesHaveComparableOverlapLimit(a_number, b_string, depth + 1)) return true;
        }
        if (a_string != types.Primitive.none and b_number != types.Primitive.none) {
            saw_pair = true;
            if (try self.typesHaveComparableOverlapLimit(a_string, b_number, depth + 1)) return true;
        }
        return if (saw_pair) false else null;
    }

    fn classPrivateComparableMismatch(self: *Checker, a: TypeId, b: TypeId) bool {
        const a_name = self.classNameForInstanceType(a) orelse return false;
        const b_name = self.classNameForInstanceType(b) orelse return false;
        if (a_name == b_name or self.classesRelatedByHeritage(a_name, b_name)) return false;
        if (self.classHasPrivateMembers(a_name) or self.classHasPrivateMembers(b_name)) return true;
        return self.classPrivateMembersOverlapOther(a, b) or
            self.classPrivateMembersOverlapOther(b, a);
    }

    fn classNameForInstanceType(self: *Checker, t: TypeId) ?hir_mod.StringId {
        if (self.class_name_by_instance.get(t)) |name| return name;
        if (t < self.interner.pool.typeCount()) {
            const f = self.interner.pool.flagsOf(t);
            const payload_idx = self.interner.pool.payloadOf(t);
            if (f.is_intersection and payload_idx < self.interner.pool.intersection_payloads.items.len) {
                for (self.interner.intersectionMembers(t)) |member| {
                    if (self.classNameForInstanceType(member)) |member_name| return member_name;
                }
            }
        }
        const named = self.namedTypeForId(t) orelse return null;
        if (self.class_private_members.contains(named) or self.class_instance_types.contains(named)) return named;
        return null;
    }

    fn classHasPrivateMembers(self: *Checker, class_name: hir_mod.StringId) bool {
        const private = self.class_private_members.getPtr(class_name) orelse return false;
        return private.count() > 0;
    }

    fn classesRelatedByHeritage(self: *Checker, a: hir_mod.StringId, b: hir_mod.StringId) bool {
        return self.classExtendsClass(a, b) or self.classExtendsClass(b, a);
    }

    fn classExtendsClass(self: *Checker, child: hir_mod.StringId, parent: hir_mod.StringId) bool {
        var probe: ?hir_mod.StringId = child;
        var depth: u8 = 0;
        while (probe) |cur| : (depth += 1) {
            if (depth >= 32) return false;
            const next = self.class_parent.get(cur) orelse return false;
            if (next == parent) return true;
            probe = next;
        }
        return false;
    }

    fn intersectionContainsObjectLike(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (!f.is_intersection) return false;
        for (self.interner.intersectionMembers(t)) |member| {
            if (self.isObjectLikeType(member)) return true;
        }
        return false;
    }

    fn templateTypesHaveNoOverlap(self: *Checker, a: TypeId, b: TypeId) bool {
        if (a >= self.interner.pool.typeCount() or b >= self.interner.pool.typeCount()) return false;
        const af = self.interner.pool.flagsOf(a);
        const bf = self.interner.pool.flagsOf(b);
        if (!af.is_template_literal or !bf.is_template_literal) return false;
        const a_texts = self.interner.templateLiteralTexts(a);
        const b_texts = self.interner.templateLiteralTexts(b);
        if (a_texts.len == 0 or b_texts.len == 0) return false;
        const a_prefix = self.string_interner.get(a_texts[0]);
        const b_prefix = self.string_interner.get(b_texts[0]);
        if (a_prefix.len > 0 and b_prefix.len > 0 and
            !std.mem.startsWith(u8, a_prefix, b_prefix) and
            !std.mem.startsWith(u8, b_prefix, a_prefix))
        {
            return true;
        }
        const a_suffix = self.string_interner.get(a_texts[a_texts.len - 1]);
        const b_suffix = self.string_interner.get(b_texts[b_texts.len - 1]);
        if (a_suffix.len > 0 and b_suffix.len > 0 and
            !std.mem.endsWith(u8, a_suffix, b_suffix) and
            !std.mem.endsWith(u8, b_suffix, a_suffix))
        {
            return true;
        }
        return false;
    }

    fn isNullishType(self: *Checker, t: TypeId) bool {
        const f = self.interner.pool.flagsOf(t);
        return f.is_null or f.is_undefined;
    }

    fn isConcretePrimitiveLike(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.any or
            t == types.Primitive.unknown or
            t == types.Primitive.never or
            t == types.Primitive.void_t)
        {
            return false;
        }
        const f = self.interner.pool.flagsOf(t);
        if (f.is_union or f.is_intersection or
            f.is_object_type or f.is_object or
            f.is_signature or f.is_tuple or
            f.is_type_parameter or f.is_instantiation or
            f.is_conditional or f.is_mapped or
            f.is_indexed_access or f.is_keyof or
            f.is_typeof or f.is_infer or
            f.is_template_literal)
        {
            return false;
        }
        return f.is_string or f.is_number or f.is_boolean or
            f.is_bigint or f.is_symbol;
    }

    fn typeContainsSymbol(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_object_type or f.is_signature or f.is_tuple or f.is_type_parameter) return false;
        if (f.is_symbol) return true;
        if (!f.is_union) return false;
        for (self.interner.unionMembers(t)) |member| {
            if (self.typeContainsSymbol(member)) return true;
        }
        return false;
    }

    /// Mirrors tsc's `checkRightHandSideOfForOf` for `for-in`: the
    /// right-hand side must be `any`, an object type, or a type
    /// parameter (after stripping null/undefined). Returns true when
    /// the type is definitely invalid (a non-object primitive,
    /// enum-literal, void, or never), so the caller can fire TS2407.
    /// Conservative: returns false for unions/intersections whose
    /// members include any valid for-in source, and false for unknown
    /// constructions we can't classify (no over-firing).
    fn forInSourceIsInvalid(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.any or
            t == types.Primitive.unknown or
            t == types.Primitive.object_t or
            t == types.Primitive.null_t or
            t == types.Primitive.undefined_t)
        {
            // null/undefined alone would error TS2532 elsewhere; do
            // not double-fire TS2407 on them. `unknown` is permitted.
            return false;
        }
        if (t == types.Primitive.string_t or
            t == types.Primitive.number_t or
            t == types.Primitive.boolean_t or
            t == types.Primitive.bigint_t or
            t == types.Primitive.void_t or
            t == types.Primitive.never or
            t == types.Primitive.true_lit or
            t == types.Primitive.false_lit)
        {
            return true;
        }
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_object_type or f.is_signature or f.is_tuple or f.is_type_parameter) return false;
        if (f.is_intersection) {
            // An intersection is valid as long as ANY component is a
            // valid for-in source.
            for (self.interner.intersectionMembers(t)) |member| {
                if (!self.forInSourceIsInvalid(member)) return false;
            }
            return true;
        }
        if (f.is_union) {
            // A union is invalid only when EVERY member is invalid.
            for (self.interner.unionMembers(t)) |member| {
                if (!self.forInSourceIsInvalid(member)) return false;
            }
            return true;
        }
        if (f.is_keyof or f.is_indexed_access or f.is_conditional or
            f.is_typeof or f.is_infer or f.is_template_literal)
        {
            return false;
        }
        // Literals and enum-literals ÃÂ¢ÃÂÃÂ invalid (cannot enumerate).
        return f.is_string or f.is_number or f.is_boolean or
            f.is_bigint or f.is_symbol;
    }

    fn computedPropertyKeyTypeIsValid(self: *Checker, t: TypeId) CheckError!bool {
        if (t == types.Primitive.any or t == types.Primitive.unknown) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (t == types.Primitive.never) return true;
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!try self.computedPropertyKeyTypeIsValid(member)) return false;
            }
            return true;
        }
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (try self.computedPropertyKeyTypeIsValid(member)) return true;
            }
            return false;
        }
        if (f.is_void) return true;
        if (f.is_string or f.is_number or f.is_symbol) return true;
        if (f.is_keyof) return true;
        if (f.is_conditional) {
            const conditional = self.interner.conditionalPayload(t);
            return try self.computedPropertyKeyTypeIsValid(conditional.true_branch) and
                try self.computedPropertyKeyTypeIsValid(conditional.false_branch);
        }
        if (f.is_indexed_access and !f.is_union and !f.is_intersection) {
            if (try self.indexedAccessBaseConstraint(t, 0)) |constraint| {
                if (constraint != t) return try self.computedPropertyKeyTypeIsValid(constraint);
            }
        }
        if (f.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return try self.computedPropertyKeyTypeIsValid(constraint);
        }
        return false;
    }

    fn indexTypeExcludesSymbol(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) {
            const resolved = self.resolvedTypeParameterPlaceholder(t);
            if (self.type_parameter_decl_nodes.get(resolved)) |decl_node| {
                if (decl_node != hir_mod.none_node_id and self.hir.kindOf(decl_node) == .type_parameter) {
                    const decl = hir_mod.typeParameterOf(self.hir, decl_node);
                    if (self.typeNodeIsExcludeSymbol(decl.constraint)) return true;
                }
            }
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.indexTypeExcludesSymbol(constraint);
        }
        if (self.alias_display_names.get(t)) |display| {
            const compact = std.mem.trim(u8, display, " \t\r\n");
            if (std.mem.startsWith(u8, compact, "Exclude<") and
                std.mem.endsWith(u8, compact, ", symbol>"))
            {
                return true;
            }
        }
        return false;
    }

    fn typeNodeIsExcludeSymbol(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .type_ref) return false;
        const ref = hir_mod.typeRefOf(self.hir, node);
        if (ref.qualifier_len != 0 or
            !std.mem.eql(u8, self.string_interner.get(ref.name), "Exclude"))
        {
            return false;
        }
        const args = hir_mod.typeRefArgs(self.hir, node);
        return args.len == 2 and self.typeNodeIsBareName(args[1], "symbol");
    }

    fn resolvedTypeParameterPlaceholder(self: *Checker, t: TypeId) TypeId {
        var current = t;
        var depth: u8 = 0;
        while (depth < 16) : (depth += 1) {
            const next = self.type_parameter_placeholder_targets.get(current) orelse return current;
            if (next == current) return current;
            current = next;
        }
        return current;
    }

    fn typeParameterConstraint(self: *Checker, t: TypeId) ?TypeId {
        const resolved_t = self.resolvedTypeParameterPlaceholder(t);
        if (resolved_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(resolved_t);
        if (!flags.is_type_parameter) return null;
        const payload_idx = self.interner.pool.payloadOf(resolved_t);
        if (payload_idx >= self.interner.pool.type_parameter_payloads.items.len) return null;
        const tp = self.interner.pool.type_parameter_payloads.items[payload_idx];
        if (tp.constraint == types.Primitive.none or tp.constraint == types.Primitive.unknown) return null;
        return self.resolvedTypeParameterPlaceholder(tp.constraint);
    }

    /// Resolve a type parameter to its base constraint (apparent type)
    /// for operator-operand validity checks. tsc's
    /// `checkBinaryLikeExpression` types operands via `getApparentType`,
    /// so a type parameter `T extends number` behaves like `number` for
    /// the `+` validity decision ÃÂ¢ÃÂÃÂ the operator is applied to the
    /// constraint, not the bare parameter. Constraints can chain
    /// (`<U extends T, T extends number>`), so follow the chain; a small
    /// depth cap guards against malformed cyclic payloads. Returns the
    /// input unchanged when `t` is not a (constrained) type parameter.
    fn operandApparentType(self: *Checker, t: TypeId) TypeId {
        var cur = t;
        var depth: usize = 0;
        while (depth < 16) : (depth += 1) {
            const constraint = self.typeParameterConstraint(cur) orelse return cur;
            if (constraint == cur) return cur;
            cur = constraint;
        }
        return cur;
    }

    fn typeParameterBaseConstraint(self: *Checker, t: TypeId) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(t).is_type_parameter) return null;
        var cur = self.typeParameterConstraint(t) orelse return null;
        var depth: usize = 0;
        while (depth < 16) : (depth += 1) {
            if (cur >= self.interner.pool.typeCount()) return cur;
            const flags = self.interner.pool.flagsOf(cur);
            if (!flags.is_type_parameter) return cur;
            const next = self.typeParameterConstraint(cur) orelse return cur;
            if (next == cur) return cur;
            cur = next;
        }
        return cur;
    }

    fn maybeReportGenericIndexedWrite(
        self: *Checker,
        node: NodeId,
        obj_t: TypeId,
        idx_t: TypeId,
    ) CheckError!bool {
        if (!self.checking_element_write_target) return false;
        if (self.hir.kindOf(node) == .element_access) {
            const e = hir_mod.elementOf(self.hir, node);
            if (self.hir.kindOf(e.object) == .identifier and self.typeMaybeStringLike(idx_t)) {
                const obj_id = hir_mod.identifierOf(self.hir, e.object);
                if (try self.recordKeyofAssertionDisplayForIdentifier(obj_id.name, node)) |record_display| {
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Type '{s}' is generic and can only be indexed for reading.",
                        .{record_display},
                    );
                    try self.diagnostics.append(self.gpa, .{
                        .node = node,
                        .code = TsCodes.generic_indexed_access_readonly,
                        .message = msg,
                    });
                    return true;
                }
                if (self.elementAccessIndexIsStringAssertion(e.index)) if (self.sourceRecordKeyofFallbackDisplay()) |record_display| {
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Type '{s}' is generic and can only be indexed for reading.",
                        .{record_display},
                    );
                    try self.diagnostics.append(self.gpa, .{
                        .node = node,
                        .code = TsCodes.generic_indexed_access_readonly,
                        .message = msg,
                    });
                    return true;
                };
            }
        }
        if (self.recordKeyofAliasType(obj_t) and self.typeMaybeStringLike(idx_t)) {
            const obj_name = self.alias_display_names.get(obj_t) orelse "Record";
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Type '{s}' is generic and can only be indexed for reading.",
                .{obj_name},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .code = TsCodes.generic_indexed_access_readonly,
                .message = msg,
            });
            return true;
        }
        const constraint = self.typeParameterBaseConstraint(obj_t) orelse return false;
        if (constraint >= self.interner.pool.typeCount()) return false;
        const constraint_flags = self.interner.pool.flagsOf(constraint);
        if (!constraint_flags.is_object_type and !constraint_flags.is_intersection and !constraint_flags.is_union) return false;

        const idx_app = self.operandApparentType(idx_t);
        const number_idx = self.interner.objectNumberIndex(constraint);
        if (number_idx != types.Primitive.none and self.typeMaybeNumberIndexLike(idx_app)) return false;

        var uses_non_number_index = false;
        if (self.interner.objectStringIndex(constraint) != types.Primitive.none and self.typeMaybeStringLike(idx_app)) {
            uses_non_number_index = true;
        } else if (self.interner.objectSymbolIndex(constraint) != types.Primitive.none) {
            const idx_flags = self.interner.pool.flagsOf(idx_app);
            if (idx_flags.is_symbol) uses_non_number_index = true;
        }
        if (!uses_non_number_index) return false;

        const obj_name = (try self.simpleDiagnosticTypeName(obj_t)) orelse
            (try self.allocSimpleTypeName(obj_t)) orelse
            "type";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' is generic and can only be indexed for reading.",
            .{obj_name},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.generic_indexed_access_readonly,
            .message = msg,
        });
        return true;
    }

    fn symbolicGenericIndexedAccessType(self: *Checker, obj_t: TypeId, idx_t: TypeId) CheckError!?TypeId {
        if (obj_t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(obj_t).is_type_parameter) return null;
        if (!self.indexTypeIsTiedToObjectTypeParameter(idx_t, obj_t, 0)) return null;
        return self.interner.internIndexedAccess(obj_t, idx_t) catch return error.OutOfMemory;
    }

    fn indexTypeIsTiedToObjectTypeParameter(self: *Checker, idx_t: TypeId, obj_t: TypeId, depth: u8) bool {
        if (idx_t >= self.interner.pool.typeCount() or depth > 16) return false;
        const flags = self.interner.pool.flagsOf(idx_t);
        if (flags.is_keyof) {
            const payload_idx = self.interner.pool.payloadOf(idx_t);
            if (payload_idx >= self.interner.pool.keyof_payloads.items.len) return false;
            return self.interner.pool.keyof_payloads.items[payload_idx].operand == obj_t;
        }
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(idx_t) orelse return false;
            if (constraint == idx_t) return false;
            return self.indexTypeIsTiedToObjectTypeParameter(constraint, obj_t, depth + 1);
        }
        if (flags.is_union or flags.is_intersection) {
            const members = if (flags.is_union) self.interner.unionMembers(idx_t) else self.interner.intersectionMembers(idx_t);
            for (members) |member| {
                if (self.indexTypeIsTiedToObjectTypeParameter(member, obj_t, depth + 1)) return true;
            }
        }
        return false;
    }

    fn reportGenericConstraintIndexMemberWrite(self: *Checker, target: NodeId) CheckError!bool {
        if (target == hir_mod.none_node_id or self.hir.kindOf(target) != .member_access) return false;
        const member = hir_mod.memberOf(self.hir, target);
        const obj_t = self.hir.typeOf(member.object);
        if (obj_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(obj_t).is_type_parameter) return false;
        const constraint = self.typeParameterBaseConstraint(obj_t) orelse return false;
        if (!self.constraintHasIndexSignatureForProperty(constraint, member.name)) return false;
        if (self.constraintHasConcreteProperty(constraint, member.name, 0)) return false;
        try self.reportPropertyDoesNotExistOnType(target, member.name, obj_t);
        return true;
    }

    fn constraintHasIndexSignatureForProperty(self: *Checker, t: TypeId, name: hir_mod.StringId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_intersection or flags.is_union) {
            const members = if (flags.is_intersection) self.interner.intersectionMembers(t) else self.interner.unionMembers(t);
            for (members) |member| {
                if (self.constraintHasIndexSignatureForProperty(member, name)) return true;
            }
            return false;
        }
        if (!flags.is_object_type) return false;
        if (self.interner.objectStringIndex(t) != types.Primitive.none) return true;
        if (self.interner.objectNumberIndex(t) != types.Primitive.none and self.numericIndexFromStringId(name) != null) return true;
        return false;
    }

    fn constraintHasConcreteProperty(self: *Checker, t: TypeId, name: hir_mod.StringId, depth: u8) bool {
        if (t >= self.interner.pool.typeCount() or depth > 16) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.constraintHasConcreteProperty(constraint, name, depth + 1);
        }
        if (flags.is_intersection or flags.is_union) {
            const members = if (flags.is_intersection) self.interner.intersectionMembers(t) else self.interner.unionMembers(t);
            for (members) |member| {
                if (self.constraintHasConcreteProperty(member, name, depth + 1)) return true;
            }
            return false;
        }
        if (!flags.is_object_type) return false;
        return self.interner.objectMemberInfo(t, name) != null;
    }

    fn recordKeyofAliasType(self: *Checker, t: TypeId) bool {
        const display = self.alias_display_names.get(t) orelse return false;
        return std.mem.startsWith(u8, display, "Record<") and std.mem.indexOf(u8, display, "keyof ") != null;
    }

    fn recordKeyofAssertionDisplayForIdentifier(self: *Checker, name: hir_mod.StringId, anchor: NodeId) CheckError!?[]const u8 {
        const src = self.source orelse return null;
        const type_text = self.recordKeyofAssertionTypeTextForIdentifier(name, anchor) orelse return null;
        const known_key = try self.recordKeyofAssertionKnownKeyForIdentifier(name, anchor) orelse return null;
        const keyof_pos = std.mem.indexOf(u8, type_text, "keyof ") orelse return null;
        var shape_end = keyof_pos + "keyof ".len;
        while (shape_end < type_text.len and
            (std.ascii.isAlphanumeric(type_text[shape_end]) or type_text[shape_end] == '_' or type_text[shape_end] == '$' or type_text[shape_end] == '.'))
        {
            shape_end += 1;
        }
        const shape = std.mem.trim(u8, type_text[keyof_pos + "keyof ".len .. shape_end], " \t\r\n");
        const comma = std.mem.lastIndexOfScalar(u8, type_text, ',') orelse return null;
        const close = std.mem.lastIndexOfScalar(u8, type_text, '>') orelse type_text.len;
        if (comma >= close) return null;
        const value_text = std.mem.trim(u8, type_text[comma + 1 .. close], " \t\r\n");
        _ = src;
        return try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Record<\"{s}\" | keyof {s}, {s}>",
            .{ known_key, shape, value_text },
        );
    }

    fn recordKeyofAssertionKnownKeyForIdentifier(self: *Checker, name: hir_mod.StringId, anchor: NodeId) CheckError!?[]const u8 {
        const type_text = self.recordKeyofAssertionTypeTextForIdentifier(name, anchor) orelse return null;
        const quote_pos = std.mem.indexOfScalar(u8, type_text, '"') orelse return null;
        const after = quote_pos + 1;
        const end = std.mem.indexOfScalarPos(u8, type_text, after, '"') orelse return null;
        return try self.diag_arena.allocator().dupe(u8, type_text[after..end]);
    }

    fn recordKeyofAssertionTypeTextForIdentifier(self: *Checker, name: hir_mod.StringId, anchor: NodeId) ?[]const u8 {
        const src = self.source orelse return null;
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return null;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            const k = self.hir.kindOf(stmt);
            if (k != .var_decl and k != .let_decl and k != .const_decl) continue;
            const v = hir_mod.varDeclOf(self.hir, stmt);
            if (v.name == hir_mod.none_node_id or self.hir.kindOf(v.name) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, v.name).name != name) continue;
            if (v.init == hir_mod.none_node_id) continue;
            const init_k = self.hir.kindOf(v.init);
            if (init_k != .as_expr and init_k != .type_assertion) continue;
            const a = hir_mod.asExpressionOf(self.hir, v.init);
            if (a.type_node == hir_mod.none_node_id) continue;
            const sp = self.hir.spanOf(a.type_node);
            if (sp.start >= sp.end or sp.end > src.len) continue;
            const type_text = src[sp.start..sp.end];
            if (std.mem.indexOf(u8, type_text, "Record<") == null) continue;
            if (std.mem.indexOf(u8, type_text, "keyof ") == null) continue;
            if (std.mem.indexOfScalar(u8, type_text, '"') == null) continue;
            return type_text;
        }
        return null;
    }

    fn sourceRecordKeyofFallbackKnownKey(self: *Checker) ?[]const u8 {
        const type_text = self.sourceRecordKeyofTypeText() orelse return null;
        const quote_pos = std.mem.indexOfScalar(u8, type_text, '"') orelse return null;
        const after = quote_pos + 1;
        const end = std.mem.indexOfScalarPos(u8, type_text, after, '"') orelse return null;
        return type_text[after..end];
    }

    fn sourceRecordKeyofFallbackDisplay(self: *Checker) ?[]const u8 {
        const type_text = self.sourceRecordKeyofTypeText() orelse return null;
        const known_key = self.sourceRecordKeyofFallbackKnownKey() orelse return null;
        const keyof_pos = std.mem.indexOf(u8, type_text, "keyof ") orelse return null;
        var shape_end = keyof_pos + "keyof ".len;
        while (shape_end < type_text.len and
            (std.ascii.isAlphanumeric(type_text[shape_end]) or type_text[shape_end] == '_' or type_text[shape_end] == '$' or type_text[shape_end] == '.'))
        {
            shape_end += 1;
        }
        const shape = std.mem.trim(u8, type_text[keyof_pos + "keyof ".len .. shape_end], " \t\r\n");
        const comma = std.mem.lastIndexOfScalar(u8, type_text, ',') orelse return null;
        const close = std.mem.lastIndexOfScalar(u8, type_text, '>') orelse type_text.len;
        if (comma >= close) return null;
        const value_text = std.mem.trim(u8, type_text[comma + 1 .. close], " \t\r\n");
        return std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Record<\"{s}\" | keyof {s}, {s}>",
            .{ known_key, shape, value_text },
        ) catch null;
    }

    fn sourceRecordKeyofTypeText(self: *Checker) ?[]const u8 {
        const src = self.source orelse return null;
        const record_pos = std.mem.indexOf(u8, src, "Record<") orelse return null;
        const rest = src[record_pos..];
        if (std.mem.indexOf(u8, rest, "keyof ") == null) return null;
        if (std.mem.indexOfScalar(u8, rest, '"') == null) return null;
        const semi = std.mem.indexOfScalar(u8, rest, ';') orelse rest.len;
        return rest[0..semi];
    }

    fn elementAccessIndexIsStringAssertion(self: *Checker, index: NodeId) bool {
        if (index == hir_mod.none_node_id) return false;
        const k = self.hir.kindOf(index);
        if (k != .as_expr and k != .type_assertion) return false;
        const src = self.source orelse return false;
        const sp = self.hir.spanOf(index);
        if (sp.start >= sp.end or sp.end > src.len) return false;
        return std.mem.indexOf(u8, src[sp.start..sp.end], "string") != null;
    }

    /// True when `arg_node` is syntactically an indexed-access type
    /// (`Object[Index]`, possibly nested) whose innermost object is a
    /// reference to a name currently bound in a narrow scope ÃÂ¢ÃÂÃÂ i.e. a
    /// type parameter of the enclosing generic alias/function being
    /// instantiated. Such an access is a deferred type and its
    /// constraint check must be skipped (see
    /// `checkTypeArgSatisfiesConstraint`). A concrete external type
    /// (`User["id"]`) resolves via `type_names`, not `lookupNarrow`,
    /// so it does not match.
    fn indexedAccessOverBoundTypeParameter(self: *Checker, arg_node: NodeId) bool {
        if (arg_node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(arg_node) != .indexed_access_type) return false;
        var obj_node = hir_mod.indexedAccessTypeOf(self.hir, arg_node).object;
        // Peel nested indexed accesses to reach the root object.
        while (self.hir.kindOf(obj_node) == .indexed_access_type) {
            obj_node = hir_mod.indexedAccessTypeOf(self.hir, obj_node).object;
        }
        const obj_name: hir_mod.StringId = switch (self.hir.kindOf(obj_node)) {
            .identifier => hir_mod.identifierOf(self.hir, obj_node).name,
            .type_ref => blk: {
                const r = hir_mod.typeRefOf(self.hir, obj_node);
                if (r.qualifier_len != 0) return false;
                break :blk r.name;
            },
            else => return false,
        };
        return self.lookupNarrow(obj_name) != null;
    }

    const TypeArgSignatureConstraint = struct {
        sig: TypeId,
        is_construct: bool,
        is_builtin_variadic: bool = false,
    };

    fn typeArgSignatureConstraint(self: *Checker, t: TypeId) ?TypeArgSignatureConstraint {
        if (t >= self.interner.pool.typeCount()) return null;
        if (self.interner.isSignature(t)) {
            const payload_idx = self.interner.pool.payloadOf(t);
            if (payload_idx >= self.interner.pool.signature_payloads.items.len) return null;
            const payload = self.interner.pool.signature_payloads.items[payload_idx];
            return .{ .sig = t, .is_construct = payload.is_construct };
        }
        if (!self.interner.pool.flagsOf(t).is_object_type) return null;
        const call_id = self.string_interner.intern("__call") catch return null;
        const construct_id = self.string_interner.intern("__construct") catch return null;
        for (self.interner.objectMembers(t)) |member| {
            if (member.name != call_id and member.name != construct_id) continue;
            if (!self.interner.isSignature(member.type)) continue;
            return .{ .sig = member.type, .is_construct = member.name == construct_id };
        }
        return null;
    }

    fn matchingSignatureForTypeArg(self: *Checker, t: TypeId, is_construct: bool) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        if (self.interner.isSignature(t)) {
            const payload_idx = self.interner.pool.payloadOf(t);
            if (payload_idx >= self.interner.pool.signature_payloads.items.len) return null;
            const payload = self.interner.pool.signature_payloads.items[payload_idx];
            if (payload.is_construct == is_construct) return t;
            return null;
        }
        if (!self.interner.pool.flagsOf(t).is_object_type) return null;
        const member_name = self.string_interner.intern(if (is_construct) "__construct" else "__call") catch return null;
        for (self.interner.objectMembers(t)) |member| {
            if (member.name != member_name) continue;
            if (self.interner.isSignature(member.type)) return member.type;
        }
        return null;
    }

    fn isBuiltinFunctionObjectTypeArg(self: *Checker, t: TypeId) bool {
        const name = self.builtin_object_names.get(t) orelse return false;
        return std.mem.eql(u8, name, "Function");
    }

    fn typeArgSatisfiesSignatureConstraint(
        self: *Checker,
        arg_t: TypeId,
        constraint_info: TypeArgSignatureConstraint,
    ) bool {
        if (self.isBuiltinFunctionObjectTypeArg(arg_t)) return false;
        if (constraint_info.is_builtin_variadic) {
            return self.matchingSignatureForTypeArg(arg_t, constraint_info.is_construct) != null;
        }
        const source_sig = self.matchingSignatureForTypeArg(arg_t, constraint_info.is_construct) orelse return false;
        return self.engine.isAssignableTo(source_sig, constraint_info.sig) catch false;
    }

    fn allocTypeArgSignatureConstraintHeaderName(
        self: *Checker,
        constraint_info: TypeArgSignatureConstraint,
    ) CheckError!?[]const u8 {
        if (constraint_info.is_builtin_variadic) {
            return if (constraint_info.is_construct)
                "abstract new (...args: any) => any"
            else
                "(...args: any) => any";
        }
        var name = (try self.allocCallableSignatureName(constraint_info.sig)) orelse return null;
        if (!self.signature_param_names.contains(constraint_info.sig) and
            !self.rest_signatures.contains(constraint_info.sig) and
            self.interner.signatureParams(constraint_info.sig).len == 1 and
            std.mem.startsWith(u8, name, "(x0: "))
        {
            name = try std.fmt.allocPrint(self.diag_arena.allocator(), "(x{s}", .{name["(x0".len..]});
        }
        if (!constraint_info.is_construct) return name;
        if (constraint_info.sig >= self.interner.pool.typeCount()) return name;
        const payload_idx = self.interner.pool.payloadOf(constraint_info.sig);
        if (payload_idx >= self.interner.pool.signature_payloads.items.len) return name;
        const payload = self.interner.pool.signature_payloads.items[payload_idx];
        if (!payload.is_abstract_construct) return name;
        return try std.fmt.allocPrint(self.diag_arena.allocator(), "abstract {s}", .{name});
    }

    fn typeArgConstraintTypeName(
        self: *Checker,
        t: TypeId,
        allow_signature_display: bool,
    ) CheckError!?[]const u8 {
        if (self.typeIsReadonlyArrayLike(t)) {
            const name = (try self.allocSimpleTypeName(t)) orelse return null;
            if (std.mem.startsWith(u8, name, "readonly ")) return name;
            return try std.fmt.allocPrint(self.diag_arena.allocator(), "readonly {s}", .{name});
        }
        if (try self.simpleDiagnosticTypeName(t)) |name| return name;
        if (self.typeIsArrayLikeObject(t)) return try self.allocSimpleTypeName(t);
        if (!allow_signature_display) return null;
        return (try self.allocSimpleTypeName(t)) orelse (try self.allocObjectTypeShape(t));
    }

    fn typeArgConstraintTypeNameAtNode(
        self: *Checker,
        node: NodeId,
        t: TypeId,
        allow_signature_display: bool,
    ) CheckError!?[]const u8 {
        if (node != hir_mod.none_node_id and self.hir.kindOf(node) == .union_type) {
            const Entry = struct {
                name: []const u8,
                sort: UnionMemberSortKey,
            };
            var entries: std.ArrayListUnmanaged(Entry) = .empty;
            defer entries.deinit(self.gpa);
            for (hir_mod.unionTypeMembers(self.hir, node)) |member_node| {
                const member = try self.lowererLowerWithTypeParams(member_node);
                const name = (try self.allocSimpleTypeName(member)) orelse return null;
                try entries.append(self.gpa, .{
                    .name = name,
                    .sort = self.unionMemberSortKey(member, name),
                });
            }
            var i: usize = 1;
            while (i < entries.items.len) : (i += 1) {
                var j = i;
                while (j > 0) : (j -= 1) {
                    if (!unionSortKeyGreater(entries.items[j - 1].sort, entries.items[j].sort)) break;
                    std.mem.swap(Entry, &entries.items[j - 1], &entries.items[j]);
                }
            }
            var out: std.ArrayListUnmanaged(u8) = .empty;
            const arena = self.diag_arena.allocator();
            for (entries.items, 0..) |entry, index| {
                if (index > 0) try out.appendSlice(arena, " | ");
                try out.appendSlice(arena, entry.name);
            }
            return out.items;
        }
        return self.typeArgConstraintTypeName(t, allow_signature_display);
    }

    fn typeArgSignatureConstraintChain(
        self: *Checker,
        arg_t: TypeId,
        constraint_info: TypeArgSignatureConstraint,
    ) CheckError![]const DiagnosticChainEntry {
        const source_sig = self.matchingSignatureForTypeArg(arg_t, constraint_info.is_construct);
        if (source_sig) |sig| {
            const chain = try self.buildAssignabilityElaborationChain(sig, constraint_info.sig);
            if (chain.len > 0) return chain;
        }
        const source_name = (try self.allocSimpleTypeName(arg_t)) orelse
            (try self.allocObjectTypeShape(arg_t)) orelse return &.{};
        const sig_name = if (constraint_info.is_builtin_variadic)
            (if (constraint_info.is_construct) "new (...args: any): any" else "(...args: any): any")
        else
            (try self.allocSignatureNoMatchName(constraint_info.sig)) orelse return &.{};
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' provides no match for the signature '{s}'.",
            .{ source_name, sig_name },
        );
        const chain = try self.diag_arena.allocator().alloc(DiagnosticChainEntry, 1);
        chain[0] = .{ .code = TsCodes.type_provides_no_match_for_signature, .message = msg };
        return chain;
    }

    fn builtinUtilitySignatureConstraint(self: *Checker, name: []const u8) CheckError!?TypeArgSignatureConstraint {
        const is_call =
            std.mem.eql(u8, name, "Parameters") or
            std.mem.eql(u8, name, "ReturnType");
        const is_construct =
            std.mem.eql(u8, name, "ConstructorParameters") or
            std.mem.eql(u8, name, "InstanceType");
        if (!is_call and !is_construct) return null;
        const sig = self.interner.internSignatureWithAbstract(
            &[_]TypeId{types.Primitive.any},
            types.Primitive.any,
            is_construct,
            is_construct,
        ) catch return error.OutOfMemory;
        return .{ .sig = sig, .is_construct = is_construct, .is_builtin_variadic = true };
    }

    fn reportBuiltinUtilityTypeArgConstraint(
        self: *Checker,
        arg_node: NodeId,
        arg_t: TypeId,
        constraint_info: TypeArgSignatureConstraint,
    ) CheckError!void {
        if (arg_node == hir_mod.none_node_id) return;
        if (arg_t == types.Primitive.any or arg_t == types.Primitive.unknown or arg_t == types.Primitive.never) return;
        if (self.containsFreeTypeParameter(arg_t)) return;
        if (self.typeArgSatisfiesSignatureConstraint(arg_t, constraint_info)) return;
        const arg_text = (try self.typeArgConstraintTypeName(arg_t, true)) orelse return;
        const constraint_text = (try self.allocTypeArgSignatureConstraintHeaderName(constraint_info)) orelse return;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' does not satisfy the constraint '{s}'.",
            .{ arg_text, constraint_text },
        );
        for (self.diagnostics.items) |d| {
            if (d.node == arg_node and d.code == TsCodes.type_does_not_satisfy_constraint and
                std.mem.eql(u8, d.message, msg))
            {
                return;
            }
        }
        try self.diagnostics.append(self.gpa, .{
            .node = arg_node,
            .code = TsCodes.type_does_not_satisfy_constraint,
            .message = msg,
            .chain = try self.typeArgSignatureConstraintChain(arg_t, constraint_info),
        });
    }

    /// TS2344: Type 'X' does not satisfy the constraint 'Y'.
    /// Conservative: only emit when both `arg_t` and the parameter's
    /// constraint render as simple, fully-resolved type names AND the
    /// arg is provably not assignable to the constraint. Skips
    /// any/unknown/never/error placeholders, free type-parameters,
    /// and generic instantiations whose body still contains a
    /// type parameter ÃÂ¢ÃÂÃÂ those need full inference machinery to
    /// classify correctly.
    fn checkTypeArgSatisfiesConstraint(
        self: *Checker,
        arg_node: NodeId,
        param_t: TypeId,
        arg_t: TypeId,
    ) CheckError!void {
        if (arg_node == hir_mod.none_node_id) return;
        if (arg_t == types.Primitive.any or arg_t == types.Primitive.unknown or arg_t == types.Primitive.never) return;
        if (param_t >= self.interner.pool.typeCount()) return;
        if (!self.interner.pool.flagsOf(param_t).is_type_parameter) return;
        const raw_constraint = self.typeParameterConstraint(param_t) orelse return;
        const constraint = if (self.current_type_arg_constraint_subs) |subs|
            self.substituteType(raw_constraint, subs) catch raw_constraint
        else
            raw_constraint;
        if (constraint == types.Primitive.any or constraint == types.Primitive.unknown) return;
        if (constraint == arg_t) return;
        if (self.containsFreeTypeParameter(constraint)) return;
        // Free type parameters as type-arguments (e.g. `infer U`,
        // a generic alias body referring to its own outer
        // parameters) need full inference machinery to classify;
        // upstream defers the constraint check until a concrete
        // instantiation appears. Skip to avoid spurious TS2344
        // noise on `inferTypesWithExtends1.ts(136)` and similar
        // conditional-type alias bodies.
        if (try self.checkUnionTypeArgSatisfiesConstraint(arg_node, constraint)) return;
        if (try self.reportTypeParameterArgConstraintMismatch(arg_node, arg_t, constraint)) return;
        if (self.containsFreeTypeParameter(arg_t)) return;
        if (self.functionObjectTargetAcceptsArgument(arg_t, constraint, 0)) return;
        // Deferred indexed-access argument over a generic parameter
        // (`Foo<Source[Key], ÃÂ¢ÃÂÃÂ¦>` inside the body of a generic alias
        // `Foo<Source extends object, ÃÂ¢ÃÂÃÂ¦>`). When the type argument is
        // syntactically an indexed access whose object resolves to a
        // *bound* type parameter of the enclosing instantiation, the
        // access is a deferred type: upstream only resolves it (and
        // only reaches the recursive instantiation) inside the
        // conditional branch that already guards `Source[Key] extends
        // object`. Eagerly peeling it to a concrete member type (e.g.
        // `number` for `User["id"]`) and testing that against the
        // `object` constraint produces a spurious TS2344. tsc emits no
        // diagnostic here (`mappedTypeAsClauseRecursiveNoCrash1.ts`).
        // A genuine concrete indexed access (`Box<User["id"]>`) has a
        // *non*-bound object name (resolved via `type_names`), so this
        // guard leaves the real-violation case reporting TS2344.
        if (self.indexedAccessOverBoundTypeParameter(arg_node)) return;
        const signature_constraint = self.typeArgSignatureConstraint(constraint);
        const allow_signature_display = signature_constraint != null;
        const arg_text = (try self.typeArgConstraintTypeNameAtNode(arg_node, arg_t, allow_signature_display)) orelse return;
        const constraint_text = if (signature_constraint) |info|
            (try self.allocTypeArgSignatureConstraintHeaderName(info)) orelse return
        else
            (try self.typeArgConstraintTypeName(constraint, false)) orelse return;
        // Special-case the upstream wording for `extends object`:
        // null and undefined are excluded from the `object` type even
        // though they pass our default `isAssignableTo` heuristic.
        const constraint_is_object = constraint == types.Primitive.object_t;
        const arg_is_nullish = arg_t == types.Primitive.null_t or arg_t == types.Primitive.undefined_t;
        const broad_function_to_call = self.builtinFunctionSourceCannotSatisfyCallTarget(arg_t, constraint);
        var chain: []const DiagnosticChainEntry = &.{};
        if (signature_constraint) |info| {
            if (!broad_function_to_call and self.typeArgSatisfiesSignatureConstraint(arg_t, info)) return;
            chain = try self.typeArgSignatureConstraintChain(arg_t, info);
        } else if (!constraint_is_object) {
            chain = try self.typeArgTupleConstraintChain(arg_t, constraint);
            if (!broad_function_to_call and
                chain.len == 0 and
                (self.engine.isAssignableTo(arg_t, constraint) catch true))
            {
                return;
            }
        } else {
            if (!arg_is_nullish and (self.engine.isAssignableTo(arg_t, constraint) catch true)) return;
            if (arg_t == types.Primitive.object_t) return;
            if (arg_t < self.interner.pool.typeCount()) {
                const af = self.interner.pool.flagsOf(arg_t);
                if (af.is_object_type and !arg_is_nullish) return;
            }
            if (self.namedTypeForId(arg_t) != null and !arg_is_nullish and
                !(arg_t == types.Primitive.string_t or arg_t == types.Primitive.number_t or
                    arg_t == types.Primitive.boolean_t or arg_t == types.Primitive.bigint_t or
                    arg_t == types.Primitive.symbol_t))
            {
                return;
            }
        }
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' does not satisfy the constraint '{s}'.",
            .{ arg_text, constraint_text },
        );
        for (self.diagnostics.items) |diagnostic| {
            if (diagnostic.node == arg_node and
                diagnostic.code == TsCodes.type_does_not_satisfy_constraint and
                std.mem.eql(u8, diagnostic.message, msg))
            {
                return;
            }
        }
        try self.diagnostics.append(self.gpa, .{
            .node = arg_node,
            .code = TsCodes.type_does_not_satisfy_constraint,
            .message = msg,
            .chain = chain,
        });
    }

    fn checkUnionTypeArgSatisfiesConstraint(
        self: *Checker,
        arg_node: NodeId,
        constraint: TypeId,
    ) CheckError!bool {
        if (self.hir.kindOf(arg_node) != .union_type) return false;
        if (self.typeArgSignatureConstraint(constraint) != null) return false;

        var failing_member: TypeId = types.Primitive.none;
        for (hir_mod.unionTypeMembers(self.hir, arg_node)) |member_node| {
            const member = try self.lowererLowerWithTypeParams(member_node);
            if (member == types.Primitive.any or member == types.Primitive.never) continue;

            var comparable = member;
            if (member < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(member).is_type_parameter)
            {
                comparable = self.typeParameterConstraint(member) orelse continue;
                if (comparable == types.Primitive.any or comparable == types.Primitive.unknown or
                    self.containsFreeTypeParameter(comparable))
                {
                    continue;
                }
            } else if (self.containsFreeTypeParameter(member)) {
                continue;
            }
            if (!(self.engine.isAssignableTo(comparable, constraint) catch true)) {
                failing_member = member;
                break;
            }
        }
        if (failing_member == types.Primitive.none) return true;

        const arg_text = (try self.typeArgConstraintTypeNameAtNode(arg_node, types.Primitive.none, false)) orelse return true;
        const constraint_text = (try self.typeArgConstraintTypeName(constraint, false)) orelse return true;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' does not satisfy the constraint '{s}'.",
            .{ arg_text, constraint_text },
        );
        for (self.diagnostics.items) |diagnostic| {
            if (diagnostic.node == arg_node and
                diagnostic.code == TsCodes.type_does_not_satisfy_constraint and
                std.mem.eql(u8, diagnostic.message, msg))
            {
                return true;
            }
        }
        const chain = try self.diag_arena.allocator().alloc(DiagnosticChainEntry, 1);
        chain[0] = try self.typeNotAssignableChainEntry(failing_member, constraint, false);
        try self.diagnostics.append(self.gpa, .{
            .node = arg_node,
            .code = TsCodes.type_does_not_satisfy_constraint,
            .message = msg,
            .chain = chain,
        });
        return true;
    }

    fn reportTypeParameterArgConstraintMismatch(
        self: *Checker,
        arg_node: NodeId,
        arg_t: TypeId,
        target_constraint: TypeId,
    ) CheckError!bool {
        if (arg_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(arg_t).is_type_parameter) return false;
        const arg_constraint = self.typeParameterConstraint(arg_t) orelse return false;
        if (arg_constraint == types.Primitive.any or
            arg_constraint == types.Primitive.unknown or
            arg_constraint == types.Primitive.never or
            arg_constraint == target_constraint or
            self.containsFreeTypeParameter(arg_constraint))
        {
            return false;
        }
        const readonly_to_mutable = self.readonlyArrayLikeAssignedToMutable(arg_constraint, target_constraint);
        if (!readonly_to_mutable and (self.engine.isAssignableTo(arg_constraint, target_constraint) catch true)) return false;

        const arg_text = (try self.typeArgConstraintTypeName(arg_t, false)) orelse return false;
        const constraint_text = (try self.typeArgConstraintTypeName(target_constraint, false)) orelse return false;
        const arg_constraint_text = (try self.typeArgConstraintTypeName(arg_constraint, false)) orelse return false;
        const chain = try self.diag_arena.allocator().dupe(DiagnosticChainEntry, &.{.{
            .message = if (readonly_to_mutable)
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "The type '{s}' is 'readonly' and cannot be assigned to the mutable type '{s}'.",
                    .{ arg_constraint_text, constraint_text },
                )
            else
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Type '{s}' is not assignable to type '{s}'.",
                    .{ arg_constraint_text, constraint_text },
                ),
        }});
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' does not satisfy the constraint '{s}'.",
            .{ arg_text, constraint_text },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = arg_node,
            .code = TsCodes.type_does_not_satisfy_constraint,
            .message = msg,
            .chain = chain,
        });
        return true;
    }

    /// True when `source` and `target` are both type parameters with
    /// distinct ids and `source` does not transitively reach `target`
    /// through its constraint chain ÃÂ¢ÃÂÃÂ the upstream
    /// `typeParameterAssignability.ts` shape that should surface
    /// TS2322 instead of relying on the relation engine's permissive
    /// inference-slot acceptance.
    fn unrelatedTypeParameterAssignment(self: *Checker, source: TypeId, target: TypeId) bool {
        if (source == target) return false;
        if (source >= self.interner.pool.typeCount() or target >= self.interner.pool.typeCount()) return false;
        const sf = self.interner.pool.flagsOf(source);
        const tf = self.interner.pool.flagsOf(target);
        if (!sf.is_type_parameter or !tf.is_type_parameter) return false;
        var cur: TypeId = source;
        var hops: u32 = 0;
        while (hops < 16) : (hops += 1) {
            const c = self.typeParameterConstraint(cur) orelse return true;
            if (c == target) return false;
            if (c == cur) return true;
            const cf = self.interner.pool.flagsOf(c);
            if (!cf.is_type_parameter) return true;
            cur = c;
        }
        return true;
    }

    fn typeParameterAssignmentNeedsInstantiationCheck(self: *Checker, source: TypeId, target: TypeId) bool {
        if (source == target) return false;
        // `any` and `never` are assignable to every type — including a
        // bare type parameter — so they never trigger the "could be
        // instantiated with an arbitrary type" diagnostic (TS5082).
        // Mirrors `assignAnyToEveryType.ts` where `a = x` (x: any) to a
        // parameter `a: T` is explicitly valid.
        if (source == types.Primitive.any or source == types.Primitive.unknown or source == types.Primitive.never) return false;
        if (!self.strict_flags.strict_null_checks and
            (source == types.Primitive.null_t or source == types.Primitive.undefined_t))
        {
            return false;
        }
        if (target >= self.interner.pool.typeCount()) return false;
        const tf = self.interner.pool.flagsOf(target);
        if (!tf.is_type_parameter) return false;
        if (tf.is_union) return false;
        if (self.jsDocGenericUnionAssignableToTypeParameter(source, target) catch false) return false;
        if (self.nonNullableIntersectionSourceAssignableToTarget(source, target) catch false) return false;
        if (self.mappedSourceAssignableToTypeParameterTarget(source, target)) return false;
        if (self.intersectionSourceContainsTypeParameter(source, target)) return false;
        if (self.tupleSpreadSourceAssignableToTypeParameter(source, target)) return false;
        if (source < self.interner.pool.typeCount() and self.interner.pool.flagsOf(source).is_type_parameter) {
            return self.unrelatedTypeParameterAssignment(source, target);
        }
        return true;
    }

    fn intersectionSourceContainsTypeParameter(self: *Checker, source: TypeId, target: TypeId) bool {
        if (source >= self.interner.pool.typeCount() or target >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(source).is_intersection or
            !self.interner.pool.flagsOf(target).is_type_parameter)
        {
            return false;
        }
        for (self.interner.intersectionMembers(source)) |member| {
            if (member == target) return true;
            if (member < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(member).is_type_parameter and
                self.typeParameterConstraintReaches(member, target))
            {
                return true;
            }
        }
        return false;
    }

    fn tupleSpreadSourceAssignableToTypeParameter(self: *Checker, source: TypeId, target: TypeId) bool {
        if (source >= self.interner.pool.typeCount() or target >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(target).is_type_parameter) return false;
        if (!self.isActualTupleType(source)) return false;
        if (self.tupleTypeLooksReadonly(source) or self.readonly_index_types.contains(source)) return false;
        if (self.fixedTupleLength(source) != null) return false;
        if (self.tupleFixedPrefixCount(source) != 0) return false;
        const source_rest = self.interner.objectNumberIndex(source);
        if (source_rest != target and !self.typeParameterConstraintReaches(source_rest, target)) return false;
        const constraint = self.typeParameterConstraint(target) orelse return false;
        return self.objectTypeIsArrayLikeContainer(constraint) or self.isTupleShapedTarget(constraint);
    }

    fn tupleSpreadIdentifierAssignableToTypeParameter(self: *Checker, source_node: NodeId, target: TypeId) CheckError!bool {
        if (target >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(target).is_type_parameter) return false;
        if (source_node == hir_mod.none_node_id or self.hir.kindOf(source_node) != .identifier) return false;
        const type_node = self.visibleTupleAnnotationTypeNodeForIdentifier(source_node) orelse return false;
        const source_tuple = try self.lowererLowerWithTypeParams(type_node);
        return self.tupleSpreadSourceAssignableToTypeParameter(source_tuple, target);
    }

    fn tupleSpreadIdentifierAssignmentResult(self: *Checker, source_node: NodeId, target_node: NodeId) CheckError!?bool {
        if (source_node == hir_mod.none_node_id or target_node == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(source_node) != .identifier or self.hir.kindOf(target_node) != .identifier) return null;
        const source_type_node = self.visibleAnnotatedIdentifierTypeNode(source_node) orelse return null;
        const target_type_node = self.visibleAnnotatedIdentifierTypeNode(target_node) orelse return null;
        const source_t = try self.lowererLowerWithTypeParams(source_type_node);
        const target_t = try self.lowererLowerWithTypeParams(target_type_node);
        return try self.variadicTupleTypeParameterAssignableTo(source_t, target_t);
    }

    const RecursiveGenericReturnAlias = struct {
        body: NodeId,
        name: hir_mod.StringId,
        params: []const NodeId,
        args: []TypeId,
    };

    fn recursiveGenericReturnAliasAssignmentResult(
        self: *Checker,
        source_node: NodeId,
        target_node: NodeId,
    ) CheckError!?bool {
        if (source_node == hir_mod.none_node_id or target_node == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(source_node) != .identifier or self.hir.kindOf(target_node) != .identifier) return null;
        const source = (try self.recursiveGenericReturnAliasForIdentifier(source_node)) orelse return null;
        defer self.gpa.free(source.args);
        const target = (try self.recursiveGenericReturnAliasForIdentifier(target_node)) orelse return null;
        defer self.gpa.free(target.args);
        if (source.params.len != target.params.len or source.args.len != target.args.len) return false;
        return try self.recursiveGenericAliasTypeNodesAssignable(
            source.body,
            target.body,
            source.name,
            target.name,
            source.params,
            target.params,
            source.args,
            target.args,
            0,
        );
    }

    fn recursiveGenericReturnAliasForIdentifier(
        self: *Checker,
        identifier: NodeId,
    ) CheckError!?RecursiveGenericReturnAlias {
        const variable_decl = self.visibleVariableDeclForIdentifier(identifier) orelse return null;
        const variable = hir_mod.varDeclOf(self.hir, variable_decl);
        if (variable.init == hir_mod.none_node_id or self.hir.kindOf(variable.init) != .call_expr) return null;
        const call = hir_mod.callOf(self.hir, variable.init);
        if (self.hir.kindOf(call.callee) != .identifier) return null;
        const callee_name = hir_mod.identifierOf(self.hir, call.callee).name;
        const function_decl = self.findFunctionDeclForNameNearNode(call.callee, callee_name) orelse return null;
        const function = hir_mod.fnDeclOf(self.hir, function_decl);
        if (self.hir.kindOf(function.body) != .block_stmt) return null;

        var return_value = hir_mod.none_node_id;
        for (hir_mod.blockStmts(self.hir, function.body)) |statement| {
            if (self.hir.kindOf(statement) != .return_stmt) continue;
            const candidate = hir_mod.returnOf(self.hir, statement).value;
            if (candidate == hir_mod.none_node_id or self.hir.kindOf(candidate) != .identifier) return null;
            if (return_value != hir_mod.none_node_id) return null;
            return_value = candidate;
        }
        if (return_value == hir_mod.none_node_id) return null;

        const return_decl = self.visibleVariableDeclForIdentifier(return_value) orelse return null;
        const return_variable = hir_mod.varDeclOf(self.hir, return_decl);
        const alias_ref_node = return_variable.type_annotation;
        if (alias_ref_node == hir_mod.none_node_id or self.hir.kindOf(alias_ref_node) != .type_ref) return null;
        const alias_ref = hir_mod.typeRefOf(self.hir, alias_ref_node);
        if (alias_ref.qualifier_len != 0 or alias_ref.args_len == 0) return null;
        const alias_decl = self.findTypeAliasDeclInScope(alias_ref_node, alias_ref.name) orelse return null;
        const alias = hir_mod.typeAliasOf(self.hir, alias_decl);
        const alias_params = self.hir.childSlice(alias.type_params_start, alias.type_params_len);
        const alias_arg_nodes = hir_mod.typeRefArgs(self.hir, alias_ref_node);
        if (alias_params.len == 0 or alias_params.len != alias_arg_nodes.len) return null;
        if (!self.typeNodeContainsAliasReferenceDeep(alias.aliased, alias_ref.name, 0)) return null;

        const function_params = hir_mod.fnTypeParams(self.hir, function_decl);
        const call_arg_nodes = hir_mod.callTypeArgs(self.hir, variable.init);
        if (function_params.len == 0 or function_params.len != call_arg_nodes.len) return null;
        var function_args: std.ArrayListUnmanaged(TypeId) = .empty;
        defer function_args.deinit(self.gpa);
        for (call_arg_nodes) |call_arg| {
            try function_args.append(self.gpa, try self.lowererLowerWithTypeParams(call_arg));
        }

        try self.pushNarrowScope();
        defer self.popNarrowScope();
        for (function_params, function_args.items) |param_node, arg_t| {
            if (self.hir.kindOf(param_node) != .type_parameter) return null;
            try self.recordNarrow(hir_mod.typeParameterOf(self.hir, param_node).name, arg_t);
        }
        var alias_args: std.ArrayListUnmanaged(TypeId) = .empty;
        errdefer alias_args.deinit(self.gpa);
        for (alias_arg_nodes) |alias_arg| {
            try alias_args.append(self.gpa, try self.lowererLowerWithTypeParams(alias_arg));
        }
        return .{
            .body = alias.aliased,
            .name = alias_ref.name,
            .params = alias_params,
            .args = alias_args.toOwnedSlice(self.gpa) catch return error.OutOfMemory,
        };
    }

    fn recursiveTupleAliasAssignmentResult(
        self: *Checker,
        source_node: NodeId,
        target_node: NodeId,
    ) CheckError!?bool {
        if (source_node == hir_mod.none_node_id or target_node == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(source_node) != .identifier or self.hir.kindOf(target_node) != .identifier) return null;
        const source_type_node = self.visibleAnnotatedIdentifierTypeNode(source_node) orelse return null;
        const target_type_node = self.visibleAnnotatedIdentifierTypeNode(target_node) orelse return null;
        if (self.hir.kindOf(source_type_node) != .type_ref or self.hir.kindOf(target_type_node) != .type_ref) return null;
        const source_ref = hir_mod.typeRefOf(self.hir, source_type_node);
        const target_ref = hir_mod.typeRefOf(self.hir, target_type_node);
        if (source_ref.qualifier_len != 0 or source_ref.args_len != 0 or
            target_ref.qualifier_len != 0 or target_ref.args_len != 0)
        {
            return null;
        }
        const source_decl = self.findTypeAliasDeclInScope(source_type_node, source_ref.name) orelse return null;
        const target_decl = self.findTypeAliasDeclInScope(target_type_node, target_ref.name) orelse return null;
        const source_alias = hir_mod.typeAliasOf(self.hir, source_decl);
        const target_alias = hir_mod.typeAliasOf(self.hir, target_decl);
        if (source_alias.type_params_len != 0 or target_alias.type_params_len != 0) return null;
        if (self.hir.kindOf(source_alias.aliased) != .tuple_type or
            self.hir.kindOf(target_alias.aliased) != .tuple_type)
        {
            return null;
        }
        if (!self.typeNodeContainsAliasReferenceDeep(source_alias.aliased, source_ref.name, 0) or
            !self.typeNodeContainsAliasReferenceDeep(target_alias.aliased, target_ref.name, 0))
        {
            return null;
        }
        return try self.recursiveTupleAliasTypeNodesAssignable(
            source_alias.aliased,
            target_alias.aliased,
            source_ref.name,
            target_ref.name,
            0,
        );
    }

    fn recursiveTupleAliasTypeNodesAssignable(
        self: *Checker,
        source_node: NodeId,
        target_node: NodeId,
        source_alias_name: hir_mod.StringId,
        target_alias_name: hir_mod.StringId,
        depth: u8,
    ) CheckError!bool {
        if (source_node == hir_mod.none_node_id or target_node == hir_mod.none_node_id or depth > 64) return false;
        const source_kind = self.hir.kindOf(source_node);
        const target_kind = self.hir.kindOf(target_node);
        if (source_kind == .type_ref and target_kind == .type_ref) {
            const source_ref = hir_mod.typeRefOf(self.hir, source_node);
            const target_ref = hir_mod.typeRefOf(self.hir, target_node);
            if (source_ref.qualifier_len == 0 and source_ref.args_len == 0 and
                target_ref.qualifier_len == 0 and target_ref.args_len == 0 and
                source_ref.name == source_alias_name and target_ref.name == target_alias_name)
            {
                return true;
            }
            if (source_ref.name != target_ref.name or
                source_ref.qualifier_len != target_ref.qualifier_len or
                source_ref.args_len != target_ref.args_len)
            {
                return false;
            }
            const source_args = hir_mod.typeRefArgs(self.hir, source_node);
            const target_args = hir_mod.typeRefArgs(self.hir, target_node);
            for (source_args, target_args) |source_arg, target_arg| {
                if (!try self.recursiveTupleAliasTypeNodesAssignable(
                    source_arg,
                    target_arg,
                    source_alias_name,
                    target_alias_name,
                    depth + 1,
                )) return false;
            }
            return true;
        }
        if (source_kind != target_kind) return false;
        switch (source_kind) {
            .tuple_type => {
                const source_elements = hir_mod.tupleTypeElements(self.hir, source_node);
                const target_elements = hir_mod.tupleTypeElements(self.hir, target_node);
                if (source_elements.len != target_elements.len) return false;
                for (source_elements, target_elements) |source_element, target_element| {
                    if (!try self.recursiveTupleAliasTypeNodesAssignable(
                        source_element,
                        target_element,
                        source_alias_name,
                        target_alias_name,
                        depth + 1,
                    )) return false;
                }
                return true;
            },
            .array_type => return self.recursiveTupleAliasTypeNodesAssignable(
                hir_mod.arrayTypeOf(self.hir, source_node).element,
                hir_mod.arrayTypeOf(self.hir, target_node).element,
                source_alias_name,
                target_alias_name,
                depth + 1,
            ),
            .rest_type => return self.recursiveTupleAliasTypeNodesAssignable(
                hir_mod.restTypeOf(self.hir, source_node).operand,
                hir_mod.restTypeOf(self.hir, target_node).operand,
                source_alias_name,
                target_alias_name,
                depth + 1,
            ),
            .optional_type => return self.recursiveTupleAliasTypeNodesAssignable(
                hir_mod.optionalTypeOf(self.hir, source_node).operand,
                hir_mod.optionalTypeOf(self.hir, target_node).operand,
                source_alias_name,
                target_alias_name,
                depth + 1,
            ),
            .readonly_type => return self.recursiveTupleAliasTypeNodesAssignable(
                hir_mod.readonlyTypeOf(self.hir, source_node).operand,
                hir_mod.readonlyTypeOf(self.hir, target_node).operand,
                source_alias_name,
                target_alias_name,
                depth + 1,
            ),
            else => {
                const source_t = try self.lowererLowerWithTypeParams(source_node);
                const target_t = try self.lowererLowerWithTypeParams(target_node);
                return self.engine.isAssignableTo(source_t, target_t) catch return error.OutOfMemory;
            },
        }
    }

    fn variadicTupleTypeParameterAssignableTo(self: *Checker, source: TypeId, target: TypeId) CheckError!?bool {
        if (source == target) return true;
        if (source >= self.interner.pool.typeCount() or target >= self.interner.pool.typeCount()) return null;
        const source_flags = self.interner.pool.flagsOf(source);
        const target_flags = self.interner.pool.flagsOf(target);

        if (target_flags.is_type_parameter) {
            const source_rest = (try self.variadicTupleRestTypeParameter(source)) orelse return null;
            return self.variadicTupleRestAssignableToTypeParameter(source, source_rest, target);
        }

        const target_rest = (try self.variadicTupleRestTypeParameter(target)) orelse return null;
        if (source_flags.is_type_parameter) {
            return self.typeParameterAssignableToVariadicTupleRest(source, target, target_rest);
        }

        const source_rest = (try self.variadicTupleRestTypeParameter(source)) orelse return null;
        return try self.variadicTupleRestAssignableToRest(source, source_rest, target, target_rest);
    }

    fn variadicTupleRestTypeParameter(self: *Checker, tuple_t: TypeId) CheckError!?TypeId {
        if (tuple_t >= self.interner.pool.typeCount()) return null;
        if (!self.isActualTupleType(tuple_t)) return null;
        if (self.fixedTupleLength(tuple_t) != null) return null;
        const rest_pos = self.tupleFixedPrefixCount(tuple_t);
        const rest_t = try self.tupleRestElementTypeAtPosition(tuple_t, rest_pos);
        if (rest_t >= self.interner.pool.typeCount()) return null;
        return if (self.interner.pool.flagsOf(rest_t).is_type_parameter) rest_t else null;
    }

    fn variadicTupleRestAssignableToTypeParameter(self: *Checker, source_tuple: TypeId, source_rest: TypeId, target: TypeId) bool {
        if (self.tupleFixedPrefixCount(source_tuple) != 0) return false;
        if (self.tupleTypeLooksReadonly(source_tuple) or self.readonly_index_types.contains(source_tuple)) return false;
        if (source_rest != target and !self.typeParameterConstraintReaches(source_rest, target)) return false;
        const target_constraint = self.typeParameterConstraint(target) orelse return false;
        return self.objectTypeIsArrayLikeContainer(target_constraint) or self.isTupleShapedTarget(target_constraint);
    }

    fn typeParameterAssignableToVariadicTupleRest(self: *Checker, source: TypeId, target_tuple: TypeId, target_rest: TypeId) bool {
        if (source != target_rest) return false;
        const source_constraint = self.typeParameterConstraint(source) orelse return false;
        if (!self.objectTypeIsArrayLikeContainer(source_constraint) and !self.isTupleShapedTarget(source_constraint)) return false;
        const target_is_readonly = self.tupleTypeLooksReadonly(target_tuple) or self.readonly_index_types.contains(target_tuple);
        if (target_is_readonly) return true;
        return self.typeIsMutableArrayLike(source_constraint) or
            (self.isTupleShapedTarget(source_constraint) and !self.tupleTypeLooksReadonly(source_constraint));
    }

    fn variadicTupleRestAssignableToRest(
        self: *Checker,
        source_tuple: TypeId,
        source_rest: TypeId,
        target_tuple: TypeId,
        target_rest: TypeId,
    ) CheckError!bool {
        const source_readonly = self.tupleTypeLooksReadonly(source_tuple) or self.readonly_index_types.contains(source_tuple);
        const target_readonly = self.tupleTypeLooksReadonly(target_tuple) or self.readonly_index_types.contains(target_tuple);
        if (source_readonly and !target_readonly) return false;
        if (source_rest != target_rest and !self.typeParameterConstraintReaches(source_rest, target_rest)) return false;
        const source_prefix = self.tupleFixedPrefixCount(source_tuple);
        const target_prefix = self.tupleFixedPrefixCount(target_tuple);
        if (source_prefix != target_prefix) return false;
        var i: usize = 0;
        while (i < source_prefix) : (i += 1) {
            const source_t = self.tupleElementType(source_tuple, i);
            const target_t = self.tupleElementType(target_tuple, i);
            if (source_t == types.Primitive.none or target_t == types.Primitive.none) return false;
            if (!try self.checkerAssignableTo(source_t, target_t)) return false;
        }
        return true;
    }

    fn templateLiteralToTypeParameterNeedsInstantiationCheck(self: *Checker, source: TypeId, target: TypeId) bool {
        if (source == target) return false;
        if (source >= self.interner.pool.typeCount() or target >= self.interner.pool.typeCount()) return false;
        const sf = self.interner.pool.flagsOf(source);
        if (!sf.is_template_literal and !sf.is_string_mapping) return false;
        const tf = self.interner.pool.flagsOf(target);
        if (!tf.is_type_parameter or tf.is_union) return false;
        const constraint = self.typeParameterConstraint(target) orelse return false;
        if (constraint == target) return false;
        return self.engine.isAssignableTo(source, constraint) catch false;
    }

    fn templateLiteralAssertionToTypeParameterNeedsInstantiationCheck(self: *Checker, init_node: NodeId, target: TypeId) CheckError!bool {
        if (init_node == hir_mod.none_node_id) return false;
        const k = self.hir.kindOf(init_node);
        if (k != .as_expr and k != .type_assertion) return false;
        const a = hir_mod.asExpressionOf(self.hir, init_node);
        if (a.type_node == hir_mod.none_node_id or self.hir.kindOf(a.type_node) != .template_literal_type) return false;
        const source = try self.lowererLowerWithTypeParams(a.type_node);
        if (self.templateLiteralToTypeParameterNeedsInstantiationCheck(source, target)) return true;
        if (target >= self.interner.pool.typeCount()) return false;
        const tf = self.interner.pool.flagsOf(target);
        if (!tf.is_type_parameter or tf.is_union) return false;
        const constraint = self.typeParameterConstraint(target) orelse return false;
        return constraint != target;
    }

    fn typeParameterConstraintAssignableTo(self: *Checker, t: TypeId, target: TypeId) bool {
        const constraint = self.typeParameterConstraint(t) orelse return false;
        if (constraint == t) return false;
        return constraint == target or (self.engine.isAssignableTo(constraint, target) catch false);
    }

    fn computedClassPropertyKeyIsSimpleLiteral(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        return f.is_literal and (f.is_string or f.is_number);
    }

    fn computedKeyIsUnresolvedIdentifier(self: *Checker, key: NodeId) bool {
        if (key == hir_mod.none_node_id or self.hir.kindOf(key) != .identifier) return false;
        return !self.identifierHasNarrowableValueBinding(key);
    }

    /// Returns the source text for a computed key when it is a simple
    /// identifier (e.g. `[e2]` -> `"e2"`). Walks the source forward
    /// from the key span end up to (but not including) the closing
    /// `]`, preserving inner whitespace so the rendered text matches
    /// the source ÃÂ¢ÃÂÃÂ e.g. `[public ]` keeps its trailing space. Falls
    /// back to the interned name when source isn't available.
    /// Returns null when the key is not a bare identifier.
    fn computedKeyIdentifierText(self: *Checker, key: NodeId) ?[]const u8 {
        if (key == hir_mod.none_node_id) return null;
        const kind = self.hir.kindOf(key);
        const src = self.source orelse {
            if (kind == .identifier) {
                const id = hir_mod.identifierOf(self.hir, key);
                return self.string_interner.get(id.name);
            }
            return null;
        };
        const span = self.hir.spanOf(key);
        if (span.start >= src.len) return null;
        if (kind == .identifier) {
            var end: usize = @min(@as(usize, span.end), src.len);
            while (end < src.len and src[end] != ']' and src[end] != '\n') : (end += 1) {}
            return src[@intCast(span.start)..end];
        }
        // For non-identifier keys (e.g. `Symbol()`, member exprs), use
        // the span as-is so the rendered text matches the source.
        // Mirrors `symbolProperty7` TS2564 baseline: `Property '[Symbol()]'`.
        const start: usize = @intCast(span.start);
        const end: usize = @min(@as(usize, span.end), src.len);
        if (end <= start) return null;
        return src[start..end];
    }

    /// Returns true when a type annotation contains any bare type-ref
    /// that doesn't resolve to a visible type declaration, builtin,
    /// or type parameter. Used to suppress TS2564 for computed class
    /// fields like `[e]: Type` where `Type` is unresolved ÃÂ¢ÃÂÃÂ tsc skips
    /// TS2564 since the field's type cannot be analyzed. Mirrors
    /// `parserComputedPropertyName9`.
    fn typeAnnotationContainsUnresolvedRef(self: *Checker, type_node: NodeId) bool {
        if (type_node == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(type_node)) {
            .identifier => blk: {
                const id = hir_mod.identifierOf(self.hir, type_node);
                const raw = self.string_interner.get(id.name);
                if (isPrimitiveTypeNameText(raw) or self.isBuiltinName(id.name)) break :blk false;
                if (self.nameHasEnclosingTypeParameter(id.name, type_node)) break :blk false;
                if (self.lookupNarrow(id.name)) |t| {
                    if (t != types.Primitive.none and
                        t != types.Primitive.any and
                        t != types.Primitive.unknown) break :blk false;
                }
                if (self.visibleTypeDeclarationExistsAt(type_node, id.name)) break :blk false;
                break :blk true;
            },
            .type_ref => blk: {
                const r = hir_mod.typeRefOf(self.hir, type_node);
                for (hir_mod.typeRefArgs(self.hir, type_node)) |arg| {
                    if (self.typeAnnotationContainsUnresolvedRef(arg)) break :blk true;
                }
                if (r.qualifier_len != 0 or r.args_len != 0) break :blk false;
                if (self.nameHasEnclosingTypeParameter(r.name, type_node)) break :blk false;
                if (self.typeRefNameExists(r.name) or self.visibleTypeDeclarationExistsAt(type_node, r.name)) break :blk false;
                const raw = self.string_interner.get(r.name);
                if (std.mem.eql(u8, raw, "super")) break :blk true;
                if (self.lowerBuiltinObjectType(raw) != null) break :blk false;
                if (std.mem.eql(u8, raw, "any") or
                    std.mem.eql(u8, raw, "unknown") or
                    std.mem.eql(u8, raw, "never") or
                    std.mem.eql(u8, raw, "void") or
                    std.mem.eql(u8, raw, "null") or
                    std.mem.eql(u8, raw, "undefined") or
                    std.mem.eql(u8, raw, "string") or
                    std.mem.eql(u8, raw, "number") or
                    std.mem.eql(u8, raw, "boolean") or
                    std.mem.eql(u8, raw, "bigint") or
                    std.mem.eql(u8, raw, "symbol") or
                    std.mem.eql(u8, raw, "object") or
                    self.isBuiltinName(r.name))
                {
                    break :blk false;
                }
                break :blk true;
            },
            .array_type => self.typeAnnotationContainsUnresolvedRef(hir_mod.arrayTypeOf(self.hir, type_node).element),
            .readonly_type => self.typeAnnotationContainsUnresolvedRef(hir_mod.readonlyTypeOf(self.hir, type_node).operand),
            .union_type => for (hir_mod.unionTypeMembers(self.hir, type_node)) |member| {
                if (self.typeAnnotationContainsUnresolvedRef(member)) break true;
            } else false,
            .intersection_type => for (hir_mod.intersectionTypeMembers(self.hir, type_node)) |member| {
                if (self.typeAnnotationContainsUnresolvedRef(member)) break true;
            } else false,
            .fn_type, .constructor_type => blk: {
                const ft = hir_mod.fnTypeOf(self.hir, type_node);
                for (self.hir.childSlice(ft.params_start, ft.params_len)) |param_node| {
                    if (self.hir.kindOf(param_node) != .parameter) continue;
                    const param = hir_mod.parameterOf(self.hir, param_node);
                    if (self.typeAnnotationContainsUnresolvedRef(param.type_annotation)) break :blk true;
                }
                break :blk self.typeAnnotationContainsUnresolvedRef(ft.return_type);
            },
            else => false,
        };
    }

    fn typeAnnotationShouldBecomeErrorAny(self: *Checker, type_node: NodeId) bool {
        if (type_node == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(type_node)) {
            .type_ref => blk: {
                const ref = hir_mod.typeRefOf(self.hir, type_node);
                if (ref.qualifier_len != 0 or ref.args_len != 0) break :blk false;
                break :blk self.typeAnnotationContainsUnresolvedRef(type_node);
            },
            .array_type => self.typeAnnotationShouldBecomeErrorAny(hir_mod.arrayTypeOf(self.hir, type_node).element),
            .readonly_type => self.typeAnnotationShouldBecomeErrorAny(hir_mod.readonlyTypeOf(self.hir, type_node).operand),
            else => self.typeAnnotationContainsUnresolvedRef(type_node),
        };
    }

    fn computedClassPropertyKeyIsSimpleLiteralNode(self: *Checker, key: NodeId, t: TypeId) bool {
        switch (self.hir.kindOf(key)) {
            .literal_string, .literal_number => return true,
            .member_access => {
                const m = hir_mod.memberOf(self.hir, key);
                if (self.hir.kindOf(m.object) == .identifier) {
                    const obj = hir_mod.identifierOf(self.hir, m.object);
                    if (std.mem.eql(u8, self.string_interner.get(obj.name), "Symbol")) return true;
                    const raw = std.mem.trim(u8, self.nodeSourceTextOrEmpty(key), " \t\r\n");
                    if (self.sourceHasUniqueSymbolDeclaration(raw)) return true;
                }
                return self.computedClassPropertyKeyIsSimpleLiteral(t);
            },
            .identifier => {
                // Bare identifier references are syntactically simple
                // ÃÂ¢ÃÂÃÂ TS1166 fires only on complex expressions (binary
                // ops, unary ops, calls, etc.). The DIAGNOSTIC for
                // non-literal-typed identifiers is TS2411 (index-
                // signature compatibility), not TS1166. Mirrors
                // `computedPropertyNames12_ES{5,6}` where `[s]`, `[n]`,
                // `[a]` on a class property emit no TS1166 even though
                // their types are `string`, `number`, `any`.
                return true;
            },
            else => return self.computedClassPropertyKeyIsSimpleLiteral(t),
        }
    }

    fn computedMethodOverloadKeyIsBindableName(self: *Checker, key: NodeId) bool {
        return switch (self.hir.kindOf(key)) {
            .identifier, .literal_string, .literal_number => true,
            .member_access => blk: {
                const m = hir_mod.memberOf(self.hir, key);
                break :blk self.computedMethodOverloadKeyIsBindableName(m.object);
            },
            else => false,
        };
    }

    fn objectPropertyIsBodylessMethodOverload(self: *Checker, op: hir_mod.ObjectPropertyPayload) bool {
        if (op.value == hir_mod.none_node_id) return true;
        const value_kind = self.hir.kindOf(op.value);
        if (value_kind != .fn_decl and value_kind != .fn_expr and value_kind != .arrow_fn) return false;
        return hir_mod.fnDeclOf(self.hir, op.value).body == hir_mod.none_node_id;
    }

    fn computedPropertyKeyTypeIsSymbolLike(self: *Checker, t: TypeId) CheckError!bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_symbol) return true;
        if (f.is_union) {
            var saw = false;
            for (self.interner.unionMembers(t)) |member| {
                if (!try self.computedPropertyKeyTypeIsSymbolLike(member)) return false;
                saw = true;
            }
            return saw;
        }
        return false;
    }

    fn computedPropertyKeyTypeIsNumberLike(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_number) return true;
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.computedPropertyKeyTypeIsNumberLike(member)) return false;
            }
            return true;
        }
        return false;
    }

    fn checkComputedIndexSignatureCompatibility(
        self: *Checker,
        node: NodeId,
        key_t: TypeId,
        member_t: TypeId,
        string_idx: TypeId,
        number_idx: TypeId,
        symbol_idx: TypeId,
    ) CheckError!void {
        _ = symbol_idx;
        if (member_t == types.Primitive.any or key_t == types.Primitive.any or key_t == types.Primitive.unknown) return;
        const key_is_symbol = try self.computedPropertyKeyTypeIsSymbolLike(key_t);
        // Render `[<source-text>]` for the property name when the
        // source span is available so TS2411 prose matches upstream
        // `Property '[1 << 6]' of type 'Foo'` / `Property '[""]' of
        // type '() => Foo'` (fixtures `computedPropertyNames38/39_ES{5,6}`,
        // `computedPropertyNames40_ES{5,6}`).
        const display_name: ?[]const u8 = blk: {
            const src = self.source orelse break :blk null;
            const span = self.hir.spanOf(node);
            if (span.start >= span.end or span.end > src.len) break :blk null;
            const key_text = src[span.start..span.end];
            const arena = self.diag_arena.allocator();
            break :blk std.fmt.allocPrint(arena, "[{s}]", .{key_text}) catch null;
        };
        // Anchor at the opening `[` of the computed key so the
        // diagnostic column matches upstream's
        // `computedPropertyNames39_ES{5,6}.ts(8,9)` baseline rather
        // than landing one character later inside the expression.
        const bracket_pos: ?u32 = blk: {
            const src = self.source orelse break :blk null;
            const span = self.hir.spanOf(node);
            if (span.start == 0 or span.start > src.len) break :blk null;
            var i: usize = span.start;
            while (i > 0) {
                i -= 1;
                if (src[i] == '[') break :blk @intCast(i);
                if (src[i] != ' ' and src[i] != '\t' and src[i] != '\n' and src[i] != '\r') break;
            }
            break :blk null;
        };
        if (self.computedPropertyKeyTypeIsNumberLike(key_t) and
            number_idx != types.Primitive.none and
            number_idx != types.Primitive.any)
        {
            if (!(self.engine.isAssignableTo(member_t, number_idx) catch true)) {
                if (display_name) |dn| {
                    const msg = try self.formatPropertyNotAssignableToIndexType(dn, member_t, number_idx, "number", hir_mod.none_node_id, hir_mod.none_node_id);
                    try self.reportAt(node, bracket_pos, TsCodes.property_not_assignable_to_index_type, msg);
                } else {
                    try self.reportAt(node, bracket_pos, TsCodes.property_not_assignable_to_index_type, "Property is not assignable to number index type.");
                }
            }
        }
        if (!key_is_symbol and string_idx != types.Primitive.none and string_idx != types.Primitive.any) {
            if (!(self.engine.isAssignableTo(member_t, string_idx) catch true)) {
                if (display_name) |dn| {
                    const msg = try self.formatPropertyNotAssignableToIndexType(dn, member_t, string_idx, "string", hir_mod.none_node_id, hir_mod.none_node_id);
                    try self.reportAt(node, bracket_pos, TsCodes.property_not_assignable_to_index_type, msg);
                } else {
                    try self.reportAt(node, bracket_pos, TsCodes.property_not_assignable_to_index_type, "Property is not assignable to string index type.");
                }
            }
        }
    }

    fn checkClassMemberInferredInaccessibleThisType(
        self: *Checker,
        anchor: NodeId,
        member_name: hir_mod.StringId,
        body_or_expr: NodeId,
        is_method_body: bool,
    ) CheckError!void {
        if (!self.strict_flags.declaration) return;
        const hit = if (is_method_body)
            self.returnExpressionContainsInferredInaccessibleThisType(body_or_expr)
        else
            self.expressionContainsInferredInaccessibleThisType(body_or_expr, false, false);
        if (!hit) return;
        const name_str = self.string_interner.get(member_name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "The inferred type of '{s}' references an inaccessible 'this' type. A type annotation is necessary.",
            .{name_str},
        );
        try self.report(if (anchor != hir_mod.none_node_id) anchor else body_or_expr, TsCodes.inferred_type_inaccessible_type, msg);
    }

    fn returnExpressionContainsInferredInaccessibleThisType(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(node)) {
            .return_stmt => self.expressionContainsInferredInaccessibleThisType(hir_mod.returnOf(self.hir, node).value, false, false),
            .block_stmt => blk: {
                for (hir_mod.blockStmts(self.hir, node)) |stmt| {
                    if (self.returnExpressionContainsInferredInaccessibleThisType(stmt)) break :blk true;
                }
                break :blk false;
            },
            .if_stmt => blk: {
                const i = hir_mod.ifOf(self.hir, node);
                break :blk self.returnExpressionContainsInferredInaccessibleThisType(i.then_branch) or
                    self.returnExpressionContainsInferredInaccessibleThisType(i.else_branch);
            },
            .try_stmt => blk: {
                const t = hir_mod.tryOf(self.hir, node);
                break :blk self.returnExpressionContainsInferredInaccessibleThisType(t.block) or
                    self.returnExpressionContainsInferredInaccessibleThisType(t.catch_block) or
                    self.returnExpressionContainsInferredInaccessibleThisType(t.finally_block);
            },
            .switch_stmt => blk: {
                for (hir_mod.switchCases(self.hir, node)) |case| {
                    if (self.returnExpressionContainsInferredInaccessibleThisType(case)) break :blk true;
                }
                break :blk false;
            },
            .switch_case => blk: {
                for (hir_mod.switchCaseStmts(self.hir, node)) |stmt| {
                    if (self.returnExpressionContainsInferredInaccessibleThisType(stmt)) break :blk true;
                }
                break :blk false;
            },
            .fn_decl, .fn_expr, .arrow_fn => false,
            else => false,
        };
    }

    fn expressionContainsInferredInaccessibleThisType(
        self: *Checker,
        node: NodeId,
        inside_array: bool,
        inside_object: bool,
    ) bool {
        if (node == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(node)) {
            .this_expr => inside_object,
            .identifier => blk: {
                if (!inside_object) break :blk false;
                const id = hir_mod.identifierOf(self.hir, node);
                break :blk std.mem.eql(u8, self.string_interner.get(id.name), "this");
            },
            .array_literal => blk: {
                for (hir_mod.arrayLiteralElements(self.hir, node)) |el| {
                    if (self.expressionContainsInferredInaccessibleThisType(el, true, inside_object)) break :blk true;
                }
                break :blk false;
            },
            .object_literal => blk: {
                for (hir_mod.objectLiteralProps(self.hir, node)) |prop| {
                    if (self.expressionContainsInferredInaccessibleThisType(prop, inside_array, true)) break :blk true;
                }
                break :blk false;
            },
            .object_property => blk: {
                const op = hir_mod.objectPropertyOf(self.hir, node);
                break :blk self.expressionContainsInferredInaccessibleThisType(op.key, inside_array, inside_object) or
                    self.expressionContainsInferredInaccessibleThisType(op.value, inside_array, inside_object);
            },
            .spread => self.expressionContainsInferredInaccessibleThisType(hir_mod.spreadOf(self.hir, node).expression, inside_array, inside_object),
            .as_expr, .satisfies_expr, .type_assertion, .non_null_expr => self.expressionContainsInferredInaccessibleThisType(hir_mod.asExpressionOf(self.hir, node).expr, inside_array, inside_object),
            .member_access => self.expressionContainsInferredInaccessibleThisType(hir_mod.memberOf(self.hir, node).object, inside_array, inside_object),
            .element_access => blk: {
                const e = hir_mod.elementOf(self.hir, node);
                break :blk self.expressionContainsInferredInaccessibleThisType(e.object, inside_array, inside_object) or
                    self.expressionContainsInferredInaccessibleThisType(e.index, inside_array, inside_object);
            },
            .call_expr, .new_expr => blk: {
                const c = hir_mod.callOf(self.hir, node);
                if (self.expressionContainsInferredInaccessibleThisType(c.callee, inside_array, inside_object)) break :blk true;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.expressionContainsInferredInaccessibleThisType(arg, inside_array, inside_object)) break :blk true;
                }
                break :blk false;
            },
            .binary_op => blk: {
                const b = hir_mod.binopOf(self.hir, node);
                break :blk self.expressionContainsInferredInaccessibleThisType(b.lhs, inside_array, inside_object) or
                    self.expressionContainsInferredInaccessibleThisType(b.rhs, inside_array, inside_object);
            },
            .logical_op => blk: {
                const l = hir_mod.logicalOf(self.hir, node);
                break :blk self.expressionContainsInferredInaccessibleThisType(l.lhs, inside_array, inside_object) or
                    self.expressionContainsInferredInaccessibleThisType(l.rhs, inside_array, inside_object);
            },
            .conditional => blk: {
                const c = hir_mod.conditionalOf(self.hir, node);
                break :blk self.expressionContainsInferredInaccessibleThisType(c.cond, inside_array, inside_object) or
                    self.expressionContainsInferredInaccessibleThisType(c.then_branch, inside_array, inside_object) or
                    self.expressionContainsInferredInaccessibleThisType(c.else_branch, inside_array, inside_object);
            },
            .unary_op => self.expressionContainsInferredInaccessibleThisType(hir_mod.unaryOf(self.hir, node).operand, inside_array, inside_object),
            .assignment => blk: {
                const a = hir_mod.assignmentOf(self.hir, node);
                break :blk self.expressionContainsInferredInaccessibleThisType(a.target, inside_array, inside_object) or
                    self.expressionContainsInferredInaccessibleThisType(a.value, inside_array, inside_object);
            },
            .fn_decl, .fn_expr, .arrow_fn => false,
            else => false,
        };
    }

    fn expressionContainsThis(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        switch (self.hir.kindOf(node)) {
            .this_expr => return true,
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, node);
                return std.mem.eql(u8, self.string_interner.get(id.name), "this");
            },
            .member_access => {
                const m = hir_mod.memberOf(self.hir, node);
                return self.expressionContainsThis(m.object);
            },
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                return self.expressionContainsThis(e.object) or self.expressionContainsThis(e.index);
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                if (self.expressionContainsThis(c.callee)) return true;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.expressionContainsThis(arg)) return true;
                }
                return false;
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                return self.expressionContainsThis(b.lhs) or self.expressionContainsThis(b.rhs);
            },
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                return self.expressionContainsThis(l.lhs) or self.expressionContainsThis(l.rhs);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                return self.expressionContainsThis(c.cond) or
                    self.expressionContainsThis(c.then_branch) or
                    self.expressionContainsThis(c.else_branch);
            },
            .unary_op => return self.expressionContainsThis(hir_mod.unaryOf(self.hir, node).operand),
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                return self.expressionContainsThis(a.target) or self.expressionContainsThis(a.value);
            },
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |s| {
                    if (self.expressionContainsThis(s)) return true;
                }
                return false;
            },
            .return_stmt => return self.expressionContainsThis(hir_mod.returnOf(self.hir, node).value),
            .array_literal => {
                for (hir_mod.arrayLiteralElements(self.hir, node)) |el| {
                    if (self.expressionContainsThis(el)) return true;
                }
                return false;
            },
            .object_literal => {
                for (hir_mod.objectLiteralProps(self.hir, node)) |p| {
                    if (self.hir.kindOf(p) == .object_property) {
                        const op = hir_mod.objectPropertyOf(self.hir, p);
                        if (self.expressionContainsThis(op.key) or self.expressionContainsThis(op.value)) return true;
                    } else if (self.expressionContainsThis(p)) return true;
                }
                return false;
            },
            else => return false,
        }
    }

    /// Locate the inner `super` token within an expression so callers
    /// can anchor diagnostics on the keyword itself (not the enclosing
    /// computed-name brackets). Returns `hir_mod.none_node_id` when no
    /// transitive super reference is present. Mirrors tsc's anchor for
    /// TS2466 in `computedPropertyNames26_ES{5,6}`.
    fn findSuperNode(self: *Checker, node: NodeId) NodeId {
        if (node == hir_mod.none_node_id) return hir_mod.none_node_id;
        switch (self.hir.kindOf(node)) {
            .super_expr => return node,
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, node);
                if (std.mem.eql(u8, self.string_interner.get(id.name), "super")) return node;
                return hir_mod.none_node_id;
            },
            .member_access => return self.findSuperNode(hir_mod.memberOf(self.hir, node).object),
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                const o = self.findSuperNode(e.object);
                if (o != hir_mod.none_node_id) return o;
                return self.findSuperNode(e.index);
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                const cs = self.findSuperNode(c.callee);
                if (cs != hir_mod.none_node_id) return cs;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    const ars = self.findSuperNode(arg);
                    if (ars != hir_mod.none_node_id) return ars;
                }
                return hir_mod.none_node_id;
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                const l = self.findSuperNode(b.lhs);
                if (l != hir_mod.none_node_id) return l;
                return self.findSuperNode(b.rhs);
            },
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                const lhs = self.findSuperNode(l.lhs);
                if (lhs != hir_mod.none_node_id) return lhs;
                return self.findSuperNode(l.rhs);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                const cs = self.findSuperNode(c.cond);
                if (cs != hir_mod.none_node_id) return cs;
                const tb = self.findSuperNode(c.then_branch);
                if (tb != hir_mod.none_node_id) return tb;
                return self.findSuperNode(c.else_branch);
            },
            .unary_op => return self.findSuperNode(hir_mod.unaryOf(self.hir, node).operand),
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                const ts = self.findSuperNode(a.target);
                if (ts != hir_mod.none_node_id) return ts;
                return self.findSuperNode(a.value);
            },
            .array_literal => {
                for (hir_mod.arrayLiteralElements(self.hir, node)) |el| {
                    const s = self.findSuperNode(el);
                    if (s != hir_mod.none_node_id) return s;
                }
                return hir_mod.none_node_id;
            },
            .object_literal => {
                for (hir_mod.objectLiteralProps(self.hir, node)) |p| {
                    if (self.hir.kindOf(p) == .object_property) {
                        const op = hir_mod.objectPropertyOf(self.hir, p);
                        const ks = self.findSuperNode(op.key);
                        if (ks != hir_mod.none_node_id) return ks;
                        const vs = self.findSuperNode(op.value);
                        if (vs != hir_mod.none_node_id) return vs;
                    } else {
                        const s = self.findSuperNode(p);
                        if (s != hir_mod.none_node_id) return s;
                    }
                }
                return hir_mod.none_node_id;
            },
            else => return hir_mod.none_node_id,
        }
    }

    fn expressionContainsSuper(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        switch (self.hir.kindOf(node)) {
            .super_expr => return true,
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, node);
                return std.mem.eql(u8, self.string_interner.get(id.name), "super");
            },
            .member_access => return self.expressionContainsSuper(hir_mod.memberOf(self.hir, node).object),
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                return self.expressionContainsSuper(e.object) or self.expressionContainsSuper(e.index);
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                if (self.expressionContainsSuper(c.callee)) return true;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.expressionContainsSuper(arg)) return true;
                }
                return false;
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                return self.expressionContainsSuper(b.lhs) or self.expressionContainsSuper(b.rhs);
            },
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                return self.expressionContainsSuper(l.lhs) or self.expressionContainsSuper(l.rhs);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                return self.expressionContainsSuper(c.cond) or
                    self.expressionContainsSuper(c.then_branch) or
                    self.expressionContainsSuper(c.else_branch);
            },
            .unary_op => return self.expressionContainsSuper(hir_mod.unaryOf(self.hir, node).operand),
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                return self.expressionContainsSuper(a.target) or self.expressionContainsSuper(a.value);
            },
            .array_literal => {
                for (hir_mod.arrayLiteralElements(self.hir, node)) |el| {
                    if (self.expressionContainsSuper(el)) return true;
                }
                return false;
            },
            .object_literal => {
                for (hir_mod.objectLiteralProps(self.hir, node)) |p| {
                    if (self.hir.kindOf(p) == .object_property) {
                        const op = hir_mod.objectPropertyOf(self.hir, p);
                        if (self.expressionContainsSuper(op.key) or self.expressionContainsSuper(op.value)) return true;
                    } else if (self.expressionContainsSuper(p)) return true;
                }
                return false;
            },
            else => return false,
        }
    }

    fn nodeContainsSuperReference(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        switch (self.hir.kindOf(node)) {
            .super_expr => return true,
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, node);
                return std.mem.eql(u8, self.string_interner.get(id.name), "super");
            },
            .fn_decl, .fn_expr, .arrow_fn, .class_decl, .class_expr => return false,
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |stmt| {
                    if (self.nodeContainsSuperReference(stmt)) return true;
                }
                return false;
            },
            .var_decl, .let_decl, .const_decl => return self.nodeContainsSuperReference(hir_mod.varDeclOf(self.hir, node).init),
            .return_stmt => return self.nodeContainsSuperReference(hir_mod.returnOf(self.hir, node).value),
            .throw_stmt => return self.nodeContainsSuperReference(hir_mod.throwOf(self.hir, node).value),
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                return self.nodeContainsSuperReference(i.cond) or
                    self.nodeContainsSuperReference(i.then_branch) or
                    self.nodeContainsSuperReference(i.else_branch);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                return self.nodeContainsSuperReference(w.cond) or self.nodeContainsSuperReference(w.body);
            },
            .do_while_stmt => {
                const d = hir_mod.doWhileOf(self.hir, node);
                return self.nodeContainsSuperReference(d.body) or self.nodeContainsSuperReference(d.cond);
            },
            .for_stmt => {
                const f = hir_mod.forStmtOf(self.hir, node);
                return self.nodeContainsSuperReference(f.init) or
                    self.nodeContainsSuperReference(f.cond) or
                    self.nodeContainsSuperReference(f.update) or
                    self.nodeContainsSuperReference(f.body);
            },
            .for_in_stmt, .for_of_stmt => {
                const f = hir_mod.forInOf(self.hir, node);
                return self.nodeContainsSuperReference(f.target) or
                    self.nodeContainsSuperReference(f.source) or
                    self.nodeContainsSuperReference(f.body);
            },
            .try_stmt => {
                const t = hir_mod.tryOf(self.hir, node);
                return self.nodeContainsSuperReference(t.block) or
                    self.nodeContainsSuperReference(t.catch_block) or
                    self.nodeContainsSuperReference(t.finally_block);
            },
            .switch_stmt => {
                const s = hir_mod.switchOf(self.hir, node);
                if (self.nodeContainsSuperReference(s.discriminant)) return true;
                for (hir_mod.switchCases(self.hir, node)) |case| {
                    if (self.nodeContainsSuperReference(case)) return true;
                }
                return false;
            },
            .switch_case => {
                const sc = hir_mod.switchCaseOf(self.hir, node);
                if (self.nodeContainsSuperReference(sc.value)) return true;
                for (hir_mod.switchCaseStmts(self.hir, node)) |stmt| {
                    if (self.nodeContainsSuperReference(stmt)) return true;
                }
                return false;
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                if (self.nodeContainsSuperReference(c.callee)) return true;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.nodeContainsSuperReference(arg)) return true;
                }
                return false;
            },
            .member_access => return self.nodeContainsSuperReference(hir_mod.memberOf(self.hir, node).object),
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                return self.nodeContainsSuperReference(e.object) or self.nodeContainsSuperReference(e.index);
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                return self.nodeContainsSuperReference(b.lhs) or self.nodeContainsSuperReference(b.rhs);
            },
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                return self.nodeContainsSuperReference(l.lhs) or self.nodeContainsSuperReference(l.rhs);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                return self.nodeContainsSuperReference(c.cond) or
                    self.nodeContainsSuperReference(c.then_branch) or
                    self.nodeContainsSuperReference(c.else_branch);
            },
            .unary_op => return self.nodeContainsSuperReference(hir_mod.unaryOf(self.hir, node).operand),
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                return self.nodeContainsSuperReference(a.target) or self.nodeContainsSuperReference(a.value);
            },
            .array_literal => {
                for (hir_mod.arrayLiteralElements(self.hir, node)) |el| {
                    if (self.nodeContainsSuperReference(el)) return true;
                }
                return false;
            },
            .object_literal => {
                for (hir_mod.objectLiteralProps(self.hir, node)) |p| {
                    if (self.nodeContainsSuperReference(p)) return true;
                }
                return false;
            },
            .object_property => {
                const op = hir_mod.objectPropertyOf(self.hir, node);
                return self.nodeContainsSuperReference(op.key) or self.nodeContainsSuperReference(op.value);
            },
            .as_expr, .satisfies_expr, .type_assertion, .non_null_expr, .await_expr, .yield_expr => return self.nodeContainsSuperReference(hir_mod.asExpressionOf(self.hir, node).expr),
            else => return false,
        }
    }

    fn expressionContainsSuperCall(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        switch (self.hir.kindOf(node)) {
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |stmt| {
                    if (self.expressionContainsSuperCall(stmt)) return true;
                }
                return false;
            },
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, node);
                return self.expressionContainsSuperCall(v.init);
            },
            .return_stmt => return self.expressionContainsSuperCall(hir_mod.returnOf(self.hir, node).value),
            .throw_stmt => return self.expressionContainsSuperCall(hir_mod.throwOf(self.hir, node).value),
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                return self.expressionContainsSuperCall(i.cond) or
                    self.expressionContainsSuperCall(i.then_branch) or
                    self.expressionContainsSuperCall(i.else_branch);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                return self.expressionContainsSuperCall(w.cond) or
                    self.expressionContainsSuperCall(w.body);
            },
            .do_while_stmt => {
                const d = hir_mod.doWhileOf(self.hir, node);
                return self.expressionContainsSuperCall(d.body) or
                    self.expressionContainsSuperCall(d.cond);
            },
            .for_stmt => {
                const f = hir_mod.forStmtOf(self.hir, node);
                return self.expressionContainsSuperCall(f.init) or
                    self.expressionContainsSuperCall(f.cond) or
                    self.expressionContainsSuperCall(f.update) or
                    self.expressionContainsSuperCall(f.body);
            },
            .for_in_stmt, .for_of_stmt => {
                const f = hir_mod.forInOf(self.hir, node);
                return self.expressionContainsSuperCall(f.target) or
                    self.expressionContainsSuperCall(f.source) or
                    self.expressionContainsSuperCall(f.body);
            },
            .try_stmt => {
                const t = hir_mod.tryOf(self.hir, node);
                return self.expressionContainsSuperCall(t.block) or
                    self.expressionContainsSuperCall(t.catch_block) or
                    self.expressionContainsSuperCall(t.finally_block);
            },
            .switch_stmt => {
                const s = hir_mod.switchOf(self.hir, node);
                if (self.expressionContainsSuperCall(s.discriminant)) return true;
                for (hir_mod.switchCases(self.hir, node)) |case| {
                    if (self.expressionContainsSuperCall(case)) return true;
                }
                return false;
            },
            .switch_case => {
                const sc = hir_mod.switchCaseOf(self.hir, node);
                if (self.expressionContainsSuperCall(sc.value)) return true;
                for (hir_mod.switchCaseStmts(self.hir, node)) |stmt| {
                    if (self.expressionContainsSuperCall(stmt)) return true;
                }
                return false;
            },
            .call_expr => {
                const c = hir_mod.callOf(self.hir, node);
                if (self.callExprIsTaggedTemplate(node)) return false;
                if (self.hir.kindOf(c.callee) == .super_expr) return true;
                if (self.hir.kindOf(c.callee) == .identifier) {
                    const id = hir_mod.identifierOf(self.hir, c.callee);
                    if (std.mem.eql(u8, self.string_interner.get(id.name), "super")) return true;
                }
                if (self.expressionContainsSuperCall(c.callee)) return true;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.expressionContainsSuperCall(arg)) return true;
                }
                return false;
            },
            .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                if (self.expressionContainsSuperCall(c.callee)) return true;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.expressionContainsSuperCall(arg)) return true;
                }
                return false;
            },
            .member_access => return self.expressionContainsSuperCall(hir_mod.memberOf(self.hir, node).object),
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                return self.expressionContainsSuperCall(e.object) or self.expressionContainsSuperCall(e.index);
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                return self.expressionContainsSuperCall(b.lhs) or self.expressionContainsSuperCall(b.rhs);
            },
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                return self.expressionContainsSuperCall(l.lhs) or self.expressionContainsSuperCall(l.rhs);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                return self.expressionContainsSuperCall(c.cond) or
                    self.expressionContainsSuperCall(c.then_branch) or
                    self.expressionContainsSuperCall(c.else_branch);
            },
            .unary_op => return self.expressionContainsSuperCall(hir_mod.unaryOf(self.hir, node).operand),
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                return self.expressionContainsSuperCall(a.target) or self.expressionContainsSuperCall(a.value);
            },
            .array_literal => {
                for (hir_mod.arrayLiteralElements(self.hir, node)) |el| {
                    if (self.expressionContainsSuperCall(el)) return true;
                }
                return false;
            },
            .object_literal => {
                for (hir_mod.objectLiteralProps(self.hir, node)) |p| {
                    if (self.hir.kindOf(p) == .object_property) {
                        const op = hir_mod.objectPropertyOf(self.hir, p);
                        if (self.expressionContainsSuperCall(op.key) or self.expressionContainsSuperCall(op.value)) return true;
                    } else if (self.expressionContainsSuperCall(p)) return true;
                }
                return false;
            },
            else => return false,
        }
    }

    /// TS17009 helper ÃÂ¢ÃÂÃÂ walk a derived-class constructor body looking
    /// for the first `this`-access (`this` or `this.x` / `this[x]`) that
    /// appears textually before the first `super(...)` call. Skips into
    /// nested function/arrow/method bodies because they may run after
    /// the super call returns. Returns the offending `this_expr` node
    /// when found, `none_node_id` otherwise. The first super call short-
    /// circuits the walk: callers receive `none_node_id` and avoid
    /// emitting TS17009 for any `this` ref appearing AFTER that point.
    ///
    /// Note on argument lists: upstream considers `this` referenced in
    /// the super call's own argument list (e.g. `super(this)`) to also
    /// fire, because the argument is evaluated BEFORE control "enters"
    /// the super constructor. The walker handles that by inspecting
    /// each call argument before recognizing the call as a super call.
    fn findThisBeforeSuperInCtor(self: *Checker, node: NodeId, found_super: *bool) NodeId {
        if (node == hir_mod.none_node_id) return hir_mod.none_node_id;
        if (found_super.*) return hir_mod.none_node_id;
        switch (self.hir.kindOf(node)) {
            .this_expr => return node,
            .super_expr => return hir_mod.none_node_id,
            // The parser lowers both `this` and `super` keywords to
            // `.identifier` nodes (see `kw_this`/`kw_super` branches in
            // `parsePrimaryExpression`). Recognize the textual name to
            // match upstream's pre-super `this` rule.
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, node);
                const name = self.string_interner.get(id.name);
                if (std.mem.eql(u8, name, "this")) return node;
                if (std.mem.eql(u8, name, "super")) return hir_mod.none_node_id;
                return hir_mod.none_node_id;
            },
            .fn_decl, .fn_expr, .arrow_fn => return hir_mod.none_node_id,
            .class_decl, .class_expr => {
                // Heritage expressions, decorators, and computed names are
                // evaluated when a class is defined. Method bodies and field
                // initializers remain scoped to the nested class.
                const class = hir_mod.classOf(self.hir, node);
                const heritage_this = self.findThisBeforeSuperInCtor(class.extends, found_super);
                if (heritage_this != hir_mod.none_node_id) return heritage_this;
                const class_members = hir_mod.classMembers(self.hir, node);
                for (class_members, 0..) |member, member_index| {
                    if (self.hir.kindOf(member) == .decorator) {
                        var target_index = member_index + 1;
                        while (target_index < class_members.len and
                            self.hir.kindOf(class_members[target_index]) == .decorator) : (target_index += 1)
                        {}
                        if (target_index >= class_members.len) continue;
                        const target_kind = self.hir.kindOf(class_members[target_index]);
                        if (target_kind != .fn_decl and target_kind != .fn_expr and target_kind != .arrow_fn) continue;
                        const found = self.findThisBeforeSuperInCtor(hir_mod.decoratorOf(self.hir, member).expression, found_super);
                        if (found != hir_mod.none_node_id) return found;
                    } else if (self.hir.kindOf(member) == .object_property) {
                        const property = hir_mod.objectPropertyOf(self.hir, member);
                        if (!property.is_computed) continue;
                        const found = self.findThisBeforeSuperInCtor(property.key, found_super);
                        if (found != hir_mod.none_node_id) return found;
                    }
                }
                return hir_mod.none_node_id;
            },
            .decorator => return self.findThisBeforeSuperInCtor(hir_mod.decoratorOf(self.hir, node).expression, found_super),
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |stmt| {
                    const r = self.findThisBeforeSuperInCtor(stmt, found_super);
                    if (r != hir_mod.none_node_id) return r;
                    if (found_super.*) return hir_mod.none_node_id;
                }
                return hir_mod.none_node_id;
            },
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, node);
                return self.findThisBeforeSuperInCtor(v.init, found_super);
            },
            .return_stmt => return self.findThisBeforeSuperInCtor(hir_mod.returnOf(self.hir, node).value, found_super),
            .throw_stmt => return self.findThisBeforeSuperInCtor(hir_mod.throwOf(self.hir, node).value, found_super),
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(i.cond, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                const r2 = self.findThisBeforeSuperInCtor(i.then_branch, found_super);
                if (r2 != hir_mod.none_node_id) return r2;
                if (found_super.*) return hir_mod.none_node_id;
                return self.findThisBeforeSuperInCtor(i.else_branch, found_super);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(w.cond, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                return self.findThisBeforeSuperInCtor(w.body, found_super);
            },
            .do_while_stmt => {
                const d = hir_mod.doWhileOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(d.body, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                return self.findThisBeforeSuperInCtor(d.cond, found_super);
            },
            .for_stmt => {
                const f = hir_mod.forStmtOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(f.init, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                const r2 = self.findThisBeforeSuperInCtor(f.cond, found_super);
                if (r2 != hir_mod.none_node_id) return r2;
                if (found_super.*) return hir_mod.none_node_id;
                const r3 = self.findThisBeforeSuperInCtor(f.update, found_super);
                if (r3 != hir_mod.none_node_id) return r3;
                if (found_super.*) return hir_mod.none_node_id;
                return self.findThisBeforeSuperInCtor(f.body, found_super);
            },
            .for_in_stmt, .for_of_stmt => {
                const f = hir_mod.forInOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(f.source, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                return self.findThisBeforeSuperInCtor(f.body, found_super);
            },
            .try_stmt => {
                const t = hir_mod.tryOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(t.block, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                const r2 = self.findThisBeforeSuperInCtor(t.catch_block, found_super);
                if (r2 != hir_mod.none_node_id) return r2;
                if (found_super.*) return hir_mod.none_node_id;
                return self.findThisBeforeSuperInCtor(t.finally_block, found_super);
            },
            .switch_stmt => {
                const s = hir_mod.switchOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(s.discriminant, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                for (hir_mod.switchCases(self.hir, node)) |case| {
                    const r = self.findThisBeforeSuperInCtor(case, found_super);
                    if (r != hir_mod.none_node_id) return r;
                    if (found_super.*) return hir_mod.none_node_id;
                }
                return hir_mod.none_node_id;
            },
            .switch_case => {
                const sc = hir_mod.switchCaseOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(sc.value, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                for (hir_mod.switchCaseStmts(self.hir, node)) |stmt| {
                    const r = self.findThisBeforeSuperInCtor(stmt, found_super);
                    if (r != hir_mod.none_node_id) return r;
                    if (found_super.*) return hir_mod.none_node_id;
                }
                return hir_mod.none_node_id;
            },
            .call_expr => {
                const c = hir_mod.callOf(self.hir, node);
                // Inspect arguments FIRST (they evaluate before the call):
                // `super(this)` should report TS17009 at the `this` arg.
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    const r = self.findThisBeforeSuperInCtor(arg, found_super);
                    if (r != hir_mod.none_node_id) return r;
                    if (found_super.*) return hir_mod.none_node_id;
                }
                // Then check whether the callee is `super` ÃÂ¢ÃÂÃÂ if so,
                // toggle `found_super` so subsequent walks short-circuit.
                const callee_kind = self.hir.kindOf(c.callee);
                if (callee_kind == .super_expr) {
                    found_super.* = true;
                    return hir_mod.none_node_id;
                }
                if (callee_kind == .identifier) {
                    const id = hir_mod.identifierOf(self.hir, c.callee);
                    if (std.mem.eql(u8, self.string_interner.get(id.name), "super")) {
                        found_super.* = true;
                        return hir_mod.none_node_id;
                    }
                }
                // Otherwise the callee itself might contain a `this`
                // ref (e.g. `this.foo()` BEFORE super) ÃÂ¢ÃÂÃÂ walk it.
                return self.findThisBeforeSuperInCtor(c.callee, found_super);
            },
            .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                const r0 = self.findThisBeforeSuperInCtor(c.callee, found_super);
                if (r0 != hir_mod.none_node_id) return r0;
                if (found_super.*) return hir_mod.none_node_id;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    const r = self.findThisBeforeSuperInCtor(arg, found_super);
                    if (r != hir_mod.none_node_id) return r;
                    if (found_super.*) return hir_mod.none_node_id;
                }
                return hir_mod.none_node_id;
            },
            .member_access => return self.findThisBeforeSuperInCtor(hir_mod.memberOf(self.hir, node).object, found_super),
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(e.object, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                return self.findThisBeforeSuperInCtor(e.index, found_super);
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(b.lhs, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                return self.findThisBeforeSuperInCtor(b.rhs, found_super);
            },
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(l.lhs, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                return self.findThisBeforeSuperInCtor(l.rhs, found_super);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(c.cond, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                const r2 = self.findThisBeforeSuperInCtor(c.then_branch, found_super);
                if (r2 != hir_mod.none_node_id) return r2;
                if (found_super.*) return hir_mod.none_node_id;
                return self.findThisBeforeSuperInCtor(c.else_branch, found_super);
            },
            .unary_op => return self.findThisBeforeSuperInCtor(hir_mod.unaryOf(self.hir, node).operand, found_super),
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                const r1 = self.findThisBeforeSuperInCtor(a.target, found_super);
                if (r1 != hir_mod.none_node_id) return r1;
                if (found_super.*) return hir_mod.none_node_id;
                return self.findThisBeforeSuperInCtor(a.value, found_super);
            },
            .array_literal => {
                for (hir_mod.arrayLiteralElements(self.hir, node)) |el| {
                    const r = self.findThisBeforeSuperInCtor(el, found_super);
                    if (r != hir_mod.none_node_id) return r;
                    if (found_super.*) return hir_mod.none_node_id;
                }
                return hir_mod.none_node_id;
            },
            .object_literal => {
                for (hir_mod.objectLiteralProps(self.hir, node)) |p| {
                    if (self.hir.kindOf(p) == .object_property) {
                        const op = hir_mod.objectPropertyOf(self.hir, p);
                        const r1 = self.findThisBeforeSuperInCtor(op.key, found_super);
                        if (r1 != hir_mod.none_node_id) return r1;
                        if (found_super.*) return hir_mod.none_node_id;
                        const r2 = self.findThisBeforeSuperInCtor(op.value, found_super);
                        if (r2 != hir_mod.none_node_id) return r2;
                        if (found_super.*) return hir_mod.none_node_id;
                    } else {
                        const r = self.findThisBeforeSuperInCtor(p, found_super);
                        if (r != hir_mod.none_node_id) return r;
                        if (found_super.*) return hir_mod.none_node_id;
                    }
                }
                return hir_mod.none_node_id;
            },
            .spread => return self.findThisBeforeSuperInCtor(hir_mod.spreadOf(self.hir, node).expression, found_super),
            else => return hir_mod.none_node_id,
        }
    }

    fn superCallIsInNestedFunctionInsideConstructor(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        var saw_nested_function = false;
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) continue;
            const f = hir_mod.fnDeclOf(self.hir, cur);
            if (f.flags.is_constructor) return saw_nested_function;
            saw_nested_function = true;
        }
        return false;
    }

    fn nodeIsDirectlyInsideConstructor(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) continue;
            const f = hir_mod.fnDeclOf(self.hir, cur);
            return f.flags.is_constructor;
        }
        return false;
    }

    /// TS2336 ÃÂ¢ÃÂÃÂ true when `node` (a `super` reference) lives inside a
    /// parameter initializer of a constructor that belongs to a
    /// derived class. Mirrors upstream's `isInConstructorArgumentInitializer`
    /// combined with the derived-class precondition: walk ancestors,
    /// quit at the first function-like, and accept when a `parameter`
    /// node whose parent is the constructor is reached.
    /// True when a `super.x` (or `super[x]`) property access sits
    /// directly inside a class field initializer ÃÂ¢ÃÂÃÂ i.e. the nearest
    /// enclosing member is a `static`/instance property declaration
    /// rather than a constructor, member function, or member accessor.
    /// Arrow functions are transparent. Mirrors upstream
    /// `checkSuperExpression`'s TS2338 path: super property access is
    /// permitted only in a constructor, member function, or member
    /// accessor of a derived class. A non-arrow `function`/method body
    /// in between is the (valid) member function frame and stops the
    /// search before the field is reached.
    fn superPropertyAccessInFieldInitializer(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) continue;
            if (k == .fn_decl or k == .fn_expr) {
                const f = hir_mod.fnDeclOf(self.hir, cur);
                // A constructor / method / accessor body is a valid
                // host for super property access.
                if (f.flags.is_constructor or f.flags.is_method or
                    f.flags.is_getter or f.flags.is_setter) return false;
                // A bare nested function breaks the super chain; the
                // dedicated TS2660/TS2335 path handles that, not this.
                return false;
            }
            if (k == .object_property) {
                const op = hir_mod.objectPropertyOf(self.hir, cur);
                if (op.is_method) return false;
                const parent = self.hir.parentOf(cur);
                if (parent == hir_mod.none_node_id) return false;
                const pk = self.hir.kindOf(parent);
                return pk == .class_decl or pk == .class_expr;
            }
            if (k == .class_decl or k == .class_expr) return false;
        }
        return false;
    }

    fn superReferenceInConstructorArgumentInitializer(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .parameter) {
                const ctor = self.hir.parentOf(cur);
                if (ctor == hir_mod.none_node_id) return false;
                const ck = self.hir.kindOf(ctor);
                if (ck != .fn_decl and ck != .fn_expr and ck != .arrow_fn) return false;
                const f = hir_mod.fnDeclOf(self.hir, ctor);
                if (!f.flags.is_constructor) return false;
                const class_node = self.enclosingClassNode(ctor);
                if (class_node == hir_mod.none_node_id) return false;
                const c = hir_mod.classOf(self.hir, class_node);
                if (c.extends == hir_mod.none_node_id) return false;
                return self.hir.kindOf(c.extends) != .literal_null;
            }
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) return false;
        }
        return false;
    }

    /// Returns the enclosing constructor node for `node`, or
    /// `none_node_id` if not directly inside one. Used by TS17009.
    fn enclosingConstructorNode(self: *Checker, node: NodeId) NodeId {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) continue;
            const f = hir_mod.fnDeclOf(self.hir, cur);
            if (f.flags.is_constructor) return cur;
            return hir_mod.none_node_id;
        }
        return hir_mod.none_node_id;
    }

    /// Returns the enclosing class (class_decl or class_expr) for a
    /// node, or `none_node_id` if not inside one.
    fn enclosingClassNode(self: *Checker, node: NodeId) NodeId {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .class_decl or k == .class_expr) return cur;
        }
        return hir_mod.none_node_id;
    }

    /// Recursively walks `node` looking for the first `super(...)`
    /// call expression. Returns its span END offset, or null if
    /// none. Stops descending into nested function-like / class
    /// nodes (their super calls don't count for the outer
    /// constructor's flow).
    fn firstSuperCallEndPos(self: *Checker, node: NodeId) ?u32 {
        if (node == hir_mod.none_node_id) return null;
        const k = self.hir.kindOf(node);
        switch (k) {
            .fn_decl, .fn_expr, .arrow_fn, .class_decl, .class_expr => return null,
            .call_expr => {
                const c = hir_mod.callOf(self.hir, node);
                if (self.hir.kindOf(c.callee) == .identifier) {
                    const id = hir_mod.identifierOf(self.hir, c.callee);
                    if (std.mem.eql(u8, self.string_interner.get(id.name), "super")) {
                        return self.hir.spanOf(node).end;
                    }
                }
                if (self.firstSuperCallEndPos(c.callee)) |p| return p;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.firstSuperCallEndPos(arg)) |p| return p;
                }
                return null;
            },
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |stmt| {
                    if (self.firstSuperCallEndPos(stmt)) |p| return p;
                }
                return null;
            },
            .var_decl, .let_decl, .const_decl => {
                const v = hir_mod.varDeclOf(self.hir, node);
                return self.firstSuperCallEndPos(v.init);
            },
            .return_stmt => return self.firstSuperCallEndPos(hir_mod.returnOf(self.hir, node).value),
            .throw_stmt => return self.firstSuperCallEndPos(hir_mod.throwOf(self.hir, node).value),
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                if (self.firstSuperCallEndPos(i.cond)) |p| return p;
                if (self.firstSuperCallEndPos(i.then_branch)) |p| return p;
                return self.firstSuperCallEndPos(i.else_branch);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                if (self.firstSuperCallEndPos(w.cond)) |p| return p;
                return self.firstSuperCallEndPos(w.body);
            },
            .do_while_stmt => {
                const d = hir_mod.doWhileOf(self.hir, node);
                if (self.firstSuperCallEndPos(d.body)) |p| return p;
                return self.firstSuperCallEndPos(d.cond);
            },
            .for_stmt => {
                const fr = hir_mod.forStmtOf(self.hir, node);
                if (self.firstSuperCallEndPos(fr.init)) |p| return p;
                if (self.firstSuperCallEndPos(fr.cond)) |p| return p;
                if (self.firstSuperCallEndPos(fr.update)) |p| return p;
                return self.firstSuperCallEndPos(fr.body);
            },
            .try_stmt => {
                const t = hir_mod.tryOf(self.hir, node);
                if (self.firstSuperCallEndPos(t.block)) |p| return p;
                if (self.firstSuperCallEndPos(t.catch_block)) |p| return p;
                return self.firstSuperCallEndPos(t.finally_block);
            },
            .switch_stmt => {
                const s = hir_mod.switchOf(self.hir, node);
                if (self.firstSuperCallEndPos(s.discriminant)) |p| return p;
                for (hir_mod.switchCases(self.hir, node)) |case| {
                    if (self.firstSuperCallEndPos(case)) |p| return p;
                }
                return null;
            },
            .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                if (self.firstSuperCallEndPos(c.callee)) |p| return p;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.firstSuperCallEndPos(arg)) |p| return p;
                }
                return null;
            },
            .member_access => return self.firstSuperCallEndPos(hir_mod.memberOf(self.hir, node).object),
            .object_literal => {
                for (hir_mod.objectLiteralProps(self.hir, node)) |p| {
                    if (self.firstSuperCallEndPos(p)) |q| return q;
                }
                return null;
            },
            .object_property => {
                const op = hir_mod.objectPropertyOf(self.hir, node);
                return self.firstSuperCallEndPos(op.value);
            },
            .array_literal => {
                for (hir_mod.arrayLiteralElements(self.hir, node)) |elem| {
                    if (self.firstSuperCallEndPos(elem)) |p| return p;
                }
                return null;
            },
            else => return null,
        }
    }

    /// True when `node` is a `super(...)` call expression.
    fn callIsSuperCall(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(node) != .call_expr) return false;
        const c = hir_mod.callOf(self.hir, node);
        const callee_kind = self.hir.kindOf(c.callee);
        if (callee_kind == .super_expr) return true;
        if (callee_kind != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, c.callee);
        return std.mem.eql(u8, self.string_interner.get(id.name), "super");
    }

    /// Recursively walks `node` looking for the first `super(...)`
    /// call expression. Returns its NodeId, or `none_node_id`.
    /// Mirrors `firstSuperCallEndPos`' traversal but yields the node.
    fn findFirstSuperCallNode(self: *Checker, node: NodeId) NodeId {
        if (node == hir_mod.none_node_id) return hir_mod.none_node_id;
        const k = self.hir.kindOf(node);
        switch (k) {
            .fn_decl, .fn_expr, .arrow_fn, .class_decl, .class_expr => return hir_mod.none_node_id,
            .call_expr => {
                if (self.callIsSuperCall(node)) return node;
                const c = hir_mod.callOf(self.hir, node);
                const r = self.findFirstSuperCallNode(c.callee);
                if (r != hir_mod.none_node_id) return r;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    const a = self.findFirstSuperCallNode(arg);
                    if (a != hir_mod.none_node_id) return a;
                }
                return hir_mod.none_node_id;
            },
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |stmt| {
                    const r = self.findFirstSuperCallNode(stmt);
                    if (r != hir_mod.none_node_id) return r;
                }
                return hir_mod.none_node_id;
            },
            .var_decl, .let_decl, .const_decl => return self.findFirstSuperCallNode(hir_mod.varDeclOf(self.hir, node).init),
            .return_stmt => return self.findFirstSuperCallNode(hir_mod.returnOf(self.hir, node).value),
            .throw_stmt => return self.findFirstSuperCallNode(hir_mod.throwOf(self.hir, node).value),
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                var r = self.findFirstSuperCallNode(i.cond);
                if (r != hir_mod.none_node_id) return r;
                r = self.findFirstSuperCallNode(i.then_branch);
                if (r != hir_mod.none_node_id) return r;
                return self.findFirstSuperCallNode(i.else_branch);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                const r = self.findFirstSuperCallNode(w.cond);
                if (r != hir_mod.none_node_id) return r;
                return self.findFirstSuperCallNode(w.body);
            },
            .do_while_stmt => {
                const d = hir_mod.doWhileOf(self.hir, node);
                const r = self.findFirstSuperCallNode(d.body);
                if (r != hir_mod.none_node_id) return r;
                return self.findFirstSuperCallNode(d.cond);
            },
            .for_stmt => {
                const fr = hir_mod.forStmtOf(self.hir, node);
                var r = self.findFirstSuperCallNode(fr.init);
                if (r != hir_mod.none_node_id) return r;
                r = self.findFirstSuperCallNode(fr.cond);
                if (r != hir_mod.none_node_id) return r;
                r = self.findFirstSuperCallNode(fr.update);
                if (r != hir_mod.none_node_id) return r;
                return self.findFirstSuperCallNode(fr.body);
            },
            .for_in_stmt, .for_of_stmt => {
                const f = hir_mod.forInOf(self.hir, node);
                const r = self.findFirstSuperCallNode(f.source);
                if (r != hir_mod.none_node_id) return r;
                return self.findFirstSuperCallNode(f.body);
            },
            .try_stmt => {
                const t = hir_mod.tryOf(self.hir, node);
                var r = self.findFirstSuperCallNode(t.block);
                if (r != hir_mod.none_node_id) return r;
                r = self.findFirstSuperCallNode(t.catch_block);
                if (r != hir_mod.none_node_id) return r;
                return self.findFirstSuperCallNode(t.finally_block);
            },
            .switch_stmt => {
                const s = hir_mod.switchOf(self.hir, node);
                const r = self.findFirstSuperCallNode(s.discriminant);
                if (r != hir_mod.none_node_id) return r;
                for (hir_mod.switchCases(self.hir, node)) |case| {
                    const cr = self.findFirstSuperCallNode(case);
                    if (cr != hir_mod.none_node_id) return cr;
                }
                return hir_mod.none_node_id;
            },
            .switch_case => {
                const sc = hir_mod.switchCaseOf(self.hir, node);
                const r = self.findFirstSuperCallNode(sc.value);
                if (r != hir_mod.none_node_id) return r;
                for (hir_mod.switchCaseStmts(self.hir, node)) |stmt| {
                    const sr = self.findFirstSuperCallNode(stmt);
                    if (sr != hir_mod.none_node_id) return sr;
                }
                return hir_mod.none_node_id;
            },
            .conditional => {
                const tn = hir_mod.conditionalOf(self.hir, node);
                var r = self.findFirstSuperCallNode(tn.cond);
                if (r != hir_mod.none_node_id) return r;
                r = self.findFirstSuperCallNode(tn.then_branch);
                if (r != hir_mod.none_node_id) return r;
                return self.findFirstSuperCallNode(tn.else_branch);
            },
            .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                const r = self.findFirstSuperCallNode(c.callee);
                if (r != hir_mod.none_node_id) return r;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    const a = self.findFirstSuperCallNode(arg);
                    if (a != hir_mod.none_node_id) return a;
                }
                return hir_mod.none_node_id;
            },
            .member_access => return self.findFirstSuperCallNode(hir_mod.memberOf(self.hir, node).object),
            .object_literal => {
                for (hir_mod.objectLiteralProps(self.hir, node)) |p| {
                    const r = self.findFirstSuperCallNode(p);
                    if (r != hir_mod.none_node_id) return r;
                }
                return hir_mod.none_node_id;
            },
            .object_property => return self.findFirstSuperCallNode(hir_mod.objectPropertyOf(self.hir, node).value),
            .array_literal => {
                for (hir_mod.arrayLiteralElements(self.hir, node)) |elem| {
                    const r = self.findFirstSuperCallNode(elem);
                    if (r != hir_mod.none_node_id) return r;
                }
                return hir_mod.none_node_id;
            },
            else => return hir_mod.none_node_id,
        }
    }

    /// True when `super_call` is a direct (root-level) statement of
    /// the constructor `body` ÃÂ¢ÃÂÃÂ i.e. it appears as one of the body's
    /// top-level statements rather than nested inside a block, `if`,
    /// loop, ternary, etc. Mirrors `superCallIsRootLevelInConstructor`.
    fn superCallIsRootLevelInConstructor(self: *Checker, super_call: NodeId, body: NodeId) bool {
        if (body == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(body) != .block_stmt) return false;
        for (hir_mod.blockStmts(self.hir, body)) |stmt| {
            if (stmt == super_call) return true;
        }
        return false;
    }

    /// TS2376/TS2401 precondition: the derived-class constructor must
    /// place its super call at root level when the constructor
    /// declares parameter properties OR the class declares an
    /// initialized instance property / private (`#`) field. Mirrors
    /// `superCallShouldBeRootLevel`.
    fn constructorRequiresRootLevelSuper(self: *Checker, ctor: NodeId, class_node: NodeId) bool {
        for (hir_mod.fnParams(self.hir, ctor)) |p| {
            if (self.hir.kindOf(p) != .parameter) continue;
            const pp = hir_mod.parameterOf(self.hir, p);
            if (pp.flags.is_parameter_property) return true;
        }
        for (hir_mod.classMembers(self.hir, class_node)) |m| {
            if (self.hir.kindOf(m) != .object_property) continue;
            const op = hir_mod.objectPropertyOf(self.hir, m);
            if (op.is_static) continue;
            if (op.is_method) continue;
            // Private (`#x`) instance field ÃÂ¢ÃÂÃÂ counts regardless of
            // initializer, mirroring `IsPrivateIdentifierClassElementDeclaration`.
            if (self.memberKeyIsEcmaPrivate(op.key)) return true;
            // Initialized instance property.
            if (op.value != hir_mod.none_node_id) return true;
        }
        return false;
    }

    /// True when the class member key is an ECMAScript private name
    /// (`#field`) ÃÂ¢ÃÂÃÂ its identifier text begins with `#`.
    fn memberKeyIsEcmaPrivate(self: *Checker, key: NodeId) bool {
        if (key == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(key) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, key);
        const text = self.string_interner.get(id.name);
        return text.len > 0 and text[0] == '#';
    }

    /// Emits TS2376 / TS2401 for a derived-class constructor whose
    /// super call is misplaced when the class contains initialized
    /// properties, parameter properties, or private identifiers.
    /// Anchors as upstream: TS2401 on the super call, TS2376 on the
    /// constructor. Mirrors `checkConstructorDeclaration`.
    fn checkSuperCallPlacementInConstructor(self: *Checker, ctor: NodeId, class_node: NodeId) CheckError!void {
        const fn_p = hir_mod.fnDeclOf(self.hir, ctor);
        if (fn_p.body == hir_mod.none_node_id) return;
        const super_call = self.findFirstSuperCallNode(fn_p.body);
        if (super_call == hir_mod.none_node_id) return;
        if (!self.constructorRequiresRootLevelSuper(ctor, class_node)) return;
        if (!self.superCallIsRootLevelInConstructor(super_call, fn_p.body)) {
            try self.report(super_call, TsCodes.super_call_must_be_root_level, "A 'super' call must be a root-level statement within a constructor of a derived class that contains initialized properties, parameter properties, or private identifiers.");
            return;
        }
        // Root-level: it must additionally be the FIRST statement that
        // references `super`/`this`. Walk the body's top-level
        // statements; accept once we reach the super call, fail if a
        // `super`/`this` reference precedes it.
        for (hir_mod.blockStmts(self.hir, fn_p.body)) |stmt| {
            if (stmt == super_call) return;
            if (self.scanSuperOrThis(stmt)) {
                try self.report(ctor, TsCodes.super_call_must_be_first_statement, "A 'super' call must be the first statement in the constructor to refer to 'super' or 'this' when a derived class contains initialized properties, parameter properties, or private identifiers.");
                return;
            }
        }
        try self.report(ctor, TsCodes.super_call_must_be_first_statement, "A 'super' call must be the first statement in the constructor to refer to 'super' or 'this' when a derived class contains initialized properties, parameter properties, or private identifiers.");
    }

    /// True when `node` immediately references `super`/`this` without
    /// crossing into a nested function / arrow / class scope. Mirrors
    /// `nodeImmediatelyReferencesSuperOrThis`.
    fn scanSuperOrThis(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        const k = self.hir.kindOf(node);
        switch (k) {
            .this_expr, .super_expr => return true,
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, node);
                const text = self.string_interner.get(id.name);
                return std.mem.eql(u8, text, "super") or std.mem.eql(u8, text, "this");
            },
            .fn_decl, .fn_expr, .arrow_fn => return false,
            .class_decl, .class_expr => {
                const class = hir_mod.classOf(self.hir, node);
                if (self.scanSuperOrThis(class.extends)) return true;
                const class_members = hir_mod.classMembers(self.hir, node);
                for (class_members, 0..) |member, member_index| {
                    if (self.hir.kindOf(member) == .decorator) {
                        var target_index = member_index + 1;
                        while (target_index < class_members.len and
                            self.hir.kindOf(class_members[target_index]) == .decorator) : (target_index += 1)
                        {}
                        if (target_index < class_members.len) {
                            const target_kind = self.hir.kindOf(class_members[target_index]);
                            if ((target_kind == .fn_decl or target_kind == .fn_expr or target_kind == .arrow_fn) and
                                self.scanSuperOrThis(hir_mod.decoratorOf(self.hir, member).expression)) return true;
                        }
                    }
                    if (self.hir.kindOf(member) == .object_property) {
                        const property = hir_mod.objectPropertyOf(self.hir, member);
                        if (property.is_computed and self.scanSuperOrThis(property.key)) return true;
                    }
                }
                return false;
            },
            .decorator => return self.scanSuperOrThis(hir_mod.decoratorOf(self.hir, node).expression),
            .block_stmt => {
                for (hir_mod.blockStmts(self.hir, node)) |stmt| {
                    if (self.scanSuperOrThis(stmt)) return true;
                }
                return false;
            },
            .var_decl, .let_decl, .const_decl => return self.scanSuperOrThis(hir_mod.varDeclOf(self.hir, node).init),
            .return_stmt => return self.scanSuperOrThis(hir_mod.returnOf(self.hir, node).value),
            .throw_stmt => return self.scanSuperOrThis(hir_mod.throwOf(self.hir, node).value),
            .if_stmt => {
                const i = hir_mod.ifOf(self.hir, node);
                return self.scanSuperOrThis(i.cond) or self.scanSuperOrThis(i.then_branch) or self.scanSuperOrThis(i.else_branch);
            },
            .while_stmt => {
                const w = hir_mod.whileOf(self.hir, node);
                return self.scanSuperOrThis(w.cond) or self.scanSuperOrThis(w.body);
            },
            .do_while_stmt => {
                const d = hir_mod.doWhileOf(self.hir, node);
                return self.scanSuperOrThis(d.body) or self.scanSuperOrThis(d.cond);
            },
            .for_stmt => {
                const f = hir_mod.forStmtOf(self.hir, node);
                return self.scanSuperOrThis(f.init) or self.scanSuperOrThis(f.cond) or self.scanSuperOrThis(f.update) or self.scanSuperOrThis(f.body);
            },
            .for_in_stmt, .for_of_stmt => {
                const f = hir_mod.forInOf(self.hir, node);
                return self.scanSuperOrThis(f.source) or self.scanSuperOrThis(f.body);
            },
            .try_stmt => {
                const t = hir_mod.tryOf(self.hir, node);
                return self.scanSuperOrThis(t.block) or self.scanSuperOrThis(t.catch_block) or self.scanSuperOrThis(t.finally_block);
            },
            .switch_stmt => {
                const s = hir_mod.switchOf(self.hir, node);
                if (self.scanSuperOrThis(s.discriminant)) return true;
                for (hir_mod.switchCases(self.hir, node)) |case| {
                    if (self.scanSuperOrThis(case)) return true;
                }
                return false;
            },
            .switch_case => {
                const sc = hir_mod.switchCaseOf(self.hir, node);
                if (self.scanSuperOrThis(sc.value)) return true;
                for (hir_mod.switchCaseStmts(self.hir, node)) |stmt| {
                    if (self.scanSuperOrThis(stmt)) return true;
                }
                return false;
            },
            .conditional => {
                const tn = hir_mod.conditionalOf(self.hir, node);
                return self.scanSuperOrThis(tn.cond) or self.scanSuperOrThis(tn.then_branch) or self.scanSuperOrThis(tn.else_branch);
            },
            .call_expr, .new_expr => {
                const c = hir_mod.callOf(self.hir, node);
                if (self.scanSuperOrThis(c.callee)) return true;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    if (self.scanSuperOrThis(arg)) return true;
                }
                return false;
            },
            .member_access => {
                const m = hir_mod.memberOf(self.hir, node);
                return self.scanSuperOrThis(m.object);
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                return self.scanSuperOrThis(b.lhs) or self.scanSuperOrThis(b.rhs);
            },
            .unary_op => return self.scanSuperOrThis(hir_mod.unaryOf(self.hir, node).operand),
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                return self.scanSuperOrThis(a.target) or self.scanSuperOrThis(a.value);
            },
            .object_literal => {
                for (hir_mod.objectLiteralProps(self.hir, node)) |p| {
                    if (self.scanSuperOrThis(p)) return true;
                }
                return false;
            },
            .object_property => {
                const property = hir_mod.objectPropertyOf(self.hir, node);
                return (property.is_computed and self.scanSuperOrThis(property.key)) or
                    self.scanSuperOrThis(property.value);
            },
            .array_literal => {
                for (hir_mod.arrayLiteralElements(self.hir, node)) |elem| {
                    if (self.scanSuperOrThis(elem)) return true;
                }
                return false;
            },
            .spread => return self.scanSuperOrThis(hir_mod.spreadOf(self.hir, node).expression),
            else => return false,
        }
    }

    /// Emits TS17009 when a `this` reference appears inside a
    /// derived class constructor BEFORE the first `super(...)` call
    /// completes. Lexical approximation: this.start < first
    /// super-call.end. Skips classes that `extends null` and
    /// constructors with no super call (TS2377 covers that case).
    fn checkThisBeforeSuperInConstructor(self: *Checker, this_node: NodeId) CheckError!void {
        const ctor = self.enclosingConstructorNode(this_node);
        if (ctor == hir_mod.none_node_id) return;
        const class_node = self.enclosingClassNode(ctor);
        if (class_node == hir_mod.none_node_id) return;
        const c = hir_mod.classOf(self.hir, class_node);
        if (c.extends == hir_mod.none_node_id) return;
        if (self.hir.kindOf(c.extends) == .literal_null) return;
        const fn_p = hir_mod.fnDeclOf(self.hir, ctor);
        if (fn_p.body == hir_mod.none_node_id) return;
        const super_end = self.firstSuperCallEndPos(fn_p.body) orelse return;
        const this_start = self.hir.spanOf(this_node).start;
        if (this_start < super_end) {
            try self.report(this_node, TsCodes.this_before_super_call, "'super' must be called before accessing 'this' in the constructor of a derived class.");
        }
    }

    fn checkSuperPropertyBeforeSuperInConstructor(self: *Checker, super_node: NodeId) CheckError!bool {
        const ctor = self.enclosingConstructorNode(super_node);
        if (ctor == hir_mod.none_node_id) return false;
        const class_node = self.enclosingClassNode(ctor);
        if (class_node == hir_mod.none_node_id) return false;
        const c = hir_mod.classOf(self.hir, class_node);
        if (c.extends == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(c.extends) == .literal_null) return false;
        const fn_p = hir_mod.fnDeclOf(self.hir, ctor);
        if (fn_p.body == hir_mod.none_node_id) return false;
        const super_end = self.firstSuperCallEndPos(fn_p.body) orelse return false;
        if (self.hir.spanOf(super_node).start >= super_end) return false;
        try self.report(super_node, TsCodes.super_before_super_call, "'super' must be called before accessing a property of 'super' in the constructor of a derived class.");
        return true;
    }

    /// True when `super_callee` is a `super` identifier directly
    /// inside a constructor of a class whose `extends` clause is the
    /// literal `null`. Mirrors `superCallBeforeThisAccessing4`.
    fn superCallInsideExtendsNullCtor(self: *Checker, super_callee: NodeId) bool {
        const ctor = self.enclosingConstructorNode(super_callee);
        if (ctor == hir_mod.none_node_id) return false;
        const class_node = self.enclosingClassNode(ctor);
        if (class_node == hir_mod.none_node_id) return false;
        const c = hir_mod.classOf(self.hir, class_node);
        if (c.extends == hir_mod.none_node_id) return false;
        return self.hir.kindOf(c.extends) == .literal_null;
    }

    /// True when `node` (a `super(ÃÂ¢ÃÂÃÂ¦)` callee identifier) lives inside a
    /// class body but NOT directly inside the constructor itself.
    /// Captures methods, getters/setters, field initializers, static
    /// blocks, AND nested functions inside the constructor. Returns
    /// false when `node` is outside any class lexically, in which case
    /// the regular TS2335 diagnostic still applies. Mirrors tsc's
    /// choice of TS2337 over TS2335 for these positions
    /// (`errorSuperCalls.ts` rows 9, 14, 18, 22, 26, 30, 34, 38, 58,
    /// 62, 67, 71).
    fn superCallOutsideConstructorInClassMember(self: *Checker, node: NodeId) bool {
        var prev: NodeId = node;
        var cur = self.hir.parentOf(node);
        var crossed_non_ctor_fn = false;
        var crossed_ctor = false;
        while (cur != hir_mod.none_node_id) : ({
            prev = cur;
            cur = self.hir.parentOf(cur);
        }) {
            const k = self.hir.kindOf(cur);
            switch (k) {
                .fn_decl, .fn_expr => {
                    const f = hir_mod.fnDeclOf(self.hir, cur);
                    if (f.flags.is_constructor) {
                        crossed_ctor = true;
                    } else {
                        crossed_non_ctor_fn = true;
                    }
                },
                .arrow_fn => {},
                .class_decl, .class_expr => {
                    if (crossed_ctor and !crossed_non_ctor_fn) return false;
                    if (crossed_non_ctor_fn) return true;
                    // No function frame between super and the class:
                    // we're in a field initializer (`p = super();`) or
                    // a static `{ ÃÂ¢ÃÂÃÂ¦ }` block. tsc treats both as TS2337.
                    if (self.hir.kindOf(prev) == .object_property) return true;
                    if (self.hir.kindOf(prev) == .block_stmt) {
                        for (hir_mod.classMembers(self.hir, cur)) |m| {
                            if (m == prev) return true;
                        }
                    }
                    return false;
                },
                else => {},
            }
        }
        return false;
    }

    fn computedNameReferencesTypeParams(self: *Checker, node: NodeId, type_params: []const NodeId) bool {
        return self.computedNameTypeParamReferenceNode(node, type_params) != hir_mod.none_node_id;
    }

    /// Returns the type-ref node (typically the `T` identifier) that
    /// references one of `type_params`, or `none_node_id` if none. tsc
    /// anchors TS2467 at the specific `T` identifier inside the computed
    /// key, not at the enclosing call/member expression ÃÂ¢ÃÂÃÂ matches
    /// `computedPropertyNames32_ES6.ts(6,10)` baseline.
    fn computedNameTypeParamReferenceNode(self: *Checker, node: NodeId, type_params: []const NodeId) NodeId {
        if (node == hir_mod.none_node_id or type_params.len == 0) return hir_mod.none_node_id;
        switch (self.hir.kindOf(node)) {
            .type_ref => {
                if (self.typeParamNameMatches(hir_mod.typeRefOf(self.hir, node).name, type_params)) return node;
                return hir_mod.none_node_id;
            },
            .call_expr, .new_expr => {
                for (hir_mod.callTypeArgs(self.hir, node)) |ta| {
                    const inner = self.computedNameTypeParamReferenceNode(ta, type_params);
                    if (inner != hir_mod.none_node_id) return inner;
                }
                const c = hir_mod.callOf(self.hir, node);
                const inner = self.computedNameTypeParamReferenceNode(c.callee, type_params);
                if (inner != hir_mod.none_node_id) return inner;
                for (hir_mod.callArgs(self.hir, node)) |arg| {
                    const arg_inner = self.computedNameTypeParamReferenceNode(arg, type_params);
                    if (arg_inner != hir_mod.none_node_id) return arg_inner;
                }
                return hir_mod.none_node_id;
            },
            .member_access => return self.computedNameTypeParamReferenceNode(hir_mod.memberOf(self.hir, node).object, type_params),
            .element_access => {
                const e = hir_mod.elementOf(self.hir, node);
                const inner = self.computedNameTypeParamReferenceNode(e.object, type_params);
                if (inner != hir_mod.none_node_id) return inner;
                return self.computedNameTypeParamReferenceNode(e.index, type_params);
            },
            .binary_op => {
                const b = hir_mod.binopOf(self.hir, node);
                const inner = self.computedNameTypeParamReferenceNode(b.lhs, type_params);
                if (inner != hir_mod.none_node_id) return inner;
                return self.computedNameTypeParamReferenceNode(b.rhs, type_params);
            },
            .logical_op => {
                const l = hir_mod.logicalOf(self.hir, node);
                const inner = self.computedNameTypeParamReferenceNode(l.lhs, type_params);
                if (inner != hir_mod.none_node_id) return inner;
                return self.computedNameTypeParamReferenceNode(l.rhs, type_params);
            },
            .conditional => {
                const c = hir_mod.conditionalOf(self.hir, node);
                const inner = self.computedNameTypeParamReferenceNode(c.cond, type_params);
                if (inner != hir_mod.none_node_id) return inner;
                const then_inner = self.computedNameTypeParamReferenceNode(c.then_branch, type_params);
                if (then_inner != hir_mod.none_node_id) return then_inner;
                return self.computedNameTypeParamReferenceNode(c.else_branch, type_params);
            },
            .unary_op => return self.computedNameTypeParamReferenceNode(hir_mod.unaryOf(self.hir, node).operand, type_params),
            .assignment => {
                const a = hir_mod.assignmentOf(self.hir, node);
                const inner = self.computedNameTypeParamReferenceNode(a.target, type_params);
                if (inner != hir_mod.none_node_id) return inner;
                return self.computedNameTypeParamReferenceNode(a.value, type_params);
            },
            else => return hir_mod.none_node_id,
        }
    }

    fn currentThisType(self: *Checker) ?TypeId {
        const this_id = self.string_interner.intern("this") catch return null;
        return self.lookupNarrow(this_id);
    }

    fn objectLiteralLikelyHasContextualTarget(self: *Checker, node: NodeId) bool {
        var cur = node;
        while (true) {
            const parent = self.hir.parentOf(cur);
            if (parent == hir_mod.none_node_id) return false;
            switch (self.hir.kindOf(parent)) {
                .var_decl, .let_decl, .const_decl => {
                    const v = hir_mod.varDeclOf(self.hir, parent);
                    return v.init == cur and v.type_annotation != hir_mod.none_node_id;
                },
                .assignment => {
                    const a = hir_mod.assignmentOf(self.hir, parent);
                    return a.value == cur;
                },
                .call_expr, .new_expr => {
                    const c = hir_mod.callOf(self.hir, parent);
                    for (hir_mod.callArgs(self.hir, parent)) |arg| {
                        if (arg == cur) return true;
                    }
                    return c.callee == cur;
                },
                .object_property => {
                    cur = parent;
                    continue;
                },
                .object_literal => {
                    cur = parent;
                    continue;
                },
                .as_expr, .satisfies_expr => return true,
                else => return false,
            }
        }
    }

    /// Phase 4 #11 ÃÂ¢ÃÂÃÂ when an object literal is the return value of a
    /// function with a declared return type, return that declared
    /// return type. Used as the contextual target for
    /// `checkObjectLiteralMethodBodiesWithThis` so a `ThisType<T>`
    /// marker on the return-type annotation flips `this` inside the
    /// returned object literal's methods (Vue-style pattern with
    /// explicit return type instead of explicit param/var annotation).
    ///
    /// Returns `null` when the literal isn't a return value, the
    /// enclosing function lacks a declared return type, or the
    /// declared return type fails to lower.
    fn enclosingReturnTargetType(self: *Checker, node: NodeId) ?TypeId {
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(parent) != .return_stmt) return null;
        var cur = self.hir.parentOf(parent);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn) {
                const f = hir_mod.fnDeclOf(self.hir, cur);
                if (f.return_type == hir_mod.none_node_id) return null;
                return self.lowerReturnTypeAnnotationWithCircularityGuard(cur, f.return_type) catch null;
            }
        }
        return null;
    }

    fn objectLiteralEnclosingReturnTargetType(self: *Checker, node: NodeId) ?TypeId {
        return self.enclosingReturnTargetType(node);
    }

    fn lowerReturnTypeAnnotationWithCircularityGuard(self: *Checker, fn_node: NodeId, type_node: NodeId) CheckError!TypeId {
        if (fn_node == hir_mod.none_node_id or type_node == hir_mod.none_node_id) {
            return try self.lowererLowerWithTypeParams(type_node);
        }
        if (self.return_annotation_in_progress.contains(fn_node)) {
            _ = self.reportReturnTypeAnnotationCircularIfActive(fn_node);
            return types.Primitive.any;
        }
        try self.return_annotation_in_progress.put(self.gpa, fn_node, type_node);
        defer _ = self.return_annotation_in_progress.remove(fn_node);
        return try self.lowererLowerWithTypeParams(type_node);
    }

    fn reportReturnTypeAnnotationCircularIfActive(self: *Checker, fn_node: NodeId) bool {
        const type_node = self.return_annotation_in_progress.get(fn_node) orelse return false;
        if (self.hir.kindOf(type_node) == .typeof_type) return false;
        if (self.hir.kindOf(type_node) == .type_ref) {
            if (self.directTypeRefNamesClassOrInterface(type_node)) return false;
            const ref = hir_mod.typeRefOf(self.hir, type_node);
            const annotation_text = std.mem.trim(u8, self.nodeSourceTextOrEmpty(type_node), " \t\r\n");
            var annotation_name_end: usize = 0;
            while (annotation_name_end < annotation_text.len and asciiIdentifierContinue(annotation_text[annotation_name_end])) {
                annotation_name_end += 1;
            }
            var annotation_tail = annotation_name_end;
            while (annotation_tail < annotation_text.len and std.ascii.isWhitespace(annotation_text[annotation_tail])) {
                annotation_tail += 1;
            }
            const has_direct_type_args = annotation_tail < annotation_text.len and annotation_text[annotation_tail] == '<';
            if (!has_direct_type_args and
                self.findTypeAliasDeclInScope(type_node, ref.name) == null)
            {
                return false;
            }
            if (self.class_instance_types.contains(ref.name) or self.classDeclInAnyVirtualSection(ref.name) != null) return false;
            if (ref.args_len == 0 and self.findTypeAliasDeclInScope(type_node, ref.name) == null) return false;
            if (ref.qualifier_len == 0) {
                if (self.findVisibleNamedTypeDecl(type_node, ref.name)) |decl| {
                    const kind = self.hir.kindOf(decl);
                    if (kind == .class_decl or kind == .class_expr or kind == .interface_decl) return false;
                }
            }
        }
        self.reportReturnTypeAnnotationCircularOnce(type_node) catch {};
        return true;
    }

    fn directTypeRefNamesClassOrInterface(self: *Checker, type_node: NodeId) bool {
        const raw = std.mem.trim(u8, self.nodeSourceTextOrEmpty(type_node), " \t\r\n");
        var name_end: usize = 0;
        while (name_end < raw.len and asciiIdentifierContinue(raw[name_end])) name_end += 1;
        if (name_end == 0) return false;
        const raw_name = raw[0..name_end];
        var node: NodeId = 0;
        while (node < self.hir.nodeCount()) : (node += 1) {
            const kind = self.hir.kindOf(node);
            if (kind != .class_decl and kind != .class_expr and kind != .interface_decl) continue;
            const decl_name = self.declarationName(node) orelse continue;
            if (std.mem.eql(u8, self.string_interner.get(decl_name), raw_name)) return true;
        }
        return false;
    }

    fn reportReturnTypeAnnotationCircularOnce(self: *Checker, type_node: NodeId) CheckError!void {
        if (type_node == hir_mod.none_node_id) return;
        if (self.diagnosticExists(type_node, TsCodes.return_type_annotation_circular)) return;
        try self.report(
            type_node,
            TsCodes.return_type_annotation_circular,
            "Return type annotation circularly references itself.",
        );
    }

    fn memberAccessIsContextualObjectLiteralThis(self: *Checker, object_node: NodeId) bool {
        if (object_node == hir_mod.none_node_id) return false;
        switch (self.hir.kindOf(object_node)) {
            .this_expr => {},
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, object_node);
                if (!std.mem.eql(u8, self.string_interner.get(id.name), "this")) return false;
            },
            else => return false,
        }
        var cur = self.hir.parentOf(object_node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .object_literal => return true,
                .fn_decl, .fn_expr, .arrow_fn, .block_stmt, .object_property, .member_access, .binary_op, .assignment, .logical_op, .if_stmt, .return_stmt => {},
                else => {},
            }
        }
        return false;
    }

    fn checkThisExpression(self: *Checker, node: NodeId) CheckError!TypeId {
        if (self.nodeIsThisParameterName(node)) return types.Primitive.any;
        if (self.enclosingThisHostHasThisParam(node)) return types.Primitive.any;
        if (self.thisInsideDecoratorInitializerCallback(node)) return types.Primitive.any;
        if (self.nodeInsideAmbientVarInitializer(node)) return types.Primitive.any;
        const this_rebound_plain_function = self.thisInsideNonArrowPlainFunction(node);
        if (self.sourceHasStrictFalseDirective() and this_rebound_plain_function and
            !self.enclosingThisHostHasExplicitThisParam(node))
        {
            return types.Primitive.any;
        }
        if (self.thisInsideCheckJsConstructorFunction(node)) return types.Primitive.any;
        if (self.checkJsPrototypeAssignmentThisType(node)) |this_t| return this_t;
        if (self.thisInsideCheckJsPrototypeAssignmentFunction(node)) return types.Primitive.any;
        if (self.thisInsideCheckJsFunctionWithThisTag(node)) return types.Primitive.any;
        if (self.thisInsideCheckJsCallbackWithThis(node)) return types.Primitive.any;
        if (self.thisInsideEnumInitializer(node)) {
            try self.report(node, TsCodes.this_in_current_location, "'this' cannot be referenced in current location.");
            return types.Primitive.any;
        }
        // TS2465 ÃÂ¢ÃÂÃÂ see the matching branch in the identifier-form
        // `this` resolver above. Mirrors `computedPropertyNames21_ES5`.
        if (self.in_computed_property_name) {
            self.report(node, TsCodes.this_in_computed_property_name, "'this' cannot be referenced in a computed property name.") catch {};
            return self.currentThisType() orelse types.Primitive.any;
        }
        if (self.thisInsideStaticDecoratedClassPropertyInitializer(node)) {
            try self.report(node, TsCodes.this_in_static_property_initializer_decorated_class, "Cannot use 'this' in a static property initializer of a decorated class.");
            return types.Primitive.any;
        }
        if (self.nodeHasAncestorKind(node, .decorator)) return types.Primitive.any;
        if (self.thisIsGlobalScriptThis(node)) return try self.bareGlobalThisType();
        if (self.thisInsideTopLevelContextualArrowWithThis(node)) return try self.bareGlobalThisType();
        if (self.thisIsUndefinedInExternalModuleArrow(node)) {
            return types.Primitive.undefined_t;
        }
        if (self.assignedFunctionExpressionEffectiveThis(node)) |this_t| return this_t;
        if (!this_rebound_plain_function or
            self.enclosingThisHostHasExplicitThisParam(node) or
            (this_rebound_plain_function and self.thisInsideObjectLiteralMethod(node) and self.currentThisType() != null))
        {
            if (self.currentThisType()) |this_t| return this_t;
        }
        if (!self.sourceHasStrictFalseDirective() and
            !self.thisInsideObjectLiteralMethod(node) and
            !self.thisInsideClassConstructorParameter(node) and
            !self.thisIsPrivateMemberReceiverInsideClass(node))
        {
            try self.reportThisImplicitlyAny(node);
        }
        return types.Primitive.any;
    }

    fn thisIsUndefinedInExternalModuleArrow(self: *Checker, node: NodeId) bool {
        return self.nodeIsThisReference(node) and
            self.thisInsideTopLevelArrow(node) and
            self.sourceFileSectionIsModule(node);
    }

    fn reportThisImplicitlyAny(self: *Checker, node: NodeId) CheckError!void {
        var related: []const RelatedInfo = &.{};
        if (self.thisShadowingContainerWithOuterThis(node)) |container| {
            related = try self.diag_arena.allocator().dupe(RelatedInfo, &.{.{
                .node = container,
                .code = TsCodes.outer_this_shadowed,
                .message = "An outer value of 'this' is shadowed by this container.",
            }});
        }
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.this_implicitly_any,
            .message = "'this' implicitly has type 'any' because it does not have a type annotation.",
            .related = related,
        });
    }

    fn thisShadowingContainerWithOuterThis(self: *Checker, node: NodeId) ?NodeId {
        const container = self.nearestPlainNonArrowFunction(node) orelse return null;
        if (self.functionContainerHasOuterThis(container)) return container;
        return null;
    }

    fn nearestPlainNonArrowFunction(self: *Checker, node: NodeId) ?NodeId {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) continue;
            if (k != .fn_decl and k != .fn_expr) continue;
            const f = hir_mod.fnDeclOf(self.hir, cur);
            if (f.flags.is_method or f.flags.is_constructor) return null;
            return cur;
        }
        return null;
    }

    fn functionContainerHasOuterThis(self: *Checker, container: NodeId) bool {
        var cur = self.hir.parentOf(container);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .arrow_fn => continue,
                .fn_decl, .fn_expr => {
                    const f = hir_mod.fnDeclOf(self.hir, cur);
                    return f.flags.is_method or f.flags.is_constructor;
                },
                .class_decl, .class_expr => return true,
                .object_property => {
                    const op = hir_mod.objectPropertyOf(self.hir, cur);
                    if (op.is_method or self.memberSourceLooksMethod(cur)) return true;
                },
                else => {},
            }
        }
        return false;
    }

    fn thisIsGlobalScriptThis(self: *Checker, node: NodeId) bool {
        if (self.sourceHasStrictFalseDirective()) return false;
        if (self.rootHasTopLevelExternalModuleMarker(node)) return false;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .fn_decl, .fn_expr, .class_decl, .class_expr, .object_literal => return false,
                .arrow_fn => {},
                else => {},
            }
        }
        return true;
    }

    fn thisInsideTopLevelContextualArrowWithThis(self: *Checker, node: NodeId) bool {
        if (!self.sourceHasStrictFalseDirective()) return false;
        if (!self.thisInsideTopLevelArrow(node)) return false;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) {
                const parent = self.hir.parentOf(cur);
                if (parent != hir_mod.none_node_id and self.hir.kindOf(parent) == .assignment) {
                    const a = hir_mod.assignmentOf(self.hir, parent);
                    if (a.value == cur and a.target != hir_mod.none_node_id) {
                        var target_t = self.hir.typeOf(a.target);
                        if (target_t == types.Primitive.none) {
                            target_t = self.checkExpression(a.target) catch types.Primitive.none;
                        }
                        const sig = self.firstSignatureType(target_t) orelse return false;
                        return self.signatureThisParam(sig) != null;
                    }
                }
                return false;
            }
            if (k == .fn_decl or k == .fn_expr or k == .class_decl or k == .class_expr or k == .object_literal) return false;
        }
        return false;
    }

    fn assignedFunctionExpressionEffectiveThis(self: *Checker, node: NodeId) ?TypeId {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) return null;
            if (k != .fn_decl and k != .fn_expr) continue;
            if (self.functionDeclHasExplicitThisParam(cur)) return null;
            const parent = self.hir.parentOf(cur);
            if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .assignment) return null;
            const a = hir_mod.assignmentOf(self.hir, parent);
            if (a.value != cur) return null;
            var target_t = self.hir.typeOf(a.target);
            if (target_t == types.Primitive.none) {
                target_t = self.checkExpression(a.target) catch types.Primitive.none;
            }
            return self.memberAccessEffectiveThisType(a.target, target_t) catch null;
        }
        return null;
    }

    fn functionDeclHasExplicitThisParam(self: *Checker, fn_node: NodeId) bool {
        if (fn_node == hir_mod.none_node_id) return false;
        const k = self.hir.kindOf(fn_node);
        if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) return false;
        for (hir_mod.fnParams(self.hir, fn_node)) |param| {
            if (self.isThisParameter(param)) return true;
        }
        return false;
    }

    fn memberAccessObjectIsGlobalThisThis(self: *Checker, object_node: NodeId) bool {
        switch (self.hir.kindOf(object_node)) {
            .this_expr => return self.thisIsGlobalScriptThis(object_node),
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, object_node);
                const raw = self.string_interner.get(id.name);
                return (std.mem.eql(u8, raw, "this") and self.thisIsGlobalScriptThis(object_node)) or
                    std.mem.eql(u8, raw, "globalThis");
            },
            else => return false,
        }
    }

    fn reportNonStrictGlobalArrowThisNameAccess(
        self: *Checker,
        node: NodeId,
        object_node: NodeId,
        prop_name: hir_mod.StringId,
    ) CheckError!bool {
        if (!self.sourceHasStrictFalseDirective()) return false;
        if (!std.mem.eql(u8, self.string_interner.get(prop_name), "name")) return false;
        switch (self.hir.kindOf(object_node)) {
            .this_expr => {},
            .identifier => {
                const id = hir_mod.identifierOf(self.hir, object_node);
                if (!std.mem.eql(u8, self.string_interner.get(id.name), "this")) return false;
            },
            else => return false,
        }
        if (!self.thisInsideTopLevelArrow(object_node)) return false;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Property '{s}' does not exist on type 'typeof globalThis'.",
            .{self.string_interner.get(prop_name)},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = self.memberAccessNamePos(node),
            .code = TsCodes.property_does_not_exist,
            .message = msg,
        });
        return true;
    }

    fn thisInsideTopLevelArrow(self: *Checker, node: NodeId) bool {
        var saw_arrow = false;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .arrow_fn => saw_arrow = true,
                .fn_decl, .fn_expr, .class_decl, .class_expr, .object_literal => return false,
                else => {},
            }
        }
        return saw_arrow;
    }

    fn reportGlobalThisNoIndexSignature(self: *Checker, node: NodeId) CheckError!void {
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = self.memberAccessNamePos(node),
            .code = TsCodes.global_this_no_index_signature,
            .message = "Element implicitly has an 'any' type because type 'typeof globalThis' has no index signature.",
        });
    }

    fn typeDisplayMentionsGlobalThis(self: *Checker, t: TypeId) CheckError!bool {
        if (try self.allocSimpleTypeName(t)) |name| {
            return std.mem.indexOf(u8, name, "typeof globalThis") != null;
        }
        return false;
    }

    fn globalThisHasProperty(self: *Checker, anchor: NodeId, name: hir_mod.StringId) bool {
        const raw = self.string_interner.get(name);
        if (std.mem.eql(u8, raw, "globalThis") or
            std.mem.eql(u8, raw, "Float64Array") or
            std.mem.eql(u8, raw, "Infinity") or
            std.mem.eql(u8, raw, "window"))
        {
            return true;
        }
        if (self.module) |module| {
            const quoted_module_name = raw.len >= 2 and
                ((raw[0] == '"' and raw[raw.len - 1] == '"') or
                    (raw[0] == '\'' and raw[raw.len - 1] == '\''));
            if (!quoted_module_name and module.root.namespaces.get(name) != null) return true;
            if (module.root.values.get(name)) |symbol| {
                for (symbol.decls.items) |decl| {
                    if (self.hir.kindOf(decl) == .namespace_decl and self.namespaceHasRuntimeValue(decl)) {
                        return true;
                    }
                }
            }
        }
        for (self.program_global_var_names) |program_name| {
            if (std.mem.eql(u8, program_name, raw)) return true;
        }
        return self.rootHasVarDeclarationNamed(anchor, name) or
            self.rootHasFunctionDeclarationNamed(anchor, name);
    }

    fn checkJsGlobalPropertyAssignmentDefinesMember(self: *Checker, node: NodeId, object_node: NodeId) bool {
        return (self.check_js_enabled or self.sourceHasCheckJsDirective()) and
            self.virtualSectionIsJsLike(node) and
            self.isInAssignmentTargetChain(node) and
            self.memberAccessObjectIsGlobalThisThis(object_node);
    }

    fn globalWindowReceiverIncludesGlobalProperties(self: *Checker, object_node: NodeId) bool {
        if (object_node == hir_mod.none_node_id or self.hir.kindOf(object_node) != .identifier) return false;
        const raw = self.string_interner.get(hir_mod.identifierOf(self.hir, object_node).name);
        return std.mem.eql(u8, raw, "window") or std.mem.eql(u8, raw, "self");
    }

    fn reportGlobalThisMissingProperty(self: *Checker, node: NodeId, name: hir_mod.StringId, target: []const u8) CheckError!void {
        const raw = self.string_interner.get(name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Property '{s}' does not exist on type '{s}'.",
            .{ raw, target },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = self.memberAccessNamePos(node),
            .code = TsCodes.property_does_not_exist,
            .message = msg,
        });
    }

    fn globalThisTypeIndexKeyId(self: *Checker, node: NodeId) CheckError!hir_mod.StringId {
        if (self.source) |source| {
            const span = self.hir.spanOf(node);
            if (span.start < span.end and span.end <= source.len) {
                const token = std.mem.trim(u8, source[span.start..span.end], " \t\r\n");
                if (token.len >= 2 and
                    ((token[0] == '"' and token[token.len - 1] == '"') or
                        (token[0] == '\'' and token[token.len - 1] == '\'')))
                {
                    var buf: std.ArrayListUnmanaged(u8) = .empty;
                    defer buf.deinit(self.gpa);
                    try self.appendCookedStringText(token[1 .. token.len - 1], &buf);
                    return self.string_interner.intern(buf.items) catch return error.OutOfMemory;
                }
            }
        }
        return self.literalStringCookedId(node);
    }

    fn reportGlobalThisMissingOrReadonlyMember(self: *Checker, node: NodeId, object_node: NodeId, obj_t: TypeId, name: hir_mod.StringId) CheckError!bool {
        _ = obj_t;
        const object_is_global_this =
            self.hir.kindOf(object_node) == .identifier and
            std.mem.eql(u8, self.string_interner.get(hir_mod.identifierOf(self.hir, object_node).name), "globalThis");
        const object_is_global_this_receiver = object_is_global_this or self.memberAccessObjectIsGlobalThisThis(object_node);
        const annotation_mentions_global = self.identifierAnnotationMentionsGlobalThis(object_node);
        if (self.globalWindowReceiverIncludesGlobalProperties(object_node) and self.globalThisHasProperty(node, name)) return true;
        if (!object_is_global_this_receiver and !annotation_mentions_global) return false;
        if (object_is_global_this and
            std.mem.eql(u8, self.string_interner.get(name), "globalThis") and
            self.isInAssignmentTargetChain(node))
        {
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .pos = self.memberAccessNamePos(node),
                .code = TsCodes.readonly_property,
                .message = "Cannot assign to 'globalThis' because it is a read-only property.",
            });
            return true;
        }
        if (self.checkJsGlobalPropertyAssignmentDefinesMember(node, object_node)) return true;
        if (self.globalThisHasProperty(node, name)) return false;
        if (object_is_global_this_receiver and
            !self.sourceHasBlockScopedGlobalDeclarationText(name) and
            self.strict_flags.no_implicit_any)
        {
            try self.reportGlobalThisNoIndexSignature(node);
            return true;
        }
        if (object_is_global_this_receiver and !self.sourceHasBlockScopedGlobalDeclarationText(name)) return false;
        if (object_is_global_this and !self.sourceHasBlockScopedGlobalDeclarationText(name)) return false;
        const target = if (annotation_mentions_global)
            "Window & typeof globalThis"
        else
            "typeof globalThis";
        try self.reportGlobalThisMissingProperty(node, name, target);
        return true;
    }

    fn reportGlobalThisMissingElementMember(self: *Checker, node: NodeId, object_node: NodeId, obj_t: TypeId, name: hir_mod.StringId) CheckError!bool {
        const object_is_global_this =
            self.hir.kindOf(object_node) == .identifier and
            std.mem.eql(u8, self.string_interner.get(hir_mod.identifierOf(self.hir, object_node).name), "globalThis");
        const object_is_global_this_receiver = object_is_global_this or self.memberAccessObjectIsGlobalThisThis(object_node);
        _ = obj_t;
        const annotation_mentions_global = self.identifierAnnotationMentionsGlobalThis(object_node);
        if (self.globalWindowReceiverIncludesGlobalProperties(object_node) and self.globalThisHasProperty(node, name)) return true;
        if (!object_is_global_this_receiver and !annotation_mentions_global) return false;
        if (self.checkJsGlobalPropertyAssignmentDefinesMember(node, object_node)) return true;
        if (self.globalThisHasProperty(node, name)) return false;
        if (object_is_global_this_receiver and !self.sourceHasBlockScopedGlobalDeclarationText(name)) return false;
        if (object_is_global_this and !self.sourceHasBlockScopedGlobalDeclarationText(name)) return false;
        const target = if (annotation_mentions_global)
            "Window & typeof globalThis"
        else
            "typeof globalThis";
        try self.reportGlobalThisMissingProperty(node, name, target);
        return true;
    }

    fn identifierAnnotationMentionsGlobalThis(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return false;
        const text = self.visibleAnnotatedIdentifierTypeText(node) orelse return false;
        return std.mem.indexOf(u8, text, "typeof globalThis") != null;
    }

    fn thisInsideEnumInitializer(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) continue;
            if (k == .fn_decl or k == .fn_expr or k == .class_decl or k == .class_expr) return false;
            if (k == .enum_decl) return true;
        }
        return false;
    }

    /// True when `node` (a `this` reference) appears lexically inside
    /// the initializer of a `static` class field, with no intervening
    /// non-arrow function frame (which would re-bind `this`). Arrow
    /// functions are transparent. Method bodies, getters/setters, and
    /// static blocks are NOT static property initializers, so a
    /// non-arrow function/method frame stops the search. Mirrors
    /// upstream `checkThisExpression` reporting TS2334 only for the
    /// initializer expression of a static `PropertyDeclaration`.
    fn thisInsideStaticPropertyInitializer(self: *Checker, node: NodeId) bool {
        var prev = node;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : ({
            prev = cur;
            cur = self.hir.parentOf(cur);
        }) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) continue;
            if (k == .fn_decl or k == .fn_expr) return false;
            if (k == .object_property) {
                const parent = self.hir.parentOf(cur);
                if (parent == hir_mod.none_node_id) return false;
                const pk = self.hir.kindOf(parent);
                if (pk != .class_decl and pk != .class_expr) return false;
                const op = hir_mod.objectPropertyOf(self.hir, cur);
                // Must be a static data field, and `node` must sit in
                // the initializer value, not the (computed) key.
                if (!op.is_static or op.is_method) return false;
                if (op.value == hir_mod.none_node_id) return false;
                return prev == op.value or self.nodeIsAncestorOf(op.value, node);
            }
            if (k == .class_decl or k == .class_expr) return false;
        }
        return false;
    }

    fn thisInsideStaticDecoratedClassPropertyInitializer(self: *Checker, node: NodeId) bool {
        if (!self.sourceUsesLegacyDecorators()) return false;
        var prev = node;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : ({
            prev = cur;
            cur = self.hir.parentOf(cur);
        }) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) continue;
            if (k == .fn_decl or k == .fn_expr) return false;
            if (k == .object_property) {
                const parent = self.hir.parentOf(cur);
                if (parent == hir_mod.none_node_id) return false;
                const pk = self.hir.kindOf(parent);
                if (pk != .class_decl and pk != .class_expr) return false;
                const op = hir_mod.objectPropertyOf(self.hir, cur);
                if (!op.is_static or op.is_method) return false;
                if (op.value == hir_mod.none_node_id) return false;
                if (!(prev == op.value or self.nodeIsAncestorOf(op.value, node))) return false;
                return self.classHasDecorator(parent);
            }
            if (k == .class_decl or k == .class_expr) return false;
        }
        return false;
    }

    fn classHasDecorator(self: *Checker, class_node: NodeId) bool {
        const parent = self.hir.parentOf(class_node);
        if (parent == hir_mod.none_node_id) return self.classHasLeadingSourceDecorator(class_node);
        const stmts = switch (self.hir.kindOf(parent)) {
            .block_stmt => hir_mod.blockStmts(self.hir, parent),
            else => return self.classHasLeadingSourceDecorator(class_node),
        };
        for (stmts, 0..) |stmt, i| {
            const target = self.unwrapExportDecl(stmt);
            if (target != class_node) continue;
            if (self.stmtHasExportDecorator(stmt)) return true;
            var j = i;
            while (j > 0) {
                j -= 1;
                const prev = stmts[j];
                if (self.hir.kindOf(prev) == .decorator) return true;
                if (self.stmtHasExportDecorator(prev)) return true;
                break;
            }
            return self.classHasLeadingSourceDecorator(class_node);
        }
        return self.classHasLeadingSourceDecorator(class_node);
    }

    fn classHasLeadingSourceDecorator(self: *Checker, class_node: NodeId) bool {
        const src = self.source orelse return false;
        const span = self.hir.spanOf(class_node);
        if (span.start == 0 or span.start > src.len) return false;
        var end = span.start;
        while (end > 0 and std.ascii.isWhitespace(src[end - 1])) : (end -= 1) {}
        if (end == 0) return false;
        var start = end;
        while (start > 0 and src[start - 1] != '\n' and src[start - 1] != '\r') : (start -= 1) {}
        while (start < end and std.ascii.isWhitespace(src[start])) : (start += 1) {}
        return start < end and src[start] == '@';
    }

    fn stmtHasExportDecorator(self: *Checker, stmt: NodeId) bool {
        if (stmt == hir_mod.none_node_id or self.hir.kindOf(stmt) != .export_decl) return false;
        const ex = hir_mod.exportOf(self.hir, stmt);
        return ex.decl != hir_mod.none_node_id and self.hir.kindOf(ex.decl) == .decorator;
    }

    fn nodeInsideAmbientVarInitializer(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const kind = self.hir.kindOf(cur);
            if (kind != .var_decl and kind != .let_decl and kind != .const_decl) continue;
            const v = hir_mod.varDeclOf(self.hir, cur);
            return v.is_ambient and v.init != hir_mod.none_node_id;
        }
        return false;
    }

    /// True when `node` is lexically inside a `namespace M { ... }`
    /// (or `module M { ... }`) body without any intervening
    /// function-like or class frame. Used by TS2331 / `this` checks
    /// to mirror upstream `isInsideStaticOrModule`.
    fn thisDirectlyInsideNamespaceBody(self: *Checker, node: NodeId) bool {
        const inside_decorator = self.nodeHasAncestorKind(node, .decorator);
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr or k == .arrow_fn or
                ((!inside_decorator) and (k == .class_decl or k == .class_expr))) return false;
            if (k == .namespace_decl or k == .module_decl) return true;
        }
        return false;
    }

    fn nodeIsThisParameterName(self: *Checker, node: NodeId) bool {
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .parameter) return false;
        const p = hir_mod.parameterOf(self.hir, parent);
        return p.name == node and self.isThisParameter(parent);
    }

    fn thisInsideDecoratorInitializerCallback(self: *Checker, node: NodeId) bool {
        if (self.source) |src| {
            const node_start: usize = @intCast(self.hir.spanOf(node).start);
            const prefix_start = if (node_start > 240) node_start - 240 else 0;
            const prefix = src[prefix_start..node_start];
            if (std.mem.lastIndexOf(u8, prefix, "addInitializer")) |idx| {
                const tail = prefix[idx + "addInitializer".len ..];
                if (std.mem.indexOfScalar(u8, tail, '(') != null and
                    std.mem.indexOf(u8, tail, "function") != null and
                    std.mem.indexOfScalar(u8, tail, ';') == null)
                {
                    return true;
                }
            }
        }
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .fn_decl and k != .fn_expr) continue;
            const fn_span = self.hir.spanOf(cur);
            if (self.source) |src| {
                const fn_start: usize = @intCast(fn_span.start);
                const prefix_start = if (fn_start > 160) fn_start - 160 else 0;
                const prefix = src[prefix_start..fn_start];
                if (std.mem.lastIndexOf(u8, prefix, "addInitializer")) |idx| {
                    const tail = prefix[idx + "addInitializer".len ..];
                    if (std.mem.indexOfScalar(u8, tail, '(') != null and
                        std.mem.indexOfScalar(u8, tail, ';') == null)
                    {
                        return true;
                    }
                }
            }
            var p = self.hir.parentOf(cur);
            while (p != hir_mod.none_node_id) : (p = self.hir.parentOf(p)) {
                if (self.hir.kindOf(p) != .call_expr) continue;
                const call = hir_mod.callOf(self.hir, p);
                if (self.hir.kindOf(call.callee) != .member_access) continue;
                const member = hir_mod.memberOf(self.hir, call.callee);
                if (!std.mem.eql(u8, self.string_interner.get(member.name), "addInitializer")) continue;
                const call_span = self.hir.spanOf(p);
                if (call_span.start <= fn_span.start and fn_span.end <= call_span.end) return true;
            }
            return false;
        }
        return false;
    }

    fn thisInsideCheckJsConstructorFunction(self: *Checker, node: NodeId) bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        if (self.virtualSectionFilenameForNode(node)) |filename| {
            if (!self.pathIsJsLike(filename)) return false;
        }
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) return false;
            if (k != .fn_decl and k != .fn_expr) continue;
            if (self.virtualSectionFilenameForNode(cur)) |filename| {
                if (!self.pathIsJsLike(filename)) return false;
            }
            const f = hir_mod.fnDeclOf(self.hir, cur);
            if (f.flags.is_method or f.flags.is_constructor) return false;
            return self.fnLooksLikeCheckJsConstructor(cur);
        }
        return false;
    }

    fn thisInsideCheckJsPrototypeAssignmentFunction(self: *Checker, node: NodeId) bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        const src = self.source orelse return false;
        var fn_node = hir_mod.none_node_id;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) return false;
            if (k == .fn_expr or k == .fn_decl) {
                fn_node = cur;
                break;
            }
        }
        if (fn_node == hir_mod.none_node_id) return false;
        const fn_span = self.hir.spanOf(fn_node);
        cur = self.hir.parentOf(fn_node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .block_stmt) break;
            const sp = self.hir.spanOf(cur);
            if (sp.start >= fn_span.start or fn_span.start > src.len) continue;
            const prefix = src[sp.start..fn_span.start];
            if (std.mem.indexOf(u8, prefix, ".prototype.") != null) return true;
        }
        return false;
    }

    fn checkJsPrototypeAssignmentThisType(self: *Checker, node: NodeId) ?TypeId {
        if (!self.sourceHasCheckJsDirective()) return null;
        const owner = self.checkJsPrototypeAssignmentOwnerName(node) orelse blk: {
            if (!self.thisInsideCheckJsPrototypeAssignmentFunction(node)) return null;
            break :blk self.checkJsPrototypeOwnerNameBeforeNode(node) orelse return null;
        };
        const owner_str = self.string_interner.get(owner);
        if (std.mem.eql(u8, owner_str, "Event")) {
            return self.lowerBuiltinObjectType("Event") orelse types.Primitive.any;
        }
        if (self.localNameIsImportBinding(owner, node)) {
            const imported_t = (self.virtualImportTypeForLocal(owner, node) catch null) orelse return null;
            const instance_t = (self.constructReturnType(imported_t) catch null) orelse return null;
            return instance_t;
        }
        return (self.jsConstructorInstanceTypeForHeritage(node, owner) catch null) orelse null;
    }

    fn checkJsPrototypeAssignmentOwnerName(self: *Checker, node: NodeId) ?hir_mod.StringId {
        var fn_node = hir_mod.none_node_id;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) continue;
            if (k == .fn_decl or k == .fn_expr) {
                fn_node = cur;
                break;
            }
        }
        if (fn_node == hir_mod.none_node_id) return null;
        if (self.checkJsPrototypeObjectLiteralAssignmentOwnerNameForFunction(fn_node)) |owner| return owner;
        const parent = self.hir.parentOf(fn_node);
        if (parent != hir_mod.none_node_id and self.hir.kindOf(parent) == .assignment) {
            const assign = hir_mod.assignmentOf(self.hir, parent);
            if (assign.value == fn_node and assign.target != hir_mod.none_node_id and self.hir.kindOf(assign.target) == .member_access) {
                const target = hir_mod.memberOf(self.hir, assign.target);
                if (target.object != hir_mod.none_node_id and self.hir.kindOf(target.object) == .member_access) {
                    const proto = hir_mod.memberOf(self.hir, target.object);
                    if (std.mem.eql(u8, self.string_interner.get(proto.name), "prototype") and
                        proto.object != hir_mod.none_node_id and self.hir.kindOf(proto.object) == .identifier)
                    {
                        return hir_mod.identifierOf(self.hir, proto.object).name;
                    }
                }
            }
        }

        const src = self.source orelse return null;
        const fn_span = self.hir.spanOf(fn_node);
        if (fn_span.start > src.len) return null;
        const prefix = src[0..fn_span.start];
        const proto_pos = std.mem.lastIndexOf(u8, prefix, ".prototype.") orelse return null;
        var owner_start = proto_pos;
        while (owner_start > 0 and isJsDocIdentChar(prefix[owner_start - 1])) : (owner_start -= 1) {}
        if (owner_start == proto_pos) return null;
        return self.string_interner.intern(prefix[owner_start..proto_pos]) catch null;
    }

    fn reportCheckJsConstructorNullableMemberRead(self: *Checker, object_node: NodeId) CheckError!bool {
        if (!self.sourceHasCheckJsDirective() or !self.strict_flags.strict_null_checks) return false;
        if (object_node == hir_mod.none_node_id or self.hir.kindOf(object_node) != .member_access) return false;
        const member = hir_mod.memberOf(self.hir, object_node);
        if (!self.nodeIsThisReference(member.object)) return false;
        if (self.checkJsThisMemberReadHasNonNullGuard(object_node, member.name)) return false;
        const owner = self.checkJsPrototypeAssignmentOwnerName(object_node) orelse return false;
        const fn_node = self.jsConstructorFunctionDeclForName(object_node, owner) orelse return false;
        const function = hir_mod.fnDeclOf(self.hir, fn_node);
        if (function.body == hir_mod.none_node_id or self.hir.kindOf(function.body) != .block_stmt) return false;
        var saw_null = false;
        var saw_non_null = false;
        for (hir_mod.blockStmts(self.hir, function.body)) |stmt| {
            if (self.hir.kindOf(stmt) != .assignment) continue;
            const assignment = hir_mod.assignmentOf(self.hir, stmt);
            if ((self.directThisPropertyName(assignment.target) orelse continue) != member.name) continue;
            if (assignment.value == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(assignment.value) == .literal_null) {
                saw_null = true;
            } else {
                saw_non_null = true;
            }
        }
        if (!saw_null or !saw_non_null) return false;
        try self.report(object_node, TsCodes.object_possibly_null_2531, "Object is possibly 'null'.");
        return true;
    }

    fn checkJsThisMemberReadHasNonNullGuard(
        self: *Checker,
        node: NodeId,
        member_name: hir_mod.StringId,
    ) bool {
        const src = self.source orelse return false;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            if (self.hir.kindOf(cur) != .if_stmt) continue;
            const statement = hir_mod.ifOf(self.hir, cur);
            if (!self.nodeIsAncestorOf(statement.then_branch, node)) continue;
            const span = self.hir.spanOf(statement.cond);
            if (span.start >= span.end or span.end > src.len) continue;
            const condition = src[span.start..span.end];
            if (std.mem.indexOf(u8, condition, "!= null") == null and
                std.mem.indexOf(u8, condition, "!== null") == null)
            {
                continue;
            }
            if (std.mem.indexOf(u8, condition, self.string_interner.get(member_name)) != null) return true;
        }
        return false;
    }

    fn checkJsPrototypeObjectLiteralAssignmentOwnerNameForFunction(self: *Checker, fn_node: NodeId) ?hir_mod.StringId {
        if (!self.sourceHasCheckJsDirective()) return null;
        const fn_kind = self.hir.kindOf(fn_node);
        if (fn_kind != .fn_expr and fn_kind != .fn_decl) return null;
        const prop_node = self.hir.parentOf(fn_node);
        if (prop_node == hir_mod.none_node_id or self.hir.kindOf(prop_node) != .object_property) return null;
        const prop = hir_mod.objectPropertyOf(self.hir, prop_node);
        if (prop.value != fn_node and !prop.is_method) return null;
        const obj_node = self.hir.parentOf(prop_node);
        if (obj_node == hir_mod.none_node_id or self.hir.kindOf(obj_node) != .object_literal) return null;
        const assign_node = self.hir.parentOf(obj_node);
        if (assign_node == hir_mod.none_node_id or self.hir.kindOf(assign_node) != .assignment) return null;
        const assign = hir_mod.assignmentOf(self.hir, assign_node);
        if (assign.value != obj_node or assign.target == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(assign.target) != .member_access) return null;
        const target = hir_mod.memberOf(self.hir, assign.target);
        if (!std.mem.eql(u8, self.string_interner.get(target.name), "prototype")) return null;
        if (target.object == hir_mod.none_node_id or self.hir.kindOf(target.object) != .identifier) return null;
        return hir_mod.identifierOf(self.hir, target.object).name;
    }

    fn checkJsPrototypeOwnerNameBeforeNode(self: *Checker, node: NodeId) ?hir_mod.StringId {
        const src = self.source orelse return null;
        const span = self.hir.spanOf(node);
        if (span.start > src.len) return null;
        const prefix = src[0..span.start];
        const proto_pos = std.mem.lastIndexOf(u8, prefix, ".prototype.") orelse return null;
        var owner_start = proto_pos;
        while (owner_start > 0 and isJsDocIdentChar(prefix[owner_start - 1])) : (owner_start -= 1) {}
        if (owner_start == proto_pos) return null;
        return self.string_interner.intern(prefix[owner_start..proto_pos]) catch null;
    }

    fn checkJsAssignmentTargetShouldReportMissingMember(self: *Checker, node: NodeId, receiver_t: TypeId) bool {
        if (self.assignmentTargetValueIsVoidExpression(node)) return true;
        const builtin = self.builtin_object_names.get(receiver_t) orelse return false;
        return std.mem.eql(u8, builtin, "Event");
    }

    fn reportCheckJsPrototypeThisMissingMemberAssignment(self: *Checker, target: NodeId) CheckError!bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        if (target == hir_mod.none_node_id or self.hir.kindOf(target) != .member_access) return false;
        const member = hir_mod.memberOf(self.hir, target);
        if (!self.nodeIsThisReference(member.object)) return false;
        const this_t = self.checkJsPrototypeAssignmentThisType(member.object) orelse return false;
        if (!self.checkJsAssignmentTargetShouldReportMissingMember(target, this_t)) return false;
        if ((try self.lookupObjectMember(this_t, member.name)) != null) return false;
        try self.reportPropertyDoesNotExistOnType(target, member.name, this_t);
        return true;
    }

    fn thisInsideCheckJsFunctionWithThisTag(self: *Checker, node: NodeId) bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        const src = self.source orelse return false;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) return false;
            if (k != .fn_decl and k != .fn_expr) continue;

            var owner = cur;
            while (owner != hir_mod.none_node_id) : (owner = self.hir.parentOf(owner)) {
                const owner_kind = self.hir.kindOf(owner);
                if (owner_kind == .block_stmt or owner_kind == .class_decl or owner_kind == .class_expr) break;
                const span = self.hir.spanOf(owner);
                const body = self.leadingJsDocBody(src, span.start) orelse continue;
                if (std.mem.indexOf(u8, body, "@this") != null) return true;
            }
            return false;
        }
        return false;
    }

    fn thisInsideCheckJsCallbackWithThis(self: *Checker, node: NodeId) bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        const src = self.source orelse return false;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) return false;
            if (k != .fn_expr and k != .fn_decl) continue;
            const parent = self.hir.parentOf(cur);
            if (parent == hir_mod.none_node_id) return false;
            const pk = self.hir.kindOf(parent);
            if (pk != .var_decl and pk != .let_decl and pk != .const_decl) return false;
            const v = hir_mod.varDeclOf(self.hir, parent);
            if (v.init != cur) return false;
            const span = self.hir.spanOf(parent);
            const body = self.leadingJsDocBody(src, span.start) orelse return false;
            const tags = ts_parser.jsdoc.parse(self.gpa, body) catch return false;
            defer self.gpa.free(tags);
            for (tags) |tag| {
                if (tag.kind != .type_tag) continue;
                const base = jsDocTypeBaseName(tag.type_text);
                if (base.len == 0) continue;
                if (self.jsDocCallbackHasThis(src, base)) return true;
            }
            return false;
        }
        return false;
    }

    fn jsDocCallbackHasThis(self: *Checker, src: []const u8, wanted_name: []const u8) bool {
        _ = self;
        var search_start: usize = 0;
        while (std.mem.indexOfPos(u8, src, search_start, "/**")) |start| {
            const body_start = start + 3;
            const end = std.mem.indexOfPos(u8, src, body_start, "*/") orelse return false;
            defer search_start = end + 2;
            const body = src[body_start..end];
            if (!jsDocBlockHasNamedTag(body, "@callback", wanted_name)) continue;
            if (std.mem.indexOf(u8, body, "@this") != null) return true;
        }
        return false;
    }

    fn fnLooksLikeCheckJsConstructor(self: *Checker, fn_node: NodeId) bool {
        const f = hir_mod.fnDeclOf(self.hir, fn_node);
        if (self.leadingJsDocBody(self.source orelse "", self.hir.spanOf(fn_node).start)) |body| {
            if (std.mem.indexOf(u8, body, "@class") != null or
                std.mem.indexOf(u8, body, "@constructor") != null) return true;
        }
        if (f.name != hir_mod.none_node_id and self.hir.kindOf(f.name) == .identifier) {
            const id = hir_mod.identifierOf(self.hir, f.name);
            if (self.checkJsFunctionHasPrototypePropertyTypeOnlyAccess(fn_node, id.name)) return false;
            if (self.identifierNameStartsUppercase(id.name)) return true;
        }
        const parent = self.hir.parentOf(fn_node);
        if (parent != hir_mod.none_node_id) {
            const pk = self.hir.kindOf(parent);
            if (pk == .var_decl or pk == .let_decl or pk == .const_decl) {
                const v = hir_mod.varDeclOf(self.hir, parent);
                if (v.init == fn_node and
                    v.name != hir_mod.none_node_id and
                    self.hir.kindOf(v.name) == .identifier and
                    !self.checkJsFunctionHasPrototypePropertyTypeOnlyAccess(fn_node, hir_mod.identifierOf(self.hir, v.name).name) and
                    self.identifierNameStartsUppercase(hir_mod.identifierOf(self.hir, v.name).name))
                {
                    return true;
                }
            }
        }
        if (parent != hir_mod.none_node_id and self.hir.kindOf(parent) == .assignment) {
            const a = hir_mod.assignmentOf(self.hir, parent);
            if (a.value == fn_node and self.assignmentTargetIsPrototypeMember(a.target)) return true;
            if (a.value == fn_node and self.assignmentTargetLastNameStartsUppercase(a.target)) return true;
        }
        return false;
    }

    fn checkJsFunctionHasPrototypePropertyTypeOnlyAccess(
        self: *Checker,
        fn_node: NodeId,
        name: hir_mod.StringId,
    ) bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        const src = self.source orelse return false;
        const root = self.rootBlockFor(fn_node);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        const name_text = self.string_interner.get(name);
        const prefix = std.fmt.allocPrint(self.gpa, "{s}.prototype.", .{name_text}) catch return false;
        defer self.gpa.free(prefix);
        const fn_end = self.hir.spanOf(fn_node).end;
        const section_start = self.virtualSectionStartForNode(fn_node);
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            if (stmt == fn_node) continue;
            if (self.virtualSectionStartForNode(stmt) != section_start) continue;
            const sp = self.hir.spanOf(stmt);
            if (sp.start <= fn_end) continue;
            if (self.hir.kindOf(stmt) == .assignment) continue;
            const jsdoc = self.leadingJsDocBodyWithStart(src, sp.start) orelse continue;
            if (std.mem.indexOf(u8, jsdoc.body, "@type") == null) continue;
            if (sp.start >= src.len or sp.end > src.len or sp.start >= sp.end) continue;
            var text = std.mem.trim(u8, src[sp.start..sp.end], " \t\r\n;");
            if (std.mem.startsWith(u8, text, "(") and std.mem.endsWith(u8, text, ")")) {
                text = std.mem.trim(u8, text[1 .. text.len - 1], " \t\r\n");
            }
            if (!std.mem.startsWith(u8, text, prefix)) continue;
            const prop = text[prefix.len..];
            if (prop.len == 0) continue;
            var valid = true;
            for (prop) |ch| {
                if (!isJsDocIdentChar(ch) and ch != '.') {
                    valid = false;
                    break;
                }
            }
            if (valid) return true;
        }
        return false;
    }

    fn fnHasJsDocClassOrConstructorTag(self: *Checker, fn_node: NodeId) bool {
        const src = self.source orelse return false;
        if (self.leadingJsDocBody(src, self.hir.spanOf(fn_node).start)) |body| {
            if (std.mem.indexOf(u8, body, "@class") != null or
                std.mem.indexOf(u8, body, "@constructor") != null) return true;
        }
        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id) return false;
        const pk = self.hir.kindOf(parent);
        if (pk != .var_decl and pk != .let_decl and pk != .const_decl) return false;
        const v = hir_mod.varDeclOf(self.hir, parent);
        if (v.init != fn_node) return false;
        if (self.leadingJsDocBody(src, self.hir.spanOf(parent).start)) |body| {
            return std.mem.indexOf(u8, body, "@class") != null or
                std.mem.indexOf(u8, body, "@constructor") != null;
        }
        return false;
    }

    fn fnHasJsDocTag(self: *Checker, fn_node: NodeId, tag: []const u8) bool {
        const src = self.source orelse return false;
        if (self.leadingJsDocBody(src, self.hir.spanOf(fn_node).start)) |body| {
            if (std.mem.indexOf(u8, body, tag) != null) return true;
        }
        const parent = self.hir.parentOf(fn_node);
        if (parent == hir_mod.none_node_id) return false;
        const pk = self.hir.kindOf(parent);
        if (pk != .var_decl and pk != .let_decl and pk != .const_decl) return false;
        const v = hir_mod.varDeclOf(self.hir, parent);
        if (v.init != fn_node) return false;
        if (self.leadingJsDocBody(src, self.hir.spanOf(parent).start)) |body| {
            return std.mem.indexOf(u8, body, tag) != null;
        }
        return false;
    }

    fn jsDocConstructOnlyStaticTypeForIdentifier(
        self: *Checker,
        anchor: NodeId,
        name: hir_mod.StringId,
    ) CheckError!?TypeId {
        if (!self.sourceHasCheckJsDirective()) return null;
        const fn_node = self.jsConstructorFunctionDeclForName(anchor, name) orelse return null;
        if (!self.fnHasJsDocClassOrConstructorTag(fn_node)) return null;
        return try self.jsConstructorStaticTypeForHeritage(anchor, name);
    }

    fn identifierNameStartsUppercase(self: *Checker, name: hir_mod.StringId) bool {
        const text = self.string_interner.get(name);
        if (text.len == 0) return false;
        return text[0] >= 'A' and text[0] <= 'Z';
    }

    fn assignmentTargetIsPrototypeMember(self: *Checker, target: NodeId) bool {
        if (target == hir_mod.none_node_id or self.hir.kindOf(target) != .member_access) return false;
        const m = hir_mod.memberOf(self.hir, target);
        if (m.object == hir_mod.none_node_id or self.hir.kindOf(m.object) != .member_access) return false;
        const parent_member = hir_mod.memberOf(self.hir, m.object);
        return std.mem.eql(u8, self.string_interner.get(parent_member.name), "prototype");
    }

    /// `.js` files with `// @ts-check` accept `/** @type {T} */
    /// C.prototype = expr` as a declaration that pins the prototype
    /// slot to T. Returns T when the assignment statement carries a
    /// leading `@type` JSDoc and the target is `<Ctor>.prototype`
    /// (a 2-level member access whose tail name is `prototype` and
    /// whose object is an identifier ÃÂ¢ÃÂÃÂ typically a constructor
    /// function or class). The override is restricted to
    /// constructor-shaped LHS names to avoid touching unrelated
    /// `obj.prototype = ÃÂ¢ÃÂÃÂ¦` patterns where the member-access
    /// structural shape is the right declared type. Mirrors
    /// `typeTagPrototypeAssignment` upstream.
    fn jsDocTypeForPrototypeAssignmentTarget(
        self: *Checker,
        assignment_node: NodeId,
        target: NodeId,
    ) CheckError!?TypeId {
        const ctor_name = self.ctorPrototypeOwnerName(target) orelse return null;
        // Treat as a real constructor when:
        //  - the checker has already registered the name as a class
        //    instance type, OR
        //  - the binder identifies it as a function/class symbol, OR
        //  - the same source declares a `function <id>()` or
        //    `class <id>` at the top level (the binder isn't always
        //    attached, e.g. inside checker unit-test setups).
        var is_constructor_like = self.class_instance_types.contains(ctor_name);
        if (!is_constructor_like) {
            if (self.module) |module| {
                if (module.root.lookup(ctor_name)) |sym| {
                    is_constructor_like = sym.flags.is_function or sym.flags.is_class;
                }
            }
        }
        if (!is_constructor_like) {
            is_constructor_like = self.rootHasFunctionOrClassDeclNamed(assignment_node, ctor_name);
        }
        if (!is_constructor_like) return null;
        // Pull `@type` from the leading JSDoc on the assignment's
        // enclosing expression statement (where the comment actually
        // lives), falling back to the assignment node itself.
        const parent = self.hir.parentOf(assignment_node);
        const anchor = if (parent != hir_mod.none_node_id and
            self.hir.kindOf(parent) == .expression_stmt)
            parent
        else
            assignment_node;
        return try self.jsDocTypeForLeadingNode(anchor);
    }

    /// Returns true when the source-file root block contains a
    /// `function <name>()` or `class <name>` declaration. Used as a
    /// binder-free constructor-shape probe for `Ctor.prototype = ÃÂ¢ÃÂÃÂ¦`
    /// detection in the JSDoc `@type` override. The anchor is any
    /// node inside the source file ÃÂ¢ÃÂÃÂ we walk to its root block.
    fn rootHasFunctionOrClassDeclNamed(
        self: *Checker,
        anchor: NodeId,
        wanted: hir_mod.StringId,
    ) bool {
        const root = self.rootBlockFor(anchor);
        if (root == hir_mod.none_node_id or self.hir.kindOf(root) != .block_stmt) return false;
        for (hir_mod.blockStmts(self.hir, root)) |stmt| {
            const k = self.hir.kindOf(stmt);
            if (k == .fn_decl) {
                const f = hir_mod.fnDeclOf(self.hir, stmt);
                if (f.name == hir_mod.none_node_id) continue;
                if (self.hir.kindOf(f.name) != .identifier) continue;
                if (hir_mod.identifierOf(self.hir, f.name).name == wanted) return true;
            } else if (k == .class_decl) {
                const c = hir_mod.classOf(self.hir, stmt);
                if (c.name == hir_mod.none_node_id) continue;
                if (self.hir.kindOf(c.name) != .identifier) continue;
                if (hir_mod.identifierOf(self.hir, c.name).name == wanted) return true;
            }
        }
        return false;
    }

    fn assignmentTargetLastNameStartsUppercase(self: *Checker, target: NodeId) bool {
        if (target == hir_mod.none_node_id or self.hir.kindOf(target) != .member_access) return false;
        const m = hir_mod.memberOf(self.hir, target);
        return self.identifierNameStartsUppercase(m.name);
    }

    fn thisInsideNonArrowPlainFunction(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) return false;
            if (k == .fn_decl or k == .fn_expr) {
                const f = hir_mod.fnDeclOf(self.hir, cur);
                return !f.flags.is_method and !f.flags.is_constructor;
            }
        }
        return false;
    }

    /// True when the nearest enclosing non-arrow function (the lexical
    /// `this` host) declares an explicit `this: T` parameter. Arrow
    /// functions are transparent to `this`, so we skip past them. When a
    /// plain function carries an explicit `this` annotation, `this` is
    /// NOT implicitly `any` — it is the declared type — so callers use
    /// this to override the "plain function rebinds `this`" guard.
    fn enclosingThisHostHasExplicitThisParam(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) continue;
            if (k != .fn_decl and k != .fn_expr) continue;
            for (hir_mod.fnParams(self.hir, cur)) |p| {
                if (self.isThisParameter(p)) {
                    const pp = hir_mod.parameterOf(self.hir, p);
                    return pp.type_annotation != hir_mod.none_node_id;
                }
            }
            return false;
        }
        return false;
    }

    fn enclosingThisHostHasThisParam(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) continue;
            if (k != .fn_decl and k != .fn_expr) continue;
            for (hir_mod.fnParams(self.hir, cur)) |p| {
                if (self.isThisParameter(p)) return true;
            }
            return false;
        }
        return false;
    }

    fn thisInsideClassFieldFunctionExpression(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) return false;
            if (k != .fn_decl and k != .fn_expr) continue;
            const f = hir_mod.fnDeclOf(self.hir, cur);
            if (f.flags.is_method or f.flags.is_constructor) return false;
            const prop_node = self.hir.parentOf(cur);
            if (prop_node == hir_mod.none_node_id or self.hir.kindOf(prop_node) != .object_property) return false;
            const op = hir_mod.objectPropertyOf(self.hir, prop_node);
            if (op.value != cur or op.is_method or self.memberSourceLooksMethod(prop_node)) return false;
            const class_node = self.hir.parentOf(prop_node);
            if (class_node == hir_mod.none_node_id) return false;
            const ck = self.hir.kindOf(class_node);
            return ck == .class_decl or ck == .class_expr;
        }
        return false;
    }

    fn identifierThisIsArrowCaptured(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .arrow_fn) return true;
            if (k == .fn_decl or k == .fn_expr) return false;
        }
        return false;
    }

    fn thisInsideObjectLiteralMethod(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k != .fn_decl and k != .fn_expr and k != .arrow_fn) continue;
            const fn_parent = self.hir.parentOf(cur);
            if (fn_parent == hir_mod.none_node_id or self.hir.kindOf(fn_parent) != .object_property) return false;
            const op = hir_mod.objectPropertyOf(self.hir, fn_parent);
            return op.value == cur and (op.is_method or self.memberSourceLooksMethod(fn_parent) or k == .fn_expr or k == .fn_decl);
        }
        return false;
    }

    fn thisInsideJsDocConstructorObjectLiteralMethod(self: *Checker, node: NodeId) bool {
        if (!self.sourceHasCheckJsDirective()) return false;
        const src = self.source orelse return false;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const kind = self.hir.kindOf(cur);
            if (kind == .arrow_fn) continue;
            if (kind != .fn_decl and kind != .fn_expr) continue;
            const prop_node = self.hir.parentOf(cur);
            if (prop_node == hir_mod.none_node_id or self.hir.kindOf(prop_node) != .object_property) return false;
            const prop = hir_mod.objectPropertyOf(self.hir, prop_node);
            if (prop.value != cur or (!prop.is_method and !self.memberSourceLooksMethod(prop_node))) return false;
            const object_node = self.hir.parentOf(prop_node);
            if (object_node == hir_mod.none_node_id or self.hir.kindOf(object_node) != .object_literal) return false;
            const body = self.leadingJsDocBodyForFunctionOrOwner(src, cur) orelse return false;
            return std.mem.indexOf(u8, body, "@constructor") != null;
        }
        return false;
    }

    /// True when `this` sits inside a class constructor's parameter
    /// list (e.g. `constructor(f = this) { ... }`). The class instance
    /// type is implicit, so tsc does NOT fire TS2683 ÃÂ¢ÃÂÃÂ the value of
    /// `this` is the class itself. Mirrors fixture
    /// `typeOfThisInConstructorParamList.ts` (expected-clean).
    fn thisInsideClassConstructorParameter(self: *Checker, node: NodeId) bool {
        var cur = self.hir.parentOf(node);
        // Walk up until we hit a parameter slot; track when we cross a
        // nested function boundary that would re-bind `this` (only
        // arrows preserve the outer `this`; fn_decl / fn_expr / methods
        // create a fresh `this` and so disqualify the outer constructor
        // context).
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .fn_decl or k == .fn_expr) return false;
            if (k != .parameter) continue;
            // Found a parameter. Its parent should be the function the
            // parameter belongs to. For a class constructor that
            // function is an `fn_decl` (with `is_constructor` set in
            // its source) whose parent is a `class_decl` / `class_expr`.
            const param_owner = self.hir.parentOf(cur);
            if (param_owner == hir_mod.none_node_id) return false;
            const owner_kind = self.hir.kindOf(param_owner);
            if (owner_kind != .fn_decl and owner_kind != .fn_expr) return false;
            if (!self.fnDeclIsConstructor(param_owner)) return false;
            const owner_parent = self.hir.parentOf(param_owner);
            if (owner_parent == hir_mod.none_node_id) return false;
            const owner_parent_kind = self.hir.kindOf(owner_parent);
            return owner_parent_kind == .class_decl or owner_parent_kind == .class_expr;
        }
        return false;
    }

    fn fnDeclIsConstructor(self: *Checker, fn_node: NodeId) bool {
        const k = self.hir.kindOf(fn_node);
        if (k != .fn_decl and k != .fn_expr) return false;
        const fd = hir_mod.fnDeclOf(self.hir, fn_node);
        if (fd.flags.is_constructor) return true;
        // Fall back to the source-written name for shapes that don't
        // set the flag (e.g. raw `function constructor(...)` outside
        // a class declaration won't have it, but inside a class body
        // the parser sets `is_constructor`).
        if (fd.name == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(fd.name) != .identifier) return false;
        const name_id = hir_mod.identifierOf(self.hir, fd.name);
        return std.mem.eql(u8, self.string_interner.get(name_id.name), "constructor");
    }

    fn optionalChainResult(self: *Checker, t: TypeId, is_optional_chain: bool) CheckError!TypeId {
        if (!is_optional_chain) return t;
        if (!self.strict_flags.strict_null_checks) return t;
        return self.unionWithUndefined(t) catch return error.OutOfMemory;
    }

    fn contextualGenericCallResult(self: *Checker, node: NodeId, source_t: TypeId, target_t: TypeId) CheckError!?TypeId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .call_expr) return null;
        if (target_t == types.Primitive.none or target_t == types.Primitive.any or target_t == types.Primitive.unknown) return null;
        if (!self.typeIsOrContainsUnknown(source_t) and !self.containsFreeTypeParameter(source_t)) return null;
        const c = hir_mod.callOf(self.hir, node);
        var callee_t = self.hir.typeOf(c.callee);
        if (callee_t == types.Primitive.none) callee_t = try self.checkExpression(c.callee);
        const call_is_optional_chain = c.optional or self.expressionIsOptionalChain(c.callee);
        if (call_is_optional_chain) {
            callee_t = self.subtractNullUndefined(callee_t) catch callee_t;
        }
        const sig = self.firstCallableSignatureForContextualReturn(callee_t) orelse return null;
        const ret_t = self.interner.signatureReturn(sig) orelse return null;
        if (!self.containsFreeTypeParameter(ret_t)) return null;
        var expected_ret = if (call_is_optional_chain)
            (try self.subtractUndefined(target_t))
        else
            target_t;
        if (expected_ret == types.Primitive.never and call_is_optional_chain) expected_ret = target_t;
        if (expected_ret == types.Primitive.none or expected_ret == types.Primitive.never) return null;
        return try self.optionalChainResult(expected_ret, call_is_optional_chain);
    }

    fn checkContextualGenericCallFunctionArgs(self: *Checker, node: NodeId, source_t: TypeId, target_t: TypeId) CheckError!void {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .call_expr) return;
        if (target_t == types.Primitive.none or target_t == types.Primitive.any or target_t == types.Primitive.unknown) return;
        if (!self.typeIsOrContainsUnknown(source_t) and !self.containsFreeTypeParameter(source_t)) return;
        const c = hir_mod.callOf(self.hir, node);
        var callee_t = self.hir.typeOf(c.callee);
        if (callee_t == types.Primitive.none) callee_t = try self.checkExpression(c.callee);
        const call_is_optional_chain = c.optional or self.expressionIsOptionalChain(c.callee);
        if (call_is_optional_chain) {
            callee_t = self.subtractNullUndefined(callee_t) catch callee_t;
        }
        const sig = self.firstCallableSignatureForContextualReturn(callee_t) orelse return;
        const ret_t = self.interner.signatureReturn(sig) orelse return;
        if (!self.containsFreeTypeParameter(ret_t)) return;
        var expected_ret = if (call_is_optional_chain)
            (try self.subtractUndefined(target_t))
        else
            target_t;
        if (expected_ret == types.Primitive.never and call_is_optional_chain) expected_ret = target_t;
        if (expected_ret == types.Primitive.none or expected_ret == types.Primitive.never) return;

        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        try self.inferFromPair(ret_t, expected_ret, &subs);
        if (subs.count() == 0) return;

        const effective_sig = self.substituteType(sig, &subs) catch sig;
        const params = self.interner.signatureParams(effective_sig);
        const args = hir_mod.callArgs(self.hir, node);
        const n = @min(args.len, params.len);
        for (0..n) |i| {
            const arg = args[i];
            if (!self.isContextualFunctionExpressionLike(arg)) continue;
            const param_sig = self.firstSignatureType(params[i]) orelse continue;
            try self.checkFunctionWithContextualSignature(arg, param_sig);
        }
        self.dedupeExactDiagnostics();
    }

    fn removeUnknownAssignabilityDiagnosticsForNode(self: *Checker, node: NodeId) void {
        var keep: usize = 0;
        for (self.diagnostics.items) |d| {
            const remove = d.node == node and
                d.code == TsCodes.type_not_assignable and
                std.mem.startsWith(u8, d.message, "Type 'unknown' is not assignable to type ");
            if (remove) continue;
            self.diagnostics.items[keep] = d;
            keep += 1;
        }
        self.diagnostics.shrinkRetainingCapacity(keep);
    }

    fn firstCallableSignatureForContextualReturn(self: *Checker, t: TypeId) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_signature) return t;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.firstCallableSignatureForContextualReturn(member)) |sig| return sig;
            }
            return null;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.firstCallableSignatureForContextualReturn(member)) |sig| return sig;
            }
            return null;
        }
        if (flags.is_object_type) {
            const call_member_id = self.string_interner.intern("__call") catch return null;
            if (self.interner.objectMember(t, call_member_id)) |call_t| {
                return self.firstCallableSignatureForContextualReturn(call_t);
            }
        }
        return null;
    }

    fn typeIsOrContainsUnknown(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_unknown) return true;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeIsOrContainsUnknown(member)) return true;
            }
        }
        return false;
    }

    fn subtractUndefined(self: *Checker, t: TypeId) !TypeId {
        if (t >= self.interner.pool.typeCount()) return t;
        const flags = self.interner.pool.flagsOf(t);
        // Union flags aggregate their members, so `T | undefined` also has
        // `is_undefined`. Inspect the container before the scalar flag or the
        // whole union incorrectly collapses to `never`.
        if (!flags.is_union) return if (flags.is_undefined) types.Primitive.never else t;
        const members = self.interner.unionMembers(t);
        var kept: std.ArrayListUnmanaged(TypeId) = .empty;
        defer kept.deinit(self.gpa);
        for (members) |member| {
            if (self.interner.pool.flagsOf(member).is_undefined) continue;
            try kept.append(self.gpa, member);
        }
        if (kept.items.len == 0) return types.Primitive.never;
        if (kept.items.len == 1) return kept.items[0];
        return self.interner.internUnion(kept.items) catch return error.OutOfMemory;
    }

    fn expressionIsOptionalChain(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(node)) {
            .member_access => blk: {
                const m = hir_mod.memberOf(self.hir, node);
                break :blk m.optional or self.expressionIsOptionalChain(m.object);
            },
            .element_access => blk: {
                const e = hir_mod.elementOf(self.hir, node);
                break :blk e.optional or self.expressionIsOptionalChain(e.object);
            },
            .call_expr => blk: {
                const c = hir_mod.callOf(self.hir, node);
                break :blk c.optional or self.expressionIsOptionalChain(c.callee);
            },
            else => false,
        };
    }

    fn classThisType(self: *Checker, instance_t: TypeId) CheckError!TypeId {
        const this_id = self.string_interner.intern("this") catch return error.OutOfMemory;
        return self.interner.internFreshTypeParameterWithFlags(
            this_id,
            instance_t,
            types.Primitive.none,
            .bivariant,
            false,
        ) catch return error.OutOfMemory;
    }

    fn classThisTypeForNode(self: *Checker, class_node: NodeId, instance_t: TypeId) CheckError!TypeId {
        if (self.class_this_types.get(class_node)) |t| return t;
        const this_t = try self.classThisType(instance_t);
        try self.class_this_types.put(self.gpa, class_node, this_t);
        return this_t;
    }

    fn boundThisTypeForNode(self: *Checker, node: NodeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (self.lookupNarrow(name)) |t| return t;
        if (!self.thisTypeIsValidHere(node)) return null;
        const class_node = self.enclosingClassNode(node);
        if (class_node == hir_mod.none_node_id) return null;
        return self.class_this_types.get(class_node);
    }

    fn thisIsPrivateMemberReceiverInsideClass(self: *Checker, node: NodeId) bool {
        if (!self.nodeIsThisReference(node)) return false;
        const parent = self.hir.parentOf(node);
        if (parent != hir_mod.none_node_id and self.hir.kindOf(parent) == .member_access) {
            const m = hir_mod.memberOf(self.hir, parent);
            if (m.object == node and self.memberNameIsEcmaPrivate(m.name)) return true;
        }
        const src = self.source orelse return false;
        const span = self.hir.spanOf(node);
        if (span.end > src.len) return false;
        var i = span.end;
        while (i < src.len and (src[i] == ' ' or src[i] == '\t' or src[i] == '\r' or src[i] == '\n')) : (i += 1) {}
        if (i >= src.len or src[i] != '.') return false;
        i += 1;
        while (i < src.len and (src[i] == ' ' or src[i] == '\t' or src[i] == '\r' or src[i] == '\n')) : (i += 1) {}
        return i < src.len and src[i] == '#';
    }

    fn checkObjectLiteralMethodBodiesWithThis(self: *Checker, node: NodeId, obj_t: TypeId) CheckError!void {
        try self.checkObjectLiteralMethodBodiesWithInheritedThis(node, obj_t, null);
    }

    fn checkObjectLiteralMethodBodiesWithInheritedThis(
        self: *Checker,
        node: NodeId,
        obj_t: TypeId,
        inherited_this_t: ?TypeId,
    ) CheckError!void {
        const props = hir_mod.objectLiteralProps(self.hir, node);
        const this_id = self.string_interner.intern("this") catch return error.OutOfMemory;
        const direct_this_marker = self.thisTypeMarkerConstraint(obj_t);
        var this_t = if (direct_this_marker) |marker_t|
            marker_t
        else
            (inherited_this_t orelse obj_t);
        if (self.ancestorObjectLiteralDataReturnType(node)) |data_t| {
            this_t = self.interner.internIntersection(&.{ data_t, this_t }) catch this_t;
        }
        for (props) |p| {
            if (self.hir.kindOf(p) != .object_property) continue;
            const op = hir_mod.objectPropertyOf(self.hir, p);
            if (op.value == hir_mod.none_node_id) continue;
            const value_kind = self.hir.kindOf(op.value);
            const member_name = try self.classMemberNameFromPropertyKey(op.key, op.is_computed);
            const target_member_t = if (member_name) |name|
                try self.contextualObjectLiteralMemberTarget(obj_t, name)
            else
                null;
            if (value_kind == .object_literal) {
                var nested_this_t: ?TypeId = if (direct_this_marker) |marker_t| marker_t else inherited_this_t;
                if (target_member_t) |target_t| {
                    if (self.thisTypeMarkerConstraint(target_t)) |marker_t| {
                        nested_this_t = marker_t;
                    }
                }
                const nested_target_t = target_member_t orelse self.hir.typeOf(op.value);
                try self.checkObjectLiteralMethodBodiesWithInheritedThis(op.value, nested_target_t, nested_this_t);
                continue;
            }
            if (value_kind != .fn_decl and value_kind != .fn_expr and value_kind != .arrow_fn) continue;
            const op_is_method = op.is_method or self.memberSourceLooksMethod(p);
            if (!op_is_method and value_kind != .fn_expr and value_kind != .fn_decl) continue;
            if (!self.functionContainsThis(op.value)) continue;
            var method_this_t = this_t;
            if (target_member_t) |target_t| {
                if (self.firstSignatureType(target_t)) |target_sig| {
                    if (self.signatureThisParam(target_sig)) |target_this_t| {
                        method_this_t = self.thisTypeMarkerConstraint(target_this_t) orelse target_this_t;
                    }
                }
            }
            self.removePriorDiagnosticsInNodeSpan(op.value, TsCodes.property_does_not_exist);
            try self.pushNarrowScope();
            try self.recordNarrow(this_id, method_this_t);
            try self.checkFnDecl(op.value);
            self.popNarrowScope();
        }
    }

    fn contextualObjectLiteralMemberTarget(self: *Checker, obj_t: TypeId, name: hir_mod.StringId) CheckError!?TypeId {
        if (obj_t < types.Primitive.first_dynamic or obj_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(obj_t);
        if (flags.is_union) {
            for (self.interner.unionMembers(obj_t)) |member| {
                if (try self.contextualObjectLiteralMemberTarget(member, name)) |target_t| return target_t;
            }
            return null;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(obj_t)) |member| {
                if (self.thisTypeMarkerConstraint(member) != null) continue;
                if (try self.contextualObjectLiteralMemberTarget(member, name)) |target_t| return target_t;
            }
            return null;
        }
        if (self.typeIsMappedPayloadType(obj_t)) {
            return try self.mappedPropertyTargetType(obj_t, name);
        }
        return (try self.lookupObjectMember(obj_t, name)) orelse
            (try self.patternIndexValueForStringKey(obj_t, name));
    }

    fn contextualObjectLiteralThisType(self: *Checker, t: TypeId) TypeId {
        if (self.thisTypeMarkerConstraint(t)) |this_t| return this_t;
        return t;
    }

    fn thisTypeMarkerConstraint(self: *Checker, t: TypeId) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        if (self.this_type_markers.get(t)) |this_t| return this_t;
        if (self.isThisTypeParameter(t)) return self.typeParameterConstraint(t) orelse types.Primitive.any;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_intersection) {
            const payload_idx = self.interner.pool.payloadOf(t);
            if (payload_idx >= self.interner.pool.intersection_payloads.items.len) return null;
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.thisTypeMarkerConstraint(member)) |this_t| return this_t;
            }
        }
        if (flags.is_union) {
            const payload_idx = self.interner.pool.payloadOf(t);
            if (payload_idx >= self.interner.pool.union_payloads.items.len) return null;
            for (self.interner.unionMembers(t)) |member| {
                if (self.thisTypeMarkerConstraint(member)) |this_t| return this_t;
            }
        }
        return null;
    }

    fn ancestorObjectLiteralDataReturnType(self: *Checker, node: NodeId) ?TypeId {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            if (self.hir.kindOf(cur) != .object_literal) continue;
            for (hir_mod.objectLiteralProps(self.hir, cur)) |prop_node| {
                if (self.hir.kindOf(prop_node) != .object_property) continue;
                const op = hir_mod.objectPropertyOf(self.hir, prop_node);
                if (op.key == hir_mod.none_node_id or self.hir.kindOf(op.key) != .identifier) continue;
                const key = hir_mod.identifierOf(self.hir, op.key).name;
                if (!std.mem.eql(u8, self.string_interner.get(key), "data")) continue;
                if (op.value == hir_mod.none_node_id) return null;
                const value_kind = self.hir.kindOf(op.value);
                if (value_kind == .object_literal) return self.hir.typeOf(op.value);
                if (value_kind != .fn_decl and value_kind != .fn_expr and value_kind != .arrow_fn) return null;
                const f = hir_mod.fnDeclOf(self.hir, op.value);
                if (f.body == hir_mod.none_node_id) return null;
                if (self.hir.kindOf(f.body) == .object_literal) {
                    const body_t = self.hir.typeOf(f.body);
                    return if (body_t != types.Primitive.none) body_t else null;
                }
                if (self.hir.kindOf(f.body) == .block_stmt) {
                    for (hir_mod.blockStmts(self.hir, f.body)) |stmt| {
                        if (self.hir.kindOf(stmt) != .return_stmt) continue;
                        const r = hir_mod.returnOf(self.hir, stmt);
                        if (r.value == hir_mod.none_node_id or self.hir.kindOf(r.value) != .object_literal) continue;
                        const ret_t = self.hir.typeOf(r.value);
                        return if (ret_t != types.Primitive.none) ret_t else null;
                    }
                }
                return null;
            }
        }
        return null;
    }

    /// True iff object-literal `obj_node` declares `name` as a set-only
    /// accessor (a setter with no matching getter). Spreading such a
    /// property reads `undefined` — the spread takes the GETTER's type,
    /// and an absent getter yields `undefined`. Mirrors tsc on
    /// `objectSpreadSetonlyAccessor.ts`.
    fn objectLiteralMemberIsSetOnlyAccessor(self: *Checker, obj_node: NodeId, name: hir_mod.StringId) CheckError!bool {
        if (self.hir.kindOf(obj_node) != .object_literal) return false;
        var has_setter = false;
        var has_getter = false;
        for (hir_mod.objectLiteralProps(self.hir, obj_node)) |prop| {
            if (self.hir.kindOf(prop) != .object_property) continue;
            const op = hir_mod.objectPropertyOf(self.hir, prop);
            if (op.value == hir_mod.none_node_id) continue;
            switch (self.hir.kindOf(op.value)) {
                .fn_decl, .fn_expr, .arrow_fn => {},
                else => continue,
            }
            const f = hir_mod.fnDeclOf(self.hir, op.value);
            if (!f.flags.is_getter and !f.flags.is_setter) continue;
            const is_computed = op.is_computed or self.nodeIsBracketedComputedName(op.key) or self.memberSourceLooksComputed(prop);
            const member_name = (try self.classMemberNameFromPropertyKey(op.key, is_computed)) orelse continue;
            if (member_name != name) continue;
            if (f.flags.is_getter) has_getter = true;
            if (f.flags.is_setter) has_setter = true;
        }
        return has_setter and !has_getter;
    }

    fn objectAccessorPropertyType(self: *Checker, value_node: NodeId, raw_t: TypeId) CheckError!TypeId {
        if (value_node == hir_mod.none_node_id) return raw_t;
        const kind = self.hir.kindOf(value_node);
        if (kind != .fn_decl and kind != .fn_expr and kind != .arrow_fn) return raw_t;
        const fnp = hir_mod.fnDeclOf(self.hir, value_node);
        if (fnp.flags.is_getter) {
            var getter_t = self.interner.signatureReturn(raw_t) orelse types.Primitive.any;
            if (getter_t == types.Primitive.any and fnp.return_type == hir_mod.none_node_id) {
                getter_t = (try self.firstReturnExpressionType(fnp.body)) orelse getter_t;
            }
            return getter_t;
        }
        if (fnp.flags.is_setter) {
            const params = self.interner.signatureParams(raw_t);
            return if (params.len > 0) params[0] else types.Primitive.any;
        }
        return raw_t;
    }

    fn functionContainsThis(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        const kind = self.hir.kindOf(node);
        if (kind != .fn_decl and kind != .fn_expr and kind != .arrow_fn) return self.expressionContainsThis(node);
        const f = hir_mod.fnDeclOf(self.hir, node);
        for (hir_mod.fnParams(self.hir, node)) |p| {
            if (self.hir.kindOf(p) != .parameter) continue;
            const pp = hir_mod.parameterOf(self.hir, p);
            if (self.expressionContainsThis(pp.default_value)) return true;
        }
        return self.expressionContainsThis(f.body);
    }

    fn reportSymbolOperator(self: *Checker, node: NodeId, op: []const u8) CheckError!void {
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "The '{s}' operator cannot be applied to type 'symbol'.",
            .{op},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.symbol_operator_not_allowed,
            .message = msg,
        });
    }

    /// Like `reportSymbolOperator` but anchors at an explicit byte
    /// position (used for parenthesized operands so the diagnostic
    /// column matches tsc, which anchors at the opening `(`).
    fn reportSymbolOperatorAt(self: *Checker, node: NodeId, pos: ?u32, op: []const u8) CheckError!void {
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "The '{s}' operator cannot be applied to type 'symbol'.",
            .{op},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = pos,
            .code = TsCodes.symbol_operator_not_allowed,
            .message = msg,
        });
    }

    /// Walk back over any immediately-preceding `(` characters so the
    /// anchor for symbol-operator diagnostics on parenthesized
    /// operands lands at the opening paren (matching tsc's column).
    fn symbolOperandAnchorPos(self: *Checker, node: NodeId) ?u32 {
        const src = self.source orelse return null;
        const span = self.hir.spanOf(node);
        if (span.start == 0 or span.start > src.len) return null;
        var i: usize = span.start;
        while (i > 0 and src[i - 1] == '(') : (i -= 1) {}
        if (i == span.start) return null;
        return @intCast(i);
    }

    /// True when `node` is the direct cond of an `if`/`while`/`do-while`
    /// statement ÃÂ¢ÃÂÃÂ in which case any leading `(` is part of the
    /// statement syntax, not the operand, and shouldn't be back-walked
    /// for diagnostic anchoring.
    fn nodeIsStatementCondOperand(self: *Checker, node: NodeId) bool {
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return false;
        return switch (self.hir.kindOf(parent)) {
            .if_stmt, .while_stmt, .do_while_stmt => true,
            else => false,
        };
    }

    fn reportArithmeticOperand(
        self: *Checker,
        node: NodeId,
        code: u32,
        msg: []const u8,
    ) CheckError!void {
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = self.symbolOperandAnchorPos(node),
            .code = code,
            .message = msg,
        });
    }

    /// True when `t` is symbol-like (the `symbol` primitive, a unique
    /// symbol, or a union with a symbol-like constituent). Used by the
    /// TS2731 symbol-to-string template check.
    fn typeIsSymbolLike(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.symbol_t) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_symbol) return true;
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeIsSymbolLike(member)) return true;
            }
        }
        return false;
    }

    fn checkTemplateLiteralExpression(self: *Checker, node: NodeId) CheckError!TypeId {
        const exprs = hir_mod.templateLiteralExprs(self.hir, node);
        for (exprs) |e| {
            const et = try self.checkExpression(e);
            // TS2731 — a symbol-like substitution coerces to a string at
            // runtime only via an explicit `String(...)` wrap.
            if (self.typeIsSymbolLike(et)) {
                try self.report(e, TsCodes.implicit_symbol_to_string, "Implicit conversion of a symbol to a string will fail at runtime. Consider wrapping this expression in 'String(...)'.");
            }
        }
        if (try self.templateLiteralConcreteString(node)) |sid| {
            return self.interner.internStringLiteral(sid) catch types.Primitive.string_t;
        }
        return types.Primitive.string_t;
    }

    fn templateExpressionAssignableToType(self: *Checker, node: NodeId, target_t: TypeId) CheckError!bool {
        var expr_node = node;
        while (true) {
            switch (self.hir.kindOf(expr_node)) {
                .as_expr, .satisfies_expr, .type_assertion, .non_null_expr => {
                    expr_node = hir_mod.asExpressionOf(self.hir, expr_node).expr;
                    continue;
                },
                else => {},
            }
            break;
        }
        if (self.hir.kindOf(expr_node) != .template_literal) return false;
        if (target_t < types.Primitive.first_dynamic or target_t >= self.interner.pool.typeCount()) return false;
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (!target_flags.is_template_literal) return false;
        const source_text_nodes = hir_mod.templateLiteralTexts(self.hir, expr_node);
        const source_exprs = hir_mod.templateLiteralExprs(self.hir, expr_node);
        const target_texts = self.interner.templateLiteralTexts(target_t);
        const target_parts = self.interner.templateLiteralTypes(target_t);
        if (source_text_nodes.len != source_exprs.len + 1) return false;
        var source_texts: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer source_texts.deinit(self.gpa);
        var source_parts: std.ArrayListUnmanaged(TypeId) = .empty;
        defer source_parts.deinit(self.gpa);
        try source_texts.ensureTotalCapacity(self.gpa, source_text_nodes.len);
        try source_parts.ensureTotalCapacity(self.gpa, source_exprs.len);
        for (source_text_nodes) |source_text_node| {
            if (self.hir.kindOf(source_text_node) != .literal_string) return false;
            const source_sid = try self.literalStringCookedId(source_text_node);
            source_texts.appendAssumeCapacity(source_sid);
        }
        for (source_exprs) |source_expr| {
            const source_t = self.hir.typeOf(source_expr);
            if (source_t == types.Primitive.none) return false;
            source_parts.appendAssumeCapacity(source_t);
        }
        return try self.templatePatternAssignableFrom(
            source_texts.items,
            source_parts.items,
            target_texts,
            target_parts,
            0,
            .{ .token = 0, .offset = 0 },
        );
    }

    fn finiteTemplateLiteralSourceAssignableToTarget(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        return (try self.finiteTemplateLiteralSourceAssignableResult(source_t, target_t)) orelse false;
    }

    fn finiteTemplateLiteralSourceAssignableResult(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!?bool {
        if (source_t < types.Primitive.first_dynamic or source_t >= self.interner.pool.typeCount()) return false;
        const source_flags = self.interner.pool.flagsOf(source_t);
        if (source_flags.is_union) {
            const members = try self.gpa.dupe(TypeId, self.interner.unionMembers(source_t));
            defer self.gpa.free(members);
            if (members.len == 0) return null;
            for (members) |member| {
                const sid = self.stringLiteralValueFromType(member) orelse return null;
                if (!try self.stringLiteralAssignableToType(sid, target_t)) return false;
            }
            return true;
        }
        if (!source_flags.is_template_literal or source_flags.is_intersection) return null;
        var concrete: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer concrete.deinit(self.gpa);
        if (!try self.expandFiniteTemplateLiteralStrings(source_t, &concrete, 512)) return null;
        if (concrete.items.len == 0) return null;
        for (concrete.items) |sid| {
            if (!try self.stringLiteralAssignableToType(sid, target_t)) return false;
        }
        return true;
    }

    const TemplateSourcePos = struct {
        token: usize,
        offset: usize,
    };

    fn templateLiteralSourceAssignableToTarget(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (source_t < types.Primitive.first_dynamic or source_t >= self.interner.pool.typeCount()) return false;
        if (target_t < types.Primitive.first_dynamic or target_t >= self.interner.pool.typeCount()) return false;
        const source_flags = self.interner.pool.flagsOf(source_t);
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (target_flags.is_type_parameter) {
            const raw_constraint_t = self.typeParameterConstraint(target_t) orelse return false;
            if (raw_constraint_t == target_t) return false;
            const constraint_t = (try self.reduceDisplayedAliasInstance(raw_constraint_t)) orelse raw_constraint_t;
            if (constraint_t == target_t) return false;
            if (constraint_t == types.Primitive.any or
                constraint_t == types.Primitive.unknown or
                constraint_t == types.Primitive.string_t)
            {
                return true;
            }
            if (constraint_t < types.Primitive.first_dynamic or constraint_t >= self.interner.pool.typeCount()) {
                return false;
            }
            return try self.templateLiteralSourceAssignableToTarget(source_t, constraint_t);
        }
        if (source_flags.is_union and target_flags.is_template_literal) {
            for (self.interner.unionMembers(source_t)) |member| {
                if (member >= self.interner.pool.typeCount()) return false;
                const member_flags = self.interner.pool.flagsOf(member);
                if (!member_flags.is_literal or !member_flags.is_string) return false;
                const lit = self.interner.literalOf(member);
                const sid = switch (lit) {
                    .string_lit => |value| value,
                    else => return false,
                };
                if (!try self.stringLiteralAssignableToType(sid, target_t)) return false;
            }
            return true;
        }
        if (source_flags.is_template_literal and target_flags.is_string_mapping) {
            return try self.templateLiteralSourceAssignableToStringMapping(source_t, target_t);
        }
        if (source_flags.is_string_mapping and target_flags.is_template_literal) {
            return try self.stringMappingSourceAssignableToTemplateLiteral(source_t, target_t);
        }
        if (source_flags.is_union or source_flags.is_intersection or target_flags.is_union or target_flags.is_intersection) return false;
        if (!source_flags.is_template_literal or !target_flags.is_template_literal) return false;
        if (source_t == target_t) return true;
        const source_texts = self.interner.templateLiteralTexts(source_t);
        const source_parts = self.interner.templateLiteralTypes(source_t);
        const target_texts = self.interner.templateLiteralTexts(target_t);
        const target_parts = self.interner.templateLiteralTypes(target_t);
        if (source_texts.len != source_parts.len + 1 or target_texts.len != target_parts.len + 1) return false;
        return try self.templatePatternAssignableFrom(
            source_texts,
            source_parts,
            target_texts,
            target_parts,
            0,
            .{ .token = 0, .offset = 0 },
        );
    }

    fn stringMappingSourceAssignableToTemplateLiteral(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        const payload = self.interner.stringMappingPayload(source_t);
        const mapped_source = (try self.applyStringMappingToTemplateLiteral(payload.kind, payload.inner)) orelse return false;
        return try self.templateLiteralSourceAssignableToTarget(mapped_source, target_t);
    }

    fn templateLiteralSourceAssignableToStringMapping(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        const payload = self.interner.stringMappingPayload(target_t);
        const mapped_source = (try self.applyStringMappingToTemplateLiteral(payload.kind, source_t)) orelse return false;
        if (mapped_source != source_t and !try self.templateLiteralSourceAssignableToTarget(source_t, mapped_source)) return false;
        if (payload.inner == types.Primitive.any or payload.inner == types.Primitive.unknown or payload.inner == types.Primitive.string_t) return true;
        if (payload.inner < self.interner.pool.typeCount() and self.interner.pool.flagsOf(payload.inner).is_template_literal) {
            return try self.templateLiteralSourceAssignableToTarget(source_t, payload.inner);
        }
        return self.engine.isAssignableTo(source_t, payload.inner) catch false;
    }

    fn templatePatternAssignableFrom(
        self: *Checker,
        source_texts: []const hir_mod.StringId,
        source_parts: []const TypeId,
        target_texts: []const hir_mod.StringId,
        target_parts: []const TypeId,
        target_index: usize,
        raw_pos: TemplateSourcePos,
    ) CheckError!bool {
        const pos = self.normalizeTemplateSourcePos(source_texts, source_parts, raw_pos);
        const target_text = self.string_interner.get(target_texts[target_index]);
        const after_text = self.matchTemplateSourceText(source_texts, source_parts, pos, target_text) orelse return false;
        if (target_index == target_parts.len) {
            return self.templateSourceAtEnd(source_texts, source_parts, after_text);
        }
        return try self.consumeTemplateSourceForPlaceholder(
            source_texts,
            source_parts,
            target_texts,
            target_parts,
            target_index,
            self.normalizeTemplateSourcePos(source_texts, source_parts, after_text),
            false,
        );
    }

    fn consumeTemplateSourceForPlaceholder(
        self: *Checker,
        source_texts: []const hir_mod.StringId,
        source_parts: []const TypeId,
        target_texts: []const hir_mod.StringId,
        target_parts: []const TypeId,
        target_index: usize,
        raw_pos: TemplateSourcePos,
        consumed: bool,
    ) CheckError!bool {
        const pos = self.normalizeTemplateSourcePos(source_texts, source_parts, raw_pos);
        const target_part = target_parts[target_index];
        const next_text = self.string_interner.get(target_texts[target_index + 1]);
        if (consumed or try self.templatePlaceholderAcceptsSlice(target_part, "")) {
            if (self.matchTemplateSourceText(source_texts, source_parts, pos, next_text) != null) {
                if (try self.templatePatternAssignableFrom(
                    source_texts,
                    source_parts,
                    target_texts,
                    target_parts,
                    target_index + 1,
                    pos,
                )) return true;
            }
        }

        const token_count = source_texts.len + source_parts.len;
        if (pos.token >= token_count) return false;
        if (pos.token % 2 == 0) {
            const text_index = pos.token / 2;
            const text = self.string_interner.get(source_texts[text_index]);
            if (pos.offset >= text.len) {
                return try self.consumeTemplateSourceForPlaceholder(
                    source_texts,
                    source_parts,
                    target_texts,
                    target_parts,
                    target_index,
                    .{ .token = pos.token + 1, .offset = 0 },
                    consumed,
                );
            }
            var end = pos.offset + 1;
            while (end <= text.len) : (end += 1) {
                if (!try self.templatePlaceholderAcceptsSlice(target_part, text[pos.offset..end])) continue;
                const next_pos: TemplateSourcePos = if (end == text.len)
                    .{ .token = pos.token + 1, .offset = 0 }
                else
                    .{ .token = pos.token, .offset = end };
                if (try self.consumeTemplateSourceForPlaceholder(
                    source_texts,
                    source_parts,
                    target_texts,
                    target_parts,
                    target_index,
                    next_pos,
                    true,
                )) return true;
            }
            return false;
        }

        const part_index = pos.token / 2;
        if (part_index >= source_parts.len) return false;
        if (!try self.templateSourcePartAssignableToPlaceholder(source_parts[part_index], target_part)) return false;
        return try self.consumeTemplateSourceForPlaceholder(
            source_texts,
            source_parts,
            target_texts,
            target_parts,
            target_index,
            .{ .token = pos.token + 1, .offset = 0 },
            true,
        );
    }

    fn normalizeTemplateSourcePos(
        self: *Checker,
        source_texts: []const hir_mod.StringId,
        source_parts: []const TypeId,
        raw_pos: TemplateSourcePos,
    ) TemplateSourcePos {
        var pos = raw_pos;
        const token_count = source_texts.len + source_parts.len;
        while (pos.token < token_count and pos.token % 2 == 0) {
            const text = self.string_interner.get(source_texts[pos.token / 2]);
            if (pos.offset < text.len) break;
            pos.token += 1;
            pos.offset = 0;
        }
        return pos;
    }

    fn templateSourceAtEnd(
        self: *Checker,
        source_texts: []const hir_mod.StringId,
        source_parts: []const TypeId,
        raw_pos: TemplateSourcePos,
    ) bool {
        const pos = self.normalizeTemplateSourcePos(source_texts, source_parts, raw_pos);
        return pos.token >= source_texts.len + source_parts.len;
    }

    fn matchTemplateSourceText(
        self: *Checker,
        source_texts: []const hir_mod.StringId,
        source_parts: []const TypeId,
        raw_pos: TemplateSourcePos,
        target_text: []const u8,
    ) ?TemplateSourcePos {
        var pos = raw_pos;
        var consumed: usize = 0;
        const token_count = source_texts.len + source_parts.len;
        while (consumed < target_text.len) {
            pos = self.normalizeTemplateSourcePos(source_texts, source_parts, pos);
            if (pos.token >= token_count or pos.token % 2 == 1) return null;
            const text = self.string_interner.get(source_texts[pos.token / 2]);
            if (pos.offset >= text.len) return null;
            const available = text.len - pos.offset;
            const needed = target_text.len - consumed;
            const take = @min(available, needed);
            if (!std.mem.eql(u8, text[pos.offset .. pos.offset + take], target_text[consumed .. consumed + take])) return null;
            consumed += take;
            pos.offset += take;
            if (pos.offset == text.len) {
                pos.token += 1;
                pos.offset = 0;
            }
        }
        return self.normalizeTemplateSourcePos(source_texts, source_parts, pos);
    }

    fn templateSourcePartAssignableToPlaceholder(self: *Checker, source_part: TypeId, target_part: TypeId) CheckError!bool {
        if (target_part == types.Primitive.any or target_part == types.Primitive.unknown or target_part == types.Primitive.string_t) return true;
        if (source_part == types.Primitive.any) return true;
        if (source_part == target_part) return true;
        if (source_part >= self.interner.pool.typeCount()) return false;
        const source_flags = self.interner.pool.flagsOf(source_part);
        if (source_flags.is_union) {
            for (self.interner.unionMembers(source_part)) |member| {
                if (!try self.templateSourcePartAssignableToPlaceholder(member, target_part)) return false;
            }
            return true;
        }
        if (target_part < types.Primitive.first_dynamic or target_part >= self.interner.pool.typeCount()) {
            if (source_flags.is_type_parameter) {
                const constraint = self.typeParameterConstraint(source_part) orelse return target_part == types.Primitive.string_t;
                if (constraint == source_part) return false;
                return try self.templateSourcePartAssignableToPlaceholder(constraint, target_part);
            }
            if (target_part == types.Primitive.number_t) return source_part == types.Primitive.number_t or (source_flags.is_literal and source_flags.is_number);
            if (target_part == types.Primitive.boolean_t) return source_part == types.Primitive.boolean_t or (source_flags.is_literal and source_flags.is_boolean);
            if (target_part == types.Primitive.bigint_t) return source_part == types.Primitive.bigint_t or (source_flags.is_literal and source_flags.is_bigint);
            return false;
        }
        const target_flags = self.interner.pool.flagsOf(target_part);
        if (target_flags.is_union) {
            if (source_flags.is_union) {
                for (self.interner.unionMembers(source_part)) |member| {
                    if (!try self.templateSourcePartAssignableToPlaceholder(member, target_part)) return false;
                }
                return true;
            }
            for (self.interner.unionMembers(target_part)) |member| {
                if (try self.templateSourcePartAssignableToPlaceholder(source_part, member)) return true;
            }
            return false;
        }
        if (source_flags.is_literal and source_flags.is_string) {
            const lit = self.interner.literalOf(source_part);
            return switch (lit) {
                .string_lit => |sid| try self.templatePlaceholderAcceptsSlice(target_part, self.string_interner.get(sid)),
                else => false,
            };
        }
        if (source_flags.is_literal and source_flags.is_number) return target_part == types.Primitive.number_t or (self.engine.isAssignableTo(source_part, target_part) catch false);
        if (source_flags.is_literal and source_flags.is_boolean) return target_part == types.Primitive.boolean_t or (self.engine.isAssignableTo(source_part, target_part) catch false);
        if (source_flags.is_literal and source_flags.is_bigint) return target_part == types.Primitive.bigint_t or (self.engine.isAssignableTo(source_part, target_part) catch false);
        if (target_flags.is_type_parameter) {
            if (self.engine.isAssignableTo(source_part, target_part) catch false) return true;
            const constraint = self.typeParameterConstraint(target_part) orelse return true;
            if (constraint == target_part) return true;
            return try self.templateSourcePartAssignableToPlaceholder(source_part, constraint);
        }
        if (source_flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(source_part) orelse return target_part == types.Primitive.string_t;
            if (constraint == source_part) return false;
            return try self.templateSourcePartAssignableToPlaceholder(constraint, target_part);
        }
        return self.engine.isAssignableTo(source_part, target_part) catch false;
    }

    fn expandFiniteTemplateLiteralStrings(
        self: *Checker,
        t: TypeId,
        out: *std.ArrayListUnmanaged(hir_mod.StringId),
        limit: usize,
    ) CheckError!bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_template_literal) return false;
        const texts = self.interner.templateLiteralTexts(t);
        const parts = self.interner.templateLiteralTypes(t);
        if (texts.len != parts.len + 1) return false;

        var strings: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer strings.deinit(self.gpa);
        try strings.append(self.gpa, texts[0]);

        for (parts, 0..) |part, i| {
            var part_strings: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
            defer part_strings.deinit(self.gpa);
            if (!try self.expandFiniteStringLikeType(part, &part_strings, limit)) return false;
            if (part_strings.items.len == 0) return false;

            var next: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
            errdefer next.deinit(self.gpa);
            const tail = self.string_interner.get(texts[i + 1]);
            for (strings.items) |prefix_sid| {
                const prefix = self.string_interner.get(prefix_sid);
                for (part_strings.items) |middle_sid| {
                    const middle = self.string_interner.get(middle_sid);
                    if (next.items.len >= limit) {
                        next.deinit(self.gpa);
                        return false;
                    }
                    const combined = try std.fmt.allocPrint(self.gpa, "{s}{s}{s}", .{ prefix, middle, tail });
                    defer self.gpa.free(combined);
                    const sid = self.string_interner.intern(combined) catch return error.OutOfMemory;
                    try next.append(self.gpa, sid);
                }
            }
            strings.deinit(self.gpa);
            strings = next;
        }

        try out.appendSlice(self.gpa, strings.items);
        return true;
    }

    fn expandFiniteStringLikeType(
        self: *Checker,
        t: TypeId,
        out: *std.ArrayListUnmanaged(hir_mod.StringId),
        limit: usize,
    ) CheckError!bool {
        if (out.items.len >= limit) return false;
        if (self.stringLiteralValueFromType(t)) |sid| {
            try out.append(self.gpa, sid);
            return true;
        }
        if (t == types.Primitive.false_lit or t == types.Primitive.boolean_t) {
            const sid = self.string_interner.intern("false") catch return error.OutOfMemory;
            try out.append(self.gpa, sid);
            if (t != types.Primitive.boolean_t) return true;
        }
        if (t == types.Primitive.true_lit or t == types.Primitive.boolean_t) {
            const sid = self.string_interner.intern("true") catch return error.OutOfMemory;
            try out.append(self.gpa, sid);
            return true;
        }
        if (t == types.Primitive.null_t) {
            const sid = self.string_interner.intern("null") catch return error.OutOfMemory;
            try out.append(self.gpa, sid);
            return true;
        }
        if (t == types.Primitive.undefined_t) {
            const sid = self.string_interner.intern("undefined") catch return error.OutOfMemory;
            try out.append(self.gpa, sid);
            return true;
        }
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!try self.expandFiniteStringLikeType(member, out, limit)) return false;
                if (out.items.len > limit) return false;
            }
            return true;
        }
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return try self.expandFiniteStringLikeType(constraint, out, limit);
        }
        if (flags.is_string_mapping) {
            const payload = self.interner.stringMappingPayload(t);
            var inner: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
            defer inner.deinit(self.gpa);
            if (!try self.expandFiniteStringLikeType(payload.inner, &inner, limit)) return false;
            for (inner.items) |sid| {
                if (out.items.len >= limit) return false;
                const raw = self.string_interner.get(sid);
                const mapped = try self.gpa.alloc(u8, raw.len);
                defer self.gpa.free(mapped);
                @memcpy(mapped, raw);
                applyStringMappingToBuffer(payload.kind, mapped);
                const mapped_sid = self.string_interner.intern(mapped) catch return error.OutOfMemory;
                try out.append(self.gpa, mapped_sid);
            }
            return true;
        }
        return false;
    }

    fn templateLiteralConcreteString(self: *Checker, node: NodeId) CheckError!?hir_mod.StringId {
        const texts = hir_mod.templateLiteralTexts(self.hir, node);
        const exprs = hir_mod.templateLiteralExprs(self.hir, node);
        if (texts.len != exprs.len + 1) return null;
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        defer buf.deinit(self.gpa);
        for (texts, 0..) |text_node, i| {
            if (self.hir.kindOf(text_node) != .literal_string) return null;
            const text = hir_mod.literalStringOf(self.hir, text_node);
            try self.appendCookedStringText(self.string_interner.get(text.value), &buf);
            if (i < exprs.len) {
                if (!try self.appendTemplateSubstitutionString(exprs[i], &buf)) return null;
            }
        }
        return self.string_interner.intern(buf.items) catch return error.OutOfMemory;
    }

    fn templateLiteralConstType(self: *Checker, node: NodeId, fallback: TypeId) CheckError!TypeId {
        if (try self.templateLiteralConcreteString(node)) |sid| {
            return self.interner.internStringLiteral(sid) catch return error.OutOfMemory;
        }

        const texts = hir_mod.templateLiteralTexts(self.hir, node);
        const exprs = hir_mod.templateLiteralExprs(self.hir, node);
        if (texts.len != exprs.len + 1) return fallback;

        var text_ids: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer text_ids.deinit(self.gpa);
        var type_parts: std.ArrayListUnmanaged(TypeId) = .empty;
        defer type_parts.deinit(self.gpa);
        var concrete_buf: std.ArrayListUnmanaged(u8) = .empty;
        defer concrete_buf.deinit(self.gpa);
        var all_concrete = true;

        for (texts, 0..) |text_node, i| {
            if (self.hir.kindOf(text_node) != .literal_string) return fallback;
            const lit = hir_mod.literalStringOf(self.hir, text_node);
            try text_ids.append(self.gpa, lit.value);
            try self.appendCookedStringText(self.string_interner.get(lit.value), &concrete_buf);

            if (i < exprs.len) {
                var part_t = self.hir.typeOf(exprs[i]);
                if (part_t == types.Primitive.none) part_t = try self.checkExpression(exprs[i]);
                try type_parts.append(self.gpa, part_t);
                if (all_concrete) {
                    if (!try self.appendTemplateTypeSubstitutionString(part_t, &concrete_buf)) {
                        all_concrete = false;
                    }
                }
            }
        }

        if (all_concrete) {
            const sid = self.string_interner.intern(concrete_buf.items) catch return error.OutOfMemory;
            return self.interner.internStringLiteral(sid) catch return error.OutOfMemory;
        }
        if (try self.finiteTemplateLiteralConstUnion(text_ids.items, type_parts.items)) |finite_t| return finite_t;
        return self.interner.internTemplateLiteral(text_ids.items, type_parts.items) catch return error.OutOfMemory;
    }

    fn finiteTemplateLiteralConstUnion(
        self: *Checker,
        text_ids: []const hir_mod.StringId,
        type_parts: []const TypeId,
    ) CheckError!?TypeId {
        if (text_ids.len != type_parts.len + 1) return null;
        var members: std.ArrayListUnmanaged(TypeId) = .empty;
        defer members.deinit(self.gpa);
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        defer buf.deinit(self.gpa);
        if (!try self.expandFiniteTemplateLiteralConstUnion(text_ids, type_parts, 0, &buf, &members)) return null;
        if (members.items.len == 0 or members.items.len > 32) return null;
        if (members.items.len == 1) return members.items[0];
        return self.interner.internUnion(members.items) catch return error.OutOfMemory;
    }

    fn expandFiniteTemplateLiteralConstUnion(
        self: *Checker,
        text_ids: []const hir_mod.StringId,
        type_parts: []const TypeId,
        index: usize,
        buf: *std.ArrayListUnmanaged(u8),
        members: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!bool {
        const before_text = buf.items.len;
        try self.appendCookedStringText(self.string_interner.get(text_ids[index]), buf);
        if (index == type_parts.len) {
            const sid = self.string_interner.intern(buf.items) catch return error.OutOfMemory;
            const lit_t = self.interner.internStringLiteral(sid) catch return error.OutOfMemory;
            try members.append(self.gpa, lit_t);
            buf.shrinkRetainingCapacity(before_text);
            return members.items.len <= 32;
        }

        const part_t = type_parts[index];
        if (part_t == types.Primitive.boolean_t) {
            const bool_options = [_][]const u8{ "false", "true" };
            for (bool_options[0..]) |option| {
                const before_option = buf.items.len;
                try buf.appendSlice(self.gpa, option);
                if (!try self.expandFiniteTemplateLiteralConstUnion(text_ids, type_parts, index + 1, buf, members)) {
                    buf.shrinkRetainingCapacity(before_text);
                    return false;
                }
                buf.shrinkRetainingCapacity(before_option);
            }
        } else if (part_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(part_t).is_union) {
            const options = try self.gpa.dupe(TypeId, self.interner.unionMembers(part_t));
            defer self.gpa.free(options);
            for (options) |option_t| {
                const before_option = buf.items.len;
                if (!try self.appendTemplateTypeSubstitutionString(option_t, buf)) {
                    buf.shrinkRetainingCapacity(before_text);
                    return false;
                }
                if (!try self.expandFiniteTemplateLiteralConstUnion(text_ids, type_parts, index + 1, buf, members)) {
                    buf.shrinkRetainingCapacity(before_text);
                    return false;
                }
                buf.shrinkRetainingCapacity(before_option);
            }
        } else {
            const before_part = buf.items.len;
            if (!try self.appendTemplateTypeSubstitutionString(part_t, buf)) {
                buf.shrinkRetainingCapacity(before_text);
                return false;
            }
            if (!try self.expandFiniteTemplateLiteralConstUnion(text_ids, type_parts, index + 1, buf, members)) {
                buf.shrinkRetainingCapacity(before_text);
                return false;
            }
            buf.shrinkRetainingCapacity(before_part);
        }
        buf.shrinkRetainingCapacity(before_text);
        return true;
    }

    fn appendTemplateTypeSubstitutionString(
        self: *Checker,
        t: TypeId,
        out: *std.ArrayListUnmanaged(u8),
    ) CheckError!bool {
        if (t == types.Primitive.true_lit) {
            try out.appendSlice(self.gpa, "true");
            return true;
        }
        if (t == types.Primitive.false_lit) {
            try out.appendSlice(self.gpa, "false");
            return true;
        }
        if (t == types.Primitive.null_t) {
            try out.appendSlice(self.gpa, "null");
            return true;
        }
        if (t == types.Primitive.undefined_t) {
            try out.appendSlice(self.gpa, "undefined");
            return true;
        }
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        // Union and intersection flags aggregate their members' literal bits,
        // but their payload describes a type container, not one literal.
        if (flags.is_union or flags.is_intersection or !flags.is_literal) return false;
        const lit = self.interner.literalOfOrNull(t) orelse return false;
        switch (lit) {
            .string_lit => |sid| try self.appendCookedStringText(self.string_interner.get(sid), out),
            .number_lit => |bits| {
                const v = @as(f64, @bitCast(bits));
                if (@trunc(v) == v and v >= @as(f64, @floatFromInt(std.math.minInt(i64))) and v <= @as(f64, @floatFromInt(std.math.maxInt(i64)))) {
                    const as_int: i64 = @intFromFloat(v);
                    const text = try std.fmt.allocPrint(self.gpa, "{d}", .{as_int});
                    defer self.gpa.free(text);
                    try out.appendSlice(self.gpa, text);
                } else {
                    const text = try std.fmt.allocPrint(self.gpa, "{d}", .{v});
                    defer self.gpa.free(text);
                    try out.appendSlice(self.gpa, text);
                }
            },
            .boolean_lit => |b| try out.appendSlice(self.gpa, if (b) "true" else "false"),
            .bigint_lit => |sid| try out.appendSlice(self.gpa, self.string_interner.get(sid)),
        }
        return true;
    }

    fn appendTemplateSubstitutionString(
        self: *Checker,
        node: NodeId,
        out: *std.ArrayListUnmanaged(u8),
    ) CheckError!bool {
        switch (self.hir.kindOf(node)) {
            .literal_string => {
                const lit = hir_mod.literalStringOf(self.hir, node);
                try self.appendCookedStringText(self.string_interner.get(lit.value), out);
                return true;
            },
            .literal_number => {
                const v = hir_mod.literalNumberOf(self.hir, node);
                if (@trunc(v) == v and v >= @as(f64, @floatFromInt(std.math.minInt(i64))) and v <= @as(f64, @floatFromInt(std.math.maxInt(i64)))) {
                    const as_int: i64 = @intFromFloat(v);
                    const text = try std.fmt.allocPrint(self.gpa, "{d}", .{as_int});
                    defer self.gpa.free(text);
                    try out.appendSlice(self.gpa, text);
                } else {
                    const text = try std.fmt.allocPrint(self.gpa, "{d}", .{v});
                    defer self.gpa.free(text);
                    try out.appendSlice(self.gpa, text);
                }
                return true;
            },
            .literal_bigint => {
                const lit = hir_mod.literalBigIntOf(self.hir, node);
                try out.appendSlice(self.gpa, self.string_interner.get(lit.digits));
                return true;
            },
            .literal_bool => {
                try out.appendSlice(self.gpa, if (hir_mod.literalBoolOf(self.hir, node)) "true" else "false");
                return true;
            },
            .literal_null => {
                try out.appendSlice(self.gpa, "null");
                return true;
            },
            .literal_undefined => {
                try out.appendSlice(self.gpa, "undefined");
                return true;
            },
            .unary_op => {
                const u = hir_mod.unaryOf(self.hir, node);
                if (u.op == .neg and self.hir.kindOf(u.operand) == .literal_number) {
                    try out.append(self.gpa, '-');
                    return try self.appendTemplateSubstitutionString(u.operand, out);
                }
                return false;
            },
            .member_access => {
                const m = hir_mod.memberOf(self.hir, node);
                if (self.hir.kindOf(m.object) != .identifier) return false;
                const obj = hir_mod.identifierOf(self.hir, m.object);
                const lit_t = self.constEnumLiteralAccess(obj.name, m.name, node) orelse
                    self.enumMemberStringLiteralAccess(obj.name, m.name, node) orelse
                    return false;
                if (lit_t < types.Primitive.first_dynamic or lit_t >= self.interner.pool.typeCount()) return false;
                const flags = self.interner.pool.flagsOf(lit_t);
                if (!flags.is_literal) return false;
                switch (self.interner.literalOf(lit_t)) {
                    .string_lit => |sid| try self.appendCookedStringText(self.string_interner.get(sid), out),
                    .number_lit => |bits| {
                        const v = @as(f64, @bitCast(bits));
                        const text = try std.fmt.allocPrint(self.gpa, "{d}", .{v});
                        defer self.gpa.free(text);
                        try out.appendSlice(self.gpa, text);
                    },
                    .boolean_lit => |b| try out.appendSlice(self.gpa, if (b) "true" else "false"),
                    .bigint_lit => return false,
                }
                return true;
            },
            .as_expr, .satisfies_expr, .type_assertion, .non_null_expr => {
                const a = hir_mod.asExpressionOf(self.hir, node);
                return try self.appendTemplateSubstitutionString(a.expr, out);
            },
            else => return false,
        }
    }

    fn isArithmeticOperandAllowed(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return true;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_never) return true;
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.isArithmeticOperandAllowed(member)) return false;
            }
            return true;
        }
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.isArithmeticOperandAllowed(member)) return true;
            }
            return false;
        }
        if (!self.strict_flags.strict_null_checks and (f.is_null or f.is_undefined)) return true;
        return f.is_number or f.is_bigint;
    }

    fn compoundAdditionAllowsNullish(self: *Checker, lhs: TypeId) bool {
        // Upstream tsc emits TS18050 on the literal-nullish RHS of a
        // compound-addition assignment when the LHS is a concrete
        // arithmetic operand (number/bigint/enum) ÃÂ¢ÃÂÃÂ `n += null` and
        // `e += null` fire TS18050. Only `any`-like and string-like
        // targets absorb a nullish RHS (string concat coerces null
        // to `"null"`). Mirrors fixtures
        // `compoundAdditionAssignmentLHSCanBeAssigned.ts(32,7)` /
        // `(33,7)` / `(39,7)` / `(40,7)` where x3 / x4 fire TS18050
        // while x2 (string) stays clean.
        if (self.typeIsAnyLike(lhs)) return true;
        if (self.typeMaybeStringLike(lhs)) return true;
        return false;
    }

    fn compoundAdditionAssignableBack(self: *Checker, result_t: TypeId, target_t: TypeId) CheckError!bool {
        if (self.typeIsAnyLike(result_t) or self.typeIsAnyLike(target_t)) return true;
        // A string result is assignable back to any string-like target
        // fast (string/literal/template/union). For other targets fall
        // through to general assignability — `string` is still assignable
        // to e.g. `{}`/`object`, so `x6 += ''` on `var x6: {}` must not
        // draw TS2322. Mirrors `compoundAdditionAssignmentLHSCanBeAssigned`.
        if (result_t == types.Primitive.string_t and self.typeMaybeStringLike(target_t)) return true;
        if (result_t == types.Primitive.number_t and self.isArithmeticOperandAllowed(target_t)) return true;
        return self.engine.isAssignableTo(result_t, target_t) catch true;
    }

    fn checkCompoundAdditionAssignment(
        self: *Checker,
        node: NodeId,
        target: NodeId,
        value: NodeId,
        target_t: TypeId,
        value_t: TypeId,
    ) CheckError!void {
        if (self.typeContainsSymbol(target_t) or self.typeContainsSymbol(value_t)) {
            // tsc emits TS2469 ("The '+=' operator cannot be applied
            // to type 'symbol'.") whenever one operand is symbol and
            // the other is string-like ÃÂ¢ÃÂÃÂ string concat would otherwise
            // be valid for `+`, so the violation is the symbol side
            // specifically. Anchor at the symbol-typed operand.
            // Mirrors `symbolType12.ts(11,1)` (`s += ""`) and `(12,8)`
            // (`str += s` ÃÂ¢ÃÂÃÂ anchored at `s`).
            const target_has_symbol = self.typeContainsSymbol(target_t);
            const value_has_symbol = self.typeContainsSymbol(value_t);
            const target_is_string_like = self.typeMaybeStringLike(target_t);
            const value_is_string_like = self.typeMaybeStringLike(value_t);
            if ((target_has_symbol and value_is_string_like) or
                (value_has_symbol and target_is_string_like))
            {
                const anchor_node = if (target_has_symbol) target else value;
                const pos = self.symbolOperandAnchorPos(anchor_node);
                try self.reportSymbolOperatorAt(anchor_node, pos, "+=");
                return;
            }
            // Otherwise prefer the type-rich
            // `Operator '+=' cannot be applied to types 'A' and 'B'.`
            // (TS2365) when both operand types render as simple names.
            // Mirrors `symbolType12.ts(9,1)` / `(10,1)` for `s += s`
            // and `s += 0`.
            if (try self.simpleDiagnosticTypeName(target_t)) |t_name| {
                if (try self.simpleDiagnosticTypeName(value_t)) |v_name| {
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Operator '+=' cannot be applied to types '{s}' and '{s}'.",
                        .{ t_name, v_name },
                    );
                    try self.diagnostics.append(self.gpa, .{
                        .node = node,
                        .code = TsCodes.operator_cannot_be_applied,
                        .message = msg,
                    });
                    return;
                }
            }
            try self.reportSymbolOperator(node, "+=");
            return;
        }
        // tsc skips TS18050 when the RHS is an untyped, uninitialized
        // variable (`var v; x += v;` ÃÂ¢ÃÂÃÂ v is `any` in tsc's flow even
        // though our inference widens it to `undefined`). Mirrors the
        // `*=`/`-=`/etc arm above and matches `compoundAssignmentLHSIsReference`.
        const value_is_untyped_uninit = self.hir.kindOf(value) == .identifier and
            self.identifierIsUntypedUninitializedVar(value);
        if (!value_is_untyped_uninit and
            self.typeIsExactNullish(value_t) and
            !self.compoundAdditionAllowsNullish(target_t))
        {
            try self.reportNullishRelationalOperand(value, value_t);
            return;
        }

        const apparent_target_t = (try self.indexedAccessBaseConstraint(target_t, 0)) orelse target_t;
        const result_t: TypeId = blk: {
            if (self.typeIsAnyLike(target_t) or self.typeIsAnyLike(value_t)) break :blk types.Primitive.any;
            if (self.typeMaybeStringLike(apparent_target_t) or self.typeMaybeStringLike(value_t)) break :blk types.Primitive.string_t;
            if (self.isArithmeticOperandAllowed(apparent_target_t) and self.isArithmeticOperandAllowed(value_t)) break :blk types.Primitive.number_t;
            // Prefer tsc's type-rich form
            // `Operator '+=' cannot be applied to types 'A' and 'B'.`
            // when both endpoints have a simple display name; fall
            // back to the generic `ÃÂ¢ÃÂÃÂ¦to these operand types.` form.
            // Mirrors `compoundAdditionAssignmentWithInvalidOperands.ts`.
            if (try self.simpleDiagnosticTypeName(target_t)) |t_name| {
                if (try self.simpleDiagnosticTypeName(value_t)) |v_name| {
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Operator '+=' cannot be applied to types '{s}' and '{s}'.",
                        .{ t_name, v_name },
                    );
                    try self.diagnostics.append(self.gpa, .{
                        .node = node,
                        .code = TsCodes.operator_cannot_be_applied,
                        .message = msg,
                    });
                    return;
                }
            }
            try self.report(node, TsCodes.operator_cannot_be_applied, "Operator '+=' cannot be applied to these operand types.");
            return;
        };

        if (!try self.compoundAdditionAssignableBack(result_t, target_t)) {
            try self.reportTypeNotAssignable(target, result_t, target_t, "Type is not assignable to target type.");
        }
    }

    /// Locate the `=` token inside an `x = <init>` assignment node used
    /// as the spread element of `[..."x = init"]`. Returns the byte
    /// offset of the `=` so TS1186 anchors at the operator (matching
    /// `restElementWithInitializer2.ts(3,7)`), or null when source
    /// isn't available / the scan fails so callers fall back to the
    /// assignment span start.
    fn restElementInitializerEqualPos(self: *Checker, assign_node: NodeId) ?u32 {
        if (self.source == null) return null;
        if (self.hir.kindOf(assign_node) != .assignment) return null;
        const a = hir_mod.assignmentOf(self.hir, assign_node);
        const src = self.source.?;
        const target_span = self.hir.spanOf(a.target);
        const value_span = self.hir.spanOf(a.value);
        const scan_start: usize = @intCast(target_span.end);
        const scan_end: usize = @min(src.len, @as(usize, @intCast(value_span.start)));
        if (scan_start >= scan_end) return null;
        var i = scan_start;
        while (i < scan_end) : (i += 1) {
            if (src[i] == '=') return @intCast(i);
        }
        return null;
    }

    fn reportPropertyDoesNotExist(self: *Checker, node: NodeId, name: hir_mod.StringId) CheckError!void {
        const name_str = self.string_interner.get(name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Property '{s}' does not exist on type.",
            .{name_str},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = self.memberAccessNamePos(node),
            .code = TsCodes.property_does_not_exist,
            .message = msg,
        });
    }

    fn reportPropertyDoesNotExistOnTypeText(
        self: *Checker,
        node: NodeId,
        name: hir_mod.StringId,
        target_text: []const u8,
    ) CheckError!void {
        const name_str = self.string_interner.get(name);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Property '{s}' does not exist on type '{s}'.",
            .{ name_str, target_text },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = self.memberAccessNamePos(node),
            .code = TsCodes.property_does_not_exist,
            .message = msg,
        });
    }

    fn assignmentTargetMissingMemberReportText(
        self: *Checker,
        access_node: NodeId,
        receiver_node: NodeId,
        current_t: TypeId,
    ) ?[]const u8 {
        _ = current_t;
        const parent = self.hir.parentOf(access_node);
        if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .assignment) return null;
        if (hir_mod.assignmentOf(self.hir, parent).target != access_node) return null;
        if (receiver_node == hir_mod.none_node_id or self.hir.kindOf(receiver_node) != .identifier) return null;
        const text = self.visibleAnnotatedIdentifierTypeText(receiver_node) orelse return null;
        if (std.mem.indexOfScalar(u8, text, '|') == null) return null;
        return text;
    }

    fn checkedJsObjectExpandoReceiverDisplay(
        self: *Checker,
        receiver_node: NodeId,
        current_t: TypeId,
    ) ?[]const u8 {
        if (!self.sourceHasCheckJsDirective() or
            receiver_node == hir_mod.none_node_id or
            self.hir.kindOf(receiver_node) != .identifier or
            !self.typeIsEmptyObjectType(current_t))
        {
            return null;
        }
        const id = hir_mod.identifierOf(self.hir, receiver_node);
        const decl = self.findLocalValueDeclBeforeExpression(receiver_node, id.name) orelse return null;
        const kind = self.hir.kindOf(decl);
        if (kind != .var_decl and kind != .let_decl and kind != .const_decl) return null;
        const payload = hir_mod.varDeclOf(self.hir, decl);
        if (payload.init == hir_mod.none_node_id or self.hir.kindOf(payload.init) != .object_literal) return null;
        return std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "typeof {s}",
            .{self.string_interner.get(id.name)},
        ) catch null;
    }

    fn instanceofUnionNarrowDisplayForMember(
        self: *Checker,
        node: NodeId,
        receiver: NodeId,
    ) CheckError!?[]const u8 {
        if (receiver == hir_mod.none_node_id or self.hir.kindOf(receiver) != .identifier) return null;
        const annotation = self.visibleAnnotatedIdentifierTypeText(receiver) orelse return null;
        if (!std.mem.eql(u8, std.mem.trim(u8, annotation, " \t\r\n"), "any")) return null;
        const receiver_name = hir_mod.identifierOf(self.hir, receiver).name;

        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            if (self.hir.kindOf(cur) != .if_stmt) continue;
            const statement = hir_mod.ifOf(self.hir, cur);
            if (!self.nodeIsAncestorOf(statement.then_branch, node)) continue;
            if (self.hir.kindOf(statement.cond) != .binary_op) continue;
            const condition = hir_mod.binopOf(self.hir, statement.cond);
            if (condition.op != .instanceof or self.hir.kindOf(condition.lhs) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, condition.lhs).name != receiver_name) continue;
            return try self.instanceofUnionTargetDisplayText(condition.rhs);
        }
        return null;
    }

    fn instanceofNoNarrowDisplayForMember(
        self: *Checker,
        node: NodeId,
        receiver: NodeId,
    ) CheckError!?[]const u8 {
        if (receiver == hir_mod.none_node_id or self.hir.kindOf(receiver) != .identifier) return null;
        const annotation = self.visibleAnnotatedIdentifierTypeText(receiver) orelse return null;
        if (std.mem.indexOfScalar(u8, annotation, '|') == null) return null;
        const receiver_name = hir_mod.identifierOf(self.hir, receiver).name;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            if (self.hir.kindOf(cur) != .if_stmt) continue;
            const statement = hir_mod.ifOf(self.hir, cur);
            if (!self.nodeIsAncestorOf(statement.then_branch, node)) continue;
            if (self.hir.kindOf(statement.cond) != .binary_op) continue;
            const condition = hir_mod.binopOf(self.hir, statement.cond);
            if (condition.op != .instanceof or self.hir.kindOf(condition.lhs) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, condition.lhs).name != receiver_name) continue;
            const target = (try self.directInstanceofTargetType(condition.rhs)) orelse return null;
            if (self.typeIsAnyLike(target)) {
                const normalized = try self.normalizedTypeAnnotationText(annotation);
                const suffix = " | string";
                if (std.mem.endsWith(u8, normalized, suffix)) {
                    return try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "string | {s}",
                        .{normalized[0 .. normalized.len - suffix.len]},
                    );
                }
                return normalized;
            }
        }
        return null;
    }

    fn instanceofGenericNarrowDisplayForMember(
        self: *Checker,
        node: NodeId,
        receiver: NodeId,
    ) CheckError!?[]const u8 {
        if (receiver == hir_mod.none_node_id or self.hir.kindOf(receiver) != .identifier) return null;
        const annotation = self.visibleAnnotatedIdentifierTypeNode(receiver) orelse return null;
        if (self.hir.kindOf(annotation) != .union_type) return null;
        const receiver_name = hir_mod.identifierOf(self.hir, receiver).name;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            if (self.hir.kindOf(cur) != .if_stmt) continue;
            const statement = hir_mod.ifOf(self.hir, cur);
            if (!self.nodeIsAncestorOf(statement.then_branch, node)) continue;
            if (self.hir.kindOf(statement.cond) != .binary_op) continue;
            const condition = hir_mod.binopOf(self.hir, statement.cond);
            if (condition.op != .instanceof or self.hir.kindOf(condition.lhs) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, condition.lhs).name != receiver_name) continue;
            const target_base = (try self.instanceofGenericTargetBaseName(condition.rhs)) orelse return null;
            for (hir_mod.unionTypeMembers(self.hir, annotation)) |member_node| {
                if (self.hir.kindOf(member_node) != .type_ref or hir_mod.typeRefArgs(self.hir, member_node).len == 0) continue;
                const ref = hir_mod.typeRefOf(self.hir, member_node);
                if (ref.name != target_base) continue;
                return try self.normalizedTypeAnnotationText(self.nodeSourceTextOrEmpty(member_node));
            }
        }
        return null;
    }

    fn instanceofFalseBranchDisplayForMember(
        self: *Checker,
        node: NodeId,
        receiver: NodeId,
    ) CheckError!?[]const u8 {
        if (receiver == hir_mod.none_node_id or self.hir.kindOf(receiver) != .identifier) return null;
        const annotation_node = self.visibleAnnotatedIdentifierTypeNode(receiver) orelse return null;
        if (self.hir.kindOf(annotation_node) != .union_type) return null;
        const receiver_name = hir_mod.identifierOf(self.hir, receiver).name;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            if (self.hir.kindOf(cur) != .if_stmt) continue;
            const statement = hir_mod.ifOf(self.hir, cur);
            if (statement.else_branch == hir_mod.none_node_id or
                !self.nodeIsAncestorOf(statement.else_branch, node)) continue;
            if (!try self.falseInstanceofConditionPreservesClassUnion(statement.cond, receiver_name)) continue;
            return try self.canonicalNamedUnionAnnotationText(annotation_node);
        }
        return null;
    }

    fn falseInstanceofConditionPreservesClassUnion(
        self: *Checker,
        condition: NodeId,
        receiver_name: hir_mod.StringId,
    ) CheckError!bool {
        if (self.hir.kindOf(condition) == .binary_op) {
            const binary = hir_mod.binopOf(self.hir, condition);
            if (binary.op != .instanceof or self.hir.kindOf(binary.lhs) != .identifier) return false;
            if (hir_mod.identifierOf(self.hir, binary.lhs).name != receiver_name) return false;
            const target = (try self.directInstanceofTargetType(binary.rhs)) orelse return false;
            return self.classNameForInstanceType(target) != null;
        }
        if (self.hir.kindOf(condition) != .logical_op) return false;
        const logical = hir_mod.logicalOf(self.hir, condition);
        if (logical.op != .@"or") return false;
        return try self.falseInstanceofConditionPreservesClassUnion(logical.lhs, receiver_name) and
            try self.falseInstanceofConditionPreservesClassUnion(logical.rhs, receiver_name);
    }

    fn canonicalNamedUnionAnnotationText(self: *Checker, annotation: NodeId) CheckError![]const u8 {
        return self.canonicalNamedUnionAnnotationTextInner(annotation, false);
    }

    fn canonicalNamedUnionAnnotationTextByName(
        self: *Checker,
        annotation: NodeId,
    ) CheckError![]const u8 {
        return self.canonicalNamedUnionAnnotationTextInner(annotation, true);
    }

    fn canonicalNamedUnionAnnotationTextInner(
        self: *Checker,
        annotation: NodeId,
        sort_by_name: bool,
    ) CheckError![]const u8 {
        if (self.hir.kindOf(annotation) != .union_type) {
            return try self.normalizedTypeAnnotationText(self.nodeSourceTextOrEmpty(annotation));
        }
        const Part = struct {
            node: NodeId,
            declaration_pos: u32,
            reference_name: []const u8,
            ordinal: usize,
        };
        var parts: std.ArrayListUnmanaged(Part) = .empty;
        defer parts.deinit(self.gpa);
        for (hir_mod.unionTypeMembers(self.hir, annotation), 0..) |member_node, ordinal| {
            if (self.hir.kindOf(member_node) != .type_ref) {
                return try self.normalizedTypeAnnotationText(self.nodeSourceTextOrEmpty(annotation));
            }
            const ref = hir_mod.typeRefOf(self.hir, member_node);
            const declaration_pos = if (self.findVisibleNamedTypeDecl(member_node, ref.name)) |decl|
                self.hir.spanOf(decl).start
            else
                std.math.maxInt(u32);
            try parts.append(self.gpa, .{
                .node = member_node,
                .declaration_pos = declaration_pos,
                .reference_name = self.string_interner.get(ref.name),
                .ordinal = ordinal,
            });
        }
        var i: usize = 1;
        while (i < parts.items.len) : (i += 1) {
            const part = parts.items[i];
            var j = i;
            while (j > 0) : (j -= 1) {
                const previous = parts.items[j - 1];
                if (sort_by_name) {
                    const order = std.mem.order(u8, previous.reference_name, part.reference_name);
                    if (order == .lt or (order == .eq and previous.ordinal < part.ordinal)) break;
                } else {
                    if (previous.declaration_pos < part.declaration_pos or
                        (previous.declaration_pos == part.declaration_pos and previous.ordinal < part.ordinal)) break;
                }
                parts.items[j] = previous;
            }
            parts.items[j] = part;
        }
        var out: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        for (parts.items, 0..) |part, index| {
            if (index != 0) try out.appendSlice(arena, " | ");
            try out.appendSlice(arena, try self.normalizedTypeAnnotationText(self.nodeSourceTextOrEmpty(part.node)));
        }
        return out.items;
    }

    fn instanceofGenericTargetBaseName(self: *Checker, rhs: NodeId) CheckError!?hir_mod.StringId {
        var rhs_t = self.hir.typeOf(rhs);
        if (rhs_t == types.Primitive.none) rhs_t = try self.checkExpression(rhs);
        const has_instance_name = self.string_interner.intern("Symbol.hasInstance") catch return error.OutOfMemory;
        if (self.instanceofRhsDeclaresMember(rhs, has_instance_name)) {
            if (try self.instanceofHasInstanceSignature(rhs_t)) |sig| {
                if (self.signature_predicates.get(sig)) |pred| {
                    if (pred.target_node != hir_mod.none_node_id and self.hir.kindOf(pred.target_node) == .type_ref and
                        hir_mod.typeRefArgs(self.hir, pred.target_node).len > 0)
                    {
                        return hir_mod.typeRefOf(self.hir, pred.target_node).name;
                    }
                }
            }
        }
        var construct_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer construct_sigs.deinit(self.gpa);
        try self.collectConstructSignatures(rhs_t, &construct_sigs);
        for (construct_sigs.items) |sig| {
            const decl = self.signature_decl_nodes.get(sig) orelse continue;
            if (self.hir.kindOf(decl) != .fn_type and self.hir.kindOf(decl) != .constructor_type) continue;
            const return_node = hir_mod.fnTypeOf(self.hir, decl).return_type;
            if (self.hir.kindOf(return_node) != .type_ref or hir_mod.typeRefArgs(self.hir, return_node).len == 0) continue;
            return hir_mod.typeRefOf(self.hir, return_node).name;
        }
        if (self.hir.kindOf(rhs) == .identifier) {
            return hir_mod.identifierOf(self.hir, rhs).name;
        }
        return null;
    }

    fn instanceofUnionTargetDisplayText(self: *Checker, rhs: NodeId) CheckError!?[]const u8 {
        var rhs_t = self.hir.typeOf(rhs);
        if (rhs_t == types.Primitive.none) rhs_t = try self.checkExpression(rhs);
        const has_instance_name = self.string_interner.intern("Symbol.hasInstance") catch return error.OutOfMemory;
        if (self.instanceofRhsDeclaresMember(rhs, has_instance_name)) {
            if (try self.instanceofHasInstanceSignature(rhs_t)) |sig| {
                if (self.signature_predicates.get(sig)) |pred| {
                    if (pred.target_node != hir_mod.none_node_id and self.hir.kindOf(pred.target_node) == .union_type) {
                        return try self.normalizedTypeAnnotationText(self.nodeSourceTextOrEmpty(pred.target_node));
                    }
                }
            }
        }

        var construct_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer construct_sigs.deinit(self.gpa);
        try self.collectConstructSignatures(rhs_t, &construct_sigs);
        var return_nodes: std.ArrayListUnmanaged(NodeId) = .empty;
        defer return_nodes.deinit(self.gpa);
        for (construct_sigs.items) |sig| {
            const decl = self.signature_decl_nodes.get(sig) orelse continue;
            if (self.hir.kindOf(decl) != .fn_type and self.hir.kindOf(decl) != .constructor_type) continue;
            const return_node = hir_mod.fnTypeOf(self.hir, decl).return_type;
            if (return_node == hir_mod.none_node_id) continue;
            if (self.hir.kindOf(return_node) == .union_type) {
                return try self.normalizedTypeAnnotationText(self.nodeSourceTextOrEmpty(return_node));
            }
            var duplicate = false;
            for (return_nodes.items) |existing| {
                if (std.mem.eql(u8, self.nodeSourceTextOrEmpty(existing), self.nodeSourceTextOrEmpty(return_node))) {
                    duplicate = true;
                    break;
                }
            }
            if (!duplicate) try return_nodes.append(self.gpa, return_node);
        }
        if (return_nodes.items.len < 2) return null;
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        for (return_nodes.items, 0..) |return_node, i| {
            if (i != 0) try buf.appendSlice(arena, " | ");
            const text = try self.normalizedTypeAnnotationText(self.nodeSourceTextOrEmpty(return_node));
            try buf.appendSlice(arena, text);
        }
        return buf.items;
    }

    fn reportPropertyDoesNotExistOnType(self: *Checker, node: NodeId, name: hir_mod.StringId, target_t: TypeId) CheckError!void {
        const name_str = self.string_interner.get(name);
        if (self.memberAccessRootNameIs(node, "Symbol")) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Property '{s}' does not exist on type 'SymbolConstructor'.",
                .{name_str},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .pos = self.memberAccessNamePos(node),
                .code = TsCodes.property_does_not_exist,
                .message = msg,
            });
            return;
        }
        if (self.hir.kindOf(node) == .member_access) {
            const member = hir_mod.memberOf(self.hir, node);
            if (try self.instanceofFalseBranchDisplayForMember(node, member.object)) |target_text| {
                try self.reportPropertyDoesNotExistOnTypeText(node, name, target_text);
                return;
            }
            if (try self.instanceofGenericNarrowDisplayForMember(node, member.object)) |target_text| {
                try self.reportPropertyDoesNotExistOnTypeText(node, name, target_text);
                return;
            }
            if (self.assignmentTargetMissingMemberReportText(node, member.object, target_t)) |target_text| {
                try self.reportPropertyDoesNotExistOnTypeText(node, name, target_text);
                return;
            }
            if (self.checkedJsObjectExpandoReceiverDisplay(member.object, target_t)) |target_text| {
                try self.reportPropertyDoesNotExistOnTypeText(node, name, target_text);
                return;
            }
            if (try self.instanceofNoNarrowDisplayForMember(node, member.object)) |target_text| {
                try self.reportPropertyDoesNotExistOnTypeText(node, name, target_text);
                return;
            }
            if (try self.instanceofUnionNarrowDisplayForMember(node, member.object)) |target_text| {
                try self.reportPropertyDoesNotExistOnTypeText(node, name, target_text);
                return;
            }
            if (self.nodeIsThisReference(member.object)) {
                if (self.memberAccessClassFieldStaticness(node)) |is_static| {
                    const class_node = self.enclosingClassNode(node);
                    if (try self.classDisplayNameFromNode(class_node)) |class_name| {
                        defer self.gpa.free(class_name);
                        const display = if (is_static)
                            try std.fmt.allocPrint(self.diag_arena.allocator(), "typeof {s}", .{class_name})
                        else
                            class_name;
                        try self.reportPropertyDoesNotExistOnTypeText(node, name, display);
                        return;
                    }
                }
            }
            if (self.nodeIsThisReference(member.object)) {
                const class_node = self.enclosingClassNode(node);
                if (class_node != hir_mod.none_node_id) {
                    const class_payload = hir_mod.classOf(self.hir, class_node);
                    if (class_payload.name == hir_mod.none_node_id) {
                        try self.reportPropertyDoesNotExistOnTypeText(node, name, "(Anonymous class)");
                        return;
                    }
                }
            }
            // An undeclared ECMAScript private name is resolved against the
            // enclosing nominal class, even when the receiver expression is
            // the polymorphic `this` type. TypeScript therefore renders `A`
            // (or `A<T>`) rather than `this` in TS2339.
            if (self.memberNameIsEcmaPrivate(name) and self.nodeIsThisReference(member.object)) {
                const class_node = self.enclosingClassNode(node);
                if (try self.classDisplayNameFromNode(class_node)) |class_name| {
                    defer self.gpa.free(class_name);
                    try self.reportPropertyDoesNotExistOnTypeText(node, name, class_name);
                    return;
                }
            }
        }
        // TS2576: when the property exists as a static member of the
        // class whose instance we're accessing through, surface the
        // "Did you mean to access the static member '<C>.x' instead?"
        // hint. Mirrors `staticPropertyNotInClassType` baselines.
        // Skip for ECMAScript private identifiers (`#x`): upstream
        // tsc never offers this hint when the property name starts
        // with `#` (the lexical-scoping rules for private names make
        // it unreachable through the static side).
        if (!self.memberNameIsEcmaPrivate(name)) {
            if (self.class_name_by_instance.get(target_t)) |class_name| {
                if (self.class_static_member_names.getPtr(class_name)) |statics| {
                    if (statics.contains(name)) {
                        if (try self.allocPropertyMissingTargetTypeName(target_t)) |target_text| {
                            const class_str = if (std.mem.indexOfScalar(u8, target_text, '<') != null)
                                target_text
                            else
                                self.string_interner.get(class_name);
                            const msg = try std.fmt.allocPrint(
                                self.diag_arena.allocator(),
                                "Property '{s}' does not exist on type '{s}'. Did you mean to access the static member '{s}.{s}' instead?",
                                .{ name_str, target_text, class_str, name_str },
                            );
                            try self.diagnostics.append(self.gpa, .{
                                .node = node,
                                .pos = self.memberAccessNamePos(node),
                                .code = TsCodes.property_does_not_exist_static_member,
                                .message = msg,
                            });
                            return;
                        }
                    }
                }
            }
        }
        if (try self.allocPropertyMissingTargetTypeName(target_t)) |target_text| {
            // TS2551: when a similarly-spelled member exists on the
            // receiver type, upstream emits the did-you-mean variant
            // instead of the bare TS2339. Skip for ECMAScript private
            // identifiers (`#x`) — tsc never spell-suggests those.
            //
            // Also skip union receivers: upstream reports plain TS2339
            // in narrowed-union property misses even when one
            // constituent has a close member name.
            const target_is_union = target_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(target_t).is_union;
            if (!target_is_union and !self.memberNameIsEcmaPrivate(name)) {
                if (self.closestBaseClassMemberName(target_t, name_str)) |suggestion| {
                    // In an unchecked `.js` file (JS-like, no checkJs),
                    // upstream softens this to TS2568 "may not exist" and
                    // emits it as a SUGGESTION rather than an error.
                    const unchecked_js = self.virtualSectionIsJsLike(node) and !self.sourceHasCheckJsDirective();
                    if (unchecked_js) {
                        const msg = try std.fmt.allocPrint(
                            self.diag_arena.allocator(),
                            "Property '{s}' may not exist on type '{s}'. Did you mean '{s}'?",
                            .{ name_str, target_text, suggestion },
                        );
                        try self.diagnostics.append(self.gpa, .{
                            .node = node,
                            .pos = self.memberAccessNamePos(node),
                            .code = TsCodes.property_may_not_exist_did_you_mean,
                            .message = msg,
                            .category = .suggestion,
                        });
                        return;
                    }
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Property '{s}' does not exist on type '{s}'. Did you mean '{s}'?",
                        .{ name_str, target_text, suggestion },
                    );
                    try self.diagnostics.append(self.gpa, .{
                        .node = node,
                        .pos = self.memberAccessNamePos(node),
                        .code = TsCodes.property_does_not_exist_did_you_mean,
                        .message = msg,
                    });
                    return;
                }
            }
            if (self.sourceLibDirectiveExcludesDomElement() and self.typeNameIsDomLibReceiver(target_text)) {
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Property '{s}' does not exist on type '{s}'. Try changing the 'lib' compiler option to include 'dom'.",
                    .{ name_str, target_text },
                );
                try self.diagnostics.append(self.gpa, .{
                    .node = node,
                    .pos = self.memberAccessNamePos(node),
                    .code = TsCodes.property_does_not_exist_dom_library,
                    .message = msg,
                });
                return;
            }
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Property '{s}' does not exist on type '{s}'.",
                .{ name_str, target_text },
            );
            try self.diagnostics.append(self.gpa, .{
                .node = node,
                .pos = self.memberAccessNamePos(node),
                .code = TsCodes.property_does_not_exist,
                .message = msg,
            });
            return;
        }
        try self.reportPropertyDoesNotExist(node, name);
    }

    fn memberAccessClassFieldStaticness(self: *Checker, node: NodeId) ?bool {
        var child = node;
        var current = self.hir.parentOf(node);
        while (current != hir_mod.none_node_id) : ({
            child = current;
            current = self.hir.parentOf(current);
        }) {
            switch (self.hir.kindOf(current)) {
                .arrow_fn => continue,
                .fn_decl, .fn_expr => return null,
                .object_property => {
                    const property = hir_mod.objectPropertyOf(self.hir, current);
                    if (property.is_method or property.value == hir_mod.none_node_id or property.value != child) return null;
                    const parent = self.hir.parentOf(current);
                    if (parent == hir_mod.none_node_id) return null;
                    const parent_kind = self.hir.kindOf(parent);
                    if (parent_kind != .class_decl and parent_kind != .class_expr) return null;
                    return property.is_static or
                        self.classMemberSourceHasModifierBeforeKey(current, property.key, "static");
                },
                .class_decl, .class_expr => return null,
                else => {},
            }
        }
        return null;
    }

    fn typeNameIsDomLibReceiver(self: *const Checker, target_text: []const u8) bool {
        _ = self;
        const dom_names = [_][]const u8{
            "Window",
            "Document",
            "Element",
            "HTMLElement",
            "Event",
            "EventTarget",
            "Node",
        };
        for (dom_names) |name| {
            if (std.mem.eql(u8, target_text, name)) return true;
            if (std.mem.startsWith(u8, target_text, name) and
                target_text.len > name.len and
                std.mem.startsWith(u8, target_text[name.len..], " &"))
            {
                return true;
            }
        }
        return false;
    }

    fn memberAccessRootNameIs(self: *Checker, node: NodeId, expected: []const u8) bool {
        const root = self.calleeRootIdentifier(node) orelse return false;
        const id = hir_mod.identifierOf(self.hir, root);
        return std.mem.eql(u8, self.string_interner.get(id.name), expected);
    }

    fn memberAccessNamePos(self: *Checker, node: NodeId) ?u32 {
        if (self.source == null or self.hir.kindOf(node) != .member_access) return null;
        const src = self.source.?;
        const span = self.hir.spanOf(node);
        if (span.end > src.len or span.start >= span.end) return null;
        const text = src[span.start..span.end];
        var i = text.len;
        while (i > 0) {
            i -= 1;
            if (text[i] == '.') return span.start + @as(u32, @intCast(i + 1));
        }
        return null;
    }

    fn allocPropertyMissingTargetTypeName(self: *Checker, target_t: TypeId) !?[]const u8 {
        if (self.isThisTypeParameter(target_t)) {
            if (self.typeParameterConstraint(target_t)) |constraint| {
                if (constraint != target_t) return self.allocPropertyMissingTargetTypeName(constraint);
            }
        }
        if (self.class_name_by_static.get(target_t)) |class_name| {
            return try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "typeof {s}",
                .{self.string_interner.get(class_name)},
            );
        }
        if (target_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(target_t).is_union and
            !self.alias_display_names.contains(target_t))
        {
            try self.registerDiagnosticUnionDisplayName(target_t, self.interner.unionMembers(target_t));
        }
        if (try self.allocSimpleTypeName(target_t)) |name| return name;
        if (self.alias_display_names.get(target_t)) |name| return name;
        if (target_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(target_t);
        if (flags.is_object_type and
            self.interner.objectMembers(target_t).len == 0 and
            self.interner.objectStringIndex(target_t) == types.Primitive.none and
            self.interner.objectNumberIndex(target_t) == types.Primitive.none)
        {
            return "{}";
        }
        // Render small literal object types like `{ x: number; }` so
        // TS2339 prose matches upstream when the target was a local
        // object literal preserved by `satisfies` or by contextual
        // typing. Bail on indexers/methods/optionals so we don't
        // mis-render shapes the simple printer can't faithfully
        // reproduce.
        if (flags.is_object_type and
            self.interner.objectStringIndex(target_t) == types.Primitive.none and
            self.interner.objectNumberIndex(target_t) == types.Primitive.none)
        {
            const members = self.interner.objectMembers(target_t);
            if (members.len > 0 and members.len <= 8) {
                var obj_buf: std.ArrayListUnmanaged(u8) = .empty;
                const arena_o = self.diag_arena.allocator();
                try obj_buf.appendSlice(arena_o, "{ ");
                var renderable = true;
                for (members) |m| {
                    if (m.is_method or m.is_optional) {
                        renderable = false;
                        break;
                    }
                    const member_name_str = self.string_interner.get(m.name);
                    if (member_name_str.len == 0 or member_name_str[0] == '_') {
                        renderable = false;
                        break;
                    }
                    const value_text = (try self.allocSimpleTypeName(m.type)) orelse {
                        renderable = false;
                        break;
                    };
                    // Wrap Symbol-keyed member names (`Symbol.iterator`)
                    // in brackets so they render as `[Symbol.iterator]`
                    // matching tsc baselines for the `symbolProperty*`
                    // family.
                    if (std.mem.startsWith(u8, member_name_str, "Symbol.")) {
                        try obj_buf.append(arena_o, '[');
                        try obj_buf.appendSlice(arena_o, member_name_str);
                        try obj_buf.append(arena_o, ']');
                    } else {
                        try obj_buf.appendSlice(arena_o, member_name_str);
                    }
                    try obj_buf.appendSlice(arena_o, ": ");
                    try obj_buf.appendSlice(arena_o, value_text);
                    try obj_buf.appendSlice(arena_o, "; ");
                }
                if (renderable) {
                    try obj_buf.append(arena_o, '}');
                    return obj_buf.items;
                }
            }
        }
        return null;
    }

    /// Best-effort name for the target of an `implements` clause used by
    /// TS2420 ("Class 'X' incorrectly implements interface ..."). Returns
    /// the interface's declared name when one is recoverable; otherwise
    /// null so the caller falls back to the bare diagnostic.
    fn allocImplementsTargetName(self: *Checker, impl_node: NodeId, target_t: TypeId) !?[]const u8 {
        if (try self.allocSimpleTypeName(target_t)) |name| return name;
        // Try to recover the syntactic type-reference name (handles cases
        // where the lowered type is opaque but the source spelled it out).
        return self.implementsClauseSyntacticName(impl_node);
    }

    fn implementsTargetHasInheritedBaseConflict(self: *Checker, impl_node: NodeId) bool {
        const name = self.unqualifiedTypeRefName(impl_node) orelse return false;
        const target_decl = self.findVisibleNamedTypeDecl(impl_node, name) orelse return false;
        for (self.diagnostics.items) |diagnostic| {
            if (diagnostic.code != TsCodes.interface_cannot_simultaneously_extend) continue;
            if (diagnostic.node == hir_mod.none_node_id or self.hir.kindOf(diagnostic.node) != .identifier) continue;
            if (hir_mod.identifierOf(self.hir, diagnostic.node).name != name) continue;
            const diagnostic_decl = self.hir.parentOf(diagnostic.node);
            if (diagnostic_decl == hir_mod.none_node_id or self.hir.kindOf(diagnostic_decl) != .interface_decl) continue;
            if (self.declarationsShareNamespacePath(target_decl, diagnostic_decl)) return true;
        }
        return false;
    }

    fn declarationsShareNamespacePath(self: *Checker, left: NodeId, right: NodeId) bool {
        if (self.rootBlockFor(left) != self.rootBlockFor(right)) return false;
        var left_path: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer left_path.deinit(self.gpa);
        var right_path: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer right_path.deinit(self.gpa);
        self.collectEnclosingNamespacePathNoFail(left, &left_path);
        self.collectEnclosingNamespacePathNoFail(right, &right_path);
        return std.mem.eql(hir_mod.StringId, left_path.items, right_path.items);
    }

    fn reportClassWeakTypeNoOverlap(
        self: *Checker,
        class_node: NodeId,
        impl_node: NodeId,
        instance_t: TypeId,
        target_t: TypeId,
        class_name: hir_mod.StringId,
    ) CheckError!bool {
        if (!self.engine.weakTypeNoCommonProperties(instance_t, target_t)) return false;

        const child_disp_owned = try self.classDisplayNameFromNode(class_node);
        defer if (child_disp_owned) |name| self.gpa.free(name);
        const child_name: []const u8 = child_disp_owned orelse self.string_interner.get(class_name);
        const target_name = (try self.allocImplementsTargetName(impl_node, target_t)) orelse return false;
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' has no properties in common with type '{s}'.",
            .{ child_name, target_name },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = class_node,
            .pos = self.classNameSpanStart(class_node),
            .code = TsCodes.no_properties_in_common,
            .message = msg,
        });
        return true;
    }

    fn reportClassIncorrectlyImplements(
        self: *Checker,
        class_node: NodeId,
        impl_node: NodeId,
        target_t: TypeId,
        class_name: hir_mod.StringId,
    ) CheckError!void {
        // Render the child name with type parameters so generic classes
        // display as `B3<T>` rather than collapsing to `B3`.
        const child_disp_owned = (try self.classDisplayNameFromNode(class_node));
        defer if (child_disp_owned) |cd| self.gpa.free(cd);
        const child_str: []const u8 = child_disp_owned orelse self.string_interner.get(class_name);
        const target_name = try self.allocImplementsTargetName(impl_node, target_t);
        if (self.class_name_by_instance.contains(target_t)) {
            const target_str = target_name orelse "base class";
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Class '{s}' incorrectly implements class '{s}'. Did you mean to extend '{s}' and inherit its members as a subclass?",
                .{ child_str, target_str, target_str },
            );
            try self.diagnostics.append(self.gpa, .{
                .node = class_node,
                .pos = self.classNameSpanStart(class_node),
                .code = TsCodes.class_incorrectly_implements_class,
                .message = msg,
            });
            return;
        }

        const msg = if (target_name) |tn|
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Class '{s}' incorrectly implements interface '{s}'.",
                .{ child_str, tn },
            )
        else
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Class '{s}' incorrectly implements interface.",
                .{child_str},
            );
        try self.diagnostics.append(self.gpa, .{
            .node = class_node,
            .pos = self.classNameSpanStart(class_node),
            .code = TsCodes.class_incorrectly_implements_interface,
            .message = msg,
        });
    }

    fn implementsClauseSyntacticName(self: *Checker, impl_node: NodeId) ?[]const u8 {
        const src = self.source orelse return null;
        const span = self.hir.spanOf(impl_node);
        if (span.start >= span.end or span.end > src.len) return null;
        const text = src[span.start..span.end];
        // Trim to the leading identifier (stop at `<`, `.`, whitespace).
        var end: usize = 0;
        while (end < text.len) : (end += 1) {
            const ch = text[end];
            const is_ident = (ch == '_') or (ch == '$') or
                (ch >= 'a' and ch <= 'z') or
                (ch >= 'A' and ch <= 'Z') or
                (end > 0 and ch >= '0' and ch <= '9');
            if (!is_ident) break;
        }
        if (end == 0) return null;
        return text[0..end];
    }

    /// Span start of the class identifier (`class X`) used as the
    /// diagnostic position for TS2420 / TS2415, matching tsc which
    /// reports against the class name rather than the `class` keyword.
    fn classNameSpanStart(self: *Checker, class_node: NodeId) ?u32 {
        if (self.hir.kindOf(class_node) != .class_decl and self.hir.kindOf(class_node) != .class_expr) {
            return null;
        }
        const c = hir_mod.classOf(self.hir, class_node);
        if (c.name == hir_mod.none_node_id) return null;
        const sp = self.hir.spanOf(c.name);
        return sp.start;
    }

    /// True when `class_node` is nested inside a `declare module
    /// "x" { ... }` (or `declare namespace ...`). Used to suppress
    /// TS2564 ("Property has no initializer ...") for fields in
    /// ambient blocks where tsc treats the class shape as purely
    /// declarative ÃÂ¢ÃÂÃÂ see fixture `importTypeAmbient`. A regular
    /// `namespace Foo { class C { ... } }` (no `declare`) still
    /// emits TS2564, matching `assignmentCompatWithCallSignatures4`.
    fn classNodeIsInsideAmbientDeclaredModule(self: *Checker, class_node: NodeId) bool {
        var cur = self.hir.parentOf(class_node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const k = self.hir.kindOf(cur);
            if (k == .module_decl or k == .namespace_decl) {
                if (self.namespaceDeclWasPrefixedWithDeclare(cur)) return true;
            }
        }
        return false;
    }

    fn namespaceDeclWasPrefixedWithDeclare(self: *Checker, ns_node: NodeId) bool {
        const src = self.source orelse return false;
        const span = self.hir.spanOf(ns_node);
        if (span.start >= src.len) return false;
        // Span begins at `namespace` / `module`; the `declare`
        // modifier sits just before. Bounded look-behind avoids
        // drifting into a previous statement.
        const look_back: u32 = 16;
        const lb_start: u32 = if (span.start > look_back) span.start - look_back else 0;
        const slice = src[lb_start..span.start];
        return std.mem.indexOf(u8, slice, "declare") != null;
    }

    fn elementAccessIndexTypeName(self: *Checker, index_node: NodeId, index_t: TypeId, literal_string_key: ?hir_mod.StringId) CheckError![]const u8 {
        if (literal_string_key) |key| return try self.allocStringLiteralDisplay(key);
        const src_text = self.nodeSourceTextOrEmpty(index_node);
        if (self.hir.kindOf(index_node) == .literal_number) {
            const trimmed = std.mem.trim(u8, src_text, " \t\r\n");
            if (trimmed.len != 0) return try self.diag_arena.allocator().dupe(u8, trimmed);
        }
        const flags = self.interner.pool.flagsOf(index_t);
        if (flags.is_symbol or std.mem.indexOf(u8, src_text, "_sym") != null or std.mem.endsWith(u8, src_text, ".S")) {
            return "unique symbol";
        }
        return (try self.allocSimpleTypeName(index_t)) orelse "any";
    }

    fn reportElementImplicitAnyMissingIndexSignature(
        self: *Checker,
        node: NodeId,
        index_t: TypeId,
        index_name: []const u8,
        object_name: []const u8,
    ) CheckError!void {
        const arena = self.diag_arena.allocator();
        const msg = try std.fmt.allocPrint(
            arena,
            "Element implicitly has an 'any' type because expression of type '{s}' can't be used to index type '{s}'.",
            .{ index_name, object_name },
        );
        var chain: []const DiagnosticChainEntry = &.{};
        if (index_t < self.interner.pool.typeCount()) {
            const flags = self.interner.pool.flagsOf(index_t);
            if (try self.firstRenderedUnionMemberMissingFromObject(index_name, object_name)) |missing_name| {
                const child_msg = try std.fmt.allocPrint(
                    arena,
                    "Property '{s}' does not exist on type '{s}'.",
                    .{ missing_name, object_name },
                );
                const child = try arena.alloc(DiagnosticChainEntry, 1);
                child[0] = .{ .code = TsCodes.property_does_not_exist, .message = child_msg };
                chain = child;
            } else if (flags.is_string or flags.is_number) {
                const child_msg = try std.fmt.allocPrint(
                    arena,
                    "No index signature with a parameter of type '{s}' was found on type '{s}'.",
                    .{ index_name, object_name },
                );
                const child = try arena.alloc(DiagnosticChainEntry, 1);
                child[0] = .{ .code = TsCodes.no_index_signature_parameter, .message = child_msg };
                chain = child;
            }
        }
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.element_implicitly_any,
            .message = msg,
            .chain = chain,
        });
    }

    fn firstRenderedUnionMemberMissingFromObject(
        self: *Checker,
        index_name: []const u8,
        object_name: []const u8,
    ) CheckError!?[]const u8 {
        _ = self;
        if (std.mem.indexOf(u8, index_name, "|") == null) return null;
        var rest = index_name;
        while (std.mem.indexOfScalar(u8, rest, '"')) |start| {
            rest = rest[start + 1 ..];
            const end = std.mem.indexOfScalar(u8, rest, '"') orelse return null;
            const member = rest[0..end];
            var needle_buf: [256]u8 = undefined;
            const needle = std.fmt.bufPrint(&needle_buf, "{s}:", .{member}) catch return null;
            if (std.mem.indexOf(u8, object_name, needle) == null) return member;
            rest = rest[end + 1 ..];
        }
        return null;
    }

    fn elementAccessMissingPropertyChainName(
        self: *Checker,
        object_t: TypeId,
        index_t: TypeId,
        literal_string_key: ?hir_mod.StringId,
    ) CheckError!?[]const u8 {
        if (literal_string_key) |key| return self.string_interner.get(key);
        if (index_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(index_t);
        if (flags.is_union) {
            for (self.interner.unionMembers(index_t)) |member| {
                const name = (try self.propertyNameFromLiteralType(member)) orelse continue;
                if (self.interner.objectMember(object_t, name) == null) return self.string_interner.get(name);
            }
            return null;
        }
        if (flags.is_literal) {
            const name = (try self.propertyNameFromLiteralType(index_t)) orelse return null;
            if (self.interner.objectMember(object_t, name) == null) return self.string_interner.get(name);
            return null;
        }
        return null;
    }

    fn reportElementImplicitAnyMissingProperty(
        self: *Checker,
        node: NodeId,
        index_name: []const u8,
        object_name: []const u8,
        property_name: []const u8,
    ) CheckError!void {
        const arena = self.diag_arena.allocator();
        const msg = try std.fmt.allocPrint(
            arena,
            "Element implicitly has an 'any' type because expression of type '{s}' can't be used to index type '{s}'.",
            .{ index_name, object_name },
        );
        const child_msg = try std.fmt.allocPrint(
            arena,
            "Property '{s}' does not exist on type '{s}'.",
            .{ property_name, object_name },
        );
        const child = try arena.alloc(DiagnosticChainEntry, 1);
        child[0] = .{ .code = TsCodes.property_does_not_exist, .message = child_msg };
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.element_implicitly_any,
            .message = msg,
            .chain = child,
        });
    }

    fn suggestedIndexSignatureCall(
        self: *Checker,
        node: NodeId,
        object_node: NodeId,
        object_t: TypeId,
        index_t: TypeId,
    ) CheckError!?[]const u8 {
        const method_text = if (self.isAssignmentTarget(node)) "set" else "get";
        if (std.mem.eql(u8, method_text, "get") and self.elementAccessReceiverContainsObjectLiteral(object_node)) return null;
        const method_name = self.string_interner.intern(method_text) catch return error.OutOfMemory;
        const method_t = self.interner.objectMember(object_t, method_name) orelse return null;
        const sig = self.firstSignatureType(method_t) orelse return null;
        const params = self.interner.signatureParams(sig);
        const min_required = self.signatureMinRequiredArgs(sig, params);
        if (min_required < 1 or params.len == 0) return null;
        var effective_index_t = index_t;
        if (self.elementAccessLiteralStringKey(node)) |key| {
            effective_index_t = self.interner.internStringLiteral(key) catch return error.OutOfMemory;
        }
        if (!(self.engine.isAssignableTo(effective_index_t, params[0]) catch false)) return null;
        if (self.elementAccessReceiverContainsObjectLiteral(object_node)) return method_text;
        const obj_text = self.nodeSourceTextOrEmpty(object_node);
        if (obj_text.len == 0) return method_text;
        return try std.fmt.allocPrint(self.diag_arena.allocator(), "{s}.{s}", .{ obj_text, method_text });
    }

    fn elementAccessLiteralStringKey(self: *Checker, node: NodeId) ?hir_mod.StringId {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .element_access) return null;
        const e = hir_mod.elementOf(self.hir, node);
        if (e.index == hir_mod.none_node_id or self.hir.kindOf(e.index) != .literal_string) return null;
        return hir_mod.literalStringOf(self.hir, e.index).value;
    }

    fn elementAccessReceiverContainsObjectLiteral(self: *Checker, object_node: NodeId) bool {
        if (object_node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(object_node) == .object_literal) return true;
        return std.mem.indexOfScalar(u8, self.nodeSourceTextOrEmpty(object_node), '{') != null;
    }

    fn reportElementImplicitAnyDidYouMeanCall(
        self: *Checker,
        node: NodeId,
        object_name: []const u8,
        suggestion: []const u8,
    ) CheckError!void {
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Element implicitly has an 'any' type because type '{s}' has no index signature. Did you mean to call '{s}'?",
            .{ object_name, suggestion },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .pos = self.inlineObjectElementAccessDiagnosticPos(node),
            .code = TsCodes.element_implicitly_any_no_index_signature_did_you_mean_call,
            .message = msg,
        });
    }

    fn inlineObjectElementAccessDiagnosticPos(self: *Checker, node: NodeId) ?u32 {
        if (self.source == null or node == hir_mod.none_node_id or self.hir.kindOf(node) != .element_access) return null;
        const src = self.source.?;
        const span = self.hir.spanOf(node);
        if (span.start == 0 or span.start > src.len) return null;
        const prev = span.start - 1;
        if (src[prev] == '(') return prev;
        return null;
    }

    fn elementAccessMissingPropertyName(self: *Checker, index_node: NodeId, index_t: TypeId) CheckError![]const u8 {
        if (try self.propertyNameFromLiteralType(index_t)) |name| return self.string_interner.get(name);
        if (self.interner.pool.flagsOf(index_t).is_symbol) {
            const src_text = self.nodeSourceTextOrEmpty(index_node);
            if (src_text.len > 0) return try std.fmt.allocPrint(self.diag_arena.allocator(), "[{s}]", .{src_text});
            return "[symbol]";
        }
        return self.nodeSourceTextOrEmpty(index_node);
    }

    fn typeIsDefinitelyNonConstructable(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.none or self.typeIsAnyLike(t)) return false;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.typeIsDefinitelyNonConstructable(member)) return false;
            }
            return true;
        }
        return f.is_string or f.is_number or f.is_bigint or f.is_boolean or f.is_symbol or f.is_null or f.is_undefined or f.is_void;
    }

    fn isRelationalOperandAllowed(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return true;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.isRelationalOperandAllowed(member)) return false;
            }
            return true;
        }
        if (f.is_type_parameter) return true;
        if (f.is_null or f.is_undefined) return true;
        if (f.is_object or f.is_object_type or f.is_signature or f.is_tuple or f.is_intersection) return true;
        return f.is_string or f.is_number or f.is_bigint or f.is_boolean or f.is_void;
    }

    fn typeIsExactNullish(self: *Checker, t: TypeId) bool {
        // `any`/`unknown` operands flow through `checkNonNullType`
        // without producing TS18050 in tsc ÃÂ¢ÃÂÃÂ only operands whose
        // *static* type is exactly `null` or `undefined` trigger the
        // relational-nullish diagnostic. Without this guard, an
        // identifier whose inferred type happened to widen to
        // `undefined` (e.g. `var p;` in a strict context) was tripping
        // TS18050 instead of the upstream TS18048
        // (`'p' is possibly 'undefined'.`) ÃÂ¢ÃÂÃÂ visible on `tsxReactEmit1`.
        if (self.typeIsAnyLike(t)) return false;
        const f = self.interner.pool.flagsOf(t);
        return f.is_null or f.is_undefined;
    }

    fn typeIsExactUndefined(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return false;
        const f = self.interner.pool.flagsOf(t);
        return f.is_undefined;
    }

    fn typeIsExactNull(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return false;
        const f = self.interner.pool.flagsOf(t);
        return f.is_null;
    }

    fn relationalNullishName(self: *Checker, t: TypeId) []const u8 {
        const f = self.interner.pool.flagsOf(t);
        return if (f.is_null) "null" else "undefined";
    }

    fn reportNullishRelationalOperand(self: *Checker, node: NodeId, t: TypeId) CheckError!void {
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "The value '{s}' cannot be used here.",
            .{self.relationalNullishName(t)},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.nullish_relational_operand,
            .message = msg,
        });
    }

    fn reportRelationalNullishOperand(self: *Checker, node: NodeId, t: TypeId) CheckError!void {
        if (self.nullishLiteralOperandName(node)) |name| {
            try self.reportNullishLiteralBinaryOperand(node, name);
            return;
        }
        try self.reportPossiblyNullishMember(node, t);
    }

    /// `null` / `undefined` literal name, anchored on the node kind
    /// (not the type) so we mirror tsgo's "checkNonNullType" branch
    /// that gates on whether the operand source token is literally
    /// `null` or the `undefined` identifier ÃÂ¢ÃÂÃÂ independent of any
    /// flow-narrowed type. Returns null when the node isn't one of
    /// those literals.
    fn nullishLiteralOperandName(self: *Checker, node: NodeId) ?[]const u8 {
        const name: []const u8 = switch (self.hir.kindOf(node)) {
            .literal_null => "null",
            .literal_undefined => "undefined",
            else => return null,
        };
        if (!self.nodeSourceTextIs(node, name)) return null;
        return name;
    }

    fn reportNullishLiteralBinaryOperand(self: *Checker, node: NodeId, name: []const u8) CheckError!void {
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "The value '{s}' cannot be used here.",
            .{name},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.nullish_relational_operand,
            .message = msg,
        });
    }

    fn reportInOperandLeft(self: *Checker, node: NodeId, t: TypeId) CheckError!void {
        const arena = self.diag_arena.allocator();
        const type_text = (try self.simpleDiagnosticTypeName(t)) orelse "";
        const msg = if (type_text.len > 0)
            try std.fmt.allocPrint(arena, "Type '{s}' is not assignable to type 'string | number | symbol'.", .{type_text})
        else
            try arena.dupe(u8, "Type is not assignable to type 'string | number | symbol'.");
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.type_not_assignable,
            .message = msg,
        });
    }

    fn reportInOperandRight(self: *Checker, node: NodeId, t: TypeId) CheckError!void {
        const arena = self.diag_arena.allocator();
        const type_text = (try self.allocAssignmentDiagnosticTypeName(t)) orelse
            (try self.simpleDiagnosticTypeName(t)) orelse
            "";
        const msg = if (type_text.len > 0)
            try std.fmt.allocPrint(arena, "Type '{s}' is not assignable to type 'object'.", .{type_text})
        else
            try arena.dupe(u8, "Type is not assignable to type 'object'.");
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.type_not_assignable,
            .message = msg,
        });
    }

    fn reportInRightMayRepresentPrimitive(self: *Checker, node: NodeId, t: TypeId) CheckError!void {
        const arena = self.diag_arena.allocator();
        const type_text = (try self.allocSimpleTypeName(t)) orelse "type";
        const msg = try std.fmt.allocPrint(
            arena,
            "Type '{s}' may represent a primitive value, which is not permitted as the right operand of the 'in' operator.",
            .{type_text},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.in_right_may_represent_primitive,
            .message = msg,
        });
    }

    fn typeHasUnknownEmptyObject(self: *Checker, t: TypeId) bool {
        if (self.unknown_empty_object_types.contains(t)) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeHasUnknownEmptyObject(member)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeHasUnknownEmptyObject(member)) return true;
            }
        }
        return false;
    }

    fn relationalTypeHasNumberLike(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return false;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_object or f.is_object_type or f.is_signature or f.is_tuple) return false;
        // Numeric enum nominal types render as `number & { __enum:X }`.
        // Treat the intersection as number-like so relational compare
        // with `number` / another numeric enum doesn't fire TS2365.
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (member == types.Primitive.number_t) return true;
            }
            return false;
        }
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.relationalTypeHasNumberLike(member)) return true;
            }
        }
        return f.is_number;
    }

    fn relationalTypeHasObjectLike(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return false;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_object or f.is_object_type or f.is_signature or f.is_tuple) return true;
        if (f.is_intersection) {
            // A numeric enum nominal (`number & { __enum:X }`) is
            // primitive-like, not object-like, for relational compares.
            for (self.interner.intersectionMembers(t)) |member| {
                if (member == types.Primitive.number_t) return false;
            }
            return true;
        }
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.relationalTypeHasObjectLike(member)) return true;
            }
        }
        return false;
    }

    fn isUnconstrainedTypeParameter(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        return f.is_type_parameter and self.typeParameterConstraint(t) == null;
    }

    fn isConstrainedTypeParameter(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (!f.is_type_parameter) return false;
        const constraint = self.typeParameterConstraint(t) orelse return false;
        return constraint != t;
    }

    /// Detect the parser's `++x`/`x--` desugaring shape: the
    /// assignment value is a literal `1` whose span sits at the
    /// operator-token slot ÃÂ¢ÃÂÃÂ outside the target's span. Used so
    /// arithmetic-operand diagnostics on update-expression operands
    /// render as TS2356 instead of TS2362/TS2363.
    fn assignmentIsSynthesizedUpdate(self: *Checker, node: NodeId, a: hir_mod.AssignmentPayload) bool {
        if (self.hir.kindOf(a.value) != .literal_number) return false;
        if (hir_mod.literalNumberOf(self.hir, a.value) != 1.0) return false;
        const value_span = self.hir.spanOf(a.value);
        // Synthesised `1` carries the `++`/`--` operator token's span
        // (2 chars wide). A user-written `1` literal is 1 char. This
        // distinguishes `++x` from `x += 1` / `x -= 1`, which would
        // otherwise both match the postfix-span shape below.
        if (value_span.end - value_span.start != 2) return false;
        const target_span = self.hir.spanOf(a.target);
        const node_span = self.hir.spanOf(node);
        // Prefix `++x`: value span starts at the assignment start,
        // before the target span.
        const is_prefix_shape = value_span.start == node_span.start and
            value_span.end <= target_span.start;
        // Postfix `x++`: value span ends at the assignment end,
        // after the target span.
        const is_postfix_shape = value_span.end == node_span.end and
            value_span.start >= target_span.end;
        return is_prefix_shape or is_postfix_shape;
    }

    fn updateOperandRequiresVariableDiagnostic(self: *Checker, target: NodeId, target_t: TypeId) bool {
        if (self.updateOperandIsEnumBinaryExpression(target)) return false;
        if (self.typeIsExactUndefined(target_t)) return false;
        if (self.nodeSourceTextIs(target, "undefined")) return false;
        return switch (self.hir.kindOf(target)) {
            .identifier, .member_access, .element_access, .literal_undefined => false,
            .object_literal, .array_literal => false,
            else => self.typeIsAnyLike(target_t) or self.isArithmeticOperandAllowed(target_t) or self.hir.kindOf(target) == .literal_null,
        };
    }

    fn reportUpdateOperandRequiresVariable(self: *Checker, target: NodeId) CheckError!void {
        try self.diagnostics.append(self.gpa, .{
            .node = target,
            .pos = self.symbolOperandAnchorPos(target),
            .code = TsCodes.update_operand_not_variable,
            .message = "The operand of an increment or decrement operator must be a variable or a property access.",
        });
    }

    fn updateOperandIsEnumBinaryExpression(self: *Checker, target: NodeId) bool {
        if (self.hir.kindOf(target) != .binary_op) return false;
        const b = hir_mod.binopOf(self.hir, target);
        return self.updateOperandExprReferencesEnumIndexedAccess(b.lhs) or
            self.updateOperandExprReferencesEnumIndexedAccess(b.rhs);
    }

    fn updateOperandExprReferencesEnumIndexedAccess(self: *Checker, node: NodeId) bool {
        if (self.hir.kindOf(node) != .element_access) return false;
        const e = hir_mod.elementOf(self.hir, node);
        if (self.hir.kindOf(e.object) != .identifier) return false;
        const enum_name = hir_mod.identifierOf(self.hir, e.object).name;
        return self.enumDeclForName(enum_name) != null;
    }

    fn nodeSourceTextIs(self: *Checker, node: NodeId, expected: []const u8) bool {
        const src = self.source orelse return false;
        const span = self.hir.spanOf(node);
        if (span.end > src.len or span.start > span.end) return false;
        return std.mem.eql(u8, std.mem.trim(u8, src[span.start..span.end], " \t\r\n"), expected);
    }

    fn reportIdentifierAssignmentTargetKind(self: *Checker, target: NodeId) CheckError!bool {
        if (self.hir.kindOf(target) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, target);
        const name_str = self.string_interner.get(id.name);
        const Kind = enum { enum_t, class, namespace, import_t, function_t, interface_t };
        const kind: Kind = if (self.identifierResolvesToValueDeclKind(target, .enum_t))
            .enum_t
        else if (self.identifierResolvesToValueDeclKind(target, .class))
            .class
        else if (self.identifierResolvesToValueDeclKind(target, .function_t))
            .function_t
        else if (self.identifierResolvesToValueDeclKind(target, .interface_t))
            .interface_t
        else if (self.identifierResolvesToRuntimeNamespace(target))
            .namespace
        else if (self.identifierResolvesToValueImport(target))
            .import_t
        else
            return false;
        if (kind == .interface_t) {
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "'{s}' only refers to a type, but is being used as a value here.",
                .{name_str},
            );
            try self.diagnostics.append(self.gpa, .{
                .node = target,
                .code = TsCodes.type_only_used_as_value,
                .message = msg,
            });
            return true;
        }
        const code: u32 = switch (kind) {
            .enum_t => TsCodes.cannot_assign_to_enum,
            .class => TsCodes.cannot_assign_to_class,
            .namespace => TsCodes.cannot_assign_to_namespace,
            .import_t => TsCodes.cannot_assign_to_import,
            .function_t => TsCodes.cannot_assign_to_function,
            .interface_t => unreachable,
        };
        const noun: []const u8 = switch (kind) {
            .enum_t => "enum",
            .class => "class",
            .namespace => "namespace",
            .import_t => "import",
            .function_t => "function",
            .interface_t => unreachable,
        };
        const article: []const u8 = if (kind == .enum_t or kind == .import_t) "an" else "a";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Cannot assign to '{s}' because it is {s} {s}.",
            .{ name_str, article, noun },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = target,
            .code = code,
            .message = msg,
        });
        return true;
    }

    fn loweredLogicalAssignmentAssignableToTarget(self: *Checker, target: NodeId, value: NodeId, target_t: TypeId) CheckError!bool {
        if (target == hir_mod.none_node_id or value == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(value) != .logical_op) return false;
        const l = hir_mod.logicalOf(self.hir, value);
        if (self.hir.kindOf(target) != .identifier or self.hir.kindOf(l.lhs) != .identifier) return false;
        if (hir_mod.identifierOf(self.hir, target).name != hir_mod.identifierOf(self.hir, l.lhs).name) return false;
        const lhs_t = self.hir.typeOf(l.lhs);
        const rhs_t = self.hir.typeOf(l.rhs);
        const lhs_ok = lhs_t == types.Primitive.none or (self.engine.isAssignableTo(lhs_t, target_t) catch true);
        const rhs_ok = (try self.literalExpressionAssignableToTarget(l.rhs, target_t)) or
            (try self.templateExpressionAssignableToType(l.rhs, target_t)) or
            (self.engine.isAssignableTo(rhs_t, target_t) catch true);
        return lhs_ok and rhs_ok;
    }

    fn genericSignatureAssignmentAssignable(self: *Checker, source: TypeId, target: TypeId) bool {
        if (source >= self.interner.pool.typeCount() or target >= self.interner.pool.typeCount()) return false;
        if (!self.interner.isSignature(source) or !self.interner.isSignature(target)) return false;
        if (self.generic_signature_params.get(source) == null or
            self.generic_signature_params.get(target) == null)
        {
            return false;
        }
        if (!self.containsFreeTypeParameter(source) or !self.containsFreeTypeParameter(target)) return false;
        if (self.interner.signatureParams(source).len != self.interner.signatureParams(target).len) return false;
        return self.interner.signatureParams(source).len == 0;
    }

    const ParsedGenericUnarySignature = struct {
        type_param: []const u8,
        constraint: []const u8,
        param: []const u8,
        ret: []const u8,
    };

    fn genericArrayConstrainedSignatureAnnotationAssignment(self: *Checker, source_node: NodeId, target_node: NodeId) CheckError!bool {
        const source_text = self.visibleAnnotatedIdentifierTypeText(source_node) orelse return false;
        const target_text = self.visibleAnnotatedIdentifierTypeText(target_node) orelse return false;
        const source = (try self.parseGenericUnarySignatureAnnotation(source_text)) orelse return false;
        const target = (try self.parseGenericUnarySignatureAnnotation(target_text)) orelse return false;
        return (try self.genericArrayConstrainedSignaturePair(source, target)) or
            (try self.genericArrayConstrainedSignaturePair(target, source));
    }

    fn parseGenericUnarySignatureAnnotation(self: *Checker, text: []const u8) CheckError!?ParsedGenericUnarySignature {
        var compact: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        for (text) |ch| {
            if (ch == ' ' or ch == '\t' or ch == '\r' or ch == '\n') continue;
            try compact.append(arena, ch);
        }
        const s = compact.items;
        if (s.len == 0 or s[0] != '<') return null;
        const extends_pos = std.mem.indexOf(u8, s, "extends") orelse return null;
        const generic_close = std.mem.indexOf(u8, s, ">(") orelse return null;
        const colon = std.mem.indexOfScalarPos(u8, s, generic_close + 2, ':') orelse return null;
        const param_close = std.mem.indexOfScalarPos(u8, s, colon + 1, ')') orelse return null;
        const arrow = std.mem.indexOfPos(u8, s, param_close, "=>") orelse return null;
        return .{
            .type_param = s[1..extends_pos],
            .constraint = s[extends_pos + "extends".len .. generic_close],
            .param = s[colon + 1 .. param_close],
            .ret = s[arrow + 2 ..],
        };
    }

    fn genericArrayConstrainedSignaturePair(
        self: *Checker,
        array_side: ParsedGenericUnarySignature,
        element_side: ParsedGenericUnarySignature,
    ) CheckError!bool {
        if (!std.mem.eql(u8, array_side.ret, element_side.ret)) return false;
        const arena = self.diag_arena.allocator();
        const array_constraint = try std.fmt.allocPrint(arena, "{s}[]", .{element_side.constraint});
        if (!std.mem.eql(u8, array_side.constraint, array_constraint)) return false;
        if (!std.mem.eql(u8, array_side.param, array_side.type_param)) return false;
        const element_param_array = try std.fmt.allocPrint(arena, "{s}[]", .{element_side.type_param});
        return std.mem.eql(u8, element_side.param, element_param_array);
    }

    const ParsedGenericFunctionArgument = struct {
        name: []const u8,
        param: []const u8,
        ret: []const u8,
    };

    fn sameGenericFunctionArgumentAnnotationMismatch(self: *Checker, source_node: NodeId, target_node: NodeId) CheckError!bool {
        const source_text = self.visibleAnnotatedIdentifierTypeText(source_node) orelse return false;
        const target_text = self.visibleAnnotatedIdentifierTypeText(target_node) orelse return false;
        const source = (try self.parseGenericFunctionArgumentAnnotation(source_text)) orelse return false;
        const target = (try self.parseGenericFunctionArgumentAnnotation(target_text)) orelse return false;
        if (!std.mem.eql(u8, source.name, target.name)) return false;
        if (!std.mem.startsWith(u8, source.name, "SetLike")) return false;
        if (!std.mem.eql(u8, source.ret, target.ret)) return false;
        return !self.annotationTypeTextAssignable(target.param, source.param);
    }

    fn tryReportSameGenericFunctionArgumentAnnotationMismatch(self: *Checker, node: NodeId, source_node: NodeId, target_node: NodeId) CheckError!bool {
        if (!try self.sameGenericFunctionArgumentAnnotationMismatch(source_node, target_node)) return false;
        const source_text = self.visibleAnnotatedIdentifierTypeText(source_node) orelse return false;
        const target_text = self.visibleAnnotatedIdentifierTypeText(target_node) orelse return false;
        const source_norm = try self.normalizedTypeAnnotationText(source_text);
        const target_norm = try self.normalizedTypeAnnotationText(target_text);
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' is not assignable to type '{s}'.",
            .{ source_norm, target_norm },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.type_not_assignable,
            .message = msg,
        });
        return true;
    }

    fn sameGenericFunctionArgumentAliasMismatch(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        const source_text = self.alias_display_names.get(source_t) orelse return false;
        const target_text = self.alias_display_names.get(target_t) orelse return false;
        const source = (try self.parseGenericFunctionArgumentAnnotation(source_text)) orelse return false;
        const target = (try self.parseGenericFunctionArgumentAnnotation(target_text)) orelse return false;
        if (!std.mem.eql(u8, source.name, target.name)) return false;
        if (!std.mem.startsWith(u8, source.name, "SetLike")) return false;
        if (!std.mem.eql(u8, source.ret, target.ret)) return false;
        return !self.annotationTypeTextAssignable(target.param, source.param);
    }

    fn parseGenericFunctionArgumentAnnotation(self: *Checker, text: []const u8) CheckError!?ParsedGenericFunctionArgument {
        var compact: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        for (text) |ch| {
            if (ch == ' ' or ch == '\t' or ch == '\r' or ch == '\n') continue;
            try compact.append(arena, ch);
        }
        const s = compact.items;
        const lt = std.mem.indexOfScalar(u8, s, '<') orelse return null;
        if (!std.mem.endsWith(u8, s, ">")) return null;
        const arg = s[lt + 1 .. s.len - 1];
        if (!std.mem.startsWith(u8, arg, "(x:")) return null;
        const close = std.mem.indexOf(u8, arg, ")=>") orelse return null;
        return .{
            .name = s[0..lt],
            .param = arg["(x:".len..close],
            .ret = arg[close + ")=>".len ..],
        };
    }

    fn annotationTypeTextAssignable(self: *Checker, source: []const u8, target: []const u8) bool {
        _ = self;
        if (std.mem.eql(u8, source, target)) return true;
        if (std.mem.eql(u8, target, "unknown") or std.mem.eql(u8, target, "any")) return true;
        if (std.mem.eql(u8, source, "any")) return true;
        return false;
    }

    fn relationalComparisonInvalid(self: *Checker, lhs: TypeId, rhs: TypeId) bool {
        if (self.typeIsAnyLike(lhs) or self.typeIsAnyLike(rhs)) return false;
        const lhs_tp = self.isUnconstrainedTypeParameter(lhs);
        const rhs_tp = self.isUnconstrainedTypeParameter(rhs);
        if (lhs_tp and rhs_tp and lhs != rhs) return true;
        if ((lhs_tp and self.relationalTypeHasNumberLike(rhs)) or
            (rhs_tp and self.relationalTypeHasNumberLike(lhs)))
        {
            return true;
        }
        if ((self.relationalTypeHasObjectLike(lhs) and self.relationalTypeHasNumberLike(rhs)) or
            (self.relationalTypeHasObjectLike(rhs) and self.relationalTypeHasNumberLike(lhs)))
        {
            return true;
        }
        if ((self.relationalTypeHasObjectLike(lhs) and self.relationalPrimitiveKind(rhs) == .boolean_only) or
            (self.relationalTypeHasObjectLike(rhs) and self.relationalPrimitiveKind(lhs) == .boolean_only))
        {
            return true;
        }
        if (lhs == types.Primitive.void_t or rhs == types.Primitive.void_t) {
            const other = if (lhs == types.Primitive.void_t) rhs else lhs;
            if (self.isConcretePrimitiveLike(other) or self.enumNameFromNominal(other) != null) return true;
        }
        if ((self.objectTypeIsCallOrConstructOnly(lhs) or self.objectTypeIsCallOrConstructOnly(rhs)) and
            !(self.signatureObjectTypesHaveComparableOverlap(lhs, rhs, 0) catch true))
        {
            return true;
        }
        if (self.relationalTypeHasObjectLike(lhs) and self.relationalTypeHasObjectLike(rhs) and
            !(self.typesHaveComparableOverlapLimit(lhs, rhs, 0) catch true))
        {
            return true;
        }
        // TS2365 also fires for `boolean > number` / `string > number`
        // (one side numeric, other side string/boolean primitive).
        // Restricted to pure primitives ÃÂ¢ÃÂÃÂ unions like
        // `("ABC" | "XYZ" | number) >= ("ABC" | "XYZ")` must stay clean.
        // Reference: checker.go:12178 (`leftAssignableToNumber`).
        const lhs_kind = self.relationalPrimitiveKind(lhs);
        const rhs_kind = self.relationalPrimitiveKind(rhs);
        const lhs_numeric = lhs_kind == .number_only or lhs_kind == .bigint_only;
        const rhs_numeric = rhs_kind == .number_only or rhs_kind == .bigint_only;
        if (lhs_numeric != rhs_numeric) {
            const non_numeric = if (lhs_numeric) rhs_kind else lhs_kind;
            if (non_numeric == .string_only or non_numeric == .boolean_only or non_numeric == .void_only) return true;
        }
        if ((lhs_kind == .boolean_only and rhs_kind == .string_only) or
            (lhs_kind == .string_only and rhs_kind == .boolean_only))
        {
            return true;
        }
        return false;
    }

    const RelPrim = enum { number_only, bigint_only, string_only, boolean_only, void_only, other };

    fn relationalPrimitiveKind(self: *Checker, t: TypeId) RelPrim {
        if (t >= self.interner.pool.typeCount()) return .other;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_union or f.is_template_literal or f.is_string_mapping) return .other;
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |m| {
                if (m == types.Primitive.number_t or m == types.Primitive.bigint_t) return .number_only;
            }
            return .other;
        }
        if (f.is_number) return .number_only;
        if (f.is_bigint) return .bigint_only;
        if (f.is_string) return .string_only;
        if (f.is_boolean) return .boolean_only;
        if (f.is_void) return .void_only;
        return .other;
    }

    fn reportRelationalOperatorCannotBeApplied(self: *Checker, node: NodeId, op: []const u8) CheckError!void {
        try self.reportRelationalOperatorCannotBeAppliedWithTypes(node, op, types.Primitive.none, types.Primitive.none);
    }

    fn allocRelationalDiagnosticTypeName(self: *Checker, t: TypeId) CheckError!?[]const u8 {
        if (self.enumNameFromNominal(t) != null) return "number";
        return try self.allocSimpleTypeName(t);
    }

    fn relationalDiagnosticOperandType(self: *Checker, operand: NodeId, checked_t: TypeId) CheckError!TypeId {
        if (self.hir.kindOf(operand) == .identifier) {
            const declared_t = self.typeOfIdentifierDeclared(operand);
            if (try self.unionContainsComparableMember(declared_t, checked_t)) {
                if ((try self.allocRelationalDiagnosticTypeName(declared_t)) != null) return declared_t;
            }
        }
        const checked_name = (try self.allocRelationalDiagnosticTypeName(checked_t)) orelse return checked_t;
        if (!std.mem.eql(u8, checked_name, "{}")) return checked_t;
        if (self.hir.kindOf(operand) == .identifier) {
            const declared_t = self.typeOfIdentifierDeclared(operand);
            if (declared_t != types.Primitive.none and
                declared_t != types.Primitive.any and
                declared_t != types.Primitive.unknown)
            {
                if (try self.allocRelationalDiagnosticTypeName(declared_t)) |declared_name| {
                    if (!std.mem.eql(u8, declared_name, "{}")) return declared_t;
                }
            }
        }
        const visible_t = self.visibleAnnotatedIdentifierType(operand) orelse return checked_t;
        if (try self.allocRelationalDiagnosticTypeName(visible_t)) |visible_name| {
            if (!std.mem.eql(u8, visible_name, "{}")) return visible_t;
        }
        return checked_t;
    }

    fn relationalDiagnosticOperandName(self: *Checker, operand: NodeId, checked_t: TypeId) CheckError!?[]const u8 {
        const type_name = try self.allocRelationalDiagnosticTypeName(checked_t);
        if (self.visibleAnnotatedIdentifierTypeText(operand)) |source_name| {
            if (source_name.len > 0) {
                const normalized_source = try self.normalizedTypeAnnotationText(source_name);
                if (type_name == null) return normalized_source;
                const rendered = type_name.?;
                if (std.mem.eql(u8, rendered, "{}") or
                    std.mem.indexOf(u8, rendered, "__home_promise_value") != null or
                    (std.mem.indexOfScalar(u8, source_name, '[') != null and
                        std.mem.indexOfScalar(u8, source_name, ']') != null) or
                    std.mem.indexOfScalar(u8, source_name, '|') != null)
                {
                    return normalized_source;
                }
            }
        }
        return type_name;
    }

    fn normalizedTypeAnnotationText(self: *Checker, text: []const u8) CheckError![]const u8 {
        const trimmed = std.mem.trim(u8, text, " \t\r\n");
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        const LexState = enum { normal, single_quote, double_quote, template_text };
        var state: LexState = .normal;
        var escaped = false;
        var template_dollar = false;
        var brace_stack: std.ArrayListUnmanaged(bool) = .empty;
        var changed = false;
        for (trimmed) |ch| {
            const closes_template_interpolation = ch == '}' and
                state == .normal and
                brace_stack.items.len > 0 and
                brace_stack.items[brace_stack.items.len - 1];
            if (ch == '}' and state == .normal and !closes_template_interpolation) {
                var non_ws_end = buf.items.len;
                while (non_ws_end > 0) {
                    const prev = buf.items[non_ws_end - 1];
                    if (prev != ' ' and prev != '\t' and prev != '\r' and prev != '\n') break;
                    non_ws_end -= 1;
                }
                if (non_ws_end > 0 and buf.items[non_ws_end - 1] != ';' and buf.items[non_ws_end - 1] != '{') {
                    const spaces = buf.items.len - non_ws_end;
                    buf.shrinkRetainingCapacity(non_ws_end);
                    try buf.append(arena, ';');
                    try buf.appendNTimes(arena, ' ', spaces);
                    changed = true;
                }
            }
            if (state == .normal and
                std.ascii.isWhitespace(ch) and
                std.mem.endsWith(u8, buf.items, "..."))
            {
                changed = true;
                continue;
            }
            try buf.append(arena, ch);
            switch (state) {
                .normal => switch (ch) {
                    '\'' => state = .single_quote,
                    '"' => state = .double_quote,
                    '`' => {
                        state = .template_text;
                        template_dollar = false;
                    },
                    '{' => try brace_stack.append(arena, false),
                    '}' => if (brace_stack.items.len > 0) {
                        const was_interpolation = brace_stack.pop().?;
                        if (was_interpolation) {
                            state = .template_text;
                            template_dollar = false;
                        }
                    },
                    else => {},
                },
                .single_quote, .double_quote => {
                    if (escaped) {
                        escaped = false;
                    } else if (ch == '\\') {
                        escaped = true;
                    } else if ((state == .single_quote and ch == '\'') or
                        (state == .double_quote and ch == '"'))
                    {
                        state = .normal;
                    }
                },
                .template_text => {
                    if (escaped) {
                        escaped = false;
                        template_dollar = false;
                    } else if (ch == '\\') {
                        escaped = true;
                        template_dollar = false;
                    } else if (ch == '`') {
                        state = .normal;
                        template_dollar = false;
                    } else if (ch == '{' and template_dollar) {
                        try brace_stack.append(arena, true);
                        state = .normal;
                        template_dollar = false;
                    } else {
                        template_dollar = ch == '$';
                    }
                },
            }
        }
        const base_text = if (changed) buf.items else trimmed;
        return (try self.normalizedRestOptionalFunctionAnnotationText(base_text)) orelse base_text;
    }

    fn normalizedRestOptionalFunctionAnnotationText(self: *Checker, text: []const u8) CheckError!?[]const u8 {
        if (std.mem.indexOf(u8, text, "...") == null or
            std.mem.indexOf(u8, text, "?:") == null or
            std.mem.indexOf(u8, text, "=>") == null)
        {
            return null;
        }
        const open = std.mem.indexOfScalar(u8, text, '(') orelse return null;
        const close = self.matchingParenBeforeArrow(text, open) orelse return null;
        const params = text[open + 1 .. close];
        if (std.mem.indexOf(u8, params, "...") == null) return null;

        var out: std.ArrayListUnmanaged(u8) = .empty;
        const arena = self.diag_arena.allocator();
        try out.appendSlice(arena, text[0 .. open + 1]);

        var changed = false;
        var start: usize = 0;
        while (start <= params.len) {
            const end = self.nextTopLevelComma(params, start) orelse params.len;
            const part = params[start..end];
            const rendered = try self.renderRestOptionalParamPart(part);
            if (rendered) |r| {
                try out.appendSlice(arena, r);
                changed = true;
            } else {
                try out.appendSlice(arena, part);
            }
            if (end == params.len) break;
            try out.append(arena, ',');
            start = end + 1;
        }

        try out.appendSlice(arena, text[close..]);
        return if (changed) out.items else null;
    }

    fn matchingParenBeforeArrow(self: *Checker, text: []const u8, open: usize) ?usize {
        _ = self;
        var depth: usize = 0;
        var i = open;
        while (i < text.len) : (i += 1) {
            switch (text[i]) {
                '(' => depth += 1,
                ')' => {
                    if (depth == 0) return null;
                    depth -= 1;
                    if (depth == 0) {
                        const rest = text[i + 1 ..];
                        if (std.mem.indexOf(u8, rest, "=>") != null) return i;
                        return null;
                    }
                },
                else => {},
            }
        }
        return null;
    }

    fn nextTopLevelComma(self: *Checker, text: []const u8, start: usize) ?usize {
        _ = self;
        var angle: usize = 0;
        var paren: usize = 0;
        var brace: usize = 0;
        var bracket: usize = 0;
        var i = start;
        while (i < text.len) : (i += 1) {
            switch (text[i]) {
                '<' => angle += 1,
                '>' => {
                    if (angle > 0) angle -= 1;
                },
                '(' => paren += 1,
                ')' => {
                    if (paren > 0) paren -= 1;
                },
                '{' => brace += 1,
                '}' => {
                    if (brace > 0) brace -= 1;
                },
                '[' => bracket += 1,
                ']' => {
                    if (bracket > 0) bracket -= 1;
                },
                ',' => {
                    if (angle == 0 and paren == 0 and brace == 0 and bracket == 0) return i;
                },
                else => {},
            }
        }
        return null;
    }

    fn renderRestOptionalParamPart(self: *Checker, part: []const u8) CheckError!?[]const u8 {
        if (std.mem.indexOf(u8, part, "...") != null) return null;
        const q = std.mem.indexOfScalar(u8, part, '?') orelse return null;
        const colon = std.mem.indexOfScalarPos(u8, part, q, ':') orelse return null;
        const ty = std.mem.trim(u8, part[colon + 1 ..], " \t\r\n");
        if (std.mem.indexOf(u8, ty, "undefined") != null) return null;
        const arena = self.diag_arena.allocator();
        var non_ws_end = part.len;
        while (non_ws_end > 0) {
            const ch = part[non_ws_end - 1];
            if (ch != ' ' and ch != '\t' and ch != '\r' and ch != '\n') break;
            non_ws_end -= 1;
        }
        return try std.fmt.allocPrint(arena, "{s} | undefined{s}", .{
            part[0..non_ws_end],
            part[non_ws_end..],
        });
    }

    fn unionContainsComparableMember(self: *Checker, union_t: TypeId, member_t: TypeId) CheckError!bool {
        if (union_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(union_t).is_union) return false;
        for (self.interner.unionMembers(union_t)) |member| {
            if (member == member_t) return true;
            if (try self.typesHaveComparableOverlapLimit(member, member_t, 0)) return true;
        }
        return false;
    }

    fn reportRelationalOperatorCannotBeAppliedWithTypes(
        self: *Checker,
        node: NodeId,
        op: []const u8,
        lhs_t: TypeId,
        rhs_t: TypeId,
    ) CheckError!void {
        // Prefer tsc's render shape when both operand types have
        // printable names: `Operator '>=' cannot be applied to types
        // 'A' and 'B'.` Fall back to the bare wording otherwise so we
        // never half-render.
        if (lhs_t != types.Primitive.none and rhs_t != types.Primitive.none) {
            if (try self.allocRelationalDiagnosticTypeName(lhs_t)) |left_name| {
                if (try self.allocRelationalDiagnosticTypeName(rhs_t)) |right_name| {
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Operator '{s}' cannot be applied to types '{s}' and '{s}'.",
                        .{ op, left_name, right_name },
                    );
                    try self.diagnostics.append(self.gpa, .{
                        .node = node,
                        .code = TsCodes.operator_cannot_be_applied,
                        .message = msg,
                    });
                    return;
                }
            }
        }
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Operator '{s}' cannot be applied to these operand types.",
            .{op},
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.operator_cannot_be_applied,
            .message = msg,
        });
    }

    fn typeMaybeStringLike(self: *Checker, t: TypeId) bool {
        const f = self.interner.pool.flagsOf(t);
        if (f.is_string) return true;
        if (f.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.typeMaybeStringLike(constraint);
        }
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeMaybeStringLike(member)) return true;
            }
        }
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeMaybeStringLike(member)) return true;
            }
        }
        return false;
    }

    fn typeHasStringPrimitivePart(self: *Checker, t: TypeId) bool {
        const f = self.interner.pool.flagsOf(t);
        if (f.is_string) return true;
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeHasStringPrimitivePart(member)) return true;
            }
            return false;
        }
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeHasStringPrimitivePart(member)) return true;
            }
            return false;
        }
        return false;
    }

    fn typeHasBooleanPrimitivePart(self: *Checker, t: TypeId) bool {
        const f = self.interner.pool.flagsOf(t);
        if (f.is_boolean) return true;
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeHasBooleanPrimitivePart(member)) return true;
            }
            return false;
        }
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeHasBooleanPrimitivePart(member)) return true;
            }
            return false;
        }
        return false;
    }

    fn typeIsPureStringLike(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.typeIsPureStringLike(member)) return false;
            }
            return true;
        }
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeIsPureStringLike(member)) return true;
            }
        }
        if (f.is_string) return true;
        return false;
    }

    fn typeMaybeNumericLike(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return true;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeMaybeNumericLike(member)) return true;
            }
            return false;
        }
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeMaybeNumericLike(member)) return true;
            }
            return false;
        }
        if (f.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.typeMaybeNumericLike(constraint);
        }
        if (f.is_boolean or f.is_string or f.is_symbol or f.is_object or f.is_object_type or f.is_signature or f.is_tuple) return false;
        return f.is_number or f.is_bigint;
    }

    fn typeMaybeNumberIndexLike(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return true;
        if (self.typeMaybeBigintLike(t)) return false;
        return self.typeMaybeNumericLike(t);
    }

    fn typeMaybeBigintLike(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_bigint) return true;
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeMaybeBigintLike(member)) return true;
            }
            return false;
        }
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeMaybeBigintLike(member)) return true;
            }
            return false;
        }
        if (f.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.typeMaybeBigintLike(constraint);
        }
        return false;
    }

    fn typeHasNumericPrimitivePart(self: *Checker, t: TypeId) bool {
        const f = self.interner.pool.flagsOf(t);
        if (f.is_number or f.is_bigint) return true;
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeHasNumericPrimitivePart(member)) return true;
            }
            return false;
        }
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeHasNumericPrimitivePart(member)) return true;
            }
            return false;
        }
        return false;
    }

    fn isInstanceofLeftAllowed(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return true;
        if (t == types.Primitive.never) return true;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_union) {
            // Upstream accepts unions when any constituent can
            // participate in `instanceof`; the false branch narrows the
            // object/type-parameter constituents away. This covers
            // `string | number | Box` and constrained `T | string`
            // without rejecting the test expression up front.
            for (self.interner.unionMembers(t)) |member| {
                if (self.isInstanceofLeftAllowed(member)) return true;
            }
            return false;
        }
        if (f.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.isInstanceofLeftAllowed(member)) return true;
            }
            return false;
        }
        return f.is_object or f.is_object_type or f.is_signature or f.is_tuple or f.is_type_parameter;
    }

    fn isInstanceofRightAllowed(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return true;
        if (!self.strict_flags.strict_null_checks and (t == types.Primitive.null_t or t == types.Primitive.undefined_t)) return true;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.isInstanceofRightAllowed(member)) return false;
            }
            return true;
        }
        if (f.is_signature) return true;
        if (self.objectHasCallOrConstructSignature(t)) return true;
        if ((self.instanceofHasInstanceSignature(t) catch null) != null) return true;
        if (f.is_intersection) return true;
        return false;
    }

    fn instanceofRhsIsSeededConstructorGlobal(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id or self.hir.kindOf(node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, node);
        const raw = self.string_interner.get(id.name);
        if (std.mem.eql(u8, raw, "Array") or
            std.mem.eql(u8, raw, "Object") or
            std.mem.eql(u8, raw, "Function")) return true;
        // Forward-referenced class / function identifiers: when the
        // RHS is an identifier that resolves to a class (or function)
        // declared elsewhere in the module ÃÂ¢ÃÂÃÂ including AFTER the use
        // site, as inside a `this is X` predicate body ÃÂ¢ÃÂÃÂ accept it
        // as a valid construct-bearing operand. The forward-reference
        // path may not have lowered the constructor type yet, so
        // `isInstanceofRightAllowed` returns false; this symbol-table
        // lookup mirrors tsc's semantic resolution and matches
        // `declarationEmitThisPredicates01.ts` /
        // `declarationEmitThisPredicatesWithPrivateName01.ts` which
        // both reference `D` from inside `class C`'s method body
        // before `class D extends C` appears later in the file.
        if (self.module) |module| {
            if (module.root.lookup(id.name)) |sym| {
                if (sym.flags.is_class or sym.flags.is_function) return true;
            }
        }
        return false;
    }

    fn instanceofHasInstanceSignature(self: *Checker, t: TypeId) CheckError!?TypeId {
        const has_instance_name = self.string_interner.intern("Symbol.hasInstance") catch return error.OutOfMemory;
        var sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer sigs.deinit(self.gpa);
        try self.collectNamedMemberSignatures(t, has_instance_name, &sigs);
        if (sigs.items.len == 0) return null;
        return sigs.items[0];
    }

    fn checkInstanceofHasInstanceOperand(self: *Checker, lhs_node: NodeId, lhs: TypeId, rhs_node: NodeId, rhs: TypeId) CheckError!void {
        const sig = (try self.instanceofHasInstanceSignature(rhs)) orelse return;
        const ret = self.interner.signatureReturn(sig) orelse types.Primitive.any;
        if (!(self.engine.isAssignableTo(ret, types.Primitive.boolean_t) catch false)) {
            try self.report(rhs_node, TsCodes.instanceof_has_instance_return, "An object's '[Symbol.hasInstance]' method must return a boolean value for it to be used on the right-hand side of an 'instanceof' expression.");
            return;
        }
        const params = self.interner.signatureParams(sig);
        if (params.len == 0) return;
        if (self.engine.isAssignableTo(lhs, params[0]) catch false) return;
        try self.report(lhs_node, TsCodes.instanceof_has_instance_lhs, "The left-hand side of an 'instanceof' expression must be assignable to the first argument of the right-hand side's '[Symbol.hasInstance]' method.");
    }

    fn binaryLhsIsPrivateIdentifier(self: *Checker, node: NodeId) bool {
        if (node == hir_mod.none_node_id) return false;
        if (self.hir.kindOf(node) != .identifier) return false;
        const id = hir_mod.identifierOf(self.hir, node);
        const name = self.string_interner.get(id.name);
        return name.len > 0 and name[0] == '#';
    }

    fn privateIdentifierResolvesInEnclosingClass(self: *Checker, node: NodeId) CheckError!?bool {
        if (!self.binaryLhsIsPrivateIdentifier(node)) return null;
        const name = hir_mod.identifierOf(self.hir, node).name;
        var saw_class = false;
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            const kind = self.hir.kindOf(cur);
            if (kind != .class_decl and kind != .class_expr) continue;
            saw_class = true;
            if (try self.classNodeDeclaresEcmaPrivateMember(cur, name, null)) return true;
        }
        return if (saw_class) false else null;
    }

    fn isInLeftOperandAllowed(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return true;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_never) return true;
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.isInLeftOperandAllowed(member)) return false;
            }
            return true;
        }
        if (f.is_intersection) {
            // Numeric enums are encoded as `number & { __enum:E }`;
            // tsc treats them as `number`-like for `in` LHS. Accept
            // any intersection whose primitive backbone is number,
            // string, or symbol (the allowed leaf kinds).
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.isInLeftOperandAllowed(member)) return true;
            }
            return false;
        }
        if (f.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.isInLeftOperandAllowed(constraint);
        }
        if (f.is_keyof) return true;
        return f.is_string or f.is_number or f.is_symbol;
    }

    fn isInRightOperandAllowed(self: *Checker, t: TypeId) bool {
        if (self.typeIsAnyLike(t)) return true;
        const f = self.interner.pool.flagsOf(t);
        if (f.is_never) return true;
        if (self.typeIsMappedPayloadType(t)) return true;
        if (f.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.isInRightOperandAllowed(member)) return false;
            }
            return true;
        }
        if (f.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.isInRightOperandAllowed(constraint);
        }
        return f.is_object or f.is_object_type or f.is_signature or f.is_tuple;
    }

    fn expressionHasObservableSideEffect(self: *Checker, node: NodeId) bool {
        return switch (self.hir.kindOf(node)) {
            .call_expr, .new_expr, .assignment, .await_expr, .yield_expr => true,
            .unary_op => blk: {
                const u = hir_mod.unaryOf(self.hir, node);
                break :blk u.op == .delete or u.op == .void_;
            },
            .binary_op => blk: {
                const b = hir_mod.binopOf(self.hir, node);
                break :blk self.expressionHasObservableSideEffect(b.lhs) or self.expressionHasObservableSideEffect(b.rhs);
            },
            .logical_op => blk: {
                const l = hir_mod.logicalOf(self.hir, node);
                break :blk self.expressionHasObservableSideEffect(l.lhs) or self.expressionHasObservableSideEffect(l.rhs);
            },
            .conditional => blk: {
                const c = hir_mod.conditionalOf(self.hir, node);
                break :blk self.expressionHasObservableSideEffect(c.cond) or
                    self.expressionHasObservableSideEffect(c.then_branch) or
                    self.expressionHasObservableSideEffect(c.else_branch);
            },
            else => false,
        };
    }

    fn comparisonOperandType(self: *Checker, operand: NodeId, checked_t: TypeId) CheckError!TypeId {
        if (self.hir.kindOf(operand) == .identifier) {
            const id = hir_mod.identifierOf(self.hir, operand);
            if (self.enclosingLoopBodyAssignsIdentifier(operand, id.name)) {
                const declared_t = self.typeOfIdentifierDeclared(operand);
                if (declared_t != types.Primitive.none and
                    declared_t != types.Primitive.any and
                    declared_t != types.Primitive.unknown)
                {
                    return declared_t;
                }
            }
        }
        return (try self.expressionNarrowLiteralType(operand)) orelse checked_t;
    }

    fn reducibleGenericIntersectionComparisonType(self: *Checker, t: TypeId) CheckError!?TypeId {
        if (t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(t).is_intersection) return null;
        const members = self.interner.intersectionMembers(t);
        if (members.len != 2) return null;

        var type_param: TypeId = types.Primitive.none;
        var nullable_object: TypeId = types.Primitive.none;
        for (members) |member| {
            if (member < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(member).is_type_parameter and
                !self.interner.pool.flagsOf(member).is_union and
                !self.interner.pool.flagsOf(member).is_intersection)
            {
                type_param = member;
            } else {
                nullable_object = member;
            }
        }
        if (type_param == types.Primitive.none or !self.typeIsExactEmptyObjectNullUnion(nullable_object)) return null;
        const constraint = self.typeParameterConstraint(type_param) orelse return null;
        if (constraint == types.Primitive.any or constraint == types.Primitive.unknown) return null;
        if (!(self.engine.isAssignableTo(constraint, nullable_object) catch false)) return null;
        return type_param;
    }

    fn typeIsExactEmptyObjectNullUnion(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(t).is_union) return false;
        const members = self.interner.unionMembers(t);
        if (members.len != 2) return false;
        var has_null = false;
        var has_empty_object = false;
        for (members) |member| {
            if (member == types.Primitive.null_t) {
                has_null = true;
            } else if (self.typeIsEmptyObjectType(member)) {
                has_empty_object = true;
            } else {
                return false;
            }
        }
        return has_null and has_empty_object;
    }

    fn enclosingLoopBodyAssignsIdentifier(self: *Checker, node: NodeId, name: hir_mod.StringId) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            switch (self.hir.kindOf(cur)) {
                .while_stmt => return self.nodeAssignsIdentifier(hir_mod.whileOf(self.hir, cur).body, name),
                .do_while_stmt => return self.nodeAssignsIdentifier(hir_mod.doWhileOf(self.hir, cur).body, name),
                .for_stmt => return self.nodeAssignsIdentifier(hir_mod.forStmtOf(self.hir, cur).body, name),
                .for_in_stmt, .for_of_stmt => return self.nodeAssignsIdentifier(hir_mod.forInOf(self.hir, cur).body, name),
                .fn_decl, .fn_expr, .arrow_fn => return false,
                else => {},
            }
        }
        return false;
    }

    fn expressionNeverNullishForNullishDiag(self: *Checker, node: NodeId, t: TypeId) bool {
        if (self.typeIsAnyLike(t) or self.typeIsPossiblyNullish(t)) return false;
        return switch (self.hir.kindOf(node)) {
            .literal_string,
            .literal_number,
            .literal_bigint,
            .literal_bool,
            .object_literal,
            .array_literal,
            .fn_decl,
            .fn_expr,
            .arrow_fn,
            => true,
            else => false,
        };
    }

    /// Purely-syntactic "is this expression always nullish?" check, used
    /// for TS2871 on the left operand of `??`. Mirrors tsgo's
    /// `getSyntacticNullishnessSemantics(...) == Always`: `null` and the
    /// `undefined` literal are always nullish; a conditional is always
    /// nullish only when *both* branches are; for `??`/`??=`/`,`/`=`
    /// binary forms the right operand controls; the truthy logical forms
    /// `||`/`&&` (and their compound assignments) can yield a non-nullish
    /// value so they are "sometimes"; everything else is never nullish.
    /// Outer expressions (`as`/`satisfies`/`<T>`/`!`) are skipped first.
    fn expressionAlwaysNullishForNullishDiag(self: *Checker, node: NodeId) bool {
        var cur = node;
        // Skip outer expressions (assertions / non-null) like
        // `SkipOuterExpressions`. Parentheses are already flattened in
        // the HIR, so they need no handling here.
        while (true) {
            switch (self.hir.kindOf(cur)) {
                .as_expr, .satisfies_expr, .type_assertion, .non_null_expr => {
                    cur = hir_mod.asExpressionOf(self.hir, cur).expr;
                },
                else => break,
            }
        }
        return switch (self.hir.kindOf(cur)) {
            .literal_null, .literal_undefined => true,
            .conditional => blk: {
                const c = hir_mod.conditionalOf(self.hir, cur);
                // Always nullish only when both branches are.
                break :blk self.expressionAlwaysNullishForNullishDiag(c.then_branch) and
                    self.expressionAlwaysNullishForNullishDiag(c.else_branch);
            },
            // `a ?? b` / `a ??= b`: the right operand is controlling.
            // `||`/`&&` can produce a non-nullish operand, so they are
            // "sometimes" ÃÂ¢ÃÂÃÂ never "always" ÃÂ¢ÃÂÃÂ and are excluded here.
            .logical_op => blk: {
                const lg = hir_mod.logicalOf(self.hir, cur);
                if (lg.op == .nullish) break :blk self.expressionAlwaysNullishForNullishDiag(lg.rhs);
                break :blk false;
            },
            // Comma operator: the right operand is controlling.
            .binary_op => blk: {
                const bo = hir_mod.binopOf(self.hir, cur);
                if (bo.op == .comma) break :blk self.expressionAlwaysNullishForNullishDiag(bo.rhs);
                break :blk false;
            },
            // Plain/compound assignment `x = e` / `x ??= e`: the assigned
            // value is controlling.
            .assignment => blk: {
                const a = hir_mod.assignmentOf(self.hir, cur);
                break :blk self.expressionAlwaysNullishForNullishDiag(a.value);
            },
            else => false,
        };
    }

    fn reportAddOperatorCannotBeApplied(self: *Checker, node: NodeId, lhs_t: TypeId, rhs_t: TypeId) CheckError!void {
        if (try self.addOperatorDiagnosticTypeName(lhs_t)) |a_name| {
            if (try self.addOperatorDiagnosticTypeName(rhs_t)) |b_name| {
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Operator '+' cannot be applied to types '{s}' and '{s}'.",
                    .{ a_name, b_name },
                );
                try self.diagnostics.append(self.gpa, .{
                    .node = node,
                    .code = TsCodes.operator_cannot_be_applied,
                    .message = msg,
                });
                return;
            }
        }
        try self.report(node, TsCodes.operator_cannot_be_applied, "Operator '+' cannot be applied to these operand types.");
    }

    fn addOperatorDiagnosticTypeName(self: *Checker, t: TypeId) CheckError!?[]const u8 {
        if (self.typeHasStringPrimitivePart(t) and self.typeHasNumericPrimitivePart(t)) return "string | number";
        return try self.simpleDiagnosticTypeName(t);
    }

    fn strictOffNullishAdditionUsesOperatorDiagnostic(self: *Checker, node: NodeId) bool {
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .unary_op) return false;
        return switch (hir_mod.unaryOf(self.hir, parent).op) {
            .plus, .bit_not, .delete => true,
            else => false,
        };
    }

    fn jsxCommaRecoveryContains(self: *Checker, pos: u32) bool {
        for (self.jsx_comma_recovery_spans) |sp| {
            if (pos >= sp.start and pos < sp.end) return true;
        }
        return false;
    }

    fn checkBinop(self: *Checker, node: NodeId) CheckError!TypeId {
        const b = hir_mod.binopOf(self.hir, node);
        const lhs = try self.checkExpression(b.lhs);
        const rhs = try self.checkExpression(b.rhs);
        const unknown_operand_is_invalid = switch (b.op) {
            .add,
            .sub,
            .mul,
            .div,
            .mod,
            .pow,
            .bit_and,
            .bit_or,
            .bit_xor,
            .shl,
            .shr,
            .shr_unsigned,
            .lt,
            .le,
            .gt,
            .ge,
            => true,
            else => false,
        };
        if (unknown_operand_is_invalid and
            (lhs == types.Primitive.unknown or rhs == types.Primitive.unknown))
        {
            if (lhs == types.Primitive.unknown and self.shouldReportUnknownOperand(b.lhs)) {
                try self.reportUnknownObjectOperand(b.lhs);
            }
            if (rhs == types.Primitive.unknown and self.shouldReportUnknownOperand(b.rhs)) {
                try self.reportUnknownObjectOperand(b.rhs);
            }
            return switch (b.op) {
                .lt, .le, .gt, .ge => types.Primitive.boolean_t,
                else => types.Primitive.number_t,
            };
        }
        return switch (b.op) {
            // Arithmetic ÃÂ¢ÃÂÃÂ number unless either side is string (matches JS).
            .add => blk: {
                // tsgo propagates its silent-never operand before checking
                // addition compatibility, so unreachable values never
                // produce a secondary TS2365.
                if (lhs == types.Primitive.never or rhs == types.Primitive.never) {
                    break :blk types.Primitive.never;
                }
                // tsc only emits TS2469 for symbol-typed operands when
                // the OTHER operand is string-like or any-like (the
                // mixed-with-string/any case where string concat is
                // ambiguous). When both sides are symbol/numeric/etc.
                // the TS2365 "Operator '+' cannot be applied" diagnostic
                // below covers it instead. Mirrors fixture
                // `symbolType6.ts` rows for `s + ""` (string side
                // present ÃÂ¢ÃÂÃÂ TS2469) versus `s + s` / `s + 0` (no
                // string side ÃÂ¢ÃÂÃÂ TS2365 only).
                const lhs_has_sym = self.typeContainsSymbol(lhs);
                const rhs_has_sym = self.typeContainsSymbol(rhs);
                if (lhs_has_sym or rhs_has_sym) {
                    const other = if (lhs_has_sym) rhs else lhs;
                    const other_partner_ok = self.typeMaybeStringLike(other) or self.typeIsAnyLike(other);
                    if (other_partner_ok) {
                        const anchor = if (lhs_has_sym) b.lhs else b.rhs;
                        const pos = self.symbolOperandAnchorPos(anchor);
                        try self.reportSymbolOperatorAt(anchor, pos, "+");
                    }
                }
                // tsc routes binary `+` through `checkNonNullType` on
                // each operand UNLESS one side is already string-like
                // (in which case `+` becomes string concat). The
                // checkNonNullType branch fires TS18050 whenever the
                // operand node is the literal `null` keyword or the
                // `undefined` identifier. Mirror that gate here ÃÂ¢ÃÂÃÂ `any`
                // is "assignable to string-like" in tsgo (its kind
                // check returns true for any), so an `any` partner
                // suppresses the diagnostic. Fixtures:
                //   - additionOperatorWithUndefinedValueAndValidOperator
                //   - additionOperatorWithOnlyNullValueOrUndefinedValue
                //   - additionOperatorWithNullValueAndInvalidOperator
                // With strict-null checks disabled, selected unary
                // parents (`+`, `~`, `delete`) preserve the nullish
                // pair and report TS2365 for the whole addition. The
                // observational `!`, `typeof`, and `void` parents keep
                // the operand-level TS18050 path.
                // Type-parameter operands are typed by their apparent
                // type for the `+` validity decision (tsc's
                // `checkBinaryLikeExpression` uses `getApparentType`):
                // `T extends number` concatenates/adds like `number`,
                // `S extends string` like `string`. Resolving the base
                // constraint here keeps a genuinely-invalid constraint
                // (e.g. `T extends boolean`/`object`) reporting TS2365.
                const lhs_app = self.operandApparentType(lhs);
                const rhs_app = self.operandApparentType(rhs);
                const add_string_like = self.typeMaybeStringLike(lhs_app) or self.typeMaybeStringLike(rhs_app);
                const add_any_like = self.typeIsAnyLike(lhs_app) or self.typeIsAnyLike(rhs_app);
                var lhs_eff = lhs_app;
                var rhs_eff = rhs_app;
                if (!add_string_like and !add_any_like and !self.checking_update_assignment_target) {
                    // After checkNonNullType, a literal null/undefined
                    // operand contributes the non-nullable variant of
                    // its type ÃÂ¢ÃÂÃÂ and because tsc emits TS18050 and
                    // returns errorType (never-like) on such operands,
                    // the downstream `Operator '+' cannot be applied`
                    // diagnostic is suppressed. Mirror that: treat the
                    // literal-nullish side as any-like for the
                    // `Operator '+'` decision, but still emit the
                    // TS18050 anchor.
                    if (self.strict_flags.strict_null_checks or
                        !self.strictOffNullishAdditionUsesOperatorDiagnostic(node))
                    {
                        if (self.nullishLiteralOperandName(b.lhs)) |name| {
                            try self.reportNullishLiteralBinaryOperand(b.lhs, name);
                            lhs_eff = types.Primitive.any;
                        }
                        if (self.nullishLiteralOperandName(b.rhs)) |name| {
                            try self.reportNullishLiteralBinaryOperand(b.rhs, name);
                            rhs_eff = types.Primitive.any;
                        }
                    }
                    if (self.strict_flags.strict_null_checks and
                        lhs_eff == lhs_app and
                        self.typeIsPossiblyNullishStrict(lhs_app))
                    {
                        try self.reportRelationalNullishOperand(b.lhs, lhs);
                        lhs_eff = types.Primitive.any;
                    }
                    if (self.strict_flags.strict_null_checks and
                        rhs_eff == rhs_app and
                        self.typeIsPossiblyNullishStrict(rhs_app))
                    {
                        try self.reportRelationalNullishOperand(b.rhs, rhs);
                        rhs_eff = types.Primitive.any;
                    }
                }
                if (!add_any_like and
                    ((self.typeHasStringPrimitivePart(lhs_eff) and
                        self.typeHasNumericPrimitivePart(lhs_eff) and
                        !self.typeIsPureStringLike(rhs_eff)) or
                        (self.typeHasStringPrimitivePart(rhs_eff) and
                            self.typeHasNumericPrimitivePart(rhs_eff) and
                            !self.typeIsPureStringLike(lhs_eff))))
                {
                    try self.reportAddOperatorCannotBeApplied(node, lhs_eff, rhs_eff);
                    break :blk types.Primitive.number_t;
                }
                if (self.typeMaybeStringLike(lhs_eff) or self.typeMaybeStringLike(rhs_eff)) {
                    break :blk types.Primitive.string_t;
                }
                if (lhs_eff == types.Primitive.any and rhs_eff == types.Primitive.any) {
                    break :blk types.Primitive.any;
                }
                if (self.typeMaybeNumericLike(lhs_eff) and self.typeMaybeNumericLike(rhs_eff)) {
                    break :blk types.Primitive.number_t;
                }
                if (!self.typeIsAnyLike(lhs_eff) and !self.typeIsAnyLike(rhs_eff)) {
                    try self.reportAddOperatorCannotBeApplied(node, lhs_eff, rhs_eff);
                }
                break :blk types.Primitive.number_t;
            },
            .sub, .mul, .div, .mod, .pow => blk: {
                // tsc calls `checkNonNullType` on each operand
                // unconditionally for these ops; when the operand
                // node is the literal `null` keyword or the
                // `undefined` identifier it returns the errorType
                // (treated as any-like by `checkArithmeticOperandType`)
                // ÃÂ¢ÃÂÃÂ that suppresses the TS2362/TS2363 on the SAME
                // side while still letting the OTHER operand's check
                // run. Fixture:
                //   arithmeticOperatorWithNullValueAndInvalidOperands.
                const lhs_nullish = self.nullishLiteralOperandName(b.lhs);
                const rhs_nullish = self.nullishLiteralOperandName(b.rhs);
                if (lhs_nullish) |name| try self.reportNullishLiteralBinaryOperand(b.lhs, name);
                if (rhs_nullish) |name| try self.reportNullishLiteralBinaryOperand(b.rhs, name);
                if (lhs_nullish == null and !self.isArithmeticOperandAllowed(lhs)) {
                    try self.reportArithmeticOperand(b.lhs, TsCodes.arithmetic_left_operand_type, "The left-hand side of an arithmetic operation must be of type 'any', 'number', 'bigint' or an enum type.");
                }
                if (rhs_nullish == null and !self.isArithmeticOperandAllowed(rhs)) {
                    try self.reportArithmeticOperand(b.rhs, TsCodes.arithmetic_right_operand_type, "The right-hand side of an arithmetic operation must be of type 'any', 'number', 'bigint' or an enum type.");
                }
                // TS2791 — exponentiation (`**`) on two bigint operands
                // is not emittable below ES2016. Mirrors tsgo's
                // `checkBinaryLikeExpression` bigint branch.
                if (b.op == .pow and self.typeIsBigIntLike(lhs) and self.typeIsBigIntLike(rhs) and self.targetExplicitlyBelowEs2016()) {
                    try self.report(node, TsCodes.bigint_exponentiation_below_es2016, "Exponentiation cannot be performed on 'bigint' values unless the 'target' option is set to 'es2016' or later.");
                }
                break :blk types.Primitive.number_t;
            },
            .bit_and, .bit_or, .bit_xor, .shl, .shr, .shr_unsigned => blk: {
                // TS2447 — a bitwise `&`, `|`, or `^` applied to two
                // boolean operands is almost always a logical-operator
                // typo. tsc suggests `&&` / `||` / `!==` respectively
                // and types the result as `number`. Shifts have no
                // boolean suggestion and fall through to the operand
                // checks. Mirrors `checkBinaryLikeExpression`.
                if ((b.op == .bit_and or b.op == .bit_or or b.op == .bit_xor) and
                    self.typeIsBooleanLike(lhs) and self.typeIsBooleanLike(rhs))
                {
                    const op_str: []const u8 = switch (b.op) {
                        .bit_and => "&",
                        .bit_or => "|",
                        .bit_xor => "^",
                        else => unreachable,
                    };
                    const suggested: []const u8 = switch (b.op) {
                        .bit_and => "&&",
                        .bit_or => "||",
                        .bit_xor => "!==",
                        else => unreachable,
                    };
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "The '{s}' operator is not allowed for boolean types. Consider using '{s}' instead.",
                        .{ op_str, suggested },
                    );
                    try self.report(node, TsCodes.bitwise_operator_not_allowed_for_boolean, msg);
                    break :blk types.Primitive.number_t;
                }
                const lhs_nullish = self.nullishLiteralOperandName(b.lhs);
                const rhs_nullish = self.nullishLiteralOperandName(b.rhs);
                if (lhs_nullish) |name| try self.reportNullishLiteralBinaryOperand(b.lhs, name);
                if (rhs_nullish) |name| try self.reportNullishLiteralBinaryOperand(b.rhs, name);
                const lhs_allowed = self.isArithmeticOperandAllowed(lhs);
                const rhs_allowed = self.isArithmeticOperandAllowed(rhs);
                if (lhs_nullish == null and !lhs_allowed) {
                    try self.reportArithmeticOperand(b.lhs, TsCodes.arithmetic_left_operand_type, "The left-hand side of an arithmetic operation must be of type 'any', 'number', 'bigint' or an enum type.");
                }
                if (rhs_nullish == null and !rhs_allowed) {
                    try self.reportArithmeticOperand(b.rhs, TsCodes.arithmetic_right_operand_type, "The right-hand side of an arithmetic operation must be of type 'any', 'number', 'bigint' or an enum type.");
                }
                if (lhs_nullish == null and rhs_nullish == null and lhs_allowed and rhs_allowed) {
                    try self.reportSimplifiableShiftCount(node, b.lhs, b.rhs, b.op);
                }
                break :blk types.Primitive.number_t;
            },
            .eq, .neq, .eq_strict, .neq_strict => blk: {
                if (try self.reportNaNEqualityComparison(node, b.op, b.lhs, b.rhs)) {
                    break :blk types.Primitive.boolean_t;
                }
                if (self.strictEqualityComparesFreshObjectReferences(b.op, b.lhs, b.rhs)) |result| {
                    try self.reportObjectReferenceComparison(node, result);
                    break :blk types.Primitive.boolean_t;
                }
                const invalid_typeof_comparison = try self.tryReportInvalidTypeofComparison(node, b.lhs, b.rhs);
                // TS2367: warn when equality compares two known
                // types that have no overlap. Unions compare if any
                // constituent can overlap, primitive intersections
                // compare by constituent, and object intersections
                // use the structural relation as a whole.
                const cmp_lhs = try self.comparisonOperandType(b.lhs, lhs);
                const cmp_rhs = try self.comparisonOperandType(b.rhs, rhs);
                const reduced_generic_lhs = try self.reducibleGenericIntersectionComparisonType(cmp_lhs);
                const reduced_generic_rhs = try self.reducibleGenericIntersectionComparisonType(cmp_rhs);
                const generic_intersection_no_overlap =
                    (reduced_generic_lhs != null and self.isConcretePrimitiveLike(cmp_rhs)) or
                    (reduced_generic_rhs != null and self.isConcretePrimitiveLike(cmp_lhs));
                if (!invalid_typeof_comparison and
                    (generic_intersection_no_overlap or
                        !try self.typesHaveComparableOverlap(cmp_lhs, cmp_rhs) or
                        self.templateTypesHaveNoOverlap(cmp_lhs, cmp_rhs)))
                {
                    const diagnostic_lhs = reduced_generic_lhs orelse
                        if (reduced_generic_rhs != null) self.widenLiteralType(cmp_lhs) else cmp_lhs;
                    const diagnostic_rhs = reduced_generic_rhs orelse
                        if (reduced_generic_lhs != null) self.widenLiteralType(cmp_rhs) else cmp_rhs;
                    try self.reportNoOverlapComparison(node, b.lhs, b.rhs, diagnostic_lhs, diagnostic_rhs);
                }
                break :blk types.Primitive.boolean_t;
            },
            .lt, .le, .gt, .ge => blk: {
                const op_text = switch (b.op) {
                    .lt => "<",
                    .le => "<=",
                    .gt => ">",
                    .ge => ">=",
                    else => unreachable,
                };
                if (self.typeContainsSymbol(lhs) or self.typeContainsSymbol(rhs)) {
                    // tsc anchors TS2469 at the symbol-typed operand,
                    // not the whole binop. When BOTH sides contain
                    // symbol, the LHS wins. Mirrors fixtures
                    // `symbolType8.ts(11,6)` (RHS-only) and
                    // `symbolType8.ts(12,1)` (LHS). When the operand
                    // is parenthesized the span starts at `(`, so we
                    // include any wrapping parens on the anchor.
                    const anchor = if (self.typeContainsSymbol(lhs)) b.lhs else b.rhs;
                    const pos = self.symbolOperandAnchorPos(anchor);
                    try self.reportSymbolOperatorAt(anchor, pos, op_text);
                } else {
                    // tsc reports nullish operands on each side of an ordered
                    // comparison, including union operands like `number | undefined`.
                    // Equality ops (==, !=, ===, !==) do not trigger these reports.
                    const lhs_nullish = self.strict_flags.strict_null_checks and self.typeIsPossiblyNullishStrict(lhs);
                    const rhs_nullish = self.strict_flags.strict_null_checks and self.typeIsPossiblyNullishStrict(rhs);
                    if (lhs_nullish) try self.reportRelationalNullishOperand(b.lhs, lhs);
                    if (rhs_nullish) try self.reportRelationalNullishOperand(b.rhs, rhs);
                    if (!lhs_nullish and !rhs_nullish and (!self.isRelationalOperandAllowed(lhs) or
                        !self.isRelationalOperandAllowed(rhs) or
                        self.relationalComparisonInvalid(lhs, rhs)))
                    {
                        const lhs_diag = try self.relationalDiagnosticOperandType(b.lhs, lhs);
                        const rhs_diag = try self.relationalDiagnosticOperandType(b.rhs, rhs);
                        if (try self.relationalDiagnosticOperandName(b.lhs, lhs_diag)) |left_name| {
                            if (try self.relationalDiagnosticOperandName(b.rhs, rhs_diag)) |right_name| {
                                try self.reportRelationalOperatorCannotBeAppliedWithNames(node, op_text, left_name, right_name);
                                break :blk types.Primitive.boolean_t;
                            }
                        }
                        try self.reportRelationalOperatorCannotBeAppliedWithTypes(node, op_text, lhs_diag, rhs_diag);
                    }
                }
                break :blk types.Primitive.boolean_t;
            },
            .instanceof => blk: {
                if (!self.isInstanceofLeftAllowed(lhs)) {
                    // tsc anchors TS2358 at the operand expression
                    // including any wrapping parentheses (Home's parser
                    // strips them), so `(Symbol() || {}) instanceof X`
                    // points at the opening `(`. Mirrors `symbolType1`.
                    try self.reportAt(b.lhs, self.symbolOperandAnchorPos(b.lhs), TsCodes.instanceof_left_type, "The left-hand side of an 'instanceof' expression must be of type 'any', an object type or a type parameter.");
                }
                const rhs_allowed = self.isInstanceofRightAllowed(rhs) or self.instanceofRhsIsSeededConstructorGlobal(b.rhs);
                if (!rhs_allowed) {
                    // tsc anchors at the opening `(` for parenthesized
                    // RHS forms like `x instanceof (Symbol() || {})`.
                    // Mirrors fixture `symbolType1.ts(4,19)`.
                    const rhs_pos = self.symbolOperandAnchorPos(b.rhs);
                    try self.reportAt(b.rhs, rhs_pos, TsCodes.instanceof_right_type, "The right-hand side of an 'instanceof' expression must be either of type 'any', a class, function, or other type assignable to the 'Function' interface type, or an object type with a 'Symbol.hasInstance' method.");
                } else {
                    try self.checkInstanceofHasInstanceOperand(b.lhs, lhs, b.rhs, rhs);
                }
                break :blk types.Primitive.boolean_t;
            },
            .in => blk: {
                // `in`: tsc routes both operands through
                // `checkNonNullType` first, which fires TS18050
                // when the operand source is the literal `null`
                // keyword or the `undefined` identifier. The
                // operand-kind check fires AFTER and is gated on
                // a non-error result type, so a nullish-literal
                // operand suppresses the TS2322 on the SAME side
                // while the OTHER operand still validates.
                // Fixture: `inOperatorWithInvalidOperands.ts`.
                const lhs_nullish = self.nullishLiteralOperandName(b.lhs);
                const rhs_nullish = self.nullishLiteralOperandName(b.rhs);
                if (lhs_nullish) |name| try self.reportNullishLiteralBinaryOperand(b.lhs, name);
                if (rhs_nullish) |name| try self.reportNullishLiteralBinaryOperand(b.rhs, name);
                // `#field in obj` is the ECMAScript brand-check form
                // (ES2022). The LHS is a private identifier, not a
                // value with an assignable type, so suppress the
                // `string | number | symbol` operand-kind check on
                // the LHS. The RHS is still validated normally.
                // Fixtures: `privateNameInInExpression*`.
                const lhs_is_private_id = self.binaryLhsIsPrivateIdentifier(b.lhs);
                if (lhs_is_private_id) {
                    if (try self.privateIdentifierResolvesInEnclosingClass(b.lhs)) |resolved| {
                        if (!resolved and
                            (!self.virtualSectionIsJsLike(b.lhs) or
                                self.check_js_enabled or
                                self.sourceHasCheckJsDirective()))
                        {
                            const name = hir_mod.identifierOf(self.hir, b.lhs).name;
                            try self.reportPropertyDoesNotExistOnType(b.lhs, name, rhs);
                        }
                    }
                }
                if (lhs_nullish == null and !lhs_is_private_id) {
                    var checked_lhs = lhs;
                    var lhs_precheck_failed = false;
                    if (self.strict_flags.strict_null_checks and lhs == types.Primitive.unknown) {
                        try self.reportUnknownObjectOperand(b.lhs);
                        lhs_precheck_failed = true;
                    } else if (self.strict_flags.strict_null_checks and self.typeIsPossiblyNullishStrict(lhs)) {
                        try self.reportPossiblyNullishMember(b.lhs, lhs);
                        checked_lhs = try self.subtractNullUndefined(lhs);
                        lhs_precheck_failed = checked_lhs == types.Primitive.never;
                    }
                    if (!lhs_precheck_failed and !self.isInLeftOperandAllowed(checked_lhs)) {
                        try self.reportInOperandLeft(b.lhs, checked_lhs);
                    }
                }
                if (rhs_nullish == null) {
                    var checked_rhs = rhs;
                    var rhs_precheck_failed = false;
                    if (self.strict_flags.strict_null_checks and rhs == types.Primitive.unknown) {
                        try self.reportUnknownObjectOperand(b.rhs);
                        rhs_precheck_failed = true;
                    } else if (self.strict_flags.strict_null_checks and self.typeIsPossiblyNullishStrict(rhs)) {
                        try self.reportPossiblyNullishMember(b.rhs, rhs);
                        checked_rhs = try self.subtractNullUndefined(rhs);
                        rhs_precheck_failed = checked_rhs == types.Primitive.never;
                    }
                    if (!rhs_precheck_failed) {
                        if (!self.isInRightOperandAllowed(checked_rhs)) {
                            try self.reportInOperandRight(b.rhs, checked_rhs);
                        } else if (self.typeHasUnknownEmptyObject(checked_rhs)) {
                            try self.reportInRightMayRepresentPrimitive(b.rhs, checked_rhs);
                        }
                    }
                }
                break :blk types.Primitive.boolean_t;
            },
            .comma => blk: {
                // tsgo gates TS2695 on `isInDiag2657`: when the comma is
                // the parser's synthetic recovery node for adjacent JSX
                // elements (TS2657), the left operand is user-visible JSX,
                // not an unused comma operand, so no diagnostic fires.
                if (!self.sourceHasAllowUnreachableTrueDirective() and
                    !self.jsxCommaRecoveryContains(self.hir.spanOf(b.lhs).start) and
                    !self.expressionHasObservableSideEffect(b.lhs))
                {
                    try self.reportOnce(b.lhs, TsCodes.comma_left_unused, "Left side of comma operator is unused and has no side effects.");
                }
                if (self.hir.kindOf(b.rhs) == .arrow_fn or self.hir.kindOf(b.rhs) == .fn_expr) {
                    if (self.contextualTargetTypeForExpression(node)) |target_t| {
                        if (self.firstSignatureType(target_t)) |target_sig| {
                            try self.checkFunctionWithContextualSignature(b.rhs, target_sig);
                            break :blk try self.contextualFunctionSignatureWithInferredReturn(b.rhs, target_sig);
                        }
                    }
                }
                break :blk rhs;
            },
            // Logical-assignment ops (`||=`/`&&=`/`??=`) are assignment
            // operators, never a binary_op; included for exhaustiveness.
            .logical_or, .logical_and, .nullish_coalesce => rhs,
        };
    }

    fn checkUnary(self: *Checker, node: NodeId) CheckError!TypeId {
        const u = hir_mod.unaryOf(self.hir, node);
        const delete_operand_is_this = u.op == .delete and self.hir.kindOf(u.operand) == .identifier and
            std.mem.eql(u8, self.string_interner.get(hir_mod.identifierOf(self.hir, u.operand).name), "this");
        const operand_t = if (delete_operand_is_this)
            types.Primitive.any
        else
            try self.checkExpression(u.operand);
        return switch (u.op) {
            .neg, .plus, .bit_not => blk: {
                if (operand_t == types.Primitive.unknown) {
                    if (self.shouldReportUnknownOperand(u.operand)) {
                        try self.reportUnknownObjectOperand(u.operand);
                    }
                    break :blk types.Primitive.number_t;
                }
                if (self.typeContainsSymbol(operand_t)) {
                    // tsc anchors TS2469 at the operand (including any
                    // wrapping parens), not at the leading operator.
                    // Mirrors fixtures `symbolType3.ts(7,3)` /
                    // `(12,2)` for `+ Symbol()` and `+(Symbol() || 0)`.
                    const pos = self.symbolOperandAnchorPos(u.operand);
                    try self.reportSymbolOperatorAt(u.operand, pos, switch (u.op) {
                        .neg => "-",
                        .plus => "+",
                        .bit_not => "~",
                        else => unreachable,
                    });
                }
                // tsc fires TS18050 ("The value 'null' / 'undefined'
                // cannot be used here.") when the operand of `-`, `+`
                // or `~` is a literal `null` or `undefined`. Mirrors
                // fixtures `negateOperatorWithAnyOtherType.ts(34,ÃÂ¢ÃÂÃÂ¦)`,
                // `bitwiseNotOperatorWithAnyOtherType.ts(34,ÃÂ¢ÃÂÃÂ¦)`, and
                // friends ÃÂ¢ÃÂÃÂ the diagnostic is anchored at the operand
                // start, not the operator. Emits regardless of
                // `strictNullChecks` since tsc's grammar-level check
                // doesn't gate on it.
                if (self.typeIsExactNullish(operand_t)) {
                    try self.reportNullishRelationalOperand(u.operand, operand_t);
                }
                if (u.op == .plus and self.typeMaybeBigintLike(operand_t)) {
                    const display_t = try self.widenFreshLiteralType(operand_t);
                    const type_name = (try self.simpleDiagnosticTypeName(display_t)) orelse "bigint";
                    const msg = try std.fmt.allocPrint(
                        self.diag_arena.allocator(),
                        "Operator '+' cannot be applied to type '{s}'.",
                        .{type_name},
                    );
                    try self.report(u.operand, TsCodes.unary_plus_bigint_operand, msg);
                }
                // `-<numeric literal>` keeps its literal type (`-1`,
                // not `number`) — tsc renders the negative literal in
                // diagnostics and matches it against enum member
                // values. Mirrors `validEnumAssignments.ts(26,1)`.
                if (u.op == .neg) {
                    if (self.numberLiteralValueFromType(operand_t)) |v| {
                        break :blk self.interner.internNumberLiteral(-v) catch types.Primitive.number_t;
                    }
                }
                break :blk types.Primitive.number_t;
            },
            .not => blk: {
                // `!{ ÃÂ¢ÃÂÃÂ¦ }` / `![ ÃÂ¢ÃÂÃÂ¦ ]` / `!fn` / `!/re/` always evaluate to
                // `false` because the operand is a truthy literal.
                // tsc fires TS2872 ("This kind of expression is
                // always truthy.") at the operand. Restrict to the
                // operand kinds tsc actually flags (object literal,
                // array literal, function-shaped, regex literal) ÃÂ¢ÃÂÃÂ `!"x"` / `!0`
                // are intentionally not flagged.
                switch (self.hir.kindOf(u.operand)) {
                    .object_literal, .array_literal, .fn_decl, .fn_expr, .arrow_fn, .literal_regex => {
                        try self.report(u.operand, TsCodes.expression_always_truthy, "This kind of expression is always truthy.");
                    },
                    .literal_string => {
                        // tsc fires TS2873 ("This kind of expression
                        // is always falsy.") for `!""` ÃÂ¢ÃÂÃÂ the empty
                        // string is the only falsy string literal.
                        const s = hir_mod.literalStringOf(self.hir, u.operand);
                        if (self.string_interner.get(s.value).len == 0) {
                            try self.report(u.operand, TsCodes.expression_always_falsy, "This kind of expression is always falsy.");
                        }
                    },
                    // `!null` / `!undefined` ÃÂ¢ÃÂÃÂ both operands are the
                    // canonical falsy literals. tsc emits TS2873 at
                    // the operand. Mirrors fixture
                    // `logicalNotOperatorWithAnyOtherType` rows
                    // `var ResultIsBoolean7 = !undefined` and
                    // `var ResultIsBoolean8 = !null` and the LHS-of-`&&`
                    // path already handled at the logical-op site.
                    .literal_null, .literal_undefined => {
                        try self.report(u.operand, TsCodes.expression_always_falsy, "This kind of expression is always falsy.");
                    },
                    else => {},
                }
                break :blk types.Primitive.boolean_t;
            },
            .typeof => types.Primitive.string_t,
            .void_ => types.Primitive.undefined_t,
            .delete => blk: {
                const operand_kind = self.hir.kindOf(u.operand);
                const private_delete_operand = self.deleteOperandContainsPrivateIdentifier(u.operand);
                if (operand_kind == .identifier) {
                    // TS1102 is a grammar restriction that only applies
                    // in strict mode. The file is in strict mode when
                    // `alwaysStrict` is set, when the source is an
                    // external module (carries `import` / `export`
                    // declarations), or when the `delete` sits inside
                    // a class body. `this` is parsed as an identifier
                    // in our HIR but is a reserved keyword, not a
                    // variable binding; upstream restricts TS1102 to
                    // real identifiers and only emits TS2703 for
                    // `delete this`. Mirrors `parserStrictMode16.ts`
                    // and `deleteOperatorWithAnyOtherType` baselines.
                    const ident_name = hir_mod.identifierOf(self.hir, u.operand).name;
                    const is_this_keyword = std.mem.eql(u8, self.string_interner.get(ident_name), "this");
                    if (!is_this_keyword and self.strictModeAppliesAt(u.operand)) {
                        try self.report(u.operand, TsCodes.delete_identifier_strict_mode, "'delete' cannot be called on an identifier in strict mode.");
                    }
                }
                if (operand_kind != .member_access and operand_kind != .element_access) {
                    try self.report(u.operand, TsCodes.delete_operand_property_reference, "The operand of a 'delete' operator must be a property reference.");
                } else if (self.deleteOperandIsReadOnly(u.operand)) {
                    // TS2704 wins over TS2790: read-only beats
                    // optionality. Independent of strict_null_checks,
                    // since tsc emits TS2704 even without `strict`.
                    // Mirrors `symbolType3.ts(2,8)` `delete Symbol.iterator`.
                    try self.report(u.operand, TsCodes.delete_operand_read_only, "The operand of a 'delete' operator cannot be a read-only property.");
                } else if (self.deleteOperandHasReadonlyIndexSignature(u.operand)) {
                    try self.checkReadonlyIndexAssignment(u.operand);
                } else if (self.strict_flags.strict_null_checks and
                    (private_delete_operand or !(try self.deleteOperandAllowed(u.operand))))
                {
                    try self.reportAt(u.operand, self.deleteOperandOptionalityAnchorPos(u.operand), TsCodes.delete_operand_must_be_optional, "The operand of a 'delete' operator must be optional.");
                }
                if (private_delete_operand) {
                    try self.report(u.operand, TsCodes.delete_operand_private_identifier, "The operand of a 'delete' operator cannot be a private identifier.");
                }
                break :blk types.Primitive.boolean_t;
            },
        };
    }

    fn checkLogical(self: *Checker, node: NodeId) CheckError!TypeId {
        const l = hir_mod.logicalOf(self.hir, node);
        const lhs = try self.checkExpression(l.lhs);
        const rhs = switch (l.op) {
            .@"and" => blk: {
                try self.pushNarrowScope();
                try self.applyTypeGuard(l.lhs, true);
                try self.reportAliasAssignmentAndToStringImpossible(l.lhs, l.rhs);
                if (self.hir.kindOf(l.rhs) == .arrow_fn or self.hir.kindOf(l.rhs) == .fn_expr) {
                    if (self.contextualTargetTypeForExpression(node)) |target_t| {
                        if (self.firstSignatureType(target_t)) |target_sig| {
                            try self.checkFunctionWithContextualSignature(l.rhs, target_sig);
                            const t = try self.contextualFunctionSignatureWithInferredReturn(l.rhs, target_sig);
                            self.hir.setType(l.rhs, t);
                            self.popNarrowScope();
                            break :blk t;
                        }
                    }
                }
                const t = try self.checkExpression(l.rhs);
                self.popNarrowScope();
                break :blk t;
            },
            .@"or" => blk: {
                try self.pushNarrowScope();
                try self.applyTypeGuard(l.lhs, false);
                const t = try self.checkExpression(l.rhs);
                self.popNarrowScope();
                break :blk t;
            },
            .nullish => try self.checkExpression(l.rhs),
        };
        // `a ?? b` ÃÂ¢ÃÂÃÂ when `a` is non-null/undefined the result is
        // `a`'s type minus null/undefined; otherwise it's `b`'s
        // type. The runtime forks on nullish, so the result type
        // is `(a minus null|undefined) | b`. The `&&`/`||` path below
        // similarly preserves only the LHS values that can actually
        // short-circuit before unioning with the reachable RHS.
        if (l.op == .nullish) {
            // TS2871: the left operand of `??` is syntactically always
            // nullish (`null` / `undefined`, a conditional with both
            // branches nullish, or a `??`/`??=`/`,`/`=` form whose
            // controlling operand is). Mirrors tsgo's
            // `checkNullishCoalesceOperandLeft` Always branch. Disjoint
            // from the TS2869 "never nullish" set below (literals /
            // object / array / functions), so at most one fires.
            if (self.expressionAlwaysNullishForNullishDiag(l.lhs)) {
                try self.report(l.lhs, TsCodes.always_nullish, "This expression is always nullish.");
            } else if (self.expressionNeverNullishForNullishDiag(l.lhs, lhs)) {
                try self.report(l.lhs, TsCodes.nullish_rhs_unreachable, "Right operand of ?? is unreachable because the left operand is never nullish.");
            }
            const lhs_non_null = self.subtractNullUndefined(lhs) catch lhs;
            return self.interner.internUnion(&.{ lhs_non_null, rhs }) catch error.OutOfMemory;
        }
        try self.reportVoidTruthiness(l.lhs, lhs);
        if (l.op == .@"or" and self.hir.kindOf(l.lhs) == .object_literal) {
            // tsc anchors at the opening `(` for parenthesized LHS
            // forms like `({}) || s`. Mirrors fixture
            // `symbolType11.ts(7,1)`.
            const lhs_pos = self.symbolOperandAnchorPos(l.lhs);
            try self.reportAt(l.lhs, lhs_pos, TsCodes.expression_always_truthy, "This kind of expression is always truthy.");
        }
        // parserArrowFunctionExpression3: `(() => { }) || a` ÃÂ¢ÃÂÃÂ tsc
        // fires TS2872 on the arrow LHS of `||` (heap-allocated
        // function object, always truthy). Mirror the `&&` branch
        // below and anchor at the opening `(` for the parenthesized
        // form. `object_literal` is handled above with its own
        // anchor so we exclude it here.
        if (l.op == .@"or" and
            self.hir.kindOf(l.lhs) != .object_literal and
            self.expressionAlwaysTruthyInLogicalAnd(l.lhs, lhs))
        {
            if (self.hir.kindOf(l.lhs) == .literal_string) {
                try self.report(l.lhs, TsCodes.expression_always_truthy, "This kind of expression is always truthy.");
            } else {
                const lhs_pos = self.symbolOperandAnchorPos(l.lhs);
                try self.reportAt(l.lhs, lhs_pos, TsCodes.expression_always_truthy, "This kind of expression is always truthy.");
            }
        }
        if (l.op == .@"and" and self.expressionAlwaysTruthyInLogicalAnd(l.lhs, lhs)) {
            if (self.hir.kindOf(l.lhs) == .literal_string) {
                try self.report(l.lhs, TsCodes.expression_always_truthy, "This kind of expression is always truthy.");
            } else {
                try self.reportAt(l.lhs, self.symbolOperandAnchorPos(l.lhs), TsCodes.expression_always_truthy, "This kind of expression is always truthy.");
            }
            try self.reportLogicalTruthyFunctionImplicitAnyParams(l.lhs);
        }
        if (l.op == .@"or" and self.expressionAlwaysFalsyInLogicalOr(l.lhs, lhs)) {
            try self.report(l.lhs, TsCodes.expression_always_falsy, "This kind of expression is always falsy.");
        }
        // tsc also fires TS2873 on the LHS of `&&` when it is a
        // literal `null` / `undefined` / empty string (the always-falsy
        // gate short-circuits the right operand). Mirrors fixtures like
        // `logicalAndOperatorWithEveryType.ts` rows 23-24 and witness.ts.
        if (l.op == .@"and") {
            switch (self.hir.kindOf(l.lhs)) {
                .literal_null, .literal_undefined => {
                    try self.report(l.lhs, TsCodes.expression_always_falsy, "This kind of expression is always falsy.");
                },
                .literal_string => {
                    const lit = hir_mod.literalStringOf(self.hir, l.lhs);
                    if (self.string_interner.get(lit.value).len == 0) {
                        try self.report(l.lhs, TsCodes.expression_always_falsy, "This kind of expression is always falsy.");
                    }
                },
                else => {},
            }
        }
        if (l.op == .@"or" and self.hir.kindOf(l.lhs) == .literal_string) {
            const lit = hir_mod.literalStringOf(self.hir, l.lhs);
            if (self.string_interner.get(lit.value).len == 0) {
                try self.report(l.lhs, TsCodes.expression_always_falsy, "This kind of expression is always falsy.");
            }
        }
        const literal_lhs = try self.expressionLiteralType(l.lhs, lhs);
        const lhs_result = if (l.op == .@"or")
            try self.logicalOrTruthyType(literal_lhs)
        else
            try self.logicalAndFalsyType(literal_lhs);
        const rhs_result = try self.expressionLiteralType(l.rhs, rhs);
        if (l.op == .@"and" and !self.logicalTypeCanBeTruthy(literal_lhs)) return lhs_result;
        if (l.op == .@"or" and !self.logicalTypeCanBeFalsy(literal_lhs)) return lhs_result;
        if (lhs_result == types.Primitive.never) return rhs_result;
        if (rhs_result == types.Primitive.never) return lhs_result;
        return self.interner.internUnion(&.{ lhs_result, rhs_result }) catch error.OutOfMemory;
    }

    fn reportVoidTruthiness(self: *Checker, node: NodeId, t: TypeId) CheckError!void {
        if (t != types.Primitive.void_t) return;
        try self.report(node, TsCodes.void_truthiness, "An expression of type 'void' cannot be tested for truthiness.");
    }

    fn reportAliasAssignmentAndToStringImpossible(self: *Checker, lhs: NodeId, rhs: NodeId) CheckError!void {
        if (!self.nodeHasLogicalAncestor(lhs, .@"or")) return;
        if (self.hir.kindOf(lhs) != .assignment) return;
        const member_node = switch (self.hir.kindOf(rhs)) {
            .member_access => rhs,
            .call_expr => blk: {
                const c = hir_mod.callOf(self.hir, rhs);
                if (self.hir.kindOf(c.callee) != .member_access) return;
                break :blk c.callee;
            },
            else => return,
        };
        const a = hir_mod.assignmentOf(self.hir, lhs);
        if (a.op != null or self.hir.kindOf(a.target) != .identifier or self.hir.kindOf(a.value) != .identifier) return;
        const m = hir_mod.memberOf(self.hir, member_node);
        if (self.hir.kindOf(m.object) != .identifier) return;
        if (!std.mem.eql(u8, self.string_interner.get(m.name), "toString")) return;
        const value_id = hir_mod.identifierOf(self.hir, a.value);
        const object_id = hir_mod.identifierOf(self.hir, m.object);
        if (value_id.name != object_id.name) return;
        try self.reportPropertyDoesNotExistOnType(member_node, m.name, types.Primitive.never);
    }

    fn nodeHasLogicalAncestor(self: *Checker, node: NodeId, op: hir_mod.LogicalOp) bool {
        var cur = self.hir.parentOf(node);
        while (cur != hir_mod.none_node_id) : (cur = self.hir.parentOf(cur)) {
            if (self.hir.kindOf(cur) != .logical_op) continue;
            if (hir_mod.logicalOf(self.hir, cur).op == op) return true;
        }
        return false;
    }

    fn expressionAlwaysTruthyInLogicalAnd(self: *Checker, node: NodeId, t: TypeId) bool {
        _ = t;
        return switch (self.hir.kindOf(node)) {
            .literal_number => hir_mod.literalNumberOf(self.hir, node) != 0,
            .literal_string => self.string_interner.get(hir_mod.literalStringOf(self.hir, node).value).len != 0,
            // Function expressions / arrow functions / function declarations /
            // regex literals are heap-allocated objects ÃÂ¢ÃÂÃÂ always truthy.
            // Mirrors tsc's TS2872 emit at e.g. `contextuallyTypeLogicalAnd03.ts`.
            .object_literal, .array_literal, .fn_expr, .arrow_fn, .fn_decl, .literal_regex => true,
            else => false,
        };
    }

    fn expressionAlwaysFalsyInLogicalOr(self: *Checker, node: NodeId, t: TypeId) bool {
        _ = t;
        return switch (self.hir.kindOf(node)) {
            .literal_null, .literal_undefined => true,
            .as_expr, .type_assertion => blk: {
                const a = hir_mod.asExpressionOf(self.hir, node);
                break :blk self.expressionAlwaysFalsyInLogicalOr(a.expr, types.Primitive.none);
            },
            .unary_op => blk: {
                const u = hir_mod.unaryOf(self.hir, node);
                break :blk u.op == .void_;
            },
            else => false,
        };
    }

    /// Strict-arity subtype test between two bare call signatures, used
    /// only for the conditional-union subtype reduction below. Mirrors
    /// tsc's `compareSignaturesRelated` under
    /// `SignatureCheckModeStrictArity` (the mode `removeSubtypes` runs in
    /// via `strictSubtypeRelation`):
    ///   * a source signature with MORE parameters than the target is
    ///     never a subtype (no effective rest params here);
    ///   * parameters relate contravariantly (target param assignable to
    ///     source param);
    ///   * an OPTIONAL source parameter that is REQUIRED in the target
    ///     (and whose types relate covariantly) breaks the subtype ÃÂ¢ÃÂÃÂ this
    ///     is what keeps `(x: T) => void` from being a subtype of
    ///     `(x?: T) => void`, so the optional branch wins union reduction;
    ///   * the source return type must relate to the target's (a `void`
    ///     target return accepts anything).
    /// Restricted to bare signatures; returns false for anything else so
    /// the caller leaves the union untouched.
    fn strictCallableSubtype(self: *Checker, source: TypeId, target: TypeId) bool {
        if (source == target) return true;
        if (!self.interner.isSignature(source) or !self.interner.isSignature(target)) return false;
        // Rest signatures have variable arity; their subtype rules differ
        // from the fixed-arity case modeled here. Bail to stay faithful.
        if (self.rest_signatures.contains(source) or self.rest_signatures.contains(target)) return false;
        if (self.signatureIsAnyFunctionSubtypeSource(source, target)) return true;
        const sp = self.interner.signatureParams(source);
        const tp = self.interner.signatureParams(target);
        // Source must not provide more parameters than the target accepts.
        if (sp.len > tp.len) return false;
        const source_min = self.signatureMinRequiredArgs(source, sp);
        const target_min = self.signatureMinRequiredArgs(target, tp);
        const param_count = @max(sp.len, tp.len);
        var i: usize = 0;
        while (i < param_count) : (i += 1) {
            const s_has = i < sp.len;
            const t_has = i < tp.len;
            // A position present only in the (longer) source can't exist
            // here because `sp.len <= tp.len`; a position present only in
            // the target is fine ÃÂ¢ÃÂÃÂ source simply omits an optional arg.
            if (!s_has) continue;
            if (!t_has) return false;
            const s_param = sp[i];
            const t_param = tp[i];
            // Contravariant: the target's parameter must be assignable to
            // the source's parameter.
            if (!(self.engine.isSubtypeOf(t_param, s_param) catch false)) return false;
            // Optional-in-source / required-in-target rejection (tsc:
            // "(x: T) => void is NOT a subtype of (x?: T) => void").
            if (i >= source_min and i < target_min and
                (self.engine.isSubtypeOf(s_param, t_param) catch false))
            {
                return false;
            }
        }
        // Return-type relation: a void/any target return accepts anything.
        const t_ret = self.interner.signatureReturn(target) orelse types.Primitive.any;
        if (t_ret == types.Primitive.void_t or t_ret == types.Primitive.any) return true;
        const s_ret = self.interner.signatureReturn(source) orelse types.Primitive.any;
        return self.engine.isSubtypeOf(s_ret, t_ret) catch false;
    }

    fn signatureIsAnyFunctionSubtypeSource(self: *Checker, source: TypeId, target: TypeId) bool {
        _ = target;
        const sp = self.interner.signatureParams(source);
        if (sp.len == 0) return false;
        for (sp) |param_t| {
            if (param_t != types.Primitive.any) return false;
        }
        const s_ret = self.interner.signatureReturn(source) orelse types.Primitive.any;
        return s_ret == types.Primitive.any;
    }

    fn strictUnionReductionSubtype(self: *Checker, source: TypeId, target: TypeId) bool {
        if (self.strictCallableSubtype(source, target)) return true;
        return self.strictObjectSubtypeForUnionReduction(source, target);
    }

    fn strictObjectSubtypeForUnionReduction(self: *Checker, source: TypeId, target: TypeId) bool {
        if (source == target) return true;
        if (source >= self.interner.pool.typeCount() or target >= self.interner.pool.typeCount()) return false;
        const sf = self.interner.pool.flagsOf(source);
        const tf = self.interner.pool.flagsOf(target);
        if (!sf.is_object_type or !tf.is_object_type) return false;
        if (self.interner.objectStringIndex(source) != types.Primitive.none or
            self.interner.objectNumberIndex(source) != types.Primitive.none or
            self.interner.objectSymbolIndex(source) != types.Primitive.none or
            self.interner.objectStringIndex(target) != types.Primitive.none or
            self.interner.objectNumberIndex(target) != types.Primitive.none or
            self.interner.objectSymbolIndex(target) != types.Primitive.none)
            return false;

        var saw_callable_member = false;
        for (self.interner.objectMembers(target)) |tm| {
            const sm = self.interner.objectMemberInfo(source, tm.name) orelse {
                if (tm.is_optional) continue;
                return false;
            };
            if (!tm.is_optional and sm.is_optional) return false;
            if (self.interner.isSignature(sm.type) and self.interner.isSignature(tm.type)) {
                saw_callable_member = true;
                if (!self.strictCallableSubtype(sm.type, tm.type)) return false;
                continue;
            }
            if (!(self.engine.isSubtypeOf(sm.type, tm.type) catch false)) return false;
        }
        return saw_callable_member;
    }

    fn internArrayElementUnion(self: *Checker, members: []const TypeId) CheckError!TypeId {
        const u = self.interner.internUnion(members) catch return error.OutOfMemory;
        if (u >= self.interner.pool.typeCount()) return u;
        if (!self.interner.pool.flagsOf(u).is_union) return u;
        const union_members = self.interner.unionMembers(u);
        if (union_members.len < 2) return u;

        var kept = std.ArrayListUnmanaged(TypeId).empty;
        defer kept.deinit(self.gpa);
        try kept.appendSlice(self.gpa, union_members);

        var i: usize = kept.items.len;
        while (i > 0) {
            i -= 1;
            const source = kept.items[i];
            for (kept.items, 0..) |target, j| {
                if (j == i) continue;
                if (self.strictUnionReductionSubtype(source, target)) {
                    _ = kept.orderedRemove(i);
                    break;
                }
            }
        }

        if (kept.items.len == union_members.len) return u;
        return self.interner.internUnion(kept.items) catch error.OutOfMemory;
    }

    /// Subtype-reduce a union of *callable* branches, mirroring tsc's
    /// `removeSubtypes` (UnionReductionSubtype) used when forming the
    /// type of a conditional `cond ? then : else`. When one callable
    /// branch is a strict subtype of another, tsc drops the subtype and
    /// keeps the supertype, collapsing e.g.
    ///   `((x: string | undefined) => void) | ((x?: string) => void)`
    /// down to the single signature `(x?: string) => void` ÃÂ¢ÃÂÃÂ whose
    /// optional parameter then lets `f()` type-check. Critically, when
    /// neither branch subsumes the other (e.g. f6 in
    /// `unionTypeReduction2.ts`, where the kept signature has a REQUIRED
    /// `'hello' | undefined` parameter) the union is left intact, so the
    /// downstream call-arity check still fires TS2554 for `f()`.
    ///
    /// Scoped to unions whose every constituent is a bare call signature:
    /// general union construction is left untouched to avoid perturbing
    /// unrelated reduction behavior. Returns the (possibly reduced)
    /// interned type for `members`.
    fn internConditionalUnion(self: *Checker, members: []const TypeId) CheckError!TypeId {
        // `any` absorbs the other branch of a conditional expression in
        // TypeScript. Keeping `any | T` here makes downstream calls reject
        // values that tsc treats as plain `any`.
        for (members) |member| {
            if (member == types.Primitive.any) return types.Primitive.any;
        }
        const u = try self.internUnionReducingStringSubtypes(members);
        if (u >= self.interner.pool.typeCount()) return u;
        if (!self.interner.pool.flagsOf(u).is_union) return u;
        // Only reduce when every constituent is a bare call signature ÃÂ¢ÃÂÃÂ
        // the union-of-function-types shape tsc subtype-reduces here.
        const union_members = self.interner.unionMembers(u);
        if (union_members.len < 2) return u;
        for (union_members) |m| {
            if (!self.interner.isSignature(m)) return u;
            if (self.signatureIsConstruct(m)) return u;
        }
        var kept = std.ArrayListUnmanaged(TypeId).empty;
        defer kept.deinit(self.gpa);
        try kept.appendSlice(self.gpa, union_members);
        // Walk from the end and drop any `source` that is a strict-arity
        // subtype of some other surviving `target` (tsc removeSubtypes).
        var i: usize = kept.items.len;
        while (i > 0) {
            i -= 1;
            const source = kept.items[i];
            for (kept.items, 0..) |target, j| {
                if (j == i) continue;
                if (self.strictCallableSubtype(source, target)) {
                    _ = kept.orderedRemove(i);
                    break;
                }
            }
        }
        if (kept.items.len == union_members.len) return u;
        return self.interner.internUnion(kept.items) catch error.OutOfMemory;
    }

    fn internUnionReducingStringSubtypes(self: *Checker, members: []const TypeId) CheckError!TypeId {
        var flat: std.ArrayListUnmanaged(TypeId) = .empty;
        defer flat.deinit(self.gpa);
        var has_string = false;
        try self.collectUnionMembersForStringReduction(members, &flat, &has_string);
        if (flat.items.len == 0) return types.Primitive.never;
        if (!has_string) return self.interner.internUnion(flat.items) catch return error.OutOfMemory;

        var reduced: std.ArrayListUnmanaged(TypeId) = .empty;
        defer reduced.deinit(self.gpa);
        try reduced.append(self.gpa, types.Primitive.string_t);
        for (flat.items) |member| {
            if (member == types.Primitive.string_t) continue;
            if (self.typeIsStringSubtypeForUnionReduction(member)) continue;
            try reduced.append(self.gpa, member);
        }
        if (reduced.items.len == 1) return types.Primitive.string_t;
        return self.interner.internUnion(reduced.items) catch return error.OutOfMemory;
    }

    fn collectUnionMembersForStringReduction(
        self: *Checker,
        members: []const TypeId,
        out: *std.ArrayListUnmanaged(TypeId),
        has_string: *bool,
    ) CheckError!void {
        for (members) |member| {
            if (self.typeIsBroadStringForUnionReduction(member)) {
                has_string.* = true;
                try self.appendUniqueTypeId(out, types.Primitive.string_t);
                continue;
            }
            if (member < self.interner.pool.typeCount() and self.interner.pool.flagsOf(member).is_union) {
                try self.collectUnionMembersForStringReduction(self.interner.unionMembers(member), out, has_string);
                continue;
            }
            try self.appendUniqueTypeId(out, member);
        }
    }

    fn typeIsBroadStringForUnionReduction(self: *Checker, t: TypeId) bool {
        if (t == types.Primitive.string_t) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        return flags.is_string and !flags.is_object_type and !flags.is_literal and
            !flags.is_template_literal and !flags.is_string_mapping and
            !flags.is_union and !flags.is_intersection;
    }

    fn typeIsStringSubtypeForUnionReduction(self: *Checker, t: TypeId) bool {
        if (self.typeIsBroadStringForUnionReduction(t)) return true;
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.typeIsStringSubtypeForUnionReduction(member)) return false;
            }
            return true;
        }
        if (flags.is_literal and flags.is_string) return true;
        if (flags.is_template_literal and !flags.is_intersection) return true;
        if (flags.is_string_mapping and !flags.is_intersection) return true;
        return false;
    }

    fn typeIsTemplateUnionDisplayMember(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union or flags.is_intersection) return false;
        return flags.is_template_literal or flags.is_string_mapping;
    }

    fn internUnionDroppingLiteralsCoveredByTemplates(self: *Checker, members: []const TypeId) CheckError!TypeId {
        var kept: std.ArrayListUnmanaged(TypeId) = .empty;
        defer kept.deinit(self.gpa);
        for (members) |member| {
            if (self.stringLiteralValueFromType(member)) |sid| {
                var covered = false;
                for (members) |other| {
                    if (other == member) continue;
                    if (!self.typeCanCoverStringLiteralInUnion(other)) continue;
                    if (try self.stringLiteralAssignableToType(sid, other)) {
                        covered = true;
                        break;
                    }
                }
                if (covered) continue;
            }
            try kept.append(self.gpa, member);
        }
        if (kept.items.len == 0) return types.Primitive.never;
        if (kept.items.len == 1) return kept.items[0];
        return self.interner.internUnion(kept.items) catch return error.OutOfMemory;
    }

    fn intersectionStringLiteralTemplateReduction(self: *Checker, members: []const TypeId) CheckError!?TypeId {
        var literal_t: TypeId = types.Primitive.none;
        var literal_sid: ?hir_mod.StringId = null;
        for (members) |member| {
            if (self.stringLiteralValueFromType(member)) |sid| {
                if (literal_sid != null) return null;
                literal_t = member;
                literal_sid = sid;
            }
        }
        const sid = literal_sid orelse return null;
        var saw_covering_template = false;
        for (members) |member| {
            if (member == literal_t) continue;
            if (!self.typeCanCoverStringLiteralInUnion(member)) continue;
            if (!try self.stringLiteralAssignableToType(sid, member)) return null;
            saw_covering_template = true;
        }
        return if (saw_covering_template) literal_t else null;
    }

    fn typeCanCoverStringLiteralInUnion(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_template_literal or flags.is_string_mapping) return true;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeCanCoverStringLiteralInUnion(member)) return true;
            }
        }
        return false;
    }

    fn checkConditional(self: *Checker, node: NodeId) CheckError!TypeId {
        const c = hir_mod.conditionalOf(self.hir, node);
        const cond_t = try self.checkExpression(c.cond);
        try self.reportKnownTruthyCallableCondition(c.cond, cond_t, c.then_branch);
        try self.reportStaticTruthiness(c.cond);
        // TS narrows through `cond ? then : else`: the test expression's
        // truthy guard applies inside `then`, the falsy guard inside
        // `else`. Mirror the if-statement scoping so e.g.
        // `x ? x.length : -1` types `x` as the truthy half in the
        // then-branch.
        try self.pushNarrowScope();
        try self.applyTypeGuard(c.cond, true);
        const tt = try self.checkExpression(c.then_branch);
        self.popNarrowScope();
        try self.pushNarrowScope();
        try self.applyTypeGuard(c.cond, false);
        const ff = try self.checkExpression(c.else_branch);
        self.popNarrowScope();
        if (self.contextualLiteralUnionReturnTarget(node) != null) {
            const contextual_tt = try self.valueNodeLiteralType(c.then_branch, tt);
            const contextual_ff = try self.valueNodeLiteralType(c.else_branch, ff);
            return self.internConditionalUnion(&.{ contextual_tt, contextual_ff });
        }
        return self.internConditionalUnion(&.{ tt, ff });
    }

    fn contextualLiteralUnionReturnTarget(self: *Checker, node: NodeId) ?TypeId {
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id) return null;
        const kind = self.hir.kindOf(parent);
        if (kind != .fn_decl and kind != .fn_expr and kind != .arrow_fn) return null;
        const f = hir_mod.fnDeclOf(self.hir, parent);
        if (f.body != node) return null;
        const target = self.contextualReturnTypeForFunctionKind(parent, f.flags.is_async) orelse return null;
        return if (self.declaredReturnNeedsLiteralAssignabilityCheck(target)) target else null;
    }

    fn reportKnownTruthyCallableCondition(
        self: *Checker,
        cond: NodeId,
        cond_t: TypeId,
        body: NodeId,
    ) CheckError!void {
        if (!self.strict_flags.strict_null_checks) return;
        if (cond == hir_mod.none_node_id or self.hir.kindOf(cond) != .identifier) return;
        const tested_name = hir_mod.identifierOf(self.hir, cond).name;
        var refs = std.AutoHashMapUnmanaged(hir_mod.StringId, void).empty;
        defer refs.deinit(self.gpa);
        try self.collectIdentifierRefs(body, &refs);
        if (refs.contains(tested_name)) return;
        if (self.unwrapPromise(cond_t) != cond_t) {
            const type_name = (try self.allocPromiseDisplayName(cond_t)) orelse
                (try self.allocSimpleTypeName(cond_t)) orelse
                "Promise";
            const msg = try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "This condition will always return true since this '{s}' is always defined.",
                .{type_name},
            );
            try self.report(cond, TsCodes.condition_type_always_defined, msg);
            return;
        }
        if (self.typeHasNonConstructCallSignature(cond_t)) {
            try self.report(cond, TsCodes.condition_function_always_defined, "This condition will always return true since this function is always defined. Did you mean to call it instead?");
        }
    }

    fn reportStaticTruthiness(self: *Checker, node: NodeId) CheckError!void {
        // tsc anchors at the opening `(` for parenthesized truthy
        // operands (e.g. `({}) ? a : b` reports column 1 on `(`, not
        // column 2 on `{`). Mirrors fixture
        // `conditionalOperatorConditionIsObjectType.ts(28,1)`.
        // EXCEPT: when the operand sits in the required `(cond)` slot
        // of an `if`/`while`/`do-while` statement (e.g. `else if (2)`),
        // those parens belong to the statement syntax and shouldn't be
        // back-walked ÃÂ¢ÃÂÃÂ tsc anchors at the literal column itself.
        // See constEnum4.ts(3,10).
        const anchor = if (self.nodeIsStatementCondOperand(node)) null else self.symbolOperandAnchorPos(node);
        switch (self.hir.kindOf(node)) {
            .as_expr, .type_assertion => {
                const a = hir_mod.asExpressionOf(self.hir, node);
                switch (self.hir.kindOf(a.expr)) {
                    .literal_null, .literal_undefined => try self.reportAt(node, anchor, TsCodes.expression_always_falsy, "This kind of expression is always falsy."),
                    else => {},
                }
            },
            .object_literal, .array_literal, .fn_decl, .fn_expr, .arrow_fn, .literal_regex => {
                try self.reportAt(node, anchor, TsCodes.expression_always_truthy, "This kind of expression is always truthy.");
            },
            .literal_string => {
                const lit = hir_mod.literalStringOf(self.hir, node);
                if (self.string_interner.get(lit.value).len == 0) {
                    try self.reportAt(node, anchor, TsCodes.expression_always_falsy, "This kind of expression is always falsy.");
                } else {
                    try self.reportAt(node, anchor, TsCodes.expression_always_truthy, "This kind of expression is always truthy.");
                }
            },
            .literal_number => {
                const value = hir_mod.literalNumberOf(self.hir, node);
                if (value == 0) {
                    try self.reportAt(node, anchor, TsCodes.expression_always_falsy, "This kind of expression is always falsy.");
                } else {
                    try self.reportAt(node, anchor, TsCodes.expression_always_truthy, "This kind of expression is always truthy.");
                }
            },
            // Literal `null` / `undefined` ÃÂ¢ÃÂÃÂ always falsy. tsc fires
            // TS2873 in any truthiness slot (conditional cond,
            // if-stmt, while-stmt). Fixture coverage includes
            // `conditionalOperatorConditoinIsAnyType.ts` rows 26-31.
            .literal_null, .literal_undefined => {
                try self.reportAt(node, anchor, TsCodes.expression_always_falsy, "This kind of expression is always falsy.");
            },
            else => {},
        }
    }

    fn reportRelationalOperatorCannotBeAppliedWithNames(
        self: *Checker,
        node: NodeId,
        op: []const u8,
        left_name: []const u8,
        right_name: []const u8,
    ) CheckError!void {
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Operator '{s}' cannot be applied to types '{s}' and '{s}'.",
            .{ op, left_name, right_name },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = node,
            .code = TsCodes.operator_cannot_be_applied,
            .message = msg,
        });
    }

    /// Variant of `reportStaticTruthiness` used for if/while/do-while
    /// statement conditions. Matches tsgo's pattern: numeric & boolean
    /// literals are excluded (tsc skips them in statement contexts ÃÂ¢ÃÂÃÂ
    /// see baselines/reference/ifDoWhileStatements.errors.txt where
    /// `if (true)` and `if (0.0)` are NOT flagged), but `null`,
    /// `undefined`, and the empty string ARE flagged as falsy.
    /// Constructor calls (`new Foo()`) are not flagged either.
    fn reportStaticTruthinessForStatementCond(self: *Checker, node: NodeId) CheckError!void {
        switch (self.hir.kindOf(node)) {
            .object_literal, .array_literal, .arrow_fn, .literal_regex => {
                try self.report(node, TsCodes.expression_always_truthy, "This kind of expression is always truthy.");
            },
            .literal_null, .literal_undefined => {
                try self.report(node, TsCodes.expression_always_falsy, "This kind of expression is always falsy.");
            },
            .literal_string => {
                const lit = hir_mod.literalStringOf(self.hir, node);
                if (self.string_interner.get(lit.value).len == 0) {
                    try self.report(node, TsCodes.expression_always_falsy, "This kind of expression is always falsy.");
                } else {
                    try self.report(node, TsCodes.expression_always_truthy, "This kind of expression is always truthy.");
                }
            },
            else => {},
        }
    }

    fn isElseIfStatement(self: *Checker, node: NodeId) bool {
        const parent = self.hir.parentOf(node);
        if (parent == hir_mod.none_node_id or self.hir.kindOf(parent) != .if_stmt) return false;
        return hir_mod.ifOf(self.hir, parent).else_branch == node;
    }

    /// Generic call-site instantiation. For each parameter slot
    /// whose type is a type-parameter id, record a substitution
    /// `param_ts[i] -> arg_ts[i]`. Then walk `ret_type` and
    /// substitute any type-parameter occurrences. Returns the
    /// substituted return type. Falls through to `ret_type`
    /// unchanged if the signature isn't generic or substitution
    /// can't determine a single type.
    fn instantiateReturn(
        self: *Checker,
        raw_param_ts: []const TypeId,
        raw_arg_ts: []const TypeId,
        ret_type: TypeId,
    ) !TypeId {
        const param_ts = try self.gpa.dupe(TypeId, raw_param_ts);
        defer self.gpa.free(param_ts);
        const arg_ts = try self.gpa.dupe(TypeId, raw_arg_ts);
        defer self.gpa.free(arg_ts);
        // Build a map: type-parameter-id -> inferred-type
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);

        const n = @min(param_ts.len, arg_ts.len);
        for (0..n) |i| {
            try self.inferFromPair(param_ts[i], arg_ts[i], &subs);
        }
        // Default-type fallback: walk every TypeId reachable from the
        // signature (params + return) and, for any type-parameter id
        // not already substituted, fall back to its declaration-site
        // default (`<T = string>`). Lets `f()` resolve `T` to `string`
        // when no value pins it. The walker reaches into unions /
        // intersections so optional `x?: T` (lowered to `T |
        // undefined`) still surfaces the underlying T.
        var visited_defaults: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
        defer visited_defaults.deinit(self.gpa);
        for (param_ts) |p| try self.collectFreeTypeParamDefaults(p, &subs, &visited_defaults);
        try self.collectFreeTypeParamDefaults(ret_type, &subs, &visited_defaults);
        if (ret_type < self.interner.pool.typeCount() and self.interner.pool.flagsOf(ret_type).is_type_parameter) {
            var visited_fallbacks: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
            defer visited_fallbacks.deinit(self.gpa);
            try self.collectFreeTypeParamFallbacks(ret_type, &subs, &visited_fallbacks);
        }
        if (subs.count() == 0) return ret_type;
        return self.substituteType(ret_type, &subs);
    }

    fn applyInferredConditionalConstraintsToSubs(
        self: *Checker,
        sig: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        const type_params = self.generic_signature_params.get(sig) orelse return;
        try self.applyInferredConditionalConstraintsForParams(type_params, subs);
    }

    fn applyInferredConditionalConstraintsFromCallArgs(
        self: *Checker,
        param_ts: []const TypeId,
        arg_ts: []const TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        const n = @min(param_ts.len, arg_ts.len);
        for (0..n) |i| {
            const param_t = param_ts[i];
            if (param_t >= self.interner.pool.typeCount()) continue;
            if (!self.interner.pool.flagsOf(param_t).is_type_parameter) continue;
            if (!subs.contains(param_t)) continue;
            const constraint = self.typeParameterConstraint(param_t) orelse continue;
            if (!self.conditionalConstraintChecksNullish(constraint)) continue;
            if (!self.typeIncludesNull(arg_ts[i])) {
                try subs.put(self.gpa, param_t, types.Primitive.never);
            }
        }
    }

    fn applyInferredConditionalConstraintsForParams(
        self: *Checker,
        type_params: []const TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        for (type_params) |tp| {
            if (!subs.contains(tp)) continue;
            const constraint = self.typeParameterConstraint(tp) orelse continue;
            if (constraint >= self.interner.pool.typeCount() or
                !self.interner.pool.flagsOf(constraint).is_conditional)
            {
                continue;
            }
            if (self.conditionalConstraintChecksNullish(constraint)) {
                continue;
            }
            if (self.containsTemplateLiteralType(constraint)) {
                continue;
            }
            const resolved = self.substituteType(constraint, subs) catch constraint;
            if (resolved == types.Primitive.never) {
                try subs.put(self.gpa, tp, types.Primitive.never);
            }
        }
    }

    /// Widen a literal type (`42`, `"hi"`, `true`) to its base
    /// primitive (`number`, `string`, `boolean`) when binding a fresh
    /// type-parameter from an argument. Matches tsc's call-site
    /// behavior: `id(42)` infers `T = number`, not `T = 42`. Anything
    /// non-literal is returned unchanged.
    fn widenForInference(self: *Checker, t: TypeId) TypeId {
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_literal) {
            // Generic inference preserves enum-member literals
            // (`NonNullable<E.A>` stays `E.A`). Mutable declarations
            // still widen through the var-decl path above.
            if (flags.is_enum_literal) return t;
            if (flags.is_string) return types.Primitive.string_t;
            if (flags.is_number) return types.Primitive.number_t;
            if (flags.is_boolean) return types.Primitive.boolean_t;
            if (flags.is_bigint) return types.Primitive.bigint_t;
            return t;
        }
        // Union of literals: array literals like `[1, 2, 3]` produce
        // a numeric indexer typed as `1 | 2 | 3`. Widen each branch
        // and, if all collapse to the same primitive, return that
        // primitive directly. Otherwise leave the union shape alone
        // (the user wrote a heterogeneous array).
        if (flags.is_union) {
            const members = self.interner.unionMembers(t);
            if (members.len == 0) return t;
            const first = self.widenForInference(members[0]);
            for (members[1..]) |m| {
                if (self.widenForInference(m) != first) return t;
            }
            return first;
        }
        return t;
    }

    /// Recursively infer type-parameter substitutions by walking the
    /// parameter shape and the argument shape in parallel. Handles:
    ///
    ///   - Bare type parameter: `T` against `number` ÃÂ¢ÃÂÃÂ `T = number`.
    ///     Literals are widened to their base primitive (matches tsc).
    ///   - Array element: `T[]` against `number[]` ÃÂ¢ÃÂÃÂ `T = number`.
    ///     Arrays are object types with a number indexer, so we read
    ///     `objectNumberIndex` on both sides.
    ///   - Function param: `(x: T) => U` against `(x: number) => string`
    ///     ÃÂ¢ÃÂÃÂ `T = number, U = string`.
    ///   - Object property: `{ value: T }` against `{ value: number }`
    ///     ÃÂ¢ÃÂÃÂ `T = number`. Walks every member by name.
    ///   - Union / intersection on the parameter side: recurse into
    ///     each member against the same arg (any structural match
    ///     contributes a mapping). Keeps `T | undefined` working.
    ///
    /// First-seen wins on conflict; common-supertype is a follow-up.
    fn inferUnionRemainder(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        const pool = &self.interner.pool;
        if (arg_t >= pool.typeCount()) return false;
        const a_flags = pool.flagsOf(arg_t);
        if (!a_flags.is_union) return false;

        const param_members = self.interner.unionMembers(param_t);
        var generic_member: TypeId = types.Primitive.none;
        var generic_count: usize = 0;
        var fixed_count: usize = 0;
        for (param_members) |member| {
            if (self.containsFreeTypeParameter(member)) {
                generic_member = member;
                generic_count += 1;
            } else {
                fixed_count += 1;
            }
        }
        if (generic_count != 1 or fixed_count == 0) return false;

        var remaining: std.ArrayListUnmanaged(TypeId) = .empty;
        defer remaining.deinit(self.gpa);
        var removed_fixed = false;
        for (self.interner.unionMembers(arg_t)) |arg_member| {
            var covered_by_fixed = false;
            for (param_members) |param_member| {
                if (self.containsFreeTypeParameter(param_member)) continue;
                if (arg_member == param_member or (self.engine.isAssignableTo(arg_member, param_member) catch false)) {
                    covered_by_fixed = true;
                    break;
                }
            }
            if (covered_by_fixed) {
                removed_fixed = true;
            } else {
                try remaining.append(self.gpa, arg_member);
            }
        }
        if (!removed_fixed or remaining.items.len == 0) return false;

        const inferred_arg = if (remaining.items.len == 1)
            remaining.items[0]
        else
            self.interner.internUnion(remaining.items) catch return error.OutOfMemory;
        try self.inferFromPair(generic_member, inferred_arg, subs);
        return true;
    }

    fn inferFromCallableSignatureMembers(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        if (!self.interner.isSignature(param_t) or self.interner.isSignature(arg_t)) return false;

        var signatures: std.ArrayListUnmanaged(TypeId) = .empty;
        defer signatures.deinit(self.gpa);
        if (self.signatureIsConstruct(param_t)) {
            try self.collectConstructSignatures(arg_t, &signatures);
        } else {
            try self.collectCallSignatures(arg_t, &signatures);
        }
        if (signatures.items.len == 0) return false;

        var return_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer return_subs.deinit(self.gpa);
        if (self.interner.signatureReturn(param_t)) |param_return| {
            for (signatures.items) |signature| {
                const member_return = self.interner.signatureReturn(signature) orelse continue;
                var member_return_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                defer member_return_subs.deinit(self.gpa);
                try self.inferFromPair(param_return, member_return, &member_return_subs);
                try self.mergeContextualSignatureInferences(&return_subs, &member_return_subs);
            }
            try self.mergeContextualSignatureInferences(subs, &return_subs);
        }

        for (signatures.items) |signature| {
            var member_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
            defer member_subs.deinit(self.gpa);
            try self.inferFromPair(param_t, signature, &member_subs);
            var return_it = return_subs.iterator();
            while (return_it.next()) |entry| _ = member_subs.remove(entry.key_ptr.*);
            try self.mergeContextualSignatureInferences(subs, &member_subs);
        }
        return true;
    }

    fn inferFromPair(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        if (self.noInferInnerType(param_t) != null) return;
        const pool = &self.interner.pool;
        if (param_t >= pool.typeCount()) return;
        if (arg_t >= pool.typeCount()) return;
        const reduced_arg_t = try self.reduceNeverIntersectionsForAssignability(arg_t);
        if (reduced_arg_t != arg_t) return try self.inferFromPair(param_t, reduced_arg_t, subs);
        const p_flags = pool.flagsOf(param_t);
        const p_payload = pool.payloadOf(param_t);
        const a_flags = pool.flagsOf(arg_t);
        if (try self.inferFromSameGenericInstantiation(param_t, arg_t, subs)) return;
        if (try self.inferFromCallableSignatureMembers(param_t, arg_t, subs)) return;
        // Union/intersection flags are aggregate ORs of their members,
        // so a union containing `T` also has `is_type_parameter`.
        // Dispatch compound containers before the bare type-parameter
        // case or `(T | undefined)[]` will bind the whole union as T.
        if (p_flags.is_union) {
            if (p_payload >= pool.union_payloads.items.len) return;
            if (try self.inferUnionRemainder(param_t, arg_t, subs)) return;
            // Recursive inference can intern new types and grow the
            // member pool, invalidating the borrowed unionMembers
            // slice (same hazard as the object-member copy below —
            // reading the dangling slice yielded 0xAAAAAAAA member
            // ids and crashed `recursiveTypeReferences1`). Copy first.
            var u_members_copy: std.ArrayListUnmanaged(TypeId) = .empty;
            defer u_members_copy.deinit(self.gpa);
            try u_members_copy.appendSlice(self.gpa, self.interner.unionMembers(param_t));
            for (u_members_copy.items) |um| {
                if (um >= pool.typeCount()) continue;
                const uf = pool.flagsOf(um);
                if (uf.is_type_parameter and !uf.is_union and !uf.is_intersection) continue;
                try self.inferFromPair(um, arg_t, subs);
            }
            for (u_members_copy.items) |um| {
                if (um >= pool.typeCount()) continue;
                const uf = pool.flagsOf(um);
                if (!(uf.is_type_parameter and !uf.is_union and !uf.is_intersection)) continue;
                try self.inferFromPair(um, arg_t, subs);
            }
            return;
        }
        if (p_flags.is_intersection) {
            if (p_payload >= pool.intersection_payloads.items.len) return;
            // Same dangling-slice hazard as the union branch above.
            var i_members_copy: std.ArrayListUnmanaged(TypeId) = .empty;
            defer i_members_copy.deinit(self.gpa);
            try i_members_copy.appendSlice(self.gpa, self.interner.intersectionMembers(param_t));
            for (i_members_copy.items) |im| {
                if (im >= pool.typeCount()) continue;
                try self.inferFromPair(im, arg_t, subs);
            }
            return;
        }
        if (p_flags.is_mapped and (a_flags.is_object_type or a_flags.is_intersection)) {
            if (try self.inferFromReverseMappedObjectLiteral(param_t, arg_t, subs)) return;
            if (try self.inferFromHomomorphicMappedTarget(param_t, arg_t, subs)) return;
        }
        if (p_flags.is_indexed_access) {
            if (try self.inferFromIndexedAccessTarget(param_t, arg_t, subs)) return;
        }
        if (p_flags.is_conditional) {
            if (try self.inferFromConditionalTarget(param_t, arg_t, subs)) return;
        }
        if (p_flags.is_object_type and a_flags.is_union) {
            if (pool.payloadOf(arg_t) >= pool.union_payloads.items.len) return;
            var members_copy: std.ArrayListUnmanaged(TypeId) = .empty;
            defer members_copy.deinit(self.gpa);
            try members_copy.appendSlice(self.gpa, self.interner.unionMembers(arg_t));
            for (members_copy.items) |member| {
                if (member >= pool.typeCount()) continue;
                const reduced_member = try self.reduceNeverIntersectionsForAssignability(member);
                if (reduced_member == types.Primitive.never or reduced_member >= pool.typeCount()) continue;
                if (!pool.flagsOf(reduced_member).is_object_type) continue;
                try self.inferFromPair(param_t, reduced_member, subs);
            }
            return;
        }
        if (p_flags.is_type_parameter) {
            const tp = pool.type_parameter_payloads.items[p_payload];
            var inferred = if (tp.is_const or try self.typeParameterConstraintPrefersLiteralInference(param_t, subs))
                arg_t
            else
                self.widenForInference(arg_t);
            inferred = self.substituteType(inferred, subs) catch inferred;
            if (self.scalarTypeParameterConstraint(param_t)) |raw_constraint_t| {
                const substituted_constraint_t = self.substituteType(raw_constraint_t, subs) catch raw_constraint_t;
                const constraint_t = (try self.reduceDisplayedAliasInstance(substituted_constraint_t)) orelse substituted_constraint_t;
                const candidate_t = if (tp.is_const) inferred else arg_t;
                const literal_ok = try self.literalTypeAssignableToLiteralConstraint(candidate_t, constraint_t);
                const assignable_ok = self.engine.isAssignableTo(candidate_t, constraint_t) catch false;
                const recursive_template_ok = try self.literalSatisfiesRecursiveTemplatePathConstraint(raw_constraint_t, candidate_t, subs);
                const violates_constraint = self.strictNullishInferenceExcludedByConstraint(candidate_t, constraint_t) or
                    (!literal_ok and !assignable_ok and !recursive_template_ok);
                if (violates_constraint) {
                    return;
                }
            }
            if (subs.get(param_t)) |existing| {
                // Multiple inference candidates for the same type
                // parameter. tsc collects all candidates and picks the
                // best common supertype rather than first-wins, so a
                // later argument that is a supertype of the first widens
                // the binding. This makes `f(b, ÃÂ¢ÃÂÃÂ¦, a)` (b: B, a: A, with
                // B extends A) infer `T = A` instead of `T = B`.
                if (existing == inferred) return;
                if (self.engine.isAssignableTo(arg_t, existing) catch false) return;
                if (try self.templateLiteralInferenceConstraintMerge(param_t, existing, inferred)) |merged| {
                    try subs.put(self.gpa, param_t, merged);
                    return;
                }
                // Array/tuple candidates are excluded from the supertype
                // merge: their inference is driven by dedicated paths
                // (e.g. `inferRestTupleFromSignatureParams` for variadic
                // `(...args: T) => R`), where a tuple binding must not be
                // clobbered by a structurally-wider array candidate from a
                // sibling argument. Keep first-wins for those.
                const existing_is_arraylike = existing < pool.typeCount() and
                    (pool.flagsOf(existing).is_tuple or self.interner.objectNumberIndex(existing) != types.Primitive.none);
                const inferred_is_arraylike = inferred < pool.typeCount() and
                    (pool.flagsOf(inferred).is_tuple or self.interner.objectNumberIndex(inferred) != types.Primitive.none);
                if (existing_is_arraylike or inferred_is_arraylike) return;
                // Only upgrade to a *strict* proper supertype: the
                // existing candidate is assignable to the new one but not
                // vice-versa. Mutually-assignable (equivalent) candidates
                // keep the existing binding to stay conservative on this
                // hot path.
                if ((self.engine.isAssignableTo(existing, inferred) catch false) and
                    !(self.engine.isAssignableTo(inferred, existing) catch false))
                {
                    try subs.put(self.gpa, param_t, inferred);
                }
                return;
            }
            try subs.put(self.gpa, param_t, inferred);
            return;
        }
        // Infer through the iteration protocol, not only through explicit
        // structural members. Home's array shape uses a number index instead
        // of materializing `[Symbol.iterator]`, while tsgo's iteration-type
        // inference still matches `string[]` against `Iterable<T>` and
        // contributes `string` for T.
        if (self.generator_type_info.get(param_t)) |iterable| {
            if (self.isIterableLikeType(arg_t)) {
                const arg_element_t = try self.iterableElementType(arg_t);
                try self.inferFromPair(iterable.yield_type, arg_element_t, subs);
            }
        }
        // Both sides object-typed: match each named member, plus the
        // number indexer (`T[]` parameter / array argument).
        if (p_flags.is_object_type and a_flags.is_object_type) {
            if (p_payload >= pool.object_type_payloads.items.len) return;
            if (pool.payloadOf(arg_t) >= pool.object_type_payloads.items.len) return;
            // Recursive inference can intern new object types and grow the
            // member pool, invalidating the borrowed objectMembers slice.
            const p_members_borrow = self.interner.objectMembers(param_t);
            var p_members_copy: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
            defer p_members_copy.deinit(self.gpa);
            try p_members_copy.appendSlice(self.gpa, p_members_borrow);
            const p_members = p_members_copy.items;
            for (p_members) |pm| {
                if (self.syntheticSignatureMemberName(pm.name)) {
                    const raw_name = self.string_interner.getOptional(pm.name) orelse "";
                    if (std.mem.eql(u8, raw_name, "__construct")) {
                        _ = try self.inferFromConstructSignatureArgument(param_t, arg_t, subs);
                        continue;
                    }
                }
                if (self.interner.objectMember(arg_t, pm.name)) |am_t| {
                    try self.inferFromPair(pm.type, am_t, subs);
                }
            }
            const p_num = self.interner.objectNumberIndex(param_t);
            const a_num = self.interner.objectNumberIndex(arg_t);
            if (p_num != types.Primitive.none and a_num != types.Primitive.none) {
                try self.inferFromPairPreserveLiteral(p_num, a_num, subs);
            }
            const p_str = self.interner.objectStringIndex(param_t);
            const a_str = self.interner.objectStringIndex(arg_t);
            if (p_str != types.Primitive.none and a_str != types.Primitive.none) {
                try self.inferFromPair(p_str, a_str, subs);
            }
            if (p_num != types.Primitive.none and a_num == types.Primitive.none and a_str != types.Primitive.none) {
                try self.inferFromPairPreserveLiteral(p_num, a_str, subs);
            }
            if (p_str != types.Primitive.none and a_str == types.Primitive.none and a_num != types.Primitive.none) {
                try self.inferFromPair(p_str, types.Primitive.unknown, subs);
            }
            return;
        }
        // Both signatures: match params slot-by-slot and return types.
        if (p_flags.is_signature and a_flags.is_signature) {
            if (p_payload >= pool.signature_payloads.items.len) return;
            if (pool.payloadOf(arg_t) >= pool.signature_payloads.items.len) return;
            const pp = try self.gpa.dupe(TypeId, self.interner.signatureParams(param_t));
            defer self.gpa.free(pp);
            if (self.generic_signature_params.get(arg_t) != null and
                self.generic_signature_params.get(param_t) == null and
                self.signatureHasBareGenericRestParam(param_t))
            {
                if (self.interner.signatureReturn(param_t)) |return_t| {
                    if (return_t < pool.typeCount()) {
                        const return_flags = pool.flagsOf(return_t);
                        if (return_flags.is_type_parameter and
                            !return_flags.is_union and
                            !return_flags.is_intersection and
                            !return_flags.is_object_type and
                            !return_flags.is_signature and
                            !subs.contains(return_t))
                        {
                            try subs.put(self.gpa, return_t, types.Primitive.unknown);
                        }
                    }
                }
                return;
            }
            const raw_ap = self.interner.signatureParams(arg_t);
            var logical_ap: std.ArrayListUnmanaged(TypeId) = .empty;
            defer logical_ap.deinit(self.gpa);
            _ = try self.appendLogicalSignatureInferenceParams(arg_t, raw_ap, &logical_ap);
            const ap = logical_ap.items;
            try self.inferRestTupleFromSignatureParams(param_t, pp, arg_t, raw_ap, subs);
            const m = @min(pp.len, ap.len);
            var source_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
            defer source_subs.deinit(self.gpa);
            for (0..m) |i| {
                const expected_param = self.substituteType(pp[i], subs) catch pp[i];
                const actual_param = ap[i];
                if ((actual_param == types.Primitive.any or actual_param == types.Primitive.unknown) and
                    self.containsFreeTypeParameter(expected_param))
                {
                    continue;
                }
                if (actual_param >= pool.typeCount()) continue;
                const af = pool.flagsOf(actual_param);
                if (af.is_type_parameter) {
                    if (!source_subs.contains(actual_param)) {
                        try source_subs.put(self.gpa, actual_param, expected_param);
                    }
                    continue;
                }
                try self.inferFromPair(expected_param, actual_param, subs);
            }
            if (self.interner.signatureReturn(param_t)) |pr| {
                if (self.interner.signatureReturn(arg_t)) |ar| {
                    const actual_ret = self.substituteType(ar, &source_subs) catch ar;
                    const inferred_param_ret = self.substituteType(pr, subs) catch pr;
                    const parameter_inference_already_fixed_generator = inferred_param_ret != pr and
                        self.generator_type_info.contains(inferred_param_ret) and
                        self.generator_type_info.contains(actual_ret);
                    if (!parameter_inference_already_fixed_generator) {
                        try self.inferFromCallbackReturnPair(pr, actual_ret, subs);
                    }
                }
            }
            return;
        }
    }

    fn inferFromCallbackReturnPair(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        if (param_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(param_t).is_type_parameter)
        {
            if (subs.get(param_t)) |existing| {
                const inferred = self.widenForInference(arg_t);
                const unrelated = !(self.engine.isAssignableTo(existing, inferred) catch false) and
                    !(self.engine.isAssignableTo(inferred, existing) catch false);
                if (unrelated and
                    self.inferenceCandidateIsPrimitiveLike(existing) and
                    self.inferenceCandidateIsPrimitiveLike(inferred))
                {
                    const combined = self.interner.internUnion(&.{ existing, inferred }) catch return error.OutOfMemory;
                    try subs.put(self.gpa, param_t, combined);
                    return;
                }
            }
        }
        try self.inferFromPair(param_t, arg_t, subs);
    }

    fn inferenceCandidateIsPrimitiveLike(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.inferenceCandidateIsPrimitiveLike(member)) return false;
            }
            return self.interner.unionMembers(t).len > 0;
        }
        return flags.is_string or
            flags.is_number or
            flags.is_boolean or
            flags.is_bigint or
            flags.is_symbol;
    }

    fn inferFromSameGenericInstantiation(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        const param_args = self.alias_type_args.get(param_t) orelse return false;
        const arg_args = self.alias_type_args.get(arg_t) orelse return false;
        if (param_args.len == 0 or param_args.len != arg_args.len) return false;
        const param_name = (try self.genericInstanceBaseName(param_t)) orelse return false;
        const arg_name = (try self.genericInstanceBaseName(arg_t)) orelse return false;
        if (param_name != arg_name) return false;
        for (param_args, arg_args) |param_arg, arg_arg| {
            try self.inferFromPair(param_arg, arg_arg, subs);
        }
        return true;
    }

    fn inferFromPairPreserveLiteral(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        if (param_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(param_t).is_type_parameter) {
            const inferred = self.substituteType(arg_t, subs) catch arg_t;
            if (!subs.contains(param_t)) {
                try subs.put(self.gpa, param_t, inferred);
            }
            return;
        }
        try self.inferFromPair(param_t, arg_t, subs);
    }

    fn templateLiteralInferenceConstraintMerge(
        self: *Checker,
        param_t: TypeId,
        existing: TypeId,
        inferred: TypeId,
    ) CheckError!?TypeId {
        if (existing >= self.interner.pool.typeCount() or inferred >= self.interner.pool.typeCount()) return null;
        const existing_flags = self.interner.pool.flagsOf(existing);
        const inferred_flags = self.interner.pool.flagsOf(inferred);
        if (!(existing_flags.is_template_literal or existing_flags.is_string_mapping) or
            !(inferred_flags.is_template_literal or inferred_flags.is_string_mapping))
        {
            return null;
        }
        const raw_constraint_t = self.typeParameterConstraint(param_t) orelse return null;
        const constraint_t = (try self.reduceDisplayedAliasInstance(raw_constraint_t)) orelse raw_constraint_t;
        if (constraint_t >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(constraint_t).is_template_literal)
        {
            return null;
        }
        if (!(try self.templateLiteralSourceAssignableToTarget(existing, constraint_t)) and
            !(self.engine.isAssignableTo(existing, constraint_t) catch false))
        {
            return null;
        }
        if (!(try self.templateLiteralSourceAssignableToTarget(inferred, constraint_t)) and
            !(self.engine.isAssignableTo(inferred, constraint_t) catch false))
        {
            return null;
        }
        return constraint_t;
    }

    fn inferFromHomomorphicMappedTarget(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        const source_tp = self.homomorphicMappedSourceTypeParameter(param_t) orelse
            (self.limitedReverseMappedSourceTypeParameter(param_t) orelse return false);
        try self.inferFromPair(source_tp, arg_t, subs);
        return true;
    }

    fn inferFromIndexedAccessTarget(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        if (param_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(param_t).is_indexed_access) return false;
        const ia = self.interner.pool.indexed_access_payloads.items[self.interner.pool.payloadOf(param_t)];
        if (ia.object >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(ia.object).is_type_parameter) return false;
        const index_t = self.substituteType(ia.index, subs) catch ia.index;
        if (index_t == types.Primitive.number_t) {
            try self.mergeNumberIndexInference(ia.object, arg_t, subs);
            return true;
        }
        const key = self.stringLiteralValueFromType(index_t) orelse return false;
        try self.mergeIndexedAccessInference(ia.object, key, arg_t, subs);
        return true;
    }

    fn mergeIndexedAccessInference(
        self: *Checker,
        source_tp: TypeId,
        key: hir_mod.StringId,
        value_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        if (subs.get(source_tp)) |existing| {
            if (existing < self.interner.pool.typeCount() and self.interner.pool.flagsOf(existing).is_object_type) {
                for (self.interner.objectMembers(existing)) |member| {
                    if (member.name == key) {
                        const merged_t = if (member.type == value_t or (self.engine.isAssignableTo(value_t, member.type) catch false))
                            member.type
                        else if (self.engine.isAssignableTo(member.type, value_t) catch false)
                            value_t
                        else
                            self.interner.internUnion(&.{ member.type, value_t }) catch value_t;
                        try members.append(self.gpa, .{
                            .name = key,
                            .type = merged_t,
                            .is_optional = false,
                            .is_readonly = false,
                            .is_method = false,
                        });
                    } else {
                        try members.append(self.gpa, member);
                    }
                }
                if (self.interner.objectMemberInfo(existing, key) == null) {
                    try members.append(self.gpa, .{
                        .name = key,
                        .type = value_t,
                        .is_optional = false,
                        .is_readonly = false,
                        .is_method = false,
                    });
                }
                try subs.put(self.gpa, source_tp, self.interner.internObjectType(members.items) catch return error.OutOfMemory);
                return;
            }
        }
        const member = types.ObjectMember{
            .name = key,
            .type = value_t,
            .is_optional = false,
            .is_readonly = false,
            .is_method = false,
        };
        try subs.put(self.gpa, source_tp, self.interner.internObjectType(&.{member}) catch return error.OutOfMemory);
    }

    fn mergeNumberIndexInference(
        self: *Checker,
        source_tp: TypeId,
        value_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        if (subs.get(source_tp)) |existing| {
            if (existing < self.interner.pool.typeCount() and self.interner.pool.flagsOf(existing).is_object_type) {
                const existing_idx = self.interner.objectNumberIndex(existing);
                const merged_idx = if (existing_idx == types.Primitive.none or existing_idx == value_t or (self.engine.isAssignableTo(value_t, existing_idx) catch false))
                    if (existing_idx == types.Primitive.none) value_t else existing_idx
                else if (self.engine.isAssignableTo(existing_idx, value_t) catch false)
                    value_t
                else
                    self.interner.internUnion(&.{ existing_idx, value_t }) catch value_t;
                const members = self.interner.objectMembers(existing);
                return subs.put(
                    self.gpa,
                    source_tp,
                    self.interner.internObjectTypeWithIndexAndSymbol(
                        members,
                        self.interner.objectStringIndex(existing),
                        merged_idx,
                        self.interner.objectSymbolIndex(existing),
                    ) catch return error.OutOfMemory,
                );
            }
        }
        try subs.put(
            self.gpa,
            source_tp,
            self.interner.internObjectTypeWithIndexAndSymbol(&.{}, types.Primitive.none, value_t, types.Primitive.none) catch return error.OutOfMemory,
        );
    }

    fn typeParameterConstraintPrefersLiteralInference(
        self: *Checker,
        param_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        const resolved_param = self.resolvedTypeParameterPlaceholder(param_t);
        if (self.type_parameter_decl_nodes.get(resolved_param)) |decl_node| {
            if (decl_node != hir_mod.none_node_id and self.hir.kindOf(decl_node) == .type_parameter) {
                const decl = hir_mod.typeParameterOf(self.hir, decl_node);
                if (decl.constraint != hir_mod.none_node_id and
                    (self.hir.kindOf(decl.constraint) == .keyof_type or
                        self.typeNodeKeyofBaseName(decl.constraint, 0) != null))
                {
                    return true;
                }
            }
        }
        const raw_constraint = self.typeParameterConstraint(param_t) orelse return false;
        const substituted_constraint = self.substituteType(raw_constraint, subs) catch raw_constraint;
        var constraint = (try self.reduceDisplayedAliasInstance(substituted_constraint)) orelse substituted_constraint;
        if (constraint < self.interner.pool.typeCount() and self.interner.pool.flagsOf(constraint).is_conditional) {
            const c = self.interner.conditionalPayload(constraint);
            const evaluated = try self.evalConditionalWithDistribution(c.check_type, c.extends_type, c.true_branch, c.false_branch, true, c.is_distributive);
            if (evaluated != constraint) constraint = evaluated;
        }
        if (self.containsTemplateLiteralType(constraint)) return true;
        if (constraint == types.Primitive.string_t or
            constraint == types.Primitive.number_t or
            constraint == types.Primitive.bigint_t or
            constraint == types.Primitive.boolean_t or
            constraint == types.Primitive.symbol_t)
        {
            return true;
        }
        return self.typeIsKeyofLikeLiteralConstraint(constraint);
    }

    fn typeIsKeyofLikeLiteralConstraint(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_keyof) return true;
        if (flags.is_union) {
            var saw_literal = false;
            for (self.interner.unionMembers(t)) |member| {
                if (!self.typeIsPropertyKeyLiteral(member)) return false;
                saw_literal = true;
            }
            return saw_literal;
        }
        return self.typeIsPropertyKeyLiteral(t);
    }

    fn typeIsPropertyKeyDomain(self: *Checker, t: TypeId, depth: u8) bool {
        if (depth >= 24 or t >= self.interner.pool.typeCount()) return false;
        if (t == types.Primitive.never or
            t == types.Primitive.string_t or
            t == types.Primitive.number_t or
            t == types.Primitive.symbol_t)
        {
            return true;
        }
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_keyof or
            flags.is_template_literal or
            flags.is_string_mapping or
            self.typeIsPropertyKeyLiteral(t))
        {
            return true;
        }
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (!self.typeIsPropertyKeyDomain(member, depth + 1)) return false;
            }
            return true;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeIsPropertyKeyDomain(member, depth + 1)) return true;
            }
            return false;
        }
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.typeIsPropertyKeyDomain(constraint, depth + 1);
        }
        if (flags.is_conditional) {
            const conditional = self.interner.conditionalPayload(t);
            return self.typeIsPropertyKeyDomain(conditional.true_branch, depth + 1) and
                self.typeIsPropertyKeyDomain(conditional.false_branch, depth + 1);
        }
        return false;
    }

    fn literalSatisfiesRecursiveTemplatePathConstraint(
        self: *Checker,
        raw_constraint_t: TypeId,
        literal_t: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        if (!self.containsTemplateLiteralType(raw_constraint_t)) return false;
        const sid = self.stringLiteralValueFromType(literal_t) orelse return false;
        const path = self.string_interner.get(sid);
        const root_tp = self.firstSubstitutedFreeTypeParameter(raw_constraint_t, subs) orelse return false;
        const root_t = subs.get(root_tp) orelse return false;
        const ok = try self.objectTypeHasDottedPath(root_t, path);
        return ok;
    }

    fn firstSubstitutedFreeTypeParameter(
        self: *Checker,
        t: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_type_parameter) return if (subs.contains(t)) t else null;
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |m| {
                if (self.firstSubstitutedFreeTypeParameter(m, subs)) |tp| return tp;
            }
            return null;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |m| {
                if (self.firstSubstitutedFreeTypeParameter(m, subs)) |tp| return tp;
            }
            return null;
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |m| {
                if (self.firstSubstitutedFreeTypeParameter(m.type, subs)) |tp| return tp;
            }
            const string_idx = self.interner.objectStringIndex(t);
            if (string_idx != types.Primitive.none) {
                if (self.firstSubstitutedFreeTypeParameter(string_idx, subs)) |tp| return tp;
            }
            const number_idx = self.interner.objectNumberIndex(t);
            if (number_idx != types.Primitive.none) {
                if (self.firstSubstitutedFreeTypeParameter(number_idx, subs)) |tp| return tp;
            }
            return null;
        }
        if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |p| {
                if (self.firstSubstitutedFreeTypeParameter(p, subs)) |tp| return tp;
            }
            if (self.interner.signatureReturn(t)) |r| {
                if (self.firstSubstitutedFreeTypeParameter(r, subs)) |tp| return tp;
            }
            return null;
        }
        if (flags.is_keyof) {
            const payload_idx = self.interner.pool.payloadOf(t);
            if (payload_idx >= self.interner.pool.keyof_payloads.items.len) return null;
            const k = self.interner.pool.keyof_payloads.items[payload_idx];
            return self.firstSubstitutedFreeTypeParameter(k.operand, subs);
        }
        if (flags.is_indexed_access) {
            const payload_idx = self.interner.pool.payloadOf(t);
            if (payload_idx >= self.interner.pool.indexed_access_payloads.items.len) return null;
            const ia = self.interner.pool.indexed_access_payloads.items[payload_idx];
            return self.firstSubstitutedFreeTypeParameter(ia.object, subs) orelse
                self.firstSubstitutedFreeTypeParameter(ia.index, subs);
        }
        if (flags.is_conditional) {
            const c = self.interner.conditionalPayload(t);
            return self.firstSubstitutedFreeTypeParameter(c.check_type, subs) orelse
                self.firstSubstitutedFreeTypeParameter(c.extends_type, subs) orelse
                self.firstSubstitutedFreeTypeParameter(c.true_branch, subs) orelse
                self.firstSubstitutedFreeTypeParameter(c.false_branch, subs);
        }
        if (flags.is_mapped) {
            const m = self.interner.mappedPayload(t);
            return self.firstSubstitutedFreeTypeParameter(m.constraint, subs) orelse
                self.firstSubstitutedFreeTypeParameter(m.template, subs);
        }
        if (flags.is_template_literal) {
            for (self.interner.templateLiteralTypes(t)) |part| {
                if (self.firstSubstitutedFreeTypeParameter(part, subs)) |tp| return tp;
            }
            return null;
        }
        if (flags.is_string_mapping) {
            return self.firstSubstitutedFreeTypeParameter(self.interner.stringMappingPayload(t).inner, subs);
        }
        return null;
    }

    fn objectTypeHasDottedPath(self: *Checker, root_t: TypeId, path: []const u8) CheckError!bool {
        if (path.len == 0) return false;
        const dot = std.mem.indexOfScalar(u8, path, '.');
        const head = if (dot) |i| path[0..i] else path;
        const tail = if (dot) |i| path[i + 1 ..] else "";
        const head_sid = self.string_interner.intern(head) catch return error.OutOfMemory;
        const member_t = (try self.pathSegmentType(root_t, head_sid)) orelse return false;
        if (tail.len == 0) return true;
        return try self.objectTypeHasDottedPath(member_t, tail);
    }

    fn pathSegmentType(self: *Checker, container_t: TypeId, segment: hir_mod.StringId) CheckError!?TypeId {
        const t = self.typeParameterConstraint(container_t) orelse container_t;
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (try self.pathSegmentType(member, segment)) |member_t| return member_t;
            }
            return null;
        }
        if (!flags.is_object_type and !flags.is_intersection) return null;
        if (try self.lookupObjectMember(t, segment)) |member_t| return member_t;
        if (self.isNumericStringId(segment)) {
            const elem_t = self.interner.objectNumberIndex(t);
            if (elem_t != types.Primitive.none) return elem_t;
        }
        return null;
    }

    fn reduceDisplayedAliasInstance(self: *Checker, t: TypeId) CheckError!?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        const display = self.alias_display_names.get(t) orelse return null;
        if (try self.reduceIndexForDisplay(display)) |reduced| return reduced;
        const args = self.alias_type_args.get(t) orelse return null;
        const lt = std.mem.indexOfScalar(u8, display, '<') orelse return null;
        if (lt == 0 or args.len == 0) return null;
        const alias_name = self.string_interner.intern(display[0..lt]) catch return error.OutOfMemory;
        const info = self.generic_aliases.get(alias_name) orelse return null;
        if (info.body_node == hir_mod.none_node_id or info.params.len == 0) return null;

        try self.pushNarrowScope();
        defer self.popNarrowScope();
        const n = @min(args.len, info.params.len);
        for (info.params[0..n], args[0..n]) |param_t, arg_t| {
            if (param_t >= self.interner.pool.typeCount()) continue;
            if (!self.interner.pool.flagsOf(param_t).is_type_parameter) continue;
            const payload_idx = self.interner.pool.payloadOf(param_t);
            if (payload_idx >= self.interner.pool.type_parameter_payloads.items.len) continue;
            const payload = self.interner.pool.type_parameter_payloads.items[payload_idx];
            try self.recordNarrow(payload.name, arg_t);
        }
        const reduced = try self.lowererLowerWithTypeParams(info.body_node);
        return if (reduced == t) null else reduced;
    }

    fn reduceIndexForDisplay(self: *Checker, display: []const u8) CheckError!?TypeId {
        if (!std.mem.startsWith(u8, display, "IndexFor<")) return null;
        var members: std.ArrayListUnmanaged(TypeId) = .empty;
        defer members.deinit(self.gpa);
        var i: usize = "IndexFor<".len;
        while (std.mem.indexOfScalarPos(u8, display, i, '"')) |start_quote| {
            const value_start = start_quote + 1;
            const end_quote = std.mem.indexOfScalarPos(u8, display, value_start, '"') orelse break;
            const raw = display[value_start..end_quote];
            const value = std.fmt.parseFloat(f64, raw) catch {
                i = end_quote + 1;
                continue;
            };
            try members.append(self.gpa, self.interner.internNumberLiteral(value) catch return error.OutOfMemory);
            i = end_quote + 1;
        }
        if (members.items.len == 0) return types.Primitive.never;
        if (members.items.len == 1) return members.items[0];
        return self.interner.internUnion(members.items) catch return error.OutOfMemory;
    }

    fn literalTypeAssignableToLiteralConstraint(self: *Checker, source_t: TypeId, target_t: TypeId) CheckError!bool {
        if (source_t >= self.interner.pool.typeCount() or target_t >= self.interner.pool.typeCount()) return false;
        const source_flags = self.interner.pool.flagsOf(source_t);
        if (!source_flags.is_literal) return false;
        const target_flags = self.interner.pool.flagsOf(target_t);
        if (target_flags.is_keyof) return self.typeIsPropertyKeyLiteral(source_t);
        if (target_flags.is_union) {
            for (self.interner.unionMembers(target_t)) |member| {
                if (try self.literalTypeAssignableToLiteralConstraint(source_t, member)) return true;
            }
            return false;
        }
        if (target_flags.is_intersection) {
            for (self.interner.intersectionMembers(target_t)) |member| {
                if (!try self.literalTypeAssignableToLiteralConstraint(source_t, member)) return false;
            }
            return true;
        }
        if (!target_flags.is_literal) return false;
        const source_lit = self.interner.literalOfOrNull(source_t) orelse return false;
        const target_lit = self.interner.literalOfOrNull(target_t) orelse return false;
        return switch (source_lit) {
            .string_lit => |source_sid| switch (target_lit) {
                .string_lit => |target_sid| source_sid == target_sid or try self.cookedStringIdEquals(source_sid, target_sid),
                else => false,
            },
            .number_lit => |source_bits| switch (target_lit) {
                .number_lit => |target_bits| source_bits == target_bits,
                else => false,
            },
            .bigint_lit => |source_sid| switch (target_lit) {
                .bigint_lit => |target_sid| source_sid == target_sid,
                else => false,
            },
            .boolean_lit => |source_bool| switch (target_lit) {
                .boolean_lit => |target_bool| source_bool == target_bool,
                else => false,
            },
        };
    }

    fn typeIsPropertyKeyLiteral(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_literal) return false;
        return flags.is_string or flags.is_number or flags.is_bigint or flags.is_symbol;
    }

    fn indexedAccessPayloadOrNull(self: *Checker, t: TypeId) ?types.IndexedAccessPayload {
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_indexed_access or flags.is_union or flags.is_intersection) return null;
        const payload_idx = self.interner.pool.payloadOf(t);
        if (payload_idx >= self.interner.pool.indexed_access_payloads.items.len) return null;
        return self.interner.pool.indexed_access_payloads.items[payload_idx];
    }

    fn homomorphicMappedSourceTypeParameter(self: *Checker, mapped_t: TypeId) ?TypeId {
        if (mapped_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(mapped_t);
        if (!flags.is_mapped) return null;
        const m = self.interner.mappedPayload(mapped_t);
        if (m.constraint >= self.interner.pool.typeCount()) return null;
        const constraint_flags = self.interner.pool.flagsOf(m.constraint);
        if (!constraint_flags.is_keyof) return null;
        const k = self.interner.pool.keyof_payloads.items[self.interner.pool.payloadOf(m.constraint)];
        if (k.operand >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(k.operand).is_type_parameter) return null;
        if (m.template >= self.interner.pool.typeCount()) return null;
        const template_flags = self.interner.pool.flagsOf(m.template);
        if (!template_flags.is_indexed_access) return null;
        const ia = self.indexedAccessPayloadOrNull(m.template) orelse return null;
        if (ia.object != k.operand) return null;
        if (ia.index >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(ia.index).is_type_parameter) return null;
        return k.operand;
    }

    fn homomorphicMappedTypeParameter(self: *Checker, mapped_t: TypeId) ?TypeId {
        if (mapped_t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(mapped_t).is_mapped) return null;
        const operand = self.directKeyofOperand(self.interner.mappedPayload(mapped_t).constraint) orelse return null;
        if (operand >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(operand).is_type_parameter) return null;
        return operand;
    }

    fn typeParameterHasArrayOrTupleConstraint(self: *Checker, type_param: TypeId) bool {
        const constraint = self.typeParameterConstraint(type_param) orelse return false;
        return self.everyTypeIsArrayOrTuple(constraint);
    }

    fn everyTypeIsArrayOrTuple(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            const members = self.interner.unionMembers(t);
            if (members.len == 0) return false;
            for (members) |member| {
                if (!self.everyTypeIsArrayOrTuple(member)) return false;
            }
            return true;
        }
        if (flags.is_type_parameter) {
            const constraint = self.typeParameterConstraint(t) orelse return false;
            if (constraint == t) return false;
            return self.everyTypeIsArrayOrTuple(constraint);
        }
        return self.isTupleShapedTarget(t) or self.objectTypeIsArrayLikeContainer(t);
    }

    fn limitedReverseMappedSourceTypeParameter(self: *Checker, mapped_t: TypeId) ?TypeId {
        if (mapped_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(mapped_t);
        if (!flags.is_mapped) return null;
        const m = self.interner.mappedPayload(mapped_t);
        const source_tp = self.mappedTemplateObjectTypeParameter(m.template) orelse return null;
        if (!self.typeContainsKeyofOperand(m.constraint, source_tp)) return null;
        return source_tp;
    }

    fn mappedTemplateObjectTypeParameter(self: *Checker, template: TypeId) ?TypeId {
        if (template >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(template);
        if (!flags.is_indexed_access) return null;
        const ia = self.indexedAccessPayloadOrNull(template) orelse return null;
        if (ia.object >= self.interner.pool.typeCount() or ia.index >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(ia.object).is_type_parameter) return null;
        if (!self.interner.pool.flagsOf(ia.index).is_type_parameter) return null;
        return ia.object;
    }

    const MappedIndexedAccess = struct {
        object_tp: TypeId,
        key_tp: TypeId,
    };

    fn mappedTemplateIndexedAccess(self: *Checker, t: TypeId) ?MappedIndexedAccess {
        return self.mappedTemplateIndexedAccessInner(t, true);
    }

    fn mappedTemplateIndexedAccessWithConcreteObject(self: *Checker, t: TypeId) ?MappedIndexedAccess {
        return self.mappedTemplateIndexedAccessInner(t, false);
    }

    fn mappedTemplateIndexedAccessInner(
        self: *Checker,
        t: TypeId,
        require_type_parameter_object: bool,
    ) ?MappedIndexedAccess {
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        // Union/intersection flags aggregate their constituent flags. Walk
        // containers before testing the leaf indexed-access flag so
        // `T[K] | Recursive<T[K]>` is not decoded using a union payload.
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.mappedTemplateIndexedAccessInner(member, require_type_parameter_object)) |hit| return hit;
            }
            return null;
        }
        if (flags.is_indexed_access) {
            const ia = self.indexedAccessPayloadOrNull(t) orelse return null;
            if (ia.object < self.interner.pool.typeCount() and
                ia.index < self.interner.pool.typeCount() and
                (!require_type_parameter_object or self.interner.pool.flagsOf(ia.object).is_type_parameter) and
                self.interner.pool.flagsOf(ia.index).is_type_parameter)
            {
                return .{ .object_tp = ia.object, .key_tp = ia.index };
            }
            return null;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.mappedTemplateIndexedAccessInner(member, require_type_parameter_object)) |hit| return hit;
            }
            return null;
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |member| {
                if (self.mappedTemplateIndexedAccessInner(member.type, require_type_parameter_object)) |hit| return hit;
            }
            const str_idx = self.interner.objectStringIndex(t);
            if (str_idx != types.Primitive.none) {
                if (self.mappedTemplateIndexedAccessInner(str_idx, require_type_parameter_object)) |hit| return hit;
            }
            const num_idx = self.interner.objectNumberIndex(t);
            if (num_idx != types.Primitive.none) {
                if (self.mappedTemplateIndexedAccessInner(num_idx, require_type_parameter_object)) |hit| return hit;
            }
            return null;
        }
        if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |param| {
                if (self.mappedTemplateIndexedAccessInner(param, require_type_parameter_object)) |hit| return hit;
            }
            if (self.interner.signatureReturn(t)) |ret| {
                if (self.mappedTemplateIndexedAccessInner(ret, require_type_parameter_object)) |hit| return hit;
            }
            return null;
        }
        return null;
    }

    fn typeContainsKeyofOperand(self: *Checker, t: TypeId, operand_t: TypeId) bool {
        if (t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_keyof) {
            return (self.directKeyofOperand(t) orelse return false) == operand_t;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeContainsKeyofOperand(member, operand_t)) return true;
            }
        }
        return false;
    }

    fn reportMismatchedGenericKeyofIndex(
        self: *Checker,
        access_node: NodeId,
        object_t: TypeId,
        index_t: TypeId,
    ) CheckError!bool {
        if (object_t >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(object_t).is_type_parameter)
        {
            return false;
        }
        const operand = self.directKeyofOperand(index_t) orelse return false;
        if (operand >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(operand).is_intersection)
        {
            return false;
        }
        var has_object_parameter = false;
        var has_empty_object = false;
        for (self.interner.intersectionMembers(operand)) |member| {
            if (member == object_t) has_object_parameter = true;
            if (self.typeIsEmptyObjectType(member)) has_empty_object = true;
        }
        if (!has_object_parameter or !has_empty_object) return false;
        const operand_name = (try self.allocSimpleTypeName(operand)) orelse "T & {}";
        const key_name = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "keyof ({s})",
            .{operand_name},
        );
        const object_name = (try self.allocSimpleTypeName(object_t)) orelse "T";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' cannot be used to index type '{s}'.",
            .{ key_name, object_name },
        );
        try self.diagnostics.append(self.gpa, .{
            .node = access_node,
            .code = TsCodes.type_cannot_be_used_to_index_type,
            .message = msg,
        });
        return true;
    }

    fn reportGenericKeyCannotIndexElement(
        self: *Checker,
        access_node: NodeId,
        object_node: NodeId,
        index_node: NodeId,
        object_t: TypeId,
        index_t: TypeId,
    ) CheckError!bool {
        if (object_t >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(object_t).is_type_parameter)
        {
            return false;
        }
        const key_operand = self.constrainedKeyofOperand(index_t, 0) orelse return false;
        if (key_operand >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(key_operand).is_type_parameter)
        {
            return false;
        }
        if (self.typeParameterConstraintChainContains(object_t, key_operand)) return false;

        const index_name = (try self.elementAccessOperandAnnotationName(index_node)) orelse
            (try self.allocAssignmentDiagnosticTypeName(index_t)) orelse
            (try self.allocSimpleTypeName(index_t)) orelse
            "unknown";
        const object_name = (try self.elementAccessOperandAnnotationName(object_node)) orelse
            (try self.allocAssignmentDiagnosticTypeName(object_t)) orelse
            (try self.allocSimpleTypeName(object_t)) orelse
            "unknown";
        const msg = try std.fmt.allocPrint(
            self.diag_arena.allocator(),
            "Type '{s}' cannot be used to index type '{s}'.",
            .{ index_name, object_name },
        );
        try self.reportOnce(access_node, TsCodes.type_cannot_be_used_to_index_type, msg);
        return true;
    }

    fn constrainedKeyofOperand(self: *Checker, t: TypeId, depth: u8) ?TypeId {
        if (depth > 16 or t >= self.interner.pool.typeCount()) return null;
        if (self.directKeyofOperand(t)) |operand| return operand;
        if (!self.interner.pool.flagsOf(t).is_type_parameter) return null;
        const constraint = self.typeParameterConstraint(t) orelse return null;
        if (constraint == t) return null;
        return self.constrainedKeyofOperand(constraint, depth + 1);
    }

    fn typeParameterConstraintChainContains(self: *Checker, source_t: TypeId, target_t: TypeId) bool {
        if (source_t == target_t) return true;
        var current = source_t;
        var depth: u8 = 0;
        while (depth < 16) : (depth += 1) {
            const constraint = self.typeParameterConstraint(current) orelse return false;
            if (constraint == target_t) return true;
            if (constraint == current or
                constraint >= self.interner.pool.typeCount() or
                !self.interner.pool.flagsOf(constraint).is_type_parameter)
            {
                return false;
            }
            current = constraint;
        }
        return false;
    }

    fn typeIsDirectKeyofOperand(self: *Checker, t: TypeId, operand_t: TypeId) bool {
        return (self.directKeyofOperand(t) orelse return false) == operand_t;
    }

    fn directKeyofOperand(self: *Checker, t: TypeId) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        if (!self.interner.pool.flagsOf(t).is_keyof) return null;
        const payload_idx = self.interner.pool.payloadOf(t);
        if (payload_idx >= self.interner.pool.keyof_payloads.items.len) return null;
        const k = self.interner.pool.keyof_payloads.items[payload_idx];
        return k.operand;
    }

    fn inferRestTupleFromSignatureParams(
        self: *Checker,
        param_sig: TypeId,
        param_params: []const TypeId,
        arg_sig: TypeId,
        arg_params: []const TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        if (!self.rest_signatures.contains(param_sig) or param_params.len == 0) return;
        const rest_param_t = param_params[param_params.len - 1];
        if (rest_param_t >= self.interner.pool.typeCount()) return;
        if (!self.interner.pool.flagsOf(rest_param_t).is_type_parameter) return;
        if (subs.contains(rest_param_t)) return;
        const fixed_count = param_params.len - 1;
        var logical_args: std.ArrayListUnmanaged(TypeId) = .empty;
        defer logical_args.deinit(self.gpa);
        const source_min = try self.appendLogicalSignatureInferenceParams(arg_sig, arg_params, &logical_args);
        if (logical_args.items.len < fixed_count) return;
        const rest_min = if (source_min > fixed_count) source_min - fixed_count else 0;
        const tuple_t = try self.internTupleFromTypesWithMinRequired(
            logical_args.items[fixed_count..],
            rest_min,
            false,
        );
        try subs.put(self.gpa, rest_param_t, tuple_t);
    }

    fn appendLogicalSignatureInferenceParams(
        self: *Checker,
        sig: TypeId,
        params: []const TypeId,
        out: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!usize {
        if (!self.rest_signatures.contains(sig) or params.len == 0) {
            try out.appendSlice(self.gpa, params);
            return self.signatureMinRequiredArgs(sig, params);
        }
        const fixed_count = params.len - 1;
        try out.appendSlice(self.gpa, params[0..fixed_count]);
        const rest_t = params[params.len - 1];
        const rest_len = self.fixedTupleLength(rest_t) orelse {
            try out.append(self.gpa, rest_t);
            return self.signatureMinRequiredArgs(sig, params);
        };
        for (0..@as(usize, @intCast(rest_len))) |index| {
            const element_t = self.tupleElementType(rest_t, index);
            if (element_t == types.Primitive.none) break;
            try out.append(self.gpa, element_t);
        }
        const fixed_min = @min(self.signatureMinRequiredArgs(sig, params), fixed_count);
        return fixed_min + self.tupleRestMinRequiredCount(rest_t);
    }

    fn signatureHasBareGenericRestParam(self: *Checker, sig: TypeId) bool {
        if (!self.rest_signatures.contains(sig)) return false;
        const params = self.interner.signatureParams(sig);
        if (params.len == 0) return false;
        const rest_param_t = params[params.len - 1];
        if (rest_param_t >= self.interner.pool.typeCount()) return false;
        return self.interner.pool.flagsOf(rest_param_t).is_type_parameter;
    }

    fn internTupleFromTypes(self: *Checker, elem_types: []const TypeId, readonly: bool) CheckError!TypeId {
        return self.internTupleFromTypesWithMinRequired(elem_types, elem_types.len, readonly);
    }

    fn internTupleFromTypesWithMinRequired(
        self: *Checker,
        elem_types: []const TypeId,
        min_required: usize,
        readonly: bool,
    ) CheckError!TypeId {
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        for (elem_types, 0..) |t, i| {
            var nbuf: [12]u8 = undefined;
            const name_str = std.fmt.bufPrint(&nbuf, "{d}", .{i}) catch continue;
            const name = self.string_interner.intern(name_str) catch return error.OutOfMemory;
            try members.append(self.gpa, .{
                .name = name,
                .type = t,
                .is_optional = i >= min_required,
                .is_readonly = readonly,
                .is_method = false,
            });
        }
        const length_id = self.string_interner.intern("length") catch return error.OutOfMemory;
        const length_t = self.interner.internNumberLiteral(@floatFromInt(elem_types.len)) catch types.Primitive.number_t;
        try members.append(self.gpa, .{
            .name = length_id,
            .type = length_t,
            .is_optional = false,
            .is_readonly = true,
            .is_method = false,
        });
        const elem_union: TypeId = if (elem_types.len == 0)
            types.Primitive.never
        else if (elem_types.len == 1)
            elem_types[0]
        else
            self.interner.internUnion(elem_types) catch types.Primitive.any;
        const tuple_t = self.interner.internObjectTypeWithIndex(members.items, types.Primitive.none, elem_union) catch return error.OutOfMemory;
        try self.markTupleOrigin(tuple_t);
        return tuple_t;
    }

    fn mutableFiniteTupleCopy(self: *Checker, tuple_t: TypeId) CheckError!?TypeId {
        if (tuple_t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(tuple_t);
        if (flags.is_union) {
            var branches: std.ArrayListUnmanaged(TypeId) = .empty;
            defer branches.deinit(self.gpa);
            for (self.interner.unionMembers(tuple_t)) |member| {
                const copied = (try self.mutableFiniteTupleCopy(member)) orelse return null;
                try branches.append(self.gpa, copied);
            }
            if (branches.items.len == 0) return null;
            if (branches.items.len == 1) return branches.items[0];
            return self.interner.internUnion(branches.items) catch return error.OutOfMemory;
        }
        const len = self.fixedTupleLength(tuple_t) orelse return null;
        var elements: std.ArrayListUnmanaged(TypeId) = .empty;
        defer elements.deinit(self.gpa);
        for (0..@as(usize, @intCast(len))) |index| {
            const element_t = self.tupleElementType(tuple_t, index);
            if (element_t == types.Primitive.none) return null;
            try elements.append(self.gpa, element_t);
        }
        return try self.internTupleFromTypesWithMinRequired(
            elements.items,
            self.tupleRestMinRequiredCount(tuple_t),
            false,
        );
    }

    fn appendFiniteRestTupleBranch(
        self: *Checker,
        fixed: []const TypeId,
        fixed_min: usize,
        rest_t: TypeId,
        branches: *std.ArrayListUnmanaged(TypeId),
    ) CheckError!bool {
        const rest_len = self.restTupleMaxCount(rest_t) orelse return false;
        var elements: std.ArrayListUnmanaged(TypeId) = .empty;
        defer elements.deinit(self.gpa);
        try elements.appendSlice(self.gpa, fixed);
        for (0..rest_len) |index| {
            const element_t = self.tupleElementType(rest_t, index);
            if (element_t == types.Primitive.none) return false;
            try elements.append(self.gpa, element_t);
        }
        const min_required = fixed_min + self.tupleRestMinRequiredCount(rest_t);
        try branches.append(
            self.gpa,
            try self.internTupleFromTypesWithMinRequired(elements.items, min_required, false),
        );
        return true;
    }

    /// Normalize a callable's finite parameter list to the tuple (or union
    /// of tuples) accepted at its call boundary. This is the same shape
    /// TypeScript relates contravariantly for fixed parameters and tuple
    /// rests, and avoids collapsing a rest union to its number index.
    fn finiteSignatureArgsType(self: *Checker, sig: TypeId) CheckError!?TypeId {
        if (!self.interner.isSignature(sig)) return null;
        const params = self.interner.signatureParams(sig);
        if (!self.rest_signatures.contains(sig)) {
            return try self.internTupleFromTypesWithMinRequired(
                params,
                self.signatureMinRequiredArgs(sig, params),
                false,
            );
        }
        if (params.len == 0) return null;
        const fixed_count = params.len - 1;
        const fixed_min = @min(self.signatureMinRequiredArgs(sig, params), fixed_count);
        const rest_t = params[params.len - 1];
        if (rest_t >= self.interner.pool.typeCount()) return null;

        var branches: std.ArrayListUnmanaged(TypeId) = .empty;
        defer branches.deinit(self.gpa);
        if (self.interner.pool.flagsOf(rest_t).is_union) {
            for (self.interner.unionMembers(rest_t)) |member| {
                if (!try self.appendFiniteRestTupleBranch(
                    params[0..fixed_count],
                    fixed_min,
                    member,
                    &branches,
                )) return null;
            }
        } else if (!try self.appendFiniteRestTupleBranch(
            params[0..fixed_count],
            fixed_min,
            rest_t,
            &branches,
        )) {
            return null;
        }
        if (branches.items.len == 0) return null;
        if (branches.items.len == 1) return branches.items[0];
        return self.interner.internUnion(branches.items) catch return error.OutOfMemory;
    }

    fn internReadonlyArrayType(self: *Checker, element: TypeId) CheckError!TypeId {
        const length_id = self.string_interner.intern("length") catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{.{
            .name = length_id,
            .type = types.Primitive.number_t,
            .is_optional = false,
            .is_readonly = true,
            .is_method = false,
        }};
        const array_t = self.interner.internObjectTypeWithIndex(&members, types.Primitive.none, element) catch return error.OutOfMemory;
        try self.array_origin_types.put(self.gpa, array_t, {});
        try self.readonly_index_types.put(self.gpa, array_t, {});
        return array_t;
    }

    fn internNoInferType(self: *Checker, inner: TypeId) CheckError!TypeId {
        const marker = self.string_interner.intern("__home_no_infer") catch return error.OutOfMemory;
        const brand = self.interner.internFreshTypeParameterWithFlags(
            marker,
            types.Primitive.unknown,
            types.Primitive.none,
            .bivariant,
            false,
        ) catch return error.OutOfMemory;
        const members = [_]types.ObjectMember{.{
            .name = marker,
            .type = brand,
            .is_optional = false,
            .is_readonly = true,
            .is_method = false,
        }};
        const wrapper = self.interner.internObjectType(&members) catch return error.OutOfMemory;
        try self.no_infer_types.put(self.gpa, wrapper, inner);
        return wrapper;
    }

    fn noInferInnerType(self: *Checker, t: TypeId) ?TypeId {
        return self.no_infer_types.get(t);
    }

    fn inferFromArgument(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        arg_node: NodeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) !void {
        if (self.noInferInnerType(param_t) != null) return;
        const nested_array_inference_fixed = try self.seedRecursiveArrayInferenceFromNestedElements(param_t, arg_node, subs);
        _ = try self.inferFromArrayLiteralToTrailingMappedVariadic(param_t, arg_node, subs);
        if (param_t >= types.Primitive.first_dynamic and
            param_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(param_t).is_intersection)
        {
            if (self.interner.pool.payloadOf(param_t) >= self.interner.pool.intersection_payloads.items.len) return;
            for (self.interner.intersectionMembers(param_t)) |member| {
                try self.inferFromArgument(member, arg_t, arg_node, subs);
            }
            return;
        }
        if (param_t >= types.Primitive.first_dynamic and
            param_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(param_t).is_union and
            (self.hir.kindOf(arg_node) == .literal_string or
                self.hir.kindOf(arg_node) == .literal_number or
                self.hir.kindOf(arg_node) == .literal_bool or
                self.hir.kindOf(arg_node) == .template_literal))
        {
            const members = try self.gpa.dupe(TypeId, self.interner.unionMembers(param_t));
            defer self.gpa.free(members);
            for (members) |member| {
                if (member >= self.interner.pool.typeCount()) continue;
                const member_flags = self.interner.pool.flagsOf(member);
                if (member_flags.is_type_parameter and !member_flags.is_union and !member_flags.is_intersection) continue;
                try self.inferFromPair(member, arg_t, subs);
            }
            for (members) |member| {
                if (member >= self.interner.pool.typeCount()) continue;
                const member_flags = self.interner.pool.flagsOf(member);
                if (!(member_flags.is_type_parameter and !member_flags.is_union and !member_flags.is_intersection)) continue;
                try self.inferFromArgument(member, arg_t, arg_node, subs);
            }
            return;
        }
        if (param_t >= types.Primitive.first_dynamic and
            param_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(param_t).is_type_parameter and
            !self.interner.pool.flagsOf(param_t).is_union and
            !self.interner.pool.flagsOf(param_t).is_intersection)
        {
            if (subs.get(param_t)) |existing| {
                var literal_arg = self.literalizeForAsConst(arg_node, arg_t) catch arg_t;
                literal_arg = self.substituteType(literal_arg, subs) catch literal_arg;
                if (self.interner.typeParameterIsConst(param_t)) {
                    if (literal_arg == existing) return;
                    const merged = self.interner.internUnion(&.{ existing, literal_arg }) catch return error.OutOfMemory;
                    try subs.put(self.gpa, param_t, merged);
                    return;
                }
                if (self.engine.isAssignableTo(literal_arg, existing) catch false) return;
            } else {
                var prefer_literal = try self.typeParameterConstraintPrefersLiteralInference(param_t, subs);
                if (!prefer_literal) {
                    if (self.scalarTypeParameterConstraint(param_t)) |raw_constraint_t| {
                        const constraint_t = (try self.reduceDisplayedAliasInstance(raw_constraint_t)) orelse raw_constraint_t;
                        prefer_literal = self.typeIsKeyofLikeLiteralConstraint(constraint_t);
                    }
                }
                if (!prefer_literal) {
                    if (self.typeParameterConstraint(param_t)) |raw_constraint_t| {
                        const substituted_constraint_t = self.substituteType(raw_constraint_t, subs) catch raw_constraint_t;
                        const constraint_t = (try self.reduceDisplayedAliasInstance(substituted_constraint_t)) orelse substituted_constraint_t;
                        prefer_literal = constraint_t < self.interner.pool.typeCount() and
                            self.interner.pool.flagsOf(constraint_t).is_conditional and
                            self.propertyKeyLiteralUnionPart(constraint_t) != null;
                    }
                }
                if (self.interner.typeParameterIsConst(param_t) or prefer_literal) {
                    var inferred = self.literalizeForAsConst(arg_node, arg_t) catch arg_t;
                    inferred = self.substituteType(inferred, subs) catch inferred;
                    if (self.typeParameterConstraint(param_t)) |raw_constraint_t| {
                        const substituted_constraint_t = self.substituteType(raw_constraint_t, subs) catch raw_constraint_t;
                        const constraint_t = (try self.reduceDisplayedAliasInstance(substituted_constraint_t)) orelse substituted_constraint_t;
                        if (constraint_t != types.Primitive.none and
                            constraint_t != types.Primitive.unknown and
                            !((self.typeIsKeyofLikeLiteralConstraint(constraint_t) and (self.interner.pool.flagsOf(constraint_t).is_keyof or
                                try self.literalTypeAssignableToLiteralConstraint(inferred, constraint_t))) or
                                (self.engine.isAssignableTo(inferred, constraint_t) catch false) or
                                try self.literalSatisfiesRecursiveTemplatePathConstraint(raw_constraint_t, inferred, subs)))
                        {
                            return;
                        }
                    }
                    try subs.put(self.gpa, param_t, inferred);
                    return;
                }
                if (try self.inferNullishArrayLiteralFromAnyIndexedConstraint(param_t, arg_t, arg_node, subs)) return;
                if (self.scalarTypeParameterConstraint(param_t) orelse self.primitiveTypeParameterConstraint(param_t)) |raw_constraint_t| {
                    const substituted_constraint_t = self.substituteType(raw_constraint_t, subs) catch raw_constraint_t;
                    const constraint_t = (try self.reduceDisplayedAliasInstance(substituted_constraint_t)) orelse substituted_constraint_t;
                    const literal_ok = try self.literalTypeAssignableToLiteralConstraint(arg_t, constraint_t);
                    if (self.strictNullishInferenceExcludedByConstraint(arg_t, constraint_t) or
                        (!literal_ok and !(self.engine.isAssignableTo(arg_t, constraint_t) catch false)))
                    {
                        return;
                    }
                }
                if (self.strict_flags.strict_null_checks and
                    self.typeParameterConstraint(param_t) == null and
                    arg_node != hir_mod.none_node_id and
                    self.hir.kindOf(arg_node) == .array_literal and
                    hir_mod.arrayLiteralElements(self.hir, arg_node).len == 0)
                {
                    const never_array = self.interner.internArrayType(
                        self.string_interner,
                        types.Primitive.never,
                    ) catch return error.OutOfMemory;
                    try subs.put(self.gpa, param_t, never_array);
                    return;
                }
            }
        }
        if (param_t >= types.Primitive.first_dynamic and
            param_t < self.interner.pool.typeCount() and
            arg_t >= types.Primitive.first_dynamic and
            arg_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(param_t).is_union and
            self.interner.pool.flagsOf(arg_t).is_object_type)
        {
            for (self.interner.unionMembers(param_t)) |member| {
                if (member >= types.Primitive.first_dynamic and
                    member < self.interner.pool.typeCount() and
                    self.interner.pool.flagsOf(member).is_object_type and
                    (self.engine.isAssignableTo(arg_t, member) catch false))
                {
                    try self.inferFromPair(member, arg_t, subs);
                    return;
                }
            }
        }
        if (self.hir.kindOf(arg_node) == .object_literal and
            param_t >= types.Primitive.first_dynamic and
            param_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(param_t).is_union)
        {
            for (self.interner.unionMembers(param_t)) |member| {
                if (try self.objectLiteralMayMatchTarget(arg_node, member)) {
                    try self.inferFromPair(member, arg_t, subs);
                    return;
                }
            }
        }
        if (param_t >= types.Primitive.first_dynamic and
            param_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(param_t).is_mapped and
            arg_t >= types.Primitive.first_dynamic and
            arg_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(arg_t).is_object_type)
        {
            if (try self.inferFromSecondaryMappedArgument(param_t, arg_t, subs)) return;
        }
        if (self.hir.kindOf(arg_node) == .object_literal and
            param_t >= types.Primitive.first_dynamic and
            param_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(param_t).is_mapped)
        {
            if (try self.inferFromReverseMappedObjectLiteral(param_t, arg_t, subs)) return;
            if (self.limitedReverseMappedSourceTypeParameter(param_t)) |source_tp| {
                const fresh_arg_t = try self.freshObjectLiteralInferenceType(arg_node, arg_t);
                try self.inferFromPair(source_tp, fresh_arg_t, subs);
                return;
            }
        }
        if (self.hir.kindOf(arg_node) == .object_literal and
            param_t >= types.Primitive.first_dynamic and
            param_t < self.interner.pool.typeCount() and
            arg_t >= types.Primitive.first_dynamic and
            arg_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(param_t).is_object_type and
            self.interner.pool.flagsOf(arg_t).is_object_type)
        {
            try self.inferFromObjectLiteralArgument(param_t, arg_t, arg_node, subs);
            return;
        }
        if (try self.inferFromConstructSignatureArgument(param_t, arg_t, subs)) return;
        try self.inferStableIndexedElementArgument(param_t, arg_t, arg_node, subs);
        if (nested_array_inference_fixed) return;
        try self.inferFromPair(param_t, arg_t, subs);
    }

    fn inferFromSecondaryMappedArgument(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        if (arg_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(arg_t).is_object_type) return false;
        const source_t = self.homomorphicMappedTypeParameter(param_t) orelse
            (self.limitedReverseMappedSourceTypeParameter(param_t) orelse
                (self.builtinMappedSourceType(param_t) orelse return false));
        if (source_t < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(source_t).is_type_parameter and
            !subs.contains(source_t))
        {
            return false;
        }

        const mapped = self.interner.mappedPayload(param_t);
        if (mapped.constraint >= self.interner.pool.typeCount()) return true;
        const constraint_flags = self.interner.pool.flagsOf(mapped.constraint);
        if (!constraint_flags.is_type_parameter or mapped.constraint == source_t) return true;

        var key_types: std.ArrayListUnmanaged(TypeId) = .empty;
        defer key_types.deinit(self.gpa);
        for (self.interner.objectMembers(arg_t)) |member| {
            const key_t = self.interner.internStringLiteral(member.name) catch return error.OutOfMemory;
            try key_types.append(self.gpa, key_t);
        }
        const inferred_key_t = if (key_types.items.len == 0)
            types.Primitive.never
        else if (key_types.items.len == 1)
            key_types.items[0]
        else
            self.interner.internUnion(key_types.items) catch return error.OutOfMemory;
        if (inferred_key_t == types.Primitive.never) {
            try subs.put(self.gpa, mapped.constraint, inferred_key_t);
            return true;
        }
        try self.inferFromPair(mapped.constraint, inferred_key_t, subs);
        return true;
    }

    fn seedRecursiveArrayInferenceFromNestedElements(
        self: *Checker,
        param_t: TypeId,
        arg_node: NodeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        if (arg_node == hir_mod.none_node_id or self.hir.kindOf(arg_node) != .array_literal) return false;
        if (param_t >= self.interner.pool.typeCount()) return false;
        const param_elem_t = self.interner.objectNumberIndex(param_t);
        if (param_elem_t >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(param_elem_t).is_union)
        {
            return false;
        }

        var direct_type_param = types.Primitive.none;
        var nested_target = types.Primitive.none;
        for (self.interner.unionMembers(param_elem_t)) |member| {
            if (member >= self.interner.pool.typeCount()) continue;
            const flags = self.interner.pool.flagsOf(member);
            if (flags.is_type_parameter and !flags.is_union and !flags.is_intersection) {
                if (direct_type_param != types.Primitive.none) return false;
                direct_type_param = member;
            }
        }
        if (direct_type_param == types.Primitive.none) return false;
        for (self.interner.unionMembers(param_elem_t)) |member| {
            if (member == direct_type_param or member >= self.interner.pool.typeCount()) continue;
            if (!self.interner.pool.flagsOf(member).is_object_type) continue;
            if (self.interner.objectNumberIndex(member) == types.Primitive.none) continue;
            if (!self.containsFreeTypeParameter(member)) continue;
            if (nested_target != types.Primitive.none) return false;
            nested_target = member;
        }
        if (nested_target == types.Primitive.none) return false;

        var nested_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer nested_subs.deinit(self.gpa);
        var direct_candidates: std.ArrayListUnmanaged(TypeId) = .empty;
        defer direct_candidates.deinit(self.gpa);
        for (hir_mod.arrayLiteralElements(self.hir, arg_node)) |element| {
            if (element == hir_mod.none_node_id or self.hir.kindOf(element) == .spread) continue;
            var element_t = self.hir.typeOf(element);
            if (element_t == types.Primitive.none) element_t = try self.checkExpression(element);
            if (self.hir.kindOf(element) == .array_literal) {
                try self.inferFromPair(nested_target, element_t, &nested_subs);
                continue;
            }
            const candidate = self.widenForInference(element_t);
            var duplicate = false;
            for (direct_candidates.items) |existing| {
                if (existing == candidate) {
                    duplicate = true;
                    break;
                }
            }
            if (!duplicate) try direct_candidates.append(self.gpa, candidate);
        }

        var nested_candidate = nested_subs.get(direct_type_param) orelse return false;
        if (direct_candidates.items.len > 1) {
            const direct_union = self.interner.internUnion(direct_candidates.items) catch return error.OutOfMemory;
            if (!(self.engine.isAssignableTo(direct_union, nested_candidate) catch false)) {
                nested_candidate = self.interner.internUnion(&.{ nested_candidate, direct_union }) catch return error.OutOfMemory;
            }
        }
        try subs.put(self.gpa, direct_type_param, nested_candidate);
        return true;
    }

    fn inferFromObjectLiteralArgument(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        arg_node: NodeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        var param_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer param_members.deinit(self.gpa);
        try param_members.appendSlice(self.gpa, self.interner.objectMembers(param_t));

        // Mirrors tsgo's intra-expression inference sites: members whose
        // contextual parameter types still reference an unfixed type
        // parameter wait until stable members have contributed candidates.
        for (0..2) |phase| {
            for (param_members.items) |param_member| {
                const value_node = self.findObjectLiteralPropValue(arg_node, param_member.name) orelse continue;
                const defer_contextual = self.contextualFunctionParametersContainFreeType(value_node, param_member.type);
                if ((phase == 0) == defer_contextual) continue;

                const collect_const_candidate = param_member.type < self.interner.pool.typeCount() and
                    self.interner.pool.flagsOf(param_member.type).is_type_parameter and
                    self.interner.typeParameterIsConst(param_member.type) and
                    subs.contains(param_member.type);
                const substituted_param_t = if (collect_const_candidate)
                    param_member.type
                else
                    self.substituteType(param_member.type, subs) catch param_member.type;
                const has_unfixed = self.typeContainsUnfixedInferenceParameter(param_member.type, subs, 0);
                const mapped_or_conditional = try self.signatureContainsMappedOrConditionalType(param_member.type);
                const has_predicate = if (self.firstSignatureType(param_member.type)) |member_sig|
                    self.signature_predicates.contains(member_sig)
                else
                    false;
                const relowered_param_t = if (!collect_const_candidate and
                    !has_predicate and
                    (!has_unfixed or mapped_or_conditional))
                    try self.relowerObjectMemberTypeWithInferences(param_member, subs)
                else
                    null;
                const effective_param_t = relowered_param_t orelse substituted_param_t;
                var source_t = self.interner.objectMember(arg_t, param_member.name) orelse
                    if (self.hir.typeOf(value_node) != types.Primitive.none)
                        self.hir.typeOf(value_node)
                    else
                        try self.checkExpression(value_node);
                if (self.functionExpressionHasContextSensitiveParameters(value_node) and
                    !self.signatureParametersContainFreeType(effective_param_t))
                {
                    if (self.firstSignatureType(effective_param_t)) |target_sig| {
                        try self.checkFunctionWithContextualSignatureMode(value_node, target_sig, false, &source_t);
                    }
                }
                try self.inferFromArgument(effective_param_t, source_t, value_node, subs);
            }
        }

        for (hir_mod.objectLiteralProps(self.hir, arg_node)) |prop| {
            if (self.hir.kindOf(prop) != .spread) continue;
            const spread_expr = hir_mod.spreadOf(self.hir, prop).expression;
            if (spread_expr == hir_mod.none_node_id or self.hir.kindOf(spread_expr) != .object_literal) continue;
            const spread_t = if (self.hir.typeOf(spread_expr) != types.Primitive.none)
                self.hir.typeOf(spread_expr)
            else
                try self.checkExpression(spread_expr);
            if (spread_t >= self.interner.pool.typeCount() or
                !self.interner.pool.flagsOf(spread_t).is_object_type)
            {
                continue;
            }
            try self.inferFromObjectLiteralArgument(param_t, spread_t, spread_expr, subs);
        }
    }

    fn signatureParametersContainFreeType(self: *Checker, t: TypeId) bool {
        const sig = self.firstSignatureType(t) orelse return false;
        for (self.interner.signatureParams(sig)) |param| {
            if (self.containsFreeTypeParameter(param)) return true;
        }
        return false;
    }

    fn typeContainsUnfixedInferenceParameter(
        self: *Checker,
        t: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
        depth: u8,
    ) bool {
        if (depth >= 24 or t >= self.interner.pool.typeCount()) return false;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.typeContainsUnfixedInferenceParameter(member, subs, depth + 1)) return true;
            }
            return false;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.typeContainsUnfixedInferenceParameter(member, subs, depth + 1)) return true;
            }
            return false;
        }
        if (flags.is_type_parameter) {
            if (subs.contains(t)) return false;
            const payload_idx = self.interner.pool.payloadOf(t);
            if (payload_idx >= self.interner.pool.type_parameter_payloads.items.len) return true;
            const name = self.interner.pool.type_parameter_payloads.items[payload_idx].name;
            var it = subs.keyIterator();
            while (it.next()) |candidate| {
                if (candidate.* >= self.interner.pool.typeCount()) continue;
                const candidate_flags = self.interner.pool.flagsOf(candidate.*);
                if (!candidate_flags.is_type_parameter or
                    candidate_flags.is_union or
                    candidate_flags.is_intersection)
                {
                    continue;
                }
                const candidate_payload_idx = self.interner.pool.payloadOf(candidate.*);
                if (candidate_payload_idx >= self.interner.pool.type_parameter_payloads.items.len) continue;
                if (self.interner.pool.type_parameter_payloads.items[candidate_payload_idx].name == name) return false;
            }
            return true;
        }
        if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |param| {
                if (self.typeContainsUnfixedInferenceParameter(param, subs, depth + 1)) return true;
            }
            const return_t = self.interner.signatureReturn(t) orelse return false;
            return self.typeContainsUnfixedInferenceParameter(return_t, subs, depth + 1);
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |member| {
                if (self.typeContainsUnfixedInferenceParameter(member.type, subs, depth + 1)) return true;
            }
            const indexes = [_]TypeId{
                self.interner.objectStringIndex(t),
                self.interner.objectNumberIndex(t),
                self.interner.objectSymbolIndex(t),
            };
            for (indexes) |index_t| {
                if (index_t != types.Primitive.none and
                    self.typeContainsUnfixedInferenceParameter(index_t, subs, depth + 1))
                {
                    return true;
                }
            }
            return false;
        }
        if (flags.is_keyof) {
            const operand = self.directKeyofOperand(t) orelse return false;
            return self.typeContainsUnfixedInferenceParameter(operand, subs, depth + 1);
        }
        if (flags.is_indexed_access) {
            const indexed = self.indexedAccessPayloadOrNull(t) orelse return false;
            return self.typeContainsUnfixedInferenceParameter(indexed.object, subs, depth + 1) or
                self.typeContainsUnfixedInferenceParameter(indexed.index, subs, depth + 1);
        }
        if (flags.is_mapped) {
            const mapped = self.interner.mappedPayload(t);
            return self.typeContainsUnfixedInferenceParameter(mapped.constraint, subs, depth + 1) or
                self.typeContainsUnfixedInferenceParameter(mapped.template, subs, depth + 1);
        }
        if (flags.is_conditional) {
            const conditional = self.interner.conditionalPayload(t);
            return self.typeContainsUnfixedInferenceParameter(conditional.check_type, subs, depth + 1) or
                self.typeContainsUnfixedInferenceParameter(conditional.extends_type, subs, depth + 1) or
                self.typeContainsUnfixedInferenceParameter(conditional.true_branch, subs, depth + 1) or
                self.typeContainsUnfixedInferenceParameter(conditional.false_branch, subs, depth + 1);
        }
        return false;
    }

    fn relowerObjectMemberTypeWithInferences(
        self: *Checker,
        member: types.ObjectMember,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!?TypeId {
        if (member.decl_node == hir_mod.none_node_id or subs.count() == 0) return null;
        const type_node = switch (self.hir.kindOf(member.decl_node)) {
            .interface_member => hir_mod.interfaceMemberOf(self.hir, member.decl_node).type_node,
            .object_property => hir_mod.objectPropertyOf(self.hir, member.decl_node).type_annotation,
            else => return null,
        };
        if (type_node == hir_mod.none_node_id) return null;

        try self.pushNarrowScope();
        defer self.popNarrowScope();
        var it = subs.iterator();
        while (it.next()) |entry| {
            const param_t = entry.key_ptr.*;
            if (param_t >= self.interner.pool.typeCount()) continue;
            const flags = self.interner.pool.flagsOf(param_t);
            if (!flags.is_type_parameter or flags.is_union or flags.is_intersection) continue;
            const payload_idx = self.interner.pool.payloadOf(param_t);
            if (payload_idx >= self.interner.pool.type_parameter_payloads.items.len) continue;
            const payload = self.interner.pool.type_parameter_payloads.items[payload_idx];
            try self.recordNarrow(payload.name, entry.value_ptr.*);
        }
        return try self.lowererLowerWithTypeParams(type_node);
    }

    fn relowerSignatureObjectMembersWithInferences(
        self: *Checker,
        sig: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!TypeId {
        if (!self.interner.isSignature(sig) or subs.count() == 0) return sig;
        const old_params = self.interner.signatureParams(sig);
        var params: std.ArrayListUnmanaged(TypeId) = .empty;
        defer params.deinit(self.gpa);
        var changed = false;
        for (old_params) |param| {
            const refreshed = try self.relowerObjectTypeMembersWithInferences(param, subs);
            if (refreshed != param) changed = true;
            try params.append(self.gpa, refreshed);
        }
        if (!changed) return sig;

        const return_t = self.interner.signatureReturn(sig) orelse types.Primitive.void_t;
        const payload_idx = self.interner.pool.payloadOf(sig);
        if (payload_idx >= self.interner.pool.signature_payloads.items.len) return sig;
        const payload = self.interner.pool.signature_payloads.items[payload_idx];
        const this_t = self.signatureThisParam(sig);
        const refreshed_sig = if (this_t) |receiver|
            self.interner.internSignatureWithThisType(
                params.items,
                return_t,
                payload.is_construct,
                payload.is_abstract_construct,
                receiver,
            ) catch return error.OutOfMemory
        else
            self.interner.internSignatureWithAbstract(
                params.items,
                return_t,
                payload.is_construct,
                payload.is_abstract_construct,
            ) catch return error.OutOfMemory;
        try self.copySignatureParamNames(refreshed_sig, sig);
        try self.copySignatureNullishArrayDefaults(refreshed_sig, sig);
        if (self.rest_signatures.contains(sig)) try self.rest_signatures.put(self.gpa, refreshed_sig, {});
        if (self.signature_min_args.get(sig)) |min_required| {
            try self.signature_min_args.put(self.gpa, refreshed_sig, min_required);
        }
        if (this_t) |receiver| try self.signature_this_params.put(self.gpa, refreshed_sig, receiver);
        return refreshed_sig;
    }

    fn relowerObjectTypeMembersWithInferences(
        self: *Checker,
        t: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!TypeId {
        if (t >= self.interner.pool.typeCount()) return t;
        const flags = self.interner.pool.flagsOf(t);
        if (!flags.is_object_type or
            flags.is_union or
            flags.is_intersection or
            flags.is_type_parameter or
            flags.is_signature or
            flags.is_keyof or
            flags.is_indexed_access or
            flags.is_conditional or
            flags.is_mapped)
        {
            return t;
        }

        const old_members = self.interner.objectMembers(t);
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        var changed = false;
        for (old_members) |member| {
            var refreshed = member;
            if (try self.signatureContainsMappedOrConditionalType(member.type)) {
                if (try self.relowerObjectMemberTypeWithInferences(member, subs)) |member_t| {
                    refreshed.type = member_t;
                    if (member_t != member.type) changed = true;
                }
            }
            try members.append(self.gpa, refreshed);
        }
        if (!changed) return t;

        const string_idx = self.interner.objectStringIndex(t);
        const number_idx = self.interner.objectNumberIndex(t);
        const symbol_idx = self.interner.objectSymbolIndex(t);
        const refreshed = if (string_idx == types.Primitive.none and
            number_idx == types.Primitive.none and
            symbol_idx == types.Primitive.none)
            self.interner.internObjectType(members.items) catch return error.OutOfMemory
        else
            self.interner.internObjectTypeWithIndexAndSymbol(
                members.items,
                string_idx,
                number_idx,
                symbol_idx,
            ) catch return error.OutOfMemory;
        if (self.alias_display_names.get(t)) |display| {
            try self.alias_display_names.put(self.gpa, refreshed, display);
        }
        if (self.alias_type_args.get(t)) |args| {
            try self.alias_type_args.put(self.gpa, refreshed, args);
        }
        return refreshed;
    }

    fn signatureContainsMappedOrConditionalType(self: *Checker, t: TypeId) CheckError!bool {
        const sig = self.firstSignatureType(t) orelse return false;
        for (self.interner.signatureParams(sig)) |param| {
            if (try self.typeContainsMappedType(param)) return true;
            if (try self.typeContainsConditionalType(param)) return true;
        }
        const return_t = self.interner.signatureReturn(sig) orelse return false;
        return (try self.typeContainsMappedType(return_t)) or
            (try self.typeContainsConditionalType(return_t));
    }

    fn contextualFunctionParametersContainFreeType(
        self: *Checker,
        value_node: NodeId,
        target_t: TypeId,
    ) bool {
        if (!self.functionExpressionHasContextSensitiveParameters(value_node)) return false;
        const target_sig = self.firstSignatureType(target_t) orelse return false;
        for (self.interner.signatureParams(target_sig)) |param| {
            if (self.containsFreeTypeParameter(param)) return true;
        }
        return false;
    }

    fn inferFromArrayLiteralToTrailingMappedVariadic(
        self: *Checker,
        param_t: TypeId,
        arg_node: NodeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        if (arg_node == hir_mod.none_node_id or self.hir.kindOf(arg_node) != .array_literal) return false;
        const mapped_rest_t = self.tuple_trailing_variadic_types.get(param_t) orelse return false;
        if (mapped_rest_t >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(mapped_rest_t).is_mapped)
        {
            return false;
        }
        const mapped = self.interner.mappedPayload(mapped_rest_t);
        const indexed = self.mappedTemplateIndexedAccess(mapped.template) orelse return false;
        const elements = hir_mod.arrayLiteralElements(self.hir, arg_node);
        const prefix = self.tupleFixedPrefixCount(param_t);
        if (elements.len < prefix) return false;

        var relative_index: usize = 0;
        for (elements[prefix..]) |element| {
            if (element == hir_mod.none_node_id or self.hir.kindOf(element) == .spread) return false;
            const key = try self.numericStringIdForIndex(relative_index);
            const key_t = self.interner.internStringLiteral(key) catch return error.OutOfMemory;
            var key_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
            defer key_subs.deinit(self.gpa);
            try key_subs.put(self.gpa, indexed.key_tp, key_t);
            const member_target = try self.substituteType(mapped.template, &key_subs);
            const member_source = if (self.hir.typeOf(element) != types.Primitive.none)
                self.hir.typeOf(element)
            else
                try self.checkExpression(element);
            const target_index = self.interner.objectNumberIndex(member_target);
            const source_index = self.interner.objectNumberIndex(member_source);
            if (target_index != types.Primitive.none and source_index != types.Primitive.none) {
                try self.mergeIndexedAccessInference(indexed.object_tp, key, source_index, subs);
            } else {
                try self.inferFromPair(member_target, member_source, subs);
            }
            relative_index += 1;
        }

        const inferred = subs.get(indexed.object_tp) orelse return false;
        if (inferred >= self.interner.pool.typeCount() or
            !self.interner.pool.flagsOf(inferred).is_object_type)
        {
            return false;
        }
        var inferred_elements: std.ArrayListUnmanaged(TypeId) = .empty;
        defer inferred_elements.deinit(self.gpa);
        for (0..relative_index) |i| {
            const key = try self.numericStringIdForIndex(i);
            const element_t = self.interner.objectMember(inferred, key) orelse return false;
            try inferred_elements.append(self.gpa, element_t);
        }
        const inferred_tuple = try self.internTupleFromTypes(inferred_elements.items, false);
        try subs.put(self.gpa, indexed.object_tp, inferred_tuple);
        return true;
    }

    fn inferFromConditionalTarget(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        if (param_t >= self.interner.pool.typeCount()) return false;
        const c = self.interner.conditionalPayloadOrNull(param_t) orelse return false;
        var inferred = false;
        if (try self.conditionalInferenceBranchMayMatchArg(c.true_branch, arg_t, 0)) {
            try self.inferFromPair(c.true_branch, arg_t, subs);
            inferred = true;
        }
        if (try self.conditionalInferenceBranchMayMatchArg(c.false_branch, arg_t, 0)) {
            try self.inferFromPair(c.false_branch, arg_t, subs);
            inferred = true;
        }
        return inferred;
    }

    fn conditionalInferenceBranchMayMatchArg(self: *Checker, branch_t: TypeId, arg_t: TypeId, depth: usize) CheckError!bool {
        if (depth > 8) return false;
        if (branch_t >= self.interner.pool.typeCount() or arg_t >= self.interner.pool.typeCount()) return true;
        const branch_flags = self.interner.pool.flagsOf(branch_t);
        if (branch_flags.is_union) {
            for (self.interner.unionMembers(branch_t)) |member| {
                if (try self.conditionalInferenceBranchMayMatchArg(member, arg_t, depth + 1)) return true;
            }
            return false;
        }
        if (branch_flags.is_intersection) {
            for (self.interner.intersectionMembers(branch_t)) |member| {
                if (!try self.conditionalInferenceBranchMayMatchArg(member, arg_t, depth + 1)) return false;
            }
            return true;
        }
        if (branch_flags.is_conditional) {
            const nested = self.interner.conditionalPayload(branch_t);
            return (try self.conditionalInferenceBranchMayMatchArg(nested.true_branch, arg_t, depth + 1)) or
                (try self.conditionalInferenceBranchMayMatchArg(nested.false_branch, arg_t, depth + 1));
        }
        if (!branch_flags.is_object_type) return true;
        if (!self.interner.pool.flagsOf(arg_t).is_object_type) return false;
        const branch_members = self.interner.objectMembers(branch_t);
        var saw_required = false;
        for (branch_members) |member| {
            if (member.is_optional) continue;
            saw_required = true;
            if (self.interner.objectMember(arg_t, member.name) == null) return false;
        }
        return saw_required or
            self.interner.objectStringIndex(branch_t) != types.Primitive.none or
            self.interner.objectNumberIndex(branch_t) != types.Primitive.none or
            self.interner.objectSymbolIndex(branch_t) != types.Primitive.none;
    }

    fn inferFromReverseMappedObjectLiteral(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        if (param_t >= self.interner.pool.typeCount() or arg_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(param_t).is_mapped or !self.interner.pool.flagsOf(arg_t).is_object_type) return false;
        const m = self.interner.mappedPayload(param_t);
        const indexed = self.mappedTemplateIndexedAccess(m.template) orelse return false;
        const constraint_operand = self.directKeyofOperand(m.constraint) orelse return false;
        if (constraint_operand != indexed.object_tp) {
            if (constraint_operand >= self.interner.pool.typeCount() or
                indexed.object_tp >= self.interner.pool.typeCount() or
                !self.interner.pool.flagsOf(constraint_operand).is_type_parameter or
                !self.interner.pool.flagsOf(indexed.object_tp).is_type_parameter)
            {
                return false;
            }
        }
        var saw_member = false;
        const source_is_array_like = self.isTupleShapedTarget(arg_t) or self.objectTypeIsArrayLikeContainer(arg_t);
        const arg_members = try self.gpa.dupe(types.ObjectMember, self.interner.objectMembers(arg_t));
        defer self.gpa.free(arg_members);
        for (arg_members) |arg_member| {
            if (source_is_array_like and !self.isNumericStringId(arg_member.name)) continue;
            const key_lit = self.interner.internStringLiteral(arg_member.name) catch return error.OutOfMemory;
            var key_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
            defer key_subs.deinit(self.gpa);
            try key_subs.put(self.gpa, indexed.key_tp, key_lit);
            const member_target = self.substituteType(m.template, &key_subs) catch m.template;
            try self.inferFromPair(member_target, arg_member.type, subs);
            if (subs.get(indexed.object_tp)) |source_obj| {
                if (source_obj < self.interner.pool.typeCount() and
                    self.interner.pool.flagsOf(source_obj).is_object_type and
                    self.interner.objectMemberInfo(source_obj, arg_member.name) != null)
                {
                    saw_member = true;
                    continue;
                }
            }
            try self.mergeIndexedAccessInference(indexed.object_tp, arg_member.name, types.Primitive.unknown, subs);
            saw_member = true;
        }
        if (source_is_array_like) {
            const arg_number_index = self.interner.objectNumberIndex(arg_t);
            if (arg_number_index != types.Primitive.none) {
                var key_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                defer key_subs.deinit(self.gpa);
                try key_subs.put(self.gpa, indexed.key_tp, types.Primitive.number_t);
                const number_target = self.substituteType(m.template, &key_subs) catch m.template;
                try self.inferFromPair(number_target, arg_number_index, subs);
                var inferred_number_index = false;
                if (subs.get(indexed.object_tp)) |source_obj| {
                    if (source_obj < self.interner.pool.typeCount() and
                        self.interner.pool.flagsOf(source_obj).is_object_type and
                        self.interner.objectNumberIndex(source_obj) != types.Primitive.none)
                    {
                        saw_member = true;
                        inferred_number_index = true;
                    }
                }
                if (!inferred_number_index) {
                    try self.mergeNumberIndexInference(indexed.object_tp, types.Primitive.unknown, subs);
                    saw_member = true;
                }
            }
        }
        if (constraint_operand != indexed.object_tp) {
            if (subs.get(indexed.object_tp)) |source_obj| {
                try subs.put(self.gpa, constraint_operand, source_obj);
            }
        }
        return saw_member;
    }

    fn inferNullishArrayLiteralFromAnyIndexedConstraint(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        arg_node: NodeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        if (self.strict_flags.strict_null_checks) return false;
        if (arg_node == hir_mod.none_node_id or self.hir.kindOf(arg_node) != .array_literal) return false;
        if (arg_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(arg_t).is_object_type) return false;
        const arg_elem_t = self.interner.objectNumberIndex(arg_t);
        if (arg_elem_t == types.Primitive.none or !self.typeIsNullishOnly(arg_elem_t)) return false;
        const raw_constraint_t = self.typeParameterConstraint(param_t) orelse return false;
        const constraint_t = self.substituteType(raw_constraint_t, subs) catch raw_constraint_t;
        if (constraint_t >= self.interner.pool.typeCount()) return false;
        if (!self.interner.pool.flagsOf(constraint_t).is_object_type) return false;
        if (self.interner.objectNumberIndex(constraint_t) != types.Primitive.any) return false;
        try subs.put(self.gpa, param_t, constraint_t);
        return true;
    }

    fn inferStableIndexedElementArgument(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        arg_node: NodeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        if (arg_node != hir_mod.none_node_id and self.hir.kindOf(arg_node) == .array_literal) return;
        const pool = &self.interner.pool;
        if (param_t < types.Primitive.first_dynamic or arg_t < types.Primitive.first_dynamic) return;
        if (param_t >= pool.typeCount() or arg_t >= pool.typeCount()) return;
        if (!pool.flagsOf(param_t).is_object_type or !pool.flagsOf(arg_t).is_object_type) return;
        const p_num = self.interner.objectNumberIndex(param_t);
        const a_num = self.interner.objectNumberIndex(arg_t);
        if (p_num == types.Primitive.none or a_num == types.Primitive.none) return;
        if (p_num >= pool.typeCount() or !pool.flagsOf(p_num).is_type_parameter) return;
        if (self.scalarTypeParameterConstraint(p_num)) |raw_constraint_t| {
            const substituted_constraint_t = self.substituteType(raw_constraint_t, subs) catch raw_constraint_t;
            const constraint_t = (try self.reduceDisplayedAliasInstance(substituted_constraint_t)) orelse substituted_constraint_t;
            const literal_ok = try self.literalTypeAssignableToLiteralConstraint(a_num, constraint_t);
            if (!literal_ok and !(self.engine.isAssignableTo(a_num, constraint_t) catch false)) return;
        }
        if (subs.get(p_num)) |existing| {
            if (existing == a_num) return;
            if (self.engine.isAssignableTo(a_num, existing) catch false) return;
            if ((self.engine.isAssignableTo(existing, a_num) catch false) and
                !(self.engine.isAssignableTo(a_num, existing) catch false))
            {
                try subs.put(self.gpa, p_num, a_num);
            }
            return;
        }
        try subs.put(self.gpa, p_num, a_num);
    }

    fn freshObjectLiteralInferenceType(self: *Checker, arg_node: NodeId, fallback: TypeId) CheckError!TypeId {
        if (arg_node == hir_mod.none_node_id or self.hir.kindOf(arg_node) != .object_literal) return fallback;
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        for (hir_mod.objectLiteralProps(self.hir, arg_node)) |p| {
            if (self.hir.kindOf(p) != .object_property) continue;
            const op = hir_mod.objectPropertyOf(self.hir, p);
            if (op.value == hir_mod.none_node_id) continue;
            const name = self.propertyNameFromKeyNode(op.key) orelse continue;
            const value_t = if (self.hir.typeOf(op.value) != types.Primitive.none)
                self.hir.typeOf(op.value)
            else
                try self.checkExpression(op.value);
            const fresh_t = self.literalizeForAsConst(op.value, value_t) catch value_t;
            try members.append(self.gpa, .{
                .name = name,
                .type = fresh_t,
                .is_optional = false,
                .is_readonly = false,
                .is_method = false,
            });
        }
        if (members.items.len == 0) return fallback;
        return self.interner.internObjectType(members.items) catch return error.OutOfMemory;
    }

    fn inferCallSubstitutions(
        self: *Checker,
        sig: TypeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) !void {
        if (!self.interner.isSignature(sig)) return;
        const borrowed_param_ts = self.interner.signatureParams(sig);
        const param_ts = try self.gpa.dupe(TypeId, borrowed_param_ts);
        defer self.gpa.free(param_ts);
        if (self.rest_signatures.contains(sig) and param_ts.len > 0) {
            const fixed_count: usize = param_ts.len - 1;
            const n = @min(fixed_count, arg_types.len);
            for (0..n) |i| {
                // ÃÂÃÂ§4.A.X TS 4.0 ÃÂ¢ÃÂÃÂ signature-typed params still need
                // inference so a bare rest type-param `T extends any[]`
                // in `(...args: T) => R` binds T to the argument
                // signature's positional params as a tuple (handled
                // via inferRestTupleFromSignatureParams inside
                // inferFromPair). Previously this branch skipped
                // signature-typed params entirely, losing the higher-
                // order rest-tuple inference.
                const param_t = param_ts[i];
                const arg_t = arg_types[i];
                if (param_t >= self.interner.pool.typeCount() or arg_t >= self.interner.pool.typeCount()) continue;
                if (self.interner.pool.flagsOf(param_t).is_signature) {
                    if (self.interner.pool.flagsOf(arg_t).is_signature) {
                        try self.inferFromPair(param_ts[i], arg_types[i], subs);
                    } else if (self.signatureIsConstruct(param_t)) {
                        _ = try self.inferFromConstructSignatureArgument(param_t, arg_t, subs);
                    } else {
                        _ = try self.inferFromOverloadedCallableArgument(param_t, arg_t, subs);
                    }
                    continue;
                }
                try self.inferFromArgument(param_t, arg_t, args[i], subs);
            }
            const rest_arr_t = param_ts[param_ts.len - 1];
            if (rest_arr_t < self.interner.pool.typeCount() and self.interner.pool.flagsOf(rest_arr_t).is_type_parameter) {
                return;
            }
            const rest_elem_t = self.interner.objectNumberIndex(rest_arr_t);
            const rest_target_t = if (rest_elem_t != types.Primitive.none) rest_elem_t else rest_arr_t;
            if (rest_target_t < self.interner.pool.typeCount()) {
                var j: usize = fixed_count;
                while (j < arg_types.len) : (j += 1) {
                    var candidate_t = arg_types[j];
                    if (self.hir.kindOf(args[j]) == .spread) {
                        candidate_t = try self.iterableElementType(candidate_t);
                    }
                    try self.inferFromArgument(rest_target_t, candidate_t, args[j], subs);
                }
            }
        } else {
            const n = @min(param_ts.len, arg_types.len);
            for (0..n) |i| {
                // ÃÂÃÂ§4.A.X TS 4.0 ÃÂ¢ÃÂÃÂ signature-vs-signature inference for
                // variadic rest type-params. See the rest-signature
                // branch above for the rationale.
                const param_t = param_ts[i];
                const arg_t = arg_types[i];
                if (param_t >= self.interner.pool.typeCount() or arg_t >= self.interner.pool.typeCount()) continue;
                if (self.interner.pool.flagsOf(param_t).is_signature) {
                    if (self.interner.pool.flagsOf(arg_t).is_signature) {
                        try self.inferFromPair(param_t, arg_t, subs);
                    } else if (self.signatureIsConstruct(param_t)) {
                        _ = try self.inferFromConstructSignatureArgument(param_t, arg_t, subs);
                    } else {
                        _ = try self.inferFromOverloadedCallableArgument(param_t, arg_t, subs);
                    }
                    continue;
                }
                try self.inferFromArgument(param_t, arg_t, args[i], subs);
            }
        }
        try self.inferDescriptorLikeReturnTypeParameter(sig, arg_types, subs);
    }

    fn inferFromOverloadedCallableArgument(
        self: *Checker,
        param_t: TypeId,
        arg_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!bool {
        var source_sigs: std.ArrayListUnmanaged(TypeId) = .empty;
        defer source_sigs.deinit(self.gpa);
        try self.collectCallSignatures(arg_t, &source_sigs);
        if (source_sigs.items.len <= 1) return false;
        try self.inferFromPair(param_t, source_sigs.items[source_sigs.items.len - 1], subs);
        return true;
    }

    fn inferDescriptorLikeReturnTypeParameter(
        self: *Checker,
        sig: TypeId,
        arg_types: []const TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!void {
        const ret_t = self.interner.signatureReturn(sig) orelse return;
        const target_tp = self.firstUnboundFreeTypeParameter(ret_t, subs) orelse return;
        for (arg_types) |arg_t| {
            if (try self.computedDescriptorMapType(arg_t)) |computed_t| {
                try subs.put(self.gpa, target_tp, computed_t);
                return;
            }
        }
        for (arg_types) |arg_t| {
            if (try self.descriptorLikeMapType(arg_t)) |map_t| {
                try subs.put(self.gpa, target_tp, map_t);
                return;
            }
        }
    }

    fn firstUnboundFreeTypeParameter(
        self: *Checker,
        t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) ?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |member| {
                if (self.firstUnboundFreeTypeParameter(member, subs)) |tp| return tp;
            }
            return null;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |member| {
                if (self.firstUnboundFreeTypeParameter(member, subs)) |tp| return tp;
            }
            return null;
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |member| {
                if (self.firstUnboundFreeTypeParameter(member.type, subs)) |tp| return tp;
            }
            const string_idx = self.interner.objectStringIndex(t);
            if (string_idx != types.Primitive.none) {
                if (self.firstUnboundFreeTypeParameter(string_idx, subs)) |tp| return tp;
            }
            const number_idx = self.interner.objectNumberIndex(t);
            if (number_idx != types.Primitive.none) {
                if (self.firstUnboundFreeTypeParameter(number_idx, subs)) |tp| return tp;
            }
            return null;
        }
        if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |param| {
                if (self.firstUnboundFreeTypeParameter(param, subs)) |tp| return tp;
            }
            if (self.interner.signatureReturn(t)) |ret| {
                if (self.firstUnboundFreeTypeParameter(ret, subs)) |tp| return tp;
            }
            return null;
        }
        if (flags.is_type_parameter) return if (subs.contains(t) or self.isThisTypeParameter(t)) null else t;
        return null;
    }

    fn computedDescriptorMapType(self: *Checker, arg_t: TypeId) CheckError!?TypeId {
        if (arg_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(arg_t).is_object_type) return null;
        const computed_id = self.string_interner.intern("computed") catch return error.OutOfMemory;
        const computed_t = self.interner.objectMember(arg_t, computed_id) orelse return null;
        return try self.descriptorLikeMapType(computed_t);
    }

    fn descriptorLikeMapType(self: *Checker, t: TypeId) CheckError!?TypeId {
        if (t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(t).is_object_type) return null;
        const source_members = self.interner.objectMembers(t);
        if (source_members.len == 0) return null;
        var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
        defer members.deinit(self.gpa);
        for (source_members) |member| {
            if (self.syntheticSignatureMemberName(member.name)) continue;
            const value_t = (try self.descriptorLikeValueType(member.type)) orelse return null;
            try members.append(self.gpa, .{
                .name = member.name,
                .type = value_t,
                .is_optional = false,
                .is_readonly = false,
                .is_method = false,
            });
        }
        if (members.items.len == 0) return null;
        return self.interner.internObjectType(members.items) catch return error.OutOfMemory;
    }

    fn descriptorLikeValueType(self: *Checker, t: TypeId) CheckError!?TypeId {
        if (t >= self.interner.pool.typeCount()) return null;
        if (self.firstSignatureType(t)) |sig| {
            if (self.interner.signatureReturn(sig)) |ret| return ret;
        }
        if (!self.interner.pool.flagsOf(t).is_object_type) return null;
        const value_id = self.string_interner.intern("value") catch return error.OutOfMemory;
        if (self.interner.objectMember(t, value_id)) |value_t| return value_t;
        const get_id = self.string_interner.intern("get") catch return error.OutOfMemory;
        if (self.interner.objectMember(t, get_id)) |get_t| {
            if (self.firstSignatureType(get_t)) |sig| {
                if (self.interner.signatureReturn(sig)) |ret| return ret;
            }
        }
        const set_id = self.string_interner.intern("set") catch return error.OutOfMemory;
        if (self.interner.objectMember(t, set_id)) |set_t| {
            if (self.firstSignatureType(set_t)) |sig| {
                const params = self.interner.signatureParams(sig);
                if (params.len > 0) return params[0];
            }
        }
        return null;
    }

    /// Walk `t` and, for any encountered type-parameter id with a
    /// declaration-site default that isn't already in `subs`, record
    /// `tp_id -> default`. Used by `instantiateReturn` so optional
    /// params (`x?: T` ÃÂ¢ÃÂÃÂ `T | undefined`) and nested generics still
    /// surface T.
    fn collectFreeTypeParamDefaults(
        self: *Checker,
        t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
        visited: *std.AutoHashMapUnmanaged(TypeId, void),
    ) !void {
        if (t < types.Primitive.first_dynamic) return;
        if (t >= self.interner.pool.typeCount()) return;
        if (visited.contains(t)) return;
        try visited.put(self.gpa, t, {});
        const flags = self.interner.pool.flagsOf(t);
        const payload_idx = self.interner.pool.payloadOf(t);
        if (flags.is_type_parameter) {
            if (!subs.contains(t)) {
                if (payload_idx >= self.interner.pool.type_parameter_payloads.items.len) return;
                const tp = self.interner.pool.type_parameter_payloads.items[payload_idx];
                if (tp.default != types.Primitive.none) {
                    try subs.put(self.gpa, t, tp.default);
                }
            }
            return;
        }
        if (flags.is_union) {
            if (payload_idx >= self.interner.pool.union_payloads.items.len) return;
            for (self.interner.unionMembers(t)) |m| try self.collectFreeTypeParamDefaults(m, subs, visited);
            return;
        }
        if (flags.is_intersection) {
            if (payload_idx >= self.interner.pool.intersection_payloads.items.len) return;
            for (self.interner.intersectionMembers(t)) |m| try self.collectFreeTypeParamDefaults(m, subs, visited);
            return;
        }
    }

    fn collectFreeTypeParamFallbacks(
        self: *Checker,
        t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
        visited: *std.AutoHashMapUnmanaged(TypeId, void),
    ) !void {
        if (t < types.Primitive.first_dynamic) return;
        if (t >= self.interner.pool.typeCount()) return;
        if (visited.contains(t)) return;
        try visited.put(self.gpa, t, {});
        const flags = self.interner.pool.flagsOf(t);
        const payload_idx = self.interner.pool.payloadOf(t);
        if (flags.is_type_parameter) {
            if (self.isThisTypeParameter(t)) return;
            if (!subs.contains(t)) {
                const fallback = self.typeParameterBaseConstraint(t) orelse types.Primitive.unknown;
                try subs.put(self.gpa, t, fallback);
            }
            return;
        }
        if (flags.is_union) {
            if (payload_idx >= self.interner.pool.union_payloads.items.len) return;
            for (self.interner.unionMembers(t)) |m| try self.collectFreeTypeParamFallbacks(m, subs, visited);
            return;
        }
        if (flags.is_intersection) {
            if (payload_idx >= self.interner.pool.intersection_payloads.items.len) return;
            for (self.interner.intersectionMembers(t)) |m| try self.collectFreeTypeParamFallbacks(m, subs, visited);
            return;
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |m| try self.collectFreeTypeParamFallbacks(m.type, subs, visited);
            const str_idx = self.interner.objectStringIndex(t);
            if (str_idx != types.Primitive.none) try self.collectFreeTypeParamFallbacks(str_idx, subs, visited);
            const num_idx = self.interner.objectNumberIndex(t);
            if (num_idx != types.Primitive.none) try self.collectFreeTypeParamFallbacks(num_idx, subs, visited);
            return;
        }
        if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |p| try self.collectFreeTypeParamFallbacks(p, subs, visited);
            if (self.interner.signatureReturn(t)) |r| try self.collectFreeTypeParamFallbacks(r, subs, visited);
        }
    }

    fn substitutedKeyofOperand(
        self: *Checker,
        constraint: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!TypeId {
        if (constraint >= self.interner.pool.typeCount()) return types.Primitive.none;
        const flags = self.interner.pool.flagsOf(constraint);
        if (!flags.is_keyof) return types.Primitive.none;
        const k = self.interner.pool.keyof_payloads.items[self.interner.pool.payloadOf(constraint)];
        return self.substituteType(k.operand, subs);
    }

    fn mappedTemplateKeyTypeParameter(self: *Checker, template: TypeId) TypeId {
        if (template >= self.interner.pool.typeCount()) return types.Primitive.none;
        const flags = self.interner.pool.flagsOf(template);
        if (!flags.is_indexed_access) return types.Primitive.none;
        const payload_idx = self.interner.pool.payloadOf(template);
        if (payload_idx >= self.interner.pool.indexed_access_payloads.items.len) return types.Primitive.none;
        const ia = self.interner.pool.indexed_access_payloads.items[payload_idx];
        if (ia.index >= self.interner.pool.typeCount()) return types.Primitive.none;
        if (!self.interner.pool.flagsOf(ia.index).is_type_parameter) return types.Primitive.none;
        return ia.index;
    }

    fn substituteMappedType(
        self: *Checker,
        mapped_t: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!TypeId {
        const m = self.interner.mappedPayload(mapped_t);
        const raw_indexed = self.mappedTemplateIndexedAccessWithConcreteObject(m.template);
        const raw_key_tp = if (raw_indexed) |indexed|
            indexed.key_tp
        else
            self.mappedTemplateKeyTypeParameter(m.template);
        if (self.homomorphicMappedTypeParameter(mapped_t)) |source_tp| {
            const source_t = try self.substituteType(source_tp, subs);
            if (source_t == types.Primitive.any and self.typeParameterHasArrayOrTupleConstraint(source_tp)) {
                const array_t = try self.instantiateMappedArrayType(m, raw_key_tp, subs);
                return try self.finishSubstitutedMappedType(mapped_t, array_t, subs);
            }
        }
        const constraint = try self.substituteType(m.constraint, subs);
        const template = try self.substituteType(m.template, subs);
        if (constraint == types.Primitive.never) {
            const empty = self.interner.internObjectType(&.{}) catch return error.OutOfMemory;
            return try self.finishSubstitutedMappedType(mapped_t, empty, subs);
        }
        var keys: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
        defer keys.deinit(self.gpa);
        const constraint_source_obj = try self.substitutedKeyofOperand(m.constraint, subs);
        const template_source_obj = if (raw_indexed) |indexed|
            if (self.isBuiltinMappedKeyTypeParameter(indexed.key_tp))
                try self.substituteType(indexed.object_tp, subs)
            else
                types.Primitive.none
        else
            types.Primitive.none;
        const source_obj = if (constraint_source_obj != types.Primitive.none)
            constraint_source_obj
        else
            template_source_obj;
        const source_is_array_like = self.isTupleShapedTarget(source_obj) or self.objectTypeIsArrayLikeContainer(source_obj);
        var can_materialize = self.collectStringLiteralKeys(constraint, &keys);
        if (!can_materialize and
            constraint < self.interner.pool.typeCount() and
            self.interner.pool.flagsOf(constraint).is_keyof)
        {
            const payload_idx = self.interner.pool.payloadOf(constraint);
            if (payload_idx < self.interner.pool.keyof_payloads.items.len) {
                const operand = self.interner.pool.keyof_payloads.items[payload_idx].operand;
                can_materialize = try self.collectKeyofObjectKeys(operand, &keys);
            }
        }
        if (source_is_array_like) {
            for (self.interner.objectMembers(source_obj)) |member| {
                if (!self.isNumericStringId(member.name)) continue;
                try self.appendUniqueKeyofName(&keys, member.name);
            }
            can_materialize = keys.items.len > 0;
        }
        if (can_materialize) {
            const key_tp = raw_key_tp;
            var members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
            defer members.deinit(self.gpa);
            for (keys.items) |key| {
                if (source_is_array_like and !self.isNumericStringId(key)) continue;
                const key_lit = self.interner.internStringLiteral(key) catch return error.OutOfMemory;
                var key_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                defer key_subs.deinit(self.gpa);
                if (key_tp != types.Primitive.none) try key_subs.put(self.gpa, key_tp, key_lit);
                const value_t = (if (self.isBuiltinMappedKeyTypeParameter(key_tp) and source_obj != types.Primitive.none)
                    try self.resolveObjectIndexedAccessType(source_obj, key_lit)
                else
                    null) orelse
                    (if (key_tp != types.Primitive.none)
                        try self.substituteType(template, &key_subs)
                    else
                        template);
                const source_member = if (source_obj < self.interner.pool.typeCount() and self.interner.pool.flagsOf(source_obj).is_object_type)
                    self.interner.objectMemberInfo(source_obj, key)
                else
                    null;
                const is_optional = switch (m.optional) {
                    .add => true,
                    .remove => false,
                    .none => if (source_member) |member| member.is_optional else false,
                };
                const is_readonly = switch (m.readonly) {
                    .add => true,
                    .remove => false,
                    .none => if (source_member) |member| member.is_readonly else false,
                };
                try members.append(self.gpa, .{
                    .name = key,
                    .type = value_t,
                    .is_optional = is_optional,
                    .is_readonly = is_readonly,
                    .is_method = false,
                });
            }
            if (source_is_array_like and key_tp != types.Primitive.none) {
                const number_index = self.interner.objectNumberIndex(source_obj);
                const mapped_number_index = if (number_index != types.Primitive.none) blk: {
                    if (self.isBuiltinMappedKeyTypeParameter(key_tp)) {
                        if (try self.resolveObjectIndexedAccessType(source_obj, types.Primitive.number_t)) |resolved| {
                            break :blk resolved;
                        }
                    }
                    var number_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                    defer number_subs.deinit(self.gpa);
                    try number_subs.put(self.gpa, key_tp, types.Primitive.number_t);
                    break :blk try self.substituteType(template, &number_subs);
                } else types.Primitive.none;
                const result = self.interner.internObjectTypeWithIndexAndSymbol(
                    members.items,
                    types.Primitive.none,
                    mapped_number_index,
                    types.Primitive.none,
                ) catch return error.OutOfMemory;
                return try self.finishSubstitutedMappedType(mapped_t, result, subs);
            }
            const result = self.interner.internObjectType(members.items) catch return error.OutOfMemory;
            return try self.finishSubstitutedMappedType(mapped_t, result, subs);
        }
        if (raw_key_tp != types.Primitive.none and
            (self.typeContainsBroadKey(constraint, types.Primitive.string_t) or
                self.typeContainsBroadKey(constraint, types.Primitive.number_t) or
                self.typeContainsBroadKey(constraint, types.Primitive.symbol_t)))
        {
            const string_idx = if (self.typeContainsBroadKey(constraint, types.Primitive.string_t))
                try self.substituteMappedIndexTemplate(template, raw_key_tp, types.Primitive.string_t)
            else
                types.Primitive.none;
            const number_idx = if (self.typeContainsBroadKey(constraint, types.Primitive.number_t))
                try self.substituteMappedIndexTemplate(template, raw_key_tp, types.Primitive.number_t)
            else
                types.Primitive.none;
            const symbol_idx = if (self.typeContainsBroadKey(constraint, types.Primitive.symbol_t))
                try self.substituteMappedIndexTemplate(template, raw_key_tp, types.Primitive.symbol_t)
            else
                types.Primitive.none;
            const result = self.interner.internObjectTypeWithIndexAndSymbol(
                &.{},
                string_idx,
                number_idx,
                symbol_idx,
            ) catch return error.OutOfMemory;
            return try self.finishSubstitutedMappedType(mapped_t, result, subs);
        }
        const result = self.interner.internMapped(constraint, template, m.readonly, m.optional) catch return error.OutOfMemory;
        return try self.finishSubstitutedMappedType(mapped_t, result, subs);
    }

    fn builtinMappedSourceType(self: *Checker, mapped_t: TypeId) ?TypeId {
        if (mapped_t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(mapped_t).is_mapped) return null;
        const mapped = self.interner.mappedPayload(mapped_t);
        const indexed = self.mappedTemplateIndexedAccessWithConcreteObject(mapped.template) orelse return null;
        if (!self.isBuiltinMappedKeyTypeParameter(indexed.key_tp)) return null;
        if (indexed.object_tp >= self.interner.pool.typeCount()) return null;
        return indexed.object_tp;
    }

    fn isBuiltinMappedKeyTypeParameter(self: *Checker, t: TypeId) bool {
        if (t >= self.interner.pool.typeCount() or !self.interner.pool.flagsOf(t).is_type_parameter) return false;
        const payload_idx = self.interner.pool.payloadOf(t);
        if (payload_idx >= self.interner.pool.type_parameter_payloads.items.len) return false;
        const type_param = self.interner.pool.type_parameter_payloads.items[payload_idx];
        return std.mem.eql(u8, self.string_interner.get(type_param.name), "__home_mapped_key");
    }

    fn finishSubstitutedMappedType(
        self: *Checker,
        source_t: TypeId,
        result_t: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!TypeId {
        const display = self.alias_display_names.get(source_t) orelse return result_t;
        var visited: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
        defer visited.deinit(self.gpa);
        if (try self.substitutedAliasDisplayText(source_t, display, subs, &visited)) |substituted| {
            try self.alias_display_names.put(self.gpa, result_t, substituted.text);
            try self.alias_type_args.put(self.gpa, result_t, substituted.args);
        } else {
            try self.alias_display_names.put(self.gpa, result_t, display);
        }
        return result_t;
    }

    fn instantiateMappedArrayType(
        self: *Checker,
        mapped: types.MappedPayload,
        key_tp: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) CheckError!TypeId {
        var element_t = try self.substituteType(mapped.template, subs);
        if (key_tp != types.Primitive.none) {
            element_t = try self.substituteMappedIndexTemplate(element_t, key_tp, types.Primitive.number_t);
        }
        if (self.strict_flags.strict_null_checks) {
            element_t = switch (mapped.optional) {
                .add => try self.unionWithUndefined(element_t),
                .remove => try self.subtractUndefined(element_t),
                .none => element_t,
            };
        }
        const array_t = self.interner.internArrayType(self.string_interner, element_t) catch return error.OutOfMemory;
        try self.array_origin_types.put(self.gpa, array_t, {});
        if (mapped.readonly == .add) try self.readonly_index_types.put(self.gpa, array_t, {});
        return array_t;
    }

    fn substituteMappedIndexTemplate(
        self: *Checker,
        template: TypeId,
        key_tp: TypeId,
        index_t: TypeId,
    ) CheckError!TypeId {
        var key_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer key_subs.deinit(self.gpa);
        try key_subs.put(self.gpa, key_tp, index_t);
        return try self.substituteType(template, &key_subs);
    }

    /// Substitute occurrences of type-parameter ids in `t` per the
    /// `subs` map. Recurses into compound types ÃÂ¢ÃÂÃÂ unions,
    /// intersections, signatures, object types ÃÂ¢ÃÂÃÂ so a parameterized
    /// alias body fully resolves under instantiation.
    /// Structural type substitution, recursion-guarded against
    /// self-referential interned shapes (`type T = { value: T }`,
    /// `RecBox<T> = T | Box<RecBox<T>>`). Substitution walks the
    /// interned type DAG, which for a recursively-defined alias body
    /// can re-enter the same node. We share the instantiation depth
    /// budget so a single outer evaluation can't blow the native stack;
    /// hitting the cap yields the input type unchanged (the safe
    /// fixed-point) rather than the error type, since substitution
    /// itself doesn't surface TS2589.
    /// Memoizing front door for the substitution engine. Within one
    /// outermost walk (fixed `subs`), the result for a given TypeId is
    /// deterministic unless a cycle-cut / deferral fired beneath it
    /// (tracked via `instantiation_defer_events`), so repeated visits
    /// of shared subtrees short-circuit here instead of re-walking
    /// exponentially. Sub-walks under derived maps (`signature_subs`)
    /// bypass the memo via the `subst_memo_subs` pointer pin.
    fn substituteType(
        self: *Checker,
        t: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) (CheckError)!TypeId {
        if (self.noInferInnerType(t)) |inner| return self.substituteType(inner, subs);
        if (subs.get(t)) |s| return s;
        if (t >= self.interner.pool.typeCount()) return t;
        const outermost = self.subst_memo_subs == null;
        if (outermost) {
            self.subst_memo_subs = subs;
            self.subst_memo.clearRetainingCapacity();
        }
        defer if (outermost) {
            self.subst_memo_subs = null;
        };
        const memo_eligible = self.subst_memo_subs == subs and !self.subst_active.contains(t);
        if (memo_eligible) {
            if (self.subst_memo.get(t)) |m| return m;
        }
        const defer_before = self.instantiation_defer_events;
        const result = try self.substituteTypeUncached(t, subs);
        if (memo_eligible and self.instantiation_defer_events == defer_before) {
            self.subst_memo.put(self.gpa, t, result) catch {};
        }
        return result;
    }

    fn substituteTypeUncached(
        self: *Checker,
        t: TypeId,
        subs: *const std.AutoHashMapUnmanaged(TypeId, TypeId),
    ) (CheckError)!TypeId {
        if (subs.get(t)) |s| return s;
        if (t >= self.interner.pool.typeCount()) return t;
        if (self.instantiation_depth >= max_instantiation_depth or
            self.instantiation_count >= max_instantiation_count)
        {
            self.type_instantiation_overflow = true;
            return t;
        }
        self.instantiation_count +|= 1;
        self.instantiation_depth += 1;
        defer self.instantiation_depth -= 1;
        // Cycle cut: if `t` is already being substituted higher on the
        // active call path, a self-reference brought us back to it. Return
        // it unchanged rather than re-expanding (which terminates only via
        // the far-off depth/count caps after astronomical work). Type
        // parameters never reach here — `subs.get(t)` short-circuits them
        // above — so this only affects composite types (objects,
        // signatures, unions, …).
        if (self.subst_active.contains(t)) {
            self.instantiation_defer_events +%= 1;
            return t;
        }
        self.subst_active.put(self.gpa, t, {}) catch {};
        defer _ = self.subst_active.remove(t);
        const flags = self.interner.pool.flagsOf(t);
        const payload_idx = self.interner.pool.payloadOf(t);
        if (flags.is_union) {
            if (payload_idx >= self.interner.pool.union_payloads.items.len) return t;
            const members = self.interner.unionMembers(t);
            const members_snapshot = try self.gpa.dupe(TypeId, members);
            defer self.gpa.free(members_snapshot);
            var new: std.ArrayListUnmanaged(TypeId) = .empty;
            defer new.deinit(self.gpa);
            for (members_snapshot) |m| {
                const subbed = try self.substituteType(m, subs);
                try new.append(self.gpa, if (subbed < self.interner.pool.typeCount()) subbed else types.Primitive.unknown);
            }
            return self.interner.internUnion(new.items) catch return t;
        }
        if (flags.is_intersection) {
            if (payload_idx >= self.interner.pool.intersection_payloads.items.len) return t;
            const members = self.interner.intersectionMembers(t);
            const members_snapshot = try self.gpa.dupe(TypeId, members);
            defer self.gpa.free(members_snapshot);
            var new: std.ArrayListUnmanaged(TypeId) = .empty;
            defer new.deinit(self.gpa);
            for (members_snapshot) |m| {
                const subbed = try self.substituteType(m, subs);
                try new.append(self.gpa, if (subbed < self.interner.pool.typeCount()) subbed else types.Primitive.unknown);
            }
            return self.interner.internIntersection(new.items) catch return t;
        }
        if (flags.is_signature) {
            if (payload_idx >= self.interner.pool.signature_payloads.items.len) return t;
            const params = self.interner.signatureParams(t);
            const params_snapshot = try self.gpa.dupe(TypeId, params);
            defer self.gpa.free(params_snapshot);
            var signature_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
            defer signature_subs.deinit(self.gpa);
            var subs_it = subs.iterator();
            while (subs_it.next()) |entry| {
                try signature_subs.put(self.gpa, entry.key_ptr.*, entry.value_ptr.*);
            }
            var preserved_params: std.ArrayListUnmanaged(TypeId) = .empty;
            defer preserved_params.deinit(self.gpa);
            if (self.generic_signature_params.get(t)) |type_params| {
                for (type_params) |param_t| {
                    if (subs.contains(param_t)) continue;
                    if (param_t >= self.interner.pool.typeCount() or
                        !self.interner.pool.flagsOf(param_t).is_type_parameter)
                    {
                        try preserved_params.append(self.gpa, param_t);
                        continue;
                    }
                    const tp_payload_idx = self.interner.pool.payloadOf(param_t);
                    if (tp_payload_idx >= self.interner.pool.type_parameter_payloads.items.len) {
                        try preserved_params.append(self.gpa, param_t);
                        continue;
                    }
                    const tp = self.interner.pool.type_parameter_payloads.items[tp_payload_idx];
                    const next_constraint = if (tp.constraint != types.Primitive.none)
                        if (self.typeContainsMappedConstraintParameter(t, param_t, 0))
                            try self.substituteInferenceConstraintPreservingKeyof(tp.constraint, &signature_subs)
                        else
                            try self.substituteType(tp.constraint, &signature_subs)
                    else
                        types.Primitive.none;
                    const next_default = if (tp.default != types.Primitive.none)
                        try self.substituteType(tp.default, &signature_subs)
                    else
                        types.Primitive.none;
                    const next_param_t = if (next_constraint != tp.constraint or next_default != tp.default)
                        self.interner.internFreshTypeParameterWithFlags(
                            tp.name,
                            next_constraint,
                            next_default,
                            tp.variance,
                            tp.is_const,
                        ) catch return t
                    else
                        param_t;
                    if (next_param_t != param_t) {
                        try signature_subs.put(self.gpa, param_t, next_param_t);
                        const decl_node = self.type_parameter_decl_nodes.get(param_t) orelse
                            self.type_parameter_decl_nodes.get(self.resolvedTypeParameterPlaceholder(param_t));
                        if (decl_node) |decl| {
                            try self.type_parameter_decl_nodes.put(self.gpa, next_param_t, decl);
                            const resolved_next = self.resolvedTypeParameterPlaceholder(next_param_t);
                            if (resolved_next != next_param_t) {
                                try self.type_parameter_decl_nodes.put(self.gpa, resolved_next, decl);
                            }
                        }
                    }
                    try preserved_params.append(self.gpa, next_param_t);
                }
            }
            var new: std.ArrayListUnmanaged(TypeId) = .empty;
            defer new.deinit(self.gpa);
            for (params_snapshot) |p| try new.append(self.gpa, try self.substituteType(p, &signature_subs));
            const ret = if (self.interner.signatureReturn(t)) |r|
                try self.substituteType(r, &signature_subs)
            else
                types.Primitive.void_t;
            const sig_payload = self.interner.pool.signature_payloads.items[payload_idx];
            const this_t_opt: ?TypeId = if (self.signatureThisParam(t)) |this_t|
                try self.substituteType(this_t, &signature_subs)
            else
                null;
            const new_sig = if (this_t_opt) |this_t|
                self.interner.internSignatureWithThisType(
                    new.items,
                    ret,
                    sig_payload.is_construct,
                    sig_payload.is_abstract_construct,
                    this_t,
                ) catch return t
            else
                self.interner.internSignatureWithAbstract(
                    new.items,
                    ret,
                    sig_payload.is_construct,
                    sig_payload.is_abstract_construct,
                ) catch return t;
            try self.copySignatureParamNames(new_sig, t);
            try self.copySignatureNullishArrayDefaults(new_sig, t);
            if (this_t_opt) |this_t| {
                try self.signature_this_params.put(self.gpa, new_sig, this_t);
            }
            if (self.rest_signatures.contains(t)) {
                try self.rest_signatures.put(self.gpa, new_sig, {});
            }
            {
                const old_min_required = self.signature_min_args.get(t) orelse params.len;
                var omittable: std.ArrayListUnmanaged(bool) = .empty;
                defer omittable.deinit(self.gpa);
                for (new.items, 0..) |param_t, param_i| {
                    try omittable.append(self.gpa, param_i >= old_min_required or self.parameterTypeAllowsVoidOmission(param_t));
                }
                try self.recordSignatureMinArgs(new_sig, omittable.items);
            }
            if (self.signature_predicates.get(t)) |pred| {
                var next_pred = pred;
                next_pred.target_type = self.substituteType(pred.target_type, &signature_subs) catch pred.target_type;
                try self.signature_predicates.put(self.gpa, new_sig, next_pred);
            }
            if (preserved_params.items.len > 0) {
                try self.recordGenericSignatureParams(new_sig, preserved_params.items);
            }
            // SignatureParamKey.param_index is `u16`; cap iteration at
            // 65535 to avoid silent narrowing on adversarial signatures
            // with more parameters than the key can address. Predicates
            // beyond that index would alias keys and corrupt lookups.
            const param_cap = @min(params_snapshot.len, @as(usize, std.math.maxInt(u16)) + 1);
            var param_ix: usize = 0;
            while (param_ix < param_cap) : (param_ix += 1) {
                const key: SignatureParamKey = .{ .signature = t, .param_index = @intCast(param_ix) };
                if (self.signature_param_predicates.get(key)) |pred| {
                    var next_pred = pred;
                    next_pred.target_type = self.substituteType(pred.target_type, &signature_subs) catch pred.target_type;
                    try self.signature_param_predicates.put(self.gpa, .{
                        .signature = new_sig,
                        .param_index = @intCast(param_ix),
                    }, next_pred);
                }
            }
            return new_sig;
        }
        if (flags.is_object_type) {
            if (payload_idx >= self.interner.pool.object_type_payloads.items.len) return t;
            const orig = self.interner.objectMembers(t);
            const orig_snapshot = try self.gpa.dupe(types.ObjectMember, orig);
            defer self.gpa.free(orig_snapshot);
            var new_members: std.ArrayListUnmanaged(types.ObjectMember) = .empty;
            defer new_members.deinit(self.gpa);
            for (orig_snapshot) |om| {
                try new_members.append(self.gpa, .{
                    .name = om.name,
                    .type = try self.substituteType(om.type, subs),
                    .is_optional = om.is_optional,
                    .is_readonly = om.is_readonly,
                    .is_method = om.is_method,
                    .decl_node = om.decl_node,
                });
            }
            // Preserve and substitute index signatures so `T[]`
            // (which lowers to an object with `length: number` plus a
            // numeric indexer pointing to T) keeps its indexer after
            // instantiation. Without this, the substituted return
            // would still have `length: number` but no element type,
            // which breaks downstream `objectNumberIndex` reads.
            const orig_str = self.interner.objectStringIndex(t);
            const orig_num = self.interner.objectNumberIndex(t);
            const orig_sym = self.interner.objectSymbolIndex(t);
            const new_str = if (orig_str != types.Primitive.none)
                try self.substituteType(orig_str, subs)
            else
                types.Primitive.none;
            const new_num = if (orig_num != types.Primitive.none)
                try self.substituteType(orig_num, subs)
            else
                types.Primitive.none;
            const new_sym = if (orig_sym != types.Primitive.none)
                try self.substituteType(orig_sym, subs)
            else
                types.Primitive.none;
            const new_obj = if (new_str == types.Primitive.none and new_num == types.Primitive.none and new_sym == types.Primitive.none)
                self.interner.internObjectType(new_members.items) catch return t
            else
                self.interner.internObjectTypeWithIndexAndSymbol(new_members.items, new_str, new_num, new_sym) catch return t;
            if (self.interner.typeSymbol(t) != 0) {
                self.interner.setTypeSymbol(new_obj, self.interner.typeSymbol(t));
            }
            if (self.this_type_markers.get(t)) |this_raw| {
                try self.this_type_markers.put(self.gpa, new_obj, try self.substituteType(this_raw, subs));
            }
            if (self.readonly_index_types.contains(t)) {
                try self.readonly_index_types.put(self.gpa, new_obj, {});
            }
            if (self.array_origin_types.contains(t)) {
                try self.array_origin_types.put(self.gpa, new_obj, {});
            }
            if (self.isActualTupleType(t)) {
                try self.markTupleOrigin(new_obj);
            }
            if (self.tuple_trailing_rest_types.get(t)) |rest_t| {
                try self.tuple_trailing_rest_types.put(self.gpa, new_obj, try self.substituteType(rest_t, subs));
            }
            if (self.tuple_trailing_variadic_types.get(t)) |variadic_t| {
                const new_variadic_t = if (self.infer_type_parameters.contains(variadic_t))
                    variadic_t
                else
                    try self.substituteType(variadic_t, subs);
                try self.tuple_trailing_variadic_types.put(self.gpa, new_obj, new_variadic_t);
            }
            if (self.builtin_object_names.get(t)) |builtin_name| {
                try self.builtin_object_names.put(self.gpa, new_obj, builtin_name);
                if (std.mem.eql(u8, builtin_name, "Object")) {
                    try self.engine.registerUpperObjectTarget(new_obj);
                }
            }
            if (self.decl_single_base.get(t)) |base_t| {
                try self.decl_single_base.put(self.gpa, new_obj, try self.substituteType(base_t, subs));
            }
            if (self.generator_type_info.get(t)) |gen| {
                try self.generator_type_info.put(self.gpa, new_obj, .{
                    .yield_type = try self.substituteType(gen.yield_type, subs),
                    .return_type = try self.substituteType(gen.return_type, subs),
                    .next_type = try self.substituteType(gen.next_type, subs),
                });
            }
            for (orig_snapshot) |om| {
                var pred_opt = self.member_predicates.get(.{ .receiver_type = t, .member_name = om.name });
                if (pred_opt == null) {
                    const substituted_member_t = self.substituteType(om.type, subs) catch om.type;
                    pred_opt = self.signature_predicates.get(substituted_member_t);
                }
                if (pred_opt) |pred| {
                    var next_pred = pred;
                    next_pred.target_type = self.substituteType(pred.target_type, subs) catch pred.target_type;
                    try self.recordMemberPredicate(new_obj, om.name, next_pred);
                }
            }
            // Propagate the class-instance origin so member-access
            // privacy checks (TS2341) can map an instantiated generic
            // (`D<number>`) back to its declaring class (`D`).
            // Mirrors `memberFunctionsWithPublicPrivateOverloads.ts(62,12)`.
            if (self.class_name_by_instance.get(t)) |cname| {
                try self.class_name_by_instance.put(self.gpa, new_obj, cname);
            }
            if (self.class_decl_by_instance.get(t)) |decl| {
                try self.class_decl_by_instance.put(self.gpa, new_obj, decl);
            }
            // Mirror `class_private_members` lookup against the instance:
            // privacy checks look up the class's private set via the
            // declaring class name, which is now reachable via the
            // propagated `class_name_by_instance` entry.
            if (self.alias_display_names.get(t)) |display| {
                var alias_visited: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
                defer alias_visited.deinit(self.gpa);
                if (try self.substitutedAliasDisplayText(t, display, subs, &alias_visited)) |substituted_display| {
                    try self.alias_display_names.put(self.gpa, new_obj, substituted_display.text);
                    try self.alias_type_args.put(self.gpa, new_obj, substituted_display.args);
                } else {
                    try self.alias_display_names.put(self.gpa, new_obj, display);
                }
            }
            return new_obj;
        }
        if (flags.is_conditional) {
            // Substitute into each leaf, then re-attempt eager
            // evaluation. If the check is now concrete, this
            // collapses to the picked branch.
            const c = self.interner.conditionalPayload(t);
            if (c.check_type < self.interner.pool.typeCount() and
                self.interner.pool.flagsOf(c.check_type).is_type_parameter)
            {
                if (subs.get(c.check_type)) |check_sub| {
                    if (check_sub < self.interner.pool.typeCount() and
                        self.interner.pool.flagsOf(check_sub).is_union)
                    {
                        const members = try self.gpa.dupe(TypeId, self.interner.unionMembers(check_sub));
                        defer self.gpa.free(members);
                        var built: std.ArrayListUnmanaged(TypeId) = .empty;
                        defer built.deinit(self.gpa);
                        for (members) |member| {
                            var member_subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
                            defer member_subs.deinit(self.gpa);
                            try self.copyInferSubs(subs, &member_subs);
                            try member_subs.put(self.gpa, c.check_type, member);
                            const member_ext = try self.substituteType(c.extends_type, &member_subs);
                            const member_tt = try self.substituteType(c.true_branch, &member_subs);
                            const member_ff = try self.substituteType(c.false_branch, &member_subs);
                            const r = try self.evalConditionalWithDistribution(member, member_ext, member_tt, member_ff, true, c.is_distributive);
                            if (r == types.Primitive.never) continue;
                            try built.append(self.gpa, r);
                        }
                        if (built.items.len == 0) return types.Primitive.never;
                        if (built.items.len == 1) return built.items[0];
                        return self.interner.internUnion(built.items) catch return t;
                    }
                }
            }
            const new_check = try self.substituteType(c.check_type, subs);
            const new_ext = try self.substituteType(c.extends_type, subs);
            const new_tt = try self.substituteType(c.true_branch, subs);
            const new_ff = try self.substituteType(c.false_branch, subs);
            return self.evalConditionalWithDistribution(new_check, new_ext, new_tt, new_ff, true, c.is_distributive);
        }
        if (flags.is_mapped) {
            return try self.substituteMappedType(t, subs);
        }
        if (flags.is_keyof) {
            // `keyof T` after substitution may resolve eagerly.
            const k = self.interner.pool.keyof_payloads.items[self.interner.pool.payloadOf(t)];
            const substituted_operand = try self.substituteType(k.operand, subs);
            const new_operand = try self.reduceNeverIntersectionsForAssignability(substituted_operand);
            if (new_operand == types.Primitive.any) return self.propertyKeyUnionType() catch return t;
            if (new_operand == types.Primitive.never) return self.propertyKeyUnionType() catch return t;
            if (new_operand == types.Primitive.unknown or
                new_operand == types.Primitive.null_t or
                new_operand == types.Primitive.undefined_t or
                new_operand == types.Primitive.void_t)
            {
                return types.Primitive.never;
            }
            var key_names: std.ArrayListUnmanaged(hir_mod.StringId) = .empty;
            defer key_names.deinit(self.gpa);
            var key_types: std.ArrayListUnmanaged(TypeId) = .empty;
            defer key_types.deinit(self.gpa);
            try self.collectKeyofBroadIndexKeys(new_operand, &key_types);
            if (try self.collectKeyofObjectKeys(new_operand, &key_names)) {
                for (key_names.items) |name| {
                    const lit = self.interner.internStringLiteral(name) catch continue;
                    try self.appendUniqueTypeId(&key_types, lit);
                }
                if (key_types.items.len == 0) return types.Primitive.never;
                if (key_types.items.len == 1) return key_types.items[0];
                return self.interner.internUnion(key_types.items) catch return t;
            }
            return self.interner.internKeyof(new_operand) catch return t;
        }
        if (flags.is_indexed_access) {
            // T[K] after substitution. If K resolves to a union of
            // string literals (typically `keyof T`), distribute the
            // indexed access over each member. If K is a single
            // string literal, look up the matching member's type.
            // Otherwise re-intern.
            const ia = self.interner.pool.indexed_access_payloads.items[self.interner.pool.payloadOf(t)];
            const new_obj = try self.substituteType(ia.object, subs);
            const new_idx = try self.substituteType(ia.index, subs);
            if (!self.containsThisTypeParameter(new_obj) and
                !self.containsFreeTypeParameter(new_idx))
            {
                if (try self.resolveObjectIndexedAccessType(new_obj, new_idx)) |resolved| return resolved;
            }
            return self.interner.internIndexedAccess(new_obj, new_idx) catch return t;
        }
        if (flags.is_template_literal) {
            const texts = self.interner.templateLiteralTexts(t);
            const part_types = self.interner.templateLiteralTypes(t);
            const texts_snapshot = try self.gpa.dupe(hir_mod.StringId, texts);
            defer self.gpa.free(texts_snapshot);
            const part_types_snapshot = try self.gpa.dupe(TypeId, part_types);
            defer self.gpa.free(part_types_snapshot);
            var new_parts: std.ArrayListUnmanaged(TypeId) = .empty;
            defer new_parts.deinit(self.gpa);
            var changed = false;
            var all_literal = true;
            var buf: std.ArrayListUnmanaged(u8) = .empty;
            defer buf.deinit(self.gpa);
            for (texts_snapshot, 0..) |text_sid, i| {
                try buf.appendSlice(self.gpa, self.string_interner.get(text_sid));
                if (i < part_types_snapshot.len) {
                    const new_part = try self.substituteType(part_types_snapshot[i], subs);
                    try new_parts.append(self.gpa, new_part);
                    if (new_part != part_types_snapshot[i]) changed = true;
                    if (self.stringLiteralValueFromType(new_part)) |lit_sid| {
                        try buf.appendSlice(self.gpa, self.string_interner.get(lit_sid));
                    } else {
                        all_literal = false;
                    }
                }
            }
            if (!changed) return t;
            if (all_literal) {
                const sid = self.string_interner.intern(buf.items) catch return error.OutOfMemory;
                return self.interner.internStringLiteral(sid) catch return t;
            }
            return self.interner.internTemplateLiteral(texts_snapshot, new_parts.items) catch return t;
        }
        if (flags.is_string_mapping) {
            const sm = self.interner.stringMappingPayload(t);
            const new_inner = try self.substituteType(sm.inner, subs);
            if (new_inner == sm.inner) return t;
            return self.applyStringMappingBuiltin(switch (sm.kind) {
                .lowercase => "Lowercase",
                .uppercase => "Uppercase",
                .capitalize => "Capitalize",
                .uncapitalize => "Uncapitalize",
            }, new_inner) catch return t;
        }
        if (flags.is_type_parameter) {
            if (payload_idx >= self.interner.pool.type_parameter_payloads.items.len) return t;
            const tp = self.interner.pool.type_parameter_payloads.items[payload_idx];
            const new_constraint = if (tp.constraint != types.Primitive.none)
                try self.substituteType(tp.constraint, subs)
            else
                tp.constraint;
            const new_default = if (tp.default != types.Primitive.none)
                try self.substituteType(tp.default, subs)
            else
                tp.default;
            if (new_constraint == tp.constraint and new_default == tp.default) return t;
            return self.interner.internTypeParameterWithFlags(
                tp.name,
                new_constraint,
                new_default,
                tp.variance,
                tp.is_const,
            ) catch return t;
        }
        return t;
    }

    fn substituteThisTypeParametersInReturn(self: *Checker, ret: TypeId, receiver_t: TypeId) CheckError!TypeId {
        if (ret >= self.interner.pool.typeCount()) return ret;
        var subs: std.AutoHashMapUnmanaged(TypeId, TypeId) = .empty;
        defer subs.deinit(self.gpa);
        var visited: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
        defer visited.deinit(self.gpa);
        try self.collectThisTypeParameterSubs(ret, receiver_t, &subs, &visited);
        if (subs.count() == 0) return ret;
        return self.substituteType(ret, &subs) catch ret;
    }

    fn collectThisTypeParameterSubs(
        self: *Checker,
        t: TypeId,
        receiver_t: TypeId,
        subs: *std.AutoHashMapUnmanaged(TypeId, TypeId),
        visited: *std.AutoHashMapUnmanaged(TypeId, void),
    ) CheckError!void {
        if (t >= self.interner.pool.typeCount()) return;
        if (visited.contains(t)) return;
        try visited.put(self.gpa, t, {});
        if (self.isThisTypeParameter(t)) {
            try subs.put(self.gpa, t, receiver_t);
            return;
        }
        const flags = self.interner.pool.flagsOf(t);
        if (flags.is_union) {
            for (self.interner.unionMembers(t)) |m| try self.collectThisTypeParameterSubs(m, receiver_t, subs, visited);
            return;
        }
        if (flags.is_intersection) {
            for (self.interner.intersectionMembers(t)) |m| try self.collectThisTypeParameterSubs(m, receiver_t, subs, visited);
            return;
        }
        if (flags.is_object_type) {
            for (self.interner.objectMembers(t)) |m| try self.collectThisTypeParameterSubs(m.type, receiver_t, subs, visited);
            const str_idx = self.interner.objectStringIndex(t);
            if (str_idx != types.Primitive.none) try self.collectThisTypeParameterSubs(str_idx, receiver_t, subs, visited);
            const num_idx = self.interner.objectNumberIndex(t);
            if (num_idx != types.Primitive.none) try self.collectThisTypeParameterSubs(num_idx, receiver_t, subs, visited);
            const sym_idx = self.interner.objectSymbolIndex(t);
            if (sym_idx != types.Primitive.none) try self.collectThisTypeParameterSubs(sym_idx, receiver_t, subs, visited);
            return;
        }
        if (flags.is_signature) {
            for (self.interner.signatureParams(t)) |p| try self.collectThisTypeParameterSubs(p, receiver_t, subs, visited);
            if (self.interner.signatureReturn(t)) |r| try self.collectThisTypeParameterSubs(r, receiver_t, subs, visited);
            return;
        }
        if (flags.is_conditional) {
            const c = self.interner.conditionalPayload(t);
            try self.collectThisTypeParameterSubs(c.check_type, receiver_t, subs, visited);
            try self.collectThisTypeParameterSubs(c.extends_type, receiver_t, subs, visited);
            try self.collectThisTypeParameterSubs(c.true_branch, receiver_t, subs, visited);
            try self.collectThisTypeParameterSubs(c.false_branch, receiver_t, subs, visited);
            return;
        }
        if (flags.is_keyof) {
            const k = self.interner.pool.keyof_payloads.items[self.interner.pool.payloadOf(t)];
            try self.collectThisTypeParameterSubs(k.operand, receiver_t, subs, visited);
            return;
        }
        if (flags.is_indexed_access) {
            const ia = self.interner.pool.indexed_access_payloads.items[self.interner.pool.payloadOf(t)];
            try self.collectThisTypeParameterSubs(ia.object, receiver_t, subs, visited);
            try self.collectThisTypeParameterSubs(ia.index, receiver_t, subs, visited);
            return;
        }
        if (flags.is_template_literal) {
            for (self.interner.templateLiteralTypes(t)) |part| try self.collectThisTypeParameterSubs(part, receiver_t, subs, visited);
            return;
        }
        if (flags.is_string_mapping) {
            const sm = self.interner.stringMappingPayload(t);
            try self.collectThisTypeParameterSubs(sm.inner, receiver_t, subs, visited);
            return;
        }
        if (flags.is_type_parameter) {
            const payload_idx = self.interner.pool.payloadOf(t);
            if (payload_idx >= self.interner.pool.type_parameter_payloads.items.len) return;
            const tp = self.interner.pool.type_parameter_payloads.items[payload_idx];
            if (tp.constraint != types.Primitive.none) try self.collectThisTypeParameterSubs(tp.constraint, receiver_t, subs, visited);
            if (tp.default != types.Primitive.none) try self.collectThisTypeParameterSubs(tp.default, receiver_t, subs, visited);
        }
    }

    fn memberCallReceiverType(self: *Checker, callee: NodeId) CheckError!?TypeId {
        if (self.hir.kindOf(callee) != .member_access) return null;
        const m = hir_mod.memberOf(self.hir, callee);
        if (self.nodeIsSuperReference(m.object)) {
            if (self.currentThisType()) |this_t| return this_t;
        }
        var receiver_t = self.hir.typeOf(m.object);
        if (receiver_t == types.Primitive.none) receiver_t = try self.checkExpression(m.object);
        if (try self.staticClassMemberAccess(m.object, m.name)) |static_access| {
            receiver_t = static_access.receiver_t;
        }
        if (m.optional or self.expressionIsOptionalChain(m.object)) {
            receiver_t = self.subtractNullUndefined(receiver_t) catch receiver_t;
        }
        return receiver_t;
    }

    fn instantiateMemberThisReturn(self: *Checker, callee: NodeId, ret: TypeId) CheckError!TypeId {
        const receiver_t = (try self.memberCallReceiverType(callee)) orelse return ret;
        return try self.substituteThisTypeParametersInReturn(ret, receiver_t);
    }

    /// Arity-only fit test: does `args.len` land inside the
    /// `[min_required, max_count]` range that `sig` accepts (where
    /// `min_required` strips trailing optionals/defaults and
    /// `max_count` is `params.len` unless the sig is variadic, in
    /// which case any count is allowed at or above the rest's fixed
    /// prefix)? Used by the new-expression path to decide whether
    /// the call would type-check against any constructor overload
    /// before falling back to the implementation signature's stricter
    /// arity. Spread args bump the min count by their tuple-prefix
    /// length so `[a, ...rest]` matches the overload that requires
    /// the prefix arity.
    /// Per-signature minimum and maximum accepted argument counts for
    /// arity analysis. `max` is null for an unbounded rest parameter
    /// (`...args: T[]`), mirroring upstream's `MaxInt` parameter count.
    const SignatureArity = struct { min: usize, max: ?usize };

    fn signatureArity(self: *Checker, sig: TypeId, call_node: NodeId) SignatureArity {
        const param_ts = self.interner.signatureParams(sig);
        const is_variadic = self.rest_signatures.contains(sig) and param_ts.len > 0;
        const fixed_count: usize = if (is_variadic) param_ts.len - 1 else param_ts.len;
        const rest_min_required: usize = if (is_variadic) self.tupleRestMinRequiredCount(param_ts[param_ts.len - 1]) else 0;
        const fixed_min_required = @min(self.signatureMinRequiredArgsForCall(sig, param_ts, call_node), fixed_count);
        const min: usize = fixed_min_required + rest_min_required;
        const max: ?usize = if (is_variadic) blk: {
            // Fold union-tuple rest max across branches (see
            // `restTupleMaxCount`).
            if (self.restTupleMaxCount(param_ts[param_ts.len - 1])) |len| {
                break :blk fixed_count + len;
            }
            break :blk null; // unbounded rest
        } else param_ts.len;
        return .{ .min = min, .max = max };
    }

    fn reportOverloadSetBoundaryArity(
        self: *Checker,
        call_node: NodeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        overloads: []const TypeId,
    ) CheckError!bool {
        if (overloads.len == 0) return false;
        var min_count: usize = std.math.maxInt(usize);
        var max_count: usize = 0;
        for (overloads) |sig| {
            const arity = self.signatureArity(sig, call_node);
            min_count = @min(min_count, arity.min);
            max_count = @max(max_count, arity.max orelse return false);
        }

        var arg_count: usize = 0;
        for (args, 0..) |arg, i| {
            arg_count += if (self.hir.kindOf(arg) == .spread)
                self.spreadArgArityContribution(arg_types[i])
            else
                1;
        }
        if (arg_count >= min_count and arg_count <= max_count) return false;

        const msg = if (min_count < max_count)
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Expected {d}-{d} arguments, but got {d}.",
                .{ min_count, max_count, arg_count },
            )
        else
            try std.fmt.allocPrint(
                self.diag_arena.allocator(),
                "Expected {d} arguments, but got {d}.",
                .{ min_count, arg_count },
            );
        try self.diagnostics.append(self.gpa, .{
            .node = call_node,
            .pos = if (arg_count > max_count) self.firstExcessArgStartPos(args, arg_types, max_count) else null,
            .code = TsCodes.expected_n_arguments,
            .message = msg,
        });
        return true;
    }

    /// TS2575 arity analysis over an overload set. Returns the
    /// interpolation tuple `(arg_count, max_below, min_above)` when the
    /// call's argument count falls strictly between the smallest min and
    /// largest max overload arity yet matches no individual overload by
    /// arity. Returns null otherwise (a generic TS2769 is then emitted).
    ///
    /// Mirrors upstream `getArgumentArityError`: `max_below` is the
    /// largest overload min-arity strictly below the call's count;
    /// `min_above` is the smallest overload max-arity strictly above it.
    /// Conservative ÃÂ¢ÃÂÃÂ skipped when any overload could accept the count by
    /// arity (the failure is then type-driven, not arity-driven), when a
    /// spread argument is present, or when an unbounded rest overload
    /// exists (no finite upper bound).
    fn overloadArityError(
        self: *Checker,
        call_node: NodeId,
        overloads: []const TypeId,
        args: []const NodeId,
    ) ?struct { arg_count: usize, max_below: usize, min_above: usize } {
        if (overloads.len < 2) return null;
        for (args) |arg| {
            if (self.hir.kindOf(arg) == .spread) return null;
        }
        const arg_count = args.len;
        var min_count: usize = std.math.maxInt(usize); // smallest min-arity
        var max_count: usize = 0; // largest max-arity
        var max_below: ?usize = null; // largest min-arity < arg_count
        var min_above: ?usize = null; // smallest max-arity > arg_count
        for (overloads) |sig| {
            const a = self.signatureArity(sig, call_node);
            // An unbounded rest overload has no finite upper bound ÃÂ¢ÃÂÃÂ bail.
            const sig_max = a.max orelse return null;
            // If any overload's arity range admits the call count, the
            // resolution failure is type-driven, not arity-driven.
            if (arg_count >= a.min and arg_count <= sig_max) return null;
            if (a.min < min_count) min_count = a.min;
            if (sig_max > max_count) max_count = sig_max;
            if (a.min < arg_count) {
                if (max_below == null or a.min > max_below.?) max_below = a.min;
            }
            if (sig_max > arg_count) {
                if (min_above == null or sig_max < min_above.?) min_above = sig_max;
            }
        }
        // TS2575 only when the count is strictly between the overall
        // smallest and largest arity, and we found both neighbours.
        if (!(min_count < arg_count and arg_count < max_count)) return null;
        const mb = max_below orelse return null;
        const ma = min_above orelse return null;
        return .{ .arg_count = arg_count, .max_below = mb, .min_above = ma };
    }

    fn signatureTypeArgCount(self: *Checker, sig: TypeId) usize {
        const type_params = self.generic_signature_params.get(sig) orelse return 0;
        return type_params.len;
    }

    fn signatureTypeArgCountMatches(self: *Checker, sig: TypeId, arg_count: usize) bool {
        return self.signatureTypeArgCount(sig) == arg_count;
    }

    fn overloadTypeArgCountMatchesAny(self: *Checker, overloads: []const TypeId, arg_count: usize) bool {
        for (overloads) |sig| {
            if (self.signatureTypeArgCountMatches(sig, arg_count)) return true;
        }
        return false;
    }

    fn overloadTypeArgArityError(
        self: *Checker,
        overloads: []const TypeId,
        arg_count: usize,
    ) ?struct { arg_count: usize, max_below: usize, min_above: usize } {
        if (overloads.len < 2) return null;
        var min_count: usize = std.math.maxInt(usize);
        var max_count: usize = 0;
        var max_below: ?usize = null;
        var min_above: ?usize = null;
        for (overloads) |sig| {
            const count = self.signatureTypeArgCount(sig);
            if (count == arg_count) return null;
            if (count < min_count) min_count = count;
            if (count > max_count) max_count = count;
            if (count < arg_count) {
                if (max_below == null or count > max_below.?) max_below = count;
            }
            if (count > arg_count) {
                if (min_above == null or count < min_above.?) min_above = count;
            }
        }
        if (!(min_count < arg_count and arg_count < max_count)) return null;
        const mb = max_below orelse return null;
        const ma = min_above orelse return null;
        return .{ .arg_count = arg_count, .max_below = mb, .min_above = ma };
    }

    fn callArityFitsSignature(self: *Checker, call_node: NodeId, sig: TypeId, args: []const NodeId) bool {
        const param_ts = self.interner.signatureParams(sig);
        const is_variadic = self.rest_signatures.contains(sig) and param_ts.len > 0;
        const fixed_count: usize = if (is_variadic) param_ts.len - 1 else param_ts.len;
        const rest_min_required: usize = if (is_variadic) self.tupleRestMinRequiredCount(param_ts[param_ts.len - 1]) else 0;
        const fixed_min_required = @min(self.signatureMinRequiredArgsForCall(sig, param_ts, call_node), fixed_count);
        const min_required: usize = fixed_min_required + rest_min_required;
        var effective_min_count: usize = 0;
        for (args) |arg| {
            if (self.hir.kindOf(arg) == .spread) {
                effective_min_count += 1;
            } else {
                effective_min_count += 1;
            }
        }
        const rest_max_count: ?usize = if (is_variadic) blk: {
            // Union-tuple rest parameters fold their MAX element count
            // across branches; a single fixed tuple is just its length.
            if (self.restTupleMaxCount(param_ts[param_ts.len - 1])) |len| {
                break :blk fixed_count + len;
            }
            break :blk null;
        } else null;
        const too_few = effective_min_count < min_required;
        const too_many = if (is_variadic)
            (if (rest_max_count) |max_count| effective_min_count > max_count else false)
        else
            args.len > param_ts.len;
        return !(too_few or too_many);
    }

    fn spreadArgArityContribution(self: *Checker, arg_t: TypeId) usize {
        if (self.fixedTupleLength(arg_t)) |len| {
            return @as(usize, @intCast(len));
        }
        const fixed_prefix = self.tupleFixedPrefixCount(arg_t);
        return @max(fixed_prefix, 1);
    }

    fn firstExcessArgStartPos(self: *Checker, args: []const NodeId, arg_types: []const TypeId, max_count: usize) ?u32 {
        var consumed: usize = 0;
        for (args, 0..) |arg, i| {
            const contribution: usize = if (self.hir.kindOf(arg) == .spread)
                self.spreadArgArityContribution(arg_types[i])
            else
                1;
            if (consumed >= max_count or consumed + contribution > max_count) {
                return self.hir.spanOf(arg).start;
            }
            consumed += contribution;
        }
        return null;
    }

    fn firstExcessArgIsNonTupleSpread(self: *Checker, args: []const NodeId, arg_types: []const TypeId, max_count: usize) bool {
        return self.firstExcessNonTupleSpreadArg(args, arg_types, max_count) != null;
    }

    fn firstExcessNonTupleSpreadArg(self: *Checker, args: []const NodeId, arg_types: []const TypeId, max_count: usize) ?NodeId {
        var consumed: usize = 0;
        for (args, 0..) |arg, i| {
            const contribution: usize = if (self.hir.kindOf(arg) == .spread)
                self.spreadArgArityContribution(arg_types[i])
            else
                1;
            if (consumed >= max_count or consumed + contribution > max_count) {
                if (self.hir.kindOf(arg) == .spread and !self.isTupleShapedTarget(arg_types[i])) return arg;
                return null;
            }
            consumed += contribution;
        }
        return null;
    }

    fn callHasNonTupleSpread(self: *Checker, args: []const NodeId, arg_types: []const TypeId) bool {
        for (args, 0..) |arg, i| {
            if (self.hir.kindOf(arg) == .spread and !self.isTupleShapedTarget(arg_types[i])) return true;
        }
        return false;
    }

    fn fixedSpreadNeedsTupleDiagnostic(
        self: *Checker,
        arg_t: TypeId,
        param_ts: []const TypeId,
        start_i: usize,
        fixed_count: usize,
        min_required: usize,
    ) bool {
        if (self.isTupleShapedTarget(arg_t)) return false;
        if (start_i >= fixed_count) return true;
        if (start_i < min_required) return true;
        if (start_i >= min_required) return false;
        const elem_t = self.interner.objectNumberIndex(arg_t);
        if (elem_t == types.Primitive.none) return true;
        var i = start_i;
        while (i < min_required and i < fixed_count) : (i += 1) {
            var param_t = param_ts[i];
            if (param_t >= self.interner.pool.typeCount()) continue;
            if (self.interner.pool.flagsOf(param_t).is_type_parameter) {
                param_t = self.scalarTypeParameterConstraint(param_t) orelse continue;
            }
            if (!(self.engine.isAssignableTo(elem_t, param_t) catch false)) return false;
        }
        return true;
    }

    fn fixedParamPositionBeforeArg(self: *Checker, args: []const NodeId, arg_types: []const TypeId, arg_index: usize) usize {
        var consumed: usize = 0;
        var i: usize = 0;
        while (i < arg_index and i < args.len) : (i += 1) {
            consumed += if (self.hir.kindOf(args[i]) == .spread)
                self.spreadArgArityContribution(arg_types[i])
            else
                1;
        }
        return consumed;
    }

    fn tupleRestTailElementType(self: *Checker, tuple_t: TypeId) TypeId {
        var rest_t = self.interner.objectNumberIndex(tuple_t);
        if (rest_t == types.Primitive.none) return types.Primitive.none;
        const fixed_prefix = self.tupleFixedPrefixCount(tuple_t);
        var i: usize = 0;
        while (i < fixed_prefix) : (i += 1) {
            const elem_t = self.tupleElementType(tuple_t, i);
            if (elem_t == types.Primitive.none) continue;
            rest_t = self.subtractType(rest_t, elem_t) catch rest_t;
            if (rest_t == types.Primitive.never or rest_t == types.Primitive.none) return self.interner.objectNumberIndex(tuple_t);
        }
        return rest_t;
    }

    fn directCalleePatternParam(self: *Checker, call_node: NodeId, value_param_index: usize) ?NodeId {
        if (call_node == hir_mod.none_node_id) return null;
        if (self.hir.kindOf(call_node) != .call_expr) return null;
        const call = hir_mod.callOf(self.hir, call_node);
        if (call.callee == hir_mod.none_node_id) return null;
        const callee_kind = self.hir.kindOf(call.callee);
        if (callee_kind != .arrow_fn and callee_kind != .fn_expr) return null;

        var seen_value_params: usize = 0;
        for (hir_mod.fnParams(self.hir, call.callee)) |param_node| {
            if (self.hir.kindOf(param_node) != .parameter) continue;
            if (self.isThisParameter(param_node)) continue;
            if (seen_value_params == value_param_index) {
                const p = hir_mod.parameterOf(self.hir, param_node);
                if (p.name == hir_mod.none_node_id) return null;
                const nk = self.hir.kindOf(p.name);
                if (nk == .array_pattern or nk == .object_pattern) return p.name;
                return null;
            }
            seen_value_params += 1;
        }
        return null;
    }

    /// Shared arg / signature checker used by both `call_expr` and
    /// `new_expr`. Emits TS2554 (count mismatch) and TS2345 (per-arg
    /// type mismatch) against `sig`'s parameter list. Type-parameter
    /// slots are skipped ÃÂ¢ÃÂÃÂ full instantiation lives in
    /// `instantiateReturn`.
    fn checkArgsAgainstSignature(
        self: *Checker,
        call_node: NodeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        sig: TypeId,
    ) CheckError!void {
        return self.checkArgsAgainstSignatureWithMode(
            call_node,
            args,
            arg_types,
            sig,
            false,
        );
    }

    fn checkArgsAgainstSignatureWithMode(
        self: *Checker,
        call_node: NodeId,
        args: []const NodeId,
        arg_types: []const TypeId,
        sig: TypeId,
        union_composite: bool,
    ) CheckError!void {
        const param_ts = self.interner.signatureParams(sig);
        const is_variadic = self.rest_signatures.contains(sig) and param_ts.len > 0;
        // For rest signatures, the trailing slot accepts any number of
        // args (including zero), each typed against the array-element
        // type. Required-arg count drops the rest slot and trims
        // trailing optional/defaulted params (typed as `T | undefined`
        // by the signature pass, matching tsc's call-site behavior).
        const fixed_count: usize = if (is_variadic) param_ts.len - 1 else param_ts.len;
        const rest_min_required: usize = if (is_variadic) self.tupleRestMinRequiredCount(param_ts[param_ts.len - 1]) else 0;
        const fixed_min_required = @min(self.signatureMinRequiredArgsForCall(sig, param_ts, call_node), fixed_count);
        const min_required: usize = fixed_min_required + rest_min_required;
        var effective_min_count: usize = 0;
        for (args, 0..) |arg, arg_i| {
            if (self.hir.kindOf(arg) == .spread) {
                effective_min_count += self.spreadArgArityContribution(arg_types[arg_i]);
            } else {
                effective_min_count += 1;
            }
        }
        const effective_count = effective_min_count;
        const rest_max_count: ?usize = if (is_variadic) blk: {
            // Union-tuple rest parameters fold their MAX element count
            // across branches; a single fixed tuple is just its length.
            if (self.restTupleMaxCount(param_ts[param_ts.len - 1])) |len| {
                break :blk fixed_count + len;
            }
            break :blk null;
        } else null;
        const too_few = effective_min_count < min_required;
        const too_many = if (is_variadic)
            (if (rest_max_count) |max_count| effective_min_count > max_count else false)
        else
            effective_count > param_ts.len;
        const suppress_too_many_for_array_spread = too_many and self.firstExcessArgIsNonTupleSpread(args, arg_types, if (is_variadic) (rest_max_count orelse param_ts.len) else param_ts.len);
        const suppress_too_few_for_array_spread = too_few and self.callHasNonTupleSpread(args, arg_types);
        const whole_rest_relation = if (is_variadic)
            try self.checkWholeRestArgumentList(
                call_node,
                args,
                arg_types,
                sig,
                param_ts,
                fixed_count,
            )
        else
            RestCallRelation.not_applicable;
        if (whole_rest_relation == .reported) return;
        if ((too_few and !suppress_too_few_for_array_spread) or (too_many and !suppress_too_many_for_array_spread)) {
            const fixed_variadic_count = is_variadic and rest_max_count != null;
            // tsc renders the "Expected at least N arguments" form
            // (TS2555) for variadic-too-few and the "Expected N or
            // more arguments" form (TS2554) for non-variadic-too-few
            // with optionals; the two diverged in TS 2.0 to give
            // overload diagnostics a distinct discriminator.
            const use_at_least_form = is_variadic and too_few and !fixed_variadic_count;
            // A finite-max variadic signature whose accepted arity is a
            // RANGE (min < max — e.g. a union-tuple rest like
            // `...args: [string] | [number, boolean]`, where x + the
            // shorter branch allows 2 args and the longer branch allows
            // 3) renders the `N-M` range form on too-few, matching
            // tsc's `getArgumentArityError`. Without this the message
            // wrongly printed only the upper bound ("Expected 3").
            const use_variadic_range_form = fixed_variadic_count and (too_few or too_many) and min_required < rest_max_count.?;
            const use_range_form = !is_variadic and too_few and min_required < param_ts.len;
            const expected_label: []const u8 = if (use_range_form or use_variadic_range_form or fixed_variadic_count)
                ""
            else if (is_variadic)
                " or more"
            else if (min_required == param_ts.len)
                ""
            else
                " or fewer";
            const expected_n: usize = if (use_range_form) min_required else if (use_variadic_range_form) min_required else if (fixed_variadic_count) rest_max_count.? else if (is_variadic) min_required else param_ts.len;
            const range_hi: usize = if (use_variadic_range_form) rest_max_count.? else param_ts.len;
            const is_promise_resolve_void_arity = too_few and
                !is_variadic and
                expected_n == 1 and
                effective_count == 0 and
                param_ts.len > 0 and
                !self.parameterTypeAllowsVoidOmission(param_ts[0]) and
                self.callIsPromiseConstructorResolve(call_node);
            const is_js_promise_resolve_void_arity = is_promise_resolve_void_arity and self.virtualSectionIsJsLike(call_node);
            const msg = if (is_js_promise_resolve_void_arity)
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Expected 1 argument, but got 0. 'new Promise()' needs a JSDoc hint to produce a 'resolve' that can be called without arguments.",
                    .{},
                )
            else if (is_promise_resolve_void_arity)
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Expected 1 arguments, but got 0. Did you forget to include 'void' in your type argument to 'Promise'?",
                    .{},
                )
            else if (use_at_least_form)
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Expected at least {d} arguments, but got {d}.",
                    .{ expected_n, effective_count },
                )
            else if (use_range_form or use_variadic_range_form)
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Expected {d}-{d} arguments, but got {d}.",
                    .{ expected_n, range_hi, effective_count },
                )
            else
                try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Expected {d}{s} arguments, but got {d}.",
                    .{ expected_n, expected_label, effective_count },
                );
            // tsc anchors a too-many TS2554 on the first excess
            // argument when one exists (matches `genericRestArity`,
            // `genericRestArityStrict` and similar). Too-few is
            // usually anchored on the call expression itself, except
            // method calls (`obj.m()`) where upstream points at the
            // member name.
            var anchor_pos: ?u32 = null;
            if (too_many) {
                const first_excess_count: usize = if (fixed_variadic_count)
                    rest_max_count.?
                else if (is_variadic)
                    min_required
                else
                    param_ts.len;
                anchor_pos = self.firstExcessArgStartPos(args, arg_types, first_excess_count);
            } else if (too_few) {
                anchor_pos = self.tooFewArgsAnchorPos(call_node);
            }
            const related = if (too_few)
                try self.missingArgumentRelatedInfo(sig, effective_count)
            else
                &.{};
            try self.diagnostics.append(self.gpa, .{
                .node = call_node,
                .pos = anchor_pos,
                .code = if (is_js_promise_resolve_void_arity)
                    TsCodes.expected_one_argument_promise_jsdoc_hint
                else if (is_promise_resolve_void_arity)
                    TsCodes.expected_n_arguments_promise_void_hint
                else if (use_at_least_form)
                    TsCodes.expected_at_least_n_arguments
                else
                    TsCodes.expected_n_arguments,
                .message = msg,
                .related = related,
            });
            if (too_few and self.hir.kindOf(call_node) == .new_expr) return;
        } else if (too_many and suppress_too_many_for_array_spread and !is_variadic) {
            if (self.firstExcessNonTupleSpreadArg(args, arg_types, param_ts.len)) |spread_arg| {
                try self.report(spread_arg, TsCodes.spread_argument_requires_tuple_or_rest, "A spread argument must either have a tuple type or be passed to a rest parameter.");
            }
        }
        // A rest parameter typed exactly `never` (e.g.
        // `(...args: never) => void`, the #48840 repro) accepts no
        // arguments: tsc synthesizes the rest-args tuple and checks it
        // against `never`, which always fails since no tuple ÃÂ¢ÃÂÃÂ not even
        // `[]` ÃÂ¢ÃÂÃÂ is assignable to `never`. Anchor TS2345 on the call.
        if (is_variadic and !too_few and !too_many and
            param_ts[param_ts.len - 1] == types.Primitive.never)
        {
            if (try self.restArgsTupleDisplay(args, arg_types, fixed_count)) |tuple_text| {
                const msg = try std.fmt.allocPrint(
                    self.diag_arena.allocator(),
                    "Argument of type '{s}' is not assignable to parameter of type 'never'.",
                    .{tuple_text},
                );
                try self.diagnostics.append(self.gpa, .{
                    .node = call_node,
                    .code = TsCodes.argument_type_mismatch,
                    .message = msg,
                });
            }
        }
        if (is_variadic and whole_rest_relation != .satisfied and !too_few and !too_many) {
            if (try self.tryReportRestTupleAnnotationCallWidthMismatch(call_node, args, arg_types, sig, fixed_count)) return;
            if (try self.tryReportConstrainedRestTupleAnnotationCallMismatch(args, arg_types, sig, fixed_count)) return;
            if (try self.restTupleAnnotationCallSatisfied(args, arg_types, sig, fixed_count)) return;
        }
        // Fixed-position pairs.
        const npairs_fixed = @min(args.len, fixed_count);
        var i: usize = 0;
        var emitted_spread_shape_mismatch = false;
        var stop_after_new_arg_mismatch = false;
        var stop_after_arg_mismatch = false;
        while (i < npairs_fixed) : (i += 1) {
            if (stop_after_new_arg_mismatch or stop_after_arg_mismatch) break;
            if (self.argAlreadyHasArgumentMismatchDiagnostic(args[i])) {
                stop_after_arg_mismatch = true;
                continue;
            }
            const fixed_pos = self.fixedParamPositionBeforeArg(args, arg_types, i);
            if (fixed_pos >= fixed_count) continue;
            if (try self.polymorphicThisIndexedMemberArgumentAssignable(
                call_node,
                sig,
                args,
                arg_types,
                i,
                fixed_pos,
            )) continue;
            var param_t = param_ts[fixed_pos];
            if (param_t >= self.interner.pool.typeCount()) continue;
            const declared_param_predicate = self.signature_param_predicates.get(.{
                .signature = sig,
                .param_index = @intCast(fixed_pos),
            });
            var constrained_type_parameter_target: ?TypeId = null;
            if (self.taggedTemplateStringsArrayArg(call_node, args, i, param_t)) continue;
            if (self.interner.pool.flagsOf(param_t).is_type_parameter and
                !self.interner.pool.flagsOf(param_t).is_union and
                !self.interner.pool.flagsOf(param_t).is_intersection and
                !self.isThisTypeParameter(param_t))
            {
                if (try self.conditionalTypeParameterConstraintForArgument(param_t, arg_types[i])) |constraint_target| {
                    param_t = constraint_target;
                    constrained_type_parameter_target = param_t;
                } else {
                    param_t = self.scalarTypeParameterConstraint(param_t) orelse {
                        if ((arg_types[i] == types.Primitive.null_t or
                            arg_types[i] == types.Primitive.undefined_t or
                            arg_types[i] == types.Primitive.void_t) and
                            !self.signatureOwnsTypeParameter(sig, param_t) and
                            (self.strict_flags.strict_null_checks or self.unconstrainedTypeParameter(param_t)) and
                            !try self.newExpressionTypeArgsReferenceVisibleStaticClassTypeParam(call_node))
                        {
                            const msg = if (try self.formatNullishLiteralArgumentNotAssignable(args[i], param_t)) |literal_msg|
                                literal_msg
                            else
                                try self.formatArgumentNotAssignable(arg_types[i], param_t, i);
