test "checker: too-few argument diagnostics carry missing-parameter related info" {
    const b = try newBoundSetup(
        \\function named(a: number): void {}
        \\function binding({ x }: { x: number }): void {}
        \\function rest(...items: [number]): void {}
        \\named();
        \\binding();
        \\rest();
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);

    var saw_6210 = false;
    var saw_6211 = false;
    var saw_6236 = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.expected_n_arguments and
            d.code != TsCodes.expected_at_least_n_arguments) continue;
        for (d.related) |r| {
            switch (r.code) {
                TsCodes.argument_for_parameter_not_provided => {
                    saw_6210 = true;
                    try T.expectEqualStrings("An argument for 'a' was not provided.", r.message);
                },
                TsCodes.argument_for_binding_pattern_not_provided => {
                    saw_6211 = true;
                    try T.expectEqualStrings("An argument matching this binding pattern was not provided.", r.message);
                },
                TsCodes.arguments_for_rest_parameter_not_provided => {
                    saw_6236 = true;
                    try T.expectEqualStrings("Arguments for the rest parameter 'items' were not provided.", r.message);
                },
                else => {},
            }
        }
    }
    try T.expect(saw_6210);
    try T.expect(saw_6211);
    try T.expect(saw_6236);
}

test "checker: intersection source assigned to weak target emits TS2559" {
    // Mirrors intersectionAsWeakTypeSource.ts(8,7): `XY = X & Y` (an
    // intersection of two object types, none of whose members overlap
    // the weak target `Z = { z?: boolean }`) is assigned to `Z`. tsc
    // surfaces TS2559 ("no properties in common"), because the target
    // is a weak type (all members optional, no index/call/construct
    // signatures) and the source shares no property name with it.
    const b = try newBoundSetup(
        \\interface X { x: string }
        \\interface Y { y: number }
        \\interface Z { z?: boolean }
        \\type XY = X & Y;
        \\const xy: XY = {x: 'x', y: 10};
        \\const z1: Z = xy;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    var found = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.no_properties_in_common and
            std.mem.indexOf(u8, d.message, "Type 'XY' has no properties in common with type 'Z'.") != null)
            found = true;
    }
    if (!found) {
        std.debug.print("expected TS2559 for intersection source assigned to weak target; diagnostics:\n", .{});
        for (b.base.checker.diagnostics.items) |d| {
            std.debug.print("  TS{d}: {s}\n", .{ d.code, d.message });
        }
    }
    try T.expect(found);
}

