test "checker: generic function expression type parameter is in scope for its own params" {
    // Mirrors functionConstraintSatisfaction.ts (line 44) and
    // functionConstraintSatisfaction3.ts (line 40): a generic function
    // *expression* `function <U>(x: U) { ... }` passed as a call argument.
    // The type parameter `U` declared on the function expression must be in
    // scope when resolving its own parameter annotation `x: U`. tsc emits no
    // diagnostics for these fixtures, so we must not spuriously raise TS2304.
    const cases = [_][]const u8{
        // functionConstraintSatisfaction.ts line 44 (generic callee).
        "function foo<T extends Function>(x: T): T { return x; }\nvar r10 = foo(function <U>(x: U) { return x; });",
        // functionConstraintSatisfaction3.ts line 40 (function-type constraint).
        "function foo<T extends (x: string) => string>(x: T): T { return x; }\nvar r9 = foo(function <U>(x: U) { return x; });",
        // Generic arrow argument variant.
        "function foo<T extends Function>(x: T): T { return x; }\nvar r = foo(<U>(x: U) => x);",
        // Non-generic callee with a generic function-expression argument.
        "function bar(x: any) {}\nvar r = bar(function <U>(x: U) { return x; });",
        // Standalone forms (must keep working).
        "var f = function <U>(x: U) { return x; };",
        "var g = <U>(x: U) => x;",
    };
    for (cases) |src| {
        const b = try newBoundSetup(src);
        defer destroyBoundSetup(b);
        try b.base.checker.checkSourceFile(b.base.root);
        for (b.base.checker.diagnostics.items) |d| {
            if (d.code == TsCodes.cannot_find_name and std.mem.indexOf(u8, d.message, "'U'") != null) {
                std.debug.print("unexpected TS2304 for 'U' in: {s}\n", .{src});
                try T.expect(false);
            }
        }
    }
}

test "checker: Function constraints accept callable and constructable arguments" {
    const b = try newBoundSetup(
        \\function accept<T extends Function>(value: T): T { return value; }
        \\interface Callable { (): string; }
        \\declare const callable: Callable;
        \\declare const constructable: { new (): string };
        \\class C { value = ""; }
        \\accept(callable);
        \\accept(constructable);
        \\accept(C);
        \\accept<Callable>(callable);
        \\accept<{ new (): string }>(constructable);
        \\function forward<T extends { (): void }, U extends T>(x: T, y: U) {
        \\    accept(x);
        \\    accept(y);
        \\}
        \\accept(1);
        \\accept({});
        \\function narrow<T extends (x: string) => string>(value: T): T { return value; }
        \\narrow(constructable);
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expectEqual(@as(usize, 3), checkerCountCode(b.base, TsCodes.argument_type_mismatch));
}

test "checker: Function constraint failures keep upstream call diagnostics" {
    const b = try newBoundSetup(
        \\function accept<T extends Function>(value: T): T { return value; }
        \\accept(1);
        \\accept(1, () => {});
        \\function narrow<T extends (x: string) => string>(value: T): T { return value; }
        \\declare const broad: Function;
        \\class C { value = ""; }
        \\declare const constructable: { new (x: string): string };
        \\interface F2 extends Function { value: string; }
        \\declare const f2: F2;
        \\narrow(broad);
        \\narrow(new Function());
        \\narrow(C);
        \\narrow(constructable);
        \\narrow(f2);
        \\function forward<T extends { (): void }, U extends T>(x: T, y: U) {
        \\    narrow(x);
        \\    narrow(y);
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expectEqual(@as(usize, 8), checkerCountCode(b.base, TsCodes.argument_type_mismatch));
    try T.expectEqual(@as(usize, 1), checkerCountCode(b.base, TsCodes.expected_n_arguments));
    try T.expect(checkerHasCodeAndMessage(
        b.base,
        TsCodes.argument_type_mismatch,
        "Argument of type 'number' is not assignable to parameter of type 'Function'.",
    ));
    const call_target = "(x: string) => string";
    const expected_sources = [_][]const u8{ "Function", "typeof C", "new (x: string) => string", "F2", "T", "U" };
    for (expected_sources) |source| {
        const message = try std.fmt.allocPrint(
            T.allocator,
            "Argument of type '{s}' is not assignable to parameter of type '{s}'.",
            .{ source, call_target },
        );
        defer T.allocator.free(message);
        try T.expect(checkerHasCodeAndMessage(b.base, TsCodes.argument_type_mismatch, message));
    }
}

