test "checker: async iterator source without next adds TS2519 related info" {
    const s = try newSetup(
        \\class AsyncSymbolIterator {
        \\    [Symbol.asyncIterator]() { return this; }
        \\}
        \\async function f() {
        \\  for await (const v of new AsyncSymbolIterator()) { }
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .isolated_modules = true });
    try s.checker.checkSourceFile(s.root);
    var primary_count: usize = 0;
    var related_count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.async_iterator_required) continue;
        primary_count += 1;
        for (d.related) |rel| {
            if (rel.code == TsCodes.async_iterator_next_missing and
                std.mem.eql(u8, rel.message, "An async iterator must have a 'next()' method."))
            {
                related_count += 1;
            }
        }
    }
    try T.expectEqual(@as(usize, 1), primary_count);
    try T.expectEqual(@as(usize, 1), related_count);
}

