        \\      name?: string,
        \\      f?: (bench?: { (): void; }) => void
        \\    ) => void;
        \\    timeFunction = function (
        \\      benchmark: Benchmark,
        \\      description: string = benchmark.description,
        \\      name: string = '',
        \\      f = benchmark.bench
