test "checker: object-shape renderer keeps declared index parameter name" {
    // `allocObjectTypeShapeOpts` renders an object type that has BOTH
    // an index signature and named members (`{ [key: string]: number;
    // foo: number; }`). Before the fix it hardcoded `[x: ...]`; now it
    // consults the declared index-parameter name via `indexParamName`,
    // matching `getNameFromIndexInfo`.
    const s = try newSetup(
        \\let m: { [key: string]: number; foo: number } = 42;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw = false;
    var saw_x = false;
    for (s.checker.diagnostics.items) |d| {
