        if (std.mem.indexOf(u8, d.message, "[key: string]: number") != null) saw = true;
        if (std.mem.indexOf(u8, d.message, "[x: string]") != null) saw_x = true;
    }
    try T.expect(saw);
    try T.expect(!saw_x);
}

