        \\    constructor(x: number) {
        \\    }
        \\}
        \\
        \\class B {
        \\    private a = x;
        \\    private b = { p: x };
        \\    private c = () => x;
        \\    constructor() {
        \\        var x = 1;
        \\    }
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
