test "checker: import = require of a non-module script emits TS2306" {
    // Mirrors `requireOfAnEmptyFile1` / `importNonExternalModule`: the
    // target file resolves but is a plain script (a bare `namespace`,
    // no top-level import/export), so it is not an external module.
    // The `{0}` slot renders the RESOLVED file name with its extension.
    const s = try newSetup(
        \\// @filename: foo_0.ts
        \\namespace foo {
        \\    export var answer = 42;
        \\}
        \\// @filename: foo_1.ts
        \\import foo = require("./foo_0");
        \\foo;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.file_is_not_a_module and
            std.mem.eql(u8, d.message, "File 'foo_0.ts' is not a module."))
            found = true;
        // The non-module file must not also surface TS2307.
        try T.expect(d.code != TsCodes.cannot_find_module);
    }
    if (!found) {
        std.debug.print("expected TS2306 for import = require of non-module; diagnostics:\n", .{});
        for (s.checker.diagnostics.items) |d| {
            std.debug.print("  TS{d}: {s}\n", .{ d.code, d.message });
        }
    }
    try T.expect(found);
}

test "checker: side-effect import of global declaration script skips TS2306" {
    // React's `jsx-runtime.d.ts` side-effect imports `./` to pull in
    // global JSX declarations from `index.d.ts`; it does not request
    // module exports, so a script-style declaration target is valid.
    const s = try newSetup(
        \\// @filename: node_modules/@types/react/index.d.ts
        \\declare namespace JSX {
        \\    interface IntrinsicElements { div: any; }
        \\}
        \\// @filename: node_modules/@types/react/jsx-runtime.d.ts
        \\import "./";
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.file_is_not_a_module) {
            std.debug.print("unexpected TS2306 for side-effect declaration import: {s}\n", .{d.message});
            try T.expect(false);
        }
    }
}

