test "checker: circular import alias chain emits TS2303" {
    // `import a = b; import b = a;` forms a cycle of import aliases that
    // resolves back to itself. Upstream tsc surfaces TS2303 at the alias
    // declaration with the alias name in the `{0}` slot.
    const b = try newBoundSetup(
        \\import a = b;
        \\import b = a;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    var found = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.circular_import_alias and
            std.mem.indexOf(u8, d.message, "Circular definition of import alias '") != null)
            found = true;
    }
    if (!found) {
        std.debug.print("expected TS2303 for circular import alias; diagnostics:\n", .{});
        for (b.base.checker.diagnostics.items) |d| {
            std.debug.print("  TS{d}: {s}\n", .{ d.code, d.message });
        }
    }
    try T.expect(found);
}

test "checker: non-circular import alias chain stays clean (no TS2303)" {
    // Negative: `import b = ns; import a = b;` terminates at a real
    // namespace, so no cycle exists and TS2303 must not fire.
    const bset = try newBoundSetup(
        \\namespace ns { export const x = 1; }
        \\import b = ns;
        \\import a = b;
        \\a.x;
    );
    defer destroyBoundSetup(bset);
    try bset.base.checker.checkSourceFile(bset.base.root);
    for (bset.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.circular_import_alias) {
            std.debug.print("unexpected TS2303 for non-circular alias chain: {s}\n", .{d.message});
            try T.expect(false);
        }
    }
}

test "checker: circular type-only re-export emits one TS2303 at the closing alias" {
    const b = try newBoundSetup(
        \\// @filename: /a.ts
        \\export type { A } from './b';
        \\// @filename: /b.ts
        \\export type { A } from './a';
