test "checker: equality against NaN emits TS2845 with Number.isNaN related info" {
    const b = try newBoundSetup("declare const x: number; x === NaN;");
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    var saw_2845 = false;
    var saw_1369 = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.condition_always_returns) continue;
        saw_2845 = true;
        try T.expectEqualStrings("This condition will always return 'false'.", d.message);
        for (d.related) |rel| {
            if (rel.code == TsCodes.did_you_mean_0 and
                std.mem.eql(u8, rel.message, "Did you mean 'Number.isNaN(x)'?"))
            {
                saw_1369 = true;
            }
        }
    }
    try T.expect(saw_2845);
    try T.expect(saw_1369);
}

