    try b.base.checker.checkSourceFile(b.base.root);
    var suggested_undefined = false;
    var plain_void = false;
    var plain_null = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.cannot_find_name_did_you_mean and
            std.mem.indexOf(u8, d.message, "Cannot find name 'Undefined'. Did you mean 'undefined'?") != null)
        {
            suggested_undefined = true;
        }
        if (d.code == TsCodes.cannot_find_name and std.mem.indexOf(u8, d.message, "'Void'") != null) plain_void = true;
        if (d.code == TsCodes.cannot_find_name and std.mem.indexOf(u8, d.message, "'Null'") != null) plain_null = true;
    }
    try T.expect(suggested_undefined);
    try T.expect(plain_void);
    try T.expect(plain_null);
}

