fn hasDiagnosticCodeMessage(s: *TestSetup, code: u32, message: []const u8) bool {
    for (s.checker.diagnostics.items) |d| {
        if (d.code == code and std.mem.eql(u8, d.message, message)) return true;
    }
    return false;
}

test "checker: TS1224 boolean signature is not assignable to predicate signature" {
    const s = try newSetup(
        \\declare const f: (x: unknown) => boolean;
        \\const g: (x: unknown) => x is string = f;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        try T.expect(std.mem.indexOf(u8, d.message, "=> x is string") != null);
        try T.expectEqual(@as(usize, 1), d.chain.len);
        if (d.chain[0].code == TsCodes.signature_must_be_type_predicate and
            std.mem.eql(u8, d.chain[0].message, "Signature '(x: unknown): boolean' must be a type predicate."))
        {
            found = true;
        }
    }
    try T.expect(found);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.signature_must_be_type_predicate));
}

test "checker: TS1226 incompatible predicate target is nested under assignment" {
    const s = try newSetup(
        \\declare const f: (x: unknown) => x is number;
        \\const g: (x: unknown) => x is string = f;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable or d.chain.len != 1) continue;
        const entry = d.chain[0];
        if (entry.code == TsCodes.type_predicate_not_assignable and
            std.mem.eql(u8, entry.message, "Type predicate 'x is number' is not assignable to 'x is string'."))
        {
            try T.expectEqual(@as(usize, 1), entry.children.len);
            try T.expectEqual(TsCodes.type_not_assignable, entry.children[0].code);
            try T.expectEqualStrings("Type 'number' is not assignable to type 'string'.", entry.children[0].message);
            found = true;
        }
    }
    try T.expect(found);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.type_predicate_not_assignable));
}

