test "checker: function expression predicate assignments use declaration metadata" {
    const s = try newSetup(
        \\class A {}
        \\let guard: (p1: any, p2: any) => p1 is A;
        \\guard = function(p1, p2): boolean { return true; };
        \\guard = function(p1, p2): p2 is A { return true; };
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.type_not_assignable));
    var saw_required_predicate = false;
    var saw_boolean_source = false;
    var saw_position_mismatch = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable or d.chain.len != 1) continue;
        if (d.chain[0].code == TsCodes.signature_must_be_type_predicate) {
            saw_required_predicate = true;
            saw_boolean_source = std.mem.indexOf(u8, d.message, "=> boolean'") != null;
        }
        if (d.chain[0].code == TsCodes.type_predicate_not_assignable and
            d.chain[0].children.len == 1 and
            d.chain[0].children[0].code == TsCodes.type_predicate_parameter_position_mismatch)
        {
            saw_position_mismatch = true;
        }
    }
    try T.expect(saw_required_predicate);
    try T.expect(saw_boolean_source);
    try T.expect(saw_position_mismatch);
}

