test "checker: TS2518 this predicate kind mismatch is nested under TS1226" {
    const s = try newSetup(
        \\declare const f: () => this is string;
        \\const g: (x: unknown) => x is string = f;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable or d.chain.len != 1) continue;
        const entry = d.chain[0];
        if (entry.code == TsCodes.type_predicate_not_assignable and
            std.mem.eql(u8, entry.message, "Type predicate 'this is string' is not assignable to 'x is string'."))
        {
            try T.expectEqual(@as(usize, 1), entry.children.len);
            try T.expectEqual(TsCodes.this_type_guard_not_parameter_type_guard, entry.children[0].code);
            try T.expectEqualStrings("A 'this'-based type guard is not compatible with a parameter-based type guard.", entry.children[0].message);
            found = true;
        }
    }
    try T.expect(found);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.this_type_guard_not_parameter_type_guard));
}

