test "checker: loose typeof branch vars retain flow types and hoist scope" {
    const s = try newSetup(
        \\class C { private p: string; }
        \\declare var value: string | number;
        \\if (typeof value == "string") {
        \\    var result = value;
        \\} else {
        \\    var result = value;
        \\}
        \\if (typeof value == "Object") {}
        \\declare var objectValue: string | C;
        \\if (typeof objectValue == "Object") {
        \\    var objectResult = objectValue;
        \\} else {
        \\    var objectResult = objectValue;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    const stmts = hir_mod.blockStmts(&s.hir, s.root);
    const if_stmt = stmts[2];
    const branch = hir_mod.ifOf(&s.hir, if_stmt);
    const then_decl = hir_mod.blockStmts(&s.hir, branch.then_branch)[0];
    const else_decl = hir_mod.blockStmts(&s.hir, branch.else_branch)[0];
    const then_init = hir_mod.varDeclOf(&s.hir, then_decl).init;
    const else_init = hir_mod.varDeclOf(&s.hir, else_decl).init;
    try T.expectEqual(types.Primitive.string_t, s.hir.typeOf(then_init));
    try T.expectEqual(types.Primitive.number_t, s.hir.typeOf(else_init));
    try T.expectEqual(s.checker.enclosingVarDeclScope(then_decl), s.checker.enclosingVarDeclScope(else_decl));
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.subsequent_var_type_mismatch));
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.no_overlap_comparison));
}

