test "checker: inferred `return null` return type widens to any when strict-null is off" {
    // tsc's `getWidenedType` collapses a bare `return null;` inferred
    // return type to `any` when `strictNullChecks` is disabled — so an
    // unannotated `() => null` displays/relates as `() => any`. Mirrors
    // `assignmentCompatWithGenericCallSignaturesWithOptionalParameters`.
    const s = try newSetup("function f() { return null; }");
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = false });
    try s.checker.checkSourceFile(s.root);
    const top = firstStatement(s);
    const t = s.hir.typeOf(top);
    try T.expect(s.ti.pool.flagsOf(t).is_signature);
    try T.expectEqual(types.Primitive.any, s.ti.signatureReturn(t).?);
}

