    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.object_possibly_nullish));
    try T.expectEqual(@as(usize, 3), checkerCountCode(s, TsCodes.property_does_not_exist));
    try T.expect(hasDiagnosticCodeMessage(s, TsCodes.property_does_not_exist, "Property 'global' does not exist on type 'never'."));
    try T.expect(hasDiagnosticCodeMessage(s, TsCodes.property_does_not_exist, "Property 'onChanges' does not exist on type 'C | (Validator & Partial<OnChanges>)'."));
}

test "checker: instanceof rejects non-callable object RHS operands" {
    const s = try newSetup(
        \\class C { foo() { } }
        \\declare var x: any;
        \\declare var o1: {};
        \\declare var o2: Object;
        \\declare var o3: C;
        \\x instanceof o1;
        \\x instanceof o2;
        \\x instanceof o3;
        \\"" instanceof {};
    );
    defer destroySetup(s);
