test "checker: instanceof derives constructor and has-instance targets" {
    const s = try newSetup(
        \\interface A { foo: string; }
        \\declare var AFactory: { new (): A };
        \\declare var a: A | string;
        \\if (a instanceof AFactory) { a.foo; a.missing; }
        \\interface P { fromPrototype: string; }
        \\interface Q { fromConstruct: string; }
        \\declare var PrototypeFactory: { prototype: P; new (): Q };
        \\declare var p: P | Q;
        \\if (p instanceof PrototypeFactory) { p.fromPrototype; p.fromConstruct; }
        \\interface R { fromPredicate: string; }
        \\declare var PredicateFactory: {
        \\  prototype: P;
        \\  new (): Q;
        \\  [Symbol.hasInstance](value: unknown): value is R;
        \\};
        \\declare var r: R | P | Q;
        \\if (r instanceof PredicateFactory) { r.fromPredicate; r.fromPrototype; }
        \\interface Generic<T> { value: T; }
        \\declare var GenericFactory: { new <T>(): Generic<T> };
        \\declare var generic: Generic<number> | string;
        \\if (generic instanceof GenericFactory) { generic.value = "bad"; generic.absent; }
        \\interface NoNarrow { present: string; }
        \\declare var NoNarrowFactory: { new (): any };
        \\declare var noNarrow: NoNarrow | string;
        \\if (noNarrow instanceof NoNarrowFactory) { noNarrow.present; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var missing_count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.property_does_not_exist) continue;
        missing_count += 1;
        try T.expect(std.mem.indexOf(u8, d.message, "missing") != null or
            std.mem.indexOf(u8, d.message, "fromConstruct") != null or
            std.mem.indexOf(u8, d.message, "fromPrototype") != null or
            std.mem.indexOf(u8, d.message, "absent") != null or
            std.mem.indexOf(u8, d.message, "present") != null);
    }
    try T.expectEqual(@as(usize, 5), missing_count);
    try T.expect(checkerHasCodeAndMessage(s, TsCodes.type_not_assignable, "Type 'string' is not assignable to type 'number'."));
    try T.expect(checkerHasCodeAndMessage(s, TsCodes.property_does_not_exist, "Property 'absent' does not exist on type 'Generic<number>'."));
    try T.expect(checkerHasCodeAndMessage(s, TsCodes.property_does_not_exist, "Property 'present' does not exist on type 'string | NoNarrow'."));
}

