test "checker: compound `+=` string result is assignable back to an empty-object LHS (no TS2322)" {
    // `x6 += ''` on `var x6: {}` yields `string`, which IS assignable to
    // `{}`, so tsc emits nothing. Home over-emitted TS2322 because the
    // compound-addition back-assignment accepted only string-like
    // targets instead of falling through to general assignability.
    // Mirrors `compoundAdditionAssignmentLHSCanBeAssigned`.
    const s = try newSetup(
        \\declare var x6: {};
        \\x6 += "";
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
    }
}

test "checker: compound addition reports nullish rhs where TS disallows it" {
    // Upstream tsc fires TS18050 on the literal-nullish RHS whenever
    // the LHS is concrete and not string-like: `b += null` (boolean)
    // and `n += null` (number) both produce TS18050, while `s += null`
    // (string) is silent. Mirrors `compoundAdditionAssignmentLHSCanBeAssigned`.
    const s = try newSetup(
        \\declare var b: boolean;
        \\declare var n: number;
        \\declare var s: string;
        \\b += null;
        \\n += null;
        \\s += null;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var nullish_errors: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.nullish_relational_operand) nullish_errors += 1;
    }
    try T.expectEqual(@as(usize, 2), nullish_errors);
}

