test "checker: TS1503 fires for named capture groups below ES2018 target" {
    // `// @target: es2015` is below ES2018, so each named capturing
    // group `(?<name>…)` reports TS1503 anchored at its `<`. The two
    // lookbehind assertions `(?<=…)` / `(?<!…)` are NOT named groups.
    const s = try newSetup(
        \\// @target: es2015
        \\const re = /(?<year>\d{4})-(?<month>\d{2})/;
        \\const look = /(?<=x)y(?<!z)/;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.regex_named_group_requires_target));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.regex_named_group_requires_target) {
            try T.expectEqualStrings("Named capturing groups are only available when targeting 'ES2018' or later.", d.message);
        }
    }
}

