test "checker: TS1272 fires for value-imported type-only names in decorated signatures (ESM + isolatedModules + emitDecoratorMetadata)" {
    const s = try newSetup(
        \\// @target: es2015
        \\// @experimentalDecorators: true
        \\// @emitDecoratorMetadata: true
        \\// @isolatedModules: true
        \\// @module: esnext
        \\// @Filename: type1.ts
        \\interface T1 {}
        \\export type { T1 }
        \\// @Filename: type2.ts
        \\export interface T2 {}
        \\// @Filename: class3.ts
        \\export class C3 {}
        \\// @Filename: index.ts
        \\import { T1 } from "./type1";
        \\import * as t1 from "./type1";
        \\import type { T2 } from "./type2";
        \\import { C3 } from "./class3";
        \\declare var EventListener: any;
        \\class HelloWorld {
        \\  @EventListener('1')
        \\  handleEvent1(event: T1) {}
        \\  @EventListener('2')
        \\  handleEvent2(event: T2) {}
        \\  @EventListener('1')
        \\  p1!: T1;
        \\  @EventListener('1')
        \\  p1_ns!: t1.T1;
        \\  @EventListener('2')
        \\  p2!: T2;
        \\  @EventListener('3')
        \\  handleEvent3(event: C3): T1 { return undefined!; }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var count: usize = 0;
    var all_have_t1_related = true;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_referenced_in_decorated_signature) continue;
        count += 1;
        try T.expectEqualStrings(
            "A type referenced in a decorated signature must be imported with 'import type' or a namespace import when 'isolatedModules' and 'emitDecoratorMetadata' are enabled.",
            d.message,
        );
        var saw_related = false;
        for (d.related) |rel| {
            if (rel.code == TsCodes.name_was_imported_here and std.mem.eql(u8, rel.message, "'T1' was imported here.")) saw_related = true;
        }
        if (!saw_related) all_have_t1_related = false;
    }
    // Exactly three offenders: handleEvent1's `event: T1`, `p1!: T1`, and
    // handleEvent3's `T1` return. T2 (import type), C3 (a value), and the
    // namespace form `t1.T1` are all exempt.
    try T.expectEqual(@as(usize, 3), count);
    try T.expect(all_have_t1_related);
}

