test "checker: TS1281 fires for cross-file unqualified enum member access under isolatedModules" {
    const s = try newSetup(
        \\// @isolatedModules: true
        \\// @Filename: enum1.ts
        \\enum Enum { A, B, C }
        \\declare enum Enum { X = 1000000 }
        \\// @Filename: enum2.ts
        \\enum Enum {
        \\  E = A,
        \\  Y = X,
        \\  Z = Enum.A
        \\}
        \\declare enum Enum {
        \\  F = A
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .isolated_modules = true });
    try s.checker.checkSourceFile(s.root);

    var count: usize = 0;
    var saw_a = false;
    var saw_x = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.cannot_access_from_another_file_unqualified) continue;
        count += 1;
        if (std.mem.indexOf(u8, d.message, "Use 'Enum.A' instead.") != null) saw_a = true;
        if (std.mem.indexOf(u8, d.message, "Use 'Enum.X' instead.") != null) saw_x = true;
    }
    // `E = A` and `Y = X` only. `Z = Enum.A` is qualified; `F = A` is in an
    // ambient (`declare`) enum — both exempt.
    try T.expectEqual(@as(usize, 2), count);
    try T.expect(saw_a);
    try T.expect(saw_x);
}

