test "checker: nested generic construct-signature assignment does not crash (regression)" {
    // Coverage for the signature-parameter assignability path that an
    // out-of-bounds panic was traced to: a malformed/partially-lowered
    // nested generic construct signature carried an invalid parameter
    // TypeId, which `computeSignatureAssignableWithMode` indexed into the
    // type pool. (The panic itself was layout-dependent — it tripped in the
    // full-corpus survey where prior allocations seed the `undefined` slot —
    // so this exercises the path rather than deterministically reproducing
    // the abort.) This is the conformance fixture
    // `assignmentCompatWithConstructSignatures4`.
    const s = try newSetup(
        \\namespace Errors {
        \\    class Base { foo: string; }
        \\    class Derived extends Base { bar: string; }
        \\    class Derived2 extends Derived { baz: string; }
        \\    class OtherDerived extends Base { bing: string; }
        \\    namespace WithNonGenericSignaturesInBaseType {
        \\        declare var a2: new (x: number) => string[];
        \\        declare var a7: new (x: (arg: Base) => Derived) => (r: Base) => Derived2;
        \\        declare var a8: new (x: (arg: Base) => Derived, y: (arg2: Base) => Derived) => (r: Base) => Derived;
        \\        declare var a10: new (...x: Base[]) => Base;
        \\        declare var a11: new (x: { foo: string }, y: { foo: string; bar: string }) => Base;
        \\        declare var a12: new (x: Array<Base>, y: Array<Derived2>) => Array<Derived>;
        \\        declare var a14: { new (x: number): number[]; new (x: string): string[]; };
        \\        declare var a15: new (x: { a: string; b: number }) => number;
        \\        declare var a16: {
        \\                new (x: { new (a: number): number; new (a?: number): number; }): number[];
        \\                new (x: { new (a: boolean): boolean; new (a?: boolean): boolean; }): boolean[];
        \\            };
        \\        declare var a17: {
        \\                new (x: { new <T extends Derived>(a: T): T; new <T extends Base>(a: T): T; }): any[];
        \\                new (x: { new <T extends Derived2>(a: T): T; new <T extends Base>(a: T): T; }): any[];
        \\            };
        \\        declare var b2: new <T, U>(x: T) => U[];
        \\        a2 = b2;
        \\        b2 = a2;
        \\        declare var b7: new <T extends Base, U extends Derived, V extends Derived2>(x: (arg: T) => U) => (r: T) => V;
        \\        a7 = b7;
        \\        b7 = a7;
        \\        declare var b8: new <T extends Base, U extends Derived>(x: (arg: T) => U, y: (arg2: { foo: number; }) => U) => (r: T) => U;
        \\        a8 = b8;
        \\        b8 = a8;
        \\        declare var b10: new <T extends Derived>(...x: T[]) => T;
        \\        a10 = b10;
        \\        b10 = a10;
        \\        declare var b11: new <T extends Derived>(x: T, y: T) => T;
        \\        a11 = b11;
        \\        b11 = a11;
        \\        declare var b12: new <T extends Array<Derived2>>(x: Array<Base>, y: Array<Base>) => T;
        \\        a12 = b12;
        \\        b12 = a12;
        \\        declare var b15: new <T>(x: { a: T; b: T }) => T;
        \\        a15 = b15;
        \\        b15 = a15;
        \\        declare var b15a: new <T extends Base>(x: { a: T; b: T }) => number;
        \\        a15 = b15a;
        \\        b15a = a15;
        \\        declare var b16: new <T>(x: (a: T) => T) => T[];
        \\        a16 = b16;
        \\        b16 = a16;
        \\        declare var b17: new <T>(x: (a: T) => T) => any[];
        \\        a17 = b17;
        \\        b17 = a17;
        \\    }
        \\}
    );
    defer destroySetup(s);
    // Must complete without panicking; the specific diagnostics are not
    // asserted here (this is a crash regression).
    try s.checker.checkSourceFile(s.root);
}

