test "checker: private-field forward ref reports TS2729 without useDefineForClassFields" {
    // tsc's gate is `useDefineForClassFields || !isPropertyDeclaredInAncestorClass`,
    // so an own (non-inherited) field used before its declaration reports
    // TS2729 even at the es2015 default where useDefineForClassFields is
    // false. Mirrors privateNamesUseBeforeDef.ts.
    const b = try newBoundSetup(
        \\// @target: es2015
        \\class A {
        \\  #foo = this.#bar;
        \\  #bar = 3;
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    var saw_2729 = false;
    var saw_bar_related = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.property_used_before_initialization) continue;
        saw_2729 = true;
        for (d.related) |rel| {
            if (rel.code == TsCodes.is_declared_here and
                std.mem.eql(u8, rel.message, "'#bar' is declared here."))
            {
                saw_bar_related = true;
            }
        }
    }
    try T.expect(saw_2729);
    try T.expect(saw_bar_related);
}

test "checker: private method/getter forward ref does NOT report TS2729" {
    // Methods and accessors live on the prototype (installed before any
    // field initializer runs), so referencing one before its textual
    // declaration is legal — no TS2729. Mirrors privateNamesUseBeforeDef.ts
    // classes A2 (method) and A3 (getter).
    const b = try newBoundSetup(
        \\// @target: es2015
        \\class A2 {
        \\  #foo = this.#bar();
        \\  #bar() { return 3 };
        \\}
        \\class A3 {
        \\  #baz = this.#qux;
        \\  get #qux() { return 3 };
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    var saw_2729 = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.property_used_before_initialization) saw_2729 = true;
    }
    try T.expect(!saw_2729);
}

test "checker: duplicate identifier (function vs var) carries TS6203 related-info to the sibling" {
    const b = try newBoundSetup(
        \\function foo() {}
        \\var foo;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    // Both declarations get a TS2300, and each links to the OTHER via a
    // TS6203 "'foo' was also declared here." related anchor.
    var ts2300_count: usize = 0;
    var with_related: usize = 0;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.duplicate_identifier) continue;
        ts2300_count += 1;
        for (d.related) |rel| {
            if (rel.code == TsCodes.was_also_declared_here and
                std.mem.eql(u8, rel.message, "'foo' was also declared here."))
            {
                with_related += 1;
            }
        }
    }
    try T.expectEqual(@as(usize, 2), ts2300_count);
    try T.expectEqual(@as(usize, 2), with_related);
}

