test "checker: TS2422 fires for a class implementing a non-object type" {
    {
        // A bare primitive keyword in `implements` is the more specific
        // TS2864 (not TS2422), matching tsc's `classImplementsPrimitive`.
        const b = try newBoundSetup("class C implements number {}");
        defer destroyBoundSetup(b);
        try b.base.checker.checkSourceFile(b.base.root);
        try T.expect(checkerHasCodeWithMessage(b, TsCodes.class_implements_primitive, "A class cannot implement a primitive type like 'number'. It can only implement other named object types."));
        // Suppresses the TS2420 assignability variant on the same target.
        try T.expect(!checkerHasCode(b, TsCodes.class_incorrectly_implements_interface));
    }
    {
        const b = try newBoundSetup("class C<T> implements T {}");
        defer destroyBoundSetup(b);
        try b.base.checker.checkSourceFile(b.base.root);
        try T.expect(checkerHasCode(b, TsCodes.class_implements_non_object));
    }
}

