test "checker: nested object mismatch collapses to a dotted-path TS2200 chain" {
    // tsc collapses a multi-level property mismatch into a single
    // TS2200 "The types of 'outer.inner' are incompatible between these
    // types." entry (verified against upstream baselines like
    // `a.b.c.d.e.f().g`), not nested TS2326 entries.
    const b = try newBoundSetup(
        \\declare const a: { outer: { inner: string } };
        \\const c: { outer: { inner: number } } = a;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    var ok = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable or d.chain.len != 1) continue;
        const e0 = d.chain[0];
        if (e0.code != TsCodes.types_of_path_incompatible or
            std.mem.indexOf(u8, e0.message, "'outer.inner'") == null or e0.children.len != 1) continue;
        const leaf = e0.children[0];
        if (leaf.code == TsCodes.type_not_assignable and
            std.mem.indexOf(u8, leaf.message, "'string'") != null and
            std.mem.indexOf(u8, leaf.message, "'number'") != null) ok = true;
    }
    try T.expect(ok);
}

