        const b = try newBoundSetup("declare const g: (() => void) | null | undefined;\ng();");
        defer destroyBoundSetup(b);
        b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
        try b.base.checker.checkSourceFile(b.base.root);
        try T.expect(checkerHasCodeWithMessage(b, TsCodes.cannot_invoke_possibly_nullish, "Cannot invoke an object which is possibly 'null' or 'undefined'."));
    }
    {
        const b = try newBoundSetup("declare const h: (() => void) | undefined;\nh();");
        defer destroyBoundSetup(b);
        b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
        try b.base.checker.checkSourceFile(b.base.root);
