test "checker: Array.filter predicate may return a non-boolean value" {
    // Upstream lib.d.ts types `filter`'s predicate as returning `unknown`,
    // so a callback that returns a truthy non-boolean (here a `string`) is
    // accepted. Regression for the spurious TS2345 on
    // `optionalChainingInArrow` (`names?.filter(x => x)`).
    const s = try newSetup(
        \\const direct = (names: string[]) => names.filter(x => x);
        \\const chained = (names: string[]) => names?.filter(x => x);
        \\const found = (names: string[]) => names.find(x => x);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.argument_type_mismatch);
    }
}

