test "checker: isolatedModules reports global value conflicts for type-only imports" {
    const s = try newSetup(
        \\// @module: commonjs
        \\// @target: es2015
        \\// @isolatedModules: true
        \\// @verbatimModuleSyntax: true
        \\// @filename: ./types.ts
        \\export interface Date { day: number; month: number; year: number; }
        \\export namespace Event { export type T = any; }
        \\// @filename: ./node.d.ts
        \\declare module "node:console" {
        \\  global {
        \\    interface Console { Console: console.ConsoleConstructor; }
        \\    namespace console { interface ConsoleConstructor { prototype: Console; new (): Console; } }
        \\    var console: Console;
        \\  }
        \\  export = globalThis.console;
        \\}
        \\// @filename: ./bad.ts
        \\import { Date, Event } from "./types";
        \\function foo(a: Date) {
        \\  const b = new Date(a.year, a.month, a.day);
        \\  return b.getTime();
        \\}
        \\function bar() {
        \\  return new Event("bar") as Event.T;
        \\}
        \\// @filename: ./good.ts
        \\import type { Date, Event } from "./types";
        \\import { Console } from "node:console";
        \\function foo(a: Date) {
        \\  const b = new Date(a.year, a.month, a.day);
        \\  return b.getTime();
        \\}
        \\function bar() {
        \\  return new Event("bar") as Event.T;
        \\}
        \\const baz: Console = new Console();
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .isolated_modules = true });
    try s.checker.checkSourceFile(s.root);

    var ts1295: usize = 0;
    var ts1484: usize = 0;
    var ts2866: usize = 0;
    var ts1361: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.esm_in_commonjs_verbatim_module) ts1295 += 1;
        if (d.code == TsCodes.type_import_required_verbatim) ts1484 += 1;
        if (d.code == TsCodes.import_conflicts_with_global_value_used) ts2866 += 1;
        if (d.code == TsCodes.type_only_import_used_as_value) ts1361 += 1;
    }
    try T.expectEqual(@as(usize, 3), ts1295);
    try T.expectEqual(@as(usize, 2), ts1484);
    try T.expectEqual(@as(usize, 2), ts2866);
    try T.expectEqual(@as(usize, 0), ts1361);
}

test "checker: TS2865 reports local value conflicts for type-only imports" {
    const s = try newSetup(
        \\// @isolatedModules: true
        \\// @filename: ./types.ts
        \\export interface LocalThing { value: number; }
        \\export interface OtherThing { value: string; }
        \\// @filename: ./bad.ts
        \\import { LocalThing as RuntimeThing } from "./types";
        \\function RuntimeThing() { return 1; }
        \\const useIt = null as unknown as RuntimeThing;
        \\// @filename: ./good.ts
        \\import type { OtherThing as RuntimeOther } from "./types";
        \\function RuntimeOther() { return 2; }
        \\const useOther = null as unknown as RuntimeOther;
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .isolated_modules = true });
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.import_conflicts_with_local_value_isolated));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.import_conflicts_with_local_value_isolated) {
            try T.expectEqualStrings("Import 'RuntimeThing' conflicts with local value, so must be declared with a type-only import when 'isolatedModules' is enabled.", d.message);
        }
    }
}

test "checker: property access on intersection containing any yields any (no TS2339)" {
    // Mirrors thisTypeInObjectLiterals2.ts(173): `defineProp` returns
    // `T & Record<K, U>` where `T` resolves to `any`, so the receiver is
    // an intersection that includes `any`. In tsc, `getPropertyOfType`
    // on a type containing `any` yields `any` and never reports TS2339,
    // even when the named property is absent from the object part.
    const s = try newSetup(
        \\declare let p: any & { x: number; y: number };
        \\p.foo = p.foo + 1;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.property_does_not_exist);
    }
}

test "checker: property access on concrete intersection without any still reports TS2339" {
    // Negative guard: a real missing property on a concrete intersection
    // (no `any` constituent) must still surface TS2339, so the any-aware
    // short-circuit doesn't over-suppress legitimate errors.
    const s = try newSetup(
        \\declare let p: { x: number } & { y: number };
        \\p.foo;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.property_does_not_exist) found = true;
    }
    try T.expect(found);
}

