test "checker: checkjs JSDoc constructor object method keeps closed this shape" {
    const b = try newBoundSetup(
        "const obj = {\r\n" ++
            "  /** @constructor */\r\n" ++
            "  Foo() { this.bar = \"bar\" }\r\n" ++
            "};\r\n" ++
            "(new obj.Foo()).bar;\r\n",
    );
    defer destroyBoundSetup(b);
    b.base.checker.setCheckJsEnabled(true);
    b.base.checker.setAllowJsEnabled(true);
    b.base.checker.setImporterPath("example.js");
    b.base.checker.setStrictFlags(.{ .no_implicit_any = true });
    try b.base.checker.checkSourceFile(b.base.root);

    try T.expectEqual(@as(usize, 1), checkerCountCode(b.base, TsCodes.property_does_not_exist));
    try T.expectEqualStrings(
        "Property 'bar' does not exist on type '{ Foo(): void; }'.",
        checkerFirstMessageForCode(b.base, TsCodes.property_does_not_exist) orelse return error.MissingDiagnostic,
    );
    try T.expectEqual(@as(usize, 1), checkerCountCode(b.base, TsCodes.new_expression_implicitly_any));
}

