test "checker: SharedArrayBuffer keeps its distinct library shape" {
    const b = try newBoundSetup(
        \\// @target: es2015
        \\// @lib: es2015,es2017.sharedmemory
        \\var shared = new SharedArrayBuffer(1024);
        \\shared.byteLength;
        \\shared.slice();
        \\shared.length;
        \\var plain: ArrayBuffer = shared;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(b.base, TsCodes.property_does_not_exist));
    try T.expectEqual(@as(usize, 1), checkerCountCode(b.base, TsCodes.type_not_assignable));
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.property_does_not_exist) {
            try T.expectEqualStrings("Property 'length' does not exist on type 'SharedArrayBuffer'.", d.message);
        }
        if (d.code == TsCodes.type_not_assignable) {
            try T.expectEqualStrings("Type 'SharedArrayBuffer' is not assignable to type 'ArrayBuffer'.", d.message);
        }
    }
}

