test "checker: JSX function component rejects excess children when props has named members" {
    // A props target with named members (other than `children`) DOES
    // emit TS2353 when the JSX block carries a child. Empty `{}`
    // props opts out ÃÂ¢ÃÂÃÂ covered by the sibling test below. Mirrors
    // `checkJsxChildrenProperty` baselines where typed props minus a
    // `children` declaration flag the structural gap.
    const s = try newTsxSetup(
        \\const Tag = (x: { a: number }) => <div></div>;
        \\const k = <Tag a={1}><div></div></Tag>;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.object_literal_excess_property) found = true;
    }
    try T.expect(found);
}

test "checker: JSX reports duplicate children from attr and body" {
    const s = try newTsxSetup(
        \\interface Props { children: any; }
        \\const Tag = (x: Props) => <div></div>;
        \\const k = <Tag children="x"><div></div></Tag>;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var found = false;
    for (s.checker.diagnostics.items) |d| {
        // ÃÂÃÂ§6.A ÃÂ¢ÃÂÃÂ switched to TS2710 (`jsx_children_attribute_overwritten`)
        // to match upstream tsc for the `children`-attribute-vs-body
        // collision specifically. The generic TS2783 still applies for
        // other duplicate-attribute cases.
        if (d.code == TsCodes.jsx_children_attribute_overwritten) found = true;
    }
    try T.expect(found);
}

