test "checker: JSX spread validates required target props" {
    const s = try newTsxSetup(
        \\declare namespace JSX { interface Element {} interface IntrinsicElements { span: any; } }
        \\interface SourceProps { property1: string; property2: number; }
        \\interface TargetProps { property1: string; property2: boolean; missing: string; }
        \\const props: SourceProps = { property1: "ok", property2: 1 };
        \\function AnotherComponent(p: TargetProps) { return <span />; }
        \\const p = <AnotherComponent {...props} />;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    // tsc prefers the more-specific TS2741 (`Property 'missing' is
    // missing in type ... but required in type 'TargetProps'.`) over
    // the generic TS2322 when the gap is a single required-property
    // miss ÃÂ¢ÃÂÃÂ accept either here so the test pins the JSX-attrs
    // assignability behaviour without forcing one specific code.
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_assignable or d.code == TsCodes.property_missing_required) found = true;
    }
    try T.expect(found);
}

test "checker: JSX intrinsic tag rejected by narrow JSX.ElementType emits TS2786+TS18053" {
    // Mirrors `jsxElementTypeLiteral.tsx`: a source-declared
    // `JSX.ElementType = "div"` accepts `<div/>` but rejects
    // `<span/>` because the intrinsic tag's string-literal type
    // `"span"` is not assignable to the `"div"` constraint.
    const s = try newTsxSetup(
        \\declare namespace JSX { interface Element {} type ElementType = "div"; interface IntrinsicElements { div: any; span: any; } }
        \\const b = <span />;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var found_primary = false;
    var found_chain = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.jsx_component_not_valid) {
            found_primary = true;
            try T.expect(std.mem.eql(u8, d.message, "'span' cannot be used as a JSX component."));
            for (d.chain) |entry| {
                if (entry.code == TsCodes.jsx_element_type_not_valid) {
                    found_chain = true;
                    try T.expect(std.mem.eql(u8, entry.message, "Its type '\"span\"' is not a valid JSX element type."));
                }
            }
        }
    }
    try T.expect(found_primary);
    try T.expect(found_chain);
}

