test "checker: component tag rejected by JSX.ElementType emits TS2786+TS18053" {
    // `JSX.ElementType` constrained to string literals rejects a
    // component value whose type (an object literal) is not assignable
    // to the constraint, emitting the primary TS2786 with the chained
    // TS18053 sub-message rendering the offending component type.
    const s = try newTsxSetup(
        \\declare namespace JSX { interface Element {} type ElementType = "div"; interface IntrinsicElements { div: any; } }
        \\const Widget = { not: "callable" };
        \\const k = <Widget />;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var found_primary = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.jsx_component_not_valid) {
            found_primary = true;
            try T.expect(std.mem.eql(u8, d.message, "'Widget' cannot be used as a JSX component."));
            var has_chain = false;
            for (d.chain) |entry| {
                if (entry.code == TsCodes.jsx_element_type_not_valid) has_chain = true;
            }
            try T.expect(has_chain);
        }
    }
    try T.expect(found_primary);
}

