test "checker: JSX without global Element does not report TS2602 (dead in tsgo)" {
    // tsgo's `checkJsxPreconditions` never fires TS2602: `getJsxType` returns
    // `errorType` rather than nil for a missing `JSX.Element`, so the
    // nil-guard is unreachable. A missing global Element must therefore
    // produce NO diagnostic here — and no TS7026 either, since
    // `JSX.IntrinsicElements` IS declared in this fixture.
    const s = try newTsxSetup(
        \\declare namespace JSX { interface IntrinsicElements { div: any; } }
        \\<div n="x" />;
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.jsx_element_implicit_any_no_global_element));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.jsx_element_implicit_any_no_intrinsic));
}

