test "checker: destructuring accessibility unwraps this and anchors renamed source keys" {
    const source =
        \\// @strict: false
        \\class K {
        \\    private priv;
        \\    protected prot;
        \\    private privateMethod() {}
        \\}
        \\class C extends K {
        \\    m() { let { priv: a } = this; }
        \\}
        \\const k = new K();
        \\let { priv: a, prot: b, privateMethod: pm } = k;
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    const subclass_priv: u32 = @intCast(std.mem.indexOf(u8, source, "priv: a } = this").?);
    const renamed_start = std.mem.indexOf(u8, source, "priv: a, prot: b, privateMethod: pm").?;
    const renamed_priv: u32 = @intCast(renamed_start);
    const renamed_prot: u32 = @intCast(renamed_start + "priv: a, ".len);
    const renamed_method: u32 = @intCast(renamed_start + "priv: a, prot: b, ".len);
    var saw_subclass_priv = false;
    var saw_renamed_priv = false;
    var saw_renamed_prot = false;
    var saw_renamed_method = false;
    for (s.checker.diagnostics.items) |d| {
        const pos = d.pos orelse s.hir.spanOf(d.node).start;
        if (d.code == TsCodes.private_member_access and pos == subclass_priv) saw_subclass_priv = true;
        if (d.code == TsCodes.private_member_access and pos == renamed_priv) saw_renamed_priv = true;
        if (d.code == TsCodes.protected_member_access and pos == renamed_prot) saw_renamed_prot = true;
        if (d.code == TsCodes.private_member_access and pos == renamed_method) saw_renamed_method = true;
    }
    try T.expect(saw_subclass_priv);
    try T.expect(saw_renamed_priv);
    try T.expect(saw_renamed_prot);
    try T.expect(saw_renamed_method);
}

test "checker: a subclass redeclaring a base private as a public member does not emit TS2341" {
    // E redeclares D's `private readonly x` as a public parameter
    // property, so `this.x` inside E resolves to E's own member —
    // assigning it in E's constructor is fine, no TS2341. (The
    // private/public mismatch surfaces as TS2415, not a private-access
    // error.) Mirrors `readonlyConstructorAssignment`.
    const s = try newSetup(
        \\class D {
        \\    constructor(private readonly x: number) { this.x = 0; }
        \\}
        \\class E extends D {
        \\    constructor(readonly x: number) { super(x); this.x = 1; }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.private_member_access);
    }
}

