test "checker: assigning a fresh literal to a void target widens the source in TS2322 prose" {
    // tsc reports `Type 'number' is not assignable to type 'void'.`
    // (and `string` / `boolean`) for fresh-literal assignments to a
    // `void` target — not the literal `'1'` / `'""'`. Mirrors
    // `invalidVoidValues.ts(2,1)` and `invalidAssignmentsToVoid`.
    const s = try newSetup(
        \\var x: void;
        \\x = 1;
        \\x = '';
        \\x = true;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var saw_number = false;
    var saw_string = false;
    var saw_boolean = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        if (std.mem.eql(u8, d.message, "Type 'number' is not assignable to type 'void'.")) saw_number = true;
        if (std.mem.eql(u8, d.message, "Type 'string' is not assignable to type 'void'.")) saw_string = true;
        if (std.mem.eql(u8, d.message, "Type 'boolean' is not assignable to type 'void'.")) saw_boolean = true;
        // The fresh literal must NOT leak through.
        try T.expect(std.mem.indexOf(u8, d.message, "Type '1'") == null);
        try T.expect(std.mem.indexOf(u8, d.message, "Type '\"\"'") == null);
    }
    try T.expect(saw_number);
    try T.expect(saw_string);
    try T.expect(saw_boolean);
}

test "checker: overloaded function value type renders anonymous call signatures in TS2322 prose" {
    // An overloaded function's value type (`typeof f`) is an anonymous
    // object with one `__call` member per overload. tsc renders it as
    // `{ (x: "foo"): number; (x: string): number; }` — no `__call`
    // member name and no `readonly` modifier. Mirrors
    // `stringLiteralTypesOverloadAssignability05.ts(15,1)`.
    const s = try newSetup(
        \\function f(x: "foo"): number;
        \\function f(x: string): number;
        \\function f(x: string): number { return 0; }
        \\function g(x: "foo"): number;
        \\function g(x: string): number { return 0; }
        \\let a = f;
        \\let b = g;
        \\a = b;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var saw_overload_target = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        // The synthetic marker and modifier must not leak.
        try T.expect(std.mem.indexOf(u8, d.message, "__call") == null);
        try T.expect(std.mem.indexOf(u8, d.message, "readonly __call") == null);
        if (std.mem.indexOf(u8, d.message, "{ (x: \"foo\"): number; (x: string): number; }") != null) {
            saw_overload_target = true;
        }
    }
    try T.expect(saw_overload_target);
}

