// ----------------------------------------------------------------------------
// Enum member-literal type modeling (`Choice.Yes` is its own unit type).
// ----------------------------------------------------------------------------

// Walk the HIR for the first member-access node and return its type.
fn firstMemberAccessType(s: *TestSetup) ?TypeId {
    var i: NodeId = 0;
    const count = s.hir.nodeCount();
    while (i < count) : (i += 1) {
        if (s.hir.kindOf(i) == .member_access) {
            const t = s.hir.typeOf(i);
            if (t != types.Primitive.none) return t;
        }
    }
    return null;
}

test "checker: enum member access yields a distinct enum-literal type" {
    const s = try newSetup(
        \\enum Choice { Yes, No }
        \\Choice.Yes;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    const t = firstMemberAccessType(s) orelse return error.TestUnexpectedResult;
    // `Choice.Yes` is an enum-literal unit type, distinct from the bare
    // numeric literal `0` that shares its value.
    try T.expect(s.ti.isEnumLiteral(t));
    const bare0 = try s.ti.internNumberLiteral(0);
    try T.expect(t != bare0);
    const info = s.ti.enumLiteralInfo(t) orelse return error.TestUnexpectedResult;
    try T.expectEqualStrings("Choice", s.sint.get(info.enum_name));
    try T.expectEqualStrings("Yes", s.sint.get(info.member_name));
}

test "checker: enum member literal assignable to its enum-typed slot" {
    const s = try newSetup(
        \\enum Choice { Yes, No }
        \\let m: Choice = Choice.Yes;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    // `Choice.Yes` (member literal) flows into a `Choice`-typed slot.
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
    }
    const member_t = firstMemberAccessType(s) orelse return error.TestUnexpectedResult;
    try T.expect(s.ti.isEnumLiteral(member_t));
}

test "checker: a string enum (union of members) is not assignable to a single member" {
    const s = try newSetup(
        \\enum Dir { Up = "U", Down = "D" }
        \\Dir.Up;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    // The whole string-enum type is the union of its member literals.
    const enum_t = s.checker.type_names.get(try s.sint.intern("Dir")) orelse return error.TestUnexpectedResult;
    try T.expect(s.ti.pool.flagsOf(enum_t).is_union);
    const member_t = firstMemberAccessType(s) orelse return error.TestUnexpectedResult;
    try T.expect(s.ti.isEnumLiteral(member_t));
    // member → whole enum holds; whole enum → single member fails.
    try T.expect(try s.engine.isAssignableTo(member_t, enum_t));
    try T.expect(!(try s.engine.isAssignableTo(enum_t, member_t)));
}

test "checker: a member of one enum is not assignable to a member of another" {
    const s = try newSetup(
        \\enum A { X }
        \\enum B { X }
        \\A.X;
        \\B.X;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    const a_x = try s.ti.internEnumNumberLiteral(0, try s.sint.intern("A"), try s.sint.intern("X"));
    const b_x = try s.ti.internEnumNumberLiteral(0, try s.sint.intern("B"), try s.sint.intern("X"));
    // Same value, same member name, different enum: distinct + unrelated.
    try T.expect(a_x != b_x);
    try T.expect(!(try s.engine.isAssignableTo(a_x, b_x)));
    try T.expect(!(try s.engine.isAssignableTo(b_x, a_x)));
    // A member literal still reduces to its base primitive.
    try T.expect(try s.engine.isAssignableTo(a_x, types.Primitive.number_t));
}

test "checker: let-bound enum member widens to its enum, const keeps the member literal" {
    const s = try newSetup(
        \\enum Color { Red, Green }
        \\let lc = Color.Red;
        \\const cc = Color.Green;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    const stmts = hir_mod.blockStmts(&s.hir, s.root);
    // stmts[1] = `let lc = ...`, stmts[2] = `const cc = ...`.
    const let_decl = stmts[1];
    const const_decl = stmts[2];
    const lc_v = hir_mod.varDeclOf(&s.hir, let_decl);
    const cc_v = hir_mod.varDeclOf(&s.hir, const_decl);
    const lc_t = s.hir.typeOf(lc_v.name);
    const cc_t = s.hir.typeOf(cc_v.name);
    // `let lc` widens to the whole enum (not an enum-literal).
    try T.expect(!s.ti.isEnumLiteral(lc_t));
    // `const cc` keeps the narrow member literal.
    try T.expect(s.ti.isEnumLiteral(cc_t));
}

test "checker: const-enum member access still inlines to its raw literal" {
    const s = try newSetup(
        \\const enum CE { A = 1, B = "two" }
        \\const x: 1 = CE.A;
        \\const y: "two" = CE.B;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    // A const-enum member is a nominal enum-literal (tsc sets
    // `TypeFlagsEnumLiteral`), but the relation still relates it to the bare
    // literal of the same value in both directions (tsc relater.go:222/228),
    // so the narrow annotations `1` / `"two"` accept it.
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
    }
    const a_t = firstMemberAccessType(s) orelse return error.TestUnexpectedResult;
    // `CE.A` is a branded enum-literal (`CE.A`), matching tsc — the raw
    // value is only inlined at emit time, not in the type.
    try T.expect(s.ti.isEnumLiteral(a_t));
}

