test "checker: class used after its declaration inside a namespace is not TS2449" {
    // Mirrors fixture `ES5SymbolProperty2.ts` ÃÂ¢ÃÂÃÂ the namespace body
    // declares `class C` and then references `(new C)[...]` *after* the
    // declaration, so no use-before-declaration error is warranted. The
    // bare `C` reference is local to the namespace and must be analyzed
    // in that scope's statement order, not flattened into the file scope.
    const s = try newSetup(
        \\namespace M {
        \\    var Symbol: any;
        \\    export class C {
        \\        [Symbol.iterator]() { }
        \\    }
        \\    (new C)[Symbol.iterator];
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.class_used_before_declaration);
    }
}

