test "checker: import-equals namespace alias class member can be TS2449" {
    // Mirrors `circularImportAlias.ts`: `a.C` resolves through
    // `export import a = A`, and the target class declaration is in a
    // later sibling namespace rather than the current statement list.
    const source =
        \\namespace B {
        \\    export import a = A;
        \\    export class D extends a.C {}
        \\}
        \\namespace A {
        \\    export import b = B;
        \\    export class C extends b.D {}
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const expected_pos: u32 = @intCast(std.mem.indexOf(u8, source, "a.C").? + 2);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.class_used_before_declaration) continue;
        if (std.mem.indexOf(u8, d.message, "Class 'C'") == null) continue;
        if ((d.pos orelse s.hir.spanOf(d.node).start) != expected_pos) continue;
        found = true;
    }
    try T.expect(found);
}

