test "checker: TS2318 reports missing noLib required globals" {
    const s = try newSetup(
        \\// @noLib: true
        \\declare function foo(): void;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    const required = [_][]const u8{
        "Array",
        "Boolean",
        "CallableFunction",
        "Function",
        "IArguments",
        "NewableFunction",
        "Number",
        "Object",
        "RegExp",
        "String",
    };
    try T.expectEqual(required.len, checkerCountCode(s, TsCodes.cannot_find_global_type));
    for (required) |name| {
        const expected = try std.fmt.allocPrint(T.allocator, "Cannot find global type '{s}'.", .{name});
        defer T.allocator.free(expected);
        var found = false;
        for (s.checker.diagnostics.items) |d| {
            if (d.code != TsCodes.cannot_find_global_type) continue;
            if (!std.mem.eql(u8, d.message, expected)) continue;
            try T.expect(d.is_global);
            found = true;
            break;
        }
        try T.expect(found);
    }
}

