test "checker: legacy method decorator return type must be descriptor-compatible" {
    const s = try newSetup(
        \\// @experimentalDecorators: true
        \\declare function dec<T>(target: T): T;
        \\class C {
        \\  @dec method() {}
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    // Under experimentalDecorators the decorator resolves as a call, so the
    // arity mismatch surfaces as the TS1241 unresolved HEADER with the
    // "runtime will invoke" text as a nested chain detail — not a standalone
    // TS1278. The TS1270 return-type error fires alongside. Mirrors
    // decoratorOnClassMethod8.
    var found_header = false;
    var found_arity_chain = false;
    var found_return = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.method_decorator_signature_unresolved) {
            found_header = true;
            for (d.chain) |c| {
                if (c.code == TsCodes.decorator_runtime_expects and
                    std.mem.eql(u8, c.message, "The runtime will invoke the decorator with 3 arguments, but the decorator expects 1."))
                {
                    found_arity_chain = true;
                }
            }
        }
        if (d.code == TsCodes.decorator_return_type_not_assignable and
            std.mem.indexOf(u8, d.message, "TypedPropertyDescriptor<() => void>") != null)
        {
            found_return = true;
        }
    }
    try T.expect(found_header);
    try T.expect(found_arity_chain);
    try T.expect(found_return);
}

