test "checker: legacy property decorator arity mismatch emits TS1240 not TS1278" {
    // Under experimentalDecorators a property decorator whose signature can't
    // accept the runtime call surfaces as TS1240 ("Unable to resolve signature
    // of property decorator when called as an expression."), not the TC39
    // TS1278 arity message. Mirrors decoratorOnClassProperty6.ts.
    const s = try newSetup(
        \\// @experimentalDecorators: true
        \\declare function dec(target: Function): void;
        \\class C {
        \\  @dec prop;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found_1240 = false;
    var found_1278 = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.property_decorator_signature_unresolved and
            std.mem.eql(u8, d.message, "Unable to resolve signature of property decorator when called as an expression."))
        {
            found_1240 = true;
        }
        if (d.code == TsCodes.decorator_runtime_expects) found_1278 = true;
    }
    try T.expect(found_1240);
    try T.expect(!found_1278);
}

test "checker: legacy property decorator wanting more args emits TS1240 header with arity chain" {
    // Mirrors decoratorOnClassProperty7.ts(4,5): when the decorator signature
    // requires more arguments than the property-decorator runtime supplies
    // (here 3 vs 2), tsc emits the TS1240 unresolved HEADER ("Unable to
    // resolve signature of property decorator...") with the arity mismatch
    // as a nested chain detail — NOT a standalone TS1278.
    const source =
        \\// @experimentalDecorators: true
        \\declare function dec(target: Function, propertyKey: string | symbol, paramIndex: number): void;
        \\class C {
        \\  @dec prop;
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found_header = false;
    var found_arity_chain = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.property_decorator_signature_unresolved) continue;
        found_header = true;
        for (d.chain) |c| {
            if (c.code == TsCodes.decorator_runtime_expects) found_arity_chain = true;
        }
    }
    try T.expect(found_header);
    try T.expect(found_arity_chain);
    // The standalone TS1278 arity header must NOT appear under legacy.
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.decorator_runtime_expects));
}

