    const first_at: u32 = @intCast(std.mem.indexOf(u8, source, "@dec").?);
    const second_at: u32 = @intCast(std.mem.indexOfPos(u8, source, first_at + 1, "@dec").?);
    var invalid_count: usize = 0;
