}

test "checker: circular private and computed class field initializers emit TS7022" {
    const source =
        \\// @strict: true
        \\// @target: es6
        \\class A {
        \\    #foo = this.#bar;
        \\    #bar = this.#foo;
        \\    ["#baz"] = this["#baz"];
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);
    const expected_cycle_positions = [_]u32{
        @intCast(std.mem.indexOf(u8, source, "#foo =").?),
        @intCast(std.mem.indexOf(u8, source, "#bar =").?),
        @intCast(std.mem.indexOf(u8, source, "[\"#baz\"] =").?),
    };
    var seen_cycle_positions = [_]bool{ false, false, false };
    var cycle_count: usize = 0;
    var used_before_init_count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code == TsCodes.variable_self_reference_implicitly_any or
            d.code == TsCodes.property_used_before_initialization);
        if (d.code == TsCodes.variable_self_reference_implicitly_any) {
            const pos = d.pos orelse s.hir.spanOf(d.node).start;
            for (expected_cycle_positions, 0..) |expected, i| {
                if (pos == expected) seen_cycle_positions[i] = true;
            }
            cycle_count += 1;
        } else {
            used_before_init_count += 1;
        }
    }
    try T.expectEqual(@as(usize, 3), cycle_count);
    try T.expectEqual(@as(usize, 1), used_before_init_count);
    for (seen_cycle_positions) |seen| try T.expect(seen);
}

