test "checker: unassigned typeof guard still reports then-branch reads" {
    // Mirrors interfaceDoesNotDependOnBaseTypes.ts. A typeof guard on a
    // typed but unassigned local reports TS2454 in the condition and in
    // each then-branch read; it also must not narrow the local before
    // checking the property access.
    const b = try newBoundSetup(
        \\var x: StringTree;
        \\if (typeof x !== "string") {
        \\  x.push("");
        \\  x.push([""]);
        \\}
        \\type StringTree = string | StringTreeArray;
        \\interface Array<T> { push(...items: T[]): number; }
        \\interface StringTreeArray extends Array<StringTree> {}
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);

    var used_before_assign: usize = 0;
    var push_missing: usize = 0;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.used_before_assignment) used_before_assign += 1;
        if (d.code == TsCodes.property_does_not_exist and
            std.mem.indexOf(u8, d.message, "Property 'push' does not exist on type 'StringTree'.") != null)
        {
            push_missing += 1;
        }
    }
    try T.expectEqual(@as(usize, 3), used_before_assign);
    try T.expectEqual(@as(usize, 2), push_missing);
}

