            saw_4113 = true;
            // Upstream renders the base by its bare declared name `Base`,
            // never the namespace-qualified `ns.Base`.
            try T.expect(std.mem.indexOf(u8, d.message, "base class 'Base'.") != null);
            try T.expect(std.mem.indexOf(u8, d.message, "ns.Base") == null);
        }
    }
    try T.expect(saw_4113);
}

