test "checker: module duplicate identifiers report exported vars and classes only" {
    const s = try newSetup(
        \\export var Foo = 2;
        \\export var Foo = 42;
        \\export interface Bar { a: any; }
        \\export interface Bar { b: any; }
        \\export namespace FooBar { export var member1 = 2; }
        \\export namespace FooBar { export var member2 = 42; }
        \\export class Kettle { member1 = 2; }
        \\export class Kettle { member2 = 42; }
        \\export enum Utensils { Spoon }
        \\export enum Utensils { Fork = 1 }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var foo_ts2323: usize = 0;
    var kettle_ts2300: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.export_default_redeclared and std.mem.indexOf(u8, d.message, "'Foo'") != null) foo_ts2323 += 1;
        if (d.code == TsCodes.duplicate_identifier and std.mem.indexOf(u8, d.message, "'Kettle'") != null) kettle_ts2300 += 1;
        if (d.code == TsCodes.duplicate_identifier) {
            try T.expect(std.mem.indexOf(u8, d.message, "'Bar'") == null);
            try T.expect(std.mem.indexOf(u8, d.message, "'FooBar'") == null);
            try T.expect(std.mem.indexOf(u8, d.message, "'Utensils'") == null);
        }
    }
    try T.expectEqual(@as(usize, 2), foo_ts2323);
    try T.expectEqual(@as(usize, 2), kettle_ts2300);
}

// Merging interfaces with incompatible type-parameter constraints is
// reported with TS2428 on EVERY participating declaration, not as
// TS2300 on the second one ÃÂ¢ÃÂÃÂ mirrors fixture
// `twoGenericInterfacesWithDifferentConstraints`. A third differing
// declaration must not re-emit TS2428 on the first one, the entry-
// level flag suppresses duplicates.
test "checker: interface type-parameter mismatch fires TS2428 on every decl" {
    const s = try newSetup(
        \\interface A<T extends Date> { x: T; }
        \\interface A<T extends Number> { y: T; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var ts2428_count: usize = 0;
    var ts2300_count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.interface_declarations_must_have_identical_type_parameters) ts2428_count += 1;
        if (d.code == TsCodes.duplicate_identifier and std.mem.indexOf(u8, d.message, "'A'") != null) ts2300_count += 1;
    }
    try T.expectEqual(@as(usize, 2), ts2428_count);
    try T.expectEqual(@as(usize, 0), ts2300_count);
}

test "checker: a merged interface uses its first declaration's type-param constraint" {
    // `interface A<T extends Date>` then `interface A<T extends Number>`
    // merge with TS2428, and tsc resolves A's type parameter from the
    // FIRST declaration (`Date`). So `A<Date>` satisfies the constraint
    // and must NOT draw TS2344 ("Type 'Date' does not satisfy the
    // constraint 'Number'."). Mirrors
    // `twoGenericInterfacesWithDifferentConstraints`.
    const s = try newSetup(
        \\interface A<T extends Date> { x: T; }
        \\interface A<T extends Number> { y: T; }
        \\interface B<T extends A<Date>> { z: T; }
    );
