    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_does_not_satisfy_constraint);
    }
}

test "checker: a merged generic interface keeps consistent type params for instantiation" {
    // Guards the param-unification path: `B<T>` declared twice with
    // overloads from both declarations; `B<boolean>` must substitute
    // `T -> boolean` across ALL merged members (no stray param from the
    // second declaration). `b.foo(true)` is valid. Mirrors
    // `twoMergedInterfacesWithDifferingOverloads`.
    const s = try newSetup(
        \\interface B<T> { foo(x: T): number; foo(x: string): string; }
        \\interface B<T> { foo(x: T): Date; foo(x: Date): string; }
        \\declare var b: B<boolean>;
        \\var r = b.foo(true);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.argument_type_mismatch);
    }
}

test "checker: interface arity mismatch fires TS2428 once per declaration" {
