// ---- Usage-based implicit-any SUGGESTIONS (TS7043-TS7050) ----
// tsc's `reportImplicitAny` routes through `errorOrSuggestion`: under
// noImplicitAny it emits the hard implicit-any error; under
// !noImplicitAny it emits the `.suggestion`-category "a better type may
// be inferred from usage" diagnostic. These are never errors and never
// appear in `.errors.txt` baselines. The checker only emits them when
// `setEmitImplicitAnySuggestions(true)` opts in.

// Count diagnostics of `code` and require their category is suggestion.
fn countSuggestionDiagnostics(s: *TestSetup, code: u32) usize {
    var n: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == code) {
            // suggestion codes must carry the suggestion category
            std.debug.assert(d.category == .suggestion);
            n += 1;
        }
    }
    return n;
}

test "checker: TS7044 parameter suggestion fires under !noImplicitAny when enabled" {
    const s = try newSetup("function f(x) { return x; }");
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = false });
    s.checker.setEmitImplicitAnySuggestions(true);
    try s.checker.checkSourceFile(s.root);
    // The hard error TS7006 must NOT fire (noImplicitAny is off).
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.parameter_implicitly_any);
    }
    try T.expectEqual(@as(usize, 1), countSuggestionDiagnostics(s, TsCodes.parameter_implicitly_any_suggestion));
    // Message carries the "better type may be inferred" tail.
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.parameter_implicitly_any_suggestion) {
            try T.expect(std.mem.indexOf(u8, d.message, "but a better type may be inferred from usage") != null);
            try T.expect(std.mem.indexOf(u8, d.message, "'x'") != null);
        }
    }
}

test "checker: parameter suggestion suppressed when suggestions disabled" {
