// Upstream tsc renders optional object-property types in TS2322
// prose with a trailing ` | undefined` even when the declared type
// does not already include it ÃÂ¢ÃÂÃÂ e.g. `{ s?: number; }` shows up as
// `{ s?: number | undefined; }`. Mirrors fixture
// `subtypingWithOptionalProperties`.
// A bare object type containing only a single construct signature
// must render in TS2322 prose as `new (params) => Ret` rather than
// the `{ new (): T; }` literal. Mirrors fixture
// `objectTypeWithConstructSignatureHidingMembersOfFunctionAssignmentCompat.ts(14,1)`.
test "checker: anonymous single-construct-signature object renders as `new () => any`" {
    const s = try newSetup("var _x;");
    defer destroySetup(s);
    const construct_id = try s.sint.intern("__construct");
    const ctor_sig = try s.ti.internSignature(&.{}, types.Primitive.any, true);
    const obj = try s.ti.internObjectType(&.{
        .{ .name = construct_id, .type = ctor_sig, .is_optional = false, .is_readonly = false, .is_method = false },
    });
    const name = (try s.checker.allocSimpleTypeName(obj)) orelse return error.SkipZigTest;
    try T.expectEqualStrings("new () => any", name);
}

test "checker: callable signature display includes explicit this parameter" {
    const s = try newSetup("var _x;");
    defer destroySetup(s);
    const y_name = try s.sint.intern("y");
    const x_name = try s.sint.intern("x");
    const this_t = try s.ti.internObjectType(&.{
        .{ .name = y_name, .type = types.Primitive.number_t, .is_optional = false, .is_readonly = false, .is_method = false },
    });
    const sig = try s.ti.internSignatureWithThisType(&.{types.Primitive.number_t}, types.Primitive.number_t, false, false, this_t);
    try s.checker.signature_param_names.put(s.checker.gpa, sig, try s.checker.gpa.dupe(hir_mod.StringId, &.{x_name}));

    const name = (try s.checker.allocSimpleTypeName(sig)) orelse return error.SkipZigTest;
    try T.expectEqualStrings("(this: { y: number; }, x: number) => number", name);
}

test "checker: annotated signature assignment display normalizes object this parameter" {
    const s = try newSetup(
        \\declare let src: (this: { x: number }, m: number) => number;
