test "checker: contextual generic signatures drive interface heritage" {
    const b = try newBoundSetup(
        \\declare class Base { foo: string }
        \\declare class Derived extends Base { bar: string }
        \\interface CallBase { value: (x: Base) => Base }
        \\interface BadCall extends CallBase { value: <T extends Derived>(x: T) => T }
        \\interface GoodCall extends CallBase { value: <T extends Base>(x: T) => T }
        \\interface ConstructBase { value: new (x: Base) => Base }
        \\interface BadConstruct extends ConstructBase { value: new <T extends Derived>(x: T) => T }
        \\interface GoodConstruct extends ConstructBase { value: new <T extends Base>(x: T) => T }
        \\interface GenericBase { value: <T>(x: T) => T[] }
        \\interface BadGeneric extends GenericBase { value: <T>(x: T) => string[] }
        \\interface GenericCallBase { value: <T, U>(x: (arg: T) => U) => T }
        \\interface GoodGenericCall extends GenericCallBase { value: <T, U>(x: (arg: T) => U) => T }
        \\interface GenericConstructBase { value: new <T, U>(x: (arg: T) => U) => T }
        \\interface GoodGenericConstruct extends GenericConstructBase { value: new <T, U>(x: (arg: T) => U) => T }
        \\interface OuterGenericCallBase { value: <T, U>(x: T, y: U) => string }
        \\interface BadOuterGenericCall<X> extends OuterGenericCallBase { value: <U>(x: X, y: U) => string }
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .strict_function_types = true });
    try b.base.checker.checkSourceFile(b.base.root);
    var heritage_errors: usize = 0;
