test "checker: duplicate index signatures report both declarations" {
    const source =
        \\interface Number {
        \\  [x: number]: string;
        \\  [x: number]: string;
        \\}
        \\interface String {
        \\  [x: number]: string;
        \\  [x: number]: string;
        \\}
        \\interface Array<T> {
        \\  [x: number]: T;
        \\  [x: number]: T;
        \\}
        \\class C {
        \\  [x: number]: string;
        \\  [x: number]: string;
        \\}
        \\interface I {
        \\  [x: number]: string;
        \\  [x: number]: string;
        \\}
        \\var a: {
        \\  [x: number]: string;
        \\  [x: number]: string;
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var count: usize = 0;
    var positions: [12]bool = @splat(false);
    const number_pos_0 = std.mem.indexOf(u8, source, "[x: number]: string;").?;
    const number_pos_1 = std.mem.indexOfPos(u8, source, number_pos_0 + 1, "[x: number]: string;").?;
    const number_pos_2 = std.mem.indexOfPos(u8, source, number_pos_1 + 1, "[x: number]: string;").?;
    const number_pos_3 = std.mem.indexOfPos(u8, source, number_pos_2 + 1, "[x: number]: string;").?;
    const array_pos_0 = std.mem.indexOf(u8, source, "[x: number]: T;").?;
    const array_pos_1 = std.mem.indexOfPos(u8, source, array_pos_0 + 1, "[x: number]: T;").?;
    const number_pos_4 = std.mem.indexOfPos(u8, source, number_pos_3 + 1, "[x: number]: string;").?;
    const number_pos_5 = std.mem.indexOfPos(u8, source, number_pos_4 + 1, "[x: number]: string;").?;
    const number_pos_6 = std.mem.indexOfPos(u8, source, number_pos_5 + 1, "[x: number]: string;").?;
    const number_pos_7 = std.mem.indexOfPos(u8, source, number_pos_6 + 1, "[x: number]: string;").?;
    const number_pos_8 = std.mem.indexOfPos(u8, source, number_pos_7 + 1, "[x: number]: string;").?;
    const number_pos_9 = std.mem.indexOfPos(u8, source, number_pos_8 + 1, "[x: number]: string;").?;
    const expected_positions = [_]usize{
        number_pos_0,
        number_pos_1,
        number_pos_2,
        number_pos_3,
        array_pos_0,
        array_pos_1,
        number_pos_4,
        number_pos_5,
        number_pos_6,
        number_pos_7,
        number_pos_8,
        number_pos_9,
    };
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.duplicate_index_signature) {
            const pos = d.pos orelse s.hir.spanOf(d.node).start;
            for (expected_positions, 0..) |expected_pos, idx| {
                if (pos == expected_pos) positions[idx] = true;
            }
            count += 1;
        }
    }
    try T.expectEqual(@as(usize, 12), count);
    for (positions) |found| try T.expect(found);
}

