test "checker: super.method() in a constructor resolves the base instance method (no TS2339)" {
    // In a constructor `super` is the base CONSTRUCTOR type (for the
    // `super(...)` call), but `super.foo(...)` must resolve the base
    // INSTANCE method. Home looked `foo` up on the constructor type and
    // over-emitted TS2339. Mirrors `superCallParameterContextualTyping3`.
    const s = try newSetup(
        \\class CBase {
        \\  constructor(param: number) {}
        \\  foo(param: number) {}
        \\}
        \\class C extends CBase {
        \\  constructor() {
        \\    super(1);
        \\    super.foo(2);
        \\  }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.property_does_not_exist);
    }
}

