test "checker: ES5 object-literal super reports TS2659 only for methods and accessors" {
    const s = try newSetup(
        \\// @target: ES5
        \\var obj = {
        \\  __proto__: { method() {} },
        \\  method() { super.method(); },
        \\  get prop() { super.method(); return 1; },
        \\  set prop(value) { super.method(); },
        \\  p1: function () { super.method(); },
        \\  p2: function f() { super.method(); },
        \\  p3: () => { super.method(); }
        \\};
        \\class A { method() {} }
        \\class B extends A {
        \\  f() {
        \\    var nested = {
        \\      __proto__: { method() {} },
        \\      method() { super.method(); },
        \\      get prop() { super.method(); return 1; },
        \\      set prop(value) { super.method(); },
        \\      p1: function () { super.method(); },
        \\      p2: function f() { super.method(); },
        \\      p3: () => { super.method(); }
        \\    };
        \\  }
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);
    var count_2659: usize = 0;
    var count_2660: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.super_only_object_literal_methods_es2015) count_2659 += 1;
        if (d.code == TsCodes.super_not_in_derived_member) count_2660 += 1;
        try T.expect(d.code != TsCodes.setter_property_implicitly_any);
        try T.expect(d.code != TsCodes.parameter_implicitly_any);
    }
    try T.expectEqual(@as(usize, 6), count_2659);
    try T.expectEqual(@as(usize, 5), count_2660);
}

