test "checker: nested self-referential typeof annotation does not emit TS2589" {
    // `var a: { foo: typeof a }` — the typeof query sits inside an object
    // type literal and references the very variable being resolved. tsc
    // resolves the recursive object type lazily and reports nothing; the
    // eager lowerer must break the cycle to `any` instead of recursing to
    // the instantiation-depth limit (which produced a spurious TS2589 and a
    // giant expanded type). Mirrors the empty baseline of
    // `assignmentCompatWithObjectMembers`.
    const s = try newSetup(
        \\var a: { foo: typeof a; };
        \\var b: { foo: typeof b; };
        \\var s2: { foo: { foo: any } };
        \\s2 = b;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_instantiation_excessively_deep);
    }
}

test "checker: override base type from construct-sig intersection omits apparent duplicates" {
    // `class Bar extends Foo` where `Foo: C1 & C2` and C1/C2 are
    // construct-signature interfaces returning I1/I2. Each interface's
    // resolved object carries a duplicate `__construct` member (one
    // returning the named ref, one the apparent object form), so the
    // TS4114 base-class prose rendered the bogus
    // `'{ m1(): void; } & { m1(): void; m2(): void; } & I1 & I2'`.
    // After folding the apparent-duplicate construct signatures it must
    // render tsc's `'I1 & I2'`. Mirrors `override20` (exact baseline).
    const s = try newSetup(
        \\const Foo: C1 & C2 = class { m1() {} m2() {} };
        \\interface I1 { m1(): void; }
        \\interface I2 { m1(): void; m2(): void; }
        \\interface C1 { new(...args: any[]): I1; }
        \\interface C2 { new(...args: any[]): I2; }
        \\class Bar extends Foo {
        \\    m1() { super.m1(); }
        \\    m2() { super.m2(); }
        \\}
    );
    defer destroySetup(s);
    s.checker.strict_flags.no_implicit_override = true;
    try s.checker.checkSourceFile(s.root);
    var saw_4114 = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.missing_override) continue;
        saw_4114 = true;
        try T.expect(std.mem.indexOf(u8, d.message, "base class 'I1 & I2'") != null);
        try T.expect(std.mem.indexOf(u8, d.message, "{ m1()") == null);
    }
    try T.expect(saw_4114);
}

