test "checker: assertion target contextually types arrow before TS2352 overlap" {
    const s = try newSetup("var x = (v => v) as (x: number) => string;");
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);
    const decl = hir_mod.blockStmts(&s.hir, s.root)[0];
    const asserted = hir_mod.varDeclOf(&s.hir, decl).init;
    const arrow = hir_mod.asExpressionOf(&s.hir, asserted).expr;
    const arrow_t = s.hir.typeOf(arrow);
    try T.expect(s.checker.interner.isSignature(arrow_t));
    try T.expectEqual(@as(?TypeId, types.Primitive.number_t), s.checker.interner.signatureReturn(arrow_t));
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.conversion_may_be_mistake));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.parameter_implicitly_any));
    const msg = checkerFirstMessageForCode(s, TsCodes.conversion_may_be_mistake) orelse return error.MissingDiagnostic;
    try T.expectEqualStrings(
        "Conversion of type '(v: number) => number' to type '(x: number) => string' may be a mistake because neither type sufficiently overlaps with the other. If this was intentional, convert the expression to 'unknown' first.",
        msg,
    );
    const expected_pos: u32 = @intCast(std.mem.indexOf(u8, s.checker.source.?, "(v => v)").?);
    for (s.checker.diagnostics.items) |diag| {
        if (diag.code == TsCodes.conversion_may_be_mistake) try T.expectEqual(@as(?u32, expected_pos), diag.pos);
    }
}

