test "checker: shadowed private identifier access reports TS18014" {
    // `Derived` is nested inside `Base`; both declare `#x`. Accessing
    // `x.#x` where `x: Base` from within `Derived` resolves the
    // lexically-scoped `Derived.#x`, which shadows `Base.#x`, so tsc
    // emits TS18014. Mirrors `privateNameNestedClassFieldShadowing.ts`.
    const src =
        \\class Base {
        \\  #x = 0;
        \\  m() {
        \\    class Derived {
        \\      #x = 0;
        \\      testBase(x: Base) {
        \\        return x.#x;
        \\      }
        \\      testDerived(x: Derived) {
        \\        return x.#x;
        \\      }
        \\    }
        \\    return Derived;
        \\  }
        \\}
    ;
    const s = try newSetup(src);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found_18014: usize = 0;
    var found_18013 = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.ecma_private_shadowed_by_another) {
            found_18014 += 1;
            try T.expect(std.mem.indexOf(u8, d.message, "The property '#x' cannot be accessed on type 'Base'") != null);
            try T.expect(std.mem.indexOf(u8, d.message, "shadowed by another private identifier") != null);
        }
        if (d.code == TsCodes.ecma_private_not_accessible_outside_class) found_18013 = true;
    }
    // Exactly the `testBase` access shadows; `testDerived` is fine.
    try T.expectEqual(@as(usize, 1), found_18014);
    // 18014 must take precedence — no spurious 18013 for the shadow.
    try T.expect(!found_18013);
}

test "checker: shadowed private identifier diagnostic anchors at the name" {
    const src =
        \\class Base {
        \\  #x = 0;
        \\  m() {
        \\    class Derived {
        \\      #x = 0;
        \\      testBase(x: Base) {
        \\        return x.#x;
        \\      }
        \\    }
        \\    return Derived;
        \\  }
        \\}
    ;
    const s = try newSetup(src);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    // Anchor at the `#x` in `x.#x` (the access inside `testBase`),
    // i.e. the last `#x` occurrence in the source.
    const name_pos = std.mem.lastIndexOf(u8, src, "#x") orelse return error.TestUnexpectedResult;
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.ecma_private_shadowed_by_another) continue;
        const pos = d.pos orelse s.checker.hir.spanOf(d.node).start;
        if (pos == @as(u32, @intCast(name_pos))) found = true;
    }
    try T.expect(found);
}

test "checker: non-shadowing nested private access does not emit TS18014" {
    // `Inner` is nested in `Outer` but does NOT redeclare `#x`, so
    // accessing `Outer.#x` from within `Inner` is a genuine
    // outside-class access (TS18013), not a shadow (TS18014).
    const src =
        \\class Outer {
        \\  #x = 0;
        \\  m() {
        \\    class Inner {
        \\      testOuter(x: Outer) {
        \\        return x.#x;
        \\      }
        \\    }
        \\    return Inner;
        \\  }
        \\}
    ;
