test "checker: for-of var conflict TS2481 names the conflicting identifier" {
    // Mirrors `for-of53` / `for-of54` baselines:
    //   for (let v of []) { var v; }
    // tsc reports TS2481 anchored at the inner `var v` with the name
    // interpolated. We previously anchored at the for-of body without
    // the name; this regression test pins the new shape.
    const s = try newSetup(
        \\for (let v of []) { var v; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.for_of_var_conflict) continue;
        if (std.mem.indexOf(u8, d.message, "outer scoped variable 'v'") == null) continue;
        if (std.mem.indexOf(u8, d.message, "block scoped declaration 'v'") == null) continue;
        found = true;
        break;
    }
    try T.expect(found);
}

test "checker: for-of let target self-references emit TS7022" {
    // Mirrors `for-of55.ts`: `for (let v of v)` shadows the outer
    // `v` and the source expression references the inner declaration
    // by TDZ ÃÂ¢ÃÂÃÂ tsc emits TS7022 ("'v' implicitly has type 'any'ÃÂ¢ÃÂÃÂ¦
    // referenced directly or indirectly in its own initializer.")
    // alongside the TS2448 used-before-declaration diagnostic. The
    // self-reference walker dispatched only on `var_decl`, dropping
    // the `let v of v` path silently.
    const s = try newSetup(
        \\let v = [1];
        \\for (let v of v) {
        \\    v;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.variable_self_reference_implicitly_any) found = true;
    }
    try T.expect(found);
}

