test "checker: &&= preserves nullish target possibility" {
    // `x &&= ""` only writes when `x` is truthy. If `x` starts as
    // `undefined`, the write is skipped and `x` remains possibly
    // undefined for subsequent statements.
    const s = try newSetup(
        \\function f(x: string | undefined) { x &&= ""; const r: string = x; }
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
    var saw_assignability = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_assignable) saw_assignability = true;
    }
    try T.expect(saw_assignability);
}

test "checker: native logical assignments narrow statements, RHS, and truthy branches" {
    const s = try newSetup(
        \\function arrays(xs: number[] | undefined) {
        \\  (xs ||= []).push(1);
        \\  xs ??= [];
        \\  xs.push(2);
        \\}
        \\function callable(f?: () => void) {
        \\  f ||= () => {};
        \\  f();
        \\}
        \\function maybeCallable(f?: () => void) {
        \\  f &&= () => {};
        \\  f();
        \\}
        \\interface Thing { name: string; original?: Thing; }
        \\function andBranch(thing: Thing | undefined, fallback: Thing | undefined) {
        \\  if (thing &&= fallback) {
        \\    thing.name;
        \\    fallback.name;
        \\  }
        \\}
        \\function orBranch(thing: Thing | undefined, fallback: Thing | undefined) {
        \\  if (thing ||= fallback) {
        \\    thing.name;
        \\    fallback.name;
        \\  }
        \\}
        \\function nullishBranch(thing: Thing | undefined, fallback: Thing | undefined) {
        \\  if (thing ??= fallback) {
        \\    thing.name;
        \\    fallback.name;
        \\  }
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.cannot_invoke_possibly_undefined));
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.object_possibly_undefined_18048));
}

test "checker: optional chaining widens the result with undefined" {
    const s = try newSetup(
        \\interface Box { value: number; }
        \\function f(b: Box): number { return b?.value; }
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
    // The return value should be `number | undefined` (broader
    // than the function's declared `number` return ÃÂ¢ÃÂÃÂ we don't
    // assert on the diagnostic since that's the assignability
    // story; instead we check the inner expression's type.)
    const stmts = hir_mod.blockStmts(&s.hir, s.root);
    const f = hir_mod.fnDeclOf(&s.hir, stmts[1]);
    const body = hir_mod.blockStmts(&s.hir, f.body);
    const ret_p = hir_mod.returnOf(&s.hir, body[0]);
    const t = s.hir.typeOf(ret_p.value);
    try T.expect(s.ti.pool.flagsOf(t).is_union);
    var has_num = false;
    var has_undef = false;
    for (s.ti.unionMembers(t)) |m| {
        if (m == types.Primitive.number_t) has_num = true;
        if (m == types.Primitive.undefined_t) has_undef = true;
    }
    try T.expect(has_num);
    try T.expect(has_undef);
}

