test "checker: noUnusedLocals TS6133 covers unread #private methods and accessors" {
    // ECMAScript `#`-private methods and accessors are privacy-by-name,
    // not the `private` modifier — they must still be flagged unread.
    // Mirrors privateNameUnused (classes A2/A3); `#used` stays silent.
    const s = try newSetup(
        \\class A2 {
        \\  #used() {}
        \\  #unused() {}
        \\  constructor() { this.#used(); }
        \\}
        \\class A3 {
        \\  get #used() { return 0; }
        \\  set #used(v: number) {}
        \\  get #unused() { return 0; }
        \\  set #unused(v: number) {}
        \\  constructor() { this.#used; }
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_unused_locals = true, .no_unused_parameters = true });
    try s.checker.checkSourceFile(s.root);
    var unused_count: usize = 0;
    var used_flagged = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.declared_but_not_read) continue;
        if (std.mem.indexOf(u8, d.message, "'#unused'") != null) unused_count += 1;
        if (std.mem.indexOf(u8, d.message, "'#used'") != null) used_flagged = true;
    }
    // One per class (A2 method, A3 accessor pair counted once).
    try T.expectEqual(@as(usize, 2), unused_count);
    try T.expect(!used_flagged);
}

