    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var ts2813: usize = 0;
    var ts2391: usize = 0;
    var ts2814: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.class_cannot_implement_overload_list) ts2813 += 1;
        if (d.code == TsCodes.implementation_missing) ts2391 += 1;
        if (d.code == TsCodes.function_body_merge_requires_ambient_class) ts2814 += 1;
        try T.expect(d.code != TsCodes.value_only_constructable);
    }
    try T.expectEqual(@as(usize, 1), ts2813);
    try T.expectEqual(@as(usize, 1), ts2391);
    try T.expectEqual(@as(usize, 1), ts2814);
}

