test "checker: virtual typeRoots resolve scoped packages without mangling custom roots" {
    const s = try newSetup(
        \\// @typeRoots: /a/types,/a/node_modules,/a/node_modules/@types
        \\// @filename: /a/types/@scoped/typescache/index.d.ts
        \\export const typesCache: number;
        \\// @filename: /a/types/mangled__typescache/index.d.ts
        \\export const mangledTypes: number;
        \\// @filename: /a/node_modules/@scoped/nodemodulescache/index.d.ts
        \\export const nodeModulesCache: number;
        \\// @filename: /a/node_modules/mangled__nodemodulescache/index.d.ts
        \\export const mangledNodeModules: number;
        \\// @filename: /a/node_modules/@types/@scoped/attypescache/index.d.ts
        \\export const atTypesCache: number;
        \\// @filename: /a/node_modules/@types/mangled__attypescache/index.d.ts
        \\export const mangledAtTypesCache: number;
        \\// @filename: /a.ts
        \\import { typesCache } from "@scoped/typescache";
        \\import { mangledTypes } from "@mangled/typescache";
        \\import { nodeModulesCache } from "@scoped/nodemodulescache";
        \\import { mangledNodeModules } from "@mangled/nodemodulescache";
        \\import { atTypesCache } from "@scoped/attypescache";
        \\import { mangledAtTypesCache } from "@mangled/attypescache";
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var missing_scoped_types = false;
    var missing_mangled_types = false;
    var missing_mangled_node_modules = false;
    var missing_scoped_at_types = false;
    var missing_mangled_at_types = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.cannot_find_module) continue;
        if (std.mem.indexOf(u8, d.message, "@scoped/typescache") != null) missing_scoped_types = true;
        if (std.mem.indexOf(u8, d.message, "@mangled/typescache") != null) missing_mangled_types = true;
        if (std.mem.indexOf(u8, d.message, "@mangled/nodemodulescache") != null) missing_mangled_node_modules = true;
        if (std.mem.indexOf(u8, d.message, "@scoped/attypescache") != null) missing_scoped_at_types = true;
        if (std.mem.indexOf(u8, d.message, "@mangled/attypescache") != null) missing_mangled_at_types = true;
    }
    try T.expect(!missing_scoped_types);
    try T.expect(missing_mangled_types);
    try T.expect(missing_mangled_node_modules);
    try T.expect(missing_scoped_at_types);
    try T.expect(!missing_mangled_at_types);
}

test "checker: self-referential type alias terminates without hanging" {
    // `Mxs` references itself through `Mx`'s type arguments. Before the
    // substituteType active-path cycle cut this re-expanded combinatorially
    // up to the depth/count caps (minutes of work, suite hang). Assert
    // checking completes promptly. Mirrors tsgo's
    // `circularlyReferentialInterfaceAccessNoCrash` (we don't emit the
    // TS4109/4110 codes — distinguishing a genuine type-args cycle from a
    // legitimate recursive generic needs tsc's type-resolution stack).
    const s = try newSetup(
        \\type Mxs = Mx<'list', Mxs['p1']>;
        \\interface Mx<T, K> { p1: T; p2: K; }
        \\type ArrElem = ['list', ArrElem[number][0]][];
        \\type TupleElem = [['list', TupleElem[0][0]]];
        \\const a: Mxs = null as any;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    // The point is termination — no assertion on diagnostics beyond
