test "checker: TS1471 import-equals require of an ES module under node16" {
    // Mirrors tsgo `nodeModules1`: `import x = require("./esm")` desugars to
    // a require call, which cannot load an ES module → TS1471 (not TS1479).
    const s = try newSetup(
        \\// @module: node16
        \\// @filename: /module.mts
        \\export {};
        \\// @filename: /main.cts
        \\import m = require("./module.mjs");
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.module_only_resolves_to_esm) continue;
        count += 1;
        try T.expectEqualStrings(
            "Module './module.mjs' cannot be imported using this construct. The specifier only resolves to an ES module, which cannot be imported with 'require'. Use an ECMAScript import instead.",
            d.message,
        );
    }
    try T.expectEqual(@as(usize, 1), count);
    // The require form takes TS1471, not the TS1479 path.
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.commonjs_importing_esm_require);
    }
}

test "checker: TS1541 type-only ESM import from CJS needs resolution-mode" {
    // Mirrors tsgo `typeOnlyESMImportFromCJS`: a type-only import of an ESM
    // `.mts` from a `.cts` under node16 must carry a `resolution-mode`
    // attribute → TS1541 (the type-only sibling of TS1479). The second
    // import supplies the attribute and is fine.
    const s = try newSetup(
        \\// @module: node16
        \\// @filename: /module.mts
        \\export {};
        \\// @filename: /common.cts
        \\import type {} from "./module.mts";
        \\import type {} from "./module.mts" with { "resolution-mode": "import" };
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_only_esm_from_cjs_needs_resolution_mode) continue;
        count += 1;
        try T.expectEqualStrings(
            "Type-only import of an ECMAScript module from a CommonJS module must have a 'resolution-mode' attribute.",
            d.message,
        );
    }
    // Exactly one — the attribute-bearing import is exempt; and a type-only
    // import must NOT take the value-import TS1479 path.
    try T.expectEqual(@as(usize, 1), count);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.commonjs_importing_esm_require);
    }
}

