/// Mock external resolver: every specifier is unresolved and carries a
/// fixed TS2209 ambiguous-project-root record, exercising the checker's
/// TS2209 emission path without wiring the full `ts_resolver`.
const MockAmbiguousResolver = struct {
    fn resolveImpl(_: *anyopaque, _: []const u8, _: []const u8) ?ExternalResolver.Resolution {
        return null;
    }
    fn ambiguousImpl(_: *anyopaque) ?ExternalResolver.AmbiguousProjectRoot {
        return .{ .entry = ".", .file = "/package.json", .is_imports = false };
    }
    const vtable = ExternalResolver.VTable{
        .resolve = resolveImpl,
        .ambiguousProjectRoot = ambiguousImpl,
    };
};

