    defer destroySetup(s);
    var dummy: u8 = 0;
    s.checker.setExternalResolver(.{ .ptr = &dummy, .vtable = &MockAmbiguousResolver.vtable });
    try s.checker.checkSourceFile(s.root);
    var found = false;
    var saw_2307 = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.project_root_ambiguous_exports) {
            found = true;
            try T.expect(d.is_global);
            try T.expectEqualStrings(
                "The project root is ambiguous, but is required to resolve export map entry '.' in file 'package.json'. Supply the `rootDir` compiler option to disambiguate.",
                d.message,
            );
        }
        if (d.code == TsCodes.cannot_find_module) saw_2307 = true;
    }
    try T.expect(found);
    // The global TS2209 replaces the would-be TS2307.
    try T.expect(!saw_2307);
}

