test "checker: explicit type args take precedence over inference" {
    // Inference would say `T = number`, but explicit `<string>`
    // wins. The arg is then checked against the substituted
    // signature, so passing a number to `id<string>` is TS2345.
    const s = try newSetup(
        \\function id<T>(x: T): T { return x; }
        \\let r = id<string>(42);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const stmts = hir_mod.blockStmts(&s.hir, s.root);
    const r_decl = stmts[1];
    // r should be `string` because the explicit type-arg wins.
    try T.expectEqual(types.Primitive.string_t, s.hir.typeOf(r_decl));
    // And we should have a TS2345 diagnostic for passing number to string.
    var saw_2345 = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.argument_type_mismatch) saw_2345 = true;
    }
    try T.expect(saw_2345);
}

test "checker: explicit type args select matching overloaded object member for argument diagnostics" {
    const s = try newSetup(
        \\interface Collection<T, U> {
        \\  length: number;
        \\  add(x: T, y: U): void;
        \\  remove(x: T, y: U): boolean;
        \\}
        \\interface Combinators {
        \\  map<T, U>(c: Collection<T, U>, f: (x: T, y: U) => any): Collection<any, any>;
        \\  map<T, U, V>(c: Collection<T, U>, f: (x: T, y: U) => V): Collection<T, V>;
        \\}
        \\declare var _: Combinators;
        \\declare var c2: Collection<number, string>;
        \\var rf1 = (x: number, y: string) => { return x.toFixed() };
        \\var r5a = _.map<number, string, Date>(c2, (x, y) => { return x.toFixed() });
        \\var r5b = _.map<number, string, Date>(c2, rf1);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_2345: usize = 0;
    var saw_2558 = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.argument_type_mismatch) saw_2345 += 1;
        if (d.code == TsCodes.expected_n_type_arguments) saw_2558 = true;
    }
    try T.expectEqual(@as(usize, 2), saw_2345);
    try T.expect(!saw_2558);
}

