test "checker: TS2808 getter accessibility must be at least setter accessibility" {
    const source =
        \\class C {
        \\  protected get p() { return 1; }
        \\  set p(v: number) {}
        \\  private get q() { return 1; }
        \\  protected set q(v: number) {}
        \\  protected static get s() { return 1; }
        \\  static set s(v: number) {}
        \\  protected get ok1() { return 1; }
        \\  private set ok1(v: number) {}
        \\  get ok2() { return 1; }
        \\  protected set ok2(v: number) {}
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var count: usize = 0;
    var saw_p_get = false;
    var saw_p_set = false;
    var saw_q_get = false;
    var saw_q_set = false;
    var saw_s_get = false;
    var saw_s_set = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.getter_must_be_at_least_as_accessible_as_setter) continue;
        count += 1;
        try T.expectEqualStrings("A get accessor must be at least as accessible as the setter", d.message);
        const pos = d.pos orelse s.hir.spanOf(d.node).start;
        if (std.mem.startsWith(u8, source[pos..], "p")) saw_p_get = true;
        if (std.mem.startsWith(u8, source[pos..], "p(v")) saw_p_set = true;
        if (std.mem.startsWith(u8, source[pos..], "q")) saw_q_get = true;
        if (std.mem.startsWith(u8, source[pos..], "q(v")) saw_q_set = true;
        if (std.mem.startsWith(u8, source[pos..], "s")) saw_s_get = true;
        if (std.mem.startsWith(u8, source[pos..], "s(v")) saw_s_set = true;
    }
    try T.expectEqual(@as(usize, 6), count);
    try T.expect(saw_p_get and saw_p_set);
    try T.expect(saw_q_get and saw_q_set);
    try T.expect(saw_s_get and saw_s_set);
}

