        \\  d = takeReturnString(d);
        \\  e = takeReturnString(e);
        \\  a = takeReturnHello(a);
        \\  b = takeReturnHello(b);
        \\  c = takeReturnHello(c);
        \\  d = takeReturnHello(d);
        \\  e = takeReturnHello(e);
        \\  a = takeReturnHelloWorld(a);
        \\  b = takeReturnHelloWorld(b);
