test "checker: failed string assignment does not narrow explicit union generic result" {
    const s = try newSetup(
        \\// @target: es2015
        \\// @declaration: true
        \\declare function randBool(): boolean;
        \\declare function takeReturnString(str: string): string;
        \\declare function takeReturnHello(str: "Hello"): "Hello";
        \\declare function takeReturnHelloWorld(str: "Hello" | "World"): "Hello" | "World";
        \\function fun2<T, U>(x: T, y: U) { return randBool() ? x : y; }
        \\function fun3<T>(...args: T[]): T { return args[+randBool()]; }
        \\namespace n3 {
        \\  export let a = fun2<"Hello", "World">("Hello", "World");
        \\  export let b = fun2<"Hello", "World">("World", "Hello");
        \\  export let c = fun2<"World", "Hello">("Hello", "Hello");
        \\  export let d = fun2<"World", "Hello">("World", "World");
        \\  export let e = fun3<"Hello" | "World">("Hello", "World");
        \\  a = takeReturnString(a);
        \\  b = takeReturnString(b);
        \\  c = takeReturnString(c);
        \\  d = takeReturnString(d);
        \\  e = takeReturnString(e);
        \\  a = takeReturnHello(a);
        \\  b = takeReturnHello(b);
        \\  c = takeReturnHello(c);
        \\  d = takeReturnHello(d);
        \\  e = takeReturnHello(e);
        \\  a = takeReturnHelloWorld(a);
        \\  b = takeReturnHelloWorld(b);
        \\  c = takeReturnHelloWorld(c);
        \\  d = takeReturnHelloWorld(d);
        \\  e = takeReturnHelloWorld(e);
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{
        .no_implicit_any = true,
        .strict_function_types = true,
        .strict_null_checks = true,
        .strict_property_initialization = true,
        .use_unknown_in_catch_variables = true,
        .declaration = true,
    });
    try s.checker.checkSourceFile(s.root);
    // Upstream also reports the three invalid explicit-argument calls that
    // initialize b, c, and d, in addition to the ten assignment/call errors.
    try T.expectEqual(@as(usize, 13), checkerCountCode(s, TsCodes.argument_type_mismatch) + checkerCountCode(s, TsCodes.type_not_assignable));
    var initializer_arg_errors: usize = 0;
    var union_to_hello_arg_errors: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        try T.expect(std.mem.indexOf(u8, d.message, "Argument of type '\"Hello\"' is not assignable to parameter of type '\"Hello\"'.") == null);
        if (d.code == TsCodes.argument_type_mismatch and
            (std.mem.indexOf(u8, d.message, "Argument of type '\"World\"' is not assignable to parameter of type '\"Hello\"'.") != null or
                std.mem.indexOf(u8, d.message, "Argument of type '\"Hello\"' is not assignable to parameter of type '\"World\"'.") != null))
        {
            initializer_arg_errors += 1;
        }
        if (d.code == TsCodes.argument_type_mismatch and
            std.mem.indexOf(u8, d.message, "Argument of type '\"Hello\" | \"World\"' is not assignable to parameter of type '\"Hello\"'.") != null)
        {
            union_to_hello_arg_errors += 1;
        }
    }
    try T.expectEqual(@as(usize, 3), initializer_arg_errors);
    try T.expectEqual(@as(usize, 5), union_to_hello_arg_errors);
}

test "checker: string literal type argument fixture diagnostic families" {
    const s = try newSetup(
        \\// @target: es2015
        \\// @declaration: true
        \\declare function randBool(): boolean;
        \\declare function takeReturnString(str: string): string;
        \\declare function takeReturnHello(str: "Hello"): "Hello";
        \\declare function takeReturnHelloWorld(str: "Hello" | "World"): "Hello" | "World";
        \\function fun1<T>(x: T, y: T) {
        \\  return randBool() ? x : y;
        \\}
        \\function fun2<T, U>(x: T, y: U) {
        \\  return randBool() ? x : y;
        \\}
        \\function fun3<T>(...args: T[]): T {
        \\  return args[+randBool()];
        \\}
        \\namespace n1 {
        \\  export let a = fun1("Hello", "World");
        \\  export let b = fun1("Hello", "Hello");
        \\  export let c = fun2("Hello", "World");
        \\  export let d = fun2("Hello", "Hello");
        \\  export let e = fun3("Hello", "Hello", "World", "Foo");
        \\  a = takeReturnString(a);
        \\  b = takeReturnString(b);
        \\  c = takeReturnString(c);
        \\  d = takeReturnString(d);
        \\  e = takeReturnString(e);
        \\  a = takeReturnHello(a);
        \\  b = takeReturnHello(b);
        \\  c = takeReturnHello(c);
        \\  d = takeReturnHello(d);
        \\  e = takeReturnHello(e);
        \\  a = takeReturnHelloWorld(a);
        \\  b = takeReturnHelloWorld(b);
        \\  c = takeReturnHelloWorld(c);
        \\  d = takeReturnHelloWorld(d);
        \\  e = takeReturnHelloWorld(e);
        \\}
        \\namespace n2 {
        \\  export let a = fun1<"Hello">("Hello", "Hello");
        \\  export let b = fun1<"Hello">("Hello", "World");
        \\  export let c = fun2<"Hello", "Hello">("Hello", "Hello");
        \\  export let d = fun2<"Hello", "Hello">("Hello", "World");
        \\  export let e = fun3<"Hello">("Hello", "World");
        \\  a = takeReturnString(a);
        \\  b = takeReturnString(b);
        \\  c = takeReturnString(c);
        \\  d = takeReturnString(d);
        \\  e = takeReturnString(e);
        \\  a = takeReturnHello(a);
        \\  b = takeReturnHello(b);
        \\  c = takeReturnHello(c);
        \\  d = takeReturnHello(d);
        \\  e = takeReturnHello(e);
        \\  a = takeReturnHelloWorld(a);
        \\  b = takeReturnHelloWorld(b);
        \\  c = takeReturnHelloWorld(c);
        \\  d = takeReturnHelloWorld(d);
        \\  e = takeReturnHelloWorld(e);
        \\}
        \\namespace n3 {
        \\  export let a = fun2<"Hello", "World">("Hello", "World");
        \\  export let b = fun2<"Hello", "World">("World", "Hello");
        \\  export let c = fun2<"World", "Hello">("Hello", "Hello");
        \\  export let d = fun2<"World", "Hello">("World", "World");
        \\  export let e = fun3<"Hello" | "World">("Hello", "World");
        \\  a = takeReturnString(a);
        \\  b = takeReturnString(b);
        \\  c = takeReturnString(c);
        \\  d = takeReturnString(d);
        \\  e = takeReturnString(e);
        \\  a = takeReturnHello(a);
        \\  b = takeReturnHello(b);
        \\  c = takeReturnHello(c);
        \\  d = takeReturnHello(d);
        \\  e = takeReturnHello(e);
        \\  a = takeReturnHelloWorld(a);
        \\  b = takeReturnHelloWorld(b);
        \\  c = takeReturnHelloWorld(c);
        \\  d = takeReturnHelloWorld(d);
        \\  e = takeReturnHelloWorld(e);
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{
        .no_implicit_any = true,
        .strict_function_types = true,
        .strict_null_checks = true,
        .strict_property_initialization = true,
        .use_unknown_in_catch_variables = true,
        .declaration = true,
    });
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 21), checkerCountCode(s, TsCodes.argument_type_mismatch));
    try T.expectEqual(@as(usize, 15), checkerCountCode(s, TsCodes.type_not_assignable));
    var union_to_hello_arg_errors: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        try T.expect(std.mem.indexOf(u8, d.message, "Argument of type '\"Hello\"' is not assignable to parameter of type '\"Hello\"'.") == null);
        if (d.code == TsCodes.argument_type_mismatch and
            std.mem.indexOf(u8, d.message, "Argument of type '\"Hello\" | \"World\"' is not assignable to parameter of type '\"Hello\"'.") != null)
        {
            union_to_hello_arg_errors += 1;
        }
    }
    try T.expectEqual(@as(usize, 5), union_to_hello_arg_errors);
}

