test "checker: no overload match carries last overload chain and declaration" {
    const s = try newSetup(
        \\function f(x: string): number;
        \\function f(x: boolean[]): boolean;
        \\function f(x: object): object;
        \\function f(x: number): string;
        \\function f(x: any): any { return x; }
        \\declare const b: boolean;
        \\let r = f(b);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var found_head = false;
    var found_chain = false;
    var found_child = false;
    var found_related = false;
    var found_impl_related = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.no_overload_matches) continue;
        found_head = true;
        for (d.chain) |entry| {
            if (entry.code == TsCodes.last_overload_error and
                std.mem.eql(u8, entry.message, "The last overload gave the following error."))
            {
                found_chain = true;
                for (entry.children) |child| {
                    if (child.code == TsCodes.argument_type_mismatch and
                        std.mem.eql(u8, child.message, "Argument of type 'boolean' is not assignable to parameter of type 'number'."))
                    {
                        found_child = true;
                    }
                }
            }
        }
        for (d.related) |rel| {
            if (rel.code == TsCodes.last_overload_declared_here and
                std.mem.eql(u8, rel.message, "The last overload is declared here."))
            {
                found_related = true;
            }
            if (rel.code == TsCodes.overload_implementation_not_visible and
                std.mem.eql(u8, rel.message, "The call would have succeeded against this implementation, but implementation signatures of overloads are not externally visible."))
            {
                found_impl_related = true;
            }
        }
    }
    try T.expect(found_head);
    try T.expect(found_chain);
    try T.expect(found_child);
    try T.expect(found_related);
    try T.expect(found_impl_related);
}

test "checker: no overload match carries per-overload chain for small overload sets" {
    const s = try newSetup(
        \\function f(x: string): number;
        \\function f(x: number): string;
        \\function f(x: any): any { return x; }
        \\declare const b: boolean;
        \\let r = f(b);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var found_head = false;
    var found_first_overload = false;
    var found_second_overload = false;
    var found_child = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.no_overload_matches) continue;
        found_head = true;
        for (d.chain) |entry| {
            if (entry.code != TsCodes.overload_n_error) continue;
            if (std.mem.eql(u8, entry.message, "Overload 1 of 2, '(x: string): number', gave the following error.")) {
                found_first_overload = true;
            }
            if (std.mem.eql(u8, entry.message, "Overload 2 of 2, '(x: number): string', gave the following error.")) {
                found_second_overload = true;
            }
            for (entry.children) |child| {
                if (child.code == TsCodes.argument_type_mismatch) found_child = true;
            }
        }
    }
    try T.expect(found_head);
    try T.expect(found_first_overload);
    try T.expect(found_second_overload);
    try T.expect(found_child);
}

