    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.assertion_call_target_needs_explicit_annotations));
    var saw_alias_related = false;
    var saw_holder_related = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.assertion_call_target_needs_explicit_annotations) continue;
        for (d.related) |rel| {
            if (rel.code != TsCodes.assertion_call_target_name_needs_annotation) continue;
            if (std.mem.eql(u8, rel.message, "'alias' needs an explicit type annotation.")) saw_alias_related = true;
            if (std.mem.eql(u8, rel.message, "'holder' needs an explicit type annotation.")) saw_holder_related = true;
        }
    }
    try T.expect(saw_alias_related);
    try T.expect(saw_holder_related);
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.assertion_call_target_needs_explicit_annotations,
        "Assertions require every name in the call target to be declared with an explicit type annotation.",
    ));
}

