test "checker: reverse mapped target with key intersection reports excess properties" {
    const s = try newSetup(
        \\type XNumber = { x: number };
        \\declare function foo<T extends XNumber>(props: { [K in keyof T & keyof XNumber]: T[K] }): T;
        \\foo({ x: 1, y: "extra" });
        \\const checkType = <T>() => <U extends T>(value: { [K in keyof U & keyof T]: U[K] }) => value;
        \\checkType<{ x: number, y: string }>()({
        \\  x: 1 as number,
        \\  y: "y",
        \\  z: "extra",
        \\});
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.object_literal_excess_property));
    var saw_y = false;
    var saw_z = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.object_literal_excess_property) continue;
        if (std.mem.indexOf(u8, d.message, "'y' does not exist in type '{ x: 1; }'") != null) saw_y = true;
        if (std.mem.indexOf(u8, d.message, "'z' does not exist in type '{ x: number; y: \"y\"; }'") != null) saw_z = true;
    }
    try T.expect(saw_y);
    try T.expect(saw_z);
}

