test "checker: homomorphic mapped assignments compare key coverage and indexed value bases" {
    const s = try newSetup(
        \\function relations<T, U extends T, K extends keyof T>(
        \\  allT: { [P in keyof T]: T[P] },
        \\  allU: { [P in keyof U]: U[P] },
        \\  valuesU: { [P in keyof T]: U[P] },
        \\  pickedT: { [P in K]: T[P] },
        \\  pickedU: { [P in K]: U[P] },
        \\) {
        \\  allT = allU;
        \\  allU = allT;
        \\  allT = valuesU;
        \\  valuesU = allT;
        \\  pickedT = allU;
        \\  allU = pickedT;
        \\  pickedT = valuesU;
        \\  valuesU = pickedT;
        \\  pickedT = pickedU;
        \\  pickedU = pickedT;
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 5), checkerCountCode(s, TsCodes.type_not_assignable));
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.type_not_assignable,
        "Type '{ [P in keyof T]: T[P]; }' is not assignable to type '{ [P in keyof U]: U[P]; }'.",
    ));
}

test "checker: synthesized mapped utility keeps alias display after materialization" {
    const s = try newSetup(
        \\type Foo = { a: number; b: number; c?: number };
        \\declare let required: Required<Foo>;
        \\required = { a: 1 };
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.type_missing_properties));
    var saw_alias = false;
    for (s.checker.diagnostics.items) |diag| {
        if (diag.code == TsCodes.type_missing_properties and
            std.mem.indexOf(u8, diag.message, "missing the following properties from type 'Required<Foo>': b, c") != null)
        {
            saw_alias = true;
        }
    }
    try T.expect(saw_alias);
}

