        \\type T6<S extends "a" | "b", L extends "a" | "b"> = { [key in AB[S]]: true }[L];
        \\type T7<S extends "a" | "b", L extends "a"> = { [key in AB[S]]: true }[L];
    );
    defer destroySetup(s);
