        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const stmts = hir_mod.blockStmts(&s.hir, s.root);
    const covariant_tp = hir_mod.interfaceOf(&s.hir, stmts[0]).type_params_start;
    const contravariant_tp = hir_mod.interfaceOf(&s.hir, stmts[1]).type_params_start;
    const invariant_tp = hir_mod.interfaceOf(&s.hir, stmts[2]).type_params_start;
    try T.expectEqual(types.Variance.covariant, s.checker.typeParameterVariance(s.hir.typeOf(s.hir.childSlice(covariant_tp, 1)[0])));
    try T.expectEqual(types.Variance.contravariant, s.checker.typeParameterVariance(s.hir.typeOf(s.hir.childSlice(contravariant_tp, 1)[0])));
    try T.expectEqual(types.Variance.invariant, s.checker.typeParameterVariance(s.hir.typeOf(s.hir.childSlice(invariant_tp, 1)[0])));
}

test "checker: conditional interface variance controls generic assignment direction" {
    const s = try newSetup(
        \\interface Covariant<T> {
        \\  foo: T extends string ? T : number;
        \\}
        \\interface Contravariant<T> {
        \\  foo: T extends string ? keyof T : number;
        \\}
        \\interface Invariant<T> {
        \\  foo: T extends string ? keyof T : T;
        \\}
        \\function f1<A, B extends A>(a: Covariant<A>, b: Covariant<B>) {
        \\  a = b;
        \\  b = a;
        \\}
        \\function f2<A, B extends A>(a: Contravariant<A>, b: Contravariant<B>) {
        \\  a = b;
        \\  b = a;
        \\}
        \\function f3<A, B extends A>(a: Invariant<A>, b: Invariant<B>) {
        \\  a = b;
        \\  b = a;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_covariant_reverse = false;
    var saw_contravariant_reverse = false;
    var saw_invariant: usize = 0;
    var total: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        total += 1;
        if (std.mem.indexOf(u8, d.message, "Type 'Covariant<A>' is not assignable to type 'Covariant<B>'.") != null) {
            saw_covariant_reverse = true;
        }
        if (std.mem.indexOf(u8, d.message, "Type 'Contravariant<B>' is not assignable to type 'Contravariant<A>'.") != null) {
            saw_contravariant_reverse = true;
        }
        if (std.mem.indexOf(u8, d.message, "Invariant<") != null) saw_invariant += 1;
    }
    try T.expectEqual(@as(usize, 4), total);
    try T.expect(saw_covariant_reverse);
    try T.expect(saw_contravariant_reverse);
    try T.expectEqual(@as(usize, 2), saw_invariant);
}

