test "checker: contextual generic callback instantiation rejects conflicting params" {
    const s = try newSetup(
        \\declare function foo<T>(cb: (x: number, y: string) => T): T;
        \\declare function bar<T, U, V>(x: T, y: U, cb: (x: T, y: U) => V): V;
        \\declare function baz<T, U>(x: T, y: T, cb: (x: T, y: T) => U): U;
        \\declare function g<T>(x: T, y: T): T;
        \\declare function h<T, U>(x: T, y: U): T[] | U[];
        \\var a: number;
        \\var a = bar(1, 1, g);
        \\var a = baz(1, 1, g);
        \\var b: number | string;
        \\var b = foo(g);
        \\var b = bar(1, "one", g);
        \\var b = bar("one", 1, g);
        \\var b = baz(b, b, g);
        \\var d: number[] | string[];
        \\var d = foo(h);
        \\var d = bar(1, "one", h);
        \\var d = bar("one", 1, h);
        \\var d = baz(d, d, g);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 6), s.checker.diagnostics.items.len);
    try T.expectEqual(@as(usize, 3), checkerCountCode(s, TsCodes.subsequent_var_type_mismatch));
    try T.expectEqual(@as(usize, 3), checkerCountCode(s, TsCodes.argument_type_mismatch));
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.subsequent_var_type_mismatch,
        "Subsequent variable declarations must have the same type.  Variable 'b' must be of type 'string | number', but here has type 'unknown'.",
    ));
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.argument_type_mismatch,
        "Argument of type '<T>(x: T, y: T) => T' is not assignable to parameter of type '(x: number, y: string) => number'.",
    ));
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.argument_type_mismatch,
        "Argument of type '<T>(x: T, y: T) => T' is not assignable to parameter of type '(x: string, y: number) => string'.",
    ));
}

test "checker: inferential callbacks fix annotations and nested literal returns" {
    const s = try newSetup(
        \\function foo2<T, U>(x: T, a: (x: T) => U, b: (x: T) => U) {
        \\  let r!: (x: T) => U;
        \\  return r;
        \\}
        \\declare let x: (a: string) => boolean;
        \\foo2(x, (a1: (y: string) => string) => (n: Object) => 1, (a2: (z: string) => string) => 2);
        \\foo2(x, (a1: (y: string) => boolean) => (n: Object) => 1, (a2: (z: string) => boolean) => 2);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.argument_type_mismatch));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.type_not_assignable));
    try T.expectEqual(@as(usize, 1), checkerCountChainCode(s, TsCodes.types_of_parameters_incompatible));
    var saw_annotated_source = false;
    var saw_nested_literal_target = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.argument_type_mismatch) continue;
        if (std.mem.indexOf(u8, d.message, "(a1: (y: string) => string)") != null) saw_annotated_source = true;
        if (std.mem.indexOf(u8, d.message, "(n: Object) => 1") != null) saw_nested_literal_target = true;
    }
    try T.expect(saw_annotated_source);
    try T.expect(saw_nested_literal_target);
}

