test "checker: NoInfer blocks nested generic call candidates" {
    const b = try newBoundSetup(
        \\declare function foo1<T extends string>(a: T, b: NoInfer<T>): void;
        \\declare function foo2<T extends string>(a: T, b: NoInfer<T>[]): void;
        \\declare function foo3<T extends string>(a: T, b: NoInfer<T[]>): void;
        \\declare function foo4<T extends string>(a: T, b: { x: NoInfer<T> }): void;
        \\declare function foo5<T extends string>(a: T, b: NoInfer<{ x: T }>): void;
        \\declare class Animal { move(): void }
        \\declare class Dog extends Animal { woof(): void }
        \\declare function doSomething<T>(value: T, getDefault: () => NoInfer<T>): void;
        \\foo1('foo', 'bar');
        \\foo2('foo', ['bar']);
        \\foo3('foo', ['bar']);
        \\foo4('foo', { x: 'bar' });
        \\foo5('foo', { x: 'bar' });
        \\doSomething(new Dog(), () => new Animal());
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expectEqual(@as(usize, 6), b.base.checker.diagnostics.items.len);
    try T.expect(checkerHasCodeWithMessage(
        b,
        TsCodes.argument_type_mismatch,
        "Argument of type '\"bar\"' is not assignable to parameter of type '\"foo\"'.",
    ));
    var nested_literal_errors: usize = 0;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_assignable and
            std.mem.eql(u8, d.message, "Type '\"bar\"' is not assignable to type '\"foo\"'."))
        {
            nested_literal_errors += 1;
        }
    }
    try T.expectEqual(@as(usize, 4), nested_literal_errors);
    try T.expect(checkerHasCodeWithMessage(
        b,
        TsCodes.property_missing_required,
        "Property 'woof' is missing in type 'Animal' but required in type 'Dog'.",
    ));
}

