test "checker: template literal union diagnostics keep union display" {
    const s = try newSetup(
        \\function f(s: string, cond: boolean) {
        \\  const c1 = cond ? `foo${s}` : `bar${s}`;
        \\  const c2: `foo${string}` | `bar${string}` = c1;
        \\  const c3 = cond ? c1 : c2;
        \\  const c4 = cond ? c3 : `baz${s}`;
        \\  const c5: `foo${string}` | `bar${string}` | `baz${string}` = c4;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var found_pair = false;
    var found_triple = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        if (std.mem.eql(u8, d.message, "Type 'string' is not assignable to type '`bar${string}` | `foo${string}`'.")) {
            found_pair = true;
        }
        if (std.mem.eql(u8, d.message, "Type 'string' is not assignable to type '`bar${string}` | `baz${string}` | `foo${string}`'.")) {
            found_triple = true;
        }
    }
    try T.expect(found_pair);
    try T.expect(found_triple);
}

test "checker: generic predicate infers type parameter from union remainder" {
