test "checker: generic NonNullable assigns back to its source type" {
    const s = try newSetup(
        \\function f1<T>(x: T, y: NonNullable<T>) {
        \\  x = y;
        \\  y = x;
        \\}
        \\function f2<T extends string | undefined>(x: T, y: NonNullable<T>) {
        \\  x = y;
        \\  y = x;
        \\  let s1: string = x;
        \\  let s2: string = y;
        \\}
        \\function f3<T>(x: Partial<T>[keyof T], y: NonNullable<Partial<T>[keyof T]>) {
        \\  x = y;
        \\  y = x;
        \\}
        \\function f4<T extends { x: string | undefined }>(x: T["x"], y: NonNullable<T["x"]>) {
        \\  x = y;
        \\  y = x;
        \\  let s1: string = x;
        \\  let s2: string = y;
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
    var assign_errors: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.arbitrary_type_parameter_instantiation_unrelated);
        try T.expect(std.mem.indexOf(u8, d.message, "NonNullable<T>' is not assignable to type 'string'") == null);
        if (d.code == TsCodes.type_not_assignable) assign_errors += 1;
    }
    try T.expectEqual(@as(usize, 4), assign_errors);
    try T.expect(hasDiagnosticCodeMessage(s, TsCodes.type_not_assignable, "Type 'T[keyof T] | undefined' is not assignable to type 'NonNullable<Partial<T>[keyof T]>'."));
    try T.expect(hasDiagnosticCodeMessage(s, TsCodes.type_not_assignable, "Type 'T[\"x\"]' is not assignable to type 'NonNullable<T[\"x\"]>'."));
    try T.expect(hasDiagnosticCodeMessage(s, TsCodes.type_not_assignable, "Type 'T' is not assignable to type 'NonNullable<T>'."));
}

