    var saw_not_callable = false;
    var saw_ts2756_chain = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.not_callable) {
            saw_not_callable = true;
            try T.expectEqual(@as(usize, 1), d.chain.len);
            if (d.chain[0].code == TsCodes.not_all_constituents_callable) {
                saw_ts2756_chain = true;
