test "checker: TS2513 fires for super access to an abstract base method" {
    // Mirrors upstream `classAbstractSuperCalls.ts`: `super.foo` from
    // `C` resolves to `B.foo` (abstract) → TS2513 twice (call + read),
    // naming the declaring base class `B`. The `super.foo()` inside
    // `B.bar()` resolves to the concrete `A.foo` and must NOT error.
    const s = try newSetup(
        \\class A { foo() { return 1; } }
        \\abstract class B extends A {
        \\  abstract foo(): number;
        \\  bar() { return super.foo(); }
        \\}
        \\class C extends B {
        \\  foo() { return 2; }
        \\  qux() { return super.foo() || super.foo; }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.abstract_method_via_super));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.abstract_method_via_super) {
            try T.expectEqualStrings("Abstract method 'foo' in class 'B' cannot be accessed via super expression.", d.message);
        }
    }
}

