test "checker: TS2564 anchors resolved computed keys at opening bracket" {
    const source =
        \\declare const key: unique symbol;
        \\class C {
        \\    [key]: string;
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_property_initialization = true, .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);

    const expected_pos: u32 = @intCast(std.mem.indexOf(u8, source, "[key]").?);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.property_not_initialized) continue;
        found = true;
        try T.expectEqual(expected_pos, d.pos orelse s.hir.spanOf(d.node).start);
    }
    try T.expect(found);
}

