test "checker: TypeBox object static synthesizes from concrete properties" {
    const s = try newBoundSetup(
        \\export type Input = Static<typeof Input>;
        \\export const Input = Type.Object({ level1: Type.Object({ level2: Type.Object({ foo: Type.String() }) }) });
        \\export type Output = Static<typeof Output>;
        \\export const Output = Type.Object({ level1: Type.Object({ level2: Type.Object({ foo: Type.String(), bar: Type.String() }) }) });
        \\export type PropertiesReduce<T extends TProperties, P extends unknown[]> = unknown;
        \\export type TPropertyKey = string | number;
        \\export type TProperties = Record<TPropertyKey, TSchema>;
        \\export interface TSchema { params: unknown[]; static: unknown; }
        \\export interface TString extends TSchema { static: string; }
        \\export interface TObject<T extends TProperties = TProperties> extends TSchema {
        \\  static: PropertiesReduce<T, this["params"]>;
        \\  properties: T;
        \\}
        \\export type Static<T extends TSchema, P extends unknown[] = []> = (T & { params: P })["static"];
        \\declare namespace Type {
        \\  function Object<T extends TProperties>(object: T): TObject<T>;
        \\  function String(): TString;
        \\}
        \\function bad1(ors: Input[]): Output[] { return ors; }
        \\function bad2(ors: (typeof Input.static)[]): Output[] { return ors; }
    );
    defer destroyBoundSetup(s);
    try s.base.checker.checkSourceFile(s.base.root);
    var assignability_count: usize = 0;
    for (s.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_assignable) assignability_count += 1;
        try T.expect(d.code != TsCodes.generic_type_requires_args);
    }
    try T.expect(assignability_count >= 2);
}

