        found_header = true;
        try T.expectEqualStrings(
            "Argument of type 'typeof B' is not assignable to parameter of type 'typeof A'.",
            d.message,
        );
        try T.expectEqual(@as(usize, 1), d.chain.len);
        if (d.chain[0].code == TsCodes.abstract_constructor_to_non_abstract) {
            try T.expectEqualStrings(
