        try T.expect(d.code != TsCodes.cannot_find_name);
        if (d.code == TsCodes.enum_member_must_have_initializer and
            std.mem.eql(u8, d.message, "Enum member must have initializer."))
        {
            found = true;
        }
    }
    try T.expect(found);
}

test "checker: TS1061 not fired for all-constant or trailing-computed enums" {
    // `enum E { A = 1, B }` auto-increments cleanly; `enum F { A, B =
    // 1 + 1 }` folds the binary op to a constant; a trailing computed
    // member is allowed because nothing follows it. None warrant
    // TS1061.
    const s = try newSetup(
        \\enum E { A = 1, B }
        \\enum F { A, B = 1 + 1 }
        \\enum G { A = 0, B = "x".length }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.enum_member_must_have_initializer);
    }
}

