test "checker: TS18055 for imported string enum initializer under isolatedModules" {
    const s = try newSetup(
        \\// @filename: ./foo.ts
        \\import { BAR } from './bar';
        \\const LOCAL = 'LOCAL';
        \\enum Foo {
        \\  A = `${BAR}`,
        \\  B = LOCAL,
        \\  C = B,
        \\  D = C + 'BAR',
        \\  F = BAR,
        \\  G = 2 + BAR,
        \\  H = A,
        \\  I = H + BAR,
        \\}
        \\// @filename: ./bar.ts
        \\export const BAR = 'bar';
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .isolated_modules = true });
    try s.checker.checkSourceFile(s.root);

    var found_f = false;
    var found_g = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.enum_string_value_requires_string_syntax_isolated) {
            if (std.mem.indexOf(u8, d.message, "'Foo.F'") != null) found_f = true;
            if (std.mem.indexOf(u8, d.message, "'Foo.G'") != null) found_g = true;
        }
        try T.expect(d.code != TsCodes.enum_value_not_number);
    }
    try T.expect(found_f);
    try T.expect(found_g);
}

