test "checker: TS9007 carries TS9030/TS9031 return-type related info" {
    const s = try newSetup(
        \\export function decl() { return 1; }
        \\export const expr = () => 1;
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .isolated_declarations = true });
    try s.checker.checkSourceFile(s.root);

    var saw_decl_related = false;
    var saw_expr_related = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.isolated_declarations_function_missing_return_type) continue;
        for (d.related) |rel| {
            if (rel.code == TsCodes.add_return_type_to_function_declaration and
                std.mem.eql(u8, rel.message, "Add a return type to the function declaration."))
            {
                saw_decl_related = true;
            }
            if (rel.code == TsCodes.add_return_type_to_function_expression and
                std.mem.eql(u8, rel.message, "Add a return type to the function expression."))
            {
                saw_expr_related = true;
            }
        }
    }
    try T.expect(saw_decl_related);
    try T.expect(saw_expr_related);
}

test "checker: TS9010 for exported variables needing declaration type inference" {
    const source =
        \\declare function id(): number;
        \\export const direct = id();
        \\const later = id();
        \\export { later };
        \\export const literal = 1;
        \\export const annotated: number = id();
        \\const local = id();
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .isolated_declarations = true });
    try s.checker.checkSourceFile(s.root);

    var direct_found = false;
    var later_found = false;
    var count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.isolated_declarations_variable_missing_type) {
            count += 1;
            try T.expectEqualStrings("Variable must have an explicit type annotation with --isolatedDeclarations.", d.message);
            const pos = d.pos orelse s.checker.hir.spanOf(d.node).start;
            if (std.mem.startsWith(u8, source[pos..], "direct")) direct_found = true;
            if (std.mem.startsWith(u8, source[pos..], "later")) later_found = true;
            try T.expect(!std.mem.startsWith(u8, source[pos..], "literal"));
            try T.expect(!std.mem.startsWith(u8, source[pos..], "annotated"));
            try T.expect(!std.mem.startsWith(u8, source[pos..], "local"));
        }
    }
    try T.expectEqual(@as(usize, 2), count);
    try T.expect(direct_found);
    try T.expect(later_found);
}

test "checker: TS9011 for asserted default before required parameter under isolatedDeclarations" {
    const source =
        \\export function foo(p = (ip = 10, v: number): void => {}): void {}
        \\type T = number;
        \\export function foo2(p = (ip = 10 as T, v: number): void => {}): void {}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .isolated_declarations = true, .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);

    var found = false;
    var count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.isolated_declarations_parameter_missing_type) continue;
        count += 1;
        const pos = d.pos orelse s.checker.hir.spanOf(d.node).start;
        try T.expectEqualStrings("T", source[pos .. pos + 1]);
        try T.expect(d.related.len == 1);
        try T.expectEqual(TsCodes.add_type_annotation_to_parameter, d.related[0].code);
        const related_pos = s.checker.hir.spanOf(d.related[0].node).start;
        try T.expectEqualStrings("ip", source[related_pos .. related_pos + 2]);
        found = true;
    }
    try T.expect(found);
    try T.expectEqual(@as(usize, 1), count);
}

test "checker: TS9023 for exported expando function properties under isolatedDeclarations" {
    const source =
        \\export function direct(): void {}
        \\direct.x = 1;
        \\direct["y"] = 2;
        \\direct.length = 3;
        \\function later(): void {}
        \\later.z = 4;
        \\later.z = 5;
        \\export { later };
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .isolated_declarations = true });
    try s.checker.checkSourceFile(s.root);

    var found_x = false;
    var found_y = false;
    var found_length = false;
    var found_z = false;
    var count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.isolated_declarations_expando_function_property) {
            count += 1;
            try T.expectEqualStrings("Assigning properties to functions without declaring them is not supported with --isolatedDeclarations. Add an explicit declaration for the properties assigned to this function.", d.message);
            const pos = d.pos orelse s.checker.hir.spanOf(d.node).start;
            if (std.mem.startsWith(u8, source[pos..], "direct.x")) found_x = true;
            if (std.mem.startsWith(u8, source[pos..], "direct[\"y\"]")) found_y = true;
            if (std.mem.startsWith(u8, source[pos..], "direct.length")) found_length = true;
            if (std.mem.startsWith(u8, source[pos..], "later.z")) found_z = true;
        }
    }
    try T.expectEqual(@as(usize, 4), count);
    try T.expect(found_x);
    try T.expect(found_y);
    try T.expect(found_length);
    try T.expect(found_z);
}

