test "checker: TS18057 for string-literal import and export names under ES2015 modules" {
    const s = try newSetup(
        \\// @module: es2015
        \\import { "import-name" as imported } from "./m";
        \\const local = 1;
        \\export { local as "export-name" };
        \\export { "source-name" as "target-name" } from "./m";
        \\export * as "ns-name" from "./m";
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    const src = s.checker.source.?;
    const expected = [_][]const u8{ "\"import-name\"", "\"export-name\"", "\"source-name\"", "\"target-name\"", "\"ns-name\"" };
    var found: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.string_literal_import_export_names_bad_module) continue;
        const pos = d.pos orelse s.checker.hir.spanOf(d.node).start;
        for (expected) |needle| {
            const expected_pos = std.mem.indexOf(u8, src, needle) orelse unreachable;
            if (pos == expected_pos) {
                found += 1;
                break;
            }
        }
    }
    try T.expectEqual(expected.len, found);
}

