test "checker: discriminated unions retain generic, nullish, truthy, and intersected variants" {
    const s = try newSetup(
        \\function excess(x: { a: null; b: string } | { a: string; c: number }) {
        \\  x = { a: null, b: "foo", c: 4 };
        \\}
        \\function generic<T>(x: { a: 0; b: string } | { a: T; c: number }) {
        \\  if (x.a === 0) x.b;
        \\}
        \\type Result<T> = { error?: undefined; value: T } | { error: Error };
        \\function result(x: Result<number>) {
        \\  if (!x.error) x.value;
        \\  else x.error.message;
        \\}
        \\interface WithError { error: Error; data: null }
        \\interface WithoutError<Data> { error: null; data: Data }
        \\type DataCarrier<Data> = WithError | WithoutError<Data>;
        \\function carrier<Data>(x: DataCarrier<Data>) {
        \\  if (x.error === null) {
        \\    const data: Data = x.data;
        \\  } else {
        \\    const data: null = x.data;
        \\  }
        \\}
        \\type A = { type: "a"; data: string };
        \\type B = { type: "b"; name: string };
        \\type C = { type: "c"; other: string };
        \\type ABC = A | B | C;
        \\function intersected(problem: ABC & (B | C)) {
        \\  if (problem.type === "b") problem.name;
        \\  else problem.other;
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 2), s.checker.diagnostics.items.len);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.object_literal_excess_property));
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.property_does_not_exist));
    try T.expect(hasDiagnosticCodeMessage(
        s,
        TsCodes.property_does_not_exist,
        "Property 'b' does not exist on type '{ a: 0; b: string; } | { a: T; c: number; }'.",
    ));
}

test "checker: if x.kind === literal narrows non-discriminant field access" {
    // Discriminated-union narrowing on if-equals: inside the
    // then-branch `x` is narrowed to the matching variant, so access
    // to `x.r` (only present on the circle variant) must type as
    // `number` rather than failing or widening.
    const s = try newSetup(
        \\type Shape = { kind: "circle"; r: number } | { kind: "square"; s: number };
        \\function area(x: Shape) {
        \\  if (x.kind === "circle") {
        \\    let r = x.r;
        \\  }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expect(s.checker.diagnostics.items.len == 0);
    const stmts = hir_mod.blockStmts(&s.hir, s.root);
    const fn_node = stmts[1];
    const f = hir_mod.fnDeclOf(&s.hir, fn_node);
    const body_stmts = hir_mod.blockStmts(&s.hir, f.body);
    const if_stmt = body_stmts[0];
    const ifp = hir_mod.ifOf(&s.hir, if_stmt);
    const then_stmts = hir_mod.blockStmts(&s.hir, ifp.then_branch);
    // `let r = x.r` ÃÂ¢ÃÂÃÂ `x.r` should resolve under the circle variant.
    const r_init = hir_mod.varDeclOf(&s.hir, then_stmts[0]).init;
    try T.expectEqual(types.Primitive.number_t, s.hir.typeOf(r_init));
}

test "checker: if x.kind !== literal narrows other variant in then-branch" {
    // `!==` flips the polarity: the then-branch sees `x` narrowed to
    // the union members whose discriminant *isn't* the literal. With
    // two variants and one excluded, that's a single variant ÃÂ¢ÃÂÃÂ so a
    // field unique to the remaining variant types correctly.
    const s = try newSetup(
        \\type S = { k: "a"; va: number } | { k: "b"; vb: string };
        \\function f(x: S) {
        \\  if (x.k !== "a") {
        \\    let v = x.vb;
        \\  }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expect(s.checker.diagnostics.items.len == 0);
    const stmts = hir_mod.blockStmts(&s.hir, s.root);
    const fn_node = stmts[1];
    const f = hir_mod.fnDeclOf(&s.hir, fn_node);
    const body_stmts = hir_mod.blockStmts(&s.hir, f.body);
    const if_stmt = body_stmts[0];
    const ifp = hir_mod.ifOf(&s.hir, if_stmt);
    const then_stmts = hir_mod.blockStmts(&s.hir, ifp.then_branch);
    // `let v = x.vb` ÃÂ¢ÃÂÃÂ only the `b` variant has `vb`, and it types as
    // `string`.
    const v_init = hir_mod.varDeclOf(&s.hir, then_stmts[0]).init;
    try T.expectEqual(types.Primitive.string_t, s.hir.typeOf(v_init));
}

test "checker: switch on x.kind narrows non-discriminant field per case" {
    // Switch-discriminant narrowing ÃÂ¢ÃÂÃÂ each case body sees `x` as the
    // matching variant, so a field that's unique to that variant
    // types under the variant's declaration (rather than emitting a
    // missing-property error or widening to a union of variant
    // fields).
    const s = try newSetup(
        \\type Shape = { kind: "circle"; r: number } | { kind: "square"; s: string };
        \\function area(x: Shape) {
        \\  switch (x.kind) {
        \\    case "circle": let r = x.r; break;
        \\    case "square": let s = x.s; break;
        \\  }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expect(s.checker.diagnostics.items.len == 0);
    const stmts = hir_mod.blockStmts(&s.hir, s.root);
    const fn_node = stmts[1];
    const f = hir_mod.fnDeclOf(&s.hir, fn_node);
    const body_stmts = hir_mod.blockStmts(&s.hir, f.body);
    const sw_node = body_stmts[0];
    const cases = hir_mod.switchCases(&s.hir, sw_node);
    // case "circle" ÃÂ¢ÃÂÃÂ `r` from circle's declaration types as number.
    const c_stmts = hir_mod.switchCaseStmts(&s.hir, cases[0]);
    const r_init = hir_mod.varDeclOf(&s.hir, c_stmts[0]).init;
    try T.expectEqual(types.Primitive.number_t, s.hir.typeOf(r_init));
    // case "square" ÃÂ¢ÃÂÃÂ `s` from square's declaration types as string.
    const sq_stmts = hir_mod.switchCaseStmts(&s.hir, cases[1]);
    const s_init = hir_mod.varDeclOf(&s.hir, sq_stmts[0]).init;
    try T.expectEqual(types.Primitive.string_t, s.hir.typeOf(s_init));
}

test "checker: tagged template ÃÂ¢ÃÂÃÂ typed tag returns its declared return type" {
    // Tagged template literals desugar to a call
    // `tag(stringsArr, ÃÂ¢ÃÂÃÂ¦values)`; v0 types `stringsArr` as `string[]`
    // (no TemplateStringsArray shape yet) and reads the call's return
    // type from the tag's declared signature.
    const s = try newSetup(
        \\function tag(s: string[]): string { return ""; }
        \\const r = tag`abc`;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const stmts = hir_mod.blockStmts(&s.hir, s.root);
    const decl = hir_mod.varDeclOf(&s.hir, stmts[1]);
    const call_expr = decl.init;
    try T.expectEqual(types.Primitive.string_t, s.hir.typeOf(call_expr));
}

test "checker: tagged template ÃÂ¢ÃÂÃÂ untyped tag (any) yields any" {
    // When the tag's type is `any`, the tagged-template call types
