test "checker: template target diagnostics preserve string literal source display" {
    const s = try newSetup(
        \\let x: `*${string}*`;
        \\x = "hello";
        \\let y: `*${number}*`;
        \\y = "123";
        \\y = "**123**";
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);

    var saw_hello = false;
    var saw_123 = false;
    var saw_star_123 = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        if (std.mem.eql(u8, d.message, "Type '\"hello\"' is not assignable to type '`*${string}*`'.")) saw_hello = true;
        if (std.mem.eql(u8, d.message, "Type '\"123\"' is not assignable to type '`*${number}*`'.")) saw_123 = true;
        if (std.mem.eql(u8, d.message, "Type '\"**123**\"' is not assignable to type '`*${number}*`'.")) saw_star_123 = true;
    }
    try T.expect(saw_hello);
    try T.expect(saw_123);
    try T.expect(saw_star_123);
}

