test "checker: finite template union satisfies its inferred generic parameter" {
    const s = try newSetup(
        \\declare function takesLiteral<T extends string>(literal: T): T;
        \\declare const someUnion: "abc" | "def" | "ghi";
        \\const inferred = takesLiteral(`foo.bar.${someUnion}`);
