    const inferred_t = s.hir.typeOf(stmts[2]);
    try T.expect(inferred_t < s.checker.interner.pool.typeCount());
    for ([_][]const u8{ "foo.bar.abc", "foo.bar.def", "foo.bar.ghi" }) |text| {
        const sid = s.checker.string_interner.intern(text) catch return error.OutOfMemory;
        try T.expect(try s.checker.stringLiteralAssignableToType(sid, inferred_t));
    }
    const unrelated_sid = s.checker.string_interner.intern("foo.bar.xyz") catch return error.OutOfMemory;
    try T.expect(!try s.checker.stringLiteralAssignableToType(unrelated_sid, inferred_t));
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.argument_type_mismatch));
}

