test "checker: private names preserve class identity through expressions and object rest" {
    const s = try newSetup(
        \\class A {
        \\  static get #fieldFunc2() { return function(a, ...b) {}; }
        \\  static #fieldFunc3 = function(a, ...b) {};
        \\  static test() {
        \\    const arr = [1, 2];
        \\    this.#fieldFunc2(0, ...arr, 3);
        \\    new this.#fieldFunc2(0, ...arr, 3);
        \\    this.getClass().#fieldFunc2`test${1}`;
        \\  }
        \\  static getClass() { return A; }
        \\  testInstance() {
        \\    const arr = [1, 2];
        \\    this.getClass().#fieldFunc3(0, ...arr, 3);
        \\    this.getClass().#fieldFunc3`test${1}`;
        \\  }
        \\  getClass() { return A; }
        \\}
        \\class StaticCounter {
        \\  static #test = 1;
        \\  getClass() { return StaticCounter; }
        \\  m() { this.getClass().#test++; }
        \\}
        \\const CExpr = class {
        \\  #field = this.#method();
        \\  #method() { return 42; }
        \\  static getInstance() { return new CExpr(); }
        \\}
        \\CExpr.getInstance().#method;
        \\CExpr.getInstance().#field;
        \\class C {
        \\  #prop = 1;
        \\  static #propStatic = 1;
        \\  method(other: C) {
        \\    const obj = { ...other };
        \\    obj.#prop;
        \\    const { ...rest } = other;
        \\    rest.#prop;
        \\    const statics = { ...C };
        \\    statics.#propStatic;
        \\    const { ...sRest } = C;
        \\    sRest.#propStatic;
        \\  }
        \\}
        \\class Branded {
        \\  #brand;
        \\  ok(x: I) { x.#brand = 1; }
        \\}
        \\interface I extends Branded {}
        \\function outside(x: I) { x.#brand = 1; }
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);

    var missing_private_spread: usize = 0;
    var outside_private: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.property_does_not_exist and
            (std.mem.indexOf(u8, d.message, "#fieldFunc2") != null or
                std.mem.indexOf(u8, d.message, "#fieldFunc3") != null or
                std.mem.indexOf(u8, d.message, "#test") != null))
        {
            return error.TestUnexpectedResult;
        }
        if (d.code == TsCodes.property_does_not_exist and
            (std.mem.indexOf(u8, d.message, "#prop") != null or std.mem.indexOf(u8, d.message, "#propStatic") != null))
        {
            missing_private_spread += 1;
        }
        if (d.code == TsCodes.ecma_private_not_accessible_outside_class or d.code == 18016) outside_private += 1;
    }
    try T.expectEqual(@as(usize, 4), missing_private_spread);
    try T.expectEqual(@as(usize, 3), outside_private);
}

