        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_spread_tail_mismatch = false;
    var saw_too_few = false;
    var saw_real_mismatch = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.argument_type_mismatch and
            std.mem.eql(u8, d.message, "Argument of type 'string | number' is not assignable to parameter of type 'boolean'."))
        {
            saw_spread_tail_mismatch = true;
        }
        if (d.code == TsCodes.expected_at_least_n_arguments) saw_too_few = true;
        if (d.code == TsCodes.argument_type_mismatch and
            std.mem.eql(u8, d.message, "Argument of type 'number' is not assignable to parameter of type 'boolean'."))
        {
            saw_real_mismatch = true;
        }
    }
    try T.expect(!saw_spread_tail_mismatch);
    try T.expect(saw_too_few);
    try T.expect(saw_real_mismatch);
}

