test "checker: TS2372 wording matches upstream tsc (no 'in its initializer' tail)" {
    // Mirrors upstream diagnosticMessages.json key
    // `Parameter '{0}' cannot reference itself.` ÃÂ¢ÃÂÃÂ the trailing
    // "in its initializer." we used to emit caused an exact-baseline
    // mismatch across the async/await es5/es6/es2017 cluster.
    const s = try newSetup(
        \\function f(await = await) {}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found_exact = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.parameter_cannot_reference_self) continue;
        // Exact upstream wording, no trailing " in its initializer.".
        if (std.mem.eql(u8, d.message, "Parameter 'await' cannot reference itself.")) {
            found_exact = true;
        }
        // Hard-fail if the legacy wording crept back.
        try T.expect(std.mem.indexOf(u8, d.message, "in its initializer") == null);
    }
    try T.expect(found_exact);
}

test "checker: async function with non-Promise return type emits TS1064/TS1065" {
    // Mirrors `asyncFunctionDeclaration15_es6` (`async function fn4(): number`)
    // and the non-Promise qualified path (`async function f(): X.Bag<void>`
    // where `Bag` doesn't extend `Promise`). Bare and qualified type-ref
    // names emit the TS1064 "Did you mean to write 'Promise<X>'?"
    // variant.
    const s = try newSetup(
        \\async function fn4(): number { }
        \\async function fn6(): Thenable { }
        \\namespace X { export class Bag<T> {} }
        \\async function fq(): X.Bag<void> { }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var ts1064: u32 = 0;
    var saw_qualified_suggestion = false;
    var saw_number_suggestion = false;
    var saw_thenable_suggestion = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.async_return_must_be_promise_did_you_mean) {
            ts1064 += 1;
            if (std.mem.indexOf(u8, d.message, "Promise<number>") != null) saw_number_suggestion = true;
            if (std.mem.indexOf(u8, d.message, "Promise<Thenable>") != null) saw_thenable_suggestion = true;
            if (std.mem.indexOf(u8, d.message, "Promise<void>") != null) saw_qualified_suggestion = true;
        }
    }
    // `number`, `Thenable`, and `X.Bag<void>` all use TS1064.
    try T.expect(ts1064 >= 3);
    try T.expect(saw_number_suggestion);
    try T.expect(saw_thenable_suggestion);
    try T.expect(saw_qualified_suggestion);
}

test "checker: ES5 async return annotations require Promise-compatible constructor values" {
