    const alias_name = try s.sint.intern("Tree");
    try T.expect(s.checker.generic_aliases.contains(alias_name));
    // The annotation `Tree<number>` on `root` should lower to an
    // object type (its `value` member typed as `number`). The
    // assignment of `{ value: 1, children: [] }` should not emit a
    // TS2322 (type-not-assignable) diagnostic.
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
    }
}

test "checker: mutually recursive type aliases ÃÂ¢ÃÂÃÂ `A = { b: B }; B = { a: A }` register both names" {
    // `type A = { b: B }; type B = { a: A };` ÃÂ¢ÃÂÃÂ A's body sees B before
    // B is encountered, and B's body refers back to A. Pre-registering
    // both names with placeholder bodies makes mutual recursion work
    // without infinite recursion or panic.
    const s = try newSetup(
        \\type A = { b: B };
        \\type B = { a: A };
        \\let x: A = { b: { a: { b: { a: null as any } } } };
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const a_name = try s.sint.intern("A");
    const b_name = try s.sint.intern("B");
    // Both aliases must be registered as named types after the pass.
    try T.expect(s.checker.type_names.contains(a_name));
    try T.expect(s.checker.type_names.contains(b_name));
    // The stored type for A must be an object type with the `b` member,
    // not the `unknown` placeholder left over from pre-registration.
    const a_t = s.checker.type_names.get(a_name).?;
    try T.expect(s.checker.interner.pool.flagsOf(a_t).is_object_type);
}

test "checker: generic type-arg inference ÃÂ¢ÃÂÃÂ array element `id<T>(x: T[]): T[]` infers T from `[1,2,3]`" {
    // Call-site argument `[1,2,3]` is `number[]`; the parameter shape
    // `T[]` should drive `T = number`, making the return type
    // `number[]` ÃÂ¢ÃÂÃÂ an object type whose number indexer is `number`.
    const s = try newSetup(
        \\function id<T>(x: T[]): T[] { return x; }
        \\let r = id([1, 2, 3]);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const stmts = hir_mod.blockStmts(&s.hir, s.root);
    const decl = hir_mod.varDeclOf(&s.hir, stmts[1]);
    const call_t = s.hir.typeOf(decl.init);
    try T.expect(s.checker.interner.pool.flagsOf(call_t).is_object_type);
    const elem = s.checker.interner.objectNumberIndex(call_t);
    try T.expectEqual(types.Primitive.number_t, elem);
}

test "checker: generic type-arg inference ÃÂ¢ÃÂÃÂ object property `key<T>(o: { value: T }): T` infers T from o.value" {
    // The parameter shape `{ value: T }` against an argument
    // `{ value: 42 }` (whose `value` is the number-literal 42) should
    // yield `T = number` after literal widening, so the call's return
    // type is the primitive `number`.
    const s = try newSetup(
        \\function key<T>(o: { value: T }): T { return o.value; }
