    const decl = hir_mod.varDeclOf(&s.hir, stmts[1]);
    try T.expectEqual(types.Primitive.number_t, s.hir.typeOf(decl.init));
}

test "checker: overload inference flows through homomorphic mapped props" {
    const s = try newSetup(
        \\interface Instance { _instanceBrand: never }
        \\type DataDef<Data, Props> = (this: Readonly<Props> & Instance) => Data
        \\type PropsDefinition<T> = { [K in keyof T]: T[K] }
        \\interface Options<Data = ((this: Instance) => object), PropsDef = {}> {
        \\  data?: Data
        \\  props?: PropsDef
        \\  watch?: Record<string, WatchHandler<any>>
        \\}
        \\type WatchHandler<T> = (val: T, oldVal: T) => void;
        \\type ThisTypedOptions<Data, Props> =
        \\  Options<DataDef<Data, Props>, PropsDefinition<Props>> &
        \\  ThisType<Data & Readonly<Props> & Instance>
        \\declare function test<Data, Props>(fn: ThisTypedOptions<Data, Props>): void;
        \\declare function test(fn: Options): void;
        \\test({
        \\  props: { foo: '' },
        \\  data(): { bar: boolean } { return { bar: true } },
