test "checker: reverse mapped inference accepts nested computed accessors" {
    const s = try newSetup(
        \\type PropDesc<T> = { value?: T; get?(): T; set?(value: T): void };
        \\type PropDescMap<T> = { [K in keyof T]: PropDesc<T[K]> };
        \\declare function defineProps<T, U>(obj: T, descs: PropDescMap<U> & ThisType<T>): T & U;
        \\const described = defineProps({ x: 1 }, {
        \\  foo: { value: 42 },
        \\  bar: { get(): number { return this.x; }, set(value: number) { this.x = value; } }
        \\});
        \\type Accessors<T> = { [K in keyof T]: (() => T[K]) | Computed<T[K]> };
        \\type Computed<T> = { get?(): T; set?(value: T): void };
        \\type Options<D, M, P> = ThisType<D & M & P> & {
        \\  data?: D | (() => D);
        \\  methods?: M;
        \\  computed?: Accessors<P>;
        \\};
        \\declare const App: new <D, M, P>(options: Options<D, M, P>) => D & M & P;
        \\const app = new App({
        \\  data: () => ({ x: 1, y: 2 }),
        \\  methods: {
        \\    f(x: string) { return this.x; }
        \\  },
        \\  computed: {
        \\    test(): number { return this.x; },
        \\    hello: {
        \\      get() { return "hi"; },
        \\      set(value: string) {}
        \\    }
        \\  }
        \\});
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{
        .no_implicit_any = true,
        .strict_function_types = true,
        .strict_null_checks = true,
    });
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
    }
}

