test "checker: checkjs JSDoc type tags validate generic constraints" {
    const source =
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @filename: t.d.ts
        \\type A<T extends string> = { a: T }
        \\// @filename: test.js
        \\/** Also should error for jsdoc typedefs
        \\ * @template {string} U
        \\ * @typedef {{ b: U }} B
        \\ */
        \\/** @type {A<number>} */
        \\var a;
        \\/** @type {B<number>} */
        \\var b;
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const first_number_index = std.mem.indexOf(u8, source, "number") orelse return error.TestUnexpectedResult;
    const second_number_index = std.mem.indexOfPos(u8, source, first_number_index + "number".len, "number") orelse return error.TestUnexpectedResult;
    const first_number: u32 = @intCast(first_number_index);
    const second_number: u32 = @intCast(second_number_index);
    var count: usize = 0;
    var saw_first_pos = false;
    var saw_second_pos = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_does_not_satisfy_constraint) continue;
        count += 1;
        if (d.pos == first_number) saw_first_pos = true;
        if (d.pos == second_number) saw_second_pos = true;
    }
    try T.expect(count >= 2);
    try T.expect(saw_first_pos);
    try T.expect(saw_second_pos);
}

