test "checker: checkjs optional require alias remains constructable without strict nulls" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @filename: jsdocTypeReferenceToImport.js
        \\const D = require("./ex")?.C;
        \\/** @type {D} */
        \\var d = new D();
        \\d.start;
        \\// @filename: ex.d.ts
        \\export class C {
        \\  start: number
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != 2351);
        try T.expect(d.code != TsCodes.property_does_not_exist);
    }
}

test "checker: checkjs direct require alias resolves as exported instance type" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @strictNullChecks: true
        \\// @filename: named.js
        \\class Named { constructor() { this.named = 1; } }
        \\module.exports = Named;
        \\// @filename: anonymous.js
        \\module.exports = class { constructor() { this.anonymous = 1; } };
        \\// @filename: use.js
        \\const NamedAlias = require("./named");
        \\/** @type {NamedAlias} */
        \\var named;
        \\named.named;
        \\/** @type {NamedAlias} */
        \\const invalidNamed = undefined;
        \\const AnonymousAlias = require("./anonymous");
        \\/** @type {AnonymousAlias} */
        \\var anonymous;
        \\anonymous.anonymous;
        \\/** @type {AnonymousAlias} */
        \\const invalidAnonymous = undefined;
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.cannot_find_name));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.property_does_not_exist));
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.type_not_assignable));
}

test "checker: checkjs JSDoc bare import typedef resolves CommonJS class expression" {
    const s = try newSetup(
        \\// @target: es2015
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @filename: MW.js
        \\/** @typedef {import("./MC")} MC */
        \\class MW {
        \\  /**
        \\   * @param {MC} compiler
        \\   */
        \\  constructor(compiler) {
        \\    this.compiler = compiler;
        \\  }
        \\}
        \\module.exports = MW;
        \\// @filename: MC.js
        \\const MW = require("./MW");
        \\module.exports = class MC {
        \\  watch() {
        \\    return new MW(this);
        \\  }
        \\};
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.cannot_find_name);
        try T.expect(d.code != 2351);
    }
}

test "checker: checkjs JSDoc typedef participates in script-global duplicate checks" {
    const s = try newSetup(
        \\// @checkjs: true
        \\// @filename: mod1.js
        \\/** @typedef {number} Foo */
        \\class Bar {}
        \\// @filename: mod2.js
        \\class Foo {}
        \\const Bar = 3;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var foo_duplicates: usize = 0;
    var bar_redeclares: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.duplicate_identifier and
            std.mem.indexOf(u8, d.message, "'Foo'") != null)
        {
            foo_duplicates += 1;
        }
        if (d.code == TsCodes.cannot_redeclare_block_scoped and
            std.mem.indexOf(u8, d.message, "'Bar'") != null)
        {
            bar_redeclares += 1;
        }
    }
    try T.expectEqual(@as(usize, 2), foo_duplicates);
    try T.expectEqual(@as(usize, 2), bar_redeclares);
}

