}

test "checker: checkjs JSDoc generic constructor type substitutes inferred this members" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @filename: index.js
        \\/**
        \\ * @template {string} K
        \\ * @template V
        \\ * @param {string} ik
        \\ * @param {V} iv
        \\ */
        \\function Multimap(ik, iv) {
        \\  /** @type {{ [s: string]: V }} */
        \\  this._map = {};
        \\  this._map2 = { [ik]: iv };
        \\}
        \\/** @type {Multimap<"a" | "b", number>} */
        \\const map = new Multimap("a", 1);
        \\/** @type {number} */
        \\const value = map._map2["hi"];
        \\/**
        \\ * @class
        \\ * @template T
        \\ * @param {T} t
        \\ */
        \\function Cp(t) {
        \\    this.x = 1
        \\    this.y = t
        \\}
        \\Cp.prototype = {
        \\    m1() { return this.x },
        \\    m2() { this.z = this.x + 1; return this.y }
        \\}
        \\var cp = new Cp(1)
        \\/** @type {number} */
        \\var nx = cp.x
        \\/** @type {number} */
        \\var ny = cp.y
        \\/** @type {number} */
        \\var nm1 = cp.m1()
        \\/** @type {number} */
        \\var nm2 = cp.m2()
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
        try T.expect(d.code != TsCodes.property_does_not_exist);
    }
}

test "checker: checkjs JSDoc constructor typed this member substitutes template" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @filename: templateTagOnConstructorFunctions.js
        \\/**
        \\ * @param {T} t
        \\ * @template T
        \\ */
        \\function Zet(t) {
        \\  /** @type {T} */
        \\  this.u
        \\  this.t = t
        \\}
        \\/** @param {T} v */
        \\Zet.prototype.add = function(v) { this.u = v || this.t; }
        \\var z = new Zet(1)
        \\z.u = false
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_mismatch = false;
    var mismatch_count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        mismatch_count += 1;
        if (std.mem.indexOf(u8, d.message, "boolean") != null and
            std.mem.indexOf(u8, d.message, "number") != null)
        {
            saw_mismatch = true;
        }
    }
    try T.expect(saw_mismatch);
    try T.expectEqual(@as(usize, 1), mismatch_count);
}

test "checker: checkjs JSDoc template constraint applies only to first parameter" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @strict: false
        \\// @filename: templateConstraints.js
        \\/**
        \\ * @template {{ a: number, b: string }} T,U
        \\ * @template W
        \\ * @template X
        \\ * @param {T} t
        \\ * @param {U} u
        \\ * @param {W} w
        \\ * @param {X} x
        \\ * @return {W | X}
        \\ */
        \\function f(t, u, w, x) {
        \\  if (u.a + u.b.length) return w;
        \\  return x;
        \\}
        \\f({ a: 1 }, undefined, 1, "x");
    );
    defer destroySetup(s);
    s.checker.setCheckJsEnabled(true);
    s.checker.setAllowJsEnabled(true);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.property_does_not_exist));
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.argument_type_mismatch));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.type_not_assignable));
}

test "checker: checkjs class template parameters drive constructor inference" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @filename: templateTagOnClasses.js
        \\/**
        \\ * @template T
        \\ * @typedef {(t: T) => T} Id
        \\ */
        \\/** @template T */
        \\class Foo {
        \\  /** @typedef {(t: T) => T} Id2 */
        \\  /** @param {T} x */
        \\  constructor(x) { this.a = x; }
        \\  /**
        \\   * @param {T} x
        \\   * @param {Id<T>} y
        \\   * @param {Id2} alpha
        \\   * @return {T}
        \\   */
        \\  foo(x, y, alpha) { return alpha(y(x)); }
        \\}
        \\var f = new Foo(1);
        \\var g = new Foo(false);
        \\f.a = g.a;
    );
    defer destroySetup(s);
    s.checker.setCheckJsEnabled(true);
    s.checker.setAllowJsEnabled(true);
