    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.type_not_assignable));
}

test "checker: checkjs JSDoc @overload declares overload signatures" {
    // Phase 4 #14 ÃÂ¢ÃÂÃÂ TS 5.0 JSDoc `@overload` tags should let JS
    // declare multiple call signatures for the next function.
    const s = try newSetup(
        \\// @checkjs: true
        \\/**
        \\ * @overload
        \\ * @param {string} x
        \\ * @returns {string}
        \\ *
        \\ * @overload
        \\ * @param {number} x
        \\ * @returns {number}
        \\ *
        \\ * @param {string | number} x
        \\ * @returns {string | number}
        \\ */
        \\function identity(x) { return x; }
        \\const a = identity("hi");
        \\const b = identity(1);
        \\const s2: string = a;
        \\const n: number = b;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
        try T.expect(d.code != TsCodes.overload_return_implicitly_any);
    }
}

test "checker: checkjs JSDoc @overload without returns reports TS7012" {
    const source =
        \\// @checkjs: true
        \\// @filename: /a.js
        \\/**
        \\ * @overload
        \\ * @param {number} x
        \\ */
        \\
        \\/**
        \\ * @overload
        \\ * @param {string} x
        \\ */
        \\
        \\/**
        \\ * @param {string | number} x
        \\ * @returns {string | number}
        \\ */
        \\function id(x) {
        \\  return x;
        \\}
        \\
        \\export let a = id(123);
        \\export let b = id("hello");
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);
    var ts7012: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.overload_return_implicitly_any) {
            ts7012 += 1;
            try T.expectEqualStrings("This overload implicitly returns the type 'any' because it lacks a return type annotation.", d.message);
        }
    }
    try T.expectEqual(@as(usize, 2), ts7012);
}

