test "checker: checkjs JSDoc @constructor @overload declares constructor overloads" {
    const s = try newSetup(
        \\// @checkjs: true
        \\// @allowjs: true
        \\// @strict: true
        \\export class Foo {
        \\  #a = true ? 1 : "1";
        \\  #b;
        \\
        \\  /**
        \\   * Should not have an implicit any return error.
        \\   * @constructor
        \\   * @overload
        \\   * @param {string} a
        \\   * @param {number} b
        \\   */
        \\  /**
        \\   * @constructor
        \\   * @overload
        \\   * @param {number} a
        \\   */
        \\  /**
        \\   * @constructor
        \\   * @overload
        \\   * @param {string} a
        \\   *//**
        \\   * @constructor
        \\   * @param {number | string} a
        \\   */
        \\  constructor(a, b) {
        \\    this.#a = a;
        \\    this.#b = b;
        \\  }
        \\}
        \\new Foo();
        \\new Foo("str");
        \\new Foo(2);
        \\new Foo("str", 2);
    );
    defer destroySetup(s);
    s.checker.setImporterPath("/overloadTag2.js");
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);
    var ts2394: usize = 0;
    var ts7006: usize = 0;
    var ts2554: usize = 0;
    var saw_no_overload = false;
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.overload_return_implicitly_any);
        if (d.code == TsCodes.overload_signature_not_compatible) {
            ts2394 += 1;
        }
        if (d.code == TsCodes.parameter_implicitly_any) {
            ts7006 += 1;
            try T.expect(std.mem.indexOf(u8, d.message, "Parameter 'b'") != null);
        }
        if (d.code == TsCodes.expected_n_arguments) {
            ts2554 += 1;
            try T.expectEqualStrings("Expected 1-2 arguments, but got 0.", d.message);
        }
        if (d.code == TsCodes.no_overload_matches) saw_no_overload = true;
    }
    try T.expectEqual(@as(usize, 1), ts2394);
    try T.expectEqual(@as(usize, 1), ts7006);
    try T.expectEqual(@as(usize, 1), ts2554);
    try T.expect(!saw_no_overload);
}

test "checker: checkjs JSDoc @satisfies validates a value" {
    // Phase 4 #14 ÃÂ¢ÃÂÃÂ TS 4.9 `@satisfies {T}` on a value declaration
    // checks the value against T without widening the inferred type.
    const s = try newSetup(
