test "checker: checkjs JSDoc satisfies contextually types direct arrows" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @strict: true
        \\// @filename: /a.js
        \\/** @satisfies {(uuid: string) => void} */
        \\const typed = uuid => {};
        \\typed(123);
        \\/** @typedef {Parameters<typeof typed>} TypedArgs */
        \\/** @type TypedArgs */
        \\const invalidArgs = [123];
        \\/**
        \\ * @satisfies {(a: string, ...args: number[]) => void}
        \\ * @param {string} a
        \\ * @param {string} b
        \\ */
        \\const mismatch = (a, b) => {};
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var saw_argument_mismatch = false;
    var saw_tuple_mismatch = false;
    var saw_named_satisfies = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.parameter_implicitly_any) return error.TestUnexpectedResult;
        if (d.code == TsCodes.argument_type_mismatch) saw_argument_mismatch = true;
        if (d.code == TsCodes.type_not_assignable and std.mem.indexOf(u8, d.message, "number") != null and
            std.mem.indexOf(u8, d.message, "string") != null)
        {
            saw_tuple_mismatch = true;
        }
        if (d.code == TsCodes.satisfies_constraint and
            std.mem.indexOf(u8, d.message, "(a: string, ...args: number[]) => void") != null)
        {
            saw_named_satisfies = true;
        }
    }
    try T.expect(saw_argument_mismatch);
    try T.expect(saw_tuple_mismatch);
    try T.expect(saw_named_satisfies);
}

test "checker: checkjs JSDoc @satisfies contextually types object property arrows" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @strict: true
        \\/** @satisfies {{ f: (x: string) => string }} */
        \\const t1 = { f: value => value.toLowerCase() };
        \\/** @satisfies {{ f: (x: string) => string }} */
        \\const t2 = { g: "oops" };
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.parameter_implicitly_any));
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.object_literal_excess_property));

    const t1_decl = hir_mod.blockStmts(&s.hir, s.root)[0];
    const object_node = hir_mod.varDeclOf(&s.hir, t1_decl).init;
    const property_node = hir_mod.objectLiteralProps(&s.hir, object_node)[0];
    const arrow_node = hir_mod.objectPropertyOf(&s.hir, property_node).value;
    const param_node = hir_mod.fnParams(&s.hir, arrow_node)[0];
    try T.expectEqual(types.Primitive.string_t, s.hir.typeOf(param_node));
}

test "checker: inline JSDoc @satisfies shadows outer @type member context" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @strict: true
        \\/** @type {{ f(s: string): void } & Record<string, unknown> }} */
        \\const value = /** @satisfies {{ g(s: string): void } & Record<string, unknown>} */ ({
        \\    f(s) {},
        \\    g(s) {},
        \\});
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);

    var implicit_any_count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.parameter_implicitly_any) continue;
        implicit_any_count += 1;
        try T.expect(std.mem.indexOf(u8, d.message, "Parameter 's'") != null);
    }
    try T.expectEqual(@as(usize, 1), implicit_any_count);

    const decl = hir_mod.blockStmts(&s.hir, s.root)[0];
    const object_node = hir_mod.varDeclOf(&s.hir, decl).init;
    const props = hir_mod.objectLiteralProps(&s.hir, object_node);
    const f_param = hir_mod.fnParams(&s.hir, hir_mod.objectPropertyOf(&s.hir, props[0]).value)[0];
    const g_param = hir_mod.fnParams(&s.hir, hir_mod.objectPropertyOf(&s.hir, props[1]).value)[0];
    try T.expectEqual(types.Primitive.any, s.hir.typeOf(f_param));
    try T.expectEqual(types.Primitive.string_t, s.hir.typeOf(g_param));
}

test "checker: checkjs bare JSDoc @satisfies type reports braces" {
    const s = try newSetup(
        \\// @checkjs: true
        \\/** @typedef {Object} T1 */
        \\/** @satisfies T1 */
        \\const t1 = { a: 1 };
        \\const t2 = /** @satisfies T1 */ ({ a: 1 });
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_open = false;
    var saw_close = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.expected_open_brace and std.mem.eql(u8, d.message, "'{' expected.")) saw_open = true;
        if (d.code == TsCodes.expected_close_brace and std.mem.eql(u8, d.message, "'}' expected.")) saw_close = true;
    }
    try T.expect(saw_open);
    try T.expect(saw_close);
}

