test "checker: checkjs JSDoc type tags preserve object and callable arity" {
    const s = try newSetup(
        \\// @allowJS: true
        \\// @checkJs: true
        \\// @strict: true
        \\// @filename: a.js
        \\/** @type {Object} */
        \\var Obj;
        \\/** @type {object} */
        \\var obj;
        \\/** @type {function(string): void} */
        \\const f = (value) => {};
        \\/** @type {(s: string) => void} */
        \\function g(s) {}
        \\/** @type {{(s: string): void}} */
        \\function h(s) {}
        \\/** @type {function (number)} */
        \\const spaced = value => value + 1;
        \\/** @type {?} */
        \\let wildcard = 1;
        \\wildcard = "ok";
        \\/** @type {Function} */
        \\const broad = input => input;
        \\/** @type {function} */
        \\const broadLower = input => input;
        \\/** @type {object} */
        \\var props = {};
        \\/** @type {Object} */
        \\var props = {};
        \\f();
        \\g();
        \\h();
        \\spaced("bad");
        \\// @filename: b.ts
        \\var Obj: any;
        \\var obj: any;
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);

    var saw_object_mismatch = false;
    var saw_lower_object_mismatch = false;
    var saw_spaced_missing_return = false;
    var saw_spaced_argument_mismatch = false;
    var broad_implicit_any: usize = 0;
    var saw_object_wrapper_mismatch = false;
    var arity_errors: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.parameter_implicitly_any and std.mem.indexOf(u8, d.message, "'value'") != null) {
            return error.TestUnexpectedResult;
        }
        if (d.code == TsCodes.subsequent_var_type_mismatch and
            std.mem.indexOf(u8, d.message, "Variable 'Obj' must be of type 'Object', but here has type 'any'.") != null)
        {
            saw_object_mismatch = true;
        }
        if (d.code == TsCodes.subsequent_var_type_mismatch and
            std.mem.indexOf(u8, d.message, "Variable 'obj' must be of type 'object', but here has type 'any'.") != null)
        {
            saw_lower_object_mismatch = true;
        }
        if (d.code == TsCodes.expected_n_arguments and
            std.mem.eql(u8, d.message, "Expected 1 arguments, but got 0."))
        {
            arity_errors += 1;
        }
        if (d.code == TsCodes.function_type_return_implicitly_any) saw_spaced_missing_return = true;
        if (d.code == TsCodes.argument_type_mismatch and
            std.mem.eql(u8, d.message, "Argument of type 'string' is not assignable to parameter of type 'number'."))
        {
            saw_spaced_argument_mismatch = true;
        }
        if (d.code == TsCodes.parameter_implicitly_any and std.mem.indexOf(u8, d.message, "'input'") != null) {
            broad_implicit_any += 1;
        }
        if (d.code == TsCodes.subsequent_var_type_mismatch and
            std.mem.indexOf(u8, d.message, "Variable 'props' must be of type 'object', but here has type 'Object'.") != null)
        {
            saw_object_wrapper_mismatch = true;
        }
        if (d.code == TsCodes.type_not_assignable and
            std.mem.eql(u8, d.message, "Type 'string' is not assignable to type 'number'."))
        {
            return error.TestUnexpectedResult;
        }
    }
    try T.expect(saw_object_mismatch);
    try T.expect(saw_lower_object_mismatch);
    try T.expectEqual(@as(usize, 3), arity_errors);
    try T.expect(saw_spaced_missing_return);
    try T.expect(saw_spaced_argument_mismatch);
    try T.expectEqual(@as(usize, 2), broad_implicit_any);
    try T.expect(saw_object_wrapper_mismatch);
}

test "checker: checkjs JSDoc callable typedefs preserve return contracts" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @filename: a.js
        \\/** @typedef {(x: 'hi' | 'bye') => 0 | 1 | 2} Single */
        \\/** @type {Single} */
        \\function single(x) { return 0; }
        \\/** @type {0 | 1 | 2} */
        \\var accepted = single('hi');
        \\/** @typedef {{(s: string): 0 | 1; (b: boolean): 2 | 3}} Overloaded */
        \\/** @type {Overloaded} */
        \\function overloaded(value) {
        \\    return typeof value === 'string' ? 1 : 2;
        \\}
        \\/** @type {2 | 3} */
        \\var rejected = overloaded(false);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var mismatch_count: usize = 0;
    var overload_tag_count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.jsdoc_function_type_mismatch) overload_tag_count += 1;
        if (d.code == TsCodes.type_not_assignable) {
            mismatch_count += 1;
            try T.expectEqualStrings("Type '1 | 2' is not assignable to type '2 | 3'.", d.message);
        }
        try T.expect(d.code != TsCodes.argument_type_mismatch);
    }
    try T.expectEqual(@as(usize, 1), overload_tag_count);
    try T.expectEqual(@as(usize, 1), mismatch_count);
}

test "checker: checkjs JSDoc function type tags enforce declaration arity" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @filename: a.js
        \\/** @type {number} */
        \\function scalar() { return 1; }
        \\/** @type {(a: number) => number} */
        \\function tooMany(a, b) { return a + b; }
        \\/** @type {() => void} */
        \\function namedExtra(more) {}
        \\/** @type {{ prop: string }} */
        \\var objectMismatch = function (prop) {};
        \\/** @type {() => void} */
        \\const functionMismatch = function (more) {};
        \\/** @type {() => void} */
        \\const arrowMismatch = (more) => {};
        \\({
        \\  /** @type {() => void} */
        \\  methodMismatch(more) {},
        \\});
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var declaration_mismatches: usize = 0;
    var assignment_mismatches: usize = 0;
