        if (d.code == TsCodes.type_not_assignable) {
            assignment_mismatches += 1;
            try T.expect(std.mem.indexOf(u8, d.message, "Type is not assignable to declared type.") == null);
            try T.expect(std.mem.indexOf(u8, d.message, "?: any") == null);
        }
    }
    try T.expectEqual(@as(usize, 3), declaration_mismatches);
    try T.expectEqual(@as(usize, 4), assignment_mismatches);
}

test "checker: checkjs JSDoc object property types contextualize values" {
    const s = try newSetup(
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @filename: a.js
        \\var lol;
        \\const obj = {
        \\  /** @type {string|undefined} */
        \\  bar: 42,
        \\  /** @type {function(number): number} */
        \\  method1(n1) { return "42"; },
        \\  /** @type {function(number): number} */
        \\  method2: (n1) => "lol",
        \\  /** @type {function(number): number} */
        \\  arrowFunc: (num="0") => num + 42,
        \\  /** @type {string} */
        \\  lol,
        \\};
        \\lol = "string";
        \\/** @type {string} */
        \\var s0 = obj.method1(0);
        \\/** @type {string} */
        \\var s1 = obj.method2("0");
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true, .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);

    var assignment_mismatches: usize = 0;
    var argument_mismatches: usize = 0;
    var number_to_string: usize = 0;
    var string_to_number: usize = 0;
    var undefined_to_string: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.variable_implicitly_any_declaration);
        if (d.code == TsCodes.type_not_assignable) {
            assignment_mismatches += 1;
            if (std.mem.eql(u8, d.message, "Type 'number' is not assignable to type 'string'.")) number_to_string += 1;
            if (std.mem.eql(u8, d.message, "Type 'string' is not assignable to type 'number'.")) string_to_number += 1;
            if (std.mem.eql(u8, d.message, "Type 'undefined' is not assignable to type 'string'.")) undefined_to_string += 1;
            try T.expect(std.mem.indexOf(u8, d.message, "=>") == null);
        }
        if (d.code == TsCodes.argument_type_mismatch) argument_mismatches += 1;
    }
    try T.expectEqual(@as(usize, 7), assignment_mismatches);
    try T.expectEqual(@as(usize, 1), argument_mismatches);
    try T.expectEqual(@as(usize, 3), number_to_string);
    try T.expectEqual(@as(usize, 3), string_to_number);
    try T.expectEqual(@as(usize, 1), undefined_to_string);
}

