        \\/** @implements {A} */
        \\class Missing {}
        \\var Ns = {};
        \\var C5;
        \\/** @implements {A} */
        \\Ns.C5 = C5 || class { method() { return 1; } };
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
