test "checker: unused ECMAScript #field reports TS6133; one read via `#x in v` does not" {
    // `#field`s are subject to noUnusedLocals TS6133. A `#brand in v`
    // ergonomic brand check counts as reading `#brand`. Mirrors
    // privateNameInInExpressionUnused.
    const s = try newSetup(
        \\// @noUnusedLocals: true
        \\class Foo {
        \\  #unused: undefined;
        \\  #brand: undefined;
        \\  isFoo(v: any): v is Foo { return #brand in v; }
        \\}
    );
    defer destroySetup(s);
    s.checker.strict_flags.no_unused_locals = true;
    try s.checker.checkSourceFile(s.root);
    var unused_count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.declared_but_not_read and std.mem.indexOf(u8, d.message, "#unused") != null) unused_count += 1;
        // `#brand` is read via the `in` check — never flagged.
        if (d.code == TsCodes.declared_but_not_read) try T.expect(std.mem.indexOf(u8, d.message, "#brand") == null);
    }
    try T.expectEqual(@as(usize, 1), unused_count);
}

