    // Just document current behavior ÃÂ¢ÃÂÃÂ don't assert pass/fail.
}

test "checker: declare module augments existing module from another virtual file" {
    // Phase 4 #15 ÃÂ¢ÃÂÃÂ `declare module "X"` in a .d.ts file augments
    // the named module's exported types. A consumer file then sees
    // the merged shape.
    const s = try newSetup(
        \\// @filename: lib.d.ts
        \\declare module "lib" {
        \\  export interface Config { name: string }
        \\}
        \\// @filename: lib-aug.d.ts
        \\declare module "lib" {
        \\  export interface Config { added: number }
        \\}
        \\// @filename: index.ts
        \\import { Config } from "lib";
        \\const c: Config = { name: "x", added: 1 };
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
        try T.expect(d.code != TsCodes.property_does_not_exist);
    }
}

test "checker: nested ambient module augmentation merges interface members" {
    // moduleAugmentationInAmbientModule3 ÃÂ¢ÃÂÃÂ a `declare module "Map"`
    // body nests `module "Observable" { interface Observable { ... } }`,
    // which augments the `Observable` class exported from the separate
    // `declare module "Observable"`. The merged members (`foo`, `foo2`)
    // must be visible on a value typed `Observable`, so member access
    // must NOT report TS2339. The legitimate TS2454 ("used before
    // assigned") on the uninitialized `x` still belongs in the baseline.
    const b = try newBoundSetup(
        \\// @filename: O.d.ts
        \\declare module "Observable" {
        \\    class Observable {}
        \\}
        \\declare module "M" {
        \\    class Cls { x: number }
        \\}
        \\declare module "Map" {
        \\    import { Cls } from "M";
        \\    module "Observable" {
        \\        interface Observable {
        \\            foo(): Cls;
        \\        }
        \\    }
        \\}
        \\declare module "Map" {
        \\    class Cls2 { x2: number }
        \\    module "Observable" {
        \\        interface Observable {
        \\            foo2(): Cls2;
        \\        }
        \\    }
        \\}
        \\// @filename: main.ts
        \\import {Observable} from "Observable";
        \\import "Map";
        \\let x: Observable;
        \\x.foo().x;
        \\x.foo2().x2;
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    for (b.base.checker.diagnostics.items) |d| {
        // The augmented members `foo`/`foo2` are real ÃÂ¢ÃÂÃÂ no TS2339.
        try T.expect(d.code != TsCodes.property_does_not_exist);
    }
}

test "checker: nested ambient module augmentation still reports genuinely missing member" {
    // Negative guard for the nested-augmentation merge: accessing a
    // member that was NOT added by any augmentation must still report
    // TS2339, so the merge does not silence genuine missing-member access.
    const b = try newBoundSetup(
        \\// @filename: O.d.ts
        \\declare module "Observable" {
        \\    class Observable {}
        \\}
        \\declare module "Map" {
        \\    module "Observable" {
        \\        interface Observable {
        \\            foo(): number;
        \\        }
        \\    }
        \\}
        \\// @filename: main.ts
        \\import {Observable} from "Observable";
        \\import "Map";
        \\declare let x: Observable;
        \\x.foo();
        \\x.missingMember();
    );
    defer destroyBoundSetup(b);
    var saw_missing = false;
    try b.base.checker.checkSourceFile(b.base.root);
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.property_does_not_exist) saw_missing = true;
    }
    try T.expect(saw_missing);
}

test "checker: TS2671 reports augmentation of export equals non-module entity" {
