test "checker: unrelated type parameters nest arbitrary instantiation under TS2322" {
    // Upstream `assignmentCompatibility/typeParameterAssignability.ts`
    // expects both `t = u` and `u = t` over `function foo<T, U>` to fail.
    // tsc's relation reporter nests the TS5082 wording under a primary
    // TS2322 when the source is another type parameter.
    // The relation engine stays permissive on
    // type-parameter targets to keep generic inference working; the
    // assignment-expression checker emits the diagnostic directly via
    // `unrelatedTypeParameterAssignment`.
    const s = try newSetup(
        \\function foo<T, U>(t: T, u: U) {
        \\  t = u;
        \\  u = t;
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
    var mismatch_count: u32 = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        mismatch_count += 1;
        try T.expectEqual(@as(usize, 1), d.chain.len);
        try T.expect(std.mem.indexOf(u8, d.chain[0].message, "could be instantiated with an arbitrary type") != null);
        try T.expectEqual(@as(usize, 1), d.related.len);
        try T.expectEqual(TsCodes.type_parameter_might_need_extends_constraint, d.related[0].code);
    }
    try T.expectEqual(@as(u32, 2), mismatch_count);
}

