test "checker: node18 JSON imports require type json attributes" {
    const s = try newSetup(
        \\// @module: node18
        \\// @filename: ./data.json
        \\// { "key": "value" }
        \\// @filename: ./main.mts
        \\import data from "./data.json";
        \\import { key } from "./data.json";
        \\import ok from "./data.json" with { type: "json" };
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .resolve_json_module = true });
    try s.checker.checkSourceFile(s.root);

    var saw_1543: usize = 0;
    var saw_1544: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.json_import_requires_type_attribute) {
            saw_1543 += 1;
            try T.expectEqualStrings("Importing a JSON file into an ECMAScript module requires a 'type: \"json\"' import attribute when 'module' is set to 'Node18'.", d.message);
        }
        if (d.code == TsCodes.json_named_imports_not_allowed) {
            saw_1544 += 1;
            try T.expectEqualStrings("Named imports from a JSON file into an ECMAScript module are not allowed when 'module' is set to 'Node18'.", d.message);
        }
    }
    try T.expectEqual(@as(usize, 2), saw_1543);
    try T.expectEqual(@as(usize, 1), saw_1544);
}

test "checker: TS2857 import attributes on type-only imports and re-exports" {
    const src =
        \\// @module: esnext
        \\// @filename: 0.ts
        \\export interface I {}
        \\// @filename: 1.ts
        \\import type { I } from "./0" with { type: "json" };
        \\export type { I } from "./0" with { type: "json" };
    ;
    const s = try newSetup(src);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var count: usize = 0;
    var import_pos: ?u32 = null;
    var export_pos: ?u32 = null;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.import_attributes_type_only) continue;
        count += 1;
        try T.expectEqualStrings("Import attributes cannot be used with type-only imports or exports.", d.message);
        const pos = d.pos orelse return error.MissingDiagnostic;
        if (import_pos == null) {
            import_pos = pos;
        } else {
            export_pos = pos;
        }
    }
    try T.expectEqual(@as(usize, 2), count);
    try T.expectEqual(@as(u32, @intCast(std.mem.indexOf(u8, src, "with { type").?)), import_pos.?);
    try T.expectEqual(@as(u32, @intCast(std.mem.lastIndexOf(u8, src, "with { type").?)), export_pos.?);
}

test "checker: default ImportAttributes requires string-valued properties" {
    const s = try newSetup(
        \\// @module: node18
        \\import * as a from "./m" with { field: 0 };
        \\import * as b from "./m" with { field: `ok` };
        \\import * as c from "./m" with { field: /a/g };
        \\import * as d from "./m" with { field: ["a"] };
        \\import * as e from "./m" with { field: { a: 0 } };
        \\import * as f from "./m" with { field: 0..toString() };
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    const expected = [_][]const u8{
        "Type '{ field: 0; }' is not assignable to type 'ImportAttributes'.",
        "Type '{ field: RegExp; }' is not assignable to type 'ImportAttributes'.",
        "Type '{ field: string[]; }' is not assignable to type 'ImportAttributes'.",
        "Type '{ field: { a: number; }; }' is not assignable to type 'ImportAttributes'.",
    };
    var found: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        try T.expectEqualStrings(expected[found], d.message);
        found += 1;
    }
    try T.expectEqual(expected.len, found);
}

