    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.declaration_file_import_requires_import_type) {
            found = true;
            try T.expectEqualStrings("A declaration file cannot be imported without 'import type'. Did you mean to import an implementation file './z.ts' instead?", d.message);
        }
        if (d.code == TsCodes.cannot_find_module) saw_cannot_find = true;
    }
    try T.expect(found);
    try T.expect(!saw_cannot_find);
}

