test "checker: TS1309 for top-level await in a CommonJS-format module under module:nodenext" {
    // Mirrors upstream `checkGrammarAwaitOrAwaitUsing`
    // (grammarchecks.go ~L1715): a module file whose implied format is
    // CommonJS (.cts) cannot use top-level await under the Node-format
    // module settings, even at a high target.
    const s = try newSetup(
        \\// @module: nodenext
        \\// @target: esnext
        \\// @filename: a.cts
        \\export {};
        \\declare const x: Promise<number>;
        \\await x;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var count: u32 = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.top_level_await_commonjs) {
            count += 1;
            try T.expectEqualStrings("The current file is a CommonJS module and cannot use 'await' at the top level.", d.message);
            try T.expectEqual(@as(usize, 1), d.related.len);
            try T.expectEqual(@as(u32, TsCodes.convert_to_esm_create_package), d.related[0].code);
        }
        // The target/module fallbacks must NOT also fire.
        try T.expect(d.code != TsCodes.top_level_await_target_module);
        try T.expect(d.code != TsCodes.top_level_await_non_module);
    }
    try T.expectEqual(@as(u32, 1), count);
}

