test "checker: TS2416 anchors at the child property and renders both class names" {
    // Mirrors `apparentTypeSupertype.ts(10,5)` ÃÂ¢ÃÂÃÂ the diagnostic must
    // underline the *child's* property name (so the column and span
    // matches tsc) and the prose must name both `Derived<U>` and
    // `Base`. Pre-fix we anchored at the extends clause and dropped
    // the type names ("Property 'x' in type is not assignable ÃÂ¢ÃÂÃÂ¦").
    const src =
        \\class Base { x!: string; }
        \\class Derived<U extends String> extends Base { x!: U; }
    ;
    const s = try newSetup(src);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const derived_x: u32 = @intCast(std.mem.lastIndexOf(u8, src, "x!: U").?);
    var saw_on_member_with_names = false;
    for (s.checker.diagnostics.items) |diag| {
        if (diag.code != TsCodes.property_not_assignable_to_base) continue;
        const node_kind = s.checker.hir.kindOf(diag.node);
        if (node_kind == .identifier and
            s.checker.diagnosticStart(diag) == derived_x and
            std.mem.indexOf(u8, diag.message, "in type 'Derived<U>'") != null and
            std.mem.indexOf(u8, diag.message, "base type 'Base'") != null)
        {
            saw_on_member_with_names = true;
        }
    }
    try T.expect(saw_on_member_with_names);
}

test "checker: unrelated constrained type parameters fail heritage member relations" {
    const s = try newSetup(
        \\class Foo { foo!: number; }
        \\class Box<T> { value!: T; }
        \\class Base<T> { foo!: T; }
        \\class Derived<T extends Foo, U extends Foo, V> extends Base<T> {
        \\  [x: string]: T;
        \\  foo!: U;
        \\}
        \\namespace M {
        \\  class RecursiveBase<T> { foo!: Box<T>; }
        \\  class RecursiveBad<T extends Box<U>, U extends Box<T>> extends RecursiveBase<T> {
        \\    foo!: T;
        \\  }
        \\  class RecursiveGood<T extends Box<U>, U extends Box<T>> extends RecursiveBase<T> {
        \\    foo!: U;
        \\  }
        \\  class RecursiveGoodReverse<T extends Box<U>, U extends Box<T>> extends RecursiveBase<U> {
        \\    foo!: T;
        \\  }
        \\  class RecursiveSelf<V extends Box<V>> extends RecursiveBase<V> {
        \\    foo!: V;
        \\  }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.property_not_assignable_to_index_type));
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.property_not_assignable_to_base));
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.property_not_assignable_to_index_type,
        "Property 'foo' of type 'U' is not assignable to 'string' index type 'T'.",
    ));
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.property_not_assignable_to_base,
        "Property 'foo' in type 'Derived<T, U, V>' is not assignable to the same property in base type 'Base<T>'.",
    ));
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.property_not_assignable_to_base,
        "Property 'foo' in type 'RecursiveBad<T, U>' is not assignable to the same property in base type 'RecursiveBase<T>'.",
    ));
}

