    try s.checker.checkSourceFile(s.root);
    var has_2390 = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.constructor_implementation_missing) has_2390 = true;
    }
    try T.expect(has_2390);
}

