test "checker: external resolver declaration result accepts unless exports null blocked" {
    // A `.d.ts` resolver outcome is valid for package `types`
    // fallbacks, including `.mts` importers. Only an explicit active
    // `exports` null condition should veto it back to TS2307.
    const s = try newSetup(
        \\import * as dep from "dep";
        \\dep;
    );
    defer destroySetup(s);
    var stub = StubExternalResolver{
        .canned_path = "/node_modules/dep/dist/index.d.ts",
        .canned_is_declaration = true,
    };
    s.checker.setExternalResolver(.{ .ptr = &stub, .vtable = &StubExternalResolver.vtable });
    s.checker.setImporterPath("/index.mts");
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.cannot_find_module);
    }

    const blocked = try newSetup(
        \\import * as dep from "dep";
        \\dep;
    );
    defer destroySetup(blocked);
    var blocked_stub = StubExternalResolver{
        .canned_path = "/node_modules/dep/dist/index.d.ts",
        .canned_is_declaration = true,
        .canned_blocked_by_exports_null = true,
    };
    blocked.checker.setExternalResolver(.{ .ptr = &blocked_stub, .vtable = &StubExternalResolver.vtable });
    blocked.checker.setImporterPath("/index.mts");
    try blocked.checker.checkSourceFile(blocked.root);
    var ts2307 = false;
    for (blocked.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.cannot_find_module) ts2307 = true;
    }
    try T.expect(ts2307);
}

