// Regression for `mappedTypeAsClauseRecursiveNoCrash1.ts`: a recursive
// mapped type whose `as` clause re-instantiates the alias with an
// indexed-access type argument (`FlattenType<Source[Key], Target>`)
// must NOT emit TS2344. `Source[Key]` is an indexed access over a free
// type parameter; upstream defers the `Source extends object`
// constraint check until a concrete instantiation, and our recursive
// instantiation must do the same rather than testing a peeled member
// type (e.g. `number`) against the constraint. tsc emits zero
// diagnostics for this fixture.
test "checker: TS2344 not emitted for recursive mapped-type as-clause instantiation" {
    const s = try newSetup(
        \\export type FlattenType<Source extends object, Target> = {
        \\  [Key in keyof Source as Key extends string
        \\    ? Source[Key] extends object
        \\      ? `${Key}.${keyof FlattenType<Source[Key], Target> & string}`
        \\      : Key
        \\    : never]-?: Target;
        \\};
        \\type User = { id: number; name: string; };
        \\type FieldSelect = { table: string; };
        \\type FlattenedUser = FlattenType<User, FieldSelect>;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_does_not_satisfy_constraint);
    }
}

// Negative companion: a *concrete* indexed-access type argument whose
// object is an ordinary type (not a bound type parameter) must still
// report TS2344 when it violates the constraint. Here `User["id"]`
// resolves to `number`, which does not satisfy `extends object`. The
// deferral guard added for the recursive mapped-type case keys off a
// *narrow-bound* object name, so this concrete access is unaffected.
test "checker: TS2344 still fires for concrete indexed-access arg violating constraint" {
    const s = try newSetup(
        \\interface Proxy<T extends object> { value: T; }
        \\type User = { id: number; name: string; };
        \\var bad: Proxy<User["id"]>;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_does_not_satisfy_constraint) continue;
        try T.expect(std.mem.indexOf(u8, d.message, "'number'") != null);
        try T.expect(std.mem.indexOf(u8, d.message, "'object'") != null);
        found = true;
    }
    try T.expect(found);
}

test "checker: TS2344 validates function and constructor type-argument constraints" {
    const s = try newSetup(
        \\type MyReturn<T extends (...args: any[]) => any> = T extends (...args: any[]) => infer R ? R : never;
        \\type MyInstance<T extends abstract new (...args: any[]) => any> = T extends abstract new (...args: any[]) => infer R ? R : never;
        \\type R1 = MyReturn<string>;
        \\type R2 = MyReturn<Function>;
        \\type I1 = MyInstance<string>;
        \\type I2 = MyInstance<Function>;
        \\type BR1 = ReturnType<string>;
        \\type BR2 = ReturnType<Function>;
        \\type BI1 = InstanceType<string>;
        \\type BI2 = InstanceType<Function>;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var constraint_errors: usize = 0;
    var function_no_match: usize = 0;
    var abstract_construct_header = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_does_not_satisfy_constraint) continue;
        constraint_errors += 1;
        if (std.mem.indexOf(u8, d.message, "abstract new") != null) abstract_construct_header = true;
        if (d.chain.len > 0 and d.chain[0].code == TsCodes.type_provides_no_match_for_signature and
            std.mem.indexOf(u8, d.chain[0].message, "Type 'Function' provides no match") != null)
        {
            function_no_match += 1;
        }
    }
    try T.expectEqual(@as(usize, 8), constraint_errors);
    try T.expectEqual(@as(usize, 4), function_no_match);
    try T.expect(abstract_construct_header);
}

test "checker: TS2344 function constraint carries signature arity chain" {
    const s = try newSetup(
        \\type ArgumentType<T extends (x: any) => any> = T extends (a: infer A) => any ? A : any;
        \\type T24 = ArgumentType<(x: string, y: string) => number>;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var found_header = false;
    var found_arity = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_does_not_satisfy_constraint) continue;
        found_header = true;
        try T.expect(std.mem.indexOf(u8, d.message, "(x: string, y: string) => number") != null);
        try T.expect(std.mem.indexOf(u8, d.message, "(x: any) => any") != null);
        if (d.chain.len > 0 and d.chain[0].code == TsCodes.target_signature_too_few_arguments) {
            try T.expectEqualStrings(
                "Target signature provides too few arguments. Expected 2 or more, but got 1.",
                d.chain[0].message,
            );
            found_arity = true;
        }
    }
    try T.expect(found_header);
    try T.expect(found_arity);
}

// ÃÂÃÂ§6.A wave-2 ÃÂ¢ÃÂÃÂ TS2367 / TS2678 should prefer literal-text rendering
// over the alias name when comparing literal types. Pins the
// `numericLiteralTypes3` family expectation that an alias `type A = 1`
// surfaces as `'1'` in the no-overlap message.
test "checker: TS2367 renders literal text for single-literal type alias" {
    const s = try newSetup(
        \\type A = 1;
        \\function f(a: A) {
        \\  a === 0;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_literal_form = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.no_overlap_comparison) continue;
        if (std.mem.indexOf(u8, d.message, "'1'") != null and
            std.mem.indexOf(u8, d.message, "'0'") != null)
        {
            saw_literal_form = true;
        }
    }
    try T.expect(saw_literal_form);
}

