test "checker: TS2367 renders enum member names (Enum.Member) not underlying values" {
    // tsc's typeToString renders a nominal enum-literal type as
    // `Choice.Yes`, not the underlying `"yes"`. Mirrors
    // stringEnumLiteralTypes3 / enumLiteralTypes3.
    const s = try newSetup(
        \\const enum Choice { Unknown = "", Yes = "yes", No = "no" }
        \\type Yes = Choice.Yes;
        \\function f(a: Yes) {
        \\  a === Choice.Unknown;
        \\  a === Choice.No;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_unknown = false;
    var saw_no = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.no_overlap_comparison) continue;
        // The message must name the enum members, never the raw string values.
        try T.expect(std.mem.indexOf(u8, d.message, "'\"yes\"'") == null);
        if (std.mem.indexOf(u8, d.message, "'Choice.Yes'") != null and
            std.mem.indexOf(u8, d.message, "'Choice.Unknown'") != null) saw_unknown = true;
        if (std.mem.indexOf(u8, d.message, "'Choice.Yes'") != null and
            std.mem.indexOf(u8, d.message, "'Choice.No'") != null) saw_no = true;
    }
    try T.expect(saw_unknown);
    try T.expect(saw_no);
}

test "checker: TS2367 renders union type-alias by its name, not structurally" {
    // tsc's typeToString prefers the alias name for a union operand:
    // `type B = 2 | 3` renders `B` (not `2 | 3`); single-literal aliases
    // (`type A = 1`) still inline to `1`. Mirrors numericLiteralTypes3.
    const s = try newSetup(
        \\type B = 2 | 3;
        \\type A = 1;
        \\function f(b: B, a: A) {
        \\  b === 0;
        \\  a === 0;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_b_alias = false;
    var saw_a_inline = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.no_overlap_comparison) continue;
        // Union alias `B` renders by name; single-literal alias `A` inlines to `1`.
        if (std.mem.indexOf(u8, d.message, "'B'") != null and
            std.mem.indexOf(u8, d.message, "'0'") != null) saw_b_alias = true;
        if (std.mem.indexOf(u8, d.message, "'1'") != null and
            std.mem.indexOf(u8, d.message, "'0'") != null) saw_a_inline = true;
    }
    try T.expect(saw_b_alias);
    try T.expect(saw_a_inline);
}

test "checker: TS2322 renders single-literal aliases as literal text" {
    const b = try newBoundSetup(
