test "checker: TS2322 expands template and string-mapping aliases" {
    const b = try newBoundSetup(
        \\type ATemplate = `aA${string}`;
        \\type BTemplate = Uppercase<ATemplate>;
        \\function f(a: ATemplate, b: BTemplate) {
        \\  a = b;
        \\  b = a;
        \\}
        \\function g(x1: Uppercase<string>, x2: Uppercase<Uppercase<string>>, x3: Uppercase<Lowercase<string>>) {
        \\  x3 = x2;
        \\  x2 = null as Lowercase<Uppercase<string>>;
        \\}
        \\function h(cap: Capitalize<string>, mapped: Capitalize<`a${string}`>) {
        \\  mapped = cap;
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type '`AA${Uppercase<string>}`' is not assignable to type '`aA${string}`'."));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type '`aA${string}`' is not assignable to type '`AA${Uppercase<string>}`'."));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type 'Uppercase<string>' is not assignable to type 'Uppercase<Lowercase<string>>'."));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type 'Lowercase<Uppercase<string>>' is not assignable to type 'Uppercase<string>'."));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type 'Capitalize<string>' is not assignable to type '`A${string}`'."));
}

