test "checker: TS2411 fires for inline object-type literal index constraints" {
    // tsc constrains named properties of an inline object type by its index
    // signature, just like class/interface bodies. Mirrors
    // stringIndexerConstrainsPropertyDeclarations (the `var a: { … }` case).
    const s = try newSetup(
        \\var a: {
        \\  [x: string]: string;
        \\  a: string;
        \\  b: number;
        \\  c: () => string;
        \\};
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var b_err = false;
    var c_err = false;
    var a_ok = true;
    var count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.property_not_assignable_to_index_type) continue;
        count += 1;
        if (std.mem.indexOf(u8, d.message, "Property 'b' of type 'number' is not assignable to 'string' index type 'string'.") != null) b_err = true;
        if (std.mem.indexOf(u8, d.message, "Property 'c'") != null) c_err = true;
        if (std.mem.indexOf(u8, d.message, "Property 'a'") != null) a_ok = false;
    }
    try T.expect(b_err);
    try T.expect(c_err);
    try T.expect(a_ok); // `a: string` is assignable → no TS2411
    // Exactly the two offenders (b, c), reported once each (no double-emit).
    try T.expectEqual(@as(usize, 2), count);
}

// ÃÂÃÂ§6.A wave-2 ÃÂ¢ÃÂÃÂ TS2698 must fire when spreading an intersection
// that includes a hard nullish member (`null`, `undefined`,
// `void`). Such intersections collapse to `never` in upstream's
// relation engine and aren't valid spread sources. Pins
// `spreadObjectOrFalsy.ts` lines 5/13 expectation.
test "checker: TS2698 fires when spreading T & undefined intersection" {
    const s = try newSetup(
        \\function f<T>(a: T & undefined) {
        \\  return { ...a };
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.spread_types_object_only) found = true;
    }
    try T.expect(found);
}

// ÃÂÃÂ§6 JSDoc-parity ÃÂ¢ÃÂÃÂ `/** @type {T} */ Ctor.prototype = expr` in a
// `.js`/`@ts-check` source pins the prototype slot's declared type
