    try T.expect(saw_new);
}

// Negative case ÃÂ¢ÃÂÃÂ without the leading JSDoc `@type` tag, the
// override must not fire and the assignment should remain valid.
test "checker: array-destructuring rest over a fixed tuple keeps the tuple slice (no spurious TS2322)" {
    // `[...rest] = tuple` / `[x, ...rest] = tuple` capture the REMAINING
    // tuple slice (preserving element types), not a widened `T[]`, so the
    // rest stays assignable to a tuple-typed target. Mirrors tsc; before the
    // tupleSliceType fix we widened to `number[]` and over-emitted TS2322.
    const s = try newSetup(
        \\var v: [number, number, number] = [1, 2, 3];
        \\var a3: [number, number, number];
        \\var a2: [number, number];
        \\[...a3] = v;
        \\[x, ...a2] = v;
        \\var x: number;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
    }
}

test "checker: array-destructuring rest over a plain array still widens to T[]" {
    // When the source is a real array (not a fixed tuple), the rest element
    // is `T[]` — assigning it to a fixed-tuple target IS an error (TS2322),
    // confirming the slice path doesn't over-trigger on arrays.
    const s = try newSetup(
        \\var v: number[] = [1, 2, 3];
        \\var a: [number, number];
        \\[...a] = v;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_assignable) found = true;
    }
    try T.expect(found);
}

