        \\  [_sym]: "ok",
        \\  [_str]: "ok",
        \\};
        \\const inst = new F();
        \\const _y = inst[_str];
        \\const _z = inst[_sym];
        \\module.exports.F = F;
        \\module.exports.S = _sym;
        \\// @filename: usage.js
        \\const x = require("./lateBoundAssignmentDeclarationSupport5.js");
        \\const inst2 = new x.F();
        \\const y = inst2["my-fake-sym"];
        \\const z = inst2[x.S];
    );
    defer destroySetup(s);
    s.checker.setCheckJsEnabled(true);
    s.checker.setAllowJsEnabled(true);
