    try s.checker.checkSourceFile(s.root);
    var saw_2315 = false;
    var saw_2346 = false;
    var saw_2508 = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_generic) saw_2315 = true;
        if (d.code == TsCodes.call_target_no_signatures) saw_2346 = true;
        if (d.code == TsCodes.base_constructor_type_arg_count) saw_2508 = true;
    }
    try T.expect(saw_2315);
    try T.expect(saw_2346);
    try T.expect(!saw_2508);
}

