    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.nullish_relational_operand));
    try T.expect(checkerHasCodeAndMessage(s, TsCodes.operator_cannot_be_applied, "Operator '+' cannot be applied to types 'null' and 'undefined'."));
    try T.expect(checkerHasCodeAndMessage(s, TsCodes.operator_cannot_be_applied, "Operator '+' cannot be applied to types 'null' and 'null'."));
    try T.expect(checkerHasCodeAndMessage(s, TsCodes.operator_cannot_be_applied, "Operator '+' cannot be applied to types 'undefined' and 'undefined'."));
}

