    // Negative guard: the apparent-type resolution must not weaken
    // TS2365 for constraints that genuinely cannot use `+`. tsc
    // reports `Operator '+' cannot be applied` for `T extends boolean`
    // and `T extends object` operands (neither is string- nor
    // number-like after resolving to the constraint).
    const s = try newSetup(
        \\function f<T extends boolean>(x: T) { return x + 1; }
        \\function g<T extends object>(y: T) { return y + 1; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.operator_cannot_be_applied) count += 1;
    }
    try T.expectEqual(@as(usize, 2), count);
}

test "checker: TS2389 anchors on the implementation's name identifier" {
    // Mirror upstream `parserFunctionDeclaration4` ÃÂ¢ÃÂÃÂ the diagnostic
    // underlines the function name, not the `function` keyword.
    const src = "function foo();\nfunction bar() { }\n";
    const s = try newSetup(src);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found_pos: ?u32 = null;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.function_implementation_name_mismatch) {
            found_pos = s.checker.hir.spanOf(d.node).start;
            break;
        }
    }
    try T.expect(found_pos != null);
    // The `b` of `bar` sits at offset 25 within the source above
    // (`function foo();\n` is 16 bytes, then `function ` adds 9).
    try T.expectEqual(@as(u32, 25), found_pos.?);
}

test "checker: TS1250 reports strict ES5 function declarations in nested blocks" {
    const src = "function g() { if (true) { function f() {} } }";
    const s = try newSetup(src);
    defer destroySetup(s);
    s.checker.setTargetEmitEs5(true);
    s.checker.setStrictFlags(.{ .always_strict = true });
    try s.checker.checkSourceFile(s.root);

    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.block_scoped_function_strict_es5) continue;
        const pos = d.pos orelse s.hir.spanOf(d.node).start;
        try T.expectEqual(@as(u32, @intCast(std.mem.indexOf(u8, src, "f()").?)), pos);
        found = true;
    }
    try T.expect(found);

    const for_of = try newSetup("for (let v of []) { function loopFn() {} }");
    defer destroySetup(for_of);
    for_of.checker.setTargetEmitEs5(true);
    for_of.checker.setStrictFlags(.{ .always_strict = true });
    try for_of.checker.checkSourceFile(for_of.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(for_of, TsCodes.block_scoped_function_strict_es5));
}

