    const direct = try newSetup("function g() { function f() {} }");
    defer destroySetup(direct);
    direct.checker.setTargetEmitEs5(true);
    direct.checker.setStrictFlags(.{ .always_strict = true });
    try direct.checker.checkSourceFile(direct.root);
    for (direct.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.block_scoped_function_strict_es5);
