test "checker: computed setter/getter name reports TS2304 on unbound identifier" {
    // `class C { set [e](v) {} }` ÃÂ¢ÃÂÃÂ the parser stores the bare `e`
    // identifier as the accessor's name node. `isDeclNameSlot` used
    // to claim that identifier was a declaration name and skipped
    // the TS2304 sweep, leaving the unbound `e` unreported. With
    // the bracketed-computed-name carve-out, the reference is
    // diagnosed correctly. Mirrors `parserComputedPropertyName24
    // .ts(2,10)` (and TS-equivalent fixture 23 for `get`).
    const s = try newSetup("class C { set [e](v) {} }");
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_e: u32 = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.cannot_find_name) continue;
        if (std.mem.indexOf(u8, d.message, "'e'") != null) saw_e += 1;
    }
    try T.expect(saw_e >= 1);
}

test "checker: TS2411 renders inline object types for property and index" {
    // Pins `interfaceWithStringIndexerHidingBaseTypeIndexer.ts(13,5)`:
    // when a derived interface declares a string indexer narrower
    // than its base, the per-property TS2411 must render the offending
    // property's inline object type AND the indexer's value type:
    //   Property 'y' of type '{ a: number; }' is not assignable to
    //   'string' index type '{ a: number; b: number; }'.
    // `formatPropertyNotAssignableToIndexType` falls back to
    // `allocObjectTypeShape` for anonymous object shapes, which
    // `simpleDiagnosticTypeName` returns null for.
    const s = try newSetup(
        \\interface Base { [x: string]: { a: number }; x: { a: number; b: number; }; }
        \\interface Derived extends Base { [x: string]: { a: number; b: number }; y: { a: number; }; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_rich: u32 = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.property_not_assignable_to_index_type) continue;
        if (std.mem.indexOf(u8, d.message, "Property 'y' of type '{") != null and
            std.mem.indexOf(u8, d.message, "'string' index type '{") != null)
        {
            saw_rich += 1;
        }
    }
    try T.expect(saw_rich >= 1);
}

test "checker: for-of let-binding self-referenced in iterable emits TS7022" {
    // Mirrors upstream `for-of55`: `let v = [1]; for (let v of v) {}` ÃÂ¢ÃÂÃÂ
    // tsc anchors TS7022 at the inner `v` binding (block-scoped to
    // the for-loop) and keeps the separate TS2448. The TS2454
    // "used before being assigned" diagnostic is var-only and must
    // not fire for `let`/`const` for-of heads (see `for-of7`).
    const s = try newSetup(
        \\let v = [1];
        \\for (let v of v) { v; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found_7022 = false;
    var found_2454 = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.variable_self_reference_implicitly_any) found_7022 = true;
        if (d.code == TsCodes.used_before_assignment) found_2454 = true;
    }
    try T.expect(found_7022);
    try T.expect(!found_2454);
}

test "checker: for-of let-binding self-reference under @strict:false skips TS7022" {
    // Mirrors upstream `ES5For-of20`: with `// @strict: false`
    // (noImplicitAny off), tsc's circular-initializer trigger
    // (`reportCircularityError`) does NOT emit TS7022 ÃÂ¢ÃÂÃÂ only the
    // related TS2448 fires for the source's TDZ reference. Mirrors
    // the difference between `ES5For-of17` (no strict directive ÃÂ¢ÃÂÃÂ
    // emits TS7022) and `ES5For-of20` (strict:false ÃÂ¢ÃÂÃÂ no TS7022).
    const s = try newSetup(
        \\// @strict: false
        \\for (let v of []) {
        \\    let v;
        \\    for (let v of [v]) {
        \\        const v;
        \\    }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.variable_self_reference_implicitly_any);
    }
}

test "checker: Map instance type carries Map<K, V> alias display name" {
    // Mirrors fixture `iterableArrayPattern26` ÃÂ¢ÃÂÃÂ `new Map([...])`
    // should preserve the alias-display name so downstream TS2345 /
    // TS2322 prose can render the type as `Map<string, number>`
    // rather than collapsing to the structural shape.
    const s = try newSetup(
