}

test "checker: for-await await-using same-name source does not emit TS7022" {
    // Mirrors upstream `awaitUsingDeclarationsInForAwaitOf.2`:
    // `for await (await using of of of) {}` ÃÂ¢ÃÂÃÂ tsc emits TS2448 only
    // (the `of` source reference is in the resource binding's TDZ)
    // and skips TS7022 because `using` / `await using` bind through
    // an explicit resource manager rather than via inferred element
    // types. The TS7022 trigger would otherwise misfire here.
    const s = try newSetup(
        \\// @strict: false
        \\async function test() {
        \\  for await (await using of of of) {};
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.variable_self_reference_implicitly_any);
    }
}

test "checker: TS2850 validates using initializer disposable shape" {
    const s = try newSetup(
        \\function f() {
        \\  using bad = {};
        \\  using nonCallable = { [Symbol.dispose]: 1 };
        \\  using good = { [Symbol.dispose]() {} };
        \\  using nil = null;
        \\  using undef = undefined;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.using_initializer_disposable) {
            count += 1;
            try T.expectEqualStrings("The initializer of a 'using' declaration must be either an object with a '[Symbol.dispose]()' method, or be 'null' or 'undefined'.", d.message);
        }
    }
    try T.expectEqual(@as(usize, 2), count);
}

