test "checker: iterator objects inherit disposable protocols" {
    const s = try newSetup(
        \\// @lib: esnext
        \\declare const iterator: Iterator<string, undefined>;
        \\declare const iteratorObject: IteratorObject<string, undefined, unknown>;
        \\declare const generator: Generator<string, void>;
        \\declare const asyncIterator: AsyncIterator<string, undefined>;
        \\declare const asyncIteratorObject: AsyncIteratorObject<string, undefined, unknown>;
        \\declare const asyncGenerator: AsyncGenerator<string, void>;
        \\class MyIterator extends Iterator<string> {
        \\  next() { return { done: true, value: undefined }; }
        \\}
        \\function f() {
        \\  using fromObject = iteratorObject;
        \\  using fromGenerator = generator;
        \\  using fromFactory = Iterator.from(iterator);
        \\  using fromArray = [].values();
        \\  using fromMap = new Map<string, string>().entries();
        \\  using fromSubclass = new MyIterator();
        \\  using invalid = iterator;
        \\}
        \\async function g() {
        \\  await using fromObject = asyncIteratorObject;
        \\  await using fromGenerator = asyncGenerator;
        \\  await using invalid = asyncIterator;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.using_initializer_disposable));
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.await_using_initializer_disposable));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.cannot_find_name_did_you_mean));
}

test "checker: import type specifier in .js virtual section emits TS8006" {
