test "checker: TS2534 reports reachable endpoint in never-returning function" {
    const source =
        \\declare function fail(): never;
        \\function empty(): never {
        \\}
        \\function partial(x: boolean): never {
        \\    if (x) throw 1;
        \\}
        \\function throwing(): never {
        \\    throw 1;
        \\}
        \\function returning(): never {
        \\    return fail();
        \\}
        \\function infinite(): never {
        \\    while (true) {
        \\    }
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var count_2534: usize = 0;
    var count_2355: usize = 0;
    var saw_never_anchor = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.fn_returning_never_reachable_endpoint) {
            count_2534 += 1;
            const p = d.pos orelse s.hir.spanOf(d.node).start;
            if (std.mem.eql(u8, source[p..][0..5], "never")) saw_never_anchor = true;
            try T.expect(std.mem.eql(u8, d.message, "A function returning 'never' cannot have a reachable end point."));
        }
        if (d.code == TsCodes.fn_must_return_value) count_2355 += 1;
    }
    try T.expectEqual(@as(usize, 2), count_2534);
    try T.expectEqual(@as(usize, 0), count_2355);
    try T.expect(saw_never_anchor);
}

test "checker: reachabilityChecks7 async TS7030 + TS2355 fire at the right anchors" {
    // Mirrors compiler/reachabilityChecks7.ts under `// @noImplicitReturns: true`.
    //   - `async function f3(x) { if (x) return 10; }` ÃÂ¢ÃÂÃÂ no annotation,
    //     one value-returning path plus a fall-through ÃÂ¢ÃÂÃÂ TS7030 anchored
    //     at the function name `f3`.
    //   - `async function f4(): Promise<number> {}` ÃÂ¢ÃÂÃÂ explicit non-void
    //     promised type, no return at all ÃÂ¢ÃÂÃÂ TS2355 anchored at the
    //     `Promise<number>` return-type annotation.
    //   - `async function f2(): Promise<void> {}` (void promised type),
    //     `async function f1() {}` (inferred void), `voidFunc(): void`,
    //     and `calltoVoidFunc(x) { if (x) return voidFunc(); }` (void
    //     value returns) must all stay clean.
    const source =
        \\async function f1() {}
        \\async function f2(): Promise<void> {}
        \\async function f3(x) {
        \\    if (x) return 10;
        \\}
        \\async function f4(): Promise<number> {
        \\}
        \\function voidFunc(): void {}
        \\function calltoVoidFunc(x) {
        \\    if (x) return voidFunc();
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_returns = true });
    try s.checker.checkSourceFile(s.root);
    var count_7030: usize = 0;
    var count_2355: usize = 0;
    var pos_7030: u32 = 0;
    var pos_2355: u32 = 0;
    for (s.checker.diagnostics.items) |d| {
        // Resolve the concrete byte position the same way the conformance
        // layer does: explicit `pos`, else the node's span start.
        const p = d.pos orelse s.hir.spanOf(d.node).start;
        if (d.code == TsCodes.not_all_code_paths_return) {
            count_7030 += 1;
            pos_7030 = p;
        }
        if (d.code == TsCodes.fn_must_return_value) {
            count_2355 += 1;
            pos_2355 = p;
        }
    }
    try T.expectEqual(@as(usize, 1), count_7030);
    try T.expectEqual(@as(usize, 1), count_2355);
    // TS7030 anchors at the function name `f3`.
    try T.expectEqualStrings("f3", source[pos_7030..][0..2]);
    // TS2355 anchors at the `Promise<number>` return-type annotation.
    try T.expectEqualStrings("Promise", source[pos_2355..][0..7]);
}

test "checker: noImplicitReturns stays silent for always-return / void / annotation-free bodies" {
    // Negative coverage for the TS7030 / TS2355 control-flow checks:
    //   - `always`: every path returns a value (no fall-through) ÃÂ¢ÃÂÃÂ clean.
    //   - `voidFn`: explicit `void` return type, no return ÃÂ¢ÃÂÃÂ clean.
    //   - `noAnno`: no annotation, no value-returning path (inferred
    //     `void`), even though it has a fall-through ÃÂ¢ÃÂÃÂ clean.
    //   - `voidValue`: no annotation, only returns a `void` value ÃÂ¢ÃÂÃÂ clean.
    //   - `f2`: async `Promise<void>` ÃÂ¢ÃÂÃÂ clean.
    const source =
        \\function always(x: boolean): number {
        \\    if (x) return 1;
        \\    return 2;
        \\}
        \\function voidFn(x: boolean): void {
        \\    if (x) { }
        \\}
        \\function noAnno(x: boolean) {
        \\    if (x) { }
        \\}
        \\function voidValue(x: boolean) {
        \\    if (x) return voidFn(x);
        \\}
        \\async function f2(): Promise<void> {
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_returns = true });
    try s.checker.checkSourceFile(s.root);
    var count_7030: usize = 0;
    var count_2355: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.not_all_code_paths_return) count_7030 += 1;
        if (d.code == TsCodes.fn_must_return_value) count_2355 += 1;
    }
    try T.expectEqual(@as(usize, 0), count_7030);
    try T.expectEqual(@as(usize, 0), count_2355);
}

