// TS2441 ÃÂ¢ÃÂÃÂ top-level `export enum require {}` / `export enum exports {}`
// in an external module collides with the names the module system
// reserves when emitting CommonJS/AMD/UMD/System. Mirrors
// `collisionExportsRequireAndEnum_externalmodule.ts(1,13)` and `(5,13)`.
test "checker: TS2441 for top-level require/exports enum in external module" {
    const src =
        "//@module: amd\n" ++
        "export enum require {\n" ++ // (2,13) ÃÂ¢ÃÂÃÂ reserved name
        "  _thisVal1,\n" ++
        "}\n" ++
        "export enum exports {\n" ++ // reserved name
        "  _thisVal1,\n" ++
        "}\n";
    const b = try newBoundSetup(src);
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);

    // Both `require` and `exports` must produce TS2441, each anchored at
    // its name identifier with tsc's exact wording.
    var saw_require = false;
    var saw_exports = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.duplicate_identifier_reserves_name) continue;
        const d_pos = d.pos orelse b.base.hir.spanOf(d.node).start;
        // Identifier follows the `export enum ` prefix on its line.
        const at = std.mem.indexOfPos(u8, src, 0, "enum require").? + "enum ".len;
        const ax = std.mem.indexOfPos(u8, src, 0, "enum exports").? + "enum ".len;
        if (d_pos == at and std.mem.eql(u8, d.message, "Duplicate identifier 'require'. Compiler reserves name 'require' in top level scope of a module.")) saw_require = true;
        if (d_pos == ax and std.mem.eql(u8, d.message, "Duplicate identifier 'exports'. Compiler reserves name 'exports' in top level scope of a module.")) saw_exports = true;
    }
    if (!saw_require or !saw_exports) {
        std.debug.print("expected TS2441 x2 (require+exports); diagnostics:\n", .{});
        for (b.base.checker.diagnostics.items) |d| {
            std.debug.print("  TS{d} @{?}: {s}\n", .{ d.code, d.pos, d.message });
        }
    }
    try T.expect(saw_require);
    try T.expect(saw_exports);
}

// Negative ÃÂ¢ÃÂÃÂ inside a namespace the reserved names are scoped to the
