test "checker: TS2529 for top-level Promise binding in async external module below ES2017" {
    const src =
        "//@target: es5\n" ++
        "//@module: amd\n" ++
        "export async function f() {}\n" ++
        "export enum Promise { A }\n";
    const b = try newBoundSetup(src);
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);

    var saw_promise = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.duplicate_identifier_reserves_name_async) continue;
        const d_pos = d.pos orelse b.base.hir.spanOf(d.node).start;
        const promise_pos = std.mem.indexOfPos(u8, src, 0, "enum Promise").? + "enum ".len;
        if (d_pos == promise_pos and
            std.mem.eql(u8, d.message, "Duplicate identifier 'Promise'. Compiler reserves name 'Promise' in top level scope of a module containing async functions."))
        {
            saw_promise = true;
        }
    }
    if (!saw_promise) {
        std.debug.print("expected TS2529 for top-level Promise enum; diagnostics:\n", .{});
        for (b.base.checker.diagnostics.items) |d| {
            std.debug.print("  TS{d} @{?}: {s}\n", .{ d.code, d.pos, d.message });
        }
    }
    try T.expect(saw_promise);
}

