    for (s.checker.diagnostics.items) |d| {
        if (std.mem.indexOf(u8, d.message, "{ '1.0': string; }") != null) saw = true;
        // The buggy form must not appear.
        try T.expect(std.mem.indexOf(u8, d.message, "{ 1.0: string") == null);
    }
    try T.expect(saw);
}

