    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.interface_cannot_simultaneously_extend));
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.interface_incorrectly_extends));
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.protected_member_access));
}

test "checker: TS2320 suppressed when derived interface overrides conflicting base property" {
    // `C extends A, B` where A.x and B.x conflict, but C declares `x`
    // itself. The override resolves the base conflict, so tsc emits NO
    // TS2320 (each base is instead checked against C's own member,
    // yielding per-base TS2430 when incompatible). Mirrors
    // `interfaceWithMultipleBaseTypes2`.
    const s = try newSetup(
        \\interface A { x: string; }
        \\interface B { x: number; }
        \\interface C extends A, B { x: string | number; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.interface_cannot_simultaneously_extend));
}

test "checker: TS2320 conflicting generic base interfaces render their type arguments" {
    // `A extends I<number>, I<string>` — the conflicting bases must render
    // with their type arguments (`I<number>` / `I<string>`), not the bare
    // ref name `I`. Mirrors `callSignaturesThatDifferOnlyByReturnType2`.
    const s = try newSetup(
        \\interface I<T> { foo(x: number): T; }
        \\interface A extends I<number>, I<string> { }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.interface_cannot_simultaneously_extend) {
            saw = true;
            try T.expect(std.mem.indexOf(u8, d.message, "extend types 'I<number>' and 'I<string>'") != null);
            try T.expect(std.mem.indexOf(u8, d.message, "extend types 'I' and 'I'") == null);
        }
    }
    try T.expect(saw);
}

test "checker: merged interface arms compare all inherited bases" {
    const s = try newSetup(
        \\class C<T> { a!: T; }
        \\class C2<T> { b!: T; }
        \\interface A<T> extends C<string> { y: T; }
        \\interface A<T> extends C<number>, C2<string> { z: T; }
        \\class D implements A<boolean> { a!: string; b!: string; y!: boolean; z!: boolean; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.interface_cannot_simultaneously_extend));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.class_incorrectly_implements_interface));
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.interface_cannot_simultaneously_extend) continue;
        try T.expectEqualStrings(
            "Interface 'A<T>' cannot simultaneously extend types 'C<string>' and 'C<number>'.",
            d.message,
        );
