test "checker: TS2366 fires for fall-through with explicit return under strictNullChecks" {
    const source =
        \\function f(x: boolean): number {
        \\    if (x) return 1;
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
    var count_2366: usize = 0;
    var count_2355: usize = 0;
    var pos_2366: u32 = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.fn_lacks_ending_return) {
            count_2366 += 1;
            pos_2366 = d.pos orelse s.hir.spanOf(d.node).start;
            try T.expectEqualStrings(
                "Function lacks ending return statement and return type does not include 'undefined'.",
                d.message,
            );
        }
        if (d.code == TsCodes.fn_must_return_value) count_2355 += 1;
    }
    try T.expectEqual(@as(usize, 1), count_2366);
    try T.expectEqual(@as(usize, 0), count_2355);
    try T.expectEqualStrings("number", source[pos_2366..][0..6]);
}

