    var saw_bad_async_union = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.fn_must_return_value) continue;
        count_2355 += 1;
        const p = d.pos orelse s.hir.spanOf(d.node).start;
        const tail = source[p..];
        if (std.mem.startsWith(u8, tail, "undefined | number")) saw_bad_union = true;
        if (std.mem.startsWith(u8, tail, "Promise<undefined | number>")) saw_bad_async_union = true;
