// ---- TS7029 (Fallthrough case in switch) ---------------------------
// Positive: under `noFallthroughCasesInSwitch`, a non-empty `case`
// whose body reaches its end and is followed by another clause falls
// through. The first clause (`if (y) { return 2; }` ÃÂ¢ÃÂÃÂ no else) reaches
// its end and falls into `case 3`; the final clause never errors.
// Mirrors fixture `reachabilityChecks4` (`foo`).
test "checker: TS7029 fires for a falling-through non-empty case under noFallthroughCasesInSwitch" {
    const source =
        \\function foo(x: number, y: boolean): number {
        \\    switch (x) {
        \\        case 1:
        \\        case 2:
        \\            return 1;
        \\        case 3:
        \\            if (y) {
        \\                return 2;
        \\            }
        \\        case 4:
        \\            return 3;
        \\    }
        \\    return 0;
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_fallthrough_cases_in_switch = true });
    try s.checker.checkSourceFile(s.root);
    var count_7029: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.fallthrough_case_in_switch) {
            count_7029 += 1;
            try T.expectEqualStrings("Fallthrough case in switch.", d.message);
        }
    }
    // Only `case 3` falls through. The empty `case 1` is intentional
    // group fallthrough; `case 2` returns; `case 4` is the last clause.
    try T.expectEqual(@as(usize, 1), count_7029);
}

// Negative: a clause that ends in `break` does not fall through, and a
// clause that ends in `return` is terminal. With every reachable clause
// terminated (and the final clause exempt), TS7029 stays silent even
// with the flag on.
test "checker: TS7029 stays silent when every case breaks or returns" {
    const source =
        \\function foo(x: number): number {
        \\    switch (x) {
        \\        case 1:
        \\            return 1;
        \\        case 2:
        \\            break;
        \\        default:
        \\            return 0;
        \\    }
        \\    return -1;
        \\}
    ;
