    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_fallthrough_cases_in_switch = true });
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.fallthrough_case_in_switch);
    }
}

