// ---- TS7015 (index expression is not of type 'number') -------------
// Positive: under `noImplicitAny`, indexing a type whose ONLY index
// signature is numeric with a string-literal index implicitly resolves
// to `any`. Anchored at the argument expression. Mirrors fixture
// `noImplicitAnyIndexing`.
test "checker: TS7015 fires indexing a numeric-only index signature with a string key" {
    const source =
        \\interface NumOnly {
        \\    [n: number]: string;
        \\}
        \\declare const obj: NumOnly;
        \\const v = obj["monehh"];
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);
    var count_7015: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.element_implicitly_any_index_not_number) {
            count_7015 += 1;
            try T.expectEqualStrings(
                "Element implicitly has an 'any' type because index expression is not of type 'number'.",
                d.message,
            );
        }
    }
    try T.expectEqual(@as(usize, 1), count_7015);
}

// Negative: the same numeric-only index signature accessed with a
// numeric index resolves through the numeric indexer ÃÂ¢ÃÂÃÂ no TS7015.
test "checker: TS7015 stays silent for a numeric index on a numeric index signature" {
    const source =
        \\interface NumOnly {
        \\    [n: number]: string;
        \\}
        \\declare const obj: NumOnly;
        \\const v = obj[0];
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.element_implicitly_any_index_not_number);
    }
}

// Negative: a type that also carries a string index signature can be
// indexed by a string key without implicit-any ÃÂ¢ÃÂÃÂ TS7015 must not fire.
test "checker: TS7015 stays silent when a string index signature is present" {
    const source =
        \\interface BothIdx {
        \\    [n: number]: string;
        \\    [s: string]: string;
        \\}
        \\declare const obj: BothIdx;
        \\const v = obj["monehh"];
    ;
