    }
}

test "checker: TS7020 fires for an unannotated interface call signature under noImplicitAny" {
    // Mirrors noImplicitAnyParametersInInterface.ts(3,5): a bare `()`
    // call signature with no return annotation implicitly returns 'any'.
    const source =
        \\interface I {
        \\  ();
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);
    var count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.call_signature_return_implicitly_any) {
            count += 1;
            try T.expectEqualStrings(
                "Call signature, which lacks return-type annotation, implicitly has an 'any' return type.",
                d.message,
            );
        }
        try T.expect(d.code != TsCodes.function_return_implicitly_any);
    }
    try T.expectEqual(@as(usize, 1), count);
}

test "checker: TS7020 stays silent for an annotated call signature and when noImplicitAny is off" {
    const source =
        \\interface Annotated {
        \\  (): void;
        \\}
        \\interface Bare {
        \\  ();
        \\}
    ;
    {
        // Annotated call signature: clean even under noImplicitAny.
        const s = try newSetup(source);
        defer destroySetup(s);
        s.checker.setStrictFlags(.{ .no_implicit_any = true });
        try s.checker.checkSourceFile(s.root);
        var count: usize = 0;
        for (s.checker.diagnostics.items) |d| {
            if (d.code == TsCodes.call_signature_return_implicitly_any) count += 1;
        }
        // Only the bare `()` should fire ÃÂ¢ÃÂÃÂ the annotated one stays clean.
        try T.expectEqual(@as(usize, 1), count);
    }
    {
        // noImplicitAny off: nothing fires at all.
        const s = try newSetup(source);
        defer destroySetup(s);
        try s.checker.checkSourceFile(s.root);
        for (s.checker.diagnostics.items) |d| {
            try T.expect(d.code != TsCodes.call_signature_return_implicitly_any);
        }
    }
}

