test "checker: call signature parameters still report TS7006 alongside TS7020" {
    // Mirrors noImplicitAnyParametersInInterface.ts(4,5)+(4,6): the bare
    // `(x1)` call signature fires TS7020 for the missing return type and
    // TS7006 for the implicitly-any parameter.
    const source =
        \\interface I {
        \\  (x1);
        \\}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);
    var count_7020: usize = 0;
    var count_7006: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.call_signature_return_implicitly_any) count_7020 += 1;
        if (d.code == TsCodes.parameter_implicitly_any) count_7006 += 1;
    }
    try T.expectEqual(@as(usize, 1), count_7020);
    try T.expectEqual(@as(usize, 1), count_7006);
}

test "checker: TS2714 fires for non-entity-name export assignment in ambient context" {
    // Mirrors `ambientExportDefaultErrors.foo2.d.ts(1,10)`: a `.d.ts`
    // (ambient) module whose `export = <expr>` assigns a non-entity
    // expression (`2 + 2`). tsc anchors TS2714 at the expression.
    const s = try newSetup("export = 2 + 2;");
    defer destroySetup(s);
    s.checker.setIsDeclarationFile(true);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.export_assignment_must_be_entity_name and
            std.mem.eql(u8, d.message, "The expression of an export assignment must be an identifier or qualified name in an ambient context."))
            found = true;
    }
    if (!found) {
        std.debug.print("expected TS2714 for non-entity export assignment; diagnostics:\n", .{});
        for (s.checker.diagnostics.items) |d| std.debug.print("  TS{d}: {s}\n", .{ d.code, d.message });
    }
    try T.expect(found);
}

