test "checker: TS2575 fires for overload call whose arity falls between two overload arities" {
    // Mirrors `functionParameterArityMismatch.ts(11,1)`: overloads with
    // arities {0, 2, 4, 6}; the call `f2(1)` matches no overload by
    // arity but sits between 0 and 2 ÃÂ¢ÃÂÃÂ TS2575 names those neighbours.
    const s = try newSetup(
        \\declare function f2();
        \\declare function f2(a: number, b: number);
        \\declare function f2(a: number, b: number, c: number, d: number);
        \\f2(1);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.no_overload_expects_n_args_but_others_exist and
            std.mem.eql(u8, d.message, "No overload expects 1 arguments, but overloads do exist that expect either 0 or 2 arguments."))
            found = true;
    }
    if (!found) {
        std.debug.print("expected TS2575 for between-arity overload call; diagnostics:\n", .{});
        for (s.checker.diagnostics.items) |d| std.debug.print("  TS{d}: {s}\n", .{ d.code, d.message });
    }
    try T.expect(found);
}

test "checker: TS2575 stays silent when an overload arity matches the call" {
    // Negative: `f1(1, 2, 3)` matches the second overload's arity
    // exactly, so overload resolution succeeds ÃÂ¢ÃÂÃÂ no TS2575 (and no
    // TS2769) should fire. Mirrors the clean lines of
    // `functionParameterArityMismatch.ts`.
    const s = try newSetup(
        \\declare function f1(a: number);
        \\declare function f1(a: number, b: number, c: number);
        \\f1(1, 2, 3);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.no_overload_expects_n_args_but_others_exist);
        try T.expect(d.code != TsCodes.no_overload_matches);
    }
}

test "checker: TS2575 not emitted (TS2554) when arity is outside the whole overload range" {
    // Negative: `f1(1, 2, 3, 4)` exceeds the largest overload arity (3),
    // so tsc emits a plain TS2554 ("Expected 1-3 arguments, but got 4."),
    // never TS2575. Mirrors `functionParameterArityMismatch.ts(5,13)`.
    const s = try newSetup(
        \\declare function f1(a: number);
        \\declare function f1(a: number, b: number, c: number);
        \\f1(1, 2, 3, 4);
