test "checker: TS2632 fires when assigning to a named import" {
    // Positive: a named import is implicitly read-only ÃÂ¢ÃÂÃÂ assigning to it
    // reports TS2632 with the import name. Mirrors
    // `importsImplicitlyReadonly.errors.txt(6,1)`.
    const b = try newBoundSetup(
        \\import { x } from "./a";
        \\x = 1;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    var found = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.cannot_assign_to_import) {
            found = true;
            try T.expect(std.mem.eql(u8, d.message, "Cannot assign to 'x' because it is an import."));
        }
    }
    try T.expect(found);
}

