            found = true;
            try T.expect(std.mem.eql(u8, d.message, "Cannot assign to 'ns' because it is an import."));
        }
    }
    try T.expect(found);
}

test "checker: namespace assignment distinguishes type-only and runtime values" {
    const b = try newBoundSetup(
        \\namespace Empty {}
        \\Empty = null;
        \\namespace Runtime { export const value = 1; }
        \\Runtime = null;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);

    try T.expectEqual(@as(usize, 1), checkerCountCode(b.base, TsCodes.namespace_as_value));
    try T.expectEqual(@as(usize, 1), checkerCountCode(b.base, TsCodes.cannot_assign_to_namespace));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.namespace_as_value, "Cannot use namespace 'Empty' as a value."));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.cannot_assign_to_namespace, "Cannot assign to 'Runtime' because it is a namespace."));
}

test "checker: nested namespace assignments retain namespace value shape" {
    const b = try newBoundSetup(
        \\namespace M2 {
        \\  export namespace M3 {
        \\    export var x: number;
        \\  }
        \\  M3 = { x: 3 };
        \\}
        \\M2.M3 = { x: '' };
        \\(M2).M3 = { x: '' };
        \\(M2.M3) = { x: '' };
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);

    try T.expectEqual(@as(usize, 1), checkerCountCode(b.base, TsCodes.cannot_assign_to_namespace));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.cannot_assign_to_namespace, "Cannot assign to 'M3' because it is a namespace."));
    try T.expectEqual(@as(usize, 3), checkerCountCode(b.base, TsCodes.type_not_assignable));
}

test "checker: merged nested namespace values expose every contribution" {
    const b = try newBoundSetup(
        \\// @filename: part1.ts
        \\namespace A {
        \\  export namespace Utils {
        \\    export function mirror(value: number) { return value; }
        \\  }
        \\}
        \\// @filename: part2.ts
        \\namespace A {
        \\  export namespace Utils {
        \\    export class Plane {}
        \\  }
        \\}
        \\// @filename: part3.ts
        \\A.Utils.mirror(1);
        \\new A.Utils.Plane();
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);

    try T.expectEqual(@as(usize, 0), checkerCountCode(b.base, TsCodes.property_does_not_exist));
}

