test "checker: object rest over nullish union reports missing named binding on union" {
    // Mirrors restUnion.ts: a rest binding over a nullish union reports
    // TS2339 on the named property against the whole union type.
    const s = try newSetup(
        \\var undefinedUnion: { n: number } | undefined;
        \\var rest2: {};
        \\var {n, ...rest2 } = undefinedUnion;
        \\var nullUnion: { n: number } | null;
        \\var rest3: {};
        \\var {n, ...rest3 } = nullUnion;
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);

    var missing_n_count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.property_does_not_exist and
            std.mem.indexOf(u8, d.message, "Property 'n' does not exist on type") != null)
        {
            missing_n_count += 1;
        }
        try T.expect(d.code != TsCodes.object_possibly_undefined);
    }
    try T.expectEqual(@as(usize, 2), missing_n_count);
}

test "checker: TS2718 fires for a data/method symbol-keyed duplicate in an object literal" {
    // Positive. tsc late-binds the `unique symbol` computed key `[sym]`
    // (a `const s = Symbol()` binding) and finds it declared once as a
    // data property and once as a method. The conflicting symbol kinds
    // make tsc 5.9 emit `TS2718: Duplicate property '[sym]'.` on the
    // later (method) declaration ÃÂ¢ÃÂÃÂ verified directly against tsc on
    //   const sym = Symbol();
    //   const o = { [sym]: 1, [sym]() { return 2; } };
    const s = try newSetup(
        \\const sym = Symbol();
        \\const o = {
        \\  [sym]: 1,
        \\  [sym]() { return 2; },
        \\};
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.duplicate_property and
            std.mem.eql(u8, d.message, "Duplicate property '[sym]'."))
            found = true;
    }
    if (!found) {
        std.debug.print("expected TS2718 for symbol-keyed data/method dup; diagnostics:\n", .{});
        for (s.checker.diagnostics.items) |d| std.debug.print("  TS{d}: {s}\n", .{ d.code, d.message });
    }
    try T.expect(found);
}

test "checker: TS2718 fires for a data/accessor symbol-keyed duplicate in an object literal" {
    // Positive. A data property and a getter sharing the late-bound
    // `unique symbol` name also conflict in kind, so tsc emits TS2718
    // (alongside its own TS1119/TS2733) on the accessor declaration.
    const s = try newSetup(
        \\const sym = Symbol();
        \\const o = {
        \\  [sym]: 1,
        \\  get [sym]() { return 2; },
        \\};
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.duplicate_property and
            std.mem.eql(u8, d.message, "Duplicate property '[sym]'."))
            found = true;
    }
    try T.expect(found);
}

test "checker: TS2718 stays silent for a valid object literal with distinct symbol keys" {
    // Negative. Two different `unique symbol` bindings name two distinct
    // members, so there is no duplicate at all ÃÂ¢ÃÂÃÂ no TS2718.
    const s = try newSetup(
        \\const sym = Symbol();
        \\const sym2 = Symbol();
        \\const o = {
        \\  [sym]: 1,
        \\  [sym2]() { return 2; },
        \\};
