        try T.expect(d.code != TsCodes.duplicate_property);
    }
}

test "checker: TS1117 duplicate object-literal property ignores parse-diagnostics flag" {
    // TS1117 must still be reported for object literals whose effective
    // keys normalize to the same name even when the file already has a
    // parse diagnostic. Mirrors `numericStringNamedPropertyEquivalence`,
    // where the duplicate property diagnostic coexists with earlier parse
    // recovery state. Same object literal, two flag states.
    {
        // Parse-clean: TS1117 fires on the later duplicate property.
        const s = try newSetup(
            \\var obj1 = { 26: "a", "26": "b" };
        );
        defer destroySetup(s);
        s.checker.setHasParseDiagnostics(false);
        try s.checker.checkSourceFile(s.root);
        var found = false;
        for (s.checker.diagnostics.items) |d| {
            if (d.code == TsCodes.object_literal_duplicate_property) found = true;
        }
        try T.expect(found);
    }
    {
        // Parse error present: the duplicate-property grammar check still
        // fires because TypeScript keeps TS1117 in this recovery state.
        const s = try newSetup(
            \\var obj1 = { 26: "a", "26": "b" };
        );
        defer destroySetup(s);
        s.checker.setHasParseDiagnostics(true);
        try s.checker.checkSourceFile(s.root);
        var found = false;
        for (s.checker.diagnostics.items) |d| {
            if (d.code == TsCodes.object_literal_duplicate_property) found = true;
        }
        try T.expect(found);
    }
}

test "checker: recovered prefixed numeric keys suppress TS1117" {
    const s = try newSetup(
        \\var invalid = 0b102;
        \\var binary = { 0b11010: "a", 26: "b", "26": "c" };
        \\var octal = { 0o32: "a", 26: "b", "26": "c" };
    );
    defer destroySetup(s);
    try T.expect(s.parser.diagnostics.items.len > 0);
    s.checker.setHasParseDiagnostics(true);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.object_literal_duplicate_property));
}

test "checker: a string-literal computed duplicate is not reclassified as TS2718" {
    // Negative. A string-literal computed key (`["foo"]`) is early-bound
    // under its string name, so tsc reports the data/method collision as
    // TS1119/TS2300 ÃÂ¢ÃÂÃÂ never TS2718. Home must not over-fire TS2718 here:
    // the symbol-like key gate excludes the string key. (Home does not
    // yet emit TS1119/TS2300 for this exact shape; the assertion only
    // pins that TS2718 specifically does not appear.)
    const s = try newSetup(
        \\const o = {
        \\  ["foo"]: 1,
        \\  ["foo"]() { return 2; },
        \\};
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.duplicate_property);
    }
}

test "checker: a same-kind symbol-keyed duplicate is not reported as TS2718" {
    // Negative. Two data properties under the same late-bound symbol name
    // do NOT conflict in kind ÃÂ¢ÃÂÃÂ tsc reports TS1117 there, not TS2718. The
    // kind-conflict guard keeps Home from firing TS2718 on this shape.
    const s = try newSetup(
        \\const sym = Symbol();
        \\const o = {
        \\  [sym]: 1,
        \\  [sym]: 2,
        \\};
