test "checker: stable late-bound unique-symbol object keys report TS1117" {
    const s = try newSetup(
        \\interface Ops { readonly equal: unique symbol; }
        \\const op = { equal: Symbol() } as Ops;
        \\const key = Symbol();
        \\function getKey(): typeof key { return key; }
        \\let broad = Symbol();
        \\function getBroad(): symbol { return broad; }
        \\const stable = {
        \\  [op.equal]: 1,
        \\  [op.equal]: 2,
        \\  [getKey()]: 3,
        \\  [getKey()]: 4,
        \\};
        \\const dynamic = {
        \\  [broad]: 1,
        \\  [broad]: 2,
        \\  [getBroad()]: 3,
        \\  [getBroad()]: 4,
        \\};
