}

test "checker: checkjs @template with curly braces but no name emits TS1069" {
    // Mirrors `jsdocOuterTypeParameters1.js(4,19)`:
    //
    //      * @template {T}
    //      * @template U
    //
    // The `{T}` is parsed as a constraint by JSDoc's type expression
    // path, then `parseJSDocIdentifierName` finds no trailing name
    // and emits TS1069 with the upstream message. Home recognizes
    // the same shape via `checkJsDocTemplateBracketedName` ÃÂ¢ÃÂÃÂ when a
    // `@template` tag has non-empty `type_text` but empty `name`,
    // surface TS1069 at the next JSDoc token (matching upstream's
    // recovery position).
    const source =
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @Filename: /a.js
        \\/**
        \\ * @template {T}
        \\ * @template U
        \\ */
        \\function f() {}
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == 1069) {
            found = true;
            try T.expect(d.pos != null);
            const expected = std.mem.indexOf(u8, source, "* @template U") orelse unreachable;
            try T.expectEqual(@as(u32, @intCast(expected)), d.pos.?);
            try T.expect(std.mem.indexOf(u8, d.message, "type parameter name was expected without curly braces") != null);
        }
    }
    try T.expect(found);
}

test "checker: checkjs @template with trailing name does NOT emit TS1069" {
    // Guard rail: `@template {Constraint} Name` is the canonical
    // constrained-type-parameter shape and must stay clean ÃÂ¢ÃÂÃÂ only
    // the empty-name variant trips TS1069.
    const source =
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @Filename: /a.js
        \\/** @template {string} T */
        \\function f(x) { return x; }
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != 1069);
    }
}

test "checker: checkjs class malformed @template and static prototype access report" {
    // Mirrors jsdocOuterTypeParameters3: class-level `@template {T}`
    // gets both the unresolved constraint name and TS1069, and
    // `this.prototype` inside a static method is the class instance type.
    const s = try newSetup(
        \\// @target: es2015
        \\// @allowJs: true
        \\// @checkJs: true
        \\// @filename: jsdocOuterTypeParameters3.js
        \\/** @template {T} */
        \\class Baz {
        \\    m() {
        \\        class Bar {
        \\            static bar() { this.prototype.foo(); }
        \\        }
        \\    }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_t = false;
    var saw_template = false;
    var saw_foo = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.cannot_find_name and std.mem.indexOf(u8, d.message, "Cannot find name 'T'.") != null) saw_t = true;
        if (d.code == 1069 and std.mem.indexOf(u8, d.message, "type parameter name was expected without curly braces") != null) saw_template = true;
        if (d.code == TsCodes.property_does_not_exist and std.mem.indexOf(u8, d.message, "Property 'foo' does not exist on type 'Bar'.") != null) saw_foo = true;
    }
    try T.expect(saw_t);
    try T.expect(saw_template);
    try T.expect(saw_foo);
}

test "checker: TS1148 fires for a top-level import under module none" {
    // Positive. `--module none` forbids files that are external
    // modules; the diagnostic anchors at the `import` keyword.
    const s = try newSetup(
        \\// @module: none
        \\import { a } from "./m";
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    const src = s.checker.source.?;
    const expected_pos = std.mem.indexOf(u8, src, "import").?;
    var found: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.imports_exports_with_module_none) continue;
        const pos = d.pos orelse s.checker.hir.spanOf(d.node).start;
        try T.expectEqual(expected_pos, pos);
        found += 1;
    }
    try T.expectEqual(@as(usize, 1), found);
}

