fn checkerHasCode(b: *BoundTestSetup, code: u32) bool {
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == code) return true;
    }
    return false;
}

test "checker: TS4020 fires for exported class extending a non-exported local class under declaration emit" {
    // Positive (TS4020). Mirrors privacyClassExtendsClauseDeclFile.ts:
    // an EXPORTED class whose `extends` clause names a module-local class
    // that is NOT exported leaks a private name into the emitted `.d.ts`.
    const b = try newBoundSetup(
        \\class PrivateBase {}
        \\export class Derived extends PrivateBase {}
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .declaration = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCode(b, TsCodes.extends_clause_class_private_name));
    // The named owner form, not the no-owner TS4021 variant.
    try T.expect(!checkerHasCode(b, TsCodes.extends_clause_class_private_name_no_owner));
}

test "checker: TS4021 fires for default-exported anonymous class extending a non-exported local class" {
    // Positive (TS4021). A default-exported ANONYMOUS class has no name to
    // interpolate, so the `extends`-clause privacy leak uses the no-owner
    // message form. Mirrors upstream's `node.Parent.Parent.Name() == nil`
    // branch in the declaration transformer.
    const b = try newBoundSetup(
        \\class PrivateBase {}
        \\export default class extends PrivateBase {}
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .declaration = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCode(b, TsCodes.extends_clause_class_private_name_no_owner));
    // The owner-interpolating TS4020 must NOT also fire (no class name).
    try T.expect(!checkerHasCode(b, TsCodes.extends_clause_class_private_name));
}

