test "checker: no heritage private-name diagnostics when declaration emit is off" {
    // Negative. With `declaration: false`, no `.d.ts` is emitted, so the
    // symbol-accessibility family must stay silent even though the base
    // is a non-exported module-local class.
    const b = try newBoundSetup(
        \\class PrivateBase {}
        \\export class Derived extends PrivateBase {}
        \\interface PrivateShape {}
        \\export class C implements PrivateShape {}
    );
    defer destroyBoundSetup(b);
    // Default strict flags leave `declaration` off.
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.extends_clause_class_private_name));
    try T.expect(!checkerHasCode(b, TsCodes.implements_clause_private_name));
    try T.expect(!checkerHasCode(b, TsCodes.extends_clause_interface_private_name));
}

test "checker: no TS4020 when a NON-exported class extends a non-exported local class" {
    // Negative. A private (non-exported) class never reaches the emitted
    // `.d.ts`, so its heritage cannot leak a private name ÃÂ¢ÃÂÃÂ matches the
    // `privateClassExtending*` cases that upstream does NOT flag.
    const b = try newBoundSetup(
        \\class PrivateBase {}
        \\class PrivateDerived extends PrivateBase {}
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .declaration = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.extends_clause_class_private_name));
}

fn checkerHasCodeWithMessage(b: *BoundTestSetup, code: u32, message: []const u8) bool {
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == code and std.mem.eql(u8, d.message, message)) return true;
    }
    return false;
}

// ---------------------------------------------------------------------------
// Declaration-emit symbol-accessibility family (TS4002/4016/4025/4028/4031/
// 4033/4035/4037/4040/4043/4052/4055/4057/4060/4063/4070/4073/4075/4078/
// 4081/4082/4083). Each fires only under `declaration: true` and only when an
// exported declaration references a non-exported module-local type.
// ---------------------------------------------------------------------------

