    b.base.checker.setStrictFlags(.{ .declaration = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.exported_variable_private_name, "Exported variable 'widget' has or is using private name 'PrivateThing'."));
}

