test "checker: TS1379 fires for an import alias referencing a type-only cross-module export" {
    const s = try newSetup(
        \\import a = require("./a");
        \\import foo = a.Foo;
    );
    defer destroySetup(s);
    var stub = CrossModuleStubResolver{ .canned_module_name = "\"a\"", .exported_name = "Foo", .exported_type = false, .type_only_export = true };
    try runCrossModuleCheck(s, &stub);
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.import_alias_references_export_type,
        "An import alias cannot reference a declaration that was exported using 'export type'.",
    ));
    // The TS1377 "was exported here" cross-file related-info is attached.
    var saw_1377 = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.import_alias_references_export_type) continue;
        for (d.related) |rel| {
            if (rel.code == TsCodes.name_was_exported_here and rel.file != null and
                std.mem.eql(u8, rel.message, "'Foo' was exported here.")) saw_1377 = true;
        }
    }
    try T.expect(saw_1377);
}

test "checker: TS1362 fires for a normally-imported name exported type-only by its module, used as a value" {
    const s = try newSetup(
        \\import { Foo } from "./b";
        \\Foo;
    );
    defer destroySetup(s);
    var stub = CrossModuleStubResolver{ .canned_module_name = "\"b\"", .exported_name = "Foo", .exported_type = false, .type_only_export = true };
    try runCrossModuleCheck(s, &stub);
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.type_only_export_used_as_value,
        "'Foo' cannot be used as a value because it was exported using 'export type'.",
    ));
}

test "checker: ambiguous type-only export specifiers publish aliases without TS2661" {
    const b = try newBoundSetup(
        \\// @filename: /imports.ts
        \\import { type, as, something, foo, bar } from "./exports.js";
        \\type;
        \\as;
        \\something;
        \\foo;
        \\bar;
        \\// @filename: /exports.ts
        \\const type = 0;
        \\const as = 0;
        \\const something = 0;
        \\export { type };
        \\export { type as };
        \\export { type something };
        \\export { type type as foo };
        \\export { type as as bar };
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);

    try T.expectEqual(@as(usize, 4), checkerCountCode(b.base, TsCodes.type_only_export_used_as_value));
    try T.expectEqual(@as(usize, 0), checkerCountCode(b.base, TsCodes.export_non_local_declaration));
    try T.expectEqual(@as(usize, 0), checkerCountCode(b.base, TsCodes.no_exported_member));
}

