test "checker: property incompatible with index signature carries TS2530 chain detail" {
    const b = try newBoundSetup(
        \\const t: { [k: string]: number } = { a: "x" };
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    var saw_2322 = false;
    var saw_2530 = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_assignable) saw_2322 = true;
        for (d.chain) |entry| {
            if (entry.code == TsCodes.property_incompatible_with_index) saw_2530 = true;
        }
    }
    try T.expect(saw_2322);
    try T.expect(saw_2530);
}

