test "checker: TS2527 reports inferred class members with inaccessible this type" {
    const b = try newBoundSetup(
        \\class C {
        \\  x1 = { a: this };
        \\  x2 = [this];
        \\  x3 = [{ a: this }];
        \\  x4 = () => this;
        \\  f1() { return { a: this }; }
        \\  f2() { return [this]; }
        \\  f3() { return [{ a: this }]; }
        \\  f4() { return () => this; }
        \\}
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .declaration = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expectEqual(@as(usize, 4), checkerCountCode(b.base, TsCodes.inferred_type_inaccessible_type));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.inferred_type_inaccessible_type, "The inferred type of 'x1' references an inaccessible 'this' type. A type annotation is necessary."));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.inferred_type_inaccessible_type, "The inferred type of 'x3' references an inaccessible 'this' type. A type annotation is necessary."));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.inferred_type_inaccessible_type, "The inferred type of 'f1' references an inaccessible 'this' type. A type annotation is necessary."));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.inferred_type_inaccessible_type, "The inferred type of 'f3' references an inaccessible 'this' type. A type annotation is necessary."));
}

