test "checker: TS5088 reports inferred declaration return through recursive conditional alias" {
    const b = try newBoundSetup(
        \\type BadFlatArray<Arr, Depth extends number> = { obj: {
        \\  "done": Arr,
        \\  "recur": Arr extends any
        \\    ? BadFlatArray<Arr, [-1, 0, 1][Depth]>
        \\    : Arr
        \\}[Depth extends -1 ? "done" : "recur"] }["obj"];
        \\declare function flat<A, D extends number = 1>(
        \\  arr: A,
        \\  depth?: D
        \\): BadFlatArray<A, D>[];
        \\function foo<T>(arr: T[], depth: number) {
        \\  return flat(arr, depth);
        \\}
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .declaration = true, .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.inferred_type_cyclic_structure, "The inferred type of 'foo' references a type with a cyclic structure which cannot be trivially serialized. A type annotation is necessary."));
}

