test "checker: no declaration-emit privacy family fires when declaration emit is off" {
    const b = try newBoundSetup(
        \\class PrivateThing {}
        \\export class Box {
        \\  contents: PrivateThing;
        \\  make(thing: PrivateThing): PrivateThing { return thing; }
        \\}
        \\export function f(thing: PrivateThing): PrivateThing { return thing; }
        \\export type Alias = PrivateThing;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.public_property_private_name));
    try T.expect(!checkerHasCode(b, TsCodes.public_method_return_private_name));
    try T.expect(!checkerHasCode(b, TsCodes.public_method_param_private_name));
    try T.expect(!checkerHasCode(b, TsCodes.exported_function_return_private_name));
    try T.expect(!checkerHasCode(b, TsCodes.exported_function_param_private_name));
    try T.expect(!checkerHasCode(b, TsCodes.exported_type_alias_private_name));
}

fn checkerCountCode(s: *TestSetup, code: u32) usize {
    var count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == code) count += 1;
    }
    return count;
}

test "checker: TS2871 fires for `null ?? 1` (left operand always nullish)" {
    // Positive. Mirrors predicateSemantics.ts `const p03 = null ?? 1;`
    // The left operand is the `null` literal ÃÂ¢ÃÂÃÂ always nullish ÃÂ¢ÃÂÃÂ so tsc
    // emits TS2871 at the left operand.
    const s = try newSetup(
        \\const p03 = null ?? 1;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.always_nullish));
}

test "checker: TS2871 fires for `undefined ?? x` (undefined literal always nullish)" {
    // Positive. The `undefined` keyword lowers to a literal-undefined
    // node which is always nullish.
    const s = try newSetup(
        \\const v = undefined ?? 1;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
