test "checker: TS2871 fires twice for chained `null ?? null ?? null`" {
    // Positive. Mirrors predicateSemantics.ts `const p07 = null ?? null ?? null;`
    // Parses left-associative as `(null ?? null) ?? null`. The inner `??`
    // left operand `null` is always nullish (1), and the outer `??` left
    // operand `(null ?? null)` is a nullish-coalescing whose right operand
    // `null` is always nullish, so it too is always nullish (2).
    const s = try newSetup(
        \\const p07 = null ?? null ?? null;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.always_nullish));
}

test "checker: TS2871 fires for a conditional with both branches nullish" {
    // Positive. Mirrors predicateSemantics.ts
    // `const test2 = (opt ? undefined : null) ?? "always reached";`
    // Both branches of the conditional are nullish literals, so the
    // conditional is always nullish.
    const s = try newSetup(
        \\declare let opt: number | undefined;
        \\const test2 = (opt ? undefined : null) ?? "always reached";
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.always_nullish));
}

test "checker: TS2871 does not fire for a sometimes-nullish left operand" {
    // Negative. Mirrors predicateSemantics.ts
    // `const test1 = (opt ? undefined : 32) ?? "possibly reached";`
    // One branch is non-nullish so the conditional is only sometimes
    // nullish ÃÂ¢ÃÂÃÂ valid `??` usage, no TS2871 (and no TS2869 either).
    const s = try newSetup(
        \\declare let opt: number | undefined;
        \\const test1 = (opt ? undefined : 32) ?? "possibly reached";
    );
    defer destroySetup(s);
