test "checker: export = under module=system emits TS1218" {
    // Mirrors `systemExportAssignment2(target=es5).errors.txt`:
    //
    //     // @module: system
    //     var a = 10;
    //     export = a;
    //
    // tsc anchors TS1218 at the `export` keyword of the assignment.
    // Upstream gate: `moduleKind === ModuleKind.System && !ambient`.
    // ESM-target (TS1203) and System (TS1218) are mutually exclusive
    // in the same `checkExportAssignmentExclusivity` loop.
    const source =
        \\// @module: system
        \\var a = 10;
        \\export = a;
    ;
    const s = try newSetup(source);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == 1218 and
            std.mem.indexOf(u8, d.message, "Export assignment is not supported when '--module' flag is 'system'") != null)
        {
            found = true;
        }
    }
    try T.expect(found);
}

