}

test "checker: TS1280 for an instantiated namespace in a global script under isolatedModules" {
    // Mirrors isolatedModulesGlobalNamespacesAndEnums: a top-level
    // instantiated (value) namespace in a global script file is
    // disallowed under isolatedModules. Type-only and ambient
    // namespaces are exempt; the file must be a script (no top-level
    // import/export).
    const b = try newBoundSetup(
        \\// @isolatedModules: true
        \\namespace Instantiated {
        \\  export const x = 1;
        \\}
        \\namespace Uninstantiated {
        \\  export type T = number;
        \\}
        \\declare namespace Ambient {
        \\  export const x: number;
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    var count: u32 = 0;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.namespaces_not_allowed_in_script) {
            count += 1;
            try T.expectEqualStrings("Namespaces are not allowed in global script files when 'isolatedModules' is enabled. If this file is not intended to be a global script, set 'moduleDetection' to 'force' or add an empty 'export {}' statement.", d.message);
        }
    }
    try T.expectEqual(@as(u32, 1), count);
}

