test "checker: TS2677 defers for a generic predicate type (Extract)" {
    // `node is Extract<Node, { kind: K }>` is generic (free K); tsc accepts it
    // via the constraint (Extract<T,U> is a subtype of T), so home must not
    // false-positive a not-assignable error. Mirrors trackedSymbolsNoCrash.
    const s = try newSetup(
        \\interface A { kind: "a"; }
        \\interface B { kind: "b"; }
        \\type Node = A | B;
        \\const isNodeOfKind =
        \\  <K extends Node["kind"]>(kind: K) =>
        \\  (node: Node | null | undefined): node is Extract<Node, { kind: K }> =>
        \\    node?.kind === kind;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.type_predicate_type_not_assignable));
}

test "checker: generic Extract argument diagnostics preserve symbolic source" {
    const s = try newSetup(
        \\type Foo = { foo: string };
        \\type Bar = { bar: string };
        \\declare function fooBar(x: { foo: string, bar: string }): void;
        \\declare function fooBat(x: { foo: string, bat: string }): void;
        \\type Extract2<T, U, V> = T extends U ? T extends V ? T : never : never;
        \\function f<T>(x: Extract<Extract<T, Foo>, Bar>, y: Extract<T, Foo & Bar>, z: Extract2<T, Foo, Bar>) {
        \\  fooBar(x);
        \\  fooBar(y);
        \\  fooBar(z);
        \\  fooBat(x);
        \\  fooBat(y);
        \\  fooBat(z);
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var saw_nested = false;
    var saw_intersection = false;
    var saw_alias = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.argument_type_mismatch) continue;
        try T.expect(std.mem.indexOf(u8, d.message, "parameter of type '{ foo: string; bar: string; }'") == null);
        if (std.mem.eql(u8, d.message, "Argument of type 'Extract<Extract<T, Foo>, Bar>' is not assignable to parameter of type '{ foo: string; bat: string; }'.")) {
            saw_nested = true;
        }
        if (std.mem.eql(u8, d.message, "Argument of type 'Extract<T, Foo & Bar>' is not assignable to parameter of type '{ foo: string; bat: string; }'.")) {
            saw_intersection = true;
        }
        if (std.mem.eql(u8, d.message, "Argument of type 'Extract2<T, Foo, Bar>' is not assignable to parameter of type '{ foo: string; bat: string; }'.")) {
            saw_alias = true;
        }
    }
    try T.expect(saw_nested);
    try T.expect(saw_intersection);
    try T.expect(saw_alias);
}

test "checker: conditional alias callback parameter infers through matching branch" {
    const s = try newSetup(
        \\declare function ff(x: Foo3<string>): void;
        \\declare function gg<T>(f: (x: Foo3<T>) => void): void;
        \\type Foo3<T> = T extends number ? { n: T } : { x: T };
        \\gg(ff);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
