}

test "checker: TS2473 fires when merged enum declarations disagree on const" {
    // Mirrors upstream `checkEnumDeclaration`: a `const enum` merged
    // with a non-const `enum` of the same name must be flagged. The
    // later (differing) declaration is anchored.
    const s = try newSetup(
        \\const enum E { A }
        \\enum E { B }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.enum_declarations_const_mismatch));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.enum_declarations_const_mismatch) {
            try T.expectEqualStrings("Enum declarations must all be const or non-const.", d.message);
        }
    }
}

test "checker: TS2432 fires when two merged enum decls both auto first member" {
    // Both `enum E { A }` and `enum E { B }` would auto-default
    // their first member to 0 - a value collision. The second decl
    // (and any subsequent) is flagged at its first member name.
    const s = try newSetup(
        \\enum E { A }
        \\enum E { B }
        \\enum E { C }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    // 2 subsequent decls (B and C) each fire TS2432.
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.merged_enum_multiple_auto_first));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.merged_enum_multiple_auto_first) {
            try T.expectEqualStrings(
                "In an enum with multiple declarations, only one declaration can omit an initializer for its first enum element.",
                d.message,
            );
        }
    }
}

test "checker: TS2432 does not merge same-named enums across virtual file sections" {
    // `enum require` in two distinct @filename sections are SEPARATE symbols
    // (different modules/scripts); neither should fire TS2432. Mirrors
    // collisionExportsRequireAndEnum.ts (globalFile vs externalmodule).
    const s = try newSetup(
        \\// @filename: a.ts
        \\enum require { _v1, _v2 }
        \\// @filename: b.ts
        \\enum require { _v1, _v2 }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.merged_enum_multiple_auto_first));
}

test "checker: TS2432 does not merge same-named enums across local scopes" {
    const s = try newSetup(
        \\function f() { enum E { A } return E.A; }
        \\function g() { enum E { A } return E.A; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.merged_enum_multiple_auto_first));
}

test "checker: TS2432 merges enum decls across separate same-name namespace blocks" {
    // `M1.E1` is declared in three SEPARATE `namespace M1 {}` blocks. The
    // first decl initializes its first member; the next two omit it. Only
    // ONE declaration may omit the first initializer, so the THIRD decl (the
    // second omitter) fires TS2432. Keying the merge tracker on the literal
    // parent block missed this (each `namespace M1` is a distinct node);
    // keying on the qualified name `M1.E1` catches it. Mirrors
    // `enumMergingErrors` (M1 block). Sibling `M2.E1` must NOT conflate.
    const s = try newSetup(
        \\namespace M1 { export enum E1 { A = 0 } }
        \\namespace M1 { export enum E1 { B } }
        \\namespace M1 { export enum E1 { C } }
        \\namespace M2 { export enum E1 { A } }
        \\namespace M2 { export enum E1 { B = 0 } }
        \\namespace M2 { export enum E1 { C } }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    // M1: decl2 (B) is the allowed omitter, decl3 (C) errors → 1.
    // M2: decl1 (A) is the allowed omitter, decl3 (C) errors → 1.
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.merged_enum_multiple_auto_first));
}

test "checker: enum declarations only merge with namespaces or other enums" {
    const s = try newSetup(
        \\enum e1111 { One }
        \\var e1111 = 1;
        \\enum e2 { One }
        \\function e2() { }
        \\enum e3 { One }
        \\var e3 = () => { };
        \\enum e4 { One }
        \\class e4 { public foo() { } }
        \\enum e5 { One }
        \\namespace e5 { }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 8), checkerCountCode(s, TsCodes.enum_declarations_can_only_merge_with_namespace_or_other_enum));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.enum_declarations_can_only_merge_with_namespace_or_other_enum) {
            try T.expectEqualStrings(
                "Enum declarations can only merge with namespace or other enum declarations.",
                d.message,
            );
        }
    }
}

test "checker: merged enum declarations reject duplicate member names" {
    const s = try newSetup(
        \\enum E { One }
