test "checker: TS2322 elaborates differing type argument for generic instances" {
    // `List<number> = List<string>` errors; tsc nests
    // "Type 'string' is not assignable to type 'number'." under the
    // header. Verify the chain entry is attached (CLI rendering of
    // chains is separate; we inspect the diagnostic directly).
    const s = try newSetup(
        \\class List<T> { data: T = undefined as any; }
        \\let a: List<number> = new List<string>();
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found_chain = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        for (d.chain) |entry| {
            if (std.mem.indexOf(u8, entry.message, "Type 'string' is not assignable to type 'number'.") != null) found_chain = true;
        }
    }
    try T.expect(found_chain);
}

test "checker: generic class instance renders type args in TS2322 message" {
    // `new List<number>()` must render as 'List<number>' (not bare
    // 'List') in assignability diagnostics, matching tsc. Mirrors
    // objectTypeWithRecursiveWrappedProperty.errors.txt header.
    const s = try newSetup(
        \\class List<T> { data: T = undefined as any; }
        \\const x: number = new List<number>();
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_assignable and std.mem.indexOf(u8, d.message, "List<number>") != null) found = true;
        // must NOT render the bare class name
        try T.expect(std.mem.indexOf(u8, d.message, "Type 'List' is not assignable") == null);
    }
    try T.expect(found);
}

test "checker: generic constructor inference instantiates private class members" {
    const s = try newSetup(
        \\class C<T> {
        \\  #foo: T;
        \\  constructor(value: T) { this.#foo = value; }
        \\  set baz(value: T) { this.#foo = value; }
        \\  get baz(): T { return this.#foo; }
        \\}
        \\let a = new C(3);
        \\let b = new C("hello");
        \\a.baz = 5;
        \\a = b;
        \\b = a;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.arbitrary_type_parameter_instantiation_unrelated));
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.type_not_assignable));
    var saw_string_to_number = false;
    var saw_number_to_string = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        if (std.mem.indexOf(u8, d.message, "Type 'C<string>' is not assignable to type 'C<number>'.") != null) saw_string_to_number = true;
        if (std.mem.indexOf(u8, d.message, "Type 'C<number>' is not assignable to type 'C<string>'.") != null) saw_number_to_string = true;
    }
    try T.expect(saw_string_to_number);
    try T.expect(saw_number_to_string);
}

test "checker: recovered private indexed access keeps implicit-any and missing-property diagnostics" {
    const s = try newSetup(
        \\class C {
        \\  #bar = 3;
        \\  constructor() {
        \\    const badForNow: C[#bar] = 3;
        \\    const badAlways: C["#bar"] = 3;
        \\  }
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.variable_implicitly_any));
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.property_does_not_exist));
    try T.expect(hasDiagnosticCodeMessage(s, TsCodes.variable_implicitly_any, "Variable '#bar' implicitly has an 'any' type."));
    try T.expect(hasDiagnosticCodeMessage(s, TsCodes.property_does_not_exist, "Property '#bar' does not exist on type 'C'."));
}

