test "checker: TS2506 for direct and indirect circular base classes" {
    // `class C extends C` (direct) and `a extends b; b extends a`
    // (indirect) both reference themselves in their own base
    // expression → TS2506 at each cycle member's name. Generic
    // heritage (`C<T>`) must also terminate rather than re-entering
    // class checking through the type-reference lowerer.
    const s = try newSetup(
        \\class C extends C {}
        \\class a extends b {}
        \\class b extends a {}
        \\class C2<T> extends E2<T> {}
        \\class D2<T> extends C2<T> {}
        \\class E2<T> extends D2<T> {}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 6), checkerCountCode(s, TsCodes.circular_base_expression));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.circular_base_expression) {
            try T.expect(std.mem.indexOf(u8, d.message, "referenced directly or indirectly in its own base expression") != null);
        }
    }
}

test "checker: TS2506 does NOT fire for a normal class hierarchy" {
