test "checker: TS1334 fires for unique symbol on for-of/for-in loop binding" {
    // `unique symbol` is only allowed on a variable in a plain
    // variable statement; a loop binding is a variable declaration
    // NOT in a variable statement → TS1334.
    const s = try newSetup(
        \\declare const arr: any[];
        \\for (const x: unique symbol of arr) {}
        \\for (const y: unique symbol in arr) {}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.unique_symbol_only_on_variable_statement));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.unique_symbol_only_on_variable_statement) {
            try T.expectEqualStrings("'unique symbol' types are only allowed on variables in a variable statement.", d.message);
        }
    }
}

test "checker: TS1335 fires for unique symbol in parameter and return type" {
    // `unique symbol` is only allowed on variable/property/property-
