        \\function f(x: unique symbol): void {}
        \\function g(): unique symbol { return Symbol(); }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.unique_symbol_not_allowed_here));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.unique_symbol_not_allowed_here) {
            try T.expectEqualStrings("'unique symbol' types are not allowed here.", d.message);
        }
    }
}

test "checker: TS1335 does NOT fire for unique symbol on const variable" {
    // The legal position — a `const` variable in a variable statement —
    // must stay clean (no TS1335).
    const s = try newSetup(
