test "checker: TS1335 fires for unique symbol in all disallowed grammar positions" {
    // tsc's checkGrammarUniqueSymbolType: anywhere other than a
    // variable/property/property-signature type is TS1335 — `this` param,
    // rest param array element, type-predicate, type-parameter constraint
    // and default, a type argument, and a union member. Mirrors
    // uniqueSymbolsErrors.
    const s = try newSetup(
        \\declare function a(this: unique symbol): void;
        \\declare function b(...r: (unique symbol)[]): void;
        \\declare function c(n: any): n is unique symbol;
        \\declare function d<T extends unique symbol>(): void;
        \\declare function e<T = unique symbol>(): void;
        \\declare let g: Array<unique symbol>;
        \\declare let h: unique symbol | string;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 7), checkerCountCode(s, TsCodes.unique_symbol_not_allowed_here));
}

