test "checker: TS1332 fires for let/var with unique symbol type" {
    // `unique symbol` denotes a single fresh symbol value - the only
    // legal binding form is `const`. Both `let` and `var` trip TS1332.
    const s = try newSetup(
        \\let bad1: unique symbol = Symbol();
        \\var bad2: unique symbol = Symbol();
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.unique_symbol_var_must_be_const));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.unique_symbol_var_must_be_const) {
            try T.expectEqualStrings("A variable whose type is a 'unique symbol' type must be 'const'.", d.message);
        }
    }
}

