test "checker: commentsAfterSpread reproducer does not stack-overflow" {
    // Repro from `tests/cases/compiler/commentsAfterSpread.ts`. A
    // self-referential destructuring binding (`const [a, b] = [...args]`,
    // `const { ...rest } = rest`) recursed `typeOfIdentifier ->
    // resolveValueDeclInStmt -> typeOfPatternBindingFromSource ->
    // checkExpression -> typeOfIdentifier` until the stack overflowed
    // (SIGABRT). The `pattern_binding_source_in_progress` cycle guard
    // must break it. We assert termination (no crash).
    const s = try newSetup(
        \\function e(...args: any[]) {
        \\    const [ea, eb] = [...args];
        \\    return args.length;
        \\}
        \\function k({ first, ...rest }: any) {
        \\    const { ka, kb, ...remaining } = rest;
        \\    return remaining;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
}

test "checker: reservedNameOnInterfaceImport reproducer terminates" {
    // Repro from `tests/cases/compiler/reservedNameOnInterfaceImport.ts`.
    // `import string = test.istring` aliases the reserved `string`
    // name to a namespace-local type; resolving whether the import
    // creates a runtime value loops back to the same import through
    // `importEqualsTargetDecl -> findNamedValueDeclInNamespace ->
    // declCreatesRuntimeValue` (which resets numeric depth to 0). The
    // `import_equals_runtime_in_progress` cycle guard must break it.
    // We assert termination (the call returns at all) rather than a
    // specific diagnostic shape.
    const s = try newSetup(
        \\declare namespace test {
        \\    interface istring { }
        \\    import string = test.istring;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
}

test "checker: circularBaseConstraint reproducer terminates" {
    // Repro from microsoft/TypeScript#54610 (`tests/cases/compiler/
    // circularBaseConstraint.ts`). The recursive conditional `B<T>`
    // expands to `B<T[key]>` and would loop without the depth/count
    // guard. We only assert termination (i.e. that the call returns
    // at all); the specific diagnostic shape isn't pinned here so
    // future legitimate expansions don't fight this test.
    const s = try newSetup(
        \\type A<T> = T;
        \\type B<T> = T extends any[]
        \\    ? never
        \\    : A<T> extends infer key
        \\    ? key extends keyof T
        \\        ? B<T[key]>
        \\        : never
        \\    : never;
        \\function foo<T>() {
        \\    "" as B<T>;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expect(true);
}

test "checker: tailRecursiveConditionalTypes Trim terminates" {
    // Excerpt from `tests/cases/compiler/tailRecursiveConditionalTypes.ts`.
    // `Trim<S>` recursively strips leading/trailing spaces from a
    // template-literal type via `${infer T}` patterns. Without
    // tail-recursion handling (or the existing depth/count guard)
    // the long-string input would blow the stack.
    const s = try newSetup(
        \\type Trim<S extends string> =
        \\    S extends ` ${infer T}` ? Trim<T> :
        \\    S extends `${infer T} ` ? Trim<T> :
        \\    S;
        \\type T10 = Trim<'                                                          hello '>;
        \\type T11 = Trim<' hello                                                          '>;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expect(true);
}

test "checker: tailRecursiveConditionalTypes TupleOf terminates" {
    // Tail-recursive `TupleOf<T, N>` builds a tuple of N elements;
    // termination requires the depth/count guard to bail before the
    // checker exhausts the stack.
    const s = try newSetup(
        \\type TupleOf<T, N extends number> = number extends N ? T[] : TupleOfRec<T, N, []>;
        \\type TupleOfRec<T, N extends number, Acc extends unknown[]> =
        \\    Acc["length"] extends N ? Acc : TupleOfRec<T, N, [T, ...Acc]>;
        \\type T40 = TupleOf<any, 200>;
        \\type T41 = TupleOf<any, number>;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expect(true);
}

