test "checker: String.prototype precision batch — position/concat/fromIndex shapes" {
    // Upstream-shape fixes batched into lib.zig stringProto:
    //   - includes / startsWith / endsWith accept optional position
    //   - indexOf accepts optional fromIndex
    //   - concat accepts rest varargs (...strs: string[])
    const s = try newSetup(
        \\const t: string = "hello world";
        \\const a = t.includes("o", 5);            // optional position
        \\const b = t.startsWith("hello", 0);       // optional position
        \\const c = t.endsWith("world", 11);        // optional position
        \\const d = t.indexOf("o", 5);              // optional fromIndex
        \\const e = t.concat(" ", "foo", " ", "bar"); // rest varargs
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
        try T.expect(d.code != TsCodes.argument_type_mismatch);
        try T.expect(d.code != 2554);
    }
}

test "checker: Array.prototype precision batch — fromIndex/optional/concat shapes" {
    // Pins the upstream-shape fixes batched into lib.zig:
    //   - indexOf / includes accept optional `fromIndex`
    //   - join() / sort() may be called with no args
    //   - concat accepts both single values and arrays via varargs
    // Each call should produce zero arity-mismatch or assignability
    // errors.
    const s = try newSetup(
        \\const a: number[] = [1, 2, 3];
        \\const i = a.indexOf(2, 1);          // optional fromIndex
        \\const j = a.includes(3, 0);          // optional fromIndex
        \\const s1 = a.join();                  // optional separator
        \\const s2 = a.join(",");
        \\const sorted = a.sort();             // optional comparator
        \\const c1 = a.concat(4, 5);            // single-value varargs
        \\const c2 = a.concat([4, 5], 6);       // mixed array+value
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
        try T.expect(d.code != TsCodes.argument_type_mismatch);
        // TS2554 — wrong number of arguments
        try T.expect(d.code != 2554);
    }
}

test "checker: Array.prototype.sort comparator contextually types both elements" {
    const s = try newSetup(
        \\interface IOptions {
        \\  name?: string;
        \\}
        \\class parser {
        \\  public options: IOptions[];
        \\  public m() {
        \\    this.options = this.options.sort(function(a, b) {
        \\      var aName = a.name.toLowerCase();
        \\      var bName = b.name.toLowerCase();
        \\      return aName > bName ? 1 : -1;
        \\    });
        \\  }
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{
        .strict_null_checks = true,
        .strict_property_initialization = true,
    });
    try s.checker.checkSourceFile(s.root);
    var saw_a_name = false;
    var saw_b_name = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.object_possibly_undefined_18048 and
            std.mem.indexOf(u8, d.message, "'a.name' is possibly 'undefined'.") != null)
            saw_a_name = true;
        if (d.code == TsCodes.object_possibly_undefined_18048 and
            std.mem.indexOf(u8, d.message, "'b.name' is possibly 'undefined'.") != null)
            saw_b_name = true;
    }
    try T.expect(saw_a_name);
    try T.expect(saw_b_name);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.object_possibly_undefined_18048));
}

test "checker: Array.prototype.flatMap accepts array-returning callback" {
    // Upstream `flatMap<U>(cb: (value: T) => U | readonly U[]): U[]`
    // — the callback may return either a single value or an array of
    // values. Before the precision fix our shape was `(value: T) => U`,
    // which rejected the common `xs.flatMap(x => [a, b])` shape with
    // TS2322. Pinning the array-returning shape here so a regression
    // in the lib surface is caught immediately.
    const s = try newSetup(
        \\const a: number[] = [1, 2, 3];
        \\const b: number[] = a.flatMap(x => [x, x * 2]);
        \\const c: number[] = a.flatMap(x => x + 1);
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    // No TS2322 / TS2345 should fire on either flatMap call.
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.type_not_assignable);
        try T.expect(d.code != TsCodes.argument_type_mismatch);
    }
}

test "checker: recursiveConditionalTypes Flatten terminates" {
    // From `tests/cases/compiler/recursiveConditionalTypes.ts`. The
    // `_Flatten<T>` alias recurses through `infer U` extraction; the
    // `InfiniteArray<T> = InfiniteArray<T>[]` pair pushes the
    // expander into an infinite loop without guards.
    const s = try newSetup(
        \\type Flatten<T extends readonly unknown[]> = T extends unknown[] ? _Flatten<T>[] : readonly _Flatten<T>[];
        \\type _Flatten<T> = T extends readonly (infer U)[] ? _Flatten<U> : T;
        \\type InfiniteArray<T> = InfiniteArray<T>[];
        \\type B0 = Flatten<string[][][]>;
        \\type B2 = Flatten<InfiniteArray<string>>;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expect(true);
}

test "checker: TS2709 does NOT fire when name resolves to a type" {
