test "checker: TS2476 fires for const enum dynamic element access" {
    // `E[dynamicKey]` on a const enum can't be inlined at emit time,
    // so upstream rejects with TS2476. Only string-literal element
    // access (`E["A"]`) and identifier access (`E.A`) are allowed.
    const s = try newSetup(
        \\const enum E { A = 1, B = 2 }
        \\let key = "A";
        \\let bad1 = E[key];
        \\let bad2 = E[0];
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, 2476));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == 2476) {
            try T.expectEqualStrings(
                "A const enum member can only be accessed using a string literal.",
                d.message,
            );
        }
    }
}

test "checker: TS2476 does NOT fire for legal const enum access" {
