test "checker: TS1333 fires for unique-symbol with destructuring binding" {
    // Both object and array binding patterns annotated with
    // `unique symbol` trip TS1333. const + pattern fires TS1333
    // only (TS1332 doesn't apply to const). let + pattern fires
    // both TS1332 (const-ness) and TS1333 (binding-name).
    const s = try newSetup(
        \\const { x }: unique symbol = Symbol() as any;
        \\const [a]: unique symbol = Symbol() as any;
        \\let { y }: unique symbol = Symbol() as any;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 3), checkerCountCode(s, TsCodes.unique_symbol_binding_pattern));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.unique_symbol_binding_pattern) {
            try T.expectEqualStrings(
                "'unique symbol' types may not be used on a variable declaration with a binding name.",
                d.message,
            );
        }
    }
    // `let { y }: unique symbol` also fires TS1332 (1x).
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.unique_symbol_var_must_be_const));
}

