test "checker: TS1355 fires for invalid 'as const' operands" {
    // Binary ops, calls, plain identifiers (non-enum), and other
    // compound expression shapes are invalid `as const` operands.
    const s = try newSetup(
        \\let a = (1 + 1) as const;
        \\function f() { return 1; }
        \\let b = f() as const;
        \\let x = 5;
        \\let c = x as const;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var ts1355: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == 1355) {
            ts1355 += 1;
            try T.expectEqualStrings(
                "A 'const' assertions can only be applied to references to enum members, or string, number, boolean, array, or object literals.",
                d.message,
            );
        }
    }
    // 3 invalid operands: binary, call, identifier
    try T.expectEqual(@as(usize, 3), ts1355);
}

