test "checker: TS1165 fires for ambient class computed key (declare class)" {
    // `declare class` makes the body ambient; computed keys whose
    // type isn't a literal/unique symbol get the ambient-context
    // wording (TS1165), not the standard TS1166.
    const s = try newSetup(
        \\let unknown_key: string;
        \\declare class C {
        \\    [unknown_key + ""]: number;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var ts1165: usize = 0;
    var ts1166: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == 1165) {
            ts1165 += 1;
            try T.expectEqualStrings(
                "A computed property name in an ambient context must refer to an expression whose type is a literal type or a 'unique symbol' type.",
                d.message,
            );
        }
        if (d.code == 1166) ts1166 += 1;
    }
    try T.expect(ts1165 >= 1);
    try T.expectEqual(@as(usize, 0), ts1166);
}

test "checker: computed method overload dynamic key emits TS1168" {
