    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.computed_property_name_method_overload and
            std.mem.eql(u8, d.message, "A computed property name in a method overload must refer to an expression whose type is a literal type or a 'unique symbol' type."))
        {
            found = true;
        }
    }
    try T.expect(found);
}

