test "checker: TS2447 fires for bitwise | suggesting || and ^ suggesting !==" {
    const s = try newSetup(
        \\declare const a: boolean;
        \\declare const b: boolean;
        \\const c = a | b;
        \\const d = a ^ b;
    );
