    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.bitwise_operator_not_allowed_for_boolean));
    var saw_or = false;
    var saw_xor = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.bitwise_operator_not_allowed_for_boolean) continue;
        if (std.mem.indexOf(u8, d.message, "'|' operator") != null and std.mem.indexOf(u8, d.message, "'||' instead") != null) saw_or = true;
        if (std.mem.indexOf(u8, d.message, "'^' operator") != null and std.mem.indexOf(u8, d.message, "'!==' instead") != null) saw_xor = true;
    }
    try T.expect(saw_or);
    try T.expect(saw_xor);
}

