test "checker: TS6807 suggests simplifying shifts with large numeric counts" {
    const s = try newSetup(
        \\const value = 1;
        \\const a = value << 33;
        \\let b = value;
        \\b >>>= 64;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.shift_count_simplifiable));
    var saw_left = false;
    var saw_assign = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.shift_count_simplifiable) continue;
        try T.expectEqual(Diagnostic.Category.suggestion, d.category);
        if (std.mem.eql(u8, d.message, "This operation can be simplified. This shift is identical to `value << 1`.")) saw_left = true;
        if (std.mem.eql(u8, d.message, "This operation can be simplified. This shift is identical to `b >>> 0`.")) saw_assign = true;
    }
    try T.expect(saw_left);
    try T.expect(saw_assign);
}

