test "checker: TS2459 fires when importing a name declared locally but not exported" {
    // Mirrors `importNonExportedMember2.ts`: `./a` declares `Foo`
    // locally but never exports it; importing `{ Foo }` is TS2459.
    const s = try newSetup(
        \\// @filename: a.ts
        \\class Foo {}
        \\export const x = 1;
        \\// @filename: b.ts
        \\import { Foo } from "./a";
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.module_declares_locally_not_exported));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.module_declares_locally_not_exported) {
            try T.expectEqualStrings("Module '\"./a\"' declares 'Foo' locally, but it is not exported.", d.message);
        }
    }
}

test "checker: TS2460 fires when importing a name exported under a different name" {
