}

test "checker: TS1269 fires for export import of a cross-file type-only namespace" {
    // Mirrors `isolatedModulesExportImportUninstantiatedNamespace.ts`:
    // `./jsx` declares a namespace containing only type aliases (no
    // runtime value); re-aliasing it via `export import JSX = JSXInternal`
    // under `isolatedModules` is TS1269.
    const s = try newSetup(
        \\// @isolatedModules: true
        \\// @filename: jsx.ts
        \\export namespace JSXInternal {
        \\  export type HTMLAttributes = string
        \\  export type ComponentChildren = string
        \\}
        \\// @filename: factory.ts
        \\import { JSXInternal } from "./jsx"
        \\export import JSX = JSXInternal;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.export_import_on_type_isolated));
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.export_import_on_type_isolated) {
            try T.expectEqualStrings(
                "Cannot use 'export import' on a type or type-only namespace when 'isolatedModules' is enabled.",
                d.message,
            );
        }
    }
}

