test "checker: TS2744 fires for a self-referencing default and detects circular default" {
    // `<T = T>` — the default references the parameter itself, which is
    // both a later (== current) reference (TS2744) and circular (TS2716).
    const s = try newSetup(
        \\function f<T = T>(x: T): void {}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found_2744: usize = 0;
    var found_2716: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_param_default_references_later) found_2744 += 1;
        if (d.code == TsCodes.type_param_circular_default) found_2716 += 1;
    }
    try T.expectEqual(@as(usize, 1), found_2744);
    try T.expectEqual(@as(usize, 1), found_2716);
}

test "checker: TS2744 stays silent when a default references an earlier parameter" {
