test "checker: TS2716 fires for a mutually circular default chain" {
    // `<T = U, U = T>` — T's default references U, whose default
    // references T: a transitive circular default for both.
    const s = try newSetup(
        \\type X<T = U, U = T> = [T, U];
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found: usize = 0;
    for (s.checker.diagnostics.items) |d| {
