            found += 1;
            try T.expect(std.mem.indexOf(u8, d.message, "has a circular default.") != null);
        }
    }
    // Both T and U participate in the cycle.
    try T.expectEqual(@as(usize, 2), found);
}

test "checker: circular type-parameter constraints carry TS2751 related info" {
    const s = try newSetup(
        \\interface Box<T extends U, U extends T> {}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found_primary: usize = 0;
    var found_related: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.circular_constraint) continue;
        found_primary += 1;
        for (d.related) |rel| {
            if (rel.code == TsCodes.circularity_originates_in_type and
                std.mem.eql(u8, rel.message, "Circularity originates in type at this location."))
            {
                found_related += 1;
            }
        }
    }
    try T.expectEqual(@as(usize, 2), found_primary);
    try T.expectEqual(@as(usize, 2), found_related);
}

