test "checker: TS2799 fires for oversized tuple type spread" {
    var source: std.ArrayListUnmanaged(u8) = .empty;
    defer source.deinit(T.allocator);
    try source.appendSlice(T.allocator, "type Huge = [...[");
    var i: usize = 0;
    while (i < 10_000) : (i += 1) {
        if (i > 0) try source.appendSlice(T.allocator, ", ");
        try source.appendSlice(T.allocator, "number");
    }
    try source.appendSlice(T.allocator, "]];");

    const s = try newSetup(source.items);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_tuple_too_large) {
            found += 1;
            try T.expect(std.mem.indexOf(u8, d.message, "tuple type that is too large") != null);
        }
    }
    try T.expectEqual(@as(usize, 1), found);
}

