        \\key = "abc";
        \\key = sym();
        \\key = 123n;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found_bigint_assign = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_assignable and
            std.mem.indexOf(u8, d.message, "Type 'bigint' is not assignable to type 'string | number | symbol'.") != null)
        {
            found_bigint_assign = true;
        }
        if (d.code == TsCodes.type_not_assignable and
            (std.mem.indexOf(u8, d.message, "Type 'number' is not assignable") != null or
                std.mem.indexOf(u8, d.message, "Type 'string' is not assignable") != null or
                std.mem.indexOf(u8, d.message, "Type 'symbol' is not assignable") != null))
        {
            return error.UnexpectedDiagnostic;
        }
    }
    try T.expect(found_bigint_assign);
}

