// =============================================================================
// Nested diagnostic elaboration (messageChain) — TS2326 / TS2327 / TS2634
// =============================================================================

/// Count the `DiagnosticChainEntry` slots (across all diagnostics, one
/// level deep) that carry `code`. The elaboration codes hang under a
/// parent TS2430 header rather than as standalone top-level diagnostics,
/// so `checkerCountCode` (which inspects top-level codes) never sees
/// them — this helper inspects the chain.
fn checkerCountChainCode(s: *TestSetup, code: u32) usize {
    var count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        for (d.chain) |entry| {
            if (entry.code == code) count += 1;
        }
    }
    return count;
}

/// Return the first chain entry with `code`, or null.
fn checkerFirstChainEntry(s: *TestSetup, code: u32) ?DiagnosticChainEntry {
    for (s.checker.diagnostics.items) |d| {
        for (d.chain) |entry| {
            if (entry.code == code) return entry;
        }
    }
    return null;
}

test "checker: TS2618 elaborates tuple source shorter than required target" {
    const s = try newSetup(
        \\let src: [number] = [1];
        \\let dst: [number, string] = src;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.type_not_assignable));
    try T.expectEqual(@as(usize, 1), checkerCountChainCode(s, TsCodes.source_tuple_too_short));
    try T.expectEqual(@as(usize, 0), checkerCountChainCode(s, TsCodes.source_tuple_too_long));
    const entry = checkerFirstChainEntry(s, TsCodes.source_tuple_too_short).?;
    try T.expectEqualStrings("Source has 1 element(s) but target requires 2.", entry.message);
}

