    const dst = hir_mod.varDeclOf(&s.hir, stmts[1]);
    const chain = try s.checker.buildAssignabilityElaborationChain(s.hir.typeOf(src.name), s.hir.typeOf(dst.name));
    try T.expectEqual(@as(usize, 1), chain.len);
    const entry = chain[0];
    try T.expectEqual(@as(u32, TsCodes.tuple_range_type_incompatible), entry.code);
    try T.expectEqualStrings("Type at positions 1 through 2 in source is not compatible with type at position 1 in target.", entry.message);
    try T.expectEqual(@as(usize, 1), entry.children.len);
    try T.expectEqual(@as(u32, TsCodes.type_not_assignable), entry.children[0].code);
    try T.expectEqualStrings("Type 'boolean' is not assignable to type 'number'.", entry.children[0].message);
}

