test "checker: TS2326 elaborates a property-type incompatibility under interface extends" {
    // A derived interface redeclares a base property with a value type
    // that does not assign to the base's. tsc emits the structural
    // TS2430 plus a nested TS2326 explaining the property types clash.
    // The elaboration is a messageChain entry under the TS2430 header,
    // not a standalone diagnostic.
    const s = try newSetup(
        \\interface Base { x: string; }
        \\interface Derived extends Base { x: number; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.interface_incorrectly_extends));
    try T.expectEqual(@as(usize, 1), checkerCountChainCode(s, TsCodes.types_of_property_incompatible));
    // The chain entry must hang under the TS2430 parent, not exist as a
    // top-level diagnostic.
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.types_of_property_incompatible));
    const entry = checkerFirstChainEntry(s, TsCodes.types_of_property_incompatible).?;
    try T.expectEqualStrings("Types of property 'x' are incompatible.", entry.message);
}

