test "checker: TS2692 elaborates wrapper objects assigned to primitives" {
    const s = try newSetup(
        \\let sObj: String = "" as any;
        \\let s: string = sObj;
        \\let nObj: Number = 0 as any;
        \\let n: number = nObj;
        \\let bObj: Boolean = true as any;
        \\let b: boolean = bObj;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 3), checkerCountCode(s, TsCodes.type_not_assignable));
    try T.expectEqual(@as(usize, 3), checkerCountChainCode(s, TsCodes.primitive_wrapper_prefer_primitive));
    var saw_wrapper_wording: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        for (d.chain) |entry| {
            if (entry.code != TsCodes.primitive_wrapper_prefer_primitive) continue;
            if (std.mem.indexOf(u8, entry.message, "is a primitive") != null and
                std.mem.indexOf(u8, entry.message, "is a wrapper object") != null and
                std.mem.indexOf(u8, entry.message, "Prefer using") != null)
            {
                saw_wrapper_wording += 1;
            }
        }
    }
    try T.expectEqual(@as(usize, 3), saw_wrapper_wording);
}

