test "checker: TS2430 header stays a single top-level diagnostic with the chain attached" {
    // The elaboration infra must be additive — exactly one TS2430
    // header line, with the elaboration nested as a chain entry rather
    // than over-counting as a second top-level diagnostic. This is the
    // header-count invariant the conformance harness depends on.
    const s = try newSetup(
        \\interface Base { x: string; }
        \\interface Derived extends Base { x: number; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var ts2430_count: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.interface_incorrectly_extends) {
            ts2430_count += 1;
            try T.expectEqual(@as(usize, 1), d.chain.len);
        }
    }
    try T.expectEqual(@as(usize, 1), ts2430_count);
}

// =============================================================================
// Main-relater elaboration (messageChain under TS2322) — TS2326 (with a
// nested TS2322 leaf) and TS2329. These hang under the structural
// `Type 'X' is not assignable to type 'Y'.` header and never appear as
// standalone diagnostic headers, so they're invisible to the header-only
// conformance comparison while matching tsc's `messageChain` flatten.
// =============================================================================

test "checker: TS2326 elaborates an incompatible same-named property under the main TS2322 relater" {
    // An object-to-object assignment (named type B into named type A)
    // where same-named property `x` has clashing value types. tsc nests
    // `Types of property 'x' are incompatible.` (TS2326) with the leaf
    // `Type 'number' is not assignable to type 'string'.` (TS2322) under
    // the structural `Type 'B' is not assignable to type 'A'.` header.
    const s = try newSetup(
        \\type A = { x: string; y: number };
        \\type B = { x: number; y: number };
        \\declare const b: B;
        \\const a: A = b;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    // Exactly one TS2322 header, carrying the elaboration as a chain.
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.type_not_assignable));
    try T.expectEqual(@as(usize, 1), checkerCountChainCode(s, TsCodes.types_of_property_incompatible));
    const entry = checkerFirstChainEntry(s, TsCodes.types_of_property_incompatible).?;
    try T.expectEqualStrings("Types of property 'x' are incompatible.", entry.message);
    // The TS2326 entry nests a TS2322 leaf naming the concrete clash.
    try T.expectEqual(@as(usize, 1), entry.children.len);
    try T.expectEqual(@as(u32, TsCodes.type_not_assignable), entry.children[0].code);
    try T.expectEqualStrings(
        "Type 'number' is not assignable to type 'string'.",
        entry.children[0].message,
    );
}

test "checker: TS2322 assignment elaborates nullable target and source unions" {
    // Mirrors elaboratedErrorsOnNullableTargets01.ts. The source-side
    // header keeps the full nullable union display; the target-side
    // header uses the failing non-nullish branch while preserving nested
    // nullish members. The chain explains the concrete failing branch or
    // source constituent.
    const s = try newSetup(
        \\declare let x: null | { foo: { bar: string | null } | undefined } | undefined;
        \\declare let y: { foo: { bar: number | undefined } };
        \\x = y;
        \\y = x;
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);

    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.type_not_assignable));
    var saw_target_union = false;
    var saw_source_union = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        if (std.mem.eql(u8, d.message, "Type '{ foo: { bar: number | undefined; }; }' is not assignable to type '{ foo: { bar: string | null; } | undefined; }'.")) {
            saw_target_union = true;
            try T.expectEqual(@as(usize, 1), d.chain.len);
            try T.expectEqual(@as(u32, TsCodes.types_of_path_incompatible), d.chain[0].code);
            try T.expectEqualStrings("The types of 'foo.bar' are incompatible between these types.", d.chain[0].message);
            try T.expectEqual(@as(usize, 1), d.chain[0].children.len);
            try T.expectEqualStrings("Type 'number | undefined' is not assignable to type 'string | null'.", d.chain[0].children[0].message);
            try T.expectEqual(@as(usize, 1), d.chain[0].children[0].children.len);
            try T.expectEqualStrings("Type 'undefined' is not assignable to type 'string | null'.", d.chain[0].children[0].children[0].message);
        }
        if (std.mem.eql(u8, d.message, "Type '{ foo: { bar: string | null; } | undefined; } | null | undefined' is not assignable to type '{ foo: { bar: number | undefined; }; }'.")) {
            saw_source_union = true;
            try T.expectEqual(@as(usize, 1), d.chain.len);
            try T.expectEqualStrings("Type 'undefined' is not assignable to type '{ foo: { bar: number | undefined; }; }'.", d.chain[0].message);
        }
    }
    try T.expect(saw_target_union);
    try T.expect(saw_source_union);
}

test "checker: TS2326 main-relater elaboration is never a standalone top-level header" {
    // Header-count invariant: the elaboration codes must hang under the
    // TS2322 parent, never appear as standalone top-level diagnostics
    // (which would over-count headers and regress the baseline).
    const s = try newSetup(
        \\type A = { x: string; y: number };
        \\type B = { x: number; y: number };
        \\declare const b: B;
        \\const a: A = b;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.types_of_property_incompatible);
        try T.expect(d.code != TsCodes.index_signature_missing);
    }
}

test "checker: TS2329 elaborates a missing target index signature under the main TS2322 relater" {
    // The target declares a string index signature the source lacks. tsc
    // nests `Index signature for type 'string' is missing in type '{...}'.`
    // (TS2329) under the structural TS2322 header.
    const s = try newSetup(
        \\type A = { [k: string]: number };
        \\type B = { a: number };
        \\declare const b: B;
        \\const a: A = b;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    if (checkerFirstChainEntry(s, TsCodes.index_signature_missing)) |entry| {
        try T.expect(std.mem.startsWith(u8, entry.message, "Index signature for type 'string' is missing in type "));
        // Never a standalone header.
        try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.index_signature_missing));
    }
}

