test "checker: buildAssignabilityElaborationChain emits TS2325 for a private/public member mismatch" {
    // Direct unit on the builder: two object types share a property `x`,
    // private on the source, public on the target. tsc's propertyRelatedTo
    // (relater.go:4246) emits TS2325 `Property 'x' is private in type
    // '...' but not in type '...'`. The private side is named first.
    const s = try newSetup("const x = 1;");
    defer destroySetup(s);
    const x_id = try s.sint.intern("x");
    const priv_members = [_]types.ObjectMember{
        .{ .name = x_id, .type = types.Primitive.number_t, .is_optional = false, .is_readonly = false, .is_method = false, .visibility = .private },
    };
    const pub_members = [_]types.ObjectMember{
        .{ .name = x_id, .type = types.Primitive.number_t, .is_optional = false, .is_readonly = false, .is_method = false, .visibility = .public },
    };
    const src_t = try s.ti.internObjectType(&priv_members);
    const tgt_t = try s.ti.internObjectType(&pub_members);
    const chain = try s.checker.buildAssignabilityElaborationChain(src_t, tgt_t);
    try T.expectEqual(@as(usize, 1), chain.len);
    try T.expectEqual(@as(u32, 2325), chain[0].code);
    // `{1}` (private side) must precede `{2}` (public side) — both are the
    // same structural shape here, so just assert the wording shell.
    try T.expect(std.mem.startsWith(u8, chain[0].message, "Property 'x' is private in type "));
    try T.expect(std.mem.indexOf(u8, chain[0].message, "but not in type ") != null);
}

