    }
}

test "checker: buildAssignabilityElaborationChain emits TS2328 for an incompatible method parameter" {
    // Two object types share a method `f`, but the parameter types are
    // mutually unassignable (number vs string). tsc's
    // compareSignaturesRelated (relater.go:1581) nests TS2328 `Types of
    // parameters '{0}' and '{1}' are incompatible.` naming the source
    // then the target parameter at the failing position.
    const s = try newSetup("const x = 1;");
    defer destroySetup(s);
    const f_id = try s.sint.intern("f");
    const src_sig = try s.ti.internSignature(&[_]TypeId{types.Primitive.number_t}, types.Primitive.void_t, false);
    const tgt_sig = try s.ti.internSignature(&[_]TypeId{types.Primitive.string_t}, types.Primitive.void_t, false);
    const src_members = [_]types.ObjectMember{
        .{ .name = f_id, .type = src_sig, .is_optional = false, .is_readonly = false, .is_method = true },
    };
    const tgt_members = [_]types.ObjectMember{
        .{ .name = f_id, .type = tgt_sig, .is_optional = false, .is_readonly = false, .is_method = true },
    };
    const src_t = try s.ti.internObjectType(&src_members);
    const tgt_t = try s.ti.internObjectType(&tgt_members);
    const chain = try s.checker.buildAssignabilityElaborationChain(src_t, tgt_t);
    try T.expectEqual(@as(usize, 1), chain.len);
    try T.expectEqual(@as(u32, 2328), chain[0].code);
    try T.expect(std.mem.startsWith(u8, chain[0].message, "Types of parameters '"));
    try T.expect(std.mem.endsWith(u8, chain[0].message, "' are incompatible."));
}

