test "checker: TS2685 nests under property incompatibility for methods" {
    const s = try newSetup(
        \\interface A { m(this: { a: string }): void; }
        \\interface B { m(this: { b: string }): void; }
        \\declare const b: B;
        \\const a: A = b;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);

    var saw_nested = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        if (d.chain.len == 0) continue;
        if (d.chain[0].code != TsCodes.types_of_property_incompatible) continue;
        if (d.chain[0].children.len == 0) continue;
        if (d.chain[0].children[0].code == TsCodes.signature_this_types_incompatible) saw_nested = true;
    }
    try T.expect(saw_nested);
}

