test "checker: strict callback assignment can surface TS2328 as the top-level header" {
    const s = try newSetup("const x = 1;");
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_function_types = true });
    const animal_prop = try s.sint.intern("animal");
    const dog_prop = try s.sint.intern("dog");
    const f_name = try s.sint.intern("f");
    const x_name = try s.sint.intern("x");
    const animal_t = try s.ti.internObjectType(&[_]types.ObjectMember{
        .{ .name = animal_prop, .type = types.Primitive.void_t, .is_optional = false, .is_readonly = false, .is_method = false },
    });
    const dog_t = try s.ti.internObjectType(&[_]types.ObjectMember{
        .{ .name = animal_prop, .type = types.Primitive.void_t, .is_optional = false, .is_readonly = false, .is_method = false },
        .{ .name = dog_prop, .type = types.Primitive.void_t, .is_optional = false, .is_readonly = false, .is_method = false },
    });
    const source_cb = try s.ti.internSignature(&[_]TypeId{dog_t}, dog_t, false);
    const target_cb = try s.ti.internSignature(&[_]TypeId{animal_t}, animal_t, false);
    const source = try s.ti.internSignature(&[_]TypeId{source_cb}, types.Primitive.void_t, false);
    const target = try s.ti.internSignature(&[_]TypeId{target_cb}, types.Primitive.void_t, false);
    try s.checker.signature_param_names.put(s.checker.gpa, source_cb, try s.checker.gpa.dupe(hir_mod.StringId, &[_]hir_mod.StringId{x_name}));
    try s.checker.signature_param_names.put(s.checker.gpa, target_cb, try s.checker.gpa.dupe(hir_mod.StringId, &[_]hir_mod.StringId{x_name}));
    try s.checker.signature_param_names.put(s.checker.gpa, source, try s.checker.gpa.dupe(hir_mod.StringId, &[_]hir_mod.StringId{f_name}));
    try s.checker.signature_param_names.put(s.checker.gpa, target, try s.checker.gpa.dupe(hir_mod.StringId, &[_]hir_mod.StringId{f_name}));
    try T.expect(try s.checker.tryReportTopLevelSignatureParameterIncompatibility(s.root, null, source, target));
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.types_of_parameters_incompatible));
    try T.expectEqualStrings(
        "Types of parameters 'f' and 'f' are incompatible.",
        s.checker.diagnostics.items[0].message,
    );
}

test "checker: assignment signature display expands nested callable aliases" {
    const s = try newSetup("const x = 1;");
    defer destroySetup(s);
    const animal_prop = try s.sint.intern("animal");
    const dog_prop = try s.sint.intern("dog");
    const cb_name = try s.sint.intern("cb");
    const x_name = try s.sint.intern("x");
    const animal_t = try s.ti.internObjectType(&[_]types.ObjectMember{
        .{ .name = animal_prop, .type = types.Primitive.void_t, .is_optional = false, .is_readonly = false, .is_method = false },
    });
    const dog_t = try s.ti.internObjectType(&[_]types.ObjectMember{
        .{ .name = animal_prop, .type = types.Primitive.void_t, .is_optional = false, .is_readonly = false, .is_method = false },
        .{ .name = dog_prop, .type = types.Primitive.void_t, .is_optional = false, .is_readonly = false, .is_method = false },
    });
    const animal_cb = try s.ti.internSignature(&[_]TypeId{animal_t}, animal_t, false);
    const dog_cb = try s.ti.internSignature(&[_]TypeId{dog_t}, animal_t, false);
    const outer = try s.ti.internSignature(&[_]TypeId{animal_cb}, types.Primitive.void_t, false);
    try s.checker.signature_param_names.put(s.checker.gpa, animal_cb, try s.checker.gpa.dupe(hir_mod.StringId, &[_]hir_mod.StringId{x_name}));
    try s.checker.signature_param_names.put(s.checker.gpa, dog_cb, try s.checker.gpa.dupe(hir_mod.StringId, &[_]hir_mod.StringId{x_name}));
    try s.checker.signature_param_names.put(s.checker.gpa, outer, try s.checker.gpa.dupe(hir_mod.StringId, &[_]hir_mod.StringId{cb_name}));
    try s.checker.alias_display_names.put(s.checker.gpa, animal_cb, "BivariantHack<Animal, Animal>");
    try s.checker.alias_display_names.put(s.checker.gpa, dog_cb, "BivariantHack<Dog, Animal>");
    const display = (try s.checker.allocAssignmentDiagnosticTypeName(outer)).?;
    try T.expectEqualStrings("(cb: (x: { animal: void; }) => { animal: void; }) => void", display);
    try T.expect(std.mem.indexOf(u8, display, "BivariantHack") == null);
}
// ---------------------------------------------------------------------------
// Declaration-emit binding-origin classifier (`classifyBareNameOrigin`).
//
// Additive analysis primitive for the deferred external/private-module
// TS4xxx privacy cluster. These tests pin the single-file-determinable
// facts the classifier reports; faithful EMISSION of the external/private
// module variants stays blocked on cross-file export-table resolution
// (see the function doc-comment + TS_PARITY_PLAN.md).
// ---------------------------------------------------------------------------

test "checker: classifyBareNameOrigin reports module_local_private for a non-exported local type" {
    const b = try newBoundSetup(
        \\class PrivateThing {}
        \\export const widget: PrivateThing = new PrivateThing();
    );
    defer destroyBoundSetup(b);
    const stmts = hir_mod.blockStmts(&b.base.hir, b.base.root);
    const name = try b.base.sint.intern("PrivateThing");
    const origin = b.base.checker.classifyBareNameOrigin(stmts, name);
    try T.expect(origin == .module_local_private);
}

