}

test "checker: classifyBareNameOrigin reports imported_external for an import-bound name with its specifier" {
    const b = try newBoundSetup(
        \\import { Foo } from "./foo";
        \\export const widget: Foo = null as any;
    );
    defer destroyBoundSetup(b);
    const stmts = hir_mod.blockStmts(&b.base.hir, b.base.root);
    const name = try b.base.sint.intern("Foo");
    const origin = b.base.checker.classifyBareNameOrigin(stmts, name);
    try T.expect(origin == .imported_external);
    try T.expect(!origin.imported_external.re_exported);
    const spec = b.base.sint.get(origin.imported_external.specifier);
    try T.expectEqualStrings("./foo", spec);
}

test "checker: classifyBareNameOrigin marks a re-exported import as re_exported" {
