test "checker: classifyBareNameOrigin prioritizes module_local_private over a same-named import" {
    // A module-local non-exported declaration shadows an import of the
    // same name for the locality check -- the local private declaration
    // is the clearly-correct same-module case `nameIsModuleLocalPrivate`
    // already handles, so it wins.
    const b = try newBoundSetup(
        \\interface Conflict {}
        \\import { Conflict as Other } from "./other";
        \\export const widget: Conflict = null as any;
    );
    defer destroyBoundSetup(b);
    const stmts = hir_mod.blockStmts(&b.base.hir, b.base.root);
    const name = try b.base.sint.intern("Conflict");
    const origin = b.base.checker.classifyBareNameOrigin(stmts, name);
    try T.expect(origin == .module_local_private);
}

test "checker: self-referential interface pair does not overflow the stack" {
    // Regression for the `isolatedModulesShadowGlobalTypeNotValue`
    // compiler-corpus crash: a `global { }` augmentation whose
    // `Console` interface references `console.ConsoleConstructor`, and
    // whose `console` namespace's `ConsoleConstructor` references
    // `Console` back, drove `checkInterfaceDecl` ->
    // `resolveUnqualifiedNamespaceTypeRef` -> `checkInterfaceDecl`
    // forever and overflowed the stack. The reentrancy guard must let
    // the check terminate. (Before the guard this test segfaults.)
    const s = try newSetup(
        \\declare global {
        \\  interface Console {
        \\    Console: console.ConsoleConstructor;
        \\  }
        \\  namespace console {
        \\    interface ConsoleConstructor {
        \\      prototype: Console;
        \\      new (): Console;
        \\    }
        \\  }
        \\  var console: Console;
        \\}
    );
    defer destroySetup(s);
    // The assertion is simply that this returns instead of recursing
    // until the stack overflows.
    try s.checker.checkSourceFile(s.root);
}

test "checker: mutually-referential interfaces resolve to object types" {
    // Tighter, single-scope version of the cycle: two interfaces that
    // reference each other. The guard must still allow both to lower to
    // real object types (not collapse to `none`/`unknown`).
    const s = try newSetup(
        \\interface A { b: B; }
        \\interface B { a: A; }
        \\const x: A = { b: { a: { b: null as any } } };
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const stmts = hir_mod.blockStmts(&s.hir, s.root);
    var resolved: usize = 0;
    for (stmts) |st| {
        if (s.hir.kindOf(st) != .interface_decl) continue;
        const t = s.hir.typeOf(st);
        if (t != types.Primitive.none and t != types.Primitive.unknown) resolved += 1;
    }
    try T.expectEqual(@as(usize, 2), resolved);
}

test "checker: TS18031 reduces a conflicting-discriminant intersection to never on property access" {
    // `A & B` has `kind: 'a'` in A and `kind: 'b'` in B; `'a' & 'b'`
    // is `never`, so tsc reduces the whole intersection to `never`.
    // Accessing any property is then a TS2339 on `never` with the
    // TS18031 reduction explained as a nested messageChain. Mirrors
    // `intersectionReduction.ts(38,4)`.
    const s = try newSetup(
        \\type A = { kind: 'a', foo: string };
        \\type B = { kind: 'b', foo: number };
        \\declare let ab: A & B;
        \\ab.kind;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.property_does_not_exist));
    try T.expectEqual(@as(usize, 1), checkerCountChainCode(s, TsCodes.intersection_reduced_never_conflicting));
    // The reduction is a chain entry, never a standalone top-level diag.
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.intersection_reduced_never_conflicting));
    const entry = checkerFirstChainEntry(s, TsCodes.intersection_reduced_never_conflicting).?;
    try T.expectEqualStrings(
        "The intersection 'A & B' was reduced to 'never' because property 'kind' has conflicting types in some constituents.",
        entry.message,
    );
}

test "checker: TS18032 reduces a conflicting-private intersection to never on property access" {
    // Both `A` and `B` declare `private x`, so the synthetic `x` exists
    // in multiple constituents and is private in some — tsc reduces the
    // intersection to `never`. Accessing `y` is a TS2339 on `never`
    // with the TS18032 chain. Mirrors
    // `intersectionWithConflictingPrivates.ts(5,4)`.
    const s = try newSetup(
        \\class A { private x: unknown; y?: string; }
        \\class B { private x: unknown; y?: string; }
        \\declare let ab: A & B;
        \\ab.y;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountChainCode(s, TsCodes.intersection_reduced_never_private));
    // The conflicting-private reduction must NOT surface a TS2341
    // "private member access" — tsc reports only the TS2339 + chain.
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.private_member_access));
    const entry = checkerFirstChainEntry(s, TsCodes.intersection_reduced_never_private).?;
    try T.expectEqualStrings(
        "The intersection 'A & B' was reduced to 'never' because property 'x' exists in multiple constituents and is private in some.",
        entry.message,
    );
}

test "checker: TS18031 reduces a never-intersection assignment target to never" {
    // Assigning into a never-reduced intersection target reads
    // `Type 'X' is not assignable to type 'never'.` with the reduction
    // chain. Mirrors `intersectionWithConflictingPrivates.ts(6,1)`.
    const s = try newSetup(
        \\type A = { kind: 'a' };
        \\type B = { kind: 'b' };
        \\declare let ab: A & B;
        \\ab = { kind: 'a' };
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountChainCode(s, TsCodes.intersection_reduced_never_conflicting));
    var saw_never_target = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_assignable and
            std.mem.indexOf(u8, d.message, "is not assignable to type 'never'") != null)
        {
            saw_never_target = true;
        }
    }
    try T.expect(saw_never_target);
}

test "checker: never-intersection reduction stays silent when no shared property conflicts" {
    // Negative. `A & D` share no property, so the intersection does not
    // reduce and property access resolves normally — no TS18031/TS18032
    // and no spurious TS2339.
    const s = try newSetup(
        \\type A = { kind: 'a', foo: string };
        \\type D = { other: number };
        \\declare let ad: A & D;
        \\let k = ad.kind;
        \\let o = ad.other;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountChainCode(s, TsCodes.intersection_reduced_never_conflicting));
    try T.expectEqual(@as(usize, 0), checkerCountChainCode(s, TsCodes.intersection_reduced_never_private));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.property_does_not_exist));
}

test "checker: never-intersection reduction stays silent for a uniform shared property" {
    // Negative. `kind: string` in both constituents is uniform, so the
    // intersection's `kind` is `string` (not `never`) and the
    // intersection does not reduce. tsc emits nothing.
    const s = try newSetup(
        \\type A = { kind: string, foo: string };
        \\type B = { kind: string, bar: number };
        \\declare let ab: A & B;
        \\let k = ab.kind;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountChainCode(s, TsCodes.intersection_reduced_never_conflicting));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.property_does_not_exist));
}

test "checker: never-intersection reduction stays silent when a literal narrows a primitive" {
    // Negative. `string & 'a'` is `'a'` (assignable, not disjoint), so
    // the shared `kind` does not collapse to `never`. The intersection
    // is preserved and property access stays clean.
    const s = try newSetup(
        \\type A = { kind: string, foo: string };
        \\type B = { kind: 'a', bar: number };
        \\declare let ab: A & B;
        \\let k = ab.kind;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountChainCode(s, TsCodes.intersection_reduced_never_conflicting));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.property_does_not_exist));
}

test "checker: never-intersection private reduction needs the property in multiple constituents" {
    // Negative. `private x` exists only in `A`; `B` has no `x`, so it is
    // not a conflicting-private property and the intersection does not
    // reduce. tsc resolves `ab.y` normally with no TS18032.
    const s = try newSetup(
        \\class A { private x: unknown; y?: string; }
        \\class B { z?: number; }
        \\declare let ab: A & B;
        \\ab.y;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountChainCode(s, TsCodes.intersection_reduced_never_private));
}

// =============================================================================
// Cross-module declaration-emit privacy (from private module '{N}') tests.
//
// These exercise the cross-file export-table merge end to end: the
// `CrossModuleStubResolver` plays the role of `ts_program` /
// `ts_resolver`, reporting (a) the resolved module's rendered name and
// (b) whether the referenced bare name is an exported type-space symbol
// there. The checker's `crossModulePrivateNameInfo` then drives the
// `from private module` variants (TS4024/4030/4032/...). Mirrors the
// `declarationEmitExpandoPropertyPrivateName` baseline shape:
//   `... has or is using name 'I' from private module '"a"'.`
// =============================================================================

/// Stub `ExternalResolver` that answers the `moduleExport` query with a
/// canned module name + export-table membership for a single name.
const CrossModuleStubResolver = struct {
    canned_module_name: []const u8,
    exported_name: []const u8,
    exported_type: bool,
    /// When true (and `exported_type` false), the canned name is reported
    /// as reachable only via a nested exported namespace — the
    /// `cannot be named` (CannotBeNamed) case.
    cannot_be_named: bool = false,
    /// When true, the canned name is reported as a TYPE-ONLY export
    /// (`export type { name }`) — drives TS1379/TS1362.
    type_only_export: bool = false,
    ambient_module: bool = false,
    ambient_module_exports_known: bool = false,
    unsafe_symbol_name: []const u8 = "",
    unsafe_module_specifier: []const u8 = "",

    pub const vtable = ExternalResolver.VTable{
        .resolve = resolveImpl,
        .moduleExport = moduleExportImpl,
        .inferredExportUnsafeReference = inferredExportUnsafeReferenceImpl,
    };

    fn resolveImpl(
        ptr: *anyopaque,
        specifier: []const u8,
        containing_file: []const u8,
    ) ?ExternalResolver.Resolution {
        _ = ptr;
        _ = specifier;
        _ = containing_file;
        return .{ .path = "/dep.ts", .is_declaration = false };
    }

    fn moduleExportImpl(
        ptr: *anyopaque,
        specifier: []const u8,
        containing_file: []const u8,
        name: []const u8,
    ) ?ExternalResolver.ModuleExport {
        const self: *CrossModuleStubResolver = @ptrCast(@alignCast(ptr));
        _ = specifier;
        _ = containing_file;
        const matches = std.mem.eql(u8, name, self.exported_name);
        const is_type_only = self.type_only_export and matches;
        return .{
            .module_name = self.canned_module_name,
            .exported_type = self.exported_type and matches,
            .exported_value = matches and !self.exported_type and !self.cannot_be_named and !self.type_only_export,
            .cannot_be_named = self.cannot_be_named and matches,
            .type_only_export = is_type_only,
            .export_path = if (is_type_only) "/dep.ts" else "",
            .export_pos = 0,
            .ambient_module = self.ambient_module,
            .ambient_module_exports_known = self.ambient_module_exports_known,
        };
    }

    fn inferredExportUnsafeReferenceImpl(
        ptr: *anyopaque,
        specifier: []const u8,
        containing_file: []const u8,
        exported_name: []const u8,
    ) ?ExternalResolver.InferredExportUnsafeReference {
        const self: *CrossModuleStubResolver = @ptrCast(@alignCast(ptr));
        _ = specifier;
        _ = containing_file;
        if (!std.mem.eql(u8, exported_name, self.exported_name)) return null;
        if (self.unsafe_module_specifier.len == 0) return null;
        return .{
            .symbol_name = self.unsafe_symbol_name,
            .module_specifier = self.unsafe_module_specifier,
        };
    }
};

test "checker: known ambient wildcard export miss reports TS2305 with pattern name" {
    const s = try newSetup(
        \\import { onlyInA } from "b.foo";
        \\declare module "a.foo" { let onlyInA: number; }
    );
    defer destroySetup(s);
    var stub = CrossModuleStubResolver{
        .canned_module_name = "\"*.foo\"",
        .exported_name = "everywhere",
        .exported_type = false,
        .ambient_module = true,
        .ambient_module_exports_known = true,
    };
    s.checker.setExternalResolver(.{ .ptr = &stub, .vtable = &CrossModuleStubResolver.vtable });
    try s.checker.checkSourceFile(s.root);

    var found = false;
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.no_exported_member_suggestion);
        if (d.code != TsCodes.no_exported_member) continue;
        found = true;
        try T.expectEqualStrings("Module '\"*.foo\"' has no exported member 'onlyInA'.", d.message);
    }
    try T.expect(found);
}

fn runCrossModuleCheck(s: *TestSetup, stub: *CrossModuleStubResolver) !void {
    s.checker.setStrictFlags(.{ .declaration = true });
    s.checker.setImporterPath("/main.ts");
    s.checker.setExternalResolver(.{ .ptr = stub, .vtable = &CrossModuleStubResolver.vtable });
    try s.checker.checkSourceFile(s.root);
}

fn checkerHasCodeAndMessage(s: *TestSetup, code: u32, message: []const u8) bool {
    for (s.checker.diagnostics.items) |d| {
        if (d.code == code and std.mem.eql(u8, d.message, message)) return true;
    }
    return false;
}

fn checkerHasAnyCode(s: *TestSetup, code: u32) bool {
    for (s.checker.diagnostics.items) |d| {
        if (d.code == code) return true;
    }
    return false;
}

test "checker: cross-module TS4024 for exported variable using imported private type" {
    const s = try newSetup(
        \\import { Foo } from "./dep";
        \\export const widget: Foo = null as any;
    );
    defer destroySetup(s);
    var stub = CrossModuleStubResolver{ .canned_module_name = "\"dep\"", .exported_name = "Foo", .exported_type = true };
    try runCrossModuleCheck(s, &stub);
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.exported_variable_private_module,
        "Exported variable 'widget' has or is using name 'Foo' from private module '\"dep\"'.",
    ));
    // The same-module private-name variant must NOT also fire.
    try T.expect(!checkerHasAnyCode(s, TsCodes.exported_variable_private_name));
}

test "checker: TS2883 for inferred exported call result with non-portable type reference" {
    const s = try newSetup(
        \\import { foo } from "foo";
        \\export const x = foo();
        \\const y = foo();
        \\export const z: unknown = foo();
    );
    defer destroySetup(s);
    var stub = CrossModuleStubResolver{
        .canned_module_name = "\"foo\"",
        .exported_name = "foo",
        .exported_type = false,
        .unsafe_symbol_name = "NestedProps",
        .unsafe_module_specifier = "foo/node_modules/nested",
    };
    try runCrossModuleCheck(s, &stub);
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.inferred_type_non_portable_reference,
        "The inferred type of 'x' cannot be named without a reference to 'NestedProps' from 'foo/node_modules/nested'. This is likely not portable. A type annotation is necessary.",
    ));
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.inferred_type_non_portable_reference));
}

test "checker: TS2742 for inferred exported call result with non-portable module reference" {
    const s = try newSetup(
        \\import { foo } from "foo";
        \\export const x = foo();
    );
    defer destroySetup(s);
    var stub = CrossModuleStubResolver{
        .canned_module_name = "\"foo\"",
        .exported_name = "foo",
        .exported_type = false,
        .unsafe_module_specifier = "foo/node_modules/nested",
    };
    try runCrossModuleCheck(s, &stub);
    try T.expect(checkerHasCodeAndMessage(
        s,
        TsCodes.inferred_type_non_portable_reference_no_symbol,
        "The inferred type of 'x' cannot be named without a reference to 'foo/node_modules/nested'. This is likely not portable. A type annotation is necessary.",
    ));
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.inferred_type_non_portable_reference_no_symbol));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.inferred_type_non_portable_reference));
}

