test "checker: no cross-module diagnostic when name is neither exported nor nested" {
    // Faithful gate: if the resolver reports the name is neither a
    // top-level type-space export nor a nested namespace member, we do
    // not emit either variant — the name does not originate in the
    // resolved module's reachable surface at all.
    const s = try newSetup(
        \\import { Foo } from "./dep";
        \\export const widget: Foo = null as any;
    );
    defer destroySetup(s);
    var stub = CrossModuleStubResolver{ .canned_module_name = "\"dep\"", .exported_name = "Foo", .exported_type = false };
    try runCrossModuleCheck(s, &stub);
    try T.expect(!checkerHasAnyCode(s, TsCodes.exported_variable_private_module));
    try T.expect(!checkerHasAnyCode(s, TsCodes.exported_variable_cannot_be_named));
}

test "checker: no cross-module diagnostic without declaration emit" {
    const s = try newSetup(
        \\import { Foo } from "./dep";
