    defer destroySetup(s);
    var stub = CrossModuleStubResolver{ .canned_module_name = "\"dep\"", .exported_name = "Foo", .exported_type = true };
    // declaration emit OFF — no privacy diagnostics at all.
    s.checker.setImporterPath("/main.ts");
    s.checker.setExternalResolver(.{ .ptr = &stub, .vtable = &CrossModuleStubResolver.vtable });
    try s.checker.checkSourceFile(s.root);
