test "checker: interface members have NO cannot-be-named variant" {
    // Upstream's interface-member selector uses the non-name-checking
    // path, so interfaces never emit a `cannot be named` diagnostic even
    // when the resolver reports CannotBeNamed. We must stay silent.
    const s = try newSetup(
        \\import { Foo } from "./dep";
        \\export interface I { x: Foo; m(p: Foo): Foo; [Foo](): void; }
    );
    defer destroySetup(s);
    var stub = CrossModuleStubResolver{ .canned_module_name = "\"dep\"", .exported_name = "Foo", .exported_type = false, .cannot_be_named = true };
    try runCrossModuleCheck(s, &stub);
    try T.expect(!checkerHasAnyCode(s, TsCodes.interface_property_private_module));
    try T.expect(!checkerHasAnyCode(s, TsCodes.interface_method_return_private_module));
    try T.expect(!checkerHasAnyCode(s, TsCodes.interface_method_param_private_module));
    try T.expect(!checkerHasAnyCode(s, TsCodes.interface_method_name_private_module));
    // And of course no variable cannot-be-named code leaks in either.
    try T.expect(!checkerHasAnyCode(s, TsCodes.exported_variable_cannot_be_named));
}

test "checker: re-exported name stays silent even when reported cannot-be-named" {
    // A re-exported alias makes the name nameable from the .d.ts, so no
    // privacy diagnostic of either flavour fires.
    const s = try newSetup(
        \\import { Foo } from "./dep";
        \\export { Foo };
        \\export const widget: Foo = null as any;
    );
    defer destroySetup(s);
    var stub = CrossModuleStubResolver{ .canned_module_name = "\"dep\"", .exported_name = "Foo", .exported_type = false, .cannot_be_named = true };
    try runCrossModuleCheck(s, &stub);
    try T.expect(!checkerHasAnyCode(s, TsCodes.exported_variable_cannot_be_named));
    try T.expect(!checkerHasAnyCode(s, TsCodes.exported_variable_private_module));
}

fn checkerFirstMessageForCode(s: *TestSetup, code: u32) ?[]const u8 {
    for (s.checker.diagnostics.items) |d| {
        if (d.code == code) return d.message;
    }
    return null;
}

test "checker: TS2411 preserves the source-written string-literal key form" {
    // tsc renders the property name using its written source form: a
    // string-literal key keeps its quotes (`'\"e\"'`). Our interner
    // canonicalises to `e`, so the display helper must re-read the key
    // span from source. Mirrors
    // stringIndexerConstrainsPropertyDeclarations.ts(48,5).
    const s = try newSetup(
        \\interface I {
        \\    [x: string]: string;
        \\    "e": number;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const msg = checkerFirstMessageForCode(s, TsCodes.property_not_assignable_to_index_type) orelse return error.MissingDiagnostic;
    try T.expect(std.mem.indexOf(u8, msg, "Property '\"e\"'") != null);
}

test "checker: TS2322 renders `typeof undefined` annotation as `undefined`" {
    // `var x: typeof undefined` declares the `undefined` type itself.
    // tsc collapses the query and renders the operand as `undefined`,
    // never the raw `typeof undefined` query text. The assignment-side
    // diagnostic renderer reads the declared annotation node, so it must
    // special-case the `undefined` operand. Mirrors
    // validUndefinedAssignments / invalidUndefinedValues.
    const s = try newSetup(
        \\var x: typeof undefined;
        \\class C { foo: string; }
        \\var f: C;
        \\f = x;
    );
    defer destroySetup(s);
    s.checker.strict_flags.strict_null_checks = true;
    s.checker.engine.setStrictNullChecks(true);
    try s.checker.checkSourceFile(s.root);
    const msg = checkerFirstMessageForCode(s, TsCodes.type_not_assignable) orelse return error.MissingDiagnostic;
    try T.expect(std.mem.indexOf(u8, msg, "Type 'undefined' is not assignable") != null);
    try T.expect(std.mem.indexOf(u8, msg, "typeof undefined") == null);
}

test "checker: a namespace fn parameter resolves a sibling namespace-local class" {
    // A function inside a namespace whose parameter is typed as a
    // namespace-local class must resolve that class, not collapse it to
    // `unknown`. Otherwise passing the parameter to a sibling class's
    // constructor false-positives TS2345 ('unknown' not assignable to the
    // class type). `resolveForwardClassInstanceType` only scanned the
    // file-root block; namespace-local classes live in the namespace body.
    // Mirrors ExportFunctionWithInaccessibleTypesInParameterTypeAnnotation.
    const s = try newSetup(
        \\namespace A {
        \\  class Point { x = 0; y = 0; }
        \\  class Line { constructor(public p: Point) {} }
        \\  function f(q: Point): Line { return new Line(q); }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.argument_type_mismatch));
}

test "checker: TS2416 renders the base class by its bare name, not namespace-qualified" {
    // tsc renders the base class in a property-override mismatch by its
    // locally-declared name (`A`), never namespace-qualified (`Ns.A`).
    // Mirrors subtypingWithObjectMembers.
    const s = try newSetup(
        \\namespace Ns {
        \\  class A { bar: { a: string }; }
        \\  class B extends A { bar: { a: number }; }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const msg = checkerFirstMessageForCode(s, TsCodes.property_not_assignable_to_base) orelse return error.MissingDiagnostic;
    try T.expect(std.mem.indexOf(u8, msg, "base type 'A'") != null);
    try T.expect(std.mem.indexOf(u8, msg, "Ns.A") == null);
}

test "checker: `Symbol` resolves to the boxed Symbol interface, not unknown" {
    // `var x: Symbol` is the boxed `Symbol` interface (the apparent type
    // of the `symbol` primitive): `symbol` boxes into it (assignable),
    // but `Symbol` is not assignable back to `symbol`. Previously `Symbol`
    // collapsed to `unknown`. Mirrors symbolType15.
    const s = try newSetup(
        \\declare var sym: symbol;
        \\var symObj: Symbol;
        \\symObj = sym;
        \\sym = symObj;
    );
    defer destroySetup(s);
    s.checker.strict_flags.strict_null_checks = true;
    s.checker.engine.setStrictNullChecks(true);
    try s.checker.checkSourceFile(s.root);
    // Exactly one TS2322 — on the `Symbol`->`symbol` line — and it names
    // `Symbol`, not `unknown`.
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.type_not_assignable));
    const msg = checkerFirstMessageForCode(s, TsCodes.type_not_assignable) orelse return error.MissingDiagnostic;
    try T.expect(std.mem.indexOf(u8, msg, "Type 'Symbol' is not assignable to type 'symbol'") != null);
}

test "checker: return undefined against a type-parameter return is allowed when strictNullChecks is off" {
    // Under `@strict: false`, `undefined`/`null` widen into every type
    // (including a type parameter), so `function f<T>(x: T): T { return
    // undefined; }` must not emit TS2322. Mirrors localTypes4.ts.
    const s = try newSetup(
        \\function f<T>(x: T): T {
        \\    return undefined;
        \\}
    );
    defer destroySetup(s);
    s.checker.strict_flags.strict_null_checks = false;
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.type_not_assignable));
}

test "checker: return undefined against a type-parameter return still errors under strictNullChecks" {
    // With strict null checks ON, `undefined` is not in the domain of an
    // arbitrary `T`, so tsc emits TS2322 — the rejection must remain.
    const s = try newSetup(
        \\function f<T>(x: T): T {
        \\    return undefined;
        \\}
    );
    defer destroySetup(s);
    s.checker.strict_flags.strict_null_checks = true;
    s.checker.engine.setStrictNullChecks(true);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.type_not_assignable));
}

test "checker: return null against a type-parameter return errors under strictNullChecks" {
    // `null` follows the same strict-null rule as `undefined`: a generic
    // `T` may be instantiated to a non-nullish type, so upstream emits
    // TS2322 for `return null;` when strict null checks are enabled.
    const s = try newSetup(
        \\function f<T>(x: T): T {
        \\    return null;
        \\}
    );
    defer destroySetup(s);
    s.checker.strict_flags.strict_null_checks = true;
    s.checker.engine.setStrictNullChecks(true);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.type_not_assignable));
    const msg = checkerFirstMessageForCode(s, TsCodes.type_not_assignable) orelse return error.MissingDiagnostic;
    try T.expect(std.mem.indexOf(u8, msg, "Type 'null' is not assignable to type 'T'.") != null);
}

test "checker: generic reversing type parameters reports strict null returns once" {
    // Mirrors genericReversingTypeParameters.ts: `get(): V` must reject
    // `return null`, and `inverse(): BiMap<V, K>` must reject it once
    // while preserving the reversed generic instance display.
    const s = try newSetup(
        \\class BiMap<K, V> {
        \\  private inverseBiMap: BiMap<V, K>;
        \\  public get(key: K): V { return null; }
        \\  public inverse(): BiMap<V, K> { return null; }
        \\}
        \\var b = new BiMap<string, number>();
        \\var i = b.inverse();
        \\var r = i.get(1);
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_property_initialization = true, .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.property_not_initialized));
    try T.expectEqual(@as(usize, 2), checkerCountCode(s, TsCodes.type_not_assignable));
    var saw_v_return = false;
    var saw_bimap_return = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable) continue;
        if (std.mem.indexOf(u8, d.message, "Type 'null' is not assignable to type 'V'.") != null) {
            saw_v_return = true;
        }
        if (std.mem.indexOf(u8, d.message, "Type 'null' is not assignable to type 'BiMap<V, K>'.") != null) {
            saw_bimap_return = true;
        }
    }
    try T.expect(saw_v_return);
    try T.expect(saw_bimap_return);
}

test "checker: non-integer numeric-literal index resolves to a same-named property (no TS7053)" {
    // `c[1.1]` on a class with a `1.1: string` property must resolve to
    // that property, not fall through to the implicit-any index path.
    // Mirrors objectTypeWithNumericProperty.ts where the only expected
    // diagnostics are TS2454 (used-before-assigned), never TS7053.
    const s = try newSetup(
        \\class C {
        \\    1: number;
        \\    1.1: string;
        \\}
        \\let c: C = new C();
        \\var r2 = c[1.1];
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.element_implicitly_any));
}

test "checker: TS2411 preserves the source-written numeric-literal key form" {
    // A numeric-literal key keeps its written form (`'2.0'`), not the
    // canonical `2`. Mirrors
    // numericIndexerConstrainsPropertyDeclarations.ts(50,5) /
    // stringIndexerConstrainsPropertyDeclarations.ts(50,5).
