        \\interface I {
        \\    [x: string]: string;
        \\    2.0: number;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const msg = checkerFirstMessageForCode(s, TsCodes.property_not_assignable_to_index_type) orelse return error.MissingDiagnostic;
    try T.expect(std.mem.indexOf(u8, msg, "Property '2.0'") != null);
}

// ---------------------------------------------------------------------
// Recursive / cyclic type-instantiation guards (TS2589 path).
//
// These tests primarily assert *termination*: before the depth/count
// guards (and the free-type-parameter deferral) were added to
// `lowererLowerWithTypeParams` / `substituteType`, the inputs below
// either spun forever or overflowed the native stack, so the test
// process itself completing is the load-bearing assertion. We
// additionally assert the absence of spurious TS2589 on legitimately
// deep-but-finite types, mirroring tsc which only emits TS2589 when a
// type instantiation genuinely cannot terminate.
// ---------------------------------------------------------------------

test "checker: self-referential conditional alias terminates without hanging" {
    // Reduced from `conditionalTypeDoesntSpinForever.ts`: a conditional
    // alias whose true/false branches re-instantiate the same alias with
    // an intersection argument that still carries a free type parameter.
    // Without the free-type-parameter deferral this expands forever.
    const s = try newSetup(
        \\type Build<T> =
        \\    T extends { name: any } ? {} : {
        \\        name: <V>(v?: V) => Build<T & { name: V }>;
        \\    };
        \\type R = Build<{}>;
        \\declare const r: R;
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    // Reaching this line at all proves termination.
    try s.checker.checkSourceFile(s.root);
}

test "checker: infinitely-nested recursive alias terminates" {
    // `InfBox<T> = Box<InfBox<T>>` has no fixed point; the lowerer must
    // not chase the cycle indefinitely.
    const s = try newSetup(
        \\type Box<T> = { value: T };
        \\type InfBox<T> = Box<InfBox<T>>;
        \\type X = InfBox<string>;
        \\declare const x: X;
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
}

test "checker: deeply recursive tail-recursive conditional alias terminates" {
    // Reduced from `tailRecursiveConditionalTypes.ts`. Previously this
    // overflowed the native stack inside the recursive type-name
    // renderer (`allocSimpleTypeName`).
    const s = try newSetup(
        \\type Trim<S extends string> =
        \\    S extends ` ${infer T}` ? Trim<T> :
        \\    S extends `${infer T} ` ? Trim<T> :
        \\    S;
        \\type T10 = Trim<'                                        hello '>;
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
}

test "checker: circular base-constraint conditional alias terminates" {
    // Repro from `circularBaseConstraint.ts` (#54610). The `B<T[key]>`
    // self-reference inside an `infer`/`keyof` chain previously hung.
    const s = try newSetup(
        \\type A<T> = T;
        \\type B<T> = T extends any[]
        \\    ? never
        \\    : A<T> extends infer key
        \\    ? key extends keyof T
        \\        ? B<T[key]>
        \\        : never
        \\    : never;
        \\function foo<T>() {
        \\    null as B<T>;
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
