test "checker: infiniteConstraints2 clean conditional base constraint terminates" {
    // Repro from tsgo `testdata/tests/cases/compiler/infiniteConstraints2.ts`
    // (#63269). The nested conditional/default constraint path should
    // typecheck cleanly instead of tripping recursive relation/indexing
    // fallbacks.
    const s = try newSetup(
        \\export type Prepend<Elm, T extends unknown[]> =
        \\ T extends unknown ?
        \\ ((arg: Elm, ...rest: T) => void) extends ((...args: infer T2) => void) ? T2 :
        \\ never :
        \\ never;
        \\export type ExactExtract<T, U> = (T extends U ? U extends T ? T : never : never) & string;
        \\type Conv<T, U = T> = {
        \\    0: [T];
        \\    1: Prepend<T, Conv<ExactExtract<U, T>, {a: number}>>;
        \\}[U extends T ? 0 : 1];
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.type_instantiation_excessively_deep));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.type_cannot_be_used_to_index_type));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.circular_type_arguments));
}

test "checker: recursive indexed access simplification reports upstream recursion diagnostics" {
    // Repro from tsgo `testdata/tests/cases/compiler/
    // recursiveIndexedAccessSimplification.ts` (#63270). The important
    // local property is that recursive indexed-access simplification
    // terminates without inventing a self-assignability TS2345. The
    // exact upstream TS4109/TS2536/TS2322/TS2589 shape is tracked by
    // the opt-in HOME_TS_COMPILER_TESTDATA exact runner.
    const s = try newSetup(
        \\type Recur<T> =
        \\    (T extends  (unknown[]) ? {} : { [K in keyof T]?: Recur<T[K]>}) |
        \\    [...Recur<T>[number][]];
        \\
        \\function join<T>(l: Recur<T>[]): Recur<T> {
        \\    return ['marker', ...l];
        \\}
        \\
        \\function a<T>(l: Recur<T>[]): void {
        \\    const x: Recur<T> | undefined = join(l);
        \\}
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        const bogus_self_assign = d.code == TsCodes.argument_type_mismatch and
            std.mem.indexOf(u8, d.message, "Argument of type 'Recur<T>[]' is not assignable to parameter of type 'Recur<T>[]'.") != null;
        try T.expect(!bogus_self_assign);
    }
}

