test "checker: self-referential type arguments report TS4109, not TS2589" {
    // Upstream `circularTypeArgumentsLocalAndOuterNoCrash1`: resolving
    // the type arguments of `NumArray<...>` re-enters the same
    // reference (the argument references the enclosing alias `X`),
    // so tsc reports TS4109 with the target name and suppresses the
    // generic depth backstop (TS2589).
    const s = try newSetup(
        \\function f<_T, _S>() {
        \\  interface NumArray<T extends number> extends Array<T> {}
        \\  type X = NumArray<X extends {} ? number : number>;
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.circular_type_arguments));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.type_instantiation_excessively_deep));
    var saw_named = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.circular_type_arguments and
            std.mem.indexOf(u8, d.message, "Type arguments for 'NumArray' circularly reference themselves.") != null)
        {
            saw_named = true;
        }
    }
    try T.expect(saw_named);
}

test "checker: legitimately body-recursive generics do not emit TS4109/4110" {
    // The argument-scoped circularity guard must not fire on valid
    // recursion that flows through a type's body/structure rather than
    // its type arguments (`List<T>`, `Tree<T>`), nor on ordinary finite
    // generic instantiation.
    const s = try newSetup(
        \\type List<T> = { value: T; next: List<T> | null };
        \\let x: List<number> = { value: 1, next: null };
        \\interface Tree<T> { v: T; kids: Tree<T>[]; }
        \\let t: Tree<string> = { v: "a", kids: [] };
        \\interface IBox<T> { value: T; }
        \\type T1 = IBox<T1>;
        \\type T2 = IBox<IBox<T2>>;
        \\type Box2 = IBox<Box2 | number>;
        \\type Box<T> = { value: T };
        \\type Nested = Box<Box<Box<string>>>;
        \\declare const n: Nested;
    );
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true });
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.circular_type_arguments));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.circular_tuple_type_arguments));
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.type_not_assignable));
}

test "checker: alias whose type argument references itself reports TS4109" {
