fn renderFirstMappedType(s: *TestSetup) ![]u8 {
    var node: NodeId = hir_mod.none_node_id;
    var i: u32 = 0;
    const n = s.checker.hir.nodeCount();
    while (i < n) : (i += 1) {
        if (s.checker.hir.kindOf(i) == .mapped_type) {
            node = i;
            break;
        }
    }
    var out: std.ArrayListUnmanaged(u8) = .empty;
    errdefer out.deinit(T.allocator);
    try s.checker.renderTypeNodeText(node, &out);
    return out.toOwnedSlice(T.allocator);
}

test "checker: renderTypeNodeText renders a homomorphic mapped type body" {
    const s = try newSetup("type M<T> = { [P in keyof T]: T[P] };");
    defer destroySetup(s);
    const out = try renderFirstMappedType(s);
    defer T.allocator.free(out);
    try T.expectEqualStrings("{ [P in keyof T]: T[P]; }", out);
}

test "checker: pushTypeResolution detects a direct self-cycle" {
    const s = try newSetup("const x = 1;");
    defer destroySetup(s);
    // First push of (42, .type) succeeds; an immediate re-push of the
    // same (target, kind) is a cycle and returns false.
    try T.expect(s.checker.pushTypeResolution(42, .type));
    try T.expect(!s.checker.pushTypeResolution(42, .type));
    // The in-flight entry is now flagged failed, so popTypeResolution
    // reports the cycle.
    try T.expect(!s.checker.popTypeResolution());
    try T.expectEqual(@as(usize, 0), s.checker.type_resolutions.items.len);
}

test "checker: pushTypeResolution distinguishes target and kind, nests cleanly" {
    const s = try newSetup("const x = 1;");
    defer destroySetup(s);
    // Distinct targets and distinct kinds never collide.
    try T.expect(s.checker.pushTypeResolution(1, .type));
    try T.expect(s.checker.pushTypeResolution(2, .type));
    try T.expect(s.checker.pushTypeResolution(1, .declared_type));
    try T.expect(s.checker.typeResolutionInProgress(2, .type));
    try T.expect(!s.checker.typeResolutionInProgress(2, .declared_type));
    // Non-cyclic resolutions pop as succeeded, LIFO.
    try T.expect(s.checker.popTypeResolution());
    try T.expect(s.checker.popTypeResolution());
    try T.expect(s.checker.popTypeResolution());
    try T.expectEqual(@as(usize, 0), s.checker.type_resolutions.items.len);
}

test "checker: pushTypeResolution marks the whole cycle chain failed" {
    const s = try newSetup("const x = 1;");
    defer destroySetup(s);
    // A -> B -> A: when the re-entrant push of A fails, both A and B
    // (every frame from the cycle start) are marked failed, so each
    // pop on the way out reports the cycle — mirroring tsc.
    try T.expect(s.checker.pushTypeResolution(10, .type)); // A
    try T.expect(s.checker.pushTypeResolution(20, .type)); // B
    try T.expect(!s.checker.pushTypeResolution(10, .type)); // re-enter A => cycle
    try T.expect(!s.checker.popTypeResolution()); // B failed
    try T.expect(!s.checker.popTypeResolution()); // A failed
    try T.expectEqual(@as(usize, 0), s.checker.type_resolutions.items.len);
}

