/// Helper for the callable-object regression cluster below: returns
/// true when `source` produces at least one TS2339 diagnostic.
fn sourceEmitsPropertyDoesNotExist(source: []const u8) !bool {
    const s = try newSetup(source);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.property_does_not_exist) return true;
    }
    return false;
}

test "checker: named member on interface with call signature resolves (no TS2339)" {
    // Mirrors objectTypeWithCallSignatureHidingMembersOfFunction /
    // a callable object type that ALSO declares a named property.
    // Accessing the named property must NOT produce a spurious TS2339
    // — tsc resolves it via getApparentType + getPropertyOfType which
    // looks past the call signature to the structural members.
    try T.expect(!try sourceEmitsPropertyDoesNotExist(
        \\interface Callable { (x: number): string; description: string; }
        \\declare const c: Callable;
        \\const d = c.description;
    ));
}

