test "checker: recursive conditional action alias keeps payload discriminants" {
    const s = try newSetup(
        \\type Action<T, P> = P extends void ? { type: T } : { type: T, payload: P }
        \\enum ActionType { Foo, Bar, Baz, Batch }
        \\type BarAction = Action<ActionType.Bar, number>;
        \\type ReducerAction =
        \\  | Action<ActionType.Bar, number>
        \\  | Action<ActionType.Baz, boolean>
        \\  | Action<ActionType.Foo, string>
        \\  | Action<ActionType.Batch, ReducerAction[]>
        \\function assertNever(a: never): never { throw new Error("Unreachable!"); }
        \\function reducer(action: ReducerAction): void {
        \\  switch(action.type) {
        \\    case ActionType.Bar:
        \\      const x: number = action.payload;
        \\      break;
        \\    case ActionType.Baz:
        \\      const y: boolean = action.payload;
        \\      break;
        \\    case ActionType.Foo:
        \\      const z: string = action.payload;
        \\      break;
        \\    case ActionType.Batch:
        \\      action.payload.map(reducer);
        \\      break;
        \\    default: return assertNever(action);
        \\  }
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    const bar_name = s.checker.string_interner.intern("BarAction") catch return error.OutOfMemory;
    const payload_name = s.checker.string_interner.intern("payload") catch return error.OutOfMemory;
    const bar_t = s.checker.type_names.get(bar_name) orelse return error.TestExpectedEqual;
    const payload_t = (try s.checker.lookupObjectMember(bar_t, payload_name)) orelse return error.TestExpectedEqual;
    try T.expectEqual(types.Primitive.number_t, payload_t);
    const reducer_name = s.checker.string_interner.intern("ReducerAction") catch return error.OutOfMemory;
    const type_name = s.checker.string_interner.intern("type") catch return error.OutOfMemory;
    const action_type_name = s.checker.string_interner.intern("ActionType") catch return error.OutOfMemory;
    const bar_member_name = s.checker.string_interner.intern("Bar") catch return error.OutOfMemory;
    const bar_value = s.checker.enum_member_values.get(.{ .obj_name = action_type_name, .prop_name = bar_member_name }) orelse return error.TestExpectedEqual;
    const bar_lit = try s.checker.interner.internEnumNumberLiteral(bar_value, action_type_name, bar_member_name);
    const reducer_t = s.checker.type_names.get(reducer_name) orelse return error.TestExpectedEqual;
    const reducer_members = s.checker.interner.unionMembers(reducer_t);
    var saw_bar_payload = false;
    for (reducer_members) |member_t| {
        const disc_t = s.checker.interner.objectMember(member_t, type_name) orelse continue;
        if (try s.checker.discriminantTypeMatchesLiteral(disc_t, bar_lit)) {
            const member_payload = (try s.checker.lookupObjectMember(member_t, payload_name)) orelse return error.TestExpectedEqual;
            try T.expectEqual(types.Primitive.number_t, member_payload);
            saw_bar_payload = true;
        }
    }
    try T.expect(saw_bar_payload);
    try T.expectEqual(@as(usize, 0), s.checker.diagnostics.items.len);
}

