test "checker: inferred conditional constraint can reduce a generic parameter to never" {
    const b = try newBoundSetup(
        \\function onlyNullablePlease<T extends null extends T ? any : never>(value: T): void {}
        \\function onlyNullablePlease2<T extends [null] extends [T] ? any : never>(value: T): void {}
        \\declare var z: string | null;
        \\declare var y: string;
        \\onlyNullablePlease(z);
        \\onlyNullablePlease2(z);
        \\onlyNullablePlease(y);
        \\onlyNullablePlease2(y);
        \\function f<T>(t: T) {
        \\  var x: T | null = Math.random() > 0.5 ? null : t;
        \\  onlyNullablePlease(x);
        \\  onlyNullablePlease2(x);
        \\}
    );
    defer destroyBoundSetup(b);
