    try b.base.checker.checkSourceFile(b.base.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(b.base, TsCodes.argument_type_mismatch));
    var saw_string_never = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.argument_type_mismatch and
            std.mem.eql(u8, d.message, "Argument of type 'string' is not assignable to parameter of type 'never'."))
        {
            saw_string_never = true;
