        \\declare function g(): Foo | null;
        \\function h() {
        \\  const f = g();
        \\  if (!f) return;
        \\  f.bar;
        \\}
    ));
}

test "checker: predicate-call alias still narrows the inner reference" {
    // The aliased-narrowing feature must remain ADDITIVE: aliasing a
    // predicate call (`const ok = isFoo(x)`) still narrows `x` inside
    // `if (ok)`. The W11 fix changed the alias path from `return` to a
    // fall-through, so this canonical case must keep working.
    try T.expect(!try sourceEmitsPropertyDoesNotExist(
        \\interface Foo { bar: number; }
        \\declare function isFoo(x: unknown): x is Foo;
        \\declare const x: unknown;
        \\const ok = isFoo(x);
        \\if (ok) { x.bar; }
    ));
}

test "checker: NON-nullable call-result is unaffected (a genuinely-missing prop still TS2339)" {
    // Negative guard: the truthiness narrow must not paper over a real
    // missing-property access on a non-nullable call result.
    try T.expect(try sourceEmitsPropertyDoesNotExist(
        \\interface Foo { bar: number; }
        \\declare function g(): Foo;
        \\const f = g();
        \\if (f) { f.nope; }
    ));
}

test "checker: a call-result union accessed WITHOUT a guard still reports" {
    // Negative guard: without the `if (f)` truthiness narrow the access
    // hits the `null` member of the union and must still be flagged.
    try T.expect(try sourceEmitsPropertyDoesNotExist(
        \\interface Foo { bar: number; }
        \\declare function g(): Foo | null;
        \\const f = g();
        \\f.bar;
    ));
}

// ---------------------------------------------------------------------
// Discriminant literal preservation (w13 parity) —
// assignmentCompatWithDiscriminatedUnion. A fresh object-literal
// discriminant property must keep its literal type when contextually
// typed by a union / literal-member target so the discriminated-union
// relater can match it. Widening it to `string`/`number` (as plain
// expression typing does) would break the match. Non-discriminant
// fresh literals must still widen where tsc widens.
// ---------------------------------------------------------------------

test "checker: namespace-scoped object-literal discriminant keeps its literal (GH14865)" {
    const s = try newSetup(
        \\namespace NS {
        \\  type Style2 = { type: "A" | "B"; data: string; };
        \\  const a: Style2 = { type: "A", data: "whatevs" };
        \\}
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), s.checker.diagnostics.items.len);
}

