}

test "checker: GH58603 namespace-scoped enum in type+value position is clean" {
    // `function f(): N.MyEnum { return N.MyEnum.A; }` — the enum is
    // referenced both as a TYPE (`N.MyEnum` return annotation) and as a
    // VALUE (`N.MyEnum.A`). Resolving the qualified value/type ref
    // re-checks the enum decl, which previously re-registered the
    // TS2432 "multiple-declaration auto-first" scope key and spuriously
    // fired. The fix keys the tracker on the declaring node so a
    // re-visit of the SAME enum is not mistaken for a second declaration.
    const b = try newBoundSetup(
        \\namespace N { export enum MyEnum { A, B } }
        \\function f(): N.MyEnum { return N.MyEnum.A; }
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.merged_enum_multiple_auto_first));
    try T.expect(!checkerHasCode(b, TsCodes.cannot_find_name));
    try T.expect(!checkerHasCode(b, TsCodes.cannot_find_namespace));
}

