test "checker: GH58603 fix preserves genuine merged-enum TS2432" {
    // Two DISTINCT `enum E` declarations at the same scope, each omitting
    // its first-member initializer, would both auto-default to 0 and
    // collide. The de-dup fix keys the tracker on the declaring node, so
    // it must STILL fire TS2432 here because the two declarations are
    // different nodes. (Confirms the fix targets only same-node re-visits,
    // not genuine declaration merging.)
    const s = try newSetup(
        \\enum E { A }
        \\enum E { B }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.merged_enum_multiple_auto_first));
}

test "checker: GH58603 qualified value-ref re-visit does not duplicate TS2432" {
    // A genuinely-merged top-level enum (two distinct auto-first `enum E`
    // declarations) is ALSO referenced through a value ref (`E.A`), which
    // re-checks the enum decls. The de-dup fix keys the auto-first tracker
    // on the declaring node, so the genuine second declaration still fires
    // TS2432 — but exactly ONCE. A re-visit of the same offending node
    // (driven by reference resolution) must not duplicate the diagnostic.
    const s = try newSetup(
        \\enum E { A }
        \\enum E { B }
        \\const x = E.A;
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.merged_enum_multiple_auto_first));
}

test "checker: GH58603 namespace enum-member literal in type-alias member position is clean" {
    // `export type T = MyEnum.A;` inside the namespace uses the enum
    // MEMBER (`MyEnum.A`) as a literal TYPE. The qualified type-position
    // resolver must descend `MyEnum` -> member `A` within the enclosing
    // namespace scope WITHOUT misreading `MyEnum` as a namespace name
    // (which would spuriously fire TS2503). Also covers the bare
    // `export type T = MyEnum;` whole-enum type-position reference.
    const member_pos = try newBoundSetup(
        \\namespace N { export enum MyEnum { A, B } export type T = MyEnum.A; }
    );
    defer destroyBoundSetup(member_pos);
    try member_pos.base.checker.checkSourceFile(member_pos.base.root);
    try T.expect(!checkerHasCode(member_pos, TsCodes.cannot_find_namespace));
    try T.expect(!checkerHasCode(member_pos, TsCodes.cannot_find_name));
    try T.expect(!checkerHasCode(member_pos, TsCodes.merged_enum_multiple_auto_first));

    const whole_enum = try newBoundSetup(
        \\namespace N { export enum MyEnum { A, B } export type T = MyEnum; }
    );
    defer destroyBoundSetup(whole_enum);
    try whole_enum.base.checker.checkSourceFile(whole_enum.base.root);
    try T.expect(!checkerHasCode(whole_enum, TsCodes.cannot_find_namespace));
    try T.expect(!checkerHasCode(whole_enum, TsCodes.cannot_find_name));
}

test "checker: non-exported namespace-scoped enum-member type ref is clean (GH58603)" {
    // A type reference to a member of a NON-exported enum declared in
    // the same namespace (`type TypeA = { kind: MyEnum.A }`) must
    // resolve the enum via the enclosing-scope walk, not just the file
    // root — otherwise it spuriously fires TS2503. Regression for the
    // GH58603 cluster's TS2503 over-report.
    const b = try newBoundSetup(
        \\namespace GH58603 {
        \\    enum MyEnum { A = 1, B = 2 }
        \\    type TypeA = { kind: MyEnum.A, id?: number };
        \\    type TypeB = { kind: MyEnum.B } & ({ id?: undefined } | { id: number });
        \\    type MyType = TypeA | TypeB;
        \\    function something(a: MyType): void {}
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.cannot_find_namespace));
    try T.expect(!checkerHasCode(b, TsCodes.cannot_find_name));
}

