    };
    s.checker.setExternalResolver(.{ .ptr = &stub, .vtable = &StubExternalResolver.vtable });
    s.checker.setImporterPath("/src/app.ts");
    s.checker.setJsxOptionPresent(false);
    s.checker.setStrictFlags(.{ .no_implicit_any = true });
    try s.checker.checkSourceFile(s.root);

    var found = false;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == 6142) found = true;
        try T.expect(d.code != TsCodes.untyped_module);
        try T.expect(d.code != TsCodes.cannot_find_module);
    }
    try T.expect(found);
}

test "checker: assigning an any-typed value to a type-parameter target is valid (no TS5082)" {
    // `any` is assignable to every type, including a bare type
    // parameter, so `a = x` (x: any) inside `function k<T>(a: T)` must
    // NOT emit the "could be instantiated with an arbitrary type"
    // diagnostic (TS5082). Mirrors `assignAnyToEveryType.ts`.
    const b = try newBoundSetup(
        \\var x: any;
        \\function k<T>(a: T) {
        \\    a = x;
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.arbitrary_type_parameter_instantiation_unrelated));
    try T.expect(!checkerHasCode(b, TsCodes.type_not_assignable));
}

test "checker: assigning a concrete type nests TS5082 under TS2322" {
    // Regression guard: the any/never exemption must not silence the
    // genuine case — assigning a concrete `string` to a parameter typed
    // by a bare type parameter `T` is unsound (T could be instantiated
    // with an unrelated type).
    const b = try newBoundSetup(
        \\function k<T>(a: T) {
        \\    a = "hello";
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    var found = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable or d.chain.len != 1) continue;
        if (d.chain[0].code != TsCodes.arbitrary_type_parameter_instantiation_unrelated) continue;
        found = true;
        try T.expectEqualStrings("Type 'string' is not assignable to type 'T'.", d.message);
    }
    try T.expect(found);
}

test "checker: assigning unrelated same-name type to type parameter reports TS2719" {
    // A generic type parameter can shadow a same-named class. The
    // rendered source and target names are both `T`, but the symbols are
    // unrelated, so tsc reports the special TS2719 header rather than the
    // generic TS5082 wording. This covers the same checker condition as
    // `incompatibleAssignmentOfIdenticallyNamedTypes.ts`.
    const b = try newBoundSetup(
        \\class T { }
        \\function f<T>(x: T) {
        \\    x = new T();
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable_unrelated_same_name, "Type 'T' is not assignable to type 'T'. Two different types with this name exist, but they are unrelated."));

    var found_chain = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code != TsCodes.type_not_assignable_unrelated_same_name) continue;
        for (d.chain) |entry| {
            if (entry.code == TsCodes.type_not_assignable_unrelated_same_name and
                std.mem.eql(u8, entry.message, "'T' could be instantiated with an arbitrary type which could be unrelated to 'T'."))
            {
                found_chain = true;
            }
        }
    }
    try T.expect(found_chain);
}

test "checker: assigning differently named type to type parameter keeps TS5082" {
