}

test "checker: relation complexity comparing template-literal intersection to null union reports TS2859" {
    // Mirrors `relationComplexityError.ts`: `T1 & T2` is trivially
    // assignable to `T1`, but comparing it to `T1 | null` sends the
    // upstream relater into a template-literal cross-product and it
    // reports TS2859 twice at the assignment.
    const b = try newBoundSetup(
        \\type Digits = '0' | '1' | '2' | '3' | '4' | '5' | '6' | '7';
        \\type T1 = `${Digits}${Digits}${Digits}${Digits}` | undefined;
        \\type T2 = { a: string } | { b: number };
        \\function f2(x: T1 | null, y: T1 & T2) {
        \\    x = y;
        \\}
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expectEqual(@as(usize, 2), checkerCountCode(b.base, TsCodes.excessive_complexity_comparing_types));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.excessive_complexity_comparing_types, "Excessive complexity comparing types 'T1 & T2' and 'T1 | null'."));
}

test "checker: template-literal intersection assignment to base alias does not report TS2859" {
    const b = try newBoundSetup(
