        \\type T1 = `${Digits}${Digits}${Digits}${Digits}` | undefined;
        \\type T2 = { a: string } | { b: number };
        \\function f1(x: T1, y: T1 & T2) {
        \\    x = y;
        \\}
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(b.base, TsCodes.excessive_complexity_comparing_types));
}

fn buildCheckerNestedRelationChain(checker: *Checker, leaf: TypeId, depth: usize) !TypeId {
    const x = try checker.string_interner.intern("x");
    const tag = try checker.string_interner.intern("tag");
    var cur = leaf;
    var i: usize = 0;
    while (i < depth) : (i += 1) {
        cur = try checker.interner.internObjectType(&.{
            .{ .name = x, .type = cur, .is_optional = false, .is_readonly = false, .is_method = false },
            .{ .name = tag, .type = types.Primitive.number_t, .is_optional = false, .is_readonly = false, .is_method = false },
        });
    }
    return cur;
}

test "checker: relation stack-depth overflow reports TS2321" {
    const s = try newSetup("");
    defer destroySetup(s);

    const deep = relation.max_relate_depth + 25;
    const source = try buildCheckerNestedRelationChain(&s.checker, types.Primitive.number_t, deep);
    const target = try buildCheckerNestedRelationChain(&s.checker, types.Primitive.number_t, deep);
    const result = try s.checker.checkerAssignableToWithRelationOverflow(source, target);
    try T.expect(result.ok);
    try T.expect(result.stack_depth_overflowed);
    try T.expect(try s.checker.tryReportExcessiveStackDepthComparingTypes(s.root, source, target));
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.excessive_stack_depth_comparing_types));
}

test "checker: large assignment chain in module body reports TS2563" {
    var source: std.ArrayListUnmanaged(u8) = .empty;
    defer source.deinit(T.allocator);
    try source.appendSlice(T.allocator, "const data = [];\n");
    var i: usize = 0;
    while (i < Checker.max_control_flow_assignment_chain) : (i += 1) {
        try source.appendSlice(T.allocator, "data[0] = 0;\n");
    }

    const s = try newSetup(source.items);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 1), checkerCountCode(s, TsCodes.body_too_large_for_control_flow));
    try T.expect(hasDiagnosticCodeMessage(
        s,
        TsCodes.body_too_large_for_control_flow,
        "The containing function or module body is too large for control flow analysis.",
    ));
}

test "checker: large declaration-only module body does not report TS2563" {
    var source: std.ArrayListUnmanaged(u8) = .empty;
