        try source.appendSlice(T.allocator, line);
    }

    const s = try newSetup(source.items);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    try T.expectEqual(@as(usize, 0), checkerCountCode(s, TsCodes.body_too_large_for_control_flow));
}

test "checker: public parameter-property override makes inherited protected member accessible (no TS2445)" {
    // `Derived` re-declares the base's `protected p` as a `public p`
    // constructor parameter property. The effective member at a
    // `Derived` receiver is the most-derived (public) declaration, so
    // `d.p` from outside the class hierarchy is legal — no TS2445.
    // Mirrors `classConstructorParametersAccessibility3.ts`.
    const b = try newBoundSetup(
        \\class Base { constructor(protected p: number) {} }
        \\class Derived extends Base { constructor(public p: number) { super(p); this.p; } }
        \\var d: Derived;
        \\d.p;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.protected_member_access));
}

test "checker: inherited protected member without override still reports TS2445 outside the hierarchy" {
    // Regression guard: when the subclass does NOT redeclare the
    // protected member, accessing it from outside the class hierarchy
    // still fires TS2445.
    const b = try newBoundSetup(
        \\class Base { constructor(protected p: number) {} }
        \\class Derived extends Base {}
        \\var d: Derived;
        \\d.p;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCode(b, TsCodes.protected_member_access));
}

test "checker: explicit this-parameter type binds this inside a plain function body" {
    // A plain (non-method) function with an explicit `this: T` parameter
    // binds `this` to the declared type `T` inside the body — `this` is
    // NOT implicitly `any` (no TS2683). A member access against a missing
    // property of `T` surfaces TS2339, exactly as tsc does. Mirrors the
    // `thisTypeInFunctions` conformance shape.
    const b = try newBoundSetup(
        \\function f(this: { n: number }) { return this.n; }
        \\function g(this: { n: number }) { return this.bogus; }
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .no_implicit_any = true, .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    // `this` is typed — no implicit-any.
    try T.expect(!checkerHasCode(b, TsCodes.this_implicitly_any));
    // The missing-property access on the declared `this` type fires TS2339.
    try T.expect(checkerHasCode(b, TsCodes.property_does_not_exist));
    // ...and the good access does NOT (one TS2339 total, for `bogus`).
    var ts2339_count: usize = 0;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.property_does_not_exist) ts2339_count += 1;
    }
    try T.expectEqual(@as(usize, 1), ts2339_count);
}

