test "checker: this:void parameter forbids property access (TS2339 on void)" {
    // `this: void` declares that the function does not use `this`. Any
    // member access on `this` then resolves against `void` and fails with
    // TS2339, rather than the implicit-any TS2683. Mirrors tsc.
    const b = try newBoundSetup(
        \\function f(this: void) { return this.n; }
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .no_implicit_any = true, .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.this_implicitly_any));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.property_does_not_exist, "Property 'n' does not exist on type 'void'."));
}

