test "checker: object-literal accessor satisfies string index by its value type (no TS2322)" {
    // A get/set accessor in an object literal contributes its VALUE type
    // (getter return / setter param) to the string-index constraint, not
    // the underlying `() => T` function type. `get X(): string` therefore
    // satisfies `[x: string]: string`. Mirrors
    // `stringIndexerConstrainsPropertyDeclarations.ts`.
    const b = try newBoundSetup(
        \\var b: { [x: string]: string } = {
        \\    get X() { return ''; },
        \\    set X(v) { },
        \\};
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.type_not_assignable));
}

