test "checker: undefined assigned to a bare type parameter reports plain TS2322 (not TS5082)" {
    // Under strictNullChecks, `undefined` is not assignable to a bare
    // type parameter `T` — but tsc reports the plain TS2322 ("Type
    // 'undefined' is not assignable to type 'T'."), NOT the "could be
    // instantiated with an arbitrary type" TS5082 elaboration (which is
    // for concrete sources). Mirrors `undefinedAssignableToEveryType.ts`.
    const b = try newBoundSetup(
        \\function foo<T>(x: T) { x = undefined; }
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.arbitrary_type_parameter_instantiation_unrelated));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type 'undefined' is not assignable to type 'T'."));
}

test "checker: assignment target keeps indexed-access annotation in TS2322" {
    // `T[P]` may resolve to a concrete constraint for checking, but tsc
    // keeps the source-written indexed-access target in assignment prose.
    // Mirrors `nonPrimitiveConstraintOfIndexAccessType.ts`.
    const b = try newBoundSetup(
        \\function n<T extends { [s: string]: number }, P extends keyof T>(s: string, tp: T[P]) {
        \\    tp = s;
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type 'string' is not assignable to type 'T[P]'."));
}

test "checker: non-primitive union/intersection diagnostics match tsc reductions" {
    const b = try newBoundSetup(
        \\var a: object & string = "";
        \\var b: object | string = "";
        \\var c: object & {} = 123;
        \\a = b;
        \\const foo: object & {} = {bar: 'bar'};
        \\const bar: object & {err: string} = {bar: 'bar'};
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type '\"\"' is not assignable to type 'never'."));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type 'number' is not assignable to type 'object'."));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type 'string' is not assignable to type 'never'."));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.object_literal_excess_property, "Object literal may only specify known properties, and 'bar' does not exist in type 'object & { err: string; }'."));
}

test "checker: concrete type assigned to a bare type parameter keeps TS5082 nested" {
    // Regression guard: the undefined/null exemption must not affect a
    // concrete source — `string` into `T` still gets the "could be
    // instantiated with an arbitrary type" elaboration.
    const b = try newBoundSetup(
        \\function k<T>(a: T) { a = "hello"; }
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    var found = false;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_assignable and
            d.chain.len == 1 and
            d.chain[0].code == TsCodes.arbitrary_type_parameter_instantiation_unrelated)
        {
            found = true;
        }
    }
    try T.expect(found);
}

test "checker: captured primitive assignments keep TS2322 over TS5082 details" {
    const b = try newBoundSetup(
        \\var n = 1;
        \\var s = "";
        \\var b = true;
        \\var v: void;
        \\function assign<T>(target: T) {
        \\    target = n;
        \\    target = s;
        \\    target = b;
        \\    target = v;
        \\}
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);

    var nested_count: usize = 0;
    for (b.base.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.arbitrary_type_parameter_instantiation_unrelated);
        if (d.code == TsCodes.type_not_assignable and
            d.chain.len == 1 and
            d.chain[0].code == TsCodes.arbitrary_type_parameter_instantiation_unrelated)
        {
            nested_count += 1;
        }
    }
    try T.expectEqual(@as(usize, 4), nested_count);
}

test "checker: undefined assigned to an enum target reports TS2322 under strict, valid enum assignments stay clean" {
    // Under strictNullChecks, `undefined` is not assignable to a
    // (non-nullable) enum-typed target — TS2322. A valid enum-member
    // (`E.A`) or numeric-member (`0`) assignment must stay clean.
    // Mirrors `undefinedAssignableToEveryType.ts(26)`.
    const b = try newBoundSetup(
        \\enum E { A }
        \\var ae: E;
        \\ae = undefined;
        \\ae = E.A;
        \\ae = 0;
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    var ts2322: usize = 0;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.type_not_assignable) ts2322 += 1;
    }
    // Exactly one TS2322, for the `undefined` assignment.
    try T.expectEqual(@as(usize, 1), ts2322);
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type 'undefined' is not assignable to type 'E'."));
}

test "checker: optional numeric property is not assignable to a number index under strict (TS2322)" {
    // Under strictNullChecks, a numeric-named optional property
    // (`{ 1?: string }`) contributes its implicit `| undefined` to the
    // number-index check, so it is NOT assignable to
    // `{ [key: number]: string }` (`obj[1]` may be `undefined`). Mirrors
    // `optionalPropertyAssignableToStringIndexSignature.ts`.
    const b = try newBoundSetup(
        \\declare let probablyArray: { [key: number]: string };
        \\declare let numberLiteralKeys: { 1?: string };
        \\probablyArray = numberLiteralKeys;
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCode(b, TsCodes.type_not_assignable));
}

test "checker: optional string property stays assignable to a string index under strict (no TS2322)" {
    // Regression guard: tsc exempts an optional property's implicit
    // undefined for STRING/dictionary indexers, so `{ k1?: string }` is
    // assignable to `{ [key: string]: string }`. The number-index fix
    // must not affect this.
    const b = try newBoundSetup(
        \\declare let strDict: { [key: string]: string };
        \\declare let optProps: { k1?: string };
        \\strDict = optProps;
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .strict_null_checks = true });
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.type_not_assignable));
}

test "checker: signed numeric-literal index resolves a string-named numeric property (no TS7053)" {
    // tsc applies ToString to a numeric-literal index and resolves it
    // against a same-named property: `i[-1]` / `i[-1.0]` -> `i["-1"]`,
    // `i[1]` -> `i["1"]`. A genuinely-missing numeric index (`i[2]`)
    // still reports TS7053 under noImplicitAny. Mirrors
    // `objectTypeWithStringNamedNumericProperty.ts`.
    const b = try newBoundSetup(
        \\interface I { "-1": Date; "1": number; }
        \\declare var i: I;
        \\var a = i[-1];
        \\var b = i[-1.0];
        \\var c = i[1];
        \\var d = i[2];
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .no_implicit_any = true });
    try b.base.checker.checkSourceFile(b.base.root);
    var ts7053: usize = 0;
    for (b.base.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.element_implicitly_any) ts7053 += 1;
    }
    // Only `i[2]` (no matching member) is implicit-any.
    try T.expectEqual(@as(usize, 1), ts7053);
}

test "checker: Object.prototype members resolve on interfaces and object literals via dot and bracket access" {
    // Every object type inherits Object.prototype members (`toString`,
    // etc.), so `i.toString()`, `i['toString']()`, `a.toString()` and
    // `a['toString']()` resolve on interfaces and object literals just
    // like on class instances — no TS2339 / TS7053. A genuinely-missing
    // member still errors. Mirrors `objectTypePropertyAccess.ts`.
    const b = try newBoundSetup(
        \\interface I { bar: string; }
        \\declare var i: I;
        \\var r1 = i.toString();
        \\var r2 = i['toString']();
        \\var a = { foo: '' };
        \\var r3 = a.toString();
        \\var r4 = a['toString']();
        \\var r5 = i.bogusMember;
    );
    defer destroyBoundSetup(b);
    b.base.checker.setStrictFlags(.{ .no_implicit_any = true });
    try b.base.checker.checkSourceFile(b.base.root);
    // Exactly one TS2339 (for `bogusMember`), and no implicit-any.
    try T.expect(!checkerHasCode(b, TsCodes.element_implicitly_any));
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.property_does_not_exist, "Property 'bogusMember' does not exist on type 'I'."));
}

test "checker: uppercase Object assignments compare inherited toString signatures" {
    const b = try newBoundSetup(
        \\interface I { toString(): number; }
        \\class C { toString(): number { return 1; } }
        \\declare let o: Object;
        \\declare let i: I;
        \\declare let c: C;
        \\o = i;
        \\i = o;
        \\o = c;
        \\c = o;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);

    try T.expectEqual(@as(usize, 4), checkerCountCode(b.base, TsCodes.type_not_assignable));
    try T.expectEqual(@as(usize, 2), checkerCountChainCode(b.base, TsCodes.object_assignable_to_few_types));
}

test "checker: uppercase Object accepts inherited non-nullish values and constraints" {
    const b = try newBoundSetup(
        \\enum E { A }
        \\declare let e: E;
        \\let o: Object = e;
        \\function accept<T extends Object>(value: T): T { return value; }
        \\accept({});
        \\interface Indexed {
        \\  [key: string]: Object;
        \\  method(value: number): number;
        \\}
    );
    defer destroyBoundSetup(b);
