    try T.expectEqual(@as(usize, 0), checkerCountCode(b.base, TsCodes.type_not_assignable));
    try T.expectEqual(@as(usize, 0), checkerCountCode(b.base, TsCodes.argument_type_mismatch));
    try T.expectEqual(@as(usize, 0), checkerCountCode(b.base, TsCodes.type_does_not_satisfy_constraint));
    try T.expectEqual(@as(usize, 0), checkerCountCode(b.base, TsCodes.property_not_assignable_to_index_type));
}

test "checker: object spread of a union distributes into a union of object types" {
    // `{ ...union }` where the spread source is a union of object types
    // distributes the whole literal into a union (one object type per
    // branch), matching tsc — so the redeclaration with the matching
    // union annotation does NOT fire TS2403. Mirrors `spreadUnion.ts`.
    const b = try newBoundSetup(
        \\declare var union: { a: number } | { b: string };
        \\var o3: { a: number } | { b: string };
        \\var o3 = { ...union };
        \\var o4: { a: boolean } | { b: string, a: boolean };
        \\var o4 = { ...union, a: false };
        \\var o5: { a: number } | { b: string } | { a: number, b: string };
        \\var o5 = { ...union, ...union };
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.subsequent_var_type_mismatch));
}

test "checker: object spread of a single object type is unchanged (no distribution)" {
    // Regression guard: a non-union spread keeps the existing
    // single-object-type computation.
    const b = try newBoundSetup(
        \\declare var o: { a: number };
        \\var x = { ...o, b: '' };
        \\let y: { a: number; b: string } = x;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.type_not_assignable));
}

test "checker: class extends a member of a value-less namespace does not emit a missing-member TS2339" {
    // `class D2 extends M.C` where `M` is a type-only namespace (no
    // runtime value side) uses `M` in value position — tsc flags that
    // with TS2708 on `M`, NOT a missing-member TS2339 on `typeof M`.
    // Mirrors `genericTypeReferenceWithoutTypeArgument2.ts`.
    const b = try newBoundSetup(
        \\namespace M { export interface E<T> { foo: T } }
        \\class D2 extends M.C { }
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCodeWithMessage(b, TsCodes.property_does_not_exist, "Property 'C' does not exist on type 'typeof M'."));
    try T.expect(checkerHasCode(b, TsCodes.namespace_as_value));
}

test "checker: object-literal numeric property violating a number index reports TS2322 (non-strict)" {
    // A numeric-named property whose value is not assignable to the
    // target's number-index value type fails — `{ 2.0: 1 }` against
    // `{ [x: number]: string }`. Non-numeric properties stay unconstrained
    // by the number index. Mirrors `numericIndexerConstrainsPropertyDeclarations.ts`.
    const b = try newBoundSetup(
        \\var b: { [x: number]: string } = { a: '', 1.0: '', 2.0: 1 };
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCodeWithMessage(b, TsCodes.type_not_assignable, "Type 'number' is not assignable to type 'string'."));
}

test "checker: scope-qualified enum nominal brand still matches its member literal" {
    // A numeric enum's whole-enum nominal brands the owning enum with a
    // scope-qualified name (`__enum:<scopeId>:E1`), but the member
    // literal records the bare name (`E1`). The relation must still
    // accept `E1.one` into an `E1`-typed slot (and the contextual tuple
    // `[E1, E2]`). Mirrors `bestCommonTypeOfTuple.ts`.
    const b = try newBoundSetup(
        \\enum E1 { one }
        \\enum E2 { two }
        \\var x: E1 = E1.one;
        \\var t: [E1, E2] = [E1.one, E2.two];
        \\var a: E1[] = [E1.one];
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.type_not_assignable));
}

test "checker: legacy property decorator returning a function does not report TS1271" {
    // `@dec prop` where `dec(): (target, key) => void` returns a
    // decorator function is the factory-returning-decorator shape; tsc
    // resolves the bare-name decorator call against the inner function's
    // arity, so the outer function return never trips TS1271. Mirrors
    // `decoratorOnClassProperty11.ts`.
    const s = try newSetup(
        \\// @experimentalDecorators: true
        \\declare function dec(): <T>(target: any, propertyKey: string) => void;
        \\class C { @dec prop; }
    );
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.decorator_return_void_or_any);
    }
}

test "checker: array literal assigned to a sparse numeric-key object target is checked element-wise" {
    // A target `{ 0: string; 5: number }` (object with sparse numeric
    // members, not a fixed tuple) constrains only indices 0 and 5; the
    // array literal's other elements are unconstrained. tsc treats it as
    // a tuple-like contextual target and accepts. Mirrors
    // `unionTypeFromArrayLiteral.ts`.
    const b = try newBoundSetup(
        \\var t: { 0: string; 5: number } = ["hello", true, false, " hi", true, 10, "any"];
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.type_not_assignable));
}

test "checker: array literal whose constrained element mismatches a sparse numeric-key target still errors" {
    // Regression guard: index 0 is constrained to `string`; a number
    // there is a genuine mismatch.
    const b = try newBoundSetup(
        \\var t: { 0: string; 5: number } = [42, true];
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCode(b, TsCodes.type_not_assignable));
}

test "checker: parenthesized/conditional literal initializer keeps its literal type" {
    // A conditional initializer contextually types both branches against
    // the literal-typed target, so a `let` binding does not widen them to
    // `string`. Parenthesized literal branches are transparent. Mirrors
    // `stringLiteralTypesAndParenthesizedExpressions01.ts` (only TS2774 is
    // expected there — never TS2322 on these assignments).
    const b = try newBoundSetup(
        \\declare function myRandBool(): boolean;
        \\let a: "foo" = ("foo");
        \\let b: "foo" | "bar" = ("foo");
        \\let c: "foo" = (myRandBool ? "foo" : ("foo"));
        \\let d: "foo" | "bar" = (myRandBool ? "foo" : ("bar"));
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.type_not_assignable));
}

test "checker: conditional initializer with a mismatched literal branch still errors" {
    // Regression guard: the else branch `"baz"` is not assignable to the
    // literal target `"foo"`, so the conditional-branch short-circuit must
    // fall through and the normal assignability path emits TS2322.
    const b = try newBoundSetup(
        \\declare function myRandBool(): boolean;
        \\let c: "foo" = (myRandBool ? "foo" : "baz");
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCode(b, TsCodes.type_not_assignable));
}

test "checker: spreading a set-only accessor reads as undefined" {
    // Spreading `{ set bar(_v: number) {} }` contributes `bar: undefined`
    // (no getter ⇒ read is undefined), so the annotated targets match and
    // no TS2322 fires. Mirrors objectSpreadSetonlyAccessor.ts.
    const b = try newBoundSetup(
        \\const o1: { foo: number, bar: undefined } = { foo: 1, ... { set bar(_v: number) { } } };
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.type_not_assignable));
}

test "checker: a get/set accessor in a spread source keeps its getter type" {
    // Regression guard: with a getter present, the spread takes the getter
    // type (`number`), so assigning to a `{ bar: undefined }` target still
    // errors — the set-only undefined rule must not apply here.
    const b = try newBoundSetup(
        \\const o: { bar: undefined } = { ... { get bar() { return 1; }, set bar(_v: number) { } } };
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCode(b, TsCodes.type_not_assignable));
}

test "checker: object-literal setter paired with a getter owes no implicit-any" {
    // A get/set accessor pair: the unannotated setter parameter takes its
    // type from the getter's return, so neither TS7032 nor TS7006 fires.
    // Mirrors thisTypeInAccessors.ts (copiedFromGetter).
    const b = try newBoundSetup(
        \\interface Foo { n: number; x: number; }
        \\const copiedFromGetter = {
        \\  n: 14,
        \\  get x(this: Foo): number { return this.n; },
        \\  set x(n) { this.n = n; }
        \\};
    );
    defer destroyBoundSetup(b);
    b.base.checker.strict_flags.no_implicit_any = true;
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.setter_property_implicitly_any));
    try T.expect(!checkerHasCode(b, TsCodes.parameter_implicitly_any));
}

test "checker: object-literal lone setter without a getter still owes implicit-any" {
    // Regression guard: with no paired getter, the unannotated setter
    // parameter is genuinely implicit-any (TS7032 + TS7006).
    const b = try newBoundSetup(
        \\const onlySetter = {
        \\  n: 14,
        \\  set x(n) { this.n = n; }
        \\};
    );
    defer destroyBoundSetup(b);
    b.base.checker.strict_flags.no_implicit_any = true;
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCode(b, TsCodes.setter_property_implicitly_any));
}

test "checker: nested-class computed key reference is not a forward reference under useDefineForClassFields" {
    // The computed key's `C` is the heritage of a nested class expression, so
    // under useDefineForClassFields it is not a parameter forward reference —
    // no TS2373. Mirrors classWithStaticFieldInParameterBindingPattern.3.ts.
    const b = try newBoundSetup(
        \\// @useDefineForClassFields: true
        \\class C {}
        \\(({ [class extends C { static x = 1 }.x]: bb = "" }) => { var C; })();
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(!checkerHasCode(b, TsCodes.parameter_cannot_reference_later));
}

test "checker: nested-class computed key reference still reports without useDefineForClassFields" {
    // Regression guard: with the flag OFF, tsc DOES report the forward
    // reference (classWithStaticFieldInParameterBindingPattern.2.ts).
    const b = try newBoundSetup(
        \\class C {}
        \\(({ [class extends C { static x = 1 }.x]: bb = "" }) => { var C; })();
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);
    try T.expect(checkerHasCode(b, TsCodes.parameter_cannot_reference_later));
}

fn appendObjectUnionAlias(source: *std.ArrayListUnmanaged(u8), name: []const u8, prop: []const u8, member_count: usize) !void {
    try source.appendSlice(T.allocator, "type ");
    try source.appendSlice(T.allocator, name);
    try source.appendSlice(T.allocator, " = ");
    var i: usize = 0;
    while (i < member_count) : (i += 1) {
        if (i > 0) try source.appendSlice(T.allocator, " | ");
        var buf: [64]u8 = undefined;
        const member = try std.fmt.bufPrint(&buf, "{{ {s}: {d} }}", .{ prop, i });
        try source.appendSlice(T.allocator, member);
    }
    try source.appendSlice(T.allocator, ";\n");
}

test "checker: TS2590 fires when an intersection union cross-product reaches the representation limit" {
    var source: std.ArrayListUnmanaged(u8) = .empty;
    defer source.deinit(T.allocator);

    const names = [_][]const u8{ "A", "B", "C", "D", "E" };
    const props = [_][]const u8{ "a", "b", "c", "d", "e" };
    var i: usize = 0;
    while (i < names.len) : (i += 1) {
        try appendObjectUnionAlias(&source, names[i], props[i], 10);
    }
    try source.appendSlice(T.allocator, "type Boom = A & B & C & D & E;");

    const s = try newSetup(source.items);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    var found: usize = 0;
    for (s.checker.diagnostics.items) |d| {
        if (d.code == TsCodes.expression_union_too_complex) {
            found += 1;
            try T.expect(std.mem.indexOf(u8, d.message, "union type that is too complex") != null);
        }
    }
    try T.expectEqual(@as(usize, 1), found);
}

test "checker: TS2590 stays silent below the intersection union cross-product limit" {
    var source: std.ArrayListUnmanaged(u8) = .empty;
    defer source.deinit(T.allocator);

    const names = [_][]const u8{ "A", "B", "C", "D" };
    const props = [_][]const u8{ "a", "b", "c", "d" };
    var i: usize = 0;
    while (i < names.len) : (i += 1) {
        try appendObjectUnionAlias(&source, names[i], props[i], 10);
    }
    try source.appendSlice(T.allocator, "type Safe = A & B & C & D;");

    const s = try newSetup(source.items);
    defer destroySetup(s);
    try s.checker.checkSourceFile(s.root);
    for (s.checker.diagnostics.items) |d| {
        try T.expect(d.code != TsCodes.expression_union_too_complex);
    }
}

