test "checker: override mismatch precedes strict property initialization on the same field" {
    const src =
        \\class Base<U extends String> {
        \\  x: U;
        \\}
        \\class Derived<U> extends Base<string> {
        \\  x: String;
        \\}
    ;
    const s = try newSetup(src);
    defer destroySetup(s);
    s.checker.setStrictFlags(.{ .strict_null_checks = true, .strict_property_initialization = true });
    try s.checker.checkSourceFile(s.root);

    const derived_x: u32 = @intCast(std.mem.indexOf(u8, src, "x: String;").?);
    var override_index: ?usize = null;
    var initialization_index: ?usize = null;
    var override_span_len: ?u32 = null;
    var initialization_span_len: ?u32 = null;
    for (s.checker.diagnostics.items, 0..) |d, i| {
        if (s.checker.diagnosticStart(d) != derived_x) continue;
        const span = s.hir.spanOf(d.node);
        if (d.code == TsCodes.property_not_assignable_to_base) {
            override_index = i;
            override_span_len = span.end - span.start;
        }
        if (d.code == TsCodes.property_not_initialized) {
            initialization_index = i;
            initialization_span_len = span.end - span.start;
        }
    }
    try T.expect(override_index != null);
    try T.expect(initialization_index != null);
    try T.expect(override_index.? < initialization_index.?);
    try T.expectEqual(initialization_span_len, override_span_len);
}

