test "checker: namespace parity batch suggests a nearby exported member" {
    const b = try newBoundSetup(
        \\namespace A {
        \\  export function fn(value: string): boolean { return true; }
        \\  export function fng<T, U>(value: T): U { throw value; }
        \\  function fn2(value: string): boolean { return false; }
        \\  function fng2<T, U>(value: T): U { throw value; }
        \\}
        \\const shortValue = A.fn2;
        \\const value = A.fng2;
    );
    defer destroyBoundSetup(b);
    try b.base.checker.checkSourceFile(b.base.root);

    try T.expectEqual(@as(usize, 1), checkerCountCode(b.base, TsCodes.property_does_not_exist_did_you_mean));
    try T.expectEqual(@as(usize, 1), checkerCountCode(b.base, TsCodes.property_does_not_exist));
    var saw_related = false;
    for (b.base.checker.diagnostics.items) |diagnostic| {
        if (diagnostic.code != TsCodes.property_does_not_exist_did_you_mean) continue;
        try T.expectEqualStrings(
            "Property 'fng2' does not exist on type 'typeof A'. Did you mean 'fng'?",
            diagnostic.message,
        );
        for (diagnostic.related) |related| {
            if (related.code == TsCodes.is_declared_here and
                std.mem.eql(u8, related.message, "'fng' is declared here."))
            {
                saw_related = true;
            }
        }
    }
    try T.expect(saw_related);
}

