        \\    for (var index = 0; index < values.length; index++) {
        \\        if (currentName) {
        \\            var unit = { name: currentName };
        \\            units.push(unit);
        \\        } else {
        \\            currentName = values[index];
        \\        }
        \\    }
        \\    currentName = currentName || "fallback";
        \\    var unit = { name: currentName };
        \\    units.push(unit);
        \\}
    );
